/****** Object:  StoredProcedure [dbo].[BOM_Child_CODE]    Script Date: 17/06/2026 11:29:46 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO



CREATE PROCEDURE [dbo].[BOM_Child_CODE]
	(@Code    [varchar](20),
	@msg   [varchar](10)  output )

AS 

Declare @sCode varchar(20)
Declare @stCode varchar(20)
Declare @tCode varchar(20)
Declare @tcCode varchar(20)
Declare @ctcCode varchar(20)

Declare FStageList cursor for

Select StageCode from bom_mps_master where ItemCode=@Code and Compid='01'


OPEN FStageList

FETCH NEXT FROM FStageList into @tCode 
	
	
			WHILE @@FETCH_STATUS = 0
					
					BEGIN
		
							if len(isnull(@tCode, 0)) = 0
		
								BEGIN
								
									select @msg= ' Invalid Code '
									
								END
			
							ELSE
								BEGIN
									while len(isnull(@tCode, 0)) = 0
								
										BEGIN
											
											select @stCode=StageCode from bom_mps_master  where ItemCode=@tCode and Compid='01'
											
											if  len(isnull(@stCode,0))=0
											
												BEGIN				
									
												select @tcCode=@tCode
											
												END
											
											select @tCode=@stCode
										
										END													
								END

		

			declare  StageList cursor For

		
				select ChildCode from bom_structure_dtl where ParentCode=@tcCode and Compid='01'	

		
					OPEN StageList
					FETCH NEXT FROM StageList into @sCode 
					WHILE @@FETCH_STATUS = 0
					
					BEGIN
		
						if (@sCode =NULL)
		
								BEGIN
								
								select @msg= ' Invalid Code '
									
								END
			
						ELSE
								BEGIN
					
								while @sCode <> NULL
								
									BEGIN
									
									select @ctcCode=ChildCode from bom_structure_dtl where ParentCode=@sCode and  Compid='01' 	
					

									if  len(isnull(@ctcCode,0))=0				
						
										BEGIN
													
										INSERT INTO [Bom_Stage_Child] 
											
											 ([Code]) 
										 
										VALUES 
						
											(@sCode)
										
										commit transaction
						
										END
									
									select @sCode=@ctcCode
															
									END
											
							END
								
						FETCH NEXT FROM StageList  into @sCode 
					END
							 	
				close StageList
				deallocate StageList

			FETCH NEXT FROM FStageList  into @tCode 

			END

		
	close FStageList
	deallocate FStageList

GO

/****** Object:  StoredProcedure [dbo].[BOM_Drawing_Master_HlpECN]    Script Date: 17/06/2026 11:29:46 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

 CREATE PROCEDURE [dbo].[BOM_Drawing_Master_HlpECN](@ItemNature char(2), @Status int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))    
    
As    
    
SET NOCOUNT ON    
    
Begin    
    
  Select a.ItemCode, c.ItemDescription, a.Status, c.ItemNature  
  From Bom_Drawing_Master a  
  Left Outer Join INV_Material_Master c    
  On a.ItemCode=c.ITemCode and a.Branchid=c.Branchid and a.Compid=c.Compid    
  Where (@ItemNature= '' OR c.ItemNature =@ItemNature) and (@Status=-1 OR a.Status=@Status)       
  and a.ItemCode in (Select ItemCode From dbo.fn_BOM_ECN(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)a     
  Where ReqStatus Not in ('A', 'C','H')  and BackEndField in('RevisionNo','Status') and EffStatus = 'A'    
  and Source ='DRAWING MASTER' and a.ItemCode = ItemCode and a.branchID = BranchID and a.CompID = CompID)    
       
End 
GO

