 Insert into BOM_ECN_Hdr      
       
        Select a.DocType, a.DocNo, a.DocDate, a.ItemCode, a.Source, a.Targetdate, a.ModificationDetails,       
    a.ModificationReason, @EffStatus, @AsOnDate, @UserID, a.BranchID, a.CompID, a.Finyear, @AsOnDate      
