CREATE PROCEDURE [dbo].[BOM_ECN_Hlp_DrawingDtl](@ItemNatureCode char(2), @BranchID varchar(3), @CompID varchar(3))      
      
 As      
      
 SET NOCOUNT ON      
      
 Begin      
        
    
         
   Select Distinct a.ItemCode, b.ItemDescription      
         From dbo.Bom_Drawing_Master a      
         Left Outer Join INV_Material_Master b      
        On a.ItemCode = b.ItemCode and a.BranchID = b.BranchID and a.CompID = b.CompID      
    where (@ItemNatureCode='' OR ItemNature= @ItemNatureCode) and a.BranchID= @BranchID and a.CompID=@CompID  
  
END 
