CREATE PROCEDURE [dbo].[BOM_ECN_Hlp_Param](@ItemNatureCode char(2), @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))        
        
 As        
        
 SET NOCOUNT ON        
        
 Begin        
          
  If @ItemNatureCode = ''        
           
       Select Distinct a.ItemCode, b.ItemDescription        
         From BOM_Inspection_Parameter a        
         Left Outer Join INV_Material_Master b        
         On a.ItemCode = b.ItemCode and a.BranchID = b.BranchID and a.CompID = b.CompID        
         Where a.ItemCode not in(Select ItemCode        
                 From dbo.fn_BOM_ECN(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear)        
                 Where ItemCode = a.ItemCode and BranchiD = a.BranchID and CompID = a.CompID         
                 and ReqStatus in ('H')        
                )        
           
  Else        
           
      Select Distinct a.ItemCode, b.ItemDescription        
         From BOM_Inspection_Parameter a        
         Left Outer Join INV_Material_Master b        
         On a.ItemCode = b.ItemCode and a.BranchID = b.BranchID and a.CompID = b.CompID        
         Where ItemNature = @ItemNatureCode        
         
    
    
    /*and a.ItemCode not in(Select ItemCode        
              From dbo.fn_BOM_ECN(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear)        
              Where ItemCode = a.ItemCode and BranchiD = a.BranchID and CompID = a.CompID         
              and ReqStatus Not in ('H')        
              )    */    
 End 
GO

