CREATE PROCEDURE [dbo].[BOM_ECN_Val](@Source varchar(50)='', @ItemCode varchar(20), @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))     
    
As    
    
 BEGIN    
    
  SET NOCOUNT ON    
      
 Select a.Source    
 From dbo.fn_BOM_ECN( @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a    
 Where a.ItemCode=@ItemCode and a.ReqStatus Not In('A','C','H')    
   and a.EffStatus<>'C' and (@Source='' OR Source = @Source) and a.BranchID=@BranchID and a.CompID=@CompID      
         
 END 
GO

/****** Object:  StoredProcedure [dbo].[BOM_ECNAuthorisation_Fil]    Script Date: 17/06/2026 11:29:47 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

 CREATE PROCEDURE [dbo].[BOM_ECNAuthorisation_Fil](@IsEHdr bit, @FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))       
As      
 BEGIN      
  SET NOCOUNT ON      
        
 If @IsEHdr='1'      
  Begin         
   Select Distinct a.DocType, a.DocNo, a.DocDate,       
     Case When a.EffStatus = 'N' Then 'New' When a.EffStatus = 'A' Then 'Authorised'      
       When a.EffStatus = 'C' Then 'Cancel' When a.EffStatus = 'H' then 'Hold' End As Status,       
     a.ItemCode, c.ItemDescription, IsNull(b.ReqStatus,'') As ECNStatus      
   From dbo.fn_BOM_ECN_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a      
   Left Outer Join dbo.fn_BOM_ECN_Status(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) b      
      On a.DocNo = b.DocNo and a.DocDate = b.DocDate and a.DocType = b.DocType and a.ItemCode = b.ItemCode      
     and a.BranchId = b.BranchID and a.CompID = b.CompID      
   Left Outer Join INV_Material_Master c      
      On a.ItemCode = c.ItemCode and a.BranchID = c.BranchID and a.CompID = c.CompID      
   Where a.DocDate Between @FromDate and @ToDate        
  End      
        
 Else      
        
  Begin      
   Select a.DocType, a.DocNo, a.DocDate, a.Fields as UserField, a.Remarks      
   -- Case When a.Status = '0' Then 'Pending' Else 'Completed' End As Status      
   From dbo.fn_BOM_ECN_Dtl(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a       
   Where a.DocDate Between @FromDate and @ToDate       
  End           
 END 
GO

/****** Object:  StoredProcedure [dbo].[BOM_HSNNo_Master_Auth]    Script Date: 17/06/2026 11:29:47 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[BOM_HSNNo_Master_Auth](@HSNId int, @AsOnDate datetime, @RptDate datetime, @AuthStatus char(2), @AuthDate datetime, @UserID Varchar(10), @BranchID Varchar(3), @CompID Varchar(3))      
      
AS  
  
BEGIN    
            
	SET NOCOUNT ON;    
     
	Declare @RevIncr int    
		Select @RevIncr=Case When Right(@AuthStatus, 1)='A' Then 1 Else 0 End    
     
	Declare @RevNo as int    
		Select @RevNo = IsNull(a.RevNo, @RevNo)     
		From fn_BOM_HSNNo_Master_Grp('A', @AsOnDate, @BranchID, @CompID)a    
		Where a.HSNId=@HSNId   
     
	INSERT into BOM_HSNNo_Master      
		Select a.HSNId, a.HSNNo, a.Rate, a.RevNo, Convert(varchar(10),@AsOnDate,120), Right(@AuthStatus, 1)+Right(a.EffStatus, 1),       
			a.EffDate, Case Right(@AuthStatus, 1) When 'H' Then a.isTranLock Else '0' End, a.UserID, @BranchID, @CompID, @AsOnDate      
		From BOM_HSNNo_Master a      
		Where a.TranStamp = (Select Max(b.TranStamp) From BOM_HSNNo_Master b      
								Where b.TranStamp <= @AsOnDate and b.HSNId=a.HSNId and b.BranchID=a.BranchID and b.CompID=a.CompID)      
			and a.HSNId = @HSNId and a.BranchID=@BranchID and a.CompID=@CompID 
			and Left(a.EffStatus, 1) Not in ('A', 'X')      
          
			  

END
GO

/****** Object:  StoredProcedure [dbo].[BOM_HSNNo_Master_Ins]    Script Date: 17/06/2026 11:29:47 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[BOM_HSNNo_Master_Ins]    
	(    
		@HSNId					[int], 
		@HSNNo					[varchar](10),                     
		@Rate					[float],      
		@EffStatus				[char](2),    
		@EffDate				[datetime],      
		@isTranLock				[bit],    
		@UserID					[varchar](10),    
		@BranchID				[varchar](3),    
		@CompID					[varchar](3),    
		@TranStamp				[datetime]
	)    
    
AS     
BEGIN  
    
	SET NOCOUNT ON;    
    
	Declare @RevNo as int    
	Declare @RevDate as datetime    
		Select @RevNo=-1     
		Select @RevDate=Convert(varchar(10),@TranStamp,120)    
    
	IF @EffStatus<>'NA'    
		Begin    
			Select @RevNo = IsNull(a.RevNo, @RevNo) ,  @RevDate=IsNull(a.RevDate, @RevDate)      
			From  dbo.fn_BOM_HSNNo_Master_Grp ('W',@TranStamp, @BranchID, @CompID) a    
			Where a.HSNId = @HSNId
		End    

	INSERT INTO [BOM_HSNNo_Master]     
	(
		[HSNId],     
		[HSNNo],     
		[Rate],      
		[RevNo],    
		[RevDate],    
		[EffStatus],    
		[EffDate],      
		[isTranLock],     
		[UserID],    
		[BranchID],    
		[CompID],    
		[TranStamp]
	)     
       
	VALUES     
	(     
		@HSNId,                
		@HSNNo,     
		@Rate,
		@RevNo,    
		@RevDate,    
		@EffStatus,    
		@EffDate,        
		@isTranLock,    
		@UserID,    
		@BranchID,    
		@CompID,    
		@TranStamp
	)    

END
GO

