CREATE PROCEDURE [dbo].[BOM_HSNNoMaster_Fil](@FrmTranType char(1), @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))
As

	Begin

		SET NOCOUNT ON;

		Select a.HSNId, b.HSNNo, b.Rate, b.EffDate, b.EffStatus, IsNull(b.IsTranLock,0) as IsTranLock
		From dbo.fn_BOM_HSNNo_Master_Grp(@FrmTranType, @AsOnDate, @BranchID, @CompID)a
		Left Outer Join dbo.fn_BOM_HSNNo_Master('M', @AsOnDate, @RptDate, @BranchID, @CompID)b
			On a.HSNId = b.HSNId and a.BranchID = b.BranchID and a.CompID = b.CompID
		Where a.BranchId = @BranchID and a.CompId = @CompID
		Order by a.HSNId
	End
GO

