CREATE PROCEDURE [dbo].[BOM_INS_CODE]
	(@Code 		[int],
	 @Description 		[varchar](30),
	 @DataType 		[char](1),
	 @Width 		[int],
	 @AutoIncrement 	[bit],
	 @Status	 	[bit],
	 @Userid		[varchar](10),
	 @Branchid 		[varchar](3),
	 @Compid		[varchar](3))

AS 

SET  NOCOUNT ON

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		INSERT INTO [BOM_CODE] 
			 ( [Code],
			 [Description],
			 [DataType],
			 [Width],
			 [AutoIncrement],
			 [Status],
			 [Userid],
			 [Branchid],
			 [Compid]) 
		 
		VALUES 
			( @Code,
			 @Description,
			 @DataType,
			 @Width,
			 @AutoIncrement,
			 @Status,
			 @Userid,
			 @cBranchid,
			 @Compid)


		commit transaction
		FETCH NEXT FROM BranchidList into @cBranchid 
	END
 	
	close BranchidList
	deallocate BranchidList
GO

