 CREATE PROCEDURE [dbo].[Bom_Ins_Drawing_Master]    
 (  
  @ItemCode  [varchar](20),    
  @DrawingNo  [int],    
  @Drawingdate  [datetime],    
  @DrawingCode [varchar](50),    
  @Description  [varchar](50),    
  @Modification  [varchar](50),    
  @RevisionNo  [int],    
  @Revisiondate  [datetime],    
  @Type   [varchar](3),    
  @Scale [varchar](20),    
  @Status  [bit],    
  @DrawingPath  [varchar](100),    
  @TotalCopies  [int],    
  @UserId  [varchar](10),    
  @BranchId  [varchar](3),    
  @CompId  [varchar](3),  
  @Transtamp [datetime]  
  )    
AS     
    
SET NOCOUNT ON    
    
declare @cDrawingNo  int    
declare @cRevisionNo  int    
    
  /*  
if exists (select * from Bom_Drawing_Master where DrawingNo=@DrawingNo and DrawingCode=@DrawingCode and Description=@Description     
      and Modification=@Modification and RevisionNo=@RevisionNo and Type=@Type and ItemCode=@ItemCode and branchid=@BranchId and Compid=@CompId)     
  begin    
         
    Update [Bom_Drawing_Master] set    
    
       [Scale]=@Scale,          
       [Status]=@Status,    
       [DrawingPath]=@DrawingPath,    
       [TotalCopies]=@TotalCopies,    
       [UserId]=@UserId    
    where DrawingNo=@DrawingNo and DrawingCode=@DrawingCode and Description=@Description     
        and Modification=@Modification and Revisionno=@RevisionNo and ItemCode=@ItemCode     
        and Type=@Type and branchid=@BranchId and Compid=@CompId      
  end    
    
else    
 begin */  
    
select @cRevisionNo=max(RevisionNo) from Bom_Drawing_Master where ItemCode=@ItemCode and Type=@Type and BranchID = @BranchID and CompID = @CompID    
select @cRevisionNo=case when @cRevisionNo is null then 0 else @cRevisionNo+1 end    
Select @cDrawingNo = DrawingNo From Bom_Drawing_Master Where ItemCode=@ItemCode and Type=@Type and BranchID = @BranchID and CompID = @CompID              
Select @cDrawingNo = Isnull(@cDrawingNo,(Select isnull( max(DrawingNo),0) From Bom_Drawing_Master Where BranchID = @BranchID and CompID = @CompID)+1)     
     
  INSERT INTO [Bom_Drawing_Master_His]     
    (  
 [ItemCode],    
    [DrawingNo],    
    [Drawingdate],    
    [DrawingCode],    
    [Description],    
    [Modification],    
    [RevisionNo],    
    [Revisiondate],    
    [Type],    
    [Scale],    
    [Status],    
    [DrawingPath],    
    [TotalCopies],    
    [UserId],    
    [BranchId],    
    [CompId],  
 [Transtamp]  
 )     
       
  VALUES     
   ( @ItemCode,    
    @cDrawingNo,    
    @Drawingdate,    
    @DrawingCode,    
    @Description,    
    @Modification,    
    @cRevisionNo,    
    @Revisiondate,    
    @Type,    
    @Scale,    
    @Status,    
    @DrawingPath,    
    @TotalCopies,    
    @UserId,    
    @BranchId,    
    @CompId,  
 @Transtamp  
 )    
-- END
GO

