SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[BOM_INS_Inspection_Parameter]      
(    
    @ParamCode  [int],       
    @ItemCode   [varchar](20),      
    @ShortName   [varchar](5),      
    @Parameter  [varchar](30),      
    @InstrumentTypeCode  [int],      
    @Dimension  [varchar](10),      
    @FromValue   [varchar](50),      
    @ToValue   [varchar](50),      
    @Mean  [varchar](50),      
    @Defect   [varchar](15),      
    @Validate   [bit],      
    @Exption   [bit],      
    @Sequence   [int],      
    @Status  [bit],      
    @Type   [Char](2),      
    @Userid   [varchar](10),      
    @Branchid   [varchar](3),      
    @Compid   [varchar](3),    
    @Transtamp [datetime]    
)      
AS
BEGIN
    SET NOCOUNT ON      
      
    declare @cParamCode int      
    declare @cBranchid varchar(3)      
      
    declare  BranchidList cursor For      
      
    Select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid      
      
    OPEN BranchidList      
    FETCH NEXT FROM BranchidList into @cBranchid 
    
    WHILE @@FETCH_STATUS = 0      
    BEGIN      
    
       Declare @isProceedInsert bit;
   
       if exists (Select * from  BOM_Inspection_Parameter where ParamCode = @ParamCode and ItemCode = @ItemCode  and Branchid = @cBranchid  and Compid = @compid)
           BEGIN
               If Exists (
                           Select * from  BOM_Inspection_Parameter where ParamCode = @ParamCode and ItemCode = @ItemCode  and Branchid = @cBranchid  and Compid = @compid 
                                and ShortName=@ShortName and Parameter = @Parameter and InstrumentTypeCode = @InstrumentTypeCode
                                and Dimension=@Dimension and FromValue = @FromValue and ToValue = @ToValue and Mean=@Mean and Defect=@Defect and Validate=@Validate
                                and Exption=@Exption and Sequence=@Sequence and Status=@Status and Type=@Type
                        )
                    Select @isProceedInsert = '0';
                Else
                BEGIN
                    Select @cParamCode=@ParamCode

                    Select @isProceedInsert = '1'; 
                END
            END
        Else
            BEGIN
                Select @cParamCode = Max(ParamCode) From Bom_Inspection_Parameter Where BranchID = @cBranchID and CompID = @CompID                
                Select @cParamCode = Isnull(@cParamCode, 0) + 1  
        
                Select @isProceedInsert = '1'; 
            END
    
        If (@isProceedInsert='1')
        BEGIN
            INSERT INTO [BOM_Inspection_Parameter_His]       
            (    
                [ParamCode],      
                [ItemCode],      
                [ShortName],      
                [Parameter],      
                [InstrumentTypeCode],      
                [Dimension],       
                [FromValue],      
                [ToValue],      
                [Mean],      
                [Defect],      
                [Validate],      
                [Exption],      
                [Sequence],      
                [Status],      
                [Type],      
                [Userid],      
                [Branchid],      
                [Compid],    
                [Transtamp]    
            )       
            VALUES       
            (    
                @cParamCode,       
                @ItemCode,      
                @ShortName,      
                @Parameter,      
                @InstrumentTypeCode,      
                @Dimension,      
                @FromValue,      
                @ToValue,      
                @Mean,      
                @Defect,      
                @Validate,      
                @Exption,      
                @Sequence,      
                @Status,      
                @Type,      
                @Userid,      
                @cBranchid,      
                @Compid,    
                @Transtamp    
            )
        END
    
        FETCH NEXT FROM BranchidList into @cBranchid       
    END      
        
    close BranchidList      
    deallocate BranchidList

END
GO

