CREATE PROCEDURE [dbo].[BOM_INS_MASTERDRAWING_DEPT]
	(@ItemCode 	[varchar](20),
	 @DrawingNo 	[varchar](20),
	 @DeptCode 	[int],
	 @Status	[bit],
	 @Userid 	[varchar](10),
 	 @Branchid	[varchar](3),
	 @Compid 	[varchar](3))

AS 
BEGIN
SET NOCOUNT ON

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		if exists (Select *  from BOM_MASTERDRAWING_DEPT where ItemCode = @ItemCode and DrawingNo = @DrawingNo and DeptCode = @DeptCode and Branchid = @cBranchid  and Compid = @compid)
		
			Begin 
				
				Update BOM_MASTERDRAWING_DEPT Set Status = @Status
				Where ItemCode = @ItemCode and DrawingNo = @DrawingNo and DeptCode = @DeptCode and Branchid = @cBranchid  and Compid = @compid

			End

		Else
			if @Status = '1'
				Begin	
	
					INSERT INTO [BOM_MASTERDRAWING_DEPT] 
						 ([ItemCode],
						 [DrawingNo],
						 [DeptCode],
						 [Status],
						 [Userid],
						 [Branchid],
						 [Compid]) 
					 
					VALUES 
			
						(@ItemCode, 
						 @DrawingNo,
						 @DeptCode,
						 @Status,
						 @Userid,
						 @cBranchid,
						 @Compid)	
	
				End    
		
		FETCH NEXT FROM BranchidList into @cBranchid 
	END
 	
	close BranchidList
	deallocate BranchidList
END
GO

