CREATE PROCEDURE [dbo].[Bom_INS_RPN]
	(@ItemCode 		[varchar](20),
	 @RPN 		[int],
	 @RPNTargetDays 	[int],
	 @Userid 		[varchar](10),
	 @Branchid		[varchar](3),
	 @Compid		[varchar](3))
AS

		if exists (select * from BOM_RPN where ItemCode=@ItemCode and Branchid=@Branchid and Compid=@Compid)
			begin
				UPDATE  [Bom_RPN] SET RPN=@RPN WHERE ItemCode=@ItemCode  and Branchid=@Branchid and Compid=@Compid
			end

		else
			begin
