CREATE PROCEDURE [dbo].[BOM_INS_STRUCTURE_DTL]    
 (  
  @ItemGroupKey [int],    
  @ParentCode   [varchar](20),    
  @ChildCode    [varchar](20),    
  @Qty   [float],    
  @RevisionNo [int],    
  @Explodable   [bit],    
  @Percentage   [float],    
  @Priority     [int],    
  @Status       [bit],    
  @Userid  [varchar](10),    
  @Branchid  [varchar](3),    
  @Compid  [varchar](3),  
  @Transtamp [datetime]  
  )    
    
AS     
BEGIN    
SET NOCOUNT ON    
    
declare @cBranchid varchar(3)    
    
declare  BranchidList cursor For    
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid    
    
 OPEN BranchidList    
 FETCH NEXT FROM BranchidList into @cBranchid     
 WHILE @@FETCH_STATUS = 0    
     
 BEGIN    
    
  --DELETE FROM BOM_STRUCTURE_DTL WHERE ParentCode = @ParentCode and RevisionNo = @RevisionNo and ChildCode = @ChildCode and Branchid = @cBranchid and Compid = @compid    
    
  INSERT INTO [BOM_STRUCTURE_DTL_HIS]     
    (  
 [ItemGroupKey],    
    [ParentCode],    
    [ChildCode],    
    [Qty],    
    [RevisionNo],    
    [Explodable],    
    [Percentage],    
    [Priority],    
    [Status],    
    [Userid],    
    [Branchid],    
    [Compid],  
 [Transtamp]  
 )     
       
  VALUES     
   (  
    @ItemGroupKey,    
    @ParentCode,    
    @ChildCode,    
    @Qty,    
    @RevisionNo,    
    @Explodable,    
    @Percentage,    
    @Priority,    
    @Status,    
    @Userid,    
    @cBranchid,    
    @Compid,  
 @Transtamp  
 )    
      
  FETCH NEXT FROM BranchidList into @cBranchid     
 END    
      
 close BranchidList    
 deallocate BranchidList 
END
GO

