CREATE PROCEDURE [dbo].[BOM_INS_ToolType]
	(@ToolTypeCode 	[int],
	 @ToolType 	[varchar](20),
	 @Regrind	[int],
	 @Corner 	[int],
	 @Reform 	[int],
	 @Status 	[int],
	 @Userid 	[varchar](10),
	 @Branchid 	[varchar](3),
	 @Compid 	[varchar](3))

AS
 IF not exists (Select * from BOM_ToolType where ToolTypeCode=@ToolTypeCode and Branchid=@Branchid and Compid=@Compid) 

	 INSERT INTO [dbo].[BOM_ToolType] 
		 ( [ToolTypeCode],
		 [ToolType],
		 [Regrind],
		 [Corner],
		 [Reform],
		 [Status],
		 [Userid],
		 [Branchid],
		 [Compid]) 
	 
	VALUES 
		( @ToolTypeCode,
		 @ToolType,
		 @Regrind,
		 @Corner,
		 @Reform,
		 @Status,
		 @Userid,
		 @Branchid,
		 @Compid)
 Else
	UPDATE BOM_ToolType
		SET 	[ToolType]=@ToolType,
			[Regrind]=@Regrind,
			[Corner]=@Corner,
			[Reform]=@Reform,
			[Status]=@Status
	WHERE  [ToolTypeCode]=@ToolTypeCode 
		  AND [Branchid]=@Branchid AND [Compid]=@Compid
