/****** Object:  StoredProcedure [dbo].[BOM_ItemwiseMachinewiseCycleTime_Hlp_ItemECN]    Script Date: 17/06/2026 11:29:49 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

      
CREATE PROCEDURE [dbo].[BOM_ItemwiseMachinewiseCycleTime_Hlp_ItemECN](@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))      
      
As      
 BEGIN      
 SET NOCOUNT ON;      
    
   Select Distinct a.ItemCode, IsNull(c.ItemDescription,'') As ItemDesc, a.Status    
   From dbo.BOM_ItemwiseMachinewiseCycleTime a      
   Left Outer Join INV_Material_Master c      
    On a.ItemCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID          
   Where a.ItemCode in (Select ItemCode From dbo.fn_BOM_ECN(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)      
    Where ReqStatus Not in('A','C','H') and BackEndField in('MachineCode','CycleTime','SettingTime','Status') and EffStatus = 'A'      
    and Source = 'STAGEWISE MACHINEWISE CYCLE TIME' and a.ItemCode = ItemCode and a.branchID = BranchID and a.CompID = CompID)      
   Order by a.ItemCode      
      
 END
GO

/****** Object:  StoredProcedure [dbo].[BOM_Material_Master_Trn_ECN]    Script Date: 17/06/2026 11:29:49 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[BOM_Material_Master_Trn_ECN](@Source varchar(50), @ItemCode varchar(20), @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))              
              
As              
              
 BEGIN              
              
  SET NOCOUNT ON              
                
 If @Source='ITEM MASTER'  --- Item Master, Item Detail & Drawing Master              
  Begin              
   Select a.ItemCode, a.DocType, a.DocNo, a.DocDate, a.BackEndField              
   From dbo.fn_BOM_ECN(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a              
   Where a.Source=@Source and a.ItemCode=@ItemCode and a.ReqStatus Not In('A','C','H') and EffStatus = 'A'                
     and a.BackEndField In('ShortDesc','BoughtOut','PurNature','Status')              
  End              
                
 Else If @Source='PARAMETER DETAIL'              
               
  Begin                    
   Select a.ItemCode, a.DocType, a.DocNo, a.DocDate, a.BackEndField              
   From dbo.fn_BOM_ECN(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a              
   Where a.Source=@Source and a.ItemCode=@ItemCode and a.ReqStatus Not In('A','C','H')                     
      and a.BackEndField In('ShortName','ParameterDesc','InstrumentTypeDesc','Dimension','FromValue','ToValue','Mean','Defect','Validate','ParamException','Seq','Type','Status')                 
      and a.EffStatus = 'A'              
  End                
                
Else If @Source='DRAWING MASTER'          
           
  Begin                
   Select DocType, DocNo, DocDate, BackEndField          
   From dbo.fn_BOM_ECN(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a          
   Where a.Source=@Source and a.ItemCode=@ItemCode and a.ReqStatus Not In('A','C','H') and EffStatus = 'A'           
     and a.BackEndField In('RevisionNo','Status')          
  End                 
                
 Else If @Source='PROCESS SEQUENCE'              
               
  Begin                    
   Select a.DocType, a.DocNo, a.DocDate, a.BackEndField              
   From dbo.fn_BOM_ECN(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a              
   Where a.Source=@Source and a.ItemCode=@ItemCode and a.ReqStatus Not In('A','C','H') and EffStatus = 'A'               
     and a.BackEndField In('StageCode','OperationCode','OperationSequence','Status')              
  End                   
               
 Else If @Source='PRODUCT STRUCTURE'              
               
  Begin                
   Select a.DocType, a.DocNo, a.DocDate, a.BackEndField              
   From dbo.fn_BOM_ECN(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a              
   Where a.Source=@Source and a.ItemCode=@ItemCode and a.ReqStatus Not In('A','C','H') and EffStatus = 'A'                
     and a.BackEndField In('ChildCode','Qty','Explodable','Status')                   
    End              
                  
 Else If @Source='STAGEWISE MACHINEWISE CYCLE TIME'              
               
  Begin                
   Select a.DocType, a.DocNo, a.DocDate, a.BackEndField              
   From dbo.fn_BOM_ECN(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a              
   Where a.Source=@Source and a.ItemCode=@ItemCode and a.ReqStatus Not In('A','C','H') and EffStatus = 'A'                
     and a.BackEndField In('MachineCode','CycleTime','SettingTime','Status')                   
    End              
                 
 END 
