CREATE PROCEDURE [dbo].[BOM_Material_Param_Hlp_ItemECN](@ItemNature char(2), @Status int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))    
    
 As    
    
 SET NOCOUNT ON    
    
 Begin    

   Select Distinct a.ItemCode, c.ItemDescription, a.Status, c.ItemNature    
   From BOM_Inspection_Parameter a    
   Left Outer Join INV_Material_Master c    
   On a.ItemCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID    
   Where a.BranchID = @BranchID and a.CompID = @CompID    
   and (@ItemNature='' OR c.ItemNature = @ItemNature)  and (@Status=-1 OR a.Status=@Status)      
   and a.ItemCode in (Select ItemCode From dbo.fn_BOM_ECN(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)a     
    Where ReqStatus Not in('A','C','H') and BackEndField in('ShortName','ParameterDesc','InstrumentTypeDesc','Dimension','FromValue','ToValue','Mean','Defect','Validate','ParamException','Seq','Type','Status')    
    and EffStatus = 'A'  and Source = 'PARAMETER DETAIL'  and a.ItemCode = ItemCode and a.branchID = BranchID and a.CompID = CompID)    
      
 END 
GO

