 CREATE PROCEDURE [dbo].[BOM_ProductStructure_Hlp_ParentECN](@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))    
    
As    
    
SET NOCOUNT ON    
    
  Begin    
    
   Select Distinct h.ParentCode, m.ItemDescription, m.UomDesc, n.DrawingNo   
   From BOM_Structure_Hdr h    
   Left Outer Join MATERIAL_MASTER m    
    On h.ParentCode = m.ItemCode and h.BranchID = m.BranchID and h.CompID=m.CompID    
    Left Outer Join BOM_Drawing_Master n      
    On m.ItemCode=n.ItemCode and  (n.Type='O' or n.Type is null)      
   Where h.BranchID=@BranchID and h.CompID=@CompID    
   and h.ParentCode in (Select ItemCode From dbo.fn_BOM_ECN(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)a     
    Where Source = 'PRODUCT STRUCTURE' and ReqStatus Not in ('A','C','H') and BackEndField in('ChildCode','Qty','Explodable','Status') and EffStatus = 'A'    
    and h.ParentCode = ItemCode and h.branchID = BranchID and h.CompID = CompID)    
   Order by h.ParentCode    
       
  End  
  
GO

/****** Object:  StoredProcedure [dbo].[BOM_Rpt_ECN_DrawingMaster]    Script Date: 17/06/2026 11:29:49 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[BOM_Rpt_ECN_DrawingMaster](@ItemCode varchar(20), @Source varchar(50), @DocType Varchar(3), @DocNo int, @DocDate datetime,@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @FinYear Varchar(20))    
    
As    
    
SET NOCOUNT ON    
    
 Begin    
    
   Select a.Source,  b.DrgRevNo, b.Flg, b.Transtamp as EffDate,     
    Case When b.Status=1  Then 'Active' Else 'Inactive' End As Status    
   From dbo.fn_BOM_ECN_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)a    
   Left Outer Join     
    (    
     Select f.ItemCode, f.RevisionNo as DrgRevNo, f.Status, f.Transtamp, f.BranchId, f.CompId, 'Before' as Flg    
     From BOM_Drawing_Master_His f     
     Where f.ItemCode = @ItemCode and f.Transtamp=    
      (    
       Select Max(Transtamp)     
       From BOM_Drawing_Master_His c       
       Where c.ItemCode=f.ItemCode---- and c.DrawingNo=f.DrawingNo and c.DrawingCode=f.DrawingCode and c.Type=f.Type    
       and c.Branchid = f.Branchid     
       and c.CompID=f.CompID and c.Transtamp < @RptDate and c.Status =1  
      )     
     Union    
      Select e.ItemCode, e.RevisionNo as DrgRevNo, e.Status, e.Transtamp, e.BranchID, e.CompID,'After' as Flg    
      From BOM_Drawing_Master_His e    
      Where e.ItemCode  = @ItemCode and e.Transtamp=    
       (    
        Select Min(Transtamp) From BOM_Drawing_Master_His c    
        Where c.ItemCode=e.ItemCode ----and c.DrawingNo=e.DrawingNo and c.DrawingCode=e.DrawingCode and c.Type=e.Type    
        and c.Branchid = e.Branchid and c.CompID=e.CompID    
        and c.Transtamp > @RptDate and c.Status=1   
       )    
    )b    
   On a.ItemCode=b.ItemCode and a.BranchID = b.BranchID and a.CompID =b.CompID    
   Where a.Source=@Source and a.DocNo=@DocNo and a.DocDate=@DocDate and a.DocType=@DocType     
 End
GO

/****** Object:  StoredProcedure [dbo].[BOM_Rpt_ECN_Hlp_Doc]    Script Date: 17/06/2026 11:29:49 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

 CREATE PROCEDURE [dbo].[BOM_Rpt_ECN_Hlp_Doc](@RptOpn Char(1), @FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))      
      
 As      
      
 SET NOCOUNT ON      
      
 Begin      
      
  If @RptOpn = 'R'      
   Select Distinct a.DocType, a.DocNo, a.DocDate, a.ItemCode, b.ItemDescription as ItemDesc,     
   Max(Convert(Varchar, a.TranStamp, 120)) as Transtamp, Convert(Varchar, a.EffDate, 120) as EffDate, a.Source      
   From dbo.fn_BOM_ECN(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear)a      
   Left Outer Join INV_Material_Master b      
   On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID= b.CompID      
   Where a.DocDate between @FromDate and @ToDate and a.EffStatus = 'A'      
   and a.ReqStatus = 'N'      
   Group by a.DocNo, a.DocDate, a.DocType,  a.ItemCode, b.ItemDescription, a.EffDate, a.Source      
  Else      
         
   Select Distinct a.DocType, a.DocNo, a.DocDate, a.ItemCode, b.ItemDescription as ItemDesc,     
   Max(Convert(Varchar, a.TranStamp, 120)) as Transtamp, Convert(Varchar, a.EffDate, 120) as EffDate, a.Source      
   From dbo.fn_BOM_ECN(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear)a      
   Left Outer Join INV_Material_Master b      
   On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID= b.CompID      
   Where a.DocDate between @FromDate and @ToDate and a.EffStatus = 'A'      
   and a.ReqStatus = 'A'      
   Group by a.DocNo, a.DocDate, a.DocType, a.ItemCode, b.ItemDescription, a.EffDate, a.Source       
      
 End
GO

/****** Object:  StoredProcedure [dbo].[BOM_Rpt_ECN_ItemMaster]    Script Date: 17/06/2026 11:29:49 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[BOM_Rpt_ECN_ItemMaster](@ItemCode Varchar(20), @Source varchar(50), @DocType Varchar(3), @DocNo int, @DocDate datetime,@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @FinYear Varchar(20))    
    
As    
    
SET NOCOUNT ON    
    
 Begin    
    
  Select a.ItemCode, b.ItemDesc, a.Source, c.SDesc as ShortDesc, b.Flg,  Case b.PurchaseNature when 'L' then 'Local' When 'I' then 'Import' Else 'Both' end as  PurchaseNature,     
   Case When b.BoughtOut='M' then 'MANUFACTURED' When b.BoughtOut='B' then 'BOUGHTOUT' Else 'Both (MANUFACTURED,BOUGHTOUT)' End as BoughtOut,    
   Case When b.Status ='1' Then 'Active'Else 'Inactive'  End As EffStatus, b.Transtamp as EffDate  
  
  From dbo.fn_BOM_ECN_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)a    
  Left Outer Join    
   (    
    Select ItemCode, ItemDescription as ItemDesc, UOM as UOMCode, i.BoughtOut, PurchaseNature, Status, BranchID, CompID,'Before' as Flg, Transtamp     
    From INV_Material_Master_His i    
    Where i.ItemCode = @ItemCode and  i.Transtamp=    
     (    
      Select Max(Transtamp) From INV_Material_Master_His c    
      Where c.ItemCode=i.ItemCode and c.Branchid = i.Branchid and c.CompID=i.CompID     
      and c.Transtamp < @RptDate and c.Status=1  
     )    
    Union    
    Select ItemCode, ItemDescription as ItemDesc, UOM as UOMCode, i.BoughtOut, PurchaseNature, Status,  BranchID, CompID,'After' as Flg,Transtamp     
    From INV_Material_Master_His i    
    Where i.ItemCode = @ItemCode and i.Transtamp=    
     (    
      Select Min(Transtamp) From INV_Material_Master_His c    
      Where c.ItemCode=i.ItemCode and c.Branchid = i.Branchid and c.CompID=i.CompID    
      and c.Transtamp > @RptDate and c.Status=1  
     )    
   )b    
  On a.ItemCode=b.ItemCode and a.BranchId= b.BranchID and a.CompId=b.CompId    
  Left Outer Join INV_UOM_MASTER c    
   On b.UOMCode=c.Code and b.BranchID=c.BranchID and b.CompID=c.CompID    
  Where a.Source=@Source and a.DocNo= @DocNo and a.DocDate = @DocDate and a.DocType=@DocType    
  Order by b.Flg desc    
    
 End 
GO

