  CREATE PROCEDURE [dbo].[BOM_Rpt_ECN_ItemwiseMachwiseAfter](@ItemCode varchar(20),@Source varchar(50),@DocType Varchar(3), @DocNo int, @DocDate datetime,@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @FinYear Varchar(20))    
    
As    
    
SET NOCOUNT ON    
    
 Begin    
    
  Select Distinct b.Flg, a.Source, b.MachineCode , c.ItemDescription as ItemDesc, b.CycleTime, b.SettingTime,    
 Case When b.Status=1 Then 'Active'Else 'Inactive' End As EffStatus, b.EffDate    
  From dbo.fn_BOM_ECN_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)a    
  Left Outer Join    
  (    
    Select e.ItemCode, e.MachineCode, e.CycleTime, e.SettingTime, e.Status, e.Transtamp as EffDate, e.BranchId, e.CompId,'After' as Flg    
    From BOM_ItemwiseMachinewiseCycleTime_His e    
    Where e.ItemCode = @ItemCode and e.Transtamp=    
   (    
    Select Min(Transtamp) From BOM_ItemwiseMachinewiseCycleTime_His c    
    Where c.ItemCode = e.ItemCode And c.BranchID = e.BranchID and c.CompID=e.CompID  and c.Status=1 and c.Transtamp > @RptDate    
  )    
  )b    
  On a.ItemCode=b.ItemCode and a.BranchID = b.BranchID and a.CompID =b.CompID    
  Left Outer Join INV_Material_Master_His c    
  On c.ItemCode=b.MachineCode and c.BranchId=b.BranchID and c.CompID=b.CompId    
  Where a.Source=@Source and a.DocNo= @DocNo and a.DocDate= @DocDate and a.DocType= @DocType     
  Order by b.MachineCode   
 End
