 CREATE PROCEDURE [dbo].[BOM_Rpt_ECN_ItemwiseMachwiseBefore](@ItemCode Varchar(20), @Source varchar(50),@DocType Varchar(3), @DocNo int, @DocDate datetime,@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @FinYear Varchar(20))   
 
    
As    
 Begin  
     
 SET NOCOUNT ON    
    
   Select Distinct 'Before' as Flg, a.Source, b.MachineCode, c.ItemDescription as ItemDesc, b.CycleTime, b.SettingTime,    
   Case When b.Status=1 Then 'Active' Else 'Inactive' End As EffStatus, b.Transtamp as EffDate    
   From dbo.fn_BOM_ECN_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)a    
   Left Outer Join BOM_ItemwiseMachinewiseCycleTime_His b    
   On a.ItemCode=b.ItemCode and a.BranchID = b.BranchID and a.CompID =b.CompID    
   Left Outer Join INV_Material_Master c    
   On c.ItemCode=b.MachineCode and c.BranchId=b.BranchID and c.CompID=b.CompId    
