 CREATE PROCEDURE [dbo].[BOM_Rpt_ECN_ParameterAfter](@ItemCode varchar(20),@Source varchar(50),@DocType Varchar(3), @DocNo int, @DocDate datetime,@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @FinYear Varchar(20))      
      
As      
      
SET NOCOUNT ON      
      
 Begin      
  Select * from    
  (Select Distinct 'After' as Flg, a.Source, b.ShortName, b.ParamCode,      
   b.ParameterDesc, b.InstrumentTypeCode, c.InstrumentType as InstrumentTypeDesc, b.Dimension, b.FromValue, b.ToValue, b.Mean, b.Defect, b.Validate,      
   b.ParamException, b.Seq,      
   Case When b.Type = 'PT' then 'Product'      
   When b.Type = 'PS' Then 'Process'      
   When b.Type = 'SP' Then 'Set Up' Else 'Packing' End as Type,      
   Case When b.Status=1  Then 'Active' Else 'Inactive' End As EffStatus, b.Transtamp as EffDate      
  From dbo.fn_BOM_ECN_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)a      
  Left Outer Join      
  (      
   Select h.ItemCode, h.ParamCode, h.ShortName, h.Parameter as ParameterDesc, h.InstrumentTypeCode, h.Dimension, h.FromValue, h.ToValue, h.Mean, h.Defect,   
   h.Validate, h.Exption as ParamException, h.Sequence as Seq, h.Type, h.Status, h.Transtamp, h.BranchId, h.CompId, 'After' as Flg      
   From BOM_Inspection_Parameter_his h      
   Where h.ItemCode = @ItemCode       
    and h.Transtamp =       
    (      
     Select Min(Transtamp) From BOM_Inspection_Parameter_his c      
     Where  c.ItemCode = @ItemCode  And c.BranchID = h.BranchID --c.ParamCode = h.ParamCode And      
     and c.CompID=h.CompID  and c.Transtamp > @RptDate   and c.Status=1  
    )      
  )b      
  On a.ItemCode=b.ItemCode and a.BranchID = b.BranchID and a.CompID =b.CompID      
  Left Outer Join BOM_InstrumentType_Master c      
  On c.InstrumentTypeCode=b.InstrumentTypeCode and c.BranchId=b.BranchID and c.CompID=b.CompId      
  Where a.Source=@Source and a.DocNo= @DocNo and a.DocDate= @DocDate and a.DocType= @DocType)x       
  Order by x.Flg desc     
     
 End
GO

