   Left Outer Join    
   (    
    Select e.ItemCode, e.StageCode,  e.OperationCode, e.OperationSequence as OperationSeq, e.Status, e.Transtamp as EffDate, e.BranchId, e.CompId,'After' as Flg    
    From BOM_Mps_Master_His e    
    Where e.ItemCode = @ItemCode and e.Transtamp=    
     (    
      Select Min(Transtamp) From BOM_Mps_Master_His c    
      Where c.ItemCode = e.ItemCode And c.BranchID = e.BranchID   
  and c.CompID=e.CompID and c.Status=1 and c.Transtamp > @RptDate    
     )    
   )b    
   On a.ItemCode=b.ItemCode and a.BranchID = b.BranchID and a.CompID =b.CompID    
   Left Outer Join INV_Material_Master c    
   On c.ItemCode =b.StageCode and c.BranchId=b.BranchID and c.CompID=b.CompId    
   Left Outer Join BOM_Operation_Master d    
   On d.OperationCode =b.OperationCode and d.BranchId=b.BranchID and d.CompID=b.CompId    
   Where a.Source=@Source and a.DocNo= @DocNo and a.DocDate= @DocDate and a.DocType= @DocType     
   Order by b.Flg desc    
 End
GO

