 CREATE PROCEDURE [dbo].[BOM_Rpt_ECN_ProcessSeqBefore](@ItemCode Varchar(20), @Source varchar(50),@DocType Varchar(3), @DocNo int, @DocDate datetime,@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @FinYear Varchar(20))    
    
As    
    
SET NOCOUNT ON    
  
    
 Begin    
    
  
   Select Distinct 'Before' as Flg, a.Source, b.ItemCode, b.StageCode, c.ItemDescription as ItemDesc, b.OperationCode, d.OperationName, b.OperationSequence as OperationSeq,    
   Case When b.Status=1 Then 'Active'     
      Else  'Inactive' End As EffStatus, b.Transtamp as EffDate    
   From dbo.fn_BOM_ECN_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)a    
   Left Outer Join BOM_Mps_Master_His b    
   On a.ItemCode=b.ItemCode and a.BranchID = b.BranchID and a.CompID =b.CompID    
   Left Outer Join INV_Material_Master c    
   On c.ItemCode =b.StageCode and c.BranchId=b.BranchID and c.CompID=b.CompId    
   Left Outer Join BOM_Operation_Master d    
   On d.OperationCode =b.OperationCode and d.BranchId=b.BranchID and d.CompID=b.CompId    
   Where a.Source=@Source and a.DocNo= @DocNo and a.DocDate= @DocDate and a.DocType= @DocType    
 and b.TranStamp = (Select Max(Transtamp) From BOM_Mps_Master_His c    
       Where c.ItemCode = b.ItemCode  And c.Branchid = @BranchID   
       and c.CompID=@CompID and c.Status=1 and c.Transtamp < @RptDate)    
  
   Order by Flg desc    
 End
