CREATE PROCEDURE [dbo].[BOM_UP_CODE]
	(@Code			[int],
	 @Description 		[varchar](30),
	 @DataType 		[char](1),
	 @Width 		[int],
	 @AutoIncrement 	[bit],
	 @Status		[bit],
	 @Userid 		[varchar](10),
	 @Branchid 		[varchar](3),
	 @Compid 		[varchar](3))

AS 
BEGIN
SET NOCOUNT ON

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		UPDATE [BOM_CODE] 
		
		SET  	 [Description]	 = @Description,
			 [DataType]	 = @DataType,
			 [Width]	 = @Width,
			 [AutoIncrement]	 = @AutoIncrement,
			 [Status] = @Status,
			 [Userid]	 = @Userid
			
		
		WHERE 
			( [Code]	 = @Code  AND
			 [Branchid]	 = @cBranchid  AND
			 [Compid]	 = @Compid)
		
		FETCH NEXT FROM BranchidList into @cBranchid 
	END
 	
	close BranchidList
	deallocate BranchidList
END
GO

