SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO






CREATE PROCEDURE [dbo].[ClosingStock_Rep] (@itemCode varchar(20) ,@Compid varchar(10), @FinYear varchar(20),
	@ItemDesc_1 varchar(50) output,
--	@Uom_1  char(3) output, 
	@OBQty_1 float output,
	@RecQty_1 float output,
	@IssQty_1 float output,
	@CBQty_1 float output,
	@Cval_1 float output
)
as 

SET NOCOUNT ON

declare 
	@ItemDesc varchar(50),
	@CBQty float,
	@OBQty float,
	@RecQty float,
	@IssQty float,
--	@Uom char(3),
	@Rate float,
	@Cval float

Begin
	
	--Fetch the Open Balance Qty and Closing Balance Qty
	 select @OBqty = SUM(ob_qty),@CBqty = SUM(cb_qty) from inv_stock_mast where item_code=@ItemCode and compid=@compid
	--Fetch the Item description ,uom rate
	 Select @ItemDesc=item_desc,@Rate = rate from inv_matl_Mast where item_code=@ItemCode and compid=@CompId
	--Fetch the Total Recived Qty an Total Issue Qty.
	select @RecQty = sum(qty_received),@IssQty = SUM(ISSUED_QTY) from inv_matltran_dtl where item_code= @ItemCode and compid= @CompId  AND FINYEAR=@FinYear group by item_code
	--Calculating the Closing Balance Value
	set @Cval=@CBQty * @Rate
	
	SET @ItemDesc_1=@ItemDesc
	set   @OBQty_1 =@OBQty
	SET @RecQty_1=@RecQty 
	SET @CBQty_1=@CBQty
	SET @IssQty_1=@IssQty
	SET @Cval_1=@Cval
end


GO

