CREATE PROCEDURE [dbo].[COM_AcceptanceUpdate_Fil_DCDocument](@DocType varchar(3), @DocNo int, @DocDate datetime, @BranchID varchar(3), 
	@CompID varchar(3), @Finyear varchar(20))                                  
As                                  
BEGIN                                       
	SET NOCOUNT ON; 

	Select distinct a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.VendorCode, 
		IsNull((Select Top 1 b.PartyName From FAS_PARTY_MASTER b Where b.PartyCode=a.VendorCode and b.Branchid=a.Branchid 
					and b.Compid=a.Compid),'') As PartyName,
		a.DCNo,a.DCDate,a.InvoiceNo,a.InvoiceDate,
		a.TransporterName,a.VehicleNo,a.Narration 
	From ReceiptEntry a 
	Where a.ReceiptEntryType=@DocType and a.ReceiptEntryNo=@DocNo and a.ReceiptEntryDate=@DocDate 
	and a.ReceiptQty>0 and (a.ReceiptDate Is Not Null)
	and a.BranchID=@BranchID and  a.Compid=@CompID   --and Finyear=@Finyear
END
GO

/****** Object:  StoredProcedure [dbo].[COM_AcceptanceUpdate_Fil_DocumentDetails]    Script Date: 17/06/2026 11:29:50 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[COM_AcceptanceUpdate_Fil_DocumentDetails](@DocType varchar(3), @DocNo int, @DocDate datetime, @InwardType varchar(3),    
 @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                                      
As                                      
BEGIN                                           
 SET NOCOUNT ON;      
 Select Distinct x.ItemCode, x.ItemDescription, x.ItemNature, x.PurchaseUOMDesc, x.PurchaseUOMDecimal,    
   x.ScheduleDate, x.ChallanQty, x.ReceiptQty, IsNull(x.RefType,'') As RefType, 
   IsNull(x.RefNo,0) As RefNo, IsNull(x.RefDate,'1900-01-01') As RefDate,   
   x.AcceptedQty, x.RejectionQty, x.ScrapQty, abs(x.QCCheck) As QCCheck,    
   x.ItemGroupKey, x.isDrawingRecd, IsNull(k.DrawingNo,0) As DrawingNo, 
   IsNull(k.RevisionNo,0) As RevisionNo, x.HeatNo, x.HeatNoApplicable,     
   x.ShelfLifePeriodApplicable, IsNull(x.ItemSeq,0) As ItemSeq, 
   IsNull(x.Trace_ItemSeq,0) As Trace_ItemSeq,   
   x.ManufactureDate, IsNull(x.ShelfLifeDays,0) As ShelfLifeDays    
 From(    
  Select a.ItemCode,c.ItemNature,    
   c.ItemDescription,c.PurchaseUOMDesc,c.PurchaseUOMDecimal,    
   a.ScheduleDate, a.ChallanQty, a.ReceiptQty, a.RefType,    
   a.RefNo, a.RefDate, a.AcceptedQty, a.RejectionQty, a.ScrapQty,      
   IsNull((Case When IsNull(@InwardType,'') = 'P' Then    
     isnull((Select distinct b.QCCheck From PUR_Vendor_ItemMaster b     
     Where b.VendorCode=a.VendorCode and b.ItemCode=a.ItemCode     
      and b.Branchid=a.Branchid and b.Compid=a.Compid),0)    
   When IsNull(@InwardType,'') = 'S' Then    
     isnull((select distinct b.QCCheck from PUR_SubCont_ItemMaster b     
     where b.SubContCode=a.VendorCode and b.RecdItemCode=a.ItemCode and b.ItemGroupkey = a.ItemGroupKey      
      and b.BranchID=a.BranchID and b.CompID=a.CompID),0)    
   When IsNull(@InwardType,'') = 'L' Then    
     isnull((select distinct b.QCCheck from PUR_SubCont_ItemMaster b     
     where b.SubContCode=a.VendorCode and b.RecdItemCode=a.ItemCode and b.ItemGroupkey = a.ItemGroupKey      
      and b.BranchID=a.BranchID and b.CompID=a.CompID),0)    
   When IsNull(@InwardType,'') = 'D' Then    
     isnull((select distinct b.QCCheck from PUR_SubCont_ItemMaster b     
     where b.SubContCode=a.VendorCode and b.RecdItemCode=a.ItemCode and b.ItemGroupkey = a.ItemGroupKey      
      and b.BranchID=a.BranchID and b.CompID=a.CompID),0)    
   When IsNull(@InwardType,'') = 'W' Then    
     isnull((select distinct b.QCCheck from PUR_SubCont_ItemMaster b     
     where b.SubContCode=a.VendorCode and b.RecdItemCode=a.ItemCode and b.ItemGroupkey = a.ItemGroupKey      
      and b.BranchID=a.BranchID and b.CompID=a.CompID),0)    
   When IsNull(@InwardType,'') = 'M' Then    
     isnull((select distinct b.QCCheck from PUR_SubCont_ItemMaster b     
     where b.SubContCode=a.VendorCode and b.RecdItemCode=a.ItemCode and b.ItemGroupkey = a.ItemGroupKey      
      and b.BranchID=a.BranchID and b.CompID=a.CompID),0)    
  --'  When IsNull(@InwardType,'') = 'I' Then    
  --'    isnull((select distinct b.QCCheck from PUR_SubCont_ItemMaster b     
  --'    where b.SubContCode=a.VendorCode and b.RecdItemCode=a.ItemCode and b.ItemGroupkey = a.ItemGroupKey      
  --'    and b.BranchID=a.BranchID and b.CompID=a.CompID),0) QCCheck,    
   Else    
    0    
   End),0) As QCCheck,    
   a.ItemGroupKey, a.isDrawingRecd, a.ReceiptDate, AcceptedDate, a.HeatNo, c.HeatNoApplicable,    
   c.ShelfLifePeriodApplicable, a.ItemSeq, IsNull(t.ItemSeq,0) As Trace_ItemSeq,   
    t.ManufactureDate, IsNull(t.ShelfLifeDays,0) As ShelfLifeDays  
  From RECEIPTENTRY a     
  Left Outer Join REC_ReceiptEntry_Dtl_Trace t    
    On a.ReceiptEntryNo=t.ReceiptEntryNo and a.ReceiptEntryDate=t.ReceiptEntryDate and a.ReceiptEntryType=t.ReceiptEntryType    
      and a.ItemCode=t.ItemCode and a.BranchID=t.BranchID and a.CompID=t.CompID    
  Left Outer Join MATERIAL_MASTER c     
    On a.ItemCode=c.ItemCode and a.Branchid=c.Branchid and a.Compid=c.Compid     
  Where a.ReceiptEntryType=@DocType and a.ReceiptEntryNo=@DocNo and a.ReceiptEntryDate=@DocDate     
    and a.BranchID=@BranchID and  a.Compid=@CompID   --and Finyear=@Finyear    
  ) x    
  Left Outer Join BOM_DrawingTran_Dtl k    
    On x.ItemCode = k.ItemCode and x.ItemGroupkey = k.ItemGroupkey and x.RefType = k.RefType and x.RefNo = k.RefNo    
      and x.RefDate = k.RefDate     
  Where ((x.QCCheck=1 and (x.AcceptedQty+x.RejectionQty+x.ScrapQty) > 0)     
    or (x.QCCheck=0)) and ((x.AcceptedQty+x.RejectionQty) = 0 or AcceptedDate is null)    
    and x.ReceiptQty > 0 and x.ReceiptDate is Not Null    
  Order by ItemSeq    
END    
GO

