   Delete From COM_BudgetMaster_Dtl Where BudgetFor = @BudgetFor and Path = @Path and Type = @Type and Code = @Code and FromDate = @FromDate and ToDate <= @ToDate and BranchID = @BranchID and CompID = @CompID         
 and Finyear = @Finyear        
         
   INSERT INTO [COM_BudgetMaster_Dtl]                 
                  
 ([BudgetFor],  
 [FromDate],            
 [ToDate],            
 [Path],          
 [Type],            
 [Code],            
 [BudgetValue],            
 [BudgetPerc],     
 [IsFixed],      
 [IsHide],      
