CREATE PROCEDURE [dbo].[COM_CountryCity_Master_Auth](@AsOnDate datetime, @ChildCode int, @ParentCode int, @AuthStatus char(2), @AuthDate datetime, @UserID varchar(10))        
AS        
 Begin        
  SET NOCOUNT ON        
      
  Declare @RevIncr int        
  Select @RevIncr=Case When Right(@AuthStatus, 1)='A' Then 1 Else 0 End        
      
  Insert into COM_CountryCity_Master        
  Select  a.ChildCode, a.ChildName, a.TypeCode, a.ParentCode, a.RevNo+@RevIncr, Convert(varchar(10),@AsOnDate,120), Right(@AuthStatus, 1)+Right(a.EffStatus, 1),        
   a.EffDate, Case Right(@AuthStatus, 1) When 'H' Then a.isTranLock Else '0' End, @UserID, @AsOnDate           
  From COM_CountryCity_Master a        
  Where a.TranStamp = (Select Max(b.TranStamp) From COM_CountryCity_Master b        
               Where b.TranStamp <= @AsOnDate and b.ChildCode=a.ChildCode and b.ParentCode = a.ParentCode            
             )        
  and a.ChildCode = @ChildCode and a.ParentCode = @ParentCode           
  and  Left(a.EffStatus, 1) Not in ('A', 'X')        
         
 End
GO

