CREATE PROCEDURE [dbo].[COM_CountryCity_Master_Ins]          
 (          
  @ChildCode  [int],          
  @ChildName  [varchar](50),         
  @TypeCode   [varchar](5),         
  @ParentCode  [int],          
  @EffStatus  [Char](2),          
  @EffDate  [datetime],          
  @isTranLock [bit],          
  @UserID   [varchar](10),          
  @TranStamp  [datetime]          
 )          
AS          
BEGIN          
SET NOCOUNT ON          
 Declare @RevNo as int          
 Declare @RevDate as datetime          
          
 Declare @isCity as bit          
  Select @isCity = Convert(bit, @ParentCode)          
          
 Declare @RevIncr int          
  Select @RevIncr=Case When Right(@EffStatus, 1)='A' Then 1 Else 0 End          
          
 Select @RevNo=-1           
 Select @RevDate=Convert(varchar(10),@TranStamp,120)          
           
 IF @EffStatus<>'NA'          
  Begin          
          
   /*Select @RevNo = IsNull(a.RevNo, @RevNo)+@RevIncr,  @RevDate =IsNull(a.RevDate, @RevDate)           
   From fn_COM_CountryCity_Master('M', @TranStamp, @TranStamp, '','')  a          
   Where a.CountryCode = @CountryCode and  a.ParentCode = @ParentCode    */      
          
   Select @RevNo = IsNull(a.RevNo, @RevNo) ,  @RevDate =IsNull(a.RevDate, @RevDate)           
   From  fn_COM_CountryCity_Master_Grp (@isCity, 'W', @TranStamp)  a          
   Where  a.ChildCode = @ChildCode and  a.ParentCode = @ParentCode         
            
  End          
           
           
 BEGIN          
   INSERT INTO [COM_CountryCity_Master]           
            
    (
		[ChildCode],          
		[ChildName],          
		[TypeCode],        
		[ParentCode],          
		[RevNo],          
		[RevDate],          
		[EffStatus],          
		[EffDate],          
		[isTranLock],          
		[UserID],          
		[TranStamp]          
   )           
            
  VALUES           
           
   (
	@ChildCode,          
	@ChildName,          
	@TypeCode,        
	@ParentCode,          
	@RevNo,          
	@RevDate,          
	@EffStatus,          
	@EffDate,          
	@isTranLock,          
	@UserID,           
	@TranStamp          
   )          
           
 END          
          
END 
GO

