CREATE PROCEDURE [dbo].[COM_CountryCityMaster_Hlp_Country](@Type bit, @FrmTranType char(1),  @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))        
As        
 Begin        
           
  SET NOCOUNT ON        
  /*      
  Select Distinct a.CountryName, a.CountryCode, Convert(varchar,a.EffDate,120) as EffDate, a.EffStatus, a.IsTranLock               
  From dbo.fn_COM_CountryCity_Master('M', @AsOnDate, @RptDate, @BranchID, @CompID) a        
  Where a.ParentCode=0   */      
        
  If @Type='0'   --Country        
   Begin        
    Select Distinct b.ChildName, b.ChildCode, Convert(varchar,b.EffDate,120) as EffDate, b.EffStatus, b.IsTranLock        
    From dbo.fn_COM_CountryCity_Master_Grp(@Type, @FrmTranType, @AsOnDate)a         
    Left Outer Join dbo.fn_COM_CountryCity_Master('M', @AsOnDate, @RptDate, @BranchID, @CompID)b        
    On a.ParentCode=b.ParentCode and a.ChildCode = b.ChildCode         
    Where b.ParentCode=0         
   End        
  Else        
   Begin        
    Select Distinct b.ChildName, b.ChildCode, Convert(varchar,b.EffDate,120)EffDate, b.EffStatus , b.IsTranLock        
    From dbo.fn_COM_CountryCity_Master_Grp(@Type, @FrmTranType, @AsOnDate) a        
    Left Outer Join dbo.fn_COM_CountryCity_Master('M', @AsOnDate, @RptDate, @BranchID, @CompID)b        
    On a.ParentCode=b.ChildCode         
    Where b.ParentCode=0        
   End        
          
 End
