CREATE PROCEDURE [dbo].[COM_CountryCityMaster_Hlp_State](@FrmTranType char(1), @ParentCode int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))              
As        
BEGIN        
 SET NOCOUNT ON        
            
 IF @FrmTranType='N' --For Create        
  
  Begin        
    Select a.ChildName, a.ChildCode --,a.TypeCode         
    From fn_COM_CountryCity_Master('A',@AsOnDate, @RptDate, @BranchID, @CompID) a        
    Where Exists        
