     Where s.ParentCode=0 and s.ChildCode=a.ParentCode and s.ChildCode=@ParentCode        
     and a.EffStatus Not In ('AX', 'AD')         
    )        
  End   
         
 Else    --For Modify        
  
  Begin  
          
    Select a.ChildName, a.ChildCode, Convert(varchar,a.EffDate,120)EffDate, a.EffStatus , a.IsTranLock, a.TypeCode        
    From fn_COM_CountryCity_Master('M',@AsOnDate, @RptDate, @BranchID, @CompID) a        
