/****** Object:  StoredProcedure [dbo].[COM_FinyearChangeProcess_INS_CompanyFinyear]    Script Date: 17/06/2026 11:29:51 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[COM_FinyearChangeProcess_INS_CompanyFinyear](@UserID int, @AsOnDate datetime, @RptDate datetime, 
	@PrevFinyear Varchar(20))  
As   
BEGIN
	SET NOCOUNT ON;

	Declare @RevDate datetime  
	Select @RevDate=Convert(varchar(10), @AsOnDate,120)  
  
	Declare @PrevFinStart datetime  
	Select @PrevFinStart = Convert(datetime, Left(@PrevFinyear, 7) + '-01',120)  
   
	Declare @PrevFinEnd datetime  
	Select @PrevFinEnd = Convert(datetime, Right(@PrevFinyear, 7) + '-31',120)  
  
	Declare @CurFinStart datetime  
	Select @CurFinStart = DateAdd(yyyy, 1, @PrevFinStart)  
  
	Declare @CurFinEnd datetime  
	Select @CurFinEnd = DateAdd(yyyy, 1, @PrevFinEnd)  
  
	/* Insert Data Into Table */
	Insert into Company_Finyear  
		Select a.CompID, a.BranchID, @CurFinStart as FromYear, @CurFinEnd as ToYear,   
			'Y' as Status, '1' as FASStatus   
		From Company_Finyear a   
		Where a.FromYear=@PrevFinStart  
			and Not Exists   
			(  
				Select * From Company_Finyear s  
				Where s.CompID=a.CompID and s.BranchID=a.BranchID   
				and (s.FromYear between @CurFinStart and @CurFinEnd  
				Or (s.ToYear between @CurFinStart and @CurFinEnd)  
				)    
			)    
END
