As 

Begin

	SET NOCOUNT ON

	Declare @RevDate datetime
		Select @RevDate=Convert(varchar(10),@AsOnDate,120)

	Declare @CurFinStart datetime
		Select @CurFinStart = DateAdd(yyyy,1,Convert(datetime, Left(@PrevFinyear, 7) + '-01',120))

	Declare @CurFinEnd datetime
		Select @CurFinEnd = DateAdd(yyyy,1,Convert(datetime, Right(@PrevFinyear, 7) + '-31',120))

	Declare @CurFinYear Varchar(20)
		Select @CurFinYear = Convert(Varchar,'04-') + Convert(Varchar(4),Year(@CurFinStart)) + ' ' + Convert(Varchar,'03-') + Convert(Varchar(4),Year(@CurFinEnd))

	Insert into COM_DocumentType_Master 
		Select a.DocumentType, a.DocumentDesc, @StartingNo as StartingNo, a.RestartAt, a.Prefix, a.Suffix, a.WidthNo, a.IsShowDocType, 
			a.PertainingTo, a.ModuleCode, 0 as RevNo, @RevDate as RevDate, 'AA' as EffStatus, @AsOnDate as EffDate, 
			'0' as isTranLock, @UserID as UserID, @BranchID as BranchID, @CompID as CompID, @CurFinYear as FinYear, @AsOnDate as TranStamp 
		From fn_COM_DocumentType_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID)a
		Where a.DocumentType=@DocumentType and a.PertainingTo=@PertainingTo and a.ModuleCode=@ModuleCode and Finyear=@PrevFinyear

