CREATE PROCEDURE [dbo].[Com_Get_Trace_LotMaster_TmpQty](@DocType Varchar(3), @DocNo int, @DocDate Datetime, @ItemCode varchar(20), @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))        
  
As       
   
Begin        
        
SET NOCOUNT ON;         
        
 Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.ItemCode, d.ItemDescription, a.Qty, c.LotId,   
 e.SDesc as UOM,  a.HeatNo, a.ManufactureDate, a.SubLotId  
from REC_ReceiptEntry_Dtl_Trace a  
Left Outer Join REC_ReceiptEntry_Dtl b  
On a.ReceiptEntryNo=b.ReceiptEntryNo and a.ReceiptEntryDate=b.ReceiptEntryDate and a.ReceiptEntryType=b.ReceiptEntryType     
           and a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID     
Left Outer Join COM_Trace_LotMaster_TmpQty c  
On a.ReceiptEntryType=c.DocType and a.ReceiptEntryNo=c.DocNo and a.ReceiptEntryDate=c.DocDate   
 and  a.ItemCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID     
Left Outer Join Inv_Material_Master d  
On a.ItemCode=d.ItemCode and a.BranchID=d.BranchID and a.CompID=d.CompID  
Left Outer Join Inv_Uom_Master e  
On d.UOM=e.Code and d.BranchID=e.BranchID and d.CompID=e.CompID  
Where a.ReceiptEntryType=@DocType and a.ReceiptEntryNo=@DocNo and a.ReceiptEntryDate=@DocDate      
 and a.ItemCode=@ItemCode and a.BranchId=@BranchID and a.CompId=@CompID and a.Finyear=@Finyear        
 Order by a.SubLotId      
  
End 
