/****** Object:  StoredProcedure [dbo].[COM_GetExpression_Prompt]    Script Date: 17/06/2026 11:29:51 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO





CREATE PROCEDURE [dbo].[COM_GetExpression_Prompt] (@ModuleCode int, @FrmID int, @SCParamInclude bit, @UserKey varchar(26), @LockRefType varchar(5), @LockRefNo int, @LockRefDate datetime,
							@ValRefType varchar(5), @ValRefNo int, @ValRefDate datetime,
							@BranchID varchar(3), @CompID varchar(4), @Finyear varchar(15))

AS
 
Set NOCOUNT ON


Select a.ExprSeq, d.ExprGroupName as ExprName, dbo.fn_FrontEndExpression(a.ModuleCode, a.FrmID, a.ExprSeq, a.BranchID, a.CompID) as Expression, 
		isNull(m2.isValueEditable, m1.isValueEditable) as isValueEditable, isNull(m2.ValueUsed, isNull(m1.ValueUsed, m.ValueUsed)) as Value 
from COM_FormulaMast_Dtl a Left Outer Join COM_FormulaExpr_Group d 
	On a.ExprRoute=d.Route+d.Width and a.ModuleCode=d.ModuleCode and a.BranchID=d.BranchID and a.CompID=d.CompID 
	--Lock Status in LockRef Document
Left Outer Join 
	(Select b.FrmID, Convert(int, b.Block) as ExprSeq, b.ValueUsed, b.isValueEditable 
	from COM_FormulaCalc_Dtl b  
	Where b.DocNo=@LockRefNo and b.DocType=@LockRefType and b.DocDate=@LockRefDate and b.BlockType='Expr' and b.isValueEditable='1' 
		and b.ModuleCode=@ModuleCode and b.FrmID=@FrmID and b.BranchID=@BranchID and b.CompID=@CompID and b.finyear=@Finyear) m
	On a.FrmID=m.FrmID and a.ExprSeq=m.ExprSeq
	--Current Value in ValRef Document
Left Outer Join 
	(Select b1.FrmID, Convert(int, b1.Block) as ExprSeq, b1.ValueUsed, b1.isValueEditable  
	from COM_FormulaCalc_Dtl b1  
	Where b1.DocNo=@ValRefNo and b1.DocType=@ValRefType and b1.DocDate=@ValRefDate and b1.BlockType='Expr'
		and b1.ModuleCode=@ModuleCode and b1.FrmID=@FrmID and b1.BranchID=@BranchID and b1.CompID=@CompID and b1.finyear=@Finyear) m1
	On a.FrmID=m1.FrmID and a.ExprSeq=m1.ExprSeq
	--Temporary Running Value Prev Executing
Left Outer Join
	(Select b2.FrmID, Convert(int, b2.Block) as ExprSeq, b2.ValueUsed, b2.isValueEditable 
	from COM_tmpFormulaCalc_Dtl b2 
	Where b2.DTKey=@UserKey and b2.BlockType='Expr' and b2.ModuleCode=@ModuleCode and b2.FrmID=@FrmID and b2.BranchID=@BranchID and b2.CompID=@CompID) m2
	On a.FrmID=m2.FrmID and a.ExprSeq=m2.ExprSeq

Where a.FrmID=@FrmID 
and a.ExprSeq Not in 
				--LockRef
			(Select Convert(int, a1.BlockType) as ExprSeq 
			from COM_FormulaCalc_Dtl a1 
			Where a1.DocNo=@LockRefNo and a1.DocType=@LockRefType and a1.DocDate=@LockRefDate and a1.BlockType='Expr' and a1.isValueEditable='0' 
			and a1.ModuleCode=@ModuleCode and a1.FrmID=@FrmID and a1.BranchID=@BranchID and a1.CompID=@CompID 

			Union All
				--Any one Parameter Editable then it should be shown in Expression Value Grid
			Select ExprSeq 
			from (Select a.ExprSeq, Case When a3.ValInputMethod='SC' Then Convert(int, @SCParamInclude)*1 Else 0 End as ScCnt, Convert(int, a.IsValueEditable) as ValEdit 
						from COM_FormulaMast_Block_Dtl a Inner Join COM_FrmParamMast_Hdr a3 
						On a.Block=Convert(varchar, a3.ParamID) and a.ModuleCode=a3.ModuleCode and a.BranchID=a3.BranchID and a.CompID=a3.CompID 
						Where a.ModuleCode=@ModuleCode and a.FrmID=@FrmID and a.BlockType='Param' and a.BranchID=@BranchID and a.CompID=@CompID
						) z 
			Group by ExprSeq 
			Having Sum(ScCnt+ValEdit)=0 
			) 
and isNull(m.isValueEditable, 1) = 1
and a.ModuleCode=@ModuleCode and a.BranchID=@BranchID and a.CompID=@CompID



GO

/****** Object:  StoredProcedure [dbo].[COM_GetMultiParameter_Prompt]    Script Date: 17/06/2026 11:29:52 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[COM_GetMultiParameter_Prompt] (@ModuleCode int, @FrmID int, @SCParamInclude bit, @UserKey varchar(50), @LockRefType varchar(3), @LockRefNo int, @LockRefDate datetime,
							@ValRefType varchar(3), @ValRefNo int, @ValRefDate datetime, @VendorCode int,
							@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))

AS

Set NOCOUNT ON

Select  x.ParamID, x.ParamShortName, x.ParamLongName, x.ValInputMethod, x.ValuesDefinedType, x.LockTypeEditable, 
	isNull(z.isTypePercentage, isNull(y.isTypePercentage,  x.isTypePercentage)) as tmpTypePercentage, 
	isNull(z.isTypeEditable,  isNull(y.isTypeEditable, x.isTypeEditable)) as tmpTypeEditable, 
	isNull(z.ValueUsed, isNull(y.ValueUsed, x.ValueUsed)) as tmpValueUsed,
	isNull(z.KeyCol, isNull(y.KeyCol, x.KeyCol)) as KeyCol
from 
	(Select Distinct Convert(int, a.Block) as ParamID, b.ParamShortName, b.ParamLongName, b.ValInputMethod, b.ValuesDefinedType,
	isNull(m.isTypeEditable, a.isTypeEditable) LockTypeEditable, 
 	isNull(m1.isTypePercentage, isNull(m.isTypePercentage, a.isTypePercentage)) isTypePercentage,  isNull(m1.isTypeEditable, isNull(m.isTypeEditable, a.isTypeEditable)) isTypeEditable, 
	isNull(m1.ValueUsed, isNull(m.ValueUsed, a.ValueUsed)) ValueUsed, isNull(m1.KeyCol, m.KeyCol) as KeyCol 
	From (Select * from COM_FormulaMast_Block_Dtl where BlockType='Param') a 			--Default Values, Type
		Inner Join COM_FrmParamMast_Hdr b 
			On Convert(int, a.Block)=b.ParamID and a.ModuleCode=b.ModuleCode and a.BranchID=b.BranchID and a.CompID=b.CompID 
		--Saved Reference Values, Type (Take Fixed Lock Status from this)
		Left Outer Join 			
			(Select f.BlockType, f.Block, f.KeyCol, f.isTypePercentage, f.isTypeEditable, f.ValueUsed, f.isValueEditable 
			from COM_FormulaCalc_Dtl f 
			Where f.DocNo=@LockRefNo and f.DocType=@LockRefType and f.DocDate=@LockRefDate 
				and f.BlockType='Param' and f.KeyCol<>''  --and f.isValueEditable='1' 
				and f.ModuleCode=@ModuleCode and f.FrmID=@FrmID and f.BranchID=@BranchID and f.CompID=@CompID --and f.Finyear=@Finyear
			) m 
				On a.Block=m.Block
		    --Saved Reference Values, Type (Take Current Values from this)
		Left Outer Join 			
			(Select f1.BlockType, f1.Block, f1.KeyCol, f1.isTypePercentage, f1.isTypeEditable, f1.ValueUsed 
			from COM_FormulaCalc_Dtl f1 
			Where f1.DocNo=@ValRefNo and f1.DocType=@ValRefType and f1.DocDate=@ValRefDate 
				and f1.BlockType='Param' and f1.KeyCol<>'' and f1.ModuleCode=@ModuleCode and f1.FrmID=@FrmID and f1.BranchID=@BranchID and f1.CompID=@CompID --and f1.Finyear=@Finyear
			) m1 
				On a.Block=m1.Block
	Where a.ModuleCode=@ModuleCode and a.FrmID=@FrmID and a.BlockType='Param' and b.isMultiple='1' and a.BranchID=@BranchID and a.CompID=@CompID 
		 --Expression Value Given and Locked should be avoided (LockRef)
		and a.ExprSeq Not In 			
					(Select Convert(int, c.Block) as ExprSeq from COM_FormulaCalc_Dtl c 
					Where c.DocNo=@LockRefNo and c.DocType=@LockRefType and c.DocDate=@LockRefDate and c.Block='Expr' and c.isValueEditable='0' 
						and c.ModuleCode=a.ModuleCode and c.FrmID=a.FrmID and c.BranchID=a.BranchID and c.CompID=a.CompID) -- and c.Finyear=@Finyear) 

		and ((isNull(m.isValueEditable, a.isValueEditable)='1' and b.ValInputMethod <> 'SC' ) 
			or (Case When @SCParamInclude='1' Then b.ValInputMethod Else '' End = 'SC'))
	) x 

Left Outer Join		--Values Given Vendor Material Master

	(Select f1.BlockType, f1.Block as ParamID, f1.KeyCol, f1.isTypePercentage, f1.isTypeEditable, f1.ValueUsed 
	from COM_FormulaCalc_Dtl f1 
	Where f1.DocNo=@VendorCode and f1.DocType='VMM' 
		and f1.BlockType='Param' and f1.KeyCol<>'' and f1.ModuleCode=@ModuleCode and f1.BranchID=@BranchID and f1.CompID=@CompID -- and f1.Finyear=@Finyear
	) y 
		On x.ParamID=y.ParamID and isNull(x.KeyCol, y.KeyCol)=y.KeyCol

Left Outer Join 		--Latest Tmp Values, Type
	(Select Convert(int, Block) as ParamID, KeyCol, isTypePercentage, isTypeEditable, ValueUsed 
	from COM_tmpFormulaCalc_Dtl  
	Where DTKey=@UserKey and BlockType='Param' and KeyCol<>'' and ModuleCode=@ModuleCode and FrmID=@FrmID and BranchID=@BranchID and CompID=@CompID
	) z 
		On x.ParamID=z.ParamID and x.KeyCol=z.KeyCol

Order by x.ParamShortName
GO

/****** Object:  StoredProcedure [dbo].[COM_GetParameter_Prompt]    Script Date: 17/06/2026 11:29:52 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
