CREATE PROCEDURE [dbo].[COM_GetParameter_Prompt] (@ModuleCode int, @FrmID int, @PartyCode int, @SCParamInclude bit, @UserKey varchar(50), @LockRefType varchar(5), @LockRefNo int, @LockRefDate datetime,
							@ValRefType varchar(5), @ValRefNo int, @ValRefDate datetime,
							@BranchID varchar(3), @CompID varchar(4), @Finyear varchar(15))

AS

Set NOCOUNT ON

Select  x.ParamID, x.ParamShortName, x.ParamLongName, x.ValInputMethod, x.ValuesDefinedType, x.LockTypeEditable, 
	isNull(y.isTypePercentage, x.isTypePercentage) as tmpTypePercentage, isNull(y.isTypeEditable, x.isTypeEditable) as tmpTypeEditable, isNull(y.ValueUsed, x.ValueUsed) as tmpValueUsed 
from 
	(Select Distinct Convert(int, a.Block) as ParamID, b.ParamShortName, b.ParamLongName, b.ValInputMethod, b.ValuesDefinedType,
	isNull(m.isTypeEditable, isNull(k.isTypeEditable, a.isTypeEditable)) LockTypeEditable, 
 	isNull(m1.isTypePercentage, isNull(m.isTypePercentage, isNull(k.isTypeEditable, a.isTypePercentage))) isTypePercentage,  
	isNull(m1.isTypeEditable, isNull(m.isTypeEditable, isNull(k.isTypeEditable, a.isTypeEditable))) isTypeEditable, 
	isNull(m1.ValueUsed, isNull(m.ValueUsed, isNull(k.ValueUsed, a.ValueUsed))) ValueUsed 
	From COM_FormulaMast_Block_Dtl a 			--Default Values, Type
		Inner Join COM_FrmParamMast_Hdr b 
			On Convert(int, a.Block)=b.ParamID and a.ModuleCode=b.ModuleCode and a.BranchID=b.BranchID and a.CompID=b.CompID
		Left Outer Join 
			(Select  f.ParamID, f.isTypePercentage, f.isTypeEditable, f.ValueUsed, f.isValueEditable 
			from COM_FrmParamValues f
			Where f.ModuleCode=@ModuleCode and f.FrmID=@FrmID and f.PartyCode=@PartyCode and f.BranchID=@BranchID and f.CompID=@CompID
			) k 
 				On Convert(int, a.Block)=k.ParamID
		--Saved Reference Values, Type (Take Fixed Lock Status from this)
		Left Outer Join 			
			(Select f.BlockType, f.Block, f.isTypePercentage, f.isTypeEditable, f.ValueUsed, f.isValueEditable 
			from COM_FormulaCalc_Dtl f 
			Where f.DocNo=@LockRefNo and f.DocType=@LockRefType and f.DocDate=@LockRefDate 
				and f.BlockType='Param' and f.MultiSeq=0 and f.ModuleCode=@ModuleCode and f.FrmID=@FrmID and f.BranchID=@BranchID and f.CompID=@CompID --and f.Finyear=@Finyear --and f.isValueEditable='1' 
			) m 
				On a.Block=m.Block
		    --Saved Reference Values, Type (Take Current Values from this)
		Left Outer Join 			
			(Select f1.BlockType, f1.Block, f1.isTypePercentage, f1.isTypeEditable, f1.ValueUsed 
			from COM_FormulaCalc_Dtl f1 
			Where f1.DocNo=@ValRefNo and f1.DocType=@ValRefType and f1.DocDate=@ValRefDate 
				and f1.BlockType='Param' and f1.MultiSeq=0 and f1.ModuleCode=@ModuleCode and f1.FrmID=@FrmID and f1.BranchID=@BranchID and f1.CompID=@CompID --and f1.Finyear=@Finyear
			) m1 
				On a.Block=m1.Block
	Where a.ModuleCode=@ModuleCode and a.FrmID=@FrmID and a.BlockType='Param' and b.isMultiple='0' and a.BranchID=@BranchID and a.CompID=@CompID 
		    --Expression Value Given and Locked should be avoided (LockRef)
		and a.ExprSeq Not In 			
					(Select Convert(int, c.Block) as ExprSeq from COM_FormulaCalc_Dtl c 
					Where c.DocNo=@LockRefNo and c.DocType=@LockRefType and c.DocDate=@LockRefDate and c.Block='Expr' and c.isValueEditable='0' 
					and c.ModuleCode=a.ModuleCode and c.FrmID=a.FrmID and c.BranchID=a.BranchID and c.CompID=a.CompID) --and c.Finyear=@Finyear) 

		and ((isNull(m.isValueEditable, a.isValueEditable)='1' and b.ValInputMethod <> 'SC' ) 
			or (Case When @SCParamInclude='1' Then b.ValInputMethod Else '' End = 'SC'))
	) x 

Left Outer Join 		--Latest Tmp Values, Type
	(Select Convert(int, Block) as ParamID, isTypePercentage, isTypeEditable, ValueUsed 
	from COM_tmpFormulaCalc_Dtl  
	Where DTKey=@UserKey and BlockType='Param' and MultiSeq=0 and ModuleCode=@ModuleCode and FrmID=@FrmID and BranchID=@BranchID and CompID=@CompID) y 
		On x.ParamID=y.ParamID
GO

