CREATE PROCEDURE [dbo].[COM_INS_DOCUMENTTYPE_MASTER]
	(@DocumentType 	[char](3),
	 @Description 		[varchar](30),
	 @StartingNo 		[int],
	 @PertainingTo 		[char](3),
	 @ModuleName 	[varchar](3),
	 @Status		[bit],
	 @Userid 		[varchar](10),
	 @Branchid 		[varchar](3),
	 @Compid 		[varchar](3))

AS 

begin

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		INSERT INTO [COM_DOCUMENTTYPE_MASTER] 
			 ( [DocumentType],
			 [Description],
			 [StartingNo],
			 [PertainingTo],
			 [ModuleName],
			 [Status],
			 [Userid],
			 [Branchid],
			 [Compid]) 
		 
		VALUES 
			( @DocumentType,
			 @Description,
			 @StartingNo,
			 @PertainingTo,
			 @ModuleName,
			 @Status,
			 @Userid,
			 @cBranchid,
			 @Compid)

		commit transaction
		FETCH NEXT FROM BranchidList into @cBranchid 
	END
 	
	close BranchidList
	deallocate BranchidList
end
GO

