CREATE PROCEDURE [dbo].[Com_INS_Inspection_Option_dtl]
	(@Code 	[int],
	 @InspectionTypeCode 	[int],
	 @isVal 	[int],
	 @Val 	[varchar](50),
	 @CarStatus 	[int],
	 @Userid 	[varchar](10),
	 @Branchid 	[varchar](3),
	 @Compid 	[varchar](3))

AS 
	IF Not Exists (select * from Com_Inspection_Option_dtl where InspectionTypeCode=@InspectionTypeCode and Code=@Code and Branchid=@BRanchid and Compid=@Compid)
		Begin
			INSERT INTO [Com_Inspection_Option_dtl] 
				 ( [Code],
				 [InspectionTypeCode],
				 [isVal],
				 [Val],
				 [CarStatus],
				 [Userid],
				 [Branchid],
				 [Compid]) 
	 
			VALUES 
				( @Code,
				 @InspectionTypeCode,
				 @isVal,
				 @Val,
				 @CarStatus,
				 @Userid,
				 @Branchid,
				 @Compid)
		End
	else
		Begin
			UPDATE [Com_Inspection_Option_dtl] 
	
				SET 	 [isVal]	 = @isVal,
					 [Val]	 = @Val,
					 [CarStatus]=@CarStatus
		
				
				WHERE 
					( [Code]	 = @Code AND
					 [InspectionTypeCode]	 = @InspectionTypeCode AND
					 [Branchid]	 = @Branchid AND
					 [Compid]	 = @Compid)
		End
