SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO






CREATE PROCEDURE [dbo].[COM_Ins_PrimaryKeyList] (@TableName nvarchar(256))

AS

SET NOCOUNT ON

	Declare @Cnt int
	Declare @ColName nvarchar(256)

	Delete from COM_PrimaryKeyList where TableName=@TableName

	Select @Cnt = 1							--For Loop Count
	Select @ColName = index_col(@TableName, 1, @Cnt)		--For Store the Column name

	WHILE @ColName is not null
	
		Begin
			Insert into COM_PrimaryKeyList
		    		Values(@TableName, @ColName, @Cnt)
		
			Select @Cnt = @Cnt + 1
			Select @ColName = index_col(@TableName, 1, @Cnt)
		End




GO

