/****** Object:  StoredProcedure [dbo].[COM_Inspection_Option_Fil]    Script Date: 17/06/2026 11:29:53 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[COM_Inspection_Option_Fil]( @InspTypeCode int,         
 @BranchID varchar(3), @CompID varchar(3))                     
AS                                 
BEGIN                                
	SET NOCOUNT ON;   
   
	Declare @OptCode As int;  
	SET @OptCode = 7; -- LOG ENTRY AT SHIFT END   
    
	Select a.Code, a.Description, a.UOM,    
		(Case When a.Code=@OptCode and b.InspectionTypeCode=@InspTypeCode Then    
		Case when IsNull(b.isval,0) = '1' Then 1 Else 0 End    
		Else IsNull(b.Val,0)     
		End) As Value,        
		IsNull(b.isVal,0) As isVal, IsNull(b.CarStatus,'') As CarStatus     
	From COM_Inspection_Option_Hdr a     
	Left Outer Join COM_Inspection_Option_Dtl b     
		On a.Code=b.Code and b.InspectionTypeCode=@InspTypeCode     
			and ((b.Code=@OptCode and b.InspectionTypeCode=@InspTypeCode)   
			or b.Code<>@OptCode)   
			and b.BranchID=@BranchID and b.CompID=@CompID    
	Where IsNull(a.Description,'')<>''  
		and ((a.Code=@OptCode and b.InspectionTypeCode=@InspTypeCode)   
		or a.Code<>@OptCode)   
END  
GO

/****** Object:  StoredProcedure [dbo].[COM_ItemNature_Fil]    Script Date: 17/06/2026 11:29:53 ******/
