GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[COM_ItemNature_Fil](@isReqItemNatureAll bit)            
As      
BEGIN      
	SET NOCOUNT ON;
 if @isReqItemNatureAll='1'      
  Begin
	  Select a.ItemNature, a.SortOrder       
	  From (      
	   Select ItemNatureDesc ItemNature, 1 as SortOrder From BOM_ItemNature_Master Where Status = '1'      
      
	   Union All      
      
	   Select 'ALL', 0 as SortOrder       
	) a      
	Order by a.SortOrder
  End
 Else
  Begin
	Select ItemNatureDesc as ItemNature  From BOM_ItemNature_Master Where Status = '1'       
	Order by ItemNatureDesc                  
  End 
END
GO

