CREATE PROCEDURE [dbo].[COM_ReceiptEntry_Fil_DCDocument](@DocType varchar(3), @DocNo int, @DocDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                                  
As                                  
BEGIN                                       
 SET NOCOUNT ON; 

Select a.VendorCode, (Select b.PartyName From FAS_PARTY_MASTER b Where 
		  b.PartyCode=a.VendorCode and b.Branchid=a.Branchid and b.Compid=a.Compid) As PartyName,
		  a.DCNo,a.DCDate,a.InvoiceNo,a.InvoiceDate,a.TransporterName,a.VehicleNo,
		  a.Narration 
From REC_RECEIPTENTRY_HDR a 
Where a.ReceiptEntryDate=@DocDate and a.ReceiptEntryNo=@DocNo  and a.ReceiptEntryType=@DocType
	and a.BranchID=@BranchID and  a.Compid=@CompID  --and Finyear=@Finyear
END
