/****** Object:  StoredProcedure [dbo].[COM_ReceiptEntry_Fil_DocumentDetails]    Script Date: 17/06/2026 11:29:53 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[COM_ReceiptEntry_Fil_DocumentDetails](@DocType varchar(3), @DocNo int, @DocDate datetime, @BranchID varchar(3), 
	@CompID varchar(3), @Finyear varchar(20))                                  
As                                  
BEGIN                                       
 SET NOCOUNT ON; 

 Select Distinct a.ItemCode,b.ItemDescription,b.PurchaseUOMDesc,b.PurchaseUOMDecimal, a.ScheduleDate,a.ChallanQty,
	 a.RefType,a.RefNo,a.RefDate,a.ItemGroupKey, a.isDrawingRecd, k.DrawingNo,  k.RevisionNo, IsNull(a.HeatNo,'') as HeatNo, 
	 b.HeatNoApplicable, b.ShelfLifePeriodApplicable, IsNull(a.ItemSeq,0) As ItemSeq, IsNull(t.ItemSeq,0) As Trace_ItemSeq, 
	 IsNull(t.ItemSeq,0) As Trace_ItemSeq, t.ManufactureDate, IsNull(t.ShelfLifeDays,0) As ShelfLifeDays
 From REC_RECEIPTENTRY_DTL a  
 Left Outer Join MATERIAL_MASTER b On a.ItemCode=b.ItemCode and a.Branchid=b.Branchid and a.Compid=b.Compid 
 Left Outer Join BOM_DrawingTran_Dtl k On a.ItemCode = k.ItemCode and a.ItemGroupkey = k.ItemGroupkey and a.RefType = k.RefType 
 and a.RefNo = k.RefNo and a.RefDate = k.RefDate and a.Branchid=b.Branchid and a.Compid=b.Compid 
 Left Outer Join REC_ReceiptEntry_Dtl_Trace t 
 On a.ReceiptEntryNo=t.ReceiptEntryNo and a.ReceiptEntryDate=t.ReceiptEntryDate and a.ReceiptEntryType=t.ReceiptEntryType 
 and a.ItemCode=t.ItemCode and a.BranchID=t.BranchID and a.CompID=t.CompID 
 Where a.ReceiptEntryType=@DocType and a.ReceiptEntryNo=@DocNo and a.ReceiptEntryDate=@DocDate 
	and a.BranchID=@BranchID and  a.Compid=@CompID   --and Finyear=@Finyear
 Order by ItemSeq
END
GO

/****** Object:  StoredProcedure [dbo].[COM_Rpt_TraceabilityData_Gen_HeatNo]    Script Date: 17/06/2026 11:29:53 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[COM_Rpt_TraceabilityData_Gen_HeatNo](@RptType varchar(15)='', @DocType varchar(3), @DocNo int, @DocDate datetime,     
@ItemCode varchar(20),  @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3),     
@Finyear Varchar(20))                
As                
BEGIN                
 SET NOCOUNT ON; 

 DECLARE @TmpTbl_TraceData As Table
 (
	DocType varchar(3), DocNo int, DocDate datetime,  
	RefType varchar(3), RefNo int, RefDate datetime, 
	ProcItemCode varchar(20), ItemCode varchar(20),
	BranchID varchar(3), CompID varchar(3), Finyear varchar(20)
 )
 
	Declare @Tmp_DocType varchar(3), @Tmp_DocNo int, @Tmp_DocDate datetime
    Declare @IsDataAvailable As int;
	Declare @TmpDate As datetime;

    SET @IsDataAvailable=0;
	SET @TmpDate='1900-01-01';

    If @RptType='QC_INSP' or @RptType='QC_FIN_IGR'
     Begin
	    /* Insert Data Into Temp Table */
	    Insert Into @TmpTbl_TraceData
		    Select Distinct a.InspectionType, a.InspectionNo, a.InspectionDate, 
				r1.StoreRequestType, r1.StoreRequestNo, r1.StoreRequestDate, 
				a.ItemCode As ProcItemCode, r2.ItemCode, 
			    a.BranchID, a.CompID, a.Finyear
		    From QC_Inspection_hdr a
		    Left Outer Join PPC_QuickProductionplan_Dtl q
			    On a.RefNo=q.DocNo and a.RefDate=q.DocDate and a.RefType=q.DocType
				    and a.ItemCode=q.StageCode and a.BranchID=q.BranchID and a.CompID=q.CompID
		    Left Outer Join INV_StoreRequest_Hdr r1
			    On q.WorkOrderNo=r1.WONo and q.WorkOrderDate=r1.WODate and q.WorkOrderType=r1.WOType
				    and q.BranchID=r1.BranchID and q.CompID=r1.CompID
		    Left Outer Join INV_StoreRequest_Dtl r2
			    On r1.StoreRequestNo=r2.StoreRequestNo and r1.StoreRequestDate=r2.StoreRequestDate and r1.StoreRequestType=r2.StoreRequestType
				    --and a.ItemCode=r2.ItemCode 
		    Left Outer Join dbo.fn_BOM_MPS_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) p1
			    On r1.ParentCode=p1.ItemCode and a.ItemCode=p1.StageCode		
			    and r1.BranchID=r2.BranchID and r1.CompID=r2.CompID		
		    Where a.InspectionNo=@DocNo and a.InspectionDate=@DocDate and a.InspectionType=@DocType  and a.ItemCode=@ItemCode
		    and a.BranchID=@BranchID and a.CompID=@CompID	--and a.Finyear=@Finyear	 
            
            SET @IsDataAvailable=1;
     End
    Else If @RptType='QC_IGR' or @RptType='PPC_IGR'
     Begin
        /* Insert Data Into Temp Table */
	    Insert Into @TmpTbl_TraceData
		    Select Distinct a.InwardGoodsReceiptType,a.InwardGoodsReceiptNo,a.InwardGoodsReceiptDate, 
                r1.StoreRequestType, r1.StoreRequestNo, r1.StoreRequestDate, 
				a.ItemCode As ProcItemCode, r2.ItemCode, 
			    a.BranchID, a.CompID, a.Finyear
		    From PPC_InwardGoodsReceipt a
		    --Left Outer Join PPC_QuickProductionplan_Dtl q
			   -- On a.WorkOrderNo=q.WorkOrderNo and a.WorkOrderDate=q.WorkOrderDate and a.WorkOrderType=q.WorkOrderType
				  --  and a.ItemCode=q.StageCode and a.BranchID=q.BranchID and a.CompID=q.CompID
		    Left Outer Join INV_StoreRequest_Hdr r1
			    On a.WorkOrderNo=r1.WONo and a.WorkOrderDate=r1.WODate and a.WorkOrderType=r1.WOType
				    and a.BranchID=r1.BranchID and a.CompID=r1.CompID
		    Left Outer Join INV_StoreRequest_Dtl r2
			    On r1.StoreRequestNo=r2.StoreRequestNo and r1.StoreRequestDate=r2.StoreRequestDate and r1.StoreRequestType=r2.StoreRequestType
				    --and a.ItemCode=r2.ItemCode 
		    Left Outer Join dbo.fn_BOM_MPS_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) p1
			    On r1.ParentCode=p1.ItemCode and a.ItemCode=p1.StageCode		
			    and r1.BranchID=r2.BranchID and r1.CompID=r2.CompID		
		    Where a.InwardGoodsReceiptNo=@DocNo and a.InwardGoodsReceiptDate=@DocDate and a.InwardGoodsReceiptType=@DocType  
                and a.ItemCode=@ItemCode and a.BranchID=@BranchID and a.CompID=@CompID	--and a.Finyear=@Finyear

                SET @IsDataAvailable=1;
     End

	 /* Get Document Data */
	 Select @Tmp_DocType=a.DocType, @Tmp_DocNo=a.DocNo, @Tmp_DocDate=a.DocDate 
	 From @TmpTbl_TraceData a Where a.BranchID=@BranchID and a.CompID=@CompID --and a.Finyear=@Finyear

	 Select @DocType=IsNull(@DocType,''), @DocNo=IsNull(@DocNo,0);

    If @IsDataAvailable=1
     Begin
        /* Output (Result) */
		If IsNull(dbo.fn_COM_Get_HeatNo(@Tmp_DocType, @Tmp_DocNo, @Tmp_DocDate, @BranchID, @CompID, @Finyear),'')<>''
		 Begin
			Select Distinct a.RefType As DocType, a.RefNo As DocNo, a.RefDate As DocDate, a.ItemCode, 
				0 As LotID, 0 As SubLotID,
				IsNull(dbo.fn_COM_Get_HeatNo(@Tmp_DocType, @Tmp_DocNo, @Tmp_DocDate, @BranchID, @CompID, @Finyear),'') As HeatNo,
				@TmpDate As ManufactureDate
			From @TmpTbl_TraceData a 
			Where a.BranchID=@BranchID and a.CompID=@CompID --and a.Finyear=@Finyear
		 End
		Else
		 Begin
			Select Distinct a.DocType, a.DocNo, a.DocDate, a.TransactionItem As ItemCode, 
				IsNull(l.LotID,0) As LotID, IsNull(l.SubLotID,0) As SubLotID, IsNull(l.HeatNo,'') As HeatNo, 
				Case When (l.ManufactureDate Is Null) Then @TmpDate Else l.ManufactureDate End As ManufactureDate
			From INV_MaterialTran_Dtl a 
			Left Outer Join COM_Trace_MaterialTran_TmpQty t 
			On a.ICode=t.TranID and a.TransactionItem=t.ItemCode and a.FromWarehouseCode=t.FromWarehouseCode 
				and a.ToWarehouseCode=t.ToWarehouseCode and a.FromRackBinCode=t.FromRackBinCode and a.ToRackBinCode=t.ToRackBinCode 
				and a.BranchID=t.BranchID and a.CompID=t.CompID and a.Finyear=t.Finyear 
			Left Outer Join COM_Trace_LotMaster_TmpQty l 
				On t.LotID=l.LotID and t.SubLotID=l.SubLotID  --and a.ItemCode=d.ItemCode 
				and t.Branchid=l.BranchId and t.Compid=l.CompID 
			Where Exists(Select * From @TmpTbl_TraceData i1 Where i1.RefNo=a.DocNo and i1.RefDate=a.DocDate 
							and i1.RefType=a.DocType and i1.ItemCode=a.TransactionItem
							and i1.BranchID=@BranchID and i1.CompID=@CompID --and i1.Finyear=@Finyear
						)
				and a.BranchID=@BranchID and a.CompID=@CompID --and a.Finyear=@Finyear
		 End
     End
    Else
     Begin
        /* Output (Result) */
        Select 0 As LotID, 0 As SubLotID, '' As HeatNo, @TmpDate As ManufactureDate;
     End   
END
GO

/****** Object:  StoredProcedure [dbo].[Com_Rpt_TraceabilityPopup_Fil_FromTrace]    Script Date: 17/06/2026 11:29:53 ******/
