CREATE PROCEDURE [dbo].[Com_Rpt_TraceabilityPopup_Fil_FromTrace](@ModuleCode int, @DocType Varchar(3), @DocNo int, 
	@DocDate Datetime, @ItemCode varchar(20), @ItemSeq int = 0, @BranchID varchar(3), @CompID varchar(3))                                          
As                                         
BEGIN                           
              
SET NOCOUNT ON;        
      
DEclare @fItemCode varchar(20)       
           
	Select distinct c.DocType, c.DocNo, c.DocDate, c.TransactionItem, IsNull(a.HeatNo,'') As HeatNo, 
		a.ManufactureDate, d.Qty,  a.SubLotID as Seq, 1 as ItemSeq, IsNull(a.LotID,0) As LotID, 
		IsNull(a.SublotID,0) As SublotID                 
	From Inv_MaterialTran_Dtl c          
	Left Outer Join COM_Trace_MaterialTran_TmpQty d          
		ON d.TranID=c.ICode   
			and d.FromWarehouseCode=c.FromWarehouseCode and d.FromRackBinCode=c.FromRackBinCode          
			and d.ToWarehouseCode=c.ToWarehouseCode and d.ToRackBinCode=c.ToRackBinCode          
			and d.ItemCode=c.TransactionItem   
			and d.Branchid=c.Branchid and d.Compid=c.Compid          
	Left Outer Join COM_Trace_LotMaster_TmpQty  a            
		On a.LotID=d.LotID and a.SubLotID=d.SubLotID and a.Branchid=d.BranchId and a.Compid=d.CompID  
	Where c.DocType=@DocType and c.DocNo=@DocNo and c.DocDate=@DocDate               
		and c.TransactionItem=@ItemCode and (d.Qty Is Not Null) and c.BranchID=@BranchID and c.CompID=@CompID                
END
GO

