CREATE PROCEDURE [dbo].[COM_tmpFormulaCalcDtl_Sel_Ins_HSNBasedTaxRate](@UserKey varchar(36), @ModuleCode int, @FrmID int, @ParamID int, @GSTParamID int=9, @IGSTParamID int=9, @CGSTParamID int=10, @SGSTParamID int=11, @AsonDate datetime , @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))      

AS      

BEGIN      
   
	Set NOCOUNT ON;  

	IF Exists (Select * From COM_FormulaMast_Block_Dtl
				Where ModuleCode=@ModuleCode and BranchID=@BranchID and CompID=@CompID and FrmID=@FrmID and BlockType='Param' and Block=@GSTParamID) 
		BEGIN
			Insert into Com_tmpFormulaCalc_Dtl
				Select a.DTKey, a.ModuleCode, a.FrmID, a.BlockType, @GSTParamID as Block, a.MultiSeq,  a.KeyCol, '1' as IsTypePercentage, '0' as IsTypeEditable, c.Rate as ValueUsed,
					'0' as IsValueEditable, a.UserID, a.BranchID, a.CompID, a.Finyear
				From Com_tmpFormulaCalc_Dtl a
				Inner Join INV_Material_Master b
					On a.KeyCol=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
				Inner Join fn_BOM_HSNNo_Master('A',@AsonDate,@RptDate,@BranchID,@CompID)c
					On b.HSNId=c.HSNId 
				Where a.DTKey=@UserKey and a.ModuleCode=@ModuleCode and a.FrmID=@FrmID and a.BlockType='Param' and a.Block=@ParamID and a.BranchID=@BranchID and a.CompID=@CompID
		END 
	END 
GO

