CREATE PROCEDURE [dbo].[Com_TraceabilityPopup_Fil_FromTraceTmp](@UserKey varchar(42), @ItemCode varchar(20), @ItemSeq int,   
@BranchID varchar(3), @CompID varchar(3))                                
As                                
BEGIN                                     
 SET NOCOUNT ON;            
          
 Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.ItemCode, a.HeatNo, a.ManufactureDate,   
    IsNull(a.ShelfLifeDays,0) As ShelfLifeDays, IsNull(a.Qty,0) As Qty, IsNull(a.AcceptedQty,0) As AcceptedQty, 
		IsNull(a.RejectedQty,0) As RejectedQty, IsNull(a.ScrapQty,0) As ScrapQty, a.Seq, a.ItemSeq, a.SublotID           
 From REC_ReceiptEntry_Trace_Tmp a         
 Where a.UserKey=@UserKey and a.ItemCode=@ItemCode and a.ItemSeq=@ItemSeq          
    and a.BranchID=@BranchID and a.CompID=@CompID        
 Order by a.Seq                  
END
