/****** Object:  StoredProcedure [dbo].[COM_TraceabilityPopup_Get_MaxQty]    Script Date: 17/06/2026 11:29:53 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
