CREATE PROCEDURE [dbo].[COM_TraceabilityPopup_Get_MaxQty](@UserKey varchar(42), @DocType varchar(3), @DocNo int, @DocDate datetime,  
@ItemCode varchar(20), @ItemSeq int, @BranchID varchar(3), @CompID varchar(3))                                
As                                
BEGIN                                     
 SET NOCOUNT ON;            
          
 Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.ItemCode, IsNull(Sum(a.Qty),0) As MaxQty,   
     IsNull(Sum(a.AcceptedQty),0) As MaxAccQty, IsNull(Sum(a.RejectedQty),0) As MaxRejQty,   
     IsNull(Sum(a.ScrapQty),0) As MaxScrQty, a.ItemSeq           
 From REC_ReceiptEntry_Trace_Tmp a         
 Where (@UserKey='' or  (@UserKey<>'' and a.UserKey=@UserKey)) and a.ReceiptEntryNo=@DocNo and a.ReceiptEntryDate=@DocDate   
    and a.ReceiptEntryType=@DocType and a.ItemCode=@ItemCode and a.ItemSeq=@ItemSeq          
    and a.BranchID=@BranchID and a.CompID=@CompID   
 Group by a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.ItemCode, a.ItemSeq                  
END     
GO

