/****** Object:  StoredProcedure [dbo].[COM_Val_HSNNoBasedOnGSTParamFormula]    Script Date: 17/06/2026 11:29:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[COM_Val_HSNNoBasedOnGSTParamFormula](@IsGSTRequired bit, @UserKey varchar(36), @ModuleCode int, @FrmID int, @ParamID int, @GSTParamID int=9, @IGSTParamID int=9, @CGSTParamID int=10, @SGSTParamID int=11, @BranchID varchar(3), @CompID varchar(3))      

AS      

BEGIN      
   
	Set NOCOUNT ON;  

		IF Exists (Select * From COM_FormulaMast_Block_Dtl
					Where ModuleCode=@ModuleCode and BranchID=@BranchID and CompID=@CompID and FrmID=@FrmID and BlockType='Param' and Block=@GSTParamID)
					
			OR (@IsGSTRequired='1')
			 
			BEGIN
				
				DECLARE @Item Varchar(8000)
					Select @Item =''

				Select  @Item = COALESCE(@Item + ', ','') + (a.ItemCode + '-' + a.ItemDescription)
				From INV_Material_Master a
				Where Exists
					(
						Select * From Com_tmpFormulaCalc_Dtl s
						Where s.KeyCol=a.ItemCode and s.DTKey=@UserKey and s.ModuleCode=@ModuleCode and s.FrmID=@FrmID and s.BlockType='Param' 
							and s.Block=@ParamID and s.BranchID=@BranchID and s.CompID=@CompID
					)
					and IsNull(a.HSNID,0)=0

				IF @Item=''
					BEGIN
						Select Top 0 '' as Item
					END
				ELSE
					BEGIN
						Select @Item as Item
					END
					/*Select a.ItemCode, a.ItemDesc
					From INV_Material_Master a
					Where Exists
						(
							Select * From Com_tmpFormulaCalc_Dtl s
							Where s.KeyCol=a.ItemCode and s.DTKey=@UserKey and s.ModuleCode=@ModuleCode and s.FrmID=@FrmID and s.BlockType='Param' 
								and s.Block=@ParamID and s.BranchID=@BranchID and s.CompID=@CompID
						)
						and IsNull(a.HSNID,0)=0*/
			END 
		ELSE
			BEGIN
				Select Top 0 '' as Item
			END
	END 
GO

