/****** Object:  StoredProcedure [dbo].[DayProductionPlanVsActualPlanReport]    Script Date: 17/06/2026 11:29:54 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO


CREATE PROCEDURE [dbo].[DayProductionPlanVsActualPlanReport] (@AsOnDtt1 varchar(16),@RepDt2 varchar(16),@YearMonth int,@ItemCode varchar(10),@RevisionNo int,@dat int,@mon int, @BranchID varchar(3), @CompID varchar(3), @FinYear varchar(16))


AS

	SET NOCOUNT ON
	
	


Select a.ItemCode,b.ItemDescription,a.PlanQty,a.PlanPeriod,Sum(IsNull(d.ActualQty,0)) As ActualQty,
dbo.fn_WtAvgRate(a.ItemCode,@AsOnDtt1,@RepDt2, @BranchID,@CompID,@FinYear)Rate,
(Sum(IsNull(d.ActualQty,0))/a.PlanQty)*100 As Percentage
From ppc_productionplan a Left outer join INV_MATERIAL_MASTER b  on a.ItemCode=b.itemCode 
and a.Branchid=b.Branchid and a.Compid=b.Compid 
Left outer join MATERIAL_MASTER c on a.ItemCode = c.ItemCode and a.BranchID = c.BranchID 
and a.CompID = c.CompID Left outer join (select x.ItemCode,Sum(x.AcceptQty)ActualQty,
x.InwardGoodsReceiptDate From (Select ItemCode,AcceptQty,InwardGoodsReceiptDate 
From PPC_InwardGoodsReceipt Where Branchid = @BranchID and Compid =@CompID 
and finyear = @FinYear Union Select ItemCode,AcceptedQty,ReceiptEntryDate 
From REC_RECEIPTENTRY_DTL Where Branchid = @BranchID and Compid =@CompID 
and finyear =@FinYear) x Where day(x.InwardGoodsReceiptDate)=@dat and 
month(x.InwardGoodsReceiptDate)=@mon and year(x.InwardGoodsReceiptDate)= @YearMonth
Group by x.itemcode,x.InwardGoodsReceiptDate) d on a.ItemCode=d.ItemCode 
Where a.ItemCode=@ItemCode and a.PlanFor=4 and a.RevisionNo=@RevisionNo and day(a.PlanPeriod)=@dat and 
month(a.PlanPeriod)=@mon and year(a.PlanPeriod)=@YearMonth
and a.Branchid = @BranchID and a.Compid =@CompID and a.finyear = @FinYear
Group by  a.ItemCode,b.ItemDescription,a.PlanQty,c.UOMDesc,a.PlanFor,a.planPeriod,
a.Branchid , a.CompID, a.Finyear, a.CreatedDate, a.RevisionNo
GO

