CREATE PROCEDURE [dbo].[DaySalesPlanVsActualPlanRpt] (@YearMonth int,@ItemCode varchar(10),@CustomerCode int,@RevisionNo int,@dat int,@mon int, @BranchID varchar(3), @CompID varchar(3), @FinYear varchar(16))


AS

	SET NOCOUNT ON
	
	


Select  a.PlanQty,a.PlanPeriod,avg(isnull(b.Rate,h.Rate))Rate, sum(isnull(b.InvoiceQty,0))InvoiceQty,
 	((sum(isnull(b.InvoiceQty,0))/case when a.PlanQty = 0 then 1 else a.PlanQty end) *100) Percentage 
from SAL_SalesPlan a 
left outer join  (Select CustomerCode, ItemCode, Rate,
 	Sum(InvoiceQty) as InvoiceQty from SalesInvoice where day(InvoiceDate)=@dat 
 	and month(InvoiceDate)=@mon and year(InvoiceDate)=@YearMonth and Branchid = @BranchID
	and Compid = @CompID  Group by CustomerCode, ItemCode,Rate) b  on a.itemCode=b.itemCode 
	and a.CustomerCode= b.CustomerCode left outer join FAS_Party_Master c 
on a.CustomerCode =c.PartyCode and a.Branchid=c.Branchid and a.Compid=c.Compid 
left outer join INV_MATERIAL_MASTER d  
on a.itemCode=d.itemCode and a.Branchid=d.Branchid 
	and a.Compid=d.Compid 
left outer join MATERIAL_MASTER e 
on a.itemCode=e.itemCode 
	and a.Branchid=e.Branchid and a.Compid=e.Compid 
left outer join SAL_CUSTOMER_ITEMMASTER h 
on A.CustomerCode = h.CustomerCode And A.ItemCode = h.ItemCode And A.Branchid = h.Branchid 
	and a.Compid=h.Compid 
where a.PlanFor = 4 and  a.RevisionNo = @RevisionNo and a.CustomerCode =@CustomerCode
	and a.itemCode =@ItemCode and day(a.PlanPeriod)= @dat and month(a.PlanPeriod)=@Mon
	and year(a.PlanPeriod)=@YearMonth
	and a.Branchid = @BranchID and a.Compid = @CompID and a.Finyear = @FinYear
group by  a.CustomerCode,c.Partyname,a.itemCode,d.ItemDescription,e.UOMDesc,
	a.PlanQty,a.planPeriod
GO

