CREATE PROCEDURE [dbo].[DD_KPI_CustomerComplaint_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))    
/* Process Current Date, Current Month, Current Year Data from the original table if it is changed from last process  
    and all other data will be taken from already processed data */  
AS                  
BEGIN              
    SET NOCOUNT ON;  
  
	DECLARE @NoofComplaintsChartTypeId int, @PendingComplaintsChartTypeId int, @RepeatedComplaintsChartTypeId int;  
	SELECT @NoofComplaintsChartTypeId=4, @PendingComplaintsChartTypeId=5, @RepeatedComplaintsChartTypeId=6; /* From Table ChartTypeMaster */  
   
	DECLARE @CurDate datetime;  
	SET @CurDate = getdate();      
        
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */    
    DECLARE @ShiftStart datetime;    
    SET @ShiftStart='06:00';    
          
    DECLARE @Finyear varchar(15);              
              
    /* Period Start End */              
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                
        
	If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)    
		BEGIN    
			SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' 06:00';    
			SET @MonthStart=Convert(varchar(7), DateAdd(day, -1, @AsOnDate), 120) + '-01';    
			SET @Finyear=dbo.fn_COM_Get_Finyear(DateAdd(day, -1, @AsOnDate));    
		END    
	Else    
		BEGIN    
			SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' 06:00';    
			SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';    
			SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);    
		END    
    
    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));    
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                
      
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;              
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                          
       
	Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))  
	From DD_KPI_HolidayMaster  
	Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID  
      
	Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1  
	From DD_KPI_HolidayMaster  
	Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID  
         
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                  
    DECLARE  @MonthTarget int,  @YearTarget int ,  @DayTarget int;                  
            
    SET @YearLabelCount=12;    /* No. of months in a Year */              
    SET @MonthLabelCount=@MonthWorkingDays;               
    SET @DayLabelCount=@TotalShiftHours;                  

	DECLARE @DayNoOfComplaintTarget int, @DayPendingComplaintTarget int, @DayPendingComplaintTargetPerc decimal(5,2), @DayRepeatedComplaintTarget int,
			@MonthNoOfComplaintTarget int, @MonthPendingComplaintTarget int, @MonthPendingComplaintTargetPerc decimal(5,2), @MonthRepeatedComplaintTarget int,
			@YearNoOfComplaintTarget int, @YearPendingComplaintTarget int, @YearPendingComplaintTargetPerc decimal(5,2), @YearRepeatedComplaintTarget int,
	
			@DayNoOfComplaintPlan int, @DayPendingComplaintPlan int, @DayRepeatedComplaintPlan int,
			@MonthNoOfComplaintPlan int, @MonthPendingComplaintPlan int, @MonthRepeatedComplaintPlan int,
			@YearNoOfComplaintPlan int, @YearPendingComplaintPlan int, @YearRepeatedComplaintPlan int,

			@DayNoOfComplaintActual int, @DayPendingComplaintActual int, @DayRepeatedComplaintActual int,
			@MonthNoOfComplaintActual int, @MonthPendingComplaintActual int, @MonthRepeatedComplaintActual int,
			@YearNoOfComplaintActual int, @YearPendingComplaintActual int, @YearRepeatedComplaintActual int;
    
			
	DECLARE @YearPeriodType Char(2), @MonthPeriodType Char(2), @DayPeriodType Char(2)
		SELECT @YearPeriodType='YR', @MonthPeriodType='MN', @DayPeriodType='DY'

	/* Target & Plan */
		--No of Complaints
	Select @DayNoOfComplaintTarget = dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@NoofComplaintsChartTypeId,'Target',@DayPeriodType,@BranchID,@CompID), 
			@MonthNoofComplaintTarget=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@NoofComplaintsChartTypeId,'Target',@MonthPeriodType,@BranchID,@CompID), 
			@YearNoofComplaintTarget=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@NoofComplaintsChartTypeId,'Target',@YearPeriodType,@BranchID,@CompID);   

	Select @DayNoOfComplaintPlan = @DayNoofComplaintTarget, @MonthNoOfComplaintPlan=@MonthNoOfComplaintTarget, @YearNoOfComplaintPlan=@YearNoofComplaintTarget
		
		--Pending Complaints 
	Select /*@DayPendingComplaintTargetPerc = dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@PendingComplaintsChartTypeId,'Target',@DayPeriodType,@BranchID,@CompID), 
			@MonthPendingComplaintTargetPerc =dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@PendingComplaintsChartTypeId,'Target',@MonthPeriodType,@BranchID,@CompID),*/ 
			@YearPendingComplaintTargetPerc =dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@PendingComplaintsChartTypeId,'Target',@YearPeriodType,@BranchID,@CompID);   

		--Repeated Complaints
	Select /*@DayRepeatedComplaintTarget = dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@RepeatedComplaintsChartTypeId,'Target',@DayPeriodType,@BranchID,@CompID), 
			@MonthRepeatedComplaintTarget=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@RepeatedComplaintsChartTypeId,'Target',@MonthPeriodType,@BranchID,@CompID), */
			@YearRepeatedComplaintTarget=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@RepeatedComplaintsChartTypeId,'Target',@YearPeriodType,@BranchID,@CompID);   

	Select --@DayRepeatedComplaintPlan = @DayRepeatedComplaintTarget, @MonthRepeatedComplaintPlan=@MonthRepeatedComplaintTarget, 
		@YearRepeatedComplaintPlan=@YearRepeatedComplaintTarget

	/* Query */
    DECLARE @CustComplaint_Tbl TABLE (ComplaintRegisterNo int, ComplaintRegisterDate datetime, 
									PendingComplaints int, RepeatedComplaints int )        
    
	Insert into @CustComplaint_Tbl 
		Select a.ComplaintRegisterNo, a.ComplaintRegisterDate, 
			Case When IsNull(b.CARClosed,'0')='0' Then 1 Else 0 End as PendingComplaints,
			Case When a.ComplaintNature='R' Then 1 Else 0 End as RepeatedComplaints
		From QC_ComplaintRegister a
		Left Outer Join Qc_CarHdr b
			On a.ComplaintRegisterNo=b.RefNo and a.ComplaintRegisterDate=b.RefDate and a.ComplaintRegisterType=b.RefType
			and a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
		Where a.ComplaintRegisterDate between @YearStart and @DayStart and a.BranchId=@BranchID and a.CompId=@CompID 

	
	/* Day Complaints */ 
	Select @DayNoofComplaintActual = IsNull(Count(*),0) 
		/*@DayPendingComplaintActual = IsNull(Sum(a.PendingComplaints),0), 
		@DayRepeatedComplaintActual = IsNull(Sum(a.RepeatedComplaints),0)*/
	From @CustComplaint_Tbl a
	Where a.ComplaintRegisterDate between @DayStart and Convert(Varchar(10),@AsOnDate,120)

	/* Month Complaints */ 
	Select @MonthNoofComplaintActual = IsNull(Count(*),0) 
		/*@MonthPendingComplaintActual = IsNull(Sum(a.PendingComplaints),0), 
		@MonthRepeatedComplaintActual = IsNull(Sum(a.RepeatedComplaints),0)*/
	From @CustComplaint_Tbl a
	Where a.ComplaintRegisterDate between @MonthStart and Convert(Varchar(10),@AsOnDate,120)

	/* Year Complaints */ 
	Select @YearNoofComplaintActual = IsNull(Count(*),0), 
		@YearPendingComplaintActual = IsNull(Sum(a.PendingComplaints),0), 
		@YearRepeatedComplaintActual = IsNull(Sum(a.RepeatedComplaints),0)
	From @CustComplaint_Tbl a
	Where a.ComplaintRegisterDate between @YearStart and Convert(Varchar(10),@AsOnDate,120) 

	Select /*@DayPendingComplaintTarget = @DayPendingComplaintTargetPerc*@DayNoofComplaintActual, 
			@MonthPendingComplaintTarget=@MonthPendingComplaintTargetPerc*@MonthNoofComplaintActual,*/
		@YearPendingComplaintTarget=@YearPendingComplaintTargetPerc*@YearNoofComplaintActual;

	Select --@DayPendingComplaintPlan = @DayPendingComplaintTarget, @MonthPendingComplaintPlan=@MonthPendingComplaintTarget, 
		@YearPendingComplaintPlan=@YearPendingComplaintTarget


	If Exists (Select * From DD_KPI_GaugeChartData 
				Where ChartTypeId in (@NoofComplaintsChartTypeId, @PendingComplaintsChartTypeId, @RepeatedComplaintsChartTypeId) 
					and AsOnDate=@AsOnDate and BranchID=@BranchId and CompID=@CompID) 
	BEGIN           
		Delete From DD_KPI_GaugeChartData 
		Where ChartTypeId in (@NoofComplaintsChartTypeId, @PendingComplaintsChartTypeId, @RepeatedComplaintsChartTypeId) 
				and AsOnDate=@AsOnDate  and BranchID=@BranchId and CompID=@CompID
	END

	/* No of Complaints */
	IF (Select dbo.fn_DD_KPI_GaugeChartData_AllowInsert(@NoofComplaintsChartTypeId, @AsOnDate, @DayPeriodType, isNull(@DayNoOfComplaintTarget, 0), isNull(@DayNoOfComplaintPlan, 0), isNull(@DayNoOfComplaintTarget, 0),
														isNull(@DayNoOfComplaintActual, 0), isNull(@DayNoOfComplaintActual, 0), 0, @DayStart, @BranchId, @CompID)) = '1'
		BEGIN
			Insert into DD_KPI_GaugeChartData  
				Select @NoofComplaintsChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @DayPeriodType as PeriodType, 
					isNull(@DayNoOfComplaintTarget, 0) as TargetValue, 
					isNull(@DayNoOfComplaintPlan, 0) as PlanValue,  isNull(@DayNoOfComplaintTarget, 0) as PlanTillPeriodValue, 
					isNull(@DayNoOfComplaintActual, 0) as AchievedValue, isNull(@DayNoOfComplaintActual, 0) as AchievedValue2,		--	AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.
					0 as AllowVariance,  Case When isNull(@DayNoOfComplaintActual, 0)=0 Then 0 Else isNull((@DayNoOfComplaintActual-@DayNoOfComplaintPlan), 0) End as Variance,  
					@BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp  
		END	


	IF (Select dbo.fn_DD_KPI_GaugeChartData_AllowInsert(@NoofComplaintsChartTypeId, @AsOnDate, @MonthPeriodType, isNull(@MonthNoOfComplaintTarget, 0), isNull(@MonthNoOfComplaintPlan, 0), isNull(@MonthNoOfComplaintTarget, 0),
														isNull(@MonthNoOfComplaintActual, 0), isNull(@MonthNoOfComplaintActual, 0), 0, @MonthStart, @BranchId, @CompID)) = '1'
		BEGIN
			Insert into DD_KPI_GaugeChartData  
				Select @NoofComplaintsChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @MonthPeriodType as PeriodType, 
					isNull(@MonthNoOfComplaintTarget, 0) as TargetValue, 
					isNull(@MonthNoOfComplaintPlan, 0) as PlanValue,  isNull(@MonthNoOfComplaintTarget, 0) as PlanTillPeriodValue, 
					isNull(@MonthNoOfComplaintActual, 0) as AchievedValue, isNull(@MonthNoOfComplaintActual, 0) as AchievedValue2,		--	AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.
					0 as AllowVariance,  Case When isNull(@MonthNoOfComplaintActual, 0)=0 Then 0 Else isNull((@MonthNoOfComplaintActual-@MonthNoOfComplaintPlan), 0) End as Variance,  
					@BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp  

		END
	
	IF (Select dbo.fn_DD_KPI_GaugeChartData_AllowInsert(@NoofComplaintsChartTypeId, @AsOnDate, @YearPeriodType, isNull(@YearNoOfComplaintTarget, 0), isNull(@YearNoOfComplaintPlan, 0), isNull(@YearNoOfComplaintTarget, 0),
														isNull(@YearNoOfComplaintActual, 0), isNull(@YearNoOfComplaintActual, 0), 0, @YearStart, @BranchId, @CompID)) = '1'
		BEGIN
			Insert into DD_KPI_GaugeChartData  
				Select @NoofComplaintsChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, 
					isNull(@YearNoOfComplaintTarget, 0) as TargetValue, 
					isNull(@YearNoOfComplaintPlan, 0) as PlanValue,  isNull(@YearNoOfComplaintTarget, 0) as PlanTillPeriodValue, 
					isNull(@YearNoOfComplaintActual, 0) as AchievedValue, isNull(@YearNoOfComplaintActual, 0) as AchievedValue2,		--	AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.
					0 as AllowVariance,   Case When isNull(@YearNoOfComplaintActual, 0)=0 Then 0 Else isNull((@YearNoOfComplaintActual-@YearNoOfComplaintPlan), 0) End as Variance,  
					@BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp 
		END


	/* Pending Compliants */
	IF (Select dbo.fn_DD_KPI_GaugeChartData_AllowInsert(@PendingComplaintsChartTypeId, @AsOnDate, @YearPeriodType, isNull(@YearPendingComplaintTarget, 0), isNull(@YearPendingComplaintPlan, 0), isNull(@YearPendingComplaintTarget, 0),
														isNull(@YearPendingComplaintActual, 0), isNull(@YearPendingComplaintActual, 0), 0, @YearStart, @BranchId, @CompID)) = '1'
		BEGIN
			Insert into DD_KPI_GaugeChartData  
				Select @PendingComplaintsChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, 
						isNull(@YearPendingComplaintTarget, 0) as TargetValue, 
						isNull(@YearPendingComplaintPlan, 0) as PlanValue,  isNull(@YearPendingComplaintTarget, 0) as PlanTillPeriodValue, 
						isNull(@YearPendingComplaintActual, 0) as AchievedValue, isNull(@YearPendingComplaintActual, 0) as AchievedValue2,		--	AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.
						0 as AllowVariance,  isNull((@YearPendingComplaintActual-@YearPendingComplaintPlan), 0) as Variance,  
						@BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp 
		END

	/* Repeated Compliants */
	IF (Select dbo.fn_DD_KPI_GaugeChartData_AllowInsert(@RepeatedComplaintsChartTypeId, @AsOnDate, @YearPeriodType, isNull(@YearRepeatedComplaintTarget, 0), isNull(@YearRepeatedComplaintPlan, 0), isNull(@YearRepeatedComplaintTarget, 0),
														isNull(@YearRepeatedComplaintActual, 0), isNull(@YearRepeatedComplaintActual, 0), 0, @YearStart, @BranchId, @CompID)) = '1'
		BEGIN
			Insert into DD_KPI_GaugeChartData  
				Select @RepeatedComplaintsChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, 
					isNull(@YearRepeatedComplaintTarget, 0) as TargetValue, 
					isNull(@YearRepeatedComplaintPlan, 0) as PlanValue,  isNull(@YearRepeatedComplaintTarget, 0) as PlanTillPeriodValue, 
					isNull(@YearRepeatedComplaintActual, 0) as AchievedValue, isNull(@YearRepeatedComplaintActual, 0) as AchievedValue2,		--	AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.
					0 as AllowVariance,  Case When isNull(@YearRepeatedComplaintActual, 0)=0 Then 0 Else isNull((@YearRepeatedComplaintActual-@YearRepeatedComplaintPlan), 0) End as Variance,  
					@BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp
		END
END  
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_CustomerEndPPM_ChartData_Ins]    Script Date: 17/06/2026 11:29:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_CustomerEndPPM_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))        
/* Process Current Date, Current Month, Current Year Data from the original table if it is changed from last process                
    and all other data will be taken from already processed data */                
AS                                
BEGIN                            
    SET NOCOUNT ON;                
                
    DECLARE @ChartTypeId int, @ChartTypeIdSales int;                
    SET @ChartTypeId=8; /* From Table ChartTypeMaster */              
    --SET @ChartTypeIdSales=1;              
                 
    DECLARE @CurDate datetime;                
    SET @CurDate = getdate();                    
                      
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */                  
    DECLARE @ShiftStart datetime;                  
    SET @ShiftStart='06:00';                  
                        
    DECLARE @Finyear varchar(15);                            
                            
    /* Period Start End */                            
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                              
                      
 If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)                  
  BEGIN                  
   SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' 06:00';                        
  END                  
    Else                  
  BEGIN                  
   SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' 06:00';                               
  END      
          
    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';                  
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);                        
                  
    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));                  
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                              
                    
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                            
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                                        
                     
    Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))                
    From DD_KPI_HolidayMaster                
    Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID                
                    
    Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1                
    From DD_KPI_HolidayMaster                
    Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID                
                       
  DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                                                                        
  SET @YearLabelCount=12;    /* No. of months in a Year */                            
  SET @MonthLabelCount=@MonthWorkingDays;                             
  SET @DayLabelCount=@TotalShiftHours;            
    
 DECLARE @YearPeriodType Char(2), @MonthPeriodType Char(2), @DayPeriodType Char(2)    
  SELECT @YearPeriodType='YR', @MonthPeriodType='MN', @DayPeriodType='DY'    
    
 /*DECLARE  @SalesChartYearTarget money,  @SalesChartMonthTarget money,  @SalesChartDayTarget money;                            
  SET @SalesChartYearTarget = dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeIdSales,'Target',@YearPeriodType,@BranchID,@CompID);                           
  SET @SalesChartMonthTarget = (@SalesChartYearTarget/12);                        
  SET @SalesChartDayTarget = (@SalesChartMonthTarget/@MonthWorkingDays);     */                   
    
 DECLARE @YearTarget money,  @MonthTarget money,  @DayTarget money;            
  SET @YearTarget=(dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'Target',@YearPeriodType,@BranchID,@CompID));     
        SET @MonthTarget=(dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'Target',@MonthPeriodType,@BranchID,@CompID));    
  SET @DayTarget=(dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'Target',@DayPeriodType,@BranchID,@CompID));    
        
    DECLARE @YearPlan money, @YearSales money, @YearAchieved money, @YearVarianceAllowedPerc decimal(5, 2), @YearVarianceAllowed money,                               
        @MonthPlan money, @MonthSales money, @MonthAchieved money, @MonthVarianceAllowedPerc decimal(5, 2), @MonthVarianceAllowed money,                               
        @DayPlan money, @DaySales money, @DayAchieved money, @DayVarianceAllowedPerc decimal(5, 2), @DayVarianceAllowed money;             
           
  Select @YearPlan=@YearTarget, @YearSales=@YearTarget, @MonthPlan=@MonthTarget, @MonthSales=@MonthTarget, @DayPlan=@DayTarget, @DaySales=@DayTarget;    
    
    
    /***************************** Actual Sales Return Value ******************************/             
 DECLARE @SalesReturn_Tbl TABLE (RRType varchar(3), RRNo int, RRDate datetime, ReturnQty money, InvoiceQty money);           
 Insert into @SalesReturn_Tbl      
  Select a.RRType, a.RRNo, a.RRDate, a.ReturnQty, b.InvoiceQty    
  From      
  (      
   Select a.DocType as RRType, a.DocNo as RRNo, a.DocDate as RRDate,       
    a.RefType as InvoiceType, a.RefNo as InvoiceNo, a.RefDate as InvoiceDate, a.CustomerCode, a.ItemCode,       
    Case When Sum(a.ReceivedQty)>0 Then Sum(a.ReceivedQty) Else Sum(a.ChallanQty) End as ReturnQty    
   From      
   (      
    Select a.ReceiptEntryType as DocType, a.ReceiptEntryNo as DocNo, a.ReceiptEntryDate as DocDate, b.RefType, b.RefNo, b.RefDate, a.VendorCode as CustomerCode, b.ItemCode,    
		b.ChallanQty, b.ReceiptQty as ReceivedQty   
		--b.GroupCode,     
     --Case When b.GroupCode='-1' Then b.Qty Else 0 End as ChallanQty,      
     --Case When b.GroupCode='-2' Then b.Qty Else 0 End as ReceivedQty      
    From REC_RECEIPTENTRY_HDR a      
    Left Outer Join REC_ReceiptEntry_Dtl b      
     On a.ReceiptEntryType=b.ReceiptEntryType and a.ReceiptEntryNo=b.ReceiptEntryNo and a.ReceiptEntryDate=b.ReceiptEntryDate --and b.GroupCode in ('-1','-2')       
     and a.BranchID=b.BranchID and a.CompID=b.CompID      
    --Left Outer Join REC_IncomingReceipt_Others c      
    -- On a.DocType=c.DocType and a.DocNo=c.DocNo and a.DocDate=c.DocDate      
    -- and a.BranchID=c.BranchID and a.CompID=c.CompID      
    Where a.InwardType in ('I') and a.ReceiptEntryDate between @YearStart and Convert(Varchar(10),@AsOnDate,121)       
     and a.BranchID=@BranchID and a.CompId=@CompId     
   )a      
   Group by a.DocType, a.DocNo, a.DocDate, a.RefType, a.RefNo, a.RefDate, a.CustomerCode, a.ItemCode       
  )a      
  Left Outer Join SalesInvoice b      
   On a.InvoiceType=b.InvoiceType and a.InvoiceNo=b.InvoiceNo and a.InvoiceDate=b.InvoiceDate       
   and a.CustomerCode=b.CustomerCode and a.ItemCode=b.ItemCode and b.BranchID=@BranchID and b.CompID=@CompId     
  Order by a.RRType, a.RRNo, a.RRDate    

 /* Day Sales Return PPM Value */     
 Select @DayAchieved = (Case When InvoiceQty=0 Then 0 Else (ReturnQty/InvoiceQty) End) *1000000 --* 1000    
 From      
 (    
  Select IsNull(Sum(ReturnQty),0) as ReturnQty,  IsNull(Sum(InvoiceQty),0) as InvoiceQty      
  From @SalesReturn_Tbl a      
  Where a.RRDate between Convert(Varchar(10),@DayStart,121) and Convert(Varchar(10),@AsOnDate,121)      
 )a    
    
 /* Month Sales Return PPM Value */      
 Select @MonthAchieved = (Case When InvoiceQty=0 Then 0 Else (ReturnQty/InvoiceQty) End) * 1000000 --* 1000    
 From    
 (    
  Select IsNull(Sum(ReturnQty),0) as ReturnQty,  IsNull(Sum(InvoiceQty),0) as InvoiceQty    
  From @SalesReturn_Tbl a      
  Where a.RRDate between @MonthStart and Convert(Varchar(10),@AsOnDate,121)      
 )a    

 /* Year Sales Return PPM Value */      
 Select @YearAchieved = (Case When InvoiceQty=0 Then 0 Else (ReturnQty/InvoiceQty) End) *1000000 --* 1000    
 From      
 (    
  Select IsNull(Sum(ReturnQty),0) as ReturnQty,  IsNull(Sum(InvoiceQty),0) as InvoiceQty    
  From @SalesReturn_Tbl a      
  Where a.RRDate between @YearStart and Convert(Varchar(10),@AsOnDate,121)      
 )a    
               
 If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate and BranchID=@BranchID and CompID=@CompID)                          
  Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate and BranchID=@BranchID and CompID=@CompID               
                
    Insert into DD_KPI_GaugeChartData               
       Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, 'DY' as PeriodType, @DayTarget as TargetValue,     
    isNull(@DayPlan, 0) as PlanValue,  isNull(@DaySales, 0) as PlanTillPeriodValue, isNull(@DayAchieved, 0) as AchievedValue,               
    isNull(@DayAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.              
    isNull(@DayVarianceAllowed, 0) as AllowVariance,                  
    isNull((@DaySales-@DayAchieved), 0) as Variance,                
    @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp                
                  
        Union All                
                    
       Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, 'MN' as PeriodType, @MonthTarget as TargetValue,                 
    isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthSales, 0) as PlanTillPeriodValue, isNull(@MonthAchieved, 0) as AchievedValue,               
    isNull(@MonthAchieved, 0) as AchievedValue2, -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.              
    isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthSales-@MonthAchieved), 0) as Variance, @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp                
                
         Union All                
                    
       Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, 'YR' as PeriodType, @YearTarget as TargetValue,                 
    isNull(@YearPlan, 0) as PlanValue, isNull(@YearSales, 0) as PlanTillPeriodValue, isNull(@YearAchieved, 0) as AchievedValue,               
    isNull(@YearAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.              
    isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearSales-@YearAchieved), 0) as Variance, @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp                
                          
END 
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_DeviceApproval_Request_Ins]    Script Date: 17/06/2026 11:29:54 ******/
SET ANSI_NULLS ON
GO

