GO


CREATE PROCEDURE [dbo].[DD_KPI_DeviceApproval_Request_Ins]
(
@MacID int,
@UserID int ,
@BranchID  varchar(2),
@CompID  varchar(2),
@TranStamp datetime
)
AS
BEGIN
SET NOCOUNT ON;
DECLARE @RequestID int;
IF EXISTS(Select * from DD_KPI_DeviceApproval_Request Where MacID=@MacID and BranchID=@BranchID and CompID=@CompID)
BEGIN
	Select @RequestID=RequestID From  DD_KPI_DeviceApproval_Request Where MacID=@MacID and BranchID=@BranchID and CompID=@CompID;
	DELETE from DD_KPI_DeviceApproval_Request Where MacID=@MacID and BranchID=@BranchID and CompID=@CompID
END
ELSE
BEGIN
Select @RequestID=max(RequestID) From  DD_KPI_DeviceApproval_Request WHERE  BranchID=@BranchID and CompID=@CompID;
END

set @RequestID=isnull(@RequestID,0) + 1;

INSERT INTO DD_KPI_DeviceApproval_Request
(
RequestID,
MacID,
UserID,
BranchID,
CompID,
TranStamp
)
VALUES
(
@RequestID,
@MacID,
@UserID,
@BranchID,
@CompID,
@TranStamp
)
END
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_DeviceApproval_Request_Sav]    Script Date: 17/06/2026 11:29:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE Procedure [dbo].[DD_KPI_DeviceApproval_Request_Sav]    
(            
@MacAddress varchar(20),        
@Name varchar(50),      
@MailID varchar(50),  
@MobileNo nvarchar(10),     
@Password NVARCHAR(50),     
@IsNewUser Bit,      
@BranchID varchar(2),        
@CompID varchar(2),        
@TranStamp datetime        
)        
AS        
BEGIN        
SET NOCOUNT ON;     
DECLARE @MacID int,@UserID int;      
    
   if(@IsNewUser=1 or @Password='')    
   BEGIN       
   EXEC [DD_KPI_UserCredentials_Ins] @Name, @MailID,@MobileNo, @Password, @BranchID, @CompID, @TranStamp;         
   END    
      
  IF EXISTS(Select * from DD_KPI_UserCredentials    
     Where MobileNo=@MobileNo and PasswordHash=  HASHBYTES('SHA2_512', @Password+CAST(Salt AS NVARCHAR(36)))            
      and BranchID=@BranchID and CompID=@CompID    
     )    
     BEGIN    
    
     Select @UserID=UserID from DD_KPI_UserCredentials     
     WHERE MobileNo = @MobileNo AND BranchID=@BranchID and CompID=@CompID ;      
    
    
      EXEC DD_KPI_DeviceDetails_Ins @MacAddress,@BranchID,@CompID,@TranStamp    
      Select  @MacID=MacID from DD_KPI_DeviceDetails     
      Where MacAddress=@MacAddress     
      and PrivateCode= Convert(NVARCHAR(32), HASHBYTES('SHA2_512', @MacAddress), 2)      
      and BranchID=@BranchID and CompID=@CompID      
    
    
      EXEC DD_KPI_DeviceApproval_Request_Ins @MacID,@UserID,@BranchID,@CompID,@TranStamp    
    
      Select 'Request Send Successfully.'     
     END    
     ELSE     
     BEGIN    
     Select 'InCorrect User Credentials.'     
     END        
END 
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_DeviceDetails_Check]    Script Date: 17/06/2026 11:29:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[DD_KPI_DeviceDetails_Check] (    
 @UserMacAddress VARCHAR(20)    
 , @BranchID varchar(2)    
 , @CompID varchar(2)    
 )    
AS    
BEGIN    
 SET NOCOUNT ON;    
    
 IF EXISTS (    
   SELECT *    
   FROM DD_KPI_DeviceDetails    
   WHERE MacAddress = @UserMacAddress    
    AND PrivateCode = Convert(NVARCHAR(32), HASHBYTES('SHA2_512', @UserMacAddress), 2)    
    AND BranchID = @BranchID    
    AND CompID = @CompID    
   )    
 BEGIN    
  SELECT CONVERT(int,ApprovalStatus) as [Status],PrivateCode as PrivateCode    
  FROM DD_KPI_DeviceDetails    
  WHERE MacAddress = @UserMacAddress    
   AND PrivateCode = Convert(NVARCHAR(32), HASHBYTES('SHA2_512', @UserMacAddress), 2)    
   AND BranchID = @BranchID    
   AND CompID = @CompID    
  
 END     
 ELSE  
 BEGIN  
  SELECT -1 as [Status],Convert(NVARCHAR(32), HASHBYTES('SHA2_512', @UserMacAddress), 2)  as PrivateCode     
 END  
END    
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_DeviceDetails_Ins]    Script Date: 17/06/2026 11:29:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[DD_KPI_DeviceDetails_Ins] (
	@MacAddress VARCHAR(20)
	, @BranchID VARCHAR(2)
	, @CompID VARCHAR(2)
	, @TranStamp DATETIME
	)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @MacID INT;

	IF NOT EXISTS (
			SELECT *
			FROM DD_KPI_DeviceDetails
			WHERE MacAddress = @MacAddress
				AND PrivateCode = Convert(NVARCHAR(32), HASHBYTES('SHA2_512', @MacAddress), 2)
				AND BranchID = @BranchID
				AND CompID = @CompID
			)
	BEGIN
		SELECT @MacID = Max(MacID)
		FROM DD_KPI_DeviceDetails
		WHERE BranchID = @BranchID
			AND CompID = @CompID;

		SET @MacID = ISNULL(@MacID, 0) + 1;

		INSERT INTO DD_KPI_DeviceDetails (
			MacID
			, MacAddress
			, PrivateCode
			, ApprovalStatus
			, BranchID
			, CompID
			, TranStamp
			)
		VALUES (
			@MacID
			, @MacAddress
			, Convert(NVARCHAR(32), HASHBYTES('SHA2_512', @MacAddress), 2)
			, 0
			, @BranchID
			, @CompID
			, @TranStamp
			)
	END
END
 
GO

