/****** Object:  StoredProcedure [dbo].[DD_KPI_DirectExpenses_ChartData_Ins]    Script Date: 17/06/2026 11:29:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_DirectExpenses_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))        
/* Process Current Date, Current Month, Current Year Data from the original table if it is changed from last process      
    and all other data will be taken from already processed data */      
AS                      
BEGIN                  
    SET NOCOUNT ON;      
      
 DECLARE @ChartTypeId int, @ChartTypeIdSalesContribution int, @ChartTypeIdNetProfit int;           
  SELECT @ChartTypeId=11, @ChartTypeIdSalesContribution=2, @ChartTypeIdNetProfit=3;  
  
 DECLARE @CurDate datetime;      
  SET @CurDate = getdate();          
            
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */        
    DECLARE @ShiftStart datetime;        
  SELECT @ShiftStart=ShiftStart From vw_DD_KPI_ShiftStart;    
              
    DECLARE @Finyear varchar(15);                  
                  
    /* Period Start End */                  
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                    
            
    If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)        
  BEGIN        
   SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' ' + Convert(varchar(8), @ShiftStart, 108);              
  END        
    Else        
  BEGIN        
   SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' ' + Convert(varchar(8), @ShiftStart, 108);                
  END  
  
    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';      
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);  
  
    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));        
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                    
          
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                  
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                              
           
    Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))      
    From DD_KPI_HolidayMaster      
    Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID      
          
    Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1      
    From DD_KPI_HolidayMaster      
    Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID      
      
    /*Select @CompletedDays=Count(*)  
    From  
    (  
        Select DateAdd(day,1,FromDate) +  ' ' + Convert(Varchar(8), @ShiftStart,108)  as DayEnd, *   
        From fn_COM_PeriodSplit(@MonthStart, Convert(varchar(10),@DayStart,120), 'D', '', 0, '0') a  
        Where Not Exists  
        (  
            Select *  
            From DD_KPI_HolidayMaster s  
            Where s.HolidayDate=a.FromDate and s.BranchID=@BranchID and s.CompID=@CompID  
        )  
    )a  
    Where DayEnd<=@AsOnDate*/  
             
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                                      
  SET @YearLabelCount=12;    /* No. of months in a Year */                  
  SET @MonthLabelCount=@MonthWorkingDays;                   
  SET @DayLabelCount=@TotalShiftHours;                      
      
 DECLARE @YearPeriodType Char(2), @MonthPeriodType Char(2), @DayPeriodType Char(2)  
  SELECT @YearPeriodType='YR', @MonthPeriodType='MN', @DayPeriodType='DY'  
                             
 DECLARE @YearTarget money, @YearPlan money, @YearPlanTillMonth money, @YearAchieved money, @YearVarianceAllowedPerc decimal(5, 2), @YearVarianceAllowed money,                     
   @MonthTarget money, @MonthPlan money, @MonthPlanTillDate money, @MonthAchieved money, @MonthVarianceAllowedPerc decimal(5, 2), @MonthVarianceAllowed money,                     
   @DayTarget money, @DayPlan money, @DayPlanTillNow money, @DayAchieved money, @DayVarianceAllowedPerc decimal(5, 2), @DayVarianceAllowed money;        
      
 /* Get Allowed Variance Perc */                       
 SELECT @YearVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@YearPeriodType,@BranchID,@CompID),   
   @MonthVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@MonthPeriodType,@BranchID,@CompID),   
   @DayVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@DayPeriodType,@BranchID,@CompID);  
  
    DECLARE @AsOnDateWithoutTime datetime;      
     SET @AsOnDateWithoutTime=Convert(varchar(10), @AsOnDate, 120);      
  
 /***************************** Sales Contribution *****************************/     
    DECLARE @SalesContribution_Tbl TABLE (ContributionPeriodType varchar(2), ContributionTargetValue money, ContributionPlanValue money, ContributionPlanTillPeriodValue money);          
    Insert into @SalesContribution_Tbl          
        Select PeriodType, TargetValue, PlanValue,  PlanTillPeriodValue        
        From DD_KPI_GaugeChartData a          
        Where a.ChartTypeId=@ChartTypeIdSalesContribution          
            and a.BranchID=@BranchID and a.CompID=@CompID          
   and a.AsOnDate=(Select Max(b.AsOnDate) From DD_KPI_GaugeChartData b           
                            Where b.ChartTypeId=a.ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate          
                                and b.BranchID=a.BranchID and b.CompID=a.CompID          
                            )          
   
 /***************************** Net Profit *****************************/     
 DECLARE @NetProfit_Tbl TABLE (NetProfitPeriodType varchar(2), NetProfitTargetValue money, NetProfitPlanValue money, NetProfitPlanTillPeriodValue money);          
    Insert into @NetProfit_Tbl          
        Select PeriodType, TargetValue, PlanValue,  PlanTillPeriodValue        
        From DD_KPI_GaugeChartData a          
        Where a.ChartTypeId=@ChartTypeIdNetProfit        
            and a.BranchID=@BranchID and a.CompID=@CompID          
   and a.AsOnDate=(Select Max(b.AsOnDate) From DD_KPI_GaugeChartData b           
                            Where b.ChartTypeId=a.ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate          
                                and b.BranchID=a.BranchID and b.CompID=a.CompID          
                            )         
   
 /* Year */  
 Select @YearTarget=(IsNull(ContributionTargetValue,0)-IsNull(NetProfitTargetValue,0)), @YearPlan=IsNull(ContributionPlanValue,0)-IsNull(NetProfitPlanValue,0)  
   --@YearPlanTillMonth=IsNull(ContributionPlanTillPeriodValue,0)-IsNull(NetProfitPlanTillPeriodValue,0)  
 From  @SalesContribution_Tbl a  
 Left Outer Join @NetProfit_Tbl b  
  On a.ContributionPeriodType=b.NetProfitPeriodType   
 Where a.ContributionPeriodType=@YearPeriodType             
    
 SET @YearPlanTillMonth=IsNull((@YearPlan/12.0) * (DateDiff(m,@YearStart,DateAdd(day, -1,@MonthStart))),0)  
    
 /* Month */  
 Select @MonthTarget=(IsNull(ContributionTargetValue,0)-IsNull(NetProfitTargetValue,0)), @MonthPlan=IsNull(ContributionPlanValue,0)-IsNull(NetProfitPlanValue,0)  
   --@MonthPlanTillDate=IsNull(ContributionPlanTillPeriodValue,0)-IsNull(NetProfitPlanTillPeriodValue,0)  
 From  @SalesContribution_Tbl a  
 Left Outer Join @NetProfit_Tbl b  
  On a.ContributionPeriodType=b.NetProfitPeriodType   
 Where a.ContributionPeriodType=@MonthPeriodType             
    
 SET @MonthPlanTillDate=Case When @MonthWorkingDays=0 Then 0 Else IsNull((@MonthPlan*@CompletedDays)/@MonthWorkingDays,0) End  
    
 /* Day */  
 Select @DayTarget=(IsNull(ContributionTargetValue,0)-IsNull(NetProfitTargetValue,0)), @DayPlan=IsNull(ContributionPlanValue,0)-IsNull(NetProfitPlanValue,0)  
   --@DayPlanTillNow=IsNull(ContributionPlanTillPeriodValue,0)-IsNull(NetProfitPlanTillPeriodValue,0)  
 From  @SalesContribution_Tbl a  
 Left Outer Join @NetProfit_Tbl b  
  On a.ContributionPeriodType=b.NetProfitPeriodType   
 Where a.ContributionPeriodType=@DayPeriodType   
    
 /* Since Hourly Plan not available DayPlanTillNow calculated on prorate basis */                  
 SET @DayPlanTillNow=IsNull((@DayPlan * DateDiff(minute, @DayStart, @AsOnDate))/DateDiff(minute, @DayStart, @DayEnd),0)   
        
 /***************************** Expense Amount From FAS *****************************/            
   
    /*  
    DECLARE @ExpenseAmount_Tbl TABLE (DocDate datetime, ExpenseAmount money)     
 Insert into @ExpenseAmount_Tbl    
  Select DocDate, Sum(DrAmt-CrAmt) as PurAmount  
  From FAS_VoucherTranSub a  
  Inner Join FAS_LedgerMaster_AuthTbl b  
   On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode  
  Where Left(b.LrRoute,2) in ('05') and a.DocDate between @YearStart and Convert(Varchar(10),@AsOnDate,121) and a.CompCode=(@CompID+@BranchID)  
  Group by DocDate  
  
 /* Day Expense Amount */       
 Select @DayAchieved=Sum(ExpenseAmount)  
 From @ExpenseAmount_Tbl a  
 Where DocDate between Convert(Varchar(10),@DayStart,121) and  Convert(Varchar(10),@AsOnDate,121)  
   
 /* Month Expense Amount */       
 Select @MonthAchieved=Sum(ExpenseAmount)  
 From @ExpenseAmount_Tbl a  
 Where DocDate between @MonthStart and Convert(Varchar(10),@AsOnDate,121)  
   
 /* Year Expense Amount */       
 Select @YearAchieved=Sum(ExpenseAmount)  
 From @ExpenseAmount_Tbl a  
 Where DocDate between @YearStart and Convert(Varchar(10),@AsOnDate,121)  
    */  
  
    /* Day */        
    Select @DayAchieved=isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId, '05', @AsOnDateWithoutTime, @AsOnDateWithoutTime, (@CompID+@BranchID)), 0);    
      
    /* Month */      
    Select @MonthAchieved=isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId, '05', @MonthStart, @AsOnDateWithoutTime, (@CompID+@BranchID)), 0);       
      
    /* Year */      
    Select @YearAchieved=isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId, '05', @YearStart, @AsOnDateWithoutTime, (@CompID+@BranchID)), 0);   
  
  
    /* Allowed Variance */                
 Select @YearVarianceAllowed=@YearVarianceAllowedPerc*@YearPlanTillMonth,                
   @MonthVarianceAllowed=@MonthVarianceAllowedPerc*@MonthPlanTillDate,          
   @DayVarianceAllowed=@DayVarianceAllowedPerc*@DayPlanTillNow        
                 
 If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate)                
  Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate      
      
 Insert into DD_KPI_GaugeChartData      
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @DayPeriodType as PeriodType, isNull(@DayTarget, 0) as TargetValue,   
   isNull(@DayPlan, 0) as PlanValue, isNull(@DayPlanTillNow, 0) as PlanTillPeriodValue, isNull(@DayAchieved, 0) as AchievedValue,     
   isNull(@DayAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.    
   isNull(@DayVarianceAllowed, 0) as AllowVariance, isNull((@DayPlanTillNow-@DayAchieved), 0) as Variance,      
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp      
        
  Union All      
          
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @MonthPeriodType as PeriodType, isNull(@MonthTarget, 0) as TargetValue,       
   isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthPlanTillDate, 0) as PlanTillPeriodValue, isNull(@MonthAchieved, 0) as AchievedValue,     
   isNull(@MonthAchieved, 0) as AchievedValue2, -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.    
   isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthPlanTillDate-@MonthAchieved), 0) as Variance,   
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp      
      
  Union All      
          
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, isNull(@YearTarget, 0) as TargetValue,       
   isNull(@YearPlan, 0) as PlanValue, isNull(@YearPlanTillMonth, 0) as PlanTillPeriodValue, isNull(@YearAchieved, 0) as AchievedValue,     
   isNull(@YearAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.    
   isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearPlanTillMonth-@YearAchieved), 0) as Variance,   
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp      
                
END   
  
  
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_FASProfit_ChartData_Ins]    Script Date: 17/06/2026 11:29:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_FASProfit_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))      
/* Process Current Date, Current Month, Current Year Data from the original table if it is changed from last process              
    and all other data will be taken from already processed data */              
AS                              
BEGIN                          
    SET NOCOUNT ON;              
              
    DECLARE @ChartTypeId int, @ChartTypeIdSales int;              
    SET @ChartTypeId=3; /* From Table ChartTypeMaster */            
    SET @ChartTypeIdSales=1;            
               
    DECLARE @CurDate datetime;              
    SET @CurDate = getdate();                  
                    
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */                
    DECLARE @ShiftStart datetime;                
    SET @ShiftStart='06:00';                
                      
    DECLARE @Finyear varchar(15);                          
                          
    /* Period Start End */                          
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                            
                    
    If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)                
    BEGIN                
        SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' 06:00';                
        --SET @MonthStart=Convert(varchar(7), DateAdd(day, -1, @AsOnDate), 120) + '-01';                
        --SET @Finyear=dbo.fn_COM_Get_Finyear(DateAdd(day, -1, @AsOnDate));                
    END                
    Else                
    BEGIN                
        SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' 06:00';                
        --SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';                
        --SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);                
    END    
        
    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';                
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);                      
                
    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));                
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                            
                  
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                          
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                                      
                   
     Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))              
     From DD_KPI_HolidayMaster              
     Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID              
                  
     Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1              
     From DD_KPI_HolidayMaster              
     Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID              
                     
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                              
    DECLARE  @MonthTarget money,  @YearTarget money ,  @DayTarget int;                              
                              
    SET @YearLabelCount=12;    /* No. of months in a Year */                          
    SET @MonthLabelCount=@MonthWorkingDays;                           
    SET @DayLabelCount=@TotalShiftHours;          
              
    DECLARE @ProfitPerc decimal(3, 2);          
    --SET @ProfitPerc=10.0/100.0;          
 SET @ProfitPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'Target','YR',@BranchID,@CompID);    
    
                              
    DECLARE @AsOnDateWithoutTime datetime, @PreviousDate datetime;        
    SET @AsOnDateWithoutTime=Convert(varchar(10), @AsOnDate, 120);       
    SET @PreviousDate=DateAdd(day, -1, @AsOnDateWithoutTime);        
                    
                 
    DECLARE @YearPlan money, @YearPlanTillMonth money, @YearAchieved money, @YearVarianceAllowedPerc decimal(5, 2), @YearVarianceAllowed money,                             
        @MonthPlan money, @MonthPlanTillDate money, @MonthAchieved int, @MonthVarianceAllowedPerc decimal(5, 2), @MonthVarianceAllowed money,                             
        @DayPlan money, @DayPlanTillNow money, @DayAchieved money, @DayVarianceAllowedPerc decimal(5, 2), @DayVarianceAllowed money;           
          
          
    DECLARE @Sales_Tbl TABLE (PeriodType varchar(2), TargetValue money, PlanValue money, AchievedValue money, AllowVariance money);          
    Insert into @Sales_Tbl          
        Select PeriodType, TargetValue, PlanValue, AchievedValue, AllowVariance          
        From DD_KPI_GaugeChartData a          
        Where a.ChartTypeId=@ChartTypeIdSales          
            and a.BranchID=@BranchID and a.CompID=@CompID          
            and a.AsOnDate=(Select Max(b.AsOnDate) From DD_KPI_GaugeChartData b           
                            Where b.ChartTypeId=a.ChartTypeId and b.AsOnDate<=@AsOnDate          
                                and b.BranchID=a.BranchID and b.CompID=a.CompID          
                            )          
                  
    Select @YearTarget=TargetValue*@ProfitPerc, @YearPlan=PlanValue*@ProfitPerc, @YearPlanTillMonth=AchievedValue*@ProfitPerc,          
            @YearVarianceAllowed=AllowVariance*@ProfitPerc          
    From @Sales_Tbl a          
    Where a.PeriodType='YR'          
          
    Select @MonthTarget=TargetValue*@ProfitPerc, @MonthPlan=PlanValue*@ProfitPerc, @MonthPlanTillDate=AchievedValue*@ProfitPerc,          
            @MonthVarianceAllowed=AllowVariance*@ProfitPerc          
    From @Sales_Tbl a          
    Where a.PeriodType='MN'      
          
    Select @DayTarget=TargetValue*@ProfitPerc, @DayPlan=PlanValue*@ProfitPerc, @DayPlanTillNow=AchievedValue*@ProfitPerc,          
            @DayVarianceAllowed=AllowVariance*@ProfitPerc          
    From @Sales_Tbl a          
    Where a.PeriodType='DY'          
    /*      
    Select @DayTarget=(@MonthTarget*@ProfitPerc/@MonthWorkingDays), @DayPlan=(@MonthPlan*@ProfitPerc/@MonthWorkingDays),         
            @DayPlanTillNow=Sum(InvoiceQty*Rate)*@ProfitPerc,  @DayVarianceAllowed=(@MonthVarianceAllowed*@ProfitPerc/@MonthWorkingDays)        
    From SalesInvoice a          
    Where a.InvoiceDate=@AsOnDateWithoutTime and a.Branchid=@BranchID and a.Compid=@CompID         
    */      
    DECLARE @CmCode varchar(12);          
    SET @CmCode=@CompId+@BranchId;          
          
    /* Day */          
    --Select @DayAchieved=-isNull(dbo.fn_FAS_Profit_Loss_Period(@AsOnDateWithoutTime, @AsOnDateWithoutTime, @CmCode), 0);      
    Select @DayAchieved=-isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId, '', @AsOnDateWithoutTime, @AsOnDateWithoutTime, @CmCode), 0);    
	    
    /* Month */        
   -- Select @MonthAchieved=-isNull(dbo.fn_FAS_Profit_Loss_Period(@MonthStart, @AsOnDateWithoutTime, @CmCode), 0);
	Select @MonthAchieved=-isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId, '', @MonthStart, @AsOnDateWithoutTime, @CmCode), 0);               
        
    /* Year */        
   -- Select @YearAchieved=-isNull(dbo.fn_FAS_Profit_Loss_Period(@YearStart, @AsOnDateWithoutTime, @CmCode), 0);        
    Select @YearAchieved=-isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId, '', @YearStart, @AsOnDateWithoutTime, @CmCode), 0);     
	            
 If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate)                        
        Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate              
              
 Insert into DD_KPI_GaugeChartData              
      Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, 'DY' as PeriodType, isNull(@DayTarget, 0) as TargetValue, isNull(@DayPlan, 0) as PlanValue,               
       isNull(@DayPlanTillNow, 0) as PlanTillPeriodValue, isNull(@DayAchieved, 0) as AchievedValue,             
    isNull(@DayAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.            
    isNull(@DayVarianceAllowed, 0) as AllowVariance,                
       isNull((@DayPlanTillNow-@DayAchieved), 0) as Variance,              
       @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp              
                
    Union All              
                  
      Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, 'MN' as PeriodType, isNull(@MonthTarget, 0) as TargetValue,               
       isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthPlanTillDate, 0) as PlanTillPeriodValue, isNull(@MonthAchieved, 0) as AchievedValue,             
    isNull(@MonthAchieved, 0) as AchievedValue2, -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.            
    isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthPlanTillDate-@MonthAchieved), 0) as Variance, @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp              
              
      Union All              
                  
      Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, 'YR' as PeriodType, isNull(@YearTarget, 0) as TargetValue,               
       isNull(@YearPlan, 0) as PlanValue, isNull(@YearPlanTillMonth, 0) as PlanTillPeriodValue, isNull(@YearAchieved, 0) as AchievedValue,             
    isNull(@YearAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.            
    isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearPlanTillMonth-@YearAchieved), 0) as Variance, @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp              
                        
END 
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_FGReceiptValue_ChartData_Ins]    Script Date: 17/06/2026 11:29:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_FGReceiptValue_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))          
/* Process Current Date, Current Month, Current Year Data from the original table if it is changed from last process        
    and all other data will be taken from already processed data */        
AS                        
BEGIN                    
    SET NOCOUNT ON;        
        
 DECLARE @ChartTypeId int, @ChartTypeIdSales int;             
  SET @ChartTypeId=9; /* From Table ChartTypeMaster */        
  SET @ChartTypeIdSales=1;              
    
 DECLARE @CurDate datetime;        
  SET @CurDate = getdate();            
              
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */          
    DECLARE @ShiftStart datetime;          
  SET @ShiftStart='06:00';          
                
    DECLARE @Finyear varchar(15);                    
                    
    /* Period Start End */                    
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                      
              
    If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)          
  BEGIN          
   SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' 06:00';              
  END          
    Else          
  BEGIN          
   SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' 06:00';               
  END    
    
    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';        
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);    
    
    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));          
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                      
            
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                    
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                                
             
    Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))        
    From DD_KPI_HolidayMaster        
    Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID        
            
    Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1        
    From DD_KPI_HolidayMaster        
    Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID        
               
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                                        
  SET @YearLabelCount=12;    /* No. of months in a Year */                    
  SET @MonthLabelCount=@MonthWorkingDays;                     
  SET @DayLabelCount=@TotalShiftHours;                        
        
 DECLARE @YearPeriodType Char(2), @MonthPeriodType Char(2), @DayPeriodType Char(2)    
  SELECT @YearPeriodType='YR', @MonthPeriodType='MN', @DayPeriodType='DY'    
                               
 DECLARE @YearTarget money, @YearPlan money, @YearPlanTillMonth money, @YearAchieved money, @YearVarianceAllowed money,                       
   @MonthTarget money, @MonthPlan money, @MonthPlanTillDate money, @MonthAchieved money, @MonthVarianceAllowed money,                       
   @DayTarget money, @DayPlan money, @DayPlanTillNow money, @DayAchieved money, @DayVarianceAllowed money;          
                                    
    
 /***************************** Sales Plan *****************************/       
    DECLARE @Sales_Tbl TABLE (PeriodType varchar(2), TargetValue money, PlanValue money, PlanTillPeriodValue money, AllowVariance money);            
    Insert into @Sales_Tbl            
        Select PeriodType, TargetValue, PlanValue, PlanTillPeriodValue, AllowVariance            
        From DD_KPI_GaugeChartData a            
        Where a.ChartTypeId=@ChartTypeIdSales            
            and a.BranchID=@BranchID and a.CompID=@CompID            
   and a.AsOnDate=(Select Max(b.AsOnDate) From DD_KPI_GaugeChartData b             
                            Where b.ChartTypeId=a.ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate            
                                and b.BranchID=a.BranchID and b.CompID=a.CompID            
                            )            
           
 Select @YearTarget=TargetValue, @YearPlan=PlanValue, @YearPlanTillMonth=PlanTillPeriodValue, @YearVarianceAllowed=AllowVariance           
    From @Sales_Tbl a            
    Where a.PeriodType=@YearPeriodType           
            
    Select @MonthTarget=TargetValue, @MonthPlan=PlanValue, @MonthPlanTillDate=PlanTillPeriodValue, @MonthVarianceAllowed=AllowVariance            
    From @Sales_Tbl a            
    Where a.PeriodType=@MonthPeriodType      
            
    Select @DayTarget=TargetValue, @DayPlan=PlanValue, @DayPlanTillNow=PlanTillPeriodValue,  @DayVarianceAllowed=AllowVariance            
    From @Sales_Tbl a            
    Where a.PeriodType=@DayPeriodType       
    
 /***************************** FG Receipt *****************************/              
     
 DECLARE @OrderRate_Tbl TABLE (ItemCode varchar(20), Rate money, CreatedDate datetime)       
  Insert into @OrderRate_Tbl    
   Select b.ItemCode, b.Rate, b.CreatedDate      
   From dbo.fn_SAL_Order_Dtl(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear) b      
   Where b.CreatedDate=(Select MAX(g.CreatedDate) AS CreatedDate                           
         FROM dbo.fn_SAL_Order_Dtl(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear) g                         
         Where g.ItemCode=b.ItemCode)       
   Union All      
      
   Select b.SentItemCode, b.Rate, b.CreatedDate      
   From dbo.fn_SAL_JobWorkOrder_Dtl(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear) b      
   Where b.CreatedDate=(Select MAX(g.CreatedDate) AS CreatedDate                           
         FROM dbo.fn_SAL_JobWorkOrder_Dtl(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear) g                         
         Where g.SentItemCode=b.SentItemCode)     
  
 DECLARE @FGReceipt_Tbl TABLE (ItemCode varchar(20),  TransactionDate datetime, FGReceiptQty money, Rate money)       
  Insert into @FGReceipt_Tbl    
   Select a.TransactionItem as ItemCode, a.TransactionDate, a.TransactionQty as FGReceiptQty,     
    Case When (IsNull(b.Rate,0)=0 or b.Rate=0)  Then IsNull(c.Rate,0) Else IsNull(b.Rate,0) End as Rate    
   From INV_MaterialTran_Dtl a    
   Outer Apply    
    (       
     Select ItemCode, o.Rate       
     From @OrderRate_Tbl o      
     Where o.ItemCode=a.TransactionItem     
      and o.CreatedDate=(Select MAX(s.CreatedDate) AS CreatedDate                           
           FROM @OrderRate_Tbl s                         
           Where s.ItemCode=o.ItemCode                          
          )       
    )b             
   Outer Apply    
    (    
     Select Top 1 o2.ItemCode, o2.Rate    
     From    
     (    
      Select ItemCode, Rate, 1 as Priority      
      From dbo.fn_Sal_Customer_ItemMaster('A', @AsOnDate, @AsOnDate, @BranchID, @CompID)o     
      Where o.Itemcode = a.TransactionItem     
       /* and o.Transtamp=(Select Max(s.Transtamp)     
            From fn_Sal_Customer_ItemMaster('A', @AsOnDate, @AsOnDate, @BranchID, @CompID) s    
            Where s.ItemCode=o.ItemCode    
           )  */  
           
      Union All       
           
      Select SentItemCode, Rate, 2 as Priority        
      From Sal_Jobwork_ItemMaster o1 --dbo.fn_Sal_Jobwork_ItemMaster('A', @AsOnDate, @AsOnDate, @BranchID, @CompID)o1      
      Where o1.SentItemCode = a.TransactionItem      
        and o1.Transtamp=(Select Max(s.Transtamp)     
             From Sal_Jobwork_ItemMaster s --fn_Sal_Jobwork_ItemMaster('A', @AsOnDate, @AsOnDate, @BranchID, @CompID) s    
             Where s.SentItemCode=o1.SentItemCode    
            )  
         
      Union All      
           
      Select a.TransactionItem, dbo.fn_BOM_Get_ItemRate('A', a.TransactionItem, @AsOnDate, @AsOnDate, @BranchID, @CompID) as Rate, 3 as Priority    
     ) o2    
     Order by o2.Priority    
    )c    
   Where TransactionDate between @YearStart and @AsOnDate and ToWarehouseCode in ('FGS')    
    and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear    
     
 /* Day FG Receipt */         
 Select @DayAchieved=Sum(FGReceiptQty*Rate)    
 From @FGReceipt_Tbl a    
 Where TransactionDate between @DayStart and @AsOnDate    
     
 /* Month FG Receipt */         
 Select @MonthAchieved=Sum(FGReceiptQty*Rate)    
 From @FGReceipt_Tbl a    
 Where TransactionDate between @MonthStart and @AsOnDate    
     
 --/* Year FG Receipt */             
 --Select @YearAchieved=Sum(YearAchieved)        
 --From        
 --(        
 -- Select @MonthAchieved as YearAchieved        
            
 -- Union All        
        
 -- /* Year Sales (From Digital Data Table) */        
 -- Select IsNull(Sum(AchievedValue),0) as YearAchieved        
 -- From DD_KPI_GaugeChartData a         
 -- Inner Join             
 --  (      
 --   Select Convert(Varchar(7), AsOnDate,120) as YearMonth, Max(AsOnDate) as AsOnDate      
 --   From DD_KPI_GaugeChartData      
 --   Where ChartTypeId=@ChartTypeId and PeriodType=@MonthPeriodType        
 --   and Convert(Varchar(10),AsOnDate,120)<@MonthStart      
 --   and BranchID=@BranchID and CompID=@CompID        
 --   Group by  Convert(Varchar(7), AsOnDate,120)      
 --  )b      
 --  On a.AsOnDate=b.AsOnDate             
 -- Where a.ChartTypeId=@ChartTypeId and a.PeriodType=@MonthPeriodType and Convert(Varchar(10),a.AsOnDate,120)<@MonthStart      
 --  and a.BranchID=@BranchID and a.CompID=@CompID         
 --)a     
    
 Select @YearAchieved=Sum(FGReceiptQty*Rate)    
 From @FGReceipt_Tbl a    
 Where TransactionDate between @YearStart and @AsOnDate    
                      
 If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate)                  
  Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate        
        
 Insert into DD_KPI_GaugeChartData        
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @DayPeriodType as PeriodType, isNull(@DayTarget, 0) as TargetValue,     
   isNull(@DayPlan, 0) as PlanValue, isNull(@DayPlanTillNow, 0) as PlanTillPeriodValue, isNull(@DayAchieved, 0) as AchievedValue,       
   isNull(@DayAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.      
   isNull(@DayVarianceAllowed, 0) as AllowVariance, isNull((@DayPlanTillNow-@DayAchieved), 0) as Variance,        
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp        
          
  Union All        
            
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @MonthPeriodType as PeriodType, isNull(@MonthTarget, 0) as TargetValue,         
   isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthPlanTillDate, 0) as PlanTillPeriodValue, isNull(@MonthAchieved, 0) as AchievedValue,       
   isNull(@MonthAchieved, 0) as AchievedValue2, -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.      
   isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthPlanTillDate-@MonthAchieved), 0) as Variance,     
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp        
        
  Union All        
            
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, isNull(@YearTarget, 0) as TargetValue,         
   isNull(@YearPlan, 0) as PlanValue, isNull(@YearPlanTillMonth, 0) as PlanTillPeriodValue, isNull(@YearAchieved, 0) as AchievedValue,       
   isNull(@YearAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.      
   isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearPlanTillMonth-@YearAchieved), 0) as Variance,        @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp        
                  
END        
      
    
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_GaugeChart_Data_Get_V2]    Script Date: 17/06/2026 11:29:55 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[DD_KPI_GaugeChart_Data_Get_V2](@ChartTypeId int, @AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))    
AS              
BEGIN          
    SET NOCOUNT ON;      
      
	DECLARE @LabelSeries Varchar(10)
		SET @LabelSeries = 'PERIOD'

		Select @LabelSeries=LabelSeries 
		From DD_KPI_ChartMaster 
		Where ChartTypeId=@ChartTypeId and BranchID=@BranchID and CompID=@CompID

    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */        
    DECLARE @ShiftStart datetime;        
    SET @ShiftStart='06:00';        
              
    /* Period Start End */                  
    DECLARE @MonthStart datetime, @MonthEnd datetime;                    
            
    If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)        
		BEGIN        
			SET @MonthStart=Convert(varchar(7), DateAdd(day, -1, @AsOnDate), 120) + '-01';        
		END        
    Else        
		BEGIN        
			SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';        
		END        
        
    SELECT @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));        
          
          
    DECLARE @MonthWorkingDays int, @TotalShiftHours int;          
    --SET @MonthWorkingDays=24;   /* It should be calculated based Sundays & Holidays in the given month */          
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */          
    -- Select * from PAY_Holiday_Dtl            
          
	Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))      
	From DD_KPI_HolidayMaster      
	Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID      
           
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;              
    DECLARE  @MonthTarget money,  @YearTarget money ,  @DayTarget int;              
              
    SET @YearLabelCount=12;    /* No. of months in a Year */          
    SET @MonthLabelCount=Day(@MonthEnd);           
    SET @DayLabelCount=@TotalShiftHours;              
              
    SET @YearTarget=360000000;              
    SET @MonthTarget=@YearTarget/12;              
    SET @DayTarget= @MonthTarget/@MonthWorkingDays ;              
            
    DECLARE @YearPlan money, @YearPlanTillMonth money, @YearSales money, @YearSales2 money,  @YearVarianceAllowed money, @YearVariance money, @YearPomoneyer money,             
        @MonthPlan money, @MonthPlanTillDate money, @MonthSales money, @MonthSales2 money, @MonthVarianceAllowed money, @MonthVariance money, @MonthPomoneyer money,      
        @DayPlan money, @DayPlanTillNow money, @DaySales money, @DaySales2 money, @DayVarianceAllowed money, @DayVariance money, @DayPomoneyer money;            
            
          
    Select @YearTarget=TargetValue, @YearPlan=PlanValue, @YearPlanTillMonth=PlanTillPeriodValue, @YearSales=AchievedValue, @YearSales2=AchievedValue2,       
                @YearVarianceAllowed=AllowVariance, @YearVariance=Variance     
    From DD_KPI_GaugeChartData a      
    Where a.ChartTypeId=@ChartTypeId and a.PeriodType='YR'    
		and a.AsOnDate=(Select Max(AsOnDate) From DD_KPI_GaugeChartData b     
						Where b.ChartTypeId=@ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate)      
    
	Select @MonthTarget=TargetValue, @MonthPlan=PlanValue, @MonthPlanTillDate=PlanTillPeriodValue, @MonthSales=AchievedValue, @MonthSales2=AchievedValue2,
                @MonthVarianceAllowed=AllowVariance, @MonthVariance=Variance      
    From DD_KPI_GaugeChartData a      
    Where a.ChartTypeId=@ChartTypeId and a.PeriodType='MN'    
		and a.AsOnDate=(Select Max(AsOnDate) From DD_KPI_GaugeChartData b     
						Where b.ChartTypeId=@ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate)    
    
	Select @DayTarget=TargetValue, @DayPlan=PlanValue, @DayPlanTillNow=PlanTillPeriodValue, @DaySales=AchievedValue, @DaySales2=AchievedValue2,       
                @DayVarianceAllowed=AllowVariance, @DayVariance=Variance    
    From DD_KPI_GaugeChartData a      
    Where a.ChartTypeId=@ChartTypeId and a.PeriodType='DY'   
		and a.AsOnDate=(Select Max(AsOnDate) From DD_KPI_GaugeChartData b     
						Where b.ChartTypeId=@ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate)    
      
	
	DECLARE @ActualLabelCount int, @ActualLabelCountBasedOnDigit int, @YearRndOffAchievedValue money, @MonthRndOffAchievedValue money, @DayRndOffAchievedValue money;	  
		Select @ActualLabelCount=10;

	/* Round Off Achieved Value */
	IF @LabelSeries = 'ACTUAL' 
		BEGIN
			/* For Year */
			IF (@YearTarget+@YearVarianceAllowed) > @YearSales
				BEGIN
					SELECT @ActualLabelCountBasedOnDigit='1' + Case When Len(Convert(int,(@YearTarget+@YearVarianceAllowed)))=1 Then '0' 
															Else Convert(Varchar,replicate(0,Len(Convert(int,(@YearTarget+@YearVarianceAllowed))+1)-1)) End

					SELECT @YearRndOffAchievedValue=dbo.fn_RoundOff((@YearTarget+@YearVarianceAllowed)+1, @ActualLabelCountBasedOnDigit, 0, 'U')  
				END
			ELSE
				BEGIN
					SELECT @ActualLabelCountBasedOnDigit='1' + Case When Len(Convert(int,@YearSales))=1 Then '0' 
															Else Convert(Varchar,replicate(0,Len(Convert(int,@YearSales)+1)-1)) End

					SELECT @YearRndOffAchievedValue=dbo.fn_RoundOff(@YearSales+1, @ActualLabelCountBasedOnDigit, 0, 'U')  
				END

			/* For Month */
			IF (@MonthTarget+@MonthVarianceAllowed) > @MonthSales 
				BEGIN
					SELECT @ActualLabelCountBasedOnDigit='1' + Case When Len(Convert(int,(@MonthTarget+@MonthVarianceAllowed)))=1 Then '0' 
															Else Convert(Varchar,replicate(0,Len(Convert(int,(@MonthTarget+@MonthVarianceAllowed))+1)-1)) End
					
					SELECT @MonthRndOffAchievedValue=dbo.fn_RoundOff((@MonthTarget+@MonthVarianceAllowed)+1, @ActualLabelCountBasedOnDigit, 0, 'U') 

				END
			ELSE
				BEGIN
					SELECT @ActualLabelCountBasedOnDigit='1' + Case When Len(Convert(int,@MonthSales))=1 Then '0' 
															Else Convert(Varchar,replicate(0,Len(Convert(int,@MonthSales)+1)-1)) End

					SELECT @MonthRndOffAchievedValue=dbo.fn_RoundOff(@MonthSales+1, @ActualLabelCountBasedOnDigit, 0, 'U')  
				END

			/* For Day */
			IF (@DayTarget+@DayVarianceAllowed) > @DaySales 
				BEGIN
					SELECT @ActualLabelCountBasedOnDigit='1' + Case When Len(Convert(int,(@DayTarget+@DayVarianceAllowed)))=1 Then '0' 
															Else Convert(Varchar,replicate(0,Len(Convert(int,(@DayTarget+@DayVarianceAllowed))+1)-1)) End
					
					SELECT @DayRndOffAchievedValue=dbo.fn_RoundOff((@DayTarget+@DayVarianceAllowed)+1, @ActualLabelCountBasedOnDigit, 0, 'U') 

				END
			ELSE
				BEGIN
					SELECT @ActualLabelCountBasedOnDigit='1' + Case When Len(Convert(int,@DaySales))=1 Then '0' 
															Else Convert(Varchar,replicate(0,Len(Convert(int,@DaySales)+1)-1)) End

					SELECT @DayRndOffAchievedValue=dbo.fn_RoundOff(@DaySales+1, @ActualLabelCountBasedOnDigit, 0, 'U')  
				END
		END
	  
     
	Select SI_No,ChartType, LabelText, ISNULL(LabelValue,0) as LabelValue     
	From 
	(        
		/* Year */
		Select 1 as SI_No,'YearWise' as  ChartType, 'Year Target' as LabelText, @YearTarget as LabelValue              
		Union All              
		Select 2 as SI_No,'YearWise' as  ChartType, 'Year Plan' as LabelText, @YearPlan as LabelValue              
		Union All              
		Select 3 as SI_No,'YearWise' as  ChartType, 'Target Till Month' as LabelText, @YearPlanTillMonth as LabelValue              
		Union All              
		Select 4 as SI_No,'YearWise' as  ChartType, 'Achieved Value' as LabelText, @YearSales as LabelValue              
		Union All              
		Select 5 as SI_No,'YearWise' as  ChartType, 'Allowed Variance' as LabelText, @YearVarianceAllowed as LabelValue              
		Union All              
		Select 6 as SI_No,'YearWise' as  ChartType, 'Variance' as LabelText, @YearVariance as LabelValue		--(@YearPlanTillMonth-@YearSales)
		Union All              
		Select 7 as SI_No,'YearWise' as  ChartType, 'Pointer Target' as LabelText, 
			Case When @LabelSeries = 'PERIOD' Then
				Case When @YearTarget <= 0 Then 0 Else (@YearLabelCount * @YearSales / @YearTarget) End  
			Else @YearSales End as LabelValue   
		Union All              
		Select 8 as SI_No,'YearWise' as  ChartType, 'Pointer Target2' as LabelText, 
			Case When @LabelSeries = 'PERIOD' Then
				Case When @YearTarget <= 0 Then 0 Else (@YearLabelCount * @YearSales2 / @YearTarget) End  
			Else @YearSales2 End as LabelValue   
		Union All
		Select 9 as SI_No,'YearWise' as  ChartType, 'Dial Max' as LabelText, 
			Case When @LabelSeries = 'PERIOD' Then
						Case When @YearTarget <= 0 Then 0 Else (@YearLabelCount * @YearSales2 / @YearTarget) End               
				Else @YearRndOffAchievedValue					
					/*Case When (@YearTarget+@YearVarianceAllowed) > @YearSales Then  
						dbo.fn_RoundOff((@YearTarget+@YearVarianceAllowed)+1, 10, 0, 'U')
					Else  
						dbo.fn_RoundOff(@YearSales+1, 10, 0, 'U') End*/
				End as LabelValue

		/* Month */
		Union All              
		Select 21 as SI_No,'MonthWise' as  ChartType, 'Month Target' as LabelText, @MonthTarget as LabelValue              
		Union All              
		Select 22 as SI_No,'MonthWise' as  ChartType, 'Month Plan' as LabelText, @MonthPlan as LabelValue              
		Union All              
		Select 23 as SI_No,'MonthWise' as  ChartType, 'Target Till Date' as LabelText, @MonthPlanTillDate as LabelValue              
		Union All              
		Select 24 as SI_No,'MonthWise' as  ChartType, 'Achieved Value' as LabelText, @MonthSales as LabelValue              
		Union All              
		Select 25 as SI_No,'MonthWise' as  ChartType, 'Allowed Variance' as LabelText, @MonthVarianceAllowed as LabelValue              
		Union All              
		Select 26 as SI_No,'MonthWise' as  ChartType, 'Variance' as LabelText, @MonthVariance as LabelValue	--(@MonthPlanTillDate-@MonthSales)            
		Union All              
		Select 27 as SI_No,'MonthWise' as  ChartType, 'Pointer Target' as LabelText, 
			Case When @LabelSeries = 'PERIOD' Then
					Case When @MonthTarget <= 0 Then 0 Else (@MonthLabelCount * @MonthSales / @MonthTarget) End  
				Else @MonthSales  End as LabelValue    
		Union All              
		Select 28 as SI_No,'MonthWise' as  ChartType, 'Pointer Target2' as LabelText, 
			Case When @LabelSeries = 'PERIOD' Then
					Case When @MonthTarget <= 0 Then 0 Else (@MonthLabelCount * @MonthSales2 / @MonthTarget) End  
				Else @MonthSales2 End as LabelValue 
		Union All              
		Select 29 as SI_No,'MonthWise' as  ChartType, 'Dial Max' as LabelText, 
			Case When @LabelSeries = 'PERIOD' Then
					Case When @MonthTarget <= 0 Then 0 Else (@MonthLabelCount * @MonthSales / @MonthTarget) End   
				Else @MonthRndOffAchievedValue 
					/*Case When (@MonthTarget+@MonthVarianceAllowed) > @MonthSales Then  
						dbo.fn_RoundOff((@MonthTarget+@MonthVarianceAllowed)+1, 10, 0, 'U') 
					Else  
						dbo.fn_RoundOff(@MonthSales+1, 10, 0, 'U')  
					End*/
				End as LabelValue

		/* Day */
		Union All              
		Select 41 as SI_No,'DayWise' as  ChartType, 'Day Target' as LabelText, @DayTarget as LabelValue              
		Union All              
		Select 42 as SI_No,'DayWise' as  ChartType, 'Day Plan' as LabelText, @DayPlan as LabelValue              
		Union All              
		Select 43 as SI_No,'DayWise' as  ChartType, 'Target Till Now ' as LabelText, @DayPlanTillNow as LabelValue              
		Union All              
		Select 44 as SI_No,'DayWise' as  ChartType, 'Achieved Value' as LabelText, @DaySales as LabelValue              
		Union All              
		Select 45 as SI_No,'DayWise' as  ChartType, 'Allowed Variance' as LabelText, @DayVarianceAllowed as LabelValue              
		Union All              
		Select 46 as SI_No,'DayWise' as  ChartType, 'Variance' as LabelText, @DayVariance as LabelValue		--(@DayPlanTillNow-@DaySales)             
		Union All              
		Select 47 as SI_No,'DayWise' as  ChartType, 'Pointer Target' as LabelText, 
			Case When @LabelSeries = 'PERIOD' Then
					Case When @DayTarget <= 0 Then 0 Else (@DayLabelCount * @DaySales / @DayTarget) End 
				Else @DaySales End as LabelValue  
		Union All              
		Select 48 as SI_No,'DayWise' as  ChartType, 'Pointer Target2' as LabelText, 
			Case When @LabelSeries = 'PERIOD' Then
					Case When @DayTarget <= 0 Then 0 Else (@DayLabelCount * @DaySales2 / @DayTarget) End 
				Else @DaySales2 End as LabelValue                
		Union All              
		Select 49 as SI_No,'DayWise' as  ChartType, 'Dial Max' as LabelText, 
			Case When @LabelSeries = 'PERIOD' Then
					Case When @DayTarget <= 0 Then 0 Else (@DayLabelCount * @DaySales2 / @DayTarget) End              
				Else @DayRndOffAchievedValue
					/*Case When (@DayTarget+@DayVarianceAllowed) > @DaySales Then  
						dbo.fn_RoundOff((@DayTarget+@DayVarianceAllowed)+1, 10, 0, 'U')
					Else  
						dbo.fn_RoundOff(@DaySales+1, 10, 0, 'U')  
					End*/
				End as LabelValue 
	) a         
	Order by a.SI_No asc        
END 

GO

