CREATE PROCEDURE [dbo].[DD_KPI_GaugeChart_LabelSeries_Get](@ChartTypeId int, @AsOnDate Datetime, @BranchID int, @CompID int)                      
AS                      
BEGIN                      
    SET NOCOUNT ON;          
    	 
	DECLARE @LabelSeries Varchar(10);
		SET @LabelSeries = 'PERIOD'

	Select @LabelSeries=LabelSeries
	From DD_KPI_ChartMaster 
	Where ChartTypeId=@ChartTypeId and BranchID=@BranchID and CompID=@CompID;

	IF @LabelSeries = 'PERIOD'
		EXECUTE DD_KPI_GaugeChart_LabelSeries_Get_Period @AsOnDate, @BranchID, @CompID
	ELSE
		EXECUTE DD_KPI_GaugeChart_LabelSeries_Get_Actual @ChartTypeId, @AsOnDate, @BranchID, @CompID
           
END 

GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_GaugeChart_LabelSeries_Get_Actual]    Script Date: 17/06/2026 11:29:55 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_GaugeChart_LabelSeries_Get_Actual](@ChartTypeId int, @AsOnDate Datetime, @BranchID int, @CompID int)                        
AS                        
BEGIN                        
    SET NOCOUNT ON;            
       
 DECLARE @LabelCount int, @LabelCountBasedOnDigit int;  
  SELECT @LabelCount = 10, @LabelCountBasedOnDigit=10;  
  
 DECLARE @PeriodType Char(2), @AchievedValue int, @RndOffAchievedValue int;  
  
 DECLARE @RetTbl TABLE (PeriodType char(2), SeqNo int,  SeriesValue int);  
  
 DECLARE GaugeChartData CURSOR  FOR  
  Select PeriodType, AchievedValue  
  From DD_KPI_GaugeChartData a   
  Where a.ChartTypeId=@ChartTypeId and a.BranchID=@BranchID and a.CompID=@CompID  
   and a.AsOnDate=(Select Max(AsOnDate) From DD_KPI_GaugeChartData b       
       Where b.ChartTypeId=a.ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate  
        and b.BranchID=a.BranchID and b.CompID=a.CompID  
       )     
 OPEN GaugeChartData  
 FETCH NEXT FROM GaugeChartData into  @PeriodType, @AchievedValue  
 WHILE @@FETCH_STATUS = 0  
  BEGIN  
  
   SELECT @LabelCountBasedOnDigit='1' + Case When Len(Convert(int,@AchievedValue))=1 Then '0'   
                      Else Convert(Varchar,replicate(0,Len(Convert(int,@AchievedValue)+1)-1)) End  
  
   SELECT @RndOffAchievedValue=dbo.fn_RoundOff(@AchievedValue+1, @LabelCountBasedOnDigit, 0, 'U')    
  
   INSERT INTO @RetTbl  
    SELECT @PeriodType as PeriodType, SeqNo, SeriesValue   
    FROM fn_COM_Get_NumberSeries(0, @RndOffAchievedValue, (@RndOffAchievedValue/@LabelCount), 0,1)  
  
   FETCH NEXT FROM GaugeChartData into  @PeriodType, @AchievedValue  
  END       
   
   
 CLOSE GaugeChartData  
 DEALLOCATE GaugeChartData  
   
 Select Convert(varchar(20), Convert(int, @LabelCount+1)) as YearSeries,       
        Convert(varchar(20), Convert(int, @LabelCount+1)) as MonthSeries,     
  Convert(varchar(20), Convert(int, @LabelCount+1)) as DaySeries            
    UNION ALL    
    
 Select a.SeriesValue as YearSeries, b.SeriesValue as MonthSeries, c.SeriesValue as DaySeries  
 From @RetTbl a  
 Full Outer Join @RetTbl b  
  On b.PeriodType='MN' and a.SeqNo=b.SeqNo  
 Full Outer Join @RetTbl c  
  On c.PeriodType='DY' and a.SeqNo=c.SeqNo  
 Where a.PeriodType='YR'  
     
END   
GO

