CREATE PROCEDURE [dbo].[DD_KPI_GaugeChart_LabelSeries_Get_Period](@AsOnDate Datetime, @BranchID int, @CompID int)                        
AS                        
BEGIN                        
    SET NOCOUNT ON;            
        
 /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */      
    DECLARE @ShiftStart datetime;      
    SET @ShiftStart='06:00';      
              
    DECLARE @Finyear varchar(15);                
                
    /* Period Start End */                
    DECLARE @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;    
          
    If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)      
    BEGIN      
        SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' 06:00';      
        SET @MonthStart=Convert(varchar(7), DateAdd(day, -1, @AsOnDate), 120) + '-01';      
        SET @Finyear=dbo.fn_COM_Get_Finyear(DateAdd(day, -1, @AsOnDate));      
    END      
    Else      
    BEGIN      
        SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' 06:00';      
        SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';      
        SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);      
    END      
      
    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));      
        
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;              
    --SET @MonthWorkingDays=DAY(@MonthEnd);   /* It should be calculated based Sundays & Holidays in the given month */              
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */              
    -- Select * from PAY_Holiday_Dtl                
        
 Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))    
 From DD_KPI_HolidayMaster    
 Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID    
    
    DECLARE @MonthCount int, @DayCount int, @HourCount int;            
    SET @MonthCount=12; /* Fixed. So Hard Coded */            
    SET @DayCount=Day(@MonthEnd);   /* It should be calculated as Month Working Days */            
    SET @HourCount=24;  /* It should be calculated from Per day production shift hours total */            
            
 DECLARE @MonthLabelStart int, @DayLabelStart int, @HourLabelStart int    
    SET @MonthLabelStart=4;  /* Generally it is always for Financial Year. So 4 for April */            
    SET @DayLabelStart=1;    /* Generally it always start from Day 1. So Hard Coded */            
    SET @HourLabelStart=6;   /* It should be come from Shift Master Day First Shift Start Time */            
            
    Select Convert(varchar(20), Convert(int, @MonthCount+1)) as YearSeries,       
        Convert(varchar(20), Convert(int, @DayCount+1)) as MonthSeries,     
  Convert(varchar(20), Convert(int, @HourCount+1)) as DaySeries            
    UNION ALL            
    Select Convert(varchar(20), Convert(int, c.SeriesValue)) as YearSeries,       
        Convert(varchar(20), Convert(int, b.SeriesValue)) as MonthSeries,     
  Convert(varchar(20), Convert(int, a.SeriesValue)) as DaySeries             
    From fn_COM_Get_NumberSeries(1, @HourCount, 1, @HourLabelStart,1) a            
    FULL OUTER JOIN fn_COM_Get_NumberSeries(1, @DayCount, 1, @DayLabelStart,1) b            
        On a.SeqNo=b.SeqNo            
    FULL OUTER JOIN fn_COM_Get_NumberSeries(1, @MonthCount, 1, @MonthLabelStart,1) c            
        On a.SeqNo=c.SeqNo            
                
END   
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_GaugeChart_SetColor_Get_V2]    Script Date: 17/06/2026 11:29:55 ******/
SET ANSI_NULLS ON
GO

