GO


CREATE PROCEDURE [dbo].[DD_KPI_GaugeChart_SetColor_Get_V2] (@ChartTypeId int, @AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))
AS                      
BEGIN                      
    SET NOCOUNT ON;            
    
	DECLARE @LabelSeries Varchar(10)
		SET @LabelSeries = 'PERIOD'

		Select @LabelSeries = LabelSeries 
		From DD_KPI_ChartMaster      
		Where ChartTypeId=@ChartTypeId and BranchID=@BranchID and CompID=@CompID

	/* Currently Day First shift starttime hard coded. It should be taken from Shift Master */        
    DECLARE @ShiftStart datetime;        
    SET @ShiftStart='06:00';        
                
    DECLARE @Finyear varchar(15);                  
                  
    /* Period Start End */                  
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                    
            
    If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)        
		BEGIN        
			SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' 06:00';        
			SET @MonthStart=Convert(varchar(7), DateAdd(day, -1, @AsOnDate), 120) + '-01';        
			SET @Finyear=dbo.fn_COM_Get_Finyear(DateAdd(day, -1, @AsOnDate));        
		END        
    Else        
		BEGIN        
			SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' 06:00';        
			SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';        
			SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);        
		END        
        
    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));        
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);      
      
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                
    --SET @MonthWorkingDays=DAY(@MonthEnd);   /* It should be calculated based Sundays & Holidays in the given month */                
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                
    -- Select * from PAY_Holiday_Dtl                  
          
    Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))      
    From DD_KPI_HolidayMaster      
    Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID      
       
    Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1      
    From DD_KPI_HolidayMaster      
    Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID      
      
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                      
    DECLARE  @MonthTarget money,  @YearTarget money ,  @DayTarget int;      
         
                      
    SET @YearLabelCount=12;                      
    SET @MonthLabelCount=Day(@MonthEnd); --@MonthWorkingDays;                      
    SET @DayLabelCount=24;                      
                      
    SET @YearTarget=360000000;                      
    SET @MonthTarget=@YearTarget/12.0;                      
    SET @DayTarget= (@MonthTarget*@CompletedDays)/@MonthWorkingDays; --1250000 ;                      
            
    DECLARE @YearPlan money, @YearPlanTillMonth money, @YearSales money,  @YearVarianceAllowed money, @YearVariance money,    
        @MonthPlan money, @MonthPlanTillDate money, @MonthSales money, @MonthVarianceAllowed money, @MonthVariance money,    
        @DayPlan money, @DayPlanTillNow money, @DaySales money, @DayVarianceAllowed money, @DayVariance money;    
            
    Select @YearTarget=TargetValue, @YearPlan=PlanValue, @YearPlanTillMonth=PlanTillPeriodValue, @YearSales=AchievedValue,                   
                @YearVarianceAllowed=AllowVariance, @YearVariance=Variance 
	From DD_KPI_GaugeChartData a                    
    Where a.ChartTypeId=@ChartTypeId and a.PeriodType='YR'    
		and a.AsOnDate=(Select Max(AsOnDate) From DD_KPI_GaugeChartData b     
    Where b.ChartTypeId=@ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate)           
             
     Select @MonthTarget=TargetValue, @MonthPlan=PlanValue, @MonthPlanTillDate=PlanTillPeriodValue, @MonthSales=AchievedValue,                   
                    @MonthVarianceAllowed=AllowVariance, @MonthVariance=Variance    
        From DD_KPI_GaugeChartData a                    
        Where a.ChartTypeId=@ChartTypeId and a.PeriodType='MN'    
      and a.AsOnDate=(Select Max(AsOnDate) From DD_KPI_GaugeChartData b     
        Where b.ChartTypeId=@ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate)           
             
     Select @DayTarget=TargetValue, @DayPlan=PlanValue, @DayPlanTillNow=PlanTillPeriodValue, @DaySales=AchievedValue,                   
                    @DayVarianceAllowed=AllowVariance, @DayVariance=Variance    
        From DD_KPI_GaugeChartData a                    
        Where a.ChartTypeId=@ChartTypeId and a.PeriodType='DY'    
      and a.AsOnDate=(Select Max(AsOnDate) From DD_KPI_GaugeChartData b     
        Where b.ChartTypeId=@ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate);             
          
    DECLARE @YearFirstBandStart money, @YearSecondBandStart money, @YearThirdBandStart money, @YearFourthBandStart money, @YearBandEnd money;   
	DECLARE @ActualLabelCount int, @LabelCountBasedOnDigit int, @RndOffAchievedValue int;
		SET @ActualLabelCount=10;

    IF @LabelSeries='PERIOD'
		BEGIN
			SELECT @YearFirstBandStart=0, @YearSecondBandStart=Convert(money, Case When @YearTarget<=0 Then 0 Else @YearLabelCount*((@YearPlanTillMonth-@YearVarianceAllowed)/@YearTarget) End),            
				@YearThirdBandStart=Convert(money, Case When @YearTarget<=0 Then 0 Else @YearLabelCount*(@YearPlanTillMonth/@YearTarget) End),            
				@YearFourthBandStart=Convert(money, Case When @YearTarget<=0 Then 0 Else @YearLabelCount*(@YearPlan/@YearTarget) End),            
				@YearBandEnd=@YearLabelCount;            
		END
	Else
		BEGIN
			IF (@YearTarget+@YearVarianceAllowed) > @YearSales
				BEGIN
					SELECT @LabelCountBasedOnDigit='1' + Case When Len(Convert(int,(@YearTarget+@YearVarianceAllowed)))=1 Then '0' 
															Else Convert(Varchar,replicate(0,Len(Convert(int,(@YearTarget+@YearVarianceAllowed))+1)-1)) End

					SELECT @RndOffAchievedValue=dbo.fn_RoundOff((@YearTarget+@YearVarianceAllowed)+1, @LabelCountBasedOnDigit, 0, 'U')  
				END
			ELSE
				BEGIN
					SELECT @LabelCountBasedOnDigit='1' + Case When Len(Convert(int,@YearSales))=1 Then '0' 
															Else Convert(Varchar,replicate(0,Len(Convert(int,@YearSales)+1)-1)) End

					SELECT @RndOffAchievedValue=dbo.fn_RoundOff(@YearSales+1, @LabelCountBasedOnDigit, 0, 'U')  
				END

			SELECT @YearFirstBandStart=0, @YearSecondBandStart=@YearTarget, @YearThirdBandStart=(@YearTarget+@YearVarianceAllowed),
					@YearBandEnd=@RndOffAchievedValue; 
								/*Case When (@YearTarget+@YearVarianceAllowed) > @YearSales Then  
											dbo.fn_RoundOff((@YearTarget+@YearVarianceAllowed)+1, 10, 0, 'U')
										Else  
											dbo.fn_RoundOff(@YearSales+1, 10, 0, 'U')  
										End;*/    

			SET @YearFourthBandStart=@YearBandEnd;
		END  
		      
    DECLARE @MonthFirstBandStart money, @MonthSecondBandStart money, @MonthThirdBandStart money, @MonthFourthBandStart money, @MonthBandEnd money;  
	IF @LabelSeries='PERIOD'   
		BEGIN     
			SELECT @MonthFirstBandStart=0, @MonthSecondBandStart=Convert(money, Case When @MonthTarget<=0 Then 0 Else @MonthLabelCount*((@MonthPlanTillDate-@MonthVarianceAllowed)/@MonthTarget) End),         
				@MonthThirdBandStart=Convert(money, Case When @MonthTarget<=0 Then 0 Else @MonthLabelCount*(@MonthPlanTillDate/@MonthTarget) End),            
				@MonthFourthBandStart=Convert(money, Case When @MonthTarget<=0 Then 0 Else @MonthLabelCount*(@MonthPlan/@MonthTarget) End),            
				@MonthBandEnd=@MonthLabelCount;            
		END
	ELSE
		BEGIN
			IF (@MonthTarget+@MonthVarianceAllowed) > @MonthSales 
				BEGIN
					SELECT @LabelCountBasedOnDigit='1' + Case When Len(Convert(int,(@MonthTarget+@MonthVarianceAllowed)))=1 Then '0' 
															Else Convert(Varchar,replicate(0,Len(Convert(int,(@MonthTarget+@MonthVarianceAllowed))+1)-1)) End
					
					SELECT @RndOffAchievedValue=dbo.fn_RoundOff((@MonthTarget+@MonthVarianceAllowed)+1, @LabelCountBasedOnDigit, 0, 'U') 

				END
			ELSE
				BEGIN
					SELECT @LabelCountBasedOnDigit='1' + Case When Len(Convert(int,@MonthSales))=1 Then '0' 
															Else Convert(Varchar,replicate(0,Len(Convert(int,@MonthSales)+1)-1)) End

					SELECT @RndOffAchievedValue=dbo.fn_RoundOff(@MonthSales+1, @LabelCountBasedOnDigit, 0, 'U')  
				END

			SELECT @MonthFirstBandStart=0, @MonthSecondBandStart=@MonthTarget, @MonthThirdBandStart=@MonthTarget+@MonthVarianceAllowed,
				@MonthBandEnd=@RndOffAchievedValue;
					/*Case When (@MonthTarget+@MonthVarianceAllowed) > @MonthSales Then  
									dbo.fn_RoundOff((@MonthTarget+@MonthVarianceAllowed)+1, 10, 0, 'U')
								Else  
									dbo.fn_RoundOff(@MonthSales+1, 10, 0, 'U')  
								End;  */             
     
			SET @MonthFourthBandStart=@MonthBandEnd;
		END
		    
    DECLARE @DayFirstBandStart money, @DaySecondBandStart money, @DayThirdBandStart money, @DayFourthBandStart money, @DayBandEnd money;   
	IF @LabelSeries='PERIOD'   
		BEGIN           
			SELECT @DayFirstBandStart=0, @DaySecondBandStart=Convert(money, Case When @DayTarget<=0 Then 0 Else @DayLabelCount*((@DayPlanTillNow-@DayVarianceAllowed)/@DayTarget) End),            
				@DayThirdBandStart=Convert(money, Case When @DayTarget<=0 Then 0 Else @DayLabelCount*(@DayPlanTillNow/@DayTarget) End),            
				@DayFourthBandStart=Convert(money, Case When @DayTarget<=0 Then 0 Else @DayLabelCount*(@DayPlan/@DayTarget) End),            
				@DayBandEnd=@DayLabelCount; 
		END
	ELSE
		BEGIN

			IF (@DayTarget+@DayVarianceAllowed) > @DaySales 
				BEGIN
					SELECT @LabelCountBasedOnDigit='1' + Case When Len(Convert(int,(@DayTarget+@DayVarianceAllowed)))=1 Then '0' 
															Else Convert(Varchar,replicate(0,Len(Convert(int,(@DayTarget+@DayVarianceAllowed))+1)-1)) End
					
					SELECT @RndOffAchievedValue=dbo.fn_RoundOff((@DayTarget+@DayVarianceAllowed)+1, @LabelCountBasedOnDigit, 0, 'U') 

				END
			ELSE
				BEGIN
					SELECT @LabelCountBasedOnDigit='1' + Case When Len(Convert(int,@DaySales))=1 Then '0' 
															Else Convert(Varchar,replicate(0,Len(Convert(int,@DaySales)+1)-1)) End

					SELECT @RndOffAchievedValue=dbo.fn_RoundOff(@DaySales+1, @LabelCountBasedOnDigit, 0, 'U')  
				END

			SELECT @DayFirstBandStart=0, @DaySecondBandStart=@DayTarget, @DayThirdBandStart=@DayTarget+@DayVarianceAllowed,                     
				@DayBandEnd=@RndOffAchievedValue;
				
					/*Case When (@DayTarget+@DayVarianceAllowed) > @DaySales Then  
								dbo.fn_RoundOff((@DayTarget+@DayVarianceAllowed)+1, 10, 0, 'U')
							Else  
								dbo.fn_RoundOff(@DaySales+1, 10, 0, 'U')  
							End; */
       
			SET @DayFourthBandStart=@DayBandEnd;
		END

    /* Adjustment for exceeding dial end */
    Select @YearSecondBandStart = Case When @YearSecondBandStart > @YearBandEnd Then @YearBandEnd Else @YearSecondBandStart End,
            @YearThirdBandStart = Case When @YearThirdBandStart > @YearBandEnd Then @YearBandEnd Else @YearThirdBandStart End,
            @YearFourthBandStart = Case When @YearFourthBandStart > @YearBandEnd Then @YearBandEnd Else @YearFourthBandStart End,
            @MonthSecondBandStart = Case When @MonthSecondBandStart > @MonthBandEnd Then @MonthBandEnd Else @MonthSecondBandStart End,
            @MonthThirdBandStart = Case When @MonthThirdBandStart > @MonthBandEnd Then @MonthBandEnd Else @MonthThirdBandStart End,
            @MonthFourthBandStart = Case When @MonthFourthBandStart > @MonthBandEnd Then @MonthBandEnd Else @MonthFourthBandStart End, 
            @DaySecondBandStart = Case When @DaySecondBandStart > @DayBandEnd Then @DayBandEnd Else @DaySecondBandStart End,
            @DayThirdBandStart = Case When @DayThirdBandStart > @DayBandEnd Then @DayBandEnd Else @DayThirdBandStart End,
            @DayFourthBandStart = Case When @DayFourthBandStart > @DayBandEnd Then @DayBandEnd Else @DayFourthBandStart End
     
	Declare @SegmentColor1 Varchar(15), @SegmentColor2 Varchar(15), @SegmentColor3 Varchar(15), @SegmentColor4 Varchar(15)
		Select @SegmentColor1=SegmentColor1, @SegmentColor2=SegmentColor2, @SegmentColor3=SegmentColor3, @SegmentColor4=SegmentColor4
		From DD_KPI_ChartMaster
		Where ChartTypeId=@ChartTypeId and BranchID=@BranchID and CompID=@CompID
	     
    Select 1 as SI_No,'Year' as  ChartType, @YearFirstBandStart as StartValue, @YearSecondBandStart as EndValue, @SegmentColor1 as ChartColor	--'red' as ChartColor            
    Union All                  
    Select 2 as SI_No,'Year' as  ChartType, @YearSecondBandStart as StartValue, @YearThirdBandStart as EndValue, @SegmentColor2 as ChartColor	--'yellow' as ChartColor            
    Union All                  
    Select 3 as SI_No,'Year' as  ChartType, @YearThirdBandStart as StartValue, @YearFourthBandStart as EndValue, @SegmentColor3 as ChartColor	--'green' as ChartColor            
    Union All                  
    Select 4 as SI_No,'Year' as  ChartType, @YearFourthBandStart as StartValue, @YearBandEnd as EndValue, @SegmentColor4 as ChartColor			--'blue' as ChartColor            
    Union All                      
            
    Select 5 as SI_No,'Month' as  ChartType, @MonthFirstBandStart as StartValue, @MonthSecondBandStart as EndValue, @SegmentColor1 as ChartColor          
    Union All                  
    Select 6 as SI_No,'Month' as  ChartType, @MonthSecondBandStart as StartValue, @MonthThirdBandStart as EndValue, @SegmentColor2 as ChartColor            
    Union All                  
    Select 7 as SI_No,'Month' as  ChartType, @MonthThirdBandStart as StartValue, @MonthFourthBandStart as EndValue, @SegmentColor3 as ChartColor
    Union All                  
    Select 8 as SI_No,'Month' as  ChartType, @MonthFourthBandStart as StartValue, @MonthBandEnd as EndValue, @SegmentColor4 as ChartColor          
    Union All                      
            
    Select 9 as SI_No,'Day' as  ChartType, @DayFirstBandStart as StartValue, @DaySecondBandStart as EndValue, @SegmentColor1 as ChartColor               
    Union All                    
    Select 10 as SI_No,'Day' as  ChartType, @DaySecondBandStart as StartValue, @DayThirdBandStart as EndValue, @SegmentColor2 as ChartColor                
    Union All                    
    Select 11 as SI_No,'Day' as  ChartType, @DayThirdBandStart as StartValue, @DayFourthBandStart as EndValue, @SegmentColor3 as ChartColor
    Union All                    
    Select 12 as SI_No,'Day' as  ChartType, @DayFourthBandStart as StartValue, @DayBandEnd as EndValue, @SegmentColor4 as ChartColor  
END



GO

