CREATE PROCEDURE  [dbo].[DD_KPI_Get_DeviceRequest]   
(  
@ApprovalStatus bit,  
@BranchID varchar(2) ,  
@CompID varchar(2)   
)  
AS  
BEGIN  
SET NOCOUNT ON;  
Select a.MacID,a.MacAddress,c.[Name],Convert(int,a.ApprovalStatus ) as ApprovalStatus
From DD_KPI_DeviceDetails a  
INNER JOIN DD_KPI_DeviceApproval_Request  b  
on a.MacID=b.MacID and a.BranchID=b.BranchID 
LEFT OUTER JOIN DD_KPI_UserCredentials c
ON c.UserID=b.UserID and c.BranchID=b.BranchID and c.CompID=b.CompID
 Where a.ApprovalStatus=@ApprovalStatus and a.BranchID=@BranchID and a.CompID=@CompID  
END
