/****** Object:  StoredProcedure [dbo].[DD_KPI_GrossProfit_ChartData_Ins]    Script Date: 17/06/2026 11:29:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_GrossProfit_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))    
/* Process Current Date, Current Month, Current Year Data from the original table if it is changed from last process            
    and all other data will be taken from already processed data */            
AS                            
BEGIN                        
    SET NOCOUNT ON;            
            
    DECLARE @ChartTypeId int, @ChartTypeIdSales int;            
  SET @ChartTypeId=23; /* From Table ChartTypeMaster */          
  SET @ChartTypeIdSales=1;          
             
    DECLARE @CurDate datetime;            
  SET @CurDate = getdate();                
                  
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */              
    DECLARE @ShiftStart datetime;              
  SELECT @ShiftStart=ShiftStart From vw_DD_KPI_ShiftStart;               
                    
    DECLARE @Finyear varchar(15);                        
                        
    /* Period Start End */                        
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                          
                  
    If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)              
  BEGIN              
   SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' ' + Convert(varchar(8), @ShiftStart, 108);                        
  END              
    Else              
  BEGIN              
   SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' ' + Convert(varchar(8), @ShiftStart, 108);                           
  END  
      
    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';              
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);                    
              
    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));              
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                          
                
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                        
  SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                                    
                 
    Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))            
    From DD_KPI_HolidayMaster            
    Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID            
                
    Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1            
    From DD_KPI_HolidayMaster            
    Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID            
          
    /*Select @CompletedDays=Count(*)  
    From  
    (  
        Select DateAdd(day,1,FromDate) +  ' ' + Convert(Varchar(8), @ShiftStart,108)  as DayEnd, *   
        From fn_COM_PeriodSplit(@MonthStart, Convert(varchar(10),@DayStart,120), 'D', '', 0, '0') a  
        Where Not Exists  
        (  
            Select *  
            From DD_KPI_HolidayMaster s  
            Where s.HolidayDate=a.FromDate and s.BranchID=@BranchID and s.CompID=@CompID  
        )  
    )a  
    Where DayEnd<=@AsOnDate*/  
               
 DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                            
 DECLARE  @MonthTarget money,  @YearTarget money ,  @DayTarget int;                            
                            
    SET @YearLabelCount=12;    /* No. of months in a Year */                        
    SET @MonthLabelCount=@MonthWorkingDays;                         
    SET @DayLabelCount=@TotalShiftHours;        
            
    DECLARE @ProfitPerc decimal(3, 2);        
  --SET @ProfitPerc=10.0/100.0;        
  SET @ProfitPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'Target','YR',@BranchID,@CompID);  
  
                            
    DECLARE @AsOnDateWithoutTime datetime;      
  SET @AsOnDateWithoutTime=Convert(varchar(10), @AsOnDate, 120);      
          
    DECLARE @YearPlan money, @YearPlanTillMonth money, @YearAchieved money, @YearVarianceAllowedPerc decimal(5, 2), @YearVarianceAllowed money,                           
        @MonthPlan money, @MonthPlanTillDate money, @MonthAchieved int, @MonthVarianceAllowedPerc decimal(5, 2), @MonthVarianceAllowed money,                           
        @DayPlan money, @DayPlanTillNow money, @DayAchieved money, @DayVarianceAllowedPerc decimal(5, 2), @DayVarianceAllowed money;         
        
        
    DECLARE @Sales_Tbl TABLE (PeriodType varchar(2), TargetValue money, PlanValue money, AchievedValue money, AllowVariance money);        
 Insert into @Sales_Tbl        
  Select PeriodType, TargetValue, PlanValue, AchievedValue, AllowVariance        
  From DD_KPI_GaugeChartData a        
  Where a.ChartTypeId=@ChartTypeIdSales        
   and a.BranchID=@BranchID and a.CompID=@CompID        
   and a.AsOnDate=(Select Max(b.AsOnDate) From DD_KPI_GaugeChartData b         
       Where b.ChartTypeId=a.ChartTypeId and b.AsOnDate<=@AsOnDate        
        and b.BranchID=a.BranchID and b.CompID=a.CompID        
       )        
                
    Select @YearTarget=TargetValue*@ProfitPerc, @YearPlan=PlanValue*@ProfitPerc, @YearPlanTillMonth=AchievedValue*@ProfitPerc,        
            @YearVarianceAllowed=AllowVariance*@ProfitPerc        
    From @Sales_Tbl a        
    Where a.PeriodType='YR'        
        
    Select @MonthTarget=TargetValue*@ProfitPerc, @MonthPlan=PlanValue*@ProfitPerc, @MonthPlanTillDate=AchievedValue*@ProfitPerc,        
            @MonthVarianceAllowed=AllowVariance*@ProfitPerc        
    From @Sales_Tbl a        
    Where a.PeriodType='MN'    
        
    Select @DayTarget=TargetValue*@ProfitPerc, @DayPlan=PlanValue*@ProfitPerc, @DayPlanTillNow=AchievedValue*@ProfitPerc,        
            @DayVarianceAllowed=AllowVariance*@ProfitPerc        
    From @Sales_Tbl a        
    Where a.PeriodType='DY'    
       
    /*    
    Select @DayTarget=(@MonthTarget*@ProfitPerc/@MonthWorkingDays), @DayPlan=(@MonthPlan*@ProfitPerc/@MonthWorkingDays),       
            @DayPlanTillNow=Sum(InvoiceQty*Rate)*@ProfitPerc,  @DayVarianceAllowed=(@MonthVarianceAllowed*@ProfitPerc/@MonthWorkingDays)      
    From SalesInvoice a        
    Where a.InvoiceDate=@AsOnDateWithoutTime and a.Branchid=@BranchID and a.Compid=@CompID       
    */    
  
    DECLARE @CmCode varchar(12);        
  SET @CmCode=@CompId+@BranchId;        
        
    /* Day */        
    --Select @DayAchieved=-isNull(dbo.fn_FAS_Profit_Loss_Period_Gross(@AsOnDateWithoutTime, @AsOnDateWithoutTime, @CmCode), 0);    
    Select @DayAchieved=-isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId, '', @AsOnDateWithoutTime, @AsOnDateWithoutTime, @CmCode), 0);    
  
    /* Month */      
    --Select @MonthAchieved=-isNull(dbo.fn_FAS_Profit_Loss_Period_Gross(@MonthStart, @AsOnDateWithoutTime, @CmCode), 0);             
    Select @MonthAchieved=-isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId,  '', @MonthStart, @AsOnDateWithoutTime, @CmCode), 0);  
      
    /* Year */      
    --Select @YearAchieved=-isNull(dbo.fn_FAS_Profit_Loss_Period_Gross(@YearStart, @AsOnDateWithoutTime, @CmCode), 0);        
    Select @YearAchieved=-isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId,  '', @YearStart, @AsOnDateWithoutTime, @CmCode), 0);        
            
                
 If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate)                      
  Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate            
            
 Insert into DD_KPI_GaugeChartData            
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, 'DY' as PeriodType, isNull(@DayTarget, 0) as TargetValue, isNull(@DayPlan, 0) as PlanValue,          
   isNull(@DayPlanTillNow, 0) as PlanTillPeriodValue, isNull(@DayAchieved, 0) as AchievedValue,           
   isNull(@DayAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.          
   isNull(@DayVarianceAllowed, 0) as AllowVariance,              
   isNull((@DayPlanTillNow-@DayAchieved), 0) as Variance,            
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp            
              
  Union All            
                
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, 'MN' as PeriodType, isNull(@MonthTarget, 0) as TargetValue,             
   isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthPlanTillDate, 0) as PlanTillPeriodValue, isNull(@MonthAchieved, 0) as AchievedValue,           
   isNull(@MonthAchieved, 0) as AchievedValue2, -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.          
   isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthPlanTillDate-@MonthAchieved), 0) as Variance, @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp            
            
  Union All            
                
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, 'YR' as PeriodType, isNull(@YearTarget, 0) as TargetValue,             
   isNull(@YearPlan, 0) as PlanValue, isNull(@YearPlanTillMonth, 0) as PlanTillPeriodValue, isNull(@YearAchieved, 0) as AchievedValue,           
   isNull(@YearAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.          
   isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearPlanTillMonth-@YearAchieved), 0) as Variance, @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp                      
END
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_GuageChart_LabelSeries_Get]    Script Date: 17/06/2026 11:29:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[DD_KPI_GuageChart_LabelSeries_Get](@ChartTypeId int, @AsOnDate Datetime, @BranchID int, @CompID int)                          
AS                          
BEGIN                          
    SET NOCOUNT ON;              
          
    DECLARE @MonthEnd datetime;          
    SELECT @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, Convert(datetime, Convert(varchar(7), @AsOnDate, 120) + '-01', 120)));          
              
    DECLARE @MonthCount decimal(3,1), @DayCount decimal(3,1), @HourCount decimal(3,1);              
    SET @MonthCount=12.0; /* Fixed. So Hard Coded */              
    SET @DayCount=Day(@MonthEnd);   /* It should be calculated as Month Working Days */              
    SET @HourCount=24.0;  /* It should be calculated from Per day production shift hours total */              
      
       
   DECLARE  @YearLabelCount int, @MonthLabelCount int, @DayLabelCount int;      
    Select @YearLabelCount=Case When a.PlanValue=0 then 0 Else CAST(@MonthCount * a.TargetValue / a.PlanValue AS INT) End
    From DD_KPI_GaugeChartData a                
    Where a.ChartTypeId=@ChartTypeId and a.PeriodType='YR'
		and a.AsOnDate=(Select Max(AsOnDate) From DD_KPI_GaugeChartData b 
				Where b.ChartTypeId=@ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate)       
         
	Select @MonthLabelCount=Case When a.PlanValue=0 Then 0 Else CAST(@DayCount * a.TargetValue / a.PlanValue AS INT) End
    From DD_KPI_GaugeChartData a                
    Where a.ChartTypeId=@ChartTypeId and a.PeriodType='MN'
		and a.AsOnDate=(Select Max(AsOnDate) From DD_KPI_GaugeChartData b 
				Where b.ChartTypeId=@ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate)       
         
	Select @DayLabelCount=Case When a.PlanValue=0 Then 0 Else CAST(@HourCount * a.TargetValue / a.PlanValue AS INT) End  
    From DD_KPI_GaugeChartData a                
    Where a.ChartTypeId=@ChartTypeId and a.PeriodType='DY'
	and a.AsOnDate=(Select Max(AsOnDate) From DD_KPI_GaugeChartData b Where b.ChartTypeId=@ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate)       
         
		      
    DECLARE @MonthStart int, @DayStart int, @HourStart int;              
    SET @MonthStart=4;  /* Generally it is always for Financial Year. So 4 for April */              
    SET @DayStart=1;    /* Generally it always start from Day 1. So Hard Coded */              
    SET @HourStart=6;   /* It should be come from Shift Master Day First Shift Start Time */              
              
    Select Convert(varchar(20), Convert(int, @YearLabelCount+1)) as YearSeries, 
		Convert(varchar(20), Convert(int, @MonthLabelCount+1)) as MonthSeries, 
		Convert(varchar(20), Convert(int, @DayLabelCount+1)) as DaySeries              
    UNION ALL      
    Select Case When YearSeq > @MonthCount+1 Then '' Else YearSeries End as YearSeries,      
        Case When MonthSeq > @DayCount+1 Then '' Else MonthSeries End as MonthSeries,      
        Case When DaySeq > @HourCount+1 Then '' Else DaySeries End as DaySeries      
    From      
    (      
    Select c.SeqNo as YearSeq, isNull(CAST(Convert(int, c.SeriesValue)as varchar), '') as YearSeries,       
        b.SeqNo as MonthSeq, isNull(CAST(Convert(int, b.SeriesValue)as varchar), '') as MonthSeries,       
        a.SeqNo as DaySeq, isNull(CAST(Convert(int, a.SeriesValue )as varchar),'') as DaySeries               
    From fn_COM_Get_NumberSeries(1, @HourCount, 1, @HourStart,1) a              
    FULL OUTER JOIN fn_COM_Get_NumberSeries(1, @DayCount, 1, @DayStart,1) b              
        On a.SeqNo=b.SeqNo              
    FULL OUTER JOIN fn_COM_Get_NumberSeries(1, @MonthCount, 1, @MonthStart,1) c              
        On a.SeqNo=c.SeqNo        
    ) m            
END      
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_IndirectExpenses_ChartData_Ins]    Script Date: 17/06/2026 11:29:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_IndirectExpenses_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))        
/* Process Current Date, Current Month, Current Year Data from the original table if it is changed from last process      
    and all other data will be taken from already processed data */      
AS                      
BEGIN                  
    SET NOCOUNT ON;      
      
 DECLARE @ChartTypeId int, @ChartTypeIdSalesContribution int, @ChartTypeIdNetProfit int;           
  SELECT @ChartTypeId=20, @ChartTypeIdSalesContribution=2, @ChartTypeIdNetProfit=3;  
  
 DECLARE @CurDate datetime;      
  SET @CurDate = getdate();          
            
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */        
    DECLARE @ShiftStart datetime;        
  SELECT @ShiftStart=ShiftStart From vw_DD_KPI_ShiftStart;    
              
    DECLARE @Finyear varchar(15);                  
                  
    /* Period Start End */                  
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                    
            
    If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)        
  BEGIN        
   SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' ' + Convert(varchar(8), @ShiftStart, 108);              
  END        
    Else        
  BEGIN        
   SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' ' + Convert(varchar(8), @ShiftStart, 108);                
  END  
  
    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';      
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);  
  
    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));        
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                    
          
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                  
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                              
           
    Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))      
    From DD_KPI_HolidayMaster      
    Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID      
          
    Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1      
    From DD_KPI_HolidayMaster      
    Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID      
      
    /*Select @CompletedDays=Count(*)  
    From  
    (  
        Select DateAdd(day,1,FromDate) +  ' ' + Convert(Varchar(8), @ShiftStart,108)  as DayEnd, *   
        From fn_COM_PeriodSplit(@MonthStart, Convert(varchar(10),@DayStart,120), 'D', '', 0, '0') a  
        Where Not Exists  
        (  
            Select *  
            From DD_KPI_HolidayMaster s  
            Where s.HolidayDate=a.FromDate and s.BranchID=@BranchID and s.CompID=@CompID  
        )  
    )a  
    Where DayEnd<=@AsOnDate*/  
             
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                                      
  SET @YearLabelCount=12;    /* No. of months in a Year */                  
  SET @MonthLabelCount=@MonthWorkingDays;                   
  SET @DayLabelCount=@TotalShiftHours;                      
      
 DECLARE @YearPeriodType Char(2), @MonthPeriodType Char(2), @DayPeriodType Char(2)  
  SELECT @YearPeriodType='YR', @MonthPeriodType='MN', @DayPeriodType='DY'  
                             
 DECLARE @YearTarget money, @YearPlan money, @YearPlanTillMonth money, @YearAchieved money, @YearVarianceAllowedPerc decimal(5, 2), @YearVarianceAllowed money,                     
   @MonthTarget money, @MonthPlan money, @MonthPlanTillDate money, @MonthAchieved money, @MonthVarianceAllowedPerc decimal(5, 2), @MonthVarianceAllowed money,                     
   @DayTarget money, @DayPlan money, @DayPlanTillNow money, @DayAchieved money, @DayVarianceAllowedPerc decimal(5, 2), @DayVarianceAllowed money;        
      
 /* Get Allowed Variance Perc */                       
 SELECT @YearVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@YearPeriodType,@BranchID,@CompID),   
   @MonthVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@MonthPeriodType,@BranchID,@CompID),   
   @DayVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@DayPeriodType,@BranchID,@CompID);  
  
     DECLARE @AsOnDateWithoutTime datetime;      
  SET @AsOnDateWithoutTime=Convert(varchar(10), @AsOnDate, 120);      
  
 /***************************** Sales Contribution *****************************/     
    DECLARE @SalesContribution_Tbl TABLE (ContributionPeriodType varchar(2), ContributionTargetValue money, ContributionPlanValue money, ContributionPlanTillPeriodValue money);          
    Insert into @SalesContribution_Tbl          
        Select PeriodType, TargetValue, PlanValue,  PlanTillPeriodValue        
        From DD_KPI_GaugeChartData a          
        Where a.ChartTypeId=@ChartTypeIdSalesContribution          
            and a.BranchID=@BranchID and a.CompID=@CompID          
   and a.AsOnDate=(Select Max(b.AsOnDate) From DD_KPI_GaugeChartData b           
                            Where b.ChartTypeId=a.ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate          
                                and b.BranchID=a.BranchID and b.CompID=a.CompID          
                            )          
   
 /***************************** Net Profit *****************************/     
 DECLARE @NetProfit_Tbl TABLE (NetProfitPeriodType varchar(2), NetProfitTargetValue money, NetProfitPlanValue money, NetProfitPlanTillPeriodValue money);          
    Insert into @NetProfit_Tbl          
        Select PeriodType, TargetValue, PlanValue,  PlanTillPeriodValue        
        From DD_KPI_GaugeChartData a          
        Where a.ChartTypeId=@ChartTypeIdNetProfit        
            and a.BranchID=@BranchID and a.CompID=@CompID          
   and a.AsOnDate=(Select Max(b.AsOnDate) From DD_KPI_GaugeChartData b           
                            Where b.ChartTypeId=a.ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate          
                                and b.BranchID=a.BranchID and b.CompID=a.CompID          
                            )         
   
 /* Year */  
 Select @YearTarget=(IsNull(ContributionTargetValue,0)-IsNull(NetProfitTargetValue,0)), @YearPlan=IsNull(ContributionPlanValue,0)-IsNull(NetProfitPlanValue,0)  
   --@YearPlanTillMonth=IsNull(ContributionPlanTillPeriodValue,0)-IsNull(NetProfitPlanTillPeriodValue,0)  
 From  @SalesContribution_Tbl a  
 Left Outer Join @NetProfit_Tbl b  
  On a.ContributionPeriodType=b.NetProfitPeriodType   
 Where a.ContributionPeriodType=@YearPeriodType             
    
 SET @YearPlanTillMonth=IsNull((@YearPlan/12.0) * (DateDiff(m,@YearStart,DateAdd(day, -1,@MonthStart))),0)  
    
 /* Month */  
 Select @MonthTarget=(IsNull(ContributionTargetValue,0)-IsNull(NetProfitTargetValue,0)), @MonthPlan=IsNull(ContributionPlanValue,0)-IsNull(NetProfitPlanValue,0)  
   --@MonthPlanTillDate=IsNull(ContributionPlanTillPeriodValue,0)-IsNull(NetProfitPlanTillPeriodValue,0)  
 From  @SalesContribution_Tbl a  
 Left Outer Join @NetProfit_Tbl b  
  On a.ContributionPeriodType=b.NetProfitPeriodType   
 Where a.ContributionPeriodType=@MonthPeriodType             
    
 SET @MonthPlanTillDate=IsNull((@MonthPlan*@CompletedDays)/@MonthWorkingDays,0)  
    
 /* Day */  
 Select @DayTarget=(IsNull(ContributionTargetValue,0)-IsNull(NetProfitTargetValue,0)), @DayPlan=IsNull(ContributionPlanValue,0)-IsNull(NetProfitPlanValue,0)  
   --@DayPlanTillNow=IsNull(ContributionPlanTillPeriodValue,0)-IsNull(NetProfitPlanTillPeriodValue,0)  
 From  @SalesContribution_Tbl a  
 Left Outer Join @NetProfit_Tbl b  
  On a.ContributionPeriodType=b.NetProfitPeriodType   
 Where a.ContributionPeriodType=@DayPeriodType   
    
 /* Since Hourly Plan not available DayPlanTillNow calculated on prorate basis */                  
 SET @DayPlanTillNow=IsNull((@DayPlan * DateDiff(minute, @DayStart, @AsOnDate))/DateDiff(minute, @DayStart, @DayEnd),0)   
        
 /***************************** InDirect Expense Amount From FAS *****************************/            
   
    /*  
    DECLARE @ExpenseAmount_Tbl TABLE (DocDate datetime, ExpenseAmount money)     
 Insert into @ExpenseAmount_Tbl    
  Select DocDate, Sum(DrAmt-CrAmt) as PurAmount  
  From FAS_VoucherTranSub a  
  Inner Join FAS_LedgerMaster_AuthTbl b  
   On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode  
  Where Left(b.LrRoute,2) in ('07') and a.DocDate between @YearStart and Convert(Varchar(10),@AsOnDate,121) and a.CompCode=(@CompID+@BranchID)  
  Group by DocDate  
  
 /* Day Expense Amount */       
 Select @DayAchieved=Sum(ExpenseAmount)  
 From @ExpenseAmount_Tbl a  
 Where DocDate between Convert(Varchar(10),@DayStart,121) and  Convert(Varchar(10),@AsOnDate,121)  
   
 /* Month Expense Amount */       
 Select @MonthAchieved=Sum(ExpenseAmount)  
 From @ExpenseAmount_Tbl a  
 Where DocDate between @MonthStart and Convert(Varchar(10),@AsOnDate,121)  
   
 /* Year Expense Amount */       
 Select @YearAchieved=Sum(ExpenseAmount)  
 From @ExpenseAmount_Tbl a  
 Where DocDate between @YearStart and Convert(Varchar(10),@AsOnDate,121)  
    */  
  
    /* Day */        
    Select @DayAchieved=isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId, '07', @AsOnDateWithoutTime, @AsOnDateWithoutTime, (@CompID+@BranchID)), 0);    
      
    /* Month */      
    Select @MonthAchieved=isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId, '07', @MonthStart, @AsOnDateWithoutTime, (@CompID+@BranchID)), 0);       
      
    /* Year */      
    Select @YearAchieved=isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId, '07', @YearStart, @AsOnDateWithoutTime, (@CompID+@BranchID)), 0);     
    /***********************************************************************************************************************************/           
    /* Allowed Variance */                
 Select @YearVarianceAllowed=@YearVarianceAllowedPerc*@YearPlanTillMonth,                
   @MonthVarianceAllowed=@MonthVarianceAllowedPerc*@MonthPlanTillDate,          
   @DayVarianceAllowed=@DayVarianceAllowedPerc*@DayPlanTillNow        
                 
 If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate)                
  Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate      
      
 Insert into DD_KPI_GaugeChartData      
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @DayPeriodType as PeriodType, isNull(@DayTarget, 0) as TargetValue,   
   isNull(@DayPlan, 0) as PlanValue, isNull(@DayPlanTillNow, 0) as PlanTillPeriodValue, isNull(@DayAchieved, 0) as AchievedValue,     
   isNull(@DayAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.    
   isNull(@DayVarianceAllowed, 0) as AllowVariance, isNull((@DayPlanTillNow-@DayAchieved), 0) as Variance,      
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp      
        
  Union All      
          
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @MonthPeriodType as PeriodType, isNull(@MonthTarget, 0) as TargetValue,       
   isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthPlanTillDate, 0) as PlanTillPeriodValue, isNull(@MonthAchieved, 0) as AchievedValue,     
   isNull(@MonthAchieved, 0) as AchievedValue2, -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.    
   isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthPlanTillDate-@MonthAchieved), 0) as Variance,   
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp      
      
  Union All      
          
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, isNull(@YearTarget, 0) as TargetValue,       
   isNull(@YearPlan, 0) as PlanValue, isNull(@YearPlanTillMonth, 0) as PlanTillPeriodValue, isNull(@YearAchieved, 0) as AchievedValue,     
   isNull(@YearAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.    
   isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearPlanTillMonth-@YearAchieved), 0) as Variance,   
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp      
END      
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_ProductionContributionValue_ChartData_Ins]    Script Date: 17/06/2026 11:29:56 ******/
SET ANSI_NULLS ON
GO

