GO

CREATE PROCEDURE [dbo].[DD_KPI_ProductionContributionValue_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))            
AS                          
BEGIN                      
    SET NOCOUNT ON;                
      
 DECLARE @ChartTypeId int, @ChartTypeIdProductionValue int;            
  SET @ChartTypeId=17; /* From Table ChartTypeMaster */                  
  SET @ChartTypeIdProductionValue = 14;          
          
 DECLARE @CurDate datetime          
  Select @CurDate = getdate();          
                
 /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */            
 DECLARE @ShiftStart datetime;            
  SET @ShiftStart='06:00';            
                   
 DECLARE @Finyear varchar(15);                      
                      
 /* Period Start End */                      
 DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                        
                
 If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)            
  BEGIN            
   SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' 06:00';             
  END            
 Else            
  BEGIN            
   SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' 06:00';            
  END            
        
    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';            
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);         
            
 SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));            
 SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                   
            
 DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                    
 SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                              
               
 Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))            
 From DD_KPI_HolidayMaster            
 Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID           
            
 Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1            
 From DD_KPI_HolidayMaster            
 Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID            
          
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                        
    DECLARE  @MonthTarget money,  @YearTarget money ,  @DayTarget money;                        
                        
    SET @YearLabelCount=12;    /* No. of months in a Year */                    
    SET @MonthLabelCount=@MonthWorkingDays;                     
    SET @DayLabelCount=@TotalShiftHours;                        
                                  
 DECLARE @YearPlan money, @YearPlanTillMonth money, @YearAchieved money, @YearVarianceAllowedPerc decimal(5, 2), @YearVarianceAllowed money,                       
  @MonthPlan money, @MonthPlanTillDate money, @MonthAchieved money, @MonthVarianceAllowedPerc decimal(5, 2), @MonthVarianceAllowed money,                       
  @DayPlan money, @DayPlanTillNow money, @DayAchieved money, @DayVarianceAllowedPerc decimal(5, 2), @DayVarianceAllowed money;                      
              
 DECLARE @YearPeriodType Char(2), @MonthPeriodType Char(2), @DayPeriodType Char(2)        
  SELECT @YearPeriodType='YR', @MonthPeriodType='MN', @DayPeriodType='DY'        
                  
 SELECT @YearVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@YearPeriodType,@BranchID,@CompID),         
  @MonthVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@MonthPeriodType,@BranchID,@CompID),         
  @DayVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@DayPeriodType,@BranchID,@CompID)        
             
 /* Production Plan List */              
 DECLARE @ProductionPlan_Tbl TABLE (PlanFor int, PlanPeriod datetime, ItemCode varchar(20), PlanQty money);        
 Insert into @ProductionPlan_Tbl              
  Select PlanFor, PlanPeriod, ItemCode, PlanQty              
  From fn_PPC_ProductionPlan_Dtl_v2(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear)              
  Where PlanFor=2 and PlanPeriod Between @MonthStart and @MonthEnd            
               
 /* Raw Material Cost & Norms */              
 DECLARE @ItemRMList TABLE (ItemCode varchar(20), RMRate money);              
 ;WITH Child_CTE              
 AS              
 (              
  Select distinct d.ItemCode, Case When d.ChildCode='' Then c.ItemCode Else d.ChildCode End as ChildCode,              
   Case When d.ChildCode='' Then c.PQty Else 1 End as RMNorms                
  From               
  (              
   Select ItemCode, '' as ChildCode /* Case When (ItemCode = '20520150T0' and PlanPeriod >= '2017-07-01') Then ItemCode Else '' End as ChildCode */    
   From @ProductionPlan_Tbl                
  ) d              
  Outer Apply fn_BOM_ExplodableItems(d.ItemCode,'C',@BranchID,@CompID)c             
 --  On d.ItemCode=c.ProductCode and c.ItemType='C' and c.BranchID=@BranchID and c.CompID=@CompID                       
 )              
 , ChildRate_CTE              
 AS              
 (              
  Select ChildCode, dbo.fn_COM_ItemRate_Pur(m.ChildCode, 3, @YearStart, @AsOnDate, 0, @AsonDate, @AsonDate, @BranchId, @CompId, @FinYear) as RMRate              
  From              
   (              
    Select distinct ChildCode             
    From Child_CTE              
   ) m              
 )              
              
 INSERT INTO @ItemRMList              
  Select j.ItemCode, SUM(IsNull(j.RMNorms,0)*IsNull(k.RMRate,0))              
  From Child_CTE j              
  Left Outer Join ChildRate_CTE k              
   On j.ChildCode=k.ChildCode              
  Group By j.ItemCode              
          
 DECLARE @PlanItemRM TABLE (ItemCode varchar(20), PlanQty money, RMRate money);              
  INSERT INTO @PlanItemRM        
   Select a.ItemCode, Sum(a.PlanQty) as PlanQty, b.RMRate                      
   From @ProductionPlan_Tbl a               
   Left Outer Join  @ItemRMList b               
    On a.ItemCode=b.ItemCode                     
   Where (a.PlanPeriod between @MonthStart and @MonthEnd)                                     
   Group by a.ItemCode, b.RMRate      
      
      
 /* Month Achieved */       
 Select @MonthPlan=Sum(PlanQty*(Rate-RMRate)),               
  @MonthPlanTillDate=Sum(PlanQtyTillDate*(Rate-RMRate)),               
  @MonthAchieved=Sum(InwardGoodsReceiptQty*(Rate-RMRate))                         
 From                      
 (                      
  Select a.ItemCode, IsNull((a.PlanQty*@CompletedDays)/@MonthWorkingDays,0) as PlanQtyTillDate,       
   IsNull(a.PlanQty,0) as PlanQty, IsNull(b.InwardGoodsReceiptQty,0) as InwardGoodsReceiptQty,            
   IsNull(dbo.fn_SAL_Item_Rate(a.ItemCode, 0, '', 0, Null,@BranchID, @CompID, @Finyear),0)as Rate,               
   IsNull(a.RMRate,0) as RMRate      
  From @PlanItemRM a                     
  Outer Apply       
   (      
    Select Sum(o.InwardGoodsReceiptQty) as InwardGoodsReceiptQty      
    From PPC_InwardGoodsReceipt o      
    Where o.Transtamp between @MonthStart and @AsOnDate and o.BranchId=@BranchId and o.CompId=@CompId      
     and Exists      
      (      
       Select Distinct pw.ProcessWorkOrderType As WOType, pw.ProcessWorkOrderNo As WONo, pw.ProcessWorkOrderDate As WODate,      
         pw.ToStageCode As ItemCode, pw.FromStageCode, pw.ToStageCode As StageCode, pw.ParentCode,      
         pw.BranchID, pw.CompID, pw.Finyear      
       From PPC_ProcessWorkOrder pw                  
       Where pw.ParentCode=a.ItemCode and pw.ToStageCode=o.ItemCode and pw.ProcessWorkOrderType=o.WorkOrderType       
        and pw.ProcessWorkOrderNo=o.WorkOrderNo and pw.ProcessWorkOrderDate=o.WorkOrderDate          
        and pw.BranchID=o.BranchID and pw.CompID=o.CompID      
                       
       UNION ALL                  
                     
       Select Distinct  aw.AssemblyWorkOrderType As WOType, aw.AssemblyWorkOrderNo As WONo, aw.AssemblyWorkOrderDate As WODate,      
         aw.ParentCode As ItemCode, aw.ItemCode As FromStageCode, aw.ItemCode As StageCode,        
         aw.ParentCode, aw.BranchID, aw.CompID, aw.Finyear                  
       From dbo.fn_PPC_AssemblyWorkOrder(@BranchID, @CompID) aw              
       Where /*aw.ParentCode=a.ItemCode and */ aw.ParentCode=o.ItemCode      
        and aw.AssemblyWorkOrderType=o.WorkOrderType and aw.AssemblyWorkOrderNo=o.WorkOrderNo and aw.AssemblyWorkOrderDate=o.WorkOrderDate      
        and aw.ParentCode in (Select StageCode From dbo.fn_BOM_Get_MPSMaster('A', @AsOnDate, @AsOnDate, @BranchID, @CompID) mp                                                
               Where mp.Itemcode=a.Itemcode)            
       UNION ALL                  
                     
       Select Distinct rw.ReworkOrderType As WOType, rw.ReworkOrderNo As WONo, rw.ReworkOrderDate As WODate,      
           rw.StageCode As ItemCode, rw.StageCode As FromStageCode, rw.StageCode,      
           rw.StageCode As ParentCode, rw.BranchID, rw.CompID, rw.Finyear          
       From dbo.fn_PPC_ReWorkOrder(@BranchID, @CompID) rw                  
       Where rw.StageCode=a.ItemCode and rw.StageCode=o.ItemCode       
        and rw.ReworkOrderType=o.WorkOrderType and rw.ReworkOrderNo=o.WorkOrderNo and rw.ReworkOrderDate=o.WorkOrderDate      
             
      )      
   )b               
 )a        
      
 /* Day Achieved */       
 Select @DayPlan=(@MonthPlan/@MonthWorkingDays),               
  @DayAchieved=Sum(InwardGoodsReceiptQty*(Rate-RMRate))                         
 From                      
 (                      
  Select a.ItemCode, IsNull(a.PlanQty,0) as PlanQty, IsNull(b.InwardGoodsReceiptQty,0) as InwardGoodsReceiptQty,            
   IsNull(dbo.fn_SAL_Item_Rate(a.ItemCode, 0, '', 0, Null, @BranchID, @CompID, @Finyear),0)as Rate,               
   IsNull(a.RMRate,0) as RMRate      
  From @PlanItemRM a                     
  Outer Apply       
   (      
    Select Sum(o.InwardGoodsReceiptQty) as InwardGoodsReceiptQty      
    From PPC_InwardGoodsReceipt o      
    Where o.Transtamp between @DayStart and @AsOnDate and o.BranchId=@BranchId and o.CompId=@CompId      
     and Exists      
      (      
       Select Distinct pw.ProcessWorkOrderType As WOType, pw.ProcessWorkOrderNo As WONo, pw.ProcessWorkOrderDate As WODate,      
         pw.ToStageCode As ItemCode, pw.FromStageCode, pw.ToStageCode As StageCode, pw.ParentCode,      
         pw.BranchID, pw.CompID, pw.Finyear      
       From PPC_ProcessWorkOrder pw                  
       Where pw.ParentCode=a.ItemCode and pw.ToStageCode=o.ItemCode and pw.ProcessWorkOrderType=o.WorkOrderType       
        and pw.ProcessWorkOrderNo=o.WorkOrderNo and pw.ProcessWorkOrderDate=o.WorkOrderDate          
        and pw.BranchID=o.BranchID and pw.CompID=o.CompID      
                       
       UNION ALL                  
                     
       Select Distinct  aw.AssemblyWorkOrderType As WOType, aw.AssemblyWorkOrderNo As WONo, aw.AssemblyWorkOrderDate As WODate,      
         aw.ParentCode As ItemCode, aw.ItemCode As FromStageCode, aw.ItemCode As StageCode,        
         aw.ParentCode, aw.BranchID, aw.CompID, aw.Finyear                  
       From dbo.fn_PPC_AssemblyWorkOrder(@BranchID, @CompID) aw              
       Where /*aw.ParentCode=a.ItemCode and */ aw.ParentCode=o.ItemCode      
        and aw.AssemblyWorkOrderType=o.WorkOrderType and aw.AssemblyWorkOrderNo=o.WorkOrderNo and aw.AssemblyWorkOrderDate=o.WorkOrderDate      
        and aw.ParentCode in (Select StageCode From dbo.fn_BOM_Get_MPSMaster('A', @AsOnDate, @AsOnDate, @BranchID, @CompID) mp                                                
               Where mp.Itemcode=a.Itemcode)            
       UNION ALL                  
                     
       Select Distinct rw.ReworkOrderType As WOType, rw.ReworkOrderNo As WONo, rw.ReworkOrderDate As WODate,      
           rw.StageCode As ItemCode, rw.StageCode As FromStageCode, rw.StageCode,      
           rw.StageCode As ParentCode, rw.BranchID, rw.CompID, rw.Finyear          
       From dbo.fn_PPC_ReWorkOrder(@BranchID, @CompID) rw                  
       Where rw.StageCode=a.ItemCode and rw.StageCode=o.ItemCode       
        and rw.ReworkOrderType=o.WorkOrderType and rw.ReworkOrderNo=o.WorkOrderNo and rw.ReworkOrderDate=o.WorkOrderDate      
             
      )      
   )b               
 )a        
      
 /* Since Hourly Plan not available DayPlanTillNow calculated on prorate basis */                        
    SET @DayPlanTillNow=(@DayPlan * DateDiff(minute, @DayStart, @AsOnDate))/DateDiff(minute, @DayStart, @DayEnd)               
          
 /* Year Achieved */             
 Select @YearPlan=Sum(YearPlan),  @YearPlanTillMonth=Sum(YearPlanTillMonth), @YearAchieved=Sum(YearAchieved)            
 From            
 (            
  Select @MonthPlan as YearPlan,  @MonthPlanTillDate as YearPlanTillMonth,  @MonthAchieved as YearAchieved           
                
  Union All            
            
  /* Year Sales (From Digital Data Table) */            
  Select IsNull(Sum(PlanValue),0) as YearPlanValue,          
   IsNull(Sum(PlanValue),0) as YearPlanTillValue, IsNull(Sum(AchievedValue),0) as YearAchievedValue            
  From DD_KPI_GaugeChartData a            
  Inner Join                 
   (          
    Select Convert(Varchar(7), AsOnDate,120) as YearMonth, Max(AsOnDate) as AsOnDate          
    From DD_KPI_GaugeChartData          
    Where ChartTypeId=@ChartTypeId and PeriodType=@MonthPeriodType            
     and Convert(Varchar(10),AsOnDate,120)<@MonthStart and Convert(Varchar(10),AsOnDate,120)>@YearStart         
     and BranchID=@BranchID and CompID=@CompID            
    Group by  Convert(Varchar(7), AsOnDate,120)          
   )b          
   On a.AsOnDate=b.AsOnDate                              
  Where a.ChartTypeId=@ChartTypeId and a.PeriodType=@MonthPeriodType and a.BranchID=@BranchID and a.CompID=@CompID            
   and Convert(Varchar(10),a.AsOnDate,120)<@MonthStart  and Convert(Varchar(10),a.AsOnDate,120)>@YearStart          
 )a           
          
 Declare @YearPlanProductionValue money,  @YearTargetProductionValue money;          
          
 Select @YearPlanProductionValue=IsNull(PlanValue,0), @YearTargetProductionValue=TargetValue          
 From DD_KPI_GaugeChartData a          
 Where ChartTypeId=@ChartTypeIdProductionValue and PeriodType=@YearPeriodType and BranchID=@BranchID and CompID=@CompID           
  and AsOnDate=         
   (        
    Select Max(AsOnDate) From DD_KPI_GaugeChartData s           
    Where s.ChartTypeId=a.ChartTypeId and s.PeriodType=a.PeriodType           
    and s.AsOnDate<=@AsOnDate and s.BranchID=a.BranchID and s.CompID=a.CompID          
   )          
          
 /* Allowed Variance */                      
 Select @YearVarianceAllowed=@YearVarianceAllowedPerc*@YearPlanTillMonth,                      
   @MonthVarianceAllowed=@MonthVarianceAllowedPerc*@MonthPlanTillDate,                
   @DayVarianceAllowed=@DayVarianceAllowedPerc*@DayPlanTillNow                    
           
 SET @YearTarget= (@YearPlan*(@YearTargetProductionValue/@YearPlanProductionValue));            
 SET @MonthTarget= (@YearTarget/12.0);            
 SET @DayTarget= (@MonthTarget/@MonthWorkingDays);        
          
 If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate)                      
  Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate            
            
 Insert into DD_KPI_GaugeChartData            
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @DayPeriodType as PeriodType, isNull(@DayTarget, 0) as TargetValue, isNull(@DayPlan, 0) as PlanValue,             
   isNull(@DayPlanTillNow, 0) as PlanTillPeriodValue, isNull(@DayAchieved, 0) as AchievedValue,           
   isNull(@DayAchieved, 0) as AchievedValue2,    -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.          
   isNull(@DayVarianceAllowed, 0) as AllowVariance,  isNull((@DayPlanTillNow-@DayAchieved), 0) as Variance,            
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp            
              
  Union All            
                
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @MonthPeriodType as PeriodType, isNull(@MonthTarget, 0) as TargetValue,             
   isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthPlanTillDate, 0) as PlanTillPeriodValue, isNull(@MonthAchieved, 0) as AchievedValue,           
   isNull(@MonthAchieved, 0) as AchievedValue2,   -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.        
   isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthPlanTillDate-@MonthAchieved), 0) as Variance, @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp            
            
  Union All            
                
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, isNull(@YearTarget, 0) as TargetValue,             
   isNull(@YearPlan, 0) as PlanValue, isNull(@YearPlanTillMonth, 0) as PlanTillPeriodValue, isNull(@YearAchieved, 0) as AchievedValue,           
   isNull(@YearAchieved, 0) as AchievedValue2,   -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.          
   isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearPlanTillMonth-@YearAchieved), 0) as Variance, @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp                  
END 
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_ProductionValue_ChartData_Ins]    Script Date: 17/06/2026 11:29:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_ProductionValue_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))            
/* Process Current Date, Current Month, Current Year Data from the original table if it is changed from last process          
    and all other data will be taken from already processed data */          
AS                          
BEGIN                      
    SET NOCOUNT ON;          
          
 DECLARE @ChartTypeId int;          
  SET @ChartTypeId=14; /* From Table ChartTypeMaster */          
           
 DECLARE @CurDate datetime;          
  SET @CurDate = getdate();              
                
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */            
    DECLARE @ShiftStart datetime;            
  SET @ShiftStart='06:00';            
                  
    DECLARE @Finyear varchar(15);                      
                      
    /* Period Start End */                      
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                        
                
    If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)            
  BEGIN            
   SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' 06:00';            
  END            
    Else            
  BEGIN            
   SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' 06:00';            
  END      
      
    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';          
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);      
      
    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));            
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                        
              
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                      
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                                  
               
    Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))          
    From DD_KPI_HolidayMaster          
    Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID          
              
    Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1          
    From DD_KPI_HolidayMaster          
    Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID          
                 
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                          
    DECLARE  @MonthTarget money,  @YearTarget money ,  @DayTarget money;                          
                          
    SET @YearLabelCount=12;    /* No. of months in a Year */                      
    SET @MonthLabelCount=@MonthWorkingDays;                       
    SET @DayLabelCount=@TotalShiftHours;                          
          
 DECLARE @YearPeriodType Char(2), @MonthPeriodType Char(2), @DayPeriodType Char(2)      
  SELECT @YearPeriodType='YR', @MonthPeriodType='MN', @DayPeriodType='DY'      
                       
 SET @YearTarget = dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'Target',@YearPeriodType,@BranchID,@CompID);                             
    SET @MonthTarget=@YearTarget/12;                          
    SET @DayTarget=  @MonthTarget/@MonthWorkingDays ;                       
                
 DECLARE @YearPlan money, @YearPlanTillMonth money, @YearAchieved money, @YearVarianceAllowedPerc decimal(5, 2), @YearVarianceAllowed money,                         
   @MonthPlan money, @MonthPlanTillDate money, @MonthAchieved money, @MonthVarianceAllowedPerc decimal(5, 2), @MonthVarianceAllowed money,                         
   @DayPlan money, @DayPlanTillNow money, @DayAchieved money, @DayVarianceAllowedPerc decimal(5, 2), @DayVarianceAllowed money;            
                                      
    SELECT @YearVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@YearPeriodType,@BranchID,@CompID),       
   @MonthVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@MonthPeriodType,@BranchID,@CompID),       
   @DayVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@DayPeriodType,@BranchID,@CompID)      
                   
    DECLARE @ProductionPlan_Tbl TABLE (ItemCode varchar(20), PlanQty money)                
  Insert into @ProductionPlan_Tbl                
   Select ItemCode, Sum(PlanQty) as PlanQty                
   From fn_PPC_ProductionPlan_Dtl_V2(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear)                
   Where PlanFor=2 and PlanPeriod Between @MonthStart and @MonthEnd                   
   Group by ItemCode      
      
 /* Month */                        
 Select @MonthPlan=Sum(PlanQty*Rate), @MonthPlanTillDate=Sum(PlanQtyTillDate*Rate), @MonthAchieved=Sum(IGRQty*Rate)      
 From                        
 (                        
  Select a.ItemCode, a.PlanQty, IsNull((a.PlanQty*@CompletedDays)/@MonthWorkingDays,0) as PlanQtyTillDate,      
   IsNull(Sum(b.InwardGoodsReceiptQty),0)As IGRQty,      
   IsNull(dbo.fn_SAL_Item_Rate(a.ItemCode, 0, '', 0, Null, @BranchID, @CompID, @Finyear),0)as Rate                        
  From @ProductionPlan_Tbl a                                      
  Outer Apply       
   (      
    Select o.InwardGoodsReceiptType, o.InwardGoodsReceiptNo, o.InwardGoodsReceiptDate,        
     o.WorkOrderType, o.WorkOrderNo, o.WorkOrderDate, o.ItemCode,  o.InwardGoodsReceiptQty       
    From PPC_InwardGoodsReceipt o      
    Where o.Transtamp between @MonthStart and @AsOnDate and o.BranchId=@BranchId and o.CompId=@CompId      
     and Exists      
      (      
       Select Distinct pw.ProcessWorkOrderType As WOType, pw.ProcessWorkOrderNo As WONo, pw.ProcessWorkOrderDate As WODate,      
         pw.ToStageCode As ItemCode, pw.FromStageCode, pw.ToStageCode As StageCode, pw.ParentCode,      
         pw.BranchID, pw.CompID, pw.Finyear      
       From dbo.fn_PPC_ProcessWorkOrder(@BranchID, @CompID)  pw                  
       Where pw.ParentCode=a.ItemCode and pw.ToStageCode=o.ItemCode and pw.ProcessWorkOrderType=o.WorkOrderType       
        and pw.ProcessWorkOrderNo=o.WorkOrderNo and pw.ProcessWorkOrderDate=o.WorkOrderDate          
        and pw.BranchID=o.BranchID and pw.CompID=o.CompID      
                       
       UNION ALL                  
                     
       Select Distinct  aw.AssemblyWorkOrderType As WOType, aw.AssemblyWorkOrderNo As WONo, aw.AssemblyWorkOrderDate As WODate,      
         aw.ParentCode As ItemCode, aw.ItemCode As FromStageCode, aw.ItemCode As StageCode,        
         aw.ParentCode, aw.BranchID, aw.CompID, aw.Finyear                  
       From dbo.fn_PPC_AssemblyWorkOrder(@BranchId, @CompId) aw              
       Where aw.ParentCode=a.ItemCode and aw.ParentCode=o.ItemCode      
        and aw.AssemblyWorkOrderType=o.WorkOrderType and aw.AssemblyWorkOrderNo=o.WorkOrderNo and aw.AssemblyWorkOrderDate=o.WorkOrderDate      
        /*and aw.ParentCode in (Select StageCode From dbo.fn_BOM_Get_MPSMaster('A', @AsOnDate, @AsOnDate, @BranchID, @CompID) mp                                                
               Where mp.Itemcode=a.Itemcode)*/      
                            
       UNION ALL                  
                     
       Select Distinct rw.ReworkOrderType As WOType, rw.ReworkOrderNo As WONo, rw.ReworkOrderDate As WODate,      
           rw.StageCode As ItemCode, rw.StageCode As FromStageCode, rw.StageCode,      
           rw.StageCode As ParentCode, rw.BranchID, rw.CompID, rw.Finyear          
       From dbo.fn_PPC_ReWorkOrder(@BranchId, @CompId) rw                  
       Where rw.StageCode=a.ItemCode and rw.StageCode=o.ItemCode       
        and rw.ReworkOrderType=o.WorkOrderType and rw.ReworkOrderNo=o.WorkOrderNo and rw.ReworkOrderDate=o.WorkOrderDate      
      )      
   )b        
  Group by a.ItemCode, a.PlanQty                   
 )a             
       
 /* Day */      
 Select @DayPlan=Sum(Date1*Rate), @DayAchieved=Sum(IGRQty*Rate)      
 From      
 (      
  Select a.DocType, a.DocNo, a.DocDate, a.Shift, a.StageCode, a.Rate, a.MachineCode, a.Date1, Sum(a.IGRQty) as IGRQty      
  From      
  (      
   Select a.DocType, a.DocNo, a.DocDate, a.Shift, a.StageCode, Max(Rate) as Rate, a.MachineCode, a.Date1, a.IGRQty      
   From      
   (      
    Select distinct a.DocType, a.DocNo, a.DocDate, a.Shift, c.ItemCode, a.StageCode,       
     IsNull((Select dbo.fn_SAL_Item_Rate(c.ItemCode,0,'',0,NULL, @BranchID, @CompID, @Finyear)),0) As Rate,       
      (a.MachineCode) As MachineCode, a.MachineCode As MachCode,       
     a.Date1, Isnull(Case When (b.Type='C' and b.CriteriaCode in (1,2,3,4)) or (b.Type in ('R','LR') and b.CriteriaCode=14) Then b.Qty Else '0' End,0) As IGRQty      
        
    From PPC_Vw_QuickProductionplan_Dtl a      
      
    Left Outer Join QC_Inspection_Criteria b                    
     On a.DocDate=b.RefDate and a.DocNo=b.RefNo and a.DocType=b.RefType and a.StageCode=b.ItemCode  and a.MachineCode=b.MachineCode            
     and a.Shift=b.Shift and a.BranchID=b.BranchID and a.CompID=b.CompID      
      
    Left Outer Join fn_Bom_MPS_Master('A',@AsOnDate, @AsOnDate, @BranchID, @CompID)c                   
     On a.StageCode=c.StageCode        
    Where a.StartDate=Convert(Varchar(10),@DayStart,120) and  a.OperationName<>'SETTING'        
     and a.BranchID=@BranchID and a.CompID=@CompID            
      /*and Exists       
      (      
       Select * From fn_PPC_Production_Configuration_Master(@AsOnDate, @AsOnDate, @BranchID, @CompID)s                            
       Where s.ItemCode=a.StageCode and s.ReportCode = 2 and s.Isselect = 1      
      )  */    
   )a      
   Group by a.DocType, a.DocNo, a.DocDate, a.Shift, a.StageCode, a.MachineCode, a.Date1, a.IGRQty      
  )a      
  Group by a.DocType, a.DocNo, a.DocDate, a.Shift, a.StageCode, a.Rate, a.MachineCode, a.Date1      
 )x      
       
 /*Select @DayPlan=(@MonthPlan/@MonthWorkingDays), @DayAchieved=Sum(IGRQty*Rate)      
 From                        
 (                        
  Select a.ItemCode, IsNull(Sum(b.InwardGoodsReceiptQty),0)As IGRQty,      
   IsNull(dbo.fn_SAL_Item_Rate(a.ItemCode, 0, '', 0, Null, @AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear),0)as Rate                        
  From @ProductionPlan_Tbl a                                        
  Outer Apply       
   (      
    Select o.InwardGoodsReceiptType, o.InwardGoodsReceiptNo, o.InwardGoodsReceiptDate,        
     o.WorkOrderType, o.WorkOrderNo, o.WorkOrderDate, o.ItemCode,  o.InwardGoodsReceiptQty       
    From PPC_InwardGoodsReceipt o      
    Where o.Transtamp between @DayStart and @AsOnDate and o.BranchId=@BranchId and o.CompId=@CompId      
     and Exists      
      (      
       Select Distinct pw.ProcessWorkOrderType As WOType, pw.ProcessWorkOrderNo As WONo, pw.ProcessWorkOrderDate As WODate,      
         pw.ToStageCode As ItemCode, pw.FromStageCode, pw.ToStageCode As StageCode, pw.ParentCode,      
         pw.BranchID, pw.CompID, pw.Finyear      
       From PPC_ProcessWorkOrder pw                  
       Where pw.ParentCode=a.ItemCode and pw.ToStageCode=o.ItemCode and pw.ProcessWorkOrderType=o.WorkOrderType       
        and pw.ProcessWorkOrderNo=o.WorkOrderNo and pw.ProcessWorkOrderDate=o.WorkOrderDate          
        and pw.BranchID=o.BranchID and pw.CompID=o.CompID      
                      
       UNION ALL                  
                     
       Select Distinct  aw.AssemblyWorkOrderType As WOType, aw.AssemblyWorkOrderNo As WONo, aw.AssemblyWorkOrderDate As WODate,      
         aw.ParentCode As ItemCode, aw.ItemCode As FromStageCode, aw.ItemCode As StageCode,        
         aw.ParentCode, aw.BranchID, aw.CompID, aw.Finyear                  
       From dbo.fn_PPC_AssemblyWorkOrder(@BranchId, @CompId) aw              
       Where /*aw.ParentCode=a.ItemCode and */aw.ParentCode=o.ItemCode      
        and aw.AssemblyWorkOrderType=o.WorkOrderType and aw.AssemblyWorkOrderNo=o.WorkOrderNo and aw.AssemblyWorkOrderDate=o.WorkOrderDate      
        and aw.ParentCode in (Select StageCode From dbo.fn_BOM_Get_MPSMaster('A', @AsOnDate, @AsOnDate, @BranchID, @CompID) mp                                                
               Where mp.Itemcode=a.Itemcode)      
                            
       UNION ALL                  
                     
       Select Distinct rw.ReworkOrderType As WOType, rw.ReworkOrderNo As WONo, rw.ReworkOrderDate As WODate,      
           rw.StageCode As ItemCode, rw.StageCode As FromStageCode, rw.StageCode,      
           rw.StageCode As ParentCode, rw.BranchID, rw.CompID, rw.Finyear          
       From dbo.fn_PPC_ReWorkOrder(@BranchId, @CompId) rw                  
       Where rw.StageCode=a.ItemCode and rw.StageCode=o.ItemCode       
        and rw.ReworkOrderType=o.WorkOrderType and rw.ReworkOrderNo=o.WorkOrderNo and rw.ReworkOrderDate=o.WorkOrderDate      
      )      
   )b          
  Group by a.ItemCode, a.PlanQty                         
 )a      
 */                        
              
 /* Since Hourly Plan not available DayPlanTillNow calculated on prorate basis */                      
 SET @DayPlanTillNow=(@DayPlan * DateDiff(minute, @DayStart, @AsOnDate))/DateDiff(minute, @DayStart, @DayEnd)             
          
      
 /* Year */           
 Select @YearPlan=Sum(YearPlan) , @YearPlanTillMonth=Sum(YearPlanTillMonth), @YearAchieved=Sum(YearAchieved)          
 From          
 (          
  Select @MonthPlan as YearPlan, @MonthPlanTillDate as YearPlanTillMonth,  @MonthAchieved as YearAchieved        
              
  Union All          
          
  /* Year Achieved (From Digital Data Table) */          
  Select IsNull(Sum(PlanValue),0) as YearPlanValue, IsNull(Sum(PlanValue),0) as YearPlanTillValue, IsNull(Sum(AchievedValue),0) as YearAchievedValue          
  From DD_KPI_GaugeChartData a           
  Inner Join               
   (        
    Select Convert(Varchar(7), AsOnDate,120) as YearMonth, Max(AsOnDate) as AsOnDate        
    From DD_KPI_GaugeChartData        
    Where ChartTypeId=@ChartTypeId and PeriodType=@MonthPeriodType          
     and Convert(Varchar(10),AsOnDate,120)<@MonthStart and Convert(Varchar(10),AsOnDate,120)>@YearStart       
     and BranchID=@BranchID and CompID=@CompID          
    Group by  Convert(Varchar(7), AsOnDate,120)        
   )b        
   On a.AsOnDate=b.AsOnDate               
  Where a.ChartTypeId=@ChartTypeId and a.PeriodType=@MonthPeriodType       
   and Convert(Varchar(10),a.AsOnDate,120)<@MonthStart and Convert(Varchar(10),a.AsOnDate,120)>@YearStart      
   and a.BranchID=@BranchID and a.CompID=@CompID           
 )a          
                
    /* Allowed Variance */                        
 Select @YearVarianceAllowed=@YearVarianceAllowedPerc*@YearPlanTillMonth,                        
  @MonthVarianceAllowed=@MonthVarianceAllowedPerc*@MonthPlanTillDate,                  
  @DayVarianceAllowed=@DayVarianceAllowedPerc*@DayPlanTillNow                      
               
 If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate)        
  Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate          
          
 Insert into DD_KPI_GaugeChartData          
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @DayPeriodType as PeriodType, isNull(@DayTarget, 0) as TargetValue, isNull(@DayPlan, 0) as PlanValue,           
   isNull(@DayPlanTillNow, 0) as PlanTillPeriodValue, isNull(@DayAchieved, 0) as AchievedValue,         
   isNull(@DayAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.        
   isNull(@DayVarianceAllowed, 0) as AllowVariance,            
   isNull((@DayPlanTillNow-@DayAchieved), 0) as Variance,          
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp          
            
  Union All          
              
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @MonthPeriodType as PeriodType, isNull(@MonthTarget, 0) as TargetValue,           
   isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthPlanTillDate, 0) as PlanTillPeriodValue, isNull(@MonthAchieved, 0) as AchievedValue,         
   isNull(@MonthAchieved, 0) as AchievedValue2, -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.        
   isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthPlanTillDate-@MonthAchieved), 0) as Variance, @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp          
          
  Union All          
            
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, isNull(@YearTarget, 0) as TargetValue,           
   isNull(@YearPlan, 0) as PlanValue, isNull(@YearPlanTillMonth, 0) as PlanTillPeriodValue, isNull(@YearAchieved, 0) as AchievedValue,         
   isNull(@YearAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.        
   isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearPlanTillMonth-@YearAchieved), 0) as Variance, @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp          
                    
END        
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_PurchaseConsumption_ChartData_Ins]    Script Date: 17/06/2026 11:29:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[DD_KPI_PurchaseConsumption_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))      
/* Process Current Date, Current Month, Current Year Data from the original table if it is changed from last process    
    and all other data will be taken from already processed data */    
AS                    
BEGIN                
    SET NOCOUNT ON;    
    
	DECLARE @ChartTypeId int, @ChartTypeIdSalesValue int, @ChartTypeIdSalesContribution int;         
		SELECT  @ChartTypeId=10, @ChartTypeIdSalesValue=1,  @ChartTypeIdSalesContribution=2;  

	DECLARE @CurDate datetime;    
		SET @CurDate = getdate();        
          
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */      
    DECLARE @ShiftStart datetime;      
		SET @ShiftStart='06:00';      
            
    DECLARE @Finyear varchar(15);                
                
    /* Period Start End */                
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                  
          
    If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)      
		BEGIN      
			SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' 06:00';          
		END      
    Else      
		BEGIN      
			SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' 06:00';           
		END

    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';    
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);

    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));      
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                  
        
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                            
         
    Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))    
    From DD_KPI_HolidayMaster    
    Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID    
        
    Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1    
    From DD_KPI_HolidayMaster    
    Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID    
           
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                                    
		SET @YearLabelCount=12;    /* No. of months in a Year */                
		SET @MonthLabelCount=@MonthWorkingDays;                 
		SET @DayLabelCount=@TotalShiftHours;                    
    
	DECLARE @YearPeriodType Char(2), @MonthPeriodType Char(2), @DayPeriodType Char(2)
		SELECT @YearPeriodType='YR', @MonthPeriodType='MN', @DayPeriodType='DY'
		                         
	DECLARE @YearTarget money, @YearPlan money, @YearPlanTillMonth money, @YearAchieved money, @YearVarianceAllowedPerc decimal(5, 2), @YearVarianceAllowed money,                   
			@MonthTarget money, @MonthPlan money, @MonthPlanTillDate money, @MonthAchieved money, @MonthVarianceAllowedPerc decimal(5, 2), @MonthVarianceAllowed money,                   
			@DayTarget money, @DayPlan money, @DayPlanTillNow money, @DayAchieved money, @DayVarianceAllowedPerc decimal(5, 2), @DayVarianceAllowed money;      
    
	/* Get Allowed Variance Perc */                     
	SELECT @YearVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@YearPeriodType,@BranchID,@CompID), 
			@MonthVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@MonthPeriodType,@BranchID,@CompID), 
			@DayVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@DayPeriodType,@BranchID,@CompID);


	/***************************** Sales Value & Sales Contribution *****************************/   

		-- Sales Value
    DECLARE @SalesValue_Tbl TABLE (SalesPeriodType varchar(2), SalesTargetValue money, SalesPlanValue money, SalesPlanTillPeriodValue money, SalesAchievedValue money);        
    Insert into @SalesValue_Tbl        
        Select PeriodType, TargetValue, PlanValue, PlanTillPeriodValue, AchievedValue      
        From DD_KPI_GaugeChartData a        
        Where a.ChartTypeId=@ChartTypeIdSalesValue        
            and a.BranchID=@BranchID and a.CompID=@CompID        
			and a.AsOnDate=(Select Max(b.AsOnDate) From DD_KPI_GaugeChartData b         
                            Where b.ChartTypeId=a.ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate        
                                and b.BranchID=a.BranchID and b.CompID=a.CompID        
                            )        

		-- Sales Contribution
    DECLARE @SalesContribution_Tbl TABLE (ContributionPeriodType varchar(2), ContributionTargetValue money, ContributionPlanValue money, ContributionPlanTillPeriodValue money, ContributionAchievedValue money);        
    Insert into @SalesContribution_Tbl        
        Select PeriodType, TargetValue, PlanValue, PlanTillPeriodValue, AchievedValue      
        From DD_KPI_GaugeChartData a        
        Where a.ChartTypeId=@ChartTypeIdSalesContribution        
            and a.BranchID=@BranchID and a.CompID=@CompID        
			and a.AsOnDate=(Select Max(b.AsOnDate) From DD_KPI_GaugeChartData b         
                            Where b.ChartTypeId=a.ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate        
                                and b.BranchID=a.BranchID and b.CompID=a.CompID        
                            )        
	
	
	
	Select @YearTarget=(IsNull(SalesTargetValue,0)-IsNull(ContributionTargetValue,0)), @YearPlan=IsNull(SalesPlanValue,0)-IsNull(ContributionPlanValue,0),
			@YearPlanTillMonth=IsNull(SalesPlanTillPeriodValue,0)-IsNull(ContributionPlanTillPeriodValue,0)
	From  @SalesValue_Tbl a
	Left Outer Join @SalesContribution_Tbl b
		On a.SalesPeriodType=b.ContributionPeriodType 
	 Where a.SalesPeriodType=@YearPeriodType     						
	
	--Month
	Select @MonthTarget=(IsNull(SalesTargetValue,0)-IsNull(ContributionTargetValue,0)), @MonthPlan=IsNull(SalesPlanValue,0)-IsNull(ContributionPlanValue,0),
			@MonthPlanTillDate=IsNull(SalesPlanTillPeriodValue,0)-IsNull(ContributionPlanTillPeriodValue,0)
	From  @SalesValue_Tbl a
	Left Outer Join @SalesContribution_Tbl b
		On a.SalesPeriodType=b.ContributionPeriodType 
	Where a.SalesPeriodType=@MonthPeriodType     
					
	--SET @MonthPlanTillDate=IsNull((@MonthPlan*@CompletedDays)/@MonthWorkingDays,0)

	 --Day
	Select @DayTarget=(IsNull(SalesTargetValue,0)-IsNull(ContributionTargetValue,0)), @DayPlan=IsNull(SalesPlanValue,0)-IsNull(ContributionPlanValue,0),
			@DayPlanTillNow=IsNull(SalesPlanTillPeriodValue,0)-IsNull(ContributionPlanTillPeriodValue,0)
	From  @SalesValue_Tbl a
	Left Outer Join @SalesContribution_Tbl b
		On a.SalesPeriodType=b.ContributionPeriodType 
	 Where a.SalesPeriodType=@DayPeriodType     				

	/* Since Hourly Plan not available DayPlanTillNow calculated on prorate basis */                
	--SET @DayPlanTillNow=(@DayPlan * DateDiff(minute, @DayStart, @AsOnDate))/DateDiff(minute, @DayStart, @DayEnd) 

	/***************************** Purchase From FAS *****************************/   						 
	DECLARE @PurchaseAmount_Tbl TABLE (DocDate datetime, PurAmount money)   
	Insert into @PurchaseAmount_Tbl  
		Select DocDate, Sum(DrAmt-CrAmt) as PurAmount
		From FAS_VoucherTranSub a
		Inner Join FAS_LedgerMaster_AuthTbl b
			On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode
		Where b.LrRoute like '0D%' and a.DocDate between @YearStart and Convert(Varchar(10),@AsOnDate,121) and a.CompCode=(@CompID+@BranchID)
		Group by DocDate

	/* Day Purchase Amount */     
	Select @DayAchieved=Sum(PurAmount)
	From @PurchaseAmount_Tbl a
	Where DocDate between Convert(Varchar(10),@DayStart,121) and  Convert(Varchar(10),@AsOnDate,121)
	
	/* Month Purchase Amount */     
	Select @MonthAchieved=Sum(PurAmount)
	From @PurchaseAmount_Tbl a
	Where DocDate between @MonthStart and  Convert(Varchar(10),@AsOnDate,121)
	
	/* Year Purchase Amount */     
	Select @YearAchieved=Sum(PurAmount)
	From @PurchaseAmount_Tbl a
	Where DocDate between @YearStart and  Convert(Varchar(10),@AsOnDate,121)


    /* Allowed Variance */              
	Select @YearVarianceAllowed=@YearVarianceAllowedPerc*@YearPlanTillMonth,              
			@MonthVarianceAllowed=@MonthVarianceAllowedPerc*@MonthPlanTillDate,        
			@DayVarianceAllowed=@DayVarianceAllowedPerc*@DayPlanTillNow      
			            
	--If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate)              
	--	Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate    
    
	--Insert into DD_KPI_GaugeChartData    
		Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @DayPeriodType as PeriodType, isNull(@DayTarget, 0) as TargetValue, 
			isNull(@DayPlan, 0) as PlanValue, isNull(@DayPlanTillNow, 0) as PlanTillPeriodValue, isNull(@DayAchieved, 0) as AchievedValue,   
			isNull(@DayAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.  
			isNull(@DayVarianceAllowed, 0) as AllowVariance, isNull((@DayPlanTillNow-@DayAchieved), 0) as Variance,    
			@BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp    
      
		Union All    
        
		Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @MonthPeriodType as PeriodType, isNull(@MonthTarget, 0) as TargetValue,     
			isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthPlanTillDate, 0) as PlanTillPeriodValue, isNull(@MonthAchieved, 0) as AchievedValue,   
			isNull(@MonthAchieved, 0) as AchievedValue2, -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.  
			isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthPlanTillDate-@MonthAchieved), 0) as Variance, 
			@BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp    
    
		Union All    
        
		Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, isNull(@YearTarget, 0) as TargetValue,     
			isNull(@YearPlan, 0) as PlanValue, isNull(@YearPlanTillMonth, 0) as PlanTillPeriodValue, isNull(@YearAchieved, 0) as AchievedValue,   
			isNull(@YearAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.  
			isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearPlanTillMonth-@YearAchieved), 0) as Variance, 
			@BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp    
              
END    
  
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_PurchaseRMActualConsumptionBasedonPPCPlan_ChartData_Ins]    Script Date: 17/06/2026 11:29:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_PurchaseRMActualConsumptionBasedonPPCPlan_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))              
/* Process Current Date, Current Month, Current Year Data from the original table if it is changed from last process            
    and all other data will be taken from already processed data */            
AS                            
BEGIN                        
    SET NOCOUNT ON;            
            
 DECLARE @ChartTypeId int, @ChartTypeIdPurRMTheoritical int;        
  SELECT  @ChartTypeId=12, @ChartTypeIdPurRMTheoritical=10;         
        
 DECLARE @CurDate datetime;            
  SET @CurDate = getdate();                
                  
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */              
    DECLARE @ShiftStart datetime;              
  SELECT @ShiftStart=ShiftStart From vw_DD_KPI_ShiftStart;               
                    
    DECLARE @Finyear varchar(15);                        
                        
    /* Period Start End */                        
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                          
                  
    If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)              
  BEGIN              
   SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' ' + Convert(varchar(8), @ShiftStart, 108);                        
  END              
    Else              
  BEGIN              
   SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' ' + Convert(varchar(8), @ShiftStart, 108);                           
  END        
        
    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';            
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);        
        
    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));              
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                          
                
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                        
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                                    
                 
    Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))            
    From DD_KPI_HolidayMaster            
    Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID            
                
    Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1            
    From DD_KPI_HolidayMaster            
    Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID        
            
    /*Select @CompletedDays=Count(*)        
    From        
    (        
        Select DateAdd(day,1,FromDate) +  ' ' + Convert(Varchar(8), @ShiftStart,108)  as DayEnd, *         
        From fn_COM_PeriodSplit(@MonthStart, Convert(varchar(10),@DayStart,120), 'D', '', 0, '0') a        
        Where Not Exists        
        (        
            Select *        
            From DD_KPI_HolidayMaster s        
            Where s.HolidayDate=a.FromDate and s.BranchID=@BranchID and s.CompID=@CompID        
        )        
    )a        
    Where DayEnd<=@AsOnDate  */        
                   
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                                            
  SET @YearLabelCount=12;    /* No. of months in a Year */                        
  SET @MonthLabelCount=@MonthWorkingDays;                         
  SET @DayLabelCount=@TotalShiftHours;                            
            
 DECLARE @YearPeriodType Char(2), @MonthPeriodType Char(2), @DayPeriodType Char(2)        
  SELECT @YearPeriodType='YR', @MonthPeriodType='MN', @DayPeriodType='DY'        
                                   
 DECLARE @YearTarget money, @YearPlan money, @YearPlanTillMonth money, @YearAchieved money, @YearVarianceAllowedPerc decimal(5, 2), @YearVarianceAllowed money,                           
   @MonthTarget money, @MonthPlan money, @MonthPlanTillDate money, @MonthAchieved money, @MonthVarianceAllowedPerc decimal(5, 2), @MonthVarianceAllowed money,               
   @DayTarget money, @DayPlan money, @DayPlanTillNow money, @DayAchieved money, @DayVarianceAllowedPerc decimal(5, 2), @DayVarianceAllowed money;              
            
 DECLARE @OBValue money, @CBValue money;        
        
 /* Get Allowed Variance Perc */                             
 SELECT @YearVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@YearPeriodType,@BranchID,@CompID),         
   @MonthVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@MonthPeriodType,@BranchID,@CompID),         
   @DayVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@DayPeriodType,@BranchID,@CompID);        
        
        
 /***************************** Theoritical Consumption -> Production Value and Production Contribution *****************************/           
        
 DECLARE @PurTheoriticalConsumption_Tbl TABLE (PeriodType varchar(2), TargetValue money, PlanValue money, PlanTillPeriodValue money, AchievedValue money);                
    Insert into @PurTheoriticalConsumption_Tbl                
        Select PeriodType, TargetValue, PlanValue, PlanTillPeriodValue, AchievedValue             
        From DD_KPI_GaugeChartData a                
        Where a.ChartTypeId=@ChartTypeIdPurRMTheoritical           
            and a.BranchID=@BranchID and a.CompID=@CompID                
   and a.AsOnDate=(Select Max(b.AsOnDate) From DD_KPI_GaugeChartData b                 
                            Where b.ChartTypeId=a.ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate                
                                and b.BranchID=a.BranchID and b.CompID=a.CompID                
                            )              
        
 /***************************** Year *****************************/          
 -- Year OB        
 Select @OBValue=Sum(a.OBQtyBasedOnNorms* IsNull(b.Rate,0))        
  --dbo.fn_COM_ItemRate_Pur(a.ItemCode, 3, '2018-04-01', '2019-01-09 18:18:18', 0, '2019-01-09 18:18:18', '2019-01-09 18:18:18', '00', '01', '04-2018 03-2019') as RMRate                
 From        
 (        
  Select a.ItemCode, IsNull(Sum(OBQtyBasedOnNorms),0) as OBQtyBasedOnNorms        
  From fn_DD_KPI_ProductionPlanItem_Stock_BasedOnNorms(@YearStart, @AsOnDate, @AsOnDate,@AsOnDate, @BranchID, @CompID, @Finyear)a        
  Group by a.ItemCode        
 )a        
 Left Outer Join fn_Com_CurrentItemRate_Dtl(@AsOnDate,@AsOnDate, @BranchID, @CompID, @Finyear) b        
  On a.ItemCode=b.ItemCode        
        
 /*-- Year OB & CB          
 Select @OBValue=IsNull(Sum(OBQty),0), @CBValue=IsNull(Sum(CBQty),0)        
 From fn_DD_KPI_StockPeriod_BasedOnNorms(@YearStart, @AsOnDate, @AsOnDate,@AsOnDate, @BranchID, @CompID, @Finyear)a*/        
        
 -- Year Purchase Consumption          
 Select @YearTarget=(a.PlanValue-@OBValue), @YearAchieved=a.AchievedValue        
 From @PurTheoriticalConsumption_Tbl a        
 Where a.PeriodType=@YearPeriodType        
        
 -- Year Plan        
 ;WITH Child_CTE        
 As        
 (        
  Select distinct Case When (a.ItemCode = '20520150T0' and a.PlanPeriod >= '2017-07-01') Then a.ItemCode Else c.ItemCode End as ChildCode                
  From fn_PPC_ProductionPlan_Dtl_V2(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear) a        
  Outer Apply fn_BOM_ExplodableItems(a.ItemCode,'C',@BranchID,@CompID) c                
   --On a.ItemCode=c.ParentCode and c.ItemType='C' and a.BranchID=c.BranchID and a.CompID=c.CompID                   
  Where a.PlanFor=2 and PlanPeriod Between @YearStart and Convert(Varchar(10),@AsOnDate,121)         
 )        
        
 Select @YearPlan=Sum(a.ScheduleQty*b.Rate)        
 From fn_PUR_Schedule(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear)a        
 Left Outer Join fn_PUR_PurchaseOrder_Dtl(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear)b        
  On a.OrderNo=b.OrderNo and a.OrderDate=b.OrderDate and a.OrderType=b.OrderType and a.ItemCode=b.ItemCode        
 Where a.RequiredDate between @YearStart and Convert(Varchar(10),@AsOnDate,121)         
  and Exists        
  (        
   Select * From Child_CTE s        
   Where s.ChildCode=a.ItemCode)        
         
          
 SET @YearPlanTillMonth=IsNull((@YearPlan/12.0) * (DateDiff(m,@YearStart,DateAdd(day, -1,@MonthStart))),0)        
        
             
 /***************************** Month *****************************/          
 -- Month OB        
 Select @OBValue=Sum(a.OBQtyBasedOnNorms* IsNull(b.Rate,0))        
  --dbo.fn_COM_ItemRate_Pur(a.ItemCode, 3, '2018-04-01', '2019-01-09 18:18:18', 0, '2019-01-09 18:18:18', '2019-01-09 18:18:18', '00', '01', '04-2018 03-2019') as RMRate                
 From        
 (        
  Select a.ItemCode, IsNull(Sum(OBQtyBasedOnNorms),0) as OBQtyBasedOnNorms        
  From fn_DD_KPI_ProductionPlanItem_Stock_BasedOnNorms(@MonthStart, @AsOnDate, @AsOnDate,@AsOnDate, @BranchID, @CompID, @Finyear)a        
  Group by a.ItemCode        
 )a        
 Left Outer Join fn_Com_CurrentItemRate_Dtl(@AsOnDate,@AsOnDate, @BranchID, @CompID, @Finyear) b        
  On a.ItemCode=b.ItemCode        
        
 /*-- Month OB & CB          
 Select @OBValue=IsNull(Sum(OBQty),0), @CBValue=IsNull(Sum(CBQty),0)        
 From fn_DD_KPI_StockPeriod_BasedOnNorms(@MonthStart, @AsOnDate, @AsOnDate,@AsOnDate, @BranchID, @CompID, @Finyear)a*/        
        
 -- Month Purchase Consumption        
 Select @MonthTarget=(a.PlanValue-@OBValue), @MonthAchieved=a.AchievedValue        
 From @PurTheoriticalConsumption_Tbl a        
 Where a.PeriodType=@MonthPeriodType        
         
 -- Month Plan        
 ;WITH Child_CTE        
 As        
 (        
  Select distinct Case When (a.ItemCode = '20520150T0' and a.PlanPeriod >= '2017-07-01') Then a.ItemCode Else c.ItemCode End as ChildCode                
  From fn_PPC_ProductionPlan_Dtl_V2(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear) a        
  Outer Apply fn_BOM_ExplodableItems(a.ItemCode,'C',@BranchID,@CompID) c           
  -- On a.ItemCode=c.ParentCode and c.ItemType='C' and a.BranchID=c.BranchID and a.CompID=c.CompID                   
  Where a.PlanFor=2 and PlanPeriod Between @MonthStart and Convert(Varchar(10),@AsOnDate,121)         
 )        
        
 Select @MonthPlan=Sum(a.ScheduleQty*b.Rate)        
 From fn_PUR_Schedule(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear)a        
 Left Outer Join fn_PUR_PurchaseOrder_Dtl(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear)b        
  On a.OrderNo=b.OrderNo and a.OrderDate=b.OrderDate and a.OrderType=b.OrderType and a.ItemCode=b.ItemCode        
 Where a.RequiredDate between @MonthStart and Convert(Varchar(10),@AsOnDate,121)         
  and Exists        
  (        
   Select * From Child_CTE s        
   Where s.ChildCode=a.ItemCode         
  )        
         
 SET @MonthPlanTillDate=IsNull((@MonthPlan*@CompletedDays)/@MonthWorkingDays,0)        
              
 /***************************** Day *****************************/          
         
 -- Day OB        
 Select @OBValue=Sum(a.OBQtyBasedOnNorms* IsNull(b.Rate,0))        
  --dbo.fn_COM_ItemRate_Pur(a.ItemCode, 3, '2018-04-01', '2019-01-09 18:18:18', 0, '2019-01-09 18:18:18', '2019-01-09 18:18:18', '00', '01', '04-2018 03-2019') as RMRate                
 From        
 (        
  Select a.ItemCode, IsNull(Sum(OBQtyBasedOnNorms),0) as OBQtyBasedOnNorms        
  From fn_DD_KPI_ProductionPlanItem_Stock_BasedOnNorms(@DayStart, @AsOnDate, @AsOnDate,@AsOnDate, @BranchID, @CompID, @Finyear)a        
  Group by a.ItemCode        
 )a        
 Left Outer Join  fn_Com_CurrentItemRate_Dtl(@AsOnDate,@AsOnDate, @BranchID, @CompID, @Finyear) b        
  On a.ItemCode=b.ItemCode        
        
 /*-- Day OB & CB          
 Select @OBValue=IsNull(Sum(OBQty),0), @CBValue=IsNull(Sum(CBQty),0)        
 From fn_DD_KPI_StockPeriod_BasedOnNorms(@DayStart, @AsOnDate, @AsOnDate,@AsOnDate, @BranchID, @CompID, @Finyear)a*/        
        
 -- Day Purchase Consumption        
 Select @DayTarget=(a.PlanValue-@OBValue), @DayAchieved=a.AchievedValue        
 From @PurTheoriticalConsumption_Tbl a        
 Where a.PeriodType=@DayPeriodType        
        
 -- Day Plan        
 ;WITH Child_CTE        
 As        
 (        
  Select distinct Case When (a.ItemCode = '20520150T0' and a.PlanPeriod >= '2017-07-01') Then a.ItemCode Else c.ItemCode End as ChildCode                
  From fn_PPC_ProductionPlan_Dtl_V2(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear) a        
  Outer Apply fn_BOM_ExplodableItems(a.ItemCode,'C',@BranchID,@CompID) c                 
   --On a.ItemCode=c.ParentCode and c.ItemType='C' and a.BranchID=c.BranchID and a.CompID=c.CompID                   
  Where a.PlanFor=2 and PlanPeriod Between @MonthStart and Convert(Varchar(10),@AsOnDate,121)         
 )        
        
 Select @DayPlan=Sum(a.ScheduleQty*b.Rate)        
 From fn_PUR_Schedule(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear)a        
 Left Outer Join fn_PUR_PurchaseOrder_Dtl(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear)b        
  On a.OrderNo=b.OrderNo and a.OrderDate=b.OrderDate and a.OrderType=b.OrderType and a.ItemCode=b.ItemCode        
 Where a.RequiredDate between Convert(Varchar(10),@DayStart,121) and Convert(Varchar(10),@AsOnDate,121)         
  and Exists        
  (        
   Select * From Child_CTE s        
   Where s.ChildCode=a.ItemCode         
  )        
         
 /* Since Hourly Plan not available DayPlanTillNow calculated on prorate basis */                        
 SET @DayPlanTillNow=IsNull((@DayPlan * DateDiff(minute, @DayStart, @AsOnDate))/DateDiff(minute, @DayStart, @DayEnd),0)         
        
 /***************************************************************************************************************/         
        
    /* Allowed Variance */                      
 Select @YearVarianceAllowed=@YearVarianceAllowedPerc*@YearPlanTillMonth,            
   @MonthVarianceAllowed=@MonthVarianceAllowedPerc*@MonthPlanTillDate,                
   @DayVarianceAllowed=@DayVarianceAllowedPerc*@DayPlanTillNow              
                       
 If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate)                      
  Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate            
            
 Insert into DD_KPI_GaugeChartData            
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @DayPeriodType as PeriodType, isNull(@DayTarget, 0) as TargetValue,         
   isNull(@DayPlan, 0) as PlanValue, isNull(@DayPlanTillNow, 0) as PlanTillPeriodValue, isNull(@DayAchieved, 0) as AchievedValue,           
   isNull(@DayAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.          
   isNull(@DayVarianceAllowed, 0) as AllowVariance, isNull((@DayPlanTillNow-@DayAchieved), 0) as Variance,            
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp            
              
  Union All            
                
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @MonthPeriodType as PeriodType, isNull(@MonthTarget, 0) as TargetValue,             
   isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthPlanTillDate, 0) as PlanTillPeriodValue, isNull(@MonthAchieved, 0) as AchievedValue,           
   isNull(@MonthAchieved, 0) as AchievedValue2, -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.          
   isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthPlanTillDate-@MonthAchieved), 0) as Variance,         
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp            
            
  Union All            
                
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, isNull(@YearTarget, 0) as TargetValue,             
   isNull(@YearPlan, 0) as PlanValue, isNull(@YearPlanTillMonth, 0) as PlanTillPeriodValue, isNull(@YearAchieved, 0) as AchievedValue,           
   isNull(@YearAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.          
   isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearPlanTillMonth-@YearAchieved), 0) as Variance,         
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp              
END 
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_PurchaseRMTheoriticalConsumptionBasedonPPCPlan_ChartData_Ins]    Script Date: 17/06/2026 11:29:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_PurchaseRMTheoriticalConsumptionBasedonPPCPlan_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))            
/* Process Current Date, Current Month, Current Year Data from the original table if it is changed from last process          
    and all other data will be taken from already processed data */          
AS                          
BEGIN                      
    SET NOCOUNT ON;          
          
 DECLARE @ChartTypeId int, @ChartTypeIdProductionValue int, @ChartTypeIdProductionContribution int;               
  SELECT  @ChartTypeId=10, @ChartTypeIdProductionValue=14,  @ChartTypeIdProductionContribution=17;        
      
 DECLARE @CurDate datetime;          
  SET @CurDate = getdate();              
                
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */            
    DECLARE @ShiftStart datetime;            
  SET @ShiftStart='06:00';            
                  
    DECLARE @Finyear varchar(15);                      
                      
    /* Period Start End */                      
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                        
                
    If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)            
  BEGIN            
   SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' 06:00';                
  END            
    Else            
  BEGIN            
   SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' 06:00';                 
  END      
      
    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';          
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);      
      
    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));            
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                        
              
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                      
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                                  
               
    Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))          
    From DD_KPI_HolidayMaster          
    Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID          
              
    Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1          
    From DD_KPI_HolidayMaster          
    Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID          
                 
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                                          
  SET @YearLabelCount=12;    /* No. of months in a Year */                      
  SET @MonthLabelCount=@MonthWorkingDays;                       
  SET @DayLabelCount=@TotalShiftHours;                          
          
 DECLARE @YearPeriodType Char(2), @MonthPeriodType Char(2), @DayPeriodType Char(2)      
  SELECT @YearPeriodType='YR', @MonthPeriodType='MN', @DayPeriodType='DY'      
                                 
 DECLARE @YearTarget money, @YearPlan money, @YearPlanTillMonth money, @YearAchieved money, @YearVarianceAllowedPerc decimal(5, 2), @YearVarianceAllowed money,                         
   @MonthTarget money, @MonthPlan money, @MonthPlanTillDate money, @MonthAchieved money, @MonthVarianceAllowedPerc decimal(5, 2), @MonthVarianceAllowed money,                         
   @DayTarget money, @DayPlan money, @DayPlanTillNow money, @DayAchieved money, @DayVarianceAllowedPerc decimal(5, 2), @DayVarianceAllowed money;            
          
 /* Get Allowed Variance Perc */                           
 SELECT @YearVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@YearPeriodType,@BranchID,@CompID),       
   @MonthVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@MonthPeriodType,@BranchID,@CompID),       
   @DayVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@DayPeriodType,@BranchID,@CompID);      
      
      
 /***************************** Production Value & Production Contribution *****************************/         
      
  -- Production Value      
    DECLARE @ProductionValue_Tbl TABLE (PPCPeriodType varchar(2), PPCTargetValue money, PPCPlanValue money, PPCPlanTillPeriodValue money, PPCAchievedValue money);              
    Insert into @ProductionValue_Tbl              
        Select PeriodType, TargetValue, PlanValue, PlanTillPeriodValue, AchievedValue            
        From DD_KPI_GaugeChartData a              
        Where a.ChartTypeId=@ChartTypeIdProductionValue              
            and a.BranchID=@BranchID and a.CompID=@CompID              
   and a.AsOnDate=(Select Max(b.AsOnDate) From DD_KPI_GaugeChartData b               
                            Where b.ChartTypeId=a.ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate              
                                and b.BranchID=a.BranchID and b.CompID=a.CompID              
                            )              
      
  -- Sales Contribution      
    DECLARE @ProductionContribution_Tbl TABLE (ContributionPeriodType varchar(2), ContributionTargetValue money, ContributionPlanValue money, ContributionPlanTillPeriodValue money, ContributionAchievedValue money);              
    Insert into @ProductionContribution_Tbl              
        Select PeriodType, TargetValue, PlanValue, PlanTillPeriodValue, AchievedValue            
        From DD_KPI_GaugeChartData a              
        Where a.ChartTypeId=@ChartTypeIdProductionContribution              
            and a.BranchID=@BranchID and a.CompID=@CompID              
   and a.AsOnDate=(Select Max(b.AsOnDate) From DD_KPI_GaugeChartData b               
                            Where b.ChartTypeId=a.ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate              
                                and b.BranchID=a.BranchID and b.CompID=a.CompID              
                            )              
       
       
       
 Select @YearTarget=(IsNull(PPCTargetValue,0)-IsNull(ContributionTargetValue,0)), @YearPlan=IsNull(PPCPlanValue,0)-IsNull(ContributionPlanValue,0),      
   @YearPlanTillMonth=IsNull(PPCAchievedValue,0)-IsNull(ContributionAchievedValue,0)      
 From  @ProductionValue_Tbl a      
 Left Outer Join @ProductionContribution_Tbl b      
  On a.PPCPeriodType=b.ContributionPeriodType       
  Where a.PPCPeriodType=@YearPeriodType                 
       
 --SET @YearPlanTillMonth=IsNull((@YearPlan/12.0) * (DateDiff(m,@YearStart,DateAdd(day, -1,@MonthStart))),0)      
        
 --Month      
 Select @MonthTarget=(IsNull(PPCTargetValue,0)-IsNull(ContributionTargetValue,0)), @MonthPlan=IsNull(PPCPlanValue,0)-IsNull(ContributionPlanValue,0),      
   @MonthPlanTillDate=IsNull(PPCAchievedValue,0)-IsNull(ContributionAchievedValue,0)      
 From  @ProductionValue_Tbl a      
 Left Outer Join @ProductionContribution_Tbl b      
  On a.PPCPeriodType=b.ContributionPeriodType       
 Where a.PPCPeriodType=@MonthPeriodType           
           
 --SET @MonthPlanTillDate=IsNull((@MonthPlan*@CompletedDays)/@MonthWorkingDays,0)      
        
  --Day      
 Select @DayTarget=(IsNull(PPCTargetValue,0)-IsNull(ContributionTargetValue,0)), @DayPlan=IsNull(PPCPlanValue,0)-IsNull(ContributionPlanValue,0),      
   @DayPlanTillNow=IsNull(PPCAchievedValue,0)-IsNull(ContributionAchievedValue,0)      
 From  @ProductionValue_Tbl a      
 Left Outer Join @ProductionContribution_Tbl b      
  On a.PPCPeriodType=b.ContributionPeriodType       
  Where a.PPCPeriodType=@DayPeriodType               
      
 /* Since Hourly Plan not available DayPlanTillNow calculated on prorate basis */                      
 --SET @DayPlanTillNow=IsNull((@DayPlan * DateDiff(minute, @DayStart, @AsOnDate))/DateDiff(minute, @DayStart, @DayEnd),0)       
        
 /***************************** Purchase From FAS *****************************/                
 DECLARE @PurRMLrCode int, @ProvBillNotBookedLrCode int;      
  SELECT @PurRMLrCode = 265, @ProvBillNotBookedLrCode=960;      
      
 DECLARE @PurchaseAmount_Tbl TABLE (DocDate datetime, PurAmount money)         
 Insert into @PurchaseAmount_Tbl        
  Select DocDate, Sum(DrAmt-CrAmt) as PurAmount      
  From FAS_VoucherTranSub a      
  /*Inner Join FAS_LedgerMaster_AuthTbl b      
   On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode*/      
  Where /*b.LrRoute like '0D%' and */ a.LrCode=@PurRMLrCode and a.DocDate between @YearStart and Convert(Varchar(10),@AsOnDate,121) and a.CompCode=(@CompID+@BranchID)      
   and Not Exists      
   (      
    Select *      
    From FAS_VoucherTranSub s      
    Where s.LrCode=@ProvBillNotBookedLrCode and s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.VrRoute=a.VrRoute and s.CompCode=a.CompCode      
     --960 -> PROV FOR PURCHASE BILLS NOT BOOKED      
   )      
  Group by DocDate      
      
 /* Day Purchase Amount */           
 Select @DayAchieved=Sum(PurAmount)      
 From @PurchaseAmount_Tbl a      
 Where DocDate between Convert(Varchar(10),@DayStart,121) and  Convert(Varchar(10),@AsOnDate,121)      
       
 /* Month Purchase Amount */           
 Select @MonthAchieved=Sum(PurAmount)      
 From @PurchaseAmount_Tbl a      
 Where DocDate between @MonthStart and  Convert(Varchar(10),@AsOnDate,121)      
       
 /* Year Purchase Amount */           
 Select @YearAchieved=Sum(PurAmount)      
 From @PurchaseAmount_Tbl a      
 Where DocDate between @YearStart and  Convert(Varchar(10),@AsOnDate,121)      
      
      
 /***************************** Purchase - Bill Not Booked *****************************/         
 --DECLARE @PurBillNotBookedAmount_Tbl TABLE (DocDate datetime, PurBillNotBookedAmount money)         
 --Insert into @PurBillNotBookedAmount_Tbl        
  --Select a.BatchDate as DocDate, Sum(BillNotBookedValue)  as BillNotBookedValue      
  --From fn_PUR_Get_BillNotBooked_RRDoc(@YearStart, Convert(Varchar(10),@AsOnDate,121), @AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear)a      
  --Left Outer Join dbo.fn_BOM_Material_Master('W', @AsOnDate, @AsOnDate, @BranchID, @CompID)b         
  -- On a.ItemCode= b.ItemCode       
  --Where b.ItemNatureCode in ('A','T','I', 'L', 'R', 'F')      
  --Group by BatchDate      
      
 Select a.BatchType as DocType, a.BatchNo as DocNo, a.BatchDate as DocDate, a.ItemCode, BillNotBookedValue as PurBillNotBookedAmount into #PurBillNotBookedAmount_Tbl      
 From fn_PUR_Get_BillNotBooked_RRDoc(@YearStart, Convert(Varchar(10),@AsOnDate,121), @AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear)a      
      
 /* Day Purchase Bill Not Booked Amount */           
 Select @DayAchieved=@DayAchieved+IsNull(Sum(PurBillNotBookedAmount),0)      
 From #PurBillNotBookedAmount_Tbl a      
 Left Outer Join INV_MATERIAL_MASTER b --fn_BOM_Material_Master('A',@AsOnDate, @AsOnDate, @BranchID, @CompID)b      
  On a.ItemCode=b.ItemCode      
 Where a.DocDate between Convert(Varchar(10),@DayStart,121) and  Convert(Varchar(10),@AsOnDate,121) --b.ItemNatureCode in ('R', 'CR', 'F') and       
  and (b.ItemNature in ('R','CR') /* OR (b.ItemNatureCode='F' and a.ItemCode='20520150T0')*/)      
      
 /* Month Purchase Bill Not BookedAmount */           
 Select @MonthAchieved=@MonthAchieved+IsNull(Sum(PurBillNotBookedAmount),0)      
 From #PurBillNotBookedAmount_Tbl a      
 Left Outer Join INV_MATERIAL_MASTER b ---fn_BOM_Material_Master('A',@AsOnDate, @AsOnDate, @BranchID, @CompID)b      
  On a.ItemCode=b.ItemCode      
 Where a.DocDate between @MonthStart and  Convert(Varchar(10),@AsOnDate,121) -- b.ItemNatureCode in ('R', 'CR', 'F') and       
  and (b.ItemNature in ('R','CR') /* OR (b.ItemNatureCode='F' and a.ItemCode='20520150T0')*/)      
      
 /* Year Purchase Bill Not BookedAmount */           
 Select @YearAchieved=@YearAchieved+IsNull(Sum(PurBillNotBookedAmount),0)      
 From #PurBillNotBookedAmount_Tbl a      
 Left Outer Join INV_MATERIAL_MASTER b --fn_BOM_Material_Master('A',@AsOnDate, @AsOnDate, @BranchID, @CompID)b      
  On a.ItemCode=b.ItemCode      
 Where a.DocDate between @YearStart and  Convert(Varchar(10),@AsOnDate,121) -- b.ItemNatureCode in ('R', 'CR', 'F') and       
  and (b.ItemNature in ('R','CR') /* OR (b.ItemNatureCode='F' and a.ItemCode='20520150T0')*/)      
      
 /***************************************************************************************************************/         
    /* Allowed Variance */                    
 Select @YearVarianceAllowed=@YearVarianceAllowedPerc*@YearPlanTillMonth,                    
   @MonthVarianceAllowed=@MonthVarianceAllowedPerc*@MonthPlanTillDate,              
   @DayVarianceAllowed=@DayVarianceAllowedPerc*@DayPlanTillNow            
                     
 If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate)                    
  Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate          
          
 Insert into DD_KPI_GaugeChartData          
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @DayPeriodType as PeriodType, isNull(@DayTarget, 0) as TargetValue,       
   isNull(@DayPlan, 0) as PlanValue, isNull(@DayPlanTillNow, 0) as PlanTillPeriodValue, isNull(@DayAchieved, 0) as AchievedValue,         
   isNull(@DayAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.        
   isNull(@DayVarianceAllowed, 0) as AllowVariance, isNull((@DayPlanTillNow-@DayAchieved), 0) as Variance,          
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp          
            
  Union All          
              
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @MonthPeriodType as PeriodType, isNull(@MonthTarget, 0) as TargetValue,           
   isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthPlanTillDate, 0) as PlanTillPeriodValue, isNull(@MonthAchieved, 0) as AchievedValue,         
   isNull(@MonthAchieved, 0) as AchievedValue2, -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.        
   isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthPlanTillDate-@MonthAchieved), 0) as Variance,       
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp          
          
  Union All          
              
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, isNull(@YearTarget, 0) as TargetValue,           
   isNull(@YearPlan, 0) as PlanValue, isNull(@YearPlanTillMonth, 0) as PlanTillPeriodValue, isNull(@YearAchieved, 0) as AchievedValue,         
   isNull(@YearAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.        
   isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearPlanTillMonth-@YearAchieved), 0) as Variance,       
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp          
                    
END 
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_PurchaseValueFromFAS_ChartData_Ins]    Script Date: 17/06/2026 11:29:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_PurchaseValueFromFAS_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))        
/* Process Current Date, Current Month, Current Year Data from the original table if it is changed from last process      
    and all other data will be taken from already processed data */      
AS                      
BEGIN                  
    SET NOCOUNT ON;      
      
 DECLARE @ChartTypeId int, @ChartTypeIdPurRMActual int;  
  SELECT  @ChartTypeId=22, @ChartTypeIdPurRMActual=12;   
  
 DECLARE @CurDate datetime;      
  SET @CurDate = getdate();          
            
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */        
    DECLARE @ShiftStart datetime;        
  SELECT @ShiftStart=ShiftStart From vw_DD_KPI_ShiftStart;         
              
    DECLARE @Finyear varchar(15);                  
                  
    /* Period Start End */                  
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                    
            
    If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)        
  BEGIN        
   SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' ' + Convert(varchar(8), @ShiftStart, 108);                  
  END        
    Else        
  BEGIN        
   SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' ' + Convert(varchar(8), @ShiftStart, 108);                     
  END  
  
    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';      
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);  
  
    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));        
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                    
          
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                  
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                              
           
    Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))      
    From DD_KPI_HolidayMaster      
    Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID      
          
    Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1      
    From DD_KPI_HolidayMaster      
    Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID  
      
    /*Select @CompletedDays=Count(*)  
    From  
    (  
        Select DateAdd(day,1,FromDate) +  ' ' + Convert(Varchar(8), @ShiftStart,108)  as DayEnd, *   
        From fn_COM_PeriodSplit(@MonthStart, Convert(varchar(10),@DayStart,120), 'D', '', 0, '0') a  
        Where Not Exists  
        (  
            Select *  
            From DD_KPI_HolidayMaster s  
            Where s.HolidayDate=a.FromDate and s.BranchID=@BranchID and s.CompID=@CompID  
        )  
    )a  
    Where DayEnd<=@AsOnDate  */  
             
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                                      
  SET @YearLabelCount=12;    /* No. of months in a Year */                  
  SET @MonthLabelCount=@MonthWorkingDays;                   
  SET @DayLabelCount=@TotalShiftHours;                      
      
 DECLARE @YearPeriodType Char(2), @MonthPeriodType Char(2), @DayPeriodType Char(2)  
  SELECT @YearPeriodType='YR', @MonthPeriodType='MN', @DayPeriodType='DY'  
                             
 DECLARE @YearTarget money, @YearPlan money, @YearPlanTillMonth money, @YearAchieved money, @YearVarianceAllowedPerc decimal(5, 2), @YearVarianceAllowed money,                     
   @MonthTarget money, @MonthPlan money, @MonthPlanTillDate money, @MonthAchieved money, @MonthVarianceAllowedPerc decimal(5, 2), @MonthVarianceAllowed money,         
   @DayTarget money, @DayPlan money, @DayPlanTillNow money, @DayAchieved money, @DayVarianceAllowedPerc decimal(5, 2), @DayVarianceAllowed money;        
      
 DECLARE @OBValue money, @CBValue money;  
  
 /* Get Allowed Variance Perc */                       
 SELECT @YearVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@YearPeriodType,@BranchID,@CompID),   
   @MonthVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@MonthPeriodType,@BranchID,@CompID),   
   @DayVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@DayPeriodType,@BranchID,@CompID);  
  
     DECLARE @AsOnDateWithoutTime datetime;      
  SET @AsOnDateWithoutTime=Convert(varchar(10), @AsOnDate, 120);      
  
 /***************************** Actual Consumption *****************************/     
  
 DECLARE @PurActualConsumption_Tbl TABLE (PeriodType varchar(2), TargetValue money, PlanValue money, PlanTillPeriodValue money);          
    Insert into @PurActualConsumption_Tbl          
        Select PeriodType, TargetValue, PlanValue, PlanTillPeriodValue       
        From DD_KPI_GaugeChartData a          
        Where a.ChartTypeId=@ChartTypeIdPurRMActual  
            and a.BranchID=@BranchID and a.CompID=@CompID          
   and a.AsOnDate=(Select Max(b.AsOnDate) From DD_KPI_GaugeChartData b           
                            Where b.ChartTypeId=a.ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate          
                                and b.BranchID=a.BranchID and b.CompID=a.CompID          
                            )        
  
 /* Year */   
 Select @YearTarget=a.TargetValue, @YearPlan=a.PlanValue, @YearPlanTillMonth=a.PlanTillPeriodValue  
 From @PurActualConsumption_Tbl a  
 Where a.PeriodType=@YearPeriodType  
     
 /* Month */    
 Select @MonthTarget=a.TargetValue, @MonthPlan=a.PlanValue, @MonthPlanTillDate=a.PlanTillPeriodValue  
 From @PurActualConsumption_Tbl a  
 Where a.PeriodType=@MonthPeriodType  
       
 /* Day */    
 Select @DayTarget=a.TargetValue, @DayPlan=a.PlanValue, @DayPlanTillNow=a.PlanTillPeriodValue  
 From @PurActualConsumption_Tbl a  
 Where a.PeriodType=@DayPeriodType  
  
    /***************************** Purchase Amount From FAS *****************************/            
    /*  
    DECLARE @PurchaseAmountFromFAS_Tbl TABLE (DocDate datetime, PurchaseAmount money)     
 Insert into @PurchaseAmountFromFAS_Tbl    
     Select DocDate, Sum(DrAmt-CrAmt) as PurchaseAmount  
        From FAS_VoucherTranSub a  
        Inner Join FAS_LedgerMaster_AuthTbl b  
            On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode  
        Where Left(b.LrRoute,2) in ('0D') and a.DocDate between @YearStart and Convert(Varchar(10),@AsOnDate,121) and a.CompCode=(@CompID+@BranchID)  
        Group by DocDate  
  
 /* Day Purchase Amount */       
 Select @DayAchieved=Sum(PurchaseAmount)  
 From @PurchaseAmountFromFAS_Tbl a  
 Where DocDate between Convert(Varchar(10),@DayStart,121) and  Convert(Varchar(10),@AsOnDate,121)  
   
 /* Month Purchase Amount */       
 Select @MonthAchieved=Sum(PurchaseAmount)  
 From @PurchaseAmountFromFAS_Tbl a  
 Where DocDate between @MonthStart and Convert(Varchar(10),@AsOnDate,121)  
   
 /* Year Purchase Amount */       
 Select @YearAchieved=Sum(PurchaseAmount)  
 From @PurchaseAmountFromFAS_Tbl a  
 Where DocDate between @YearStart and Convert(Varchar(10),@AsOnDate,121)  
    */  
  
    /* Day */        
    Select @DayAchieved=isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId, '0D', @AsOnDateWithoutTime, @AsOnDateWithoutTime, (@CompID+@BranchID)), 0);    
      
    /* Month */      
    Select @MonthAchieved=isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId, '0D', @MonthStart, @AsOnDateWithoutTime, (@CompID+@BranchID)), 0);       
      
    /* Year */      
    Select @YearAchieved=isNull(dbo.fn_DD_KPI_FASReports(@ChartTypeId, '0D', @YearStart, @AsOnDateWithoutTime, (@CompID+@BranchID)), 0);   
  
    /**********************************************************************************/     
  
    /* Allowed Variance */                
 Select @YearVarianceAllowed=@YearVarianceAllowedPerc*@YearPlanTillMonth,      
   @MonthVarianceAllowed=@MonthVarianceAllowedPerc*@MonthPlanTillDate,          
   @DayVarianceAllowed=@DayVarianceAllowedPerc*@DayPlanTillNow        
                 
 If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate)                
  Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate      
      
 Insert into DD_KPI_GaugeChartData      
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @DayPeriodType as PeriodType, isNull(@DayTarget, 0) as TargetValue,   
   isNull(@DayPlan, 0) as PlanValue, isNull(@DayPlanTillNow, 0) as PlanTillPeriodValue, isNull(@DayAchieved, 0) as AchievedValue,     
   isNull(@DayAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.    
   isNull(@DayVarianceAllowed, 0) as AllowVariance, isNull((@DayPlanTillNow-@DayAchieved), 0) as Variance,      
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp      
        
  Union All      
          
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @MonthPeriodType as PeriodType, isNull(@MonthTarget, 0) as TargetValue,       
   isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthPlanTillDate, 0) as PlanTillPeriodValue, isNull(@MonthAchieved, 0) as AchievedValue,     
   isNull(@MonthAchieved, 0) as AchievedValue2, -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.    
   isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthPlanTillDate-@MonthAchieved), 0) as Variance,   
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp      
      
  Union All      
          
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, isNull(@YearTarget, 0) as TargetValue,       
   isNull(@YearPlan, 0) as PlanValue, isNull(@YearPlanTillMonth, 0) as PlanTillPeriodValue, isNull(@YearAchieved, 0) as AchievedValue,     
   isNull(@YearAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.    
   isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearPlanTillMonth-@YearAchieved), 0) as Variance,   
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp                      
END
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_PurchaseVsSalesContribution_ChartData_Ins]    Script Date: 17/06/2026 11:29:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[DD_KPI_PurchaseVsSalesContribution_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))      
/* Process Current Date, Current Month, Current Year Data from the original table if it is changed from last process    
    and all other data will be taken from already processed data */    
AS                    
BEGIN                
    SET NOCOUNT ON;    
    
	DECLARE @ChartTypeId int, @ChartTypeIdSalesContribution int;         
		SET @ChartTypeId=10; /* From Table ChartTypeMaster */    
		SET @ChartTypeIdSalesContribution=2;          

	DECLARE @CurDate datetime;    
		SET @CurDate = getdate();        
          
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */      
    DECLARE @ShiftStart datetime;      
		SET @ShiftStart='06:00';      
            
    DECLARE @Finyear varchar(15);                
                
    /* Period Start End */                
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                  
          
    If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)      
		BEGIN      
			SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' 06:00';          
		END      
    Else      
		BEGIN      
			SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' 06:00';           
		END

    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';    
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);

    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));      
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                  
        
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                            
         
    Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))    
    From DD_KPI_HolidayMaster    
    Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID    
        
    Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1    
    From DD_KPI_HolidayMaster    
    Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID    
           
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                                    
		SET @YearLabelCount=12;    /* No. of months in a Year */                
		SET @MonthLabelCount=@MonthWorkingDays;                 
		SET @DayLabelCount=@TotalShiftHours;                    
    
	DECLARE @YearPeriodType Char(2), @MonthPeriodType Char(2), @DayPeriodType Char(2)
		SELECT @YearPeriodType='YR', @MonthPeriodType='MN', @DayPeriodType='DY'
		                         
	DECLARE @YearTarget money, @YearTargetPerc decimal(5, 2), @YearPlan money, @YearPlanTillMonth money, @YearAchieved money, @YearVarianceAllowedPerc decimal(5, 2), @YearVarianceAllowed money,                   
			@MonthTarget money, @MonthTargetPerc decimal(5, 2), @MonthPlan money, @MonthPlanTillDate money, @MonthAchieved money, @MonthVarianceAllowedPerc decimal(5, 2), @MonthVarianceAllowed money,                   
			@DayTarget money, @DayTargetPerc decimal(5, 2), @DayPlan money, @DayPlanTillNow money, @DayAchieved money, @DayVarianceAllowedPerc decimal(5, 2), @DayVarianceAllowed money;      
    
	/* Get Target Perc */                     
	SELECT @YearTargetPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'Target',@YearPeriodType,@BranchID,@CompID), 
			@MonthTargetPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'Target',@MonthPeriodType,@BranchID,@CompID), 
			@DayTargetPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'Target',@DayPeriodType,@BranchID,@CompID);

	/* Get Allowed Variance Perc */                     
	SELECT @YearVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@YearPeriodType,@BranchID,@CompID), 
			@MonthVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@MonthPeriodType,@BranchID,@CompID), 
			@DayVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@DayPeriodType,@BranchID,@CompID);

	/***************************** Sales Contribution *****************************/   
    DECLARE @SalesContribution_Tbl TABLE (PeriodType varchar(2), TargetValue money, PlanValue money, AchievedValue money);        
    Insert into @SalesContribution_Tbl        
        Select PeriodType, TargetValue, PlanValue, AchievedValue      
        From DD_KPI_GaugeChartData a        
        Where a.ChartTypeId=@ChartTypeIdSalesContribution        
            and a.BranchID=@BranchID and a.CompID=@CompID        
			and a.AsOnDate=(Select Max(b.AsOnDate) From DD_KPI_GaugeChartData b         
                            Where b.ChartTypeId=a.ChartTypeId and b.PeriodType=a.PeriodType and b.AsOnDate<=@AsOnDate        
                                and b.BranchID=a.BranchID and b.CompID=a.CompID        
                            )        
							
	Select @YearTarget=(TargetValue-(@YearTargetPerc*TargetValue)), @YearPlan=(PlanValue-(@YearTargetPerc*PlanValue)), @YearPlanTillMonth=(AchievedValue-(@YearTargetPerc*AchievedValue))
    From @SalesContribution_Tbl a        
    Where a.PeriodType=@YearPeriodType       
        
    Select @MonthTarget=(TargetValue-(@MonthTargetPerc*TargetValue)), @MonthPlan=(PlanValue-(@MonthTargetPerc*PlanValue)), @MonthPlanTillDate=(AchievedValue-(@MonthTargetPerc*AchievedValue))
    From @SalesContribution_Tbl a        
    Where a.PeriodType=@MonthPeriodType  
      
    Select @DayTarget=(TargetValue-(@DayTargetPerc*TargetValue)), @DayPlan=(PlanValue-(@DayTargetPerc*PlanValue)), @DayPlanTillNow=(AchievedValue-(@DayTargetPerc*AchievedValue))
    From @SalesContribution_Tbl a        
    Where a.PeriodType=@DayPeriodType   

	/***************************** Purchase From FAS *****************************/   						 
	DECLARE @PurchaseAmount_Tbl TABLE (DocDate datetime, PurAmount money)   
	Insert into @PurchaseAmount_Tbl  
		Select DocDate, Sum(DrAmt-CrAmt) as PurAmount
		From FAS_VoucherTranSub a
		Inner Join FAS_LedgerMaster_AuthTbl b
			On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode
		Where b.LrRoute like '0D%' and a.DocDate between @YearStart and Convert(Varchar(10),@AsOnDate,121) and a.CompCode=(@CompID+@BranchID)
		Group by DocDate

	/* Day Purchase Amount */     
	Select @DayAchieved=Sum(PurAmount)
	From @PurchaseAmount_Tbl a
	Where DocDate between Convert(Varchar(10),@DayStart,121) and  Convert(Varchar(10),@AsOnDate,121)
	
	/* Month Purchase Amount */     
	Select @MonthAchieved=Sum(PurAmount)
	From @PurchaseAmount_Tbl a
	Where DocDate between @MonthStart and  Convert(Varchar(10),@AsOnDate,121)
	
	/* Year Purchase Amount */     
	Select @YearAchieved=Sum(PurAmount)
	From @PurchaseAmount_Tbl a
	Where DocDate between @YearStart and  Convert(Varchar(10),@AsOnDate,121)


    /* Allowed Variance */              
	Select @YearVarianceAllowed=@YearVarianceAllowedPerc*@YearPlanTillMonth,              
			@MonthVarianceAllowed=@MonthVarianceAllowedPerc*@MonthPlanTillDate,        
			@DayVarianceAllowed=@DayVarianceAllowedPerc*@DayPlanTillNow      
			            
	If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate)              
		Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate    
    
	Insert into DD_KPI_GaugeChartData    
		Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @DayPeriodType as PeriodType, isNull(@DayTarget, 0) as TargetValue, 
			isNull(@DayPlan, 0) as PlanValue, isNull(@DayPlanTillNow, 0) as PlanTillPeriodValue, isNull(@DayAchieved, 0) as AchievedValue,   
			isNull(@DayAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.  
			isNull(@DayVarianceAllowed, 0) as AllowVariance, isNull((@DayPlanTillNow-@DayAchieved), 0) as Variance,    
			@BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp    
      
		Union All    
        
		Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @MonthPeriodType as PeriodType, isNull(@MonthTarget, 0) as TargetValue,     
			isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthPlanTillDate, 0) as PlanTillPeriodValue, isNull(@MonthAchieved, 0) as AchievedValue,   
			isNull(@MonthAchieved, 0) as AchievedValue2, -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.  
			isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthPlanTillDate-@MonthAchieved), 0) as Variance, 
			@BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp    
    
		Union All    
        
		Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, isNull(@YearTarget, 0) as TargetValue,     
			isNull(@YearPlan, 0) as PlanValue, isNull(@YearPlanTillMonth, 0) as PlanTillPeriodValue, isNull(@YearAchieved, 0) as AchievedValue,   
			isNull(@YearAchieved, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.  
			isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearPlanTillMonth-@YearAchieved), 0) as Variance, 
			@BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp    
              
END    
  



GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_ReportData_Ins]    Script Date: 17/06/2026 11:29:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_ReportData_Ins](@PeriodType char(2), @ChartType int, @FromDate datetime, @ToDate datetime, @BranchID varchar(3), @CompID varchar(3))    
As              
BEGIN              
    SET NOCOUNT ON;              
                
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */                              
    DECLARE @ShiftStart datetime;                              
        SET @ShiftStart='06:00';        
    
    IF(@PeriodType ='MN')   /* Month Report */        
        BEGIN   
            Declare @MonthStartDate datetime, @MonthEndDate datetime;  
                Select @MonthStartDate = Convert(Varchar(7),@FromDate,121) + '-01'  
                Select @MonthEndDate = DateAdd(day,-1,DateAdd(month,1,@MonthStartDate))  
  
            Delete From DD_KPI_ReportData   
            Where ChartTypeId=@ChartType and PeriodType=@PeriodType                        
                    and AsOnDate >= @MonthStartDate and AsOnDate<=@MonthEndDate                     
                    and BranchID=@BranchID and CompID=@CompID     
    
            IF (@ChartType=3 OR @ChartType=11 OR @ChartType=20 OR @ChartType=21 OR  @ChartType=22 OR  @ChartType=23)         -- FAS Related Reports  
                BEGIN  
                    Insert into DD_KPI_ReportData    
                        Select @ChartType, b.StartDate as AsOnDate, @PeriodType,     
                            Floor(a.TargetValue) as TargetValue, Floor(a.PlanValue) as PlanValue, Floor(a.AchievedValue) as AchievedValue,    
                            @BranchId, @CompId, getdate() as Transtamp    
                        From DD_KPI_GaugeChartData a                         
                        Inner Join                             
                        (                      
                            Select Convert(Varchar(10), AsOnDate, 120) as StartDate, Max(AsOnDate) as MaxAsOnDate                      
                            From DD_KPI_GaugeChartData                      
                            Where ChartTypeId=@ChartType and PeriodType='DY'                        
                                and Convert(Varchar(10),AsOnDate,120)>=@FromDate and Convert(Varchar(10),AsOnDate,120)<=@ToDate                     
                                and BranchID=@BranchID and CompID=@CompID                        
                            Group by Convert(Varchar(10), AsOnDate,120)                
                        )b            
                            On a.AsOnDate=b.MaxAsOnDate                             
                        Where a.ChartTypeId=@ChartType and a.PeriodType='DY' and Convert(Varchar(10),a.AsOnDate,120)>=@FromDate  and Convert(Varchar(10),a.AsOnDate,120)<=@ToDate                      
                            and a.BranchID=@BranchID and a.CompID=@CompID                           
                        Order by b.StartDate      
                END  
  
            ELSE  
                BEGIN  
  
                    ;With ChartData_CTE                      
                    As                      
                    (                      
                        Select Case When Convert(varchar(8), a.AsOnDate, 108)<=@ShiftStart            
                                        Then Convert(varchar(10), DateAdd(day, -1, a.AsOnDate), 120) + ' ' + @ShiftStart   
                                        Else Convert(varchar(10), a.AsOnDate, 120) + ' ' + @ShiftStart End as ShiftAsOnDate,                       
                            AsOnDate, ChartTypeId, PeriodType, Floor(TargetValue) as TargetValue, Floor(PlanValue) as PlanValue,             
                            Floor(PlanTillPeriodValue) as PlanTillPeriodValue, Floor(AchievedValue) as AchievedValue, Floor(Variance) as Variance       
                        From DD_KPI_GaugeChartData  a                      
                        where a.PeriodType='DY' and a.ChartTypeId=@ChartType   
                            and a.AsOnDate> Convert(varchar(10), @MonthStartDate, 120) + ' ' + @ShiftStart and Convert(Varchar(10),a.AsOnDate,121)<=@MonthEndDate                    
  
                        Union All  
  
                        Select Convert(datetime,Convert(varchar(10), a.AsOnDate, 121)) as ShiftAsOnDate, AsOnDate, ChartTypeId, 'DY' as PeriodType, 0 as TargetValue, 0 as PlanValue,   
                            0 as PlanTillPeriodValue, Floor(a.AchievedValue) as AchievedValue, Floor(Variance) as Variance   
                        From DD_KPI_GaugeChartData a         
                        Where a.ChartTypeId=@ChartType and a.PeriodType='MN' and Convert(Varchar(10),a.AsOnDate,120)>=@MonthStartDate and a.AsOnDate<= Convert(varchar(10), @MonthStartDate, 120) + ' ' + @ShiftStart                      
                            and a.BranchID=@BranchID and a.CompID=@CompID                          
                            and a.AsOnDate = (Select Max(s.AsOnDate) From DD_KPI_GaugeChartData s   
                                                Where s.ChartTypeId=a.ChartTypeId and s.PeriodType=a.PeriodType   
                                                and Convert(Varchar(10),s.AsOnDate,120)>=@MonthStartDate  and s.AsOnDate<=Convert(varchar(10), @MonthStartDate, 120) + ' ' + @ShiftStart)  
                    )     
     
                    Insert into DD_KPI_ReportData    
                        Select @ChartType, Convert(Varchar(10), a.ShiftAsOnDate,121) as AsOnDate, @PeriodType,    
                            Floor(Sum(a.TargetValue)) as TargetValue, Floor(Sum(a.PlanValue)) as PlanValue, Floor(Sum(a.AchievedValue)) as AchievedValue,    
                            @BranchId, @CompId, getdate() as Transtamp   
                        From ChartData_CTE a                      
                        Inner Join                       
                        (                      
                            Select ShiftAsOnDate,  Max(AsOnDate) as MaxAsOnDate                      
                            From ChartData_CTE                      
                            Group by ShiftAsOnDate                      
                        )b                      
                            On a.AsOnDate=b.MaxAsOnDate  
                        Where a.ShiftAsOnDate>=@MonthStartDate  
                        Group by Convert(Varchar(10), a.ShiftAsOnDate,121)  
                        Order by 1   
                          
               END                
        END        
                      
    ELSE IF(@PeriodType ='YR')  /* Year Report */        
        BEGIN      
            Delete From DD_KPI_ReportData Where ChartTypeId=@ChartType and PeriodType=@PeriodType                        
                        and Convert(Varchar(10),AsOnDate,120)>=@FromDate and Convert(Varchar(10),AsOnDate,120)<=@ToDate                     
                        and BranchID=@BranchID and CompID=@CompID     
    
            Insert into DD_KPI_ReportData    
                Select @ChartType, b.YearMonth as AsOnDate, @PeriodType,     
                    Floor(a.TargetValue) as TargetValue, Floor(a.PlanValue) as PlanValue, Floor(a.AchievedValue) as AchievedValue,    
                    @BranchId, @CompId, getdate() as Transtamp    
                From DD_KPI_GaugeChartData a                         
                Inner Join                             
                (                      
                    Select Convert(Varchar(7), AsOnDate, 120) + '-01' as YearMonth, Max(AsOnDate) as MaxAsOnDate                      
                    From DD_KPI_GaugeChartData                      
                    Where ChartTypeId=@ChartType and PeriodType='MN'                        
                        and Convert(Varchar(10),AsOnDate,120)>=@FromDate and Convert(Varchar(10),AsOnDate,120)<=@ToDate                     
                        and BranchID=@BranchID and CompID=@CompID                        
                    Group by Convert(Varchar(7), AsOnDate,120)        
                )b            
                    On a.AsOnDate=b.MaxAsOnDate                             
                Where a.ChartTypeId=@ChartType and a.PeriodType='MN' and Convert(Varchar(10),a.AsOnDate,120)>=@FromDate  and Convert(Varchar(10),a.AsOnDate,120)<=@ToDate                      
                    and a.BranchID=@BranchID and a.CompID=@CompID                           
                Order by b.YearMonth                    
        END      
END  
  
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_ReportData_Ins_ForFAS]    Script Date: 17/06/2026 11:29:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_ReportData_Ins_ForFAS](@PeriodType char(2), @ChartType int, @FromDate datetime, @ToDate datetime, @BranchID varchar(3), @CompID varchar(3))    
As              
BEGIN              
    SET NOCOUNT ON;              
  
    DECLARE @CurDate datetime;  
     Select @CurDate = getdate();  
  
    DECLARE @CurDateWithOutTime datetime;  
        Select @CurDateWithOutTime = CONVERT(VARCHAR(10),@CurDate,121)  
  
    DECLARE @LrRoute Varchar(42), @MultiplyValue int; 
		set @LrRoute='';
		set @MultiplyValue = 1;
	 
        IF @ChartType=11            --DIRECT EXPENSES  
            Select @LrRoute = '05', @MultiplyValue=1  
        ELSE IF @ChartType=20       --INDIRECT EXPENSES  
             Select @LrRoute = '07', @MultiplyValue=1    
        ELSE IF @ChartType=21       --SALES VALUE FROM FINANCE  
            Select @LrRoute = '0E', @MultiplyValue=-1   
        ELSE IF @ChartType=22       --PURCHASE VALUE FROM FINANCE         
             Select @LrRoute = '0D', @MultiplyValue=1     
        ELSE IF @ChartType=3       --NET PROFIT  
             Select @LrRoute = '', @MultiplyValue=-1     
        ELSE IF @ChartType=23       --GROSS PROFIT  
             Select @LrRoute = '', @MultiplyValue=-1     
  
    --DECLARE @TblAchieved TABLE (DocDate datetime, AchievedValue money)  
    --    Insert into @TblAchieved    
    --        Select DocDate, Sum(DrAmt-CrAmt) as AchievedValue  
    --        From FAS_VoucherTranSub a  
    --        Inner Join FAS_LedgerMaster_AuthTbl b  
    --            On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode  
    --        Where Left(b.LrRoute,2) in (@LrRoute) and a.DocDate between @FromDate and Convert(Varchar(10),@ToDate,121) and a.CompCode=(@CompID+@BranchID)  
    --        Group by DocDate  
  
    IF(@PeriodType ='MN')   /* Month Report */        
        BEGIN   
            DECLARE @MonthStartDate datetime, @MonthEndDate datetime;  
                Select @MonthStartDate = Convert(Varchar(7),@FromDate,121) + '-01'  
                Select @MonthEndDate = DateAdd(day,-1,DateAdd(month,1,@MonthStartDate))  
  
            Delete From DD_KPI_ReportData   
            Where ChartTypeId=@ChartType and PeriodType=@PeriodType                        
                    and AsOnDate >= @MonthStartDate and AsOnDate<=@MonthEndDate                     
                    and BranchID=@BranchID and CompID=@CompID     
  
            Insert into DD_KPI_ReportData    
                Select @ChartType, b.StartDate as AsOnDate, @PeriodType,     
                    Floor(a.TargetValue) as TargetValue, Floor(a.PlanValue) as PlanValue, Floor(IsNull(c.AchievedValue,0))*@MultiplyValue as AchievedValue,   
                        --Floor(a.AchievedValue) as AchievedValue,    
                    @BranchId, @CompId, getdate() as Transtamp    
                From DD_KPI_GaugeChartData a                         
                Inner Join                             
                    (                      
                        Select Convert(Varchar(10), AsOnDate, 120) as StartDate, Max(AsOnDate) as MaxAsOnDate                      
                        From DD_KPI_GaugeChartData                      
                        Where ChartTypeId=@ChartType and PeriodType='DY'                        
                            and Convert(Varchar(10),AsOnDate,120)>=@FromDate and Convert(Varchar(10),AsOnDate,120)<=@ToDate                     
                            and BranchID=@BranchID and CompID=@CompID                        
                        Group by Convert(Varchar(10), AsOnDate,120)                
                    )b            
                    On a.AsOnDate=b.MaxAsOnDate      
                --Left Outer Join @TblAchieved c  
                --    On b.StartDate=c.DocDate             
                Outer Apply  
                    (  
                        Select isNull(dbo.fn_DD_KPI_FASReports(@ChartType, @LrRoute, b.StartDate, b.StartDate, @CompID+@BranchID), 0) as AchievedValue     
                    )c                         
    Where a.ChartTypeId=@ChartType and a.PeriodType='DY' and Convert(Varchar(10),a.AsOnDate,120)>=@FromDate  and Convert(Varchar(10),a.AsOnDate,120)<=@ToDate                      
            and a.BranchID=@BranchID and a.CompID=@CompID                           
                Order by b.StartDate      
        END           
       
    ELSE IF(@PeriodType ='YR')  /* Year Report */        
   BEGIN      
            Delete From DD_KPI_ReportData   
            Where ChartTypeId=@ChartType and PeriodType=@PeriodType                        
                        and Convert(Varchar(10),AsOnDate,120)>=@FromDate and Convert(Varchar(10),AsOnDate,120)<=@ToDate         
                        and BranchID=@BranchID and CompID=@CompID     
    
            Insert into DD_KPI_ReportData    
                Select @ChartType, b.YearMonth as AsOnDate, @PeriodType,     
                    Floor(a.TargetValue) as TargetValue, Floor(a.PlanValue) as PlanValue, Floor(IsNull(c.AchievedValue,0))*@MultiplyValue as AchievedValue,  --Floor(a.AchievedValue) as AchievedValue,    
                    @BranchId, @CompId, getdate() as Transtamp    
                From DD_KPI_GaugeChartData a                         
                Inner Join                             
                    (                      
                        Select Convert(Varchar(7), AsOnDate, 120) + '-01' as YearMonth, Max(AsOnDate) as MaxAsOnDate                      
                        From DD_KPI_GaugeChartData                      
                        Where ChartTypeId=@ChartType and PeriodType='MN'                        
                            and Convert(Varchar(10),AsOnDate,120)>=@FromDate and Convert(Varchar(10),AsOnDate,120)<=@ToDate                     
                            and BranchID=@BranchID and CompID=@CompID                        
                        Group by Convert(Varchar(7), AsOnDate,120)        
                    )b            
                    On a.AsOnDate=b.MaxAsOnDate  
                --Left Outer Join   
                --    (  
                --        Select Convert(Varchar(7), DocDate, 120) + '-01' as YearMonth, Sum(AchievedValue) as AchievedValue   
                --        From @TblAchieved   
                --        Group by Convert(Varchar(7), DocDate, 120)   
                --    )c  
                --    On b.YearMonth=c.YearMonth    
                 Outer Apply  
                    (  
                        Select isNull(dbo.fn_DD_KPI_FASReports(@ChartType, @LrRoute, b.YearMonth,   
                                Case When DateAdd(day,-1,DateAdd(month,1,b.YearMonth))>@CurDateWithOutTime Then @CurDateWithOutTime Else DateAdd(day,-1,DateAdd(month,1,b.YearMonth)) End, @CompID+@BranchID), 0) as AchievedValue     
                    )c                                
                Where a.ChartTypeId=@ChartType and a.PeriodType='MN' and Convert(Varchar(10),a.AsOnDate,120)>=@FromDate  and Convert(Varchar(10),a.AsOnDate,120)<=@ToDate                      
                    and a.BranchID=@BranchID and a.CompID=@CompID                           
                Order by b.YearMonth                    
        END      
END  
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_Rpt_Details_Get]    Script Date: 17/06/2026 11:29:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_Rpt_Details_Get](@PeriodType char(2), @ChartType int, @FromDate datetime, @ToDate datetime, @BranchID varchar(3), @CompID varchar(3), @isForceInsert bit=0)          
As                    
BEGIN                    
    SET NOCOUNT ON;                    
  
    Declare @CurDate datetime ;
	Set  @CurDate = getdate();  
          
    IF (@isForceInsert='1' OR     
            Exists (Select * From DD_KPI_GaugeChartData a     
                    Where a.ChartTypeId=@ChartType and Convert(Varchar(10),a.AsOnDate,121)> @fromDate and  Convert(Varchar(10),a.AsOnDate,121)<=@ToDate    
                        and a.AsOnDate>isNull((Select Max(Transtamp) From DD_KPI_ReportData b    
                                        Where b.ChartTypeId=@ChartType and b.PeriodType=@PeriodType and Convert(Varchar(10),b.AsOnDate,121)>@fromDate and  Convert(Varchar(10),b.AsOnDate,121)<=@ToDate    
                                    ), '1900-01-01')    
                )   
            OR (Convert(Varchar(7),@CurDate,121)>Convert(Varchar(7),@FromDate,121))         
        )    
    --If Not Exists (Select * From DD_KPI_ReportData a where a.PeriodType=@PeriodType and a.ChartTypeId=@ChartType and a.AsOnDate > @fromDate and  a.AsOnDate<=@ToDate)              
    BEGIN              
          
        IF (@ChartType=11 OR @ChartType=20 OR @ChartType=21 OR @ChartType=22 OR @ChartType=23 OR @ChartType=3)  --DIRECT EXPENSES, INDIRECT EXPENSES, SALES FROM FAS, PURCHASE FROM FAS, GROSS PROFIT, NET PROFIT    
            BEGIN  
                Execute DD_KPI_ReportData_Ins_ForFAS @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID      
            END  
        ELSE  
            BEGIN  
                /* Insert from GaugeChart_Data Table to DD_KPI_ReportData Table */     
                Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID      
            END         
        /*  
        if (@ChartType=1) /* SALES VALUE */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=2) /* SALES CONTRIBUTION */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=3) /* NET PROFIT */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=4) /* NEW COMPLAINTS */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=5) /* PENDING COMPLAINTS */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=6) /* REPEATED COMPLAINTS */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=7) /* SALES RETURN */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=8) /* CUSTOMER END PPM */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=9) /* FG RECEIPT VALUE */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=10) /* PURCHASE RM THEORITICAL CONSUMPTION */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=11) /* DIRECT AND INDIRECT EXPENSES */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=12) /* PURCHASE RM ACTUAL CONSUMPTION */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=13) /* FG STOCK VALUE */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=14) /* PRODUCTION VALUE */         
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=15) /* COST OF POOR QUALITY */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=16) /* INPROCESS PPM */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID            
        else if (@ChartType=17) /* PRODUCTION CONTRIBUTION */            
            Execute DD_KPI_ReportData_Ins @PeriodType, @ChartType, @FromDate, @ToDate, @BranchID, @CompID     
        */         
    END          
              
    Select       
        CASE WHEN @PeriodType='YR' THEN Convert(varchar(7),a.AsOnDate,120)       
        ELSE  Convert(varchar(10),a.AsOnDate,120) END as AsOnDate,     
        a.TargetValue, a.PlanValue,           
        CASE WHEN a.TargetValue<=0 THEN 0 ELSE (a.TargetValue-a.PlanValue) END as PlanShortage_Against_Target,          
        a.AchievedValue,          
        CASE WHEN a.PlanValue<=0 THEN 0 ELSE (a.PlanValue-a.AchievedValue) END as Shortage_Against_Plan,          
        CASE WHEN a.TargetValue<=0 THEN 0 ELSE (a.TargetValue-a.AchievedValue) END as Shortage_Against_Target -- , @FromDate, @ToDate          
    From DD_KPI_ReportData  a                            
    Where a.ChartTypeId=@ChartType and a.PeriodType=@PeriodType           
        and (a.AsOnDate>=@FromDate and  a.AsOnDate<=@ToDate)          
        and a.BranchID=@BranchID and a.CompID=@CompID          
    Order By 1            
                         
END
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_SalesContributionValue_ChartData_Ins]    Script Date: 17/06/2026 11:29:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[DD_KPI_SalesContributionValue_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))              
AS                            
BEGIN                        
    SET NOCOUNT ON;                  
               
 DECLARE @ChartTypeId int, @ChartTypeIdSalesValue int;              
  SET @ChartTypeId=2; /* From Table ChartTypeMaster */                    
  SET @ChartTypeIdSalesValue = 1;            
            
 DECLARE @CurDate datetime            
  Select @CurDate = getdate();            
                  
 /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */              
 DECLARE @ShiftStart datetime;              
  SET @ShiftStart='06:00';              
                     
 DECLARE @Finyear varchar(15);                        
                        
 /* Period Start End */                        
 DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                          
                  
 If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)              
  BEGIN              
   SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' 06:00';              
   --SET @MonthStart=Convert(varchar(7), DateAdd(day, -1, @AsOnDate), 120) + '-01';              
   --SET @Finyear=dbo.fn_COM_Get_Finyear(DateAdd(day, -1, @AsOnDate));              
  END              
 Else              
  BEGIN              
   SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' 06:00';              
   --SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';              
   --SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);              
  END              
          
    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';              
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);           
              
 SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));              
 SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                     
              
 DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                      
  SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                                
                 
 Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))              
 From DD_KPI_HolidayMaster              
 Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID             
              
 Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1              
 From DD_KPI_HolidayMaster              
 Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID              
            
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                          
    DECLARE  @MonthTarget money,  @YearTarget money ,  @DayTarget money;                          
                          
    SET @YearLabelCount=12;    /* No. of months in a Year */                      
    SET @MonthLabelCount=@MonthWorkingDays;                       
    SET @DayLabelCount=@TotalShiftHours;                          
                                    
 DECLARE @YearPlan money, @YearPlanTillMonth money, @YearSales money, @YearVarianceAllowedPerc decimal(5, 2), @YearVarianceAllowed money,                         
   @MonthPlan money, @MonthPlanTillDate money, @MonthSales money, @MonthVarianceAllowedPerc decimal(5, 2), @MonthVarianceAllowed money,                         
   @DayPlan money, @DayPlanTillNow money, @DaySales money, @DayVarianceAllowedPerc decimal(5, 2), @DayVarianceAllowed money;                        
                
 DECLARE @YearPeriodType Char(2), @MonthPeriodType Char(2), @DayPeriodType Char(2)          
  SELECT @YearPeriodType='YR', @MonthPeriodType='MN', @DayPeriodType='DY'          
                    
 --SELECT @YearVarianceAllowedPerc=5.0/100.0, @MonthVarianceAllowedPerc=5.0/100.0, @DayVarianceAllowedPerc=5.0/100.0;                     
 SELECT @YearVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@YearPeriodType,@BranchID,@CompID),           
   @MonthVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@MonthPeriodType,@BranchID,@CompID),           
   @DayVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@DayPeriodType,@BranchID,@CompID)          
               
 /* Sales Plan List */                
 DECLARE @SalesPlan_Tbl TABLE (PlanFor int, PlanPeriod datetime, CustomerCode int, ItemCode varchar(20), PlanQty money);                
  Insert into @SalesPlan_Tbl                
   Select PlanFor, PlanPeriod, CustomerCode, ItemCode, PlanQty                
   From fn_SAL_SalesPlan_Dtl_v2(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear)                
   Where PlanPeriod Between @MonthStart and @MonthEnd              
                 
 /* Raw Material Cost & Norms */                
 DECLARE @ItemRMList TABLE (ItemCode varchar(20), RMRate money);                
 ;WITH Child_CTE                
 AS                
  (                
   Select distinct d.ItemCode, Case When d.ChildCode='' Then c.ItemCode Else d.ChildCode End as ChildCode,                
   --Case When d.ChildCode='' Then c.PQty Else 1 End as RMNorms                
    Case When d.ChildCode='' Then c.Qty Else 1 End as RMNorms                
   From                 
    (                
     Select Distinct ItemCode, ChildCode             
     From                
     (                
      Select ItemCode, Case When (ItemCode = '20520150T0' and PlanPeriod >= '2017-07-01') Then ItemCode Else '' End as ChildCode                
      From @SalesPlan_Tbl                
                
      UNION ALL                
                
      Select ItemCode, Case When (ItemCode = '20520150T0' and InvoiceDate >= '2017-07-01') Then ItemCode Else '' End as ChildCode                
      From SalesInvoice a                
      Where /*a.InvoiceDate<=@AsOnDate*/              
      ((Convert(varchar(10), a.InvoiceDate, 120)+ ' ' + Convert(varchar(8), a.InvoiceTime, 108)) BETWEEN @MonthStart and @AsOnDate)              
      and a.Type In ('OE', 'Labour', 'VAT', 'EOU') and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear                 
     ) b                
    ) d                
	--Outer Apply fn_BOM_ExplodableItems(d.ItemCode,'C',@BranchID,@CompID) c                
    
	Outer Apply   
	(  
        Select distinct o.ItemCode, o.Qty   
        From fn_BOM_GetBottomMostChild(d.ItemCode,@BranchId, @CompId) o    
    )c   
			                      
  )                
 , ChildRate_CTE                
 AS                
 (                
  Select ChildCode, dbo.fn_COM_ItemRate_Pur(m.ChildCode, 3, @YearStart, @AsOnDate, 0, @AsonDate, @AsonDate, @BranchId, @CompId, @FinYear) as RMRate                
  From                
   (                
    Select distinct ChildCode               
    From Child_CTE                
   ) m                
 )                
                
 INSERT INTO @ItemRMList                
  Select j.ItemCode, SUM(IsNull(j.RMNorms,0)*IsNull(k.RMRate,0))                
  From Child_CTE j                
  Left Outer Join ChildRate_CTE k                
  On j.ChildCode=k.ChildCode                
  Group By j.ItemCode                
            
 /* Day Sales */                        
 Select @DayPlan=Sum(PlanQty*(Rate-RMRate)), @DaySales=Sum(InvoiceValue)     --Sum(InvoiceQty*(Rate-RMRate))                
 From                        
  (                        
   Select isNull(a.CustomerCode, b.CustomerCode) as CustomerCode, isNull(a.ItemCode, b.ItemCode) as ItemCode,                         
    IsNull(a.PlanQty,0) as PlanQty, IsNull(b.InvoiceValue,0) as InvoiceValue,                         
    isNull(b.Rate, dbo.fn_SAL_Item_Rate(a.ItemCode, a.CustomerCode, '', 0, Null, @BranchID, @CompID, @Finyear))as Rate,                
    isNull(a.RMRate, b.RMRate) as RMRate                         From                        
    (                        
     Select a.CustomerCode, a.ItemCode, Sum(PlanQty) as PlanQty, b.RMRate                      
     From @SalesPlan_Tbl a                
     Left Outer Join  @ItemRMList b                 
      On a.ItemCode=b.ItemCode           
     Where a.PlanFor=4 and a.PlanPeriod=Convert(varchar(10), @DayStart, 120)            
     Group by a.CustomerCode, a.ItemCode, b.RMRate                        
    )a                        
   Full Outer Join                        
    (                        
     Select a.CustomerCode, a.ItemCode, Sum(InvoiceQty*(Rate-b.RMRate)) as InvoiceValue, AVG(Rate) as Rate, b.RMRate                        
     From SalesInvoice a                
     Left Outer Join  @ItemRMList b                 
      On a.ItemCode=b.ItemCode                        
     Where ((Convert(varchar(10),InvoiceDate, 120)+ ' ' + Convert(varchar(8),InvoiceTime, 108)) BETWEEN @DayStart and @AsOnDate)                      
      and Type In ('OE', 'Labour', 'VAT', 'EOU') and BranchID=@BranchID and CompID=@CompID and Finyear = @Finyear                          
     Group by a.CustomerCode, a.ItemCode, b.RMRate                        
    )b                        
   On a.CustomerCode=b.CustomerCode and a.ItemCode=b.ItemCode                        
  )a               
            
 /* Since Hourly Plan not available DayPlanTillNow calculated on prorate basis */                          
    SET @DayPlanTillNow=(@DayPlan * DateDiff(minute, @DayStart, @AsOnDate))/DateDiff(minute, @DayStart, @DayEnd)                 
            
             
 /* Month Sales */                        
 Declare @MonthPlanSales money, @tmpMonthPlan  money, @tmpMonthPlanTillDate money, @tmpMonthSales money;            
            
 Select @MonthPlan=Sum(PlanQty*(Rate-RMRate)),                 
   @MonthPlanTillDate=Sum(PlanQtyTillDate*(Rate-RMRate)),                 
   @MonthSales=Sum(InvoiceValue), --Sum(InvoiceQty*(Rate-RMRate)),              
   @MonthPlanSales=Sum(PlanQty*Rate),             
              
   @tmpMonthPlan=Sum(PlanQty*(Rate)),                 
   @tmpMonthPlanTillDate=Sum(PlanQtyTillDate*(Rate)),                 
   @tmpMonthSales=Sum(InvoiceValue)                 
                           
 From                        
  (                        
   Select isNull(a.CustomerCode, b.CustomerCode) as CustomerCode, isNull(a.ItemCode, b.ItemCode) as ItemCode,                         
    IsNull((a.PlanQty*@CompletedDays)/@MonthWorkingDays,0) as PlanQtyTillDate, IsNull(a.PlanQty,0) as PlanQty, IsNull(b.InvoiceValue,0) as InvoiceValue,              
    isNull(b.Rate, dbo.fn_SAL_Item_Rate(a.ItemCode, a.CustomerCode, '', 0, Null, @BranchID, @CompID, @Finyear))as Rate,                 
    isNull(a.RMRate, b.RMRate) as RMRate                
   From                        
    (                        
     Select a.CustomerCode, a.ItemCode, Sum(a.PlanQty) as PlanQty,              
      /*Sum(Case When a.PlanFor=4 and a.PlanPeriod <= @DayStart Then a.PlanQty Else 0 End) as PlanQtyTillDate,                 
      Sum(Case When a.PlanFor=2 Then a.PlanQty Else 0 End) as PlanQty,*/ b.RMRate                        
     From @SalesPlan_Tbl a                 
     Left Outer Join  @ItemRMList b                 
      On a.ItemCode=b.ItemCode                       
     Where a.PlanFor=2 and (a.PlanPeriod between @MonthStart and @MonthEnd)                                       
     Group by a.CustomerCode, a.ItemCode, b.RMRate                        
    )a                        
   Full Outer Join                        
    (                 
     Select a.CustomerCode, a.ItemCode, Sum(InvoiceQty*(Rate-b.RMRate)) as InvoiceValue,  AVG(Rate) as Rate, b.RMRate                        
     From SalesInvoice a                
     Left Outer Join  @ItemRMList b                 
      On a.ItemCode=b.ItemCode                        
     Where ((Convert(varchar(10),InvoiceDate, 120)+ ' ' + Convert(varchar(8),InvoiceTime, 108)) BETWEEN @MonthStart and @AsOnDate)                        
      and Type In ('OE', 'Labour', 'VAT', 'EOU') and BranchID=@BranchID and CompID=@CompID and Finyear = @Finyear                          
     Group by a.CustomerCode, a.ItemCode, b.RMRate                        
    )b                        
    On a.CustomerCode=b.CustomerCode and a.ItemCode=b.ItemCode                        
  )a             
                
 /* Year Sales */               
 Select @YearPlan=Sum(YearPlan),  @YearPlanTillMonth=Sum(YearPlanTillMonth), @YearSales=Sum(YearSales)              
 From              
  (              
   Select @MonthPlan as YearPlan,  @MonthPlanTillDate as YearPlanTillMonth,  @MonthSales as YearSales              
                  
   Union All              
              
   /* Year Sales (From Digital Data Table) */              
   Select IsNull(Sum(PlanValue),0) as YearPlanValue,            
    IsNull(Sum(PlanValue),0) as YearPlanTillValue, IsNull(Sum(AchievedValue),0) as YearSalesValue              
   From DD_KPI_GaugeChartData a              
   Inner Join                   
    (            
     Select Convert(Varchar(7), AsOnDate,120) as YearMonth, Max(AsOnDate) as AsOnDate            
     From DD_KPI_GaugeChartData            
     Where ChartTypeId=@ChartTypeId and PeriodType=@MonthPeriodType              
      and Convert(Varchar(10),AsOnDate,120)<@MonthStart and Convert(Varchar(10),AsOnDate,120)>@YearStart             
      and BranchID=@BranchID and CompID=@CompID              
     Group by  Convert(Varchar(7), AsOnDate,120)            
    )b            
    On a.AsOnDate=b.AsOnDate                                
   Where a.ChartTypeId=@ChartTypeId and a.PeriodType=@MonthPeriodType and a.BranchID=@BranchID and a.CompID=@CompID              
   and Convert(Varchar(10),a.AsOnDate,120)<@MonthStart  and Convert(Varchar(10),a.AsOnDate,120)>@YearStart                      
  )a             
            
 Declare @YearPlanSalesValue money,  @YearTargetSalesValue money;            
            
 Select @YearPlanSalesValue=IsNull(PlanValue,0), @YearTargetSalesValue=TargetValue            
 From DD_KPI_GaugeChartData a            
 Where ChartTypeId=@ChartTypeIdSalesValue and PeriodType=@YearPeriodType and BranchID=@BranchID and CompID=@CompID             
  and AsOnDate=           
   (          
    Select Max(AsOnDate) From DD_KPI_GaugeChartData s             
    Where s.ChartTypeId=a.ChartTypeId and s.PeriodType=a.PeriodType             
     and s.AsOnDate<=@AsOnDate and s.BranchID=a.BranchID and s.CompID=a.CompID            
   )            
            
 /* Allowed Variance */                        
 Select @YearVarianceAllowed=@YearVarianceAllowedPerc*@YearPlanTillMonth,                        
   @MonthVarianceAllowed=@MonthVarianceAllowedPerc*@MonthPlanTillDate,                  
   @DayVarianceAllowed=@DayVarianceAllowedPerc*@DayPlanTillNow                      
             
 SET @YearTarget= (@YearPlan*(@YearTargetSalesValue/@YearPlanSalesValue));              
 SET @MonthTarget= (@YearTarget/12.0);              
 SET @DayTarget= (@MonthTarget/@MonthWorkingDays);          
            
 If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate)                        
  Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate              
              
 Insert into DD_KPI_GaugeChartData              
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @DayPeriodType as PeriodType, isNull(@DayTarget, 0) as TargetValue, isNull(@DayPlan, 0) as PlanValue,               
   isNull(@DayPlanTillNow, 0) as PlanTillPeriodValue, isNull(@DaySales, 0) as AchievedValue,             
   isNull(@DaySales, 0) as AchievedValue2,    -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.            
   isNull(@DayVarianceAllowed, 0) as AllowVariance,  isNull((@DayPlanTillNow-@DaySales), 0) as Variance,              
   @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp              
                
  Union All              
                  
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @MonthPeriodType as PeriodType, isNull(@MonthTarget, 0) as TargetValue,               
   isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthPlanTillDate, 0) as PlanTillPeriodValue, isNull(@MonthSales, 0) as AchievedValue,             
   isNull(@MonthSales, 0) as AchievedValue2,   -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.            
   isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthPlanTillDate-@MonthSales), 0) as Variance, @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp              
              
  Union All              
                  
  Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, isNull(@YearTarget, 0) as TargetValue,               
   isNull(@YearPlan, 0) as PlanValue, isNull(@YearPlanTillMonth, 0) as PlanTillPeriodValue, isNull(@YearSales, 0) as AchievedValue,             
   isNull(@YearSales, 0) as AchievedValue2,   -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.            
   isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearPlanTillMonth-@YearSales), 0) as Variance, @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp                    
END              
        
GO

/****** Object:  StoredProcedure [dbo].[DD_KPI_SalesQty_ChartData_Ins]    Script Date: 17/06/2026 11:29:57 ******/
SET ANSI_NULLS ON
GO

