CREATE PROCEDURE [dbo].[DES_INS_ITEMWISEMACHINEWISECYCLETIME]
	(@ItemCode 		[varchar](20),
	 @MachineCode 	[varchar](20),
	 @CycleTime		[float],
	 @OperationCost 	[float],
	 @SettingTime	 	[float],
	 @Priority 		[int],
	 @Userid 		[varchar](10),
	 @Branchid		[varchar](3),
	 @Compid		[varchar](3))

AS 
BEGIN
SET NOCOUNT ON

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		delete from DES_ItemwiseMachinewiseCycleTime where ItemCode = @ItemCode and MachineCode = @MachineCode and Branchid = @cBranchid  and Compid = @compid

		INSERT INTO  [DES_ItemwiseMachinewiseCycleTime] 
			 ( [ItemCode],
			 [MachineCode],
			 [CycleTime],
			 [OperationCost],
			 [SettingTime],
			 [Priority],
			 [Userid],
			 [Branchid],
			 [Compid]) 
		 
		VALUES 
			( @ItemCode,
			 @MachineCode,
			 @CycleTime,
			 @OperationCost,
			 @SettingTime,
			 @Priority,
			 @Userid,
			 @cBranchid,
			 @Compid)
		
		FETCH NEXT FROM BranchidList into @cBranchid 
	END
 	
	close BranchidList
	deallocate BranchidList
END
GO

