/****** Object:  Stored Procedure dbo.FAM_Dis_AssetModify    Script Date: 05/06/2006 3:04:37 PM ******/
CREATE PROCEDURE [dbo].[Fam_Dis_AssetModify] (@AssetCode varchar(10), @ItemCode Varchar(20), @BranchID varchar(3), @CompID varchar(3), @CmCode char(4))

AS

Begin
	SET NOCOUNT ON


	Select a.AssetCode, a.ItemCode, a.LocationCode, 

		(Select CompanyName From Company_Master Where CompID = a.LocationCode and BranchID = a.BranchID and CompID = a.CompID)LocationName,  a.DivisionCode, 
		
		(Select DivisionDescript From Fam_Division_Master Where DivisionCode = a.DivisionCode and BranchID = a.BranchID and CompID = a.CompID)DivisionName, a.SubDivisionCode, 
		
		(Select SubDivisionDescript from Fam_SubDivision_Master  Where SubDivisionCode = a.SubDivisionCode and BranchID = a.BranchID and CompID = a.CompID)SubDivisionName,  a.ClassificationCode, 
				
		b.ClassificationDescript, a.SubClassificationCode, b.SubClassDescript,  a.SupplierCode, 
		
		(Select PartyName From Fas_Party_Master Where PartyCode = a.SupplierCode and BranchID = a.BranchID and CompID = a.CompID) SupplierName, a.BankCode, 
		
		(Select LedgerName From Fas_LedgerMaster Where Ledgercode = a.BankCode and CompCode = @CmCode)LedgerName, 
		
		a.PJVType, a.PJVNo, a.PJVDate,   a.InvoiceNo, a.InvoiceDate, a.PurchaseOrderType, a.PurchaseOrderNo, a.PurchaseOrderDate, a.CurrencyCode, 

		(Select TName From Fam_Currency_Master  Where  Code = a.CurrencyCode and BranchID = a.BranchID and CompID = a.CompID)CurrencyName, 
	
		a.ExchangeRate, a.Amount, a.IsFreight, a.IsInterest, a.IsInsurance, a.IsAdditional, a.IsDuty, a.IsInstallation,

		a.Freight, a.Interest, a.Insurance, a.Additional, a.Duty, a.InstallationCharge, 

		Case a.IsValue When 'V' Then 'Value' Else 'Percentage' End as IsValue, 
		
		a.ValueAmt, a.OpBalance, a.BookValue, a.MarketValue, a.DeliveryDate, a.DutyRefNo, a.PolicyNo, 
	
		Case a.Status When '1' Then 'Active' Else 'InActive' End As Status, 
	
		Case a.IsWithRR When '0' Then 'WithOutRR' Else 'WithRR' End as IsWithRR, a.Remarks,
		(Select LedgerName From FAS_LedgerMaster Where LedgerCode = b.CreditAccCode and Left(LrRoute, 2) = '09'  and CompCode = @CmCode
		and isActive = 1) CreditAccName,
		(Select LedgerName From FAS_LedgerMaster Where LedgerCode = b.DebitAccCode and Left(LrRoute, 2) = '07'  and CompCode = @CmCode
		and isActive = 1) DebitAccName
		
	From FAM_Asset_Master  a
		
		Left Outer Join FAM_AssetClassification_Master b
		On b.ClassificationCode = a.ClassificationCode and b.BranchID = a.BranchID and b.CompID = a.CompID


	Where a.AssetCode = @AssetCode and a.ItemCode = @ItemCode and a.BranchID = @BranchID and a.CompID =  @CompID


End
GO

