/****** Object:  StoredProcedure [dbo].[FAS_Budget_Dis_Ledgers]    Script Date: 17/06/2026 11:29:58 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Budget_Dis_Ledgers] (@RptEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12))

 AS

Begin
	Set NOCOUNT ON	
	
	Select LedgerCode, LrRoute,  LedgerName as Ledgers 
	from FAS_Budget_LedgerMaster a
	where CompCode=@CmCode and (OpBalance<>0 OR 
								Exists (Select * from dbo.fn_FAS_Budget_VoucherTranSub_UpTo(@RptEnd, @ActualsCutOff, @CmCode) b 
										Where b.LrCode=a.LedgerCode and b.CompCode=a.CompCode))
	Order by LedgerName
End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Budget_Dis_Monthwise_Ledgers]    Script Date: 17/06/2026 11:29:58 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Budget_Dis_Monthwise_Ledgers] (@LrCode int, @PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12)) 

AS

Begin

	Set NoCount On

	Select @LrCode as LrCode, Mncode, DMonth as [AcMonth], r.Debit, r.Credit, 
		r.Closing_Balance
	From 
		 (Select j.MnCode,  Datename(month, convert(datetime, Convert(varchar, j.MnCode)+'01', 112 )) as DMonth, 

				j.DrAmt as Debit, j.CrAmt as Credit,
				(Case sign(isNull(j.CB, 0))  When  0 then ' '  When 1 then Convert(varchar, CB) + ' Dr'else Convert(varchar, -CB) + ' Cr' end) as Closing_Balance
		From
			(Select h.Mncode,  Sum(h.DrAmt) as DrAmt, Sum(h.CrAmt) as CrAmt,  
				dbo.fn_FAS_Budget_LedgerOpBalance(@LrCode, DateAdd(mm, 1, Convert(datetime, h.MnCode+'01', 112)), @ActualsCutOff, '0', @CmCode) as CB
					/*	(Select Sum(DrAmt-CrAmt) from FAS_VoucherTranSub m Where  LrCode=@LrCode and m.CompCode =@CmCode 
						and (m.DocDate between @PrStart and @PrEnd) and Convert(varchar(6), m.DocDate, 112) <= h.MnCode) as CB */
			From 
				(Select h1.MnCode, h2.DrAmt, h2.CrAmt
				From

					(Select Convert(varchar(6), Monthdate, 112) MnCode from dbo.fn_FAS_Months(@PrStart, @PrEnd)) h1 
				Left Outer Join
					(Select Convert(varchar(6), Docdate, 112) MnCode, Sum(DrAmt) as DrAmt, Sum(CrAmt) as CrAmt 
					From dbo.fn_FAS_Budget_VoucherTranSub_Period_Lr(@LrCode, @PrStart, @PrEnd, @ActualsCutOff, @CmCode) c 
					Group by Convert(varchar(6), Docdate, 112)
					) h2
				On h1.MnCode=h2.MnCode
				) h
			Group by MnCode
			) j
		)r
	Order by MnCode
End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Budget_Dis_Monthwise_Voucher]    Script Date: 17/06/2026 11:29:58 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Budget_Dis_Monthwise_Voucher] (@Route varchar(42), @PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12)) 

AS

Begin

	Set NoCount On

	Declare @Debit varchar(1), @LnRoute int
	Set @Debit =' '
	Set @LnRoute=Len(@Route)	


	Select @Route as Route, MnCode, AcMonth, r.TranAmt, r.Cum_Total
	from 
		 (Select j.MnCode,  Datename(month, convert(datetime, Convert(varchar, j.MnCode)+'01', 112 )) as AcMonth,  Case When isNull(j.TranAmt, 0) = 0 then ' ' else Convert(varchar, j.TranAmt)  end as TranAmt,
				(Case when sign(isNull(j.CB, 0)) = 0 then ' ' else Convert(varchar, CB) end) as Cum_Total
		from
			(Select h.Mncode, Sum(h.Amount) as TranAmt,  
						(Select Sum(DrAmt) 
						From dbo.fn_FAS_VoucherTranSub_Period_VrSub(@Route, @PrStart, @PrEnd, @ActualsCutOff, @CmCode) m 
						Where Convert(varchar(6), m.DocDate, 112) <= h.MnCode
						) as CB
			from 
				(Select h1.MnCode, h2.Amount
				from
					(Select Convert(varchar(6), Monthdate, 112) MnCode from dbo.fn_FAS_Months(@PrStart, @PrEnd)) h1 
				Left Outer Join
					(Select Convert(varchar(6), Docdate, 112) MnCode, Sum(DrAmt) as Amount 
					From dbo.fn_FAS_VoucherTranSub_Period_VrSub(@Route, @PrStart, @PrEnd, @ActualsCutOff, @CmCode) c 
					Group by Convert(varchar(6), Docdate, 112)
					) h2
				On h1.MnCode=h2.MnCode
			    ) h
			group by MnCode
			) j
		)r
	Order by MnCode
End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Budget_Dis_MonthwiseCnt_Voucher]    Script Date: 17/06/2026 11:29:58 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Budget_Dis_MonthwiseCnt_Voucher] (@Route varchar(42), @PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12)) 

AS

Begin 
	
		Set NoCount On

		If @Route='07'
			Begin	
				Select @Route as Route,  h1.MnCode,  Datename(month, convert(datetime, Convert(varchar, h1.MnCode)+'01', 112 )) as AcMonth,
						IsNull(Convert(Varchar(5), h2.Cnt), '') as TranCount 
						From (Select Convert(varchar(6), Monthdate, 112) MnCode from dbo.fn_FAS_Months(@PrStart, @PrEnd)) h1 
				Left Outer Join
						(Select Count(distinct DocNo) as Cnt, Convert(varchar(6), Docdate, 112) MnCode from FAS_MEM_VoucherTranMast c 
							Where (c.DocDate between @PrStart and @PrEnd) and CompCode = @CmCode
							Group by Convert(varchar(6), Docdate, 112)
						) h2
				On h1.MnCode=h2.MnCode
				Order by h1.MnCode
			End
		Else
			Begin	
				Select @Route as Route,  h1.MnCode,  Datename(month, convert(datetime, Convert(varchar, h1.MnCode)+'01', 112 )) as AcMonth,
						IsNull(Convert(Varchar(5), h2.Cnt), '') as TranCount 
						From (Select Convert(varchar(6), Monthdate, 112) MnCode from dbo.fn_FAS_Months(@PrStart, @PrEnd)) h1 
				Left Outer Join
						(Select Count(distinct DocNo) as Cnt, Convert(varchar(6), Docdate, 112) MnCode 
						From dbo.fn_FAS_Budget_VoucherTranMast_Period_Vr(@Route, @PrStart, @PrEnd, @ActualsCutOff, @CmCode) c 
							Group by Convert(varchar(6), DocDate, 112)
						) h2
				On h1.MnCode=h2.MnCode
				Order by h1.MnCode
			End
End
GO

