CREATE PROCEDURE [dbo].[FAS_Budget_Dis_Vouchers] (@PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12))

AS

Begin
	Set NOCOUNT ON	


	Select a.VoucherCode, a.VrRoute+a.VrWidth as Path, a.VoucherName as [Voucher Types],  Count(b.DocNo) as [No. of Vouchers]	
	From FAS_Budget_VoucherMaster a
	Left Outer Join dbo.fn_FAS_Budget_VoucherTranMast_Period(@PrStart, @PrEnd, @ActualsCutOff, @CmCode) b
		On a.VrRoute+a.VrWidth = b.VrRoute
	Where a.CompCode= @CmCode
	Group by a.VoucherCode, a.VrRoute+a.VrWidth, a.VoucherName

	UNION ALL

	Select 7, '07', 'MEMORANDUM', Count(DocNo) 
	From FAS_MEM_VoucherTranMast
	Where CompCode=@CmCode and (DocDate Between @PrStart and @PrEnd)


	Order by 2

End
GO

