CREATE PROCEDURE [dbo].[FAS_Budget_Dtl_Fil]  (@VrRoute varchar(42), @PlanFor tinyint, @FrmDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @CmCode Varchar(12))

As

SET NOCOUNT ON

	Begin
 
		Select b.PlanPeriod, b.PlanDate, b.DrCode, IsNull(d.LedgerName, '') As DrName, b.CrCode, 
				IsNull(c.LedgerName,'') As CrName, b.Amount, IsNull(b.Narration,'') As Narration, b.IsLocked 
		From FAS_Budget_Dtl b 
		Left Outer Join FAS_Budget_LedgerMaster d 
		  On b.DrCode='L'+Convert(varchar, d.LedgerCode) and b.CompCode=d.CompCode
		Left Outer Join FAS_Budget_LedgerMaster c 
		  On b.CrCode='L'+Convert(varchar, c.LedgerCode) and b.CompCode=c.CompCode
		Where b.VrRoute=@VrRoute and (b.DrCode Like 'L%' and b.CrCode Like 'L%') and b.PlanFor=@PlanFor
				and b.PlanDate Between @FrmDate and @ToDate and b.CompCode=@CmCode
				
		Order By b.PlanDate, DrName, CrName

	End
GO

