CREATE PROCEDURE [dbo].[FAS_Budget_Purchase_Consolidate] (@Fromdate datetime, @Todate datetime, @AsOndate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))


AS



		Select VendorCode, PostingAc, Sum(PlanQty*Rate) Purchase
			From (
				Select a.VendorCode, a.ItemCode, a.RequiredDate as PlanPeriod, isNull(a.ScheduleQty, 0) PlanQty,  b.PostingAccount as PostingAc,
					isNull(dbo.fn_Pur_Item_Rate(a.ItemCode, VendorCode, a.OrderType, a.OrderNo, a.OrderDate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear), 0) as Rate 
				From dbo.fn_PUR_Schedule_Period(@Fromdate, @Todate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear)a
				Left Outer Join dbo.fn_BOM_Material_Others('A', @AsOndate, @AsOndate, @BranchID, @CompID) b
					On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
				Where a.RequiredDate Between @Fromdate and @Todate and a.Status not in ('C') and a.BranchID=@BranchID and a.CompID=@CompID
			)x
		Group By VendorCode, PostingAc		
		Order By VendorCode
GO

/****** Object:  StoredProcedure [dbo].[FAS_Budget_Purchase_Splitup]    Script Date: 17/06/2026 11:29:58 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Budget_Purchase_Splitup] (@SplitUpFor Char(1), @Fromdate datetime, @Todate datetime, @AsOndate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))


AS

		Declare @SplitValue as int

		If @SplitUpFor='M'  ---Month
			Select @SplitValue=2
		else
			If @SplitUpFor='W' --Week
				Select @SplitValue=3
			Else                         --Day
				Select @SplitValue=4


		
		IF @SplitValue='2' /* Month */

			Select VendorCode, PostingAc,  Convert(varchar(7), PlanPeriod, 120) as PlanPeriod, Sum(PlanQty*Rate) PurchaseValue
				From (
					Select a.VendorCode, a.ItemCode, a.RequiredDate as PlanPeriod, isNull(a.ScheduleQty, 0) PlanQty, b.PostingAccount as PostingAc,
						isNull(dbo.fn_Pur_Item_Rate(a.ItemCode, VendorCode, a.OrderType, a.OrderNo, a.OrderDate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear), 0) as Rate 
					From dbo.fn_PUR_Schedule_Period(@Fromdate, @Todate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear)a 
					Left Outer Join dbo.fn_BOM_Material_Others('A', @AsOndate, @AsOndate, @BranchID, @CompID) b
						On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
					Where a.RequiredDate Between @Fromdate and @Todate and a.Status not in ('C') and a.BranchID=@BranchID and a.CompID=@CompID
					)x
				Group By Convert(varchar(7), PlanPeriod, 120), VendorCode, PostingAc
				Order By Convert(varchar(7), PlanPeriod, 120), VendorCode


		IF @SplitValue='3' /*  Week  */

			Select VendorCode,  PostingAc, 
					Case When Day(PlanPeriod) between 1 and 7 Then Convert(varchar(7), PlanPeriod, 120) + '-01'
					When Day(PlanPeriod) between 8 and 14 Then Convert(varchar(7), PlanPeriod, 120) + '-08'
					When Day(PlanPeriod) between 15 and 21 Then Convert(varchar(7), PlanPeriod, 120) + '-15'
					Else Convert(varchar(7), PlanPeriod, 120) + '-22' End as PlanPeriod, 
					Sum(PlanQty*Rate) PurchaseValue
				From (
						Select a.VendorCode, a.ItemCode, a.RequiredDate as PlanPeriod, isNull(a.ScheduleQty, 0) PlanQty, b.PostingAccount as PostingAc,
						isNull(dbo.fn_Pur_Item_Rate(a.ItemCode, VendorCode, a.OrderType, a.OrderNo, a.OrderDate,@AsOndate, @AsOndate, @BranchID, @CompID, @Finyear), 0) as Rate 
						From dbo.fn_PUR_Schedule_Period(@Fromdate, @Todate,@AsOndate, @AsOndate, @BranchID, @CompID, @Finyear)a
						Left Outer Join	dbo.fn_BOM_Material_Others('A', @AsOndate, @AsOndate, @BranchID, @CompID) b
							On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID					
						Where a.RequiredDate Between @Fromdate and @Todate and a.Status not in ('C') and a.BranchID=@BranchID and a.CompID=@CompID
					)x
			Group By VendorCode, PlanPeriod,  PostingAc
			Order By PlanPeriod,  VendorCode


/*
			Select VendorCode, DatePart(wk, PlanPeriod)  as PlanPeriod, Sum(PlanQty*Rate) PurchaseValue
				From (
					Select a.VendorCode, a.ItemCode, a.RequiredDate as PlanPeriod, isNull(a.ScheduleQty, 0) PlanQty,
						isNull(dbo.fn_Pur_Item_Rate(ItemCode, VendorCode, a.OrderType, a.OrderNo, a.OrderDate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear), 0) as Rate 
					From dbo.fn_PUR_Schedule(@AsOndate, @AsOndate, @BranchID, @CompID, @Finyear)a
					Where a.RequiredDate Between @Fromdate and @Todate and a.Status not in ('C') and a.BranchID=@BranchID and a.CompID=@CompID
					)x
				Group By DatePart(wk, PlanPeriod),  VendorCode
				Order By DatePart(wk, PlanPeriod),  VendorCode
*/			


		IF @SplitValue='4' /*  Day  */

			Select VendorCode, PostingAc,  PlanPeriod, Sum(PlanQty*Rate) PurchaseValue
				From (
					Select a.VendorCode, a.ItemCode, a.RequiredDate as PlanPeriod, isNull(a.ScheduleQty, 0) PlanQty, b.PostingAccount as PostingAc,
						isNull(dbo.fn_Pur_Item_Rate(a.ItemCode, VendorCode, a.OrderType, a.OrderNo, a.OrderDate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear), 0) as Rate 
					From dbo.fn_PUR_Schedule_Period(@Fromdate, @Todate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear) a
					Left Outer Join	dbo.fn_BOM_Material_Others('A', @AsOndate, @AsOndate, @BranchID, @CompID) b
						On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID		
					Where a.RequiredDate Between @Fromdate and @Todate and a.Status not in ('C') and a.BranchID=@BranchID and a.CompID=@CompID
					)x
				Group By VendorCode, PlanPeriod, PostingAc
				Order By  VendorCode, PlanPeriod
GO

/****** Object:  StoredProcedure [dbo].[FAS_Budget_Rpt_BRS]    Script Date: 17/06/2026 11:29:58 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Budget_Rpt_BRS] (@UserKey varchar(36), @RptDate datetime,  @PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12))

AS

BEGIN

	SET NOCOUNT ON	

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)


	Select c.LrCode, a.ChqNo, Case c.DrAmt When 0 then a.ChqDate Else b.DocDate End  as CDate, Case c.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
			Case c.DrAmt When 0 Then Convert(varchar, isNull(c.CrAmt, 0)) Else  Convert(varchar, isNull(c.DrAmt, 0)) End as Amount,
			Case a.isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 								
					Else a.ChqFavor End as ChqFavor, a.DocNo, a.VrRoute, b.DocDate
	from FAS_VoucherTranPay a 
	Left Outer Join dbo.fn_FAS_Budget_VoucherTranMast_UpTo(@RptDate, @ActualsCutOff, @CmCode) b
		On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
				Left Outer Join dbo.fn_FAS_Budget_VoucherTranSub_UpTo(@RptDate, @ActualsCutOff, @CmCode) c
				On c.DocNo=a.DocNo and a.DocDate=c.DocDate and c.VrRoute=a.VrRoute and c.CompCode=a.CompCode
	Where c.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
	 and a.CompCode=@CmCode and (a.BankDate is Null or a.BankDate >@RptDate)
	
	
	Union All
	
	Select '' LrCode, a.ChqNo, a.ChqDate, Case a.isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType, Convert(varchar, a.ChqAmount) as Amount,
			Case a.isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 
				Else a.ChqFavor End as ChqFavor, 
			a.DocNo, a.VrRoute, a.ChqDate	
		from FAS_VoucherTranPay a
	Where VrRoute like 'OpBal-%' and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6)) in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
	and CompCode=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate)	
	
	Order by PayType Desc, CDate, Amount


END
GO

/****** Object:  StoredProcedure [dbo].[FAS_Budget_Rpt_BRS_Book]    Script Date: 17/06/2026 11:29:58 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Budget_Rpt_BRS_Book] (@UserKey varchar(36), @RptDate datetime,  @PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12))

AS

BEGIN

	SET NOCOUNT ON	

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)	

	Select 'OB' as ChqType, ' ' as PayType, isNull(Sum(Amount), 0) as Amount 
	from (
		Select (Sum(DrAmt)-Sum(CrAmt)) as Amount  
		from dbo.fn_FAS_Budget_VoucherTranSub_UpTo(@RptDate, @ActualsCutOff, @CmCode)
		where LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)

		Union All 

		Select OpBalance from FAS_LedgerMaster 
		where LedgerCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
			and CompCode=@CmCode
	       ) a

	Union All

	Select 'NotCleared' ChqType, PayType, isNull(Sum(Amount) , 0)
	from (
		Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
			Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else   isNull(b.DrAmt, 0) End as Amount
		from FAS_VoucherTranPay a 
		Left Outer Join dbo.fn_FAS_Budget_VoucherTranSub_UpTo(@RptDate, @ActualsCutOff, @CmCode) b 
		On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
		Where b.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID 
								and CompId = @CompID)
		and a.CompCode=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate)
	
		Union All

		Select Case isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType, ChqAmount as Amount
		from FAS_VoucherTranPay
		Where VrRoute in (Select 'OpBal-'+Convert(varchar, SelectInt) From Com_SelectList 
					Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID) 
		and CompCode=@CmCode and (BankDate is Null or BankDate > @RptDate)
	) x 
	Group by PayType
	
	Union All
	
	Select 'Cleared' ChqType, PayType, isNull(Sum(Amount) , 0)
	from (
		Select Case R.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
			Case R.DrAmt When 0 Then  isNull(R.CrAmt, 0) Else   isNull(R.DrAmt, 0) End as Amount
		From dbo.fn_FAS_Budget_VoucherTranSub_UpTo(@RptDate, @ActualsCutOff, @CmCode) R 
		Left Outer Join FAS_VoucherTranPay a 
			On R.DocNo=a.DocNo and R.DocDate=a.DocDate and R.VrRoute=a.VrRoute and R.CompCode=a.CompCode and a.BankDate is Not NULL
		Where R.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
		 and a.CompCode=@CmCode and  a.BankDate <= @RptDate
	
		Union All
	
		Select Case isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType,  ChqAmount as Amount
		from FAS_VoucherTranPay
		Where VrRoute in (Select 'OpBal-'+Convert(varchar, SelectInt) From Com_SelectList 
						Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
		 and CompCode=@CmCode and (BankDate is Not Null AND BankDate <= @RptDate)
	) x 

	Group by PayType
	Order by 1 desc, 2 desc

END
GO

