CREATE PROCEDURE [dbo].[FAS_Budget_Rpt_DB_0] (@UserKey varchar(36), @VrRoute varchar(42), @Start as datetime, @End as datetime, @PrStart as datetime, @PrEnd as datetime, @ActualsCutOff datetime, @CmCode as varchar(12))

 AS

Begin
	SET NOCOUNT ON

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	SELECT a.DocDate, a.DocNo, b.VTSNo, b.LrCode, d.LrRoute as Ledger_Route, d.LedgerName,  c.VoucherName,  a.VrRoute as Voucher_Route, 
		Convert(varchar, isNull(b.DrAmt, 0)) as DrAmt, Convert(varchar, isNull(b.CrAmt, 0)) as CrAmt, Narration
	From dbo.fn_FAS_VoucherTranMast_Period_Vr(@VrRoute, @Start, @End, @CmCode) a
	Left Outer Join dbo.fn_FAS_VoucherTranSub_Period_Vr(@VrRoute, @Start, @End, @CmCode) b
		On a.VrRoute=b.VrRoute and a.DocDate=b.DocDate and a.DocNo=b.DocNo and a.CompCode=b.CompCode
	Left Outer Join FAS_Budget_VoucherMaster c
		On a.VrRoute=c.VrRoute+c.VrWidth and a.CompCode=c.CompCode
	Left Outer Join FAS_Budget_LedgerMaster d
		On b.LrCode=d.LedgerCode and a.CompCode=d.CompCode
	Where DocNo in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
	order by DocDate, Voucher_Route, DocNo, VTSNo

End
GO

