CREATE PROCEDURE [dbo].[FAS_Budget_Rpt_Dy_0] (@UserKey varchar(36), @VrRoute varchar(42), @Start datetime, @End datetime, @PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12))

AS

Begin

	SET NOCOUNT ON	
	
	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)
	
	Select a.VrRoute, a.DocDate as [Date], Case a.isCancelled When 0 then d.LedgerName Else 'CANCELLED' End as Particulars,
		c.VoucherName as [Voucher Type], a.DocNo as [Voucher No], Convert(Varchar, a.Amount) as Amount
	From dbo.fn_FAS_VoucherTranMast_Period_Vr(@VrRoute, @Start, @End, @ActualsCutOff, @CmCode) a
	Left Outer Join dbo.fn_FAS_VoucherTranSub_Period_Vr(@VrRoute, @Start, @End, @ActualsCutOff, @CmCode) b
		On a.VrRoute=b.VrRoute and a.DocDate=b.DocDate and a.DocNo=b.DocNo and a.CompCode=b.CompCode and a.VTSNo=1
	Left Outer Join FAS_Budget_VoucherMaster c
		On a.VrRoute=c.VrRoute+c.VrWidth and a.CompCode=c.CompCode
	Left Outer Join FAS_Budget_LedgerMaster d
		On b.LrCode=d.LedgerCode and a.CompCode=d.CompCode
	Where a.DocNo in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID) 
	Order by [Date], [Voucher Type], [Voucher No]
	
End
