CREATE PROCEDURE [dbo].[FAS_Budget_Rpt_Lr_0] (@UserKey varchar(36), @Start as datetime, @End as datetime, @PrStart as datetime, @PrEnd as datetime, @ActualsCutOff as datetime, @CmCode as varchar(12))

 AS

Begin
	SET NOCOUNT ON
	
	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)

	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Select distinct c.DocDate, c.VrRoute as Voucher_Route, c.DocNo, a.FileRef, c.VTSNo, c.LrCode, d.LedgerName, e.VoucherName, 
			Convert(varchar, c.DrAmt) as DrAmt, Convert(varchar, c.CrAmt) as CrAmt, r.BankDate, a.Narration, c.LrCode as LedgerCode
	From dbo.fn_FAS_VoucherTranSub_Period(@Start, @End, @ActualsCutOff, @CmCode) c
	Left Outer Join dbo.fn_FAS_VoucherTranMast_Period(@Start, @End, @ActualsCutOff, @CmCode) a
		On a.DocDate=c.DocDate and a.DocNo=c.DocNo and a.VrRoute=c.VrRoute and a.CompCode=c.CompCode
	Left Outer Join FAS_Budget_LedgerMaster d
		On c.LrCode=d.LedgerCode and c.CompCode=d.CompCode
	Left Outer Join FAS_Budget_VoucherMaster e
		On c.VrRoute=e.VrRoute+e.VrWidth and c.CompCode=e.CompCode
	Left Outer Join FAS_VoucherTranPay r 
		On c.DocNo = r.DocNo and c.DocDate=r.DocDate and c.VrRoute = r.VrRoute and c.CompCode = r.CompCode
	Where c.LrCode in (Select SelectInt From Com_SelectList 
					Where UserKey = @UserKey and BranchId = @BranchId and CompId = @CompId)
	Order by c.LrCode, c.DocDate, c.VrRoute, c.DocNo, c.VTSNO

End
