CREATE PROCEDURE [dbo].[FAS_Budget_Rpt_Lr_1] (@Userkey varchar(36), @Start datetime, @End datetime,  @PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12)) 

AS

Begin

	Set NOCOUNT ON	
	
	Declare @BranchID varchar(2)
	select @BranchId = SubString(@CmCode, 3, 2)

	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Select m.VrRoute as Voucher_Route,  Convert(Varchar(16),  m.DocDate, 105) as Date,  Particulars,  [Voucher Type],  [Voucher No.],  Debit,  Credit,  f.ChqNo , Narration
	from 
	 	(Select c.VrRoute,  c.DocDate, g.LedgerName as Particulars, f.VoucherName as [Voucher Type], 
			c.DocNo as [Voucher No.],  Case When e.DrAmt > 0 then Convert(Varchar, e.DrAmt) Else '' End as Debit, 
			Case When e.CrAmt > 0 then Convert(Varchar, e.CrAmt) Else '' End as Credit, b.Narration, c.CompCode
	
		from dbo.fn_FAS_Budget_VoucherTranSub_Period(@Start, @End, @ActualsCutOff, @CmCode) c
		Inner Join

			(Select min(VTSNo) as MinVTSNo, a.DocNo, a.DocDate, a.VrRoute 
			from dbo.fn_FAS_Budget_VoucherTranSub_Period(@Start, @End, @ActualsCutOff, @CmCode) a 
			Inner Join
				(select m.DocNo, m.DocDate, m.VrRoute 
				from dbo.fn_FAS_Budget_VoucherTranSub_Period(@Start, @End, @ActualsCutOff, @CmCode) m
				where Exists (Select * From Com_SelectList n Where n.UserKey = @Userkey and n.SelectInt=m.LrCode and n.BranchID = @BranchID and n.CompID = @CompID) 
				) b
				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute 
			where Not Exists (Select * From Com_SelectList a2 Where a2.UserKey = @Userkey and a2.SelectInt=a.LrCode and a2.BranchID = @BranchID and a2.CompID = @CompID) 
			Group By a.VrRoute, a.DocDate, a.DocNo 
			) d
			On c.DocNo=d.DocNo and c.DocDate=d.DocDate and c.VrRoute=d.VrRoute and c.VTSNo=d.MinVTSNo 	

		Left Outer Join
			(select m.DocNo, m.DocDate, m.VrRoute, m.DrAmt, m.CrAmt 
			From dbo.fn_FAS_Budget_VoucherTranSub_Period(@Start, @End, @ActualsCutOff, @CmCode) m
			where Exists (Select * From Com_SelectList n Where n.UserKey = @Userkey and n.SelectInt=m.LrCode and n.BranchID = @BranchID and n.CompID = @CompID) 
			) e
			On  c.DocNo=e.DocNo  and c.DocDate=e.DocDate and c.VrRoute=e.VrRoute 
		Left Outer Join dbo.fn_FAS_Budget_VoucherTranMast_Period(@Start, @End, @ActualsCutOff, @CmCode) b
			On c.DocDate=b.DocDate and c.DocNo=b.DocNo and c.VrRoute=b.VrRoute
		Left Outer Join FAS_Budget_VoucherMaster f
			On c.VrRoute=f.VrRoute+f.VrWidth and c.CompCode=f.CompCode
		Left Outer Join FAS_Budget_LedgerMaster g
			On c.LrCode=g.LedgerCode and c.CompCode=g.CompCode		
		 )m

	Left Outer Join FAS_VoucherTranPay f
	On m.[Voucher No.] = f.DocNo and m.DocDate=f.DocDate and m.VrRoute = f.VrRoute and m.CompCode = f.CompCode
	Where  m.CompCode =  @CmCode

	Order by  m.DocDate,  m.VrRoute,  [Voucher No.] 

End
GO

