CREATE PROCEDURE [dbo].[FAS_Budget_Rpt_Lr_2] (@UserKey Varchar(36), @Start datetime, @End datetime, @PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12)) 

AS

Begin

	Set NoCount On

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)


	Select m.VrRoute, p.VoucherName, m.DocNo, m.DocDate, m.FileRef,  m.LrCode, n.LedgerName as Particulars, 
		Case When m.DrAmt > 0 then Convert(Varchar, m.DrAmt) Else '' End as Debit, Case When m.CrAmt > 0 then Convert(Varchar, m.CrAmt) Else '' End as Credit,
		r.ChqNo, r.ChqDate, r.BankDate
	from
		(Select a.DocNo, a.VrRoute, a.DocDate, a.FileRef, a.LrCode, a.DrAmt, a.CrAmt, a.MinVTSNo, b.LrCode as PLrCode
		from
			(select a2.DocNo, a2.VrRoute, a2.DocDate, a.FileRef, a2.LrCode, a2.DrAmt, a2.CrAmt, min(a3.VTSNo) as MinVTSNo
			from dbo.fn_FAS_Budget_VoucherTranSub_Period(@Start, @End, @ActualsCutOff, @CmCode) a2
			Left Outer Join dbo.fn_FAS_Budget_VoucherTranMast_Period(@Start, @End, @ActualsCutOff, @CmCode) a
				On a.DocDate=a2.DocDate and a.DocNo=a2.DocNo and a.VrRoute=a2.VrRoute
			Left Outer Join dbo.fn_FAS_Budget_VoucherTranSub_Period(@Start, @End, @ActualsCutOff, @CmCode) a3
				On a2.DocDate=a3.DocDate and a2.DocNo=a3.DocNo and a2.VrRoute=a3.VrRoute and a2.LrCode<>a3.LrCode	
			where a2.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID) 
			Group By a2.DocNo, a2.VrRoute, a2.DocDate, a.FileRef, a2.LrCode, a2.DrAmt, a2.CrAmt
			 ) a
			Left Outer Join dbo.fn_FAS_Budget_VoucherTranSub_Period(@Start, @End, @ActualsCutOff, @CmCode) b 
				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.MinVTSNo=b.VTSNo
		) m 
		Left Outer Join FAS_Budget_LedgerMaster n 
			On m.PLrCode=n.LedgerCode and n.CompCode=@CmCode
		Left Outer Join FAS_Budget_VoucherMaster p 
			On m.VrRoute=p.VrRoute+p.VrWidth and n.CompCode=p.CompCode
		Left Outer Join FAS_VoucherTranPay r 
			On m.DocNo = r.DocNo and m.DocDate=r.DocDate and m.VrRoute = r.VrRoute and n.CompCode = r.CompCode		

	Order by  m.LrCode, m.DocDate, m.VrRoute, m.DocNo

End
GO

