CREATE PROCEDURE [dbo].[FAS_Budget_Rpt_LrMonthwise_Sum] (@UserKey Varchar(36), @isRealisedAmtOnly bit, @Start datetime, @End datetime, @PrStart datetime, @PrEnd datetime, @ActualsCutOff datetime, @CmCode varchar(12)) 

AS

Begin

	Set NoCount On

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Select  r.LrCode, (Select LedgerName From FAS_Budget_LedgerMaster Where LedgerCode = r.LrCode and CompCode = @CmCode) as LedgerName,
		 Mncode, DMonth as AcMonth, r.Debit, r.Credit, r.OpBalance, r.ClBalance
	from 
		 (Select j.LrCode, j.MnCode,  Datename(month, convert(datetime, Convert(varchar, j.MnCode)+'01', 112 )) as DMonth, 	IsNull(OB, 0) as OpBalance,	
				Case When isNull(j.DrAmt, 0) = 0 then ' ' else Convert(varchar, j.DrAmt)  end as Debit,
				Case When isNull(j.CrAmt, 0) = 0 then ' ' else Convert(varchar, j.CrAmt)  end as Credit,
				isNull(j.CB, 0)  as ClBalance
		from
			(Select h.LrCode, h.Mncode,  Sum(h.DrAmt) as DrAmt, Sum(h.CrAmt) as CrAmt,  
				 h.OpBalance as Ob,
				dbo.fn_FAS_Budget_LedgerOpBalance(h.LrCode, DateAdd(mm, 1, Convert(datetime, h.MnCode+'01', 112)), @ActualsCutOff, @isRealisedAmtOnly, @CmCode) as CB
					
			from 
				(Select h1.MnCode, h1.LrCode, Isnull(h2.DrAmt, 0)DrAmt,  Isnull(h2.CrAmt, 0) CrAmt, q.OpBalance
				from	(Select m.SelectInt as LrCode, n.MnCode 
					From
						(Select SelectInt, @CmCode as CompCode From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchId and CompId = @CompId) m
						Full Outer Join 
						(Select Convert(varchar(6), Monthdate, 112) MnCode, @CmCode as CompCode from dbo.fn_FAS_Months(@Start, @End)) n
						On m.CompCode=n.CompCode
					) h1
					Left Outer Join
					(Select LrCode, Convert(varchar(6), c.Docdate, 112) MnCode, 
						Sum(Case When @isRealisedAmtOnly='1' and c1.DocNo is Not Null and c1.BankDate is Null then 0 Else DrAmt End) as DrAmt, 
						Sum(Case When @isRealisedAmtOnly='1' and c1.DocNo is Not Null and c1.BankDate is Null then 0 Else CrAmt End) as CrAmt 
					from dbo.fn_FAS_Budget_VoucherTranSub_Period(@Start, @End, @ActualsCutOff, @CmCode) c 
					Left Outer Join FAS_VoucherTranPay c1
						On c.DocNo=c1.DocNo and c.DocDate=c1.DocDate and c.DocDate=c1.DocDate and c.CompCode=c1.CompCode
					Where c.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchId and CompId =@CompId) 
					Group by c.LrCode, Convert(varchar(6), c.Docdate, 112)
					) h2
					On h1.LrCode=h2.LrCode and h1.MnCode=h2.MnCode			

					Left Outer Join 
					(Select LedgerCode, OpBalance 
					from dbo.fn_FAS_Budget_AllOpBalance(@Start, @ActualsCutOff, @isRealisedAmtOnly, '0',  @CmCode)
				 	Where LedgerCode in (Select SelectInt From Com_SelectList Where UserKey = @Userkey and BranchId = @BranchId and CompId = @CompID)				
					) q
					On q.LedgerCode = h2.LrCode

				) h
			Group by h.LrCode, MnCode,  h.OpBalance
			) j
		)r
	Order by LrCode, MnCode
End
GO

