CREATE PROCEDURE [dbo].[FAS_Budget_Sales_Consolidate] (@PlanFor int, @Fromdate datetime, @Todate datetime, @AsOndate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))


AS


		

			Select x.PlanFor, x.CustomerCode, x.PostingAc, Sum(x.PlanQty*x.Rate)SalesValue
			From 
				(Select a.CustomerCode, a.ItemCode, a.PlanFor, a.PlanPeriod, isNull(a.PlanQty, 0)as PlanQty, b.PostingAccount as PostingAc,
						isNull(dbo.fn_SAL_Item_Rate(a.ItemCode, a.CustomerCode, '', 0, Null, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear), 0) as Rate 
				From dbo.fn_SAL_SalesPlan_Period(@Fromdate, @Todate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear) a
				Left Outer Join	fn_BOM_Material_Others('A', @AsOndate, @AsOndate, @BranchID, @CompID) b
				On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
				Where PlanPeriod Between @Fromdate and @Todate
					and PlanFor = (Select Min(PlanFor) From dbo.fn_SAL_SalesPlan_Period(@Fromdate, @Todate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear)
								Where PlanPeriod Between  @Fromdate and @Todate and Planfor>=@PlanFor and BranchID=@BranchID and CompID=@CompID) 
				) x 
			Group By x.PlanFor, x.CustomerCode, x.PostingAc
			Order By x.PlanFor, x.CustomerCode, x.PostingAc
			



/*  Without PostingAc */

