			From 
					(Select CustomerCode, ItemCode, PlanFor, PlanPeriod, isNull(PlanQty, 0)as PlanQty, 
							isNull(dbo.fn_SAL_Item_Rate(ItemCode, CustomerCode, '', 0, Null, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear), 0) as Rate 
					From dbo.fn_SAL_SalesPlan(@AsOndate, @AsOndate, @BranchID, @CompID, @Finyear)
