CREATE PROCEDURE [dbo].[FAS_Budget_Sales_Consolidate_Modify] (@PlanFor int, @DocType Varchar(3), @DocNo int,  @DocDate datetime, @Fromdate datetime, @Todate datetime, @AsOndate datetime, @CompCode varchar(12), @Finyear varchar(20))

AS

Begin


	Declare @Transtamp datetime

	/*  Fetching Transtamp for Retreive Prev Revision Sales Plan*/
	Select @Transtamp=Max(Transtamp) From FAS_Budget_Hdr_History  Where DocNo=@DocNo and DocType=@DocType and DocDate=@DocDate and CompCode=@CompCode
	
	If @TranStamp is Null
		/*  If History Transtamp is null move to Hdr Table for Fetching Transtamp for Retreive Prev Revision Sales Plan*/
		Select @Transtamp=Transtamp From FAS_Budget_Hdr  Where DocNo=@DocNo and DocType=@DocType and DocDate=@DocDate and CompCode=@CompCode
		
	
	Declare @BranchID Varchar(3)
	Declare @CompID Varchar(3)
	
	/*  @BranchID and @CompID for Fetching data from Sales Plan*/
	Select @BranchID=SubString(@CompCode, 3, 2)
	Select @CompID=Left(@CompCode, 2)

	Select PlanFor, CustomerCode, PostingAc, Sum(PlanQty*Rate)SalesValue
