CREATE PROCEDURE [dbo].[FAS_Budget_Sales_Splitup] (@SplitUpFor Char(1), @Fromdate datetime, @Todate datetime, @AsOndate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))


AS

		Declare @PlanFor as int


		If @SplitUpFor='M'  ---Month
			Select @PlanFor=2
		else
			If @SplitUpFor='W' --Week
				Select @PlanFor=3
			Else                         --Day
				Select @PlanFor=4


		
		IF @PlanFor='2' /* Month */

			Select PlanFor, Convert(varchar(7), PlanPeriod, 120) as PlanPeriod, CustomerCode,  PostingAc, Sum(PlanQty*Rate)SalesValue
			From 
					(Select CustomerCode, a.ItemCode, PlanFor, PlanPeriod, isNull(PlanQty, 0)as PlanQty, b.PostingAccount as PostingAc,
							isNull(dbo.fn_SAL_Item_Rate(a.ItemCode, CustomerCode, '', 0, Null, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear), 0) as Rate 
					From dbo.fn_SAL_SalesPlan_Period(@Fromdate, @Todate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear) a
					Left Outer Join dbo.fn_BOM_Material_Others('A', @AsOndate, @AsOndate, @BranchID, @CompID) b
						On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
					Where PlanPeriod Between @Fromdate and @Todate 
						and PlanFor = (Select Min(PlanFor) From dbo.fn_SAL_SalesPlan_Period(@Fromdate, @Todate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear) 
										Where PlanPeriod Between @Fromdate and @Todate and Planfor>=@PlanFor and BranchID=@BranchID and CompID=@CompID) 
					) x 
			Group By Convert(varchar(7), PlanPeriod, 120), PlanFor, CustomerCode, PostingAc
			Order By  CustomerCode, PlanPeriod, PlanFor

		IF @PlanFor='3' /*  Week  */

			Select  PlanFor, 
					Case When Day(PlanPeriod) between 1 and 7 Then Convert(varchar(7), PlanPeriod, 120) + '-01'
					When Day(PlanPeriod) between 8 and 14 Then Convert(varchar(7), PlanPeriod, 120) + '-08'
					When Day(PlanPeriod) between 15 and 21 Then Convert(varchar(7), PlanPeriod, 120) + '-15'
					Else Convert(varchar(7), PlanPeriod, 120) + '-22' End as PlanPeriod,  CustomerCode,  PostingAc,
					Sum(PlanQty*Rate) SalesValue
				From 
					(Select CustomerCode, a.ItemCode, PlanFor, PlanPeriod, isNull(PlanQty, 0)as PlanQty, b.PostingAccount as PostingAc,
							isNull(dbo.fn_SAL_Item_Rate(a.ItemCode, CustomerCode, '', 0, Null, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear), 0) as Rate 
						From dbo.fn_SAL_SalesPlan_Period(@Fromdate, @Todate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear) a
						Left Outer Join dbo.fn_BOM_Material_Others('A', @AsOndate, @AsOndate, @BranchID, @CompID) b
							On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
						Where PlanPeriod Between @Fromdate and @Todate  
							and PlanFor = (Select Min(PlanFor) From dbo.fn_SAL_SalesPlan_Period(@Fromdate, @Todate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear) 
										Where PlanPeriod Between @Fromdate and @Todate and Planfor>=@PlanFor and BranchID=@BranchID and CompID=@CompID) 
					) x 
			Group By CustomerCode, PlanPeriod, PlanFor, PostingAc
			Order By CustomerCode, PlanPeriod, PlanFor


/*			Select PlanFor, DatePart(wk, PlanPeriod) as PlanPeriod, CustomerCode, Sum(PlanQty*Rate)SalesValue
			From 
					(Select CustomerCode, ItemCode, PlanFor, PlanPeriod, isNull(PlanQty, 0)as PlanQty, 
							isNull(dbo.fn_SAL_Item_Rate(ItemCode, CustomerCode, '', 0, Null, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear), 0) as Rate 
					From dbo.fn_SAL_SalesPlan(@AsOndate, @AsOndate, @BranchID, @CompID, @Finyear)
					Where PlanPeriod Between @Fromdate and @Todate  
						and PlanFor = (Select Min(PlanFor) From SAL_SalesPlan 
										Where PlanPeriod Between @Fromdate and @Todate and Planfor>=@PlanFor and BranchID=@BranchID and CompID=@CompID) 
					) a 
			Group By DatePart(wk, PlanPeriod), PlanFor, CustomerCode
			Order By PlanPeriod, PlanFor, CustomerCode
*/

		IF @PlanFor='4' /*  Day  */
			Select PlanFor, PlanPeriod as PlanPeriod, CustomerCode, PostingAc, Sum(PlanQty*Rate)SalesValue
			From 
				(Select CustomerCode, a.ItemCode, PlanFor, PlanPeriod, isNull(PlanQty, 0)as PlanQty,  b.PostingAccount as PostingAc,
						isNull(dbo.fn_SAL_Item_Rate(a.ItemCode, CustomerCode, '', 0, Null, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear), 0) as Rate 
				From dbo.fn_SAL_SalesPlan_Period(@Fromdate, @Todate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear) a
				Left Outer Join dbo.fn_BOM_Material_Others('A', @AsOndate, @AsOndate, @BranchID, @CompID) b
					On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
				Where PlanPeriod Between @Fromdate and @Todate    
					and PlanFor = (Select Min(PlanFor) From dbo.fn_SAL_SalesPlan_Period(@Fromdate, @Todate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear) 
									Where PlanPeriod Between @Fromdate and @Todate  and Planfor>=@PlanFor and BranchID=@BranchID and CompID=@CompID) 
				) x 
			Group By PlanFor, CustomerCode, PlanPeriod, PostingAc
			Order By CustomerCode, PlanPeriod, PlanFor
GO

/****** Object:  StoredProcedure [dbo].[FAS_Budget_Sales_Splitup_Modify]    Script Date: 17/06/2026 11:29:59 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Budget_Sales_Splitup_Modify] (@SplitUpFor Char(1), @DocType Varchar(3), @DocNo int,  @DocDate datetime, @Fromdate datetime, @Todate datetime, @AsOndate datetime, @CompCode varchar(12),  @Finyear varchar(20))


AS
	

		Declare @Transtamp datetime
		/*  Fetching Transtamp for Retreive Prev Revision Sales Plan*/
		Select @Transtamp=Max(Transtamp) From FAS_Budget_Hdr_History  Where DocNo=@DocNo and DocType=@DocType and DocDate=@DocDate and CompCode=@CompCode
		
		If @TranStamp is Null
			/*  If History Transtamp is null move to Hdr Table for Fetching Transtamp for Retreive Prev Revision Sales Plan*/
			Select @Transtamp=Transtamp From FAS_Budget_Hdr  Where DocNo=@DocNo and DocType=@DocType and DocDate=@DocDate and CompCode=@CompCode
		
		
		
		Declare @BranchID Varchar(3)
		Declare @CompID Varchar(3)

	
		/*  @BranchID and @CompID for Fetching data from Sales Plan*/
		Select @BranchID=SubString(@CompCode, 3, 2)
		Select @CompID=Left(@CompCode, 2)



		Declare @PlanFor as int

		If @SplitUpFor='M'  ---Month

			Select @PlanFor=2

		Else
			Begin
				If @SplitUpFor='W' --Week
					Select @PlanFor=3
				Else                         --Day
					Select @PlanFor=4
			End 





		IF @PlanFor='2' /* Month */
			Execute dbo.[FAS_Budget_Sales_Splitup_Modify_Month] @PlanFor,  @Fromdate, @Todate, @TranStamp, @AsOndate, @BranchID,  @CompID,  @Finyear


		IF @PlanFor='3' /*  Week  */
			Execute dbo.[FAS_Budget_Sales_Splitup_Modify_Week] @PlanFor,  @Fromdate, @Todate, @TranStamp, @AsOndate, @BranchID,  @CompID,  @Finyear


		IF @PlanFor='4' /*  Day  */
			Execute dbo.[FAS_Budget_Sales_Splitup_Modify_Day] @PlanFor,  @Fromdate, @Todate, @TranStamp, @AsOndate, @BranchID,  @CompID,  @Finyear
GO

