AS
	

Begin				

		Select  PlanFor, 
				Case 	When Day(PlanPeriod) between 1 and 7 Then Convert(varchar(7), PlanPeriod, 120) + '-01'
					When Day(PlanPeriod) between 8 and 14 Then Convert(varchar(7), PlanPeriod, 120) + '-08'
					When Day(PlanPeriod) between 15 and 21 Then Convert(varchar(7), PlanPeriod, 120) + '-15'
					Else Convert(varchar(7), PlanPeriod, 120) + '-22' End as PlanPeriod,  CustomerCode, PostingAc,
				Sum(PlanQty*Rate) SalesValue
			From 
				(            /* Prev Rev Value*/
					Select CustomerCode, a.ItemCode, PlanFor, PlanPeriod, -isNull(PlanQty, 0)as PlanQty, b.PostingAccount as PostingAc,
						isNull(dbo.fn_SAL_Item_Rate(a.ItemCode, CustomerCode, '', 0, Null, @Transtamp, @Transtamp, @BranchID, @CompID, @Finyear), 0) as Rate 
					From dbo.fn_SAL_SalesPlan_Period(@Fromdate, @Todate, @Transtamp, @Transtamp, @BranchID, @CompID, @Finyear) a
					Left Outer Join dbo.fn_BOM_Material_Others('A', @Transtamp, @Transtamp, @BranchID, @CompID) b
						On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
					Where PlanPeriod Between @Fromdate and @Todate  
						and PlanFor = (Select Min(PlanFor) From dbo.fn_SAL_SalesPlan_Period(@Fromdate, @Todate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear) 
									Where PlanPeriod Between @Fromdate and @Todate and Planfor>=@PlanFor and BranchID=@BranchID and CompID=@CompID) 
				

					Union All

					/* Current Rev Value*/
					Select CustomerCode, a.ItemCode, PlanFor, PlanPeriod, isNull(PlanQty, 0)as PlanQty, b.PostingAccount as PostingAc,
						isNull(dbo.fn_SAL_Item_Rate(a.ItemCode, CustomerCode, '', 0, Null, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear), 0) as Rate 
					From dbo.fn_SAL_SalesPlan_Period(@Fromdate, @Todate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear) a
					Left Outer Join dbo.fn_BOM_Material_Others('A', @AsOndate, @AsOndate, @BranchID, @CompID) b
						On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
					Where PlanPeriod Between @Fromdate and @Todate  
						and PlanFor = (Select Min(PlanFor) From dbo.fn_SAL_SalesPlan_Period(@Fromdate, @Todate, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear) 
									Where PlanPeriod Between @Fromdate and @Todate and Planfor>=@PlanFor and BranchID=@BranchID and CompID=@CompID) 
				) x 
		Group By CustomerCode, PlanPeriod, PlanFor, PostingAc
		Order By PlanPeriod, PlanFor, CustomerCode




	/*	Select PlanFor, PlanPeriod, CustomerCode, Sum(SalesValue)
		From
			(	/* Prev Rev Value*/
				Select  PlanFor, 
						Case When Day(PlanPeriod) between 1 and 7 Then Convert(varchar(7), PlanPeriod, 120) + '-01'
						When Day(PlanPeriod) between 8 and 14 Then Convert(varchar(7), PlanPeriod, 120) + '-08'
						When Day(PlanPeriod) between 15 and 21 Then Convert(varchar(7), PlanPeriod, 120) + '-15'
						Else Convert(varchar(7), PlanPeriod, 120) + '-22' End as PlanPeriod,  CustomerCode,
						-Sum(PlanQty*Rate) SalesValue
					From 
						(Select CustomerCode, ItemCode, PlanFor, PlanPeriod, isNull(PlanQty, 0)as PlanQty, 
								isNull(dbo.fn_SAL_Item_Rate(ItemCode, CustomerCode, '', 0, Null, @Transtamp, @Transtamp, @BranchID, @CompID, @Finyear), 0) as Rate 
							From dbo.fn_SAL_SalesPlan(@Transtamp, @Transtamp, @BranchID, @CompID, @Finyear)
							Where PlanPeriod Between @Fromdate and @Todate  
								and PlanFor = (Select Min(PlanFor) From SAL_SalesPlan   --dbo.fn_SAL_SalesPlan(@AsOndate, @AsOndate, @BranchID, @CompID, @Finyear) 
											Where PlanPeriod Between @Fromdate and @Todate and Planfor>=@PlanFor and BranchID=@BranchID and CompID=@CompID) 
						) a 
				Group By CustomerCode, PlanPeriod, PlanFor
						
				Union All
	
				/* Current Rev Value*/
				Select  PlanFor, 
						Case When Day(PlanPeriod) between 1 and 7 Then Convert(varchar(7), PlanPeriod, 120) + '-01'
						When Day(PlanPeriod) between 8 and 14 Then Convert(varchar(7), PlanPeriod, 120) + '-08'
						When Day(PlanPeriod) between 15 and 21 Then Convert(varchar(7), PlanPeriod, 120) + '-15'
						Else Convert(varchar(7), PlanPeriod, 120) + '-22' End as PlanPeriod,  CustomerCode,
						Sum(PlanQty*Rate) SalesValue
					From 
						(Select CustomerCode, ItemCode, PlanFor, PlanPeriod, isNull(PlanQty, 0)as PlanQty, 
								isNull(dbo.fn_SAL_Item_Rate(ItemCode, CustomerCode, '', 0, Null, @AsOndate, @AsOndate, @BranchID, @CompID, @Finyear), 0) as Rate 
							From dbo.fn_SAL_SalesPlan(@AsOndate, @AsOndate, @BranchID, @CompID, @Finyear)
							Where PlanPeriod Between @Fromdate and @Todate  
								and PlanFor = (Select Min(PlanFor) From SAL_SalesPlan   --dbo.fn_SAL_SalesPlan(@AsOndate, @AsOndate, @BranchID, @CompID, @Finyear) 
											Where PlanPeriod Between @Fromdate and @Todate and Planfor>=@PlanFor and BranchID=@BranchID and CompID=@CompID) 
						) a 
				Group By CustomerCode, PlanPeriod, PlanFor					
			)x 
		Group By CustomerCode, PlanPeriod, PlanFor	
		Order By PlanPeriod, PlanFor, CustomerCode

*/

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Budget_Schedule_BSPLGroup_Rpt]    Script Date: 17/06/2026 11:29:59 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_Budget_Schedule_BSPLGroup_Rpt]  (@RptType tinyint, @PeriodStart datetime, @PeriodEnd datetime, @ActualsCutOff datetime, @FixedAssetFromCalculation bit, @Level int, @isShowZeroCB bit, @SuppliedOpeningStock money, @SuppliedClosingStock money, @CmCode Varchar(12))
/* @isExpandAll bit,*/
/* @RptType = 0 -Profit & Loss Entries; 1 - BalanceSheet Entries; Other than 0 & 1 - All Schedules Entries */

AS

 Begin
 
	CREATE TABLE [#TMP_SubGroups](
		[SubGrpCode] [int] NOT NULL,
		[SubGrpPath] [varchar](42) NOT NULL,
		[SubSchName] [varchar](50) NOT NULL,
		[Amount] [money] NOT NULL,
		[isDebit] [bit] NOT NULL,
		[isExpand] [bit] NOT NULL,
		[Seq] [int] NOT NULL,
		[EntryType] [varchar](3) NOT NULL
	) ON [PRIMARY]


	/* To Fill Temp Table with Schedule Group data */
	INSERT INTO [#TMP_SubGroups]
		Execute FAS_Budget_ScheduleGroup_Rpt @RptType, @PeriodStart, @PeriodEnd, @ActualsCutOff, @FixedAssetFromCalculation, 0, @isShowZeroCB, @SuppliedOpeningStock, @SuppliedClosingStock, @CmCode

	
	/* To Update Closing Stock value to positive for Stock-In-Trade (balance sheet use) HardCoded */
	If @RptType=1
		UPDATE [#TMP_SubGroups] Set Amount=-Amount
		Where SubGrpCode = -5
	
	/* To Update Schedule Total with Sum of Sub Ledgers Values */
	UPDATE [#TMP_SubGroups] Set Amount=isNull((Select Sum(Amount) From [#TMP_SubGroups] b Where b.SubGrpPath Like a.SubGrpPath+'%' and b.EntryType='LED'), 0)
	From [#TMP_SubGroups] a 
	Where a.EntryType='SCH'
	

	/* Other than Top Level Schedules are deleted */
/*	If @isExpandAll='0'		
		Delete [#TMP_SubGroups] Where Not (Len(SubGrpPath)=2 and EntryType='SCH')
*/


/* Select data based on @isBalanceSheet Option */
/*
	
	If @RptType=1
		Select (a.SubGrpRoute+a.SubGrpWidth) as SubGrpPath, b.SchSeq as SubGrpSeq, d.SubGrpCode, b.SchCode, d.SubSchName as GroupName, d.Amount as CurrentCB, d.isDebit, d.isExpand, d.EntryType, d.SubGrpPath as SchPath
		From FAS_BSPLGroupMaster_vw a
		Left Outer Join FAS_BSPLGroup b
			On a.SubGrpCode= b.SubGrpCode and a.CompCode = b.CompCode
		Left Outer Join FAS_ScheduleMaster c
			On c.SchCode = b.SchCode and c.CompCode=a.CompCode
		Left Outer Join [#TMP_SubGroups] d 
			On d.SubGrpPath like c.SchRoute+c.SchWidth+'%' 
		Where a.SubGrpRoute Like '01%' and a.EffStatus='AA' and a.ByParentStatus='1' and a.CompCode=@CmCode and b.SchCode is Not Null
		Order By (a.SubGrpRoute+a.SubGrpWidth), b.SchCode, b.SchSeq
	Else
		If @RptType=0
			Select (a.SubGrpRoute+a.SubGrpWidth) as SubGrpPath, b.SchSeq as SubGrpSeq, d.SubGrpCode, b.SchCode, d.SubSchName as GroupName, d.Amount as CurrentCB, d.isDebit, d.isExpand, d.EntryType, d.SubGrpPath as SchPath
			From FAS_BSPLGroupMaster_vw a
			Left Outer Join  FAS_BSPLGroup b
				On a.SubGrpCode= b.SubGrpCode and a.CompCode = b.CompCode
			Left Outer Join FAS_ScheduleMaster c
				On c.SchCode = b.SchCode and c.CompCode=a.CompCode
			Left Outer Join [#TMP_SubGroups] d 
				On d.SubGrpPath like c.SchRoute+c.SchWidth+'%'
			Where a.SubGrpRoute Like '02%' and a.EffStatus='AA' and a.ByParentStatus='1' and a.CompCode=@CmCode and b.SchCode is Not Null
			Order By (a.SubGrpRoute+a.SubGrpWidth), b.SchCode, b.SchSeq
*/

	Declare @LevelMinus as int
	
	If @RptType=0  or @RptType=2 --Profit And Loss And All Schedule - Default Path is 2
		Select @LevelMinus=2     -- P&  L  Default Path is 2

	If @RptType=1 --Balace Sheet - Default Path is 4
		Select @LevelMinus=3 
	


	If @RptType=2  /*For All Schedule Show*/

				/* Select data based on @RptType Option */

		Select (a.SubGrpRoute+a.SubGrpWidth) as SubGrpPath, b.SchSeq as SubGrpSeq, d.SubGrpCode, b.SchCode, d.SubSchName as GroupName, 
			d.Amount as CurrentCB, d.isDebit, d.isExpand, d.EntryType, d.SubGrpPath as SchPath
		From FAS_BSPLGroupMaster_vw a
		Left Outer Join FAS_BSPLGroup b
			On a.SubGrpCode= b.SubGrpCode and a.CompCode = b.CompCode
		Left Outer Join FAS_ScheduleMaster c
			On c.SchCode = b.SchCode and c.CompCode=a.CompCode
		Left Outer Join [#TMP_SubGroups] d 
			On d.SubGrpPath like c.SchRoute+c.SchWidth+'%' 
		Where a.EffStatus='AA' and a.ByParentStatus='1' and a.CompCode=@CmCode and b.SchCode is Not Null	
			/* Schedules shown based on levels selected */ --This condition used in frontEnd
			--and  (((Len(a.SubGrpRoute+a.SubGrpWidth)+Len(d.SubGrpPath))/2)- Case When a.SubGrpRoute like '02%'  Then @LevelMinus Else @LevelMinus+1 End) + Case When EntryType='LED' Then 1 Else 0 End <=  @Level 
		Order By (a.SubGrpRoute+a.SubGrpWidth), b.SchCode, b.SchSeq


	Else	

		/*For BalanceSheet and P & L Schedule only*/

		/* Select data based on @RptType Option */

		Select (a.SubGrpRoute+a.SubGrpWidth) as SubGrpPath, b.SchSeq as SubGrpSeq, d.SubGrpCode, b.SchCode, d.SubSchName as GroupName, 
			d.Amount as CurrentCB, d.isDebit, d.isExpand, d.EntryType, d.SubGrpPath as SchPath
		From FAS_BSPLGroupMaster_vw a
		Left Outer Join FAS_BSPLGroup b
			On a.SubGrpCode= b.SubGrpCode and a.CompCode = b.CompCode
		Left Outer Join FAS_ScheduleMaster c
			On c.SchCode = b.SchCode and c.CompCode=a.CompCode
		Left Outer Join [#TMP_SubGroups] d 
			On d.SubGrpPath like c.SchRoute+c.SchWidth+'%' 
		Where a.SubGrpRoute Like Case @RptType When 0 Then '02%' When 1 Then '01%' Else '%' End and a.EffStatus='AA' and a.ByParentStatus='1'
			and a.CompCode=@CmCode and b.SchCode is Not Null
				/* Schedules Shown based on levels Selected */
			and  (((Len(a.SubGrpRoute+a.SubGrpWidth)+Len(d.SubGrpPath))/2)-@LevelMinus) + Case When EntryType='LED' Then 1 Else 0 End <=  @Level 
		Order By (a.SubGrpRoute+a.SubGrpWidth), b.SchCode, b.SchSeq

		
		--Select * from [#TMP_SubGroups] Order By SubSchName

	DROP TABLE [#TMP_SubGroups]

End
GO

