CREATE PROCEDURE [dbo].[FAS_Budget_Schedules_Fill]  (@RptType tinyint, @PeriodStart datetime, @PeriodEnd datetime, @FixedAssetFromCalculation bit, @Level int, @isShowZeroCB bit, @SuppliedOpeningStock money, @SuppliedClosingStock money, @CmCode Varchar(12))
/* @RptType = 0 -Profit & Loss Entries; 1 - BalanceSheet Entries; Other than 0 & 1 - All Schedules Entries */

AS

 Begin
 
	CREATE TABLE [#TMP_SubGroups](
		[SubGrpCode] [int] NOT NULL,
		[SubGrpPath] [varchar](42) NOT NULL,
		[SubSchName] [varchar](50) NOT NULL,
		[Amount] [money] NOT NULL,
		[isDebit] [bit] NOT NULL,
		[isExpand] [bit] NOT NULL,
		[Seq] [int] NOT NULL,
		[EntryType] [varchar](3) NOT NULL
	) ON [PRIMARY]


	/* To Fill Temp Table with Schedule Group data */
	INSERT INTO [#TMP_SubGroups]
		Execute FAS_ScheduleGroup_Rpt @RptType, @PeriodStart, @PeriodEnd, @FixedAssetFromCalculation, @Level, '1', @SuppliedOpeningStock, @SuppliedClosingStock, @CmCode

	
	/* To Update Closing Stock value to positive for Stock-In-Trade (balance sheet use) HardCoded */
	If @RptType=1
		UPDATE [#TMP_SubGroups] Set Amount=-Amount
		Where SubGrpCode = -5
	
	/* To Update Schedule Total with Sum of Sub Ledgers Values */
	UPDATE [#TMP_SubGroups] Set Amount=isNull((Select Sum(Amount) From [#TMP_SubGroups] b Where b.SubGrpPath Like a.SubGrpPath+'%' and b.EntryType='LED'), 0)
	From [#TMP_SubGroups] a 
	Where a.EntryType='SCH'
	
	
	/* Other than Top Level Schedules are deleted */

/*	If @isExpandAll='0'	
		Delete [#TMP_SubGroups] Where Not (Len(SubGrpPath)=2 and EntryType='SCH')
*/

	if @RptType=2
		/* All option -  For no need to show P&L OB, Current period and Transferred Account */
				
		Delete [#TMP_SubGroups] Where SubGrpCode in (-1, -2, -3)
	
	
	/* Select data based on @RptType Option */
	Select (a.SubGrpRoute+a.SubGrpWidth) as SubGrpPath, b.SchSeq as SubGrpSeq, d.SubGrpCode, b.SchCode, d.SubSchName as GroupName, d.Amount as CurrentCB, d.isDebit, d.isExpand, d.EntryType, d.SubGrpPath as SchPath
	From FAS_BSPLGroupMaster_vw a
	Left Outer Join FAS_BSPLGroup b
		On a.SubGrpCode= b.SubGrpCode and a.CompCode = b.CompCode
	Left Outer Join FAS_ScheduleMaster c
		On c.SchCode = b.SchCode and c.CompCode=a.CompCode
	Left Outer Join [#TMP_SubGroups] d 
		On d.SubGrpPath like c.SchRoute+c.SchWidth+'%' 
	Where a.SubGrpRoute Like Case @RptType When 0 Then '02%' When 1 Then '01%' Else '%' End and a.EffStatus='AA' and a.ByParentStatus='1' and a.CompCode=@CmCode and b.SchCode is Not Null
	Order By (a.SubGrpRoute+a.SubGrpWidth), b.SchCode, b.SchSeq

	DROP TABLE [#TMP_SubGroups]

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Budget_UpdateVrRouteNo]    Script Date: 17/06/2026 11:30:00 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_Budget_UpdateVrRouteNo](@PlanPeriod datetime, @PlanFor int, @VrRoute varchar(4), @CmCode varchar(12))

AS

BEGIN
		SET NOCOUNT ON
		
		DECLARE @tmpPlanPeriod datetime
		DECLARE @tmpPlanFor int
		
		IF (@PlanPeriod IS NULL)
			DECLARE curPlanPeriod CURSOR FOR
				Select Distinct PlanPeriod From FAS_Budget_Dtl Where CompCode=@CmCode
		ELSE
			DECLARE curPlanPeriod CURSOR FOR
				Select @PlanPeriod
		
		OPEN curPlanPeriod
		
		FETCH NEXT FROM curPlanPeriod into @tmpPlanPeriod
		
		WHILE @@FETCH_STATUS = 0
		BEGIN
		
			IF @PlanFor=0
				DECLARE curPlanFor CURSOR FOR
					Select Distinct PlanFor From FAS_Budget_Dtl Where PlanPeriod=@tmpPlanPeriod and CompCode=@CmCode
			ELSE
				DECLARE curPlanFor CURSOR FOR
					Select @PlanFor
			
			OPEN curPlanFor	
			
			FETCH NEXT FROM curPlanFor into @tmpPlanFor
		
			WHILE @@FETCH_STATUS = 0
			BEGIN
				If (@VrRoute='')
					/* Update the Voucher Route using Function */
					Update FAS_Budget_Dtl Set VrRoute = dbo.fn_FAS_Budget_ReturnVoucherType(DrCode, CrCode, @CmCode)
					Where PlanPeriod=@tmpPlanPeriod and PlanFor=@tmpPlanFor and CompCode=@Cmcode	
				
				/* Update Voucher No */
				Update FAS_Budget_Dtl Set VrNo=(Select Count(*) From FAS_Budget_Dtl n 
												Where n.PlanPeriod=m.PlanPeriod and n.PlanFor=m.PlanFor and n.VrRoute=m.VrRoute and n.CompCode=m.CompCode
													and n.PlanDate<m.PlanDate)
													
												+	(Select Count(*) From FAS_Budget_Dtl n 
													Where n.PlanPeriod=m.PlanPeriod and n.PlanFor=m.PlanFor and n.VrRoute=m.VrRoute and n.CompCode=m.CompCode
														and n.PlanDate=m.PlanDate
														and n.DrCode<m.DrCode)
														
												+ 	(Select Count(*) From FAS_Budget_Dtl n2 
													Where n2.PlanPeriod=m.PlanPeriod and n2.PlanFor=m.PlanFor and n2.VrRoute=m.VrRoute and n2.CompCode=m.CompCode
														and n2.PlanDate=m.PlanDate and n2.DrCode=m.DrCode 
														and n2.CrCode<=m.CrCode)
				From FAS_Budget_Dtl m
				Where PlanPeriod=@tmpPlanPeriod and PlanFor=@tmpPlanFor and VrRoute Like @VrRoute+'%' and CompCode=@Cmcode
			
				FETCH NEXT FROM curPlanFor into @tmpPlanFor
			END	
		
			CLOSE curPlanFor
			FETCH NEXT FROM curPlanPeriod into @tmpPlanPeriod
		END
		
		CLOSE curPlanPeriod
		DEALLOCATE curPlanPeriod
		DEALLOCATE curPlanFor
		
END
GO

