CREATE PROCEDURE [dbo].[FAS_BudgetEntryPolicy_Hlp]  (@AsOnDate datetime, @RptDate datetime, @UserID varchar(10), @CmCode Varchar(12))

As

SET NOCOUNT ON

	Begin
	
		Select Distinct d.PolicyCode, d.VrCode, v.VoucherName
		From FAS_BudgetEntryPolicy_Dtl d
		Left Outer Join FAS_BudgetEntryPolicy_Users u
		On d.PolicyCode=u.PolicyCode and u.isActive='1' and d.CompCode=u.CompCode
		Left Outer Join Fas_VoucherMaster v
		On d.VrCode=v.VrWidth and v.isActive='1' and v.VrRoute='' and v.VrWidth Not in ('02', '03')    /* Credit Note & Debit Note not Allowed */
		and d.CompCode=v.CompCode
		Where u.UserCode=@UserID and d.isActive='1' and d.CompCode=@CmCode

	End
GO

