GO

CREATE PROCEDURE [dbo].[FAS_BudgetVsActuals_Rpt_TrialBalance](@RptType char(1), @Start datetime, @End datetime, @ActualsCutOff datetime, @CmCode varchar(12))

 As 

 

 Begin


	SET NOCOUNT ON

	
		
 /* Budget Vs Actuals TrialBalace Data get stored in this Table*/
 CREATE TABLE [#TMP_BudgetActualsDet]
 	(
	[Master] [varchar](10),
	[Path] [varchar](42),
	[Type] [varchar] (10),
	[Code] [int],
	[Particulars] [varchar] (100),
	[BudgetOB] [money],
	[BudgetDrAmt] [money],
	[BudgetCrAmt] [money],
	[BudgetCB] [money],
	[ActualsOB] [money],
	[ActualsDrAmt] [money],
	[ActualsCrAmt] [money],
	[ActualsCB] [money]
	) ON [PRIMARY]
	
 
	/* Trial Balance Split up Data get Stored in this Table */
 	CREATE TABLE [#TMP_Budget]
	(
		[Master] 	[varchar](10),
		[Path] 		[varchar](42),
		[Type] 		[varchar] (10),
		[Code] 		[int],
		[Particulars]	[varchar] (100),
		[BudgetOB] 	[money],
		[BudgetDrAmt] 	[money],
		[BudgetCrAmt] 	[money],
		[BudgetCB] 	[money]

	) ON [PRIMARY]
	
	

	INSERT INTO [#TMP_BudgetActualsDet]
		Select Master, Path, Type, Code, Particulars, 0, 0, 0, 0, OpBalance, DrAmt, CrAmt, ClosingBalance
		From dbo.fn_FAS_Rpt_TrialBalance(@RptType, @Start, @End, @CmCode)


	INSERT INTO [#TMP_Budget]
		Select Master, Path, Type, Code, Particulars, OpBalance, DrAmt, CrAmt, ClosingBalance
		From dbo.fn_FAS_Budget_Rpt_TrialBalance(@RptType, @Start, @End, @ActualsCutOff, @CmCode)





 End
GO

