CREATE PROCEDURE [dbo].[FAS_ChqPrint_Bank_Hlp](@CompCode Varchar(12))   
   
As    
  
BEGIN  
  
    SET NOCOUNT ON    
      
     Select a.LedgerName, a.LedgerCode 
     From FAS_LedgerMaster_AuthTbl a    
     Where Exists (Select * From FAS_ChequePrint_Master b    
                    Where b.BankCode=a.LedgerCode and b.CompCode=a.CompCode
                  )    
        And Left(a.LrRoute, 4) in ('0201', '0B01') and a.EffStatus='AA' and a.CompCode=@CompCode     
     Order By a.LedgerName  
    
END
