CREATE PROCEDURE [dbo].[FAS_CostCategoryMaster_Ins]

	(@CategoryCode 	[int],
	 @ShortName		[varchar](10),
	 @LongName		[varchar](50),
	 @Description 		[varchar](50),
	 @Priority 		[int],
	 @IsMandatory 		[bit], 
	 @UserID		[varchar](10),
	 @CompCode 		[varchar](12),
	 @TranStamp		[datetime])

AS 

SET  NOCOUNT ON	

	declare @cBranchID varchar(12)	
	
	declare  BranchIDList cursor For
	select CompID+BranchID from COM_Company_Master where IsBranchAvail='0' and CompID=Left(@CompCode,2)


	OPEN BranchIDList
	FETCH NEXT FROM BranchIDList into @cBranchID 
	WHILE @@FETCH_STATUS=0
	
	BEGIN

		INSERT INTO [FAS_CostCategoryMaster] 
			 ([CategoryCode],
			  [ShortName],
			  [LongName],
			  [Description],
			  [Priority],
			  [IsMandatory],			
			  [UserID],
			  [CompCode],
			  [TranStamp]) 
		 
		VALUES 

			(@CategoryCode,
			 @ShortName,
			 @LongName,
			 @Description,
			 @Priority,
			 @IsMandatory,
			 @UserID,
			 @CompCode,
			 @TranStamp)
	
		FETCH NEXT FROM BranchIDList into @cBranchID
	END
 	
	close BranchIDList
	deallocate BranchIDList
GO

