CREATE PROCEDURE [dbo].[FAS_Del_Voucher] (@VrNo int, @DocDate datetime, @VrRoute varchar(42),  @CmCode varchar(12))

      AS

     SET NOCOUNT ON

	 Delete from FAS_VoucherTranMast where DocNo=@VrNo and DocDate=@DocDate and VrRoute=@VrRoute and Compcode=@CmCode
	
	 Delete from FAS_VoucherTranSub where DocNo=@VrNo and DocDate=@DocDate and VrRoute=@VrRoute and Compcode=@CmCode
	
	 Delete from FAS_VoucherTranPay where DocNo=@VrNo and DocDate=@DocDate and VrRoute=@VrRoute and Compcode=@CmCode
	 
	 Delete from FAS_VoucherTranRef where DocNo=@VrNo and DocDate=@DocDate and VrRoute=@VrRoute and Compcode=@CmCode
	
	 Delete from FAS_VoucherTranNarr where DocNo=@VrNo and DocDate=@DocDate and VrRoute=@VrRoute and Compcode=@CmCode
	
	 Delete from FAS_VoucherTranCostCentre where DocNo=@VrNo and DocDate=@DocDate and VrRoute=@VrRoute and Compcode=@CmCode
	
	 Delete from FAS_BillDetails where DocNo=@VrNo and DocDate=@DocDate and VrRoute=@VrRoute and Compcode=@CmCode
	
	 Execute [FAS_Mod_VrTranReNum_From] @VrNo, @DocDate, @VrRoute, -1, @CmCode
