CREATE PROCEDURE [dbo].[FAS_Del_Voucher_RefBased] (@RefType varchar(5), @RefNo int, @RefDate datetime, @CmCode varchar(12))

AS

BEGIN
     SET NOCOUNT ON
     
     Declare @VrNo int, @VrDate datetime, @VrRoute varchar(42)
     
     Declare VrList cursor For
		 Select DocNo, DocDate, VrRoute
		 From FAS_VoucherTranRef
		 Where RefType=@RefType and RefNo=@RefNo and RefDate=@RefDate and CompCode=@CmCode
		 Order By VrRoute, DocDate Desc, DocNo Desc
		 
	Open VrList
	FETCH NEXT FROM VrList into @VrNo, @VrDate, @VrRoute 
	
	WHILE @@FETCH_STATUS = 0
		BEGIN
			 Delete from FAS_VoucherTranMast where DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and Compcode=@CmCode
			
			 Delete from FAS_VoucherTranSub where DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and Compcode=@CmCode
			
			 Delete from FAS_VoucherTranPay where DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and Compcode=@CmCode
			 
			 Delete from FAS_VoucherTranRef where DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and Compcode=@CmCode
			
			 Delete from FAS_VoucherTranNarr where DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and Compcode=@CmCode
			
			 Delete from FAS_VoucherTranCostCentre where DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and Compcode=@CmCode
			
			 Delete from FAS_BillDetails where DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and Compcode=@CmCode
			
			 Execute [FAS_Mod_VrTranReNum_From] @VrNo, @VrDate, @VrRoute, -1, @CmCode
			 
			FETCH NEXT FROM VrList into @VrNo, @VrDate, @VrRoute 
		END
		
	close VrList
	deallocate VrList
END
GO

