CREATE PROCEDURE [dbo].[FAS_DeleteEntireGroup] (@GrRoute varchar(42), @CmCode varchar(12))

AS

Begin
/*
	Delete from FAS_VoucherTranMast a 
		Where Exists (Select * from FAS_VoucherTranSub b 
				Where Exists (Select LedgerCode From FAS_LedgerMaster c
						Where Left(LrRoute, Len(@GrRoute)) = @GrRoute and b.CompCode = c.CompCode and c.LedgerCode = b.LrCode)
				and a.DocNo=b.DocNo and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode)
		and a.CompCode=@CmCode

	Delete from FAS_VoucherTranPay a 
		Where Exists (Select * from FAS_VoucherTranSub b 
				Where Exists (Select LedgerCode From FAS_LedgerMaster c
						Where Left(LrRoute, Len(@GrRoute)) = @GrRoute and b.CompCode = c.CompCode and c.LedgerCode = b.LrCode)
				and a.DocNo=b.DocNo and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode)
		and a.CompCode=@CmCode

	Delete from FAS_VoucherTranRef a 
		Where Exists (Select * from FAS_VoucherTranSub b 
				Where Exists (Select LedgerCode From FAS_LedgerMaster c
						Where Left(LrRoute, Len(@GrRoute)) = @GrRoute and b.CompCode = c.CompCode and c.LedgerCode = b.LrCode)
				and a.DocNo=b.DocNo and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode)
		and a.CompCode=@CmCode

	Delete from FAS_VoucherTranNarr a 
		Where Exists (Select * from FAS_VoucherTranSub b 
				Where Exists (Select LedgerCode From FAS_LedgerMaster c
						Where Left(LrRoute, Len(@GrRoute)) = @GrRoute and b.CompCode = c.CompCode and c.LedgerCode = b.LrCode)
				and a.DocNo=b.DocNo and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode)
		and a.CompCode=@CmCode

	Delete from FAS_BillDetails a 
		Where Exists (Select * from FAS_VoucherTranSub b 
				Where Exists (Select LedgerCode From FAS_LedgerMaster c
						Where Left(LrRoute, Len(@GrRoute)) = @GrRoute and b.CompCode = c.CompCode and c.LedgerCode = b.LrCode)
				and a.DocNo=b.DocNo and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode)
		and a.CompCode=@CmCode

	Delete from FAS_VoucherTranSub b 
				Where Exists (Select LedgerCode From FAS_LedgerMaster c
						Where Left(LrRoute, Len(@GrRoute)) = @GrRoute and b.CompCode = c.CompCode and c.LedgerCode = b.LrCode)
				and b.CompCode=@CmCode

	Delete from FAS_BillDetails a Where Exists (Select LedgerCode From FAS_LedgerMaster b
					Where Left(LrRoute, Len(@GrRoute)) = @GrRoute and CompCode = @CmCode and b.LedgerCode = a.LrCode)
				and CompCode = @CmCode and VrRoute = 'OpBal')

	Delete from FAS_VoucherTranPay a Where Exists (Select LedgerCode From FAS_LedgerMaster b
							Where Left(LrRoute, Len(@GrRoute)) = @GrRoute and CompCode = @CmCode and a.VrRoute='OpBal-'+b.LedgerCode)
					and VrRoute like 'OpBal-%' and CompCode = @CmCode
*/
	Delete from FAS_LedgerMaster Where Left(LrRoute, Len(@GrRoute))=@GrRoute and CompCode=@CmCode
	Delete from FAS_GroupMaster Where Left(GrRoute+GrWidth, Len(@GrRoute))=@GrRoute and CompCode=@CmCode

End
GO

