CREATE PROCEDURE [dbo].[FAS_DepreciationClassification_Ins]
	(@ClassificationCode 			[int],
	 @ClassificationDesc 			[varchar](50),
	 @DefaultDeprPerc			[float],
	 @DefaultDeprPostingAc			[int],
	 @PostingVrRoute			[Varchar](40),
	 @UserID				[varchar](10),
 	 @CompCode 				[varchar](12),
	 @TranStamp 				[datetime])
AS 

SET NOCOUNT ON

	
	declare @cBranchID varchar(12)	
	
	declare  BranchIDList cursor For
	select CompID+BranchID from COM_Company_Master where IsBranchAvail = '0' and CompID = Left(@CompCode, 2)


	OPEN BranchIDList
	FETCH NEXT FROM BranchIDList into @cBranchID 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN
	
		 

		INSERT INTO [FAS_DepreciationClassification] 
			 ([ClassificationCode],
			  [ClassificationDesc],
			  [DefaultDeprPerc],
			  [DefaultDeprPostingAc],
			  [PostingVrRoute],
			  [UserID],
			  [CompCode],
			  [TranStamp]) 
		 
		VALUES 
			( @ClassificationCode,
			 @ClassificationDesc,
			 @DefaultDeprPerc,
			 @DefaultDeprPostingAc,
			 @PostingVrRoute,
			 @UserID,
			 @cBranchID,
			 @TranStamp)
	

		FETCH NEXT FROM BranchIDList into @cBranchID 
	END
 	
	close BranchIDList
	deallocate BranchIDList
GO

