SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Dis_AA_0] (@RptDate Datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON
	
	Select LrCode, Particulars, Less1,  Amount1to30,  Amount31to60,  Amount61to90,  Amount90,   (Less1+Amount1to30+Amount31to60+Amount61to90+Amount90) PendingAmt,  AdvAmt, 
	 (Less1+Amount1to30+Amount31to60+Amount61to90+Amount90+AdvAmt) TotAmt, LrRoute
	From

	(	Select m.LrCode, n.LedgerName  as Particulars,  LrRoute, 
			Sum(Less1) as Less1, Sum(Amount1to30) as Amount1to30, Sum(Amount31to60) as Amount31to60, Sum(Amount61to90) as Amount61to90,
			Sum(Amount90) as Amount90,  Sum(AdvAmt) as AdvAmt
		From FAS_LedgerMaster n

		Right Outer Join
		 (
			Select b.LrCode,  AdvAmt, Case when Overdue < 1 then Amount else 0 End as Less1,
			  Case when Overdue between 1 and 30 then Amount else 0 End as Amount1to30,
			  Case when Overdue between 31 and 60 then Amount else 0 End as Amount31to60,
			  Case when Overdue between 61 and 90 then Amount else 0 End as Amount61to90,
			  Case when Overdue > 90 then Amount else 0 End as Amount90
			from  
				(
					Select d.LrCode, RefNo as [Invoice No], Convert(Datetime,  RefDate, 105) as [Invoice Date], Convert(Datetime,  Dateadd(day, isNull(CreditDays, 0), RefDate) , 105) as [Due Date], 
					Amount, AdvAmt,
					DateDiff(day, Dateadd(day, isNull(CreditDays, 0), RefDate), @RptDate) as OverDue
					from 
						(
							Select isNull(y.LrCode, z.LrCode) LrCode, isNull(y.RefNo, z.RefNo) as RefNo, 
								isNull(y.RefDate, (Select Min(x.RefDate) from FAS_BillDetails x where x.RefNo=z.RefNo and x.LrCode = z.LrCode and x.RefDate <= @RptDate and x.CompCode=@CmCode)) as RefDate, 
								isNull(y.CreditDays, 0) CreditDays, z.Amount,  z.AdvAmt
							from 
								(Select LrCode, RefNo, RefDate, CreditDays from fas_billdetails where Type in ('New Ref', 'Advance') and CompCode=@CmCode
								) y 
							Right Outer Join
								(Select LrCode, RefNo, Case When Type='On Acct' then Sum(Amount) Else 0 End as AdvAmt,
										           Case When Type<>'On Acct' then Sum(Amount) Else 0 End as Amount 
								from fas_billdetails
								where RefDate <= @RptDate and CompCode=@CmCode
								group by LrCode, RefNo, Type having sum(Amount) <> 0 ) z 
							On y.RefNo=z.RefNo and y.LrCode = z.LrCode
						) d
				) b		
			)m

			On n.LedgerCode = m.LrCode 	
			Where Left(n.LrRoute, 4) in ('0206', '0303') and n.CompCode=@CmCode
			group by m.LrCode, LedgerName, LrRoute
		)k
		Order by LrRoute, Particulars
	End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Dis_AA_1]    Script Date: 17/06/2026 11:30:01 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Dis_AA_1] (@LrCode int, @RptDate Datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON

	
	Select [Invoice No], [Invoice Date], Amount, [Due Date], OverDue,	Less1 as  [x < 1],  Amount1to30 as [1 <= x <= 30],  Amount31to60 as [31 <= x <= 60],  Amount61to90 as [61 <= x <= 90],  Amount90 as [x > 90], 
	(Less1+Amount1to30+Amount31to60+Amount61to90+Amount90) as PendingAmt
	From (
		Select [Invoice No], [Invoice Date], Amount, [Due Date], Convert(varchar, OverDue) + space(4) as OverDue,	
										Case when Overdue < 1 then Amount else 0 End as Less1,
										Case when Overdue between 1 and 30 then Amount else 0 End as Amount1to30,
										Case when Overdue between 31 and 60 then Amount else 0 End as Amount31to60,
										Case when Overdue between 61 and 90 then Amount else 0 End as Amount61to90,
										Case when Overdue > 90 then Amount else 0 End as Amount90
		from 
			(Select RefNo as [Invoice No], Convert(Datetime,  RefDate, 105) as [Invoice Date], Convert(Datetime,  Dateadd(day, isNull(CreditDays, 0), RefDate) , 105) as [Due Date], 
				Amount, --(Convert(varchar, Abs(Amount)) + ' ' + Case sign(Amount) when 1 then 'Dr' When -1 then 'Cr' End + '     ') as Amount,
				DateDiff(day, Dateadd(day, isNull(CreditDays, 0), RefDate), @RptDate) as OverDue
			from 
				(
				Select isNull(y.RefNo, z.RefNo) as RefNo, 
						isNull(y.RefDate, (Select Min(x.RefDate) from FAS_BillDetails x where x.RefNo=z.RefNo and x.RefDate <= @RptDate and x.LrCode=@LrCode and x.CompCode=@CmCode)) as RefDate, 
						isNull(y.CreditDays, 0) CreditDays, z.Amount 
					from 
						(Select RefNo, RefDate, CreditDays from fas_billdetails where LrCode=@LrCode and Type in ('New Ref', 'Advance') and CompCode=@CmCode
						) y 
					Right Outer Join
						(Select RefNo, Sum(Amount) as Amount from fas_billdetails
						where Type <> 'On Acct' and RefDate <= @RptDate and LrCode=@LrCode and CompCode=@CmCode
						group by RefNo having sum(Amount) <> 0 ) z 
					On y.RefNo=z.RefNo 
				) d
			) b
			
	)m

	Order by [Invoice Date]

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Dis_AgeingAnalysis_Header]    Script Date: 17/06/2026 11:30:01 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[FAS_Dis_AgeingAnalysis_Header] (@sCnt int, @isPrint Char(1), @UserKey varchar(100),  @CmCode Varchar(12))

AS

	Declare @Cnt int
	Declare @Sql  NVarchar(1000)
	Declare @RndNo float

	Select @Cnt = 0
	Select @Sql = ''


--	Select @Sql = N'Declare @RetTable Table (LrCode int, Particulars varchar(35), Amount float,'

	Select @Sql = N'Create Table TmpTables (Userkey varchar(100), LrCode int, Particulars Varchar(35), Amount Float,'

	While @sCnt >@Cnt

		Begin
			Select @Cnt = @Cnt + 1			
			Select @Sql = @Sql + N' Fld' + Convert(varchar, @cnt) + N' float,'		
		End
	

	Select @Sql = @Sql +  N' PendAmt Float, OnAcct Float, TotAmt Float, LrRoute Varchar(42) )'
	Execute sp_executesql @Sql
	

	/*  Insert Value into TmpTable*/
	Declare @FldName Varchar
	Declare @FldValue Varchar
	
	Declare @StValue Varchar
	Declare @EValue Varchar

	Begin Tran

		Declare HeaderList Cursor For
	
		Select Startvalue, Endvalue From FAS_AgeingReport_Option Where Compcode = @CmCode and isPrint = @isPrint
	
		Open HeaderList	
		Fetch Next From HeaderList into @StValue, @EValue
			
			Select @cnt = 0
	
			While @@Fetch_Status = 0
		
				Begin
					Select @cnt = @cnt+1
					Select @FldName = 'Fld' + Convert(Varchar, @Cnt)
					Select @FldValue = @StValue +'<= x <='+ @Evalue
	
					Update TmpTables Set @FldName = @FldValue
	
					FETCH NEXT FROM HeaderList into @StValue, @EValue 
				End
	 	
		close HeaderList
		deallocate HeaderList	
					
		Select * From TmpTable

	Commit Tran
GO

