CREATE PROCEDURE [dbo].[FAS_Dis_BRS_Book] (@BankCode int, @RptDate datetime, @CmCode char(12))

AS

 Set NOCOUNT ON
/*
 Declare @MastCmCode char(4)
 Select @MastCmCode=Left(@CmCode, 4)
*/
 Select 'OB' as ChqType, ' ' as PayType, isNull(Sum(Amount), 0) as Amount 
 from (
  Select (Sum(DrAmt)-Sum(CrAmt)) as Amount  
  from fas_voucher_Vw 
  where DocDate <= Convert(datetime, @RptDate, 111) and lrcode=@BankCode and CompCode=@CmCode

  Union All 

  Select opbalance from fas_ledgermaster where ledgercode=@BankCode and CompCode=@CmCode
        ) a

 Union All

 Select 'NotCleared' ChqType, PayType, isNull(Sum(Amount) , 0)
 from (
  Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
   Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else   isNull(b.DrAmt, 0) End as Amount
  from FAS_VoucherTranPay a Join FAS_Voucher_Vw b 
  On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
  Where b.LrCode=@BankCode and a.CompCode=@CmCode
    and (a.BankDate is Null or a.BankDate > @RptDate) and b.DocDate <= @RptDate 
 
  Union All

  Select Case isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType, ChqAmount as Amount
  from FAS_VoucherTranPay
  Where VrRoute='OpBal-'+Convert(varchar, @BankCode) and CompCode=@CmCode
   and (BankDate is Null or BankDate > @RptDate)
 ) x 
 Group by PayType
 
 Union All
 
 Select 'Cleared' ChqType, PayType, isNull(Sum(Amount) , 0)
 from (
  Select Case R.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
   Case R.DrAmt When 0 Then  isNull(R.CrAmt, 0) Else   isNull(R.DrAmt, 0) End as Amount
  from FAS_VoucherTranPay a Join FAS_VoucherTranMast b 
  On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
    Join FAS_VoucherTranSub R
    On R.DocNo=a.DocNo and R.DocDate=a.DocDate and R.VrRoute=a.VrRoute and R.CompCode=a.CompCode
  Where R.LrCode=@BankCode and a.CompCode=@CmCode
    and (a.BankDate is Not Null or a.BankDate <= @RptDate) and b.DocDate <= @RptDate 
 
  Union All
 
  Select Case isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType,  ChqAmount as Amount
  from FAS_VoucherTranPay
  Where VrRoute='OpBal-'+Convert(varchar, @BankCode) and CompCode=@CmCode
   and (BankDate is Not Null or BankDate <= @RptDate)
 ) x 
 Group by PayType

 Order by 1 desc, 2 desc
GO

