CREATE PROCEDURE [dbo].[FAS_Dis_BS_0]  (@isRealisedAmtOnly bit, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

Begin

	SET NOCOUNT ON

	
	Select Case GrpHd when '01' then 1 when '0B' then 2 when '03' then 3 when '09' then 4 when '0A' then 5 when '02' then 6 when '04' then 7 when '0C' then 8 when '0F' then 9 when 'PL' then 10 when 'LT' then 11 when 'OP' then 12 End as SortOrder,
		GrpHd, Particulars, Amount 
	from
		(


		Select Left(Path, 2) as GrpHd, Particulars, Convert(varchar, Sum(Isnull(DrAmt, 0)-isNull(CrAmt, 0))) as Amount
				From dbo.fn_FAS_Rpt_TrialBalance(@PrStart, @PrStart,@PrEnd, @CmCode) 
				Where Left(Path, 2) in ('01', '02', '03', '04', '09', '0A', '0B', '0C', '0F')
				group by Master, Type, Path, Particulars, OpBalance
/*	
		Select P.Path as GrpHd, R.GroupName as Particulars, Convert(varchar, P.OpBalance+ isNull(Q.VrAmt, 0)) as Amount 
		from 
			(Select Path, Sum(OpBalance) as OpBalance
			from
				(Select Left(LrRoute, 2) as Path, OpBalance
				from dbo.fn_FAS_AllOpBalance(@PrStart, @isRealisedAmtOnly, @CmCode) 
				where Left(LrRoute, 4)<>'0205'
				) x1
			Where Path in ('01','02','03', '04', '09','0A','0B','0C', '0F')
			Group by Path
			) P

			Left Outer Join

			(Select Left(c1.LrRoute, 2) as Path, Sum(b1.DrAmt-b1.CrAmt) as VrAmt
				from FAS_VoucherTranSub b1 Left Outer Join FAS_LedgerMaster c1
				On c1.LedgerCode=b1.LrCode and c1.CompCode=b1.CompCode
				Where (Left(c1.LrRoute, 2) in ('01','02','03', '04', '09','0A','0B','0C', '0F') and Left(LrRoute, 4)<>'0205')and (b1.DocDate between @PrStart and @PrEnd) and b1.CompCode=@CmCode
				Group by Left(c1.LrRoute, 2)
			) Q

			On P.Path=Q.Path

			Left Outer Join (Select Left(GrRoute+GrWidth, 2) as Path, GroupName from FAS_GroupMaster Where Len(GrRoute+GrWidth)=2 and CompCode=@CmCode) R
		
			On P.Path=R.Path

*/	
		UNION ALL

		Select 'PO', 'Opening Balance', Convert(varchar, isNull(OpBalance, 0)) as Amount
		from dbo.fn_FAS_AllOpBalance(@PrStart, @isRealisedAmtOnly, @CmCode)
		where LedgerCode=2 and CompCode=@CmCode

		UNION ALL
/*
		Select 'PC', 'Current Period', Convert(varchar, isNull(Sum(Amount),0)) as Amount
		from
			(Select a.LrCode, a1. LrRoute, a.Amount
			from
				(Select LrCode, isnull((sum(DrAmt)-sum(CrAmt)),0) as Amount, CompCode 
				from FAS_VoucherTranSub
				where (DocDate between @PrStart and @PrEnd) and Compcode =@CmCode 
				group by LrCode, CompCode 
				) a  Left Outer Join FAS_LedgerMaster a1 On a.LrCode=a1.LedgerCode and a.CompCode=a1.CompCode
			) b
		where Substring(b.LrRoute, 1, 2) in ('0D', '0E', '05', '06', '07', '08')
*/
		Select 'PC', 'Current Period', Convert(varchar, isNull(Sum(Amount), 0)) as Amount
		from
			(Select a.LrCode, a1.LrRoute, a.Amount
			from
				(Select LrCode, (sum(DrAmt)-sum(CrAmt)) as Amount from FAS_VoucherTranSub
				where (DocDate between @PrStart and @PrEnd) and Compcode = @CmCode 
				group by LrCode 
				
				Union All
	
				--Opening Stock
				Select LedgerCode, OpBalance from FAS_LedgerMaster where Left(LrRoute, 4)='0205' and CompCode=@CmCode
	
				) a 
				Left Outer Join FAS_LedgerMaster a1 On a.LrCode=a1.LedgerCode Where a1.CompCode=@CmCode
			) b
		where (Left(b.LrRoute, 2) in ('0D', '0E', '05', '06', '07', '08') or Left(b.LrRoute, 4) = '0205')

		UNION ALL
	
		Select 'PT', 'Less Transfered', Convert(varchar, isNull((Sum(DrAmt)-sum(CrAmt)), 0)) as Amount 
		from FAS_VoucherTranSub
		where (DocDate between @PrStart and @PrEnd) and LrCode=2 and CompCode =@CmCode

		UNION ALL

		Select 'OP', 'Diff in Opening Balance', Convert(varchar, isnull(-Sum(OpBalance),0)) as Amount from dbo.fn_FAS_AllOpBalance(@PrStart, @isRealisedAmtOnly, @CmCode) where Compcode=@CmCode
	
		) M

	Order by 1

End
GO

