CREATE PROCEDURE [dbo].[FAS_Dis_Dy_0] (@Start datetime, @End datetime, @CmCode varchar(12))

AS

Begin

	SET NOCOUNT ON		
	
	Select VrRoute, Date, Case isCancelled When 0 then (Select LedgerName from FAS_LedgerMaster where LedgerCode=M.LrCode and CompCode=@CmCode)  Else 'CANCELLED' End as Particulars,
		[Voucher Type], [Voucher No], Convert(Varchar, Amount) as Amount
	from
		(Select isCancelled, VrRoute, Convert(Varchar(16), DocDate, 105) as Date, 
			Case when Left(VrRoute, 2) in ('01', '0B', '0F') then
				(Select top 1 LrCode from fas_VoucherTranSub where CrAmt > 0 and VrRoute=a.VrRoute and DocNo=a.DocNo and CompCode=@Cmcode)
			         else  
				(Select top 1 LrCode from fas_VoucherTranSub where DrAmt > 0 and VrRoute=a.VrRoute and DocNo=a.DocNo and CompCode=@Cmcode) end as LrCode,
			(Select VoucherName from FAS_VoucherMaster where VrRoute+VrWidth=a.VrRoute and CompCode=@CmCode) as [Voucher Type],
			 DocNo as [Voucher No], Amount
		from FAS_VoucherTranMast a
		Where (DocDate between @Start and @End) 
			and Compcode = @Cmcode ) M
	Order by 2, 4, 5
End
GO

