CREATE PROCEDURE [dbo].[FAS_Dis_Gr_1]  (@Route varchar(42), @FinStart datetime, @Start datetime, @End datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON
	

	Select d.LrCode, d.Ledgers, Case when Sign(d.CB) = 1 then Convert(Varchar, d.CB) end  as Debit, Case when Sign(d.CB) = -1 then Convert(varchar, -d.CB) end as Credit 
	from
		(Select a.LrCode, b.LedgerName as Ledgers, Sum(a.DrAmt-a.CrAmt)+Case when  @Start=@FinStart then b.OpBalance Else 0 End as CB
		from Fas_Voucher_Vw a Left Outer Join Fas_LedgerMaster b
		On a.LrCode=b.LedgerCode and b.CompCode=a.CompCode
		Where Left(b.LrRoute, Len(@Route)) =@Route and (a.DocDate between @Start and @End)
					and a.Compcode = @CmCode group by a.LrCode, b.LedgerName, b.OpBalance 
		) d

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Dis_Gr_2]    Script Date: 17/06/2026 11:30:01 ******/
