CREATE PROCEDURE [dbo].[FAS_Dis_Gr_2] (@LrCode int, @CmCode varchar(12)) AS

Begin

	Set NoCount On

	
	
	
	Declare @OPBalDr as money, @OPBalCr as money
	Select @OPBalCr=OpBalance from FAS_LedgerMaster Where LedgerCode=@LrCode and CompCode=@CmCode
	Select @OPBalDr=@OPBalCr

	If (@OPBalCr <= 0) 
		Select @OPBalCr=0 
	 Else 
		Select @OPBalDr=0 
	
	Select Mncode, @LrCode, DMonth as [Ac Month], Case When r.Debit > 0 then Convert(varchar, r.Debit) Else '' End as Debit, 
		Case When r.Credit > 0 Then Convert(varchar, r.Credit) Else '' End as Credit, r.Closing_Balance
	from 
		 (Select j.MnCode,  Datename(month, convert(datetime, Convert(varchar, j.MnCode)+'01', 112 )) as DMonth,  j.Debit,  j.Credit,
				(Case	when sign(j.CB) = -1 then convert(varchar, -CB)+' Cr' when sign(j.CB) = 1 then Convert(varchar, CB)+' Dr' when sign(j.CB) = 0 then ' ' end) as Closing_Balance
		from
			(Select h.Mncode,  sum(h.dramt) as Debit, sum(h.cramt) as Credit,  
						(Select Sum(m.DrAmt-m.CrAmt)+(@OPBalCr+@OPBalDr) from fas_Voucher_Vw m where m.lrcode=@LrCode and m.compcode =@CmCode and h.MnCode >= Convert(int, Convert(varchar(6), m.DocDate, 112))) as CB
			from 
				(Select Convert(int, Convert(varchar(6), DocDate, 112)) MnCode, DocDate, DrAmt, CrAmt from FAS_Voucher_Vw c where Lrcode=@LrCode and CompCode =@CmCode
				) h
			group by mncode
			) j
		)r
	
	Order by MnCode

End
GO

