CREATE PROCEDURE [dbo].[FAS_Dis_Groups_CashBankBook] (@CashCode char(4), @BankCode char(4), @BankODCode char(4),  @Start datetime,  @End datetime,  @CmCode varchar(12))
--Old Name FAS_Dis_CB_0

AS

Begin
	SET NOCOUNT ON
	
	Select Route,   Particulars,  Case Sign(CB) When 1 then Convert(Varchar, CB) End as Debit,
		Case Sign(CB) When -1 then Convert(Varchar, -CB) End as Credit
	From (
		Select Route, GroupName as Particulars, Sum(Cb) CB 
		From (
			Select Left(b.LrRoute, 4) as Route,  
			(Sum(DrAmt) - Sum(CrAmt)+ OpBalance) as CB
			From FAS_VoucherTranSub a
			Left Outer Join FAS_LedgerMaster b
			On a.LrCode= b.LedgerCode and a.CompCode = b.CompCode 
			Where Left(b.LrRoute, 4) in (@CashCode, @BankCode, @BankODCode) and a.DocDate between @Start and @End and a.CompCode = @CmCode
			group by Left(b.LrRoute, 4), OpBalance
		       )x
		Left Outer Join FAS_GroupMaster c
			On x.Route = c.GrRoute+c.GrWidth
		Where isNull(x.CB, 0) <> 0 and  c.CompCode=@CmCode
		Group by Route, GroupName
	      )y




/*
	Select a.PC as Route, b.GroupName as Particulars,  Case Sign(a.CB) When 1 then Convert(Varchar, CB) End as Debit,
		Case Sign(a.CB) When -1 then Convert(Varchar, -CB) End as Credit
	from
		(
		Select substring(ledger_route, 1, 4) as PC, (sum(DrAmt)-sum(CrAmt)) as CB from fas_vrdetails_vw 
		where substring(ledger_route, 1, 4) in (@CashCode, @BankCode, @BankODCode) and CompCode=@CmCode
		Group By substring(ledger_route, 1, 4)
		) a 
		Left Outer Join FAS_GroupMaster b
		On a.PC = b.GrRoute+b.GrWidth
	Where isNull(a.CB, 0) <> 0 and  b.CompCode=@CmCode
*/


End
