CREATE PROCEDURE [dbo].[FAS_Dis_Jr_0] (@Route varchar(42), @FinStart datetime, @FinEnd datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON
	
	Select  Convert(varchar(6), a.mndate, 112) as MnCode, DateName(Month, a.MnDate) as [Accounting Month], b.NoVouch as [No of Vouchers] 
	from fas_month a left outer join
				 (Select Convert(varchar(6), DocDate, 112) as VMonth, Count(DocNo) as NoVouch 
				from fas_vouchertranmast 
				where Left(VrRoute, Len(@Route))=@Route and Compcode= @CmCode
				group by Convert(varchar(6), DocDate, 112)) b 
	on Convert(varchar(6), a.MnDate, 112) = VMonth 
	Where Convert(varchar(6), a.MnDate, 112) between Convert(varchar(6), @FinStart, 112) and Convert(varchar(6), @FinEnd, 112)
	Order by a.mncode
End
GO

