CREATE PROCEDURE [dbo].[FAS_Dis_Jr_1] (@Route varchar(42), @MnCode varchar(6), @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON

	Select Voucher_Route, Convert(Varchar(10), DocDate, 105) as Date, 
		(Select Top 1 a.LedgerName from FAS_VrDetails_Vw a where isNull(a.CrAmt, 0)=0 and  Left(a.Voucher_Route, Len(@Route)) = @Route and CompCode=@CmCode and 
			Convert(varchar(6), DocDate, 112) = @MnCode and a.DocNo=b.DocNo and a.Voucher_Route=b.Voucher_Route) as  Particulars, 
		 VoucherName as [Voucher Type], DocNo as [Voucher No.], Sum(DrAmt) as Debit, '' as Credit 
	from FAS_VrDetails_Vw b 
	Where Left(b.Voucher_Route, Len(@Route)) = @Route and b.VTSNo=1 and Convert(varchar(6), b.DocDate, 112) = @MnCode and Compcode = @CmCode 
	group by Voucher_Route, DocDate, VoucherName, DocNo

End
GO

