CREATE PROCEDURE [dbo].[FAS_Dis_Ledgers] (@RptEnd datetime, @CmCode varchar(12))
--Old Name     FAS_Dis_Lr_0

 AS

Begin
	Set NOCOUNT ON	
	
	Select LedgerCode, LrRoute,  LedgerName as Ledgers 
	from fas_ledgerMaster a
	where CompCode=@CmCode 
		and (OpBalance<>0 or  Exists (Select * from FAS_VoucherTranSub b 
					Where b.DocDate<=@RptEnd and b.LrCode=a.LedgerCode and b.CompCode=a.CompCode))
	Order by LedgerName
End
GO

