CREATE PROCEDURE [dbo].[FAS_Dis_Ledgers_CashBankBook] (@LrRoute varchar(42), @Start Datetime, @End DateTime, @CmCode varchar(12)) AS
--Old Name FAS_Dis_CB_1
Begin
	SET NOCOUNT ON
	Select Z.LrCode, Z.Ledgers, Case When Amt > 0 then Convert(Varchar, Amt) Else '' End as Debit, Case When Amt < 0 then Convert(Varchar, -Amt) Else '' End as Credit
	from
		(Select a.Lrcode, b.LedgerName as Ledgers, (Sum(DrAmt-CrAmt)+ b.OpBalance) as Amt
		from FAS_VoucherTranSub a join FAS_LedgerMaster b
			On a.LrCode=b.LedgerCode and b.CompCode=a.CompCode
		Where b.LrRoute like @LrRoute+'%' and a.DocDate between @Start and @End and a.Compcode = @CmCode 
		Group by a.LrCode, b.LedgerName, b.OpBalance 
		) Z

End
GO

