CREATE PROCEDURE [dbo].[FAS_Dis_Lr_1] (@LrCode int, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12)) 

AS

Begin

	Set NoCount On

	Select @LrCode as LrCode, Mncode, DMonth as [Ac Month], r.Debit, r.Credit, 
		r.Closing_Balance
	from 
		 (Select j.MnCode,  Datename(month, convert(datetime, Convert(varchar, j.MnCode)+'01', 112 )) as DMonth, 
				Case When isNull(j.DrAmt, 0) = 0 then ' ' else Convert(varchar, j.DrAmt)  end as Debit,
				 Case When isNull(j.CrAmt, 0) = 0 then ' ' else Convert(varchar, j.CrAmt)  end as Credit,
				(Case sign(isNull(j.CB, 0))  When  0 then ' '  When 1 then Convert(varchar, CB) + ' Dr'else Convert(varchar, -CB) + ' Cr' end) as Closing_Balance
		from
			(Select h.Mncode,  Sum(h.DrAmt) as DrAmt, Sum(h.CrAmt) as CrAmt,  dbo.fn_FAS_LedgerOpBalance(@LrCode, DateAdd(mm, 1, Convert(datetime, h.MnCode+'01', 112)), '0', @CmCode) as CB
					/*	(Select Sum(DrAmt-CrAmt) from FAS_VoucherTranSub m Where  LrCode=@LrCode and m.CompCode =@CmCode 
						and (m.DocDate between @PrStart and @PrEnd) and Convert(varchar(6), m.DocDate, 112) <= h.MnCode) as CB */
			from 
				(Select h1.MnCode, h2.DrAmt, h2.CrAmt
				from

					(Select Convert(varchar(6), Monthdate, 112) MnCode from dbo.fn_FAS_Months(@PrStart, @PrEnd)) h1 
				Left Outer Join
					(Select Convert(varchar(6), Docdate, 112) MnCode, Sum(DrAmt) as DrAmt, Sum(CrAmt) as CrAmt from FAS_VoucherTranSub c 
					Where LrCode=@LrCode and (c.DocDate between @PrStart and @PrEnd) and CompCode =@CmCode
					Group by Convert(varchar(6), Docdate, 112)
					) h2
				On h1.MnCode=h2.MnCode
				) h
			Group by MnCode
			) j
		)r
	Order by MnCode
End
GO

