CREATE PROCEDURE [dbo].[FAS_Dis_Lr_2] (@LrCode varchar(42), @MnCode varchar(6), @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON

	Select Voucher_Route, Convert(Varchar(10), DocDate, 105) as Date, Voucher, RefNo, [Voucher No.], Debit, Credit 
	from (
		Select a.VrRoute as Voucher_Route, a.DocDate, c.VoucherName as Voucher,
			Case When LTrim(RTrim(a.Ref))='' then b.RefType+':'+Convert(varchar, b.RefNo) else a.Ref end as RefNo, a.DocNo as [Voucher No.], 
			Case When a.DrAmt=0 then '' else Convert(varchar, a.DrAmt) end as Debit, Case When a.CrAmt=0 then '' else Convert(varchar, a.CrAmt) end as Credit, a.LrCode 
		from FAS_Voucher_vw a Left Outer Join FAS_VoucherTranRef b
		On a.DocNo=b.DocNo and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode and a.DocDate=b.DocDate and a.DocType=b.DocType
		Left Outer Join FAS_VoucherMaster c On a.VrRoute=c.VrRoute+c.VrWidth and a.CompCode=c.CompCode
		Where LrCode = @LrCode and a.VTSNo=1 and Convert(varchar(6), a.DocDate, 112)=@MnCode and a.CompCode=@CmCode 
	       ) P 
	Order by P.DocDate, [Voucher No.]

End
GO

