CREATE PROCEDURE [dbo].[FAS_Dis_Monthwise_GroupSummary] (@LrCode int, @Start datetime, @End datetime, @CmCode varchar(12)) AS
--Old Name FAS_Dis_Gr_2
Begin

	Set NoCount On
	
	Select LrCode, MnCode, AcMonth, Case When Debit > 0 then Convert(varchar, Debit) Else '' End as Debit,  Case When Credit > 0 then Convert(varchar, Credit) Else '' End as Credit,  
			(Case when sign(CB) = -1 then convert(varchar, -CB)+' Cr' when sign(CB) = 1 then Convert(varchar, CB)+' Dr' when sign(CB) = 0 then ' ' end) as Closing_Balance
	From (
		Select h1.LrCode, h1.MnCode, Datename(month, convert(datetime, Convert(varchar, h1.MnCode)+'01', 112 )) as AcMonth, Isnull(h2.DrAmt, 0) Debit,  Isnull(h2.CrAmt, 0) Credit,
			dbo.fn_FAS_LedgerOpBalance(@LrCode, DateAdd(mm, 1, Convert(datetime, h1.MnCode+'01', 112)), '0', @CmCode) as CB
		From 		(
					Select m.LrCode, n.MnCode 
					From (Select @LrCode as LrCode, @CmCode as CompCode )m
					Full Outer Join (Select Convert(varchar(6), Monthdate, 112) MnCode,@CmCode as CompCode from dbo.fn_FAS_Months(@Start, @End)) n
					On m.CompCode=n.CompCode 	
				)h1
		Left Outer Join
				(
					Select LrCode, Convert(varchar(6), c.Docdate, 112) MnCode, Sum(DrAmt) DrAmt, Sum(CrAmt) CrAmt
					from FAS_VoucherTranSub c 
					Where c.LrCode = @LrCode and (c.DocDate between @Start and @End) and c.CompCode =@CmCode
					Group by c.LrCode, Convert(varchar(6), c.Docdate, 112)
				) h2
		On h1.LrCode=h2.LrCode and h1.MnCode=h2.MnCode			
	       )h	
	
/*	
	
	Declare @OPBalDr as money, @OPBalCr as money
	Select @OPBalCr=OpBalance from FAS_LedgerMaster Where LedgerCode=@LrCode and CompCode=@CmCode
	Select @OPBalDr=@OPBalCr

	If (@OPBalCr <= 0) 
		Select @OPBalCr=0 
	 Else 
		Select @OPBalDr=0 
	
	Select Mncode, @LrCode, DMonth as [Ac Month], Case When r.Debit > 0 then Convert(varchar, r.Debit) Else '' End as Debit, 
		Case When r.Credit > 0 Then Convert(varchar, r.Credit) Else '' End as Credit, r.Closing_Balance
	from 
		 (Select j.MnCode,  Datename(month, convert(datetime, Convert(varchar, j.MnCode)+'01', 112 )) as DMonth,  j.Debit,  j.Credit,
				(Case	when sign(j.CB) = -1 then convert(varchar, -CB)+' Cr' when sign(j.CB) = 1 then Convert(varchar, CB)+' Dr' when sign(j.CB) = 0 then ' ' end) as Closing_Balance
		from
			(Select h.Mncode,  sum(h.dramt) as Debit, sum(h.cramt) as Credit,  
						(Select Sum(m.DrAmt-m.CrAmt)+(@OPBalCr+@OPBalDr) from fas_Voucher_Vw m where m.lrcode=@LrCode and m.compcode =@CmCode and h.MnCode >= Convert(int, Convert(varchar(6), m.DocDate, 112))) as CB
			from 
				(Select Convert(int, Convert(varchar(6), DocDate, 112)) MnCode, DocDate, DrAmt, CrAmt from FAS_Voucher_Vw c where Lrcode=@LrCode and CompCode =@CmCode
				) h
			group by mncode
			) j
		)r
	
	Order by MnCode
*/

End
