CREATE PROCEDURE [dbo].[FAS_Dis_Monthwise_PurchaseRegister] (@Route varchar(42), @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  AS
--Old Name  FAS_Dis_Pr_0
Begin

	Set NoCount On
	Declare @Credit varchar(1), @LnRoute int
	Set @Credit =' '
	Set @LnRoute = Len(@Route)

	Select Mncode, DMonth as [Ac Month], r.Debit, @Credit as Credit, 
		r.Closing_Balance
	from 
		 (Select j.MnCode,  Datename(month, convert(datetime, Convert(varchar, j.MnCode)+'01', 112 )) as DMonth,  Case When isNull(j.Debit, 0) = 0 then ' ' else Convert(varchar, j.Debit)  end as Debit,
				(Case when sign(isNull(j.CB, 0)) = 0 then ' ' else Convert(varchar, CB) end) as Closing_Balance
		from
			(Select h.Mncode,  Sum(h.Amount) as Debit,  
						(Select Sum(Amount) from FAS_VoucherTranMast m Where Left(VrRoute, @LnRoute)=@Route and m.CompCode =@CmCode 
						and (m.DocDate between @PrStart and @PrEnd) and Convert(varchar(6), m.DocDate, 112) <= h.MnCode) as CB
			from 
				(Select h1.MnCode, h2.Amount
				from

					(Select Convert(varchar(6), Monthdate, 112) MnCode from dbo.fn_FAS_Months(@PrStart, @PrEnd)) h1 
				Left Outer Join
					(Select Convert(varchar(6), Docdate, 112) MnCode, Sum(Amount) as Amount from FAS_VoucherTranMast c 
					Where Left(VrRoute, @LnRoute)=@Route and (c.DocDate between @PrStart and @PrEnd) and CompCode =@CmCode
					Group by Convert(varchar(6), Docdate, 112)
					) h2
				On h1.MnCode=h2.MnCode
				) h
			group by mncode
			) j
		)r
	Order by MnCode

End
GO

