CREATE PROCEDURE [dbo].[FAS_Dis_MonthwiseCnt_Voucher] (@Route varchar(42), @PrStart datetime, @PrEnd datetime, @CmCode varchar(12)) 

AS

Begin 
	
		Set NoCount On

		If @Route='07'
			Begin	
				Select @Route as Route,  h1.MnCode,  Datename(month, convert(datetime, Convert(varchar, h1.MnCode)+'01', 112 )) as AcMonth,
						IsNull(Convert(Varchar(5), h2.Cnt), '') as TranCount 
						From (Select Convert(varchar(6), Monthdate, 112) MnCode from dbo.fn_FAS_Months(@PrStart, @PrEnd)) h1 
				Left Outer Join
						(Select Count(distinct DocNo) as Cnt, Convert(varchar(6), Docdate, 112) MnCode from FAS_MEM_VoucherTranMast c 
							Where (c.DocDate between @PrStart and @PrEnd) and CompCode = @CmCode
							Group by Convert(varchar(6), Docdate, 112)
						) h2
				On h1.MnCode=h2.MnCode
				Order by h1.MnCode
			End
		Else
			Begin	
				Select @Route as Route,  h1.MnCode,  Datename(month, convert(datetime, Convert(varchar, h1.MnCode)+'01', 112 )) as AcMonth,
						IsNull(Convert(Varchar(5), h2.Cnt), '') as TranCount 
						From (Select Convert(varchar(6), Monthdate, 112) MnCode from dbo.fn_FAS_Months(@PrStart, @PrEnd)) h1 
				Left Outer Join
						(Select Count(distinct DocNo) as Cnt, Convert(varchar(6), Docdate, 112) MnCode from FAS_VoucherTranMast c 
							Where VrRoute = @Route and (c.DocDate between @PrStart and @PrEnd) and CompCode = @CmCode
							Group by Convert(varchar(6), Docdate, 112)
						) h2
				On h1.MnCode=h2.MnCode
				Order by h1.MnCode
			End
End
GO

