CREATE PROCEDURE [dbo].[FAS_Dis_OB_0] (@LrRoute varchar(42),  @RptDate Datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON		--Corrected On '2005-04-21'	
	
	Select n.LedgerCode as LrCode, n.LedgerName as Particulars,
		isNull((Convert(varchar, Abs(m.BillAmt))  + ' ' + Case sign(m.BillAmt) when -1 then 'Cr' When 1 then 'Dr' End + '     ' ), '') as Amount, 
		isNull((Convert(varchar, Abs(m.AdvAmt)) + ' ' + Case sign(m.AdvAmt) when -1 then 'Cr' When 1 then 'Dr' End + '     ' ), '') as OnAcct, 
		isNull((Convert(varchar, Abs(m.BillAmt+m.AdvAmt)) + ' ' + Case sign(m.BillAmt+m.AdvAmt) when -1 then 'Cr' When 1 then 'Dr' End + '     ' ), '') as TotAmt, n.LrRoute as LrRoute
	from FAS_LedgerMaster n Right Outer Join 
		(Select p.LrCode, Sum(p.AdvAmt) as AdvAmt, Sum(p.BillAmt) as BillAmt
		from
			(Select LrCode, Case When Type='On Acct' then Amount Else 0 End as AdvAmt,
				Case When Type<>'On Acct' then Amount Else 0 End as BillAmt
			from FAS_BillDetails
			where RefDate <= @RptDate and CompCode=@CmCode
			) p 
		group by p.Lrcode) m
	On m.LrCode=n.LedgerCode
	Where (m.BillAmt+m.AdvAmt) <> 0 and Left(n.LrRoute, 4) = @LrRoute and n.CompCode = @CmCode
/*		and Left(n.LrRoute, 4) in ('0206', '0303')  */
	
	order by n.LrRoute, n.LedgerName
End
GO

