CREATE PROCEDURE [dbo].[FAS_Dis_OB_1] (@LrCode int, @RptDate Datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON

	
	

	Select RefNo as [Invoice No], Convert(varchar(10), RefDate, 105) as [Invoice Date],  Amount + ' ' + AcType+'     ' as Amount, Convert(datetime,  DueDate, 105) as [Due Date], DateDiff(day, [DueDate], @RptDate) as Overdue
	from 
		(Select RefNo, RefDate, Dateadd(day, isNull(CreditDays, 0), RefDate) as DueDate, Convert(varchar, Abs(Amount)) as Amount, AcType=Case sign(Amount) when -1 then 'Cr' When 1 then 'Dr' End 
			from 
				(Select isNull(y.RefNo, z.RefNo) as RefNo, 
					isNull(y.RefDate, (Select Min(x.RefDate) from FAS_BillDetails x where x.RefNo=z.RefNo and x.RefDate <= @RptDate and x.LrCode=@LrCode and x.CompCode=@CmCode)) as RefDate, 
					isNull(y.CreditDays, 0) CreditDays, z.Amount 
				from 
					(Select RefNo, RefDate, CreditDays 
					from FAS_BillDetails 
					where LrCode=@LrCode and Type in ('New Ref', 'Advance') and CompCode=@CmCode
					) y 
				Right Outer Join
					(Select RefNo, Sum(Amount) as Amount 
					from FAS_BillDetails
					where Type <> 'On Acct' and RefDate <= @RptDate and LrCode=@LrCode and CompCode=@CmCode
					group by RefNo having sum(Amount) <> 0 
					) z 
				On y.RefNo=z.RefNo 
				) d

		) b
	
	Order by RefDate, RefNo
End
GO

