CREATE PROCEDURE [dbo].[FAS_Dis_OB_2] (@RptDate Datetime, @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON		--Corrected On '2005-04-21'


	
	
	
	Select Case when Left(m.Route, 4) = '0206' then 'Sundry Debtors' when Left(m.Route, 4) = '0303' then 'Sundry Creditors' Else 'Others' End as Particulars,
		isNull((Convert(varchar, Abs(m.BillAmt))  + ' ' + Case sign(m.BillAmt) when -1 then 'Cr' When 1 then 'Dr' End + '     ' ), '') as Amount, 
		isNull((Convert(varchar, Abs(m.AdvAmt)) + ' ' + Case sign(m.AdvAmt) when -1 then 'Cr' When 1 then 'Dr' End + '     ' ), '') as OnAcct, 
		isNull((Convert(varchar, Abs(m.BillAmt+m.AdvAmt)) + ' ' + Case sign(m.BillAmt+m.AdvAmt) when -1 then 'Cr' When 1 then 'Dr' End + '     ' ), '') as TotAmt
	
	from
		(Select q.Route, Sum(BillAmt) as BillAmt, Sum(AdvAmt) as AdvAmt
		from
			(Select p.Route, p.LrCode, Sum(p.AdvAmt) as AdvAmt, Sum(p.BillAmt) as BillAmt
			from
				(Select Left(b.LrRoute, 4) as Route, a.LrCode, Case When Type<>'On Acct' then Amount Else 0 End as BillAmt,
					Case When Type='On Acct' then Amount Else 0 End as AdvAmt
				from FAS_BillDetails a Left Outer Join FAS_LedgerMaster b
				On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode
				where a.RefDate <= @RptDate and Left(b.LrRoute, 4) in ('0206', '0303') and a.CompCode=@CmCode
				) p 
			group by p.Route, p.Lrcode) q
		group by q.Route
		) m
	order by 1
End
GO

