CREATE PROCEDURE [dbo].[FAS_Dis_OB_21] (@LrCode int, @RptDate Datetime, @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON

	
	

	Select 'Bill Amount' as Particulars, Sum(c.Amount) as Amount
	from
		(Select z.Amount
		from fas_billdetails y Join
			(Select m.LrCode, m.RefNo, Sum(m.Amount) as Amount
			from FAS_BillDetails m 
			where m.RefNo <> '' and m.RefDate <= @RptDate and m.LrCode=@LrCode and m.CompCode=@CmCode
			group by m.LrCode, m.RefNo ) z 
		on y.RefNo=z.RefNo and y.LrCode=z.LrCode
		where z.Amount <> 0  and y.Type = 'New Ref' and  y.CompCode=@CmCode
		) c

	Union All

	Select 'Adv/On Acct', isNull(Sum(Amount), 0) 
	from FAS_BillDetails 
	where LrCode = @LrCode and RefNo='' and RefDate <= @RptDate and CompCode=@CmCode
	
End
GO

