CREATE PROCEDURE [dbo].[FAS_Dis_OB_3] (@LrCode int, @RefNo varchar(20), @RefDate datetime, @FinStart datetime, @CmCode varchar(12))

AS

Begin
	Set NOCOUNT ON

	
	

	Select VrRoute, Case VrRoute When 'OpBal' then 'Opening Balance' Else (Select VoucherName from FAS_VoucherMaster b where b.VrRoute+b.VrWidth=a.VrRoute and b.CompCode=@CmCode) End as VName,
		Case VrRoute  When 'OpBal' then '' Else Convert(varchar, DocNo) End as VrNo, 
		Case VrRoute When 'OpBal' then @FinStart Else (Select DocDate from FAS_VoucherTranMast c where c.DocNo=a.DocNo and c.VrRoute=a.VrRoute and c.CompCode=@CmCode) End as VTDate,
		Case Sign(Amount) When -1 then Convert(varchar, -Amount) + ' Cr' When 1 then Convert(varchar, Amount) + ' Dr' Else '' End as Amount
	from FAS_BillDetails a
	where RefNo=@RefNo and LrCode=@LrCode and CompCode=@CmCode and RefDate >= @RefDate
	Order by 4

End
GO

