CREATE PROCEDURE [dbo].[FAS_Dis_OB_Sum] (@LrCode varchar(4), @RptDate Datetime, @CmCode char(4)) 

AS

Begin
	SET NOCOUNT ON

	
	
	
	Select a.Particulars, Case Sign(a.BillAmt) When 1 then Convert(varchar, a.BillAmt)+' Dr' When -1 then Convert(varchar, -a.BillAmt) + ' Cr' End as Amt
	From
		(Select 'Bill Amount' as Particulars, Sum(Amount) as BillAmt
		from FAS_BillDetails
		where Type <> 'On Acct' and RefDate <=  @RptDate and LrCode =@LrCode and CompCode=@CmCode
	
		Union All
	
		Select 'On Acct', Sum(Amount) as AdvAmt
		from FAS_BillDetails
		where Type = 'On Acct' and RefDate <=  @RptDate and LrCode =@LrCode and CompCode=@CmCode
		
		Union All

		Select 'Balance', Sum(Amount) as AdvAmt
		from FAS_BillDetails
		where RefDate <=  @RptDate and LrCode =@LrCode and CompCode=@CmCode

		) a

End
GO

