CREATE PROCEDURE [dbo].[FAS_Dis_PL_0]  (@PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON
	

	Select  Case GrpHd When '0205' Then 0  When '0E' Then 1 When '0D' Then 2 When '06' Then 3 When '05' Then 4 When '08' Then 5 When '07' Then 6 End as SortOrder,
		GrpHd, Case When GrpHd='0205' then 'Opening Stock' else (Select GroupName from FAS_GroupMaster where GrRoute+GrWidth= GrpHd and CompCode=@CmCode) end as Particulars,
		Convert(varchar, Sum(Amount)) as Amount
	
	from
		(Select Case When Left(LrRoute, 4)='0205' then '0205' else Left(LrRoute, 2) end as GrpHd, Amount
		from
			(Select a.LrCode, a1.LrRoute, a.Amount
			from
				(Select LrCode, (sum(DrAmt)-sum(CrAmt)) as Amount from FAS_VoucherTranSub
				where (DocDate between @PrStart and @PrEnd) and Compcode = @CmCode 
				group by LrCode 
				
				Union All
	
				--Opening Stock
				Select LedgerCode, OpBalance from FAS_LedgerMaster where Left(LrRoute, 4)='0205' and CompCode=@CmCode
	
				) a 
				Left Outer Join FAS_LedgerMaster a1 On a.LrCode=a1.LedgerCode Where a1.CompCode=@CmCode
			) b
		where (Left(b.LrRoute, 2) in ('0D', '0E', '05', '06', '07', '08') or Left(b.LrRoute, 4) = '0205')
		) c
	
		group by GrpHd 
		order by 1


End
GO

