CREATE PROCEDURE [dbo].[FAS_Dis_Pr_1] (@Route varchar(42), @MnCode varchar(6),  @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON
		

	Select Voucher_Route, Convert(Varchar(16), DocDate, 105) as Date, Particulars, RefNo, [Voucher No.], Convert(varchar, Debit) as Debit, Convert(varchar, Credit ) as Credit
	from (
		Select a.VrRoute as Voucher_Route, a.DocDate, b.LedgerName as Particulars,
			a.Ref as RefNo, a.DocNo as [Voucher No.], '' as Debit, a.VrAmt as Credit, a.LrCode 
		from FAS_Voucher_Vw a Left Outer Join FAS_LedgerMaster b
		On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode
		Where Left(a.VrRoute, Len(@Route)) = @Route and a.VTSNo=1 and (a.DocDate between @PrStart and @PrEnd) and Convert(varchar(6), a.DocDate, 112) = @MnCode and a.CompCode=@CmCode 
	       ) P 
	Order by P.DocDate, [Voucher No.]

End
