/****** Object:  StoredProcedure [dbo].[FAS_Dis_RatioAnalysis_Groups]    Script Date: 17/06/2026 11:30:02 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Dis_RatioAnalysis_Groups]  (@PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

Begin

	SET NOCOUNT ON

	Select * From 
		(	Select SortOrder, Master, Path, Type, Code, Particulars, (CurrentAsset-CurrentLiability) as ClosingBalance
			From 
			(	Select 1 as SortOrder, '00' as Master,  'WC' as Path, 'Group' as Type, '9999' as Code, 'Working Capital' as Particulars, 
					Sum(IsNull((Case Path When '02' Then ClosingBalance End), 0)) as CurrentAsset,
					Sum(IsNull((Case Path When '03' Then ClosingBalance End), 0)) as CurrentLiability
				From dbo.fn_FAS_LedgersClosingBalance(@PrStart, @PrStart, @PrEnd, @CmCode)  
				Where Path in ('02', '03') and Type = 'Group'
			)m

			Union All

			Select Case Path when '0202'  then 2 when '0201' then 3 when '0B01' then 4 when '0206' then 5 when '0303' then 6
					when '0E' then 7 when '0D' then 8 when '0205' then 9 when '00' then 10 End as SortOrder,
					Master, Path, Type, Code, Particulars, ClosingBalance 
			From dbo.fn_FAS_LedgersClosingBalance(@PrStart, @PrStart, @PrEnd, @CmCode) 
			Where  Path in ('00', '0201', '0202', '0205', '0206', '0303', '0B01', '0D', '0E') and Type = 'Group' 
								
			Union All 

			Select SortOrder, Master, Path, Type, Code, Particulars, (SalesAc/(CurrentAsset-CurrentLiability)) as ClosingBalance
			From 
			(	Select 11 as SortOrder, '00' as Master,  'WT' as Path, 'Group' as Type, '9999' as Code,  'Working Capital TurnOver' as Particulars, 
					Sum(IsNull((Case Path When '0E' Then ClosingBalance End ) , 0)) as SalesAc,
					Sum(IsNull((Case Path When '02' Then ClosingBalance End), 0)) as CurrentAsset,
					Sum(IsNull((Case Path When '03' Then ClosingBalance End), 0)) as CurrentLiability
				From dbo.fn_FAS_LedgersClosingBalance(@PrStart, @PrStart, @PrEnd, @CmCode)  
				Where  Path in('0E', '02', '03') and Type = 'Group'			
			)n

			Union All
			
			Select SortOrder, Master, Path, Type, Code, Particulars, (SalesAc/ClStock) as ClosingBalance
			From 			
			(	Select 12 as SortOrder, '00' as Master,  'IT' as Path, 'Group' as Type, '9999' as Code,  'Inventory TurnOver' as Particulars, 
					Sum(IsNull((Case Path When '0E' Then ClosingBalance End ) , 0)) as SalesAc,
					(Select Sum(ClosingStock) as ClosingStock From dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode) ) as ClStock
				From dbo.fn_FAS_LedgersClosingBalance(@PrStart, @PrStart, @PrEnd, @CmCode)  
				Where  Path in('0E', '02', '03') and Type = 'Group'			
			)p
		)x
	Order by SortOrder
		

End
GO

