CREATE PROCEDURE [dbo].[FAS_Dis_TB_0] (@PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON

	Select Master, Path, Type, Code, Case Type when 'Master' then Particulars
	 				        when 'Group' then Space(Len(Path)) + Particulars
	                                                             when 'Ledger' then space(Len(Path))+'    '+Particulars End as Particulars,
	Case sign(OpBalance) When 1 Then Convert(varchar, OpBalance) Else '' End as OB_Dr, 
	Case sign(OpBalance) When -1 Then Convert(varchar, -OpBalance) Else '' End as OB_Cr, 
	
	Case sign(DrAmt) When 0 Then '' Else Convert(varchar, DrAmt)  End as Tran_Dr, 
	Case sign(CrAmt) When 0 Then '' Else Convert(varchar, CrAmt) End as Tran_Cr, 
	
	Case sign(ClosingBalance) When 1 Then Convert(varchar, ClosingBalance) Else '' End as CB_Dr, 
	Case sign(ClosingBalance) When -1 Then Convert(varchar, -ClosingBalance) Else '' End as CB_Cr
	
	from [dbo].[fn_FAS_Rpt_TrialBalance] (@PrStart, @PrStart, @PrEnd, @CmCode) 
	Order by Master, Path, Type, Particulars

End
GO

