CREATE PROCEDURE [dbo].[FAS_Dis_Vouchers] (@PrStart datetime, @PrEnd datetime, @CmCode varchar(12))
--Old Name FAS_Dis_Vr_0
 AS

Begin
	Set NOCOUNT ON	


	Select a.VoucherCode, a.VrRoute+a.VrWidth as Path, a.VoucherName as [Voucher Types],  Count(b.DocNo) as [No. of Vouchers]	
	From FAS_VoucherMaster a
	Left Outer Join FAS_VoucherTranMast b
		On a.VrRoute+a.VrWidth = b.VrRoute and a.CompCode = b.CompCode and (b.DocDate Between @PrStart and @PrEnd)
	Where a.CompCode= @CmCode
	Group by a.VoucherCode, a.VrRoute+a.VrWidth, a.VoucherName

	UNION ALL

	Select 7, '07', 'MEMORANDUM', Count(DocNo) 
	From FAS_MEM_VoucherTranMast
	Where CompCode=@CmCode and (DocDate Between @PrStart and @PrEnd)


	Order by 2

End
GO

