CREATE PROCEDURE [dbo].[FAS_Dis_Vouchers_GroupSummary] (@LrCode int, @YearMonth varchar(10), @CmCode varchar(12))
--Old Name FAS_Dis_Gr_3
AS

Begin
	SET NOCOUNT ON

	Select Voucher_Route, Convert(Varchar(10), f.DocDate, 105) as Date, LedgerName as Particulars, VoucherName as [Voucher Type], 
		c.DocNo as [Voucher No.],  Case When f.DrAmt > 0 then Convert(Varchar, f.DrAmt) Else '' End as Debit, 
		Case When f.CrAmt > 0 then Convert(Varchar, f.CrAmt) Else '' End as Credit 
	from FAS_VrDetails_Vw c Right Outer Join 
			(Select DocNo, DocDate, VrRoute, DrAmt, CrAmt, CompCode from FAS_VoucherTranSub Where LrCode=@LrCode and CompCode=@CmCode) f
		On c.DocNo=f.DocNo and c.DocDate=f.DocDate and c.Voucher_Route=f.VrRoute and c.CompCode=f.CompCode
	Inner Join
		(Select Min(VTSNo) as MinVTSNo, a.DocNo, a.DocDate, a.VrRoute 
		from fas_VoucherTranSub a
		Where a.LrCode <> @LrCode and Convert(varchar(6), DocDate, 112) = @YearMonth and a.CompCode=@CmCode
		Group By a.VrRoute, a.DocNo, a.DocDate ) d
	On c.DocNo=d.DocNo and c.DocDate=d.DocDate and c.VTSNo=d.MinVTSNo and c.Voucher_Route=d.VrRoute 
	Where c.Compcode = @CmCode
	Order by f.DocDate, c.DocNo

End
GO

