CREATE PROCEDURE [dbo].[FAS_Dis_Vouchers_Ledgers] (@LrCode varchar(42), @MnCode varchar(6), @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))
--Old Name FAS_Dis_Lr_2
AS

Begin
	SET NOCOUNT ON

	Declare @OPBal money
	Select @OPBal=dbo.fn_FAS_LedgerOpBalance(@LrCode,  Convert(datetime, @MnCode+'01', 112), '0', @CmCode)

	Select VrRoute, DocDate, VoucherName, DocNo, RefNo, n1.LedgerName as Particulars, Debit, Credit, Case When CB < 0 then Convert(varchar, -CB) + ' Cr' When CB > 0 then Convert(varchar, CB) + ' Dr' Else ' ' End Closing_Balance
	from
	
		(Select m.VrRoute, m.DocDate, m.VoucherName, m.DocNo, m.RefNo, 
			isNull((Select Top 1 m1.LrCode from FAS_VoucherTranSub m1 Where m1.DocNo=m.DocNo and m1.VrRoute=m.VrRoute and m1.LrCode<>m.LrCode and m1.CompCode=@CmCode), m.LrCode) as Particulars,
			m.Debit, m.Credit, m.LrCode,
			isNull((Select Sum(DrAmt-CrAmt)  from FAS_VoucherTranSub d 
				Where d.LrCode=m.LrCode and Convert(varchar(6), d.DocDate, 112)=@MnCode
					and ((d.docDate < m.DocDate) or ((d.DocDate=m.DocDate) and (d.VrRoute < m.VrRoute or (d.VrRoute=m.VrRoute and d.DocNo<=m.DocNo))))
					 and d.CompCode=m.CompCode
			), 0)  + @OpBal as CB
		from
	
			(Select top 100 Percent  a.VrRoute, a.DocDate, c.VoucherName, a.DocNo,
				Case When LTrim(RTrim(a.Ref))='' then b.RefType+':'+Convert(varchar, b.RefNo) else a.Ref end as RefNo,  
				a.DrAmt as Debit, a.CrAmt as Credit, a.LrCode, a.CompCode
			from FAS_Voucher_vw a Left Outer Join FAS_VoucherTranRef b
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode and a.DocDate=b.DocDate and a.DocType=b.DocType
			Left Outer Join FAS_VoucherMaster c On a.VrRoute=c.VrRoute+c.VrWidth and a.CompCode=c.CompCode
			Where a.LrCode = @LrCode and Convert(varchar(6), a.DocDate, 112)=@MnCode and a.CompCode=@CmCode 
			Order by a.DocDate,  a.DocNo
			)  m

		) n
	Left Outer Join FAS_LedgerMaster n1 On n.Particulars=n1.LedgerCode 
	Where n1.CompCode=@CmCode
	Order by DocDate, VrRoute, DocNo	

End
GO

