CREATE PROCEDURE [dbo].[FAS_Dis_Vouchers_Vouchers] (@Route varchar(42), @IncludeSubVouchers bit, @FromDate datetime, @ToDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))
--Old Name FAS_Dis_Vr_2
AS

Begin
	SET NOCOUNT ON

	If Len(@Route)=0  or @Route = '0'
		Begin
			Select a.VrRoute, a.DocDate, 
				Case When a.isCancelled='1' Then 'CANCELLED' Else
				(Select p.LedgerName from  FAS_VoucherTranSub q  Inner Join FAS_LedgerMaster p On p.LedgerCode=q.LrCode and p.CompCode=q.CompCode
				Where q.VrRoute=a.VrRoute and q.DocNo=a.DocNo and q.VTSNo=1 and q.CompCode=@CmCode) End as Particulars,
				a.Ref as RefNo, a.DocNo as VrNo, isNull(Sum(a.DrAmt), 0) as TranAmt
			from FAS_Voucher_vw a 
			Where (a.DocDate between @PrStart and @PrEnd) and (a.DocDate between @FromDate and @ToDate)  and a.CompCode=@CmCode
			Group by a.VrRoute, a.DocDate, a.DocNo, a.Ref, a.isCancelled 
			Order by DocDate, VrNo
		End
	Else
		If @Route='07'
			Begin
				Select a.VrRoute, a.DocDate, 
					Case When a.isCancelled='1' Then 'CANCELLED' Else
					(Select p.LedgerName from  FAS_MEM_VoucherTranSub q  Inner Join FAS_LedgerMaster p On p.LedgerCode=q.LrCode and p.CompCode=q.CompCode
					Where q.VrRoute=a.VrRoute and q.DocNo=a.DocNo and q.VTSNo=1 and q.CompCode=@CmCode) End as Particulars,
					a.Ref as RefNo, a.DocNo as VrNo, isNull(Sum(b.DrAmt), 0) as TranAmt
				from FAS_MEM_VoucherTranMast a Left Outer Join FAS_MEM_VoucherTranSub b
					On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
				Where (a.DocDate between @PrStart and @PrEnd) and (a.DocDate between @FromDate and @ToDate)  and a.CompCode=@CmCode
				Group by a.VrRoute, a.DocDate, a.DocNo, a.Ref, a.isCancelled
				Order by a.DocDate, a.DocNo
			End	
		Else
			Begin
				If @IncludeSubVouchers = '1'
					Begin
						Select a.VrRoute, a.DocDate, 
							Case When a.isCancelled='1' Then 'CANCELLED' Else
							(Select p.LedgerName from  FAS_VoucherTranSub q  Inner Join FAS_LedgerMaster p On p.LedgerCode=q.LrCode and p.CompCode=q.CompCode
							Where q.VrRoute=a.VrRoute and q.DocNo=a.DocNo and q.VTSNo=1 and q.CompCode=@CmCode) End as Particulars,
							a.Ref as RefNo, a.DocNo as VrNo, isNull(Sum(a.DrAmt), 0) as TranAmt
						from FAS_Voucher_vw a 
						Where Left(a.VrRoute, Len(@Route)) = @Route  and (a.DocDate between @PrStart and @PrEnd) and (a.DocDate between @FromDate and @ToDate)  and a.CompCode=@CmCode
						Group by a.VrRoute, a.DocDate, a.DocNo, a.Ref, a.isCancelled 
						Order by DocDate, VrNo
					End		
				Else
					Begin
						Select a.VrRoute, a.DocDate, 
							Case When a.isCancelled='1' Then 'CANCELLED' Else
							(Select p.LedgerName from  FAS_VoucherTranSub q  Inner Join FAS_LedgerMaster p On p.LedgerCode=q.LrCode and p.CompCode=q.CompCode
							Where q.VrRoute=a.VrRoute and q.DocNo=a.DocNo and q.VTSNo=1 and q.CompCode=@CmCode) End as Particulars,
							a.Ref as RefNo, a.DocNo as VrNo, isNull(Sum(a.DrAmt), 0) as TranAmt
						from FAS_Voucher_vw a 
						Where a.VrRoute = @Route  and (a.DocDate between @PrStart and @PrEnd) and (a.DocDate between @FromDate and @ToDate)  and a.CompCode=@CmCode
						Group by a.VrRoute, a.DocDate, a.DocNo, a.Ref, a.isCancelled  
						Order by DocDate, VrNo
					End	

			End
End
GO

