CREATE PROCEDURE [dbo].[FAS_Dis_Vr_1] (@Route varchar(42), @PrStart datetime, @PrEnd datetime, @CmCode varchar(12)) 

AS

Begin

	Set NoCount On

	Declare @Debit varchar(1), @LnRoute int
	Set @Debit =' '
	Set @LnRoute=Len(@Route)	

	Select @Route as Route, Mncode, DMonth as [Ac Month], r.TranAmt as  [Tran Amt], r.Cum_Total
	from 
		 (Select j.MnCode,  Datename(month, convert(datetime, Convert(varchar, j.MnCode)+'01', 112 )) as DMonth,  Case When isNull(j.TranAmt, 0) = 0 then ' ' else Convert(varchar, j.TranAmt)  end as TranAmt,
				(Case when sign(isNull(j.CB, 0)) = 0 then ' ' else Convert(varchar, CB) end) as Cum_Total
		from
			(Select h.Mncode,  Sum(h.Amount) as TranAmt,  
						(Select Sum(DrAmt) from FAS_VoucherTranSub m Where Left(VrRoute, @LnRoute)=@Route and m.CompCode =@CmCode 
						and (m.DocDate between @PrStart and @PrEnd) and Convert(varchar(6), m.DocDate, 112) <= h.MnCode) as CB
			from 
				(Select h1.MnCode, h2.Amount
				from

					(Select Convert(varchar(6), Monthdate, 112) MnCode from dbo.fn_FAS_Months(@PrStart, @PrEnd)) h1 
				Left Outer Join
					(Select Convert(varchar(6), Docdate, 112) MnCode, Sum(DrAmt) as Amount from FAS_VoucherTranSub c 
					Where Left(VrRoute, @LnRoute)=@Route and (c.DocDate between @PrStart and @PrEnd) and CompCode =@CmCode
					Group by Convert(varchar(6), Docdate, 112)
					) h2
				On h1.MnCode=h2.MnCode
				) h
			group by mncode
			) j
		)r
	Order by MnCode
End
GO

