CREATE PROCEDURE [dbo].[FAS_Dis_Vr_2] (@Route varchar(42), @MnName varchar(10), @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON

	Declare @RouteLen int
	Set @RouteLen = Len(@Route)

	Select Voucher_Route, Convert(Varchar(10), DocDate, 105) as Date, Particulars, RefNo, [Voucher No.], Convert(varchar, TranAmt)  as [Tran Amt], Convert(varchar, CB) as Cum_Total
	from (
		Select a.VrRoute as Voucher_Route, a.DocDate, 
			(Select p.LedgerName from  FAS_VoucherTranSub q  Inner Join FAS_LedgerMaster p On p.LedgerCode=q.LrCode and p.CompCode=q.CompCode
			Where q.VrRoute=a.VrRoute and q.DocNo=a.DocNo and q.VTSNo=1 and q.CompCode=@CmCode) as Particulars,
			a.Ref as RefNo, a.DocNo as [Voucher No.], Sum(a.DrAmt) as TranAmt, 
					(Select Sum(DrAmt) from FAS_VoucherTranSub m Where Left(VrRoute, @RouteLen)=@Route and m.CompCode =@CmCode 
						and Convert(varchar(6), m.DocDate, 112) = Convert(varchar(6), a.DocDate, 112)  and m.DocDate<=a.DocDate and m.DocNo<=a.DocNo)as CB
		from FAS_Voucher_vw a 
		Where Left(a.VrRoute, @RouteLen) = @Route  and (a.DocDate between @PrStart and @PrEnd) and datename(Month, a.DocDate)=@MnName and a.CompCode=@CmCode
		Group by a.VrRoute, a.DocDate, a.DocNo, a.Ref 
	       ) P 
	Order by P.DocDate, [Voucher No.]

End
