CREATE PROCEDURE [dbo].[FAS_ExpenseBudget] (@UserKey varchar(32), @DocType varchar(3), @DocNo int, @DocDate datetime, @CmCode varchar(12), @Finyear varchar(15))

 AS

BEGIN

	Declare @AsOnDate datetime, @RptDate datetime

	Select @AsOnDate=getdate()
	Select @RptDate=Convert(varchar(10), @AsOnDate, 120)

	Declare @BranchID varchar(2), @CompID varchar(2)

	Select @BranchID=Substring(@CmCode, 3, 2), @CompID=Left(@CmCode, 2)
	

	Declare @StartFrom datetime, @Frequency tinyint, @Period varchar(1)
	
	Select @StartFrom=StartFrom, @Frequency=Frequency, @Period=Period 
	From FAS_ExpenseBudget_Hdr a1
	Where a1.DocNo=@DocNo and a1.DocDate=@DocDate and a1.DocType=@DocType and a1.CompCode=@CmCode
		and a1.RevNo=isNull((Select Max(RevNo) From FAS_ExpenseBudget_Hdr a2 
					Where a2.DocNo=@DocNo and a2.DocDate=@DocDate and a2.DocType=@DocType and a2.CompCode=@CmCode
					), 0)

	Declare @ColSeq int, @FromDate datetime, @ToDate datetime
	
	
	Select @FromDate = Convert(varchar(7), @StartFrom, 120) + '-01'

	If @Period='Y'
		Select @ToDate = DateAdd(yyyy, @Frequency, @FromDate)
	Else
		Select @ToDate = DateAdd(mm, @Frequency, @FromDate)
	    	


	CREATE TABLE [#FAS_ExpenseBudget_LrValues] 
		(
			[UserKey] [varchar] (32) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL ,
			[ColSeq] [int] NOT NULL CONSTRAINT [DF_FAS_ExpenseBudget_LrValues_ColumnSeq] DEFAULT (0),
			[LrCode] [int] NOT NULL ,
			[ActualAmt] [money] NOT NULL CONSTRAINT [DF_FAS_ExpenseBudget_LrValues_CashAmt] DEFAULT (0),
			[CompCode] [char] (10) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL ,
			CONSTRAINT [PK_FAS_ExpenseBudget_LrValues] PRIMARY KEY  CLUSTERED 
				(
					[UserKey],
					[ColSeq],
					[LrCode],
					[CompCode]
				)  ON [PRIMARY] 
		) ON [PRIMARY]


	    	
	Select @ColSeq=1

	Insert into #FAS_ExpenseBudget_LrValues
		Select @UserKey, @ColSeq+2, -1,  
			isNull(dbo.fn_FAS_Get_ExpenseBudget_SalesPlan (@AsOnDate, @RptDate, 2, @FromDate, @ToDate, @BranchID, @CompID, @Finyear), 0), @CmCode

	Insert into #FAS_ExpenseBudget_LrValues		
		Select @UserKey, @ColSeq, LrCode, isNull(CashAmt, 0), @CmCode 
		From FAS_ExpenseBudget_Dtl a1
		Where a1.DocNo=@DocNo and a1.DocDate=@DocDate and a1.DocType=@DocType and a1.LrCode is Not Null and a1.CompCode=@CmCode
			and a1.RevNo = (Select Max(RevNo) From FAS_ExpenseBudget_Dtl a2 
						Where a2.DocNo=@DocNo and a2.DocDate=@DocDate and a2.DocType=@DocType and a2.CompCode=@CmCode
							and a2.LrCode=a1.LrCode
						Group By LrCode
					)

	Insert into #FAS_ExpenseBudget_LrValues		
		Select @UserKey, @ColSeq+1, LrCode, isNull(CreditAmt, 0), @CmCode 
		From FAS_ExpenseBudget_Dtl a1
		Where a1.DocNo=@DocNo and a1.DocDate=@DocDate and a1.DocType=@DocType and a1.LrCode is Not Null and a1.CompCode=@CmCode
			and a1.RevNo = (Select Max(RevNo) From FAS_ExpenseBudget_Dtl a2 
						Where a2.DocNo=@DocNo and a2.DocDate=@DocDate and a2.DocType=@DocType and a2.CompCode=@CmCode
							and a2.LrCode=a1.LrCode
						Group By LrCode
					)


	Declare curValue Cursor For
		Select ColSeq, FromDate, ToDate
		From FAS_ExpenseBudget_Tmp
		Where UserKey=@UserKey and CompCode=@CmCode
		Order By ColSeq
	
		OPEN curValue
		FETCH NEXT FROM curValue into @ColSeq, @FromDate, @ToDate			
		

		WHILE @@FETCH_STATUS =  0 

			BEGIN

				Insert into #FAS_ExpenseBudget_LrValues
					Select @UserKey, @ColSeq, -1,  
						isNull(dbo.fn_FAS_Get_ExpenseBudget_SalesPlan (@AsOnDate, @RptDate, 2, @FromDate, @ToDate, @BranchID, @CompID, @Finyear), 0), @CmCode

				Insert into #FAS_ExpenseBudget_LrValues
					Select @UserKey, @ColSeq, LrCode, isNull(ActualAmt, 0), @CmCode
					From dbo.fn_FAS_Get_ExpenseBudget_Ledgers (@FromDate, @ToDate, @CmCode) 


				FETCH NEXT FROM curValue into @ColSeq, @FromDate, @ToDate
			END

	CLOSE curValue
	DEALLOCATE curValue


	Select ColSeq, LrCode, ActualAmt From #FAS_ExpenseBudget_LrValues Where ActualAmt > 0 Order By ColSeq

END
GO

