GO


CREATE PROCEDURE [dbo].[FAS_FinyearSplit_Tfr_Bill](@DocDate datetime,@FinEnd datetime,@UserID int,@Transtamp datetime,@SplitCmCode Varchar(12),@CompCode Varchar(12))
As
BEGIN
	SET NOCOUNT ON 
			
	Insert into FAS_BillDetails
	Select 'OPB', 0, @DocDate, 1, 'OpBal', LrCode,
		(
			Select Count(distinct RefNo) 
			from FAS_Billdetails q 
			Where q.LrCode=p.LrCode and q.RefNo<=p.RefNo and q.CompCode=@SplitCmCode
		) as BillIndex,
	RefType, RefNo, RefDate, BalanceAmt, 0, @CompCode, @UserID, @Transtamp
	From 
	(
		Select m.LrCode, 'New Ref' as RefType, m.RefNo, m.BalanceAmt, 
			(
				Select Min(RefDate) 
				from FAS_BillDetails m1 
				Where m1.RefNo=m.RefNo and m1.LrCode=m.LrCode and m1.CompCode=@SplitCmCode
			) as RefDate
		From 
		(
			Select a.LrCode, a.RefNo, Sum(a.Amount)as BalanceAmt 
			from fas_billdetails a
			Where a.Type <> 'On Acct' and a.DocDate <= @FinEnd and a.CompCode=@SplitCmCode
			group by a.LrCode, a.RefNo Having Sum(A.Amount) <> 0
		) m 
	) p
	Order By LrCode, RefNo
  
END

GO

