/****** Object:  StoredProcedure [dbo].[FAS_GetCurBalance]    Script Date: 17/06/2026 11:30:04 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_GetCurBalance] (@LCode char(5), @CompCode varchar(12), @CBal float Output) AS
begin

Set NoCount On

	Declare @OPBal float, @Cr Float, @Dr Float

	Select @OPBal = OPbalance  from FAS_LedgerMaster where LedgerCode = @LCode and CompCode = @CompCode

	Select @Cr = Sum(CrAmt), @Dr = Sum(DrAmt) from FAS_VoucherTranSub where LrCode = @LCode and CompCode = @CompCode

	/* Select @Cr = isNull(Sum(Amt), 0) from FAS_VoucherTranSub where LrCode = @LCode and AcType = 'Cr'
	Select @Dr = isNull(Sum(Amt), 0) from FAS_VoucherTranSub where LrCode = @LCode and AcType = 'Dr' */

	If sign(@OPBal) = 1
		Set @CBal = (@OPBal+@Cr) - @Dr
	Else
		Set @CBal =@Cr -  (-@OPBal+@Dr)
end
GO

/****** Object:  StoredProcedure [dbo].[FAS_GetTermsDetails]    Script Date: 17/06/2026 11:30:04 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO





CREATE PROCEDURE [dbo].[FAS_GetTermsDetails] (@AcCode int, @BranchID varchar(3), @CompID varchar(3))
AS
SET NOCOUNT ON
	Select 
		a.PackingCode,
			isNull((select b1.Description from TERMSMASTER b1 
			where b1.TypeFlg='Packing & Forwarding' and b1.Code=a.PackingCode and b1.Branchid=a.Branchid and b1.Compid=a.Compid), '') PackingDesc,
		a.InsuranceCode,
			isNull((select b4.Description from TERMSMASTER b4 
			where b4.TypeFlg='Insurance' and b4.Code=a.InsuranceCode and b4.Branchid=a.Branchid and b4.Compid=a.Compid), '') InsuranceDesc,
		a.DeliveryCode,
			isNull((select b2.Description from TERMSMASTER b2 
			where b2.TypeFlg='Delivery Instruction' and b2.Code=a.DeliveryCode and b2.Branchid=a.Branchid and b2.Compid=a.Compid), '') DeliveryDesc,
		a.PaymentCode,
			isNull((select b3.Description from TERMSMASTER b3 
			where b3.TypeFlg='Payment Terms' and b3.Code=a.PaymentCode and b3.Branchid=a.Branchid and b3.Compid=a.Compid), '') PaymentDesc,
		a.Freightcode,
			isNull((select b6.Description from TERMSMASTER b6 
			where b6.TypeFlg='Freight' and b6.Code=a.FreightCode and b6.Branchid=a.Branchid and b6.Compid=a.Compid), '') FreightDesc,
		a.ModeCode,
			isNull((select b5.Description from TERMSMASTER b5 
			where b5.TypeFlg='Mode' and b5.Code=a.ModeCode and b5.Branchid=a.Branchid and b5.Compid=a.Compid), '') ModeDesc,
		a.FormCode,
			isNull((select b.Description from TERMSMASTER b 
			where b.TypeFlg='Form' and b.Code=a.FormCode and b.Branchid=a.Branchid and b.Compid=a.Compid), '') FormDesc, 
		a.CustomerFormulaCode,
			isNull((Select top 1 b7.FrmLName from Com_FormulaMast_Hdr b7
			where b7.ModuleCode = 4 and b7.FrmID=a.CustomerFormulaCode and b7.BranchID=a.BranchID and b7.CompID=a.CompID), '') CustomerFormulaName,
		a.VendorFormulaCode,
			isNull((Select top 1 b8.FrmLName from Com_FormulaMast_Hdr b8
			where b8.ModuleCode = 9 and b8.FrmID=a.VendorFormulaCode and b8.BranchID=a.BranchID and b8.CompID=a.CompID), '') VendorFormulaName
  	from FAS_PARTY_MASTER a 
	where a.PartyCode = @AcCode and a.Branchid=@BranchID and a.Compid = @CompID
GO

