CREATE PROCEDURE [dbo].[FAS_Ins_DefaultBooks]  
 (@CCode [varchar](5),   
  @UserCreated  [varchar](20),  
  @DateCreated  [datetime])  
  
AS  
Begin  
  
Set NoCount On  
  
 Declare @MaxNo [varchar](5)  
  
 Insert into FAS_GroupMaster Select Code, Name, Alias,  Width, Route, '0', Master, '1', @CCode, @UserCreated, @DateCreated  
          from FAS_DefaultGroups where Type = 'G'  
  
 Insert into FAS_LedgerMaster Select Code, Name, Alias, Name, Route, 0, 0, 0, 0,  0, '1', @CCode, @UserCreated, @DateCreated  
          from FAS_DefaultGroups where Type = 'L'  
  
   Insert into FAS_VoucherMaster Select Code, Name,  Alias, Width, Route,0, '', '', '', 1, 1, 0,  'Finyearly', 0, '1', '1',  
          @CCode, @UserCreated, @DateCreated  
          from FAS_DefaultGroups where Type = 'V' and Code in (1, 2, 3, 6, 9, 11, 15, 20)  
  
  
End
GO

