CREATE PROCEDURE [dbo].[FAS_Ins_ExpenseBudget_Dtl]
	(@DocType	[Varchar](3),
	 @DocNo	[int],
	 @DocDate 	[datetime],
	 @LrCode 	[int],
	 @CashAmt 	[float],
	 @CreditAmt 	[float],
	 @UserID 	[varchar](10),
	 @CompCode 	[varchar](12),
	 @TranStamp 	[datetime])

AS 


	DECLARE @RevNo int, @RevDate datetime
	
	Select @RevNo=Max(RevNo)
	From FAS_ExpenseBudget_Dtl 
	Where DocType=@DocType and DocNo=@DocNo and DocDate=@DocDate and LrCode=@LrCode and CompCode=@CompCode --and TranStamp=@TranStamp

	Select @RevNo=isNull(@RevNo+1, 0)

	Select @RevDate=Convert(varchar(10), @TranStamp, 120)


	INSERT INTO [FAS_ExpenseBudget_Dtl] 
		 ( [DocType],
		 [DocNo],
		 [DocDate],
		 [LrCode],
		 [CashAmt],
		 [CreditAmt],
		 [RevNo],
		 [RevDate],
		 [UserID],
		 [CompCode],
		 [TranStamp]) 
	 
	VALUES 
		( @DocType,
		 @DocNo,
		 @DocDate,
		 @LrCode,
		 @CashAmt,
		 @CreditAmt,
		 @RevNo,
	   	 @RevDate,
		 @UserID,
		 @CompCode,
		 @TranStamp)
GO

