/****** Object:  StoredProcedure [dbo].[FAS_Ins_LedgerMaster]    Script Date: 17/06/2026 11:30:05 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_Ins_LedgerMaster]    
 (@LedgerCode     [int],    
  @LedgerName     [varchar](50),      
  @Alias      [varchar](50),   
  @RegisteredName [varchar](200),   
  @LrRoute     [varchar](42),    
  @MaxReached     [bit],    
  @isBillwise    [bit],    
  @CreditDays    [int],    
  @OPbalance     [money],    
  @isCostCentreApplicable [bit],    
  @isActive      [bit],    
  @CompCode      [varchar](12),    
  @UserID      [varchar](10),    
  @TranStamp     [datetime])    
AS     
BEGIN    
SET NOCOUNT ON;

	Begin Tran    
     
	 declare @cBranchid varchar(12)    
     
	 --Delete From FAS_LedgerMaster Where LedgerCode = @LedgerCode and CompCode= @CompCode    
     
	 declare  BranchidList cursor For    
	 select Compid+Branchid from Company_Master where IsBranchAvail = '0' and Compid = Left(@CompCode, 2)    
    
    
	 OPEN BranchidList    
	 FETCH NEXT FROM BranchidList into @cBranchid     
	 WHILE @@FETCH_STATUS = 0    
     
	 BEGIN    
     
	  if not exists (select * from FAS_LedgerMaster Where LedgerCode = @LedgerCode and CompCode= @cBranchid)     
      
	   begin     
		INSERT INTO [FAS_LedgerMaster]     
		  ( [LedgerCode],    
		  [LedgerName],          
		  [Alias],     
		  [RegisteredName],         
		  [LrRoute],    
		  [MaxReached],    
		  [isBillwise],    
		  [CreditDays],    
		  [OPbalance],    
		  [isCostCentreApplicable],    
		  [isActive],    
		  [CompCode],    
		  [UserID],    
		  [TranStamp])     
         
		VALUES     
		 ( @LedgerCode,    
		  @LedgerName,          
		  @Alias,     
		  @RegisteredName,         
		  @LrRoute,    
		  @MaxReached,    
		  @isBillwise,    
		  @CreditDays,    
		  0,    
		  @isCostCentreApplicable,    
		  @isActive,    
		  @cBranchid,    
		  @UserID,    
		  @TranStamp)    
	   end    
    
	  FETCH NEXT FROM BranchIDList into @cBranchid     
	 END    
      
	 close BranchIDList    
	 deallocate BranchIDList    
     
	 Update FAS_LedgerMaster  Set OPbalance = @OPbalance where LedgerCode=@LedgerCode and CompCode = @CompCode    
    
	Commit Tran  
END  
GO

/****** Object:  StoredProcedure [dbo].[FAS_Ins_LedgerMaster_ERPRef]    Script Date: 17/06/2026 11:30:05 ******/
