CREATE PROCEDURE [dbo].[FAS_Ins_LedgerMaster_ERPRef]
	(@LedgerCode 	[int],
	 @VendorCode 	[varchar](10),
	 @IsParty 	[bit],
	 @FormCode 	[int],
	 @PackingCode 	[int],
	 @DeliveryCode 	[int],
	 @PaymentCode 	[int],
	 @InsuranceCode 	[int],
	 @ModeCode 	[int],
	 @Freightcode 	[int],
	 @IsSubcontractor 	[bit],
	 @CreditDaysPeriod 	[varchar](20),
	 @CurrencyCode 	[char](3),
	 @CustomerFormulaCode 	[int],
	 @VendorFormulaCode 	[int],
	 @Userid 	[varchar](10),
	 @CompCode 	[varchar](12),
	 @TranStamp 	[datetime])

AS

	
	declare @cBranchid varchar(12)
	
	declare  CurBranchidList cursor For
	select Compid+Branchid from Company_Master where IsBranchAvail = '0' and Compid = Left(@CompCode, 2)

	OPEN CurBranchidList
	FETCH NEXT FROM CurBranchidList into @cBranchid 

	WHILE @@FETCH_STATUS = 0
		BEGIN	
			INSERT INTO [ERP].[dbo].[FAS_LedgerMaster_ERPRef] 
				 ( [LedgerCode],
				 [VendorCode],
				 [IsParty],
				 [FormCode],
				 [PackingCode],
				 [DeliveryCode],
				 [PaymentCode],
				 [InsuranceCode],
				 [ModeCode],
				 [Freightcode],
				 [IsSubcontractor],
				 [CreditDaysPeriod],
				 [CurrencyCode],
				 [CustomerFormulaCode],
				 [VendorFormulaCode],
				 [Userid],
				 [CompCode],
				 [TranStamp]) 
			 
			VALUES 
				( @LedgerCode,
				 @VendorCode,
				 @IsParty,
				 @FormCode,
				 @PackingCode,
				 @DeliveryCode,
				 @PaymentCode,
				 @InsuranceCode,
				 @ModeCode,
				 @Freightcode,
				 @IsSubcontractor,
				 @CreditDaysPeriod,
				 @CurrencyCode,
				 @CustomerFormulaCode,
				 @VendorFormulaCode,
				 @Userid,
				 @CompCode,
				 @TranStamp)
	
			FETCH NEXT FROM CurBranchidList into @cBranchid 
	
		End
	
 	
	close CurBranchidList
	deallocate CurBranchidList
GO

