CREATE PROCEDURE [dbo].[FAS_INS_PARTY_ADDRESS]      --(Not in used)
 (  
  @PartyCode  [int],      
  @Add1  [varchar](30),      
  @Add2  [varchar](30),      
  @Add3  [varchar](30),      
  @Country [varchar](50),  
  @State [varchar](50),  
  @City   [varchar](20),      
  @Pincode  [varchar](7),      
  @Phone  [varchar](25),      
  @Fax   [varchar](25),      
  @Cellular  [varchar](25),      
  @EMail  [varchar](50),      
  @CST   [varchar](25),      
  @CSTDate  [datetime],      
  @LST   [varchar](25),      
  @LSTDate  [datetime],      
  @GSTRegNo [Varchar](50),    
  @GSTRegDate [datetime],    
  @ProvisionalID [Varchar](50),    
  @AreaCode  [varchar](15),      
  @ECCNo  [varchar](15),      
  @Range [varchar](50),      
  @EDRegNo  [varchar](15),      
  @EDRegDate  [datetime],      
  @ContactPerson  [varchar](50),
  @UdyamNo [varchar](30)='',
  @UdyamDate [datetime]=null,      
  @Userid  [varchar](10),      
  @Branchid  [varchar](3),      
  @Compid [varchar](3))      
      
AS
BEGIN             
  SET NOCOUNT ON;      
      
  Begin Transaction            
  declare @cBranchid varchar(3)      
      
  declare  BranchidList cursor For      
  select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid      
      
  OPEN BranchidList      
  FETCH NEXT FROM BranchidList into @cBranchid       
  WHILE @@FETCH_STATUS = 0      
       
  Begin      
  INSERT INTO [FAS_PARTY_ADDRESS]       
  (     
    [PartyCode],      
    [Add1],      
    [Add2],      
    [Add3],    
    [Country],  
    [State],    
    [City],      
    [Pincode],      
    [Phone],      
    [Fax],      
    [Cellular],      
    [EMail],      
    [CST],      
    [CSTDate],      
    [LST],      
    [LSTDate],      
    [GSTRegNo],    
    [GSTRegDate],    
    [ProvisionalID],    
    [AreaCode],      
    [ECCNo],      
    [Range],      
    [EDRegNo],      
    [EDRegDate],      
    [ContactPerson], 
    [UdyamNo],
    [UdyamDate],     
    [Userid],      
    [Branchid],      
    [Compid]  
 )                
 VALUES       
 (   
    @PartyCode,      
    @Add1,      
    @Add2,      
    @Add3,     
    @Country,  
    @State,   
    @City,      
    @Pincode,      
    @Phone,      
    @Fax,      
    @Cellular,      
    @EMail,      
    @CST,      
    @CSTDate,      
    @LST,      
    @LSTDate,      
    @GSTRegNo,    
    @GSTRegDate,    
    @ProvisionalID,    
    @AreaCode,      
    @ECCNo,      
    @Range,      
    @EDRegNo,      
    @EDRegDate,      
    @ContactPerson,
    @UdyamNo,
    @UdyamDate,      
    @Userid,      
    @cBranchid,      
    @Compid  
  )      
      
  FETCH NEXT FROM BranchidList into @cBranchid       
  End      
        
 close BranchidList      
 deallocate BranchidList      
      
 commit transaction
END
GO

