CREATE PROCEDURE [dbo].[FAS_INS_PARTY_MASTER]
	(@PartyCode 		[int],
	 @VendorCode 		[varchar](10),
	 @SuplierCode 		[varchar](10),
	 @PartyName 		[varchar](50),
	 @AcType		[varchar](1),
	 @FormCode 		[int],
	 @PackingCode 	[int],
	 @DeliveryCode 	[int],
	 @PaymentCode	[int],
	 @InsuranceCode 	[int],
	 @ModeCode	 	[int],
	 @Freightcode	 	[int],
	 @IsSubcontractor 	[bit],
	 @AliasName 		[char](10),
	 @EffStatus 		[bit],
	 @EffDate 		[datetime],
	 @CreditDays		[int],
	 @CreditDaysPeriod	[varchar](20),
	 @CurrencyCode	[char](3),
	 @CustomerFormulaCode [int],
	 @VendorFormulaCode	 [int],
              @TinNo		[Varchar](50),  
	 @PanNo		[Varchar](50),  
	 @Userid 		[varchar](10),
	 @Branchid 		[varchar](3),
	 @Compid 		[varchar](3))

AS 
BEGIN
SET NOCOUNT ON

Begin Transaction

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		INSERT INTO [FAS_PARTY_MASTER] 
			 ( [PartyCode],
			 [VendorCode],
			 [SuplierCode],
			 [PartyName],
			 [AcType],
			 [FormCode],
			 [PackingCode],
			 [DeliveryCode],
			 [PaymentCode],
			 [InsuranceCode],
			 [ModeCode],
			 [Freightcode],
			 [IsSubcontractor],
			 [AliasName],
			 [EffStatus],
			 [EffDate],
			 [CreditDays],
			 [CreditDaysPeriod],
			 [CurrencyCode],
			 [CustomerFormulaCode],
			 [VendorFormulaCode],
			 [TinNo],
	 		 [PanNo],
			 [Userid],
			 [Branchid],
			 [Compid]) 
		 
		VALUES 
			( @PartyCode,
			 @VendorCode,
			 @SuplierCode,
			 @PartyName,
			 @AcType,
			 @FormCode,
			 @PackingCode,
			 @DeliveryCode,
			 @PaymentCode,
			 @InsuranceCode,
			 @ModeCode,
			 @Freightcode,
			 @IsSubcontractor,
			 @AliasName,
			 @EffStatus,
			 @EffDate,
			 @CreditDays,
			 @CreditDaysPeriod,
			 @CurrencyCode,
			 @CustomerFormulaCode,
			 @VendorFormulaCode,
			 @TinNo,
			 @PanNo,
			 @Userid,
			 @cBranchid,
			 @Compid)

		
		FETCH NEXT FROM BranchidList into @cBranchid 
	END
 	
	close BranchidList
	deallocate BranchidList

	Commit Transaction
END
GO

