/****** Object:  StoredProcedure [dbo].[FAS_Ins_tmp_SelLst_Sel]    Script Date: 17/06/2026 11:30:06 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_Ins_tmp_SelLst_Sel]
	(@tmp 	[varchar](1000),
	 @UserID 	[varchar](10),
	 @CmCode 	[varchar](12))

AS 
BEGIN
	Set NOCOUNT ON
	
	Declare @cCnt int, @SelFld int

	Begin Transaction	

		Delete from FAS_tmp_SelLst where UserID=@UserID and CmCode=@CmCode
		
		Select @cCnt=0		
		
		While Len(@tmp) > 0

			Begin
				Select @cCnt=CharIndex('-', @tmp)
				
				Select @SelFld=(Case when @cCnt<>0 then Convert(int, Left(@tmp,  @CCnt-1))  else Convert(int, @tmp) end)
	
				INSERT INTO [FAS_tmp_SelLst] 	 ([SelFld], [UserID], [CmCode])  VALUES (@SelFld, @UserID, @CmCode)
				
				If @cCnt=0 
					Break

				Select @tmp=Right(@tmp, Len(@tmp)-@cCnt)

			End

	Commit Transaction
END
GO

