/****** Object:  StoredProcedure [dbo].[FAS_InsUp_VoucherTranSub]    Script Date: 17/06/2026 11:30:07 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_InsUp_VoucherTranSub]      
 (@DocType  [varchar](3),      
  @DocNo  [int],      
  @DocDate  [datetime],      
  @VTSNo  [int],      
  @VrRoute  [varchar](42),      
  @LrCode  [int],      
  @DrAmt  [money],      
  @CrAmt  [money],      
  @CompCode  [varchar](12),      
  @Userid [Varchar](10),      
  @TranStamp  [datetime])      
      
AS       
      
BEGIN     
     
    SET NOCOUNT ON;    
        
    IF Exists (Select * From FAS_VoucherTranSub     
                Where DocNo=@DocNo and DocDate=@DocDate and VrRoute=@VrRoute and LrCode=@LrCode and CompCode=@CompCode)      
        BEGIN  
            Declare @Dr money, @Cr money, @Amt money, @VTS int  
              
            Select @VTS=VTSNo, @Dr=DrAmt, @Cr=CrAmt From FAS_VoucherTranSub     
                Where DocNo=@DocNo and DocDate=@DocDate and VrRoute=@VrRoute and LrCode=@LrCode and CompCode=@CompCode  
                  
            Set @Amt=(@Dr+@DrAmt)-(@Cr+@CrAmt)  
              
            If (@Amt=0)  
                BEGIN  
                    Delete FAS_VoucherTranSub   
                    Where DocNo=@DocNo and DocDate=@DocDate and VrRoute=@VrRoute and LrCode=@LrCode and VTSNo=@VTS and CompCode=@CompCode  
                      
                    Update FAS_VoucherTranSub Set VTSNo=VTSNo-1  
                    Where DocNo=@DocNo and DocDate=@DocDate and VrRoute=@VrRoute and LrCode=@LrCode and VTSNo>@VTS and CompCode=@CompCode  
                END  
            Else  
                BEGIN  
                    Update FAS_VoucherTranSub Set DrAmt=Case When @Amt>0 Then @Amt Else 0 End, CrAmt=Case When @Amt<0 Then -@Amt Else 0 End  
                    Where DocNo=@DocNo and DocDate=@DocDate and VrRoute=@VrRoute and LrCode=@LrCode and CompCode=@CompCode      
                END  
        END      
    ELSE      
        BEGIN      
            Select @VTSNo=MAX(VTSNo) From FAS_VoucherTranSub     
            Where DocNo=@DocNo and DocDate=@DocDate and VrRoute=@VrRoute and CompCode=@CompCode    
                
            SET @VTSNo=isNull(@VTSNo, 0)+1    
                
            INSERT INTO [FAS_VoucherTranSub]       
            ( [DocType],      
            [DocNo],      
            [DocDate],      
            [VTSNo],      
            [VrRoute],      
            [LrCode],      
            [DrAmt],      
            [CrAmt],      
            [CompCode],      
            [UserID],      
            [TranStamp])       
    
            VALUES       
            (@DocType,      
            @DocNo,      
            @DocDate,      
            @VTSNo,      
            @VrRoute,      
            @LrCode,      
            @DrAmt,      
            @CrAmt,      
            @CompCode,      
            @UserID,      
            @TranStamp)      
        END      
END
GO

/****** Object:  StoredProcedure [dbo].[FAS_MIS_CrAgeing_0]    Script Date: 17/06/2026 11:30:07 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_MIS_CrAgeing_0] (@LrRoute varchar(4), @RptDate Datetime, @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON

	Select 'Creditor' as LrName, -Sum(Amount) as Amount, -Sum(ODAmt) as ODAmt, -Sum(Amt115) as Amt115, -Sum(Amt1630) as Amt1630,
			-Sum(Amt3145) as Amt3145, -Sum(Amt4675) as Amt4675, -Sum(Amt7690) as Amt7690,
			-Sum(Amt91) as Amt91, -Sum(AdvAmt) AdvAmt, -Sum(BrsAmt) BrsAmt
	from
		(Select  isNull(f.LrCode, isNull(g.Lrcode, g2.LrCode)) as LrCode, (Select LedgerName from FAS_LedgerMaster Where LedgerCode =  isNull(f.LrCode, isNull(g.Lrcode, g2.LrCode))  and CompCode=@CmCode) LrName,
			isNull(Amount, 0) as Amount, isNull(ODAmt, 0) as ODAmt, isNull(Amt115, 0) as Amt115, isNull(Amt1630, 0) as Amt1630,
			isNull(Amt3145, 0) as Amt3145, isNull(Amt4675, 0) as Amt4675, isNull(Amt7690, 0) as Amt7690,
			isNull(Amt91, 0) as Amt91,
			-- (Select isNull(Sum(Amount), 0) from FAS_BillDetails where LrCode=isNull(f.LrCode, g.Lrcode) and Type='On Acct' and RefDate <= Convert(datetime, @RptDate, 111) and CompCode=@CmCode) as AdvAmt,
			isNull(g2.AdvAmt, 0) as AdvAmt,
			isNull(-g.BrsAmt, 0) as BrsAmt
		from
			(Select LrCode, 
				Sum(Amount) as Amount, Sum(ODAmt) as ODAmt, Sum(Amt115) as Amt115, Sum(Amt1630) as Amt1630,
				Sum(Amt3145) as Amt3145, Sum(Amt4675) as Amt4675, Sum(Amt7690) as Amt7690,
				Sum(Amt91) as Amt91
			from
				(Select LrCode,  Amount, 
					Case when Overdue >= 1 then Amount else 0 End as ODAmt,	
					Case when Overdue between 1 and 15 then Amount else 0 End as Amt115,
					Case when Overdue between 16 and 30 then Amount else 0 End as Amt1630,
					Case when Overdue between 31 and 45 then Amount else 0 End as Amt3145,
					Case when Overdue between 46 and 75 then Amount else 0 End as Amt4675,
					Case when Overdue between 76 and 90 then Amount else 0 End as Amt7690,
					Case when Overdue > 91 then Amount else 0 End as Amt91
				from 
					(Select LrCode, Amount, DateDiff(day, DueDate, @RptDate) as OverDue
					from
						(Select  isNull(y.DueDate, z.RefDate) DueDate,  z.LrCode, z.Amount 
						from 
							(Select LrCode, RefNo, DateAdd(day, CreditDays, RefDate) as DueDate from FAS_BillDetails
							where Type in ('Advance', 'New Ref') and CompCode=@CmCode
							) y

							Full Outer Join

							
							(Select z1.LrCode, z1.RefNo, Sum(z1.Amount) as Amount,
							 	(Select Min(z2.RefDate) from FAS_BillDetails z2 where z2.RefNo=z1.RefNo and z2.LrCode=z1.LrCode and z2.CompCode=z1.CompCode) as RefDate
							from fas_billdetails z1
							where z1.Type <> 'On Acct' and z1.RefDate <= Convert(datetime, @RptDate, 111) 
								and z1.LrCode in (Select LedgerCode from FAS_LedgerMaster where Left(LrRoute, 4)=@LrRoute and CompCode=@CmCode)
								and z1.CompCode=@CmCode
							group by z1.LrCode, z1.RefNo, z1.CompCode 
							) z 
							On y.RefNo=z.RefNo and y.LrCode=z.LrCode
						where z.Amount <> 0 
						) c
					) d
				) e
			group by LrCode 
			) f
	
			Full Outer Join

			(Select a.LrCode, Sum(a.Amount) as BrsAmt
			from FAS_BillDetails a Inner join
				(Select DocNo, DocDate, VrRoute, Lrcode from FAS_BankRecon_Vw 
				Where Lrcode in (Select LedgerCode from FAS_LedgerMaster Where Left(LrRoute, 4) in ('0201', '0B01') and CompCode=@CmCode)
				and isLrCode='1' and (BankDate is Null or BankDate > @RptDate) and Compcode=@CmCode
				) b
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=@CmCode
			Where a.LrCode in (Select LedgerCode from FAS_LedgerMaster Where Left(LrRoute, Len(@LrRoute))=@LrRoute and CompCode=@CmCode) and a.RefDate <= Convert(datetime, @RptDate, 111)
			Group by a.LrCode 
			Having Sum(a.Amount) <> 0
			) g
	
			On f.LrCode=g.LrCode


			Full Outer Join

			(Select a.LrCode, Sum(a.Amount) as AdvAmt
			from FAS_BillDetails a
			Where a.LrCode in (Select LedgerCode from FAS_LedgerMaster Where Left(LrRoute, Len(@LrRoute))=@LrRoute and CompCode=@CmCode) and a.RefDate <= Convert(datetime, @RptDate, 111)
				and a.Type='On Acct' and a.CompCode=@CmCode
			Group By a.LrCode
			) g2

			On f.LrCode=g2.LrCode
		) h
	--group by LrName
	--Order by LrName
End
GO

