CREATE PROCEDURE [dbo].[FAS_MIS_CrAgeing_01] (@LrRoute varchar(4), @RptDate Datetime, @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON

	Select LrName, LrCode, -Sum(Amount) as Amount, -Sum(ODAmt) as ODAmt, -Sum(Amt115) as Amt115, -Sum(Amt1630) as Amt1630,
			-Sum(Amt3145) as Amt3145, -Sum(Amt4675) as Amt4675, -Sum(Amt7690) as Amt7690,
			-Sum(Amt91) as Amt91, -Sum(AdvAmt) AdvAmt, -Sum(BrsAmt) BrsAmt
	from
		(Select  isNull(f.LrCode, isNull(g.Lrcode, g2.LrCode)) as LrCode, (Select LedgerName from FAS_LedgerMaster Where LedgerCode =  isNull(f.LrCode, isNull(g.Lrcode, g2.LrCode))  and CompCode=@CmCode) LrName,
			isNull(Amount, 0) as Amount, isNull(ODAmt, 0) as ODAmt, isNull(Amt115, 0) as Amt115, isNull(Amt1630, 0) as Amt1630,
			isNull(Amt3145, 0) as Amt3145, isNull(Amt4675, 0) as Amt4675, isNull(Amt7690, 0) as Amt7690,
			isNull(Amt91, 0) as Amt91,
			-- (Select isNull(Sum(Amount), 0) from FAS_BillDetails where LrCode=isNull(f.LrCode, g.Lrcode) and Type='On Acct' and RefDate <= Convert(datetime, @RptDate, 111) and CompCode=@CmCode) as AdvAmt,
			isNull(g2.AdvAmt, 0) as AdvAmt,
			isNull(-g.BrsAmt, 0) as BrsAmt
		from
			(Select LrCode, 
				Sum(Amount) as Amount, Sum(ODAmt) as ODAmt, Sum(Amt115) as Amt115, Sum(Amt1630) as Amt1630,
				Sum(Amt3145) as Amt3145, Sum(Amt4675) as Amt4675, Sum(Amt7690) as Amt7690,
				Sum(Amt91) as Amt91
			from
				(Select LrCode,  Amount, 
					Case when Overdue >= 1 then Amount else 0 End as ODAmt,	
					Case when Overdue between 1 and 15 then Amount else 0 End as Amt115,
					Case when Overdue between 16 and 30 then Amount else 0 End as Amt1630,
					Case when Overdue between 31 and 45 then Amount else 0 End as Amt3145,
					Case when Overdue between 46 and 75 then Amount else 0 End as Amt4675,
					Case when Overdue between 76 and 90 then Amount else 0 End as Amt7690,
					Case when Overdue > 91 then Amount else 0 End as Amt91
				from 
					(Select LrCode, Amount, DateDiff(day, DueDate, @RptDate) as OverDue
					from
						(Select  isNull(y.DueDate, z.RefDate) DueDate,  z.LrCode, z.Amount 
						from 
							(Select LrCode, RefNo, DateAdd(day, CreditDays, RefDate) as DueDate from FAS_BillDetails
							where Type in ('Advance', 'New Ref') and CompCode=@CmCode
							) y

							Full Outer Join

							
							(Select z1.LrCode, z1.RefNo, Sum(z1.Amount) as Amount,
							 	(Select Min(z2.RefDate) from FAS_BillDetails z2 where z2.RefNo=z1.RefNo and z2.LrCode=z1.LrCode and z2.CompCode=z1.CompCode) as RefDate
							from fas_billdetails z1
							where z1.Type <> 'On Acct' and z1.RefDate <= Convert(datetime, @RptDate, 111) 
								and z1.LrCode in (Select LedgerCode from FAS_LedgerMaster where Left(LrRoute, 4)=@LrRoute and CompCode=@CmCode)
								and z1.CompCode=@CmCode
							group by z1.LrCode, z1.RefNo, z1.CompCode 
							) z 
							On y.RefNo=z.RefNo and y.LrCode=z.LrCode
						where z.Amount <> 0 
						) c
					) d
				) e
			group by LrCode 
			) f
	
			Full Outer Join

			(Select a.LrCode, Sum(a.Amount) as BrsAmt
			from FAS_BillDetails a Inner join
				(Select DocNo, DocDate, VrRoute, Lrcode from FAS_BankRecon_Vw 
				Where Lrcode in (Select LedgerCode from FAS_LedgerMaster Where Left(LrRoute, 4) in ('0201', '0B01') and CompCode=@CmCode)
				and isLrCode='1' and (BankDate is Null or BankDate > @RptDate) and Compcode=@CmCode
				) b
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=@CmCode
			Where a.LrCode in (Select LedgerCode from FAS_LedgerMaster Where Left(LrRoute, Len(@LrRoute))=@LrRoute and CompCode=@CmCode) and a.RefDate <= Convert(datetime, @RptDate, 111)
			Group by a.LrCode 
			Having Sum(a.Amount) <> 0
			) g
	
			On f.LrCode=g.LrCode


			Full Outer Join

			(Select a.LrCode, Sum(a.Amount) as AdvAmt
			from FAS_BillDetails a
			Where a.LrCode in (Select LedgerCode from FAS_LedgerMaster Where Left(LrRoute, Len(@LrRoute))=@LrRoute and CompCode=@CmCode) and a.RefDate <= Convert(datetime, @RptDate, 111)
				and a.Type='On Acct' and a.CompCode=@CmCode
			Group By a.LrCode
			) g2

			On f.LrCode=g2.LrCode
		) h
	group by h.LrCode, LrName
	--Order by LrName
End
GO

/****** Object:  StoredProcedure [dbo].[FAS_MIS_DrAgeing_0]    Script Date: 17/06/2026 11:30:07 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_MIS_DrAgeing_0] (@LrRoute varchar(4), @RptDate Datetime, @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON


	Select LrName, 	Sum(Amount) as Amount, Sum(ODAmt) as ODAmt, Sum(Amt115) as Amt115, Sum(Amt1630) as Amt1630,
			Sum(Amt3145) as Amt3145, Sum(Amt4675) as Amt4675, Sum(Amt7690) as Amt7690,
			Sum(Amt91) as Amt91, Sum(AdvAmt) AdvAmt, Sum(BrsAmt) BrsAmt,  LrCode
	from

		(Select IsNull(f.LrCode, IsNull(g.LrCode, g2.LrCode)) as LrCode, (Select Case when Alias = '' then LedgerName else Alias End from FAS_LedgerMaster where LedgerCode=isNull(f.LrCode, isNull(g.LrCode, g2.LrCode)) and CompCode=@CmCode) as LrName,
			isNull(Amount, 0) as Amount, isNull(ODAmt, 0) as ODAmt, isNull(Amt115, 0) as Amt115, isNull(Amt1630, 0) as Amt1630,
			isNull(Amt3145, 0) as Amt3145, isNull(Amt4675, 0) as Amt4675, isNull(Amt7690, 0) as Amt7690,
			isNull(Amt91, 0) as Amt91, 
			--(Select isNull(Sum(Amount), 0) from FAS_BillDetails where LrCode=isNull(f.LrCode, g.Lrcode) and Type='On Acct' and RefDate <= Convert(datetime, @RptDate, 111) and CompCode=@CmCode) as AdvAmt,
			isNull(g2.AdvAmt, 0) as AdvAmt,
			isNull(g.BrsAmt, 0) as BrsAmt
		from


			(Select LrCode, 
				Sum(Amount) as Amount, Sum(ODAmt) as ODAmt, Sum(Amt115) as Amt115, Sum(Amt1630) as Amt1630,
				Sum(Amt3145) as Amt3145, Sum(Amt4675) as Amt4675, Sum(Amt7690) as Amt7690,
				Sum(Amt91) as Amt91			

			from
				(Select LrCode, Amount, 
					Case when Overdue >= 1 then Amount else 0 End as ODAmt,	
					Case when Overdue between 1 and 15 then Amount else 0 End as Amt115,
					Case when Overdue between 16 and 30 then Amount else 0 End as Amt1630,
					Case when Overdue between 31 and 45 then Amount else 0 End as Amt3145,
					Case when Overdue between 46 and 75 then Amount else 0 End as Amt4675,
					Case when Overdue between 76 and 90 then Amount else 0 End as Amt7690,
					Case when Overdue > 91 then Amount else 0 End as Amt91
				from 


					(Select LrCode, Amount as Amount, DateDiff(day,  DueDate,@RptDate) as OverDue
						from (Select DateAdd(day, y.CreditDays, y.RefDate) as DueDate, z.LrCode, z.Amount 
						From fas_billdetails y
						Left Outer Join (Select k.LrCode, k.RefNo, Sum(Amount) as Amount From fas_billdetails k 
								Left Outer Join FAS_VoucherTranSub l
								On k.DocNo = l.DocNo and k.DocDate=l.DocDate and k.VrRoute = l.VrRoute and k.LrCode = l.LrCode and k.Compcode = l.Compcode
								Where k.Type <> 'On Acct' and k.RefDate <= Convert(datetime, @RptDate, 111) 
									and k.LrCode in (Select LedgerCode from FAS_LedgerMaster where Left(LrRoute, 4)=@LrRoute and CompCode=@CmCode)
									and k.CompCode=@CmCode
								Group by k.LrCode, k.RefNo ) z 
						On y.RefNo=z.RefNo and y.LrCode=z.LrCode
						Where z.Amount <> 0  and y.Type in ('Advance', 'New Ref') and y.CompCode=@CmCode
						) c
					) d
				) e
			group by LrCode 
			) f


			Full Outer Join
			
			(Select LrCode, Sum(Amount) as BrsAmt
			from
				(Select a.LrCode, Case When isNull(a.RefNo, '')='' then a.Type Else a.RefNo End as RefNo, RefDate, (Select DateAdd(day, CreditDays, RefDate) from FAS_BillDetails m Where m.RefNo=a.RefNo and m.LrCode=a.LrCode and m.Type = 'New Ref' and m.CompCode=@CmCode) as DueDate, Sum(a.Amount) as Amount
				from FAS_BillDetails a join

						(Select DocNo, DocDate, VrRoute, Lrcode from FAS_BankRecon_Vw 
						Where Lrcode in (Select LedgerCode from FAS_LedgerMaster Where Left(LrRoute, 4) in ('0201', '0B01') and CompCode=@CmCode)
						and isLrCode='1' and (BankDate is Null or BankDate > Convert(datetime, @RptDate, 111)) and Compcode=@CmCode
						) b

				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=@CmCode
							--add the top 1 by ramana on 19/12/05
				Where a.LrCode in (Select top 1 LedgerCode from FAS_LedgerMaster Where Left(LrRoute, Len(@LrRoute))=@LrRoute and CompCode=@CmCode) and a.RefDate <= Convert(datetime, @RptDate, 111)
				Group by a.LrCode, a.RefNo, a.RefDate, a.Type 
				) K
			group by LrCode
			) g 

			On f.LrCode=g.LrCode

		Full Outer Join

			(Select a.LrCode, Sum(a.Amount) as AdvAmt
			from FAS_BillDetails a
			Where a.LrCode in (Select LedgerCode from FAS_LedgerMaster Where Left(LrRoute, Len(@LrRoute))=@LrRoute and CompCode=@CmCode) and a.RefDate <= Convert(datetime, @RptDate, 111)
				and a.Type='On Acct' and a.CompCode=@CmCode
			Group By a.LrCode
			) g2

			On f.LrCode=g2.LrCode
	) h
	Group by h.LrCode, h.LrName
	Order by LrName

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_MIS_GrpCB_0]    Script Date: 17/06/2026 11:30:07 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_MIS_GrpCB_0] (@LrRoute varchar(4), @RptDate Datetime, @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON
	
	Select isNull(Sum(isNull(a.BRSAmt, 0)+isNull(b.OpBalance, 0)), 0) as BRSAmt, isNull(Sum(isNull(a.VrAmt, 0)+isNull(b.OpBalance, 0)), 0) as VrAmt
	from
		(Select LrCode, Sum(BRSAmt) BRSAmt, Sum(VrAmt) VrAmt
		from
			(Select LrCode, Case When Vrdate <= @RptDate then (DrAmt-CrAmt) else 0 End as BRSAmt, (DrAmt-CrAmt) as VrAmt
			from
				(Select LrCode, CrAmt, DrAmt, Case when m.PayMode in ('', 'Cash') then m.DocDate else n.BankDate end VrDate
				from fas_Voucher_vw m Left Outer Join fas_VoucherTranPay n
				on m.DocNo=n.DocNo and m.DocDate=n.DocDate and m.VrRoute=n.VrRoute and m.CompCode=n.CompCode
				where m.DocDate <= @RptDate and m.Compcode=@CmCode 
				) x
			) y
			group by LrCode
		) a
	left outer join fas_LedgerMaster b
	on a.LrCode=b.LedgerCode
	where Left(b.LrRoute, 4)=@LrRoute and b.CompCode=@CmCode

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_MIS_Loans_0]    Script Date: 17/06/2026 11:30:07 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_MIS_Loans_0] (@LrRoute varchar(2), @RptDate Datetime, @CmCode varchar(12)) 

AS

Begin

	SET NOCOUNT ON

	Select  LrName, Credit, BRSCredit, Debit, BRSDebit, LedgerCode
	from 
		(Select a.LedgerCode, a.LedgerName as LrName, (a.OPbalance-isnull(c.CrAmt,0)) Credit, isNull(c.DrAmt, 0) Debit,
			(a.OpBalance-isnull(c.BRSCrAmt,0)) BRSCredit, isNull(c.BRSDrAmt, 0) BRSDebit
		from FAS_LedgerMaster a 
		Left Outer Join
			(Select b.LrCode, Sum(b.DrAmt) as DrAmt, Sum(b.CrAmt) as CrAmt, 
				Sum(Case when b.PayMode in ('', 'Cash') then b.DrAmt else (Case when d.BankDate <= @RptDate then b.DrAmt else 0 end)  end) BRSDrAmt, 
				Sum(Case when b.PayMode in ('', 'Cash') then b.CrAmt else (Case when d.BankDate <= @RptDate then b.CrAmt else 0 end) end) BRSCrAmt 
			from FAS_Voucher_Vw b 
			Left Outer Join FAS_VoucherTranPay d
			on b.DocNo=d.DocNo and b.DocDate=d.DocDate and b.VrRoute=d.VrRoute and b.CompCode=d.CompCode
			where b.DocDate <= @RptDate and b.CompCode=@CmCode 
			group by b.LrCode
			) c
		On a.LedgerCode=c.LrCode
		where Left(a.LrRoute, 2)=@LrRoute and Left(a.LrRoute, 4) Not in ('0B01',  '0B04')  and a.CompCode=@CmCode
	) d
	where (Credit-Debit) <> 0 or (BRSCredit-BRSDebit) <> 0

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_MIS_PDC_0]    Script Date: 17/06/2026 11:30:07 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_MIS_PDC_0] (@RptDate Datetime, @CmCode varchar(12)) 

AS

Begin

	SET NOCOUNT ON

	

	Select isNull(e.LrCode, f.LrCode) LrCode, (Select Case when Alias = '' then LedgerName else Alias End from FAS_LedgerMaster where LedgerCode=isNull(e.LrCode, f.LrCode) and CompCode=@CmCode) as LrName,
		isNull(e.Amt, 0) Amt, isNull(e.Amt2, 0) Amt2, isNull(e.Amt3, 0) Amt3, isNull(e.Amt47, 0) Amt47, isNull(e.Amt814, 0) Amt814, isNull(e.Amt1521, 0) Amt1521, isNull(e.Amt2230, 0) Amt2230, isNull(e.AmtYear, 0) AmtYear, isNull(e.AmtTotal, 0) AmtTotal, isNull(f.Amt, 0)  BankAmt
	from	--Bank CB as per Our Book
		(Select Lrcode, Sum(DayAmt) Amt, Sum(DayAmt2) Amt2, Sum(DayAmt3) Amt3, Sum(DayAmt47) Amt47,
				Sum(DayAmt814) Amt814, Sum(DayAmt1521) Amt1521, Sum(DayAmt2230) Amt2230,
				Sum(DayAmtYear) AmtYear, Sum(TotalAmt) AmtTotal
		from
			(Select Lrcode,
				Case when ChqDate <= @RptDate then ChqAmt Else 0 End as DayAmt,
				Case when ChqDate = DateAdd(day, 1, @RptDate) then ChqAmt Else 0 End as DayAmt2,
				Case when ChqDate = DateAdd(day, 2, @RptDate) then ChqAmt Else 0 End as DayAmt3,
				Case when ChqDate between DateAdd(day, 3, @RptDate) and DateAdd(day, 6, @RptDate) then ChqAmt Else 0 End as DayAmt47,
				Case when ChqDate between DateAdd(day, 7, @RptDate) and DateAdd(day, 13, @RptDate) then ChqAmt Else 0 End as DayAmt814,
				Case when ChqDate between DateAdd(day, 14, @RptDate) and DateAdd(day, 20, @RptDate) then ChqAmt Else 0 End as DayAmt1521,
				Case when ChqDate between DateAdd(day, 21, @RptDate) and DateAdd(day, 29, @RptDate) then ChqAmt Else 0 End as DayAmt2230,
				Case when ChqDate >= DateAdd(day, 30, @RptDate) then ChqAmt Else 0 End as DayAmtYear,
				ChqAmt as TotalAmt
			from
				(Select R.Lrcode, a.ChqDate, isNull(R.CrAmt, 0) as ChqAmt
				from FAS_VoucherTranPay a Join FAS_VoucherTranMast b 
				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
					Join FAS_VoucherTranSub R
					On R.DocNo=a.DocNo and a.DocDate=R.DocDate and R.VrRoute=a.VrRoute and R.CompCode=a.CompCode
				Where R.LrCode in (Select LedgerCode from FAS_Ledgermaster where Left(LrRoute, 4) in ('0201', '0B01') and CompCode=@CmCode) 
					and R.DrAmt = 0 and a.CompCode=@CmCode and a.BankDate is Null and b.DocDate <= Convert(datetime, @RptDate, 111) 
			
				Union All
			
				Select Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6)) as LrCode, ChqDate, isNull(ChqAmount, 0) as ChqAmt
				from FAS_VoucherTranPay 	
				Where DocNo=0 and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6))in (Select LedgerCode from FAS_Ledgermaster where Left(LrRoute, 4) in ('0201', '0B01') and CompCode=@CmCode) 
					and CompCode=@CmCode and BankDate is Null  
				) m
			) n
		group by LrCode 
		) e
	
		Full Outer Join
		--Bank CB as per Bank Book
		(Select LrCode, Sum(OBAmt+BrsAmt) as Amt
		from
			(Select Case when isNull(m.Lrcode, '')='' then n.LrCode else m.Lrcode End as LrCode, isNull(m.OBAmt, 0) OBAmt, isnull(n.BrsAmt, 0) BrsAmt
			from
				(select c.Lrcode, isNull(-(b.OpBalance+c.Amt), 0) as OBAmt
				from 
					(select a.Lrcode, Sum(a.CrAmt-a.DrAmt) Amt
					from fas_voucher_vw a 
					where a.DocDate <= Convert(datetime, @RptDate, 111) and a.CompCode=@CmCode group by a.LrCode
					) c 
					Left Outer Join fas_ledgermaster b
					on c.LrCode=b.LedgerCode 
					where Left(b.LrRoute, 4) in ('0201', '0B01') and b.CompCode=@CmCode
				) m
					
				full outer join
					
				(Select LrCode, isNull(Sum(Amount) , 0) as BrsAmt
				from 
					(Select LrCode,
						Case R.DrAmt When 0 Then  isNull(R.CrAmt, 0) Else  isNull(-R.DrAmt, 0) End as Amount
					from FAS_VoucherTranPay a Join FAS_VoucherTranMast b 
					On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
							Join FAS_VoucherTranSub R
							On R.DocNo=a.DocNo and a.DocDate=R.DocDate and R.VrRoute=a.VrRoute and R.CompCode=a.CompCode
					Where R.LrCode in (Select LedgerCode from fas_ledgermaster x where Left(x.LrRoute, 4) in ('0201', '0B01') and x.CompCode=@CmCode) and a.CompCode=@CmCode
							and (a.BankDate is Null or a.BankDate > Convert(datetime, @RptDate, 111)) and b.DocDate <= Convert(datetime, @RptDate, 111) 
				
					Union All
				
					Select Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6)) as Lrcode, Case isReceipt When 0 then ChqAmount Else -ChqAmount End as Amount
					from FAS_VoucherTranPay
					Where DocNo=0 and CompCode=@CmCode
						and (BankDate is Null or BankDate > Convert(datetime, @RptDate, 111))
					) z
				group by LrCode
				) n
				on m.LrCode=n.Lrcode
			) p
		group by lrcode
		) f
		on e.Lrcode=f.Lrcode
	Order by LrName

End
GO

