CREATE PROCEDURE [dbo].[FAS_MIS_PDC_01] (@RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12)) 

-- This Procedure Copy of this Procedure Name FAS_MIS_PDC_0 Only amt1521 is change to amt1530 and additionly BankBookValue
-- is displayed (Date Modify On 2006-12-29)

AS

Begin

	SET NOCOUNT ON

	Select isNull(e.LrCode, f.LrCode) LrCode, (Select Case when Alias = '' then LedgerName else Alias End from FAS_LedgerMaster where LedgerCode=isNull(e.LrCode, f.LrCode) and CompCode=@CmCode) as LrName,
		isNull(e.Amt, 0) Amt, isNull(e.Amt2, 0) Amt2, isNull(e.Amt3, 0) Amt3, isNull(e.Amt47, 0) Amt47, isNull(e.Amt814, 0) Amt814, isNull(e.Amt1530, 0) Amt1530, --isNull(e.Amt2230, 0) Amt2230, 
		isNull(e.AmtYear, 0) AmtYear, isNull(e.AmtTotal, 0) AmtTotal, isNull(f.Amt, 0)  OurBookAmt, IsNull(BankAmt, 0) as BankAmt

	from	--Bank CB as per Our Book
		(Select Lrcode, Sum(DayAmt) Amt, Sum(DayAmt2) Amt2, Sum(DayAmt3) Amt3, Sum(DayAmt47) Amt47,
				Sum(DayAmt814) Amt814, Sum(DayAmt1530) Amt1530,-- Sum(DayAmt2230) Amt2230,
				Sum(DayAmtYear) AmtYear, Sum(TotalAmt) AmtTotal,
				dbo.fn_FAS_BankBook_Value (LrCode, @RptDate, @PrStart, @PrEnd, @CmCode) BankAmt
		from
			(Select Lrcode,
				Case when ChqDate <= @RptDate then ChqAmt Else 0 End as DayAmt,
				Case when ChqDate = DateAdd(day, 1, @RptDate) then ChqAmt Else 0 End as DayAmt2,
				Case when ChqDate = DateAdd(day, 2, @RptDate) then ChqAmt Else 0 End as DayAmt3,
				Case when ChqDate between DateAdd(day, 3, @RptDate) and DateAdd(day, 6, @RptDate) then ChqAmt Else 0 End as DayAmt47,
				Case when ChqDate between DateAdd(day, 7, @RptDate) and DateAdd(day, 13, @RptDate) then ChqAmt Else 0 End as DayAmt814,
				Case when ChqDate between DateAdd(day, 14, @RptDate) and DateAdd(day, 29, @RptDate) then ChqAmt Else 0 End as DayAmt1530,				
--				Case when ChqDate between DateAdd(day, 21, @RptDate) and DateAdd(day, 29, @RptDate) then ChqAmt Else 0 End as DayAmt2230,				
				Case when ChqDate >= DateAdd(day, 30, @RptDate) then ChqAmt Else 0 End as DayAmtYear,
				ChqAmt as TotalAmt
			from
				(Select R.Lrcode, a.ChqDate, isNull(R.CrAmt, 0) as ChqAmt
				from FAS_VoucherTranPay a Join FAS_VoucherTranMast b 
				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
					Join FAS_VoucherTranSub R
					On R.DocNo=a.DocNo and a.DocDate=R.DocDate and R.VrRoute=a.VrRoute and R.CompCode=a.CompCode
				Where R.LrCode in (Select LedgerCode from FAS_Ledgermaster where Left(LrRoute, 4) in ('0201', '0B01') and CompCode=@CmCode) 
					and R.DrAmt = 0 and a.CompCode=@CmCode and a.BankDate is Null and b.DocDate <= Convert(datetime, @RptDate, 111) 
			
				Union All
			
				Select Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6)) as LrCode, ChqDate, isNull(ChqAmount, 0) as ChqAmt
				from FAS_VoucherTranPay 	
				Where DocNo=0 and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6))in (Select LedgerCode from FAS_Ledgermaster where Left(LrRoute, 4) in ('0201', '0B01') and CompCode=@CmCode) 
					and CompCode=@CmCode and BankDate is Null  
				) m
			) n
		group by LrCode 
		) e
	
		Full Outer Join
		--Bank CB as per Bank Book( OurBookAmt)
		(Select LrCode, Sum(OBAmt+BrsAmt) as Amt
		from
			(Select Case when isNull(m.Lrcode, '')='' then n.LrCode else m.Lrcode End as LrCode, isNull(m.OBAmt, 0) OBAmt, isnull(n.BrsAmt, 0) BrsAmt
			from
				(select c.Lrcode, isNull(-(b.OpBalance+c.Amt), 0) as OBAmt
				from 
					(select a.Lrcode, Sum(a.CrAmt-a.DrAmt) Amt
					from fas_voucher_vw a 
					where a.DocDate <= Convert(datetime, @RptDate, 111) and a.CompCode=@CmCode group by a.LrCode
					) c 
					Left Outer Join fas_ledgermaster b
					on c.LrCode=b.LedgerCode 
					where Left(b.LrRoute, 4) in ('0201', '0B01') and b.CompCode=@CmCode
				) m
					
				full outer join
					
				(Select LrCode, isNull(Sum(Amount) , 0) as BrsAmt
				from 
					(Select LrCode,
						Case R.DrAmt When 0 Then  isNull(R.CrAmt, 0) Else  isNull(-R.DrAmt, 0) End as Amount
					from FAS_VoucherTranPay a Join FAS_VoucherTranMast b 
					On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
							Join FAS_VoucherTranSub R
							On R.DocNo=a.DocNo and a.DocDate=R.DocDate and R.VrRoute=a.VrRoute and R.CompCode=a.CompCode
					Where R.LrCode in (Select LedgerCode from fas_ledgermaster x where Left(x.LrRoute, 4) in ('0201', '0B01') and x.CompCode=@CmCode) and a.CompCode=@CmCode
							and (a.BankDate is Null or a.BankDate > Convert(datetime, @RptDate, 111)) and b.DocDate <= Convert(datetime, @RptDate, 111) 
				
					Union All
				
					Select Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6)) as Lrcode, Case isReceipt When 0 then ChqAmount Else -ChqAmount End as Amount
					from FAS_VoucherTranPay
					Where DocNo=0 and CompCode=@CmCode
						and (BankDate is Null or BankDate > Convert(datetime, @RptDate, 111))
					) z
				group by LrCode
				) n
				on m.LrCode=n.Lrcode
			) p
		group by lrcode
		) f
		on e.Lrcode=f.Lrcode
	Order by LrName

End
GO

