CREATE PROCEDURE [dbo].[FAS_MIS_Pymt_0] (@VrRoute varchar(2), @LrRoute varchar(4), @FinStart Datetime, @RptDate Datetime, @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON
	

	Select LrCode, (Select LedgerName from FAS_LedgerMaster b where b.LedgerCode=a.LrCode and b.CompCode=@CmCode) LrName,
		Sum(DayAmt) DayAmt, Sum(MonthAmt) MonthAmt, Sum(YearAmt) YearAmt
	from
		(select LrCode, Case when n.BankDate=@RptDate then n.ChqAmount Else 0 End as DayAmt,
			Case when Convert(varchar(6), n.BankDate, 112)= Convert(varchar(6), @RptDate, 112) then n.ChqAmount Else 0 End as MonthAmt,
			Case when n.BankDate between @FinStart and @RptDate then n.ChqAmount Else 0 End as YearAmt
		from FAS_Voucher_Vw m Left Outer Join FAS_VoucherTranPay n
		On m.DocNo=n.DocNo and m.DocDate=n.DocDate and m.VrRoute=n.VrRoute and m.Compcode=n.CompCode
		where m.DocDate <= @RptDate and Left(m.VrRoute, 2)=@VrRoute and n.BankDate is not Null
			and m.LrCode in (Select LedgerCode from FAS_Ledgermaster k where Left(k.LrRoute, Len(@LrRoute)) = @LrRoute and compcode=@CmCode) 
			and m.Compcode=@CmCode 
		) a
	group by LrCode

	Order by LrName

End
GO

