CREATE PROCEDURE [dbo].[FAS_MIS_Rcpt_0] (@VrRoute varchar(2), @LrRoute varchar(4), @FinStart Datetime, @RptDate Datetime, @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON
	
	Select * 
	from
		(Select LrCode, Case when LrCode = 0 then 'SIDBI' else (Select Case when Alias = '' then LedgerName else Alias End from FAS_LedgerMaster b where b.LedgerCode=a.LrCode and b.CompCode=@CmCode) End as LrName,
			Sum(DayAmt) DayAmt, Sum(MonthAmt) MonthAmt, Sum(YearAmt) YearAmt
		from

			(select distinct m.DocNo, m.DocDate, Case when Left(k.LrRoute, 4) = '0304' then 0 else m.LrCode End as LrCode, Case when n.BankDate=@RptDate then n.ChqAmount Else 0 End as DayAmt,
				Case when Convert(varchar(6), n.BankDate, 112)= Convert(varchar(6), @RptDate, 112) then n.ChqAmount Else 0 End as MonthAmt,
				Case when n.BankDate between @FinStart and @RptDate then n.ChqAmount Else 0 End as YearAmt
			from FAS_Voucher_Vw m Left Outer Join FAS_VoucherTranPay n
			On m.DocNo=n.DocNo and m.DocDate=n.DocDate and m.VrRoute=n.VrRoute and m.Compcode=n.CompCode
				Left Outer Join FAS_LedgerMaster k
				On m.LrCode=k.LedgerCode and Left(m.CompCode, 4)=k.CompCode
			where m.DocDate <= @RptDate and Left(m.VrRoute, 2)=@VrRoute and n.BankDate is not Null
				and Left(k.LrRoute, 4) in (@LrRoute, '0304')  and m.CompCode=@CmCode 
			) a

		group by LrCode ) z
	where DayAmt+MonthAmt+YearAmt <> 0
	Order by LrName

End
GO

