CREATE PROCEDURE [dbo].[FAS_Mod_GroupParent] (@OldPath varchar(42), @NewPath varchar(42), @CmCode varchar(12))

AS

Begin
	Set NOCOUNT ON

	Declare @LnPath int
	Select @LnPath = Len(@OldPath)

	Update FAS_GroupMaster Set GrRoute = Stuff(GrRoute,1,@LnPath, @NewPath) Where Substring(GrRoute,1,@LnPath) = @OldPath and CompCode = @CmCode

	Update FAS_LedgerMaster Set LrRoute = Stuff(LrRoute,1,@LnPath, @NewPath) Where Substring(LrRoute,1,@LnPath) = @OldPath and CompCode = @CmCode

End
GO

