CREATE PROCEDURE [dbo].[FAS_Mod_MEM_VrTranReNum_From] (@StNo int, @VrDate datetime, @NumToAdd int, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON

	Declare @Restart varchar(15), @isAutoNo bit


	Select @Restart=RestartAt, @isAutoNo=isAutoNumber From FAS_VoucherMaster Where VrRoute+VrWidth='07' and CompCode=@CmCode

	If @Restart='FinYearly'
		Begin

			Declare @CurFinStart datetime,  @CurFinEnd datetime

			If Month(@VrDate) <= 3 
				Select @CurFinStart = Convert(datetime, Convert(varchar, Year(@VrDate)-1) + '04' + '01', 112), 
				           @CurFinEnd = Convert(datetime, Convert(varchar, Year(@VrDate)) + '03' + '31', 112)
			Else
				Select @CurFinStart = Convert(datetime,Convert(varchar,  Year(@VrDate)) + '04' + '01', 112), 
				           @CurFinEnd = Convert(datetime, Convert(varchar, Year(@VrDate)+1) + '03' + '31', 112)


			Update FAS_MEM_VoucherTranMast Set DocNo = DocNo + @NumToAdd Where  (DocDate Between @CurFinStart and @CurFinEnd) and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranSub Set DocNo = DocNo + @NumToAdd Where  (DocDate Between @CurFinStart and @CurFinEnd) and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranPay Set DocNo = DocNo + @NumToAdd Where  (DocDate Between @CurFinStart and @CurFinEnd) and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranRef Set DocNo = DocNo + @NumToAdd Where  (DocDate Between @CurFinStart and @CurFinEnd) and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranNarr Set DocNo = DocNo + @NumToAdd Where  (DocDate Between @CurFinStart and @CurFinEnd) and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranCostCentre Set DocNo = DocNo + @NumToAdd Where  (DocDate Between @CurFinStart and @CurFinEnd) and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_BillDetails Set DocNo = DocNo + @NumToAdd Where (DocDate Between @CurFinStart and @CurFinEnd) and DocNo >= @StNo and CompCode=@CmCode
		End
	Else
	If @Restart='Monthly'
		Begin
			Declare @Year int, @Month int
			Select @Year=Year(@VrDate), @Month=Month(@VrDate)

			Update FAS_MEM_VoucherTranMast Set DocNo = DocNo + @NumToAdd Where  Year(DocDate)=@Year and Month(DocDate)=@Month and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranSub Set DocNo = DocNo + @NumToAdd Where  Year(DocDate)=@Year and Month(DocDate)=@Month and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranPay Set DocNo = DocNo + @NumToAdd Where  Year(DocDate)=@Year and Month(DocDate)=@Month and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranRef Set DocNo = DocNo + @NumToAdd Where  Year(DocDate)=@Year and Month(DocDate)=@Month and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranNarr Set DocNo = DocNo + @NumToAdd Where  Year(DocDate)=@Year and Month(DocDate)=@Month and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranCostCentre Set DocNo = DocNo + @NumToAdd Where  Year(DocDate)=@Year and Month(DocDate)=@Month and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_BillDetails Set DocNo = DocNo + @NumToAdd Where Year(DocDate)=@Year and Month(DocDate)=@Month and DocNo >= @StNo and CompCode=@CmCode
		End
	Else
	If @Restart='Weekly'
		Begin
			Declare @Year2 int, @Week int
			Select @Year2=Year(@VrDate), @Week=Datepart(wk, @VrDate) 
			
			Update FAS_MEM_VoucherTranMast Set DocNo = DocNo + @NumToAdd Where  Year(DocDate)=@Year2 and Datepart(wk, DocDate)=@Week and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranSub Set DocNo = DocNo + @NumToAdd Where  Year(DocDate)=@Year2 and Datepart(wk, DocDate)=@Week and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranPay Set DocNo = DocNo + @NumToAdd Where  Year(DocDate)=@Year2 and Datepart(wk, DocDate)=@Week and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranRef Set DocNo = DocNo + @NumToAdd Where  Year(DocDate)=@Year2 and Datepart(wk, DocDate)=@Week and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranNarr Set DocNo = DocNo + @NumToAdd Where  Year(DocDate)=@Year2 and Datepart(wk, DocDate)=@Week and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranCostCentre Set DocNo = DocNo + @NumToAdd Where  Year(DocDate)=@Year2 and Datepart(wk, DocDate)=@Week and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_BillDetails Set DocNo = DocNo + @NumToAdd Where Year(DocDate)=@Year2 and Datepart(wk, DocDate)=@Week and DocNo >= @StNo and CompCode=@CmCode
		End
	Else
	If @Restart='Daily'
		Begin
			Update FAS_MEM_VoucherTranMast Set DocNo = DocNo + @NumToAdd Where  DocDate=@VrDate and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranSub Set DocNo = DocNo + @NumToAdd Where  DocDate=@VrDate and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranPay Set DocNo = DocNo + @NumToAdd Where  DocDate=@VrDate and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranRef Set DocNo = DocNo + @NumToAdd Where  DocDate=@VrDate and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranNarr Set DocNo = DocNo + @NumToAdd Where  DocDate=@VrDate and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_VoucherTranCostCentre Set DocNo = DocNo + @NumToAdd Where  DocDate=@VrDate and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_MEM_BillDetails Set DocNo = DocNo + @NumToAdd Where DocDate=@VrDate and DocNo >= @StNo and CompCode=@CmCode
		End
	Else
		Begin
			Declare @tmpCmCode varchar(5)
			Select @tmpCmCode=Left(@CmCode, 4)+'%'

			Update FAS_MEM_VoucherTranMast Set DocNo = DocNo + @NumToAdd Where  DocNo >= @StNo and DocDate >= @VrDate and CompCode like @tmpCmCode
		
			Update FAS_MEM_VoucherTranSub Set DocNo = DocNo + @NumToAdd Where  DocNo >= @StNo and DocDate >= @VrDate and CompCode like @tmpCmCode
		
			Update FAS_MEM_VoucherTranPay Set DocNo = DocNo + @NumToAdd Where  DocNo >= @StNo and DocDate >= @VrDate and CompCode like @tmpCmCode
		
			Update FAS_MEM_VoucherTranRef Set DocNo = DocNo + @NumToAdd Where  DocNo >= @StNo and DocDate >= @VrDate and CompCode like @tmpCmCode
		
			Update FAS_MEM_VoucherTranNarr Set DocNo = DocNo + @NumToAdd Where  DocNo >= @StNo and DocDate >= @VrDate and CompCode like @tmpCmCode
		
			Update FAS_MEM_VoucherTranCostCentre Set DocNo = DocNo + @NumToAdd Where  DocNo >= @StNo and DocDate >= @VrDate and CompCode like @tmpCmCode
		
			Update FAS_MEM_BillDetails Set DocNo = DocNo + @NumToAdd Where DocNo >= @StNo and DocDate >= @VrDate and CompCode like @tmpCmCode
		End

End
GO

