/****** Object:  StoredProcedure [dbo].[FAS_Mod_MEM_VrTranReNum_FromTo]    Script Date: 17/06/2026 11:30:08 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Mod_MEM_VrTranReNum_FromTo] (@FromVrNo int, @FromVrDate datetime, @ToVrNo int, @ToVrDate datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON

/*	Declare @Restart varchar(15), @isAutoNo bit


	Select @Restart=RestartAt, @isAutoNo=isAutoNumber From FAS_VoucherMaster Where VrRoute+VrWidth='07' and CompCode=@CmCode

*/
	Declare @VrTranType char(1)	-- 'P' to Previous Date; 'F' to Future Date; 'N' to No Date Change

	If @FromVrDate > @ToVrDate
		Select @VrTranType='P'
	Else
	If @FromVrDate < @ToVrDate
		Select @VrTranType='F'
	Else
		Select @VrTranType='N'



	Declare @isSamePeriod bit	-- True means Both the dates are within the restart period Else it is in different period.


--	If @Restart='FinYearly'
		Begin

			Declare @CurFinStart datetime,  @CurFinEnd datetime


			If Month(@ToVrDate) <= 3 
				Select @CurFinStart = Convert(datetime, Convert(varchar, Year(@ToVrDate)-1) + '04' + '01', 112), 
				           @CurFinEnd = Convert(datetime, Convert(varchar, Year(@ToVrDate)) + '03' + '31', 112)
			Else
				Select @CurFinStart = Convert(datetime, Convert(varchar, Year(@ToVrDate)) + '04' + '01', 112), 
				           @CurFinEnd = Convert(datetime, Convert(varchar, Year(@ToVrDate)+1) + '03' + '31', 112)

			If (@FromVrDate Between @CurFinStart AND @CurFinEnd) AND (@ToVrDate Between @CurFinStart AND @CurFinEnd)
				Select @isSamePeriod = '1'
			Else
				Select @isSamePeriod = '0'

		End

/*	Else
	If @Restart='Monthly'
		Begin
			If Convert(varchar(6), @FromVrDate, 112)=Convert(varchar(6), @ToVrDate, 112)
				Select @isSamePeriod = '1'
			Else
				Select @isSamePeriod = '0'
		End
	Else
	If @Restart='Weekly'
		Begin			
			If (Year(@FromVrDate)=Year(@ToVrDate)) AND (Datepart(wk, @FromVrDate) =Datepart(wk, @ToVrDate) )
				Select @isSamePeriod = '1'
			Else
				Select @isSamePeriod = '0'
		End
	Else
	If @Restart='Daily'
		Begin
			If @FromVrDate=@ToVrDate
				Select @isSamePeriod = '1'
			Else
				Select @isSamePeriod = '0'
		End
	Else
		Select @isSamePeriod = '1'

*/

	If @isSamePeriod='1'
		If @VrTranType='P'
			Execute FAS_Mod_MEM_VrTranReNum_FromTo_SamePeriod @ToVrNo, @ToVrDate, @FromVrNo,  @FromVrDate, 1, @CmCode
		Else
		If @VrTranType='F'  
			Execute FAS_Mod_MEM_VrTranReNum_FromTo_SamePeriod @FromVrNo, @FromVrDate, @ToVrNo,  @ToVrDate, -1, @CmCode
	Else
		If @VrTranType<>'N'
			Begin
				Execute FAS_Mod_MEM_VrTranReNum_From @FromVrNo, @FromVrDate,  -1, @CmCode
				Execute FAS_Mod_MEM_VrTranReNum_From @ToVrNo, @ToVrDate,  1, @CmCode
			End
End
GO

