CREATE PROCEDURE [dbo].[FAS_Mod_MEM_VrTranReNum_FromTo_SamePeriod] (@StVrNo int, @StVrDate datetime, @EnVrNo int, @EnVrDate datetime, @VrRoute varchar(42), @NumToAdd int, @CmCode varchar(12))

AS

Begin

	Update FAS_MEM_VoucherTranMast Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and (DocNo Between  @StVrNo and @EnVrNo) and (DocDate Between  @StVrDate and @EnVrDate) and CompCode=@CmCode

	Update FAS_MEM_VoucherTranSub Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and (DocNo Between  @StVrNo and @EnVrNo) and (DocDate Between  @StVrDate and @EnVrDate) and CompCode=@CmCode

	Update FAS_MEM_VoucherTranPay Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and (DocNo Between  @StVrNo and @EnVrNo) and (DocDate Between  @StVrDate and @EnVrDate) and CompCode=@CmCode

	Update FAS_MEM_VoucherTranRef Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and (DocNo Between  @StVrNo and @EnVrNo) and (DocDate Between  @StVrDate and @EnVrDate) and CompCode=@CmCode

	Update FAS_MEM_VoucherTranNarr Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and (DocNo Between  @StVrNo and @EnVrNo) and (DocDate Between  @StVrDate and @EnVrDate) and CompCode=@CmCode

	Update FAS_MEM_VoucherTranCostCentre Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and (DocNo Between  @StVrNo and @EnVrNo) and (DocDate Between  @StVrDate and @EnVrDate) and CompCode=@CmCode

	Update FAS_MEM_BillDetails Set DocNo = DocNo + @NumToAdd Where VrRoute=@VrRoute and (DocNo Between  @StVrNo and @EnVrNo) and (DocDate Between  @StVrDate and @EnVrDate) and CompCode=@CmCode


End
