CREATE PROCEDURE [dbo].[FAS_Mod_VoucherParent] (@OldPath varchar(42), @NewPath varchar(42), @CmCode varchar(12))

AS

Begin
	Set NOCOUNT ON

	Declare @LnPath int
	Select @LnPath = Len(@OldPath)

	Update FAS_VoucherMaster Set VrRoute = Stuff(VrRoute,1,@LnPath, @NewPath) Where Substring(VrRoute,1,@LnPath) = @OldPath and CompCode = @CmCode

	Update FAS_VoucherTranMast Set VrRoute = Stuff(VrRoute,1,@LnPath, @NewPath) Where Substring(VrRoute,1,@LnPath) = @OldPath and CompCode = @CmCode

	Update FAS_VoucherTranSub Set VrRoute = Stuff(VrRoute,1,@LnPath, @NewPath) Where Substring(VrRoute,1,@LnPath) = @OldPath and CompCode = @CmCode

	Update FAS_VoucherTranPay Set VrRoute = Stuff(VrRoute,1,@LnPath, @NewPath) Where Substring(VrRoute,1,@LnPath) = @OldPath and CompCode = @CmCode

	Update FAS_VoucherTranRef Set VrRoute = Stuff(VrRoute,1,@LnPath, @NewPath) Where Substring(VrRoute,1,@LnPath) = @OldPath and CompCode = @CmCode

End
GO

