			Update FAS_VoucherTranPay Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and Year(DocDate)=@Year2 and Datepart(wk, DocDate)=@Week and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_VoucherTranRef Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and Year(DocDate)=@Year2 and Datepart(wk, DocDate)=@Week and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_VoucherTranNarr Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and Year(DocDate)=@Year2 and Datepart(wk, DocDate)=@Week and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_VoucherTranCostCentre Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and Year(DocDate)=@Year2 and Datepart(wk, DocDate)=@Week and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_BillDetails Set DocNo = DocNo + @NumToAdd Where VrRoute=@VrRoute and Year(DocDate)=@Year2 and Datepart(wk, DocDate)=@Week and DocNo >= @StNo and CompCode=@CmCode
		End
	Else
	If @Restart='Daily'
		Begin
			Update FAS_VoucherTranMast Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and DocDate=@VrDate and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_VoucherTranSub Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and DocDate=@VrDate and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_VoucherTranPay Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and DocDate=@VrDate and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_VoucherTranRef Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and DocDate=@VrDate and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_VoucherTranNarr Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and DocDate=@VrDate and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_VoucherTranCostCentre Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and DocDate=@VrDate and DocNo >= @StNo and CompCode=@CmCode
		
			Update FAS_BillDetails Set DocNo = DocNo + @NumToAdd Where VrRoute=@VrRoute and DocDate=@VrDate and DocNo >= @StNo and CompCode=@CmCode
		End
	Else
		Begin

			Declare @tmpCmCode varchar(5)
			Select @tmpCmCode=Left(@CmCode, 4)+'%'

			Update FAS_VoucherTranMast Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and DocNo >= @StNo and DocDate >= @VrDate and CompCode like @tmpCmCode
		
			Update FAS_VoucherTranSub Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and DocNo >= @StNo and DocDate >= @VrDate and CompCode like @tmpCmCode
		
			Update FAS_VoucherTranPay Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and DocNo >= @StNo and DocDate >= @VrDate and CompCode like @tmpCmCode
		
			Update FAS_VoucherTranRef Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and DocNo >= @StNo and DocDate >= @VrDate and CompCode like @tmpCmCode
		
			Update FAS_VoucherTranNarr Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and DocNo >= @StNo and DocDate >= @VrDate and CompCode like @tmpCmCode
		
			Update FAS_VoucherTranCostCentre Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and DocNo >= @StNo and DocDate >= @VrDate and CompCode like @tmpCmCode
		
			Update FAS_BillDetails Set DocNo = DocNo + @NumToAdd Where VrRoute=@VrRoute and DocNo >= @StNo and DocDate >= @VrDate and CompCode like @tmpCmCode
		End
End
