CREATE PROCEDURE [dbo].[FAS_Mod_VrTranReNum_FromTo_SamePeriod] (@StVrNo int, @StVrDate datetime, @EnVrNo int, @EnVrDate datetime, @VrRoute varchar(42), @NumToAdd int, @CmCode varchar(12))

AS

Begin

	Update FAS_VoucherTranMast Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and (DocNo Between  @StVrNo and @EnVrNo) and (DocDate Between  @StVrDate and @EnVrDate) and CompCode=@CmCode

	Update FAS_VoucherTranSub Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and (DocNo Between  @StVrNo and @EnVrNo) and (DocDate Between  @StVrDate and @EnVrDate) and CompCode=@CmCode

	Update FAS_VoucherTranPay Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and (DocNo Between  @StVrNo and @EnVrNo) and (DocDate Between  @StVrDate and @EnVrDate) and CompCode=@CmCode

	Update FAS_VoucherTranRef Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and (DocNo Between  @StVrNo and @EnVrNo) and (DocDate Between  @StVrDate and @EnVrDate) and CompCode=@CmCode

	Update FAS_VoucherTranNarr Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and (DocNo Between  @StVrNo and @EnVrNo) and (DocDate Between  @StVrDate and @EnVrDate) and CompCode=@CmCode

	Update FAS_VoucherTranCostCentre Set DocNo = DocNo + @NumToAdd Where  VrRoute=@VrRoute and (DocNo Between  @StVrNo and @EnVrNo) and (DocDate Between  @StVrDate and @EnVrDate) and CompCode=@CmCode

	Update FAS_BillDetails Set DocNo = DocNo + @NumToAdd Where VrRoute=@VrRoute and (DocNo Between  @StVrNo and @EnVrNo) and (DocDate Between  @StVrDate and @EnVrDate) and CompCode=@CmCode


End
GO

