CREATE PROCEDURE [dbo].[FAS_MonthUpdate] (@Start Datetime) AS

Begin
	Declare @Count int, @Date Datetime
	Set @Count = 1
	Set @Date = @Start

	While @Count < 13
		Begin
			Update fas_month set mndate=@Date where mnCode=@Count
			Set @Date = Dateadd(month, 1, @Date)
			Set @Count = @Count + 1
		End
End






GO

