CREATE PROCEDURE [dbo].[FAS_PartyMaster_Fil_Address](@PartyCode int, @AsOnDate datetime, @RptDate datetime, 
  @BranchID varchar(3),@CompID Varchar(3))                          
AS                          
BEGIN                          
  SET NOCOUNT ON;  
   
  Select IsNull(a.PartyCode,0) As PartyCode, IsNull(a.Add1,'') As Add1, IsNull(a.Add2,'') As Add2, IsNull(a.Add3,'') As Add3, 
    a.Country, a.State, a.City, IsNull(a.Pincode,'') As Pincode, IsNull(a.Phone,'') As Phone, IsNull(a.Fax,'') As Fax, 
    IsNull(a.Cellular,'') As Cellular, IsNull(a.EMail,'') As EMail, a.CST, a.CSTDate, a.LST, a.LSTDate, 
    a.GSTRegNo, a.GSTRegDate, a.ProvisionalID, a.AreaCode, a.ECCNo,
    a.Range, a.EDRegNo, a.EDRegDate, a.ContactPerson, IsNull(a.UdyamNo,'') As UdyamNo, a.UdyamDate, a.Userid, a.Branchid, a.Compid, a.TranStamp,
    isnull(b.CountryCode,0) as CountryCode,  isnull(b.StateCode,0) as StateCode, isnull(b.CityCode, 0) as CityCode
  From FAS_PARTY_ADDRESS a
  Left Outer Join dbo.fn_COM_Get_CountryStateCity_Dtl(@AsOnDate, @RptDate, @BranchID, @CompID) b
    On a.State= b.StateName and a.Country=b.CountryName and a.City=b.CityName
  Where PartyCode=@PartyCode and Compid=@CompID and Branchid=@BranchID
END
GO

