CREATE PROCEDURE [dbo].[FAS_Pymt_Addr] (@LrCode int, @CmCode varchar(12))

AS

	Set NOCOUNT ON

	

	Select 'Party' as Type, 
		isNull(a.PartyName, c.LedgerName) as LrName, 
		isNull(b.Add1, '') as Add1, isNull(b.Add2, '') as Add2, isNull(b.Add3, '') as Add3, isNull(b.City, '') as City, isNull(b.Pincode, '') as Pincode
	from FAS_Party_Master a Left Outer Join FAS_Party_Address b 
	On a.PartyCode=b.PartyCode and a.BranchID=b.BranchID and a.CompID=b.CompID
	Full Outer Join FAS_LedgerMaster c
	On a.PartyCode=c.LedgerCode and a.CompID+a.BranchID=c.CompCode	
	Where IsNull(a.PartyCode, c.LedgerCode) = @LrCode and IsNull(a.CompID+a.BranchID, c.CompCode)=@CmCode

	Union All

	Select 'We' as Type, CompanyName, Address1, Address2, '', City, Pincode from Company_Master Where CompID+BranchID = @CmCode

	Order by 1 desc
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_AA_0]    Script Date: 17/06/2026 11:30:09 ******/
SET ANSI_NULLS OFF
