CREATE PROCEDURE [dbo].[FAS_Rpt_AA_0] (@UserKey Varchar(36), @LrRoute varchar(4), @RptDate Datetime,  @PrStart Datetime, @PrEnd Datetime, @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON

	Declare @BranchID varchar(2)
	Select @BranchID = substring(@CmCode, 3, 2)	
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)


	Select LrCode, [Invoice No], [Invoice Date], Amount, [Due Date], Convert(varchar, OverDue) + space(4) as OverDue,	
									Case when Overdue < 1 then Amount else '' End as [x < 1],
									Case when Overdue between 1 and 30 then Amount else '' End as [1 <= x <= 30],
									Case when Overdue between 31 and 60 then Amount else '' End as [31 <= x <= 60],
									Case when Overdue between 61 and 90 then Amount else '' End as [61 <= x <= 90],
									Case when Overdue > 90 then Amount else '' End as [x > 90]
	from 
		(Select LrCode, RefNo as [Invoice No], Convert(Datetime,  RefDate, 105) as [Invoice Date], Convert(Datetime,  DueDate, 105) as [Due Date], 
			(Convert(varchar, Abs(Amount)) + ' ' + Case sign(Amount) when -1 then 'Cr' When 1 then 'Dr' End) as Amount,
			DateDiff(day, DueDate, @RptDate) as OverDue
		from 
			(
			Select y.RefNo, y.RefDate, DateAdd(day, y.CreditDays, y.RefDate) as DueDate, z.LrCode, z.Amount 
			from fas_billdetails y,
				(Select LrCode, RefNo, Sum(Amount) as Amount from fas_billdetails
				where Type <> 'On Acct' and RefDate <= @RptDate 
					and LrCode in (Select LedgerCode from FAS_LedgerMaster where Left(LrRoute, 4)=@LrRoute and CompCode=@CmCode
							and LedgerCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID)
							)
					and CompCode=@CmCode
				group by LrCode, RefNo ) z 
			where z.Amount <> 0  and y.Type in ('Advance',  'New Ref') and y.RefNo=z.RefNo and y.LrCode=z.LrCode and y.CompCode=@CmCode
			) d
				) b  
		Order by LrCode, [Invoice Date]

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_AA_01]    Script Date: 17/06/2026 11:30:09 ******/
