CREATE PROCEDURE [dbo].[FAS_Rpt_AA_01] (@UserKey Varchar(36), @RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode Varchar(12))

AS

Begin
	SET NOCOUNT ON

	
	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Select [Invoice No], [Invoice Date], Amount, [Due Date], Convert(varchar, OverDue) + space(4) as OverDue,	
									Case when Overdue < 1 then Amount else '' End as [x < 1],
									Case when Overdue between 1 and 30 then Amount else '' End as [1 <= x <= 30],
									Case when Overdue between 31 and 60 then Amount else '' End as [31 <= x <= 60],
									Case when Overdue between 61 and 90 then Amount else '' End as [61 <= x <= 90],
									Case when Overdue > 90 then Amount else '' End as [x > 90]
	from 
		(Select RefNo as [Invoice No], Convert(Datetime,  RefDate, 105) as [Invoice Date], Convert(Datetime,  Dateadd(day, isNull(CreditDays, 0), RefDate) , 105) as [Due Date], 
			(Convert(varchar, Abs(Amount)) + ' ' + Case sign(Amount) when 1 then 'Dr' When -1 then 'Cr' End + '     ') as Amount,
			DateDiff(day, Dateadd(day, isNull(CreditDays, 0), RefDate), @RptDate) as OverDue
		from 
			(
			Select isNull(y.RefNo, z.RefNo) as RefNo, 
					isNull(y.RefDate, (Select Min(x.RefDate) from FAS_BillDetails x 
								where x.RefNo=z.RefNo and x.RefDate <= @RptDate 
									and x.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @Userkey and BranchID = @BranchID and CompID = @CompID) 
									and x.CompCode=@CmCode)
							) as RefDate, 
					isNull(y.CreditDays, 0) CreditDays, z.Amount 
				from 
					(Select RefNo, RefDate, CreditDays from fas_billdetails 
						where LrCode in (Select SelectInt From Com_SelectList Where UserKey = @Userkey and BranchID = @BranchID and CompID = @CompID) 
							and Type in ('New Ref', 'Advance') and CompCode=@CmCode
					) y 
				Right Outer Join
					(Select RefNo, Sum(Amount) as Amount from fas_billdetails
					where Type <> 'On Acct' and RefDate <= @RptDate 
					and LrCode in (Select SelectInt From Com_SelectList Where UserKey = @Userkey and BranchID = @BranchID and CompID = @CompID) 
					and CompCode=@CmCode
					group by RefNo having sum(Amount) <> 0 ) z 
				On y.RefNo=z.RefNo 
			) d
				) b
		Order by [Invoice Date]

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_AA_1]    Script Date: 17/06/2026 11:30:09 ******/
SET ANSI_NULLS OFF
GO

