CREATE PROCEDURE [dbo].[FAS_Rpt_AA_1] (@UserKey varchar(36), @LrRoute varchar(4), @RptDate Datetime, @PrStart Datetime, @PrEnd Datetime, @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON

	Declare @BranchID varchar(2)
	Select @BranchID = substring(@CmCode, 3, 2)	
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Select LrCode, (Select LedgerName from FAS_LedgerMaster where LedgerCode=e.LrCode and CompCode=@CmCode) as LrName,
		Sum(Amount) as Amount, Sum(UnderDue) as UnderDue, Sum(Amt30) as Amt30, Sum(Amt3160) as Amt3160,
		Sum(Amt6190) as Amt6190, Sum(Amt90) as Amt90,
		(Select isNull(Sum(Amount), 0) from FAS_BillDetails where LrCode=e.LrCode and Type='On Acct' and RefDate <= @RptDate and CompCode=@CmCode) as AdvAmt
	from

		(Select LrCode,  Amount, Convert(varchar, OverDue) as OverDue,	
			Case when Overdue < 1 then Amount else 0 End as UnderDue,
			Case when Overdue between 1 and 30 then Amount else 0 End as Amt30,
			Case when Overdue between 31 and 60 then Amount else 0 End as Amt3160,
			Case when Overdue between 61 and 90 then Amount else 0 End as Amt6190,
			Case when Overdue > 90 then Amount else 0 End as Amt90
		from 
			(Select y.LrCode, DateDiff(day, y.RefDate, @RptDate)-y.CreditDays  as OverDue, isNull(z.Amount, 0) as Amount
			from FAS_BillDetails y Left Outer Join
				(Select LrCode, RefNo, CompCode, Sum(Amount) as Amount from FAS_BillDetails
				where Type <> 'On Acct' and RefDate <= @RptDate 
					and LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID)
					and CompCode=@CmCode
				group by LrCode, RefNo, CompCode) z 
			On y.RefNo=z.RefNo and y.LrCode=z.LrCode and y.CompCode=z.CompCode
			where isNull(z.Amount, 0) <> 0  and y.Type in ('Advance', 'New Ref') and y.CompCode=@CmCode
			) d
		) e
	group by LrCode Order by 2
End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_AA_2]    Script Date: 17/06/2026 11:30:09 ******/
SET ANSI_NULLS OFF
