CREATE PROCEDURE [dbo].[FAS_Rpt_AA_2] (@UserKey Varchar(36), @LrRoute varchar(4), @RptDate Datetime, @PrStart Datetime, @PrEnd Datetime,  @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON


	Declare @BranchID varchar(2)
	select @BranchID = substring(@CmCode, 3, 2)	
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Select 'Overall Total', Sum(Amount) as Amount, Sum(UnderDue) as UnderDue, Sum(Amt30) as Amt30, Sum(Amt3160) as Amt3160,
		Sum(Amt6190) as Amt6190, Sum(Amt90) as Amt90
	from

		(Select Amount, Convert(varchar, OverDue) as OverDue,	
									Case when Overdue < 1 then Amount else 0 End as UnderDue,
									Case when Overdue between 1 and 30 then Amount else 0 End as Amt30,
									Case when Overdue between 31 and 60 then Amount else 0 End as Amt3160,
									Case when Overdue between 61 and 90 then Amount else 0 End as Amt6190,
									Case when Overdue > 90 then Amount else 0 End as Amt90
		from 
			(Select Amount, DateDiff(day, DueDate, @RptDate) as OverDue
			from
				(Select DateAdd(day, y.CreditDays, y.RefDate) as DueDate, Sum(z.Amount) as Amount
				from fas_billdetails y,
					(Select LrCode, RefNo, Sum(Amount) as Amount from fas_billdetails
					where Type <> 'On Acct' and RefDate <= @RptDate 
						and LrCode in (Select LedgerCode from FAS_LedgerMaster where Left(LrRoute, 4)=@LrRoute and CompCode=@CmCode
								and LedgerCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID)
							)
						and CompCode=@CmCode
					group by LrCode, RefNo ) z 
				where z.Amount <> 0  and y.Type in ('Advance', 'New Ref') and y.RefNo=z.RefNo and y.LrCode=z.LrCode and y.CompCode=@CmCode
				group by DateAdd(day, y.CreditDays, y.RefDate)
				) c
			) d
		) e
	End
GO

