CREATE PROCEDURE [dbo].[FAS_Rpt_BRS] (@UserKey varchar(36), @RptDate datetime,  @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

BEGIN

	SET NOCOUNT ON	

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)


	Select c.LrCode, a.ChqNo, Case c.DrAmt When 0 then a.ChqDate Else b.DocDate End  as CDate, Case c.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
			Case c.DrAmt When 0 Then Convert(varchar, isNull(c.CrAmt, 0)) Else  Convert(varchar, isNull(c.DrAmt, 0)) End as Amount,
			Case a.isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 								
					Else a.ChqFavor End as ChqFavor, a.DocNo, a.VrRoute, b.DocDate
	from FAS_VoucherTranPay a 
	Left Outer Join FAS_VoucherTranMast b
		On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
				Left Outer Join FAS_VoucherTranSub c
				On c.DocNo=a.DocNo and a.DocDate=c.DocDate and c.VrRoute=a.VrRoute and c.CompCode=a.CompCode
	Where c.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
	 and a.CompCode=@CmCode and (a.BankDate is Null or a.BankDate >@RptDate) and b.DocDate <= @RptDate 
	
	
	Union All
	
	Select '' LrCode, a.ChqNo, a.ChqDate, Case a.isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType, Convert(varchar, a.ChqAmount) as Amount,
			Case a.isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 
				Else a.ChqFavor End as ChqFavor, 
			a.DocNo, a.VrRoute, a.ChqDate	
		from FAS_VoucherTranPay a
	Where VrRoute like 'OpBal-%' and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6)) in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
	and CompCode=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate)	
	
	Order by PayType Desc, CDate, Amount


END
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_BRS_Book]    Script Date: 17/06/2026 11:30:09 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_BRS_Book] (@UserKey varchar(36), @RptDate datetime,  @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

BEGIN

	SET NOCOUNT ON	

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)	

	Select 'OB' as ChqType, ' ' as PayType, isNull(Sum(Amount), 0) as Amount 
	from (
		Select (Sum(DrAmt)-Sum(CrAmt)) as Amount  
		from fas_voucher_Vw 
		where DocDate <= @RptDate 
			and lrcode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
			and CompCode=@CmCode

		Union All 

		Select opbalance from fas_ledgermaster 
		where ledgercode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
			and CompCode=@CmCode
	       ) a

	Union All

	Select 'NotCleared' ChqType, PayType, isNull(Sum(Amount) , 0)
	from (
		Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
			Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else   isNull(b.DrAmt, 0) End as Amount
		from FAS_VoucherTranPay a Join FAS_Voucher_Vw b 
		On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
		Where b.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID 
								and CompId = @CompID)
		and a.CompCode=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate) and b.DocDate <= @RptDate 
	
		Union All

		Select Case isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType, ChqAmount as Amount
		from FAS_VoucherTranPay
		Where VrRoute like 'OpBal%' and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6)) in (Select SelectInt From Com_SelectList 
					Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID) 
		and CompCode=@CmCode and (BankDate is Null or BankDate > @RptDate)
	) x 
	Group by PayType
	
	Union All
	
	Select 'Cleared' ChqType, PayType, isNull(Sum(Amount) , 0)
	from (
		Select Case R.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
			Case R.DrAmt When 0 Then  isNull(R.CrAmt, 0) Else   isNull(R.DrAmt, 0) End as Amount
		From FAS_VoucherTranSub R Left Outer Join FAS_VoucherTranPay a 
			On R.DocNo=a.DocNo and R.DocDate=a.DocDate and R.VrRoute=a.VrRoute and R.CompCode=a.CompCode and a.BankDate is Not NULL
		Where R.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
		 and a.CompCode=@CmCode and  a.BankDate <= @RptDate and R.DocDate <= @RptDate 
	
		Union All
	
		Select Case isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType,  ChqAmount as Amount
		from FAS_VoucherTranPay
		Where VrRoute like 'OpBal%' and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6))  in (Select SelectInt From Com_SelectList 
						Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
		 and CompCode=@CmCode and (BankDate is Not Null AND BankDate <= @RptDate)
	) x 

	Group by PayType
	Order by 1 desc, 2 desc

END
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_BRS_Cleared]    Script Date: 17/06/2026 11:30:09 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_BRS_Cleared] (@BankCode int, @RptDate datetime, @CmCode varchar(12))

AS

	Set NOCOUNT ON

	
	Select 1 as SortOrder, a.ChqNo,  Case R.DrAmt When 0 then a.ChqDate Else b.DocDate End as cDate,
		Case R.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
		Case R.DrAmt When 0 Then Convert(varchar, isNull(R.CrAmt, 0)) Else  Convert(varchar, isNull(R.DrAmt, 0)) End as Amount,
		Case isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 
			Else a.ChqFavor End as ChqFavor, 
		a.DocNo, a.VrRoute, a.BankDate, b.DocDate
	from FAS_VoucherTranPay a Join FAS_VoucherTranMast b 
	On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
			Join FAS_VoucherTranSub R
			On R.DocNo=a.DocNo and a.DocDate=R.DocDate and R.VrRoute=a.VrRoute and R.CompCode=a.CompCode
	Where R.LrCode=@BankCode and a.CompCode=@CmCode
			and (a.BankDate is Not Null AND a.BankDate <= @RptDate) and b.DocDate <= @RptDate 

	Union All

	Select 1 as SortOrder, ChqNo, ChqDate, Case isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType, Convert(varchar, ChqAmount) as Amount,
		Case isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=ChqFavor and CompCode=@CmCode) 
			Else ChqFavor End as ChqFavor, 
		DocNo, VrRoute, BankDate, ChqDate
	from FAS_VoucherTranPay
	Where DocNo=0 and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6))=@BankCode and CompCode=@CmCode
		and (BankDate is Not Null AND BankDate <= @RptDate)


	Order by 3 Desc, 2, 4
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_BRS_NonCleared_Data]    Script Date: 17/06/2026 11:30:09 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_BRS_NonCleared_Data] (@BankCode int, @RptDate datetime, @isAnyFromDate bit, @FromDate datetime, @isAnyToDate bit, @ToDate datetime, @isBankDate bit, @CmCode varchar(12))
AS
BEGIN
	Set NOCOUNT ON;

	Declare @FDate datetime, @TDate datetime


	if @isAnyFromDate='1' 
		if @isBankDate='1'
			Select @FDate = isNull((Select Min(ChqDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and CompCode=@CmCode), @FromDate)
		else
			Select @FDate = isNull((Select Min(DocDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and CompCode=@CmCode), @FromDate)
	else
		Select @FDate=@FromDate

	if @isAnyToDate='1' 
		if @isBankDate='1'
			Select @FDate = isNull((Select Max(ChqDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and CompCode=@CmCode), @ToDate)
		else
			Select @FDate = isNull((Select Max(DocDate) from FAS_VoucherTranPay where ChqBank=Convert(varchar, @BankCode) and CompCode=@CmCode), @ToDate)
	else
		Select @TDate=@ToDate


	Select 1 as SortOrder, '0' as ChqNo, Null as CDate, PayType,  Sum(Amount) as Amount, 'Opening Balance' as ChqFavor, 0 as DocNo, '' as VrRoute, Null as DocDate
	from
		(Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
				Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else  isNull(b.DrAmt, 0) End as Amount
		from FAS_VoucherTranPay a 
		Left Outer Join FAS_Voucher_vw b
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
		Where b.LrCode=@BankCode and Left(a.CompCode, 4)=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate) and b.DocDate < @FDate
	
		Union All
		
		Select Case a.isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType, a.ChqAmount as Amount
			from FAS_VoucherTranPay a
		Where DocNo=0 and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6))=@BankCode and Left(CompCode, 4)=@CmCode
			and (a.BankDate is Null or a.BankDate > @RptDate)
		) x
	Group by PayType

	Union All
	
	Select * from (
		Select 2 as SortOrder, a.ChqNo, 
				Case When a.docNo=0 then a.ChqDate else Case b.DrAmt When 0 then a.ChqDate Else b.DocDate End end as CDate, 
				Case When a.docNo=0 then Case When a.isReceipt='1' then 'Rcpt' else 'Issue' End
					Else Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End End as PayType,
				Case When a.docNo=0 then a.ChqAmount Else
						Case b.DrAmt When 0 Then isNull(b.CrAmt, 0) Else   isNull(b.DrAmt, 0) End End as Amount,
				Case a.isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 								
						Else a.ChqFavor End as ChqFavor, a.DocNo, a.VrRoute, 
				Case When a.docNo=0 then a.DocDate else b.DocDate end as DocDate
		from FAS_VoucherTranPay a 
		Left Outer Join FAS_Voucher_vw b
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
		Where isNull(b.LrCode, a.ChqBank)=@BankCode and a.CompCode=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate) 
		) x
		where (DocDate Between @FDate and @TDate)
	
	Union All

	Select 3 as SortOrder, '0' as ChqNo, Null as CDate,  PayType, Sum(Amount) as Amount, 'Closing Balance' as ChqFavor, 0 as DocNo, '' as VrRoute, Null as DocDate
	from
		(Select Case b.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType,
				Case b.DrAmt When 0 Then  isNull(b.CrAmt, 0) Else  isNull(b.DrAmt, 0) End as Amount
		from FAS_VoucherTranPay a 
		Left Outer Join FAS_Voucher_vw b
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
		Where b.LrCode=@BankCode and a.CompCode=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate) and b.DocDate > @TDate
		) y
	Group by PayType


	Order by 1, 4 Desc, 3, 5
END
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_BS]    Script Date: 17/06/2026 11:30:09 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
