CREATE PROCEDURE [dbo].[FAS_Rpt_BS] (@RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

	Set NOCOUNT ON

	Declare @Start datetime
	Select @Start = @PrStart

	Select Master, Path, Type, Case Type when 'Group' then Space(Len(Path)) + Particulars
                                                             when 'Ledger' then space(Len(Path))+'    '+Particulars End as Particulars,
		Case When Type='Ledger' or (Len(Path) > 2 and Type='Group') then
			Case When Path in ('09', '02', '0C', '04', '0A') then Amt1 Else Amt1 End
		Else 0 End as SubAmt,	
		Case When Len(Path)=2 and Type='Group' then
			Case When Path in ('09', '02', '0C', '04', '0A') then Amt1 Else Amt1 End
		Else 0 End as TotAmt,
		Case Left(Path, 2) 
			When '0F' then 1 When '00' then 2 When 'ZZ' then 3
			 When '01' then 5 When '0B' then 6 
			 When '09' then 11 When '02' then 12  When '03' then 13 When '0C' then 14 When '04' then 15 When '0A' then 16
		End as SortOrder

	from

		(Select Master, Type, Particulars, isNull(ClosingBalance, 0) as Amt1, Path, 0 as LrCode
		from dbo.fn_FAS_LedgersClosingBalance(@PrStart, @Start,@RptDate, @CmCode) 
		Where Left(Path, 2) in ('00', '01', '02', '03', '04', '09', '0A', '0B', '0C', '0F')
		) N

	Order by Path, Type
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_BSPLSchedule_Fil_RptLevel]    Script Date: 17/06/2026 11:30:10 ******/
SET ANSI_NULLS ON
