GO

CREATE PROCEDURE [dbo].[FAS_Rpt_BSPLSchedule_Fil_RptLevel](@FrmFlg  Char(1),@CompCode Varchar(12))  
As  
SET NOCOUNT ON  
  
  
 Begin  
   
  IF @FrmFlg='B' --Balance Sheet  
    
   Begin  
     
    Select Sum(LevelNo)   
    From  
    (  
     Select Max(len(SchRoute+SchWidth))/2 LevelNo   
     From FAS_ScheduleMaster  
     Where CompCode=@CompCode and IsBalancesheetEntry='1'  
  
     Union All  
  
     Select Max(Len(SubGrpRoute+SubGrpWidth))/2 LevelNo   
     From FAS_BSPLGroupMaster  
     Where CompCode=@CompCode and (SubGrpRoute+SubGrpWidth)='01'  
    )x  
   End  
  
  Else ---Profit And Loss  
   
   Begin  
     
    Select Sum(LevelNo)   
    From  
    (  
     Select Max(len(SchRoute+SchWidth))/2 LevelNo   
     From FAS_ScheduleMaster  
     Where CompCode=@CompCode and IsBalancesheetEntry='0'  
  
     Union All  
  
     Select Max(Len(SubGrpRoute+SubGrpWidth))/2 LevelNo   
     From FAS_BSPLGroupMaster  
     Where CompCode=@CompCode and (SubGrpRoute+SubGrpWidth)='02'  
    )x  
   End   
  
  
END  
GO

