CREATE PROCEDURE [dbo].[FAS_Rpt_BSPLSchedule_Gen_SubGrp](@SubGrpRoute Varchar(40),@CompCode Varchar(12))  
As  
BEGIN
    SET NOCOUNT ON;  
   
    Select SubGrpCode, SubGrpLongName, SubGrpRoute+SubGrpWidth as SubGrpPath, isDebitBalance, isExpand   
    From FAS_BSPLGroupMaster_vw  
    Where EffStatus='AA' and ByParentStatus='1' and SubGrpRoute Like @SubGrpRoute and CompCode=@CompCode  
    Order By SubGrpPath, Seq  
END  
GO

