GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_BSPLSchedule_Val](@CompCode Varchar(12))  
As  
BEGIN
    SET NOCOUNT ON;  
   
    Select LedgerCode   
    From FAS_LedgerMaster_AuthTbl a  
    Where Not Exists   
        (  
            Select * From FAS_ScheduleGroup b   
            Where b.LrCode=a.LedgerCode and b.CompCode=a.CompCode  
        )  
        and Not (a.LrRoute Like '00%' OR a.LrRoute Like '0205%')  
        and a.CompCode=@CompCode and a.EffStatus='AA'  
  
END
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_BudgetData_Fil]    Script Date: 17/06/2026 11:30:10 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_BudgetData_Fil](@PlanFor int, @PlanStart datetime, @PlanEnd datetime, @CmCode Varchar(12))

AS

BEGIN
	
		SET NOCOUNT ON
		
		Declare @tmpCmCode varchar(4)
		Select @tmpCmCode = Left(@CmCode, 4)
 
		Select a.SLCode, b.PlanDate,  Sum(Case When b.DrCode=a.SLCode Then Amount Else -Amount End) as BudgetAmount
		From
			(Select Distinct DrCode as SLCode
			From FAS_Budget_Dtl
			Where PlanFor= @PlanFor and PlanDate between @PlanStart and @PlanEnd and CompCode=@tmpCmCode
			Union 
			Select Distinct CrCode
			From FAS_Budget_Dtl
			Where PlanFor= @PlanFor and PlanDate between @PlanStart and @PlanEnd and CompCode=@tmpCmCode 
			) a 
		Left Outer Join FAS_Budget_Dtl b
			On a.SLCode=b.DrCode OR a.SLCode=b.CrCode
		where b.PlanFor= @PlanFor and (b.PlanDate between @PlanStart and @PlanEnd) and b.CompCode=@tmpCmCode 
		Group By a.SLCode, b.PlanDate
		Order by a.SLCode, b.PlanDate

END
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_ChqPrint_Fil]    Script Date: 17/06/2026 11:30:10 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[FAS_Rpt_ChqPrint_Fil]
    (@BankCode int, @isChqDateRestrict bit, @FromDate datetime, @ToDate datetime, @IncludePrintedChequeAlso bit,
     @AsOnDate datetime, @RptDate datetime, @CmCode Varchar(12))         
As
BEGIN
    SET NOCOUNT ON
            
    Declare @CompID varchar(2), @BranchID varchar(2)
    SET @CompID=Left(@CmCode, 2)
    SET @BranchID=Substring(@CmCode, 3, 2)        
            
    If (@isChqDateRestrict=Convert(bit, 1))  /* Cheque Date Between */        
        BEGIN      
            If (@IncludePrintedChequeAlso=Convert(bit, '1'))      
                BEGIN      
                    Select b.ChqNo, b.ChqDate, b.ChqAmount,         
                        (Select CurrencyCode From dbo.fn_COM_Company_Master('A', @AsOnDate, @RptDate) Where BranchID=@BranchID and CompID=@CompID) as Symbol,         
                        c.LedgerCode As PayeeCode, isNull(c.LedgerName, b.ChqFavor) As PayeeName,        
                        (Select Max(PrintDate) From FAS_ChequePrint_Tran m        
                            Where m.BankCode=@BankCode and m.ChequeNo=b.ChqNo and m.CompCode=@CmCode) As LastPrintDate,
                        a.DocNo, a.DocDate, a.VrRoute
                    From FAS_VoucherTranMast a         
                    Left Outer Join Fas_VoucherTranPay b         
                        On a.DocDate = b.DocDate and a.DocNo = b.DocNo and a.VrRoute = b.VrRoute and a.CompCode = b.CompCode         
                    Left Outer Join Fas_LedgerMaster_AuthTbl c         
                        On b.ChqFavor = Convert(varchar, c.LedgerCode) and b.CompCode = c.CompCode        
                    Where b.ChqDate Between @FromDate and @ToDate and Left(a.VrRoute, 2) in ('01', '09')  
                        and a.PayMode in ('Cheque', 'AtPar') and a.isCancelled='0' and a.CompCode=@CmCode         
                        and (b.isBankCode='1' and ChqBank=Convert(varchar, @BankCode)) --and IsChqDelivered='0'        
                    Order By b.ChqDate, PayeeName      
                END      
            ELSE      
                BEGIN      
                    Select b.ChqNo, b.ChqDate, b.ChqAmount,         
                        (Select CurrencyCode From dbo.fn_COM_Company_Master('A', @AsOnDate, @RptDate) Where BranchID=@BranchID and CompID=@CompID) as Symbol,         
                        c.LedgerCode As PayeeCode, isNull(c.LedgerName, b.ChqFavor) as PayeeName,        
                        NULL as LastPrintDate, a.DocNo, a.DocDate, a.VrRoute
                    From FAS_VoucherTranMast a         
                    Left Outer Join Fas_VoucherTranPay b         
                        On a.DocDate = b.DocDate and a.DocNo = b.DocNo and a.VrRoute = b.VrRoute and a.CompCode = b.CompCode         
                    Left Outer Join Fas_LedgerMaster_AuthTbl c         
                        On b.ChqFavor = Convert(varchar, c.LedgerCode) and b.CompCode = c.CompCode        
                    Where b.ChqDate Between @FromDate and @ToDate and Left(a.VrRoute, 2) in ('01', '09')  
                        and a.PayMode in ('Cheque', 'AtPar') and a.isCancelled='0' and a.CompCode=@CmCode         
                        and (b.isBankCode='1' and ChqBank=Convert(varchar, @BankCode))      
                        and Not Exists (Select * From FAS_ChequePrint_Tran m      
                                        Where m.BankCode=@BankCode and m.ChequeNo=b.ChqNo and m.CompCode=@CmCode) --and IsChqDelivered='0'      
                    Order By b.ChqDate, PayeeName      
                END      
                        
        END        
    ELSE                                  /* Voucher Date Between */       
        BEGIN      
            IF (@IncludePrintedChequeAlso=Convert(bit, '1'))      
                BEGIN        
                    Select b.ChqNo, b.ChqDate, b.ChqAmount,         
                        (Select CurrencyCode From dbo.fn_COM_Company_Master('A', @AsOnDate, @RptDate) Where BranchID=@BranchID and CompID=@CompID) as Symbol,         
                        c.LedgerCode As PayeeCode, isNull(c.LedgerName, b.ChqFavor) as PayeeName,        
                        (Select Max(PrintDate) From FAS_ChequePrint_Tran m        
                            Where m.BankCode=@BankCode and m.ChequeNo=b.ChqNo and m.CompCode=@CmCode
                         ) As LastPrintDate,
                        a.DocNo, a.DocDate, a.VrRoute
                    From FAS_VoucherTranMast a         
                    Left Outer Join Fas_VoucherTranPay b         
                        On a.DocDate = b.DocDate and a.DocNo = b.DocNo and a.VrRoute = b.VrRoute and a.CompCode = b.CompCode         
                    Left Outer Join Fas_LedgerMaster_AuthTbl c         
                        On b.ChqFavor = Convert(varchar, c.LedgerCode) and b.CompCode = c.CompCode        
                                 
                    Where a.DocDate Between @FromDate and @ToDate and Left(a.VrRoute, 2) in ('01', '09')  
                        and a.PayMode in ('Cheque', 'AtPar') and a.isCancelled='0' and a.CompCode=@CmCode --and IsChqDelivered='0'     
                        and (b.isBankCode='1' and ChqBank=Convert(varchar, @BankCode))        
                    Order By b.DocDate, PayeeName        
                END      
            ELSE      
                BEGIN        
                    Select b.ChqNo, b.ChqDate, b.ChqAmount,         
                        (Select CurrencyCode From dbo.fn_COM_Company_Master('A', @AsOnDate, @RptDate) Where BranchID=@BranchID and CompID=@CompID) as Symbol,         
                        c.LedgerCode As PayeeCode, isNull(c.LedgerName, b.ChqFavor) as PayeeName,        
                        NULL As LastPrintDate, a.DocNo, a.DocDate, a.VrRoute
                    From FAS_VoucherTranMast a         
                    Left Outer Join Fas_VoucherTranPay b         
                        On a.DocDate = b.DocDate and a.DocNo = b.DocNo and a.VrRoute = b.VrRoute and a.CompCode = b.CompCode         
                    Left Outer Join Fas_LedgerMaster_AuthTbl c         
                        On b.ChqFavor = Convert(varchar, c.LedgerCode) and b.CompCode = c.CompCode        
                                 
                    Where a.DocDate Between @FromDate and @ToDate and Left(a.VrRoute, 2) in ('01', '09')  
                        and a.PayMode in ('Cheque', 'AtPar') and a.isCancelled='0' and a.CompCode=@CmCode         
                        and (b.isBankCode='1' and ChqBank=Convert(varchar, @BankCode))        
                        and Not Exists (Select * From FAS_ChequePrint_Tran m      
                                        Where m.BankCode=@BankCode and m.ChequeNo=b.ChqNo and m.CompCode=@CmCode) --and IsChqDelivered='0'     
                    Order By b.DocDate, PayeeName
                END
        END
END
GO

