CREATE PROCEDURE [dbo].[FAS_Rpt_DB_0] (@UserKey varchar(36), @VrRoute varchar(42), @Start as datetime, @End as datetime, @PrStart as datetime, @PrEnd as datetime, @CmCode as varchar(12))

 AS

Begin
	SET NOCOUNT ON

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	SELECT DocDate, DocNo, VTSNo, LrCode, Ledger_Route, LedgerName,  VoucherName,  Voucher_Route, Convert(varchar, isNull(DrAmt, 0)) as DrAmt, Convert(varchar, isNull(CrAmt, 0)) as CrAmt, Narration
	from Fas_VrDetails_vw
	where Docdate Between @Start and @End 
		and DocNo in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
		and Voucher_Route = @VrRoute and CompCode = @CmCode
	order by DocDate, Voucher_Route, DocNo, VTSNo

End
