CREATE PROCEDURE [dbo].[FAS_Rpt_FundMgmt] (@Userkey varchar(36), @RptDate datetime, @EndDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

BEGIN

	SET NOCOUNT ON
	
	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Select ChqNo, cDate, PayType, Amount, ChqFavor
	from 
		(Select a.ChqNo,  Case R.DrAmt When 0 then a.ChqDate Else b.DocDate End as cDate,
			Case R.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType, Case R.DrAmt When 0 Then  isNull(R.CrAmt, 0) Else  isNull(R.DrAmt, 0) End as Amount,
			Case isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 
			Else a.ChqFavor End as ChqFavor
		from FAS_VoucherTranPay a Join FAS_VoucherTranMast b 
		On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
			Join FAS_VoucherTranSub R
			On R.DocNo=a.DocNo and a.DocDate=R.DocDate and R.VrRoute=a.VrRoute and R.CompCode=a.CompCode
		Where R.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
			 and a.CompCode=@CmCode and (a.BankDate is Null or a.BankDate > @RptDate) and b.DocDate <= @RptDate 

		Union All

		Select ChqNo, ChqDate, Case isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType,  ChqAmount as Amount,
			Case isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=ChqFavor and CompCode=@CmCode) 
			Else ChqFavor End as ChqFavor
		from FAS_VoucherTranPay 	
		Where DocNo=0 and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6)) in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
		 and CompCode=@CmCode and (BankDate is Null or BankDate > @RptDate)  
		) k
	Where k.cDate <= @EndDate

	Union All

	Select '0', @RptDate, 'Balance', Sum(Amount), 'Opening Balance'
	from
		(Select -Sum(Amount) as Amount 
		from
			(Select (Sum(CrAmt)-Sum(DrAmt)) as Amount  
			from fas_voucher_Vw 
			Where DocDate <= @RptDate and lrcode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
			 and CompCode=@CmCode 

		        	Union All 

		        	Select opbalance from fas_ledgermaster where ledgercode in (Select SelectInt From Com_SelectList 
							Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
			 and CompCode=@CmCode 
			) a 
	Union All

		Select  Sum(Case When PayType='Issue' then Amount Else -Amount End) as IssAmt 
		from
			(Select a.ChqNo,  Case R.DrAmt When 0 then a.ChqDate Else b.DocDate End as cDate,
				Case R.DrAmt When 0 then 'Issue' Else 'Rcpt' End as PayType, Case R.DrAmt When 0 Then  isNull(R.CrAmt, 0) Else  isNull(R.DrAmt, 0) End as Amount,
				Case isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=a.ChqFavor and CompCode=@CmCode) 
				Else a.ChqFavor End as ChqFavor
			from FAS_VoucherTranPay a Join FAS_VoucherTranMast b 
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode 
				Join FAS_VoucherTranSub R
				On R.DocNo=a.DocNo and a.DocDate=R.DocDate and R.VrRoute=a.VrRoute and R.CompCode=a.CompCode
			Where r.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
			and a.CompCode=@CmCode
				and (a.BankDate is Null or a.BankDate > @RptDate) and b.DocDate <= @RptDate 

			Union All

			Select ChqNo, ChqDate, Case isReceipt When 0 then 'Issue' Else 'Rcpt' End as PayType,  ChqAmount as Amount,
				Case isLrCode When 1 then (Select LedgerName from FAS_LedgerMaster Where LedgerCode=ChqFavor and CompCode=@CmCode) 
				Else ChqFavor End as ChqFavor
			from FAS_VoucherTranPay 	
			Where DocNo=0 and Convert(int, Substring(VrRoute, 7, Len(VrRoute)-6)) in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
			and CompCode=@CmCode and (BankDate is Null or BankDate > @RptDate)
	 		) k 
		) b
	
	----Union All

	----Select '0', EstDate, Case Sign(EstAmt) When -1 then 'EstRcpt' When 1 then 'EstIssue' End as PayType, Sign(EstAmt)*EstAmt as EstAmt, Particulars 
	----from FAS_FundEstimation Where  BankCode=@BankCode and  Compcode=@CmCode
	
	Order by Paytype, cDate

END
GO

/****** Object:  StoredProcedure [dbo].[Fas_Rpt_Gr_Monthwise]    Script Date: 17/06/2026 11:30:10 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[Fas_Rpt_Gr_Monthwise] (@UserKey Varchar(36), @Start datetime, @End datetime,  @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

Begin

	Set NoCount On	
	
	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Declare @OPBalDr as money
	Declare @OPBalCr as money

	Select @OPBalCr=OpBalance From FAS_LedgerMaster 
	Where LrRoute in (Select SelectStr From Com_SelectList 
				Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID
			   ) 
		and CompCode=@CmCode

	Select @OPBalDr=@OPBalCr

	If (@OPBalCr <= 0) 
		Select @OPBalCr=0 
	 Else 
		Select @OPBalDr=0 
	
	Select Mncode, LrCode, DMonth as [Ac Month], 
		Case When r.Debit > 0 then Convert(varchar, r.Debit) Else '' End as Debit, 
		Case When r.Credit > 0 Then Convert(varchar, r.Credit) Else '' End as Credit, 
		r.Closing_Balance
	from 
		 (Select LrCode, j.MnCode, Datename(month, convert(datetime, Convert(varchar, j.MnCode)+'01', 112 )) as DMonth,  j.Debit,  j.Credit,
				(Case	When sign(j.CB) = -1 then convert(varchar, -CB)+' Cr' 
					When sign(j.CB) = 1 then Convert(varchar, CB)+' Dr' 
					When sign(j.CB) = 0 then ' ' 
				 end
				) as Closing_Balance
		from
			(	Select LrCode, h.Mncode,  sum(h.dramt) as Debit, sum(h.cramt) as Credit,  
						(Select Sum(m.DrAmt-m.CrAmt)+(@OPBalCr+@OPBalDr) from FAS_Voucher_Vw m 
							Where LrCode in (Select SelectStr From Com_SelectList 
								Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID) 
								and m.compcode =@CmCode and h.MnCode >= Convert(int, Convert(varchar(6), m.DocDate, 112))
							) as CB
				From 
					(Select LrCode, Convert(int, Convert(varchar(6), DocDate, 112)) MnCode, DocDate, DrAmt, CrAmt 
						From FAS_Voucher_Vw c 
						Where LrCode in (Select SelectStr From Com_SelectList 
						Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID) 
						and CompCode =@CmCode
					) h
				group by LrCode, Mncode
			) j
		)r
	
	Order by MnCode

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_GST_Purchase_Input]    Script Date: 17/06/2026 11:30:10 ******/
SET ANSI_NULLS ON
