GO

CREATE PROCEDURE [dbo].[FAS_Rpt_GST_Purchase_Input](@ReportOption int, @StartDate datetime, @EndDate datetime, 
@AsonDate datetime, @RptDate datetime, @CompCode Varchar(12))                                                                            
AS                                                                            
BEGIN
	SET NOCOUNT ON;                                  
                                        
  iF @ReportOption = 1                              
   /* 1. Register Interstate */                                        
  Begin                                 
   Select Convert(Varchar(10), Count(distinct GSTRegNo)) GSTRegNo, '' As VoucherType, '' As LedgerName, 
			Convert(Varchar(10), Count(distinct IsNull(RefNo, ''))) As InvoiceNo, '' As InvoiceDate, Sum(InvoiceValue) As InvoiceValue, 
			'' As PlaceOfSupply, '' As ReverseCharge, '' As TypeOfInvoice, '' As ECommerceGSTRegNo, '' As TaxRate, 
			Sum(TaxableValue) As TaxableValue, Sum(CGSTTaxAmount) As CGSTTaxAmount,  Sum(SGSTTaxAmount) As SGSTTaxAmount, 
			Sum(IGSTTaxAmount) As IGSTTaxAmount, Sum(((TaxableValue/100)*TaxRate)) As TaxValue, Sum(CESSAmount) As CESSAmount, 
			1 As Seq                                     
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where (IsUnRegisterDealer=0 and GSTRegNo <> '') and (VrRoute Like '0B%'  OR VrRoute Like '06%')     and TaxName='InterState'                               
   --Order By InvoiceDate, InvoiceNo                                       
                                      
   UNION ALL                               
                                    
   Select GSTRegNo, VoucherType, LedgerName, IsNull(RefNo, '') As InvoiceNo, IsNull(RefDAte, '') As InvoiceDate, 
			InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, TaxRate, TaxableValue,                                   
			CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, ((TaxableValue/100)*TaxRate) As TaxValue, CESSAmount, 
			2 As Seq                                  
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where (IsUnRegisterDealer=0 and GSTRegNo <> '') and (VrRoute Like '0B%'  OR VrRoute Like '06%')   and TaxName='InterState'                                    
   Order By Seq, InvoiceDate, InvoiceNo                                        
  End                                     
                                      
  If @ReportOption = 2                                    
    /* 2. Register Intrastate */                           
  Begin
   Select Convert(Varchar(10), Count(distinct GSTRegNo)) GSTRegNo, '' As VoucherType, '' As LedgerName, 
			Convert(Varchar(10), Count(distinct IsNull(RefNo, ''))) As InvoiceNo, '' As InvoiceDate, Sum(InvoiceValue) As InvoiceValue,                             
			'' As PlaceOfSupply, '' As ReverseCharge, '' As TypeOfInvoice, '' As ECommerceGSTRegNo, '' As TaxRate, 
			Sum(TaxableValue) As TaxableValue, Sum(CGSTTaxAmount) As CGSTTaxAmount,                                  
			Sum(SGSTTaxAmount) As SGSTTaxAmount, Sum(IGSTTaxAmount) As IGSTTaxAmount, 
			Sum(((TaxableValue/100)*TaxRate)) As TaxValue, Sum(CESSAmount) As CESSAmount, 
			1 As Seq                                     
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where (IsUnRegisterDealer=0 and GSTRegNo <> '') and (VrRoute Like '0B%'  OR VrRoute Like '06%')  and TaxName='IntraState'                                   
                                     
   UNION ALL                           
                                      
   Select GSTRegNo, VoucherType, LedgerName, IsNull(RefNo, '') As InvoiceNo, IsNull(RefDAte, '') As InvoiceDate, InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, TaxRate, TaxableValue,      
    CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, ((TaxableValue/100)*TaxRate) As TaxValue, CESSAmount, 2 As Seq                                     
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                 
   Where (IsUnRegisterDealer=0 and GSTRegNo <> '') and (VrRoute Like '0B%'  OR VrRoute Like '06%')   and TaxName='IntraState'                                     
   Order By Seq, InvoiceDate, InvoiceNo                
  End                                    
                                      
  If @ReportOption = 3                                   
  /* 3. UnRegister Interstate */                         
  Begin
   Select distinct Convert(Varchar(10), Count(distinct LedgerName)) As LedgerName, '' As VoucherType, 
			Convert(Varchar(10), Count(distinct IsNull(RefNo, ''))) As InvoiceNo, '' As InvoiceDate, Sum(InvoiceValue) As InvoiceValue,                          
			'' As PlaceOfSupply, '' As ReverseCharge, '' As TypeOfInvoice, '' As ECommerceGSTRegNo, '' As TaxRate, 
			Sum(TaxableValue) As TaxableValue, Sum(CGSTTaxAmount) As CGSTTaxAmount, Sum(SGSTTaxAmount) As SGSTTaxAmount, 
			Sum(IGSTTaxAmount) As IGSTTaxAmount, Sum(((TaxableValue/100)*TaxRate)) As TaxValue, Sum(CESSAmount) As CESSAmount, 
			1 As Seq                                   
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where  (IsUnRegisterDealer=1 and GSTRegNo='')   and (VrRoute Like '0B%'  OR VrRoute Like '06%') and TaxName='InterState'                                     
   --Group By PlaceOfSupply, TaxRate, ECommerceGSTRegNo                                     
                                  
   UNION ALL                            
                                  
   Select distinct LedgerName, VoucherType, IsNull(RefNo, '') As InvoiceNo, IsNull(RefDate, '') As InvoiceDate, 
			InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, TaxRate, TaxableValue,                                   
			CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, ((TaxableValue/100)*TaxRate) As TaxValue, CESSAmount, 
			2 As Seq                                         
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where (IsUnRegisterDealer=1 and GSTRegNo='')  and (VrRoute Like '0B%'  OR VrRoute Like '06%')  and TaxName='InterState'                                     
   --Group By PlaceOfSupply, TaxRate, ECommerceGSTRegNo                                 
   Order By Seq                                       
  End                                      
                                    
  If @ReportOption = 4                                      
  /* 4. UnRegister Intrastate */                              
  Begin
   Select distinct Convert(Varchar(10), Count(distinct LedgerName)) As LedgerName, '' As VoucherType, 
			Convert(Varchar(10), Count(distinct IsNull(RefNo, ''))) As InvoiceNo, '' As InvoiceDate, Sum(InvoiceValue) As InvoiceValue,                              
			'' As PlaceOfSupply, '' As ReverseCharge, '' As TypeOfInvoice, '' As ECommerceGSTRegNo, '' As TaxRate, 
			Sum(TaxableValue) As TaxableValue, Sum(CGSTTaxAmount) As CGSTTaxAmount,                                  
			Sum(SGSTTaxAmount) As SGSTTaxAmount, Sum(IGSTTaxAmount) As IGSTTaxAmount, 
			Sum(((TaxableValue/100)*TaxRate)) As TaxValue, Sum(CESSAmount) As CESSAmount, 1 As Seq                                   
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where  (IsUnRegisterDealer=1 and GSTRegNo='')  and (VrRoute Like '0B%'  OR VrRoute Like '06%') and TaxName='IntraState'                                     
   --Group By PlaceOfSupply, TaxRate, ECommerceGSTRegNo                                   
                                  
   UNION ALL                             
                                  
   Select distinct LedgerName, VoucherType, IsNull(RefNo, '') As InvoiceNo, IsNull(RefDate, '') As InvoiceDate, 
			InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, TaxRate, TaxableValue,                                   
			CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, ((TaxableValue/100)*TaxRate) As TaxValue, CESSAmount, 
			2 As Seq                                        
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where  (IsUnRegisterDealer=1 and GSTRegNo='') and (VrRoute Like '0B%'  OR VrRoute Like '06%') and TaxName='IntraState'                                     
   --Group By PlaceOfSupply, TaxRate, ECommerceGSTRegNo                                      
   Order By Seq                                  
  End                                                                                                           
 If @ReportOption = 5                                     
  /* 5. Credit Note Regsiter / UnRegister - All (Inter / Intra) */                                      
  Begin
   Select Convert(Varchar(10), Count(distinct GSTRegNo)) GSTRegNo,  '' As VoucherType, '' As LedgerName, Convert(Varchar(10), Count(distinct IsNull(RefNo, ''))) As InvoiceNo, '' As InvoiceDate,                                   
    Count(distinct DocNo) As DocNo, '' As DocDate, '' As DocumentType, '' As ReasonForIssueDocument, '' As PlaceOfSupply, Sum(InvoiceValue) As VoucherValue, '' As TaxRate,                                   
    Sum(TaxableValue) As TaxableValue, Sum(CGSTTaxAmount) As CGSTTaxAmount, Sum(SGSTTaxAmount) As SGSTTaxAmount, Sum(IGSTTaxAmount) As IGSTTaxAmount,                                   
    Sum(((TaxableValue/100)*TaxRate)) As TaxValue, Sum(CESSAmount) As CESSAmount,'' As PreGST, 1 As Seq                                        
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where VrRoute Like '02%'                                   
                                    
   UNION ALL                           
                                         
   Select GSTRegNo,  
			Case When (InvoiceNo Is Null and InvoiceDate Is Null) Then VoucherType Else 'SYSTEM GENERATED - ' + VoucherType End As VoucherType, 
			LedgerName, IsNull(RefNo, '') As InvoiceNo, IsNull(RefDate, '') As InvoiceDate, DocNo, DocDate,                   
			Case When VrRoute='02' then 'C' When VrRoute='03'  Then 'D' Else 'R' End As DocumentType,                                       
			'' As ReasonForIssueDocument, PlaceOfSupply, InvoiceValue As VoucherValue, TaxRate, TaxableValue, 
			CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, ((TaxableValue/100)*TaxRate) As TaxValue, CESSAmount, 'N' As PreGST, 
			2 As Seq                                        
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where VrRoute Like '02%'                                   
   Order By Seq                                    
  End
                                      
 If @ReportOption = 6                           
  /* 6. Debit Note Regsiter / UnRegister - All (Inter / Intra)  */                                     
  Begin
   Select Convert(Varchar(10), Count(distinct GSTRegNo)) GSTRegNo,  '' As VoucherType, '' As LedgerName, 
			Convert(Varchar(10), Count(distinct IsNull(RefNo, ''))) As InvoiceNo, '' As InvoiceDate,                                   
			Count(distinct DocNo) As DocNo, '' As DocDate, '' As DocumentType, '' As ReasonForIssueDocument, 
			'' As PlaceOfSupply, Sum(InvoiceValue) As VoucherValue, '' As TaxRate,                                   
			Sum(TaxableValue) As TaxableValue, Sum(CGSTTaxAmount) As CGSTTaxAmount, 
			Sum(SGSTTaxAmount) As SGSTTaxAmount, Sum(IGSTTaxAmount) As IGSTTaxAmount,                                   
			Sum(((TaxableValue/100)*TaxRate)) As TaxValue, Sum(CESSAmount) As CESSAmount,'' As PreGST, 
			1 As Seq                                       
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where VrRoute Like '03%'                                   
                                    
   UNION ALL                             
                                     
   Select GSTRegNo, 
			Case When (RefNo Is Null and RefDate Is Null) Then VoucherType Else 'SYSTEM GENERATED - ' + VoucherType End As VoucherType,		
			LedgerName, IsNull(RefNo, '') As InvoiceNo, IsNull(RefDate, '') As InvoiceDate,  DocNo, DocDate, 
			Case When VrRoute='02' then 'C' When VrRoute='03'    Then 'D' Else 'R' End As DocumentType,                                       
			'' As ReasonForIssueDocument, PlaceOfSupply, InvoiceValue As VoucherValue, TaxRate, TaxableValue, 
			CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, ((TaxableValue/100)*TaxRate) As TaxValue, CESSAmount, 'N' As PreGST, 
			2 As Seq
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where VrRoute Like '03%'                                     
   --Order by GSTRegNo                                    
   Order By Seq                                  
  End                                  
                                    
 If @ReportOption = 7                         
 /* 7. Register, UnRegister Dealer Without Tax */                                                        
 /* Yet to be completed */                         
  Begin
   Select Convert(Varchar(10), Count(distinct GSTRegNo)) GSTRegNo, '' As VoucherType, '' As LedgerName, 
			Convert(Varchar(10), Count(distinct IsNull(RefNo, ''))) As InvoiceNo, '' As InvoiceDate, Sum(InvoiceValue) As InvoiceValue,                            
			'' As PlaceOfSupply, '' As ReverseCharge, '' As TypeOfInvoice, '' As ECommerceGSTRegNo, '' As TaxRate, 
			Sum(CGSTTaxAmount) As CGSTTaxAmount, Sum(TaxableValue) As TaxableValue,                                 
			Sum(SGSTTaxAmount) As SGSTTaxAmount, Sum(IGSTTaxAmount) As IGSTTaxAmount,
			Sum(((TaxableValue/100)*TaxRate)) As TaxValue, Sum(CESSAmount) As CESSAmount, 
			1 As Seq                                     
		 From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where  (VrRoute Like '06%' or VrRoute Like '09%') and TaxRate Is Null and TaxableValue is Null                                   
                                     
   UNION ALL                                
                                      
   Select GSTRegNo, VoucherType, LedgerName, IsNull(RefNo, '') As InvoiceNo, IsNull(RefDate, '') As InvoiceDate,  
			InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, TaxRate, TaxableValue,                                   
			CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, ((TaxableValue/100)*TaxRate) As TaxValue, CESSAmount, 
			2 As Seq                                     
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where  (VrRoute Like '06%' or VrRoute Like '09%') and TaxRate Is Null and TaxableValue is Null                                    
   Order By Seq, InvoiceDate, InvoiceNo                                 
  End                                
                          
 If @ReportOption = 8                                    
  /* 10. HSN summary */                                
  /* HSN wise summary of goods /services Received during the tax period */                    
	Begin
		Select '' As LedgerName, Convert(Varchar(10), Count(distinct HSNNo)) As HSNNo, '' As ItemCode, 
			'' As ItemDesc, '' As UOMDesc, '' As UOMDecimal, Sum(InvoiceQty) As InvoiceQty, Sum(GoodsValue) As GoodsValue, 
			Sum(TaxableValue) As TaxableValue, Sum(IGSTTaxAmount) As IGSTTaxAmount, Sum(CGSTTaxAmount) As CGSTTaxAmount, 
			Sum(SGSTTaxAmount) As SGSTTaxAmount, Sum(CESSAmount) As CESSAmount, 1 As Seq               
		From dbo.[fn_FAS_Rpt_GST_Purchase_HSNSummary] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
		Where VrRoute Like '0B%' and (IsUnRegisterDealer=0 and GSTRegNo <> '') and ItemCode is not Null                
           
		UNION ALL             
              
		Select LedgerName, HSNNo, ItemCode, ItemDesc, UOMDesc, UOMDecimal, Sum(InvoiceQty) As InvoiceQty, 
			Sum(GoodsValue) As GoodsValue, Sum(TaxableValue) As TaxableValue, Sum(IGSTTaxAmount) As IGSTTaxAmount, 
			Sum(CGSTTaxAmount) As CGSTTaxAmount, Sum(SGSTTaxAmount) As SGSTTaxAmount,	Sum(CESSAmount) As CESSAmount, 
			2 As Seq              
		From dbo.[fn_FAS_Rpt_GST_Purchase_HSNSummary] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
		Where VrRoute Like '0B%' and (IsUnRegisterDealer=0 and GSTRegNo <> '') and ItemCode is not Null             
		Group by LedgerName, HSNNo, ItemCode, ItemDesc, UOMDesc, UOMDecimal                
		Order By Seq, HSNNo, ItemCode            
	 End               
          
 If @ReportOption = 9                                      
  /* 9. GSTNo not available list */                              
  Begin                                     
   Select distinct Convert(Varchar(10), Count(distinct LedgerName)) As LedgerName, '' As VoucherType, 
			Convert(Varchar(10), Count(distinct IsNull(RefNo, ''))) As InvoiceNo, '' As InvoiceDate,                                
			Sum(InvoiceValue) As InvoiceValue, '' As PlaceOfSupply, '' As ReverseCharge, '' As TypeOfInvoice, 
			'' As ECommerceGSTRegNo, '' As TaxRate, Sum(TaxableValue) As TaxableValue, Sum(CGSTTaxAmount) As CGSTTaxAmount,                                  
			Sum(SGSTTaxAmount) As SGSTTaxAmount, Sum(IGSTTaxAmount) As IGSTTaxAmount, 
			Sum(((TaxableValue/100)*TaxRate)) As TaxValue, Sum(CESSAmount) As CESSAmount, 1 As Seq                                   
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where  GSTRegNo=''  and (VrRoute Like '0B%'  OR VrRoute Like '06%') and LedgerName <> ''                                
   --Group By PlaceOfSupply, TaxRate, ECommerceGSTRegNo                                   
                                  
   UNION ALL
                                  
   Select distinct LedgerName, VoucherType, IsNull(RefNo, '') As InvoiceNo, IsNull(RefDate, '') As InvoiceDate, InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, TaxRate, TaxableValue,                                   
   CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, ((TaxableValue/100)*TaxRate) As TaxValue, CESSAmount, 2 As Seq                                        
   From dbo.[fn_FAS_Rpt_GST_Purchase] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                                      
   Where GSTRegNo='' and (VrRoute Like '0B%'  OR VrRoute Like '06%') and LedgerName <> ''                                
   --Group By PlaceOfSupply, TaxRate, ECommerceGSTRegNo                                      
   Order By Seq                                  
  End                                            
END  
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_GST_Sales_Output]    Script Date: 17/06/2026 11:30:10 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Procedure [dbo].[FAS_Rpt_GST_Sales_Output] (@ReportOption int, @StartDate datetime, @EndDate datetime, @AsonDate datetime, @RptDate datetime, @CompCode Varchar(12))                          
                          
AS                          
                          
BEGIN                          
 
                            
	 IF @ReportOption = 1                                   
                            
		/* 1. B2b Supply */                          
		/*  "Details of invoices of Taxable supplies made to other registered taxpayers"  */                              
		-- Seq 1 - Summary, 2 - Detail                 
                       
		BEGIN 
             
			Select Convert(Varchar(10), Count(distinct GSTRegNo)) GSTRegNo, Count(distinct Lrcode) as LrCode,  '' as LedgerName, Count(distinct InvoiceNo) as InvoiceNo, '' as InvoiceDate,                         
				Sum(InvoiceValue) as InvoiceValue, '' as PlaceOfSupply, '' as ReverseCharge, '' as TypeOfInvoice, '' as ECommerceGSTRegNo, '' as TaxRate, Sum(TaxableValue) as TaxableValue,                   
				Sum(CGSTTaxAmount) as CGSTTaxAmount, Sum(SGSTTaxAmount) as SGSTTaxAmount, Sum(IGSTTaxAmount) as IGSTTaxAmount, Sum(CESSAmount) as CESSAmount, 1 as Seq          
			From
			(   
				Select distinct GSTRegNo, Lrcode, LedgerName, InvoiceNo, InvoiceDate, InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, TaxRate, TaxableValue,                     
					CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CESSAmount                     
				From dbo.[fn_FAS_Rpt_GST_Sales] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                          
				Where VrRoute Like '0K%' and GSTRegNo <> '' 
			)a                                        
                         
			Union All                          
                         
			Select distinct GSTRegNo, Lrcode, LedgerName, InvoiceNo, InvoiceDate, InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice, ECommerceGSTRegNo, TaxRate, TaxableValue,                     
				CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CESSAmount, 2 as Seq                          
			From dbo.[fn_FAS_Rpt_GST_Sales] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                          
			Where VrRoute Like '0K%' and GSTRegNo <> ''                            
			Order By Seq, InvoiceDate, InvoiceNo  
	                        
		END                          
                          
	IF @ReportOption = 2                    
 
		/* 2. B2Cl Supply - Interstate, Registered and Invoice value grater than 250000 */                     
		/* "Invoices for Taxable outward supplies to consumers where     a)The place of supply is outside the state where the supplier is registered and     b)The total invoice value is more that Rs 2,50,000"  */                                
		/* Customer Unregister, Other State with More than 250000 */                          
                      
		-- Seq 1 - Summary, 2 - Detail                    
                
		BEGIN                            
			Select distinct '' as LedgerName, Count(distinct InvoiceNo) as InvoiceNo,  '' as InvoiceDate, Sum(InvoiceValue) as InvoiceValue, '' as PlaceOfSupply, '' as TaxRate,  Sum(TaxableValue) as TaxableValue,                       
				Sum(CGSTTaxAmount) as CGSTTaxAmount, Sum(SGSTTaxAmount) as SGSTTaxAmount, Sum(IGSTTaxAmount) as IGSTTaxAmount, Sum(CESSAmount) as CESSAmount, '' as ECommerceGSTRegNo,  1 as Seq                          
			From dbo.[fn_FAS_Rpt_GST_Sales] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                          
			Where VrRoute Like '0K%' and GSTRegNo=''  and (TaxName='InterState' and InvoiceValue > 250000)                          
			--Order By InvoiceDate, InvoiceNo                       
                      
			Union All                          
                         
			Select distinct LedgerName, InvoiceNo, InvoiceDate, InvoiceValue, PlaceOfSupply, TaxRate, TaxableValue, CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CESSAmount, ECommerceGSTRegNo, 2 as Seq                            
			From dbo.[fn_FAS_Rpt_GST_Sales] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                     
			Where VrRoute Like '0K%' and GSTRegNo=''  and (TaxName='InterState' and InvoiceValue > 250000)                          
			Order by Seq                      
		END                 
                          
	IF @ReportOption = 3                          
      
	   /* 3. B2Cs Supply */                          
                          
		/*  "Supplies made to consumers and unregistered persons of the following nature      a) Intra-State: any value      b) Inter-State: Invoice value Rs 2.5 lakh or less"                             
		 Type (first col) - In the Type column, enter E if the supply is done through E-Commerce or else enter OE (other than E-commerce).                             
		*/                          
                          
		/* Customer Unregister, Intrastate sales with any value, and Other State with less than or equal 250000*/                          
                         
	   -- Seq 1 - Summary, 2 - Detail                   
                      
		BEGIN                 
			Select '' as Type, '' as PlaceOfSupply, '' as TaxRate, Sum(TaxableValue) as TaxableValue, Sum(CGSTTaxAmount) as CGSTTaxAmount, Sum(SGSTTaxAmount) as SGSTTaxAmount, Sum(IGSTTaxAmount) as IGSTTaxAmount,                     
				Sum(CESSAmount) as CESSAmount, '' as ECommerceGSTRegNo, 1 as Seq                            
			From dbo.[fn_FAS_Rpt_GST_Sales] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                          
			Where  VrRoute Like '0K%' and GSTRegNo='' and ((TaxName='InterState' and InvoiceValue<=250000) or  (TaxName='IntraState'))                           
			--Group By PlaceOfSupply, TaxRate, ECommerceGSTRegNo                        
                         
			Union All                       
                          
			Select 'OE' as Type, PlaceOfSupply, TaxRate, Sum(TaxableValue) as TaxableValue, Sum(CGSTTaxAmount) as CGSTTaxAmount, Sum(SGSTTaxAmount) as SGSTTaxAmount, Sum(IGSTTaxAmount) as IGSTTaxAmount,                     
				Sum(CESSAmount) as CESSAmount, ECommerceGSTRegNo, 2 as Seq                           
			From dbo.[fn_FAS_Rpt_GST_Sales] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                          
			Where  VrRoute Like '0K%' and GSTRegNo='' and ((TaxName='InterState' and InvoiceValue<=250000) or  (TaxName='IntraState'))                           
			Group By PlaceOfSupply, TaxRate, ECommerceGSTRegNo                      
		END                          
                          
	IF @ReportOption = 4                          
                            
		/* 4. cdnr */                          
		/* Credit/ Debit Notes/Refund vouchers issued to the registered taxpayers during the tax period.                           
		Debit or credit note issued against invoice will be reported here against original invoice,                           
		hence fill the details of original invoice also which was furnished in B2B,B2CL section of earlier/current period tax period.                                 
		*/                         
                      
		-- Seq 1 - Summary, 2 - Detail                  
                     
		BEGIN                     
			Select distinct '' as LedgerName, Convert(Varchar(10), Count(distinct GSTRegNo)) GSTRegNo, Count(distinct InvoiceNo) as InvoiceNo, '' as InvoiceDate,'' as VoucherNo, '' as VoucherDate, '' as DocumentType, '' as ReasonForIssueDocument,
				'' as PlaceOfSupply, Sum(InvoiceValue) as VoucherValue, '' as TaxRate, Sum(TaxableValue) as TaxableValue, Sum(CGSTTaxAmount) as CGSTTaxAmount, Sum(SGSTTaxAmount) as SGSTTaxAmount, Sum(IGSTTaxAmount) as IGSTTaxAmount, Sum(CESSAmount) as CESSAmount,
				'N' as PreGST, 1 as Seq                          
			From dbo.[fn_FAS_Rpt_GST_Sales] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                          
			Where GSTRegNo <> '' and (VrRoute Like '02%' OR VrRoute Like '03%') and (TaxName='IntraState'  OR (TaxName='InterState' and InvoiceValue > 250000))                       
                         
			Union All     
                      
			Select distinct LedgerName, GSTRegNo, InvoiceNo, InvoiceDate, DocNo  as VoucherNo, DocDate  as VoucherDate, Case When VrRoute='02' then 'C' When VrRoute='03' Then 'D' Else 'R' End as DocumentType,                             
				'' as ReasonForIssueDocument, PlaceOfSupply, InvoiceValue as VoucherValue, TaxRate, TaxableValue, CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CESSAmount, 'N' as PreGST, 2 as Seq                            
			From dbo.[fn_FAS_Rpt_GST_Sales] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                          
			Where GSTRegNo <> '' and (VrRoute Like '02%' OR VrRoute Like '03%') and (TaxName='IntraState'  OR (TaxName='InterState' and InvoiceValue > 250000))             
		END                          
                          
	IF @ReportOption = 5                          
                            
		/* 5. cdnur */                          
		/* Credit/ Debit Notes/Refund vouchers issued to the unregistered persons against interstate invoice value is  more than Rs 2.5 lakh */                             
                         
		-- Seq 1 - Summary, 2 - Detail                      
		BEGIN                   
			Select distinct '' as URType, '' as LedgerName, ''  as VoucherNo, ''  as VoucherDate, '' as DocumentType, Count(distinct InvoiceNo) as InvoiceNo, '' as InvoiceDate, '' as ReasonForIssueDocument,                            
			'' as PlaceOfSupply, Sum(InvoiceValue) as VoucherValue, '' as TaxRate, Sum(TaxableValue) as TaxableValue, Sum(CGSTTaxAmount) as CGSTTaxAmount, Sum(SGSTTaxAmount) as SGSTTaxAmount, Sum(IGSTTaxAmount) as IGSTTaxAmount,                   
			Sum(CESSAmount) as CESSAmount, 'N' as PreGST, 1 as Seq                           
			From dbo.[fn_FAS_Rpt_GST_Sales] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                          
			Where GSTRegNo='' and (VrRoute Like '02%' OR VrRoute Like '03%') and (TaxName='InterState' and InvoiceValue > 250000)                         
                         
			Union All                          
                          
			Select distinct 'B2CL' as URType,LedgerName, DocNo as VoucherNo, DocDate as VoucherDate, Case When VrRoute='02' then 'C' When VrRoute='03' Then 'D' Else 'R' End as DocumentType, InvoiceNo, InvoiceDate,                              
			'' as ReasonForIssueDocument, PlaceOfSupply, InvoiceValue as VoucherValue, TaxRate, TaxableValue, CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CESSAmount, 'N' as PreGST, 2 as Seq                            
			From dbo.[fn_FAS_Rpt_GST_Sales] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                          
			Where GSTRegNo='' and (VrRoute Like '02%' OR VrRoute Like '03%') and (TaxName='InterState' and InvoiceValue > 250000)                        
		END                          
                          
	IF @ReportOption = 6                          
                            
		/* 6. exp */                          
		/* Exports supplies including supplies to SEZ/SEZ Developer or deemed exports */                           
		-- Interstate - IGST will come informed by PMAC - Neelakandan                              
		BEGIN                        
			Select distinct '' as ExportType, Count(distinct InvoiceNo) as InvoiceNo, '' as InvoiceDate, Sum(InvoiceValue) as InvoiceValue, '' as PortCode, '' as ShippingBillNo,                             
			'' as ShippingBillDate, '' as TaxRate, Sum(TaxableValue) as TaxableValue,Sum(CGSTTaxAmount) as CGSTTaxAmount, Sum(SGSTTaxAmount) as SGSTTaxAmount, Sum(IGSTTaxAmount) as IGSTTaxAmount,  1 as Seq                         
			From dbo.[fn_FAS_Rpt_GST_Sales] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                          
			Where VrRoute Like '0K%' and IsExportSales='1' and GSTRegNo=''                         
                          
			Union All                          
                          
			Select distinct '' as ExportType, InvoiceNo, InvoiceDate, InvoiceValue, '' as PortCode, '' as ShippingBillNo, '' as ShippingBillDate, TaxRate, TaxableValue, CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, 2 as Seq                            
			From dbo.[fn_FAS_Rpt_GST_Sales] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                          
			Where VrRoute Like '0K%' and IsExportSales='1' and GSTRegNo=''                    
		END                            
                
	IF @ReportOption = 10                          
                         
		/* 10. HSN summary */                          
                          
		/* HSN wise summary of goods /services supplied during the tax period */   
  
		BEGIN      
			Select Convert(Varchar(10), Count(distinct HSNNo)) as HSNNo, '' as ItemCode, '' as ItemDesc, '' as UOMDesc, '' as UOMDecimal, 
				Sum(InvoiceQty) as InvoiceQty, Sum(GoodsValue) as GoodsValue, Sum(TaxableValue) as TaxableValue, 		   
				Sum(IGSTTaxAmount) as IGSTTaxAmount, Sum(CGSTTaxAmount) as CGSTTaxAmount, Sum(SGSTTaxAmount) as SGSTTaxAmount,   
				Sum(CESSAmount) as CESSAmount, 1 as Seq     
			From dbo.[fn_FAS_Rpt_GST_Sales_HSNSummary] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                            
			Where VrRoute Like '0K%' and GSTRegNo<>''       
	
			Union All    
    
			Select HSNNo, ItemCode, ItemDesc, UOMDesc, UOMDecimal, Sum(InvoiceQty) as InvoiceQty, Sum(GoodsValue) as GoodsValue, Sum(TaxableValue) as TaxableValue, 		   
				Sum(IGSTTaxAmount) as IGSTTaxAmount, Sum(CGSTTaxAmount) as CGSTTaxAmount, Sum(SGSTTaxAmount) as SGSTTaxAmount,   
				Sum(CESSAmount) as CESSAmount, 2 as Seq    
			From dbo.[fn_FAS_Rpt_GST_Sales_HSNSummary] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode)                            
			Where VrRoute Like '0K%' and GSTRegNo<>''       
			group by HSNNo, ItemCode, ItemDesc, UOMDesc, UOMDecimal      
			Order By Seq, HSNNo, ItemCode  
	END      
                          
END 

GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_GST_SalesRegister_GST]    Script Date: 17/06/2026 11:30:10 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_GST_SalesRegister_GST](@StartDate datetime, @EndDate datetime, @AsonDate datetime, @RptDate datetime, @CompCode Varchar(12))    
AS
BEGIN
	SET NOCOUNT ON;

	Declare @BranchID varchar(3), @CompID varchar(3);  

	Select @CompID=Left(@CompCode, 2);
	Select @BranchID=Substring(@CompCode, 3, 2);  

	;with SalesData_CTE
	AS
	(
			Select distinct GSTRegNo, Lrcode, LedgerName, InvoiceNo, InvoiceDate, InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice,   
				ECommerceGSTRegNo, TaxRate, TaxableValue, CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CESSAmount                            
			From dbo.[fn_FAS_Rpt_GST_Sales_V1] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode) a                       
			Where VrRoute Like '0K%' --and GSTRegNo <> ''  
	)
  
	Select Convert(Varchar(10), Count(distinct GSTRegNo)) GSTRegNo, '' as  HSNNo,  Count(distinct InvoiceNo) as InvoiceNo, '' as InvoiceDate,                           
		Sum(InvoiceValue) as InvoiceValue, '' as PlaceOfSupply, '' as ReverseCharge, '' as TypeOfInvoice, '' as ECommerceGSTRegNo, '' as TaxRate, Sum(TaxableValue) as TaxableValue,                     
		Sum(CESSAmount) as CESSAmount, Sum(CGSTTaxAmount) as CGSTTaxAmount, Sum(SGSTTaxAmount) as SGSTTaxAmount, Sum(IGSTTaxAmount) as IGSTTaxAmount, 0 as Qty, 1 as Seq  --'' as LedgerName,    
		, '' Type, '' as OrginalInvType,0 as OrginalInvNo, NULL as OrginalInvDate  
	From SalesData_CTE a
                    
	Union All                            
      
	Select a.GSTRegNo, c.HSNNo, a.InvoiceNo, a.InvoiceDate, a.InvoiceValue, a.PlaceOfSupply, a.ReverseCharge, a.TypeOfInvoice, a.ECommerceGSTRegNo,   
		a.TaxRate, a.TaxableValue, a.CESSAmount, a.CGSTTaxAmount, a.SGSTTaxAmount, a.IGSTTaxAmount,  Sum(b.InvoiceQty) as InvoiceQty, 2 as Seq --a.LedgerName    
		,  b.[Type], Case When b.[Type]='Supplementary' Then b.OrderType ELSE '' End as OrginalInvType,   
		Case When b.[Type]='Supplementary' Then b.OrderNo ELSE '' End as OrginalInvNo,  
		Case When b.[Type]='Supplementary' Then b.OrderDate ELSE '' End as OrginalInvDate  
	From SalesData_CTE a  
	Left Outer Join SalesInvoice b  
		On a.InvoiceNo=b.InvoiceNo and a.InvoiceDate=b.InvoiceDate and b.InvoiceType='INV' and b.BranchID=@BranchID and b.CompID=@CompID    
	Left Outer Join   
	(  
		Select ItemCode, TariffNo, d.HSNNo  
		From INV_Material_Master c  
		Left Outer Join fn_BOM_HSNNo_Master('M',@AsonDate, @RptDate, @BranchID, @CompID)d  
		On c.HSNID=d.HSNID  
	)c  
		On b.Itemcode=c.ItemCode  
	Group by a.GSTRegNo, a.Lrcode, a.LedgerName, a.InvoiceNo, a.InvoiceDate, a.InvoiceValue, a.PlaceOfSupply, a.ReverseCharge, a.TypeOfInvoice, a.ECommerceGSTRegNo,   
		a.TaxRate, a.TaxableValue,  a.CGSTTaxAmount, a.SGSTTaxAmount, a.IGSTTaxAmount, a.CESSAmount, c.HSNNo, b.[Type], b.OrderType, b.OrderNo, b.OrderDate  
	Order By Seq, InvoiceDate, InvoiceNo    
End  
  
  
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_GST_SalesRegister_GST_tmp]    Script Date: 17/06/2026 11:30:11 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_GST_SalesRegister_GST_tmp](@StartDate datetime, @EndDate datetime, @AsonDate datetime, @RptDate datetime, @CompCode Varchar(12))    
AS
BEGIN
	SET NOCOUNT ON;

	Declare @BranchID varchar(3), @CompID varchar(3);  

	Select @CompID=Left(@CompCode, 2);
	Select @BranchID=Substring(@CompCode, 3, 2);  

	;with SalesData_CTE
	AS
	(
			Select distinct GSTRegNo, Lrcode, LedgerName, InvoiceNo, InvoiceDate, InvoiceValue, PlaceOfSupply, ReverseCharge, TypeOfInvoice,   
				ECommerceGSTRegNo, TaxRate, TaxableValue, CGSTTaxAmount, SGSTTaxAmount, IGSTTaxAmount, CESSAmount                            
			From dbo.[fn_FAS_Rpt_GST_Sales_tmp2] (@StartDate, @EndDate, @AsonDate, @RptDate, @CompCode) a                       
			Where VrRoute Like '0K%' --and GSTRegNo <> ''  
	)
  
	Select Convert(Varchar(10), Count(distinct GSTRegNo)) GSTRegNo, '' as  HSNNo,  Count(distinct InvoiceNo) as InvoiceNo, '' as InvoiceDate,                           
		Sum(InvoiceValue) as InvoiceValue, '' as PlaceOfSupply, '' as ReverseCharge, '' as TypeOfInvoice, '' as ECommerceGSTRegNo, '' as TaxRate, Sum(TaxableValue) as TaxableValue,                     
		Sum(CESSAmount) as CESSAmount, Sum(CGSTTaxAmount) as CGSTTaxAmount, Sum(SGSTTaxAmount) as SGSTTaxAmount, Sum(IGSTTaxAmount) as IGSTTaxAmount, 0 as Qty, 1 as Seq  --'' as LedgerName,    
		, '' Type, '' as OrginalInvType,0 as OrginalInvNo, NULL as OrginalInvDate  
	From SalesData_CTE a
                    
	Union All                            
      
	Select a.GSTRegNo, c.HSNNo, a.InvoiceNo, a.InvoiceDate, a.InvoiceValue, a.PlaceOfSupply, a.ReverseCharge, a.TypeOfInvoice, a.ECommerceGSTRegNo,   
		a.TaxRate, a.TaxableValue, a.CESSAmount, a.CGSTTaxAmount, a.SGSTTaxAmount, a.IGSTTaxAmount,  Sum(b.InvoiceQty) as InvoiceQty, 2 as Seq --a.LedgerName    
		,  b.[Type], Case When b.[Type]='Supplementary' Then b.OrderType ELSE '' End as OrginalInvType,   
		Case When b.[Type]='Supplementary' Then b.OrderNo ELSE '' End as OrginalInvNo,  
		Case When b.[Type]='Supplementary' Then b.OrderDate ELSE '' End as OrginalInvDate  
	From SalesData_CTE a  
	Left Outer Join SalesInvoice b  
		On a.InvoiceNo=b.InvoiceNo and a.InvoiceDate=b.InvoiceDate and b.InvoiceType='INV' and b.BranchID=@BranchID and b.CompID=@CompID    
	Left Outer Join   
	(  
		Select ItemCode, TariffNo, d.HSNNo  
		From INV_Material_Master c  
		Left Outer Join fn_BOM_HSNNo_Master('M',@AsonDate, @RptDate, @BranchID, @CompID)d  
		On c.HSNID=d.HSNID  
	)c  
		On b.Itemcode=c.ItemCode  
	Group by a.GSTRegNo, a.Lrcode, a.LedgerName, a.InvoiceNo, a.InvoiceDate, a.InvoiceValue, a.PlaceOfSupply, a.ReverseCharge, a.TypeOfInvoice, a.ECommerceGSTRegNo,   
		a.TaxRate, a.TaxableValue,  a.CGSTTaxAmount, a.SGSTTaxAmount, a.IGSTTaxAmount, a.CESSAmount, c.HSNNo, b.[Type], b.OrderType, b.OrderNo, b.OrderDate  
	Order By Seq, InvoiceDate, InvoiceNo    
End  
  
  
GO

