CREATE PROCEDURE [dbo].[FAS_Rpt_LedgerPrint_Gen_Narr](@UserKey Varchar(36), @FromDate datetime, @ToDate datetime, @CompCode Varchar(12))              
As              
BEGIN            
    SET NOCOUNT ON;

    Select b.LrCode, b.VrRoute, b.DocNo, b.DocDate, isNull(a.Narration, '') as Narration      
    From COM_SelectList s1          
    Inner Join FAS_VoucherTranSub b          
        On s1.UserKey=@UserKey and s1.SelectInt=b.LrCode          
    Inner Join FAS_VoucherTranMast a          
        On b.DocNo=a.DocNo and b.DocDate=a.DocDate and b.VrRoute=a.VrRoute and b.CompCode=a.CompCode
    Where (b.DocDate Between @FromDate and @ToDate) and b.CompCode=@CompCode          
          
    Union All          
              
    Select Distinct b.LrCode, b.VrRoute, b.DocNo, b.DocDate, isNull(a.EnNarration, '') as Narration         
    From COM_SelectList s2          
    Inner Join FAS_VoucherTranSub b          
        On s2.UserKey=@UserKey and s2.SelectInt=b.LrCode          
    Left Outer Join FAS_VoucherTranNarr a          
        On b.DocNo=a.DocNo and b.DocDate=a.DocDate and b.VrRoute=a.VrRoute and b.VTSNo=a.VTSNo and b.CompCode=a.CompCode  
    Where (b.DocDate Between @FromDate and @ToDate) and b.CompCode=@CompCode          
    Order by b.LrCode, b.VrRoute, b.DocDate, b.DocNo               
END
GO

