CREATE PROCEDURE [dbo].[FAS_Rpt_Lr_0] (@UserKey varchar(36), @Start as datetime, @End as datetime, @PrStart as datetime, @PrEnd as datetime, @CmCode as varchar(12))

 AS

Begin
	SET NOCOUNT ON
	
	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)

	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Select distinct c.DocDate, a.Voucher_Route, a.DocNo, a.FileRef, a.VTSNo, c.LrCode, a.LedgerName, a.VoucherName, 
			Convert(varchar, a.DrAmt) as DrAmt, Convert(varchar, a.CrAmt) as CrAmt, r.BankDate, a.Narration, a.LrCode as LedgerCode
	From FAS_VrDetails_Vw a
	Inner Join (	
			Select b.DocDate, b.DocNo, b.VrRoute, b.VTSNo, b.LrCode 
			From FAS_VoucherTranSub b
			Where b.LrCode in (Select SelectInt From Com_SelectList 
					Where UserKey = @UserKey and BranchId = @BranchId and CompId = @CompId)
			and b.DocDate Between @Start and @End and b.CompCode = @CmCode
		)c
	On a.DocNo = c.DocNo and a.DocDate=c.DocDate and a.Voucher_Route=c.VrRoute 
	Left Outer Join FAS_VoucherTranPay r 
	On a.DocNo = r.DocNo and a.DocDate=r.DocDate and a.Voucher_Route = r.VrRoute and a.CompCode = r.CompCode
	Where a.CompCode = @CmCode
	Order by c.LrCode, c.DocDate, a.Voucher_Route, a.DocNo, a.VTSNO

End
GO

