CREATE PROCEDURE [dbo].[FAS_Rpt_Lr_1] (@Userkey varchar(36), @Start datetime, @End datetime,  @PrStart datetime, @PrEnd datetime,  @CmCode varchar(12)) 

AS

Begin
	Set NOCOUNT ON	
	
	Declare @BranchID varchar(2)
	select @BranchId = SubString(@CmCode, 3, 2)

	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Select Voucher_Route,  Convert(Varchar(16),  m.DocDate, 105) as Date,  Particulars,  [Voucher Type],  [Voucher No.],  Debit,  Credit,  f.ChqNo , Narration
	from 


	( 	Select c.Voucher_Route,  c.DocDate, c.LedgerName as Particulars, c.VoucherName as [Voucher Type], 
			c.DocNo as [Voucher No.],  Case When e.DrAmt > 0 then Convert(Varchar, e.DrAmt) Else '' End as Debit, 
			Case When e.CrAmt > 0 then Convert(Varchar, e.CrAmt) Else '' End as Credit, Narration, CompCode
	
		from FAS_VrDetails_Vw c
		Inner Join

			(Select min(VTSNo) as MinVTSNo, a.DocNo, a.DocDate, a.VrRoute 
			from FAS_VoucherTranSub a 
			Inner Join
				(select DocNo, DocDate, VrRoute 
				from FAS_Voucher_Vw 
				where LrCode in (Select SelectInt From Com_SelectList Where UserKey = @Userkey and BranchID = @BranchID and CompID = @CompID ) 
				and DocDate between  @Start and @End and CompCode= @CmCode 
				) b
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute 
			where a.CompCode= @CmCode and a.LrCode <> (Select SelectInt From Com_SelectList Where UserKey = @Userkey and BranchID = @BranchID and CompID = @CompID ) 
			group by a.VrRoute, a.DocDate, a.DocNo 
			) d
		On c.DocNo=d.DocNo and c.DocDate=d.DocDate and c.Voucher_Route=d.VrRoute and c.VTSNo=d.MinVTSNo 	

	Left Outer Join
			(select DocNo, DocDate, Voucher_Route as VrRoute, DrAmt, CrAmt from FAS_VrDetails_Vw 
			where lrcode in (Select SelectInt From Com_SelectList Where UserKey = @Userkey and BranchID = @BranchID and CompID = @CompID ) 
			and DocDate between @Start and @End and CompCode= @CmCode 
			) e
	
		On  c.DocNo=e.DocNo  and c.DocDate=e.DocDate and c.Voucher_Route=e.VrRoute 
		Where  CompCode =  @CmCode
		 )m

		Left Outer Join FAS_VoucherTranPay f
		On m.[Voucher No.] = f.DocNo and m.DocDate=f.DocDate and m.Voucher_Route = f.VrRoute and m.CompCode = f.CompCode
		Where  m.CompCode =  @CmCode

	Order by  m.DocDate,  Voucher_Route,  [Voucher No.] 

End
GO

