 from   
  
  
 (  Select c.Voucher_Route,  c.DocDate, e.LrCode, c.LedgerName as Particulars, c.VoucherName as Voucher_Type,   
   c.DocNo as Voucher_No,  Case When e.DrAmt > 0 then Convert(Varchar, e.DrAmt) Else '' End as Debit,   
