    where LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)   
    and DocDate between  @Start and @End and CompCode= @CmCode   
    ) b  
   On a.DocNo=b.DocNo and a.VrRoute=b.VrRoute   
   where a.CompCode= @CmCode and a.LrCode <> b.LrCode  
   group by a.VrRoute, a.DocNo, a.LrCode   
   ) d  
  On c.DocNo=d.DocNo and c.Voucher_Route=d.VrRoute and c.VTSNo=d.MinVTSNo    
  
 Left Outer Join  
   (select LrCode, DocNo, Voucher_Route as VrRoute, DrAmt, CrAmt from FAS_VrDetails_Vw   
   where Lrcode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)   
     and DocDate between @Start and @End  
     and CompCode= @CmCode   
   ) e  
   
  On  c.DocNo=e.DocNo  and c.Voucher_Route=e.VrRoute   
