CREATE PROCEDURE [dbo].[FAS_Rpt_Lr_OpBal] (@UserKey varchar(36), @FinStart datetime, @Start datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12)) 

AS

BEGIN

	Set NOCOUNT ON	

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Select Case Sign(Amt) When -1 then '' Else Convert(varchar, Amt) End as Debit, Case Sign(Amt) When -1 then Convert(varchar, -Amt) Else '' End as Credit 
	from
		(Select Sum(Amt) as Amt 
		from
			(Select OpBalance as Amt from FAS_LedgerMaster 
				Where LedgerCode in (Select SelectInt From Com_SelectList 
					Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
				 and CompCode=@CmCode

			Union All

			Select Sum(DrAmt)-Sum(CrAmt) as Amt 
				from FAS_Voucher_Vw
				Where LrCode in (Select SelectInt From Com_SelectList 
					Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID) 
				 and DocDate between @FinStart and Convert(datetime, DateAdd(day, -1, @Start), 111) 
				and CompCode=@CmCode
			
			) X 
		)Y

END
GO

