CREATE PROCEDURE [dbo].[FAS_Rpt_Lr_OpBal_BRS] (@UserKey varchar(36), @FinStart datetime, @Start datetime,  @PrStart datetime, @PrEnd datetime, @CmCode char(4)) 

AS

Begin

	Set NOCOUNT ON	

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)
	
	Declare @ToDate datetime
	Select @ToDate=DateAdd(day, -1, @Start)
	
	Select Case Sign(Amt) When -1 then -Amt Else 0 End as Debit, Case Sign(Amt) When 1 then Amt Else 0 End as Credit 
	from (
		Select Sum(Amt) Amt
		from
			(Select a.CrAmt-a.DrAmt as Amt, Case when a.PayMode in ('', 'Cash') then a.DocDate else b.BankDate end as DocDate
			from FAS_Voucher_Vw a Left Outer Join FAS_VoucherTranPay b
			on a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
			Where a.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID) 
			and a.DocDate <=  @ToDate and a.CompCode=@CmCode
			) W
		where DocDate between @FinStart and @ToDate
		) X 

End
GO

