CREATE PROCEDURE [dbo].[FAS_Rpt_Lr_Sum] (@UserKey varchar(36), @isRealisedAmtOnly bit, @FinStart datetime, @Start datetime, @End datetime, @PrStart datetime, @PrEnd datetime,  @CmCode varchar(12)) 

AS

Begin
	Set NOCOUNT ON	

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)


	Select 'OPBal' as Type,  isNull(Case When Amt > 0 then Amt Else 0 End, 0) as Debit, isNull(Case When Amt < 0 then -Amt Else 0 End, 0) as Credit 
	from
		(Select Sum(Amt) as Amt 
		from
			(Select OpBalance as Amt from FAS_LedgerMaster where LedgerCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID) 
				and CompCode=@CmCode
			Union All
			Select Sum(Case When @isRealisedAmtOnly='1' and b.DocNo is Not Null and b.BankDate is Null Then 0 Else DrAmt-CrAmt End) as Amt 
				from FAS_VoucherTranSub a Left Outer Join FAS_VoucherTranPay b
				On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
				Where a.LrCode in (select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID)
				and a.DocDate between @FinStart and Convert(datetime, DateAdd(day, -1, @Start), 111) and a.CompCode=@CmCode
			) X 
		)Y

Union
	Select 'Current' as Type, isNull(Sum(DrAmt), 0) as Debit, isNull(Sum(CrAmt), 0) as Credit 
		from FAS_Voucher_Vw
		Where LrCode in (select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID)
			 and DocDate between @Start and @End and CompCode=@CmCode
	Order by 1

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_LrMonthwise_Sum]    Script Date: 17/06/2026 11:30:11 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_LrMonthwise_Sum] (@UserKey Varchar(36), @isRealisedAmtOnly bit, @Start datetime, @End datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12)) 

AS

Begin

	Set NoCount On

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Select  r.LrCode, (Select LedgerName From FAS_LedgerMaster Where LedgerCode = r.LrCode and CompCode = @CmCode) as LedgerName,
		 Mncode, DMonth as AcMonth, r.Debit, r.Credit, r.OpBalance, r.ClBalance
	from 
		 (Select j.LrCode, j.MnCode,  Datename(month, convert(datetime, Convert(varchar, j.MnCode)+'01', 112 )) as DMonth, 	IsNull(OB, 0) as OpBalance,	
				Case When isNull(j.DrAmt, 0) = 0 then ' ' else Convert(varchar, j.DrAmt)  end as Debit,
				Case When isNull(j.CrAmt, 0) = 0 then ' ' else Convert(varchar, j.CrAmt)  end as Credit,
				isNull(j.CB, 0)  as ClBalance
		from
			(Select h.LrCode, h.Mncode,  Sum(h.DrAmt) as DrAmt, Sum(h.CrAmt) as CrAmt,  
				 h.OpBalance as Ob,
				dbo.fn_FAS_LedgerOpBalance(h.LrCode, DateAdd(mm, 1, Convert(datetime, h.MnCode+'01', 112)), @isRealisedAmtOnly, @CmCode) as CB
					
			from 
				(Select h1.MnCode, h1.LrCode, Isnull(h2.DrAmt, 0)DrAmt,  Isnull(h2.CrAmt, 0) CrAmt, q.OpBalance
				from	(Select m.SelectInt as LrCode, n.MnCode 
					From
						(Select SelectInt, @CmCode as CompCode From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchId and CompId = @CompId) m
						Full Outer Join 
						(Select Convert(varchar(6), Monthdate, 112) MnCode, @CmCode as CompCode from dbo.fn_FAS_Months(@Start, @End)) n
						On m.CompCode=n.CompCode
					) h1
					Left Outer Join
					(Select LrCode, Convert(varchar(6), c.Docdate, 112) MnCode, 
						Sum(Case When @isRealisedAmtOnly='1' and c1.DocNo is Not Null and c1.BankDate is Null then 0 Else DrAmt End) as DrAmt, 
						Sum(Case When @isRealisedAmtOnly='1' and c1.DocNo is Not Null and c1.BankDate is Null then 0 Else CrAmt End) as CrAmt 
					from FAS_VoucherTranSub c Left Outer Join FAS_VoucherTranPay c1
					On c.DocNo=c1.DocNo and c.DocDate=c1.DocDate and c.DocDate=c1.DocDate and c.CompCode=c1.CompCode
					Where c.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchId and CompId =@CompId) 
						and (c.DocDate between @Start and @End) and c.CompCode =@CmCode
					Group by c.LrCode, Convert(varchar(6), c.Docdate, 112)
					) h2
					On h1.LrCode=h2.LrCode and h1.MnCode=h2.MnCode			

					Left Outer Join 
					(Select LedgerCode, OpBalance from dbo.fn_FAS_AllOpBalance(@Start, @isRealisedAmtOnly, '0',  @CmCode)
				 	Where LedgerCode in (Select SelectInt From Com_SelectList Where UserKey = @Userkey and BranchId = @BranchId and CompId = @CompID)				
					) q
					On q.LedgerCode = h2.LrCode

				) h
			Group by h.LrCode, MnCode,  h.OpBalance
			) j
		)r
	Order by LrCode, MnCode
End
GO

