CREATE PROCEDURE [dbo].[FAS_Rpt_OB_1] (@UserKey varchar(36), @LrRoute varchar(4), @RptDate Datetime, @Start datetime, @End datetime, @Status char(2),  @PrStart datetime, @PrEnd datetime, @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON
	--@Status 11-From, To Both Date given; 00 From & To may be any; 01 From may be any but To Date specified; 10 To Date may be any but From Date specified
	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)
	
	Declare @From datetime, @To datetime	
	
	Select @From=Case Left(@Status, 1) when '0' then (Select Min(Refdate) from Fas_BillDetails where CompCode=@CmCode) Else @Start End 
	Select @To=Case Right(@Status, 1) when '0' then (Select Max(Refdate) from Fas_BillDetails where CompCode=@CmCode) Else @End End


	Select y.LrCode, z.LrName, Sum(z.Amount) as Amount, 
	(Select isNull(Sum(x.Amount), 0) from Fas_BillDetails x where x.RefDate between @From and @To and x.Type='On Acct' and x.LrCode=y.LrCode and x.CompCode=@CmCode) as AdvAmt
	from fas_billdetails y
	Left Outer Join
		(Select a.LrCode, b.LedgerName LrName, a.RefNo, Sum(a.Amount) as Amount
		from fas_billdetails a
		Left Outer Join Fas_Ledgermaster b
			On a.LrCode=b.LedgerCode and a.CompCode=b.CompCode
		where a.Type<>'On Acct' and RefDate <=  @RptDate  and a.CompCode=@CmCode
			and LrCode in (Select selectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID)
	 	group by a.LrCode, b.LedgerName, a.RefNo ) z 
	On y.RefNo=z.RefNo and y.LrCode=z.LrCode
	where (y.RefDate between @From and @To) and z.Amount <> 0 and y.Type in ('Advance', 'New Ref') and y.CompCode=@CmCode
	group by y.LrCode, z.LrName


End
GO

