CREATE PROCEDURE [dbo].[FAS_Rpt_OB_1_BRS] (@UserKey varchar(36), @LrRoute varchar(4), @RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12)) 
-- Created On 27-11-2006
AS

Begin
	SET NOCOUNT ON

	Declare @BranchID varchar(2)
	Select @BranchID =Substring(@CmCode, 3, 2)

	Declare @CompID varchar(2)
	Select @CompID = Left(@Cmcode, 2)

	Select LrCode, LrName, BrsAmt, AdvAmt, OBAmt
	from (

		Select LrCode,  (Select LedgerName from FAS_LedgerMaster where LedgerCode=X.LrCode and CompCode=@CmCode) as LrName, isNull(Sum(BrsAmt), 0) as BrsAmt, isNull(Sum(AdvAmt), 0) as AdvAmt, isNull(Sum(ObAmt),0) as ObAmt
		from (
			Select Z.LrCode,  Case Z.Type When 'BrsBal' Then Sum(Amount) End as BrsAmt, Case Z.Type When 'OutBal' Then Sum(Amount) End as ObAmt, Case Z.Type When 'AdvAcct' Then Sum(Amount) End as AdvAmt
			from (	
				Select 'OutBal' as Type, LrCode,  Sum(Amount) as Amount 
				from 
					(Select LrCode, Amount
					from
						/*(Select y.DueDate, z.LrCode, z.Amount 
						from fas_billdetails y,
							(Select LrCode, RefNo, Sum(Amount) as Amount from fas_billdetails
							where Type <> 'On Acct' and RefDate <= @RptDate and LrCode in (Select LedgerCode from FAS_LedgerMaster where Left(Route, Len(@LrRoute))=@LrRoute and CompCode=@CmCode)
								and CompCode=@CmCode
							group by LrCode, RefNo 
							) z 
						where z.Amount <> 0  and y.Type in ('Advance', 'New Ref') and y.RefNo=z.RefNo and y.LrCode=z.LrCode and y.CompCode=@CmCode
						) c*/
	
						(Select z1.LrCode, Sum(z1.Amount) as Amount
						from fas_billdetails z1
						where z1.Type <> 'On Acct' and z1.RefDate <= @RptDate
							and z1.LrCode in (Select LedgerCode from FAS_LedgerMaster where Left(LrRoute, 4)=@LrRoute and CompCode=@CmCode
										and LedgerCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompID = @CompID)
									  )
							and z1.CompCode = @CmCode
						group by z1.LrCode, z1.RefNo, z1.CompCode
						) c
					) d
				group by LrCode 
		
				UNION All
		
				Select 'BrsBal' as Type, a.LrCode, Sum(a.Amount) as BrsAmount
				from FAS_BillDetails a join
					(Select DocNo, VrRoute, Lrcode from FAS_BankRecon_Vw 
					Where Lrcode in (Select LedgerCode from FAS_LedgerMaster Where Left(LrRoute, 4) in ('0201', '0B01') and CompCode=@CmCode
								and LedgerCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompID = @CompID)
							)
					and isLrCode='1' and (BankDate is Null or BankDate > @RptDate) and Compcode=@CmCode
					) b
				On a.DocNo=b.DocNo and a.VrRoute=b.VrRoute and a.CompCode=@CmCode
				Where a.LrCode in (Select LedgerCode from FAS_LedgerMaster Where Left(LrRoute, Len(@LrRoute))=@LrRoute and CompCode=@CmCode) and a.RefDate <= @RptDate
				Group by a.LrCode
	
				UNION All			

				Select 'AdvAcct' as Type, Lrcode, Amount 
				from (
					Select LrCode, Sum(Amount) as Amount 
					from fas_billdetails 
					Where 
						/*Convert(varchar, VTNo)+'-'+VRoute not in
						(Select Convert(varchar, VTNo)+'-'+Route from FAS_BankRecon_Vw 
						Where Lrcode in (Select LedgerCode from FAS_LedgerMaster Where Left(route, 4) in ('0201', '0B01') and CompCode=@CmCode)
							and isLrCode='1' and BankDate is Null and Compcode=@CmCode
						) 
						and */
						Type = 'On Acct' and RefDate <=@RptDate
						and LrCode in (Select LedgerCode 
								from FAS_LedgerMaster where Left(LrRoute, Len(@LrRoute))=@LrRoute and CompCode=@CmCode
								and LedgerCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompID = @CompID)
								)
						and CompCode=@CmCode
					group by LrCode ) M
				Where M.Amount <> 0
				
			 )  Z 
			Group by Z.LrCode, Z.Type
		       )  X
		Group by X.LrCode
		) W
	Where BRSAmt<>0 or AdvAmt<>0 or OBAmt<>0
	Order by LrName
End
GO

