CREATE PROCEDURE [dbo].[FAS_Rpt_OB_2] (@UserKey varchar(36), @LrRoute varchar(4), @RptDate Datetime,  @PrStart datetime, @PrEnd datetime, @CmCode varchar(12)) 
AS
Begin
	SET NOCOUNT ON

	
	

	Declare @BranchID varchar(2)
	Select @BranchID =Substring(@CmCode, 3, 2)

	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Select 'Overall Total',  Sum(Amount) as Amount, Sum(AdvAmt) as AdvAmt
	from
		(Select c.LrCode, Sum(c.Amount) as Amount,
				(Select isNull(Sum(Amount), 0) from FAS_BillDetails where LrCode = c.LrCode and Type='On Acct' and RefDate <= @RptDate and CompCode=@CmCode) as AdvAmt
		from
			(Select DateAdd(day, y.CreditDays, y.RefDate) as DueDate, z.LrCode, z.Amount 
			from fas_billdetails y,
				(Select LrCode, RefNo, Sum(Amount) as Amount from fas_billdetails
				where Type <> 'On Acct' and RefDate <= @RptDate 
					and LrCode in (Select LedgerCode from FAS_LedgerMaster where Left(LrRoute, Len(@LrRoute))=@LrRoute and CompCode=@CmCode
							and LedgerCode in (Select selectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID)
							)
					and CompCode=@CmCode
				group by LrCode, RefNo ) z 
			where z.Amount <> 0  and y.Type in ('Advance', 'New Ref') and y.RefNo=z.RefNo and y.LrCode=z.LrCode and y.CompCode=@CmCode
			) c
		group by c.LrCode 
		) d
End
GO

