CREATE PROCEDURE [dbo].[FAS_Rpt_OB_Det_New] (@UserKey varchar(36), @RptDate Datetime, @Start datetime, @End datetime, @Status varchar(2),  @PrStart datetime, @PrEnd datetime, @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON
	--@Status 11-From, To Both Date given; 00 From & To may be any; 01 From may be any but To Date specified; 10 To Date may be any but From Date specified	

	Declare @BranchID varchar(2)
	Select @BranchID = substring(@CmCode, 3, 2)

	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Declare @From datetime, @To datetime
	Select @From=Case Left(@Status, 1) when '0' then (Select Min(Refdate) from Fas_BillDetails where CompCode=@CmCode) Else @Start End 
	Select @To=Case Right(@Status, 1) when '0' then (Select Max(Refdate) from Fas_BillDetails where CompCode=@CmCode) Else @End End

	Select p.DocNo, p.DocDate, p.VrRoute, n.LrCode, n.RefNo, n.RefDate, p.Amount as InitialAmt, n.BalanceAmt,
			isNull(q.VoucherName, 'OpBal') as VrName, r.LrRoute,
			DateAdd(day, p.CreditDays, p.RefDate) as DueDate, (DateDiff(day, p.RefDate, @RptDate) - p.CreditDays) as OverDue
	from
		(Select m.LrCode, m.RefNo, m.BalanceAmt, 
				(Select Min(RefDate) from FAS_BillDetails m1 
				Where m1.RefNo=m.RefNo and m1.LrCode=m.LrCode and m1.CompCode=@CmCode) as RefDate
		from
			(Select a.LrCode, a.RefNo, Sum(a.Amount)as BalanceAmt
			from fas_billdetails a 
			Where a.LrCode in (Select selectInt From Com_SelectList Where UserKey = @UserKey
										and BranchID = @BranchID and CompID = @CompID) 
				and a.Type <> 'On Acct' and a.RefDate <= @RptDate and a.CompCode=@CmCode
			group by a.LrCode, a.RefNo 
			having Sum(a.Amount)<>0
			) m
		) n
		Left Outer Join FAS_BillDetails p 
			On n.RefNo=p.RefNo and n.RefDate=p.RefDate and n.LrCode=p.LrCode and p.CompCode=@CmCode
		Left Outer Join FAS_VoucherMaster q
			On (q.VrRoute+q.VrWidth)=p.VrRoute and q.CompCode=p.CompCode
		Left Outer Join Fas_LedgerMaster r
			On n.LrCode=r.LedgerCode and r.CompCode=p.CompCode


/*
	Select g.LrCode, g.RefNo, g.RefDate, m.DocNo, m.DocDate, q.LrRoute, m.VrRoute, n.VoucherName, g.DueDate,
		Case When g.RefDate between @From and @To then g.Amount Else 0 End as Amount, 
		Case When g.RefDate < @From then g.Amount Else 0 End as ObAmount, 	
		DateDiff(day, g.DueDate, @To) as OverDue
	from 
		(Select e.LrCode, e.RefNo, e.RefDate,  e.Amount, isNull(e.DueDate, e.RefDate) as DueDate
		from
			(Select isNull(b.LrCode, c.LrCode) as LrCode, isNull(c.RefNo, b.RefNo) as RefNo,  
				isNull(c.RefDate, (Select Min(d.RefDate) from FAS_BillDetails d where d.RefNo=b.RefNo and d.LrCode=b.LrCode and d.CompCode=@CmCode)) as RefDate,
			 	c.DueDate, b.Amount					
			from 
				(Select c1.LrCode, c1.RefNo, c1.RefDate, DateAdd(day, c1.CreditDays, c1.RefDate) as DueDate 
					from Fas_billdetails c1 
				where c1.LrCode in (Select selectInt From Com_SelectList Where UserKey = @UserKey
										and BranchID = @BranchID and CompID = @CompID) 
					and c1.Type in ('Advance', 'New Ref') and c1.CompCode=@CmCode)c
			Full Outer Join
				(Select a.LrCode, a.RefNo, Sum(a.Amount)as Amount
				from fas_billdetails a 
				Where a.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey
								and BranchID = @BranchID and CompID = @CompID) 
					and a.Type <> 'On Acct' and a.RefDate <= @RptDate and a.CompCode=@CmCode
				group by a.LrCode, a.RefNo having Sum(a.Amount)<>0
				) b 
			On c.RefNo=b.RefNo and c.LrCode=b.LrCode
			Where b.Amount <> 0  
			) e	
		Where (e.RefDate between @From and @To) 	
	) g		
	Left Outer Join (Select * From Fas_billdetails Where CompCode = @CmCode and RefDate between @From and @To)m
		On g.RefNo=m.RefNo and g.LrCode=m.LrCode  
	Left Outer Join FAS_VoucherMaster n
		On (n.VrRoute+VrWidth) = m.VrRoute and n.CompCode = m.CompCode
	Left Outer Join (Select * From Fas_LedgerMaster Where CompCode = @CmCode)q
		On m.LrCode=q.LedgerCode	
	Order by q.LrRoute, g.LrCode, g.RefDate, g.RefNo
*/

/*	Select LrCode, --LrName,
	 RefNo, RefDate, DueDate,  Amount,  DateDiff(day, DueDate, @RptDate) as OverDue
	from 
		(Select e.LrCode, e.RefNo, e.RefDate, e.Amount, isNull(e.DueDate, e.RefDate) as DueDate
		from
			(Select isNull(b.LrCode, c.LrCode) as LrCode, isNull(c.RefNo, b.RefNo) as RefNo,  
				isNull(c.RefDate, (Select Min(d.RefDate) from FAS_BillDetails d where d.RefNo=b.RefNo and d.LrCode=b.LrCode and d.CompCode=@CmCode)) as RefDate,
				 c.DueDate, b.Amount 
			from 
				(Select c1.LrCode, c1.RefNo, c1.RefDate, DateAdd(day, c1.CreditDays, c1.RefDate) as DueDate from fas_billdetails c1 
				where c1.LrCode in (Select selectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID) and c1.Type in ('Advance', 'New Ref') and c1.CompCode=@CmCode)c
			Full Outer Join
