				where a.LrCode in (Select selectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID) and a.Type <> 'On Acct' and a.RefDate <= @RptDate and a.CompCode=@CmCode
				group by a.LrCode, a.RefNo having Sum(a.Amount)<>0
