CREATE PROCEDURE [dbo].[FAS_Rpt_OB_Det_Sn] (@LrCode int, @RptDate Datetime, @PrStart datetime, @PrEnd datetime, @Status char(2), @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON
	--@Status 11-From, To Both Date given; 00 From & To may be any; 01 From may be any but To Date specified; 10 To Date may be any but From Date specified


	Declare @From datetime, @To datetime
	Select @From=Case Left(@Status, 1) when '0' then (Select Min(Refdate) from Fas_BillDetails where CompCode=@CmCode) Else @PrStart End 
	Select @To=Case Right(@Status, 1) when '0' then (Select Max(Refdate) from Fas_BillDetails where CompCode=@CmCode) Else @PrEnd End


	Select y.RefNo, y.RefDate, DateAdd(day, y.CreditDays, y.RefDate) as DueDate, DateDiff(day, DateAdd(day, y.CreditDays, y.RefDate), @RptDate) as Overdue, z.Amount 
	from fas_billdetails y Left Outer Join
		(Select RefNo, Sum(Amount) as Amount from fas_billdetails
		where Type <> 'On Acct' and RefDate <= @RptDate and LrCode=@LrCode and CompCode=@CmCode
		group by RefNo ) z 
	On y.RefNo=z.RefNo 
	where y.RefDate between @From and @To and z.Amount <> 0  and y.Type in ('New Ref', 'Advance') and y.LrCode=@LrCode and y.CompCode=@CmCode

	Order by y.RefDate, y.RefNo
End
GO

