CREATE PROCEDURE [dbo].[FAS_Rpt_OB_RR] (@UserKey Varchar(36), @RptDate Datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)

	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Select RefNo,  RefDate,  isnull(c.PartNo, '') as CustPartNo, isnull(c.ItemDescription, '') as ItemDesc,
		Convert(varchar, q.InvAmt) as InvAmt, Convert(varchar, q.PyAmt) as PyAmt, Convert(varchar, q.CrDrAmt) as CrDrAmt, Convert(varchar, q.OtherAmt) as OtherAmt, Convert(varchar, q.PnAmt) as PnAmt, 
		DueDate, DateDiff(day, DueDate, @RptDate) as Overdue, Convert(varchar, Actual) as Actual, isnull(RRNo, '') RRNo, RRDate
	from 

		( Select isNull(x.Ref, '') as InvRef, y.RefNo, y.RefDate, DateAdd(day, y.CreditDays, y.RefDate) as DueDate, z.InvAmt, z.PyAmt, z.CrDrAmt, z.OtherAmt, z.PnAmt
		from Fas_billdetails y Left Outer Join FAS_VoucherTranMast x
		On y.DocNo=x.DocNo and y.VrRoute=x.VrRoute and y.CompCode=x.CompCode
			Right Outer Join
			(Select RefNo, -Sum(InvAmt) as InvAmt, Sum(PyAmt) as PyAmt, Sum(CrDrAmt) as CrDrAmt, Sum(OtherAmt) as OtherAmt, -Sum(PnAmt) as PnAmt
			from 
				(Select RefNo,  Case when Type in ('Advance', 'New Ref') then Amount Else 0 End as InvAmt, 
					Case when Type='Agst Ref' and Left(VrRoute, 2)='0F' then Amount Else 0 End as PyAmt,
					Case when Type='Agst Ref' and Left(VrRoute, 2) in ('02', '03') then Amount Else 0 End as CrDrAmt,
					Case when Type='Agst Ref' and Left(VrRoute, 2) Not in ('02', '03', '0F') then Amount Else 0 End as OtherAmt,
					Amount as PnAmt
				from Fas_billdetails
				where Type <> 'On Acct' and RefDate <= @RptDate and LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID) 
				and CompCode=@CmCode
				 ) q
			group by RefNo 

			) z
		On y.RefNo=z.RefNo
		where z.PnAmt <> 0  and y.Type in ('Advance', 'New Ref') and y.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID) 
		and y.CompCode=@CmCode
		) q

 	 left outer join

		(Select Ltrim(Rtrim(b.Invoicetype))+':'+Convert(varchar,  b.Invoiceno) as InvRef, b.InvoiceDate, b.TotalAmount, b.RRNo, b.RRDate, (b.TotalAmount-((a.InvoiceQty-a.AcceptedQty)*(b.TotalAmount/a.InvoiceQty))) as Actual,
			e.PartNo, f.ItemDescription
		from Sal_Invoice_Dtl a Inner Join Sal_Invoice_Hdr b 
		On  a.Invoiceno=b.Invoiceno and a.Invoicetype=b.Invoicetype  and a.BranchID = b.BranchID and a.compid=b.compid and a.Finyear=b.Finyear
			Left Outer Join Sal_Customer_ItemMaster e
			On a.Itemcode=e.ItemCode  and b.CustomerCode=e.CustomerCode and b.BranchID = e.BranchID and b.CompId=e.CompId 
				Left Outer Join Inv_Material_Master f
				On a.ItemCode=f.ItemCode and b.BranchID = e.BranchID and b.CompId=f.CompId 
		where  b.InvoiceDate <= @RptDate
			and b.CustomerCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID) 
			and a.CompID+a.BranchID=@CmCode 
		) c
	On q.InvRef=c.InvRef and q.RefDate=c.InvoiceDate
	Order by q. RefDate, RefNo

End
GO

