CREATE PROCEDURE [dbo].[FAS_Rpt_OB_Smy_Sn] (@LrCode int, @RptDate Datetime, @PrStart datetime, @PrEnd datetime, @Status char(2), @CmCode varchar(12)) 

AS

Begin
	SET NOCOUNT ON
	--@Status 11-From, To Both Date given; 00 From & To may be any; 01 From may be any but To Date specified; 10 To Date may be any but From Date specified
	

	Declare @From datetime, @To datetime
	Select @From=Case Left(@Status, 1) when '0' then (Select Min(Refdate) from Fas_BillDetails where CompCode=@CmCode) Else @PrStart End 
	Select @To=Case Right(@Status, 1) when '0' then (Select Max(Refdate) from Fas_BillDetails where CompCode=@CmCode) Else @PrEnd End

	Select * 
	from
		(Select Sum(isNull(n.CurAmt, 0)) CurAmt, Sum(isNull(n.ObAmt, 0)) ObAmt, Sum(isNull(n.CbAmt, 0)) CbAmt, Sum(isNull(m.CurOnAc, 0)) CurOnAc, Sum(isNull(m.ObOnAc, 0)) ObOnAc, Sum(isNull(m.CbOnAc, 0)) CbOnAc
		from 
			(Select '1' as LrType, Sum(isNull(case when d.RefDate between @From and @To then d.Amount else 0 End, 0)) as CurOnAc,
				Sum(isNull(case when d.RefDate < @From then d.Amount else 0 End, 0)) as ObOnAc,
				Sum(isNull(case when d.RefDate > @To then d.Amount else 0 End, 0)) as CbOnAc
			from fas_billdetails d 
			where d.Type = 'On Acct' and d.RefDate <= @RptDate
					and d.LrCode = @LrCode and d.CompCode=@CmCode
			) m
		Full Outer Join
			(Select  '1' as LrType, Sum(isNull(case when g.RefDate between @From and @To then g.Amount else 0 End, 0)) as CurAmt,
				Sum(isNull(case when g.RefDate < @From then g.Amount else 0 End, 0)) as ObAmt,
				Sum(isNull(case when g.RefDate > @To then g.Amount else 0 End, 0)) as CbAmt
			from 
				(Select e.RefDate, e.Amount
				from
					(Select isNull(c.RefNo, b.RefNo) as RefNo,  
						isNull(c.RefDate, (Select Min(d.RefDate) from FAS_BillDetails d where d.RefNo=b.RefNo and d.LrCode=@LrCode and d.CompCode=@CmCode)) as RefDate,
						 c.DueDate, b.Amount 
					from 
						(Select c1.RefNo, c1.RefDate, DateAdd(day, c1.CreditDays, c1.RefDate) as DueDate from fas_billdetails c1 where c1.LrCode=@LrCode and c1.Type in ('Advance', 'New Ref') and c1.CompCode=@CmCode)c
					Full Outer Join
						(Select a.RefNo, Sum(a.Amount) as Amount 
						from fas_billdetails a 
						where a.LrCode=@LrCode and a.Type <> 'On Acct' and a.RefDate <= @RptDate  and a.CompCode=@CmCode
						group by a.RefNo having Sum(a.Amount)<>0
						) b 
					On c.RefNo=b.RefNo 
					where b.Amount <> 0  
					) e
				) g			
			) n 
		On m.LrType=n.LrType
		) q
	where q.ObAmt+q.CurAmt+q.CbAmt+q.ObOnAc+q.CurOnAc+q.CbOnAc <> 0
End
GO

