CREATE PROCEDURE [dbo].[FAS_Rpt_OB_SR_Det] (@RptDate Datetime, @PrStart Datetime, @PrEnd Datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON	

	Select LrCode, RefNo,  RefDate, (Select Case when Alias='' then Name else Alias End from Fas_LedgerMaster g where g.LedgerCode=LrCode and g.compcode=@CmCode) LrName, isnull(c.CustPartNo, '') as CustPartNo, --isnull(c.Item_Desc, '') as ItemDesc,
		Convert(varchar, q.InvAmt) as InvAmt, Convert(varchar, q.CrDrAmt) as CrDrAmt, Convert(varchar, q.OtherAmt) as OtherAmt, Convert(varchar, isnull(Actual, 0)) as Actual, Convert(varchar, q.PyAmt) as PyAmt, Convert(varchar, q.PnAmt) as PnAmt, isnull(RRNo, '') RRNo, Convert(varchar(10), RRDate, 110) RRDate, DueDate, DateDiff(day, DueDate, @RptDate) as Overdue 
	from 

		( Select y.LrCode, isNull(x.Ref, '') as InvRef, y.RefNo, y.RefDate, y.DueDate, z.InvAmt, z.PyAmt, z.CrDrAmt, z.OtherAmt, z.PnAmt
		from fas_billdetails y Left Outer Join FAS_VoucherTranMast x
		On y.DocNo=x.DocNo and x.DocDate=y.DocDate and y.VrRoute=x.VrRoute and y.CompCode=x.CompCode
			Left Outer Join
			(Select LrCode, RefNo, -Sum(InvAmt) as InvAmt, Sum(PyAmt) as PyAmt, Sum(CrDrAmt) as CrDrAmt, Sum(OtherAmt) as OtherAmt, -Sum(PnAmt) as PnAmt
			from 
				(Select LrCode, RefNo, Case when Type in ('Advance', 'New Ref') then Amount Else 0 End as InvAmt, 
					Case when Type='Agst Ref' and Left(VRoute, 2)='0F' then Amount Else 0 End as PyAmt,
					Case when Type='Agst Ref' and Left(VRoute, 2) in ('02', '03') then Amount Else 0 End as CrDrAmt,
					Case when Type='Agst Ref' and Left(VRoute, 2) Not in ('02', '03', '0F') then Amount Else 0 End as OtherAmt,
					Amount as PnAmt
				from fas_billdetails
				where Type <> 'On Acct' and RefDate <= @RptDate and LrCode in (Select f.LedgerCode from Fas_Ledgermaster f where Left(f.Route, 4)='0206' and f.CompCode=@CmCode) and CompCode=@CmCode
				 ) q
			group by LrCode, RefNo 
	
			) z
		On y.RefNo=z.RefNo and y.LrCode=z.LrCode
		where y.Type in ('Advance', 'New Ref') and  y.RefDate between @PrStart and @PrEnd and y.LrCode in (Select e.LedgerCode from Fas_Ledgermaster e where Left(e.Route, 4)='0206' and e.CompCode=@CmCode) and y.CompCode=@CmCode
		) q

		 Left outer join
	
		(Select Ltrim(Rtrim(b.invtype))+':'+Convert(varchar,  b.invnum) as InvRef, b.invdt, b.invoiceamt, b.RRNo, b.RRDate, (b.invoiceamt-((a.Qty-a.AcceptQty)*(b.invoiceamt/a.Qty))) as Actual,
			e.CustPartNo--, f.Item_Desc
		from sal_invsub a Inner Join sal_invmai b 
		On  a.invnum=b.invnum and a.invtype=b.invtype  and a.compid=b.compid and a.Finyear=b.Finyear
			Left Outer Join Sal_CustItemMast e
			On a.Item_code=e.Item_Code  and b.CustCode=e.CustCode and b.CompId=e.CompId 
		where  b.InvDt  between @PrStart and @PrEnd 
			and a.CompID+a.BranchID=@CmCode 
		) c
	On q.InvRef=c.InvRef and q.RefDate=c.InvDt
	Order by q. RefDate, RefNo

End
GO

