CREATE PROCEDURE [dbo].[FAS_Rpt_OB_SR_Sum_New] ( @UserKey varchar(36), @RptDate Datetime, @Start Datetime, @End Datetime, @Status char(2), @UserID char(5), @PrStart Datetime, @PrEnd Datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON

	--@Status 11-From, To Both Date given; 00 From & To may be any; 01 From may be any but To Date specified; 10 To Date may be any but From Date specified

		
	Declare @BranchID varchar(2)
	select @BranchID = substring(@CmCode, 3, 2)
	
	Declare @CompID char(3)
	select @CompID = Left(@CmCode, 2)

	Declare @From datetime, @To datetime
	Select @From=Case Left(@Status, 1) when '0' then (Select Min(Refdate) from Fas_BillDetails where CompCode=@CmCode) Else @Start End 
	Select @To=Case Right(@Status, 1) when '0' then (Select Max(Refdate) from Fas_BillDetails where CompCode=@CmCode) Else @End End


	Select LrCode, LrName, 
		Sum(Case when RefDate < @From then InvAmt else 0 end) as OBInvAmt,
			Sum(Case when RefDate between @From and @To then InvAmt else 0 end) as CurInvAmt,
			Sum(Case when RefDate > @To then InvAmt else 0 end) as CBInvAmt,
		Sum(Case when RefDate < @From then CrDrAmt else 0 end) as OBCrDrAmt,
			Sum(Case when RefDate between @From and @To then CrDrAmt else 0 end) as CurCrDrAmt,
			Sum(Case when RefDate > @To then CrDrAmt else 0 end) as CBCrDrAmt,
		Sum(Case when RefDate < @From then OtherAmt else 0 end) as OBOtherAmt,
			Sum(Case when RefDate between @From and @To then OtherAmt else 0 end) as CurOtherAmt,
			Sum(Case when RefDate > @To then OtherAmt else 0 end) as CBOtherAmt,
		Sum(Case when RefDate < @From then ActAmt else 0 end) as OBActAmt,
			Sum(Case when RefDate between @From and @To then ActAmt else 0 end) as CurActAmt,
			Sum(Case when RefDate > @To then ActAmt else 0 end) as CBActAmt,
		Sum(Case when RefDate < @From then PyAmt else 0 end) as OBPyAmt,
			Sum(Case when RefDate between @From and @To then PyAmt else 0 end) as CurPyAmt,
			Sum(Case when RefDate > @To then PyAmt else 0 end) as CBPyAmt,
		Sum(Case when RefDate < @From then PnAmt else 0 end) as OBPnAmt,
			Sum(Case when RefDate between @From and @To then PnAmt else 0 end) as CurPnAmt,
			Sum(Case when RefDate > @To then PnAmt else 0 end) as CBPnAmt
	
	
	from
		(Select LrCode, RefNo,  RefDate, (Select Case when Alias='' then LedgerName else Alias End from Fas_LedgerMaster g where g.LedgerCode=LrCode and g.compcode=@CmCode) LrName,
			q.InvAmt, q.CrDrAmt, q.OtherAmt, Convert(money, isnull(c.Actual, 0)) as ActAmt, q.PyAmt, q.PnAmt
		from 
			(Select e.LrCode, e.RefNo, e.RefDate, e.DueDate, e.InvAmt, e.PyAmt, e.CrDrAmt, e.OtherAmt, e.PnAmt, e.InvRef
			from
				(Select isNull(b.LrCode, c.LrCode) as LrCode, isNull(c.RefNo, b.RefNo) as RefNo,  
					isNull(c.RefDate, (Select Min(d.RefDate) from FAS_BillDetails d where d.RefNo=b.RefNo and d.LrCode=b.LrCode and d.CompCode=@CmCode)) as RefDate,
					 c.DueDate, b.InvAmt, b.PyAmt, b.CrDrAmt, b.OtherAmt, b.PnAmt, isNull(c.Ref, '') as InvRef 
				from 
					(Select c1.LrCode, c1.RefNo, c1.RefDate, DateAdd(day, c1.CreditDays, c1.RefDate) as DueDate, c2.Ref 
					from fas_billdetails c1 Left Outer Join fas_VoucherTranMast c2 
					on c1.VrRoute=c2.VrRoute and c1.DocDate=c2.DocDate and c1.DocNo=c2.DocNo and c1.CompCode=c2.CompCode
					where c1.LrCode in (Select SelectInt from Com_SelectList where UserKey=@UserKey and @BranchID = @BranchID and CompID=@CompID)
						and c1.Type in ('Advance', 'New Ref') and c1.CompCode=@CmCode)c
				Full Outer Join
					(Select LrCode, RefNo, -Sum(isNull(InvAmt, 0)) as InvAmt, Sum(isNull(PyAmt, 0)) as PyAmt, Sum(isNull(CrDrAmt, 0)) as CrDrAmt, Sum(isNull(OtherAmt, 0)) as OtherAmt, -Sum(isNull(PnAmt, 0)) as PnAmt
					from 
						(Select LrCode, RefNo, Case when Type in ('Advance', 'New Ref') then Amount Else 0 End as InvAmt, 
							Case when Type='Agst Ref' and Left(VrRoute, 2)='0F' then Amount Else 0 End as PyAmt,
							Case when Type='Agst Ref' and Left(VrRoute, 2) in ('02', '03') then Amount Else 0 End as CrDrAmt,
							Case when Type='Agst Ref' and Left(VrRoute, 2) Not in ('02', '03', '0F') then Amount Else 0 End as OtherAmt,
							Amount as PnAmt

						from fas_billdetails
						where LrCode in (Select SelectInt from Com_SelectList where UserKey=@UserKey and @BranchID = @BranchID and CompID=@CompID) 
							and Type <> 'On Acct' and RefDate <= @RptDate and CompCode=@CmCode
						 ) q
					group by LrCode, RefNo
					) b 
				On c.RefNo=b.RefNo and c.LrCode=b.LrCode
				where b.PnAmt <> 0  
				) e
			where e.RefDate <= @RptDate 
			) q
		
		Left outer join
			
			(Select Ltrim(Rtrim(b.Invoicetype))+':'+Convert(varchar,  b.Invoiceno) as InvRef, b.InvoiceDate, b.TotalAmount, b.RRNo, b.RRDate, (b.TotalAmount-((a.InvoiceQty-a.AcceptedQty)*(b.TotalAmount/a.InvoiceQty))) as Actual
			from Sal_Invoice_Dtl a Inner Join Sal_Invoice_Hdr b 
			On  a.Invoiceno=b.Invoiceno and a.Invoicetype=b.Invoicetype and a.BranchID = b.BranchID and a.CompID =b.CompID and a.Finyear=b.Finyear
				Left Outer Join Sal_Customer_ItemMaster e
				On a.ItemCode=e.ItemCode  and b.CustomerCode=e.CustomerCode and b.BranchID = e.BranchID and b.CompId=e.CompId 
			where  b.InvoiceDate <= @RptDate 
				and a.CompID+a.BranchID=@CmCode 
			) c
		On q.InvRef=c.InvRef and q.RefDate=c.InvoiceDate
		) m
	group by LrCode, LrName
	Order by LrName

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_OB_Tot_New]    Script Date: 17/06/2026 11:30:12 ******/
SET ANSI_NULLS OFF
GO

