CREATE PROCEDURE [dbo].[FAS_Rpt_OB_Tot_New] (@UserKey Varchar(36),  @RptDate Datetime, @Start datetime, @End datetime, @Status char(2),  @UserID char(5),  @PrStart datetime, @PrEnd datetime, @CmCode varchar(12)) 

AS

Begin

	SET NOCOUNT ON
	--@Status 11-From, To Both Date given; 00 From & To may be any; 01 From may be any but To Date specified; 10 To Date may be any but From Date specified

	
	
	
	Declare @BranchID varchar(2)
	select @BranchID = substring(@CmCode, 3, 2)

	Declare @CompID char(3)
	Select @CompID = Left(@CmCode, 2)

	Declare @From datetime, @To datetime
	Select @From=Case Left(@Status, 1) when '0' then (Select Min(Refdate) from Fas_BillDetails where CompCode=@CmCode) Else @Start End 
	Select @To=Case Right(@Status, 1) when '0' then (Select Max(Refdate) from Fas_BillDetails where CompCode=@CmCode) Else @End End


	Select 'Overall Total',  Sum(isNull(p.CurAmt, 0)) CurAmt, Sum(isNull(p.ObAmt, 0)) ObAmt, Sum(isNull(p.CbAmt, 0)) CbAmt, Sum(isNull(p.CurOnAc, 0)) CurOnAc, Sum(isNull(p.ObOnAc, 0)) ObOnAc, Sum(isNull(p.CbOnAc, 0)) CbOnAc
	from
		(Select isNull(n.LrCode, m.LrCode) LrCode, isNull(n.CurAmt, 0) CurAmt, isNull(n.ObAmt, 0) ObAmt, isNull(n.CbAmt, 0) CbAmt, isNull(m.CurOnAc, 0) CurOnAc, isNull(m.ObOnAc, 0) ObOnAc, isNull(m.CbOnAc, 0) CbOnAc
		from 
			(Select d.LrCode, Sum(isNull(case when d.RefDate between @From and @To then d.Amount else 0 End, 0)) as CurOnAc,
				Sum(isNull(case when d.RefDate < @From then d.Amount else 0 End, 0)) as ObOnAc,
				Sum(isNull(case when d.RefDate > @To then d.Amount else 0 End, 0)) as CbOnAc
			from fas_billdetails d 
			where d.Type = 'On Acct' and d.RefDate <= Convert(datetime, @RptDate, 111) 
					and d.LrCode in (Select selectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID) 
					and d.CompCode=@CmCode
			group by d.LrCode 
			) m
		Full Outer Join
			(Select g.LrCode, Sum(isNull(case when g.RefDate between @From and @To then g.Amount else 0 End, 0)) as CurAmt,
				Sum(isNull(case when g.RefDate < @From then g.Amount else 0 End, 0)) as ObAmt,
				Sum(isNull(case when g.RefDate > @To then g.Amount else 0 End, 0)) as CbAmt
			from 
				(Select e.LrCode, e.RefDate, e.Amount
				from
					(Select isNull(b.LrCode, c.LrCode) as LrCode, isNull(c.RefNo, b.RefNo) as RefNo,  
						isNull(c.RefDate, (Select Min(d.RefDate) from FAS_BillDetails d where d.RefNo=b.RefNo and d.LrCode=b.LrCode and d.CompCode=@CmCode)) as RefDate,
						 c.DueDate, b.Amount 
					from 
						(Select c1.LrCode, c1.RefNo, c1.RefDate, DateAdd(day, c1.CreditDays, c1.RefDate) as DueDate from fas_billdetails c1
						 where c1.LrCode in (Select selectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID) 
						and c1.Type in ('Advance', 'New Ref') and c1.CompCode=@CmCode)c
					Full Outer Join
						(Select a.LrCode, a.RefNo, Sum(a.Amount) as Amount 
						from fas_billdetails a 
						where a.LrCode in (Select selectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID)
						and a.Type <> 'On Acct' and a.RefDate <= Convert(datetime, @RptDate, 111)  and a.CompCode=@CmCode
						group by a.LrCode, a.RefNo having Sum(a.Amount)<>0
						) b 
					On c.RefNo=b.RefNo and c.LrCode=b.LrCode
					where b.Amount <> 0  
					) e
				) g			
			group by g.Lrcode
			) n 
		On m.LrCode=n.LrCode
		) p

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_PL_0]    Script Date: 17/06/2026 11:30:12 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_PL_0] (@PrStart datetime, @PrEnd datetime, @CmCode varchar(12))
AS

Begin
	SET NOCOUNT ON

	Select Master, Path, Type, Case Type when 'Group' then Space(Len(Path)) + Particulars
	                                                             when 'Ledger' then space(Len(Path))+'    '+Particulars End as Particulars,

			Case When Type='Ledger' or (Len(Path) > 2 and Type='Group') then --Amt1 Else 0
				  Case   When Path = '0D' then Amt1 When Path = '0E' then -Amt1
					When Path = '05' then Amt1 When Path = '06' then -Amt1 
					When Path = '07' then Amt1 When Path = '08' then -Amt1
					When Path = '21' then Amt1 When Path = '31' then -Amt1
					Else 0 End
					End as SubAmt,	

			Case When Len(Path)=2 and Type='Group' then --Amt1 Else 0
				  Case   When Path = '0D' then Amt1 When Path = '0E' then -Amt1
					When Path = '05' then Amt1 When Path = '06' then -Amt1 
					When Path = '07' then Amt1 When Path = '08' then -Amt1
					When Path = '21' then Amt1 When Path = '31' then -Amt1
					Else 0 End
					End as TotAmt,

				  Case   Left(Path, 2) 	When  '0E' then 1 	When  '21' then 2  	When  '0D' then 3 	When '31' then 4
						When  '06' then 5 	When  '05'  then 6 	When  '08' then 7 	When  '07' then 8
					End as SortOrder

	From 
		(Select Master, Type, Particulars,ClosingBalance as Amt1, Path
		from dbo.fn_FAS_Rpt_TrialBalance(@PrStart, @PrStart, @PrEnd, @CmCode)
		where Left(Path, 2) in ('0E', '0D', '05', '06', '07', '08') --or Path like '0205%')
		
		Union All

		Select '00', 'Group' as Type,  'Opening Stock'  as Particulars, Sum(OpeningStock), '21' as Path
		from dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode)

		Union All

		Select '00', 'Group' as Type,  'Closing Stock'  as Particulars, Sum(ClosingStock), '31' as Path
		from dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode)

		Union All

		Select '00', 'Ledger' as Type,  isNull(b.LedgerName, '')  as Particulars, OpeningStock, '21' as Path
		from dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
		where OpeningStock<>0

		Union All

		Select '00', 'Ledger' as Type,  isNull(b.LedgerName, '')   as Particulars, ClosingStock, '31' as Path
		from dbo.fn_FAS_StockValue (@PrStart, @PrEnd, @CmCode) a Left Outer Join FAS_LedgerMaster b On a.LedgerCode=b.LedgerCode and a.CompCode=b.CompCode
		where ClosingStock<>0

     		) M

	Order by 7, Type, 4

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_PL_Mgmt]    Script Date: 17/06/2026 11:30:12 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_PL_Mgmt] (@FromDate datetime, @Branchid varchar(3), @ToDate datetime, @CmCode varchar(12), @CompID varchar(3), @Finyear varchar(15))

AS

	Set NOCOUNT ON
	
	Declare @tmpCompID as varchar(3)   --For Power Provision to ACE & Bharath
	Select Case @CompID When '01' Then @CompID Else '03' End

	Declare @PerUnitCost as money
	Select @PerUnitCost = 5.0

--Sales
	Select Particulars, Seq, Sum(Amt) as Amt 
	from 
		(Select Particulars, Seq, Sum(Amt) as Amt 
		from 
			(Select case when Type='Labour' then 'Labour Sales' else 'Auto Turned Components' end as Particulars, Case When Type='Labour' then 20000 Else 10000 End as Seq, a.GoodsValue as amt 
			from sal_invoice_vw a  
			where a.invsource<>'C' and a.Type in ('OE','Labour') and a.invdt between @FromDate  and @ToDate and a.compid=@CompID and a.finyear=@Finyear
			) x 
		group by Particulars, Seq 
	
		Union All 
	
		Select 'Labour Sales', 20000, isnull(sum(Qty*rate),0) as amt 
		from sal_dcsub a left outer join sal_dcmain b on  a.dcno=b.dcno and a.dctype=b.dctype and a.compid=b.compid and a.finyear=b.finyear 
		where b.dcdate between   @FromDate and @ToDate and b.compid=@CompID and b.finyear=@Finyear 
	
		Union All 
	
		Select 'Sales Return', 30000, sum(isNull(rate, 0)*-rej_Qty) as salReturn 
		from GRIR a 
		where a.Pur_sub='R' and a.compid=@CompID and a.finyear=@Finyear and a.grir_dt Between   @FromDate and @ToDate
	)x1 
	group by Particulars, Seq  

--Closing balance

	Union All
	
	Select Space(2)+c.WHS_Desc as Particulars, 
		40000+isNull((Select Count(*) from Inv_WHS_Mast c1 
		Where c1.WHS_Code <> 'CGS' and c1.WHS_Nature not in ('WIP', 'StockAcknowledge', 'Scrap') and c1.CompID=a.CompID and c1.WHS_Code < c.WHS_Code), 0) as Seq, 
			Sum(CB_Qty*b.Rate) as Amt 
	from dbo.fn_Inv_AsOnDate_Stock(@ToDate, @BranchID, @CompID, @Finyear) a Left Outer Join Inv_Matl_Mast b On a.Item_code=b.Item_Code and a.CompID=b.CompID 
		Left Outer Join Inv_WHS_Mast c On a.WHScode=c.WHS_Code and a.CompID=c.CompID
	where c.WHS_Code <> 'CGS' and c.WHS_Nature not in ('WIP', 'StockAcknowledge', 'Scrap') and a.compid=@CompID 
	Group by c.WHS_Desc, c.WHS_Code, a.CompID

	Union All 

	Select Space(2)+'Work in Progress' as Particulars, 50000, Sum(StockVal) as WIPValue 
	from 
		(Select ItemCode, Sum(Qty)*isNull(z.Rate, 0) as StockVal 
		from 
			(Select ItemCode, Case When FromWHS='WIP' Then -Qty Else Qty End as Qty 
			from 
				(Select Case When a.FromItem='' then a.TranItem else a.FromItem End as ItemCode, 
					Case when a.FromItem=a.TranItem Then a.TranQty Else a.TranQty * a.Norms End as Qty, FromWHS , ToWHS 
				from inv_matltran_dtl a  
				Where a.TranDate <= @ToDate and (FromWHS='WIP' or ToWHS='WIP') and a.CompID=@CompID and a.Finyear=@Finyear 
				) x 
			) y 
			Left Outer Join Inv_Matl_Mast z On y.ItemCode=z.Item_Code 
		Where z.Item_Type not in ('P', 'L') and z.CompID=@CompID 
		group by y.itemcode, z.Rate
		) y1 

	Union All 

	Select Space(2)+'Subcontract' as Particulars, 60000, Sum(SCValue) as SCValue 
	From 
		(Select x.ItemCode, Sum(Case When Len(FromWHS)=4 then -Qty Else Qty End*y.Rate) as SCValue 
		From 
			(Select Case When a.FromItem='' then a.TranItem else a.FromItem End as ItemCode, 
				Case when a.FromItem=a.TranItem Then a.TranQty Else a.TranQty * a.Norms End as Qty, FromWHS , ToWHS 
			from FAS_AcMast a1 Inner Join inv_matltran_dtl a On a1.Code = a.FromWHS and a1.CompID=a.CompID 
			Where a1.Ac_Type in ('P', 'Y') and a1.Type='S' 
				and a.ToWHS not in ('TCS', 'RMS') and a.ToWHS in (Select WHS_Code from Inv_WHS_Mast where WHS_Nature in ('InHouse', 'JobWork', 'UnderInspection', 'StockAcknowledge') and CompID=@CompID) 
				and a.TranDate <= @ToDate and a.CompID=@CompID and a.Finyear=@Finyear 

			Union All 

			Select Case When a.FromItem='' then a.TranItem else a.FromItem End as ItemCode, 
				Case when a.FromItem=a.TranItem Then a.TranQty Else a.TranQty * a.Norms End as Qty, FromWHS , ToWHS 
			from FAS_AcMast a1 Inner Join inv_matltran_dtl a On a1.Code = a.ToWHS and a1.CompID=a.CompID 
			Where a1.Ac_Type in ('P', 'Y') and a1.Type='S' 
				and a.FromWHS<>'TCS' and a.FromWHS in (Select WHS_Code from Inv_WHS_Mast where WHS_Nature in ('InHouse', 'JobWork', 'UnderInspection', 'StockAcknowledge') and CompID=@CompID) 
				and a.TranDate <= @ToDate and a.CompID=@CompID and a.Finyear=@Finyear
			 ) x 
			Left Outer Join Inv_Matl_Mast y On x.ItemCode=y.Item_Code 
		Where y.CompID=@CompID 
		Group By x.ItemCode
	) z 

--Cost of Sales

--Opening Balance

	Union All

	Select Space(2)+c.WHS_Desc as Particulars,
		70000+isNull((Select Count(*) from Inv_WHS_Mast c1 
		Where c1.WHS_Code <> 'CGS' and c1.WHS_Nature not in ('WIP', 'StockAcknowledge', 'Scrap') and c1.CompID=a.CompID and c1.WHS_Code < c.WHS_Code), 0) as Seq, 
		Sum(CB_Qty*b.Rate) as Amt 
	from dbo.fn_Inv_AsOnDate_Stock(@ToDate, @Branchid, @CompID, @Finyear) a Left Outer Join Inv_Matl_Mast b On a.Item_code=b.Item_Code and a.CompID=b.CompID 
		Left Outer Join Inv_WHS_Mast c On a.WHScode=c.WHS_Code and a.CompID=c.CompID
	where c.WHS_Code <> 'CGS' and c.WHS_Nature not in ('WIP', 'StockAcknowledge', 'Scrap') and a.compid=@CompID 
	Group by c.WHS_Desc, c.WHS_Code, a.CompID

	Union All 

	Select Space(2)+'Work in Progress' as Particulars, 80000, Sum(StockVal) as WIPValue 
	from 
		(Select ItemCode, Sum(Qty)*isNull(z.Rate, 0) as StockVal 
		from 
			(Select ItemCode, Case When FromWHS='WIP' Then -Qty Else Qty End as Qty 
			from 
				(Select Case When a.FromItem='' then a.TranItem else a.FromItem End as ItemCode, 
					Case when a.FromItem=a.TranItem Then a.TranQty Else a.TranQty * a.Norms End as Qty, FromWHS , ToWHS 
				from inv_matltran_dtl a  
				Where a.TranDate <= @ToDate and (FromWHS='WIP' or ToWHS='WIP') and a.CompID=@CompID and a.Finyear=@Finyear 
				) x 
			) y 
			Left Outer Join Inv_Matl_Mast z On y.ItemCode=z.Item_Code 
		Where z.Item_Type not in ('P', 'L') and z.CompID=@CompID 
		group by y.itemcode, z.Rate
		) y1 

	Union All 

	Select Space(2)+'Subcontract' as Particulars, 90000, Sum(SCValue) as SCValue 
	From 
		(Select x.ItemCode, Sum(Case When Len(FromWHS)=4 then -Qty Else Qty End*y.Rate) as SCValue 
		From 
			(Select Case When a.FromItem='' then a.TranItem else a.FromItem End as ItemCode, 
				Case when a.FromItem=a.TranItem Then a.TranQty Else a.TranQty * a.Norms End as Qty, FromWHS , ToWHS 
			from FAS_AcMast a1 Inner Join inv_matltran_dtl a On a1.Code = a.FromWHS and a1.CompID=a.CompID 
			Where a1.Ac_Type in ('P', 'Y') and a1.Type='S' 
				and a.ToWHS not in ('TCS', 'RMS') and a.ToWHS in (Select WHS_Code from Inv_WHS_Mast where WHS_Nature in ('InHouse', 'JobWork', 'UnderInspection', 'StockAcknowledge') and CompID=@CompID) 
				and a.TranDate < @FromDate and a.CompID=@CompID and a.Finyear=@Finyear 

			Union All 

			Select Case When a.FromItem='' then a.TranItem else a.FromItem End as ItemCode, 
				Case when a.FromItem=a.TranItem Then a.TranQty Else a.TranQty * a.Norms End as Qty, FromWHS , ToWHS 
			from FAS_AcMast a1 Inner Join inv_matltran_dtl a On a1.Code = a.ToWHS and a1.CompID=a.CompID 
			Where a1.Ac_Type in ('P', 'Y') and a1.Type='S' 
				and a.FromWHS<>'TCS' and a.FromWHS in (Select WHS_Code from Inv_WHS_Mast where WHS_Nature in ('InHouse', 'JobWork', 'UnderInspection', 'StockAcknowledge') and CompID=@CompID) 
				and a.TranDate < @FromDate and a.CompID=@CompID and a.Finyear=@Finyear
			 ) x 
			Left Outer Join Inv_Matl_Mast y On x.ItemCode=y.Item_Code 
		Where y.CompID=@CompID 
		Group By x.ItemCode
	) z

--Purchase Accounts

	Select Space(2)+Particulars as Particulars, Seq, Sum(Value) as Amt  
	from 
		(Select Case b.Item_Type When 'R' then 'Raw Material' Else 'Tools & Consumables' End as Particulars, 
			Case b.Item_Type When 'R' Then 100000 Else 110000 End as Seq, Accd_Qty*Rate as Value 
		from rec_grir_vw a  Left Outer Join Inv_Matl_Mast b On a.Item_Code=b.Item_Code and a.CompID=b.CompID 
		Where a.pur_sub in ('P', 'C') and b.Item_Type in ('R', 'T', 'L') and a.CompID=@CompID and a.Finyear=@Finyear and a.grir_dt between @FromDate and @ToDate 
		) x 
	Group by Particulars, Seq


--Power Provision

	Union All

	Select  'Power Provision',  120000, Case @CompID When '01' then Units*@PerUnitCost When '02' Then (Units*@PerUnitCost)*(40/100) When '03' Then (Units*@PerUnitCost)*(60/100) End as Amt
	from
		(Select isNull((Units/Period)*(datediff(hh, @FromDate, @ToDate)+24), 0) as Units  
		from
			(Select datediff(hh, (a.DateTaken+a.TimeTaken+2), (b.DateTaken+b.TimeTaken+2)) as Period, b.ActualReadings-a.ActualReadings as Units 
			from  
				(Select * 
				from PPC_ElectricalMeterReading_Tran a1 
				where (DateTaken+TimeTaken+2) = (Select Max(DateTaken+TimeTaken+2) from PPC_ElectricalMeterReading_Tran a2 where (DateTaken+TimeTaken+2) <= @FromDate and a1.CompID=a2.CompID and a1.Finyear=a2.Finyear) 
					and a1.CompID=@tmpCompID and a1.Finyear=@Finyear
				) a 
		
			Full outer join 
		
				(Select * 
				from PPC_ElectricalMeterReading_Tran b1 
				where (DateTaken+TimeTaken+2) = (Select Max(DateTaken+TimeTaken+2) from PPC_ElectricalMeterReading_Tran b2 where (DateTaken+TimeTaken+2) >= @ToDate + '23:59:59' and b1.CompID=b2.CompID and b1.Finyear=b2.Finyear) 
					and b1.CompID=@tmpCompID and b1.Finyear=@Finyear) b 
			On a.CompID=b.CompID and a.finyear=b.finyear
			)c
		) d

--Operationg Expenses

	Union All

	Select Space(2)+Particulars as Particulars, 130000 as Seq, Sum(Amt) as Amt  
	from
		(
			--Salary, PF, ESI

		Select 'Salary and Wages' as Particulars,  sum(earnings) as Amt 
		from 
			(Select  a.Emp_cd, sum(b.amount/30) * (datediff(day, @FromDate, @ToDate)+1) as earnings 
			from Pay_Emp_Mast a left outer join Pay_curr_sal_Mast b on a.emp_cd=b.emp_Cd and a.compid=b.compid 
			Where b.edate in (select max(c.edate) from Pay_curr_sal_Mast c where c.compid=@CompID and c.emp_cd=a.emp_cd) 
			and a.status='C' and a.compid=@CompID group by a.Emp_cd
			) x 
	
		Union All 
		
		select 'Employee State Insurance (ESI)', sum(esi) 
		from 
			(Select a.Emp_cd, sum(c.Mon_deduct/30) * (datediff(day, @FromDate, @ToDate)+1) as esi  
			from Pay_Emp_Mast a left outer join PAY_F_DEDUCT_MAST c on a.emp_cd=c.emp_Cd and a.compid=c.compid 
			where a.status='C' and a.compid=@CompID and EDcode='ESI' group by a.Emp_cd
			)x1 
	
		Union All 
		
		Select 'Employee Provident Fund (EPF)',  sum(pf) 
		from 
			(select a.Emp_cd, sum(c.Mon_deduct/30) * (datediff(day, @FromDate, @ToDate)+1) as pf  
			from Pay_Emp_Mast a left outer join PAY_F_DEDUCT_MAST c on a.emp_cd=c.emp_Cd and a.compid=c.compid 
			where a.status='C' and a.compid=@CompID and EDcode='PF' group by a.Emp_cd
			)x2
	
		--Other Expenses
	
		Union All
		
		Select Particulars, Sum(Amt) as Amt
		from
			(Select b.name as Particulars, b.Ledger_Route as Path, (sum(b.dramt)-sum(b.cramt)) as Amt 
			from fas_groupmaster a Right Outer Join fas_vrdetails_vw b On b.Ledger_Route=a.Route+a.width and a.CompCode=b.CompCode 
			where a.route='' and a.Width ='07' and b.LrCode not in 
									(select distinct LedgerCode from Fas_PL_VariableMaster where Rptcode='Rpt0001' and compcode=@CmCode 
									group by ledgercode, Lastupdateddate 
									having Lastupdateddate=Max(Lastupdateddate)
									)  
				and b.VTDate between @FromDate and @ToDate and b.compcode=@CmCode 
			group by b.Ledger_Route, b.name 
			) m1
		Group by Particulars
		
		Union All 
		
		Select distinct LrDescription,  (LrValues/30) * (datediff(day, @FromDate, @ToDate)+1) as lrvalues  
		from Fas_PL_VariableMaster
		where FromERP='0' and rptcode='Rpt0001' and compcode=@CmCode and lastupdateddate in (select max(Lastupdateddate) from Fas_PL_VariableMaster where compcode=@CmCode) 
		
		Union All 
		
		Select 'Job Work Expenses',  sum(Qty*rate) 
		from 
			(Select y.Item_Code, Case when y.Qty > z.accd_Qty then z.accd_Qty else y.Qty end as Qty, isNull(dbo.fn_GRIR_Rate(z.GRIR_No, z.GRIR_Dt, z.CompID), 0) as rate 
			from 
				(Select Item_Code, Sum(Qty) as qty 
				from 
					(Select Item_Code, Sum(Qty) as qty 
					from SAL_Invoice_Vw a 
					where a.invsource<>'C' and a.Type in ('OE','Labour') and a.invdt between @FromDate and @ToDate and a.compid=@CompID and a.finyear=@Finyear 
					group by item_code 

					Union All 

					Select ItemCode, Sum(Qty) as Qty 
					from SAL_DCSub a 
					Left Outer Join SAL_DCMain b On  a.dcno=b.dcno and a.dctype=b.dctype and a.compid=b.compid and a.finyear=b.finyear 
					where b.dcdate between @FromDate and @ToDate and b.compid=@CompID and b.finyear=@Finyear 
					group by itemcode 
					) x 
				group by item_code 
				) y 
			Left Outer Join grir z On y.item_code=z.item_code 
			where z.compid=@CompID and z.finyear=@Finyear and z.pur_sub in ('S', 'L', 'W') 
			and z.grir_dt between @FromDate and @ToDate
			) a

		)  q
	Group by Particulars
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_PLPrint_Gen_Budget]    Script Date: 17/06/2026 11:30:12 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[FAS_Rpt_PLPrint_Gen_Budget](@BudgetFor [Char] (2),@IncludeZero bit, @Sort bit, @UserKey Varchar(36), @ReportType int,   
    @FromDate datetime, @ToDate datetime, @CompCode Varchar(12))                  
As                  
BEGIN                
    SET NOCOUNT ON;  
    SET ARITHABORT ON;  
     
    Declare @BranchID Varchar(5);     
    Set @BranchID = '00';    
    Declare @CompID Varchar(5);    
    Set @CompID = '02';    
    Declare @sDate Datetime;    
    Set @sDate = Getdate();        
              
    If @IncludeZero='0'                  
    BEGIN              
        If @Sort='1'                  
                  
            Select Master, a.Path, a.Type, a.Code, Particulars, a.SubAmount, a.TotalAmount, a.SortOrder, Isnull(b.BudgetValue,0) as BudgetValue,           
                Isnull(b.BudgetPerc,0) as BudgetPerc, b.IsHide                 
            From dbo.fn_FAS_Dis_ProfitAndLoss ('1', @ReportType, @FromDate, @ToDate, @CompCode) a                 
            Left Outer Join COM_BudgetMaster_dtl b            
                On a.Code = b.Code and a.Type = b.Type  and a.Path = b.Path and b.CompID+b.BranchID = @CompCode            
            Where b.FromDate = @FromDate and b.ToDate = @ToDate and a.TotalAmount <> 0 or a.SubAmount <> 0                  
            Order By a.SortOrder, a.Path, a.Type, SubAmount, Particulars                  
                      
        Else                  
            Select a1.Master, a1.Path, a1.Type, a1.Code, Isnull(a.Particulars,a1.Particulars) as Particulars, Isnull(a.SubAmount,0) as SubAmount, Isnull(a.TotalAmount,0) as TotalAmount,          
                ISNULL(a1.SortOrder,0) as SortOrder, Isnull(b.BudgetValue,0) as BudgetValue, Isnull(b.BudgetPerc,0) as BudgetPerc,           
                Isnull(Case When b.IsHide Is null or b.IsHide = 'False' then 0 else 1 End,0) as IsHide, Isnull(b.RespID,0) as RespID, Isnull(c.EmployeeName,'') as EmployeeName,    
                Isnull(Case When b.IsFixed Is null or b.IsFixed = 'False' then 0 else 1 End,0) as IsFixed    
            From dbo.fn_FAS_Dis_ProfitAndLoss ('1', @ReportType, '2020-04-01 00:00:00', @ToDate, @CompCode) a1            
            Left Outer Join (Select * from dbo.fn_FAS_Dis_ProfitAndLoss ('1', @ReportType, @FromDate, @ToDate, @CompCode)            
                                Where TotalAmount <> 0 or SubAmount <> 0) a          
                On a1.Code = a.Code and a1.Type = a.Type and a1.Master = a.Master and a1.Path = a.Path             
            Left Outer Join COM_BudgetMaster_dtl b            
                On b.BudgetFor = @BudgetFor and b.FromDate = @FromDate and b.ToDate <= @ToDate and a1.Path = b.Path and a1.Type = b.Type and a1.Code = b.Code and b.CompID+b.BranchID = @CompCode            
            Left Outer Join EmployeeDetails c On b.RespID = c.EmployeeCode        
            Order By a1.SortOrder, a1.Path, a1.Type, Isnull(a.Particulars,a1.Particulars)                 
    END                  
    Else                  
    BEGIN                     
        If @Sort='1'                  
            Select Master, a.Path, a.Type, a.Code, Particulars, SubAmount, TotalAmount, SortOrder, Isnull(b.BudgetValue,0) as BudgetValue,           
                Isnull(b.BudgetPerc,0) as BudgetPerc, b.IsHide                   
            From dbo.fn_FAS_Dis_ProfitAndLoss ('1', @ReportType, @FromDate, @ToDate, @CompCode) a                  
            Left Outer Join COM_BudgetMaster_dtl b            
                On  a.Code = b.Code and a.Type = b.Type and a.Path = b.Path  
            Where b.FromDate = @FromDate and b.ToDate = @ToDate and b.CompID+b.BranchID = @CompCode  
            Order By SortOrder, a.Path, a.Type, SubAmount, Particulars                  
                     
        Else                  
            Select distinct a1.Master, a1.Path, a1.Type, a1.Code, Isnull(a.Particulars,a1.Particulars) as Particulars, Isnull(a.SubAmount,0) as SubAmount, Isnull(a.TotalAmount,0) as TotalAmount,          
                a1.SortOrder, Isnull(b.BudgetValue,0) as BudgetValue, Isnull(b.BudgetPerc,0) as BudgetPerc,           
                Isnull(Case When b.IsHide Is null or b.IsHide = 'False' then 0 else 1 End,0) as IsHide, Isnull(b.RespID,0) as RespID, Isnull(c.EmployeeName,'') as EmployeeName,    
                Isnull(Case When b.IsFixed Is null or b.IsFixed = 'False' then 0 else 1 End,0) as IsFixed    
            From dbo.fn_FAS_Dis_ProfitAndLoss ('1', @ReportType, '2020-04-01 00:00:00', @ToDate, @CompCode) a1            
            Left Outer Join dbo.fn_FAS_Dis_ProfitAndLoss ('1', @ReportType, @FromDate, @ToDate, @CompCode)a      
                On a1.Code = a.Code and a1.Type = a.Type and a1.Path = a.Path and a1.Master = a.Master           
            Left Outer Join COM_BudgetMaster_dtl b            
                On b.BudgetFor = @BudgetFor and  a1.Code = b.Code and a1.Type = b.Type and a1.Path = b.Path              
            Left Outer Join EmployeeDetails c On b.RespID = c.EmployeeCode  
            Where b.FromDate = @FromDate and b.ToDate <= @ToDate and b.CompID+b.BranchID = @CompCode  
            Order By a1.SortOrder, a1.Path, a1.Type, Isnull(a.Particulars,a1.Particulars)  
    END  
    
    SET ARITHABORT OFF;  
END 
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_RcptVrSummary]    Script Date: 17/06/2026 11:30:12 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_RcptVrSummary] (@LrCode int, @VrRoute varchar(42), @RptDate Datetime, @CmCode varchar(12)) 

AS

Begin

	SET NOCOUNT ON

	
	

	Select P.BillIndex, P.VTNo, Case isNull(P.RefNo, '') When '' then 'On Acct' Else P.RefNo End as RefNo, P.RefDate, P.InvAmt, P.RcptAmt, Case P.PendingAmt When 0 then '' else Convert(varchar, P.PendingAmt) End as PendingAmt, 
		Q.Shortage, Q.Rejection, Q.RateDiff, Q.Excess, Q.Others
	 from
		(Select a.BillIndex, a.VTNo, a.RefNo, a.RefDate, 
			(Select b.Amount from FAS_BillDetails b 
				Where b.RefNo=a.RefNo and b.LrCode=@LrCode and b.Type = 'New Ref' and b.CompCode=@CmCode
			) as InvAmt,
			a.Amount as RcptAmt,
			(Select z.Amount 
			from fas_billdetails y, (Select RefNo, Sum(Amount) as Amount from fas_billdetails
						where RefNo <> '' and RefDate <= Convert(datetime, @RptDate, 111) and LrCode=@LrCode and CompCode=@CmCode
						group by RefNo ) z 
			where y.RefNo=a.RefNo and y.Type = 'New Ref' and y.RefNo=z.RefNo and y.LrCode=@LrCode and y.CompCode=@CmCode
			) as PendingAmt
		from FAS_BillDetails a 
		where a.vroute=@VrRoute and LrCode=@LrCode and a.CompCode=@CmCode 
		) P
		Left Outer Join
		(Select RefNo, Sum(Shortage) as Shortage, Sum(Rejection) as Rejection, Sum(RateDiff) as RateDiff, Sum(Excess) as Excess, Sum(Others) as Others 
		from (Select RefNo, Case When ReasonCode=1 then Amount End as Shortage, Case When ReasonCode=2 then Amount End as Rejection,
				Case When ReasonCode=3 then Amount End as RateDiff, Case When ReasonCode=5 then Amount End as Excess,
				Case When ReasonCode=4 then Amount End as Others
		        from (Select RefNo, ReasonCode, Amount 
			   from FAS_Reasondetails 
			   where Route=@VrRoute and CompCode=@CmCode  ) a ) b Group by RefNo 
		)Q
		On P.RefNo=Q.RefNo
	Order by Billindex
End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_RG_0]    Script Date: 17/06/2026 11:30:12 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_RG_0] (@IsDocwise bit, @Userkey varchar(36), @VrRoute varchar(42), @Start as datetime, @End as datetime, @PrStart as datetime, @PrEnd as datetime,  @CmCode as varchar(12))

 AS

Begin
	SET NOCOUNT ON

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	If @IsDocwise = '1' 	--Document wise

		Select DocDate, DocNo, VTSNo, LrCode, Voucher_Route, Ledger_Route, LedgerName, Convert(varchar, isNull(DrAmt, 0)) as DrAmt, Convert(varchar, isNull(CrAmt, 0)) as CrAmt, Ref, Narration
		From FAS_VrDetails_vw
		Where (DocDate Between @Start and @End) and Left(Voucher_Route,len(@VrRoute))=@VrRoute 	
			and DocNo in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID)
			and CompCode = @CmCode	
		Order by DocDate, DocNo, VTSNo, LedgerName
	Else --Party wise
		SELECT DocDate, DocNo, VTSNo, LrCode, Voucher_Route, Ledger_Route, LedgerName, Convert(varchar, isNull(DrAmt, 0))  as DrAmt, Convert(varchar,  isNull(CrAmt, 0))  as CrAmt,Ref, Narration
		From FAS_VrDetails_vw
		Where (DocDate Between @Start and @End) and Left(Voucher_Route,len(@VrRoute))=@VrRoute 	
			and DocNo in ( Select distinct DocNo From FAS_VrDetails_Vw Where DocDate Between @Start and @End
						and Left(Voucher_Route,len(@VrRoute))=@VrRoute and CompCode =@CmCode
						and LrCode in (Select SelectStr From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompID = @CompID)
				          )
			and CompCode = @CmCode	
		Order by DocDate, DocNo, VTSNo, LedgerName

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_RG_Sum]    Script Date: 17/06/2026 11:30:12 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_RG_Sum] (@isDocwise bit,  @UserKey varchar(36), @VrRoute varchar(42),  @Start as datetime, @End as datetime, @PrStart as datetime, @PrEnd as datetime, @CmCode as varchar(12))

 AS

Begin

	SET NOCOUNT ON	

	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)
	
	if @isDocwise = '1'
		Select Sum(a.Amount) as TotAmt	
		from FAS_VoucherTranMast a 
		where (a.DocDate Between @Start and @End) and a.VrRoute=@VrRoute 
		and a.DocNo in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
		and a.CompCode = @CmCode
	Else
		Select Sum(TotAmt) as TotAmt 
		From (
			Select distinct VrAmt as TotAmt	
			from FAS_Voucher_Vw a 
			where (a.DocDate Between @Start and @End) and a.VrRoute=@VrRoute 
			and a.LrCode in (Select SelectStr From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
			and a.CompCode = @CmCode
		         )	x		

End
GO

