CREATE PROCEDURE [dbo].[FAS_Rpt_RGsum_0] (@IsDocwise bit, @UserKey varchar(36), @VrRoute varchar(42), @Start as datetime, @End as datetime, @PrStart as datetime, @PrEnd as datetime, @CmCode as varchar(12))

 AS

Begin

	SET NOCOUNT ON
	
	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	
	If Left(@isDocwise, 1) = '1'
		Select a.DocDate, a.DocNo, a.VrRoute, Case When a.isCancelled='1' Then 'CANCELLED' Else c.LedgerName End as LedgerName, a.Ref, Convert(varchar, a.Amount) as VrAmt	
		from fas_VoucherTranMast a Left Outer Join fas_VoucherTranSub b
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
				Left Outer Join FAS_LedgerMaster c
					On b.LrCode=c.LedgerCode and b.CompCode=c.CompCode				
		where (a.DocDate Between @Start and  @End) and a.VrRoute=@VrRoute and isNull(b.VTSNo, 1)=1 
			and a.DocNo in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
			and a.CompCode = @CmCode 
		order by a.DocDate, a.DocNo, c.LedgerName

	Else
		Select a.DocDate, a.DocNo, a.VrRoute, Case When a.isCancelled='1' Then 'CANCELLED' Else c.LedgerName End as LedgerName, a.Ref, Convert(varchar, a.Amount) as VrAmt	
		from fas_VoucherTranMast a Left Outer Join fas_VoucherTranSub b
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
				Left Outer Join FAS_LedgerMaster c
					On b.LrCode=c.LedgerCode and b.CompCode=c.CompCode				
		where (a.DocDate Between @Start and  @End) and a.VrRoute=@VrRoute and isNull(b.VTSNo, 1)=1 
			and c.LedgerCode in (Select SelectStr From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
			and a.CompCode = @CmCode 
		order by a.DocDate, a.DocNo, c.LedgerName

	End
GO

