CREATE PROCEDURE [dbo].[FAS_Rpt_RnP_Cmp_Det] (@UserKey varchar(36), @Start datetime, @PrStart datetime, @PrEnd datetime, @Rcpt as int, @CmCode varchar(12))

AS

	Set NOCOUNT ON

	BEGIN

		Declare @BranchID varchar(2)
		Select @BranchID = SubString(@CmCode, 3, 2)
		
		Declare @CompID varchar(2)
		Select @CompID = Left(@CmCode, 2)
		
		Declare @Start2 as datetime, @Start3 as datetime, @Start4 as datetime
		Declare @End1 as datetime, @End2 as datetime, @End3 as datetime, @End4 as datetime
	
		Select @Start2 = DateAdd(Month, 1, @Start), @Start3 = DateAdd(Month, 2, @Start), @Start4 = DateAdd(Month, 3, @Start)
		Select @End1 = DateAdd(Day, -1, @Start2), @End2 = DateAdd(Day, -1, @Start3), @End3 = DateAdd(Day, -1, @Start4), @End4 = DateAdd(Day, -1, DateAdd(Month, 4, @Start))
	
		Select d.LrName, Case When @Rcpt*DrAmt1 > 0 then Convert(varchar, @Rcpt*DrAmt1) else Convert(varchar, 0) End as Amt1,
				  Case When @Rcpt*DrAmt2 > 0 then Convert(varchar, @Rcpt*DrAmt2) else Convert(varchar, 0) End as Amt2,
				  Case When @Rcpt*DrAmt3 > 0 then Convert(varchar, @Rcpt*DrAmt3) else Convert(varchar, 0) End as Amt3,
				  Case When @Rcpt*DrAmt4 > 0 then Convert(varchar, @Rcpt*DrAmt4) else Convert(varchar, 0) End as Amt4
		from
	
	
			(Select  c.LedgerName as LrName, Sum(DrAmt1) as DrAmt1, Sum(DrAmt2) as DrAmt2, Sum(DrAmt3) as DrAmt3, Sum(DrAmt4) as DrAmt4 
				from
					(Select LrCode,  Case  when DocDate between @Start and @End1 then (CrAmt - DrAmt) Else 0 End as DrAmt1,
							Case  when DocDate between @Start2 and @End2 then (CrAmt - DrAmt) Else 0 End as DrAmt2,
							Case  when DocDate between @Start3 and @End3 then (CrAmt - DrAmt) Else 0 End as DrAmt3,
							Case  when DocDate between @Start4 and @End4 then (CrAmt - DrAmt) Else 0 End as DrAmt4				
						From FAS_Voucher_Vw a
						Where Exists 
								(Select * From FAS_VoucherTranSub a1
								Where a1.DocNo=a.DocNo and a1.DocDate=a.DocDate and a1.VrRoute=a.VrRoute
									and LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
									 and CompCode=@CmCode) 
						and LrCode not in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
						and  (DocDate Between @Start and @End4) and CompCode=@CmCode 
					) b Left Outer Join FAS_LedgerMaster c
					On b.LrCode=c.LedgerCode 
					Where c.CompCode=@CmCode 	
				group by lrcode, c.LedgerName
				) d
			Where (@Rcpt*DrAmt1 > 0) or (@Rcpt*DrAmt2 > 0) or (@Rcpt*DrAmt3 > 0 ) or (@Rcpt*DrAmt4 > 0)
			Order by LrName

	END
GO

