CREATE PROCEDURE [dbo].[FAS_Rpt_RnP_Cr_BRS] (@UserKey varchar(36), @Start datetime, @End datetime, @Status char(2),  @PrStart datetime, @PrEnd datetime, @CmCode Varchar(12))

AS

BEGIN

	Set NOCOUNT ON
	
	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	--@Status 11-From, To Both Date given; 00 From & To may be any; 01 From may be any but To Date specified; 10 To Date may be any but From Date specified
	Declare @From datetime, @To datetime
	Select @From=Case Left(@Status, 1) when '0' then (Select Min(DocDate) from Fas_VoucherTranMast where CompCode=@CmCode) Else @Start End 
	Select @To=Case Right(@Status, 1) when '0' then (Select Max(DocDate) from Fas_VoucherTranMast where CompCode=@CmCode) Else @End End

	Select c.LrCode, (Select LedgerName from FAS_LedgerMaster Where LedgerCode=c.LrCode and CompCode=@CmCode) as LrName, Sum(c.CrAmt) as Credit 
	from (
		Select a.LrCode, a.CrAmt, Case when PayMode in ('',  'Cash') then a.DocDate else b.BankDate end DocDate
		From FAS_Voucher_Vw a 
		Left Outer Join FAS_VoucherTranPay b
		On a.DocNo = b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
		Where Exists
				(Select * From FAS_VoucherTranSub a1
				 Where a1.DocNo=a.DocNo and a1.DocDate=a.DocDate and a1.VrRoute=a.VrRoute 
					and LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
				 	and CompCode=@CmCode) 
			and a.CrAmt <> 0 and a.LrCode Not in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID) 
			and (a.DocDate <= @To) and a.CompCode=@CmCode 
		) c
		where c.DocDate between @From and @To

	Group by c.LrCode 
	Order by 2


END
GO

