CREATE PROCEDURE [dbo].[FAS_Rpt_RnP_Dr] (@UserKey varchar(36), @Start datetime, @End datetime, @Status char(2),  @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

BEGIN

	Set NOCOUNT ON	
	
	Declare @BranchID varchar(2)
