/****** Object:  StoredProcedure [dbo].[FAS_Rpt_RnP_Over_Sum]    Script Date: 17/06/2026 11:30:12 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_RnP_Over_Sum] (@UserKey varchar(36), @isRealisedAmtOnly bit, @FinStart datetime, 
@FinEnd datetime, @Pymt as int, @Route char(4), @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))  
  
AS  
 Set NOCOUNT ON  
  
 Declare @BranchID varchar(2)  
 Select @BranchID = SubString(@CmCode, 3, 2)  
   
 Declare @CompID varchar(2)  
 Select @CompID = Left(@CmCode, 2)   
  
 Select  LrName,  OpBal, sTotAmt,  rTotAmt, CrAmt, DrAmt, OtherAmt, BrsCB, VrCB,  BrsDiff  
 From   
 (Select h.LedgerName as LrName, Convert(varchar, h.OpBal) as OpBal, Convert(varchar, h.sTotAmt) as sTotAmt, Convert(varchar, h.rTotAmt) as rTotAmt,   
  Convert(varchar, h.CrAmt) as CrAmt, Convert(varchar, h.DrAmt) as DrAmt, Convert(varchar, h.OtherAmt) as OtherAmt,   
  Convert(varchar, @Pymt*(h.OpBal+h.sTotAmt+h.rTotAmt+(@Pymt*h.CrAmt)+(@Pymt*h.DrAmt)+h.OtherAmt)) as BrsCB,  
  Convert(varchar, h.OpBal+h.TrAmt) as VrCB , Convert(varchar, @Pymt*(h.sTotAmt+h.rTotAmt+(@Pymt*h.CrAmt)+(@Pymt*h.DrAmt)+h.OtherAmt-h.TrAmt)) as BrsDiff  
 from  
  (Select isNull(f.LedgerName, g.LedgerName) as LedgerName, isnull(g.OpBal, 0) OpBal, @Pymt*isnull(Sum(f.sTotAmt), 0) as sTotAmt, @Pymt*isnull(Sum(f.rTotAmt), 0) as rTotAmt, isnull(Sum(f.CrAmt), 0) as CrAmt, isnull(Sum(f.DrAmt),0) as DrAmt,   
  @Pymt*isnull(Sum(f.OtherAmt), 0) as OtherAmt, @Pymt*isnull(Sum(f.TrAmt), 0) as TrAmt  
  from  
    (Select e.LrCode, e.LedgerName,    
      Case When Rte in ('0B', '0K') then VrAmt Else 0 End as sTotAmt,  
      Case When Rte in ('09', '0F') Then Case When PayMode in ('Cheque', 'Draft') then   
        Case When e.BankDate is Not Null then  VrAmt Else 0 End Else VrAmt End Else 0 End as rTotAmt,  
      Case When Rte = '02' then VrAmt Else 0 End as CrAmt,  
      Case When Rte = '03' then VrAmt Else 0 End as DrAmt,  
      Case When Rte not in ('0B', '0K', '09', '0F', '02', '03') then VrAmt Else 0 End as OtherAmt,  
      VrAmt as TrAmt       
    from  
  
  
     (Select d.LedgerName, a.LrCode, (a.DrAmt - a.CrAmt) as VrAmt, b.DocDate, Left(a.VrRoute, 2) as Rte, c.BankDate, b.PayMode  
     from FAS_VoucherTranSub a Join FAS_VoucherTranMast b  
     On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode  
      Join FAS_LedgerMaster d  
      On a.LrCode=d.LedgerCode and a.CompCode=d.CompCode  
       Left Outer Join FAS_VoucherTranPay c  
       On a.DocNo=c.DocNo and a.DocDate=c.DocDate and a.VrRoute=c.VrRoute and a.CompCode=c.CompCode   
     Where  (b.DocDate Between @FinStart and @FinEnd)  and  Left(d.LrRoute, 4) = @Route  
     and a.LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)  
      and a.CompCode=@CmCode  
     ) e  
    )f  
   Full Outer Join (Select LedgerCode, LedgerName, @Pymt*OpBalance as OpBal 
   from dbo.fn_FAS_AllOpBalance(@FinStart, @isRealisedAmtOnly, '0', @CmCode) where OpBalance<>0 and Left(LrRoute, 4)=@Route and CompCode=@CmCode) g  
   On f.LrCode=g.LedgerCode  
  Group by isNull(f.LedgerName, g.LedgerName), g.OpBal  
  ) h   
 )x   
 Order by LrName
GO

