CREATE PROCEDURE [dbo].[FAS_Rpt_RnP_Reg_Det] (@UserKey varchar(36), @Start datetime, @Rcpt as int, @Path as varchar(42), @PrStart datetime, @PrEnd datetime,  @CmCode varchar(12))

AS

	Set NOCOUNT ON
	
	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	Declare @Start2 as datetime, @Start3 as datetime, @Start4 as datetime, @Start5 as datetime, @Start6 as datetime
	Declare @End1 as datetime, @End2 as datetime, @End3 as datetime, @End4 as datetime, @End5 as datetime, @End6 as datetime

	Select @Start2 = DateAdd(Month, 1, @Start), @Start3 = DateAdd(Month, 2, @Start), @Start4 = DateAdd(Month, 3, @Start), @Start5 = DateAdd(Month, 4, @Start), @Start6 = DateAdd(Month, 5, @Start)
	Select @End1 = DateAdd(Day, -1, DateAdd(Month, 1, @Start)), @End2 = DateAdd(Month, 1, @End1), @End3 = DateAdd(Month, 2, @End1), @End4 = DateAdd(Month, 3, @End1), @End5 = DateAdd(Month, 4, @End1), @End6 = DateAdd(Month, 5, @End1)


	Select f.LedgerName as LrName, Convert(varchar, @Rcpt*Sum(f.Amt1)) as Amt1, Convert(varchar, @Rcpt*Sum(f.Amt2)) as Amt2, Convert(varchar, @Rcpt*Sum(f.Amt3)) as Amt3, 
		Convert(varchar, @Rcpt*Sum(f.Amt4)) as Amt4, Convert(varchar, @Rcpt*Sum(f.Amt5)) as Amt5, Convert(varchar, @Rcpt*Sum(f.Amt6)) as Amt6, Convert(varchar, @Rcpt*Sum(f.TotAmt)) as TotAmt
	from
		(Select e.LedgerName, Case When e.BankDate is Not Null then Case  when DocDate between @Start and @End1 then (VrAmt) Else 0 End  Else 0 End as Amt1,
				Case When e.BankDate is Not Null then Case  when DocDate between @Start2 and @End2 then (VrAmt) Else 0 End  Else 0 End as Amt2,
				Case When e.BankDate is Not Null then Case  when DocDate between @Start3 and @End3 then (VrAmt) Else 0 End  Else 0 End as Amt3,
				Case When e.BankDate is Not Null then Case  when DocDate between @Start4 and @End4 then (VrAmt) Else 0 End  Else 0 End as Amt4,
				Case When e.BankDate is Not Null then Case  when DocDate between @Start5 and @End5 then (VrAmt) Else 0 End  Else 0 End as Amt5,
				Case When e.BankDate is Not Null then Case  when DocDate between @Start6 and @End6 then (VrAmt) Else 0 End  Else 0 End as Amt6,
				Case When e.BankDate is Not Null then  (VrAmt) Else 0 End as TotAmt					
		from
			(Select d.LedgerName, a.LrCode, (a.DrAmt - a.CrAmt) as VrAmt, b.DocDate, c.BankDate
			from FAS_VoucherTranSub a Join FAS_VoucherTranMast b
			On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.VrRoute=b.VrRoute and a.CompCode=b.CompCode
				Join FAS_LedgerMaster d
				On a.LrCode=d.LedgerCode and a.CompCode=d.CompCode
					Left Outer Join FAS_VoucherTranPay c
					On a.DocNo=c.DocNo and a.DocDate=c.DocDate and a.VrRoute=c.VrRoute and a.CompCode=c.CompCode 
			Where Left(a.VrRoute, Len(@Path))=@Path and (b.DocDate Between @Start and @End6)  --and  Left(d.LrRoute, 4) in ('0206', '0303') 			
			and LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchId = @BranchID and CompId = @CompID)
			and a.CompCode=@CmCode
			) e
		) f
	Group by f.LedgerName
	Order by LedgerName
GO

/****** Object:  StoredProcedure [dbo].[FAS_Rpt_TB_New]    Script Date: 17/06/2026 11:30:12 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_Rpt_TB_New] (@Start datetime, @End datetime, @FinStart datetime,  @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))

AS

Begin
	SET NOCOUNT ON	
	
	
Select * 
	from  (
		Select Master, Path, Type, Case Type when 'Group' then Space(Len(Path)) + M.Name
						        when 'OpBal' then Space(Len(Path)) + M.Name
		                                                             when 'Ledger' then space(Len(Path)) + '    ' + M.Name End as Particulars, 
					   Case sign(amt1) when -1 then -Amt1 else 0 end as DrGr, Case sign(amt1) when 1 then Amt1 else 0 end as CrGr
		From (
			Select l.Master, 'Ledger' as Type, k.Name, ((Case when Left(k.LrRoute, 2) in ('0E', '0D', '05', '06', '07', '08') then Case when @Start=@FinStart then k.OpBalance else 0 end else k.OpBalance end) + k.Amt1) as Amt1, k.LrRoute as Path
			from

			(
				Select a.LrRoute, a.LedgerCode, a.LedgerName as Name , a.OpBalance, Sum(b.CrAmt-b.DrAmt) as Amt1
				from FAS_LedgerMaster a Left Outer Join FAS_Voucher_vw b
				On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode
				where Len(a.LrRoute)=2 and b.DocDate between Case When a.LrRoute in ('0E', '0D', '05', '06', '07', '08') then @Start else @FinStart end and @End and a.compcode=@CmCode
				group by a.LrRoute, a.LedgerCode, a.LedgerName, a.OpBalance 

			) k  Left Outer Join FAS_GroupMaster l
			On k.LrRoute = l.GrRoute+l.GrWidth
			Where l.CompCode=@CmCode
			
			Union All
			
			Select m.Master, 'Group' as Type, m.GroupName as Name, Sum(n.OpBalance+n.Amt1) as Amt1, m.GrRoute+m.GrWidth as Path
			from Fas_GroupMaster m Right Outer join
				(
				Select LrRoute, LedgerCode, OpBalance,
				isNull((Select Sum(b.CrAmt-b.DrAmt) from fas_Voucher_vw b where b.LrCode=a.LedgerCode and b.DocDate between Case when Left(a.LrRoute, 2) in ('0E', '0D', '05', '06', '07', '08') then @Start else @FinStart end and @End and b.CompCode=@CmCode), 0) Amt1
				from FAS_LedgerMaster a
				where Compcode=@CmCode
	
				) n
			On m.GrRoute+m.GrWidth=Left(n.LrRoute, Len(m.GrRoute+m.GrWidth))
			where Len(m.GrRoute) <= 2 and m.CompCode=@CmCode
			group by  m.Master, m.GroupName, m.GrRoute+m.GrWidth

		Union All

/*

			Select '04', 'Group', 'Profit & Loss A/c', Sum(Amount) as Amount, 'yy'
			from
				(Select isNull(p.LedgerCode, a.LrCode) LrCode, p.Route as LrRoute, (isnull(a.Amount,0)+ p.OpBalance) as Amount
				from FAS_LedgerMaster p Full Outer Join
					(Select LrCode, (sum(CrAmt)-sum(DrAmt)) as Amount from FAS_Voucher_Vw 
					where VTDate between @FinStart and DateAdd(day, -1, @PrStart) and Compcode = @CmCode 
					group by LrCode 
				) a 
				On p.LedgerCode=a.LrCode Where p.CompCode=@CmCode
			) b
			where (b.LrRoute='' or Left(b.LrRoute, 2) in ('0D', '0E', '05', '06', '07', '08'))
*/
			Select '04', 'Group', 'Profit & Loss A/c OB', p.OpBalance+q.TranAmt as Amount, 'yy'
			from FAS_LedgerMaster p Left Outer Join
				(
				Select isNull(Sum(CrAmt-DrAmt), 0) as TranAmt, CompCode
				from FAS_VoucherTranSub
				where LrCode=2 and CompCode=@CmCode
				group by CompCode
				) q
			On p.CompCode=q.CompCode 
			where p.LedgerCode=2 and p.CompCode=@CmCode

		Union All
	
			Select '05', 'OPBal', 'Diff. in Opening Balance', -Sum(OpBalance) as Amt1, 'zz'
			from FAS_LedgerMaster 
			where Compcode = @CmCode
		    ) M
	) Z
	Where DrGr+CrGr <> 0
	Order by Master, Left(Path, 2), Type, Path

End
GO

