CREATE PROCEDURE [dbo].[FAS_Rpt_Vr_0] (@Userkey varchar(36), @VrRoute varchar(42), @Start as datetime, @End as datetime, @PrStart as datetime, @PrEnd as datetime, @CmCode as varchar(12))

 AS
	
Begin
	SET NOCOUNT ON
	
	Declare @BranchID varchar(2)
	Select @BranchID = SubString(@CmCode, 3, 2)
	
	Declare @CompID varchar(2)
	Select @CompID = Left(@CmCode, 2)

	SELECT DocDate, DocNo, LrCode, Ledger_Route, LedgerName, Convert(varchar, DrAmt) as DrAmt, Convert(varchar, CrAmt) as CrAmt, Narration
	from FAS_VrDetails_vw
	where (Docdate Between @Start and @End)  and LrCode in (Select SelectInt From Com_SelectList Where UserKey = @UserKey and BranchID = @BranchID and CompId = @CompID)
	and Voucher_Route=@VrRoute and VTSNo=1 and CompCode = @CmCode
	order by Docdate, Docno, Ledger_Route, ledgername

End
