/****** Object:  StoredProcedure [dbo].[FAS_ScheduleGroup_Period_Rpt]    Script Date: 17/06/2026 11:30:13 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_ScheduleGroup_Period_Rpt](@PeriodStart datetime, @NoOfSplit int, @GroupBy varchar(5), @OrderByDesc bit, @isExpandAll bit, @isShowZeroCB bit, @SuppliedClosingStock money, @CmCode varchar(12))    
AS     
BEGIN    
  SET NOCOUNT ON;    
      
  /* Use this Description as Ledger Name for negative Ledger Codes    
   Code  Description    
   -1   'P & L OPENING BALANCE'    
   -2   'P & L CURRENT PERIOD'    
   -3   'P & L TRANSFERED'    
   -4   'OPENING STOCK'    
   -5   'CLOSING STOCK'    
   -6   'DEPRECIATION CURRENT PERIOD'    
   -7   'DEPRECIATION CUMULATIVE'      
  */    
     
     
 /* Trial Balance Split up Data get Stored in this Table */    
  DECLARE @TMP_Ledger TABLE  
 (    
  [LrCode] [int],    
  [AsOnYear] [int],    
  [AsOnPeriod] [int],    
  [DrAmt] [money],    
  [CrAmt] [money],    
  [SortOrder] [int],    
  [CompCode] [varchar](12)    
 ) --ON [PRIMARY]    
     
     
 /* Split up Period in this Table */    
  DECLARE @TMP_Period  TABLE  
 ( [Seq] [int],    
  [PrStart] [datetime],    
  [PrEnd] [datetime]    
 ) --ON [PRIMARY]    
     
 Declare @PeriodEnd datetime    
     
 DECLARE @tmpCnt int, @tmpStart datetime, @tmpEnd datetime    
     
 If @GroupBy='YEAR'    
  BEGIN         
   If Month(@PeriodStart)<=3    
    SET @tmpEnd=Convert(datetime, Convert(varchar, Year(@PeriodStart))+'0331', 112)    
   Else    
    SET @tmpEnd=Convert(datetime, Convert(varchar, Year(@PeriodStart)+1)+'0331', 112)    
        
   SET @tmpStart=@PeriodStart    
       
   INSERT INTO @TMP_Period    
      Select @tmpCnt, @tmpStart, @tmpEnd    
           
   SET @tmpCnt=1    
       
   WHILE @tmpCnt < @NoOfSplit    
    BEGIN    
         
     SET @tmpStart=DateAdd(day, 1, @tmpEnd)    
     SET @tmpEnd=DateAdd(day, -1, DateAdd(mm, 12, @tmpStart))    
         
     INSERT INTO @TMP_Period    
      Select @tmpCnt, @tmpStart, @tmpEnd    
         
     SET @tmpCnt = @tmpCnt + 1    
    END      
  END      
 Else    
 If @GroupBy='MONTH'    
  BEGIN              
   SET @tmpStart=@PeriodStart    
   SET @tmpEnd=Convert(datetime, Convert(varchar(6), @PeriodStart, 112)+'01', 112)    
   SET @tmpEnd=DateAdd(day, -1, DateAdd(mm, 1, @tmpEnd))    
       
   INSERT INTO @TMP_Period    
      Select @tmpCnt, @tmpStart, @tmpEnd    
              
   SET @tmpCnt=1    
       
   WHILE @tmpCnt < @NoOfSplit    
    BEGIN    
        
     SET @tmpStart=DateAdd(day, 1, @tmpEnd)    
     SET @tmpEnd=DateAdd(day, -1, DateAdd(mm, 1, @tmpStart))    
         
     INSERT INTO @TMP_Period    
      Select @tmpCnt, @tmpStart, @tmpEnd    
         
     SET @tmpCnt = @tmpCnt + 1    
         
    END      
  END      
 Else    
 If @GroupBy='WEEK'    
  BEGIN    
   SET @tmpStart=@PeriodStart    
   SET @tmpEnd = DateAdd(day, 7-DatePart(w, @PeriodStart), @PeriodStart)    
       
   INSERT INTO @TMP_Period    
      Select @tmpCnt, @tmpStart, @tmpEnd    
          
   SET @tmpCnt=1    
       
   WHILE @tmpCnt < @NoOfSplit    
    BEGIN    
         
     SET @tmpStart=DateAdd(day, 1, @tmpEnd)    
     SET @tmpEnd=DateAdd(day, -1, DateAdd(wk, 1, @tmpStart))    
         
     INSERT INTO @TMP_Period    
      Select @tmpCnt, @tmpStart, @tmpEnd    
         
     SET @tmpCnt = @tmpCnt + 1    
    END      
   END    
 Else    
 If @GroupBy='DAY'    
   SET @tmpStart=@PeriodStart    
   SET @tmpEnd = @tmpStart    
       
   INSERT INTO @TMP_Period    
      Select @tmpCnt, @tmpStart, @tmpEnd    
          
   SET @tmpCnt=1    
       
   WHILE @tmpCnt < @NoOfSplit    
    BEGIN    
         
     SET @tmpStart=DateAdd(day, 1, @tmpEnd)    
     SET @tmpEnd=@tmpStart    
         
     INSERT INTO @TMP_Period    
      Select @tmpCnt, @tmpStart, @tmpEnd    
         
     SET @tmpCnt = @tmpCnt + 1    
    END      
     
 SET @PeriodEnd=@tmpEnd    
     
    
 INSERT INTO @TMP_Ledger    
  Execute [FAS_TrialBalance_Period] @PeriodStart, @PeriodEnd, @GroupBy, @CmCode    
    
    
 Delete From @TMP_Ledger From @TMP_Ledger a  
 Where Exists (Select * from FAS_LedgerMaster b Where b.LrRoute Like '0205%' and a.LrCode=b.LedgerCode and a.CompCode=b.CompCode)    
    
/*    
 Insert into @TMP_Ledger     
  Select LedgerCode, Year(@PeriodStart), Convert(int, Convert(varchar(8), @PeriodStart, 112)),    
   Case When OpBalance > 0 Then OpBalance Else 0 End, Case When OpBalance <= 0 Then OpBalance Else 0 End, 0, @CmCode    
  from dbo.fn_FAS_AllOpBalance(@PeriodStart, '0', '1', @CmCode) a     
*/    
    
    
    
 Declare @Amt1 money, @Amt2 money    
 Declare @isDataFound bit    
     
 SET @tmpCnt=1    
 WHILE (@tmpCnt<=@NoOfSplit)    
  BEGIN    
   Select @tmpStart=PrStart, @tmpEnd=PrEnd From @TMP_Period Where Seq=@tmpCnt    
       
   /* BEGIN - To insert Profit & Loss A/c Details */    
   /* Opening Balance */    
   SET @Amt1=isNull(dbo.fn_FAS_Profit_Loss_OB(@tmpStart, @CmCode) , 0)    
       
   INSERT INTO @TMP_Ledger    
   Select -1, 0, 0, Case When @Amt1>=0 Then @Amt1 Else 0 End, Case When @Amt1<0 Then @Amt1 Else 0 End, 0, @CmCode    
    
       
   /* Current Period */    
   SET @Amt1=isNull(dbo.fn_FAS_Profit_Loss_Period(@tmpStart, @tmpEnd, @CmCode), 0)    
       
   INSERT INTO @TMP_Ledger    
   Select -2, 0, 0, Case When @Amt1>=0 Then @Amt1 Else 0 End, Case When @Amt1<0 Then @Amt1 Else 0 End, 0, @CmCode    
       
       
   /* Less Transferred */    
   Select @Amt1=(sum(DrAmt)-sum(CrAmt))    
    from FAS_VoucherTranSub     
    where (DocDate between @tmpStart and  @tmpEnd) and LrCode=2 and Compcode = @CmCode    
       
   INSERT INTO @TMP_Ledger    
   Select -3, 0, 0, Case When @Amt1>=0 Then @Amt1 Else 0 End, Case When @Amt1<0 Then @Amt1 Else 0 End, 0, @CmCode    
   /* END - To insert Profit & Loss A/c Details */    
       
    
   /* BEGIN - Opening Stock and Closing Stock Update */    
   --Declare @Amt1 money, @Amt2 money    
   Select @Amt1=Sum(OpeningStock), @Amt2=Sum(-ClosingStock) From dbo.fn_FAS_StockValue (@tmpStart, @tmpEnd, @CmCode)    
    
   INSERT INTO @TMP_Ledger    
   Select -4, 0, 0, Case When @Amt1>=0 Then @Amt1 Else 0 End, Case When @Amt1<0 Then @Amt1 Else 0 End, 0, @CmCode    
       
   INSERT INTO @TMP_Ledger    
   Select -4, 0, 0, Case When @Amt1>=0 Then @Amt1 Else 0 End, Case When @Amt2<0 Then @Amt1 Else 0 End, 0, @CmCode    
   /* END - Opening Stock and Closing Stock Update */    
    
/*    
   /* Depreciation Value Update */      
         
     /* DEPRECIATION CURRENT PERIOD */    
     SELECT @Amt1=0, @Amt2=0    
     If @FixedAssetFromCalculation='1'    
    BEGIN    
       Select @Amt1=Sum(CurrentDepreciation) From FAS_DepreciationProcess     
       Where Left(CompCode, 4)=Left(@CmCode, 4) and ((FromDate Between @PeriodStart and @PeriodEnd) and (ToDate Between @PeriodStart and @PeriodEnd))    
           
       If isNull(@Amt1, 0)=0    
      SET @isDataFound='0'    
       Else    
      SET @isDataFound='1'    
    END    
         
     IF @FixedAssetFromCalculation='0' OR @isDataFound='0'    
    Select @Amt1=Sum(a.CrAmt-a.DrAmt)    
    From FAS_VoucherTranSub a     
    Where a.CompCode=@CmCode and a.LrCode in (Select LrCode From FAS_ScheduleGroup b Where b.LrCode=a.LrCode and b.SchCode=-222 and b.CompCode=a.CompCode)    
     and a.DocDate Between @PeriodStart and @PeriodEnd    
         
     Update @TMP_Schedule Set Amount=isNull(@Amt1, 0)    
     Where SchLrCode=-6 and EntryType='LED'    
         
     /* DEPRECIATION CUMULATIVE */    
     If @FixedAssetFromCalculation='1'    
    BEGIN    
       Select @Amt2=Sum(CurrentDepreciation) From FAS_DepreciationProcess     
       Where Left(CompCode, 4)=Left(@CmCode, 4) and ToDate < @PeriodStart    
           
       If isNull(@Amt2, 0)=0    
      SET @isDataFound='0'    
       Else    
      SET @isDataFound='1'    
     END    
         
     IF @FixedAssetFromCalculation='0' OR @isDataFound='0'    
    Select @Amt2=Sum(a.DrAmt-a.CrAmt)    
    From FAS_VoucherTranSub a     
    Where a.CompCode like Left(@CmCode, 4)+'%' and a.LrCode in (Select LrCode From FAS_ScheduleGroup b Where b.LrCode=a.LrCode and b.LrCode>0 and b.SchCode=-222 and b.CompCode=a.CompCode)    
     and a.DocDate < @PeriodStart    
         
     Update @TMP_Schedule Set Amount=(isNull(@Amt1, 0)+isNull(@Amt2, 0))    
     Where SchLrCode=-7 and EntryType='LED'    
         
         
     /* FIXED ASSET GROSS BLOCK */    
     Declare @Gross money    
     If @FixedAssetFromCalculation='1'    
    BEGIN       
       Select @Gross=Sum(OpBalance) From FAS_DepreciationMaster    
       Where Left(CompCode, 4)=Left(@CmCode, 4) and OpBalDate <= @PeriodEnd    
           
       If isNull(@Gross, 0)=0    
      SET @isDataFound='0'    
       Else    
      SET @isDataFound='1'    
    END    
        
     IF @FixedAssetFromCalculation='0' OR @isDataFound='0'    
    BEGIN    
     Select @Gross=Sum(a.DrAmt-a.CrAmt)    
     From FAS_VoucherTranSub a     
     Where a.CompCode=@CmCode and a.LrCode in (Select LrCode From FAS_ScheduleGroup b Where b.LrCode=a.LrCode and b.SchCode=-111 and b.CompCode=a.CompCode)    
      and a.DocDate <= @PeriodEnd    
          
     SET @Gross=isNull(@Gross, 0)+(isNull(@Amt1, 0)+isNull(@Amt2, 0))       
    END    
        
     Update @TMP_Schedule Set Amount=isNull(@Gross, 0)    
     Where SchLrCode=-8 and EntryType='LED'      
    
   /* END - Depreciation Value Update */     
    
*/    
    
    
   SET @tmpCnt = @tmpCnt+1    
  END    
    
    
 If @OrderByDesc=Convert(bit, '1')    
  BEGIN    
   DECLARE @MaxSort int    
   Select @MaxSort=Max(SortOrder) From @TMP_Ledger    
      
   Update @TMP_Ledger Set SortOrder=@MaxSort-SortOrder    
  END    
     
 Select * from @TMP_Ledger Where NOT (DrAmt=0 AND CrAmt=0) Order By LrCode, SortOrder    
     
END  
GO

/****** Object:  StoredProcedure [dbo].[FAS_ScheduleGroup_Period_SCH]    Script Date: 17/06/2026 11:30:13 ******/
SET ANSI_NULLS ON
