CREATE PROCEDURE [dbo].[FAS_ScheduleGroup_Period_SCH](@CmCode varchar(12))  
 As   
BEGIN  
  SET NOCOUNT ON;  
    
  /* Use this Description as Ledger Name for negative Ledger Codes  
   Code  Description  
   -1   'P & L OPENING BALANCE'  
   -2   'P & L CURRENT PERIOD'  
   -3   'P & L TRANSFERED'  
   -4   'OPENING STOCK'  
   -5   'CLOSING STOCK'  
   -6   'DEPRECIATION CURRENT PERIOD'  
   -7   'DEPRECIATION CUMULATIVE'    
  */  
   
 /* Trial Balance Split up Data get Stored in this Table */  
  DECLARE @TMP_Ledger TABLE  
 (  
  [SchCode] [int],  
  [SchLrCode] [int],  
  [SchLrName] [varchar](50),  
  [SchPath] [varchar](42),  
  [LrSeq] [int]  
 ) --ON [PRIMARY]  
   
 INSERT INTO @TMP_Ledger  
 Select SchCode, SchCode, SchLongName as SchName, SchRoute+SchWidth as SchPath, 0  
 From FAS_ScheduleMaster_vw   
 Where EffStatus='AA' and ByParentStatus='1' and CompCode=@CmCode   
 Union All    
 Select 0 as SchCode, 0, 'UNGROUPED' as SCHName, 'zz' as SchPath, 0  
   
 INSERT INTO @TMP_Ledger  
 Select isNull(b.SchCode, 0), LedgerCode, LedgerName,  '', isNull(b.GroupSeq, 1)  
 From (  
   Select LedgerCode, LedgerName, CompCode   
   From FAS_LedgerMaster   
   Where (LrRoute Not Like '0205%' and LedgerCode<>2) and CompCode = @CmCode   
   Union All   
   Select -1, 'P & L OPENING BALANCE', @CmCode   
   Union All   
   Select -2, 'P & L CURRENT PERIOD', @CmCode  
   Union All   
   Select -3, 'P & L TRANSFERED', @CmCode  
   Union All  
   Select -4, 'OPENING STOCK', @CmCode  
   Union All   
   Select -5, 'CLOSING STOCK', @CmCode   
   Union All   
   Select -6, 'DEPRECIATION CURRENT PERIOD', @CmCode   
   Union All   
   Select -7, 'DEPRECIATION CUMULATIVE', @CmCode  
  ) a   
 Left Outer Join FAS_ScheduleGroup b  
  On a.LedgerCode=b.LrCode and a.CompCode=b.CompCode  
 Where a.CompCode=@CmCode  
   
 UPDATE @TMP_Ledger Set SchPath=b.SchPath  
 FROM @TMP_Ledger a  
 Left Outer Join (Select * from @TMP_Ledger) b  
  On a.SchCode=b.SchCode  
 Where a.SchPath='' and b.SchPath<>''  
   
 Select * from @TMP_Ledger Order By SchPath, LrSeq  
   
END
GO

