CREATE PROCEDURE [dbo].[FAS_ScheduleGroup_Rpt](@RptType tinyint, @PeriodStart datetime, @PeriodEnd datetime, @FixedAssetFromCalculation bit, @Level int, @isShowZeroCB bit, @SuppliedOpeningStock money, @SuppliedClosingStock money, @CmCode varchar(12))    
/* @RptType = 0 -Profit & Loss Entries; 1 - BalanceSheet Entries; Other than 0 & 1 - All Schedules Entries */    
 As     
BEGIN    
    SET NOCOUNT ON;  
    
   DECLARE @TMP_Schedule TABLE  
   (    
     [SchLrCode] [int] NOT NULL,    
     [SchPath] [varchar](42) NOT NULL,    
     [SchLrName] [varchar](50) NOT NULL,    
     [Amount] [money] NOT NULL,    
     [isDebit] [bit] NOT NULL,    
     [isExpand] [bit] NOT NULL,    
     [Seq] [int] NOT NULL,    
     [EntryType] [varchar](3) NOT NULL    
    ) --ON [PRIMARY]    
     
     
    INSERT INTO @TMP_Schedule    
     Select 0, 'zz', 'UNGROUPED', 0, '1', '1', 1, 'SCH'    
        
    INSERT INTO @TMP_Schedule    
     Select a.SchCode, a.SchRoute+a.SchWidth as SchPath, a.SchLongName, 0, isDebitBalance, isExpand, a.Seq, 'SCH'    
       From FAS_ScheduleMaster_vw a    
       Where a.EffStatus='AA' and a.ByParentStatus='1' and a.CompCode=@CmCode    
     --and a.SchCode Not In (-111, -222)    
        --and a.SchRoute+a.SchWidth Not Like '05%' --'Fixed Assets'    
     
   INSERT INTO @TMP_Schedule    
     Select a.LedgerCode, isNull(d.SchPath, 'zz') as SchPath, a.LedgerName, isNull(b.ClosingBalance, 0) as CurrentCB,     
        isNull(d.isDebit, '1'), isNull(d.isExpand, '1'), isNull(d.Seq, 0), 'LED'    
      From  (    
         Select LedgerCode, LedgerName, CompCode     
         From FAS_LedgerMaster     
         Where (LrRoute Not Like '0205%' and LedgerCode<>2) and CompCode = @CmCode     
         Union All     
         Select -1, 'P & L OPENING BALANCE', @CmCode     
         Union All     
         Select -2, 'P & L CURRENT PERIOD', @CmCode    
         Union All     
         Select -3, 'P & L TRANSFERED', @CmCode    
         Union All    
         Select -4, 'OPENING STOCK', @CmCode    
         Union All     
         Select -5, 'CLOSING STOCK', @CmCode     
         Union All     
         Select -6, 'DEPRECIATION CURRENT PERIOD', @CmCode     
         Union All     
         Select -7, 'DEPRECIATION CUMULATIVE', @CmCode    
         Union All     
         Select -8, 'FIXED ASSET GROSS BLOCK', @CmCode    
         ) a     
      Left Outer Join dbo.fn_FAS_Rpt_TrialBalance('L', @PeriodStart, @PeriodEnd, @CmCode) b On b.Code = a.LedgerCode      
      Full Outer Join FAS_ScheduleGroup c On a.LedgerCode=c.LrCode and a.CompCode=c.CompCode    
      Left Outer Join @TMP_Schedule d On c.SchCode =d.SchLrCode     
      Where a.CompCode =@CmCode --and isNull(c.SchCode, 0) Not in (-111, -222)    
    
    
     /* Delete the Ledgers Grouped Under Fixed Asset and Depreciation Schedule */    
    
     Delete From @TMP_Schedule    
     Where SchPath in (Select SchPath From @TMP_Schedule b Where b.SchLrCode in (-111, -222) and EntryType='SCH')    
     and EntryType='LED' and SchLrCode>=0    
      
    
    Declare @Amt1 money, @Amt2 money    
      
    /* To insert Profit & Loss A/c Details */    
    
    /* Opening Balance */    
    Update @TMP_Schedule Set Amount=isNull(dbo.fn_FAS_Profit_Loss_OB_SCH(@PeriodStart, @SuppliedOpeningStock,  @SuppliedClosingStock, @CmCode) , 0)    
    Where SchLrCode=-1 and EntryType='LED'    
        
    /* Current Period */    
    Update @TMP_Schedule Set Amount=isNull(dbo.fn_FAS_Profit_Loss_Period_SCH(@PeriodStart, @PeriodEnd, @SuppliedOpeningStock, @SuppliedClosingStock, @CmCode), 0)    
    Where SchLrCode=-2 and EntryType='LED'    
        
    /* Less Transferred */    
    Select @Amt1=(sum(DrAmt)-sum(CrAmt))    
     from FAS_VoucherTranSub     
     where (DocDate between @PeriodStart and  @PeriodEnd) and LrCode=2 and Compcode = @CmCode    
        
    Update @TMP_Schedule Set Amount=isNull(@Amt1, 0)    
    Where SchLrCode=-3 and EntryType='LED'    
     
      
   /* Opening Stock and Closing Stock Update */    
    SELECT @Amt1=0, @Amt2=0    
  Select @Amt1=Sum(OpeningStock), @Amt2=Sum(-ClosingStock) From dbo.fn_FAS_StockValue (@PeriodStart, @PeriodEnd, @CmCode)    
      
  /* Opening Stock Update */    
   If @SuppliedOpeningStock >= 0    
    Update @TMP_Schedule Set Amount=isNull(@SuppliedOpeningStock, 0)    
     Where SchLrCode=-4 and EntryType='LED'    
   Else      
     Update @TMP_Schedule Set Amount=isNull(@Amt1, 0)    
     Where SchLrCode=-4 and EntryType='LED'    
    
   /* Closing Stock Update */    
    If @SuppliedClosingStock >= 0    
      Update @TMP_Schedule Set Amount=isNull(-@SuppliedClosingStock, 0)    
      Where SchLrCode=-5 and EntryType='LED'    
    Else    
      Update @TMP_Schedule Set Amount=isNull(@Amt2, 0)    
      Where SchLrCode=-5 and EntryType='LED'    
    
       
  /* Depreciation Value Update */      
    Declare @isDataFound bit    
      
  /* DEPRECIATION CURRENT PERIOD */    
    SELECT @Amt1=0, @Amt2=0    
    If @FixedAssetFromCalculation='1'    
   BEGIN    
      Select @Amt1=Sum(CurrentDepreciation) From FAS_DepreciationProcess     
      Where Left(CompCode, 4)=Left(@CmCode, 4) and ((FromDate Between @PeriodStart and @PeriodEnd) and (ToDate Between @PeriodStart and @PeriodEnd))    
          
      If isNull(@Amt1, 0)=0    
     SET @isDataFound='0'    
      Else    
     SET @isDataFound='1'    
   END    
      
    IF @FixedAssetFromCalculation='0' OR @isDataFound='0'    
   Select @Amt1=Sum(a.DrAmt-a.CrAmt)    
   From FAS_VoucherTranSub a     
   Where a.CompCode=@CmCode and a.LrCode in (Select LrCode From FAS_ScheduleGroup b Where b.LrCode>0 and b.SchCode=-222 and b.CompCode=a.CompCode)    
    and a.DocDate Between @PeriodStart and @PeriodEnd    
        
    Update @TMP_Schedule Set Amount=isNull(@Amt1, 0)    
    Where SchLrCode=-6 and EntryType='LED'    
      
  /* DEPRECIATION CUMULATIVE */    
    
    If @FixedAssetFromCalculation='1'    
   BEGIN    
      Select @Amt2=Sum(CurrentDepreciation) From FAS_DepreciationProcess     
      Where Left(CompCode, 4)=Left(@CmCode, 4) and ToDate < @PeriodStart    
          
      If isNull(@Amt2, 0)=0    
     SET @isDataFound='0'    
      Else    
     SET @isDataFound='1'    
    END    
        
    IF @FixedAssetFromCalculation='0' OR @isDataFound='0'    
   Select @Amt2=Sum(a.DrAmt-a.CrAmt)    
   From FAS_VoucherTranSub a     
   Where a.CompCode like Left(@CmCode, 4)+'%' and a.LrCode in (Select LrCode From FAS_ScheduleGroup b Where b.LrCode>0 and b.SchCode=-222 and b.CompCode=@CmCode)    
    and a.DocDate <= @PeriodEnd    
        
    Update @TMP_Schedule Set Amount=-isNull(@Amt2, 0)    
    Where SchLrCode=-7 and EntryType='LED'    
      
      
  /* FIXED ASSET GROSS BLOCK */    
    Declare @Gross money    
    
    If @FixedAssetFromCalculation='1'    
   BEGIN       
      Select @Gross=Sum(OpBalance) From FAS_DepreciationMaster    
      Where Left(CompCode, 4)=Left(@CmCode, 4) and OpBalDate <= @PeriodEnd    
          
      If isNull(@Gross, 0)=0    
     SET @isDataFound='0'    
      Else    
     SET @isDataFound='1'    
         
    SET @Gross=isNull(@Gross, 0)+isNull(@Amt1, 1)    
   END    
       
    IF @FixedAssetFromCalculation='0' OR @isDataFound='0'    
   BEGIN    
    Select @Gross=Sum(b.DrAmt-b.CrAmt)    
    From FAS_VoucherTranSub b    
    Where b.LrCode in (Select LedgerCode from FAS_LedgerMaster a Where a.LrRoute like '09%' and a.CompCode=@CmCode)    
     and b.CompCode like Left(@CmCode, 4)+'%' and b.DocDate <= @PeriodEnd     
      
    SET @Gross=isNull(@Gross, 0)+isNull(@Amt2, 0)    
   END    
    
    Update @TMP_Schedule Set Amount=isNull(@Gross, 0)    
    Where SchLrCode=-8 and EntryType='LED'      
    
     /*Update the Group Amount from Ledgers*/    
   UPDATE @TMP_Schedule Set Amount=isNull((Select Sum(Amount) From @TMP_Schedule b Where b.SchPath Like a.SchPath+'%' and b.EntryType='LED'), 0)    
   From @TMP_Schedule a     
   Where a.EntryType='SCH'     
     
  /*  Update Amount for Ungrouped Schedule*/    
  Update @TMP_Schedule Set Amount=isNull((Select Sum(Amount) From @TMP_Schedule b Where b.SchPath Like 'zz%' and b.EntryType='LED'), 0)    
  From @TMP_Schedule a     
  Where EntryType='SCH' and schPath='zz'    
    
  /* Levels Cut */    
  If @Level > 0 /* Schedules delete based on levels selected */    
   Delete From @TMP_Schedule     
   Where  (Len(SchPath)/2) >@Level    
    
    
   /* Delete the Non-Expandable Entries */    
 /*   If @isExpandAll='0'    
     BEGIN    
      Declare @sPath varchar(42)    
          
      Declare curSch CURSOR FOR     
       Select SchPath from @TMP_Schedule a     
       Where isExpand='0'     
       and Not Exists (Select * from @TMP_Schedule b     
           Where b.isExpand='0' and Len(b.SchPath)<Len(a.SchPath) and a.SchPath like Left(b.SchPath, 2)+'%')    
          
      OPEN curSch    
      FETCH NEXT FROM curSch into @sPath    
       
      WHILE @@FETCH_STATUS =  0     
       Begin    
        Delete From @TMP_Schedule Where SchPath Like @sPath+'%' and ((SchPath<>@sPath and EntryType='SCH') OR EntryType='LED')    
            
        FETCH NEXT FROM curSch into @sPath    
       End    
     END    
*/    
     
   /* Delete Zero Closing Balance Entries Based On the Option @@isShowZeroCB */    
    
   If @isShowZeroCB=Convert(bit, '0')    
    Delete From @TMP_Schedule Where Amount=0    
    
   /* Select * from @TMP_Schedule Where (@isShowZeroCB='1' OR Amount<>0) Order By SchPath, EntryType Desc */    
     
      
   /* Update the Amount to Zero for Expandable Item */     
  /* If Show All Levels only need to update Amt is zero other wise need to show the amount*/    
    
/*  IF @Level = 0     
    Update @TMP_Schedule Set Amount=0     
    Where EntryType='SCH' and isExpand='1'     
*/      
    
  Select * from @TMP_Schedule Order By SchPath+case when EntryType='LED' Then 'ZZ' Else '' End, SchLrName --, EntryType Desc    
     
   --Select * from @TMP_Schedule Order By SchLrName --, EntryType Desc     
    
END
GO

/****** Object:  StoredProcedure [dbo].[FAS_ScheduleGroup_Rpt_New]    Script Date: 17/06/2026 11:30:13 ******/
SET ANSI_NULLS ON
