CREATE PROCEDURE [dbo].[FAS_Split_FinanicalYear] (@FinEnd datetime, @CmCode varchar(12), @SplitCmCode varchar(12), @UserID varchar(15))

AS

BEGIN
	SET NOCOUNT ON

	--Transfer Group Master Data
	Insert into FAS_GroupMaster
	Select GroupCode, GroupName, Alias, GrWidth, GrRoute, MaxReached, Master, isActive, @SplitCmCode, @UserID,  TranStamp
	From FAS_GroupMaster
	Where CompCode=@CmCode and isActive='1'

	--Transfer Ledger Master Data
	Insert into FAS_LedgerMaster
	Select LedgerCode, LedgerName, Alias, LrRoute, MaxReached, isBillwise, CreditDays, OpBalance, isCostCentreApplicable, isActive, @SplitCmCode, @UserID,  TranStamp
	From FAS_LedgerMaster
	Where CompCode=@CmCode and isActive='1'

	--Transfer Voucher Master Data
	Insert into FAS_VoucherMaster
	Select VoucherCode, VoucherName, Alias, VrWidth, VrRoute, MaxReached, VAbbr, Prefix, Suffix, isAutoNumber,
		StartNo, WidthNo, RestartAt, UseEntryWiseNarr, PrintAtSave, isActive, @SplitCmCode, @UserID,  TranStamp
	From FAS_VoucherMaster
	Where CompCode=@CmCode and isActive='1'
	

	-- Update CompCode for the Spliting Financial Year
	Update FAS_VoucherTranMast Set CompCode=@SplitCmCode
	Where DocDate <= @FinEnd and CompCode=@CmCode
	
	Update FAS_VoucherTranSub Set CompCode=@SplitCmCode
	Where DocDate <= @FinEnd and CompCode=@CmCode
	
	Update FAS_VoucherTranRef Set CompCode=@SplitCmCode
