	Update FAS_BillDetails Set CompCode=@SplitCmCode
	Where DocDate <= @FinEnd and CompCode=@CmCode
	
	Update FAS_StockEntry Set CompCode=@SplitCmCode
	Where StockDate <= @FinEnd and CompCode=@CmCode
	

