/****** Object:  StoredProcedure [dbo].[FAS_TDI_TrimStringData]    Script Date: 17/06/2026 11:30:13 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_TDI_TrimStringData] 

AS

Begin
	Update FAS_TDI_GroupMaster Set GroupName=dbo.Trim(GroupName), Parent=dbo.Trim(Parent), GrRoute=dbo.Trim(GrRoute), GrWidth=dbo.Trim(GrWidth)

	Update FAS_TDI_LedgerMaster Set LedgerName=dbo.Trim(LedgerName), LrRoute=dbo.Trim(LrRoute), GrName=dbo.Trim(GrName)
	
	Update FAS_TDI_BillDetails Set VrRoute=dbo.Trim(VrRoute), VrName=dbo.Trim(VrName), LrName=dbo.Trim(LrName), Type=dbo.Trim(Type), RefNo=dbo.Trim(RefNo)

	Update FAS_TDI_VoucherMaster Set VoucherName=dbo.Trim(VoucherName), Parent=dbo.Trim(Parent), VrRoute=dbo.Trim(VrRoute), VrWidth=dbo.Trim(VrWidth)

	Update FAS_TDI_VoucherTranMast Set VrRoute=dbo.Trim(VrRoute), VrName=dbo.Trim(VrName), Ref=dbo.Trim(Ref), PayMode=dbo.Trim(PayMode), Narration=dbo.Trim(Narration)

	Update FAS_TDI_VoucherTranSub Set VrRoute=dbo.Trim(VrRoute), VrName=dbo.Trim(VrName), LrName=dbo.Trim(LrName)

End
GO

/****** Object:  StoredProcedure [dbo].[FAS_TDI_UpdateGroups]    Script Date: 17/06/2026 11:30:13 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_TDI_UpdateGroups] (@CallFrom varchar(10))

AS

Begin


	If (@CallFrom='Groups')
		Begin

			Declare @GroupName varchar(50)
		
			While Exists (Select * from FAS_TDI_GroupMaster a Inner Join (Select * from FAS_TDI_GroupMaster) b
					On a.Parent=b.GroupName
					Where a.GrRoute = '' and a.Parent<>'' and b.GrWidth<>'')
		
				Begin
					Declare curGroup Cursor For
						(Select a.GroupName from FAS_TDI_GroupMaster a Inner Join (Select * from FAS_TDI_GroupMaster) b
						On a.Parent=b.GroupName
						Where a.GrRoute = '' and a.Parent<>'' and b.GrWidth<>'')
					
					Open curGroup
					FETCH NEXT FROM curGroup into @GroupName 			
					
					WHILE @@FETCH_STATUS = 0	
						Begin 
							
							Update FAS_TDI_GroupMaster Set GrRoute = b.GrRoute+b.GrWidth--, 
									--GrWidth = dbo.fn_FAS_Get_Width(Convert(varchar, isNull((Select Max(GrWidth) from FAS_TDI_GroupMaster c where c.GrRoute=b.GrRoute+b.GrWidth), 0) ), 1, 2)
								 from FAS_TDI_GroupMaster a Inner Join (Select * from FAS_TDI_GroupMaster) b
								On a.Parent=b.GroupName
								Where a.GrRoute = '' and a.Parent<>'' and b.GrWidth<>'' and a.GroupName=@GroupName				
							
							FETCH NEXT FROM curGroup into @GroupName 	
						End
		
						Close curGroup
						Deallocate curGroup
		
				End
		End
	Else
		If (@CallFrom='Ledgers')
			Begin
				If Exists (Select * from FAS_TDI_LedgerMaster a Inner Join FAS_TDI_GroupMaster b On a.GrName=b.GroupName
						Where a.LrRoute='')
					Begin
						Update FAS_TDI_LedgerMaster Set LrRoute=isNull(b.GrRoute+b.GrWidth, '')
						from FAS_TDI_LedgerMaster a Inner Join FAS_TDI_GroupMaster b
						On a.GrName=b.GroupName
						Where LrRoute=''
					End
			End	
End
GO

/****** Object:  StoredProcedure [dbo].[FAS_TDI_UpdateLedgers]    Script Date: 17/06/2026 11:30:13 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_TDI_UpdateLedgers] (@CallFrom varchar(10))

AS

Begin

	If (@CallFrom='Bills')
		Begin
			If Exists (Select * from FAS_TDI_BillDetails a Inner Join FAS_TDI_LedgerMaster b On a.LrName=b.LedgerName
					Where isNull(a.LrCode, 0)=0 and isNull(b.LedgerCode, 0) > 0)
				Begin
					Update FAS_TDI_BillDetails Set LrCode=b.LedgerCode
					from FAS_TDI_BillDetails a Inner Join FAS_TDI_LedgerMaster b
					On a.LrName=b.LedgerName
					Where isNull(a.LrCode, 0)=0 and isNull(b.LedgerCode, 0) > 0
				End
		End
	Else
		If (@CallFrom='VrTran')
			Begin
				If Exists (Select * from FAS_TDI_VoucherTranSub a Inner Join FAS_TDI_LedgerMaster b On a.LrName=b.LedgerName
					Where isNull(a.LrCode, 0)=0 and isNull(b.LedgerCode, 0) > 0)
					Begin
						Update FAS_TDI_VoucherTranSub Set LrCode=b.LedgerCode
						from FAS_TDI_VoucherTranSub a Inner Join FAS_TDI_LedgerMaster b
						On a.LrName=b.LedgerName
						Where isNull(a.LrCode, 0)=0 and isNull(b.LedgerCode, 0) > 0
					End
			End


	
End
GO

/****** Object:  StoredProcedure [dbo].[FAS_TDI_UpdateVouchers]    Script Date: 17/06/2026 11:30:13 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_TDI_UpdateVouchers] (@CallFrom varchar(10))

AS

Begin


	If (@CallFrom='Vouchers')
		Begin

			Declare @VoucherName varchar(50)
		
			While Exists (Select * from FAS_TDI_VoucherMaster a Inner Join (Select * from FAS_TDI_VoucherMaster) b
					On a.Parent=b.VoucherName
					Where a.VrRoute = '' and a.Parent<>'' and b.VrWidth<>'') 
		
				Begin
					Declare curVoucher Cursor For
						(Select a.VoucherName from FAS_TDI_VoucherMaster a Inner Join (Select * from FAS_TDI_VoucherMaster) b
						On a.Parent=b.VoucherName
						Where a.VrRoute = '' and a.Parent<>'' and b.VrWidth<>'')
					
					Open curVoucher
					FETCH NEXT FROM curVoucher into @VoucherName 			
					
					WHILE @@FETCH_STATUS = 0	
						Begin 
							
							Update FAS_TDI_VoucherMaster Set VrRoute = b.VrRoute+b.VrWidth--, 
									--VrWidth = dbo.fn_FAS_Get_Width(Convert(varchar, isNull((Select Max(VrWidth) from FAS_TDI_VoucherMaster c where c.VrRoute=b.VrRoute+b.VrWidth), 0) ), 1, 2)
								 from FAS_TDI_VoucherMaster a Inner Join (Select * from FAS_TDI_VoucherMaster) b
								On a.Parent=b.VoucherName
								Where a.VrRoute = '' and a.Parent<>'' and b.VrWidth<>'' and a.VoucherName=@VoucherName				
							
							FETCH NEXT FROM curVoucher into @VoucherName 	
						End
		
						Close curVoucher
						Deallocate curVoucher
		
				End
		End
	Else
		If (@CallFrom='Bills')
			Begin
				If Exists (Select * from FAS_TDI_BillDetails a Inner Join FAS_TDI_VoucherMaster b On a.VrName=b.VoucherName
						Where isNull(a.VrRoute, '') = '' and b.VrWidth<>'')
					Begin
						Update FAS_TDI_BillDetails Set VrRoute=b.VrRoute+b.VrWidth
						from FAS_TDI_BillDetails a Inner Join FAS_TDI_VoucherMaster b 
						On a.VrName=b.VoucherName
						Where isNull(a.VrRoute, '') = '' and b.VrWidth<>''
					End
			End
		Else
			If (@CallFrom='VrTran')
				Begin
					If Exists (Select * from FAS_TDI_VoucherTranMast a Inner Join FAS_TDI_VoucherMaster b On a.VrName=b.VoucherName
							Where isNull(a.VrRoute, '') = '' and b.VrWidth<>'')
						Begin
							Update FAS_TDI_VoucherTranMast Set VrRoute=b.VrRoute+b.VrWidth
							from FAS_TDI_VoucherTranMast a Inner Join FAS_TDI_VoucherMaster b 
							On a.VrName=b.VoucherName
							Where isNull(a.VrRoute, '') = '' and b.VrWidth<>''
						End			

					If Exists (Select * from FAS_TDI_VoucherTranSub a Inner Join FAS_TDI_VoucherMaster b On a.VrName=b.VoucherName
							Where isNull(a.VrRoute, '') = '' and b.VrWidth<>'')
						Begin
							Update FAS_TDI_VoucherTranSub Set VrRoute=b.VrRoute+b.VrWidth
							from FAS_TDI_VoucherTranSub a Inner Join FAS_TDI_VoucherMaster b 
							On a.VrName=b.VoucherName
							Where isNull(a.VrRoute, '') = '' and b.VrWidth<>''
						End	

					If Exists (Select * from FAS_TDI_BillDetails a Inner Join FAS_TDI_VoucherMaster b On a.VrName=b.VoucherName
							Where isNull(a.VrRoute, '') = '' and b.VrWidth<>'')
						Begin
							Update FAS_TDI_BillDetails Set VrRoute=Case When a.VrName='OpBal' then 'OpBal' Else b.VrRoute+b.VrWidth End
							from FAS_TDI_BillDetails a Inner Join FAS_TDI_VoucherMaster b 
							On a.VrName=b.VoucherName
							Where isNull(a.VrRoute, '') = '' and b.VrWidth<>''
						End


				End
	
End
GO

/****** Object:  StoredProcedure [dbo].[FAS_TransferStockToTmp_Insert]    Script Date: 17/06/2026 11:30:13 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[FAS_TransferStockToTmp_Insert] (@UserKey varchar(36), @OBDate datetime, @CBDate datetime, @isDataFromModifiedStock bit, @isActualsFromWHS bit, @CmCode Varchar(12))      
/* @isDataFromModifiedStock = 1-Data Taken From modified stock; 0-Data Taken From Actuals based on the Option @isActualsFromWHS */      
/* @isActualsFromWHS = Applicable only isDataFromModifiedStock=0;  1-Data Taken From Stock Ledger; 2-Data Taken From FAS */      
      
AS       
      
BEGIN      
       
  Delete From FAS_StockValue_Tmp Where UserKey=@UserKey and CompCode=@CmCode      
        
  If @isDataFromModifiedStock=Convert(bit, 1)       
    INSERT INTO FAS_StockValue_Tmp      
      SELECT @UserKey, LedgerCode, OpeningStock, ClosingStock, @CmCode      
      FROM dbo.fn_FAS_StockRPT_OBCB(@OBDate, @CBDate, @isActualsFromWHS, @CmCode)       
          
  Else      
   If @isActualsFromWHS=Convert(bit, 1)      
     INSERT INTO FAS_StockValue_Tmp      
       SELECT @UserKey, LedgerCode, OpeningStock, ClosingStock, @CmCode      
       FROM dbo.fn_FAS_StockWHS_OBCB(@OBDate, @CBDate, @CmCode)       
         
   Else      
     INSERT INTO FAS_StockValue_Tmp      
       SELECT @UserKey, LedgerCode, OpeningStock, ClosingStock, @CmCode      
       FROM dbo.fn_FAS_StockFAS_OBCB(@OBDate, @CBDate, @CmCode)       
       
END 
GO

/****** Object:  StoredProcedure [dbo].[FAS_TrialBalance_Period]    Script Date: 17/06/2026 11:30:13 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[FAS_TrialBalance_Period](@PeriodStart datetime, @PeriodEnd datetime, @GroupBy varchar(5), @CmCode varchar(12))

 As 

 SET NOCOUNT ON

 Begin
 
	CREATE TABLE [#RetTable]
	(
	[LrCode] [int],
	[AsOnYear] [int],
	[AsOnPeriod] [int],
	[Amt] [money],
	[SortOrder] [int],
	[CompCode] [varchar](12)
	) ON [PRIMARY]
	
	
	--Select @PeriodStart='2007-04-01', @PeriodEnd='2008-03-31', @GroupBy='YEAR', @isDrCrSplitUpRequired='1', @CmCode='010020072008'
	
	Declare @CmpCode varchar(12)
	Select @CmpCode=Left(@CmCode, 4)
	
	Declare @tmpDate datetime, @tmpCmCode varchar(12)
	
	If (month(@PeriodStart)<=3)
		SET @tmpDate=Convert(datetime, Convert(varchar, year(@PeriodStart)-1) + '0401', 112)
	Else
		SET @tmpDate=Convert(datetime, Convert(varchar, year(@PeriodStart)) + '0401', 112)
	
	Select distinct top 1 @tmpCmCode=CompCode from FAS_VoucherTranSub 
	Where DocDate Between @tmpDate and DateAdd(dd, -1, DateAdd(mm, 12, @tmpDate)) and CompCode like @CmpCode+'%'
	
	If @tmpCmCode is Null
		Select distinct top 1 @tmpCmCode=CompCode from FAS_VoucherTranSub 
		Where DocDate < @tmpDate and CompCode like @CmpCode+'%' Order By DocDate Desc
		
		If @tmpCmCode is Null	
			Select distinct top 1 @tmpCmCode=CompCode from FAS_VoucherTranSub 
			Where CompCode like @CmpCode+'%' 

		If @tmpCmCode is Null
			Select @tmpCmCode=@CmCode
	
	/* Opening Balance Insert */
	Insert into [#RetTable]
		Select LedgerCode, Year(@PeriodStart), Convert(int, Convert(varchar(8), @PeriodStart, 112)),
			OpBalance, 0, @CmCode
		from dbo.fn_FAS_AllOpBalance(@PeriodStart, '0', '1', @tmpCmCode) a 



	If @GroupBy='YEAR'
		BEGIN
			Insert into [#RetTable]
				Select LrCode, 0 as AsOnYear, AsOnPeriod, Sum(Amt), SortOrder, CompCode
				From
					(Select LrCode, Case When Month(DocDate)<=3 Then Year(DocDate)-1 Else Year(DocDate) End as AsOnPeriod, DrAmt-CrAmt as Amt, 
						((Case When Month(DocDate)<=3 Then Year(DocDate)-1 Else Year(DocDate) End)
						- (Case When Month(@PeriodStart)<=3 Then Year(@PeriodStart)-1 Else Year(@PeriodStart) End)
						+ 1) as SortOrder, 
						CompCode
					from FAS_VoucherTranSub
					Where (DocDate Between @PeriodStart and @PeriodEnd)	
					) x
				Group By LrCode, AsOnPeriod, SortOrder, CompCode
/*				
			Set @NoOfPeriodSplitCols=(Case When Month(@PeriodEnd)<=3 Then Year(@PeriodEnd)-1 Else Year(@PeriodEnd) End
										- Case When Month(@PeriodStart)<=3 Then Year(@PeriodStart)-1 Else Year(@PeriodStart) End
										+ 1)
*/
		END
	Else
	If @GroupBy='MONTH'
		BEGIN
			Insert into [#RetTable]
				Select LrCode, AsOnYear, AsOnPeriod, Sum(Amt), SortOrder, CompCode
				From
					(Select LrCode, Year(DocDate) as AsOnYear, DatePart(mm, DocDate) as AsOnPeriod,  DrAmt-CrAmt as Amt,
						(DateDiff(mm, @PeriodStart, DocDate) + 1) as SortOrder, 
						CompCode
					from FAS_VoucherTranSub
					Where (DocDate Between @PeriodStart and @PeriodEnd)	
					) x
				Group By LrCode, AsOnYear, AsOnPeriod, SortOrder, CompCode
/*				
			Set @NoOfPeriodSplitCols= DateDiff(mm, @PeriodStart, @PeriodEnd) + 1
*/
		END
	Else
	If @GroupBy='WEEK'
		BEGIN
			Insert into [#RetTable]
				Select LrCode, AsOnYear, AsOnPeriod, Sum(Amt), SortOrder, CompCode
				From
					(Select LrCode, Year(DocDate) as AsOnYear, DatePart(wk, DocDate) as AsOnPeriod,  DrAmt-CrAmt as Amt,
						(DateDiff(wk, @PeriodStart, DocDate) + 1) as SortOrder, 
						CompCode
					from FAS_VoucherTranSub
					Where (DocDate Between @PeriodStart and @PeriodEnd)	
					) x
				Group By LrCode, AsOnYear, AsOnPeriod, SortOrder, CompCode
/*				
			Set @NoOfPeriodSplitCols= DateDiff(wk, @PeriodStart, @PeriodEnd) + 1
*/			
		END
	Else
	If @GroupBy='DAY'
		BEGIN
			Insert into [#RetTable]
				Select LrCode, AsOnYear, AsOnPeriod, Sum(Amt), SortOrder, CompCode
				From
					(Select LrCode, Year(DocDate) as AsOnYear, Convert(varchar(8), DocDate, 112) as AsOnPeriod,  DrAmt-CrAmt as Amt,
						(DateDiff(dd, @PeriodStart, DocDate) + 1) as SortOrder, 
						CompCode
					from FAS_VoucherTranSub
					Where (DocDate Between @PeriodStart and @PeriodEnd)	
					) x
				Group By LrCode, AsOnYear, AsOnPeriod, SortOrder, CompCode
/*				
			Set @NoOfPeriodSplitCols= DateDiff(dd, @PeriodStart, @PeriodEnd) + 1
*/			
		END


	SELECT LrCode, AsOnYear, AsOnPeriod, Case When Amt > 0 Then Amt Else 0 End as DrAmt, Case When Amt < 0 Then -Amt Else 0 End as CrAmt,
		SortOrder, CompCode
	from [#RetTable] Order By LrCode, SortOrder

	DROP TABLE [#RetTable]

 End
GO

