CREATE PROCEDURE [dbo].[FAS_UP_LedgerMaster_ERPRef]  
  (@LedgerCode   [int],  
  @VendorCode   [varchar](10),  
  @IsParty   [bit],  
  @FormCode   [int],  
  @PackingCode  [int],  
  @DeliveryCode  [int],  
  @PaymentCode  [int],  
  @InsuranceCode  [int],  
  @ModeCode   [int],  
  @Freightcode   [int],  
  @IsSubcontractor  [bit],  
  @CreditDaysPeriod  [varchar](20),  
  @CurrencyCode  [char](3),  
  @CustomerFormulaCode [int],  
  @VendorFormulaCode  [int],  
  @Userid   [int],  
  @CompCode   [varchar](12),  
  @TranStamp   [datetime])  
  
AS   
  
 BEGIN   
  
 DECLARE @CompID varchar(2), @BranchID varchar(2)  
  
 SET @CompID=Left(@CompCode,2)  
 SET @BranchID=SubString(@CompCode, 3, 2)  
  
   
 BEGIN  
   
  
   If Exists (Select * From FAS_LedgerMaster_ERPRef Where LedgerCode=@LedgerCode and CompCode= @CompCode)   
    Begin  
     UPDATE [FAS_LedgerMaster_ERPRef]   
       
     SET    [LedgerCode] = @LedgerCode,  
         [VendorCode] = @VendorCode,  
         [IsParty] = @IsParty,  
         [FormCode] = @FormCode,  
         [PackingCode] = @PackingCode,  
         [DeliveryCode] = @DeliveryCode,  
         [PaymentCode] = @PaymentCode,  
         [InsuranceCode] = @InsuranceCode,  
         [ModeCode] = @ModeCode,  
         [Freightcode] = @Freightcode,  
         [IsSubcontractor] = @IsSubcontractor,  
         [CreditDaysPeriod] = @CreditDaysPeriod,  
         [CurrencyCode] = @CurrencyCode,  
         [CustomerFormulaCode] = @CustomerFormulaCode,  
         [VendorFormulaCode] = @VendorFormulaCode,  
         [Userid] = @Userid   
   
       
     WHERE   
      ( [LedgerCode]  = @LedgerCode AND  
       [CompCode]  = @CompCode)      
    END  
   ELSE    
    BEGIN  
     INSERT INTO [FAS_LedgerMaster_ERPRef]   
        ([LedgerCode],  
       [VendorCode],  
       [IsParty],  
       [FormCode],  
       [PackingCode],  
       [DeliveryCode],  
       [PaymentCode],  
       [InsuranceCode],  
       [ModeCode],  
       [Freightcode],  
       [IsSubcontractor],  
       [CreditDaysPeriod],  
       [CurrencyCode],  
       [CustomerFormulaCode],  
       [VendorFormulaCode],  
       [Userid],  
       [CompCode],  
       [TranStamp])   
   
        
     VALUES   
      (@LedgerCode,  
       @VendorCode,  
       @IsParty,  
       @FormCode,  
       @PackingCode,  
       @DeliveryCode,  
       @PaymentCode,  
       @InsuranceCode,  
       @ModeCode,  
       @Freightcode,  
       @IsSubcontractor,  
       @CreditDaysPeriod,  
       @CurrencyCode,  
       @CustomerFormulaCode,  
       @VendorFormulaCode,  
       @Userid,  
       @CompCode,  
       @TranStamp)  
       
  END   
End
End
