CREATE PROCEDURE [dbo].[FAS_UP_LrAddress]      
 (       
 @LrCode  [int],      
 @Add1  [Varchar](50),      
 @Add2  [Varchar](50),      
 @Add3  [Varchar](50),   
 @Country  [Varchar](50),  
 @State  [Varchar](50),     
 @City  [Varchar](30),      
 @Pincode  [varchar](15),      
 @Phone  [varchar](50),      
 @EMail  [varchar](30),      
 @TinNo [varchar](50),      
 @PanNo [varchar](50),      
 @ECCNo [varchar](15),      
 @Range [varchar](50),      
 @GSTRegNo [varchar](50),      
 @GSTRegDate [datetime],    
 @ProvisionalID [varchar](50),
 @UdyamNo [varchar](30)='',
 @UdyamDate [datetime]=null,         
 @CompCode  [varchar](4),      
 @UserID  [varchar](10),      
 @TranStamp  [datetime]  
 )            
AS
BEGIN
 SET NOCOUNT ON;        
      
 If Exists (Select * From FAS_LrAddress Where LrCode=@LrCode and CompCode=@CompCode)      
  Begin      
   UPDATE [FAS_LrAddress]       
         
   SET    
 [Add1]  =@Add1,      
 [Add2]  =@Add2,      
 [Add3]  =@Add3,   
 [Country]=@Country,  
 [State]=@State,     
 [City]  =@City,      
 [Pincode]  = @Pincode,      
 [Phone]  = @Phone,      
 [EMail]    = @EMail,      
 [TinNo]   = @TinNo,      
 [PANNo] = @PanNo,      
 [ECCNo] = @ECCNo,      
 [Range] = @Range,      
 [GSTRegNo]=@GSTRegNo,    
 [GSTRegDate]=@GSTRegDate,    
 [ProvisionalID]=@ProvisionalID,    
 [UdyamNo]=@UdyamNo, 
 [UdyamDate]=@UdyamDate, 
 [UserID]  = @UserID,      
 [TranStamp]  = @TranStamp      
         
   WHERE       
    ( [LrCode]  = @LrCode AND      
     [CompCode]  = @CompCode)      
  End      
 Else      
  Begin      
   Execute FAS_Ins_LrAddress @LrCode, @Add1, @Add2,@Add3, @Country, @State, @City,@Pincode, @Phone, @EMail, 
        @TinNo, @PanNo, @ECCNo, @Range,@GSTRegNo, @GSTRegDate, @ProvisionalID, @UdyamNo, @UdyamDate,
        @CompCode, @UserID, @TranStamp      
  End
END
