CREATE PROCEDURE [dbo].[HRD_INS_SkillSet_Master]

	(@GroupCode		[int],
	 @TeamGroupCode	[int],
	 @DepartmentCode 	[int],
	 @DesignationCode 	[int],
	 @SkillLevelCode	[int],
	 @SkillCode 		[int],
	 @sValue		[float],
	 @Experience 		[float],
	 @Userid 		[varchar](10),
	 @Branchid 		[varchar](3),
	 @Compid 		[varchar](3))

AS 
BEGIN
SET NOCOUNT ON

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		INSERT INTO [HRD_SkillSet_Master] 
		
			 ([GroupCode],
			 [TeamGroupCode],
			 [DepartmentCode],
			 [DesignationCode],
			 [SkillLevelCode],
			 [SkillCode],
			 [sValue],
			 [Experience],
			 [Userid],
			 [Branchid],
			 [Compid]) 
		 
		VALUES 
		
			( @GroupCode,
			 @TeamGroupCode,	
			 @DepartmentCode,
			 @DesignationCode,
			 @SkillLevelCode,
			 @SkillCode,
			 @sValue,
			 @Experience,
			 @Userid,
			 @cBranchid,
			 @Compid)

		FETCH NEXT FROM BranchidList into @cBranchid 
	END
 	
	close BranchidList
	deallocate BranchidList
END
GO

