CREATE PROCEDURE [dbo].[INV_AsOnDateStock_ItemWhsBased_Get_CBQty](@ItemCode varchar(30), @WarehouseCode varchar(10),     
 @StockDate datetime, @AsOnDate datetime=NULL, @RptDate datetime=NULL, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(15))                  
As    
BEGIN    
 SET NOCOUNT ON;    
    
  /* Get CBQty */  
  Select a.ItemCode, @WarehouseCode As WarehouseCode, IsNull(a.RackBinCode,'') As RackBinCode,   
	IsNull(a.CBQty,0) As CBQty                           
  From dbo.fn_INV_AsOnDate_Stock_Item_WHS_V2(@ItemCode, @WarehouseCode, @StockDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a  
  Where a.ItemCode=@ItemCode and a.BranchID=@BranchID and a.CompID=@CompID             
END  
GO

/****** Object:  StoredProcedure [dbo].[INV_GSRShortclose_Fil]    Script Date: 17/06/2026 11:30:16 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[INV_GSRShortclose_Fil]( @FromDate DateTime, @ToDate DateTime, @BranchID varchar(3), @CompID varchar(3))              
As              
 Begin              
   
  SET NOCOUNT ON              
   
  Select a.ItemCode, b.ItemDescription As ItemDesc, d.SDesc As UOMDesc, d.NoOfDecimals As UOMDecimal, a.RequiredQty, a.IssuedQty, b.ItemNature, Isnull(c.Norms,0) As Norms  
    --,case when ItemInOutType='P' then 1 else 0 end IsPur 
	,a.StoreRequestType as Doctype,a.StoreRequestNo as DocNo, Convert(Varchar(10),a.StoreRequestDate,120) As DocDate              
  From StoreRequest a               
      
  Left Outer Join dbo.INV_Material_Master b               
  On a.ItemCode=b.ItemCode and a.Branchid=b.Branchid and a.compid=b.Compid    
    
  Left Outer Join 
  (
  select Norms, ProcessWorkOrderType as Doctype, ProcessWorkOrderNo as DocNo, ProcessWorkOrderDate as DocDate
  from PPC_ProcessWorkOrder
  where BranchID=@BranchID and CompID=@CompID
  
  Union
  
  select Norms, AssemblyWorkOrderType as Doctype, AssemblyWorkOrderNo as DocNo, AssemblyWorkOrderDate as DocDate
  from PPC_AssemblyWorkOrder_Dtl
  where BranchID=@BranchID and CompID=@CompID
  
  Union
  
  select Norms, ReworkorderType as Doctype, ReworkOrderNo as DocNo, ReworkOrderDate as DocDate
  from PPC_reworkorder
  where BranchID=@BranchID and CompID=@CompID
  )c
  On c.Doctype=a.WOtype and c.DocNo=a.WONo and c.DocDate=a.WODate

  Left Outer Join dbo.INV_UOM_Master d 
  On d.Code=b.UOM and d.BranchID=@BranchID and d.CompID=@CompID
            
  Where a.StoreRequestDate between Convert(datetime,@FromDate,111) and Convert(datetime,@ToDate,111) and a.StoreRequestType='GSR'             
  
  and a.RequiredQty > a.IssuedQty  and a.BranchId=@BranchID and a.CompId=@CompID  and a.ShortClose = '0'           
      
 End
GO

