CREATE PROCEDURE [dbo].[INV_INS_MATERIAL_MASTER]
(
	@ItemCode [varchar](20),
	@ItemDescription [varchar](50),
	@ItemNature [char](2),
	@ProductCategoryCode [int],
	@ProductSubCategoryCode [int],
	@PurchaseNature [char](1),
	@Origin [varchar](20),
	@Boughtout [char](1),
	@ItemSpecification [varchar](3000),
	@IsHeatNoApp [bit],
	@PostingAccount [int],
	@PostingAccountEditable [bit],
	@CostCenter [int],
	@UOM [int],
	@PurchaseUOM [int],
	@PurConversionFactor [float],
	@IssueUOM [int],
	@IssConversionFactor [float],
	@AlternateUOM [int],
	@AlternateConvFactor [float],
	@MinimumStock [float],
	@MaximumStock [float],
	@ReOrderLevel [float],
	@ReOrderQty [float],
	@SafetyStock [float],
	@MinLeadTime [float],
	@MaxLeadTime [float],
	@IsShelfLifePeriodApp [bit],
	@SelfLifePeriod [int],
	@Rate [float],
	@Modvat [bit],
	@TariffNo [varchar](10),
	@HSNId [int],
	@isAsset [bit],
	@TolerancePlusApplicable [bit],
	@PurchaseTolerancePlus [float],
	@ToleranceMinusApplicable [bit],
	@PurchaseToleranceMinus [float],
	@PackingType [varchar](10),
	@StdPackingQty [float],
	@DrawingNo [varchar](10),
	@DrawingDescription [varchar](50),
	@RevisionNo [varchar](10),
	@RevisionDate [Datetime],
	@DrawingPath [varchar](200),
	@TrayTypeCode [int],
	@Status [Bit],
	@Userid [varchar](10),
	@BranchId [varchar](3),
	@Compid [varchar](3) ,
	@Transtamp [datetime]
)

AS
BEGIN
	SET NOCOUNT ON;

	Declare @ItemID int;

	IF Exists (Select * From BOM_Material_Master Where ItemCode=@ItemCode and BranchID=@BranchID and CompID=@CompID)
	Begin
		Select Top 1 @ItemID = ItemID
		From INV_Material_Master
		Where ItemCode=@ItemCode and BranchID=@BranchID and CompID=@CompID
	END
	ELSE
	BEGIN
		Select @ItemID=IsNull(Max(ItemID), 0)+1
		From INV_Material_Master
		Where BranchID=@BranchID and CompID=@CompID
	END

	INSERT INTO [INV_MATERIAL_MASTER_HIS]
	(
		[ItemID],
		[ItemCode],
		[ItemDescription],
		[ItemNature],
		[ProductCategoryCode],
		[ProductSubCategoryCode],
		[PurchaseNature],
		[Origin],
		[Boughtout],
		[ItemSpecification],
		[IsHeatNoApp],
		[PostingAccount],
		[PostingAccountEditable],
		[CostCenter],
		[UOM],
		[PurchaseUOM],
		[PurConversionFactor],
		[IssueUOM],
		[IssConversionFactor],
		[AlternateUOM],
		[AlternateConvFactor],
		[MinimumStock],
		[MaximumStock],
		[ReOrderLevel],
		[ReOrderQty],
		[SafetyStock],
		[MinLeadTime],
		[MaxLeadTime],
		[IsShelfLifePeriodApp],
		[SelfLifePeriod],
		[Rate],
		[Modvat],
		[TariffNo],
		[HSNId],
		[isAsset],
		[TolerancePlusApplicable],
		[PurchaseTolerancePlus],
		[ToleranceMinusApplicable],
		[PurchaseToleranceMinus],
		[PackingType],
		[StdPackingQty],
		[DrawingNo],
		[DrawingDescription],
		[RevisionNo],
		[RevisionDate],
		[DrawingPath],
		[TrayTypeCode],
		[Status],
		[Userid],
		[BranchId],
		[Compid] ,
		[Transtamp]
	)
	VALUES
	(
		@ItemID,
		@ItemCode,
		@ItemDescription,
		@ItemNature,
		@ProductCategoryCode,
		@ProductSubCategoryCode,
		@PurchaseNature,
		@Origin,
		@Boughtout,
		@ItemSpecification,
		@IsHeatNoApp,
		@PostingAccount,
		@PostingAccountEditable,
		@CostCenter,
		@UOM,
		@PurchaseUOM,
		@PurConversionFactor,
		@IssueUOM,
		@IssConversionFactor,
		@AlternateUOM,
		@AlternateConvFactor,
		@MinimumStock,
		@MaximumStock,
		@ReOrderLevel,
		@ReOrderQty,
		@SafetyStock,
		@MinLeadTime,
		@MaxLeadTime,
		@IsShelfLifePeriodApp,
		@SelfLifePeriod,
		@Rate,
		@Modvat,
		@TariffNo,
		@HSNId,
		@isAsset,
		@TolerancePlusApplicable,
		@PurchaseTolerancePlus,
		@ToleranceMinusApplicable,
		@PurchaseToleranceMinus,
		@PackingType,
		@StdPackingQty,
		@DrawingNo,
		@DrawingDescription,
		@RevisionNo,
		@RevisionDate,
		@DrawingPath,
		@TrayTypeCode,
		@Status,
		@Userid,
		@BranchId,
		@Compid ,
		@Transtamp
	)

END
GO

