			VALUES 
				( @ItemCode,
				 @WhsCode,
				 @RackBinCode,
				 @InternalQCReqd,
				 @isAeroSpaceComp,
				 @EffDate,
				 @Userid,
				 @cBranchid,
				 @Compid,
				 @TranStamp)
		
			FETCH NEXT FROM BranchidList into @cBranchid 
		END

	close BranchidList
	deallocate BranchidList
GO

