CREATE PROCEDURE [dbo].[INV_INS_UOM_MASTER]
	(@Code 		[int],
	 @SDesc 		[varchar](3),
	 @LDesc 		[varchar](30),
	 @NoofDecimals 	[int],
	 @Status        [bit],
	 @UserId 		[varchar](8),
	 @Branchid		[varchar](3),
	 @CompId 		[varchar](3))

AS
BEGIN
SET NOCOUNT ON

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		INSERT INTO [INV_UOM_MASTER] 
			 ( [Code],
			 [SDesc],
			 [LDesc],
			 [NoofDecimals],
			 [Status],
			 [UserId],
			 [Branchid],
			 [CompId]) 
		 
		VALUES 
			( @Code,
			 @SDesc,
			 @LDesc,
			 @NoofDecimals,
			 @Status,
			 @UserId,
			 @cBranchid,
			 @CompId)
	
		FETCH NEXT FROM BranchidList into @cBranchid 
	END
 	
	close BranchidList
	deallocate BranchidList
END
GO

