CREATE PROCEDURE [dbo].[INV_Material_Master_Hlp_PostingAc](@AsOnDate datetime, @RptDate datetime, @CompCode varchar(12))        
AS        
BEGIN  
	SET NOCOUNT ON;
	      
	Select Distinct a.LedgerName, a.LedgerCode 
	From FAS_LedgerMaster_Authtbl a
	Where Left(a.LrRoute,4) Not In('0206','0303') and a.CompCode=@CompCode    
	Order by a.LedgerName
END
