CREATE PROCEDURE [dbo].[INV_Material_Master_Sel_Ins](@ItemCode Varchar(20), @ItemDescription Varchar(50),   
	@Transtamp datetime, @BranchID Varchar(3), @CompID Varchar(3))      
AS      
BEGIN      
	SET NOCOUNT ON;    
	
	/* Variables Declaration */
	DECLARE @ItemSpecification As varchar(3000), @Origin As varchar(20), @TariffNo As varchar(10), 
		@PackingType As varchar(10), @DrawingNo As varchar(10), @DrawingDescription As varchar(50), 
		@RevisionNo As varchar(10), @DrawingPath As varchar(200), @UserID As varchar(10);

	DECLARE @ItemNature char(2), @PurchaseNature As char(1), @Boughtout As char(1);
	
	DECLARE @ProductCategoryCode As int, @ProductSubCategoryCode As int, @PostingAccount As int, 
		@CostCenter As int, @UOM As int, @PurchaseUOM As int, @IssueUOM As int, @AlternateUOM As int, 
		@SelfLifePeriod As int, @HSNId As int, @TrayTypeCode As int;

	DECLARE @PurConversionFactor As float, @IssConversionFactor As float, @AlternateConvFactor As float,  
		@MinimumStock As float, @MaximumStock As float, @ReOrderLevel As float, @ReOrderQty As float,  
		@SafetyStock As float, @MinLeadTime As float, @MaxLeadTime As float, @Rate As float,
		@PurchaseTolerancePlus As float, @PurchaseToleranceMinus As float, @StdPackingQty As float;

	DECLARE @IsHeatNoApp As bit, @PostingAccountEditable As bit, @IsShelfLifePeriodApp As bit,	
		@Modvat As bit, @isAsset As bit, @TolerancePlusApplicable As bit, 
		@ToleranceMinusApplicable As bit, @Status As Bit;

	DECLARE @RevisionDate As Datetime;

	/* Get Item Data */
	BEGIN
		Select @ItemNature=a.ItemNature, @ProductCategoryCode=a.ProductCategoryCode,     
			@ProductSubCategoryCode=a.ProductSubCategoryCode, @PurchaseNature=a.PurchaseNature, @Origin=a.Origin, 
			@Boughtout=a.Boughtout, @ItemSpecification=a.ItemSpecification, @IsHeatNoApp=a.IsHeatNoApp,   
			@PostingAccount=a.PostingAccount, @PostingAccountEditable=a.PostingAccountEditable, @CostCenter=a.CostCenter, 
			@UOM=a.UOM, @PurchaseUOM=a.PurchaseUOM, @PurConversionFactor=a.PurConversionFactor,   
			@IssueUOM=a.IssueUOM, @IssConversionFactor=a.IssConversionFactor, @AlternateUOM=a.AlternateUOM, 
			@AlternateConvFactor=a.AlternateConvFactor, @MinimumStock=a.MinimumStock, @MaximumStock=a.MaximumStock,     
			@ReOrderLevel=a.ReOrderLevel, @ReOrderQty=a.ReOrderQty, @SafetyStock=a.SafetyStock, @MinLeadTime=a.MinLeadTime, 
			@MaxLeadTime=a.MaxLeadTime, @IsShelfLifePeriodApp=a.IsShelfLifePeriodApp, @SelfLifePeriod=a.SelfLifePeriod, 
			@Rate=a.Rate, @Modvat=a.Modvat, @TariffNo=a.TariffNo, @HSNId=a.HSNId, @isAsset=a.isAsset, 
			@TolerancePlusApplicable=a.TolerancePlusApplicable, @PurchaseTolerancePlus=a.PurchaseTolerancePlus, 
			@ToleranceMinusApplicable=a.ToleranceMinusApplicable, @PurchaseToleranceMinus=a.PurchaseToleranceMinus, 
			@PackingType=a.PackingType, @StdPackingQty=a.StdPackingQty, @DrawingNo=a.DrawingNo, 
			@DrawingDescription=a.DrawingDescription, @RevisionNo=a.RevisionNo, @RevisionDate=a.RevisionDate, 
			@DrawingPath=a.DrawingPath, @TrayTypeCode=a.TrayTypeCode, @Status=a.Status, 
			@UserID=a.UserID
		From INV_Material_Master a    
		Where a.ItemCode=@ItemCode and a.BranchID=@BranchID and a.CompID=@CompID  
	END

	/* Insert Item Data Into Table */
	EXECUTE INV_INS_MATERIAL_MASTER @ItemCode, @ItemDescription, @ItemNature, @ProductCategoryCode, @ProductSubCategoryCode,
			@PurchaseNature, @Origin, @Boughtout, @ItemSpecification, @IsHeatNoApp, @PostingAccount, @PostingAccountEditable,
			@CostCenter, @UOM, @PurchaseUOM, @PurConversionFactor, @IssueUOM, @IssConversionFactor, @AlternateUOM,
			@AlternateConvFactor, @MinimumStock, @MaximumStock, @ReOrderLevel, @ReOrderQty, @SafetyStock, @MinLeadTime,
			@MaxLeadTime, @IsShelfLifePeriodApp, @SelfLifePeriod, @Rate, @Modvat, @TariffNo, @HSNId, @isAsset, 
			@TolerancePlusApplicable, @PurchaseTolerancePlus, @ToleranceMinusApplicable, @PurchaseToleranceMinus, 			
			@PackingType, @StdPackingQty, @DrawingNo, @DrawingDescription, @RevisionNo, @RevisionDate, @DrawingPath, 
			@TrayTypeCode, @Status, @UserID, @BranchID, @CompiD, @Transtamp      
----------------------------------
/* -- Previous Query:
 Insert into INV_Material_Master_His  
         
 Select a.ItemCode, @ItemDescription, a.ItemNature, a.ProductCategoryCode, a.ProductSubCategoryCode,   
   a.PurchaseNature, a.Origin, a.Boughtout, a.ItemSpecification, a.IsHeatNoApp, a.PostingAccount,   
   a.PostingAccountEditable, a.CostCenter, a.UOM, a.PurchaseUOM, a.PurConversionFactor, a.IssueUOM,   
   a.IssConversionFactor, a.AlternateUOM, a.AlternateConvFactor, a.MinimumStock, a.MaximumStock,   
   a.ReOrderLevel, a.ReOrderQty, a.SafetyStock, a.MinLeadTime, a.MaxLeadTime, a.IsShelfLifePeriodApp,   
   a.SelfLifePeriod, a.Rate, a.Modvat, a.TariffNo, a.HSNId, a.isAsset, a.TolerancePlusApplicable,   
   a.PurchaseTolerancePlus, a.ToleranceMinusApplicable, a.PurchaseToleranceMinus, a.PackingType,   
   a.StdPackingQty, a.DrawingNo, a.DrawingDescription, a.RevisionNo, a.RevisionDate, a.DrawingPath,   
   a.TrayTypeCode, a.Status, a.Userid, @BranchID, @CompID, @Transtamp      
 From INV_Material_Master a      
 Where ItemCode=@ItemCode and Status=1 and BranchID= @BranchID and CompID=@CompID 
*/ 
END
