/****** Object:  StoredProcedure [dbo].[INV_Rpt_ShelfLifePeriodReport_Gen]    Script Date: 17/06/2026 11:30:18 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[INV_Rpt_ShelfLifePeriodReport_Gen](@ItemUserKey varchar(36)='', @ItemNature char(1),        
@WarehouseCode varchar(6)='', @RackBinCode varchar(6)='', @ChkShowValue bit='0', @ChkRestrictZeroStockItem bit='0',     
@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                  
AS          
BEGIN          
SET NOCOUNT ON;       
    
 Declare @CurrDate As datetime;    
 Declare @BeforeAlertDays As int;    
    
 SET @CurrDate=getdate(); /* Get ServerDate */    
 SET @BeforeAlertDays=5;    
    
 If @ChkShowValue='1'    
  Begin          
   Select Distinct IsNull(x.ItemNature,'') As ItemNature, x.ItemCode, IsNull(x.ItemDescription,'') As ItemDescription,         
    IsNull(x.LotID,0) As LotID, IsNull(x.SubLotID,0) As SubLotID, IsNull(x.CBQty1,IsNull(CBQty2,0)) As CBQty,         
    IsNull(x.Rate,0) As Rate, IsNull(x.UOM,'') As UOM, IsNull(x.NoOfDec,0) As NoOfDec,    
    Case When (x.ManufactureDate Is Not Null) Then Convert(varchar(10),x.ManufactureDate,121)     
    Else 'Not Available' End As ManufactureDate, IsNull(x.ShelfLifeDays,0) As ShelfLifeDays,     
    IsNull(x.SLExpireDate,'Not Available') As SLExpireDate, IsNull(x.SLRemainDays,'0') As SLRemainDays,    
    IsNull(x.ShelfLifeStatus,'Not Available') As ShelfLifeStatus, IsNull(x.AlertStatus,'Not Available') As AlertStatus               
   From         
   ( Select m.ItemNature, a.TransactionItem As ItemCode, m.ItemDescription,        
    IsNull(b.LotID,0) As LotID, IsNull(b.SubLotID,0) As SubLotID,     
    c.ManufactureDate, c.ShelfLifeDays,    
    
    (Case When IsNull(c.ShelfLifeDays,0)>0 and (c.ManufactureDate Is Not Null) Then     
     Convert(varchar(10),DateAdd(Day,IsNull(c.ShelfLifeDays,0),c.ManufactureDate))    
     Else 'Not Available' End) As SLExpireDate,    
    
    (Case When IsNull(c.ShelfLifeDays,0)>0 and (c.ManufactureDate Is Not Null) Then     
     Convert(varchar(10),Case When IsNull(c.ShelfLifeDays,0)>DateDiff(Day,c.ManufactureDate,@CurrDate) Then     
       IsNull(c.ShelfLifeDays,0)-DateDiff(Day,c.ManufactureDate,@CurrDate)    
     Else 0 End)     
     Else '0' End) As SLRemainDays,    
    
    (Case When IsNull(c.ShelfLifeDays,0)>0 and (c.ManufactureDate Is Not Null) Then     
     (Case When DateDiff(Day,c.ManufactureDate,@CurrDate)>IsNull(c.ShelfLifeDays,0) Then 'Expired'     
    Else 'Not Expired' End) Else 'Not Available' End) As ShelfLifeStatus,     
         
    (Case When IsNull(c.ShelfLifeDays,0)>0 and (c.ManufactureDate Is Not Null) Then     
     (Case When DateDiff(Day,c.ManufactureDate,@CurrDate)>=(IsNull(c.ShelfLifeDays,0)-@BeforeAlertDays)     
          and DateDiff(Day,c.ManufactureDate,@CurrDate)<=IsNull(c.ShelfLifeDays,0) Then     
       Convert(varchar(10),(DateDiff(Day,c.ManufactureDate,@CurrDate)-IsNull(c.ShelfLifeDays,0)-@BeforeAlertDays)) + ' days before expiration'    
      Else (Case When DateDiff(Day,c.ManufactureDate,@CurrDate)>IsNull(c.ShelfLifeDays,0) Then 'Expired'    
         Else 'Not Available' End)    
      End)    
     Else 'Not Available' End) As AlertStatus,     
        
    IsNull(Sum(Case When (b.ToWarehouseCode=@WarehouseCode and b.ToRackBinCode=IsNull(@RackBinCode,'')) Then b.Qty               
      When (b.FromWarehouseCode=@WarehouseCode and b.FromRackBinCode=IsNull(@RackBinCode,'')) Then -b.Qty  Else 0 End),0) As CBQty1,            
    IsNull(Sum(Case When (a.ToWarehouseCode=@WarehouseCode and a.ToRackBinCode=IsNull(@RackBinCode,'')) Then a.TransactionQty               
      When (a.FromWarehouseCode=@WarehouseCode and a.FromRackBinCode=IsNull(@RackBinCode,'')) Then -a.TransactionQty Else 0 End),0) As CBQty2,        
    IsNull(m.Rate,0) As Rate, m.UOMDesc As UOM, IsNull(m.UOMDecimal,0) As NoOfDec         
    From Inv_MaterialTran_Dtl a              
   Left Outer Join COM_Trace_MaterialTran_TmpQty b        
   On a.ICode=b.TranID and a.TransactionItem=b.ItemCode and a.FromWarehouseCode=b.FromWarehouseCode         
    and a.ToWarehouseCode=b.ToWarehouseCode and a.FromRackBinCode=b.FromRackBinCode and a.ToRackBinCode=b.ToRackBinCode        
    and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear        
   Left Outer Join REC_ReceiptEntry_Dtl_Trace c         
    On a.DOCNo=c.ReceiptEntryNo and a.DOCDate=c.ReceiptEntryDate and a.DOCType=c.ReceiptEntryType         
     and a.TransactionItem=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID and a.Finyear=c.Finyear    
   Left Outer Join Material_Master m        
   On a.TransactionItem = m.ItemCode and a.Branchid = m.Branchid and a.CompID=m.CompID       
   Where @WarehouseCode In(a.FromWarehouseCode, a.ToWarehouseCode)          
    and @RackBinCode In(a.FromRackBinCode, a.ToRackBinCode)            
    and a.TransactionDate <= @AsOnDate and m.Status='1'              
    and (@ItemNature='' or (@ItemNature<>'' and m.ItemNature=@ItemNature))        
    and (@ItemUserKey='' or (@ItemUserKey<>''         
     and Exists(Select * From COM_SelectList s1        
      Where s1.UserKey=@ItemUserKey and s1.SelectStr=a.TransactionItem         
        and s1.BranchID=@BranchID and s1.CompID=@CompID        
        ))        
     )        
    and a.BranchID = @BranchID and a.CompID = @CompID --and a.Finyear = @Finyear                
    Group by m.ItemNature, a.TransactionItem, m.ItemDescription, m.Rate, m.UOMDesc, m.UOMDecimal,        
     b.LotID, b.SubLotID, c.ManufactureDate, c.ShelfLifeDays          
   ) x        
   Where IsNull(x.ItemCode,'')<>''   
    and (@ChkRestrictZeroStockItem='0' or (@ChkRestrictZeroStockItem='1' and IsNull(x.CBQty1,IsNull(CBQty2,0))<>0))        
   Order by ItemNature, x.ItemCode     
  End    
 Else    
  Begin    
  Select Distinct IsNull(x.ItemNature,'') As ItemNature, x.ItemCode, IsNull(x.ItemDescription,'') As ItemDescription,         
    IsNull(x.LotID,0) As LotID, IsNull(x.SubLotID,0) As SubLotID, IsNull(x.CBQty1,IsNull(CBQty2,0)) As CBQty,         
    IsNull(x.UOM,'') As UOM, IsNull(x.NoOfDec,0) As NoOfDec,     
    Case When (x.ManufactureDate Is Not Null) Then Convert(varchar(10),x.ManufactureDate,121)     
    Else 'Not Available' End As ManufactureDate, IsNull(x.ShelfLifeDays,0) As ShelfLifeDays,    
    IsNull(x.SLExpireDate,'Not Available') As SLExpireDate, IsNull(x.SLRemainDays,'Not Available') As SLRemainDays,    
    IsNull(x.ShelfLifeStatus,'Not Available') As ShelfLifeStatus, IsNull(x.AlertStatus,'Not Available') As AlertStatus         
   From         
   ( Select m.ItemNature, a.TransactionItem As ItemCode, m.ItemDescription,        
    IsNull(b.LotID,0) As LotID, IsNull(b.SubLotID,0) As SubLotID,     
    c.ManufactureDate, c.ShelfLifeDays,    
    
    (Case When IsNull(c.ShelfLifeDays,0)>0 and (c.ManufactureDate Is Not Null) Then     
     Convert(varchar(10),DateAdd(Day,IsNull(c.ShelfLifeDays,0),c.ManufactureDate))    
     Else 'Not Available' End) As SLExpireDate,    
    
    (Case When IsNull(c.ShelfLifeDays,0)>0 and (c.ManufactureDate Is Not Null) Then     
     Convert(varchar(10),Case When IsNull(c.ShelfLifeDays,0)>DateDiff(Day,c.ManufactureDate,@CurrDate) Then     
       IsNull(c.ShelfLifeDays,0)-DateDiff(Day,c.ManufactureDate,@CurrDate)    
     Else 0 End)     
     Else '0' End) As SLRemainDays,    
    
    (Case When IsNull(c.ShelfLifeDays,0)>0 and (c.ManufactureDate Is Not Null) Then     
     (Case When DateDiff(Day,c.ManufactureDate,@CurrDate)>IsNull(c.ShelfLifeDays,0) Then 'Expired'     
    Else 'Not Expired' End) Else 'Not Available' End) As ShelfLifeStatus,     
         
    (Case When IsNull(c.ShelfLifeDays,0)>0 and (c.ManufactureDate Is Not Null) Then     
     (Case When DateDiff(Day,c.ManufactureDate,@CurrDate)>=(IsNull(c.ShelfLifeDays,0)-@BeforeAlertDays)     
          and DateDiff(Day,c.ManufactureDate,@CurrDate)<=IsNull(c.ShelfLifeDays,0) Then     
       Convert(varchar(10),(DateDiff(Day,c.ManufactureDate,@CurrDate)-IsNull(c.ShelfLifeDays,0)-@BeforeAlertDays)) + ' days before expiration'    
      Else (Case When DateDiff(Day,c.ManufactureDate,@CurrDate)>IsNull(c.ShelfLifeDays,0) Then 'Expired'    
         Else 'Not Available' End)    
      End)    
     Else 'Not Available' End) As AlertStatus,    
            
    IsNull(Sum(Case When (b.ToWarehouseCode=@WarehouseCode and b.ToRackBinCode=IsNull(@RackBinCode,'')) Then b.Qty               
      When (b.FromWarehouseCode=@WarehouseCode and b.FromRackBinCode=IsNull(@RackBinCode,'')) Then -b.Qty  Else 0 End),0) As CBQty1,            
    IsNull(Sum(Case When (a.ToWarehouseCode=@WarehouseCode and a.ToRackBinCode=IsNull(@RackBinCode,'')) Then a.TransactionQty               
      When (a.FromWarehouseCode=@WarehouseCode and a.FromRackBinCode=IsNull(@RackBinCode,'')) Then -a.TransactionQty Else 0 End),0) As CBQty2,  
    m.UOMDesc As UOM, IsNull(m.UOMDecimal,0) As NoOfDec         
    From Inv_MaterialTran_Dtl a              
   Left Outer Join COM_Trace_MaterialTran_TmpQty b        
   On a.ICode=b.TranID and a.TransactionItem=b.ItemCode and a.FromWarehouseCode=b.FromWarehouseCode         
    and a.ToWarehouseCode=b.ToWarehouseCode and a.FromRackBinCode=b.FromRackBinCode and a.ToRackBinCode=b.ToRackBinCode        
    and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear        
   Left Outer Join REC_ReceiptEntry_Dtl_Trace c         
    On a.DOCNo=c.ReceiptEntryNo and a.DOCDate=c.ReceiptEntryDate and a.DOCType=c.ReceiptEntryType         
     and a.TransactionItem=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID and a.Finyear=c.Finyear    
   Left Outer Join Material_Master m        
   On a.TransactionItem = m.ItemCode and a.Branchid = m.Branchid and a.CompID=m.CompID       
   Where @WarehouseCode In(a.FromWarehouseCode, a.ToWarehouseCode)          
    and @RackBinCode In(a.FromRackBinCode, a.ToRackBinCode)            
    and a.TransactionDate<=@AsOnDate and m.Status='1'               
    and (@ItemNature='' or (@ItemNature<>'' and m.ItemNature=@ItemNature))        
    and (@ItemUserKey='' or (@ItemUserKey<>''         
     and Exists(Select * From COM_SelectList s1        
      Where s1.UserKey=@ItemUserKey and s1.SelectStr=a.TransactionItem         
        and s1.BranchID=@BranchID and s1.CompID=@CompID        
        ))        
     )        
    and a.BranchID = @BranchID and a.CompID = @CompID --and a.Finyear = @Finyear                
    Group by m.ItemNature, a.TransactionItem, m.ItemDescription, m.UOMDesc, m.UOMDecimal,        
     b.LotID, b.SubLotID, c.ManufactureDate, c.ShelfLifeDays          
   ) x        
   Where IsNull(x.ItemCode,'')<>''   
    and (@ChkRestrictZeroStockItem='0' or (@ChkRestrictZeroStockItem='1' and IsNull(x.CBQty1,IsNull(CBQty2,0))<>0))        
   Order by ItemNature, x.ItemCode       
  End         
END        
GO

/****** Object:  StoredProcedure [dbo].[INV_Rpt_ShelfLifePeriodReport_Sel]    Script Date: 17/06/2026 11:30:18 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[INV_Rpt_ShelfLifePeriodReport_Sel] (@ItemNature char(1), @WarehouseCode varchar(6)='',   
@RackBinCode varchar(6)='', @ChkRestZeroStkItem bit='0', @AsOnDate datetime, @RptDate datetime,   
@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS          
BEGIN          
 SET NOCOUNT ON; 

 Declare @TmpTbl_MaterialTran As Table
 (
		ICode int,
		DOCType varchar(3),
		DOCNo int,
		DOCDate datetime,		
		TransactionDate datetime,
		TransactionTime datetime,
		TransactionItem varchar(20),
		TransactionQty float,
		FromWarehouseCode varchar(6),
		ToWarehouseCode varchar(6), 
		FromRackBinCode varchar(6),	
		ToRackBinCode varchar(6), 
		BranchID varchar(3), 
		CompID varchar(3), 
		Finyear varchar(20)
 )

 Declare @TmpTbl_MaterialTran_TmpQty As Table
 (
		TranID int,		
		ItemCode varchar(20),		
		Qty float,
		FromWarehouseCode varchar(6),
		ToWarehouseCode varchar(6), 
		FromRackBinCode varchar(6),	
		ToRackBinCode varchar(6), 
		BranchID varchar(3), 
		CompID varchar(3), 
		Finyear varchar(20)
 )
 
 /* Insert Data Into Temp Table */
 Begin
	Insert Into @TmpTbl_MaterialTran

	Select a.ICode, a.DOCType, a.DOCNo, a.DOCDate, a.TransactionDate, a.TransactionTime, a.TransactionItem, 
				a.TransactionQty, a.FromWarehouseCode, a.ToWarehouseCode, a.FromRackBinCode, a.ToRackBinCode, 
				a.BranchID, a.CompID, a.Finyear
	From INV_MATERIALTRAN_DTL a
	Where @WarehouseCode In(a.FromWarehouseCode, a.ToWarehouseCode)          
			and @RackBinCode In(a.FromRackBinCode, a.ToRackBinCode)            
			and a.TransactionDate<=@AsOnDate    
			and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear 		

	Insert Into @TmpTbl_MaterialTran_TmpQty

	Select a.TranID, a.ItemCode, a.Qty, a.FromWarehouseCode, a.ToWarehouseCode, a.FromRackBinCode, 
					a.ToRackBinCode, a.BranchID, a.CompID, a.Finyear
	From COM_Trace_MaterialTran_TmpQty a   
	Where Exists(Select * From @TmpTbl_MaterialTran mt1
							Where mt1.ICode=a.TranID and mt1.TransactionItem=a.ItemCode and mt1.FromWarehouseCode=a.FromWarehouseCode         
										and mt1.ToWarehouseCode=a.ToWarehouseCode and mt1.FromRackBinCode=a.FromRackBinCode 
										and mt1.ToRackBinCode=a.ToRackBinCode	and mt1.BranchID=@BranchID 
										and mt1.CompID=@CompID and mt1.Finyear=@Finyear
					)
				and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear				
End 

/* Output Data */
	Select Distinct x.TransactionItem, x.ItemDescription  
	From ( 
		Select a.TransactionItem, m.ItemDescription,   
		IsNull(Sum(Case When (b.ToWarehouseCode=@WarehouseCode and b.ToRackBinCode=IsNull(@RackBinCode,'')) Then b.Qty               
			When (b.FromWarehouseCode=@WarehouseCode and b.FromRackBinCode=IsNull(@RackBinCode,'')) Then -b.Qty  Else 0 End),0) As CBQty1,            
		IsNull(Sum(Case When (a.ToWarehouseCode=@WarehouseCode and a.ToRackBinCode=IsNull(@RackBinCode,'')) Then a.TransactionQty               
			When (a.FromWarehouseCode=@WarehouseCode and a.FromRackBinCode=IsNull(@RackBinCode,'')) Then -a.TransactionQty Else 0 End),0) As CBQty2  
		From @TmpTbl_MaterialTran a  
		Left Outer Join @TmpTbl_MaterialTran_TmpQty b        
			On a.ICode=b.TranID and a.TransactionItem=b.ItemCode and a.FromWarehouseCode=b.FromWarehouseCode         
				and a.ToWarehouseCode=b.ToWarehouseCode and a.FromRackBinCode=b.FromRackBinCode and a.ToRackBinCode=b.ToRackBinCode        
				and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear   
		Left Outer Join INV_MATERIAL_MASTER m   
		On a.TransactionItem=m.ItemCode and a.BranchID=m.BranchID and a.CompID=m.CompID   
		Where m.Status='1' and (@ItemNature='' or (@ItemNature<>'' and m.ItemNature=@ItemNature))   
			and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear   
		Group by a.TransactionItem, m.ItemDescription  
	) x  
	Where IsNull(x.TransactionItem,'')<>''   
		and (@ChkRestZeroStkItem='0' or (@ChkRestZeroStkItem='1' and IsNull(x.CBQty1,IsNull(CBQty2,0))<>0))     
	Order by x.TransactionItem         
END   
GO

/****** Object:  StoredProcedure [dbo].[INV_Rpt_StockMultiWHS_Gen]    Script Date: 17/06/2026 11:30:18 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[INV_Rpt_StockMultiWHS_Gen] (@IsProduct bit='0', @ItemNatureUserKey varchar(36), @WHSUserKey Varchar(36), 
	@ItemUserKey varchar(36), @ShowZeroStock as bit, @StockDate datetime, @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))    
AS                                            
BEGIN                                            
 SET NOCOUNT ON;               
      
 DECLARE @TblStockMultiWHS Table (ItemCode Varchar(30), ItemDesc Varchar(50), UomDesc Varchar(3), UomDecimal int, WarehouseCode Varchar(6), 
		WarehouseName Varchar(50), RackBinCode Varchar(6), RackBin Varchar(30), CBQty Decimal(20,6), IsSubcontractor Varchar(1))  
   
 Insert into @TblStockMultiWHS  
  Select a.ItemCode, IsNull(b.ItemDesc, '') ItemDesc, IsNull(b2.SDesc, '')  as UomDesc, IsNull(b2.NoofDecimals, '')  as UomDecimal,    
   a.WarehouseCode, isNull(c.WarehouseName,'') as WarehouseName,     
   a.RackCode as RackBin, isNull(d.[Description], '') as RackBin, a.CBQty, '0' as IsSubcontractor               
  from fn_INV_AsOnDate_Stock(@StockDate, @BranchID, @CompID, @Finyear) a    
    
  Left Outer Join dbo.fn_BOM_Get_Material_AssetItem_MasterCode('R', @AsOnDate, @RptDate, @BranchID, @CompID) b    
   On a.ItemCode=(b.Itemcode+b.AssetCode) and a.BranchID=b.BranchID and a.CompID=b.CompID    
      
  Left Outer Join INV_UOM_Master b2		--dbo.fn_BOM_UOM_Master('W', @AsOnDate, @RptDate, @BranchID, @CompID) b2    
   On b.UOMCode=b2.Code    
  /*    
  Left outer join dbo.fn_BOM_Get_Material_Master_Inv('A', @AsOnDate, @RptDate, @BranchID, @CompID) b                                
  On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID    
  */                 
  Left Outer Join fn_INV_Get_WareHouse_Master_All('W', @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) c                                      
   On c.WarehouseCode=a.WarehouseCode              
  Left Outer Join INV_RackBin_Master d		-- fn_INV_RackBin_Master('A',@AsOnDate, @RptDate, @BranchID, @CompID) d                                      
   On d.WarehouseCode=c.WarehouseCode and d.RackBinCode=a.RackCode             
  Where a.WarehouseCode not in ('OPB','WAP','SV','SCO')      
   and (@ShowZeroStock='0' OR (@ShowZeroStock='1'and a.CBQty>0))    
   and (@ItemUserKey=''                             
     OR (@ItemUserKey<>'' and Exists (Select * From COM_SelectList s1                                                   
        Where s1.UserKey=@ItemUserKey and s1.SelectStr=a.ItemCode                         
         and s1.BranchID=@BranchID and s1.CompID=@CompID                              
       ))                       
    )    
   and (@WHSUserKey=''                             
     OR (@WHSUserKey<>'' and Exists (Select * From COM_SelectList s1                                                   
        Where s1.UserKey=@WHSUserKey and s1.SelectStr=a.WarehouseCode                         
         and s1.BranchID=@BranchID and s1.CompID=@CompID                              
        ))                      
    )               
   and (@ItemNatureUserKey=''                         
     OR (@ItemNatureUserKey<>'' and Exists (Select * From COM_SelectList s1                                               
        Where s1.UserKey=@ItemNatureUserKey and s1.SelectStr=b.ItemNatureCode                     
        and s1.BranchID=@BranchID and s1.CompID=@CompID                          
     ))                   
    )  
  Order by WarehouseCode, a.ItemCode    
    
 IF @IsProduct = '1'  
  BEGIN  
   /* Get ERP Option Code, Option Value */        
   DECLARE @OptionCode int; 
   DECLARE @IsCarryForwardSubcontractStock bit;
   
   SET @OptionCode=87;
   SET @IsCarryForwardSubcontractStock='0';

    Select @IsCarryForwardSubcontractStock = IsNull(OptionValue,'0')    
    From fn_COM_ERP_Options(@AsOnDate, @RptDate, @BranchID, @CompID)    
    Where OptionCode=@OptionCode    
  
   Insert into @TblStockMultiWHS  
    Select b.SentItemCode as ItemCode, IsNull(d.ItemDesc,'') as ItemDesc, IsNull(d.UomDesc, '')  as UomDesc, IsNull(d.UomDecimal, '')  as UomDecimal,   
     Convert(Varchar,a.VendorCode) as WarehouseCode, c.LedgerName as WarehouseName,  '' as RackBinCode, '' as RackBin, IsNull(Sum(b.ScheduleQty),0) as CBQty, '1' as IsSubcontractor                                  
    From Pur_DCSR_Hdr a                                      
    Left Outer Join fn_Pur_DCSR_Tran(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) b                         
     On a.DCSRNo=b.DCSRNo and a.DCSRDate=b.DCSRDate and a.DCSRType=b.DCSRType                                          
    Left Outer Join dbo.fn_BOM_Get_Material_Inv('A',@AsOnDate, @RptDate, @BranchID, @CompID) d                                         
     On b.SentItemCode = d.ItemCode   
    Left Outer Join FAS_LedgerMaster_AuthTbl c  
     On a.VendorCode=c.LedgerCode and c.CompCode=a.CompID+a.BranchID  
    Where b.CreatedDate <= @StockDate and a.BranchId=@BranchID and a.CompID=@CompID                            
     and (@IsCarryForwardSubcontractStock='1' OR a.Finyear=@FinYear)   
     and (@ItemUserKey=''                             
       OR (@ItemUserKey<>'' and Exists (Select * From COM_SelectList s1                                                   
          Where s1.UserKey=@ItemUserKey and s1.SelectStr=b.SentItemCode                         
           and s1.BranchID=@BranchID and s1.CompID=@CompID                              
         ))                        
      )    
     and (@WHSUserKey=''                             
       OR (@WHSUserKey<>'' and Exists (Select * From COM_SelectList s1                                                   
          Where s1.UserKey=@WHSUserKey and s1.SelectStr=Convert(Varchar,a.VendorCode)  
           and s1.BranchID=@BranchID and s1.CompID=@CompID                              
          ))                        
      )               
     and (@ItemNatureUserKey=''                         
       OR (@ItemNatureUserKey<>'' and Exists (Select * From COM_SelectList s1                                               
          Where s1.UserKey=@ItemNatureUserKey and s1.SelectStr=d.ItemNatureCode                     
          and s1.BranchID=@BranchID and s1.CompID=@CompID                          
       ))                    
      )    
    Group By b.SentItemCode, d.ItemDesc, d.UomDesc, d.UomDecimal, a.VendorCode, c.LedgerName  
    Having (@ShowZeroStock='0' OR (@ShowZeroStock='1'and Sum(b.ScheduleQty)>0))  
    --Having Sum(b.ScheduleQty) <> 0                                     
  END  
  
	/* Output (Result) */   
	Select a.ItemCode, a.ItemDesc, a.UomDesc, a.UomDecimal, a.WarehouseCode, a.WarehouseName, 
		a.RackBinCode, a.RackBin, a.CBQty, a.IsSubcontractor    
	From @TblStockMultiWHS a  
	Order by IsSubcontractor, WarehouseCode, ItemCode   
            
END
GO

/****** Object:  StoredProcedure [dbo].[INV_Rpt_StockReport_Gen_LotIDBased]    Script Date: 17/06/2026 11:30:18 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[INV_Rpt_StockReport_Gen_LotIDBased] (@ItemUserKey varchar(36)='', @ItemNature char(1),        
@WarehouseCode varchar(6)='', @RackBinCode varchar(6)='', @ChkRestZeroStkItem bit='0', @AsOnDate datetime,         
@RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
          
AS          
BEGIN          
SET NOCOUNT ON;        
          
 Select Distinct IsNull(x.ItemNature,'') As ItemNature, x.ItemCode, IsNull(x.ItemDescription,'') As ItemDescription,         
   IsNull(x.LotID,0) As LotID, IsNull(x.SubLotID,0) As SubLotID, IsNull(x.CBQty1,IsNull(CBQty2,0)) As CBQty,         
   IsNull(x.Rate,0) As Rate, IsNull(x.UOM,'') As UOM, IsNull(x.NoOfDec,0) As NoOfDec                
 From         
 ( Select m.ItemNature, a.TransactionItem As ItemCode, m.ItemDescription,        
    IsNull(b.LotID,0) As LotID, IsNull(b.SubLotID,0) As SubLotID,              
    IsNull(Sum(Case When (b.ToWarehouseCode=@WarehouseCode and b.ToRackBinCode=IsNull(@RackBinCode,'')) Then b.Qty               
        When (b.FromWarehouseCode=@WarehouseCode and b.FromRackBinCode=IsNull(@RackBinCode,'')) Then -b.Qty  Else 0 End),0) As CBQty1,            
    IsNull(Sum(Case When (a.ToWarehouseCode=@WarehouseCode and a.ToRackBinCode=IsNull(@RackBinCode,'')) Then a.TransactionQty               
        When (a.FromWarehouseCode=@WarehouseCode and a.FromRackBinCode=IsNull(@RackBinCode,'')) Then -a.TransactionQty Else 0 End),0) As CBQty2,        
    IsNull(m.Rate,0) As Rate, m.UOMDesc As UOM, IsNull(m.UOMDecimal,0) As NoOfDec         
  From Inv_MaterialTran_Dtl a              
  Left Outer Join COM_Trace_MaterialTran_TmpQty b        
  On a.ICode=b.TranID and a.TransactionItem=b.ItemCode and a.FromWarehouseCode=b.FromWarehouseCode         
   and a.ToWarehouseCode=b.ToWarehouseCode and a.FromRackBinCode=b.FromRackBinCode and a.ToRackBinCode=b.ToRackBinCode        
   and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear        
 Left Outer Join Material_Master m        
  On a.TransactionItem = m.ItemCode and a.Branchid = m.Branchid and a.CompID=m.CompID        
  Where @WarehouseCode In(a.FromWarehouseCode, a.ToWarehouseCode)          
   and @RackBinCode In(a.FromRackBinCode, a.ToRackBinCode)            
   and a.TransactionDate <= @AsOnDate              
   and (@ItemNature='' or (@ItemNature<>'' and m.ItemNature=@ItemNature))        
   and (@ItemUserKey='' or (@ItemUserKey<>''         
      and Exists(Select * From COM_SelectList s1        
        Where s1.UserKey=@ItemUserKey and s1.SelectStr=a.TransactionItem         
           and s1.BranchID=@BranchID and s1.CompID=@CompID        
           ))        
     )        
   and a.BranchID = @BranchID and a.CompID = @CompID --and a.Finyear = @Finyear                
    Group by m.ItemNature, a.TransactionItem, m.ItemDescription, m.Rate, m.UOMDesc, m.UOMDecimal,        
     b.LotID, b.SubLotID          
 ) x        
 Where IsNull(x.ItemCode,'')<>'' and (@ChkRestZeroStkItem='0' or (@ChkRestZeroStkItem='1' and IsNull(x.CBQty1,IsNull(CBQty2,0))<>0))        
 Order by ItemNature, x.ItemCode        
END 
GO

/****** Object:  StoredProcedure [dbo].[INV_Rpt_StockReport_Gen_Summary]    Script Date: 17/06/2026 11:30:18 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
