CREATE PROCEDURE [dbo].[INV_StockConversion_Hlp_ItemDtl](@ItemNatureCode varchar(2), @AsOnDate datetime, 
	@RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(15))    
As    
 BEGIN    
  SET NOCOUNT ON;    
      
	Select a.itemcode As ItemCode, a.itemdescription As ItemDesc, a.itemnature As ItemNatureCode, 
			b.ItemNatureDesc As ItemNatureDesc, IsNull(a.UOM,0) As UOM, IsNull(a.UOMDesc,'') As UOMDesc,
			IsNull(a.UOMDecimal,0) As UOMDecimal 			   
	From Material_Master a   
	Left Outer Join BOM_ItemNature_Master b    
		On a.itemnature=b.ItemNatureCode		  
	Where a.itemnature=@ItemNatureCode	
	/*		
				and Exists(Select * From Inv_MaterialTran_Dtl t1
										Where t1.TransactionItem=a.ItemCode and t1.BranchID=@BranchID and t1.CompID=@CompID
													and t1.Finyear=@Finyear
									)
 */
				/* ((@ItemNatureCode Not In('CR','CC') and (a.itemnature In(@ItemNatureCode,'CR','CC')))
					or (@ItemNatureCode In('CR','CC') and a.itemnature=@ItemNatureCode)
				)	*/		
			and b.Status='1' and a.BranchID=@BranchID and a.CompID=@CompID       
	Order by a.ItemCode             
END
