CREATE PROCEDURE [dbo].[INV_StockConversion_Hlp_ItemNature](@Status bit='1')    
As    
BEGIN    
  SET NOCOUNT ON;
      
	Select a.ItemNatureCode, a.ItemNatureDesc
  From BOM_ItemNature_Master a
  Where a.Status=@Status and a.ItemNatureCode In('R', 'F', 'C', 'CR', 'CC')
  Order by a.ItemNatureDesc
END
