/****** Object:  StoredProcedure [dbo].[INV_StockConversion_Hlp_ItemQty]    Script Date: 17/06/2026 11:30:18 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[INV_StockConversion_Hlp_ItemQty](@ChildCode varchar(20), @AsOnDate datetime, 
 @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))
As
BEGIN
  SET NOCOUNT ON;

	Select b.ItemCode, c.itemdescription As ItemDesc, a.Qty
	From BOM_Structure_Dtl a
	Left Outer Join BOM_MPS_MASTER b 
	   On a.ParentCode=b.StageCode and a.BranchID=b.BranchID and a.CompId=b.CompID
	Left Outer Join Material_Master c
	   On c.ItemCode=b.ItemCode and c.BranchID=b.BranchID and c.CompId=b.CompID 
	Where a.ChildCode=@ChildCode and b.ItemCode<>'' and a.BranchID=@BranchID and a.CompID=@CompID 
									
END
GO

