CREATE PROCEDURE [dbo].[INV_StockConversion_Hlp_StageOpt](@ItemNatureCode varchar(2), @ItemCode varchar(20), 
 @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))
As
BEGIN
  SET NOCOUNT ON;
  
	If @ItemNatureCode<>'R' and @ItemNatureCode<>'CR'
	 Begin
		Select Distinct a.StageCode, IsNull(b.itemdescription,'') As StageDesc, a.OperationCode, a.OperationSequence, 
				IsNull(b.UOM,'') As UOM, IsNull(b.UOMDesc,'') As UOMDesc, IsNull(b.UOMDecimal,0) As UOMDecimal,
				IsNull((Select dbo.fn_BOM_Norms(@ItemCode, a.StageCode, @AsOnDate, @RptDate, @BranchID, @CompID)),1) As Norms						

		From BOM_MPS_MASTER a
		Left Outer Join Material_Master b
			  On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompId=b.CompID
		Where Exists( Select * From BOM_MPS_MASTER c
									  Where c.ItemCode=a.ItemCode and c.StageCode=@ItemCode and c.Status='1'
													and c.BranchID=a.BranchID and c.CompId=a.CompID
									)     
				and a.StageCode<>@ItemCode and a.Status='1' and a.BranchID=@BranchID and a.CompID=@CompID 
	 End		
  Else		
	 Begin
		Select Distinct a.StageCode, IsNull(b.itemdescription,'') As StageDesc, a.OperationCode, a.OperationSequence, 
				IsNull(b.UOM,'') As UOM, IsNull(b.UOMDesc,'') As UOMDesc, IsNull(b.UOMDecimal,0) As UOMDecimal 			
		From BOM_MPS_MASTER a
		Left Outer Join Material_Master b
			On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompId=b.CompID
		Where Exists( Select * From BOM_MPS_MASTER c
									  Where c.ItemCode=a.ItemCode and c.StageCode=@ItemCode and c.Status='1'
													and c.BranchID=a.BranchID and c.CompId=a.CompID
									) 
					and a.Status='1' and a.BranchID=@BranchID and a.CompID=@CompID
					  	
	 End		
END
GO

