CREATE PROCEDURE [dbo].[INV_StockConversion_Hlp_WarehouseMRN](@IsIGR int, @WHNature char(2), @AsOnDate datetime, 
@RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                   
AS      
BEGIN      
    SET NOCOUNT ON      
                
    Declare @IsWhsFilter int     
		
		SET @IsWhsFilter=0;
   /* Select @IsWhsFilter=OptionValue From COM_ERP_Options 
		  Where OptionCode=15 and BranchID=@BranchID and CompID=@CompID */
                    
    If @WHNature='HI' and @IsIGR='2'                  
        Begin                  
            If @IsWhsFilter=1                
                Select a.WarehouseCode, a.WarehouseName, a.WarehouseNature, a.WarehouseLocation                    
                From INV_Warehouse_Master a                   
                Where a.WarehouseNature In('InHouse','Inspection') and a.WarehouseCode In('RMS') 
										and a.WarehouseStatus='1' and a.BranchID=@BranchID and a.CompID=@CompID
            Else                
                Select a.WarehouseCode, a.WarehouseName, a.WarehouseNature, a.WarehouseLocation                    
                From INV_Warehouse_Master a                   
                Where a.WarehouseNature In('InHouse','Inspection') and a.WarehouseStatus='1' 
											and a.BranchID=@BranchID and a.CompID=@CompID                 
					End   
					                
    Else If @WHNature='HI' and @IsIGR='1'                  
        Begin                  
            If @IsWhsFilter=1                
                Select a.WarehouseCode, a.WarehouseName, a.WarehouseNature, a.WarehouseLocation                    
                From INV_Warehouse_Master a                   
                Where a.WarehouseNature In('InHouse','Inspection') and a.WarehouseCode In('WFF','CSF') 
											and a.WarehouseStatus='1' and a.BranchID=@BranchID and a.CompID=@CompID    
            Else                
                Select a.WarehouseCode, a.WarehouseName, a.WarehouseNature, a.WarehouseLocation                    
                From INV_Warehouse_Master a                   
                Where a.WarehouseNature In('InHouse','Inspection') and a.WarehouseStatus='1' 
									and a.BranchID=@BranchID and a.CompID=@CompID                  
        End                     
                     
    Else If @WHNature='HI' and @IsIGR='0'                  
        Begin                  
            If @IsWhsFilter=1                
                Select a.WarehouseCode, a.WarehouseName, a.WarehouseNature, a.WarehouseLocation                    
                From INV_Warehouse_Master a                   
                Where a.WarehouseCode In('FGS') and a.WarehouseStatus='1' 
									and a.BranchID=@BranchID and a.CompID=@CompID                    
            Else                
                Select a.WarehouseCode, a.WarehouseName, a.WarehouseNature, a.WarehouseLocation                    
                From INV_Warehouse_Master a                   
                Where a.WarehouseCode In('FGS') and a.WarehouseStatus='1' 
									and a.BranchID=@BranchID and a.CompID=@CompID      
        End                
                 
    Else If @WHNature='I' and @IsIGR='0'                  
        Begin                  
            Select a.WarehouseCode, a.WarehouseName, a.WarehouseNature, a.WarehouseLocation                    
            From INV_Warehouse_Master a                   
            Where a.WarehouseNature In('InHouse') and a.WarehouseStatus='1' 
									and a.BranchID=@BranchID and a.CompID=@CompID      
        End                  
                 
    Else If @WHNature='S' and @IsIGR='0'                  
        Begin                  
            Select a.WarehouseCode, a.WarehouseName                   
          From INV_Warehouse_Master a                   
            Where a.WarehouseNature='Scrap' and a.WarehouseStatus='1' 
									and a.BranchID=@BranchID and a.CompID=@CompID                   
        End                   
                 
    Else If @WHNature='A' and @IsIGR='0'                   
        Begin                     
            Select a.WarehouseCode, a.WarehouseName, a.WarehouseNature                    
            From dbo.fn_INV_Warehouse_Master_Get_All('1', @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a                  
            Where a.WarehouseStatus='1' and a.BranchID=@BranchID and a.CompID=@CompID                   
            Order by a.WarehouseNature, a.WarehouseName                  
        End      
    Else      
        Begin      
            Select a.WarehouseCode, a.WarehouseName, a.WarehouseNature, a.WarehouseLocation                    
            From dbo.fn_INV_Warehouse_Master('1', @AsOnDate, @RptDate, @BranchID, @CompID) a                  
            Where a.WarehouseStatus='1' and a.BranchID=@BranchID and a.CompID=@CompID                  
            Order by a.WarehouseCode,a.WarehouseName       
        End                       
END
GO

/****** Object:  StoredProcedure [dbo].[INV_StockConversion_Val_Stock]    Script Date: 17/06/2026 11:30:19 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[INV_StockConversion_Val_Stock](@ItemCode varchar(20), @WHSCode varchar(6),   
@RefType varchar(3)='', @RefNo int=0, @RefDate datetime='1900-01-01', @AsOnDate datetime,   
@RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(15))      
As      
BEGIN      
  SET NOCOUNT ON;  
  
 Declare @StockQty As float;  
 Declare @StkQty As float;  
 Declare @TranQty As float;  
  
 Select @StkQty=0, @TranQty=0;  

 /* Get StockQty Data */  
 Select @StkQty=IsNull(a.CBQty,0)   
 From fn_INV_AsOnDate_Stock_Item_WHS_V2(@ItemCode, @WHSCode, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a
 Where a.BranchID=@BranchID and a.CompID=@CompID
  
 --Select @StkQty=IsNull(a.CBQty,0)   
 --From dbo.fn_INV_AsOnDate_Stock_Item_WHS(@ItemCode, @WHSCode, @AsOnDate, @BranchID, @CompID, @Finyear) a  
 --Where a.BranchID=@BranchID and a.CompID=@CompID
  
 /* Get TransactionQty Data */  
 If IsNull(@RefType,'')<>''  
  Begin  
  Select Top 1 @TranQty=a.TransactionQty  
  From INV_MaterialTran_Dtl a  
  Where a.DocType=@RefType and a.DocNo=@RefNo and a.DocDate=@RefDate  
     and a.TransactionItem=@ItemCode and a.BranchID=@BranchID and a.CompID=@CompID  
  End  
   
 /* Adding StkQty + TranQty */  
 Select @StockQty=IsNull(@StkQty,0)+IsNull(@TranQty,0)  
  
 /* Output */  
 Select IsNull(@StockQty,0) As StockQty  
END
GO

/****** Object:  StoredProcedure [dbo].[INV_StockOpeningBalance_Fil]    Script Date: 17/06/2026 11:30:19 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[INV_StockOpeningBalance_Fil](@ItemNatureCode varchar(2)='',       
 @WareHouseCode varchar(6), @RackBinCode varchar(6), @AsOnDate datetime, @RptDate datetime,       
 @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                        
AS                        
BEGIN                                        
	SET NOCOUNT ON;   
     
 Declare @DocumentType As varchar(3);   
 Declare @PrevFinyear varchar(20);   
 Declare @TmpCurrFin As datetime;      
 Declare @StockDate As datetime;  
 
 SET @DocumentType='OPBAL';			--'OPB';  
 SET @PrevFinyear='';
    
 Declare @PrevFYCBQtySeq1_CurrFYOBQtySeq2 As Table    
 (    
  ItemCode varchar(20), WarehouseCode varchar(6), RackBinCode varchar(10), PrevCBQty decimal(20,6),     
  CurrOBQty decimal(20,6), BranchID  varchar(3), CompID  varchar(3), Finyear  varchar(20), SetSeq int    
 )    
    
 /* Get Previous Finyear */     
 Select @PrevFinyear=dbo.fn_PreviousFinyearProcess_Get_BasedOnGivenFinyear(@Finyear)    
 SET @TmpCurrFin=(SubString(@Finyear,4,4) + '-' + SubString(@Finyear,1,2) + '-01 23:59:59');    
 SET @StockDate=(DateAdd(day,-1,@TmpCurrFin));     
    
 /* Insert Data Into Tmp Table - Previous Finyear CBQty Data */    
 Begin    
  Insert Into @PrevFYCBQtySeq1_CurrFYOBQtySeq2    
  Select a.ItemCode, a.WarehouseCode, a.RackBinCode, a.CBQty As PrevCBQty, 0 As CurrOBQty,       
   a.BranchID, a.CompID, a.Finyear, 1 As SetSeq    
  From dbo.fn_INV_AsOnDate_Stock_V2_OPBal(@StockDate, @StockDate, @StockDate, @BranchID, @CompID, @PrevFinyear) a      
  Where a.WarehouseCode=@WareHouseCode and a.RackBinCode=@RackBinCode and IsNull(a.CBQty,0)>0     
   and a.BranchID=@BranchID and a.CompID=@CompID    
 End    
    
 /* Insert Data Into Tmp Table - Current Finyear OBQty Data  */    
 Begin    
  Insert Into @PrevFYCBQtySeq1_CurrFYOBQtySeq2    
  Select a.TransactionItem As ItemCode, a.ToWarehouseCode, a.ToRackBinCode, 0 As PrevCBQty, IsNull(a.TransactionQty,0) As CurrOBQty,    
   a.BranchID, a.CompID, a.Finyear, 2 As SetSeq    
  From INV_MaterialTran_Dtl a    
  Where a.DocType=@DocumentType and a.FromWarehouseCode=@DocumentType and a.ToWarehouseCode=@WareHouseCode      
    and a.ToRackBinCode=@RackBinCode and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear     
 End    
    
 --Select @PrevFinyear As PrevFinyear, @Finyear As CurrFinyear, @StockDate As StockDate    
 --Select * From @PrevFYCBQtySeq1_CurrFYOBQtySeq2 Where SetSeq=1    
 --Select * From @PrevFYCBQtySeq1_CurrFYOBQtySeq2 Where SetSeq=2    
    
 /* Output (Result) */    
 Select Distinct x.ItemCode, b.ItemDesc, IsNull(b.ItemNatureCode,'') As ItemNatureCode,   
 IsNull(b.UOMDesc,'') As UOMDesc, IsNull(b.LotID,0) As LotID, IsNull(b.HeatNo,'') As HeatNo,   
 IsNull(b.ItemRMRate,0) As ItemRMRate, x.WarehouseCode, IsNull(x.RackBinCode,'') As RackBinCode,     
 IsNull(x.PrevCBQty,0) As PrevCBQty, IsNull(x.CurrOBQty,0) As CurrOBQty, x.SetSeq    
 From (    
 Select a.ItemCode, a.WarehouseCode, IsNull(a.RackBinCode,'') As RackBinCode, IsNull(a.PrevCBQty,0) As PrevCBQty,     
  IsNull(b.CurrOBQty,0) As CurrOBQty, a.BranchID, a.CompID, a.Finyear, a.SetSeq    
 From @PrevFYCBQtySeq1_CurrFYOBQtySeq2 a    
 Left Outer Join @PrevFYCBQtySeq1_CurrFYOBQtySeq2 b    
  On b.SetSeq=2 and a.ItemCode=b.ItemCode and a.WarehouseCode=b.WareHouseCode    
    and a.BranchID=b.BranchID and a.CompID=b.CompID    
 Where a.SetSeq=1 and a.BranchID=@BranchID and a.CompID=@CompID    
    
 UNION    
    
 Select a.ItemCode, a.WarehouseCode, IsNull(a.RackBinCode,'') As RackBinCode, 0 As PrevCBQty,     
  IsNull(a.CurrOBQty,0) As CurrOBQty, a.BranchID, a.CompID, a.Finyear, a.SetSeq    
 From @PrevFYCBQtySeq1_CurrFYOBQtySeq2 a     
 Where a.SetSeq=2 and Not Exists(Select * From @PrevFYCBQtySeq1_CurrFYOBQtySeq2 ps1    
  Where ps1.SetSeq=1 and ps1.ItemCode=a.ItemCode and ps1.WarehouseCode=a.WareHouseCode    
    and IsNull(ps1.PrevCBQty,0)>0 and ps1.BranchID=a.BranchID and ps1.CompID=a.CompID)    
  and a.BranchID=@BranchID and a.CompID=@CompID    
 ) x    
 Inner Join (Select b1.ItemCode, b1.itemdescription as ItemDesc, b1.itemnature as ItemNatureCode, b1.UOMDesc, c1.LotID, c1.HeatNo, c1.ItemRMRate  
     From MATERIAL_MASTER b1		-- dbo.fn_BOM_Get_Material_INV('A',@AsOnDate, @RptDate, @BranchID, @CompID) b1         
      Left Outer Join COM_Trace_LotMaster c1  
       On b1.ItemID=c1.ItemID and c1.TranStamp=(Select Max(c2.TranStamp) From COM_Trace_LotMaster c2  
           Where c2.ItemID=c1.ItemID and c2.BranchID=c1.BranchID and c2.CompID=c1.CompID  
           Group by c2.ItemID)  
        and b1.BranchID=c1.BranchID and b1.CompID=c1.CompID  
     Where (@ItemNatureCode='' or (@ItemNatureCode<>'' and b1.itemnature=@ItemNatureCode))  
      and b1.BranchID=@BranchID and b1.CompID=@CompID  
 ) b  
 On x.ItemCode=b.ItemCode    
 Where x.BranchID=@BranchID and x.CompID=@CompID       
END        
GO

