/****** Object:  StoredProcedure [dbo].[INV_StockReport_Gen_LotIDBased]    Script Date: 17/06/2026 11:30:19 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[INV_StockReport_Gen_LotIDBased] (@ItemUserKey varchar(36)='', @ItemNature char(1),      
@WarehouseCode varchar(6)='', @RackBinCode varchar(6)='', @ChkTran bit='0', @AsOnDate datetime,       
@RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))        
        
AS        
BEGIN        
SET NOCOUNT ON;      
        
 Select Distinct IsNull(x.ItemNature,'') As ItemNature, x.ItemCode, IsNull(x.ItemDescription,'') As ItemDescription,       
   IsNull(x.LotID,0) As LotID, IsNull(x.SubLotID,0) As SubLotID, IsNull(x.CBQty1,IsNull(CBQty2,0)) As CBQty,       
   IsNull(x.Rate,0) As Rate, IsNull(x.UOM,'') As UOM, IsNull(x.NoOfDec,0) As NoOfDec              
 From       
 ( Select m.ItemNature, a.TransactionItem As ItemCode, m.ItemDescription,      
    IsNull(b.LotID,0) As LotID, IsNull(b.SubLotID,0) As SubLotID,            
    IsNull(Sum(Case When (b.ToWarehouseCode = @WarehouseCode and b.ToRackBinCode='') Then b.Qty             
        When (b.FromWarehouseCode = @WarehouseCode and b.FromRackBinCode='') Then -b.Qty  Else 0 End),0) As CBQty1,          
    IsNull(Sum(Case When (a.ToWarehouseCode = @WarehouseCode and a.ToRackBinCode='') Then a.TransactionQty             
        When (a.FromWarehouseCode = @WarehouseCode and a.FromRackBinCode='') Then -a.TransactionQty Else 0 End),0) As CBQty2,      
    IsNull(m.Rate,0) As Rate, m.UOMDesc As UOM, IsNull(m.UOMDecimal,0) As NoOfDec       
   From Inv_MaterialTran_Dtl a            
  Left Outer Join COM_Trace_MaterialTran_TmpQty b      
  On a.ICode=b.TranID and a.TransactionItem=b.ItemCode and a.FromWarehouseCode=b.FromWarehouseCode       
    and a.ToWarehouseCode=b.ToWarehouseCode and a.FromRackBinCode=b.FromRackBinCode and a.ToRackBinCode=b.ToRackBinCode      
    and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear      
 Left Outer Join Material_Master m      
  On a.TransactionItem = m.ItemCode and a.Branchid = m.Branchid and a.CompID=m.CompID      
  Where @WarehouseCode In(a.FromWarehouseCode, a.ToWarehouseCode)        
   and @RackBinCode In(a.FromRackBinCode, a.ToRackBinCode)          
   and a.TransactionDate <= @AsOnDate            
   and (@ItemNature='' or (@ItemNature<>'' and m.ItemNature=@ItemNature))      
   and (@ItemUserKey='' or (@ItemUserKey<>''       
      and Exists(Select * From COM_SelectList s1      
        Where s1.UserKey=@ItemUserKey and s1.SelectStr=a.TransactionItem       
           and s1.BranchID=@BranchID and s1.CompID=@CompID      
           ))      
     )      
   and a.BranchID = @BranchID and a.CompID = @CompID --and a.Finyear = @Finyear              
    Group by m.ItemNature, a.TransactionItem, m.ItemDescription, m.Rate, m.UOMDesc, m.UOMDecimal,      
     b.LotID, b.SubLotID        
 ) x      
 Where IsNull(x.ItemCode,'')<>'' and (@ChkTran='0' or (@ChkTran='1' and IsNull(x.CBQty1,IsNull(CBQty2,0))<>0))      
 Order by ItemNature, x.ItemCode      
END   
GO

/****** Object:  StoredProcedure [dbo].[INV_StockReport_Gen_Summary]    Script Date: 17/06/2026 11:30:19 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[INV_StockReport_Gen_Summary] (@ItemUserKey varchar(36)='', @ItemNature char(1),  
@WarehouseCode varchar(6)='', @RackBinCode varchar(6)='', @ChkTran bit='0', @AsOnDate datetime,   
@RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))    
    
AS    
BEGIN    
SET NOCOUNT ON;  
	Select Distinct IsNull(m.ItemNature,'') As ItemNature, a.ItemCode, IsNull(m.ItemDescription,'') As ItemDescription, 
		IsNull(a.CBQty,0) As CBQty, IsNull(m.Rate,0) As Rate, m.UOMDesc As UOM, IsNull(m.UOMDecimal,0) As NoOfDec
	From dbo.fn_INV_AsOnDate_Stock_WHSRackBin(@WarehouseCode, @RackBinCode, @AsOnDate, @BranchID, @CompID, @Finyear) a     /* dbo.fn_INV_AsOnDate_Stock */
	Left Outer Join Material_Master m  
		On a.ItemCode = m.ItemCode and a.Branchid = m.Branchid and a.CompID=m.CompID  
	Where /* a.WarehouseCode=@WarehouseCode and a.RackCode=@RackBinCode */			     			
			(@ItemNature='' or (@ItemNature<>'' and m.ItemNature=@ItemNature))  
			and (@ItemUserKey='' or (@ItemUserKey<>''   
				and Exists(Select * From COM_SelectList s1  
				Where s1.UserKey=@ItemUserKey and s1.SelectStr=a.ItemCode
					and s1.BranchID=@BranchID and s1.CompID=@CompID  
					))  
				) 
			and IsNull(a.ItemCode,'')<>'' and m.Status='1'
			and (@ChkTran='0' or (@ChkTran='1' and IsNull(a.CBQty,0)<>0))  
			and a.BranchID = @BranchID and a.CompID = @CompID --and a.Finyear = @Finyear          

	Order by ItemNature, a.ItemCode  
END 
GO

/****** Object:  StoredProcedure [dbo].[INV_StockReport_Gen_TraceStatus]    Script Date: 17/06/2026 11:30:19 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[INV_StockReport_Gen_TraceStatus] (@ItemUserKey varchar(36)='', @ItemNature char(1),    
@WarehouseCode varchar(6)='', @RackBinCode varchar(6)='', @ChkTran bit='0', @AsOnDate datetime,     
@RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))      
      
AS      
BEGIN      
SET NOCOUNT ON;   

	Declare @CurrDate As datetime;
	Declare @BeforeAlertDays As int;

	SET @CurrDate=getdate();	/* Get ServerDate */
	SET @BeforeAlertDays=5;
      
 Select Distinct IsNull(x.ItemNature,'') As ItemNature, x.ItemCode, IsNull(x.ItemDescription,'') As ItemDescription,     
   IsNull(x.LotID,0) As LotID, IsNull(x.SubLotID,0) As SubLotID, IsNull(x.CBQty1,IsNull(CBQty2,0)) As CBQty,     
   IsNull(x.Rate,0) As Rate, IsNull(x.UOM,'') As UOM, IsNull(x.NoOfDec,0) As NoOfDec,
	 x.ManufactureDate, IsNull(x.ShelfLifeDays,0) As ShelfLifeDays,
	 IsNull(x.ShelfLifeStatus,'') As ShelfLifeStatus, IsNull(x.AlertStatus,'') As AlertStatus           
 From     
 ( Select m.ItemNature, a.TransactionItem As ItemCode, m.ItemDescription,    
    IsNull(b.LotID,0) As LotID, IsNull(b.SubLotID,0) As SubLotID, 
		c.ManufactureDate, c.ShelfLifeDays,
		(Case When IsNull(c.ShelfLifeDays,0)>0 and (c.ManufactureDate Is Not Null) Then 
			(Case When DateDiff(Day,c.ManufactureDate,@CurrDate)>IsNull(c.ShelfLifeDays,0) Then 'Expired' 
		Else 'Not Expired' End) Else 'Not Available' End) As ShelfLifeStatus,		
		(Case When IsNull(c.ShelfLifeDays,0)>0 and (c.ManufactureDate Is Not Null) Then 
			(Case When DateDiff(Day,c.ManufactureDate,@CurrDate)>=(IsNull(c.ShelfLifeDays,0)-@BeforeAlertDays) 
								and DateDiff(Day,c.ManufactureDate,@CurrDate)<=IsNull(c.ShelfLifeDays,0) Then 
					Convert(varchar(10),(DateDiff(Day,c.ManufactureDate,@CurrDate)-IsNull(c.ShelfLifeDays,0)-@BeforeAlertDays)) + ' days before expiration'
				Else (Case When DateDiff(Day,c.ManufactureDate,@CurrDate)>IsNull(c.ShelfLifeDays,0) Then 'Expired'
							Else 'Not Available' End)
				End)
		 Else 'Not Available' End) As AlertStatus,			
    IsNull(Sum(Case When (b.ToWarehouseCode = @WarehouseCode and b.ToRackBinCode='') Then b.Qty           
        When (b.FromWarehouseCode = @WarehouseCode and b.FromRackBinCode='') Then -b.Qty  Else 0 End),0) As CBQty1,        
    IsNull(Sum(Case When (a.ToWarehouseCode = @WarehouseCode and a.ToRackBinCode='') Then a.TransactionQty           
        When (a.FromWarehouseCode = @WarehouseCode and a.FromRackBinCode='') Then -a.TransactionQty Else 0 End),0) As CBQty2,    
    IsNull(m.Rate,0) As Rate, m.UOMDesc As UOM, IsNull(m.UOMDecimal,0) As NoOfDec     
   From Inv_MaterialTran_Dtl a          
  Left Outer Join COM_Trace_MaterialTran_TmpQty b    
  On a.ICode=b.TranID and a.TransactionItem=b.ItemCode and a.FromWarehouseCode=b.FromWarehouseCode     
    and a.ToWarehouseCode=b.ToWarehouseCode and a.FromRackBinCode=b.FromRackBinCode and a.ToRackBinCode=b.ToRackBinCode    
    and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear    
	Left Outer Join REC_ReceiptEntry_Dtl_Trace c  	  
		On a.DOCNo=c.ReceiptEntryNo and a.DOCDate=c.ReceiptEntryDate and a.DOCType=c.ReceiptEntryType     
     and a.TransactionItem=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID and a.Finyear=c.Finyear
 Left Outer Join Material_Master m    
  On a.TransactionItem = m.ItemCode and a.Branchid = m.Branchid and a.CompID=m.CompID   
  Where @WarehouseCode In(a.FromWarehouseCode, a.ToWarehouseCode)      
   and @RackBinCode In(a.FromRackBinCode, a.ToRackBinCode)        
   and a.TransactionDate <= @AsOnDate          
   and (@ItemNature='' or (@ItemNature<>'' and m.ItemNature=@ItemNature))    
   and (@ItemUserKey='' or (@ItemUserKey<>''     
      and Exists(Select * From COM_SelectList s1    
        Where s1.UserKey=@ItemUserKey and s1.SelectStr=a.TransactionItem     
           and s1.BranchID=@BranchID and s1.CompID=@CompID    
           ))    
     )    
   and a.BranchID = @BranchID and a.CompID = @CompID --and a.Finyear = @Finyear            
    Group by m.ItemNature, a.TransactionItem, m.ItemDescription, m.Rate, m.UOMDesc, m.UOMDecimal,    
     b.LotID, b.SubLotID, c.ManufactureDate, c.ShelfLifeDays      
 ) x    
 Where IsNull(x.ItemCode,'')<>'' and (@ChkTran='0' or (@ChkTran='1' and IsNull(x.CBQty1,IsNull(CBQty2,0))<>0))    
 Order by ItemNature, x.ItemCode    
END 
GO

