CREATE PROCEDURE [dbo].[INV_StoreIssue_Hlp_PertainingTo_P] (@StoreRequestType varchar(5), @AsOnDate Datetime, @RptDate Datetime, 
@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20)) 
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

    
     Select distinct a.StoreRequestType, a.StoreRequestNo, a.StoreRequestDate, a.WOType, a.WONo, a.WODate,  
        a.ParentCode, (select d.ItemDescription From INV_MATERIAL_MASTER d 
                    Where d.ItemCode=a.ParentCode  and d.Branchid=a.Branchid and d.Compid=a.Compid) ItemDescription 
     from StoreRequest a 
     Left Outer Join dbo.fn_PPC_PROCESSWORKORDER(@BranchID, @CompID) b 
        On a.WOType=b.ProcessWorkOrderType and a.WONo=b.ProcessWorkOrderNo and a.WODate=b.ProcessWorkOrderDate 
            and a.ItemCode = b.FromStageCode and a.Branchid=b.Branchid and a.Compid=b.Compid 
     Where round(a.IssuedQty,3) < round(a.RequiredQty,3) and a.PrintFlg=1  
         and (b.CompletedQty < b.WorkOrderQty)  and b.WOShortClose=0 and a.StoreRequestType=@StoreRequestType 
         and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear>=@TmpFinyear
END
GO

