CREATE PROCEDURE [dbo].[INV_UP_Category_Master]
	(@CategoryCode 	[int],
	 @CategoryName 	[varchar](50),
	 @ParentCode 	[int],
	 @Status  	[bit],
	 @userid 	[varchar](10),
	 @Branchid 	[varchar](3),
	 @compid	[varchar](3))

AS
BEGIN
SET NOCOUNT ON

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		UPDATE [INV_Category_Master] 
		
		SET 	 [CategoryName]	 = @CategoryName,
			 [ParentCode]	 = @ParentCode,
			 [Status] = @Status,
			 [userid]	 = @userid
			
		
		WHERE 
			( [CategoryCode]	 = @CategoryCode AND
			 [ParentCode]	 = @ParentCode AND
			 [Status]		= @Status And
			 [Branchid] 	= @cBranchid and 
			 [compid]	 = @compid)

		FETCH NEXT FROM BranchidList into @cBranchid 
	END
 	
	close BranchidList
	deallocate BranchidList
END
GO

