    [PurConversionFactor]  = @PurConversionFactor,    
    [IssueUOM]  = @IssueUOM,    
    [IssConversionFactor]  = @IssConversionFactor,    
    [MinimumStock]  = @MinimumStock,    
    [MaximumStock]  = @MaximumStock,    
    [ReOrderLevel]  = @ReOrderLevel,    
    [ReOrderQty]  = @ReOrderQty,    
    [SafetyStock]  = @SafetyStock,    
    [MinLeadTime]  = @MinLeadTime,    
    [MaxLeadTime]  = @MaxLeadTime,    
    [SelfLifePeriod]  = @SelfLifePeriod,    
    [Rate]  = @Rate,    
    [Modvat]  = @Modvat,    
    [TariffNo]  = @TariffNo,  
    [HSNId]  = @HSNId,  
    [isAsset]  = @isAsset,    
    [TolerancePlusApplicable]  = @TolerancePlusApplicable,    
    [PurchaseTolerancePlus]  = @PurchaseTolerancePlus,    
    [ToleranceMinusApplicable]  = @ToleranceMinusApplicable,    
    [PurchaseToleranceMinus]  = @PurchaseToleranceMinus,    
    [PackingType]  = @PackingType,    
    [StdPackingQty]  = @StdPackingQty,    
    [DrawingNo]= @DrawingNo,    
    [DrawingDescription]=@DrawingDescription,    
    [RevisionNo]=@RevisionNo,    
    [RevisionDate]=@RevisionDate,    
    [DrawingPath]=@DrawingPath,    
    [TrayTypeCode]=@TrayTypeCode,    
    [Status]=@Status,    
    [Userid]  = @Userid    
    
  WHERE     
   ( [ItemCode]  = @ItemCode AND    
    [BranchId]  = @BranchId AND    
    [Compid]  = @Compid)  
  
END
