CREATE PROCEDURE [dbo].[INV_UP_WAREHOUSE_MASTER]

	(@WarehouseCode 	[varchar](6),
	 @WarehouseName 	[varchar](30),
	 @WarehouseNature 	[varchar](15),
	 @WarehouseLocation 	[varchar](20),
	 @WarehouseStatus 	[bit],
	 @Userid 		[varchar](10),
	 @Branchid 		[varchar](3),
	 @Compid 		[varchar](3))

AS 
BEGIN
SET NOCOUNT ON

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		UPDATE [INV_WAREHOUSE_MASTER] 
		
		SET 	 [WarehouseName]	 = @WarehouseName,
			 [WarehouseNature]	 = @WarehouseNature,
			 [WarehouseLocation]	 = @WarehouseLocation,
			 [WarehouseStatus]	 = @WarehouseStatus,
			 [Userid]	 = @Userid
		
		WHERE 
			( [WarehouseCode]	 = @WarehouseCode AND
			 [Branchid]		 = @cBranchid AND
			 [Compid]		 = @Compid)
		
		FETCH NEXT FROM BranchidList into @cBranchid 
	END
 	
	close BranchidList
	deallocate BranchidList
END
GO

