CREATE PROCEDURE [dbo].[MAINT_BreakdownRegistration_Up_FeedBack]    
( @BRType   [varchar](3),  
  @BRNo   [int],  
  @BRDate   [datetime],  
  @EquipmentCode  [varchar](20),  
  @FaultCode  [int],  
  @CompletedDate  [datetime],  
  @CompletedTime  [datetime],
	@RootCause   [varchar](8000),  
  @ActionTaken   [varchar](8000),			/* Repair Work Done */  
  @ActionTakenBy  [varchar](30),			/* Service Works Done by */
	@SpareReplaced  [varchar](100),
	@ServiceCost   [money],							/* Cost Of Service */
	@MachineResetOn   [datetime],
  @Branchid   [varchar](3),  
  @Compid   [varchar](3),  
  @Finyear   [varchar](20)
)    
AS 
BEGIN   
	SET NOCOUNT ON; 
  
	UPDATE [MAINT_BreakdownRegistration]   
  
	SET [CompletedDate]  = @CompletedDate,  
		[CompletedTime]  = @CompletedTime,  
		[RootCause]  = @RootCause,  
		[ActionTaken]  = @ActionTaken,  
		[ActionTakenBy]  = @ActionTakenBy,
		[SpareReplaced]  = @SpareReplaced,
		[ServiceCost]  = @ServiceCost,
		[MachineResetOn]  = @MachineResetOn

	WHERE     
	 ( [BRType]    = @BRType AND  
		[BRNo]     = @BRNo AND  
		[BRDate]   = @BRDate AND  
		[EquipmentCode]  = @EquipmentCode AND  
		[FaultCode]   = @FaultCode AND  
		[Branchid]   = @Branchid AND  
		[Compid]   = @Compid   
		/*  AND [Finyear]    = @Finyear */    
	 )
END
GO

/****** Object:  StoredProcedure [dbo].[MAINT_Equipment_Master_Gen_Accessories]    Script Date: 17/06/2026 11:30:20 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[MAINT_Equipment_Master_Gen_Accessories](@Filter varchar(2), @ItemCode varchar(20)='', @AsOnDate datetime, 
	@RptDate datetime, @BranchID  varchar(3), @CompID varchar(3))   
AS    
BEGIN
	SET NOCOUNT ON;
	
	Select a.EquipmentCode, IsNull((Case m.ItemNature When 'A' Then 'SPARES' When 'T' Then 'TOOL' When 'Y' Then 'ACCESSORY' When 'L' Then 'CONSUMABLE' End),'') As ItemNature, 
		IsNull(b.AccessoryCode,'') As AccessoryCode, (Case When IsNull(b.AccessoryCode,'')<>'' Then m.ItemDescription Else '' End) As AccessoryDesc, 
		IsNull((Case b.Returnable When '1' Then 'Returnable' Else 'Non-Returnable' End),'Non-Returnable') As Returnable,		
		IsNull(c.ParentCode,'') As ParentCode, m.ProductCategoryCode, m.ProductSubCategoryCode, m.ItemNature
	From MAINT_Equipment_Master a
	Left Outer Join MAINT_Equipment_Accessories b
		On a.EquipmentCode=b.EquipmentCode and a.BranchID=b.BranchID and a.CompID=b.CompID	
	Left Outer Join INV_Category_Master c
		On (b.AccessoryCode=c.CategoryName or b.AccessoryCode=c.CategoryName) 
			and a.BranchID=c.BranchID and a.CompID=c.CompID
	Left Outer Join INV_Material_Master m 
		On a.EquipmentCode=m.ItemCode -- and (c.ParentCode=m.ProductCategoryCode or c.ParentCode=m.ProductSubCategoryCode)
			and a.BranchID=m.BranchID and a.CompID=m.CompID
	Where (@ItemCode='' or (@ItemCode<>'' and a.EquipmentCode=@ItemCode)) and IsNull(b.AccessoryCode,'')<>'' 
		and  a.BranchID=@BranchID and a.CompID=@CompID		   
END
GO

