CREATE PROCEDURE [dbo].[MAINT_GeneratorOperatingRecord_Fil](@DocType varchar(3), @DocNo int, @DocDate datetime, @GeneratorCode varchar(20), @BranchID varchar(3), @CompID varchar(3))        
As        
SET NOCOUNT ON        
 BEGIN      
          
  Select Distinct a.StartDate, a.EndDate, a.Voltage, a.Amps, a.Frequency, a.WaterTemperature, a.OilTemperature,        
      a.OilPressure,  a.BatteryVolt, a.RPM, a.InitialEnergyUnit, a.FinalEnergyUnit, a.DieselConsumed,        
      IsNull(a.Remarks,'') As Remarks  
  From MAINT_GeneratorOperatingRecord a          
  Where a.DocNo=@DocNo and a.DocDate=@DocDate and a.DocType=@DocType and a.GeneratorCode=@GeneratorCode    
    and a.Branchid=@BranchID and a.Compid = @CompID        
 END     
GO

