/****** Object:  StoredProcedure [dbo].[MAINT_GeneratorOperatingRecord_Val_Date]    Script Date: 17/06/2026 11:30:20 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO



CREATE PROCEDURE [dbo].[MAINT_GeneratorOperatingRecord_Val_Date](@Type char(1), @GeneratorCode varchar(20), @DocType varchar(3), @DocNo integer, @DocDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))          
As          
SET NOCOUNT ON          
 BEGIN        
      
 If @Type='C' --Create      
      
  Begin      
   Select a.DocType, a.DocNo, a.DocDate, a.GeneratorCode, a.StartDate, a.EndDate      
   From MAINT_GeneratorOperatingRecord a      
   Where a.GeneratorCode=@GeneratorCode and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear = @Finyear              
  End      
      
 Else --'M'--> Modify      
      
  Begin      
   Select a.DocType, a.DocNo, a.DocDate, a.GeneratorCode, a.StartDate, a.EndDate      
   From MAINT_GeneratorOperatingRecord a      
   Where a.GeneratorCode=@GeneratorCode      
     and a.StartDate Not In( Select b.StartDate From MAINT_GeneratorOperatingRecord b      
             Where b.DocNo=@DocNo and b.DocDate=@DocDate and b.DocType=@DocType      
               and b.GeneratorCode=@GeneratorCode      
               and b.BranchID=@BranchID and b.CompID=@CompID and b.Finyear = @Finyear     
              )       
     and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear = @Finyear      
  End      
 END 
GO

