CREATE PROCEDURE [dbo].[MAINT_Rpt_GeneratorOperatingRecord_All](@GeneratorUserKey varchar(36), @FromDate datetime, @ToDate datetime, @AsOnDate datetime, @BranchID varchar(3), @CompID varchar(3))       
       
As        
      
SET NOCOUNT ON        
      
 BEGIN      
    
 Insert into COM_SelectList    
   
 Select @GeneratorUserKey, 0, x.GeneratorCode, @BranchID, @CompID, @AsOnDate     
 From    
 (     
  Select Distinct a.GeneratorCode     
  From MAINT_GeneratorOperatingRecord a    
  Where a.StartDate Between @FromDate and @ToDate and a.BranchID=@BranchID and a.CompID=@CompID         
 ) x    
          
 END   
GO

/****** Object:  StoredProcedure [dbo].[MAINT_Rpt_GeneratorOperatingRecord_Gen]    Script Date: 17/06/2026 11:30:21 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[MAINT_Rpt_GeneratorOperatingRecord_Gen](@GeneratorUserKey varchar(36), @FromDate datetime, @ToDate datetime, @BranchID varchar(3), @CompID varchar(3))    
    
As    
    
SET NOCOUNT ON    
 BEGIN    
 Select a.DocType, a.DocNo, a.DocDate, a.GeneratorCode, IsNull(b.ItemDescription,'') As GeneratorDesc,     
    a.StartDate, a.EndDate, a.Voltage, a.Amps, a.Frequency,     
    a.WaterTemperature, a.OilTemperature, a.OilPressure, a.BatteryVolt, a.RPM,     
    a.InitialEnergyUnit, a.FinalEnergyUnit, a.DieselConsumed, IsNull(a.Remarks,'') As Remarks    
 From MAINT_GeneratorOperatingRecord a    
 Left Outer Join INV_Material_Master b       
   On a.GeneratorCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID    
 Where a.StartDate Between @FromDate and @ToDate and a.BranchID=@BranchID and a.CompID=@CompID     
   and a.GeneratorCode In     
    (    
     Select s1.SelectStr From COM_SelectList s1    
     Where s1.UserKey = @GeneratorUserKey and s1.BranchID = @BranchID and s1.CompID = @CompID    
    )     
 Order by a.GeneratorCode, a.StartDate  
 END    
GO

/****** Object:  StoredProcedure [dbo].[MAINT_Rpt_GeneratorOperatingRecord_Sel]    Script Date: 17/06/2026 11:30:21 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[MAINT_Rpt_GeneratorOperatingRecord_Sel](@FromDate datetime, @ToDate datetime, @BranchID varchar(3), @CompID varchar(3))       
       
As        
      
SET NOCOUNT ON        
      
 BEGIN      
    
 Select Distinct a.GeneratorCode, IsNull(b.ItemDescription,'') As GeneratorDesc         
 From MAINT_GeneratorOperatingRecord a    
 Left Outer Join INV_Material_Master b       
   On a.GeneratorCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID    
 Where a.StartDate Between @FromDate and @ToDate and a.BranchID=@BranchID and a.CompID=@CompID     
 Order by a.GeneratorCode    
          
 END     
GO

/****** Object:  StoredProcedure [dbo].[MAINT_Rpt_MachineHistoryCardReport_Gen]    Script Date: 17/06/2026 11:30:21 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[MAINT_Rpt_MachineHistoryCardReport_Gen](@ShiftCode varchar(3)='GH1',
	@MachineCode varchar(20), @IsInstallation bit='0', @FromDate datetime, @ToDate datetime, 
	@AsonDate datetime, @RptDate datetime, @BranchID Varchar(3), @CompID Varchar(3), @Finyear Varchar(20))
AS                
 BEGIN                    
  SET NOCOUNT ON;          
          
  Declare @StartTime as datetime         
        
  /* Get Shift Start Time */      
  If Exists(Select * From PPC_Shift_Master a Where a.ShiftCode=@ShiftCode)       
   Begin      
		 Select @StartTime=a.StartTime From PPC_Shift_Master a        
		 Where a.ShiftCode=@ShiftCode      
   End      
	Else      
   Begin      
		 Select @StartTime=a.StartTime From PAY_Shift_Master a      
		 Where a.ShiftCode=@ShiftCode      
   End       
  
	/* Output (Result) */
	Select Distinct x.MachineCode, x.MachineName, x.BDDT, x.TGDT, x.CMPDT, x.CURDT, 
		IsNull(x.BreakDownDetails,'') As BreakDownDetails, IsNull(x.Capacity,'') As Capacity, x.InstalledDate, 
		IsNull(x.PrventMins,0) As PrventMins, IsNull(x.PrdtMins,0) As PrdtMins, IsNull(x.Remarks,'') As Remarks, 
				IsNull(x.RootCause,'') As RootCause, IsNull(x.ActionTaken,'') As ActionTaken, IsNull(x.ActionTakenBy,'') As ActionTakenBy, 
				IsNull(x.SpareReplaced,'') As SpareReplaced, IsNull(x.ServiceCost,0) As ServiceCost, x.MachineResetOn
	From ( 
				Select e.EquipmentCode As MachineCode, IsNull(m.ItemDescription,'') As MachineName, 
					Case When b.BreakdownDate=NULL or Convert(varchar(10),b.BreakdownDate,121)<='1900-12-30' 
							Then 'Nil' Else Convert(varchar(10),b.BreakdownDate,121)+' '+Convert(varchar(8),b.BreakdownTime,108) End As BDDT, 
					Case When b.TargetDate=NULL or Convert(varchar(10),b.TargetDate,121)<='1900-12-30' 
							Then 'Nil' Else Convert(varchar(10),b.TargetDate,121)+' '+Convert(varchar(8),'23:59:59',108) End As TGDT, 
					Case When b.CompletedDate=NULL or Convert(varchar(10),b.CompletedDate,121)<='1900-12-30' 
							Then 'Nil' Else Convert(varchar(10),b.CompletedDate,120)+' '+Convert(varchar(8),b.CompletedTime,108) End As CMPDT, 
					Convert(varchar(10),GetDate(),121)+' '+Convert(varchar(8),GetDate(),108) As CURDT, 
					f.FaultDescription As BreakDownDetails, e.Capacity, e.InstalledDate, 
					IsNull((Select DateDiff(mi, e1.ScheduleDate+@StartTime, (e1.CompletedDate+e1.CompletedTime))           
									 From MAINT_EquipmentActivity_Schedule e1          
									 Where e1.EquipmentCode=e.EquipmentCode and e1.Finyear=@Finyear          
									 ),0) As PrventMins, 0 As PrdtMins,          
					/*IsNull((Select distinct Sum(DateDiff(mi, c.ScheduleDate+@StartTime, (c.CompletedDate+c.CompletedTime)))              
									From MAINT_PredictiveMaintenanceSchedule c          
									Where c.EquipmentCode=e.EquipmentCode and Finyear=@Finyear),0) As PrdtMins,*/ 
					IsNull(b.Remarks,'') As Remarks, b.RootCause, b.ActionTaken, b.ActionTakenBy, 
					b.SpareReplaced, b.ServiceCost, b.MachineResetOn 
				From Maint_Equipment_Master e 
				Left Outer Join INV_Material_Master m 
					On e.EquipmentCode=m.ItemCode and e.BranchID=m.BranchID and e.CompID=m.CompID 
				Left Outer Join MAINT_BreakdownRegistration b 
					On b.EquipmentCode=m.ItemCode and b.BranchID=m.BranchID and b.CompID=m.CompID 
				Left Outer Join MAINT_Fault_Master f 
					On b.FaultCode=f.FaultCode and b.BranchID=f.BranchID and b.CompID=f.CompID 
			Where e.EquipmentCode=@MachineCode 
				and ((@IsInstallation='1' and b.BreakDownDate<=@ToDate) or (@IsInstallation='0' and (b.BreakDownDate Between @FromDate and @ToDate)))
				and m.Status='1' and e.BranchID=@BranchID and e.CompID=@CompID 
	) x
END
GO

