CREATE PROCEDURE [dbo].[MAINT_UP_BreakdownRegistration1]

	(@BRType 			[varchar](3),
	 @BRNo 			[int],
	 @BRDate 			[datetime],
	 @EquipmentCode 		[varchar](20),
	 @FaultCode 			[int],
	 @ComplaintReportedTo 	[varchar](10),
	 @ForwardDate 			[datetime],
	 @ForwardTime 			[datetime],
	 @Branchid 			[varchar](3),
	 @Compid 			[varchar](3),
	 @Finyear 			[varchar](20))

AS

SET NOCOUNT ON

 UPDATE [MAINT_BreakdownRegistration] 

SET 	 [ComplaintReportedTo]	 = @ComplaintReportedTo,
	 [ForwardDate]		 = @ForwardDate,
	 [ForwardTime]	 	= @ForwardTime

WHERE 

	( [BRType]		 = @BRType AND
	 [BRNo]			 = @BRNo AND
	 [BRDate]	 	= @BRDate AND
	 [EquipmentCode]	 = @EquipmentCode AND
	 [FaultCode]		 = @FaultCode AND
