/****** Object:  Stored Procedure dbo.MIS_Inventory_Ran_NonConfirmingMaterialScrap    Script Date: 18/04/2007 3:35:24 PM ******/

CREATE PROCEDURE  [dbo].[MIS_Inventory_Ran_NonConfirmingMaterialScrap]  (@Start datetime,@End datetime,@BranchCode varchar(4),@CmCode varchar(4))

 AS
Begin
Set NoCount On
Select Period,ScrapQty,SubString(Period,6,2) as [Month],null,'NonConformingMatlScrap',@CmCode as CompId from  (
	select Convert(VarChar(7),psn_date,126) as Period,sum(scrap_qty) as [ScrapQty]
	from qc_psn_hdr where PSN_Date between Convert(DateTime,@Start,111) and Convert (DateTime,@End,111) and 
	Branchid=@BranchCode and Compid=@CmCode 
	group by Convert(VarChar(7),psn_date,126) 
) NonConformingMatlScrap 
Order by Period

End
GO

/****** Object:  StoredProcedure [dbo].[MIS_Pay_EmpoyeeTurnOver]    Script Date: 17/06/2026 11:30:22 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Procedure [dbo].[MIS_Pay_EmpoyeeTurnOver] (@Start DateTime, @End DateTime, @Branchid varchar(3),@Compid VarChar(3)) 
As
Begin 
Set NoCount On

Select Period, Round((((ResEmps+JoinEmps) / cast(NOE as float) )*100),2) as NOP
from (
	Select Isnull(RejJoin.Period,PaySum.Period) as Period, isnull(RejJoin.ResEmps,0) as ResEmps, isnull(RejJoin.JoinEmps,0) as JoinEmps , IsNull(PaySum.NOE,0) as NOE from (
		(Select isnull(Res.Period, Joined.Period) as Period, Res.ResEmps ,Joined.JoinEmps from (
			(select  Convert(VarChar(7),RelievedDate,126) as Period,count(EmployeeCode) as ResEmps from PAY_Employee_Master 
			where RelievedDate between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111) 
			and not RelievedDate is null 
			group by Convert(VarChar(7),RelievedDate,126)) Res
		Full Outer Join
			(select Convert(VarChar(7),DateofJoining,126) as Period,count(EmployeeCode) as JoinEmps from PAY_Employee_Master 
			where DateofJoining between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111) 
			and not RelievedDate is null group by Convert(VarChar(7),DateofJoining,126) ) Joined
		On Res.Period=Joined.Period
		)) RejJoin
	Full Outer Join
	 (select convert(VarChar(7),ProcessMonth,126)  as Period,count(distinct EmployeeCode) as NOE from PAY_ProcessResult 
		where convert(VarChar(7),ProcessMonth,126)  between convert(VarChar(7),@Start,126)  and  convert(VarChar(7),@End,126)  
		and ResultValue > 0 and Branchid = @Branchid and Compid = @Compid  group by convert(VarChar(7),ProcessMonth,126) ) PaySum
	on RejJoin.Period=PaySum.Period
	)
) EmpTurn where resemps+JoinEmps > 0

End
GO

/****** Object:  StoredProcedure [dbo].[MIS_PayRoll_EmployeeOverTime]    Script Date: 17/06/2026 11:30:22 ******/
SET ANSI_NULLS OFF
