CREATE PROCEDURE  [dbo].[MIS_PayRoll_EmployeeOverTime] (@EmpCode Varchar(8),@Start varchar(7), @End varchar(7), @CmCode varchar(4))
As
Begin
Set NoCount On

Select Period, Sum(Salary) as Salary ,SubString(Period,6,2) as [Month],Null,Null,@CmCode
from  (
	Select Period, 
	       Case Ltrim(Rtrim(@EmpCode)) When '' then Sum(Salary) else Case When Emp_Cd=@EmpCode then Sum(Salary) Else 0 End End as Salary
	from (
		select year_month as Period,Emp_Cd,isnull(sum(amount),0) as Salary 
		from Pay_Salary_Tran where Year_Month between @Start and @End and 
		compid = @CmCode and ed_code = 'OT' group by year_month,Emp_Cd
	) Sal Group By Period,Emp_Cd
) SumSal  Group By Period

End
GO

