CREATE PROCEDURE  [dbo].[MIS_PayRoll_TotAbs]  (@EmpCode Varchar(8),@Start varchar(7), @End varchar(7), @CmCode varchar(4))
As
Begin
Set NoCount On

	select Year_Month as [Period], Sum(LeaveDays) as TotaLeave, SubString(Year_Month,6,2) as [Month], Sum(LD) as Leave, Sum(LOP) as LOP,@CmCode as CompId
	from ( 
		Select Emp_Cd, Year_Month,
					 Case Ltrim(Rtrim(@EmpCode)) When '' then Sum(Ldays) else Case When Emp_Cd=@EmpCode then Sum(Ldays) Else 0 End End as LD,
	  			 Case Ltrim(Rtrim(@EmpCode)) When '' then Sum(Lop) else Case When Emp_Cd=@EmpCode then Sum(Lop) Else 0 End End as LOP,
					 Case Ltrim(Rtrim(@EmpCode)) When '' then Sum(Lop+Ldays) else Case When Emp_Cd=@EmpCode then Sum(Lop+Ldays) Else 0 End End as LeaveDays
		from (
			Select Emp_Cd,Year_Month,Lop,Ldays 
			from pay_attend_ot_tran where  
			Year_Month between @Start  and @End
			and compid = @CmCode
		) GetEmpLD  Group By Emp_Cd,Year_Month
	) FinLD where LD+Lop > 0 Group BY Year_Month

End
GO

