CREATE PROCEDURE  [dbo].[MIS_Production_Ran_ConsumptionRawMaterial]  (@Start datetime,@End datetime,@BranchCode varchar(3),@CmCode varchar(3))

AS

Begin
Set NoCount On

	Select Distinct a.ItemCode, a.ItemDescription As ItemName, a.ItemNature
	From INV_Material_Master a
	Left Outer Join INV_MaterialTran_Dtl b
	On a.ItemCode=b.TransactionItem and b.Branchid=a.Branchid and b.Compid=a.compid
	Where a.ItemNature='R' 	and b.DOCDate between @Start and @End 
	            and a.Branchid=@BranchCode and a.Compid=@CmCode
	Order by a.ItemCode
	
End
GO

