 (Select Ac_Name from Fas_AcMast where Code=a.VendCode and CompId=@CmCode) as [Name]
 from Pur_SchMai a,Pur_SchSub b
Where A.ordtype = b.ordtype And A.ordno = b.ordno
and b.SchDate between convert(datetime,@Start,111) and Convert(Datetime,@End,111)
and a.compId=b.CompId and b.CompId=@CmCode
and a.FinYear=b.FinYear and b.FinYear=@FinYear order by 1

end
