/****** Object:  StoredProcedure [dbo].[MIS_Purchase_PurchaseValue]    Script Date: 17/06/2026 11:30:23 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

/****** Object:  Stored Procedure dbo.MIS_Purchase_PurchaseValue    Script Date: 22/04/2007 1:03:15 PM ******/

CREATE PROCEDURE  [dbo].[MIS_Purchase_PurchaseValue] (@ItemNature char(1), @Start datetime, @End datetime, @BranchCode varchar(3), @CompCode varchar(3))

AS
begin

	if @ItemNature <> ''
		begin

		select YearMonth, sum(Value) Value, @BranchCode, @CompCode  from (
		select convert(varchar(7),a.ReceiptEntryDate,120) YearMonth, a.ItemCode, sum(AcceptedQty) AcceptedQty, 
		b.Rate, (sum(AcceptedQty) * b.Rate) Value from ReceiptEntry a left outer join INV_Material_Master b
		on a.ItemCode = b.ItemCode and a.Branchid = b.Branchid and a.Compid = b.Compid
		where a.InwardType = 'P' and ReceiptEntryDate between 	@Start and @End and a.Branchid = @BranchCode and a.Compid = @CompCode
		and b.ItemNature = @ItemNature
	
			group by  convert(varchar(7),a.ReceiptEntryDate,120), a.ItemCode, b.Rate
		
		) x group by YearMonth order by YearMonth

		end 
	else
		begin

		select YearMonth, sum(Value) Value, @BranchCode, @CompCode from (
			select convert(varchar(7),a.ReceiptEntryDate,120) YearMonth, a.ItemCode, sum(AcceptedQty) AcceptedQty, 
			b.Rate, (sum(AcceptedQty) * b.Rate) Value from ReceiptEntry a left outer join INV_Material_Master b
			on a.ItemCode = b.ItemCode and a.Branchid = b.Branchid and a.Compid = b.Compid
			where a.InwardType = 'P' and ReceiptEntryDate between 	@Start and @End and a.Branchid = @BranchCode and a.Compid = @CompCode
			group by  convert(varchar(7),a.ReceiptEntryDate,120), a.ItemCode, b.Rate
		
		) x group by YearMonth order by YearMonth
		
		end
	
end
GO

