CREATE PROCEDURE  [dbo].[MIS_Sal_CustRejPPM] (@Start datetime, @End datetime, @CmCode varchar(4),@FinYear varchar(25))

 AS
begin
Set NoCount On

Select CustCode,
 (Select Ac_Name From Fas_AcMast where Code=CustCode and CompId=@CmCode) as CustName
from (
	Select Case When Grir.GrirCustCode is null then sal.SalCustCode else Grir.GrirCustCode end as CustCode from
		(Select Distinct VendorCode as GrirCustCode from Rec_Grir_Hdr
		where Pur_Sub = 'R' and Grir_Dt between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111)
		and CompId=@CmCode and FinYear=@FinYear ) as Grir
	Full Outer Join
		 (Select Distinct CustCode as SalCustCode from Sal_InvMai
		where InvDt between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111)
		and CompId=@CmCode and FinYear=@FinYear ) as Sal
	on Grir.GrirCustCode=Sal.SalCustCode
      ) c
order by CustName 
End
GO

