/****** Object:  Stored Procedure dbo.MIS_Sales_Ran_CustomerRejectionPPM    Script Date: 16/04/2007 1:01:15 PM ******/

CREATE PROCEDURE  [dbo].[MIS_Sales_Ran_CustomerRejectionPPM] (@Start datetime, @End datetime, @BranchCode varchar(3), @CmCode varchar(3))

 AS
begin
Set NoCount On

Select cc.CustCode, pn.PartyName As CustName
From (
	Select Case When Rec.RecCustCode Is Null Then sal.SalCustCode Else Rec.RecCustCode End As CustCode
	From (
	  		Select Distinct VendorCode As RecCustCode From REC_ReceiptEntry_Hdr
			  Where InwardType = 'S' and (ReceiptEntryDate between Convert(datetime,@Start,111) and Convert(datetime,@End,111))
				and Branchid=@BranchCode and Compid=@CmCode
	  	 ) As Rec
	Full Outer Join
	( Select Distinct CustomerCode As SalCustCode From SAL_Invoice_Hdr
		Where (InvoiceDate between Convert(datetime,@Start,111) and Convert(datetime,@End,111))
		and Branchid=@BranchCode and Compid=@CmCode
	) As Sal
	On Rec.RecCustCode=Sal.SalCustCode
    ) cc
Left Outer Join PartyMaster pn 
On cc.CustCode=pn.PartyCode and pn.BranchID=@BranchCode and pn.CompID=@CmCode
Order by pn.PartyName

End
GO

