/****** Object:  Stored Procedure dbo.MIS_Sales_Ran_DeliveryComplianceQtyVal    Script Date: 16/04/2007 1:01:15 PM ******/

CREATE PROCEDURE  [dbo].[MIS_Sales_Ran_DeliveryComplianceQtyVal](@Start datetime, @End datetime, @BranchCode varchar(3), @CmCode varchar(3))

AS

begin
Set NoCount On

Select x.SPItemCode As ItemCode, a.ItemDescription As ItemName  
From INV_Material_Master a
Left Outer Join ( 
	Select Case When Pln.SchItemCode Is Null Then sal.SalItemCode Else Pln.SchItemCode End As SPItemCode
	From
		 ( Select Distinct ItemCode As SchItemCode From PPC_ProductionPlan 
		 	 Where PlanFor=2 and PlanPeriod between Convert(datetime,@Start,111) and Convert(datetime,@End,111)
						 and Branchid=@BranchCode and Compid=@CmCode
		 ) as Pln
	 	 Full Outer Join
		 ( Select Distinct ItemCode As SalItemCode  From SAL_Invoice_Dtl
			 Where InvoiceDate between Convert(datetime,@Start,111) and Convert(datetime,@End,111)
						 and Branchid=@BranchCode and Compid=@CmCode
		 ) As Sal
  	On Pln.SchItemCode=Sal.SalItemCode
		) x
On a.ItemCode=x.SPItemCode
Where x.SPItemCode=a.ItemCode and a.Branchid=@BranchCode and a.Compid=@CmCode
Order by x.SPItemCode

End
GO

