/****** Object:  StoredProcedure [dbo].[MISCorrection_BillNotBooked_Vendor]    Script Date: 17/06/2026 11:30:23 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[MISCorrection_BillNotBooked_Vendor](@ModuleCode int, @RptOpn Char(1), @FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))    
As    
    
SET NOCOUNT ON    
    
Begin     
      
 If @RptOpn = 'P'    
      
   Select Distinct d.PartyName, d.PartyCode, a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.ItemCode, e.ItemDesc     
   From RECEIPTENTRY a    
   Left Outer Join dbo.fn_BOM_Material_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID)e     
   On a.ItemCode= e.ItemCode and a.BranchId=e.BranchId and a.CompId=e.CompId     
   Left Outer Join dbo.fn_PartyMaster(@ModuleCode, @AsOnDate, @RptDate, @BranchID, @CompID)d     
   On a.VendorCode= d.PartyCode and a.BranchId=d.BranchId and a.CompId=d.CompId     
     Where InwardType='P' and a.ShortClose = '0' and a.ReceiptEntryNo not in (Select b.RefNo From PUR_PurchaseInvoice_Ref b    
    Where a.ReceiptEntryNo=b.RefNo and a.ReceiptEntryDate=b.RefDate and a.ReceiptEntryType=b.RefType and a.BranchId=b.BranchId and a.CompId=b.CompId)    
     and a.BranchId = @BranchID and a.CompId = @CompID     
     and ReceiptEntryDate between @FromDate and @ToDate    
    
  Else    
    
   Select Distinct d.PartyName, d.PartyCode, a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.ItemCode, e.ItemDesc     
   From RECEIPTENTRY a    
   Left Outer Join dbo.fn_BOM_Material_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID)e     
   On a.ItemCode= e.ItemCode and a.BranchId=e.BranchId and a.CompId=e.CompId     
   Left Outer Join dbo.fn_PartyMaster(@ModuleCode, @AsOnDate, @RptDate, @BranchID, @CompID)d     
   On a.VendorCode= d.PartyCode and a.BranchId=d.BranchId and a.CompId=d.CompId     
     Where inwardType='S' and a.ShortClose = '0' and a.ReceiptEntryNo not in (select b.RefNo From PUR_laborInvoice_Ref b    
    Where a.ReceiptEntryNo=b.RefNo and a.ReceiptEntryDate=b.RefDate and a.ReceiptEntryType=b.RefType and a.BranchId=b.BranchId and a.CompId=b.CompId)    
    and a.BranchId = @BranchID and a.CompId = @CompID    
    and ReceiptEntryDate between  @FromDate and @ToDate    
    
 End
GO

