/****** Object:  StoredProcedure [dbo].[MisPayRoll_EmpoyeeTurnOver]    Script Date: 17/06/2026 11:30:23 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Procedure [dbo].[MisPayRoll_EmpoyeeTurnOver] (@Start DateTime, @End DateTime, @Branchid varchar(3),@Compid VarChar(3)) 
As
Begin 
Set NoCount On

Select Period, Round((((ResEmps+JoinEmps) / cast(NOE as float) )*100),2) as NOP ,
SubString(Period,6,2) as [Month], ResEmps,JoinEmps,  NOE
from (
	Select Isnull(RejJoin.Period,PaySum.Period) as Period, isnull(RejJoin.ResEmps,0) as ResEmps, isnull(RejJoin.JoinEmps,0) as JoinEmps , IsNull(PaySum.NOE,0) as NOE from (
		(Select isnull(Res.Period, Joined.Period) as Period, Res.ResEmps ,Joined.JoinEmps from (
			(select  Convert(VarChar(7),RelievedDate,126) as Period,count(EmployeeCode) as ResEmps from PAY_Employee_Master 
			where RelievedDate between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111) 
			and not RelievedDate is null 
			group by Convert(VarChar(7),RelievedDate,126)) Res
		Full Outer Join
			(select Convert(VarChar(7),DateofJoining,126) as Period,count(EmployeeCode) as JoinEmps from PAY_Employee_Master 
			where DateofJoining between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111) 
			and not RelievedDate is null group by Convert(VarChar(7),DateofJoining,126) ) Joined
		On Res.Period=Joined.Period
		)) RejJoin
	Full Outer Join
	 (select convert(VarChar(7),ProcessMonth,126)  as Period,count(EmployeeCode) as NOE from PAY_ProcessResult 
		where convert(VarChar(7),ProcessMonth,126)  between @Start and  @End 
		and ResultValue > 0 and Branchid = @Branchid and Compid = @Compid  group by convert(VarChar(7),ProcessMonth,126) ) PaySum
	on RejJoin.Period=PaySum.Period
	)
) EmpTurn where resemps+JoinEmps > 0

End
GO

/****** Object:  StoredProcedure [dbo].[MisProd_ConsRawMatl_Sel]    Script Date: 17/06/2026 11:30:23 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

--Sel
CREATE Procedure [dbo].[MisProd_ConsRawMatl_Sel] (@ItemCode VarChar(15),@Start VarChar(10), @End VarChar(10), @CmCode VarChar(4), @FinYear VarChar(20))
As
Begin
Set NoCount On

Select Period,Sum(MatlValue) as Value,SubString(Period,6,2) as [Month], Null, 'Consumption of Rawmaterial',@CmCode from (
	Select Period ,Item,(Con*Rate) as MatlValue from (
		Select Period,Item,Con,
		Case When WtAvgRate is null then MatlRate else WtAvgRate end As Rate from (
			Select Period,Item,Con ,WtAvg.WtAvgRate,MatlRate from (
				(Select Period,Item,
				Case when Consum < 0 then 0 else Consum End as Con,MatlRate from (
  				 Select Period,Item, ((ob_qty + recqty) -  issqty)  as Consum,
		  		 IssQty,RecQty,Ob_Qty,MatlRate from (
  		  		  Select Period,IssRec.IssRecItem as Item,
    		  		IssQty,RecQty,Ob_Qty,MatlRate from (
      		  		 (Select Period,ItemCode as IssRecItem,IssQty,RecQty,
								 (Select Avg(Rate) from Pur_VenMat where ItemCode=y.ItemCode and CompId=@CmCode) as MatlRate
								 from (
  	  	    		    Select Period,ItemCode,IssQty,RecQty,
    	  	    		  (Select Item_Type from Inv_Matl_Mast where Item_Code=ItemCode and CompId=@CmCode) as ItemType 
										 from (
      	  	    		   Select Convert(varchar(7),doc_dt,126) as Period,item_code as ItemCode,sum(issued_qty) as IssQty ,sum(qty_received) as RecQty
        	  	    		 from inv_MatlTran_Dtl where Doc_Dt Between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111)
													  and Item_Code=@ItemCode and CompId=@CmCode and FinYear= @FinYear
	        	  	    	 group by Convert(varchar(7),doc_dt,126),item_code 
	  	        	  	)x
			    	     ) y where ItemType='R' ) IssRec
  			    	left  Outer Join
    			    	 (select item_code as ObItem,sum(ob_qty) as ob_qty from inv_stock_mast where Item_Code =@ItemCode and ob_Date <= @End and CompId=@CmCode
	    			     group by item_code ) Stock
  	    			On IssRec.IssRecItem=Stock.ObItem 
	    	  		)   
				   ) J
				) T ) ConS
			left Outer Join 
				(select Item_Code as WtAvgItem, (Sum(Value) /Sum(Recd_Qty) )as WtAvgRate
				from ( 
					Select Item_Code , Recd_Qty, Rate, (Recd_Qty * Rate ) as Value from 
					(
						Select b.Item_Code, b.Recd_qty,
						(select max(Rate) from Pur_OrdSub Where OrderType=b.Po_Type and OrderNumber=b.Po_No 
						and Item_Code=b.Item_Code and  CompId=@CmCode and FinYear=@FinYear			) as Rate
						from Rec_Grir_Hdr a,Rec_Grir_Dtl b where a.Grir_No=b.Grir_No and a.Pur_Sub ='P'   and b.Grir_Dt < = Convert(DateTime,@End,111)
						and b.Item_Code=@ItemCode and a.CompId=b.CompId and b.CompId=@CmCode
						and a.FinYear=b.FInYear and b.FinYear=@FinYear
					)  x
				) y
				group by Item_Code ) WtAvg
			on WtAvgItem= Item 
			)  
		) yu
	) matlV
) PV Group by Period

End
GO

