--InHouse Rejection Persentage
CREATE Procedure [dbo].[MisProd_InHouseRejQtyPer] (@Start VarChar(10), @End VarChar(10), @CmCode VarChar(4), @FinYear VarChar(20))
As
Begin
Set NoCount On

select Period, Round(((rqty/a.Cqty)*100),2) as RejPer,substring(Period,6,2) as [Month],Rqty as RejQty,CQty as ComplQty,@CmCode as CompId 
from  (
	select Convert(VarChar(7),wo_date,126) as Period,sum(completed_qty) as Cqty,sum(rej_qty) as Rqty 
	from ppc_wo_hdr  where Wo_Date between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111)
	and CompId=@CmCode and FinYear=@FinYear
	group by Convert(VarChar(7),wo_date,126) 
)   a order by period

End
GO

/****** Object:  StoredProcedure [dbo].[MisProd_InHouseRejQtyPerPartNo]    Script Date: 17/06/2026 11:30:24 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

--InHouse Rejection Persentage Partnowise
CREATE Procedure [dbo].[MisProd_InHouseRejQtyPerPartNo](@Start VarChar(10), @End VarChar(10), @CmCode VarChar(4), @FinYear VarChar(20))
As
Begin
Set NoCount On

		SELECT TOP 12  isnull((select top 1 partno from partmast c where stagecode=x.item_code 
		and c.compid= @CmCode),item_code) partno,((SCRAP_QTY/PROD_QTY)*100) REJ_PER,'1',SCRAP_QTY ,PROD_QTY,COMPID 
		FROM (SELECT A.ITEM_CODE,SUM(IGR_QTY) PROD_QTY,(SELECT SUM(SCRAP_QTY) FROM 
		QC_PSN_HDR B WHERE B.ITEM_CODE=A.ITEM_CODE AND b.PSN_DATE between @Start and @End
		AND B.COMPID= @CmCode AND B.FINYEAR= @FinYear) SCRAP_QTY,A.COMPID FROM PPC_IGR A
		WHERE a.IGR_DATE between @Start and @End AND A.COMPID= @CmCode AND A.FINYEAR= @FinYear 
		GROUP BY A.ITEM_CODE,A.COMPID) X  ORDER BY REJ_PER DESC,X.ITEM_CODE

End
GO

