--InProcess PPM
CREATE Procedure [dbo].[MisProd_InProcPPM] (@Start VarChar(10), @End VarChar(10), @CmCode VarChar(4), @FinYear VarChar(20))
As
Begin
Set NoCount On

Select Period,Convert(VarChar,Convert(Money,((RejQty/AppQty) * 1000000))) as InProcessPPM ,SubString(Period,6,2) as [Month],AppQty,RejQty,@CmCOde as CompId 
from (
	select Convert(VarChar(7),schDate,126) as Period ,Sum(QtyAppr) as AppQty,sum(QtyRej)  as RejQty
	from ml_logsheet 
	where SchDate Between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111)
	and CompId=@CmCode and FinYear=@FinYear
	Group by Convert(VarChar(7),schDate,126)
 ) f

End
