/****** Object:  StoredProcedure [dbo].[MisProd_LineRej]    Script Date: 17/06/2026 11:30:24 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

--Line Rejection
CREATE Procedure [dbo].[MisProd_LineRej] (@Start VarChar(10), @End VarChar(10), @CmCode VarChar(4), @FinYear VarChar(20))
As
Begin
Set NoCount On

Select Period,Sum(LineValue) as LineVal,SubString(Period,6,2) as [Month],Sum(LineQty) as LineQty ,'Material Return' as [Description],@CmCode as [CompId] 
from (
	Select Period,Item_Code,(LineQty*WtAvgRate)as LineValue,LineQty 
	from (
		Select Mrn.Period,Mrn.Item_Code,LineQty,WtAvgRate 
		from (
			(select Convert(VarChar(7),qc_date,126) as Period,Item_Code,sum(Line_qty) as LineQty 
			 from inv_mrn_return 
			 where Qc_Date Between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111) and line_Qty >0	
			 and CompId=@CmCode and FinYear=@FinYear Group by Convert(VarChar(7),qc_date,126),Item_Code ) MRN
		Join 
			(select Item_Code as WtAvgItem, (Sum(Value) /Sum(Recd_Qty) )as WtAvgRate from ( 
				Select Item_Code , Recd_Qty, Rate, (Recd_Qty * Rate ) as Value from (
					Select b.Item_Code, b.Recd_qty,
					(select max(Rate) from Pur_OrdSub Where OrderType=b.Po_Type and OrderNumber=b.Po_No 
					and Item_Code=b.Item_Code and  CompId=@CmCode and FinYear=@FinYear			) as Rate
					from Rec_Grir_Hdr a,Rec_Grir_Dtl b where a.Grir_No=b.Grir_No and a.Pur_Sub ='P'  and b.Grir_Dt < = Convert(DateTime,@End,111)
					and a.CompId=b.CompId and b.CompId=@CmCode
					and a.FinYear=b.FInYear and b.FinYear=@FinYear
				)  x
			) y
			group by Item_Code ) WtAvg
		on WtAvg.WtAvgItem=Mrn.Item_Code ) 
	) RetValue
) SumRetVal Group By Period

End
GO

/****** Object:  StoredProcedure [dbo].[MisProd_MatlRet]    Script Date: 17/06/2026 11:30:24 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

--Material Return
CREATE Procedure [dbo].[MisProd_MatlRet] (@Start VarChar(10), @End VarChar(10), @CmCode VarChar(4), @FinYear VarChar(20))
As
Begin
Set NoCount On

Select Period,Convert(VarChar,Convert(Money,Sum(RetValue))) as RetVal,SubString(Period,6,2) as [Month],Convert(VarChar,Convert(Money,Sum(RetQty))) as RetQty ,'Material Return' as [Description],@CmCode as [CompId] 
from (
	Select Period,Item_Code,(RetQty*WtAvgRate)as RetValue,RetQty 
	from (
		Select Mrn.Period,Mrn.Item_Code,RetQty,WtAvgRate 
		from (
			(select Convert(VarChar(7),qc_date,126) as Period,Item_Code,sum(return_qty) as RetQty 
			from inv_mrn_return a
			where Qc_Date Between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111)	
			and CompId=@CmCode and FinYear=@FinYear Group by Convert(VarChar(7),qc_date,126),Item_Code ) MRN
		Join 
			(select Item_Code as WtAvgItem, (Sum(Value) /Sum(Recd_Qty) )as WtAvgRate from ( 
				Select Item_Code , Recd_Qty, Rate, (Recd_Qty * Rate ) as Value from (
					Select b.Item_Code, b.Recd_qty,
					(select max(Rate) from Pur_OrdSub Where OrderType=b.Po_Type and OrderNumber=b.Po_No 
					and Item_Code=b.Item_Code and  CompId=@CmCode and FinYear=@FinYear			) as Rate
					from Rec_Grir_Hdr a,Rec_Grir_Dtl b where a.Grir_No=b.Grir_No and a.Pur_Sub ='P' and b.Grir_Dt < = Convert(DateTime,@End,111)
					and a.CompId=b.CompId and b.CompId=@CmCode
					and a.FinYear=b.FInYear and b.FinYear=@FinYear
				)  x
			) y
			group by Item_Code ) WtAvg
		on WtAvg.WtAvgItem=Mrn.Item_Code ) 
	) RetValue
) SumRetVal Group By Period



End
GO

