/****** Object:  StoredProcedure [dbo].[MisProd_RawSubConPer]    Script Date: 17/06/2026 11:30:24 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

--Rawmaterial / SubContractor in Persentage
CREATE Procedure [dbo].[MisProd_RawSubConPer] (@Start VarChar(10), @End VarChar(10), @CmCode VarChar(4), @FinYear VarChar(20))
As
Begin
Set NoCount On

Select Period,Round((ConsAmt/SalAmt) * 100,2) as ConsPer,Round((SubConAmt/SalAmt) *100,2) as SubConPer,
SubString(Period,6,2) as [Month] ,'RawMatl SubCon Per',@CmCode as CompId
from (
	Select Case When ConsSalPeriod is null then SubConPeriod Else ConsSalPeriod end  as Period,
	ConsAmt,SalAmt,SubConAmt from (
		(Select case when Cons.ConsPeriod is null then Sal.SalPeriod else Cons.COnsPeriod ENd as ConsSalPeriod,
		Cons.ConsAmt,Sal.SalAmt from (
			(Select Period as ConsPeriod,Sum(MatlValue) as ConsAmt from (
				Select Period ,Item,(Con*Rate) as MatlValue from (
					Select Period,Item,Con,
					Case When WtAvgRate is null then MatlRate else WtAvgRate end As Rate from (
						Select Period,Item,Con ,WtAvg.WtAvgRate,MatlRate from (
							(Select Period,Item,
							Case when Consum < 0 then 0 else Consum End as Con,MatlRate from (
			  				 Select Period,Item, ((ob_qty + recqty) -  issqty)  as Consum,
					  		 IssQty,RecQty,Ob_Qty,MatlRate from (
			  		  		  Select Period,IssRec.IssRecItem as Item,
			    		  		IssQty,RecQty,Ob_Qty,MatlRate from (
			      		  		 (Select Period,ItemCode as IssRecItem,IssQty,RecQty,
											 (Select Rate from Inv_Matl_Mast where Item_Code=ItemCode and CompId=@CmCode) as MatlRate
											 from (
			  	  	    		    Select Period,ItemCode,IssQty,RecQty,
			    	  	    		  (Select Item_Type from Inv_Matl_Mast where Item_Code=ItemCode and CompId=@CmCode) as ItemType from (
			      	  	    		   Select Convert(varchar(7),doc_dt,126) as Period,item_code as ItemCode,sum(issued_qty) as IssQty ,sum(qty_received) as RecQty
			        	  	    		 from inv_MatlTran_Dtl where Doc_Dt Between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111)and CompId=@CmCode and FinYear= @FinYear
				        	  	    	 group by Convert(varchar(7),doc_dt,126),item_code 
				  	        	  	)x
						    	     ) y where ItemType='R' ) IssRec
			  			    	left  Outer Join
			    			    	 (select Item_Code as ObItem, sum(Qty_Received) as ob_qty from inv_matltran_dtl 
							  where Doc_Type='OB' and Doc_Dt <= @End and WHS_Code in (Select Whs_Code from Inv_whs_mast where whs_nature='General' and CompId=@CmCode)  
							     and CompId=@CmCode group by item_code ) Stock
			  	    			On IssRec.IssRecItem=Stock.ObItem 
				    	  		)   
							   ) J
							) T ) ConS
						left Outer Join 
							(select Item_Code as WtAvgItem, (Sum(Value) /Sum(Recd_Qty) )as WtAvgRate
							from ( 
								Select Item_Code , Recd_Qty, Rate, (Recd_Qty * Rate ) as Value from 
								(
									Select b.Item_Code, b.Recd_qty,
									(select max(Rate) from Pur_OrdSub Where OrderType=b.Po_Type and OrderNumber=b.Po_No 
									and Item_Code=b.Item_Code and  CompId=@CmCode and FinYear=@FinYear			) as Rate
									from Rec_Grir_Hdr a,Rec_Grir_Dtl b where a.Grir_No=b.Grir_No and a.Pur_Sub ='P' and b.Grir_Dt < = Convert(DateTime,@End,111)
									and a.CompId=b.CompId and b.CompId=@CmCode
									and a.FinYear=b.FInYear and b.FinYear=@FinYear
								)  x
							) y
							group by Item_Code ) WtAvg
						on WtAvgItem= Item 
						)  
					) yu
				) matlV
			) PV Group by Period ) Cons 
		
		Full Outer Join
		
			(select Convert(VarChar(7),invdt,126) as SalPeriod,sum(invoiceamt) as SalAmt from sal_invmai where 
			invDt between Convert(Datetime,@Start,111) and Convert(Datetime,@End,111)
			and CompId=@CmCode and FinYear=@FinYear group by Convert(VarChar(7),invdt,126) ) Sal
		On Sal.SalPeriod = Cons.ConsPeriod )  ) ConsSal
	Full Outer Join 	
		(select Period as SubConPeriod,sum(Value)as SubConAmt from (
			select Period,rate,qty  as Qty,(Rate*qty) as Value,CompID  from (
				select  convert(varchar(7),a.Grir_Dt,126) as Period, 
				b.accd_qty As Qty,
				(select max(rate) from pur_lordsub where ordertype=b.po_type and ordernumber=b.po_no and
				compid=@CmCode and finyear=@FinYear) as Rate ,b.CompId
				from rec_grir_hdr a,rec_grir_dtl b
				Where a.pur_sub = 'S' and a.grir_no = b.grir_no and convert(datetime,b.grir_Dt ,111)
				between convert(datetime, @Start,111) and convert(datetime,@End,111) 
				and a.CompId=b.CompId and b.CompId=@CmCode and a.FinYear=b.FinYear and b.FinYear=@FinYear
			) x
		) y group by period,compid ) SubCon
	On SubConPeriod=ConsSalPeriod ) 
) Gen
 
End
GO

/****** Object:  StoredProcedure [dbo].[MisSal_CustRejPPM_Sel]    Script Date: 17/06/2026 11:30:24 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

/****** Object:  Stored Procedure dbo.MisSal_CustRejPPM_Sel    Script Date: 16/04/2007 1:04:28 PM ******/
CREATE PROCEDURE  [dbo].[MisSal_CustRejPPM_Sel] (@CustCode Varchar(5), @Start datetime, @End datetime, @CmCode varchar(4),@FinYear varchar(25))

 AS
begin
Set NoCount On

Select Period,CustRejPPM,SubString(Period,6,2) as [Month],Null,'Customer Rejection PPM' as ReportTitle,@CmCode from (
Select Case when Grir.GrirPeriod is null then Sal.SalPeriod else Grir.GrirPeriod end as Period,
(isnull(Grir.RejQty,0)*1000000/Sal.InvQty)as CustRejPPM from(
	Select Convert(VarChar(7),A.GRIR_DT,126) as GrirPeriod ,SUM(REJ_QTY) as RejQty 
	FROM REC_GRIR_HDR A,REC_GRIR_DTL B WHERE A.GRIR_NO = B.GRIR_NO AND 
	a.Pur_Sub = 'R'  and a.VendorCode =@CustCode and a.Grir_Dt between Convert(Datetime,@Start,111) and Convert(Datetime,@End,111)
	and  a.CompId=b.CompId and b.CompId=@CmCode and a.FinYear=b.FinYear and b.FinYear =@FinYear
	 GROUP BY Convert(VarChar(7),A.GRIR_DT,126) ) Grir
Full Outer Join
	(select Convert(VarChar(7),A.invdt,126) as SalPeriod,sum(qty) as InvQty from 
	sal_invmai a,sal_invsub b where a.invnum = b.invnum and a.invtype = b.invtype  and
	a.InvDt between Convert(Datetime,@Start,111) and Convert(Datetime,@End,111) and a.CustCode =@CustCode 
	and a.CompId=b.CompId and b.CompId=@CmCode and a.FinYear=b.FinYear and b.FinYear =@FinYear
	GROUP BY Convert(VarChar(7),A.invdt,126) ) Sal 
on Grir.GrirPeriod =Sal.SalPeriod ) CustRej
   





end
GO

