CREATE PROCEDURE  [dbo].[MisSal_DelComQty] (@CustCode VarChar(5),  @Start datetime, @End datetime, @CmCode varchar(4),@FinYear varchar(25))

 AS
begin
Set NoCount On
if ltrim(Rtrim(@CustCode)) ='' 
   exec MisSal_DelComQty_All @Start,@End,@CmCode,@FinYear
else
   exec MisSal_DelComQty_Sel @CustCode,@Start,@End,@CmCode,@FinYear
end
