/****** Object:  Stored Procedure dbo.MisSal_DelComQty_Sel    Script Date: 16/04/2007 1:04:28 PM ******/
CREATE PROCEDURE  [dbo].[MisSal_DelComQty_Sel] (@CustCode Varchar(5), @Start datetime, @End datetime, @CmCode varchar(4),@FinYear varchar(25))

 AS
begin
Set NoCount On

SELECT q.Period,(isnull(r.qty,0)/isnull(q.qty,0))*100 as DelCompQty,SubString(q.Period,6,2) as [Month],Null,'Schdule/Despatch' as description,@CmCode as CompId 
FROM  (
SELECT Convert(Varchar(7),a.SCHMONTH,126)as period,SUM(b.TOTALQTY) AS QTY 
FROM PPC_SCHDULEMAIN A,PPC_SCHDULESUB B  WHERE A.SCHNO = B.SCHNO 
and a.CustCode=@CustCode
and a.SchMonth between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111) 
and a.CompId=b.CompId and b.CompId=@CmCode
and a.FinYear=b.FinYear and b.FinYear=@FinYear
GROUP BY Convert(Varchar(7),SCHMONTH,126)) q, 
(SELECT Convert(Varchar(7),INVDT,126) as period,SUM(QTY) AS QTY 
FROM SAL_INVMAI A,SAL_INVSUB B WHERE A.INVTYPE = B.INVTYPE AND 
A.INVNUM = B.INVNUM AND A.TYPE = 'OE'  and a.CustCode=@CustCode
and a.InvDt between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111) 
and a.CompId=b.CompId and b.CompId=@CmCode
and a.FinYear=b.FinYear and b.FinYear=@FinYear
GROUP BY Convert(Varchar(7),INVDT,126)) r
 Where q.Period = r.Period  order by q.period

end
