/****** Object:  Stored Procedure dbo.MisSal_DelComVal_All    Script Date: 16/04/2007 1:04:28 PM ******/
CREATE PROCEDURE  [dbo].[MisSal_DelComVal_All] ( @Start datetime, @End datetime, @CmCode varchar(4),@FinYear varchar(25))

 AS
begin
Set NoCount On

	Select Case When Sch.SchPeriod is null then Sal.SalPeriod else Sch.SchPeriod End as Period ,
	Convert(decimal (5,2),Round((isnull(Sal.SumSalValue,0)/isnull(Sch.SumSchValue,0))*100 ,2)) as [DelComValPer],
	SubString(Case When Sch.SchPeriod is null then Sal.SalPeriod else Sch.SchPeriod End ,6,2) as [Month],null,'DelveryComplValue' ,@CmCode as CompId from 
	
		 (Select SchPeriod,Sum(SchValue) as SumSchValue from (
			Select SchPeriod,TotalQty*Rate as SchValue from ( 
				SELECT Convert(VarChar(7),a.SCHMONTH,126) as SchPeriod,TOTALQTY,
			  	(Select Rate from Sal_OrdSub where OrdType=b.OrderType  and OrdNum=b.OrderNo and
				 Item_Code=b.ItemCode and CompId=@CmCode and FinYear=@FinYear) as Rate
				FROM PPC_SCHDULEMAIN A,PPC_SCHDULESUB B
				WHERE A.SCHNO = B.SCHNO 
				and a.SchMonth between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111)   
				 and TotalQty >0 and  a.CompId=b.CompId and A.FINYEAR = B.FINYEAR 
				and b.CompId=@CmCode and b.FinYear=@FinYear
			) A  
		) b Group by SchPeriod ) as Sch
	Full Outer Join 
		(SELECT Convert(VarChar(7),INVDT,126) as SalPeriod,SUM(GoodsValue) AS SumSalValue 
		FROM SAL_INVMAI A,SAL_INVSUB B WHERE A.INVTYPE = B.INVTYPE AND A.INVNUM = B.INVNUM  AND A.TYPE = 'OE'  
		and a.InvDt between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111)   
		and a.CompId =b.CompId and b.CompId=@CmCode and 
		a.FinYear=b.FinYear and b.FinYear =@FinYear GROUP BY Convert(VarChar(7),INVDT,126) ) as Sal
	on sch.schPeriod=Sal.SalPeriod 
end
GO

/****** Object:  StoredProcedure [dbo].[MisSal_DelComVal_Sel]    Script Date: 17/06/2026 11:30:24 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

--Sel
CREATE PROCEDURE  [dbo].[MisSal_DelComVal_Sel] ( @CustCode Varchar(5),@Start datetime, @End datetime, @CmCode varchar(4),@FinYear varchar(25))

 AS
begin
Set NoCount On

	Select Case When Sch.SchPeriod is null then Sal.SalPeriod else Sch.SchPeriod End as Period ,
	Convert(decimal (5,2),Round((isnull(Sal.SumSalValue,0)/isnull(Sch.SumSchValue,0))*100 ,2)) as [DelComValPer],
	SubString(Case When Sch.SchPeriod is null then Sal.SalPeriod else Sch.SchPeriod End ,6,2) as [Month],null,'DelveryComplValue',@CmCode as CompId 
	from (
			Select SchPeriod,Sum(SchValue) as SumSchValue 
from (
			Select SchPeriod,TotalQty*Rate as SchValue 
from ( 
				SELECT Convert(VarChar(7),a.SCHMONTH,126) as SchPeriod,TOTALQTY,
			  	(Select Rate from Sal_OrdSub where OrdType=b.OrderType  and OrdNum=b.OrderNo and
				 Item_Code=b.ItemCode and CompId=@CmCode and FinYear=@FinYear) as Rate
				FROM PPC_SCHDULEMAIN A,PPC_SCHDULESUB B
				WHERE A.SCHNO = B.SCHNO  and a.CustCode=@CustCode
				and a.SchMonth between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111)   
				 and TotalQty >0 and  a.CompId=b.CompId and A.FINYEAR = B.FINYEAR 
				and b.CompId=@CmCode and b.FinYear=@FinYear
			) A  
		) b Group by SchPeriod ) as Sch

	Full Outer Join 

		(SELECT Convert(VarChar(7),INVDT,126) as SalPeriod,SUM(GoodsValue) AS SumSalValue 
		FROM SAL_INVMAI A,SAL_INVSUB B WHERE A.INVTYPE = B.INVTYPE AND A.INVNUM = B.INVNUM  AND A.TYPE = 'OE'  
		and a.CustCode=@CustCode and a.InvDt between Convert(DateTime,@Start,111) and Convert(DateTime,@End,111)   
		and a.CompId =b.CompId and b.CompId=@CmCode and 
		a.FinYear=b.FinYear and b.FinYear =@FinYear GROUP BY Convert(VarChar(7),INVDT,126) ) as Sal
	on sch.schPeriod=Sal.SalPeriod 
end
GO

