CREATE PROCEDURE [dbo].[NET_COM_Rpt_Gen_CompAddress](@AsOnDate datetime,@RptDate datetime,@BranchID varchar(3), @CompID varchar(3))                                            
As                                            
 BEGIN                                            
  SET NOCOUNT ON;               
                  
  Select                                 
    /* ( Select distinct CompanyName                                 
      From dbo.fn_COM_Company_Master('A',@AsOnDate,@RptDate)                                 
      Where Branchid ='00' and Compid=@CompID                                
    )As CompanyName,*/                                                               
    b.CompanyName, b.Address1, b.Address2, b.City, b.State as State, Isnull(J.TypeCode,'') as StateCode, b.Country as Country, b.Pincode, b.Phone, b.EMail, b.web,         
    b.CST, b.CSTDate, IsNull(b.GSTRegNo, '') as GSTRegNo, IsNull(b.GSTRegDate, '') as GSTRegDate,         
    b.LST, b.AreaCode, b.Phone, b.Fax, b.EMail, b.ECCNo, b.Division, b.Range, b.EDRegNo,                    
    IsNull(b.CollectAddress1,'') As CollectAddress1,                        
    b.CAddress1, b.CAddress2, b.CCity, CState as CState, Isnull(J1.TypeCode,'') as CStateCode, b.CCountry as CCountry, b.CPinCode, b.CPhone,                 
    b.CFax, b.CEMail, b.CWeb, RangeAddress1,RangeAddress2, NotificationNo, NotificationDate, 'AAACU4426D' as PANNo,
    IsNull(b.UdyamNo,'') As UdyamNo, b.UdyamDate                       
  From dbo.company_master b                      
  Left Outer Join dbo.fn_Com_Countrycity_Master ('A', @AsOnDate, @RptDate, @BranchID, @CompID) J                      
    On j.ChildName=b.State and J.Parentcode<>0      
  Left Outer Join dbo.fn_Com_Countrycity_Master ('A', @AsOnDate, @RptDate, @BranchID, @CompID) J1                      
    On j1.ChildName=b.CState  and J1.Parentcode<>0             
  Where b.Branchid =@BranchID and b.Compid=@CompID                                      
 END 
GO

