CREATE PROCEDURE [dbo].[NET_Com_Rpt_TraceabilityPopup_Fil_FromTrace](@ModuleCode int, @DocType Varchar(3), @DocNo int, @DocDate Datetime,         
@ItemCode varchar(20)='', @ItemSeq int = 0, @BranchID varchar(3), @CompID varchar(3))                                          
As                                         
BEGIN                                         
	SET NOCOUNT ON;           
                  
	/* Get Sales Invoice based ItemCode */
	 Select @ItemCode = ItemCode from SalesInvoice Where InvoiceType = @DocType and InvoiceNo = @DocNo and InvoiceDate = @DocDate        
	 and Branchid = @Branchid and Compid = @Compid        
       
	 Declare @ShowHeatNo as varchar(500);    
	 Declare @sDocType as varchar(3);     
	 Declare @sDocNo as int;     
	 Declare @sDocDate as datetime;     
	 Declare @TransactionItem as varchar(20);     
	 Declare @ManufactureDate datetime;     
	 Declare @Qty float;     
	 Declare @Seq int;     
	 Declare @sItemSeq int;     
	 Declare @LotID int;     
	 Declare @SublotID int;     
	 Set @ShowHeatNo = '';     
	 Declare @HeatNo as varchar(500);      
	 DECLARE HEAT_CURSOR CURSOR for    
              
	 Select c.DocType, c.DocNo, c.DocDate, c.TransactionItem, IsNull(a.HeatNo,'') As HeatNo, a.ManufactureDate, b.Qty, b.Seq, b.ItemSeq, a.LotID, a.SublotID                
	  From Inv_MaterialTran_Dtl c          
	  Left Outer Join COM_Trace_MaterialTran_TmpQty d          
	  ON d.TranID=c.ICode and d.FromWarehouseCode=c.FromWarehouseCode and d.FromRackBinCode=c.FromRackBinCode          
		and d.ToWarehouseCode=c.ToWarehouseCode and d.ToRackBinCode=c.ToRackBinCode          
		and d.ItemCode=c.TransactionItem and d.Branchid=c.Branchid and d.Compid=c.Compid          
	  Left Outer Join COM_Trace_LotMaster_TmpQty  a            
	  On a.LotID=d.LotID and a.SubLotID=d.SubLotID --and a.ItemCode=d.ItemCode          
	   and a.Branchid=d.BranchId and a.Compid=d.CompID           
	  Left Outer Join REC_ReceiptEntry_Dtl_Trace b          
	  On a.DocType=b.ReceiptEntryType AND a.DocNo=b.ReceiptEntryNo AND a.DocDate=b.ReceiptEntryDate          
	   AND a.ItemCode=b.ItemCode AND a.Branchid=b.BranchId AND a.Compid=b.CompID                             
	  Where c.DocType=@DocType and c.DocNo=@DocNo and c.DocDate=@DocDate               
		and c.TransactionItem=@ItemCode and (@ItemSeq=0 or b.ItemSeq=@ItemSeq) and c.BranchID=@BranchID and c.CompID=@CompID             
	  Order by a.TranStamp Desc     
     
	 OPEN HEAT_CURSOR      
	 FETCH NEXT FROM HEAT_CURSOR INTO @sDocType, @sDocNo, @sDocDate, @TransactionItem, @HeatNo, @ManufactureDate, @Qty, @Seq, @ItemSeq, @LotID, @SublotID      
	 WHILE @@FETCH_STATUS = 0      
	 BEGIN     

	  /* Traceability process is incomplete, so the multiple HeatNo assignment has been temporarily commented out on 29/10/2025 */
	  if @ShowHeatNo = ''    
	   Begin    
		Set @ShowHeatNo = @HeatNo;    
	   End    
	  --Else    
	  -- Begin    
	  --  Set @ShowHeatNo = @ShowHeatNo + ',' + @HeatNo;    
	  -- End    
    
	  FETCH NEXT FROM HEAT_CURSOR INTO  @sDocType, @sDocNo, @sDocDate, @TransactionItem, @HeatNo, @ManufactureDate, @Qty, @Seq, @ItemSeq, @LotID, @SublotID      
	 END      
	 CLOSE HEAT_CURSOR      
	 DEALLOCATE HEAT_CURSOR      
                 
	/* Output */
	Select @ShowHeatNo as HeatNo                      
END 
GO

/****** Object:  StoredProcedure [dbo].[NET_Com_Rpt_TraceabilityPopup_Fil_FromTrace_2]    Script Date: 17/06/2026 11:30:24 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[NET_Com_Rpt_TraceabilityPopup_Fil_FromTrace_2](@ModuleCode int, @DocType Varchar(3), @DocNo int, @DocDate Datetime,       
@ItemCode varchar(20)='', @ItemSeq int = 0, @BranchID varchar(3), @CompID varchar(3))                          
            
As                         
            
BEGIN                         
            
SET NOCOUNT ON;         
        
      
 Select @ItemCode = ItemCode from SalesInvoice Where InvoiceType = @DocType and InvoiceNo = @DocNo and InvoiceDate = @DocDate      
 and Branchid = @Branchid and Compid = @Compid      
     
 Declare @ShowHeatNo as varchar(500);  
 Declare @sDocType as varchar(3);   
 Declare @sDocNo as int;   
 Declare @sDocDate as datetime;   
 Declare @TransactionItem as varchar(20);   
 Declare @ManufactureDate datetime;   
 Declare @Qty float;   
 Declare @Seq int;   
 Declare @sItemSeq int;   
 Declare @LotID int;   
 Declare @SublotID int;   
 Set @ShowHeatNo = '';   
 Declare @HeatNo as varchar(500);
 
     
 DECLARE HEAT_CURSOR CURSOR for  
            
 Select c.DocType, c.DocNo, c.DocDate, c.TransactionItem, a.HeatNo, a.ManufactureDate, b.Qty, b.Seq, b.ItemSeq, a.LotID, a.SublotID              
  From Inv_MaterialTran_Dtl c        
  Left Outer Join COM_Trace_MaterialTran_TmpQty d        
  ON d.TranID=c.ICode and d.FromWarehouseCode=c.FromWarehouseCode and d.FromRackBinCode=c.FromRackBinCode        
    and d.ToWarehouseCode=c.ToWarehouseCode and d.ToRackBinCode=c.ToRackBinCode        
    and d.ItemCode=c.TransactionItem and d.Branchid=c.Branchid and d.Compid=c.Compid        
  Left Outer Join COM_Trace_LotMaster_TmpQty  a          
  On a.LotID=d.LotID and a.SubLotID=d.SubLotID --and a.ItemCode=d.ItemCode        
   and a.Branchid=d.BranchId and a.Compid=d.CompID         
  Left Outer Join REC_ReceiptEntry_Dtl_Trace b        
  On a.DocType=b.ReceiptEntryType AND a.DocNo=b.ReceiptEntryNo AND a.DocDate=b.ReceiptEntryDate        
   AND a.ItemCode=b.ItemCode AND a.Branchid=b.BranchId AND a.Compid=b.CompID                           
  Where c.DocType=@DocType and c.DocNo=@DocNo and c.DocDate=@DocDate             
    and c.TransactionItem=@ItemCode and (@ItemSeq=0 or b.ItemSeq=@ItemSeq) and c.BranchID=@BranchID and c.CompID=@CompID           
  Order by A.HeatNo    
   
 OPEN HEAT_CURSOR    
 FETCH NEXT FROM HEAT_CURSOR INTO @sDocType, @sDocNo, @sDocDate, @TransactionItem, @HeatNo, @ManufactureDate, @Qty, @Seq, @ItemSeq, @LotID, @SublotID    
 WHILE @@FETCH_STATUS = 0    
 BEGIN   
  
  if @ShowHeatNo = ''  
   Begin  
    Set @ShowHeatNo = @HeatNo;  
   End  
  Else  
   Begin  
    Set @ShowHeatNo = @ShowHeatNo + ',' + @HeatNo;  
   End  
  
  FETCH NEXT FROM HEAT_CURSOR INTO  @sDocType, @sDocNo, @sDocDate, @TransactionItem, @HeatNo, @ManufactureDate, @Qty, @Seq, @ItemSeq, @LotID, @SublotID    
 END    
 CLOSE HEAT_CURSOR    
 DEALLOCATE HEAT_CURSOR    
               
  Select @ShowHeatNo as HeatNo  
                
END 
GO

