SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

  
CREATE PROCEDURE [dbo].[NET_SAL_Rpt_Invoiceprint_Expr_Gen](@InvType Varchar(3),@InvNo int,@InvDate datetime,@ModuleCode int,@AsonDate datetime,     
     @RptDate datetime,@BranchID Varchar(3),@CompID varchar(3),@FinYear Varchar(20))    
AS    
BEGIN    
 SET NOCOUNT ON; 
 
	Declare @MdlCode int;  
  
	Select @MdlCode= Case When Type ='Rejection' then 9 Else @ModuleCode End   
	from SAL_Invoice_Hdr a1 Where a1.InvoiceNo = @InvNo and a1.InvoiceDate = @InvDate and a1.InvoiceType = @InvType and                                       
	a1.BranchID = @BranchID and a1.CompId = @CompID and a1.Finyear = @Finyear    
    
 DECLARE @Rpt_TaxInvoice_Gen_Expr TABLE    
 (    
  ExprSeq int,    
  ExprName varchar(50),    
  Resultvalue varchar(15),    
  GrandTotalFlag int,  
  TaxableAmount  varchar(50)    
 )    
    
 INSERT INTO @Rpt_TaxInvoice_Gen_Expr    
 Select distinct a.ExprSeq, a.ExprName, a.Resultvalue, a.GrandTotalFlag, Case When a.ExprName = 'TOTAL GST' Then a.Resultvalue Else 0 End as TaxableAmount    
 from dbo.fn_COM_GetExprResults_Saved (@InvType,@InvNo,@InvDate, @MdlCode, @BranchID, @CompID, @FinYear) a   
 Where a.Resultvalue>0  
 order by a.ExprSeq   
  
 DECLARE @Output varchar(800);    
 SET @Output='';    
    
 DECLARE @ExprName char(50), @ResultValue money;    
    
 DECLARE Cur CURSOR FOR     
  SELECT ExprName, ResultValue FROM @Rpt_TaxInvoice_Gen_Expr Order By ExprSeq    
 OPEN Cur    
  FETCH NEXT FROM Cur INTO @ExprName, @Resultvalue    
    
 WHILE (@@FETCH_STATUS = 0)    
 BEGIN    
  SET @Output = @Output + @ExprName + Convert(char(15), @ResultValue);                              
  FETCH NEXT FROM Cur INTO @ExprName, @Resultvalue    
 END    
    
 CLOSE Cur       
 DEALLOCATE Cur    
    
 --Print @Output;    
    
 SELECT TOP 1 IsNull(@Output,'') as ExprString FROM @Rpt_TaxInvoice_Gen_Expr a     
    
END 

GO

/****** Object:  StoredProcedure [dbo].[NET_SAL_Rpt_InvoicePrint_Gen]    Script Date: 17/06/2026 11:30:24 ******/
SET ANSI_NULLS ON
GO

