CREATE PROCEDURE [dbo].[NET_SAL_Rpt_InvoicePrint_Gen](@InvType varchar(3), @InvNo int, @InvDate datetime, @AsOnDate datetime,     
@RptDate datetime, @BranchID varchar(3), @Compid varchar(3), @Finyear varchar(20))                    
AS              
                  
BEGIN                            
 SET NOCOUNT ON;    
     
 Declare @CompCode As varchar(5);      
 Declare @PertainingToID As int, @VerticalID As int, @ModuleCode As int;     
 Declare @NoWidth As bit;               
     
 /* Get FormattedDocNo Data */    
 DECLARE @DOCNoFormatted TABLE        
 (        
  DocNoFormatted varchar(200)        
 )                        
             
 SET @CompCode=(@Compid+@BranchID);    
 Select @PertainingToID=1, @VerticalID=5, @ModuleCode=4, @NoWidth='0';     
    
 /* Insert Data Into Temp Table */      
 INSERT INTO @DOCNoFormatted          
 EXECUTE COM_Net_Get_FormattedDocNo @InvType, @InvNo, @InvDate, @PertainingToID, @NoWidth, @VerticalID, @ModuleCode,     
                   @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear       
 --------------------------------------------------------    
    
 Select distinct a.InvoiceType, a.InvoiceNo, -- (IsNull(ps.DocNoFormatted, Convert(varchar, a.InvoiceNo))) As InvoiceNo,    
  IsNull(ps.DocNoFormatted,'') As PrefixSuffix, a.InvoiceDate, a.InvoiceTime, a.TotalAmount,     
  IsNull(b.VendorCode,'') as VendorCode, a.CustomerCode as CustomerCode,                     
  IsNull((Select b.PartyName From FAS_PArty_Master b             
      Where b.PartyCode = a.CustomerCode and b.Branchid = a.Branchid and b.Compid = a.Compid            
     ),'') PartyName,                     
  a.ModeCode,              
  IsNull((select h.Description             
   from TermsMaster h             
   where h.TypeFlg = 'Mode' and h.Code = a.ModeCode and h.Branchid = a.Branchid and h.Compid = a.Compid            
  ),'') As Mode,                     
  a.RemovalTime, f.TariffNo,             
  IsNull((select c.Commodity from INV_Commodity_Master c  where c.TariffNo = f.TariffNo and c.Branchid = @BranchID and c.compid = @CompID            
    ),'') As Commodity,                     
  a.VehicleNo, a.ItemCode,              
  IsNull((select g.PartNo from SAL_Customer_ItemMaster g             
   where g.CustomerCode = a.CustomerCode and g.ItemCode = a.ItemCode and g.Branchid = @BranchID and g.Compid = @CompID            
  ),'') As PartNo,                     
  f.ItemDescription, a.InvoiceQty , a.Rate,  a.AssessableRate, (a.InvoiceQty*a.Rate) GoodsValue,     
  (a.InvoiceQty*a.AssessableRate) AssessableGoods,                     
  a.NoofPackets, a.OrderType, a.OrderNo,a.OrderDate, e.Add1, e.Add2,e.Add3,e.City,e.Pincode, e.State,     
  Isnull(j.TypeCode,'') as StateCode, e.GSTRegNo, e.LST,  e.CST, e.ECCNo, IsNull(e.UdyamNo,'') As UdyamNo, e.UdyamDate,                     
  isNull((Select top 1 ReferenceNo + ' - ' + Convert(varchar(10),ReferenceDate,103)             
     From SAL_ORDER_HDR d       
     Where  d.OrderType = IsNull(g.OrderType,a.OrderType) and d.OrderNo = IsNull(g.OrderNo,a.OrderNo)     
        and d.OrderDate = IsNull(g.OrderDate,a.OrderDate)            
        and d.Branchid = @BranchID and d.Compid = @CompID --and d.finyear = @Finyear            
    ), (Select top 1 ReferenceNo + ' - ' + Convert(varchar(10),ReferenceDate,103)             
      From SAL_JOBWORKORDER_HDR d     
      where d.OrderType = a.OrderType and d.OrderNo = a.OrderNo and d.OrderDate = a.OrderDate              
        and d.Branchid = @BranchID and d.Compid = @CompID and d.finyear = @Finyear            
  )) As RefNo,                     
  a.AInformation1,a.Type,f.UOMDecimal,f.UOMDesc, IsNull(i.HSNNo,f.HSNId) as HSNNo,              
  IsNull((Select CreditDays From fn_Fas_Ledgermaster(@AsOnDate, @RptDate, @CompCode) d1                  
      Where d1.LedgerCode = a.CustomerCode                  
     ),0) As CreditDays,     
  a.AInformation1, Convert(Datetime,a.AInformation2,120) as AInformation2        
  --Case When CharIndex('-', a.AInformation2, 1)=0 Then convert(datetime, a.AInformation2, 103) Else Convert(Datetime,a.AInformation2,120) End as AInformation2    
 From  SalesInvoice a                     
 left outer join FAS_PARTY_Master b                     
  on a.CustomerCode = b.PartyCode and a.Branchid = b.Branchid  and a.Compid = b.Compid                     
 left outer join FAS_PARTY_ADDRESS e                     
  on a.CustomerCode = e.PartyCode and a.Branchid = e.Branchid  and a.Compid = e.Compid                     
 left outer join Material_Master f                      
  on f.ItemCode = a.ItemCode and f.Branchid = a.Branchid and f.Compid = a.Compid                     
 Left Outer Join fn_BOM_HSNNo_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) i                        
  On i.HSNId=f.HSNId               
 Left Outer Join dbo.fn_Com_Countrycity_Master ('A', @AsOnDate, @RptDate, @BranchID, @CompID) J                                
  On j.ChildName=e.State  and J.Parentcode<>0             
 and j.ParentCode NOT IN               
  (            
   Select ChildCode             
   From fn_COM_CountryCity_MAster('A', @AsOnDate, @RptDate, @BranchID, @CompID)             
   Where ParentCode <> 0 and ParentCode<>j.ChildCode            
  )       
 Left Outer Join SalesInvoice g          
  On a.AInformation1=(g.InvoiceType + '-' +  Convert(Varchar,g.InvoiceNo)) and a.AInformation2=g.InvoiceDate           
   and a.ItemCode=g.ItemCode and a.BranchID=g.BranchID and a.CompID=g.CompID    
    
 OUTER APPLY @DOCNoFormatted ps    
                       
 Where a.InvoiceType=@InvType and a.InvoiceNo=@InvNo and a.InvoiceDate=@InvDate     
    and a.Branchid=@BranchID and a.Compid=@CompID and a.finyear=@Finyear                    
END
GO

