CREATE PROCEDURE [dbo].[NET_SAL_Rpt_InvoicePrint_Gen_GSTTaxableAmount](@InvType Varchar(3),@InvNo int,@InvDate datetime,@ModuleCode int,@AsonDate datetime,@RptDate datetime,@BranchID Varchar(3),@CompID varchar(3),@FinYear Varchar(20))  
  
As  
  
 BEGIN  
  
  SET NOCOUNT ON  
  
  	Declare @MdlCode int;  
  
	Select @MdlCode= Case When Type ='Rejection' then 9 Else @ModuleCode End   
	from SAL_Invoice_Hdr a1 Where a1.InvoiceNo = @InvNo and a1.InvoiceDate = @InvDate and a1.InvoiceType = @InvType and                                       
	a1.BranchID = @BranchID and a1.CompId = @CompID and a1.Finyear = @Finyear    
    
   Select a.Resultvalue as GSTTaxableAmount  
   From dbo.fn_COM_GetExprResults_Saved (@InvType,@InvNo, @InvDate, @MdlCode, @BranchID,@CompID ,@Finyear) a  
   Where a.ExprName = 'TOTAL GST' and a.Resultvalue>0  
  
END
GO

