CREATE PROCEDURE [dbo].[OperationCostUpDate] 

AS

	begin

	if exists (select * from dbo.sysobjects where id = object_id(N'[dbo].[HrRate]') and OBJECTPROPERTY(id, N'IsView') = 1) drop view [dbo].[HrRate]


	--create view HrRate as
		(select a.itemcode, a.machinecode, a.cycletime, a.operationcost, b.machineHrrate,round((b.machineHrrate*a.cycletime)/3600.0,2) OCost
		from BOM_ItemwiseMachinewiseCycleTime a left outer join MAINT_Equipment_Master b 
		on a.MachineCode = b.EquipmentCode and a.branchid = b.branchid and a.compid = b.compid)

	update HrRate set operationcost = OCost

	end


GO

