SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE procedure [dbo].[PAY_Get_GrossSalary](@UserKey as varchar(30), @AsOnDate datetime, @BranchID Varchar(3), @CompID varchar(3))  

AS  

Create Table #GrossSalary
	 (EmployeeCode	varchar(10),
	EmployeeName 	varchar(50),
	ExprGroupID int,
	ExprGroupName varchar(50),
	Amount	float,
	Period	int,
	EffDate	datetime,
	SalaryFormula	int,
	FormulaName varchar(50),
	Branchid	varchar(3),
	Compid	varchar(10))

BEGIN

	SET NOCOUNT ON
	
	Declare @EmployeeId  float
	
	declare  EmployeeList cursor For
	select distinct b.SelectStr from COM_SelectList b where UserKey=@UserKey and b.Branchid = @Branchid and b.Compid = @compid
	
		OPEN EmployeeList
		FETCH NEXT FROM EmployeeList into @EmployeeId
		WHILE @@FETCH_STATUS = 0
		
		BEGIN
	
			Insert into #GrossSalary
			execute PAY_Get_GrossSalary_CommonSalary @AsOnDate, @EmployeeId, @Branchid, @compid
			
			FETCH NEXT FROM EmployeeList into @EmployeeId 
		END
	 	
		close EmployeeList
		deallocate EmployeeList
	
		Select * from #GrossSalary
	
		Return

END
GO

/****** Object:  StoredProcedure [dbo].[PAY_Get_GrossSalary_CommonSalary]    Script Date: 17/06/2026 11:30:25 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PAY_Get_GrossSalary_CommonSalary](@EffDate datetime, @EmployeeCode Varchar(10),
	@BranchID varchar(3), @CompID varchar(3))    
AS  
BEGIN
 SET NOCOUNT ON;      
  
 Declare @DOJ datetime  
  Select @DOJ=DateofJoining   
  From PAY_Employee_Master  
  Where EmployeeCode=@EmployeeCode and BranchID=@BranchID and CompID=@CompID  
  
 Select @DOJ=@DOJ+ ' ' + '23:59:59'  
   
 IF @DOJ < @EffDate  
  BEGIN  
   Select @DOJ=@EffDate  
  END  
  
  
 Select n.EmployeeCode, n.EmployeeName, n.ExprGroupID,o.ExprGroupName, n.Amount, n.Period, n.EffDate, n.SalaryFormula,   
  n.FormulaName, n.Branchid, n.Compid   
 From  
  (  
   Select ExprGroupID, Max(SlNo) as SlNo  
  
   From  
    (  
     Select b1.EmployeeCode, b1.EmployeeName, a1.ExprGroupId, a1.Amount, 1 as SlNo, a1.Period, a1.EffDate, 0 as SalaryFormula,   
      '' as FormulaName, a1.Branchid, a1.Compid   
     From dbo.fn_PAY_CommonSalary_Master(@DOJ,@BranchID,@CompID) a1  
     Left outer Join PAY_Employee_Master b1   
      On a1.EmploymentNature = b1.EmploymentNature and a1.Branchid = b1.Branchid and a1.Compid = b1.Compid  
     Where a1.CadreAll = 1 and a1.DesignationAll = 1 and a1.GradeAll = 1 and b1.EmployeeCode = @EmployeeCode  
      and a1.Branchid = @BranchID and a1.Compid = @CompID  
   
     UNION  
   
     Select b2.EmployeeCode, b2.EmployeeName, a2.ExprGroupId, a2.Amount, 2 as SlNo, a2.Period, a2.EffDate, 0 as SalaryFormula,   
      '' as FormulaName, a2.Branchid, a2.Compid   
     From dbo.fn_PAY_CommonSalary_Master(@DOJ,@BranchID,@CompID) a2  
     Left outer Join PAY_Employee_Master b2   
      On a2.EmploymentNature = b2.EmploymentNature and a2.CadreCode = b2.CadreCode   
      and a2.Branchid = b2.Branchid and a2.Compid = b2.Compid  
     Where a2.CadreAll = 0 and a2.DesignationAll = 1 and a2.GradeAll = 1 and b2.EmployeeCode = @EmployeeCode  
      and a2.Branchid = @BranchID and a2.Compid = @CompID  
   
     UNION  
   
     Select b3.EmployeeCode, b3.EmployeeName, a3.ExprGroupId, a3.Amount, 3 as SlNo, a3.Period, a3.EffDate, 0 as SalaryFormula,   
      '' as FormulaName, a3.Branchid, a3.Compid   
     From dbo.fn_PAY_CommonSalary_Master(@DOJ,@BranchID,@CompID) a3  
     Left outer Join PAY_Employee_Master b3   
      On a3.EmploymentNature = b3.EmploymentNature and a3.CadreCode = b3.CadreCode   
      and a3.DesignationCode = b3.DesignationCode and a3.Branchid = b3.Branchid and a3.Compid = b3.Compid  
     Where a3.CadreAll = 0 and a3.DesignationAll = 0 and a3.GradeAll = 1 and b3.EmployeeCode = @EmployeeCode  
      and a3.Branchid = @BranchID and a3.Compid = @CompID  
   
     UNION  
   
     Select b4.EmployeeCode, b4.EmployeeName, a4.ExprGroupId, a4.Amount, 4 as SlNo, a4.Period, a4.EffDate, 0 as SalaryFormula,   
      '' as FormulaName, a4.Branchid, a4.Compid   
     From dbo.fn_PAY_CommonSalary_Master(@DOJ,@BranchID,@CompID) a4  
     Left outer Join PAY_Employee_Master b4   
      On a4.EmploymentNature = b4.EmploymentNature and a4.CadreCode = b4.CadreCode   
      and a4.DesignationCode = b4.DesignationCode and a4.GradeCode = b4.GradeCode and a4.Branchid = b4.Branchid and a4.Compid = b4.Compid  
     Where a4.CadreAll = 0 and a4.DesignationAll = 0 and a4.GradeAll = 0 and b4.EmployeeCode = @EmployeeCode  
      and a4.Branchid = @BranchID and a4.Compid = @CompID  
    ) x  
   Group By ExprGroupID  
  ) m  
  
 Inner Join   
  (  
   Select b1.EmployeeCode, b1.EmployeeName, a1.ExprGroupId, a1.Amount, 1 as SlNo, a1.Period, a1.EffDate, 0 as SalaryFormula,   
    '' as FormulaName, a1.Branchid, a1.Compid   
   From dbo.fn_PAY_CommonSalary_Master(@DOJ,@BranchID,@CompID) a1  
   Left outer Join PAY_Employee_Master b1   
    On a1.EmploymentNature = b1.EmploymentNature and a1.Branchid = b1.Branchid and a1.Compid = b1.Compid  
   Where a1.CadreAll = 1 and a1.DesignationAll = 1 and a1.GradeAll = 1 and b1.EmployeeCode = @EmployeeCode  
     and a1.Branchid = @BranchID and a1.Compid = @CompID  
   
   UNION  
   
   Select b2.EmployeeCode, b2.EmployeeName, a2.ExprGroupId, a2.Amount, 2 as SlNo, a2.Period, a2.EffDate, 0 as SalaryFormula,   
    '' as FormulaName, a2.Branchid, a2.Compid   
   From dbo.fn_PAY_CommonSalary_Master(@DOJ,@BranchID,@CompID) a2  
   Left outer Join PAY_Employee_Master b2   
    On a2.EmploymentNature = b2.EmploymentNature and a2.CadreCode = b2.CadreCode   
    and a2.Branchid = b2.Branchid and a2.Compid = b2.Compid  
   Where a2.CadreAll = 0 and a2.DesignationAll = 1 and a2.GradeAll = 1 and b2.EmployeeCode = @EmployeeCode  
     and a2.Branchid = @BranchID and a2.Compid = @CompID  
   
   UNION  
   
   Select b3.EmployeeCode, b3.EmployeeName, a3.ExprGroupId, a3.Amount, 3 as SlNo, a3.Period, a3.EffDate, 0 as SalaryFormula,   
    '' as FormulaName, a3.Branchid, a3.Compid   
   From dbo.fn_PAY_CommonSalary_Master(@DOJ,@BranchID,@CompID) a3  
   Left outer Join PAY_Employee_Master b3   
    On a3.EmploymentNature = b3.EmploymentNature and a3.CadreCode = b3.CadreCode   
    and a3.DesignationCode = b3.DesignationCode and a3.Branchid = b3.Branchid and a3.Compid = b3.Compid  
   Where a3.CadreAll = 0 and a3.DesignationAll = 0 and a3.GradeAll = 1 and b3.EmployeeCode = @EmployeeCode  
     and a3.Branchid = @BranchID and a3.Compid = @CompID  
   
   UNION  
   
   Select b4.EmployeeCode, b4.EmployeeName, a4.ExprGroupId, a4.Amount, 4 as SlNo, a4.Period, a4.EffDate, 0 as SalaryFormula,   
    '' as FormulaName, a4.Branchid, a4.Compid   
   From dbo.fn_PAY_CommonSalary_Master(@DOJ,@BranchID,@CompID) a4  
   Left outer Join PAY_Employee_Master b4   
    On a4.EmploymentNature = b4.EmploymentNature and a4.CadreCode = b4.CadreCode   
    and a4.DesignationCode = b4.DesignationCode and a4.GradeCode = b4.GradeCode and a4.Branchid = b4.Branchid and a4.Compid = b4.Compid  
    Where a4.CadreAll = 0 and a4.DesignationAll = 0 and a4.GradeAll = 0 and b4.EmployeeCode = @EmployeeCode  
     and a4.Branchid = @BranchID and a4.Compid = @CompID  
  ) n  
  
  On m.ExprGroupID=n.ExprGroupID and m.SlNo=n.SlNo  
 Left outer Join PAY_FormulaExpr_Group o   
  On n.ExprGroupID = o.ExprGroupID and n.Branchid = o.Branchid and n.Compid = o.Compid  
  
 UNION   
   
 select a.EmployeeCode, b.EmployeeName, a.ExprGroupID, o.ExprGroupName, a.Amount, a.Period, a.EDate, a.SalaryFormula,   
  c.FrmLName as FormulaName, a.Branchid, a.Compid   
 From dbo.fn_PAY_Salary_Master(@DOJ,@BranchID,@CompID)  a   
 Left outer Join PAY_FormulaExpr_Group o   
  On a.ExprGroupID = o.ExprGroupID and a.Branchid = o.Branchid and a.Compid = o.Compid  
 Left outer Join PAY_Employee_Master b   
  On a.EmployeeCode = b.EmployeeCode and a.Branchid = b.Branchid and a.Compid = b.Compid  
 Left outer Join PAY_FormulaMast_Hdr c   
  On c.FrmId=a.SalaryFormula and c.Branchid = a.Branchid and c.Compid = a.Compid  
 Where a.EmployeeCode = @EmployeeCode and a.Branchid = @BranchID and a.Compid = @CompID   
END  
  
GO

/****** Object:  StoredProcedure [dbo].[PAY_Get_Salary_CommonSalary]    Script Date: 17/06/2026 11:30:25 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PAY_Get_Salary_CommonSalary] (@EffDate datetime, @TDate datetime, @EmploymentNature Char(1), @EmployeeCode Varchar(10), @CadreCode int, @DesignationCode int, @GradeCode int, @ExprGroupId int, @BranchID varchar(3), @CompID varchar(3))

 AS

Begin

Select n.ExprGroupID,o.ExprGroupName, n.Amount, n.Branchid, n.Compid from
(Select ExprGroupID, Max(SlNo) as SlNo

From
	(select ExprGroupId, Amount, 1 as SlNo, Branchid, Compid from dbo.fn_PAY_CommonSalary_Master(@TDate,@BranchID,@CompID) 
		where EmploymentNature= @EmploymentNature and CadreAll = 1 and DesignationAll = 1 and GradeAll = 1
			and ExprGroupId = @ExprGroupId and Branchid = @BranchID and Compid = @CompID
	
	UNION
	
	select ExprGroupId, Amount, 2 as SlNo, Branchid, Compid from dbo.fn_PAY_CommonSalary_Master(@TDate,@BranchID,@CompID) 
		where EmploymentNature= @EmploymentNature and CadreAll = 0 and DesignationAll = 1 and GradeAll = 1
			and CadreCode = @CadreCode and ExprGroupId = @ExprGroupId and Branchid = @BranchID and Compid = @CompID
	
	UNION
	
	select ExprGroupId, Amount, 3 as SlNo, Branchid, Compid from dbo.fn_PAY_CommonSalary_Master(@TDate,@BranchID,@CompID) 
		where EmploymentNature= @EmploymentNature and CadreAll = 0 and DesignationAll = 0 and GradeAll = 1
			and CadreCode = @CadreCode and DesignationCode = @DesignationCode and ExprGroupId = @ExprGroupId and Branchid = @BranchID and Compid = @CompID
	
	UNION
	
	select ExprGroupId, Amount, 4 as SlNo, Branchid, Compid from dbo.fn_PAY_CommonSalary_Master(@TDate,@BranchID,@CompID) 
		where EmploymentNature= @EmploymentNature and CadreAll = 0 and DesignationAll = 0 and GradeAll = 0
			and CadreCode = @CadreCode and DesignationCode = @DesignationCode and GradeCode = @GradeCode 
			and ExprGroupId = @ExprGroupId and Branchid = @BranchID and Compid = @CompID
	) x
Group By ExprGroupID
) m

Inner Join 

(select ExprGroupId, Amount, 1 as SlNo, Branchid, Compid from dbo.fn_PAY_CommonSalary_Master(@TDate,@BranchID,@CompID) 
		where EmploymentNature= @EmploymentNature and CadreAll = 1 and DesignationAll = 1 and GradeAll = 1
			and ExprGroupId = @ExprGroupId and Branchid = @BranchID and Compid = @CompID
	
	UNION
	
	select ExprGroupId, Amount, 2 as SlNo, Branchid, Compid from dbo.fn_PAY_CommonSalary_Master(@TDate,@BranchID,@CompID) 
		where EmploymentNature= @EmploymentNature and CadreAll = 0 and DesignationAll = 1 and GradeAll = 1
			and CadreCode = @CadreCode and ExprGroupId = @ExprGroupId and Branchid = @BranchID and Compid = @CompID
	
	UNION
	
	select ExprGroupId, Amount, 3 as SlNo, Branchid, Compid from dbo.fn_PAY_CommonSalary_Master(@TDate,@BranchID,@CompID) 
		where EmploymentNature= @EmploymentNature and CadreAll = 0 and DesignationAll = 0 and GradeAll = 1
			and CadreCode = @CadreCode and DesignationCode = @DesignationCode and ExprGroupId = @ExprGroupId 
			and Branchid = @BranchID and Compid = @CompID
	
	UNION
	
	select ExprGroupId, Amount, 4 as SlNo, Branchid, Compid from dbo.fn_PAY_CommonSalary_Master(@TDate,@BranchID,@CompID) 
		where EmploymentNature= @EmploymentNature and CadreAll = 0 and DesignationAll = 0 and GradeAll = 0
			and CadreCode = @CadreCode and DesignationCode = @DesignationCode and GradeCode = @GradeCode 
			and ExprGroupId = @ExprGroupId and Branchid = @BranchID and Compid = @CompID
	) n

On m.ExprGroupID=n.ExprGroupID and m.SlNo=n.SlNo
left outer join PAY_FormulaExpr_Group o on n.ExprGroupID = o.ExprGroupID
and n.Branchid = o.Branchid and n.Compid = o.Compid

union select a.ExprGroupID, o.ExprGroupName, a.Amount, a.Branchid, a.Compid from PAY_Salary_Master a 
left outer join PAY_FormulaExpr_Group o on a.ExprGroupID = o.ExprGroupID
and a.Branchid = o.Branchid and a.Compid = o.Compid
where a.EmployeeCode = @EmployeeCode and a.ExprGroupId = @ExprGroupId  and a.Branchid = @BranchID and a.Compid = @CompID 
and a.EDate = @EffDate

End
GO

