CREATE PROCEDURE [dbo].[PAY_GetExpression_Prompt] (@FrmID int, @SCParamInclude bit, @UserKey varchar(26), @LockRefType varchar(5), @LockRefNo int, @LockRefDate datetime,
							@ValRefType varchar(5), @ValRefNo int, @ValRefDate datetime,
							@BranchID varchar(3), @CompID varchar(4), @Finyear varchar(15))

AS

Set NOCOUNT ON


Select a.ExprSeq, d.ExprGroupName as ExprName, dbo.fn_PayFrontEndExpression(a.FrmID, a.ExprSeq, a.BranchID, a.CompID) as Expression, 
		isNull(m2.isValueEditable, m1.isValueEditable) as isValueEditable, isNull(m2.ValueUsed, isNull(m1.ValueUsed, m.ValueUsed)) as Value 
from PAY_FormulaMast_Dtl a Left Outer Join PAY_FormulaExpr_Group d 
	On a.ExprRoute=d.Route+d.Width and a.BranchID=d.BranchID and a.CompID=d.CompID 
	--Lock Status in LockRef Document

Left Outer Join 

	(Select b.FrmID, b.ExprSeq, b.ValueUsed, b.isValueEditable from PAY_FormulaCalc_Dtl b  
	Where b.EmployeeCode=@LockRefType and b.ProcessMonth=@LockRefDate and b.ParamID=-1 and b.isValueEditable='1' 
		and b.FrmID=@FrmID and b.BranchID=@BranchID and b.CompID=@CompID ) m
	On a.FrmID=m.FrmID and a.ExprSeq=m.ExprSeq
	--Current Value in ValRef Document

Left Outer Join 

	(Select b1.FrmID, b1.ExprSeq, b1.ValueUsed, b1.isValueEditable  from PAY_FormulaCalc_Dtl b1  
	Where b1.EmployeeCode=@ValRefType and b1.ProcessMonth=@ValRefDate and b1.ParamID=-1
		and b1.FrmID=@FrmID and b1.BranchID=@BranchID and b1.CompID=@CompID ) m1
	On a.FrmID=m1.FrmID and a.ExprSeq=m1.ExprSeq
	--Temporary Running Value Prev Executing

Left Outer Join

	(Select b2.FrmID, b2.ExprSeq, b2.ValueUsed, b2.isValueEditable from PAY_tmpFormulaCalc_Dtl b2 
	Where b2.DTKey=@UserKey and b2.ParamID=-1 and b2.FrmID=@FrmID and b2.BranchID=@BranchID and b2.CompID=@CompID) m2
	On a.FrmID=m2.FrmID and a.ExprSeq=m2.ExprSeq

Where  a.FrmID=@FrmID 

and a.ExprSeq Not in 
				--LockRef
			(Select a1.ExprSeq from PAY_FormulaCalc_Dtl a1 
			Where a1.EmployeeCode=@LockRefType and a1.ProcessMonth=@LockRefDate and a1.ParamID=-1 and a1.isValueEditable='0' 
			and a1.FrmID=@FrmID and a1.BranchID=@BranchID and a1.CompID=@CompID 

			Union All
				--Any one Parameter Editable then it should be shown in Expression Value Grid
			Select ExprSeq 
			from (Select a@FrmID.ExprSeq, Case When a3.ValInputMethod='SC' Then Convert(int, @SCParamInclude)*1 Else 0 End as ScCnt, Convert(int, a@FrmID.IsValueEditable) as ValEdit 
						from PAY_FormulaMast_Block_Dtl a@FrmID Inner Join PAY_FrmParamMast_Hdr a3 
						On a@FrmID.Block=Convert(varchar, a3.ParamID) and a@FrmID.BranchID=a3.BranchID and a@FrmID.CompID=a3.CompID 
						Where a@FrmID.FrmID=@FrmID and a@FrmID.BlockType='Param' and a@FrmID.BranchID=@BranchID and a@FrmID.CompID=@CompID
						) z 
			Group by ExprSeq 
			Having Sum(ScCnt+ValEdit)=0 
			) 
and isNull(m.isValueEditable, 1) = 1
and a.BranchID=@BranchID and a.CompID=@CompID


GO

/****** Object:  StoredProcedure [dbo].[PAY_GetParameter_Prompt]    Script Date: 17/06/2026 11:30:25 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO


CREATE PROCEDURE [dbo].[PAY_GetParameter_Prompt] (@FrmID int, @SCParamInclude bit, @UserKey varchar(26), @LockRefType varchar(5), @LockRefDate datetime,
							@ValRefType varchar(5), @ValRefNo int, @ValRefDate datetime,
							@BranchID varchar(3), @CompID varchar(4))

AS

Set NOCOUNT ON


Select x.ExprName, x.ExprSeq, x.BlockSeq, x.Block, x.ParamShortName, x.ValInputMethod, x.LockTypeEditable, 
	isNull(y.isTypePercentage, x.isTypePercentage) as tmpTypePercentage, isNull(y.isTypeEditable, x.isTypeEditable) as tmpTypeEditable, isNull(y.ValueUsed, x.ValueUsed) as tmpValueUsed 
from 
	(Select p.ExprGroupName as ExprName, a.ExprSeq, a.BlockSeq, a.Block, b.ParamShortName, b.ValInputMethod,
	isNull(m.isTypeEditable, a.isTypeEditable) LockTypeEditable, 
 	isNull(m1.isTypePercentage, isNull(m.isTypePercentage, a.isTypePercentage)) isTypePercentage,  isNull(m1.isTypeEditable, isNull(m.isTypeEditable, a.isTypeEditable)) isTypeEditable, 
	isNull(m1.ValueUsed, isNull(m.ValueUsed, a.ValueUsed)) ValueUsed 
	From PAY_FormulaMast_Block_Dtl a 			--Default Values, Type
		Left Outer Join PAY_FrmParamMast_Hdr b 
			On Convert(int, a.Block)=b.ParamID and a.BranchID=b.BranchID and a.CompID=b.CompID 
		--Saved Reference Values, Type (Take Fixed Lock Statusfrom this)
		Left Outer Join 			
			(Select f.ExprSeq, f.BlockSeq, f.ParamID, f.isTypePercentage, f.isTypeEditable, f.ValueUsed, f.isValueEditable 
			from PAY_FormulaCalc_Dtl f 
			Where f.EmployeeCode=@LockRefType and f.ProcessMonth=@LockRefDate 
				and f.ParamID<>-1 and f.isValueEditable='1' and f.FrmID=@FrmID and f.BranchID=@BranchID and f.CompID=@CompID ) m 
				On a.ExprSeq=m.ExprSeq and a.BlockSeq=m.BlockSeq and Convert(int, a.Block)=m.ParamID 
		    --Saved Reference Values, Type (Take Current Values from this)
		Left Outer Join 			
			(Select f1.ExprSeq, f1.BlockSeq, f1.ParamID, f1.isTypePercentage, f1.isTypeEditable, f1.ValueUsed 
			from PAY_FormulaCalc_Dtl f1 
			Where f1.EmployeeCode=@ValRefType and f1.ProcessMonth=@ValRefDate 
				and f1.ParamID<>-1 and f1.FrmID=@FrmID and f1.BranchID=@BranchID and f1.CompID=@CompID ) m1 
				On a.ExprSeq=m1.ExprSeq and a.BlockSeq=m1.BlockSeq and Convert(int, a.Block)=m1.ParamID 
		    --for Expression Name FormulaMast_Dtl & FormulaExpr_Group Added
		Left Outer Join PAY_FormulaMast_Dtl n 
			On a.FrmID=n.FrmID and a.ExprSeq=n.ExprSeq and a.BranchID=n.BranchID and a.CompID=n.CompID 
		Left Outer Join PAY_FormulaExpr_Group p 
			On n.ExprRoute=p.Route+p.Width and n.BranchID=p.BranchID and n.CompID=p.CompID 

	Where a.FrmID=@FrmID and a.BlockType='Param' and a.BranchID=@BranchID and a.CompID=@CompID 
		    --Expression Value Given and Locked should be avoided (LockRef)
		and a.ExprSeq Not In 			
					(Select c.ExprSeq from PAY_FormulaCalc_Dtl c 
					Where c.EmployeeCode=@LockRefType and c.ProcessMonth=@LockRefDate and c.ParamID=-1 and c.isValueEditable='0' 
					and c.FrmID=a.FrmID and c.BranchID=a.BranchID and c.CompID=a.CompID ) 

		and ((isNull(m.isValueEditable, a.isValueEditable)='1' and b.ValInputMethod <> 'SC' ) 
			or (Case When @SCParamInclude='1' Then b.ValInputMethod Else '' End = 'SC'))
	) x 

Left Outer Join 		--Latest Tmp Values, Type
	(Select ExprSeq, BlockSeq, ParamID, isTypePercentage, isTypeEditable, ValueUsed 
	from PAY_tmpFormulaCalc_Dtl  
	Where DTKey=@UserKey and BranchID=@BranchID and CompID=@CompID) y 
		On x.ExprSeq=y.ExprSeq and x.BlockSeq=y.BlockSeq and Convert(int, x.Block)=y.ParamID
GO

