	(@FrmID 		[int],
	 @ExprSeq 		[int],
	 @BlockSeq 		[int],
	 @BlockType 		[varchar](15),
	 @Block 		[varchar](50),
	 @isTypePercentage	[bit],
	 @isTypeEditable	[bit],
	 @ValueUsed 		[float],
	 @isValueEditable	[bit],
	 @UserID 		[varchar](10),
	 @BranchID 		[varchar](3),
	 @CompID 		[varchar](3)) 
AS 

SET NOCOUNT ON

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		If Not Exists (Select * from PAY_FormulaMast_Block_Dtl Where FrmID=@FrmID and ExprSeq=@ExprSeq and BlockSeq=@BlockSeq and BranchID=@cBranchID and CompID=@CompID)

			INSERT INTO [PAY_FormulaMast_Block_Dtl] 
			
				 ( [FrmID],
				 [ExprSeq],
				 [BlockSeq],
				 [BlockType],
				 [Block],
				 [isTypePercentage],
				 [isTypeEditable],
				 [ValueUsed],
				 [isValueEditable],
				 [UserID],
				 [BranchID],
				 [CompID]) 
			 
			VALUES 
			
				( @FrmID,
				 @ExprSeq,
				 @BlockSeq,
				 @BlockType,
				 @Block,
				 @isTypePercentage,
				 @isTypeEditable,
				 @ValueUsed,
				 @isValueEditable,
				 @UserID,
				 @cBranchID,
				 @CompID)
	
		FETCH NEXT FROM BranchidList into @cBranchid 
	    END
	 	
	    close BranchidList
	    deallocate BranchidList
GO

