CREATE PROCEDURE [dbo].[PAY_INS_PolicyGrouping]

	(@InsuranceCompany 	[int],
	 @PolicyCode 		[int],
	 @Userid 		[varchar](10),
	 @Branchid 		[varchar](3),
	 @Compid 		[varchar](3))

AS
BEGIN
SET NOCOUNT ON

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN
		If (@cBranchID=@BranchID)
			delete from PAY_PolicyGrouping where InsuranceCompany = @InsuranceCompany and @PolicyCode = PolicyCode and Branchid = @Branchid  and Compid = @compid

		If Not Exists (Select *  from PAY_PolicyGrouping where InsuranceCompany = @InsuranceCompany and @PolicyCode = PolicyCode and Branchid = @cBranchid  and Compid = @compid)


		INSERT INTO [PAY_PolicyGrouping] 
		
			 ( [InsuranceCompany],
			 [PolicyCode],
			 [Userid],
			 [Branchid],
			 [Compid]) 
		 
		VALUES 
		
			( @InsuranceCompany,
			 @PolicyCode,
			 @Userid,
			 @cBranchid,
			 @Compid)
		
		FETCH NEXT FROM BranchidList into @cBranchid 
	END
 	
	close BranchidList
	deallocate BranchidList
END
GO

/****** Object:  StoredProcedure [dbo].[PAY_Ins_PrimaryKeyList]    Script Date: 17/06/2026 11:30:27 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO








CREATE PROCEDURE [dbo].[PAY_Ins_PrimaryKeyList] (@TableName nvarchar(256))

AS

SET NOCOUNT ON

	Declare @Cnt int
	Declare @ColName nvarchar(256)

	Delete from PAY_PrimaryKeyList where TableName=@TableName

	Select @Cnt = 1							--For Loop Count
	Select @ColName = index_col(@TableName, 1, @Cnt)		--For Store the Column name

	WHILE @ColName is not null
	
		Begin
			Insert into PAY_PrimaryKeyList
		    		Values(@TableName, @ColName, @Cnt)
		
			Select @Cnt = @Cnt + 1
			Select @ColName = index_col(@TableName, 1, @Cnt)
		End






GO

