	 @ShiftMinutes 	[int],
	 @LunchStartTime 	[datetime],
	 @LunchMinutes 	[int],
	 @ParamId 	[int],
	 @Userid 	[varchar](10),
	 @Branchid 	[varchar](3),
	 @Compid 	[varchar](3))

AS 
BEGIN
SET NOCOUNT ON

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 

	WHILE @@FETCH_STATUS = 0
		
		BEGIN

			If @BranchID = @cBranchID
				delete From PAY_Shift_Master Where ShiftCode = @ShiftCode and BranchID = @BranchID and CompID = @CompID
		
			If Not Exists 
				(Select *  From PAY_Shift_Master Where ShiftCode = @ShiftCode and BranchID = @cBranchID and CompID = @CompID)
	
				INSERT INTO [PAY_Shift_Master] 
					 ( [ShiftCode],
					 [ShiftDescription],
					 [StartTime],
					 [ShiftMinutes],
					 [LunchStartTime],
					 [LunchMinutes],
					 [ParamId],
					 [Userid],
					 [Branchid],
					 [Compid]) 
				 
				VALUES 
					( @ShiftCode,
					 @ShiftDescription,
					 @StartTime,
					 @ShiftMinutes,
					 @LunchStartTime,
					 @LunchMinutes,
					 @ParamId,
					 @Userid,
					 @cBranchid,
					 @Compid)

			FETCH NEXT FROM BranchidList into @cBranchid 
		    END
	 	
	    close BranchidList
	    deallocate BranchidList
END
