/****** Object:  StoredProcedure [dbo].[PAY_PayrollProcess_Sel_Employee]    Script Date: 17/06/2026 11:30:28 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PAY_PayrollProcess_Sel_Employee](@YearMonth Varchar(7), @BranchID varchar(3), @CompID varchar(3))         
As        
BEGIN        
	SET NOCOUNT ON;       
  
	-- Get Company Working Days
	DECLARE @NoofWorkingDays int;
		Select @NoofWorkingDays= dbo.fn_PAY_CompanyWorkingDays(@YearMonth, @BranchID, @CompID)

	Select distinct a.EmployeeCode, a.EmployeeName 
	From PAY_Employee_Master a
	Where ((a.Status='W') OR (a.Status='R' and convert(varchar(7), a.RelievedDate, 120) = @YearMonth))
		and Convert(varchar(7),a.DateOfJoining,120) <= @YearMonth and a.BranchID=@BranchID and a.CompID=@CompID
		and a.EmployeeCode not in 
			(
				Select distinct b.EmployeeCode from PAY_FormulaCalc_Hdr b 
				where convert(varchar(7), b.ProcessMonth, 120) = @YearMonth and b.Process = 1 and ProcessType = 'S' 
					and b.BranchId = @BranchID and b.CompId = @CompId
			)
		and ( (@NoofWorkingDays=0) OR (@NoofWorkingDays>0 and Exists
										(
											Select * From PAY_Time_Entry s
											Where s.EmployeeCode=a.EmployeeCode 
												and Convert(varchar(7),s.DateIn,120) = @YearMonth 
												and s.BranchId = @BranchID and s.CompId = @CompId  
										))
			)
			         
END 
GO

