CREATE PROCEDURE [dbo].[PAY_PFESILimit_Fil](@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))      
AS      
BEGIN      
    SET NOCOUNT ON      
        
    Select a.EmployeeCode, isNull(b.EmployeeName, '') as EmployeeName, IsNull(a.PFApplicable,'0') As PFApplicable,         
        IsNull(a.PFMaxLimit,0) As PFMaxLimit, IsNull(a.ESIApplicable,'0') As ESIApplicable,         
        IsNull(a.ESIMaxLimit,0) As ESIMaxLimit       
    From dbo.fn_PAY_PFESILimit(@AsOnDate,@RptDate,@BranchID,@CompID) a        
    Left Outer Join PAY_Employee_Master b        
       On a.EmployeeCode=b.EmployeeCode        
    Where (IsNull(a.PFApplicable,'0')='1' or IsNull(a.ESIApplicable,'0')='1')         
    Order by a.EmployeeCode    
      
END
GO

/****** Object:  StoredProcedure [dbo].[PAY_PFESILimit_Hlp]    Script Date: 17/06/2026 11:30:28 ******/
SET ANSI_NULLS ON
