SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PAY_PFESILimit_Hlp](@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))    
AS    
BEGIN    
    SET NOCOUNT ON    
        
    Select  a.EmployeeCode, a.EmployeeName          
    From PAY_Employee_Master a  
    Where Not Exists(Select * From dbo.fn_PAY_PFESILimit(@AsOnDate,@RptDate,@BranchID,@CompID) b  
                     Where b.EmployeeCode=a.EmployeeCode  
                    )          
    Order by a.EmployeeName        
END  

GO

