/****** Object:  StoredProcedure [dbo].[PAY_Up_CadreGrouping]    Script Date: 17/06/2026 11:30:28 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PAY_Up_CadreGrouping]
	(@EmploymentNature  [Char](1),
	 @CadreCode 	[int],
	 @DesignationCode 	[int],
	 @GradeCode 	[int],
	 @Sequence 	[int],
	 @Userid 	[varchar](10),
	 @Branchid 	[varchar](3),
	 @Compid 	[varchar](3))

AS 
BEGIN
declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		UPDATE [PAY_CadreGrouping] 
		
		SET  	 [Sequence]	= @Sequence,
			 [Userid]	 	= @Userid
			
		
		WHERE 
			([EmploymentNature]	= @EmploymentNature and
			 [CadreCode]	 	= @CadreCode AND
			 [DesignationCode]	= @DesignationCode AND
			 [GradeCode]		= @GradeCode AND
			 [Branchid]		= @cBranchid AND
			 [Compid]	 	= @Compid)
		
		FETCH NEXT FROM BranchidList into @cBranchid 
	END
 	
	close BranchidList
	deallocate BranchidList
END
GO

