CREATE PROCEDURE [dbo].[PAY_UP_Leave_Master]

	(@LeaveCode 			[varchar](3),
	 @LeaveDescription 		[varchar](30),
	 @AttendanceLinked 		[char](1),
	 @MaxLeaveDays 		[float],
	 @InitialCredit			[float],
	 @NoofDaysWorked 		[float],
	 @NoofDaysCredited 		[float],
	 @DaysPerOccurenceMin 	[float],
	 @DaysPerOccurenceMax 	[float],
	 @IsWeeklyoffInclusive		[bit],
	 @IsPaidHolidaysInclusive	[bit],
	 @DaysBetweenOccurence 	[float],
	 @NoofOccasions		[float],
	 @CarryOver 			[char](1),
	 @CreditType 			[char](1),
	 @CreditPolicy 			[char](1),
	 @Userid 			[varchar](10),
	 @Branchid 			[varchar](3),
	 @Compid 			[varchar](3))

AS
BEGIN
SET NOCOUNT ON

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		UPDATE [PAY_Leave_Master] 
		
		SET 	
		
			 [LeaveDescription]		 = @LeaveDescription,
			 [AttendanceLinked]	 	 = @AttendanceLinked,
			 [MaxLeaveDays]		 = @MaxLeaveDays,
			 [InitialCredit]			 = @InitialCredit,
			 [NoofDaysWorked]		 = @NoofDaysWorked,
			 [NoofDaysCredited]		 = @NoofDaysCredited,
			 [DaysPerOccurenceMin]	 	 = @DaysPerOccurenceMin,
			 [DaysPerOccurenceMax]	 = @DaysPerOccurenceMax,
			 [IsWeeklyoffInclusive]		 = @IsWeeklyoffInclusive,
			 [IsPaidHolidaysInclusive]	 = @IsPaidHolidaysInclusive,
			 [DaysBetweenOccurence]	 = @DaysBetweenOccurence,
			 [NoofOccasions]		 = @NoofOccasions,
			 [CarryOver]	 		 = @CarryOver,
			 [CreditType]	 		 = @CreditType,
			 [CreditPolicy] 			 = @CreditPolicy,
			 [Userid]	 			 = @Userid
		
		WHERE 
		
			( [LeaveCode]	 = @LeaveCode AND
			 [Branchid]	 = @cBranchid AND
			 [Compid]	 = @Compid)
		
		FETCH NEXT FROM BranchidList into @cBranchid 
	    END
	 	
	    close BranchidList
	    deallocate BranchidList
END
