CREATE PROCEDURE [dbo].[PPAP_ControlPlanApproval_Hlp_MxRev](@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))    
    
AS    
    
SET NOCOUNT ON    
    
 BEGIN         
           
  Select Distinct c.ControlType, c.ControlNo, c.ControlDate, c.ItemCode, c.RevisionNo, c.RevisionDate,    
    IsNull(    
    (    
    (Select ItemDescription from INV_MAterial_Master where ItemCode=c.ItemCode and Branchid=c.Branchid and   
    Compid=c.Compid)   ),'') As ItemDescription    
  From PAP_ControlPlan_Hdr c    
  Where RevisionNo=    
   (    
    Select Max(RevisionNo) From PAP_ControlPlan_Hdr     
    Where ControlNo=c.ControlNo and ControlDate=c.ControlDate and ControlType=c.ControlType     
     and ItemCode=c.ItemCode and BranchID=c.BranchID and CompID=c.CompID    
   )     
   and BranchID=@BranchID and CompID=@CompID    
    
 END  
GO

