/****** Object:  StoredProcedure [dbo].[PPAP_Rpt_StandardOperation_Gen_Param]    Script Date: 17/06/2026 11:30:30 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PPAP_Rpt_StandardOperation_Gen_Param](@ItemCode varchar(20), @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))                
                
AS                
                
SET NOCOUNT ON                
                
 BEGIN                
                 
  Select Distinct * From                 
     (               
     Select Distinct ProcessSequence, ProcessCode, ProcessFlow, a.StageCode, ShortName,                
      Case When j.Type='PT' Then ParameterDesc Else '' End As Product,                
      Case When j.Type='PS' Then ParameterDesc Else '' End As Process,                
      Case When IsNumeric(FromValue)=0 Then FromValue Else Case When Dimension='Angle' Then                     
      dbo.CDegree(fromValue) Else FromValue End +'/'+ Case When Dimension='Angle' Then                 
      dbo.CDegree(ToValue) Else toValue End End As Specification, d.InspectionTypeLongName,                 
      e.InstrumentTypeDesc, IsNull(d.DurationPeriod,'') as DurationPeriod,                
      Case d.LotsizeType When 'Actual' Then SamplingPlanTypeShortName               
  When 'Reference' then '100%'              
   Else Convert(varchar,d.NoofReading) End As Size,                
      Convert(varchar,d.InspectionDuration) As Freq,                 
      Case j.Defect When 'IdentChars' Then '<IC>' When 'Significant' Then '<SC>' When 'Major' Then ''                 
      When 'Critical' Then '<CC>' Else '' End As SplChar, d.InspectionTypeReportName, j.Seq, Type                
  From PPAP_VW_ProcessFlow a          
             
              
      Left Outer Join dbo.fn_QC_Inspection_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) c                
      On convert(varchar,c.InspectionTypeCode)=a.ProcessCode and c.ItemCode=a.StageCode and a.BranchID=c.BranchID and a.CompID =c.CompID                      
      Left Outer Join dbo.fn_BOM_Material_Parameter('A', @AsOnDate, @RptDate, @BranchID, @CompID) j                
      On c.ItemCode=j.ItemCode and c.MparamCode=j.ParamCode and c.BranchID=j.BranchID and c.CompID=j.CompID                      
      Left Outer Join dbo.fn_QC_InspectionType_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) d             
      On c.InspectionTypeCode=d.InspectionTypeCode and c.BranchID=d.BranchID and c.CompID=d.CompID                
      Left Outer Join QC_SamplingPlanType_Master h                
      On h.SamplingPlanTypeCode=d.SamplingPlanTypeCode and h.BranchID=d.BranchID and h.CompID =d.CompID                
      Left Outer Join dbo.fn_QC_QualityPlanType_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) i                
      On i.QualityPlanTypeCode=d.QualityPlanTypeCode and i.BranchID =d.BranchID and i.CompID=d.CompID                
      Left Outer Join dbo.fn_BOM_InstrumentType_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) e                
      On c.InstrumentTypeCode=e.InstrumentTypeCode and c.BranchID=e.BranchID and c.CompID=e.CompID          
             
       Where a.BranchID=@BranchID and a.CompID=@CompID and a.ItemCode=@ItemCode       
          
      UNION           
              
      Select Distinct ProcessSequence, ProcessCode, ProcessFlow, a.StageCode, ShortName,                 
      Case When c.Type='PT' Then ParameterDesc Else ''End Product,                
      Case When c.Type='PS' or c.Type='SP' Then ParameterDesc Else '' End Process,                
      Case When IsNumeric(FromValue)=0 Then FromValue Else Case When Dimension='Angle' Then                 
      dbo.CDegree(fromValue) Else fromValue End +'/'+ Case When Dimension='Angle' Then                 
      dbo.CDegree(ToValue)Else toValue End End Specification,'' As tmp ,                
      ( Select InstrumentTypeDesc From dbo.fn_BOM_InstrumentType_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID)                
        Where InstrumentTypeCode=c.InstrumentTypeCode and BranchID =c.BranchID and CompID=c.CompID                
      ) As InstrumentType,'' As Period, b.Samplesize, b.SampleFreq,                
      Case c.Defect When 'IdentChars' Then '<IC>' When 'Significant' Then '<SC>' When 'Major' Then ''                 
      When 'Critical' Then '<CC>' Else '' End As SplChar, b.ControlMethod , Seq, Type       From PPAP_VW_ProcessFlow a                
     Left Outer Join dbo.fn_BOM_Material_Parameter('A',@AsOnDate, @RptDate, @BranchID, @CompID) c                
     On c.ItemCode=a.StageCode and a.BranchID =c.BranchID and a.CompID=c.CompID                
     Left Outer Join PPAP_VW_ControlPlan b                
     On b.ItemCode=a.ItemCode and a.ProcessSequence=b.Processno and a.ProcessFlow=b.Processname                
       and c.ShortName=b.Chrno and (c.ParameterDesc=b.ChrProduct or c.ParameterDesc=b.ChrProcess)                
       and a.BranchID=b.BranchID and a.CompID=b.CompID                
     Where a.BranchID=@BranchID and a.CompID=@CompID and a.ItemCode=@ItemCode and c.ParamException=1                 
    and IsNumeric(a.Processcode)=0 and a.Processcode Not in ('P014','P02')        
             
     UNION       
               
     Select Distinct a.ProcessSequence,a.ProcessCode,a.ProcessFlow,a.StageCode,Chrno,                
      ChrProduct,ChrProcess,c.Specification, '' rplan,Evaluation,'' as Period, SampleSize, SampleFreq,                
      SplChrClass, ControlMethod, c.Seq, c.Type                
     From PPAP_VW_ProcessFlow a                
     Left Outer Join PPAP_VW_ControlPlan j                
     On a.ItemCode=j.ItemCode and a.ProcessSequence=j.Processno and a.BranchID=j.BranchID and a.CompID=j.CompID                
     Left Outer Join dbo.fn_BOM_Get_Inspection_Parameter('A', @AsOnDate, @RptDate, @BranchID, @CompID) c                
     On c.ItemCode=j.Stagecode and c.ShortName=j.Chrno and c.Specification=j.Specification                
     and (c.ParameterDesc=j.ChrProduct or c.ParameterDesc=j.ChrProcess) and c.BranchID=j.BranchID and c.CompID=j.CompID                
     Where a.BranchID=@BranchID and a.CompID=@CompID and a.ItemCode=@ItemCode                 
     and ProcessFlow In('STORAGE','TRANSPORTATION','TRANSPORTTATION')        
              
   ) x                
  Where x.Specification Is Not Null                
  Order by x.ProcessSequence, x.Seq             
                 
 END
GO

