/****** Object:  StoredProcedure [dbo].[Ppc_Get_ProductionPlan]    Script Date: 17/06/2026 11:30:30 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[Ppc_Get_ProductionPlan] (@isCreate bit,  @PDocType varchar(3), @SDocType varchar(3),  @PlanFor int,  @Period datetime,  @Finstart datetime,  @AsOnDate datetime,  @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))

AS

Begin
	SET NOCOUNT ON

	Declare @PlanMonth varchar(2)
	Declare @PlanYear varchar(4)

	Select @PlanMonth = Month(@Period) 
	Select @PlanYear = Year(@Period) 

	Select a.ItemCode, b.ItemDescription, b.UomDesc, b.UomDecimal, a.PlanQty,  a.PlanFor, a.PlanPeriod,
		(dbo.fn_WtAvgRate (a.ItemCode, @Finstart, @RptDate, @BranchID,  @CompID, @Finyear)
		 + dbo.fn_OperationCost (a.ItemCode, @BranchID,  @CompID) )Rate, 1 Seq
		From dbo.fn_PPC_ProductionPlan (@AsOnDate,  @RptDate,  @BranchID,  @CompID,  @Finyear)    a
			Left Outer Join Material_Master b
				On b.ItemCode = a.ItemCode 	and b.BranchID = a.BranchID and b.CompID = a.CompID
		Where ((a.PlanFor=1 and Month(PlanPeriod)=4) or (a.PlanFor > 1 and Month(PlanPeriod) = @PlanMonth))  and Year(PlanPeriod) = @PlanYear	
			and PlanFor = (Select Max(PlanFor) PlanFor From dbo.fn_PPC_ProductionPlan (@AsOnDate,  @RptDate,  @BranchID,  @CompID,  @Finyear)    
						Where ((PlanFor=1 and Month(PlanPeriod)=4) or (PlanFor > 1 and Month(PlanPeriod) = @PlanMonth))  and Year(PlanPeriod) = @PlanYear 
							and ((@isCreate='1' and PlanFor < @PlanFor) or (@isCreate='0' and PlanFor <= @PlanFor))
							and BranchID = a.BranchID and CompID = a.CompID and Finyear = a.Finyear and a.DocType = @PDocType)
							and a.DocType = @PDocType
Union All

	Select a.ItemCode, b.ItemDescription, b.UomDesc, b.UomDecimal, a.PlanQty,  a.PlanFor, a.PlanPeriod,
		(dbo.fn_WtAvgRate (a.ItemCode,  @Finstart, @RptDate, @BranchID,  @CompID, @Finyear)
		 + dbo.fn_OperationCost (a.ItemCode, @BranchID,  @CompID) )Rate, 2 Seq
		From dbo.fn_Sal_SalesPlan (@AsOnDate,  @RptDate,  @BranchID,  @CompID,  @Finyear)    a
			Left Outer Join Material_Master b
				On b.ItemCode = a.ItemCode 	and b.BranchID = a.BranchID and b.CompID = a.CompID
		Where ((a.PlanFor=1 and Month(PlanPeriod)=4) or (a.PlanFor > 1 and Month(PlanPeriod) = @PlanMonth))  and Year(PlanPeriod) = @PlanYear	
			and PlanFor = (Select Max(PlanFor) PlanFor From dbo.fn_Sal_SalesPlan (@AsOnDate,  @RptDate,  @BranchID,  @CompID,  @Finyear)    
						Where ((PlanFor=1 and Month(PlanPeriod)=4) or (PlanFor > 1 and Month(PlanPeriod) = @PlanMonth))  and Year(PlanPeriod) = @PlanYear and PlanFor <= @PlanFor
							and BranchID = a.BranchID and CompID = a.CompID and Finyear = a.Finyear and a.DocType = @SDocType) 
			and a.DocType = @SDocType
			
			and not exists

					(Select *
						From dbo.fn_PPC_ProductionPlan (@AsOnDate,  @RptDate,  @BranchID,  @CompID,  @Finyear)    a
						Where ((a.PlanFor=1 and Month(PlanPeriod)=4) or (a.PlanFor > 1 and Month(PlanPeriod) = @PlanMonth))  and Year(PlanPeriod) = @PlanYear	
							and PlanFor = (Select Max(PlanFor) PlanFor From dbo.fn_PPC_ProductionPlan (@AsOnDate,  @RptDate,  @BranchID,  @CompID,  @Finyear)    
										Where ((PlanFor=1 and Month(PlanPeriod)=4) or (PlanFor > 1 and Month(PlanPeriod) = @PlanMonth))  and Year(PlanPeriod) = @PlanYear and PlanFor <= @PlanFor
											and BranchID = a.BranchID and CompID = a.CompID and Finyear = a.Finyear and a.DocType = @PDocType)
											and a.DocType = @PDocType) 
								
	Order By a.ItemCode, a.PlanFor

	End
GO

