CREATE PROCEDURE [dbo].[PPC_INS_Employee_Master]
	(@EMPCode 	[int],
	 @EMPName 	[varchar](50),
	 @Term 	[varchar](10),
	 @MachineCode 	[varchar](20),
	 @OperatorType 	[varchar](50),
	 @OperatorMethod 	[varchar](20),
	 @Status 	[bit])

	
	
AS 
begin 
		select @EmpCode=isnull((select distinct EmpCode from PPC_Employee_Master where EmpName=@EMPName),0)
	
		if @EmpCode=0
			begin
				select @EmpCode=isnull((select max(EmpCode) from PPC_Employee_Master),0)+1
			end



INSERT INTO [PPC_Employee_Master] 
	 ( [EMPCode],
	 [EMPName],
	 [Term],
	 [MachineCode],
	 [OperatorType],
	 [OperatorMethod],
	 [Status]) 
 
VALUES 
	( @EMPCode,
	 @EMPName,
	 @Term,
	 @MachineCode,
	 @OperatorType,
	 @OperatorMethod,
	 @Status)

end
GO

