/****** Object:  StoredProcedure [dbo].[PPC_LogEntry_Get_LogQty]    Script Date: 17/06/2026 11:30:31 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[PPC_LogEntry_Get_LogQty](@DocType Varchar(3), @DocNo int, @DocDate datetime, @ItemCode Varchar(20), @MachineCode Varchar(20), 
@Shift Varchar(10),  @BranchID Varchar(3), @CompID Varchar(3), @FinYear Varchar(20)) 
             
AS              
              
 BEGIN              
               
  SET NOCOUNT ON              
                
            
  SELECT isnull(SUM(QTY),0) as Qty         
  FROM          
  (          
   Select Sum(Qty) as Qty          
   From QC_Inspection_Criteria            
   Where RefType=@DocType And RefNo=@DocNo and RefDate=@DocDate and ItemCode=@ItemCode            
    and MachineCode=@MachineCode and Shift=@Shift and BranchId= @BranchID and CompID= @CompID and FinYear=@FinYear            
    and Type = 'C'        
              
   UNION ALL          
              
   Select Sum(Qty) as Qty          
   From QC_Inspection_Criteria            
   Where RefType=@DocType And RefNo=@DocNo and RefDate=@DocDate and ItemCode=@ItemCode            
    and MachineCode=@MachineCode and Shift=@Shift and BranchId= @BranchID and CompID= @CompID and FinYear=@FinYear            
    and Type = 'LR'       
  )X          
           
END
GO

