CREATE PROCEDURE [dbo].[PPC_LogEntry_Get_Qty](@DocType Varchar(3), @DocNo int, @DocDate datetime, @ItemCode Varchar(20),    
 @MachineCode Varchar(20), @Shift Varchar(10), /*@WOType Varchar(3), @WONo int, @WODate datetime, */    
 @BranchID Varchar(3), @CompID Varchar(3), @FinYear Varchar(20))    
AS    
    
 BEGIN    
     
  SET NOCOUNT ON    
      
      
   Select isnull(Sum(Date1),0) as PlanQty    
   From PPC_Vw_QuickProductionplan_Dtl    
   Where DocType=@DocType and DocNo=@DocNo and DocDate=@DocDate and StageCode=@ItemCode    
    and MachineCode=@MachineCode and Shift=@Shift    
    --and WorkOrderType=@WOType and WorkOrderNo=@WONo and WorkOrderDate=@WODate    
    and BranchId= @BranchID and CompID= @CompID and FinYear=@FinYear    
    
    
END
