CREATE PROCEDURE [dbo].[PPC_LogEntry_Hlp_Inspection](@DocType varchar(3), @DocNo int, @DocDate datetime,   
 @ShiftCode varchar(10), @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3),   
 @CompID varchar(3), @Finyear Varchar(20))               
AS                           
BEGIN                          
    SET NOCOUNT ON;  
   
 Declare @TmpTbl_LogItem As Table  
 (  
  DocType varchar(3),   
  DocNo int,   
  DocDate datetime,  
  ItemCode varchar(20),  
  StageCode varchar(20),   
  ItemDescription varchar(50),  
  MachineCode varchar(20),  
  OperationSequence int,  
  CycleTime float,  
  Starttime datetime,  
  EndTime datetime,  
  TobeEnterTime datetime,  
  LotSize int,   
  Status int,  
  BranchID varchar(3),  
  CompID varchar(3),  
  SetSeq int  
 )  
  
 /* Insert Data Into Temp Table */  
 Insert Into @TmpTbl_LogItem  
 Select a.DocType, a.DocNo, a.DocDate, '' As ItemCode, a.StageCode, a.ItemDescription, a.MachineCode,   
  0 As OperationSequence, a.CycleTime, a.Starttime, a.EndTime, a.TobeEnterTime,   
  a.lotSize, a.Status, a.BranchID, a.CompID, 1 As SetSeq  
 From dbo.fn_QC_LogItemSelect(@DocType, @DocNo, @DocDate, @ShiftCode, @BranchID, @CompID) a  
 Where a.LotSize>=1 and a.BranchID=@BranchID and a.CompID=@CompID  
  
 /* Insert Data Into Temp Table */  
 Insert Into @TmpTbl_LogItem  
 Select a.DocType, a.DocNo, a.DocDate, b.ItemCode, a.StageCode, a.ItemDescription,   
  a.MachineCode, b.OperationSequence, a.CycleTime, a.Starttime, a.EndTime, a.TobeEnterTime,   
  a.lotSize, a.Status, a.BranchID, a.CompID, 2 As SetSeq  
 From @TmpTbl_LogItem a  
 Left Outer Join MpsMaster b  
  On a.StageCode=b.StageCode and a.BranchID=b.BranchID and a.CompID=b.CompID    
 Where a.SetSeq=1 and a.BranchID=@BranchID and a.CompID=@CompID  
   
 /* Output */  
 Select Distinct case a.Status when 0 then IsNull(b.InspectionType,d.InspectionType) else b.InspectionType end InspectionType,   
  case a.Status when 0 then IsNull(b.InspectionNo,d.InspectionNo) else b.InspectionNo end InspectionNo,   
  case a.Status when 0 then IsNull(b.InspectionDate,d.InspectionDate) else b.InspectionDate end InspectionDate,  
  a.StageCode, a.ItemDescription, a.MachineCode, a.ItemCode, a.OperationSequence, a.LotSize, a.Status, b.CompletedDate,   
  a.Starttime, a.Cycletime, Convert(varchar(16),a.TobeEnterTime,120) As TobeEnterTime   
 From @TmpTbl_LogItem a  -- dbo.fn_QC_LogItemSelect(@DocType, @DocNo, @DocDate, @ShiftCode, @BranchID, @CompID) a   
 Left Outer Join Qc_Inspection_Hdr b    
  On a.DocNo=b.RefNo and a.DocDate = b.RefDate and a.DocType=b.RefType and b.InspectionTypeCode=8   
   and a.Starttime=b.Starttime and a.StageCode = b.ItemCode And a.MachineCode = b.MachineCode    
 --Left Outer Join MpsMaster c   
 -- On c.StageCode=a.StageCode and c.Branchid=a.Branchid and c.Compid=a.Compid   
 Left Outer Join Qc_Inspection_Criteria d   
  On a.DocType=d.RefType and a.DocNo=d.RefNo and d.InspectionType<>'SIR'   
   and a.DocDate = d.RefDate and a.StageCode = d.ItemCode And a.MachineCode = d.MachineCode   
 Where a.SetSeq=2 and IsNull(b.InspectionTypeCode,0)<>9 and IsNull(b.CompletedStatus,0)=0    
 Order by a.ItemCode, a.OperationSequence  
END  
GO

