CREATE PROCEDURE [dbo].[PPC_LogEntry_Hlp_Patrol](@CurrDate datetime, @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))             
AS                         
BEGIN                        
    SET NOCOUNT ON;

	Declare @CurrAddDate As datetime;
	SET @CurrAddDate=DateAdd(d,-7,@CurrDate);

	Select Distinct DocType, DocNo, DocDate, StartDate, Shift 
	From PPC_QuickProductionplan_Dtl a
	Where Startdate >=@CurrAddDate and StartDate<=@CurrDate
		and ShortClose='0' and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear 
  Order by DocNo
	
END
