/****** Object:  StoredProcedure [dbo].[PPC_MaterialPossiblyProdQty]    Script Date: 17/06/2026 11:30:32 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO


CREATE PROCEDURE [dbo].[PPC_MaterialPossiblyProdQty] (@UserKey varchar(28), @ReqQty float)

AS

SET NOCOUNT ON

Begin

	Declare @Continue bit
	Declare @Level int
	Declare @Round int
	Declare @MaxLevel int
	
	Select @Level = 0
	Select @Round = 0
	Select @Continue = Convert(bit, '1')

	Select @MaxLevel=Max(StLevel) from PPC_MaterialShortage_tmp	 Where UserKey=@UserKey
	
	Update PPC_MaterialShortage_tmp Set Stock = 0, ReqQty=@ReqQty, tmpStock = 0  where UserKey=@UserKey and Stlevel=0 and ItemType='P'
	Update PPC_MaterialShortage_tmp Set tmpStock=Stock, ReqQty=0  Where UserKey=@UserKey and Stlevel>0	
	---Update PPC_MaterialShortage_tmp Set ReqQty=0 where UserKey=@UserKey and Stlevel>0
	Update PPC_MaterialShortage_tmp Set Consumed=0, tmpCons=0 Where UserKey=@UserKey

	While (@Continue = Convert(bit, '1'))

		Begin

			If Exists (Select * from PPC_MaterialShortage_tmp where UserKey=@UserKey and ReqQty > 0)
				Begin
					If  Exists 	(Select * from
								(Select Sum(tmpStock) as StockQty from PPC_MaterialShortage_tmp where UserKey=@UserKey and ItemType='S'
				
								Union All
				
								Select Sum(Qty) as StockQty from
									(Select Min(Convert(int, tmpStock / Norms)) as Qty from PPC_MaterialShortage_tmp Where UserKey=@UserKey and ItemType='C' Group by ParentCode ) y
								) x
							Where StockQty > 0
							)
					
		
						Begin
							
							Select @Level = @Level + 1		
							
							If (@MaxLevel < @Level)
								Select @Level = 1
		
							If (@Level=1)
								Select @Round = @Round + 1
		
							-- Print 'Level-'+Convert(varchar, @Level); Print 'Round-'+Convert(varchar, @Round)
		
							If (@Level % 2) = 1
					
								Begin
									--For Stages Level
					
									--to update the required stock
									Update PPC_MaterialShortage_tmp 
									Set tmpCons = Case When d.ReqQty < d.CumTotal then 0 else 
													Case When (d.ReqQty - d.CumTotal) > d.tmpStock then d.tmpStock 
														else (d.ReqQty - d.CumTotal) end
											end
									from PPC_MaterialShortage_tmp a Left Outer Join
										(Select a1.UserKey, a1.ParentCode, a1.ItemCode, a1.StLevel, a1.tmpStock, b.ReqQty, a1.OprSeq,
											isNull((Select Sum(tmpStock) from PPC_MaterialShortage_tmp c 
												where c.UserKey=a1.UserKey and c.StLevel=a1.StLevel and c.OprSeq > a1.OprSeq and c.ParentCode=a1.ParentCode), 0) as CumTotal
										from PPC_MaterialShortage_tmp a1 Left Outer Join (Select * from PPC_MaterialShortage_tmp where UserKey=@UserKey and StLevel=@Level-1) b
										On a1.ParentCode=b.ItemCode and a1.UserKey=b.UserKey
										where a1.UserKey=@UserKey and a1.StLevel=@Level) d
									On a.UserKey=d.UserKey and a.ParentCode=d.ParentCode and a.ItemCode=d.ItemCode and a.StLevel=d.StLevel
									where a.UserKey=@UserKey and a.StLevel=@Level
									
							
									-- to Reduce reqQty and Add the tmpStock in previous level
									Update PPC_MaterialShortage_tmp
									Set ReqQty = ReqQty - isNull(b.stQty, 0), tmpStock = tmpStock +  isNull(b.stQty, 0)
									from PPC_MaterialShortage_tmp a Left Outer Join (Select UserKey, ParentCode, Sum(tmpCons / Norms) as stQty from PPC_MaterialShortage_tmp b Where b.UserKey=@UserKey and b.StLevel=@Level Group by UserKey, ParentCode) b
									On a.UserKey=b.UserKey and a.ItemCode=b.ParentCode
									Where a.UserKey=@UserKey and a.StLevel=@Level-1
					
								End
							Else
								Begin
					
									--For Child Level
									
									--to update the required stock
									Update PPC_MaterialShortage_tmp 
									Set tmpCons = Case When d.ReqQty < d.MinTotal then d.ReqQty * a.Norms Else d.MinTotal * a.Norms End
									from PPC_MaterialShortage_tmp a Left Outer Join
										(Select a1.UserKey, a1.ParentCode, a1.ItemCode, a1.StLevel, a1.Stock, b.ReqQty, 
											isNull((Select Min(Convert(int, tmpStock / Norms)) from PPC_MaterialShortage_tmp c 
															where c.UserKey=a1.UserKey and c.StLevel=a1.StLevel and c.ParentCode=a1.ParentCode), 0) as MinTotal
										from PPC_MaterialShortage_tmp a1 Left Outer Join (Select * from PPC_MaterialShortage_tmp where UserKey=@UserKey and StLevel=@Level-1) b
										On a1.UserKey=b.UserKey and a1.ParentCode=b.ItemCode
										where a1.UserKey=@UserKey and a1.StLevel=@Level) d
									On a.UserKey=d.UserKey and a.ParentCode=d.ParentCode and a.ItemCode=d.ItemCode and a.StLevel=d.StLevel
									where a.UserKey=@UserKey and a.StLevel=@Level
										
									-- to Reduce reqQty and Add the tmpStock in previous level
									Update PPC_MaterialShortage_tmp
									Set ReqQty = ReqQty - isNull(b.stQty, 0), tmpStock = tmpStock +  isNull(b.stQty, 0)
									from PPC_MaterialShortage_tmp a Left Outer Join (Select UserKey, ParentCode, Min(Convert(int, tmpCons / Norms)) as stQty from PPC_MaterialShortage_tmp b Where b.UserKey=@UserKey and b.StLevel=@Level Group by UserKey, ParentCode) b
									On a.UserKey=b.UserKey and a.ItemCode=b.ParentCode
									Where a.UserKey=@UserKey and a.StLevel=@Level-1
								End						
		
							-- to update the current stock
							Update PPC_MaterialShortage_tmp
							Set tmpStock = tmpStock - tmpCons
							where UserKey=@UserKey and StLevel=@Level

							--To Update ReqQty for next level
							Update PPC_MaterialShortage_tmp
							Set ReqQty=Case When c.ParentCode is Null then 0 Else (Select ReqQty from PPC_MaterialShortage_tmp b 
															Where b.UserKey=a.UserKey and b.StLevel=a.StLevel-1 and b.ItemCode=a.ParentCode) * a.Norms End
							from PPC_MaterialShortage_tmp a Left Outer Join (Select distinct UserKey, ParentCode, StLevel from PPC_MaterialShortage_tmp Where UserKey=@UserKey and StLevel=@Level+1) c
							On a.UserKey=c.UserKey and a.StLevel=c.StLevel-1 and a.ItemCode=c.ParentCode
							Where a.UserKey=@UserKey and a.StLevel=@Level
			
			
							If @Round=1
								Begin
									--Applicable only for the First Round to take actual consumption
									UpDate PPC_MaterialShortage_tmp
									Set Consumed = tmpCons
									where UserKey=@UserKey and StLevel=@Level
								End
					
			
							End
					Else
						Begin
							Select @Continue=Convert(bit, '0')
						End
		
		--			If (@Level=6 and @Round=1)
			--			Select @Continue=Convert(bit, '0')
					
				End
			Else
				Begin
					Select @Continue=Convert(bit, '0')
				End


		End
End
GO

