CREATE PROCEDURE [dbo].[PPC_Rpt_DownTime_Gen_Machine](@ItemUserkey varchar(36)='', @ShiftUserkey varchar(36)='', 
	@RPTCode Int, @Fromdate datetime, @Todate datetime, @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))              
As              
BEGIN    
	SET NOCOUNT ON; 

	Declare @TotalShiftMinutes As int;  

	Declare @TmpTbl_PlanCriteriaReason As Table
	(
		MachineCode varchar(20), 
		AssetCode varchar(10),
		StageCode varchar(20), 
		StartDate datetime, 
		ShiftCode varchar(3), 
		PlanQty int, 
		Starttime datetime,  
		Endtime datetime,
		CriteriaCode int,
		AccQty float, 
		ReworkQty float,
		ScrapQty float,
		ReasonQty float, 		
		ReasonStartTime datetime, 
		ReasonEndTime datetime, 
		ReasonType varchar(1), 
		ReasonCode int,
		ReasonShortName varchar(10),
		Reason varchar(50),
		BranchID varchar(3), 
		CompID varchar(3), 
		Finyear varchar(20),
		SetSeq int
	)
	 
	Begin
		/* Insert Data Into Temp Table */
		Insert Into @TmpTbl_PlanCriteriaReason

		EXECUTE PPC_Rpt_DownTime_Get_PlanCriteriaReason @ItemUserkey, @ShiftUserkey, 
		@RPTCode, @Fromdate, @Todate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear

		/* Insert Data Into Temp Table */
		Insert Into @TmpTbl_PlanCriteriaReason

		Select Distinct a.MachineCode, a.AssetCode, a.StageCode, a.StartDate, a.ShiftCode, a.PlanQty, a.Starttime, 
				a.Endtime, a.CriteriaCode, a.AccQty, a.ReworkQty, a.ScrapQty, a.ReasonQty, a.ReasonStartTime, 
				a.ReasonEndTime, a.ReasonType, a.ReasonCode, a.ReasonShortName, a.Reason, a.BranchID, 
				a.CompID, a.Finyear, 2 As SetSeq  
		From @TmpTbl_PlanCriteriaReason a    	 				
		Where a.SetSeq=1 and (@ItemUserkey='' or (@ItemUserkey<>'' and Exists (Select * From COM_SelectList s2        
							Where s2.UserKey=@ItemUserkey and s2.SelectStr=a.StageCode and s2.BranchID=@BranchID and s2.CompID=@CompID
					))  
			 )    		
			and a.BranchID=@BranchID and a.CompID=@CompID --and a.Finyear=@Finyear    
  End

	Begin
		SET @TotalShiftMinutes=0;

		/* Get TotalShiftMinutes Data */
		Select @TotalShiftMinutes=Sum(b.ShiftMinutes-b.LunchMinutes) 		
		From (  
				Select Distinct a1.StartDate, a1.ShiftCode, a1.BranchID, a1.CompID, a1.Finyear  
				From @TmpTbl_PlanCriteriaReason a1  
				Where a1.SetSeq=1 and a1.BranchID=@BranchID and a1.CompID=@CompID --and a1.Finyear=@Finyear  
		) a  
		Left Outer Join PPC_Shift_Master b     
			On a.ShiftCode=b.ShiftCode and a.BranchID=@BranchID and a.CompID=@CompID  

		SET @TotalShiftMinutes=IsNull(@TotalShiftMinutes,0);
  End  
  
/* Output (Result) */	
 Select j.MachineCode, IsNull(j.ItemDesc,'') As ItemDesc, @TotalShiftMinutes As ShiftMinutes, 
	Sum(j.PlanMins) As PlanHrs, (@TotalShiftMinutes-Sum(j.PlanMins)) As UnPlanHrs,  
  Sum(ProdMins) As ProdMins, Sum(ReasMins) As ReasMins,  
  (Sum(PlanMins) - (Sum(ProdMins) + Sum(ReasMins))) As PendingMins    
 From (  
  Select /*(a.MachineCode+a.AssetCode)*/ IsNull(a.MachineCode,'') As MachineCode, f.ItemDesc, a.StartDate, a.ShiftCode,  
   Round((Sum(a.PlanQty*a.CycleTime)/60),0) As PlanMins,  
   --Sum(Datediff(minute,a.Starttime,a.Endtime)) As PlanMins,  
   IsNull(Round((Sum(a.AccQty*a.CycleTime)/60),0),0) As ProdMins,  
   IsNull(Round((Sum(a.ReasonQty*a.CycleTime)/60),0), 0) As ReasMins  
  From (  
   Select a.MachineCode, /*a.AssetCode,*/ a.StageCode, a.StartDate, a.ShiftCode, a.PlanQty, /* a.Starttime,a.Endtime, */   
    Convert(numeric(10,2), c.CycleTime) As CycleTime, a.BranchID, a.CompID, Sum(a.AccQty) As AccQty, Sum(a.ReasonQty) As ReasonQty  
   From @TmpTbl_PlanCriteriaReason a     
	 Left Outer Join BOM_ItemwiseMachinewiseCycleTime c
		On a.Stagecode=c.ItemCode and a.MachineCode=c.MachineCode and c.Status='1' 
			and a.BranchID=c.BranchID and a.CompID=c.CompID        
   Where a.SetSeq=2 and a.BranchID=@BranchID and a.CompID=@CompID --and a1.Finyear=@Finyear       
    Group By a.MachineCode, /*a.AssetCode,*/ a.StageCode, a.StartDate, a.ShiftCode, 
			a.PlanQty, /* a.Starttime, a.Endtime, */ c.CycleTime, a.BranchID, a.CompID  
  ) a  
  
  Left Outer Join dbo.fn_BOM_Material_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) f        
   On a.MachineCode=f.ItemCode and a.BranchID=f.BranchID and a.CompID=f.CompID     
  
  Group by a.MachineCode, /*a.AssetCode,*/ f.ItemDesc, a.StartDate, a.ShiftCode  
 ) j   
 Group by MachineCode, ItemDesc  
 Order by MachineCode    
END
GO

