CREATE PROCEDURE [dbo].[PPC_Rpt_DownTime_Gen_Reason](@ItemUserkey varchar(36)='', @ShiftUserkey varchar(36)='', 
	@RptCode Int, @FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                     
As              
BEGIN    
	SET NOCOUNT ON; 

	Declare @TmpTbl_PlanCriteriaReason As Table
	(
		MachineCode varchar(20), 
		AssetCode varchar(10),
		StageCode varchar(20), 
		StartDate datetime, 
		ShiftCode varchar(3), 
		PlanQty int, 
		Starttime datetime,  
		Endtime datetime,
		CriteriaCode int,
		CriteriaType varchar(1),
		AccQty float, 
		ReworkQty float,
		ScrapQty float,		
		--ReasonQty float, 		
		ReasonStartTime datetime, 
		ReasonEndTime datetime, 
		--ReasonType varchar(1), 
		--ReasonCode int,
		--ReasonShortName varchar(10),
		--Reason varchar(50),
		BranchID varchar(3), 
		CompID varchar(3), 
		Finyear varchar(20),
		SetSeq int
	)
	 
	Begin
		/* Insert Data Into Temp Table */
		Insert Into @TmpTbl_PlanCriteriaReason

		EXECUTE PPC_Rpt_DownTime_Get_PlanCriteria @ItemUserkey, @ShiftUserkey, 
		@RPTCode, @Fromdate, @Todate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear
  End
	--Select * From @TmpTbl_PlanCriteriaReason
	--Where SetSeq=1
	Begin
		/* Insert Data Into Temp Table */
		Insert Into @TmpTbl_PlanCriteriaReason

		Select Distinct a.MachineCode, a.AssetCode, a.StageCode, a.StartDate, a.ShiftCode, a.PlanQty, a.StartTime, 
			a.EndTime, 0 As CriteriaCode, '' As CriteriaType, /*a.CriteriaCode, a.CriteriaType,*/ a.AccQty, a.ReworkQty,	a.ScrapQty,
			null As ReasonStartTime, null As ReasonEndTime, a.BranchID, a.CompID, a.Finyear, 2 As SetSeq
		From (
			Select a1.MachineCode, a1.AssetCode, a1.StageCode, a1.StartDate, a1.ShiftCode, a1.PlanQty, a1.StartTime, 
				a1.EndTime, /*a1.CriteriaCode, a1.CriteriaType,*/ Sum(a1.AccQty) As AccQty, Sum(a1.ReworkQty) As ReworkQty, 
				Sum(a1.ScrapQty) As ScrapQty, a1.BranchID, a1.CompID, a1.Finyear, a1.SetSeq
		 From @TmpTbl_PlanCriteriaReason a1     
		 Left Outer Join BOM_ItemwiseMachinewiseCycleTime c1
			On a1.Stagecode=c1.ItemCode and a1.MachineCode=c1.MachineCode and c1.Status='1' 
				and a1.BranchID=c1.BranchID and a1.CompID=c1.CompID        
		 Where a1.SetSeq=1 and ((a1.CriteriaType='C' and a1.CriteriaCode In(1,3,4)) or (a1.CriteriaType In('R','LR') and a1.CriteriaCode=14))
					and (@ItemUserkey='' or (@ItemUserkey<>'' and Exists (Select * From COM_SelectList s2        
										Where s2.UserKey=@ItemUserkey and s2.SelectStr=a1.StageCode and s2.BranchID=@BranchID 
											and s2.CompID=@CompID
								))  
							)	 
			and a1.BranchID=@BranchID and a1.CompID=@CompID --and a1.Finyear=@Finyear       
			Group By a1.MachineCode, a1.AssetCode, a1.StageCode, a1.StartDate, a1.ShiftCode, a1.PlanQty, a1.StartTime, 
				a1.EndTime, /*a1.CriteriaCode, a1.CriteriaType,*/ a1.BranchID, a1.CompID, a1.Finyear, a1.SetSeq
		) a	
		Where a.SetSeq=1 and a.BranchID=@BranchID and a.CompID=@CompID --and a.Finyear=@Finyear 
	End
	--Select * From @TmpTbl_PlanCriteriaReason
	--Where SetSeq=2

	/* Output (Result) */
	Select Distinct a.MachineCode, IsNull(a.AssetCode,'') As AssetCode, IsNull(a.StageCode,'') As ItemCode, 
			a.StartDate, IsNull(a.ShiftCode,'') As ShiftCode,  IsNull(a.PlanQty,0) As PlanQty, a.StartTime, 
			a.EndTime, /* IsNull(a.CriteriaCode,0) As CriteriaCode, IsNull(a.CriteriaType,'') As CriteriaType,*/ 
			IsNull(a.AccQty,0) As AccQty, IsNull(a.ReworkQty,0) As ReworkQty, 
			IsNull(a.ScrapQty,0) As ScrapQty, 		
			Case When (a.StartDate Is Not Null) and (a.EndTime Is Not Null) Then
				(a.MachineCode+a.StageCode+a.ShiftCode+Convert(varchar(19), a.StartDate,121)+Convert(varchar(19), a.EndTime,121))
			Else
				(a.MachineCode+a.StageCode+a.ShiftCode) 
			End As LogData,
			a.BranchID, a.CompID, a.Finyear, 3 As SetSeq  
	From @TmpTbl_PlanCriteriaReason a    	 				
	Where a.SetSeq=2 --and (@ItemUserkey='' or (@ItemUserkey<>'' and Exists (Select * From COM_SelectList s2        
			--			Where s2.UserKey=@ItemUserkey and s2.SelectStr=a.StageCode and s2.BranchID=@BranchID and s2.CompID=@CompID
			--	))  
			--)
		--and IsNull(a.ReasonQty,0)>0    		
		and a.BranchID=@BranchID and a.CompID=@CompID --and a.Finyear=@Finyear 
	Order by  ShiftCode, a.MachineCode, AssetCode, ItemCode, a.StartDate, a.Starttime
END
GO

