CREATE PROCEDURE [dbo].[PPC_Rpt_DownTime_Gen_ReasonDtl](@ShiftCode varchar(3), @MachineCode varchar(20), @ItemCode varchar(20), 
	@Starttime datetime, @FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                     
As              
BEGIN    
	SET NOCOUNT ON; 

	/* Output (Result) */
	Select Distinct  a.ShiftCode, a.MachineCode,  a.ItemCode, a.Starttime, 
			a.CriteriaCode, IsNull(a.ReasonQty,0) As ReasonQty, a.ReasonStartTime, a.ReasonEndTime, 
			IsNull(a.ReasonType,'') As ReasonType, IsNull(a.ReasonCode,0) As ReasonCode, 
			IsNull(a.ReasonShortName,'') As ReasonShortName, IsNull(a.Reason,'') As Reason, 
			a.BranchID, a.CompID, a.Finyear, 1 As SetSeq
	From (
			Select a1.Shift As ShiftCode, a1.MachineCode, a1.ItemCode, a1.Starttime,
					a1.CriteriaCode, Sum(a1.Qty) As ReasonQty, a1.ReasonStartTime, 
					a1.ReasonEndTime, a1.Type As ReasonType, a1.CriteriaCode As ReasonCode, b2.ShortName As ReasonShortName, b2.Reason,
					a1.BranchID, a1.CompID, a1.Finyear
			From QC_Inspection_Criteria a1
			Left Outer Join Criteria_Reason b2
				On Right(a1.Type,1)=b2.Type and a1.CriteriaCode=b2.ReasonCode			
			Where a1.MachineCode=@MachineCode /*and a1.Assetcode=@Assetcode*/ and a1.ItemCode=@ItemCode
				and a1.Starttime=@Starttime and (a1.Type In('R','LR') and a1.CriteriaCode<>14)
				and a1.Shift=@ShiftCode			
				and Exists(Select * From PPC_Vw_QuickProductionplan_Dtl p1					
									Where (p1.StartTime>=@Fromdate and p1.EndTime<=@Todate) 
												and p1.DocNo=a1.RefNo and p1.DocDate=a1.RefDate and p1.DocType=a1.RefType and p1.Shift=a1.Shift       
												and p1.MachineCode=a1.MachineCode /*and p1.Assetcode=a1.Assetcode*/ and p1.StageCode=a1.ItemCode 
												and p1.Starttime=a1.Starttime and p1.BranchID=a1.BranchID and p1.CompID=a1.CompID and p1.Finyear=a1.Finyear
								)

				and a1.BranchID=@BranchID and a1.CompID=@CompID --and a1.Finyear=@Finyear
			Group by a1.Shift, a1.MachineCode,a1.ItemCode, a1.Starttime, 
					a1.CriteriaCode, a1.ReasonStartTime, a1.ReasonEndTime, a1.Type, 
					b2.ShortName, b2.Reason, a1.BranchID, a1.CompID, 
					a1.Finyear
			) a
	Where IsNull(a.ReasonQty,0)>0 and a.BranchID=@BranchID and a.CompID=@CompID --and a.Finyear=@Finyear
END
GO

/****** Object:  StoredProcedure [dbo].[PPC_Rpt_DownTime_Get_PlanCriteria]    Script Date: 17/06/2026 11:30:32 ******/
