CREATE PROCEDURE [dbo].[PPC_Rpt_DownTime_Get_PlanCriteria](@ItemUserkey varchar(36)='', @ShiftUserkey varchar(36)='', 
	@RPTCode Int, @Fromdate datetime, @Todate datetime, @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))              
As              
BEGIN    
	SET NOCOUNT ON; 

	/* Output (Result) */				
	Select Distinct a.MachineCode, '' As AssetCode, a.StageCode, a.StartDate, IsNull(a.Shift,'') As ShiftCode, 
			IsNull(a.Date1,0) As PlanQty, a.StartTime, a.EndTime, IsNull(b.CriteriaCode,0) As CriteriaCode, 
			IsNull(b.CriteriaType,'') As CriteriaType, IsNull(b.AccQty,0) As AccQty, IsNull(b.ReworkQty,0) As ReworkQty, 
			IsNull(b.ScrapQty,0) As ScrapQty, b.ReasonStartTime, b.ReasonEndTime,
			--IsNull(b.ReasonQty,0) As ReasonQty, b.ReasonStartTime, b.ReasonEndTime, 
			--IsNull(b.ReasonType,'') As ReasonType, IsNull(b.ReasonCode,0) As ReasonCode, 
			--IsNull(b.ReasonShortName,'') As ReasonShortName, IsNull(b.Reason,'') As Reason, 
			a.BranchID, a.CompID, a.Finyear, 1 As SetSeq  
	From PPC_Vw_QuickProductionplan_Dtl a    	 		
	Left Outer Join ( Select b1.RefType, b1.RefNo, b1.RefDate, b1.Shift, b1.MachineCode, /*b1.AssetCode,*/ b1.ItemCode, b1.Starttime, b1.CriteriaCode,
												b2.Type As CriteriaType,     
												Case When ((b1.Type='C' and b1.CriteriaCode=1) or (b1.Type In('R','LR') and b1.CriteriaCode=14)) Then b1.Qty Else 0 End As AccQty,
												Case When (b1.Type='C' and b1.CriteriaCode=3) Then b1.Qty Else 0 End As ReworkQty,
												Case When (b1.Type='C' and b1.CriteriaCode=4) Then b1.Qty Else 0 End As ScrapQty,
												b1.ReasonStartTime, b1.ReasonEndTime,
												--Case When (b1.Type In('R','LR') and b1.CriteriaCode<>14) Then b1.Qty Else 0 End As ReasonQty, 
												--b2.Type As ReasonType, b2.ReasonCode As ReasonCode, b2.ShortName As ReasonShortName, b2.Reason, 
												 b1.BranchID, b1.CompID, b1.Finyear   
										From QC_Inspection_Criteria b1
										Left Outer Join Criteria_Reason b2
											On Right(b1.Type,1)=b2.Type and b1.CriteriaCode=b2.ReasonCode
										Where b1.BranchID=@BranchID and b1.CompID=@CompID and b1.Finyear=@Finyear  										      
		) b      
	On a.DocNo=b.RefNo and a.DocDate=b.RefDate and a.DocType=b.RefType and a.Shift=b.Shift       
		and a.MachineCode=b.MachineCode /*and a.Assetcode=b.Assetcode*/ and a.Stagecode=b.ItemCode 
		and a.Starttime=b.Starttime and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear
	Where (a.StartTime>=@Fromdate and a.EndTime<=@Todate) 
		and (@ShiftUserkey='' or (@ShiftUserkey<>'' and Exists (Select * From COM_SelectList s1    
						Where s1.UserKey=@ShiftUserkey and s1.SelectStr=a.Shift and s1.BranchID=@BranchID and s1.CompID=@CompID
				))    
			)  
		--and (@ItemUserkey='' or (@ItemUserkey<>'' and Exists (Select * From COM_SelectList s2        
		--				Where s2.UserKey=@ItemUserkey and s2.SelectStr=a.StageCode and s2.BranchID=@BranchID and s2.CompID=@CompID
		--		))  
			--)    
		and a.OperationName<>'Setting' and a.[Priority]=1 /*and a.Shift<>'SH4'*/
		and a.BranchID=@BranchID and a.CompID=@CompID --and a.Finyear=@Finyear		 	   
END
GO

