/****** Object:  Stored Procedure dbo.PPC_Rpt_Incentive_Gen_Criteria    Script Date: 18/02/2010 2:01:13 PM ******/
CREATE PROCEDURE [dbo].[PPC_Rpt_Incentive_Gen_Criteria](@RptOption Char(1), @Shift varchar(3), @InsNo int, @InsDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))

As

SET NOCOUNT ON

 	Begin

		If @RptOption = 'R'
			Select distinct TobeEnterTime, a.Machinecode, a.AssetCode, a.Type, a.CriteriaCode, a.Qty, a.Starttime, 
			(Select max(ToBeEnterTime) Endtime FROM QC_Inspection_Criteria b Where b.InspectionType = a.InspectionType AND b.InspectionNo = a.InspectionNo
			AND b.InspectionDate = a.InspectionDate AND b.ItemCode = a.ItemCode and b.Branchid = a.Branchid and b.Compid = a.Compid) AS EndTime, 
			CASE WHEN c.OperationName = 'SETTING' THEN c.Operator ELSE '' END Ops,
			CASE WHEN c.OperationName <> 'SETTING' THEN c.Operator ELSE '' END Ops1, a.Shift 
			From QC_Inspection_Criteria a Left Outer Join PPC_QuickProductionplan_Dtl c 
			On c.Docno = a.Refno and c.DocDate = a.Refdate and c.Stagecode = a.Itemcode 
			and c.MachineCode = a.Machinecode and c.AssetCode = a.AssetCode and c.Branchid = a.Branchid and c.Compid = a.Compid 
			Where Inspectionno = @InsNo and a.InspectionDate =  @InsDate and c.Shift = @Shift
				and a.BranchId = @BranchID and a.CompId = @CompID and a.Shift = @Shift
		ELSE
			Select distinct TobeEnterTime, a.Machinecode, a.AssetCode, a.Type, a.CriteriaCode, a.Qty, a.Starttime, 
			(Select max(ToBeEnterTime) Endtime FROM QC_Inspection_Criteria b Where b.InspectionType = a.InspectionType AND b.InspectionNo = a.InspectionNo
			AND b.InspectionDate = a.InspectionDate AND b.ItemCode = a.ItemCode and b.Branchid = a.Branchid and b.Compid = a.Compid) AS EndTime, 
			CASE WHEN c.OperationName = 'SETTING' THEN c.Operator ELSE '' END Ops,
			CASE WHEN c.OperationName <> 'SETTING' THEN c.Operator ELSE '' END Ops1, a.Shift 
			From QC_Inspection_Criteria a Left Outer Join PPC_QuickProductionplan_Dtl c 
			On c.Docno = a.Refno and c.DocDate = a.Refdate and c.Stagecode = a.Itemcode 
			and c.MachineCode = a.Machinecode and c.AssetCode = a.AssetCode and c.Branchid = a.Branchid and c.Compid = a.Compid 
			Where Inspectionno = @InsNo and a.InspectionDate =  @InsDate 
				and a.BranchId = @BranchID and a.CompId = @CompID 
				
	End
GO

