CREATE PROCEDURE [dbo].[PPC_Rpt_Incentive_Gen_Inspection](@RptOption Char(1), @Shift varchar(3), @StageCode varchar(20), @MachineCode varchar(20), @AssetCode varchar(10), @InsDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))

As

SET NOCOUNT ON

 	Begin

		If @RptOption = 'R'
			Select distinct a.InspectionNo, a.InspectionDate From QC_Inspection_Criteria a
			Left Outer Join  PPC_QuickProductionplan_Dtl d 
			On a.ItemCode = d.StageCode and a.Machinecode = d.MachineCode and a.InspectionDate = d.StartDate and a.Branchid = d.Branchid and a.Compid = d.Compid
			Where a.InspectionType IN ('PIR','SIR','LOG') and a.Itemcode = @StageCode and a.Machinecode = @MachineCode and a.AssetCode = @AssetCode
			and a.Shift = @Shift and d.Shift = @Shift and a.InspectionDate = @InsDate and a.Branchid = @BranchID and a.CompId = @CompID
		Else
			Select distinct a.InspectionNo, a.InspectionDate From QC_Inspection_Criteria a
			Left Outer Join  PPC_QuickProductionplan_Dtl d 
			On a.ItemCode = d.StageCode and a.Machinecode = d.MachineCode and a.InspectionDate = d.StartDate and a.Branchid = d.Branchid and a.Compid = d.Compid
			Where a.InspectionType IN ('PIR','SIR','LOG') and a.Itemcode = @StageCode and a.Machinecode = @MachineCode and a.AssetCode = @AssetCode
			and a.InspectionDate = @InsDate and a.Branchid = @BranchID and a.CompId = @CompID		
	End
