			On a.StageCode = b.ItemCode and a.Branchid = b.Branchid and a.Compid = b.Compid   
			Left Outer Join dbo.fn_QC_Inspectiontype_Master('A',@AsOnDate,@RptDate,@BranchID,@CompID)c 
			On  a.BranchId = c.BranchId and a.CompId = c.CompId 
		 	 Where a.Shift = @Shift 
				and a.StartDate between @FromDate and @ToDate
				and a.Status <> 0 and c.InspectiontypelongName = 'PATROL INSPECTION' and a.Branchid = @BranchID
				and a.CompId = @CompID --and a.Operationname <> 'SETTING' 
				and b.EffDate=(Select Max(EffDate) From BOM_Material_Master Where ItemCode=b.ItemCode and BranchID=b.BranchID and CompID=b.CompID)

		Else
			Select distinct a.StartDate, a.StageCode, b.ItemDesc, a.MachineCode,  a.AssetCode,  a.Operationname,
				a.Date1, a.Shift,InspectionDuration 
			From PPC_QuickProductionplan_Dtl a 
			Left Outer Join dbo.fn_BOM_Material_Master('A',@AsOnDate,@RptDate, @BranchID,@CompID)b
			On a.StageCode = b.ItemCode and a.Branchid = b.Branchid and a.Compid = b.Compid   
