/****** Object:  StoredProcedure [dbo].[PPC_Rpt_LogDownTimeAnalysis_Fil_Shift]    Script Date: 17/06/2026 11:30:32 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Procedure [dbo].[PPC_Rpt_LogDownTimeAnalysis_Fil_Shift](@FromDate datetime, @ToDate datetime, @AsOnDate datetime,           
@RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                                          
                                           
AS                                            
                                          
 BEGIN                                            
                
 SET NOCOUNT ON          
         
  Declare @TmpFromDate As datetime          
  Declare @TmpStartDate As datetime          
  Declare @TmpEndDate As datetime        
  Declare @FDate As datetime        
  Declare @rCnt As int          
           
  Declare @TabShiftDate Table                          
  (             
   [DataID]   [int],                        
   [ShiftCode]  [varchar](3),                      
   [ShiftDescription] [varchar](30),               
   [StartTime]  [datetime],          
   [EndTime]   [datetime],          
   [ShiftMinutes]  [int],          
   [LunchStartTime] [datetime],          
   [LunchMinutes]  [int]                                
  )                      
                     
 Begin                    
  --Insert Shift Details  (1)          
  Begin        
   Insert into @TabShiftDate           
             
   Select 1 As DataID, a.ShiftCode, a.ShiftDescription, a.StartTime,           
   (Convert(varchar(10),a.StartTime,101)+' '+Convert(varchar(10),DateAdd(minute,a.ShiftMinutes,a.StartTime),108)) As EndTime,          
   a.ShiftMinutes, a.LunchStartTime, a.LunchMinutes           
   From PPC_Shift_Master a		--dbo.fn_PPC_Shift_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) a          
   Order by StartTime               
  End        
         
  Set @TmpFromDate=DateAdd(day,1, @FromDate) --DateForward          
            
  --Insert DateTime Details (2)          
  While @FromDate <= @ToDate         
   Begin           
   Set @rCnt=1        
 /*        
   --Test Part1        
   Select @rCnt As RowCnt, @FromDate As StartDate, @ToDate As EndDate        
 */        
   Declare @DataID As int          
   Declare @ShiftCode As varchar(3)          
   Declare @ShiftDescription varchar(30)               
   Declare @StartTime As datetime          
   Declare @EndTime As datetime          
   Declare @ShiftMinutes AS int          
   Declare @LunchStartTime As datetime          
   Declare @LunchMinutes As int          
         
   Declare curShiftDate Cursor For         
               
   Select * From @TabShiftDate a        
   Where DataID=1        
   Order by a.StartTime        
         
   OPEN curShiftDate           
   FETCH NEXT FROM curShiftDate into @DataID, @ShiftCode, @ShiftDescription, @StartTime, @EndTime, @ShiftMinutes, @LunchStartTime, @LunchMinutes            
         
   WHILE @@FETCH_STATUS = 0            
   Begin   
              
		 --If @rCnt=1        
		 -- Begin        
		Set @TmpStartDate=(Convert(varchar(10),@FromDate,101)+' '+Convert(varchar(10),@StartTime,108))        
		Set @FDate=(Convert(varchar(10),@FromDate,101)+' '+Convert(varchar(10),@StartTime,108))        
			--End        
         
		--Set @TmpEndDate=(Convert(varchar(10),@TmpStartDate,101)+' '+Convert(varchar(10),DateAdd(minute,@ShiftMinutes,@FDate),108))        
		Set @TmpEndDate=Convert(varchar(19),DateAdd(minute,@ShiftMinutes,@FDate),120)        
		Set @FDate=@TmpEndDate        
         
 /*        
   --Test Part2        
   Select @rCnt As RowCnt, @TmpStartDate As StartDate, @TmpEndDate As EndDate, @FDate As ForwordEndDate        
 */            
         
  If Convert(varchar(10),@TmpEndDate,101)>Convert(varchar(10),@TmpStartDate,101)        
   Begin        
		Insert into @TabShiftDate        
              
		Select 2 As DataID, @ShiftCode, @ShiftDescription,         
		(Convert(varchar(10),@FromDate,101)+' '+Convert(varchar(10),@StartTime,108)) As StartTime,         
		(Convert(varchar(10),@TmpEndDate,101)+' '+Convert(varchar(10),@EndTime,108)) As EndTime,        
		@ShiftMinutes, @LunchStartTime, @LunchMinutes      
   End        
  Else        
   Begin        
		Insert into @TabShiftDate        
         
		Select 2 As DataID, @ShiftCode, @ShiftDescription,         
		(Convert(varchar(10),@FromDate,101)+' '+Convert(varchar(10),@StartTime,108)) As StartTime,         
		(Convert(varchar(10),@TmpStartDate,101)+' '+Convert(varchar(10),@EndTime,108)) As EndTime,        
		@ShiftMinutes, @LunchStartTime, @LunchMinutes        
		End        
         
		Set @rCnt=@rCnt+1        
         
		FETCH NEXT FROM curShiftDate into @DataID, @ShiftCode, @ShiftDescription, @StartTime, @EndTime, @ShiftMinutes, @LunchStartTime, @LunchMinutes             
		End              
                
		Close curShiftDate            
		Deallocate curShiftDate         
         
		Set @FromDate=DateAdd(day,1, @FromDate) --DateForward          
   End          
         
		--Display Data        
		Begin        
		 Select * From @TabShiftDate a        
		 Where DataID=2 and EndTime <= @ToDate        
		 Order by a.StartTime        
		End        
      
  End        
 END 
GO

