CREATE PROCEDURE [dbo].[PPC_Rpt_LogEntryReport_AllSel](@OptionAll bit='0', @ItemUserKey varchar(36)='', @DocType varchar(3), 
	@FromDate datetime,  @ToDate datetime, @ModuleCode int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), 
	@CompID varchar(3), @Finyear Varchar(20))                        
As                        
BEGIN                      
	SET NOCOUNT ON; 

	If @OptionAll='1'
	 Begin
			Insert Into COM_SelectList

			Select Distinct @ItemUserKey, 0, a.ItemCode, @BranchID, @CompID, @AsOnDate
			From Qc_Inspection_Criteria a  
			Left Outer Join Criteria_Reason b 
				On b.Type=right(a.Type,1) and b.ReasonCode=a.CriteriaCode 
			Left Outer Join PPC_QuickProductionplan_Dtl c 
				On c.stagecode=a.itemcode and a.machinecode=c.machinecode and a.inspectiondate=c.startdate 
					and a.shift=c.shift 
			Where a.RefType=@DocType and (c.DocDate Between @FromDate and @ToDate)  
				and c.Revisionno=(Select Max(Revisionno) From PPC_QuickProductionplan_Dtl 
													Where DocType=c.DocType and DocNo=c.Docno and DocDate=c.DocDate and BranchID=c.BranchID 
																and CompID=c.CompID) 
					and c.Status<>0 and c.OperationName<>'SETTING' 
				and ((a.Type='C' and a.CriteriaCode=1) or (a.Type In('R','LR') and a.CriteriaCode=14))			--and a.Type='C'
				--and RefType='PWA' and Inspectiondate between convert(datetime,'2022-11-01',111)  and convert(datetime,'2022-11-29',111)  
				--and b.reason In('Accepted','HIGHER OUTPUT') 
				 and c.BranchID=@BranchID and c.CompID=@CompID and c.Finyear=@Finyear
		End
	Else
		Begin
			Select Distinct a.ItemCode 
			From Qc_Inspection_Criteria a  
			Left Outer Join Criteria_Reason b 
				On b.Type=right(a.Type,1) and b.ReasonCode=a.CriteriaCode 
			Left Outer Join PPC_QuickProductionplan_Dtl c 
				On c.stagecode=a.itemcode and a.machinecode=c.machinecode and a.inspectiondate=c.startdate 
					and a.shift=c.shift 
			Where a.RefType=@DocType and (c.DocDate Between @FromDate and @ToDate)  
				and c.Revisionno=(Select Max(Revisionno) From PPC_QuickProductionplan_Dtl 
													Where DocType=c.DocType and DocNo=c.Docno and DocDate=c.DocDate and BranchID=c.BranchID 
																and CompID=c.CompID) 
					and c.Status<>0 and c.OperationName<>'SETTING' 
				and ((a.Type='C' and a.CriteriaCode=1) or (a.Type In('R','LR') and a.CriteriaCode=14))			--and a.Type='C'
				--and RefType='PWA' and Inspectiondate between convert(datetime,'2022-11-01',111)  and convert(datetime,'2022-11-29',111)  
				--and b.reason In('Accepted','HIGHER OUTPUT') 
				 and c.BranchID=@BranchID and c.CompID=@CompID and c.Finyear=@Finyear

			Order by a.ItemCode
	 End
END
GO

/****** Object:  StoredProcedure [dbo].[PPC_Rpt_LogEntryReport_Gen]    Script Date: 17/06/2026 11:30:32 ******/
SET ANSI_NULLS ON
GO

