CREATE PROCEDURE [dbo].[PPC_Rpt_LogEntryReport_Gen](@DocType varchar(3), @DocNo int, @DocDate datetime,
	@OrderBy int, @ModuleCode int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), 
	@CompID varchar(3), @Finyear Varchar(20))                        
As                        
BEGIN                      
	SET NOCOUNT ON;

	If @OrderBy=2			/* 2 For MachineCode */ 
	 Begin     
		Select IsNull((Select Top 1 PartNo From Sal_Customer_Itemmaster p
									Where p.ItemCode=(Select Top 1 ItemCode from MPSMAster m1 
																	where m1.StageCode=x.StageCode and m1.BranchID=x.BranchID and m1.CompID=x.CompID) 
											and p.BranchID=x.BranchID and p.CompID=x.CompID),0) As PartNo, 
			x.StageCode, x.ItemDescription, x.MachineCode, x.Operator, x.Date1 As PlanQty,
			(Sum(x.Acc)+Sum(x.hihgerop)) As AccQty, Sum(x.Rej) As RejQty, Sum(x.Scr) As Scrap, Sum(x.Lun) As LunchBreak, 
			Sum(x.AllQty) As AllQty, Sum(x.POPut) As POPut, Sum(x.MQty) As MatQty 
		From (
				Select Distinct c.StageCode, d.ItemDescription, c.MachineCode, c.Operator, c.Date1, a.CriteriaCode, 
				Case When (a.Type='C' and a.CriteriaCode=1) or (a.Type in ('R','LR') and a.CriteriaCode=14) Then a.Qty Else '0' End As Acc, 
				Case When a.CriteriaCode=14 and a.Type='lr' Then a.Qty Else '0' End As Hihgerop,
				Case When a.Type in ('C') and a.CriteriaCode=3 Then a.Qty Else '0' End As Rej, 
				Case When a.Type in ('C') and a.CriteriaCode=4 Then a.Qty Else '0' End As Scr, 
				Case When a.Type in ('R','LR') and a.CriteriaCode in(4,5) Then a.Qty Else '0' End As MQty, 
				Case When a.CriteriaCode=13 Then a.Qty Else '0' End As POPut, 
				Case When a.CriteriaCode=16 Then a.Qty Else '0' End As Lun, 
				Case When a.CriteriaCode Not In(1,2,3,4,5,14,13,16) Then a.Qty Else '0' End As AllQty,
				c.BranchID, c.CompID 			 			
				From PPC_QuickProductionplan_Dtl c 
				Left Outer Join QC_Inspection_Criteria a  
					On c.DocType=a.RefType and c.Docno=a.Refno and c.DocDate=a.RefDate and c.StageCode=a.ItemCode 
						and c.MachineCode=a.MachineCode and c.Starttime=a.Starttime and c.BranchID=a.BranchID 
						and c.CompID=a.CompID 
				Left Outer Join INV_Material_Master d 
					On c.StageCode=d.ItemCode and c.BranchID=d.BranchID and c.CompID=d.CompID
				Where c.Docno=@Docno and DocDate=@DocDate and c.DocType=@DocType
					and c.Revisionno=(Select Max(r1.Revisionno) From PPC_QuickProductionplan_Dtl r1
													where r1.DocNo=c.DocNo and r1.DocDate=c.DocDate and r1.DocType=c.DocType
														and r1.BranchID=c.BranchID and r1.CompID=c.CompID) 
														and c.Status<>0 and c.OperationName<>'SETTING'  
		) x 		
		Group by x.StageCode, x.MachineCode, x.Operator, x.Date1, x.ItemDescription, x.BranchID, x.CompID 		
		Order by x.MachineCode, x.StageCode, x.Operator
	 End
	Else If @OrderBy=3			/* 3 For Operator */ 
	 Begin
		Select IsNull((Select Top 1 PartNo From Sal_Customer_Itemmaster p
									Where p.ItemCode=(Select Top 1 ItemCode from MPSMAster m1 
																	where m1.StageCode=x.StageCode and m1.BranchID=x.BranchID and m1.CompID=x.CompID) 
											and p.BranchID=x.BranchID and p.CompID=x.CompID),0) As PartNo, 
			x.StageCode, x.ItemDescription, x.MachineCode, x.Operator, x.Date1 As PlanQty,
			(Sum(x.Acc)+Sum(x.hihgerop)) As AccQty, Sum(x.Rej) As RejQty, Sum(x.Scr) As Scrap, Sum(x.Lun) As LunchBreak, 
			Sum(x.AllQty) As AllQty, Sum(x.POPut) As POPut, Sum(x.MQty) As MatQty 
		From (
				Select Distinct c.StageCode, d.ItemDescription, c.MachineCode, c.Operator, c.Date1, a.CriteriaCode, 
				Case When (a.Type='C' and a.CriteriaCode=1) or (a.Type in ('R','LR') and a.CriteriaCode=14) Then a.Qty Else '0' End As Acc, 
				Case When a.CriteriaCode=14 and a.Type='lr' Then a.Qty Else '0' End As Hihgerop,
				Case When a.Type in ('C') and a.CriteriaCode=3 Then a.Qty Else '0' End As Rej, 
				Case When a.Type in ('C') and a.CriteriaCode=4 Then a.Qty Else '0' End As Scr, 
				Case When a.Type in ('R','LR') and a.CriteriaCode in(4,5) Then a.Qty Else '0' End As MQty, 
				Case When a.CriteriaCode=13 Then a.Qty Else '0' End As POPut, 
				Case When a.CriteriaCode=16 Then a.Qty Else '0' End As Lun, 
				Case When a.CriteriaCode Not In(1,2,3,4,5,14,13,16) Then a.Qty Else '0' End As AllQty,
				c.BranchID, c.CompID 			 			
				From PPC_QuickProductionplan_Dtl c 
				Left Outer Join QC_Inspection_Criteria a  
					On c.DocType=a.RefType and c.Docno=a.Refno and c.DocDate=a.RefDate and c.StageCode=a.ItemCode 
						and c.MachineCode=a.MachineCode and c.Starttime=a.Starttime and c.BranchID=a.BranchID 
						and c.CompID=a.CompID 
				Left Outer Join INV_Material_Master d 
					On c.StageCode=d.ItemCode and c.BranchID=d.BranchID and c.CompID=d.CompID
				Where c.Docno=@Docno and DocDate=@DocDate and c.DocType=@DocType
					and c.Revisionno=(Select Max(r1.Revisionno) From PPC_QuickProductionplan_Dtl r1
													where r1.DocNo=c.DocNo and r1.DocDate=c.DocDate and r1.DocType=c.DocType
														and r1.BranchID=c.BranchID and r1.CompID=c.CompID) 
														and c.Status<>0 and c.OperationName<>'SETTING'  
		) x 		
		Group by x.StageCode, x.MachineCode, x.Operator, x.Date1, x.ItemDescription, x.BranchID, x.CompID   
		Order by x.Operator, x.StageCode, x.MachineCode
	 End
	Else 					/* 1 For ItemCode (StageCode) */
	 Begin
		Select IsNull((Select Top 1 PartNo From Sal_Customer_Itemmaster p
									Where p.ItemCode=(Select Top 1 ItemCode from MPSMAster m1 
																	where m1.StageCode=x.StageCode and m1.BranchID=x.BranchID and m1.CompID=x.CompID) 
											and p.BranchID=x.BranchID and p.CompID=x.CompID),0) As PartNo, 
			x.StageCode, x.ItemDescription, x.MachineCode, x.Operator, x.Date1 As PlanQty,
			(Sum(x.Acc)+Sum(x.hihgerop)) As AccQty, Sum(x.Rej) As RejQty, Sum(x.Scr) As Scrap, Sum(x.Lun) As LunchBreak, 
			Sum(x.AllQty) As AllQty, Sum(x.POPut) As POPut, Sum(x.MQty) As MatQty 
		From (
				Select Distinct c.StageCode, d.ItemDescription, c.MachineCode, c.Operator, c.Date1, a.CriteriaCode, 
				Case When (a.Type='C' and a.CriteriaCode=1) or (a.Type in ('R','LR') and a.CriteriaCode=14) Then a.Qty Else '0' End As Acc, 
				Case When a.CriteriaCode=14 and a.Type='lr' Then a.Qty Else '0' End As Hihgerop,
				Case When a.Type in ('C') and a.CriteriaCode=3 Then a.Qty Else '0' End As Rej, 
				Case When a.Type in ('C') and a.CriteriaCode=4 Then a.Qty Else '0' End As Scr, 
				Case When a.Type in ('R','LR') and a.CriteriaCode in(4,5) Then a.Qty Else '0' End As MQty, 
				Case When a.CriteriaCode=13 Then a.Qty Else '0' End As POPut, 
				Case When a.CriteriaCode=16 Then a.Qty Else '0' End As Lun, 
				Case When a.CriteriaCode Not In(1,2,3,4,5,14,13,16) Then a.Qty Else '0' End As AllQty,
				c.BranchID, c.CompID 			 			
				From PPC_QuickProductionplan_Dtl c 
				Left Outer Join QC_Inspection_Criteria a  
					On c.DocType=a.RefType and c.Docno=a.Refno and c.DocDate=a.RefDate and c.StageCode=a.ItemCode 
						and c.MachineCode=a.MachineCode and c.Starttime=a.Starttime and c.BranchID=a.BranchID 
						and c.CompID=a.CompID 
				Left Outer Join INV_Material_Master d 
					On c.StageCode=d.ItemCode and c.BranchID=d.BranchID and c.CompID=d.CompID
				Where c.Docno=@Docno and DocDate=@DocDate and c.DocType=@DocType
					and c.Revisionno=(Select Max(r1.Revisionno) From PPC_QuickProductionplan_Dtl r1
													where r1.DocNo=c.DocNo and r1.DocDate=c.DocDate and r1.DocType=c.DocType
														and r1.BranchID=c.BranchID and r1.CompID=c.CompID) 
														and c.Status<>0 and c.OperationName<>'SETTING'  
		) x 		
		Group by x.StageCode, x.MachineCode, x.Operator, x.Date1, x.ItemDescription, x.BranchID, x.CompID   
		Order by x.StageCode, x.MachineCode, x.Operator
	End
END
