CREATE PROCEDURE [dbo].[PPC_Rpt_LogEntryReport_Gen_Month](@ItemUserKey varchar(36)='', @DocType varchar(3), @FromDate datetime,  @ToDate datetime,  
	@OrderBy int, @ModuleCode int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))                        
As                        
BEGIN                      
	SET NOCOUNT ON;     

	If @OrderBy=2			/* 2 For InspectionDate */ 
	 Begin
		 Select Distinct IsNull((Select Top 1 PartNo From Sal_Customer_Itemmaster 
														Where ItemCode=(Select Top 1 ItemCode From MPSMAster 
																						Where StageCode=x.StageCode and BranchID=x.BranchID and CompID=x.CompID) 
																							and BranchID=x.BranchID and CompID=x.CompID),0) As Partno, 
				x.InspectionDate, x.StageCode, x.ITemDescription, x.MachineCode, x.Operator, x.Date1 As PlanQty, 
				Sum(x.qty) As Qty, x.shift, j.cycletime, j.settingtime, x.starttime 
		From (
					Select Distinct c.StageCode, d.ITemDescription, c.MachineCode, c.Operator, c.Date1, c.BranchID, c.CompID, 
							a.InspectionDate, a.qty, a.shift, a.type, a.criteriacode, a.tobeentertime, a.starttime 
					From PPC_QuickProductionplan_Dtl c 
					Left Outer Join QC_Inspection_Criteria a 
						On c.DocType=a.RefType and c.Docno=a.Refno and c.DocDate=a.refdate and c.StageCode=a.ItemCode 
							and c.MachineCode=a.MachineCode  and c.BranchID=a.BranchID And c.CompID=a.CompID 
					Left Outer Join INV_Material_Master d 
						On c.StageCode=d.ItemCode and c.BranchID=d.BranchID and c.CompID=d.CompID
					Where c.DocType=@DocType and (c.DocDate Between @FromDate and @ToDate)  
						and c.Revisionno=(Select Max(Revisionno) From PPC_QuickProductionplan_Dtl 
														Where DocType=c.DocType and DocNo=c.Docno and DocDate=c.DocDate and BranchID=c.BranchID 
																	and CompID=c.CompID) 
						and c.Status<>0 and c.OperationName<>'SETTING' 
						and ((a.Type='C' and a.CriteriaCode=1) or (a.Type In('R','LR') and a.CriteriaCode=14))			--and a.Type='C' 
						and (@ItemUserKey='' or (@ItemUserKey<>'' and Exists(Select * From COM_SelectList s1
														Where s1.UserKey=@ItemUserKey and s1.SelectStr=c.StageCode
															and s1.BranchID=@BranchID and s1.CompID=@CompID
								)))
						and  a.starttime=c.starttime and c.BranchID=@BranchID and c.CompID=@CompID		--and c.Finyear=@Finyear
		) x 
		Left Outer Join BOM_ItemwiseMachinewiseCycleTime j 
			On j.itemcode=x.stagecode and j.machinecode=x.machinecode 
		Group by j.cycletime,j.settingtime, x.inspectiondate, x.shift, x.StageCode, x.ITemDescription, 
			x.MachineCode, x.Operator,x.Date1, x.BranchID, x.CompID, x.starttime 
		Order by x.InspectionDate, x.StageCode
	 End
	Else If @OrderBy=3			/* 3 For Operator */ 
	 Begin
		Select Distinct IsNull((Select Top 1 PartNo From Sal_Customer_Itemmaster 
														Where ItemCode=(Select Top 1 ItemCode From MPSMAster 
																						Where StageCode=x.StageCode and BranchID=x.BranchID and CompID=x.CompID) 
																							and BranchID=x.BranchID and CompID=x.CompID),0) As Partno, 
				x.inspectiondate, x.StageCode, x.ITemDescription, x.MachineCode, x.Operator, x.Date1 As PlanQty, 
				Sum(x.qty) As Qty, x.shift, j.cycletime, j.settingtime, x.starttime 
		From (
					Select Distinct c.StageCode, d.ITemDescription, c.MachineCode, c.Operator, c.Date1, c.BranchID, c.CompID, 
							a.inspectiondate, a.qty, a.shift, a.type, a.criteriacode, a.tobeentertime, a.starttime 
					From PPC_QuickProductionplan_Dtl c 
					Left Outer Join QC_Inspection_Criteria a 
						On c.DocType=a.RefType and c.Docno=a.Refno and c.DocDate=a.refdate and c.StageCode=a.ItemCode 
							and c.MachineCode=a.MachineCode  and c.BranchID=a.BranchID And c.CompID=a.CompID 
					Left Outer Join INV_Material_Master d 
						On c.StageCode=d.ItemCode and c.BranchID=d.BranchID and c.CompID=d.CompID
					Where c.DocType=@DocType and (c.DocDate Between @FromDate and @ToDate)  
						and c.Revisionno=(Select Max(Revisionno) From PPC_QuickProductionplan_Dtl 
														Where DocType=c.DocType and DocNo=c.Docno and DocDate=c.DocDate and BranchID=c.BranchID 
																	and CompID=c.CompID) 
						and c.Status<>0 and c.OperationName<>'SETTING' 
						and ((a.Type='C' and a.CriteriaCode=1) or (a.Type In('R','LR') and a.CriteriaCode=14))			--and a.Type='C' 
						and (@ItemUserKey='' or (@ItemUserKey<>'' and Exists(Select * From COM_SelectList s1
														Where s1.UserKey=@ItemUserKey and s1.SelectStr=c.StageCode
															and s1.BranchID=@BranchID and s1.CompID=@CompID
								)))
						and  a.starttime=c.starttime and c.BranchID=@BranchID and c.CompID=@CompID		--and c.Finyear=@Finyear
		) x 
		Left Outer Join BOM_ItemwiseMachinewiseCycleTime j 
			On j.itemcode=x.stagecode and j.machinecode=x.machinecode 
		Group by j.cycletime,j.settingtime, x.inspectiondate, x.shift, x.StageCode, x.ITemDescription, 
			x.MachineCode, x.Operator,x.Date1, x.BranchID, x.CompID, x.starttime 
		Order by x.Operator, x.StageCode
	 End
	Else			/* 1 For ItemCode (StageCode) */
	 Begin
		Select Distinct IsNull((Select Top 1 PartNo From Sal_Customer_Itemmaster 
														Where ItemCode=(Select Top 1 ItemCode From MPSMAster 
																						Where StageCode=x.StageCode and BranchID=x.BranchID and CompID=x.CompID) 
																							and BranchID=x.BranchID and CompID=x.CompID),0) As Partno, 
				x.inspectiondate, x.StageCode, x.ITemDescription, x.MachineCode, x.Operator, x.Date1 As PlanQty, 
				Sum(x.qty) As Qty, x.shift, j.cycletime, j.settingtime, x.starttime 
		From (
					Select Distinct c.StageCode, d.ITemDescription, c.MachineCode, c.Operator, c.Date1, c.BranchID, c.CompID, 
							a.inspectiondate, a.qty, a.shift, a.type, a.criteriacode, a.tobeentertime, a.starttime 
					From PPC_QuickProductionplan_Dtl c 
					Left Outer Join QC_Inspection_Criteria a 
						On c.DocType=a.RefType and c.Docno=a.Refno and c.DocDate=a.refdate and c.StageCode=a.ItemCode 
							and c.MachineCode=a.MachineCode  and c.BranchID=a.BranchID And c.CompID=a.CompID 
					Left Outer Join INV_Material_Master d 
						On c.StageCode=d.ItemCode and c.BranchID=d.BranchID and c.CompID=d.CompID
					Where c.DocType=@DocType and (c.DocDate Between @FromDate and @ToDate)  
						and c.Revisionno=(Select Max(Revisionno) From PPC_QuickProductionplan_Dtl 
														Where DocType=c.DocType and DocNo=c.Docno and DocDate=c.DocDate and BranchID=c.BranchID 
																	and CompID=c.CompID) 
						and c.Status<>0 and c.OperationName<>'SETTING' 
						and ((a.Type='C' and a.CriteriaCode=1) or (a.Type In('R','LR') and a.CriteriaCode=14))			--and a.Type='C' 
						and (@ItemUserKey='' or (@ItemUserKey<>'' and Exists(Select * From COM_SelectList s1
														Where s1.UserKey=@ItemUserKey and s1.SelectStr=c.StageCode
															and s1.BranchID=@BranchID and s1.CompID=@CompID
								)))
						and  a.starttime=c.starttime and c.BranchID=@BranchID and c.CompID=@CompID		--and c.Finyear=@Finyear
		) x 
		Left Outer Join BOM_ItemwiseMachinewiseCycleTime j 
			On j.itemcode=x.stagecode and j.machinecode=x.machinecode 
		Group by j.cycletime,j.settingtime, x.inspectiondate, x.shift, x.StageCode, x.ITemDescription, 
			x.MachineCode, x.Operator,x.Date1, x.BranchID, x.CompID, x.starttime 
		Order by x.StageCode
	 End
END
GO

