CREATE PROCEDURE [dbo].[PPC_Rpt_LogEntryReport_Get_OperationCost](@MachineCode varchar(20), @Itemcode varchar(20), @BranchID varchar(3),   
 @CompID varchar(3))                          
As                          
BEGIN                        
 SET NOCOUNT ON; 
	
	
 Select Distinct a.OperationCost 
 From BOM_ItemwiseMachinewiseCycleTime a
 Where a.MachineCode=@MachineCode and a.Itemcode=@Itemcode
		and a.BranchID=@BranchID and a.CompID=@CompID 
END  
