CREATE PROCEDURE [dbo].[PPC_Rpt_LogEntryReport_Hlp_Document]( @ModuleCode int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), 
	@CompID varchar(3), @Finyear Varchar(20))                        
As                        
BEGIN                      
	SET NOCOUNT ON;

	Select Distinct a.DocType, a.DocNo, a.DocDate, a.StartDate, a.Shift 
	From PPC_QuickProductionplan_Dtl a  
	Where a.BranchID=@BranchID and a.CompID=@CompID and a.ShortClose=0 
	Order by a.DocDate Desc, a.DocNo Desc
END
GO

/****** Object:  StoredProcedure [dbo].[PPC_Rpt_LogEntrySummaryReport_Gen]    Script Date: 17/06/2026 11:30:32 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PPC_Rpt_LogEntrySummaryReport_Gen](@DocType varchar(3), @DocNo int, @DocDate datetime,
	@OrderBy int, @ModuleCode int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), 
	@CompID varchar(3), @Finyear Varchar(20))                        
As                        
BEGIN                      
	SET NOCOUNT ON;
	
	If @OrderBy=2			/* 2 For MachineCode */ 
	 Begin     
		Select IsNull((Select Top 1 PartNo From Sal_Customer_Itemmaster p
									Where p.ItemCode=(Select Top 1 ItemCode from MPSMAster m1 
																	where m1.StageCode=x.StageCode and m1.BranchID=x.BranchID and m1.CompID=x.CompID) 
											and p.BranchID=x.BranchID and p.CompID=x.CompID),0) As Partno, 
			x.StageCode, x.ItemDescription, x.MachineCode, x.Operator, x.Date1 As PlanQty, 
			(Sum(Acc)+Sum(hihgerop)) As AccQty, Sum(Rej) As RejQty,Sum(Scr) As Scrap, 
			((Sum(Acc)+Sum(hihgerop))/x.date1 *100) As pvsacc, Min(x.starttime) As starttime,
			Max(x.tobeentertime) As tobeentertime, Max(x.EndTime) As EndTime,
			j.cycletime, DateDiff(n,Min(x.starttime),Max(x.EndTime)) As Minutes, 
			((Sum(Acc)+Sum(hihgerop))/x.Date1) As Hours, x.BranchID, x.CompID  
		From (	
				Select Distinct c.StageCode, c.starttime, a.tobeentertime, c.EndTime, d.ItemDescription, c.MachineCode, 
					c.Operator, c.Date1, 
					Case When a.CriteriaCode=1 and a.Type='c' Then a.Qty Else '0' End As Acc, 
					Case When a.CriteriaCode=14 and a.Type='lr' Then a.Qty Else '0' End As Hihgerop,
					Case When a.CriteriaCode not in(1,14) Then a.Qty Else '0' End As Rej, 
					Case When a.CriteriaCode=4 and a.Type='c' Then a.Qty Else '0' End As Scr,
					c.BranchID, c.CompID 
				From PPC_QuickProductionplan_Dtl c 
				Left Outer Join QC_Inspection_Criteria a  
					On c.DocType=a.RefType and c.Docno=a.Refno and c.DocDate=a.RefDate and c.StageCode=a.ItemCode 
						and c.MachineCode=a.MachineCode and c.Starttime=a.Starttime and c.BranchID=a.BranchID 
						and c.CompID=a.CompID 
				Left Outer Join INV_Material_Master d 
					On c.StageCode=d.ItemCode and c.BranchID=d.BranchID and c.CompID=d.CompID 
				Where c.Docno=@Docno and DocDate=@DocDate and c.DocType=@DocType
					and c.Revisionno=(Select Max(r1.Revisionno) From PPC_QuickProductionplan_Dtl r1
													where r1.DocNo=c.DocNo and r1.DocDate=c.DocDate and r1.DocType=c.DocType
														and r1.BranchID=c.BranchID and r1.CompID=c.CompID) 
														and c.Status<>0 and c.OperationName<>'SETTING'  
		) x 
		Left Outer Join BOM_ItemwiseMachinewiseCycleTime j 
			On x.StageCode=j.ItemCode and x.MachineCode=j.MachineCode and x.BranchID=j.BranchID and x.CompID=j.CompID
		Group by j.cycletime, x.StageCode, x.MachineCode, x.Operator, x.Date1, x.ItemDescription, x.BranchID, x.CompID   		
		Order by x.MachineCode, x.StageCode, x.Operator
	 End
	Else If @OrderBy=3			/* 3 For Operator */ 
	 Begin
		Select IsNull((Select Top 1 PartNo From Sal_Customer_Itemmaster p
									Where p.ItemCode=(Select Top 1 ItemCode from MPSMAster m1 
																	where m1.StageCode=x.StageCode and m1.BranchID=x.BranchID and m1.CompID=x.CompID) 
											and p.BranchID=x.BranchID and p.CompID=x.CompID),0) As Partno, 
			x.StageCode, x.ItemDescription, x.MachineCode, x.Operator, x.Date1 As PlanQty, 
			(Sum(Acc)+Sum(hihgerop)) As AccQty, Sum(Rej) As RejQty,Sum(Scr) As Scrap, 
			((Sum(Acc)+Sum(hihgerop))/x.date1 *100) As pvsacc, Min(x.starttime) As starttime,
			Max(x.tobeentertime) As tobeentertime, Max(x.EndTime) As EndTime,
			j.cycletime, DateDiff(n,Min(x.starttime),Max(x.EndTime)) As Minutes, 
			((Sum(Acc)+Sum(hihgerop))/x.Date1) As Hours, x.BranchID, x.CompID  
		From (	
				Select Distinct c.StageCode, c.starttime, a.tobeentertime, c.EndTime, d.ItemDescription, c.MachineCode, 
					c.Operator, c.Date1, 
					Case When a.CriteriaCode=1 and a.Type='c' Then a.Qty Else '0' End As Acc, 
					Case When a.CriteriaCode=14 and a.Type='lr' Then a.Qty Else '0' End As Hihgerop,
					Case When a.CriteriaCode not in(1,14) Then a.Qty Else '0' End As Rej, 
					Case When a.CriteriaCode=4 and a.Type='c' Then a.Qty Else '0' End As Scr,
					c.BranchID, c.CompID 
				From PPC_QuickProductionplan_Dtl c 
				Left Outer Join QC_Inspection_Criteria a  
					On c.DocType=a.RefType and c.Docno=a.Refno and c.DocDate=a.RefDate and c.StageCode=a.ItemCode 
						and c.MachineCode=a.MachineCode and c.Starttime=a.Starttime and c.BranchID=a.BranchID 
						and c.CompID=a.CompID 
				Left Outer Join INV_Material_Master d 
					On c.StageCode=d.ItemCode and c.BranchID=d.BranchID and c.CompID=d.CompID 
				Where c.Docno=@Docno and DocDate=@DocDate and c.DocType=@DocType
					and c.Revisionno=(Select Max(r1.Revisionno) From PPC_QuickProductionplan_Dtl r1
													where r1.DocNo=c.DocNo and r1.DocDate=c.DocDate and r1.DocType=c.DocType
														and r1.BranchID=c.BranchID and r1.CompID=c.CompID) 
														and c.Status<>0 and c.OperationName<>'SETTING'  
		) x 
		Left Outer Join BOM_ItemwiseMachinewiseCycleTime j 
			On x.StageCode=j.ItemCode and x.MachineCode=j.MachineCode and x.BranchID=j.BranchID and x.CompID=j.CompID
		Group by j.cycletime, x.StageCode, x.MachineCode, x.Operator, x.Date1, x.ItemDescription, x.BranchID, x.CompID  
		Order by x.Operator, x.StageCode, x.MachineCode
	 End
	Else 					/* 1 For ItemCode (StageCode) */
	 Begin
		Select IsNull((Select Top 1 PartNo From Sal_Customer_Itemmaster p
									Where p.ItemCode=(Select Top 1 ItemCode from MPSMAster m1 
																	where m1.StageCode=x.StageCode and m1.BranchID=x.BranchID and m1.CompID=x.CompID) 
											and p.BranchID=x.BranchID and p.CompID=x.CompID),0) As Partno, 
			x.StageCode, x.ItemDescription, x.MachineCode, x.Operator, x.Date1 As PlanQty, 
			(Sum(Acc)+Sum(hihgerop)) As AccQty, Sum(Rej) As RejQty,Sum(Scr) As Scrap, 
			((Sum(Acc)+Sum(hihgerop))/x.date1 *100) As pvsacc, Min(x.starttime) As starttime,
			Max(x.tobeentertime) As tobeentertime, Max(x.EndTime) As EndTime,
			j.cycletime, DateDiff(n,Min(x.starttime),Max(x.EndTime)) As Minutes, 
			((Sum(Acc)+Sum(hihgerop))/x.Date1) As Hours, x.BranchID, x.CompID  
		From (	
				Select Distinct c.StageCode, c.starttime, a.tobeentertime, c.EndTime, d.ItemDescription, c.MachineCode, 
					c.Operator, c.Date1, 
					Case When a.CriteriaCode=1 and a.Type='c' Then a.Qty Else '0' End As Acc, 
					Case When a.CriteriaCode=14 and a.Type='lr' Then a.Qty Else '0' End As Hihgerop,
					Case When a.CriteriaCode not in(1,14) Then a.Qty Else '0' End As Rej, 
					Case When a.CriteriaCode=4 and a.Type='c' Then a.Qty Else '0' End As Scr,
					c.BranchID, c.CompID 
				From PPC_QuickProductionplan_Dtl c 
				Left Outer Join QC_Inspection_Criteria a  
					On c.DocType=a.RefType and c.Docno=a.Refno and c.DocDate=a.RefDate and c.StageCode=a.ItemCode 
						and c.MachineCode=a.MachineCode and c.Starttime=a.Starttime and c.BranchID=a.BranchID 
						and c.CompID=a.CompID 
				Left Outer Join INV_Material_Master d 
					On c.StageCode=d.ItemCode and c.BranchID=d.BranchID and c.CompID=d.CompID						
				Where c.Docno=@Docno and DocDate=@DocDate and c.DocType=@DocType
					and c.Revisionno=(Select Max(r1.Revisionno) From PPC_QuickProductionplan_Dtl r1
													where r1.DocNo=c.DocNo and r1.DocDate=c.DocDate and r1.DocType=c.DocType
														and r1.BranchID=c.BranchID and r1.CompID=c.CompID) 
														and c.Status<>0 and c.OperationName<>'SETTING'  
		) x 
		Left Outer Join BOM_ItemwiseMachinewiseCycleTime j 
			On x.StageCode=j.ItemCode and x.MachineCode=j.MachineCode and x.BranchID=j.BranchID and x.CompID=j.CompID
		Group by j.cycletime, x.StageCode, x.MachineCode, x.Operator, x.Date1, x.ItemDescription, x.BranchID, x.CompID  
		Order by x.StageCode, x.MachineCode, x.Operator
	End
END
GO

