CREATE PROCEDURE [dbo].[PPC_Rpt_LogEntrySummaryReport_Hlp_Document]( @ModuleCode int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), 
	@CompID varchar(3), @Finyear Varchar(20))                        
As                        
BEGIN                      
	SET NOCOUNT ON;

	Select Distinct a.DocType, a.DocNo, a.DocDate, a.StartDate, a.Shift 
	From PPC_QuickProductionplan_Dtl a  
