CREATE PROCEDURE [dbo].[PPC_Rpt_PatrolInspectionPPMReport_All_Item](@ItemUserKey varchar(36), @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))  
  
 AS  
  
 BEGIN  
  
 SET NOCOUNT ON  
  
 Insert into COM_SelectList  
  
 Select @ItemUserKey, 0, x.ItemCode, @BranchID, @CompID, @AsOnDate   
 From  
 (  
  
  Select Distinct IsNull(b.ItemCode,'') As ItemCode  
  From FAS_Party_Master a  
  Left Outer Join (Select Distinct b.CustomerCode, b.ItemCode, b.BranchID, b.CompID  
     From SAL_Customer_ItemMaster b       
     Where b.BranchID=@BranchID and b.CompID=@CompID  
    ) b  
     On a.PartyCode=b.CustomerCode and a.BranchID=b.BranchID and a.CompID=b.CompID  
  Where a.AcType In('D','Y') and a.EffStatus='1' and a.BranchID=@BranchID and a.CompID=@CompID  
	and IsNull(b.ItemCode,'') <>''
 ) x  
       
 END  
