/****** Object:  StoredProcedure [dbo].[PPC_Rpt_PatrolInspectionPPMReport_Gen_Item]    Script Date: 17/06/2026 11:30:33 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE  PROCEDURE  [dbo].[PPC_Rpt_PatrolInspectionPPMReport_Gen_Item](@ItemUserKey varchar(36), @CustCode int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))

 AS

 BEGIN

	SET NOCOUNT ON
		
		If @ItemUserKey = '-1' and @CustCode = 0		--Based On ItemCode (All)
		
			Begin

				Select Distinct a.ItemCode, a.StageCode, IsNull(b.ItemDescription,'') As ItemDescription,
					IsNull(c.PartNo,'') As PartNo
				From MpsMaster a
			   	Left Outer Join INV_Material_Master b
				   On a.ItemCode = b.ItemCode and a.BranchID = b.BranchID
					and a.CompID = b.CompID and b.Status = '1'
				Left Outer Join(Select Distinct c.PartNo, c.ItemCode, c.BranchID, c.CompID 
						From PartMast c
						Where c.BranchID=@BranchID and c.CompID=@CompID
					       ) c
				   On a.ItemCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID
				Where IsNull(a.StageCode,'')<>'' and a.Branchid=@BranchID and a.Compid=@CompID					
				Order by a.ItemCode
			End
					
		Else If @ItemUserKey <> '-1' and @CustCode = 0		--Based On ItemCode (Selective)

			Begin

				Select Distinct a.ItemCode, a.StageCode, IsNull(b.ItemDescription,'') As ItemDescription,
					IsNull(c.PartNo,'') As PartNo
				From MpsMaster a
			   	Left Outer Join INV_Material_Master b
				   On a.ItemCode = b.ItemCode and a.BranchID = b.BranchID
					and a.CompID = b.CompID and b.Status = '1'
				Left Outer Join(Select Distinct c.PartNo, c.ItemCode, c.BranchID, c.CompID 
						From PartMast c
						Where c.BranchID=@BranchID and c.CompID=@CompID
					       ) c
				   On a.ItemCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID
				Where a.Branchid=@BranchID and a.Compid=@CompID
					and a.ItemCode In(Select d.ItemCode From MpsMaster d 
							  Where d.BranchID=@BranchID and d.CompID=@CompID
								and d.StageCode In 
								(
									Select s1.SelectStr From COM_SelectList s1
									Where s1.UserKey = @ItemUserKey and s1.BranchID = @BranchID and s1.CompID = @CompID
								) 
							  )
					and IsNull(a.StageCode,'')<>'' 
				Order by a.ItemCode

			End

		Else	--Based On CustomerCode ( Help )

			Begin

				Select Distinct a.ItemCode, b.StageCode, IsNull(c.ItemDescription,'') As ItemDescription,
					IsNull(d.PartNo,'') As PartNo									
				From SAL_Customer_ItemMaster a
				Left Outer Join MpsMaster b 
				   On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
				Left Outer Join INV_Material_Master c
				   On a.ItemCode = c.ItemCode and a.BranchID = c.BranchID
					and a.CompID = c.CompID and c.Status = 1
				Left Outer Join(Select Distinct d.PartNo, d.ItemCode, d.BranchID, d.CompID 
						From PartMast d
						Where d.Branchid=@BranchID and d.Compid=@CompID
					       ) d
				   On a.ItemCode=d.ItemCode and a.Branchid=d.BranchID and a.Compid=d.CompID
				Where a.CustomerCode = @CustCode and a.Status = '1' and IsNull(b.StageCode,'')<>''
					and a.Branchid=@BranchID and a.Compid=@CompID
				Order by a.ItemCode
				
			End


							
 END

GO

/****** Object:  StoredProcedure [dbo].[PPC_Rpt_PatrolInspectionPPMReport_Gen_Paynter]    Script Date: 17/06/2026 11:30:33 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE  [dbo].[PPC_Rpt_PatrolInspectionPPMReport_Gen_Paynter](@PaynterItemUserKey varchar(36), @Type varchar(3), @FinalInsp bit, @FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))

 AS

 BEGIN

	SET NOCOUNT ON
	If @PaynterItemUserKey <> '-1' 

		Begin

		If @Type = 'PAT'	--Patrol Inspection
	
			Begin
	
				If @FinalInsp = '1'	--Patrol & Final Inspection 
				
					Begin
						
						Select a.DocDate, a.DocNo As CarNo, IsNull(c.RevisionNo,'') As RevisionNo, IsNull(c.Occurence,'') As Occurence,
							   IsNull(c.Detection,'') As Detection, IsNull(c.ReasonNo,'') As ReasonNo,
							   IsNull(c.Reason1,'') As Reason1,  IsNull(c.Reason2,'') As Reason2,
							   Month(a.DueDate) As mMonth
			   			From QC_Car_Hdr a
						Left Outer Join QC_CAR_Reason c
						   On a.DocType=c.DocType and a.DocNo=c.DocNo and a.RevisionNo=c.RevisionNo
							and a.RefType=c.RefType and a.RefNo=c.RefNo and a.BranchID=c.BranchID and a.CompID=c.CompID
						Where a.RefDate Between @FromDate and  @ToDate
							and a.ItemCode In 
									(
										Select s1.SelectStr From COM_SelectList s1
										Where s1.UserKey = @PaynterItemUserKey and s1.BranchID = @BranchID and s1.CompID = @CompID
									) 	  					  
							and a.RefType In('SIR','PIR','FIN')			  
							and a.RevisionNo=(Select Max(b.RevisionNo) As RevisionNo From QC_CAR_Hdr b 
									  Where a.DocType=b.DocType and a.DocNo=b.DocNo and a.DocDate=b.DocDate 
										and a.RefType=b.RefType and a.RefNo=b.RefNo and a.RefDate=b.RefDate 
										and a.ItemCode=b. ItemCode and a.MachineCode=b.MachineCode 
										and a.BranchID=b.BranchID and a.CompID=b.compID
						   			)
						   	and a.BranchID=@BranchID and a.CompID=@CompID				
						Order by a.DocDate, a.DocNo, c.ReasonNo
	
					End
	
				Else	--Patrol Inspection Only Without Final Inspection
	
					Begin
											Select a.DocDate, a.DocNo As CarNo, IsNull(c.RevisionNo,'') As RevisionNo, IsNull(c.Occurence,'') As Occurence,
							   IsNull(c.Detection,'') As Detection, IsNull(c.ReasonNo,'') As ReasonNo,
							   IsNull(c.Reason1,'') As Reason1,  IsNull(c.Reason2,'') As Reason2,
							   Month(a.DueDate) As mMonth
			   			From QC_Car_Hdr a
						Left Outer Join QC_CAR_Reason c
						   On a.DocType=c.DocType and a.DocNo=c.DocNo and a.RevisionNo=c.RevisionNo
							and a.RefType=c.RefType and a.RefNo=c.RefNo and a.BranchID=c.BranchID and a.CompID=c.CompID
						Where a.RefDate Between @FromDate and  @ToDate
							and a.ItemCode In 
									(
										Select s1.SelectStr From COM_SelectList s1
										Where s1.UserKey = @PaynterItemUserKey and s1.BranchID = @BranchID and s1.CompID = @CompID
									)
						     	and a.RefType In('SIR','PIR')						  
							and a.RevisionNo=(Select Max(b.RevisionNo) As RevisionNo From QC_CAR_Hdr b 
									  Where a.DocType=b.DocType and a.DocNo=b.DocNo and a.DocDate=b.DocDate 
										and a.RefType=b.RefType and a.RefNo=b.RefNo and a.RefDate=b.RefDate 
										and a.ItemCode=b. ItemCode and a.MachineCode=b.MachineCode 
										and a.BranchID=b.BranchID and a.CompID=b.compID
						   			)
						   	and a.BranchID=@BranchID and a.CompID=@CompID				
						Order by a.DocDate, a.DocNo, c.ReasonNo
	
					End		
			End
	
		Else If @Type = 'FIN'	--Final Inspection
	
			Begin
	
				Select a.DocDate, a.DocNo As CarNo, IsNull(c.RevisionNo,'') As RevisionNo, IsNull(c.Occurence,'') As Occurence,
					   IsNull(c.Detection,'') As Detection, IsNull(c.ReasonNo,'') As ReasonNo, IsNull(c.Reason1,'') As Reason1,
					   IsNull(c.Reason2,'') As Reason2, Month(a.DueDate) As mMonth			   
				From QC_Car_Hdr a
				Left Outer Join QC_CAR_Reason c
				   On a.DocType=c.DocType and a.DocNo=c.DocNo and a.Revisionno=c.Revisionno
				   	and a.RefType=c.RefType and a.RefNo=c.RefNo and a.BranchID=c.BranchID and a.CompID=c.CompID
				Where a.RefDate Between @FromDate and @ToDate
					and a.ItemCode In 
							(
								Select s1.SelectStr From COM_SelectList s1
								Where s1.UserKey = @PaynterItemUserKey and s1.BranchID = @BranchID and s1.CompID = @CompID
							)
					and a.RefType In('FIN')
					and a.RevisionNo=(Select Max(b.RevisionNo) As RevisionNo From QC_CAR_Hdr b 
							  Where a.DocType=b.DocType and a.DocNo=b.DocNo and a.DocDate=b.DocDate 
								and a.RefType=b.RefType and a.RefNo=b.RefNo and a.RefDate=b.RefDate 
								and a.ItemCode=b. ItemCode and a.MachineCode=b.MachineCode 
								and a.BranchID=b.BranchID and a.CompID=b.compID
				   			)
				   	and a.BranchID=@BranchID and a.CompID=@CompID
	  			Order by a.DocDate, a.DocNo, c.ReasonNo
	
			End
	
		Else 	--'INC' Incoming Inspection
	
			Begin
		
				Select a.DocDate, a.DocNo As CarNo, IsNull(c.RevisionNo,'') As RevisionNo, IsNull(c.Occurence,'') As Occurence,
					   IsNull(c.Detection,'') As Detection, IsNull(c.ReasonNo,'') As ReasonNo, IsNull(c.Reason1,'') As Reason1,
					   IsNull(c.Reason2,'') As Reason2, Month(a.DueDate) As mMonth			   
				From QC_Car_Hdr a
				Left Outer Join QC_CAR_Reason c
				   On a.DocType=c.DocType and a.DocNo=c.DocNo and a.Revisionno=c.Revisionno
				   	and a.RefType=c.RefType and a.RefNo=c.RefNo and a.BranchID=c.BranchID and a.CompID=c.CompID
				Where a.RefDate Between @FromDate and @ToDate
					and a.ItemCode In 
							(
								Select s1.SelectStr From COM_SelectList s1
								Where s1.UserKey = @PaynterItemUserKey and s1.BranchID = @BranchID and s1.CompID = @CompID
							)	
					and a.RefType In('RIR') 
					and a.RevisionNo=(Select Max(b.RevisionNo) As RevisionNo From QC_CAR_Hdr b 
							  Where a.DocType=b.DocType and a.DocNo=b.DocNo and a.DocDate=b.DocDate 
								and a.RefType=b.RefType and a.RefNo=b.RefNo and a.RefDate=b.RefDate 
								and a.ItemCode=b. ItemCode and a.MachineCode=b.MachineCode 
								and a.BranchID=b.BranchID and a.CompID=b.compID
				   			)
				   	and a.BranchID=@BranchID and a.CompID=@CompID
				   Order by a.DocDate, a.DocNo, c.ReasonNo
			End
	End

 END
GO

/****** Object:  StoredProcedure [dbo].[PPC_Rpt_PatrolInspectionPPMReport_Gen_PPMValue]    Script Date: 17/06/2026 11:30:33 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE  PROCEDURE  [dbo].[PPC_Rpt_PatrolInspectionPPMReport_Gen_PPMValue](@Type varchar(3), @FinalInsp bit, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))

 AS

 BEGIN

	SET NOCOUNT ON

	If @Type = 'PAT'	--Patrol Inspection
	
		Begin
			If @FinalInsp = '1'	--Patrol & Final Inspection 
		
				Begin
					Select a.PPMValue From QC_InspectionType_Master a
					Where a.InspectionTypeCode In(15,3) and a.BranchID=@BranchID and a.CompID=@CompID
				End
		
			Else	--Patrol Inspection Only Without Final Inspection
				Begin
					Select a.PPMValue From QC_InspectionType_Master a
					Where a.InspectionTypeCode=15 and a.BranchID=@BranchID and a.CompID=@CompID
				End
		End

	Else If @Type = 'FIN'	--Final Inspection

		Begin
			Select a.PPMValue From QC_InspectionType_Master a
			Where a.InspectionTypeCode=3 and a.BranchID=@BranchID and a.CompID=@CompID

		End

	Else 	--'INC' Incoming Inspection

		Begin
			Select a.PPMValue From QC_InspectionType_Master a
			Where a.InspectionTypeCode=12 and a.BranchID=@BranchID and a.CompID=@CompID
		End

 END
GO

/****** Object:  StoredProcedure [dbo].[PPC_Rpt_PatrolInspectionPPMReport_Gen_Quantity]    Script Date: 17/06/2026 11:30:33 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE  PROCEDURE  [dbo].[PPC_Rpt_PatrolInspectionPPMReport_Gen_Quantity](@Type varchar(3), @FinalInsp bit, @StageCode varchar(20), @FromDate datetime, @Todate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))

 AS

 BEGIN

	SET NOCOUNT ON

	If @Type='PAT'	--Patrol Inspection

		Begin

			If @FinalInsp='1'	--Final Inspection
				Begin
					Select y.ItemCode, y.InspectionDate, Sum(y.AccQty) As AccQty, Sum(y.Rewqty) As Rewqty,
					Sum(y.ScrQty) As ScrQty, Sum(y.HopQty) As HopQty
					From (Select x.ItemCode, x.InspectionDate, Sum(x.AccQty1) As AccQty, Sum(x.RewQty1) As RewQty,
					Sum(x.ScrQty1) As ScrQty, Sum(x.HopQty1) As HopQty
					From (Select ItemCode, InspectionDate,
					Case When Type='C' and CriteriaCode='1' Then Qty Else 0 End As AccQty1,
					Case When Type='C' and CriteriaCode='2' Then Qty Else 0 End As RejQty1,
					Case When Type='C' and CriteriaCode='3' Then Qty Else 0 End As RewQty1,
					Case When Type='C' and CriteriaCode='4' Then Qty Else 0 End As ScrQty1,
					Case When Type='R' and CriteriaCode='14' Then Qty Else 0 End As HopQty1
					From QC_Inspection_Criteria a
					Where InspectionType In('SIR','PIR') and InspectionDate between @FromDate and @Todate
					and ItemCode=@StageCode and BranchID=@BranchID and CompID=@CompID
					) x
					Group by x.ItemCode, x.InspectionDate	
					Union All
					Select x.ItemCode, x.InspectionDate, Sum(AccQty2) As AccQty, Sum(RewQty2) As RewQty,
					Sum(ScrQty2) As ScrQty, Sum(x.HopQty2) As HopQty
					From (Select b.ItemCode,a.InspectionDate,
					Case When a.CriteriaCode='1' Then Qty Else 0 End As AccQty2,
					Case When a.CriteriaCode='2' Then Qty Else 0 End As RejQty2,
					Case When a.CriteriaCode='3' Then Qty Else 0 End As RewQty2,
					Case When a.CriteriaCode='4' Then Qty Else 0 End As ScrQty2,
					Case When a.CriteriaCode='14' Then Qty Else 0 End As HopQty2
					From QC_Inspection_Criteria1 a
					Left Outer Join QC_Inspection_Hdr1 b On a.InspectionType=b.InspectionType
					and a.InspectionNo=b.InspectionNo and a.InspectionDate=b.InspectionDate
					and a.BranchID=b.BranchID and a.CompID=b.CompID
					Where a.InspectionType='FIN' and a.InspectionDate between @FromDate and @Todate
					and b.ItemCode=@StageCode and a.BranchID=@BranchID and a.CompID=@CompID
					) x
					Group by x.ItemCode, x.InspectionDate
					) y
					Group by y.ItemCode, y.InspectionDate
					Order by y.ItemCode, y.InspectionDate
				End
		
			Else	--Without Final Inspection
		
				Begin
					Select x.ItemCode, x.InspectionDate, Sum(x.AccQty1) As AccQty, Sum(x.RewQty1) As RewQty,
						Sum(x.ScrQty1) As ScrQty, Sum(x.HopQty1) As HopQty
					From (Select ItemCode, InspectionDate,
							Case When Type='C' and CriteriaCode='1' Then Qty Else 0 End As AccQty1,
							Case When Type='C' and CriteriaCode='2' Then Qty Else 0 End As RejQty1,
							Case When Type='C' and CriteriaCode='3' Then Qty Else 0 End As RewQty1,
							Case When Type='C' and CriteriaCode='4' Then Qty Else 0 End As ScrQty1,
							Case When Type='R' and CriteriaCode='14' Then Qty Else 0 End As HopQty1
						From QC_Inspection_Criteria a
						Where InspectionType In('SIR','PIR') and InspectionDate between @FromDate and @Todate
							and ItemCode=@StageCode and BranchID=@BranchID and CompID=@CompID
					) x
					Group by x.ItemCode, x.InspectionDate
					Order by x.ItemCode, x.InspectionDate
				End
		End

	Else If @Type = 'FIN'	--Final Inspection

		Begin
			Select x.ItemCode, x.InspectionDate, Sum(AccQty2) As AccQty,
			Sum(RewQty2) As RewQty, Sum(ScrQty2) As ScrQty,
			Sum(x.HopQty2) As HopQty
			From (	Select b.ItemCode,a.InspectionDate,
				Case When a.CriteriaCode='1' Then Qty Else 0 End As AccQty2,
				Case When a.CriteriaCode='2' Then Qty Else 0 End As RejQty2,
				Case When a.CriteriaCode='3' Then Qty Else 0 End As RewQty2,
				Case When a.CriteriaCode='4' Then Qty Else 0 End As ScrQty2,
				Case When a.CriteriaCode='14' Then Qty Else 0 End As HopQty2
				From QC_Inspection_Criteria1 a
				Left Outer Join QC_Inspection_Hdr1 b On a.InspectionType=b.InspectionType
				and a.InspectionNo=b.InspectionNo and a.InspectionDate=b.InspectionDate
				and a.BranchID=b.BranchID and a.CompID=b.CompID
				Where a.InspectionType='FIN'
				and a.InspectionDate Between @FromDate and @ToDate
				and b.ItemCode=@StageCode and a.BranchID=@BranchID and a.CompID=@CompID
			) x
			Group by x.ItemCode, x.InspectionDate
		End

	Else --'INC' Incoming Inspection

		Begin

			Select x.ItemCode, x.InspectionDate, Sum(AccQty2) As AccQty, Sum(RewQty2) As RewQty,
				Sum(ScrQty2) As ScrQty, Sum(x.HopQty2) As HopQty 
			From (	Select b.ItemCode,a.InspectionDate,
					Case When a.CriteriaCode='1' Then Qty Else 0 End As AccQty2,
					Case When a.CriteriaCode='2' Then Qty Else 0 End As RejQty2,
					Case When a.CriteriaCode='3' Then Qty Else 0 End As RewQty2,
					Case When a.CriteriaCode='4' Then Qty Else 0 End As ScrQty2,
					Case When a.CriteriaCode='14' Then Qty Else 0 End As HopQty2
				From QC_Inspection_Criteria1 a
			Left Outer Join QC_Inspection_Hdr1 b 
			On a.InspectionType=b.InspectionType and a.InspectionNo=b.InspectionNo 
				and a.InspectionDate=b.InspectionDate and a.BranchID=b.BranchID and a.CompID=b.CompID
			Where a.InspectionType='RIR' and a.InspectionDate Between @FromDate and @ToDate
				and b.ItemCode=@StageCode and a.BranchID=@BranchID and a.CompID=@CompID
			) x Group by x.ItemCode, x.InspectionDate
			Order by x.ItemCode, x.InspectionDate

		End
				
 END
GO

/****** Object:  StoredProcedure [dbo].[PPC_Rpt_PatrolInspectionPPMReport_Gen_Reason]    Script Date: 17/06/2026 11:30:33 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PPC_Rpt_PatrolInspectionPPMReport_Gen_Reason](@Type varchar(3), @FinalInsp bit, @FromDate datetime, @ToDate datetime, @ItemCode varchar(20), @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))  
  
 AS  
  
 BEGIN  
  
 SET NOCOUNT ON  

	If @Type = 'PAT'	--Patrol Inspection
  
		If @FinalInsp = '1'	--Patrol Inspection & Final Inspection
	
			Begin
				Select Distinct x.* 
				From (	Select Distinct p.InspectionDate, p.ItemCode, IsNull(p.ItemDescription,'') As ItemDescription,
						p.Defect_Reason, Reason
					From (
						Select Distinct a.InspectionDate, a.ItemCode, c.ItemDescription,
							IsNull(d.Parameter+' - '+d.DefectReading,'') As Defect_Reason,
							Case When Type In('R','LR') Then
							IsNull((Select b.Reason From PPC_Reason_Master b
								Where a.CriteriaCode=b.ReasonCode and a.BranchID=b.BranchID
									and a.CompID=b.CompID),'') Else
							IsNull((Select b.CriteriaDescription From QC_Criteria_Master b
								Where a.CriteriaCode=b.CriteriaCode and b.Category='R'
								),'') End As Reason
						From QC_Inspection_Criteria a
						Left Outer Join INV_Material_Master c
						   On c.ItemCode=a.ItemCode and c.BranchID=a.BranchID and c.CompID=a.CompID and c.status = 1
						Left Outer Join QC_Inspection_Defectcount d
						   On a.inspectionType=d.InspectionType and a.InspectionNo=d.InspectionNo
							and a.InspectionDate=d.InspectionDate and a.ItemCode=d.ItemCode
							and a.BranchID=d.BranchID and a.CompID=d.CompID
						  
						Where a.InspectionType In('SIR','PIR') and a.InspectionDate Between @FromDate and @Todate
						and a.ItemCode=@ItemCode and a.BranchID=@BranchID and a.CompID=@CompID
					) p
					Where p.Defect_Reason<>''
			
					UNION ALL
			
					Select Distinct a.InspectionDate, a.ItemCode, d.ItemDescription,
						IsNull(e.Parameter+' - '+e.DefectReading,'') As Defect_Reason,
						IsNull(c.CriteriaDescription,'') As Reason
					From QC_Inspection_Hdr1 a
					Left Outer Join QC_Inspection_Criteria1 b
					  On a.InspectionNo=b.InspectionNo and a.InspectionDate=b.InspectionDate 
						and a.BranchID=b.BranchID and a.CompID=b.CompID
					Left Outer Join QC_Criteria_Master c
					  On b.CriteriaCode=c.CriteriaCode and c.Category='R'
					Left Outer Join INV_MATERIAL_MASTER d
					  On d.ItemCode=a.ItemCode and d.BranchID=a.BranchID and d.CompID=a.CompID
					Left Outer Join QC_Inspection_Defectcount1 e
					  On a.inspectionType=e.InspectionType and a.InspectionNo=e.InspectionNo
						and a.InspectionDate=e.InspectionDate and a.ItemCode=e.ItemCode
						and a.BranchID=e.BranchID and a.CompID=e.CompID
					Where a.InspectionType='FIN' and a.InspectionDate Between @FromDate and @Todate
						and a.ItemCode=@ItemCode and a.BranchID=@BranchID and a.CompID=@CompID
				) x
				Where x.Defect_Reason<>''
				Order by x.InspectionDate
			End
	
		Else 	--Patrol Inspection Only
	
			Begin
				Select Distinct p.InspectionDate, p.ItemCode, IsNull(p.ItemDescription,'') As ItemDescription,
					p.Defect_Reason, Reason
				From (
					Select Distinct a.InspectionDate, a.ItemCode, c.ItemDescription,
					IsNull(d.Parameter+' - '+d.DefectReading,'') As Defect_Reason,
					Case When Type in('R','LR') Then
					IsNull((Select b.Reason From PPC_Reason_Master b
						Where a.CriteriaCode=b.ReasonCode and a.BranchID=b.BranchID
							and a.CompID=b.CompID),'') Else
					IsNull((Select b.CriteriaDescription From QC_Criteria_Master b
						Where a.CriteriaCode=b.CriteriaCode and b.Category='R'),'') End As Reason
					From QC_Inspection_Criteria a
					Left Outer Join INV_Material_Master c
					  On c.ItemCode=a.ItemCode and c.BranchID=a.BranchID and c.CompID=a.CompID and c.status = 1
					Left Outer Join QC_Inspection_Defectcount d
					  On a.inspectionType=d.InspectionType and a.InspectionNo=d.InspectionNo
						and a.InspectionDate=d.InspectionDate and a.ItemCode=d.ItemCode
						and a.BranchID=d.BranchID and a.CompID=d.CompID		  
					Where a.InspectionType In('SIR','PIR') and a.InspectionDate Between @FromDate and @Todate
						and a.ItemCode=@ItemCode and a.BranchID=@BranchID and a.CompID=@CompID
				) p
				Where p.Defect_Reason<>''
				Order by p.InspectionDate
			End

	Else If @Type = 'FIN'	--Final Inspection

		Begin

			Select Distinct a.InspectionDate, a.ItemCode, d.ItemDescription,
				IsNull(e.Parameter+' - '+e.DefectReading,'') As Defect_Reason,
			  	IsNull(c.CriteriaDescription,'') As Reason
			From QC_Inspection_Hdr1 a
			  Left Outer Join QC_Inspection_Criteria1 b
			     On a.InspectionNo=b.InspectionNo
			  and a.InspectionDate=b.InspectionDate and a.BranchID=b.BranchID and a.CompID=b.CompID
			  Left Outer Join QC_Criteria_Master c
			     On b.CriteriaCode=c.CriteriaCode and c.Category='R'
			  Left Outer Join INV_MATERIAL_MASTER d
			     On d.ItemCode=a.ItemCode and d.BranchID=a.BranchID and d.CompID=a.CompID
			  Left Outer Join QC_Inspection_Defectcount1 e
			    On a.inspectionType=e.InspectionType and a.InspectionNo=e.InspectionNo
			  	and a.InspectionDate=e.InspectionDate and a.ItemCode=e.ItemCode
			  	and a.BranchID=e.BranchID and a.CompID=e.CompID
			Where a.InspectionType='FIN' and a.InspectionDate Between @FromDate and @Todate and a.ItemCode=@ItemCode 
				and IsNull(e.Parameter+' - '+e.DefectReading,'')<>'' and IsNull(c.CriteriaDescription,'')<>''
				and a.BranchID=@BranchID and a.CompID=@CompID
			Order by a.InspectionDate

		End

	If @Type = 'INC'	--Incoming Inspection

		Begin
			
			Select Distinct x.* 
			From (	Select Distinct a.InspectionDate, a.ItemCode, IsNull(c.ItemDescription,'') As ItemDescription,
			   	Case When Type='R' Then 
					IsNull((Select b.Reason From PPC_Reason_Master b 
						Where a.CriteriaCode=b.ReasonCode and a.BranchID=b.BranchID and a.CompID=b.CompID),'')
			   	Else Case When Type='LR' Then
			   		IsNull((Select b.Reason From PPC_Reason_Master b 
						Where a.CriteriaCode=b.ReasonCode and a.BranchID=b.BranchID and a.CompID=b.CompID),'')
			   	Else Case When Type='C' Then
			   		IsNull((Select b.CriteriaDescription From QC_Criteria_Master b
			  			Where a.CriteriaCode=b.CriteriaCode and Category='R'),'')
			   	Else '' End End End As Reason
				From QC_Inspection_Criteria a
			   	Left Outer Join INV_MATERIAL_MASTER c
			   	   On c.ItemCode=a.ItemCode and c.BranchID=a.BranchID and c.CompID=a.CompID and c.status = 1
			   	Where a.InspectionType In('SIR','PIR') and a.InspectionDate Between @FromDate and @Todate 
					and a.ItemCode=@ItemCode and a.BranchID=@BranchID and a.CompID=@CompID
			
				UNION ALL
			
			     	Select Distinct a.InspectionDate, a.ItemCode, d.ItemDescription,
			     		IsNull(c.CriteriaDescription,'') As Reason
			     	From QC_Inspection_Hdr1 a
				Left Outer Join QC_Inspection_Criteria1 b
				   On a.InspectionNo=b.InspectionNo and a.InspectionDate=b.InspectionDate and a.BranchID=b.BranchID and a.CompID=b.CompID
				Left Outer Join QC_Criteria_Master c
				   On b.CriteriaCode=c.CriteriaCode and c.Category='R'
				Left Outer Join INV_MATERIAL_MASTER d
				   On d.ItemCode=a.ItemCode and d.BranchID=a.BranchID and d.CompID=a.CompID
			     	Where a.InspectionType='FIN' and a.InspectionDate Between @FromDate and @Todate 
					and a.ItemCode=@ItemCode and a.BranchID=@BranchID and a.CompID=@CompID			     
			) x
			Where x.Reason<>''
			Order by x.InspectionDate

		End

 END  
GO

