/****** Object:  StoredProcedure [dbo].[PPC_WorkAllocationMachine_Fil_ModifyItem]    Script Date: 17/06/2026 11:30:33 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PPC_WorkAllocationMachine_Fil_ModifyItem](@DocType varchar(3), @DocNo int, @DocDate datetime,
	@ShiftCode varchar(20), @PlanType varchar(25), @RevNo int, @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))
AS                  
BEGIN  
	SET NOCOUNT ON; 
	DECLARE @Tmp_PlanType varchar(1);
	SET @Tmp_PlanType=Left(Upper(@PlanType),1);

	Select Distinct IsNull((Select Top 1 P1.PartNo From PartMast P1
					Where P1.ItemCode=(Select Top 1 mp1.ItemCode From MPSMAster mp1
							Where mp1.StageCode=a.StageCode)),'') as PartNo,
		 a.WOrkOrderType, a.WOrkOrderNo, a.WOrkOrderDate, 
		 a.StageCode, a.OperationName, IsNull(a.CurStock,0) as CurStock, a.MachineCode, 
		 IsNull(a.BalOrderQty,0) as Qty, IsNull(a.Date1,0) as Date1, IsNull(a.BalanceQty,0) as BalanceQty, 
		 IsNull(a.Operator,'') as Operator, a.[Status], IsNull(a.Reason,'') as Reason,
		 a.RevisionNo, IsNull(a.InChargeName,'') as InChargeName, a.[Priority], 
		 IsNull(b.CyCleTime,0) As CyCleTime, a.StartTime, a.EndTime 
	 From PPC_QuickProductionplan_Dtl a 
	 Left Outer Join BOM_ItemwiseMachinewiseCycleTime b
		On a.MachineCode=b.MachineCode and a.StageCode=b.ItemCode and a.BranchID=b.BranchID 
		 and a.CompID=b.CompID
	 Where a.DocDate=@DocDate and a.DOCNo=@DOCNo and a.DocType=@DocType  
		and a.RevisionNo=@RevNo and a.BranchID=@BranchID and a.CompID=@CompID 
	 Order by a.MachineCode, a.[Priority]
END
