CREATE PROCEDURE [dbo].[PPC_WorkAllocationMachine_Get_MaxDocument](@ShiftDate datetime, @ShiftCode varchar(20), @PlanType varchar(25),   
 @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  
AS                    
BEGIN    
 SET NOCOUNT ON;  
   
 DECLARE @MaxDocDate as int;  
 DECLARE @MaxDocNo as int;  
 DECLARE @MaxRevNo as int;  
  
 DECLARE @Tmp_PlanType varchar(1);  
 SET @Tmp_PlanType=Left(Upper(@PlanType),1);  
  
 /* Get Max DocNo */  
 Select @MaxDocNo=Max(a.DocNo)  
 From PPC_QuickProductionplan_Dtl a  
 Where /* Month(a.StartDate)=Month(@ShiftDate) and */ a.[Shift]=@ShiftCode and a.PlanType=@Tmp_PlanType 	
	and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear  
  
 /* Get Max RevisionNo */  
 Select @MaxRevNo=Max(a.RevisionNo)  
 From PPC_QuickProductionplan_Dtl a  
 Where a.DocNo=@MaxDocNo and a.[Shift]=@ShiftCode and a.PlanType=@Tmp_PlanType  
  and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear  
  
 /* Output */  
 Select Distinct a.DocType, a.DocNo, a.Docdate, a.RevisionNo, a.[Shift], a.StartDate,  
  a.NoofDay, a.PlanType  
 From PPC_QuickProductionplan_Dtl a  
 Where a.DocNo=@MaxDocNo and a.RevisionNo=@MaxRevNo and a.PlanType=@Tmp_PlanType  
  and a.[Shift]=@ShiftCode and a.BranchID=@BranchID   
  and a.CompID=@CompID and a.Finyear=@Finyear  
END  
GO

