CREATE Procedure [dbo].[PpcWoYieldRep]
 (@Start DateTime,@End DateTime,@CmCode VarChar(5),@FinYear VarChar(20) )
as 
Begin
Set NoCount On
	select isnull(PartNo,'')as PartNo,ItemDesc,Norms,PrdQty,IgrQty,McsQty,(PrdQty-(IgrQty+McsQty)) as PenWo,
	(IgrQty/PrdQty)*100 as Yeld1,
	((IgrQty+PrdQty-(IgrQty+McsQty))/PrdQty) * 100 as Yeld2
	 from (
		Select PartNo,ItemDesc,Norms, Sum(IsNull(PrdQty,0)) PrdQty, Sum(IsNull(IGR_Qty,0)) IGRqty , Sum(IsNull(MCS_Qty,0)) as MCSqty
		from (
			Select (Select top 1 PartNo from PartMast Where StageCode=Estage_Code and CompId=@CmCode) as PartNo,
			(select item_desc from inv_matl_mast  where item_code =ParentCode  and compid=@CmCode) ItemDesc,Norms	
			,PrdQty,IGR_Qty, MCS_Qty
			from ( 
				 Select Estage_Code,Convert(VarChar,Norms) as Norms, Round((Iss_Qty/Norms),0) as PrdQty ,
				 (Select top 1 Item_Code from PartMast Where StageCode=Estage_Code and CompId=@CmCode) as ParentCode,
				 Completed_Qty as IGR_Qty,Rej_Qty as MCS_Qty from PPC_WO_HDR
				 where Wo_Date Between convert(datetime,@Start,111) and convert(datetime,@End,111) 
				 AND COMPID = @CmCode AND FINYEAR = @FinYear
			 	) A 
		 ) B Group by PartNO,ItemDesc,Norms
	    ) C order by PartNo
End





GO

/****** Object:  StoredProcedure [dbo].[ProductionPlanVsActualRpt]    Script Date: 17/06/2026 11:30:34 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO


CREATE PROCEDURE [dbo].[ProductionPlanVsActualRpt] (@YearMonth datetime, @FromDate dateTime, @ToDate datetime, @BranchID varchar(3), @CompID varchar(3), @FinYear varchar(20))

AS

SET NOCOUNT ON

	
	Declare @PlanMonth varchar(2)
	Declare @PlanYear varchar(4)

	Select @PlanMonth = Month(@YearMonth) 
	Select @PlanYear = Year(@YearMonth) 


Select ItemCode, ItemDescription,
	isNull((Select top 1 d1.partno  from partmast d1 where d1.Itemcode = ItemCode and d1.BranchID = @BranchID and d1.CompID = @CompID), 'Not Available') Partno,  
	PlanWeek1, PlanWeek2, PlanWeek3, PlanWeek4, ActWeek1, ActWeek2, ActWeek3, ActWeek4,
	(PlanWeek1 + PlanWeek2 + PlanWeek3 + PlanWeek4)PlanQty, Rate

From 
	(Select   isNull(x.ItemCode, y.ItemCode) ItemCode, isnull(x.ItemDescription, y.ItemDescription)ItemDescription,	
		isNull(x.Week1, 0) PlanWeek1, isNull(x.Week2, 0) PlanWeek2, isNull(x.Week3, 0) PlanWeek3, isNull(x.Week4, 0) PlanWeek4,
		isNull(y.ActWeek1, 0) ActWeek1, isNull(y.ActWeek2, 0) ActWeek2, isNull(y.ActWeek3, 0) ActWeek3, isNull(y.ActWeek4, 0) ActWeek4,
		isNull(x.Rate, y.Rate) Rate

From 

	(
		Select a.ItemCode,(Select b.ItemDescription From INV_MATERIAL_MASTER b  Where b.ItemCode = a.ItemCode 
			and b.BranchID = a.BranchID and b.CompID = a.CompID) ItemDescription, a.ScheduleQty, a.ProductionPlanQty,
			a.Week1,a.Week2,a.Week3,a.Week4, 
			dbo.fn_WtAvgRate (a.ItemCode, @FromDate, @ToDate, @BranchID, @CompID, @FinYear)Rate 
		From PPC_ProductionPlanMonth a 
		Where  month(ProductionPlanMonth) = @PlanMonth and year(ProductionPlanMonth) = @PlanYear and a.BranchID = @BranchID 
			and a.CompID = @CompID and a.Finyear = @FinYear 
			and a.ModifiedDate = (Select  max(b.ModifiedDate) From PPC_ProductionPlanMonth b 
						Where b.ProductionPlanType = a.ProductionPlanType and b.ProductionPlanNo = a.ProductionPlanNo 
						and b.ProductionPlanDate = a.ProductionPlanDate and b.BranchID = a.BranchID and b.CompID = a.CompID 
						and b.Finyear = a.Finyear)
	)x

Full Outer Join 

	(	

	Select a.ItemCode, (Select b.ItemDescription From INV_MATERIAL_MASTER b  Where b.ItemCode=a.ItemCode 
			and b.Branchid=a.Branchid and b.Compid=a.Compid) ItemDescription,
			Sum(Case when day(a.InwardGoodsReceiptDate) between 1 and 7 then a.InwardGoodsReceiptQty else 0 End )as ActWeek1,
			Sum(Case when day(a.InwardGoodsReceiptDate) between 8 and 14 then a.InwardGoodsReceiptQty else 0 End) as ActWeek2,
			Sum(Case when day(a.InwardGoodsReceiptDate) between 15 and 21 then a.InwardGoodsReceiptQty else 0 End) as ActWeek3,
			Sum(Case when day(a.InwardGoodsReceiptDate) >= 22 then a.InwardGoodsReceiptQty else 0 End) as ActWeek4,
			dbo.fn_WtAvgRate (a.ItemCode, @FromDate, @ToDate, @BranchID, @CompID, @FinYear) Rate 
	From PPC_InwardGoodsReceipt a
	Where  month(InwardGoodsReceiptDate) = @PlanMonth and year(InwardGoodsReceiptDate) = @PlanYear and a.BranchID = @BranchID 
		and a.CompID = @CompID and a.Finyear = @FinYear 
	Group By a.ItemCode, a.BranchID, a.CompID
	)y
On y.ItemCode = x.ItemCode)z
GO

/****** Object:  StoredProcedure [dbo].[PUR_Get_DCSR_Valid_Item]    Script Date: 17/06/2026 11:30:34 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PUR_Get_DCSR_Valid_Item] (@OrderType varchar(3), @OrderNo int, @OrderDate datetime, 
@Vendor int, @Relation varchar(3), @AsOnDate datetime, @RptDate datetime,  @BranchID varchar(3),
@CompID varchar(3), @Finyear varchar(20))  
  
AS  
BEGIN  
SET NOCOUNT ON;
  
Select distinct c1.ItemGroupKey, c1.ItemCode, c2.ItemDescription as ItemDesc, c2.PurchaseUOMDesc as UOM, c2.PurchaseUOMDecimal as NoOfDec,  
 c1.RatePer, c1.Rate, c1.OrderingType, c1.OrderQty, c1.DCSRQty, c1.CompQty, fItemCode  
from  
 (Select b2.ItemCode, b2.ItemGroupKey, b2.OrderingType, isNull(b2.OrderQty, 0) as OrderQty, isNull(Sum(b1.DCSRQty), 0) as DCSRQty, isNull(Sum(b1.CompQty), 0) as CompQty,  
  b2.RatePer, b2.Rate, fItemCode  
 from  
  (Select Distinct a6.VendorCode, a6.OrderType, a6.OrderNo, a6.OrderDate, a6.OrderingType, a6.ItemGroupKey,   
   a6.ItemCode,a6.RatePer, a6.Rate,sum(a6.ToBeRecdQty)OrderQty, fItemCode from (Select distinct   
   a6.VendorCode, a6.OrderType, a6.OrderNo, a6.OrderDate, a6.OrderingType, a6.ItemGroupKey,   
   Case When a5.RelationType='N-1' then a5.RecdItemCode else a5.SentItemCode End as ItemCode,      
   a6.ToBeRecdQty, a6.RatePer, a6.Rate,  
   Case When a5.RelationType='N-1' then a5.SentItemCode else a5.RecdItemCode End as fItemCode  
   from dbo.fn_PUR_LaborOrder_Vw (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a6   
  Left Outer Join   
   (Select Distinct a7.ItemGroupKey, a7.RelationType, a7.RecdItemCode, a7.SentItemCode   
   from PUR_SubCont_ItemMaster a7  
   where a7.SubContCode=@Vendor and a7.BranchID=@BranchID and a7.CompID=@CompID  
     and a7.isActive = '1'  
   ) a5  
  On a6.ItemGroupKey=a5.ItemGroupKey   
  Where a6.OrderType=@OrderType and a6.OrderNo=@OrderNo and a6.OrderDate=@OrderDate  
   and a6.isActive='1' and a6.VendorCode=@Vendor and a5.RelationType=@Relation  
   and a6.BranchID=@BranchID and a6.CompID=@CompID)a6  
  Group By a6.VendorCode, a6.OrderType, a6.OrderNo, a6.OrderDate, a6.OrderingType, a6.ItemGroupKey, a6.RatePer, a6.Rate,a6.ItemCode, a6.fItemCode      
  )b2  
  
  Left Outer Join   
  
  (Select k.DCSRType, k.DCSRNo, k.DCSRDate, k.ItemGroupKey, m.RecdItemCode,   
       Case When exists (Select distinct * from PUR_DCSR_Tran b where b.DCSRType=k.DCSRType and b.DCSRNo=k.DCSRNo and b.DCSRDate=k.DCSRDate  
      and Mode='SC' and b.BranchID=@BranchID and b.CompID=@CompID)   
    Then Round(Min(k.CompQty), n.PurchaseUOMDecimal, 1)   
    Else Round(Min(k.DCSRQty-k.CompQty), n.PurchaseUOMDecimal, 1)   
    End as DCSRQty,   
     Round(Min(k.CompQty), n.PurchaseUOMDecimal, 1) as CompQty  
  from   
   (Select a.DCSRType, a.DCSRNo, a.DCSRDate, a.ItemGroupKey, a.SentItemCode,   
    isNull(Sum(Case When a.Mode='NW' then a.Qty Else 0 End), 0) / a.Norms as DCSRQty,   
    -1 * isnull(Sum(Case When a.Mode='CM' then a.Qty Else 0 End), 0) / a.Norms as CompQty  
   from PUR_DCSR_Tran a   
   Where Mode in ('NW', 'CM')  and a.BranchID = @BranchID and CompID = @CompID  
   Group by a.DCSRType, a.DCSRNo, a.DCSRDate, a.ItemGroupKey, a.SentItemCode, a.Norms  
   ) k   
   Left Outer Join dbo.fn_PUR_DCSR_Schedule (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) m  
    On k.DCSRType=m.DCSRType and k.DCSRNo=m.DCSRNo and k.DCSRDate=m.DCSRDate  
     Left Outer Join Material_Master n  
      On m.RecdItemCode=n.ItemCode and m.BranchID=n.BranchID and m.CompID=n.CompID  
     Left Outer Join PUR_DCSR_Hdr a1  
      On k.DCSRType=a1.DCSRType and k.DCSRNo=a1.DCSRNo and k.DCSRDate=a1.DCSRDate  
       and a1.BranchID=m.BranchID and a1.CompID=m.CompID  
  Where a1.OrderType=@OrderType and a1.OrderNo=@OrderNo and a1.OrderDate=@OrderDate  
   and m.BranchID=@BranchID and m.CompID=@CompID ----and m.Finyear=@Finyear  
  Group by k.DCSRType, k.DCSRNo, k.DCSRDate, k.ItemGroupKey, m.RecdItemCode, n.PurchaseUOMDecimal  
  ) b1  
  On b1.ItemGroupKey=b2.ItemGroupKey  
  Group by b2.OrderingType, b2.ItemGroupKey, b2.ItemCode, b2.OrderQty, b2.RatePer, b2.Rate, b2.fItemCode  
 ) c1  
 Left Outer Join Material_Master c2  
 On c1.ItemCode=c2.ItemCode  
Where (c1.OrderingType='Open') or (c1.OrderingType='Specific' and ((c1.DCSRQty=0) or (c1.OrderQty-c1.DCSRQty) > 0))  
 and c2.BranchID=@BranchID and c2.CompID=@CompID
END
GO

/****** Object:  StoredProcedure [dbo].[PUR_Get_DCSR_Valid_Order]    Script Date: 17/06/2026 11:30:34 ******/
SET ANSI_NULLS OFF
GO

