CREATE PROCEDURE [dbo].[PUR_Get_DCSR_Valid_Vendor] (@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))

AS

SET NOCOUNT ON

Select Distinct  (Select c2.PartyName from FAS_Party_Master c2 where c2.PartyCode=c1.VendorCode and c2.BranchID=@BranchID and c2.CompID=@CompID) as VendorName,
	c1.VendorCode
from
	(Select b2.VendorCode, b2.OrderType, b2.OrderNo, b2.OrderDate, b2.ItemGroupKey, b2.RecdItemCode,
		b2.OrderingType, isNull(b2.OrderQty, 0) as OrderQty, isNull(Sum(b1.DCSRQty), 0) as DCSRQty, isNull(Sum(b1.CompQty), 0) as CompQty
	from
		(Select a6.VendorCode, a6.OrderType, a6.OrderNo, a6.OrderDate, a6.OrderingType, a6.ItemGroupKey, a6.RecdItemCode, Sum(a6.ToBeRecdQty) as OrderQty
 		from dbo.fn_PUR_LaborOrder_Vw (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a6
		Where a6.ValidFrom <= @RptDate and a6.ValidTo >= @RptDate and a6.isActive='1' and a6.Status='A'
			and a6.BranchID=@BranchID and a6.CompID=@CompID
		Group By a6.VendorCode, a6.OrderType, a6.OrderNo, a6.OrderDate, a6.OrderingType, a6.ItemGroupKey, a6.RecdItemCode
		)b2

		Left Outer Join 

		(Select k.DCSRType, k.DCSRNo, k.DCSRDate, k.ItemGroupKey, m.RecdItemCode, a1.OrderType, a1.OrderNo, a1.OrderDate,
			Case    When exists (Select distinct * from dbo.fn_PUR_DCSR_Tran (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) b 
						where b.DCSRType=k.DCSRType and b.DCSRNo=k.DCSRNo and b.DCSRDate=k.DCSRDate
						and Mode='SC' and b.BranchID=@BranchID and b.CompID=@CompID ) 
				Then Round(Min(k.CompQty), n1.NoofDecimals, 1) 
				Else Round(Min(k.DCSRQty-k.CompQty), n1.NoofDecimals, 1) 
			End as DCSRQty, 
			Round(Min(k.CompQty), n1.NoofDecimals, 1) as CompQty
		from 
			(Select a.DCSRType, a.DCSRNo, a.DCSRDate, a.ItemGroupKey, a.SentItemCode, 
				isNull(Sum(Case When a.Mode='NW' then a.Qty Else 0 End), 0) / a.Norms as DCSRQty, 
				-1 * isnull(Sum(Case When a.Mode='CM' then a.Qty Else 0 End), 0) / a.Norms as CompQty
			from PUR_DCSR_Tran a 
			Where Mode in ('NW', 'CM')
			Group by a.DCSRType, a.DCSRNo, a.DCSRDate, a.ItemGroupKey, a.SentItemCode, a.Norms
			) k 
		
			Left Outer Join dbo.fn_PUR_DCSR_Schedule (@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) m
			On k.DCSRType=m.DCSRType and k.DCSRNo=m.DCSRNo and k.DCSRDate=m.DCSRDate
				Left Outer Join INV_Material_Master n
				On m.RecdItemCode=n.ItemCode and m.BranchID=n.BranchID and m.CompID=n.CompID
				Left Outer Join INV_UOM_Master n1
				On n.PurchaseUOM=n1.Code and m.BranchID=n1.BranchID and m.CompID=n1.CompID
					Left Outer Join PUR_DCSR_Hdr a1
					On k.DCSRType=a1.DCSRType and k.DCSRNo=a1.DCSRNo and k.DCSRDate=a1.DCSRDate
						and a1.BranchID=m.BranchID and a1.CompID=m.CompID
		Where m.BranchID=@BranchID and m.CompID=@CompID 
		Group by k.DCSRType, k.DCSRNo, k.DCSRDate, k.ItemGroupKey, m.RecdItemCode, n1.NoofDecimals, a1.OrderType, a1.OrderNo, a1.OrderDate
		) b1
		On b1.OrderType=b2.OrderType and b1.OrderNo=b2.OrderNo and b1.OrderDate=b2.OrderDate and b1.ItemGroupKey=b2.ItemGroupKey and b1.RecdItemCode=b2.RecdItemCode
		Group by b2.VendorCode, b2.OrderType, b2.OrderNo, b2.OrderDate, b2.OrderingType, b2.ItemGroupKey, b2.RecdItemCode, b2.OrderQty
	) c1
Where (c1.OrderingType='Open') or (c1.OrderingType='Specific' and ((c1.DCSRQty=0) or (c1.OrderQty-c1.DCSRQty) > 0))
GO

