CREATE PROCEDURE [dbo].[PUR_Get_FillRR_LOMiscInvoice] (@UserKey varchar(100), @PartyCode int, @RefStr varchar(50), @AsOnDate datetime, @RptDate datetime,  @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))

AS

SET NOCOUNT ON

		Select ReceiptEntryType, ReceiptEntryNo, ReceiptEntryDate, ItemCode, ItemDescription,
				UOM, NoDec, RatePer, Rate, AcceptedQty, InvoicedQty, SeqNo, OrderType, OrderNo, Orderdate
		From (Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.ItemCode, c.ItemDescription,
				c.PurchaseUomDesc as UOM, c.PurchaseUomDecimal as NoDec, e.RatePer, isNull(e.Rate, -1) as Rate, 
				sum(a.AcceptedQty)AcceptedQty, 
				isNull((Select Sum(Qty) from PUR_PurchaseInvoice_OrdRef c 
					Where c.RefNo = a.ReceiptEntryNo And c.RefDate = a.ReceiptEntryDate And c.RefType = a.ReceiptEntryType 
						And c.ItemCode = a.ItemCode and c.BranchID=a.BranchID and c.CompID=a.CompID), 0) as InvoicedQty,
				e.SeqNo, r.OrderType, r.OrderNo, r.Orderdate 
			from ReceiptEntry a 
			Left Outer Join Material_Master c 
				On a.ItemCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID 
			Left Outer Join dbo.fn_PUR_LaborOrderMiscDC_Dtl(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) q 
				On a.RefNo=q.RefNo and a.RefDate=q.RefDate and a.RefType=q.RefType 
						and a.ItemCode=q.ItemCode and a.BranchID=q.BranchID and a.CompID=q.CompID 
			Left Outer Join PUR_LaborOrderMiscDC_Hdr m
				On m.DocNo=q.DocNo and m.DocDate=q.DocDate and m.DocType=q.DocType and m.BranchID=q.BranchID and m.CompID=q.CompID 
			Left Outer Join dbo.fn_PUR_LaborOrderMisc_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) r 
				On r.OrderNo=m.OrderNo and r.Orderdate=m.OrderDate and r.OrderType=m.OrderType and m.BranchID=r.BranchID and m.CompID=r.CompID 
			Left Outer Join (Select * from dbo.fn_PUR_LaborOrderMisc_Dtl(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) x  
						Where Exists (Select * From PUR_Invoice_Tmp y Where y.UserKey = @UserKey
							and x.OrderNo=y.OrdNo and x.OrderDate=y.OrdDate and x.OrderType=y.OrdType 
							and y.BranchID = x.BranchID and y.CompID = x.CompID) 
					   ) e 
			On a.ItemCode=e.ItemCode and a.BranchID=e.BranchID and a.CompID=e.CompID 
				and r.OrderNo=e.OrderNo and r.Orderdate=e.OrderDate and r.OrderType=e.OrderType 
			Where a.VendorCode=@PartyCode and a.InwardType='I'  
				and a.ReceiptEntryType + ':' + Convert(varchar, a.ReceiptEntryNo) in (@RefStr) 
				and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear
			Group by a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.ItemCode, c.ItemDescription, c.PurchaseUomDesc, 
				c.PurchaseUomDecimal,	e.RatePer, e.Rate, A.Branchid, A.Compid, e.SeqNo, r.OrderType, r.OrderNo, r.Orderdate 
			)z 
		Where AcceptedQty > 0 
		Order by ItemCode
GO

