CREATE PROCEDURE [dbo].[PUR_Get_LaborOrderMisc_Valid_Item] (@OrderType varchar(3), @OrderNo int, @OrderDate datetime, @Vendor int,  @AsOnDate datetime, @RptDate datetime,  @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))

AS

SET NOCOUNT ON

	Select Distinct c1.OrderType, c1.OrderNo, c1.OrderDate,  c1.ItemCode, c1.ItemDescription, c1.PurchaseUOMDecimal as UOM, 
			c1.PurchaseUOMDesc as UOMdesc, c1.Rate, c1.RatePer, c1.OrderQty, c1.DCQty
	from
		(Select b2.OrderType, b2.OrderNo, b2.OrderDate, b2.ItemCode, b3.ItemDescription, b2.Rate, b2.RatePer,
			b2.OrderingType, isNull(b2.OrderQty, 0) as OrderQty,  isNull(Sum(b1.DCQty), 0) as DCQty, 
				b3.PurchaseUOMDecimal, b3.PurchaseUOMDesc
		from
			(Select a6.OrderType, a6.OrderNo, a6.OrderDate, a6.VendorCode, a6.OrderingType, a6.ItemCode, Convert(Varchar(8),a6.Rate) Rate, a6.RatePer, Sum(a6.Qty) as OrderQty
	 		from PUR_LaborOrderMisc_Vw  a6
			Where a6.VendorCode=@Vendor and a6.ValidFrom <= @RptDate and a6.ValidTo >= @RptDate and a6.isActive='1' and a6.Status='A'
				and a6.BranchID=@BranchID and a6.CompID=@CompID and a6.OrderingType = 'MWI'
			Group By a6.OrderType, a6.OrderNo, a6.OrderDate, a6.VendorCode, a6.OrderingType, a6.ItemCode, a6.Rate, a6.RatePer
			)b2
	        
		Left Outer Join 
			(Select k.DocType, k.DocNo, k.DocDate, k.DCQty, k.ItemCode, n.ItemDescription,  a1.OrderType, a1.OrderNo, a1.OrderDate
			From
				(Select  a.DocType, a.DocNo, a.DocDate, a.ItemCode, isNull(Sum(a.Qty),0) as DCQty
				From Pur_LaborOrderMiscDc_Dtl a
				Where a.Mode in ('NW', 'CM')
				Group by a.DocType, a.DocNo, a.DocDate, a.ItemCode
				) k
			Left Outer Join Material_Master n
				On k.ItemCode = n.ItemCode and n.BranchID = @BranchID and n.CompID = @CompID
			Left Outer Join Pur_LaborOrderMiscDc_Hdr a1
				On k.DocType= a1.DocType and k.DocNo = a1.DocNo and k.DocDate = a1.DocDate
					and a1.BranchID = @BranchID and a1.CompID = @CompID
			Where n.BranchID = @BranchID and n.CompID = @CompID
				
			Group by k.DocType, k.DocNo, k.DocDate, k.DCQty,  k.ItemCode, n.ItemDescription,  a1.OrderType, a1.OrderNo, a1.OrderDate
			) b1
			On b1.OrderType=b2.OrderType and b1.OrderNo=b2.OrderNo and b1.OrderDate=b2.OrderDate and b1.ItemCode=b2.ItemCode
			Left Outer Join (Select ItemCode, ItemDescription, PurchaseUOMDecimal,  PurchaseUOMDesc  from  Material_Master where BranchID=@BranchID and CompID=@CompID) b3 
				On b2.ItemCode=b3.ItemCode
			
			Group by b2.OrderType, b2.OrderNo, b2.OrderDate, b2.Rate, b2.RatePer,  b2.OrderingType,  b2.ItemCode, b3.itemdescription, 
					b2.OrderQty,  b3.PurchaseUOMDecimal, b3.PurchaseUOMDesc
		) c1
	Where (c1.OrderingType='MWI') and (c1.OrderQty-c1.DCQty) > 0


/*
	Select Distinct c1.OrderType, c1.OrderNo, c1.OrderDate, c1.ItemGroupKey,  c1.ItemCode, c1.ItemDescription, c1.PurchaseUOMDecimal as UOM, c1.PurchaseUOMDesc as UOMdesc, c1.Rate, c1.RatePer, c1.OrderQty, c1.DCQty
	from
		(Select b2.OrderType, b2.OrderNo, b2.OrderDate, b2.ItemCode, b3.ItemDescription, b2.Rate, b2.RatePer,
			b2.OrderingType, isNull(b2.OrderQty, 0) as OrderQty,  isNull(Sum(b1.DCQty), 0) as DCQty,  b1.ItemGroupKey,  b3.PurchaseUOMDecimal, b3.PurchaseUOMDesc
		from
			(Select a6.OrderType, a6.OrderNo, a6.OrderDate, a6.VendorCode, a6.OrderingType, a6.ItemCode, Convert(Varchar(8),a6.Rate) Rate, a6.RatePer, Sum(a6.Qty) as OrderQty
	 		from PUR_LaborOrderMisc_Vw  a6
			Where a6.VendorCode=@Vendor and a6.ValidFrom <= @RptDate and a6.ValidTo >= @RptDate and a6.isActive='1' and a6.Status='A'
				and a6.BranchID=@BranchID and a6.CompID=@CompID
			Group By a6.OrderType, a6.OrderNo, a6.OrderDate, a6.VendorCode, a6.OrderingType, a6.ItemCode, a6.Rate, a6.RatePer
			)b2
	        
		Left Outer Join 
			(Select k.DCType, k.DCNo, k.DCDate, k.ItemGroupKey, k.DCQty, k.ItemCode, n.ItemDescription,  a1.OrderType, a1.OrderNo, a1.OrderDate
			From
				(Select  a.DCType, a.DCNo, a.DCDate, a.ItemGroupKey, a.ItemCode, isNull(Sum(a.Qty),0) as DCQty
				From PUR_LaborOrderDC_Tran a
				Where a. Mode in ('NW', 'CM')
				Group by a.DCType, a.DCNo, a.DCDate, a.ItemGroupKey, a.ItemCode
				) k
			Left Outer Join Material_Master n
				On k.ItemCode = n.ItemCode and n.BranchID = @BranchID and n.CompID = @CompID
			Left Outer Join PUR_LaborOrderDC_dtl a1
				On k.DCtype= a1.DCType and k.DCNo = a1.DCNo and k.DCDate = a1.DCDate
					and a1.BranchID = @BranchID and a1.CompID = @CompID
			Where n.BranchID = @BranchID and n.CompID = @CompID
				
			Group by k.DCType, k.DCNo, k.DCDate, k.ItemGroupKey, k.DCQty,  k.ItemCode, n.ItemDescription,  a1.OrderType, a1.OrderNo, a1.OrderDate
			) b1
			On b1.OrderType=b2.OrderType and b1.OrderNo=b2.OrderNo and b1.OrderDate=b2.OrderDate and b1.ItemCode=b2.ItemCode
			Left Outer Join (Select ItemCode, ItemDescription, PurchaseUOMDecimal,  PurchaseUOMDesc  from  Material_Master where BranchID=@BranchID and CompID=@CompID) b3 
				On b2.ItemCode=b3.ItemCode
			
			Group by b2.OrderType, b2.OrderNo, b2.OrderDate, b2.Rate, b2.RatePer,  b2.OrderingType,  b2.ItemCode, b3.itemdescription, b2.OrderQty, b1.ItemGroupKey,  b3.PurchaseUOMDecimal, b3.PurchaseUOMDesc
		) c1
	Where (c1.OrderingType='MWI') and (c1.OrderQty-c1.DCQty) > 0
*/
