CREATE PROCEDURE [dbo].[PUR_Get_LaborOrderMisc_Valid_Order] (@Vendor int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  


AS

SET NOCOUNT ON

	Select Distinct c1.OrderType, c1.OrderNo, c1.OrderDate, c1.ItemCode, c1.ItemDescription, c1.ValidTo
	from
		(Select b2.OrderType, b2.OrderNo, b2.OrderDate, b2.ValidTo,  b2.ItemCode, b3.ItemDescription,
			b2.OrderingType, isNull(b2.OrderQty, 0) as OrderQty,  isNull(Sum(b1.DCQty), 0) as DCQty
		from
			(Select a6.OrderType, a6.OrderNo, a6.OrderDate, a6.ValidTo, a6.OrderingType,  a6.ItemCode, Sum(a6.Qty) as OrderQty
	 		from PUR_LaborOrderMisc_Vw  a6
			Where a6.VendorCode=@Vendor and a6.ValidFrom <= @RptDate and a6.ValidTo >= @RptDate and a6.isActive='1' and a6.Status='A'
				and a6.BranchID=@BranchID and a6.CompID=@CompID
			Group By a6.OrderType, a6.OrderNo, a6.OrderDate, a6.ValidTo, a6.OrderingType,  a6.ItemCode
			)b2
	        
		Left Outer Join 
			(Select k.DocType, k.DocNo, k.DocDate, k.DCQty, k.ItemCode, n.ItemDescription, a1.OrderType, a1.OrderNo, a1.OrderDate
			From
				(Select  a.DocType, a.DocNo, a.DocDate, a.ItemCode, isNull(Sum(a.Qty),0) as DCQty
				From PUR_LaborOrderMiscDC_Dtl a
				Where a. Mode in ('NW', 'CM')  and a.BranchID = @BranchID and a.CompID = @CompID
				Group by a.DocType, a.DocNo, a.DocDate, a.ItemCode
				) k
			Left Outer Join Material_Master n
				On k.ItemCode = n.ItemCode
			Left Outer Join PUR_LaborOrderMiscDC_Hdr a1
				On k.DocType= a1.DocType and k.DocNo = a1.DocNo and k.DocDate = a1.DocDate
					and a1.BranchID = @BranchID and a1.CompID = @CompID
			Where n.BranchID = @BranchID and n.CompID = @CompID
				
			Group by k.DocType, k.DocNo, k.DocDate, k.DCQty,  k.ItemCode, n.ItemDescription, n.PurchaseUOMDecimal, a1.OrderType, a1.OrderNo, a1.OrderDate
			) b1
		On b1.OrderType=b2.OrderType and b1.OrderNo=b2.OrderNo and b1.OrderDate=b2.OrderDate and b1.ItemCode=b2.ItemCode
		Left Outer Join (Select ItemCode, ItemDescription from  INV_Material_Master where BranchID=@BranchID and CompID=@CompID) b3 
		On b2.ItemCode=b3.ItemCode
			
		Group by b2.OrderType, b2.OrderNo, b2.OrderDate, b2.ValidTo,  b2.OrderingType,  b2.ItemCode, b3.itemdescription, b2.OrderQty
		) c1
	Where (c1.OrderingType='MWI') and (c1.OrderQty-c1.DCQty) > 0
GO

