CREATE PROCEDURE [dbo].[Pur_Get_MaterialPlan] (@isCreate bit, @MDocType Varchar(3), @PDocType Varchar(3), @PlanFor int,  @Period datetime,  @Finstart datetime,  @AsOnDate datetime,  @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))

AS

Begin
	SET NOCOUNT ON

	Declare @PlanMonth varchar(2)
	Declare @PlanYear varchar(4)

	Select @PlanMonth = Month(@Period) 
	Select @PlanYear = Year(@Period) 

	Select a.ItemCode, b.ItemDescription, b.UomDesc, b.UomDecimal, a.PlanQty,  a.PlanFor, a.PlanPeriod,
		------dbo.fn_WtAvgRate (a.ItemCode, @Finstart, @RptDate, @BranchID,  @CompID, @Finyear)Rate, 
		dbo.fn_Pur_Item_Rate (a.ItemCode, 0, '', 0, Null, @AsOnDate,  @RptDate, @BranchID,  @CompID, @Finyear)Rate,  ---0 refer Vendorcode, '' refer OrderType, 0 refer OrderNo, Null refer OrderDate
		1 Seq
		From dbo.fn_Pur_Materialplan (@AsOnDate,  @RptDate,  @BranchID,  @CompID,  @Finyear)    a
			Left Outer Join Material_Master b
				On b.ItemCode = a.ItemCode and b.BranchID = a.BranchID and b.CompID = a.CompID
		Where ((a.PlanFor=1 and Month(PlanPeriod)=4) or (a.PlanFor > 1 and Month(PlanPeriod) = @PlanMonth)) and Year(PlanPeriod) = @PlanYear	
			and PlanFor = (Select Max(PlanFor) PlanFor From dbo.fn_Pur_Materialplan (@AsOnDate,  @RptDate,  @BranchID,  @CompID,  @Finyear)    
						Where ((PlanFor=1 and Month(PlanPeriod)=4) or (PlanFor > 1 and Month(PlanPeriod) = @PlanMonth)) and Year(PlanPeriod) = @PlanYear and 
							((@isCreate='1' and PlanFor < @PlanFor) or (@isCreate='0' and PlanFor <= @PlanFor))
							and BranchID = a.BranchID and CompID = a.CompID and a.DocType =  @MDocType)
			and a.DocType =  @MDocType
Union All

	Select a.ItemCode, b.ItemDescription, b.UomDesc, b.UomDecimal, a.PlanQty,  a.PlanFor, a.PlanPeriod,
		-----dbo.fn_WtAvgRate (a.ItemCode,  @Finstart, @RptDate, @BranchID,  @CompID, @Finyear)Rate,
		dbo.fn_Pur_Item_Rate (a.ItemCode, 0, '', 0, Null, @AsOnDate,  @RptDate, @BranchID,  @CompID, @Finyear)Rate,  ---0 refer Vendorcode, '' refer OrderType, 0 refer OrderNo, Null refer OrderDate
		 2 Seq
		From dbo.fn_Ppc_Productionplan (@AsOnDate,  @RptDate,  @BranchID,  @CompID,  @Finyear)    a
			Left Outer Join Material_Master b
				On b.ItemCode = a.ItemCode and b.BranchID = a.BranchID and b.CompID = a.CompID
		Where ((a.PlanFor=1 and Month(PlanPeriod)=4) or (a.PlanFor > 1 and Month(PlanPeriod) = @PlanMonth))  and Year(PlanPeriod) = @PlanYear	
			and PlanFor = (Select Max(PlanFor) PlanFor From dbo.fn_Ppc_Productionplan (@AsOnDate,  @RptDate,  @BranchID,  @CompID,  @Finyear)    
						Where ((PlanFor=1 and Month(PlanPeriod)=4) or (PlanFor > 1 and Month(PlanPeriod) = @PlanMonth))  and Year(PlanPeriod) = @PlanYear and PlanFor <= @PlanFor
							and BranchID = a.BranchID and CompID = a.CompID and a.DocType =  @PDocType) and a.DocType =  @PDocType
			and not Exists 
					(Select *
						From dbo.fn_Pur_Materialplan (@AsOnDate,  @RptDate,  @BranchID,  @CompID,  @Finyear)    a
						Where ((a.PlanFor=1 and Month(PlanPeriod)=4) or (a.PlanFor > 1 and Month(PlanPeriod) = @PlanMonth))  and Year(PlanPeriod) = @PlanYear	
							and PlanFor = (Select Max(PlanFor) PlanFor From dbo.fn_Pur_Materialplan (@AsOnDate,  @RptDate,  @BranchID,  @CompID,  @Finyear)    
										Where ((PlanFor=1 and Month(PlanPeriod)=4) or (PlanFor > 1 and Month(PlanPeriod) = @PlanMonth))  and Year(PlanPeriod) = @PlanYear and PlanFor <= @PlanFor
											and BranchID = a.BranchID and CompID = a.CompID and a.DocType =  @MDocType)
											and a.DocType =  @MDocType) 
		Order By a.ItemCode, a.PlanFor
	End
GO

/****** Object:  StoredProcedure [dbo].[PUR_Get_PendingRR_LOMiscInvoice]    Script Date: 17/06/2026 11:30:35 ******/
SET ANSI_NULLS OFF
GO

