GO

CREATE PROCEDURE [dbo].[PUR_Get_PendingRR_LOMiscInvoice] (@ModuleCode int, @OrderingType char(3), @Vendor int, @AsOnDate datetime, @RptDate datetime,  @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))

AS

SET NOCOUNT ON

		Select distinct p.ReceiptEntryType, p.ReceiptEntryNo, p.ReceiptEntryDate, m.OrderType, 
					m.OrderNo, m.OrderDate, r.FormulaCode, s.FrmLName, r.PostingAc 
		from (	
			Select distinct ReceiptEntryType, ReceiptEntryNo, ReceiptEntryDate, RefType, RefNo, RefDate 
			from (
				Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.RefType, a.RefNo,
					a.RefDate, a.ItemCode, a.AcceptedQty, isNull(Sum(c.Qty), 0) as InvoicedQty 
				from ReceiptEntry a 
				Left Outer Join PUR_LaborMiscInvoice_Ref c  
					On c.RefNo=a.ReceiptEntryNo And c.RefDate=a.ReceiptEntryDate And c.RefType=a.ReceiptEntryType 
						and c.itemcode=a.itemcode and c.BranchID=a.BranchID and c.CompID=a.CompID 
				Where a.VendorCode=@Vendor and a.InwardType='I' and a.BranchID=@BranchID and a.CompID=@CompID
					and a.Finyear=@Finyear 
				Group by a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.RefType, a.RefNo, 
					a.RefDate, a.ItemCode, a.AcceptedQty 
			  ) x 
			Where AcceptedQty > InvoicedQty 
		) p 
		Left Outer Join dbo.fn_PUR_LaborOrderMiscDC_Dtl(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) q 
			On p.RefNo=q.RefNo and p.RefDate=q.RefDate and p.RefType=q.RefType 
		Left Outer Join PUR_LaborOrderMiscDC_Hdr m
			On m.DocNo=q.DocNo and m.DocDate=q.DocDate and m.DocType=q.DocType and m.BranchID=q.BranchID and m.CompID=q.CompID 
		Left Outer Join dbo.fn_PUR_LaborOrderMisc_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) r 
			On r.OrderNo=m.OrderNo and r.Orderdate=m.OrderDate and r.OrderType=m.OrderType and m.BranchID=r.BranchID and m.CompID=r.CompID 
		Left Outer Join COM_FormulaMast_Hdr s 
			On r.FormulaCode=s.FrmID and s.ModuleCode=@ModuleCode and r.BranchID=s.BranchID and r.CompID=s.CompID 
		Where r.OrderingType = @OrderingType
		Order by m.OrderNo
GO

/****** Object:  StoredProcedure [dbo].[PUR_Get_PendingVendorDCSR]    Script Date: 17/06/2026 11:30:35 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[PUR_Get_PendingVendorDCSR] (@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))

AS

SET NOCOUNT ON


Select distinct (select PartyName from FAS_Party_Master f where f.PartyCode=x.VendorCode and f.Branchid=@BranchID 
and f.Compid=@CompID) AcName,x.VendorCode,x.DCSRType, x.DCSRNo, x.DCSRDate
from (
	Select k.DCSRType, k.DCSRNo, k.DCSRDate, k.ItemGroupKey, m.RecdItemCode, a1.OrderType, 
        		a1.OrderNo, a1.OrderDate,(select e.VendorCode from PUR_LaborOrder_Hdr e where 
	   	e.OrderType=a1.OrderType and e.OrderNo=a1.OrderNo and e.OrderDate=a1.OrderDate
		and e.Branchid=@BranchID and e.Compid=@CompID) VendorCode,

	Case    When exists (Select distinct * from PUR_DCSR_Tran b where b.DCSRType=k.DCSRType and b.DCSRNo=k.DCSRNo and b.DCSRDate=k.DCSRDate
		and Mode='SC' and b.BranchID=@BranchID and b.CompID=@CompID) 
		Then Round(Min(k.CompQty), n.PurchaseUOMDecimal, 1) 
		Else Round(Min(k.DCSRQty-k.CompQty), n.PurchaseUOMDecimal, 1) 
	        End as DCSRQty, Round(Min(k.CompQty), n.PurchaseUOMDecimal, 1) as CompQty
		from 
		(Select a.DCSRType, a.DCSRNo, a.DCSRDate, a.ItemGroupKey, a.SentItemCode, 
		isNull(Sum(Case When a.Mode='NW' then a.Qty Else 0 End), 0) / a.Norms as DCSRQty, 
		-1 * isnull(Sum(Case When a.Mode='CM' then a.Qty Else 0 End), 0) / a.Norms as CompQty
		from PUR_DCSR_Tran a Where Mode in ('NW', 'CM')
		Group by a.DCSRType, a.DCSRNo, a.DCSRDate, a.ItemGroupKey, a.SentItemCode, a.Norms
		) k 
		
		Left Outer Join PUR_DCSR_Schedule m
		On k.DCSRType=m.DCSRType and k.DCSRNo=m.DCSRNo and k.DCSRDate=m.DCSRDate
		Left Outer Join Material_Master n
		On m.RecdItemCode=n.ItemCode and m.BranchID=n.BranchID and m.CompID=n.CompID
     		    	Left Outer Join PUR_DCSR_Hdr a1
			On k.DCSRType=a1.DCSRType and k.DCSRNo=a1.DCSRNo and k.DCSRDate=a1.DCSRDate
			and a1.BranchID=m.BranchID and a1.CompID=m.CompID
		Where m.BranchID=@BranchID and m.CompID=@CompID
		Group by k.DCSRType, k.DCSRNo, k.DCSRDate, k.ItemGroupKey, m.RecdItemCode, 
		n.PurchaseUOMDecimal, a1.OrderType, a1.OrderNo, a1.OrderDate) x 
		where (x.DCSRQty-CompQty) >0
GO

/****** Object:  StoredProcedure [dbo].[PUR_GetQuotationForComparison]    Script Date: 17/06/2026 11:30:35 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[PUR_GetQuotationForComparison] (@ItemCode varchar(20), @ValidFrom datetime, @ValidTo datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(15))

AS

SET NOCOUNT ON

		Select a.QuotationType, a.QuotationNo, a.QuotationDate, a.VendorCode, a.VendorName, 
			a.Qty, a.RatePer, a.Rate, a.AssRate, c.PurchaseUOMDesc, c.PurchaseUOMDecimal, a.ValidFrom, a.ValidTo, 
			a.FormCode,
				isNull((select b.Description from TERMSMASTER b 
				where b.TypeFlg='Form' and b.Code=a.FormCode and b.Branchid=a.Branchid and b.Compid=a.Compid), '') FormDesc, 
			a.PackingCode,
				isNull((select b1.Description from TERMSMASTER b1 
				where b1.TypeFlg='Packing & Forwarding' and b1.Code=a.PackingCode and b1.Branchid=a.Branchid and b1.Compid=a.Compid), '') PackingDesc,
			a.DeliveryCode,
				isNull((select b2.Description from TERMSMASTER b2 
				where b2.TypeFlg='Delivery Instruction' and b2.Code=a.DeliveryCode and b2.Branchid=a.Branchid and b2.Compid=a.Compid), '') DeliveryDesc,
			a.PaymentCode,
				isNull((select b3.Description from TERMSMASTER b3 
				where b3.TypeFlg='Payment Terms' and b3.Code=a.PaymentCode and b3.Branchid=a.Branchid and b3.Compid=a.Compid), '') PaymentDesc,
			a.InsuranceCode,
				isNull((select b4.Description from TERMSMASTER b4 
				where b4.TypeFlg='Insurance' and b4.Code=a.InsuranceCode and b4.Branchid=a.Branchid and b4.Compid=a.Compid), '') InsuranceDesc,
			a.ModeCode,
				isNull((select b5.Description from TERMSMASTER b5 
				where b5.TypeFlg='Mode' and b5.Code=a.ModeCode and b5.Branchid=a.Branchid and b5.Compid=a.Compid), '') ModeDesc,
			a.Freightcode,
				isNull((select b6.Description from TERMSMASTER b6 
				where b6.TypeFlg='Freight' and b6.Code=a.FreightCode and b6.Branchid=a.Branchid and b6.Compid=a.Compid), '') FreightDesc,
			a.FormulaCode,
				isNull((Select b7.FrmLName from Com_FormulaMast_Hdr b7
				where b7.modulecode=9 and b7.FrmID=a.FormulaCode and b7.BranchID=a.BranchID and b7.CompID=a.CompID), '') FormulaName
		from PURCHASEQUOTATION a Left Outer Join MATERIAL_MASTER c
			On a.ItemCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID
		where a.ItemCode=@ItemCode and a.OrderNo=0 and a.ValidFrom <= @ValidTo and a.ValidTo >= @ValidFrom
			and a.BranchID=@BranchID and a.CompID=@CompID
GO

/****** Object:  StoredProcedure [dbo].[PUR_Hlp_PurchaseRequest_ItemSelect]    Script Date: 17/06/2026 11:30:35 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[PUR_Hlp_PurchaseRequest_ItemSelect] (@Category int, @SubCategory int, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(15))

 AS


	Declare @StockDate datetime
	Select @StockDate=getdate()

	if @Category > 0 and @SubCategory > 0 
		begin
			Select a.ItemCode, a.ItemDescription, a.Rate, isNull(Sum(m.CBQty), 0) as CBQty,  c.SDesc as UOM, c.NoOfDecimals as NoOfDec
			from Inv_Material_Master a 
			Left Outer Join dbo.fn_INV_AsOnDate_Stock_AllWhs (@StockDate, @BranchID, @CompID, @Finyear)  m 
				On a.ItemCode=m.ItemCode and a.BranchID=m.BranchID and a.CompID=m.CompID
			Left Join (Select * from Inv_WareHouse_Master Where WareHouseNature Not in ('Scrap', 'Rejection') and BranchID=@BranchID and CompID=@CompID) n
				On m.WareHouseCode=n.WareHouseCode 
			Left Outer Join INV_UOM_Master c 
				On c.Code=a.PurchaseUOM and c.BranchID=a.BranchID and c.CompID=a.CompID
			Where a.BoughtOut in ('B','S')  and a.ProductCategoryCode = @Category and a.ProductSubCategoryCode = @SubCategory
			and a.Status = 1 and n.WarehouseCode not in ('UI') and m.WarehouseCode not in ('UI')  and a.BranchID=@BranchID and a.CompID=@CompID 
			Group by a.ItemCode, a.ItemDescription, a.Rate, c.SDesc, c.NoOfDecimals
			Order by a.ItemCode, a.ItemDescription
		end
	ELSE
	if @Category > 0 
		begin
			Select a.ItemCode, a.ItemDescription, a.Rate, isNull(Sum(m.CBQty), 0) as CBQty,  c.SDesc as UOM, c.NoOfDecimals as NoOfDec
			from Inv_Material_Master a 
			Left Outer Join dbo.fn_INV_AsOnDate_Stock_AllWhs (@StockDate, @BranchID, @CompID, @Finyear)  m 
				On a.ItemCode=m.ItemCode and a.BranchID=m.BranchID and a.CompID=m.CompID
			Left Join (Select * from Inv_WareHouse_Master Where WareHouseNature Not in ('Scrap', 'Rejection') and BranchID=@BranchID and CompID=@CompID) n
				On m.WareHouseCode=n.WareHouseCode 
			Left Outer Join INV_UOM_Master c 
				On c.Code=a.PurchaseUOM and c.BranchID=a.BranchID and c.CompID=a.CompID
			Where a.BoughtOut in ('B','S')  and a.ProductCategoryCode = @Category 
			and a.Status = 1 and n.WarehouseCode not in ('UI') and m.WarehouseCode not in ('UI')  and a.BranchID=@BranchID and a.CompID=@CompID 
			Group by a.ItemCode, a.ItemDescription, a.Rate, c.SDesc, c.NoOfDecimals
			Order by a.ItemCode, a.ItemDescription
		END
	ELSE
	if @SubCategory > 0 
		begin
			Select a.ItemCode, a.ItemDescription, a.Rate, isNull(Sum(m.CBQty), 0) as CBQty,  c.SDesc as UOM, c.NoOfDecimals as NoOfDec
			from Inv_Material_Master a 
			Left Outer Join dbo.fn_INV_AsOnDate_Stock_AllWhs (@StockDate, @BranchID, @CompID, @Finyear)  m 
				On a.ItemCode=m.ItemCode and a.BranchID=m.BranchID and a.CompID=m.CompID
			Left Join (Select * from Inv_WareHouse_Master Where WareHouseNature Not in ('Scrap', 'Rejection') and BranchID=@BranchID and CompID=@CompID) n
				On m.WareHouseCode=n.WareHouseCode 
			Left Outer Join INV_UOM_Master c 
				On c.Code=a.PurchaseUOM and c.BranchID=a.BranchID and c.CompID=a.CompID
			Where a.BoughtOut in ('B','S')  and a.ProductSubCategoryCode = @SubCategory
			and a.Status = 1 and n.WarehouseCode not in ('UI') and m.WarehouseCode not in ('UI')  and a.BranchID=@BranchID and a.CompID=@CompID 
			Group by a.ItemCode, a.ItemDescription, a.Rate, c.SDesc, c.NoOfDecimals
			Order by a.ItemCode, a.ItemDescription
		END
	Else
		begin
			Select a.ItemCode, a.ItemDescription, a.Rate, isNull(Sum(m.CBQty), 0) as CBQty,  c.SDesc as UOM, c.NoOfDecimals as NoOfDec
			from Inv_Material_Master a 
			Left Outer Join dbo.fn_INV_AsOnDate_Stock_AllWhs (@StockDate, @BranchID, @CompID, @Finyear)  m 
				On a.ItemCode=m.ItemCode and a.BranchID=m.BranchID and a.CompID=m.CompID
			Left Join (Select * from Inv_WareHouse_Master Where WareHouseNature Not in ('Scrap', 'Rejection') and BranchID=@BranchID and CompID=@CompID) n
				On m.WareHouseCode=n.WareHouseCode 
			Left Outer Join INV_UOM_Master c 
				On c.Code=a.PurchaseUOM and c.BranchID=a.BranchID and c.CompID=a.CompID
			Where a.BoughtOut in ('B','S')  
			and a.Status = 1 and n.WarehouseCode not in ('UI') and m.WarehouseCode not in ('UI')  and a.BranchID=@BranchID and a.CompID=@CompID 
			Group by a.ItemCode, a.ItemDescription, a.Rate, c.SDesc, c.NoOfDecimals
			Order by a.ItemCode, a.ItemDescription
		end
GO

