CREATE PROCEDURE [dbo].[PUR_Ins_LSTCSTGrouping]
	(@Description 	[varchar](30),
	 @ExprGroupID 	[int],
	 @Userid 	[varchar](10),
	 @Branchid 	[varchar](3),
	 @Compid 	[varchar](3))

AS 
BEGIN
declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		delete from PUR_LSTCSTGrouping where [Description] = @Description and ExprGroupID = @ExprGroupID and Branchid = @cBranchid
		and Compid = @Compid
		
		INSERT INTO [PUR_LSTCSTGrouping] 
			 ( [Description],
			 [ExprGroupID],
			 [Userid],
			 [Branchid],
			 [Compid]) 
		 
		VALUES 
			( @Description,
			 @ExprGroupID,
			 @Userid,
			 @cBranchid,
			 @Compid)
		
		FETCH NEXT FROM BranchidList into @cBranchid 
	END
 	
	close BranchidList
	deallocate BranchidList
END
GO

