CREATE PROCEDURE [dbo].[PUR_Ins_Request_Dtl]
	(@PRType 	[varchar](3),
	 @PRNo 	[int],
	 @PRDate 	[datetime],
	 @ItemCode 	[varchar](20),
	 @ReqQty 	[float],
	 @APRQty 	[float],
	 @Reason 	[varchar](100),
	 @HdrStatus 	[char](1),
	 @RevNo 	[int],
	 @RevDate 	[datetime],
	 @EffStatus 	[char](1),
	 @EffDate 	[datetime],
	 @TranStamp 	[datetime],
	 @UserID 	[varchar](10),
	 @BranchID 	[varchar](3),
	 @CompID 	[varchar](3),
	 @Finyear 	[varchar](20))

AS

SET NOCOUNT ON

	
	if @HdrStatus='E'
		Begin
			Select @RevNo=Isnull(Max(RevNo),0) from PUR_Request_Dtl where PRType=@PRType and PRNo=@PRNo and PRDate=@PRDate and Branchid=@Branchid and Compid=@Compid and ItemCode=@ItemCode
			Select @RevNo=@RevNo+1
		End

	Else
		Select @RevNo=Isnull(Max(RevNo),0) from PUR_Request_Dtl where PRType=@PRType and PRNo=@PRNo and PRDate=@PRDate and Branchid=@Branchid and Compid=@Compid and ItemCode=@ItemCode
		Select @RevDate=Isnull(RevDate,@RevDate) from PUR_Request_Dtl where PRType=@PRType and PRNo=@PRNo and PRDate=@PRDate and RevNo=@RevNo and Branchid=@Branchid and Compid=@Compid

 INSERT INTO [dbo].[PUR_Request_Dtl] 
	 ( [PRType],
	 [PRNo],
	 [PRDate],
	 [ItemCode],
	 [ReqQty],
	 [APRQty],
	 [Reason],
	 [RevNo],
	 [RevDate],
	 [EffStatus],
	 [EffDate],
	 [TranStamp],
	 [UserID],
	 [BranchID],
	 [CompID],
	 [Finyear]) 
 
VALUES 
	( @PRType,
	 @PRNo,
	 @PRDate,
	 @ItemCode,
	 @ReqQty,
	 @APRQty,
	 @Reason,
	 @RevNo,
	 @RevDate,
	 @EffStatus,
	 @EffDate,
	 @TranStamp,
	 @UserID,
	 @BranchID,
	 @CompID,
	 @Finyear)
GO

