CREATE PROCEDURE [dbo].[PUR_Invoice_Delete] (@InvType varchar(3), @InvNo int, @InvDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(15) )

AS

Begin

	SET NOCOUNT ON

	Declare @ErrNo int

	Begin Transaction

	Delete from PUR_PurchaseInvoice_Hdr 
	where DocType=@InvType and DocNo=@InvNo and DocDate=@InvDate and BranchID=@BranchID and CompID=@CompID

	Delete from PUR_PurchaseInvoice_Dtl 
	where DocType=@InvType and DocNo=@InvNo and DocDate=@InvDate and BranchID=@BranchID and CompID=@CompID
	
	Delete from COM_FormulaCalc_Hdr
	where DocType=@InvType and DocNo=@InvNo and DocDate=@InvDate and BranchID=@BranchID and CompID=@CompID
	
	Delete from COM_FormulaCalc_Dtl
	where DocType=@InvType and DocNo=@InvNo and DocDate=@InvDate and BranchID=@BranchID and CompID=@CompID

	Declare @FASCode varchar(12)
	Select @FASCode = @CompID+@BranchID
	
	Declare @VrType varchar(3)
	Declare @VrNo int
	Declare @VrDate datetime
	Declare @VrRoute varchar(42)
	
	Declare VrDtl Cursor for
		Select DocType, DocNo, DocDate, VrRoute from FAS_VoucherTranRef
		Where RefType=@InvType and RefNo=@InvNo and RefDate=@InvDate and CompCode=@FASCode

	OPEN VrDtl
	
	FETCH NEXT FROM VrDtl into @VrType, @VrNo, @VrDate, @VrRoute 

	WHILE @@FETCH_STATUS = 0

		Begin


			Execute [FAS_Del_Voucher] @VrNo, @VrDate, @VrRoute,  @FASCode

/*

			Delete from FAS_VoucherTranRef 
			where DocType=@VrType and DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and CompCode=@FASCode
			
			Delete from FAS_BillDetails 
			where DocType=@VrType and DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and CompCode=Left(@FASCode, 4)
			
			Delete from FAS_VoucherTranMast 
			where DocType=@VrType and DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and CompCode=@FASCode
			
			Delete from FAS_VoucherTranSub 
			where DocType=@VrType and DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and CompCode=@FASCode
			
			Delete from FAS_VoucherTranPay 
			where DocType=@VrType and DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and CompCode=@FASCode
		
			Delete from FAS_VoucherTranNarr 
			where DocType=@VrType and DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and CompCode=@FASCode
		
			Delete from FAS_VoucherTranCostCentre 
			where DocType=@VrType and DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and CompCode=@FASCode
		
			Execute FAS_Mod_VrTranReNum_From @VrNo, @VrRoute, -1, @FASCode
*/	



		End

	Close VrDtl
	Deallocate VrDtl

	Commit Transaction
End
GO

