CREATE PROCEDURE [dbo].[PUR_LaborPendingItem ](@OrderType varchar(3),@OrderNo int,@OrderDate datetime,@AsonDate datetime,@RptDate datetime,@Branchid varchar(3),@Compid varchar(3),@Finyear varchar(20))
 AS
SET NOCOUNT ON

	
BEGIN

SELECT    distinct  m.OrderType, m.OrderNo, m.OrderDate, m.SentItemCode, m.RecdItemCode, d .ItemDescription, d .UomDesc UOM, d .UomDecimal NoOfDec, 
                      m.ToBeRecdQty OrderQty, m.RatePer, m.Rate, m.AssRate,m.DcsrType,m.DcsrNo,m.DcsrDate
FROM         (SELECT DISTINCT 
                                              a.OrderType, a.OrderNo, a.OrderDate, a.SentItemCode, a.RecdItemCode, a.TobeRecdQty, isnull(b.DcsrType, '') DcsrType, isnull(b.DcsrNo, 0) 
                                              DcsrNo, isnull(b.DcsrDate, '') DcsrDate, isnull(b.DcsrQty, 0) DcsrQty, a.RatePer, a.Rate, a.AssRate, a.Branchid, a.Compid
                       FROM          dbo.fn_PUR_LaborOrder_Dtl(@AsonDate, @RptDate, @Branchid, @Compid, @Finyear) a LEFT OUTER JOIN
                                              dbo.fn_Pur_Dcsr(@AsonDate, @RptDate, @Branchid, @Compid, @Finyear) b ON a.OrderType = b.OrderType AND 
                                              a.OrderNO = b.ORderNo AND a.OrderDate = b.Orderdate AND a.ItemGroupKey = b.ItemGroupKey AND a.SentItemCode = b.SentItemCode AND
                                               a.RecdItemCode = b.RecdItemCode AND a.Branchid = b.Branchid AND a.Compid = b.Compid ) m LEFT OUTER JOIN
                          (SELECT     x.DcsrType, x.DcsrNo, x.DcsrDate, x.RecdItemCode, SUM(x.ScheduleQty) ScheduleQty, x.Branchid, x.Compid,
                                                   isnull(SUM(z.AcceptedQty + z.RejectionQty + z.ScrapQty), 0) CompletedQty
                            FROM          dbo.fn_Pur_Dcsr_Schedule(@AsonDate, @RptDate, @Branchid, @Compid, @Finyear) x LEFT OUTER JOIN
                                                   Rec_ReceiptEntry_Dtl z ON x.DcsrType = z.RefType AND x.DcsrNO = z.RefNO AND x.RequiredDate = z.RefDate AND 
                                                   x.RecdItemCode = z.ItemCode AND x.Branchid = z.Branchid AND x.Compid = z.Compid 
                            GROUP BY x.DcsrType, x.DcsrNo, x.DcsrDate, x.RecdItemCode, x.Branchid, x.Compid) n ON m.DcsrType = n.DcsrType AND 
                      m.DcsrNo = n.DcsrNo AND m.DcsrDate = n.DcsrDate AND m.RecdItemCode = n.RecdItemCode AND m.Branchid = n.Branchid AND 
                      m.Compid = n.Compid LEFT OUTER JOIN
                      Material_Master d ON d .ItemCode = m.RecdItemCode AND d .Branchid = m.Branchid AND d .Compid = m.Compid
WHERE     (ToBeRecdQty > isnull(CompletedQty, 0) OR
                      ToBeRecdQty = 0) AND m.OrderType = @OrderType AND m.OrderNo = @OrderNo AND m.OrderDate = @OrderDate AND m.Branchid = @Branchid AND 
                      m.compid = @Compid 
ORDER BY m.OrderType, m.OrderNo, m.OrderDate, m.DcsrType, m.DcsrNo, m.DcsrDate, m.RecdItemCode

end
GO

