SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[PUR_LaborPendingorder ](@AsonDate datetime,@RptDate datetime,@Branchid varchar(3),@Compid varchar(3),@Finyear varchar(20))
 AS
SET NOCOUNT ON

	
BEGIN

		SELECT     x.OrderType, x.OrderNo, x.OrderDate, x.StatusDate, x.CreatedDate, X.VendorCode,
                         		 (SELECT     v.PartyName  FROM          FAS_Party_Master v   WHERE      v.PartyCode = x.VendorCode AND v.BranchID = x.BranchID AND v.CompID = x.CompID) AS VendorName, 
                     		 CASE x.Status WHEN 'N' THEN 'New' WHEN 'M' THEN 'Amendment' WHEN 'A' THEN 'Authorised' WHEN 'H' THEN 'Hold' END AS Status, 
                      		x.OrderingType
	FROM         dbo.fn_PUR_Labororder_Hdr(@AsonDate, @RptDate, @Branchid, @Compid, @Finyear) x
	WHERE     x.Status <> 'C' AND x.OrderNo NOT IN
                          (SELECT DISTINCT x.OrderNo
                            FROM          (SELECT     OrderType, OrderNo, OrderDate, SUM(ToBeRecdQty) OrderQty
                                                    FROM          dbo.fn_PUR_Labororder_Dtl(@AsonDate, @RptDate, @Branchid, @Compid, @Finyear) where ToBeRecdQty<>0
                                                    GROUP BY OrderType, OrderNo, OrderDate) x LEFT OUTER JOIN
                                                       (SELECT     a.OrderType, a.OrderNo, a.OrderDate, SUM(b.CompletedQty) CompletedQty
                                                         FROM          (SELECT DISTINCT 
                                                                                                        b.OrderType, b.OrderNo, b.OrderDate, c.DcsrType, c.DcsrNo, c.DcsrDate, c.ItemGroupKey, b.SentItemCode, 
                                                                                                        c.RecdItemCode, isnull(SUM(ScheduleQty), 0) ScheduleQty, b.Branchid, b.Compid
                                                                                 FROM          dbo.fn_PUR_DCSR_Schedule(@AsonDate, @RptDate, @Branchid, @Compid, @Finyear) c LEFT OUTER JOIN
                                                                                                        dbo.fn_PUR_DCSR(@AsonDate, @RptDate, @Branchid, @Compid, @Finyear) b ON c.DcsrType = b.DcsrType AND
                                                                                                         c.DcsrNo = b.DcsrNo AND c.DcsrDate = b.DcsrDate AND c.ItemGroupKey = b.ItemGroupKey AND 
                                                                                                        c.RecdItemCode = b.RecdItemCode AND c.Branchid = b.Branchid AND c.Compid = b.Compid  
                                                                                                   
                                                                                 GROUP BY b.OrderType, b.OrderNo, b.OrderDate, c.DcsrType, c.DcsrNo, c.DcsrDate, c.ItemGroupKey, c.RecdItemCode, 
                                                                                                        b.SentItemCode, b.Branchid, b.Compid) a LEFT OUTER JOIN
                                                                                    (SELECT     DcsrType, DcsrNo, SentItemCode, SUM(ScheduleQty) CompletedQty, Branchid, Compid
                                                                                      FROM          dbo.fn_PUR_DCSR_Tran_Min(@AsonDate, @RptDate, @Branchid, @Compid, @Finyear)
                                                                                      GROUP BY DcsrType, DcsrNo, SentItemCode, Branchid, Compid) b ON a.DcsrType = b.DcsrType AND 
                                                                                a.DcsrNo = b.DcsrNo AND a.Branchid = b.Branchid AND a.Compid = b.Compid  
                                                                                
                                                         GROUP BY a.OrderType, a.OrderNo, a.OrderDate) z ON x.OrderType = z.OrderType AND x.OrderNo = z.OrderNo AND 
                                                   x.OrderDate = z.orderdate
                            WHERE      x.OrderQty <= isnull(x.OrderQty-z.CompletedQty, 0)
                            UNION
                            SELECT DISTINCT OrderNo
                            FROM         dbo.fn_PUR_DCSR(@AsonDate, @RptDate, @Branchid, @Compid, @Finyear) x
                            WHERE     DcsrNo IN
                                                      (SELECT     RefNo
                                                        FROM          REC_ReceiptEntry_Dtl z
                                                        WHERE      RefType = x.DcsrType AND ReceiptQty = 0 AND ReceiptDate IS NULL AND z.Branchid = x.Branchid AND 
                                                                               z.Compid = x.Compid ))

END
GO

/****** Object:  StoredProcedure [dbo].[PUR_LabourInvoice_Fil_RRBasedItem]    Script Date: 17/06/2026 11:30:40 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PUR_LabourInvoice_Fil_RRBasedItem](@OrderUserKey varchar(36)='', @ItemUserKey varchar(36)='', 
	@VendorCode int, @InwardType char(1), @ModuleCode int, @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                                                       
 As                                                        
BEGIN                                                        
 SET NOCOUNT ON;     

Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, b.ItemCode, c.ItemDescription, e.sentItemCode,
		IsNull((Select m1.ItemDescription From INV_Material_Master m1 Where m1.ItemCode=e.sentItemCode and m1.BranchID=e.BranchID and m1.CompID=e.CompID),'') As SentItemdesc, 
		IsNull(d.SDesc,'') As UOM, IsNull(d.NoOfDecimals,0) As NoDec, e.RatePer, IsNull(e.Rate, -1) as Rate, e.AssRate, b.AcceptedQty, 
		IsNull((Select Sum(Qty) From PUR_LaborInvoice_OrdRef c 
						Where c.RefNo=a.ReceiptEntryNo And c.RefDate=a.ReceiptEntryDate And c.RefType=a.ReceiptEntryType and c.ItemCode=b.ItemCode 
							and c.BranchID=a.BranchID and c.CompID=a.CompID),0) As InvoicedQty, 
		r.OrderType, r.OrderNo, r.OrderDate  
from REC_ReceiptEntry_Hdr a 
Left Outer Join REC_ReceiptEntry_Dtl b 
On a.ReceiptEntryNo=b.ReceiptEntryNo and a.ReceiptEntryDate=b.ReceiptEntryDate and a.ReceiptEntryType=b.ReceiptEntryType 
	and a.BranchID=b.BranchID and a.CompID=b.CompID 
Left Outer Join INV_Material_Master c 
	On b.ItemCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID 
Left Outer Join INV_UOM_Master d 
	On c.PurchaseUOM=d.Code and a.BranchID=d.BranchID and a.CompID=d.CompID 
Left Outer Join PUR_DCSR_Hdr q 
	On b.RefNo=q.DCSRNo and b.RefDate=q.DCSRDate and b.RefType=q.DCSRType and b.BranchID=q.BranchID and b.CompID=q.CompID 
Left Outer Join dbo.fn_PUR_LaborOrder_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) r 
	On r.OrderNo=q.OrderNo and r.Orderdate=q.OrderDate and r.OrderType=q.OrderType and r.BranchID=q.BranchID and r.CompID=q.CompID 
Left Outer Join (Select * From dbo.fn_PUR_LaborOrder_Dtl(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) l1
									Where (@OrderUserKey='' or (@OrderUserKey<>'' 
														and Exists(Select * From PUR_Invoice_Tmp t1
																				Where t1.UserKey=@OrderUserKey 
																					and (t1.OrdType+'-'+Convert(varchar,t1.OrdNo)+'/'+Convert(varchar(10),t1.OrdDate,121)=l1.OrderType+'-'+Convert(varchar,l1.OrderNo)+'/'+Convert(varchar(10),l1.OrderDate,121))
																					and t1.BranchID=@BranchID and t1.CompID=@CompID
																			))
													)
											and l1.BranchID=@BranchID and l1.CompID=@CompID 																												
	) e 
	On b.ItemGroupKey=e.ItemGroupKey /* and b.ItemCode=e.RecdItemCode*/ and r.OrderNo=e.OrderNo 
		and r.Orderdate=e.OrderDate and r.OrderType=e.OrderType and a.BranchID=e.BranchID and a.CompID=e.CompID 
Where a.VendorCode=@VendorCode and a.InwardType=@InwardType and b.AcceptedQty>0 
			and (@ItemUserKey='' or (@ItemUserKey<>'' 
														and Exists(Select * From COM_SelectList s1
																				Where s1.UserKey=@ItemUserKey 
																					and (s1.SelectStr=a.ReceiptEntryType+'-'+Convert(varchar,a.ReceiptEntryNo)+'/'+Convert(varchar(10),a.ReceiptEntryDate,121))
																					and s1.BranchID=@BranchID and s1.CompID=@CompID
																			))
													)
	--and a.ReceiptEntryType + ':' + Convert(varchar, a.ReceiptEntryNo)+ ':'+ Convert(Varchar(8), a.ReceiptEntryDate, 112) In('RR:1157:20220730','RR:1158:20220730','RR:1159:20220730','RR:1160:20220730','RR:1163:20220731','RR:1162:20220731') 
	and a.BranchID=@BranchID and a.CompID=@CompID 
Order by b.ItemCode, a.ReceiptEntryNo
END
GO

/****** Object:  StoredProcedure [dbo].[PUR_LabourInvoice_Hlp_RRBasedDocument]    Script Date: 17/06/2026 11:30:40 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PUR_LabourInvoice_Hlp_RRBasedDocument](@InwardType varchar(1)='', @VendorCode int,
@VendBillDate datetime, @ModuleCode int, @AsOnDate datetime, @RptDate datetime, 
@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                                                      
 As                                                      
BEGIN                                                      
 SET NOCOUNT ON;   
 
	Select Distinct y.ReceiptEntryType, y.ReceiptEntryNo, y.ReceiptEntryDate, 
			IsNull(r.OrderType,'') As OrderType, IsNull(r.OrderNo,0) As OrderNo, r.OrderDate, 
			IsNull(r.FormulaCode,0) As FormulaCode, IsNull(s.FrmLName,'') As FrmLName,  
			IsNull(r.PostingAc,0) As PostingAc  
	From (
			Select Distinct x.ReceiptEntryType, x.ReceiptEntryNo, x.ReceiptEntryDate, x.RefType, x.RefNo, x.RefDate,
					 x.BranchID, x.CompID --, x.Finyear 
			From (
					Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, b.RefType, b.RefNo, 
						b.RefDate, b.ItemCode, b.AcceptedDate, b.AcceptedQty, 
						IsNull((Select Sum(Qty) From PUR_LaborInvoice_Ref c 
										Where c.RefNo = a.ReceiptEntryNo and c.RefDate = a.ReceiptEntryDate 
													and c.RefType = a.ReceiptEntryType and c.itemcode = b.itemcode 
													and c.BranchID=a.BranchID and c.CompID=a.CompID), 0) As InvoicedQty,
						a.BranchID, a.CompID --, a.Finyear 
					From REC_ReceiptEntry_Hdr a 
					Left Outer Join REC_ReceiptEntry_Dtl b 
						On a.ReceiptEntryNo=b.ReceiptEntryNo and a.ReceiptEntryDate=b.ReceiptEntryDate 
								and a.ReceiptEntryType=b.ReceiptEntryType and a.BranchID=b.BranchID and a.CompID=b.CompID 
					Where a.VendorCode=@VendorCode and a.InwardType=@InwardType 
								and a.ReceiptEntryDate<=@VendBillDate and (b.AcceptedDate Is Not Null)
								and a.BranchID=@BranchID and a.CompID=@CompID
			) x  
		Where x.AcceptedQty>x.InvoicedQty and (x.AcceptedDate Is Not Null)
	) y 
	Left Outer Join PUR_DCSR_Hdr q 
		On y.RefNo=q.DCSRNo and y.RefDate=q.DCSRDate and y.RefType=q.DCSRType 
	Left Outer Join dbo.fn_PUR_LaborOrder_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) r 
		On r.OrderNo=q.OrderNo and r.Orderdate=q.OrderDate and r.OrderType=q.OrderType 
	Left Outer Join COM_FormulaMast_Hdr s 
		On r.FormulaCode=s.FrmID and s.ModuleCode=@ModuleCode and r.BranchID=s.BranchID and r.CompID=s.CompID 
	Where y.BranchID=@BranchID and y.CompID=@CompID -- and y.Finyear 
	Order by r.OrderDate, OrderNo
END
GO

/****** Object:  StoredProcedure [dbo].[PUR_LabourOrder_Hlp_AmendmentDocument]    Script Date: 17/06/2026 11:30:40 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PUR_LabourOrder_Hlp_AmendmentDocument](@FormType varchar(1), @Status varchar(3)='', @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20)='')    
As                                
BEGIN                                    
	SET NOCOUNT ON; 

	If @FormType='L'				-- LaborOrder
	 Begin
		Select Distinct a.OrderType, a.OrderNo, a.OrderDate, a.VendorCode, (Select b.PartyName from FAS_Party_Master b 
			where b.PartyCode=a.VendorCode and b.BranchID=a.BranchID and b.CompID=a.CompID) as VendorName, 
			a.Source, a.ValidFrom, a.ValidTo, a.CreditDays, a.OrderingType, a.Narration, a.SplInstruction, a.OrderValue, 
			Convert(varchar(19), a.CreatedDate, 120) as CreatedDate, 
			Case a.Status when 'N' then 'New' when 'M' then 'Amendment' when 'A' then 'Authorised' when 'H' then 'Hold' when 'S' then 'Short Close' when 'E' then 'Modify'End as Status, 
			a.Finyear 
		From dbo.fn_Pur_LaborOrder_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a 
		Where (((@Status='' or @Status='ALL') and a.Status In ('A', 'M', 'Y')) or (@Status='ME' and a.Status In('M')) or (@Status='AU' and a.Status In('A')))
			and a.BranchID=@BranchID and a.CompID=@CompID and (@Finyear='' or (@Finyear<>'' and a.Finyear=@Finyear))
	 End
	Else If @FormType='R'				-- ReWorkOrder
	 Begin
		Select Distinct a.OrderType, a.OrderNo, a.OrderDate, a.VendorCode, (Select b.PartyName from FAS_Party_Master b 
			where b.PartyCode=a.VendorCode and b.BranchID=a.BranchID and b.CompID=a.CompID) as VendorName, 
			a.Source, a.ValidFrom, a.ValidTo, a.CreditDays, a.OrderingType, a.Narration, a.SplInstruction, a.OrderValue, 
			Convert(varchar(19), a.CreatedDate, 120) as CreatedDate, 
			Case a.Status when 'N' then 'New' when 'M' then 'Amendment' when 'A' then 'Authorised' when 'H' then 'Hold' when 'S' then 'Short Close' when 'E' then 'Modify'End as Status, 
			a.Finyear 
		From dbo.fn_Pur_ReworkOrder_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a 
		Where (((@Status='' or @Status='ALL') and a.Status In ('A', 'M', 'Y')) or (@Status='ME' and a.Status In('M')) or (@Status='AU' and a.Status In('A')))
			and a.BranchID=@BranchID and a.CompID=@CompID and (@Finyear='' or (@Finyear<>'' and a.Finyear=@Finyear))
	 End
	Else If @FormType='D'				-- DismantlingOrder
	 Begin
		Select Distinct a.OrderType, a.OrderNo, a.OrderDate, a.VendorCode, (Select b.PartyName from FAS_Party_Master b 
			where b.PartyCode=a.VendorCode and b.BranchID=a.BranchID and b.CompID=a.CompID) as VendorName, 
			a.Source, a.ValidFrom, a.ValidTo, a.CreditDays, a.OrderingType, a.Narration, a.SplInstruction, a.OrderValue, 
			Convert(varchar(19), a.CreatedDate, 120) as CreatedDate, 
			Case a.Status when 'N' then 'New' when 'M' then 'Amendment' when 'A' then 'Authorised' when 'H' then 'Hold' when 'S' then 'Short Close' when 'E' then 'Modify'End as Status, 
			a.Finyear 
		From dbo.fn_Pur_DismantlingOrder_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a 
		Where (((@Status='' or @Status='ALL') and a.Status In ('A', 'M', 'Y')) or (@Status='ME' and a.Status In('M')) or (@Status='AU' and a.Status In('A')))
			and a.BranchID=@BranchID and a.CompID=@CompID and (@Finyear='' or (@Finyear<>'' and a.Finyear=@Finyear))
	 End
END
GO

/****** Object:  StoredProcedure [dbo].[PUR_LabourOrder_Hlp_DtlAuthorization]    Script Date: 17/06/2026 11:30:40 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PUR_LabourOrder_Hlp_DtlAuthorization](@FormType varchar(1), @OptAmend bit='0', 
	@FromDate datetime, @ToDate datetime, @Status varchar(3)='', @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20)='')      
As                                  
BEGIN                                      
	SET NOCOUNT ON;   

	Declare @AsOnDate2 datetime;
	Declare @RptDate2 datetime;

	SET @AsOnDate2=Convert(datetime,(Convert(varchar(10),@AsOnDate,121)+' '+'23:59:59'),121);
	SET @RptDate2=Convert(datetime,Convert(varchar(10),@AsOnDate,121),121);

	If @OptAmend='1'		-- Option Amendment 
	 Begin
		Select Distinct a.OrderType, a.OrderNo, a.OrderDate, a.SentItemCode As SentItem, 
			b.ItemDescription As SentDesc, a.RecdItemCode As RecdItem, c.ItemDescription As RecdDesc,
			c.PurchaseUOMDesc As UOM, c.PurchaseUOMDecimal As NoOfDec, a.ToBeRecdQty, a.RatePer, 
			a.Rate,a.Status, a.ItemGroupKey, 
			IsNull((Select top 1 d.RelationType From PUR_SubCont_ItemMaster d 
					Where d.ItemGroupKey=a.ItemGroupKey and d.BranchID=a.BranchID 
						and d.CompID=a.CompID),'1-1') As Relation
		From dbo.fn_Pur_LaborOrder_Dtl(@AsOnDate2, @RptDate2, @BranchID, @CompID, @Finyear) a
		Inner Join Pur_Order_Amendment f 
			On a.OrderType=f.OrderType and a.OrderNo=f.OrderNo and a.OrderDate=f.OrderDate
				and a.BranchID=f.BranchID and a.compID=f.compID
		Left Outer Join INV_Material_Master b
		  On a.SentItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
		Left Outer Join Material_Master c 
			On a.RecdItemCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID
		Where (f.AmendmentDate Between @FromDate and @ToDate) and a.BranchID=@BranchID and a.CompID=@CompID
		Order by a.ItemGroupKey, a.SentItemCode
	 End
	Else			-- Option Authorization 
	 Begin
		If @FormType=1		-- Labor Order Authorization
		 Begin
			Select Distinct a.OrderType, a.OrderNo, a.OrderDate, a.SentItemCode As SentItem, 
				b.ItemDescription As SentDesc, a.RecdItemCode As RecdItem, c.ItemDescription As RecdDesc,
				c.PurchaseUOMDesc As UOM, c.PurchaseUOMDecimal As NoOfDec, a.ToBeRecdQty, a.RatePer, 
				a.Rate,a.Status, a.ItemGroupKey, 
				IsNull((Select top 1 d.RelationType From PUR_SubCont_ItemMaster d 
						Where d.ItemGroupKey=a.ItemGroupKey and d.BranchID=a.BranchID 
							and d.CompID=a.CompID),'1-1') As Relation
			From dbo.fn_Pur_LaborOrder_Dtl(@AsOnDate2, @RptDate2, @BranchID, @CompID, @Finyear) a
			Left Outer Join INV_Material_Master b
			  On a.SentItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
			Left Outer Join Material_Master c 
				On a.RecdItemCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID
			Where (a.OrderDate Between @FromDate and @ToDate) and a.BranchID=@BranchID and a.CompID=@CompID
			Order by a.ItemGroupKey, a.SentItemCode
		 End	 
		Else If @FormType=3		-- Rework Order Authorization
		  Begin
			Select Distinct a.OrderType, a.OrderNo, a.OrderDate, a.SentItemCode As SentItem, 
				b.ItemDescription As SentDesc, a.RecdItemCode As RecdItem, c.ItemDescription As RecdDesc,
				c.PurchaseUOMDesc As UOM, c.PurchaseUOMDecimal As NoOfDec, a.ToBeRecdQty, a.RatePer, 
				a.Rate,a.Status, a.ItemGroupKey, 
				IsNull((Select top 1 d.RelationType From PUR_SubCont_ItemMaster d 
						Where d.ItemGroupKey=a.ItemGroupKey and d.BranchID=a.BranchID 
							and d.CompID=a.CompID),'1-1') As Relation
			From dbo.fn_Pur_ReworkOrder_Dtl(@AsOnDate2, @RptDate2, @BranchID, @CompID, @Finyear) a
			Left Outer Join INV_Material_Master b
			  On a.SentItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
			Left Outer Join Material_Master c 
				On a.RecdItemCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID
			Where (a.OrderDate Between @FromDate and @ToDate) and a.BranchID=@BranchID and a.CompID=@CompID
			Order by a.ItemGroupKey, a.SentItemCode
		  End
		Else If @FormType=6		-- Dismantling Order Authorization
		  Begin
			Select Distinct a.OrderType, a.OrderNo, a.OrderDate, a.SentItemCode As SentItem, 
				b.ItemDescription As SentDesc, a.RecdItemCode As RecdItem, c.ItemDescription As RecdDesc,
				c.PurchaseUOMDesc As UOM, c.PurchaseUOMDecimal As NoOfDec, a.ToBeRecdQty, a.RatePer, 
				a.Rate,a.Status, a.ItemGroupKey, 
				IsNull((Select top 1 d.RelationType From PUR_SubCont_ItemMaster d 
						Where d.ItemGroupKey=a.ItemGroupKey and d.BranchID=a.BranchID 
							and d.CompID=a.CompID),'1-1') As Relation
			From dbo.fn_Pur_DismantlingOrder_Dtl(@AsOnDate2, @RptDate2, @BranchID, @CompID, @Finyear) a
			Left Outer Join INV_Material_Master b
			  On a.SentItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
			Left Outer Join Material_Master c 
				On a.RecdItemCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID
			Where (a.OrderDate Between @FromDate and @ToDate) and a.BranchID=@BranchID and a.CompID=@CompID
			Order by a.ItemGroupKey, a.SentItemCode
		  End
	 End
END
GO

/****** Object:  StoredProcedure [dbo].[PUR_LabourOrder_Hlp_HdrAuthorization]    Script Date: 17/06/2026 11:30:40 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PUR_LabourOrder_Hlp_HdrAuthorization](@FormType varchar(1), @OptAmend bit='0', 
	@FromDate datetime, @ToDate datetime, @Status varchar(3)='', @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20)='')      
As                                  
BEGIN                                      
	SET NOCOUNT ON;   

	Declare @AsOnDate2 datetime;
	Declare @RptDate2 datetime;

	SET @AsOnDate2=Convert(datetime,(Convert(varchar(10),@AsOnDate,121)+' '+'23:59:59'),121);
	SET @RptDate2=Convert(datetime,Convert(varchar(10),@AsOnDate,121),121);

	If @OptAmend='1'		-- Option Amendment 
	 Begin
		Select Distinct a.OrderType, a.OrderNo, a.OrderDate, 
			Case a.Status when 'N' then 'New' 
				when 'M' then 'Amendment' 
				when 'A' then 'Authorised' 
				when 'H' then 'Hold'when 'E' then 'Modified' End As Status, 
			a.StatusDate, a.CreatedDate, a.OrderingType, b.PartyName As VendorName,
			a.CreatedDate, a.TranStamp
		From dbo.fn_Pur_LaborOrder_Hdr(@AsOnDate2, @RptDate2, @BranchID, @CompID, @Finyear) a
		Left Outer Join FAS_Party_Master b
			On a.VendorCode=b.PartyCode and a.BranchID=b.BranchID and a.CompID=b.CompID
		Inner Join Pur_Order_Amendment f 
			On a.OrderType=f.OrderType and a.OrderNo=f.OrderNo and a.OrderDate=f.OrderDate
				and a.BranchID=f.BranchID and a.compID=f.compID				
		Where (f.AmendmentDate Between @FromDate and @ToDate)
			and f.AmendmentNo=(Select Max(g.AmendmentNo) From Pur_Order_Amendment g
							Where g.AmendmentType=f.AmendmentType and g.AmendmentDate=f.AmendmentDate 
								and g.OrderType=f.OrderType and g.OrderNo=f.OrderNo and g.OrderDate=f.OrderDate
								and g.BranchID=f.BranchID and g.CompID=f.CompID)
			and a.Status In('N','M','A','H','E')
			and a.BranchID=@BranchID and a.CompID=@CompID
		Order by a.OrderDate, a.OrderNo
	 End
	Else			-- Option Authorization 
	 Begin
		If @FormType=1		-- Labor Order Authorization
		  Begin
			Select Distinct a.OrderType, a.OrderNo, a.OrderDate, 
				Case a.Status when 'N' then 'New' 
					when 'M' then 'Amendment' 
					when 'A' then 'Authorised' 
					when 'H' then 'Hold'when 'E' then 'Modified' End As Status, 
				a.StatusDate, a.CreatedDate, a.OrderingType, b.PartyName As VendorName,
				a.CreatedDate, a.TranStamp
			From dbo.fn_Pur_LaborOrder_Hdr(@AsOnDate2, @RptDate2, @BranchID, @CompID, @Finyear) a
			Left Outer Join FAS_Party_Master b
				On a.VendorCode=b.PartyCode and a.BranchID=b.BranchID and a.CompID=b.CompID
			Where (a.OrderDate Between @FromDate and @ToDate) 
				and a.Status In ('N', 'M','H','E')		-- a.Status In('N','M','A','H','E') 
				and a.BranchID=@BranchID and a.CompID=@CompID
			Order by a.OrderDate, a.OrderNo
		  End
		Else If @FormType=3		-- Rework Order Authorization
		  Begin
			Select Distinct a.OrderType, a.OrderNo, a.OrderDate, 
				Case a.Status when 'N' then 'New' 
					when 'M' then 'Amendment' 
					when 'A' then 'Authorised' 
					when 'H' then 'Hold'when 'E' then 'Modified' End As Status, 
				a.StatusDate, a.CreatedDate, a.OrderingType, b.PartyName As VendorName,
				a.CreatedDate, a.TranStamp
			From dbo.fn_Pur_ReworkOrder_Hdr(@AsOnDate2, @RptDate2, @BranchID, @CompID, @Finyear) a 
			Left Outer Join FAS_Party_Master b
				On a.VendorCode=b.PartyCode and a.BranchID=b.BranchID and a.CompID=b.CompID
			Where (a.OrderDate Between @FromDate and @ToDate) 
				and a.Status In ('N', 'M','H','E')		-- a.Status In('N','M','A','H','E') 
				and a.BranchID=@BranchID and a.CompID=@CompID
			Order by a.OrderDate, a.OrderNo
		  End
		Else If @FormType=6		-- Dismantling Order Authorization
		  Begin
			Select Distinct a.OrderType, a.OrderNo, a.OrderDate, 
				Case a.Status when 'N' then 'New' 
					when 'M' then 'Amendment' 
					when 'A' then 'Authorised' 
					when 'H' then 'Hold'when 'E' then 'Modified' End As Status, 
				a.StatusDate, a.CreatedDate, a.OrderingType, b.PartyName As VendorName,
				a.CreatedDate, a.TranStamp
			From dbo.fn_Pur_DismantlingOrder_Hdr(@AsOnDate2, @RptDate2, @BranchID, @CompID, @Finyear) a 
			Left Outer Join FAS_Party_Master b
				On a.VendorCode=b.PartyCode and a.BranchID=b.BranchID and a.CompID=b.CompID
			Where (a.OrderDate Between @FromDate and @ToDate) 
				and a.Status In ('N', 'M','H','E')		-- a.Status In('N','M','A','H','E')  
				and a.BranchID=@BranchID and a.CompID=@CompID
			Order by a.OrderDate, a.OrderNo
		  End
	 End
END
GO

/****** Object:  StoredProcedure [dbo].[PUR_LabourOrder_Hlp_ModifyDocument]    Script Date: 17/06/2026 11:30:40 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
