CREATE PROCEDURE [dbo].[PUR_Pending_Order ](@AsonDate datetime,@RptDate datetime,@OrdFrom datetime,@OrdTo datetime,@Branchid varchar(3),@Compid varchar(3),@Finyear varchar(20))
 AS
SET NOCOUNT ON

	BEGIN
	select distinct  x.OrderType, x.OrderNo, x.OrderDate,x.CreatedDate,X.VendorCode,(
	Select v.PartyName from FAS_Party_Master v where v.PartyCode=x.VendorCode and v.BranchID=x.BranchID and v.CompID=x.CompID) as VendorName,
	Case x.Status when 'N' then 'New' when 'M' then 'Amendment' when 'A' then 'Authorised' when 'H' then 'Hold' End as Status, x.OrderingType
	from dbo.fn_PUR_PurchaseOrder_Hdr(@AsonDate, @RptDate, @Branchid, @Compid, @Finyear)x
	inner join
	(SELECT distinct a.OrderType,a.OrderNo,a.OrderDate,a.ItemCode,a.Qty,isnull(sum(c.AcceptedQty+ScrapQty+RejectedQty),0)CQty 
	FROM dbo.fn_PUR_PurchaseOrder_Dtl(@AsonDate, @RptDate, @Branchid, @Compid, @Finyear)a
	left outer join dbo.fn_PUR_Schedule(@AsonDate, @RptDate, @Branchid, @Compid, @Finyear)b
	on a.OrderType=b.OrderType and a.OrderNo=b.OrderNo and a.OrderDate=b.OrderDate and a.ItemCode=b.Itemcode
	left outer join PUR_SCHEDULE_RECEIVE_DTL c
	on b.ScheduleType=c.ScheduleType and b.ScheduleNo=c.ScheduleNo and b.ScheduleDate=c.ScheduleDate
	and b.ItemCode=c.ItemCode and b.Branchid=c.Branchid and b.Compid=c.Compid
	where a.Status<>'C' /*and a.OrderNo not in (
	select distinct a.OrderNo from dbo.fn_Pur_Schedule(@AsonDate, @RptDate, @Branchid, @Compid, @Finyear)a
	where ScheduleNo in (select distinct RefNo from REC_Receiptentry_Dtl where ReceiptQty=0 and ReceiptDate is null 
	and RefType=a.ScheduleType) and Branchid=@Branchid and Compid=@Compid)*/
	and a.OrderDate between @OrdFrom and @OrdTo
	group by a.OrderType,a.OrderNo,a.OrderDate,a.ItemCode,a.Qty 
	having Qty=0 or (Qty<>0 and Qty>isnull(sum(c.AcceptedQty+ScrapQty+RejectedQty),0)))z
	on x.OrderType=z.OrderType and x.OrderNo=z.OrderNo and x.OrderDate=z.OrderDate 	
		
END
GO

