CREATE PROCEDURE [dbo].[PUR_PendingItem ](@OrderType varchar(3),@OrderNo int,@OrderDate datetime,@AsonDate datetime,@RptDate datetime,@Branchid varchar(3),@Compid varchar(3),@Finyear varchar(20))
 AS
SET NOCOUNT ON

	
BEGIN
	select k.ItemCode,l.ItemDescription,l.PurchaseUOMDesc as UOM,l.PurchaseUomDecimal as NoOfDec,k.Qty,k.RatePer,k.Rate,k.AssRate from 
		dbo.fn_PUR_purchaseorder_Dtl(@AsonDate,@RptDate,@Branchid,@Compid,@Finyear)k
		left outer join Material_Master l
		on k.ItemCode=l.ItemCode and k.Branchid=l.Branchid and k.Compid=l.Compid
		where k.Status<>'C' and k.OrderType=@OrderType and k.OrderNo=@OrderNo and k.OrderDate=@OrderDate
		and k.branchid=@Branchid and k.compid=@Compid
		and k.ItemCode not in (
					select ItemCode from (select z.OrderType,z.OrderNo,z.OrderDate,ItemCode,sum(OrderQty)OrderQty,sum(CompletedQty)CompletedQty from (
						select a.OrderType,a.OrderNo,a.OrderDate,a.ItemCode,b.Qty as OrderQty,c.CompletedQty,a.Branchid,a.Compid from (
							select OrderType,OrderNo,Orderdate,ItemCode,sum(ScheduleQty)ScheduleQty,Branchid,Compid from 
							dbo.fn_Pur_Schedule(@AsonDate,@RptDate,@Branchid,@Compid,@Finyear)
							group by OrderType,OrderNo,Orderdate,ItemCode,Branchid,Compid) a
							left outer join 
								(select OrderType,OrderNo,Orderdate,ItemCode,sum(Qty)Qty,Branchid,Compid from 
									dbo.fn_Pur_PurchaseOrder_Dtl(@AsonDate,@RptDate, @Branchid, @Compid, @Finyear)
								group by OrderType,OrderNo,Orderdate,ItemCode,Branchid,Compid) b
								on a.OrderType=b.OrderType and a.OrderNo=b.OrderNo and a.Orderdate=b.Orderdate and a.ItemCode=b.ItemCode
								and a.Branchid=b.Branchid and a.Compid=b.Compid
							left outer join
								(select z.OrderType,z.OrderNo,z.OrderDate,x.ItemCode,x.CompletedQty,x.Branchid,x.Compid from (
									select RefType,RefNo,RefDate,ItemCode,sum(AcceptedQty+RejectionQty+ScrapQty)CompletedQty,Branchid,Compid from REC_Receiptentry_Dtl
									group by RefType,RefNo,RefDate,ItemCode,Branchid,Compid)x--completed qty
									left outer join dbo.fn_Pur_Schedule(@AsonDate,@RptDate,@Branchid,@Compid,@Finyear)z
										on x.RefType=z.ScheduleType and x.RefNo=z.ScheduleNo and x.RefDate=z.RequiredDate
										and x.Branchid=z.Branchid and x.Compid=z.Compid and x.ItemCode=z.ItemCode)c
							on a.OrderType=c.OrderType and a.OrderNo=c.OrderNo and a.Orderdate=c.Orderdate and a.ItemCode=c.ItemCode)z
							where z.OrderQty<>0 and z.OrderType=k.OrderType and z.OrderNo=k.OrderNo and z.OrderDate=k.OrderDate 
							and OrderQty<=completedQty and Branchid=@Branchid and Compid=@Compid
							group by z.OrderType,z.OrderNo,z.OrderDate,ItemCode)f)
							order by k.ItemCode



END
GO

/****** Object:  StoredProcedure [dbo].[PUR_Pendingorder ]    Script Date: 17/06/2026 11:30:41 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[PUR_Pendingorder ](@AsonDate datetime,@RptDate datetime,@Branchid varchar(3),@Compid varchar(3),@Finyear varchar(20))
 AS
SET NOCOUNT ON

	
BEGIN
	select distinct * from (
			Select x.OrderType, x.OrderNo, x.OrderDate,x.CreatedDate,X.VendorCode,x.VendorName,
					Case x.Status when 'N' then 'New' when 'M' then 'Amendment' when 'A' then 'Authorised' when 'H' then 'Hold' End as Status, x.OrderingType From (
			
			Select a.VendorCode,(Select v.PartyName from FAS_Party_Master v where v.PartyCode=a.VendorCode 
							and v.BranchID=a.BranchID and v.CompID=a.CompID) as VendorName, a.OrderType, a.OrderNo, a.OrderDate, a.ItemCode, d.Qty, sum(a.ScheduleQty) ScheduleQty , sum(isNull(c.AcceptedQty,0)) AcceptedQty,  
			 b.Status,b.CreatedDate,b.OrderingType from dbo.fn_PUR_SCHEDULE(@AsonDate, @RptDate, @Branchid, @Compid, @Finyear) a 
			Left Outer join PUR_SCHEDULE_RECEIVE_DTL c On c.RequiredDate=a.RequiredDate and c.ItemCode=a.ItemCode  
			and c.ScheduleNo=a.ScheduleNo and c.ScheduleDate=a.ScheduleDate and  c.ScheduleType=a.ScheduleType  
			and c.Branchid=a.Branchid and  c.Compid=a.Compid
			left outer join dbo.fn_PUR_PurchaseOrder_Hdr (@AsonDate, @RptDate, @Branchid, @Compid, @Finyear) b
			on a.OrderType = b.OrderType and a.OrderNo = b.OrderNo and a.OrderDate = b.OrderDate and a.Branchid = b.Branchid 
			and a.Compid = b.Compid 
			
			left outer join dbo.fn_PUR_PurchaseOrder_Dtl (@AsonDate, @RptDate, @Branchid, @Compid, @Finyear) d
			on a.OrderType = d.OrderType and a.OrderNo = d.OrderNo and a.OrderDate = d.OrderDate and a.ItemCode = d.ItemCode 
			and a.Branchid = d.Branchid and a.Compid = d.Compid
			
			where b.Status <> 'C' and a.Branchid = @Branchid and a.Compid = @Compid
			Group by a.VendorCode, a.OrderType, a.OrderNo, a.OrderDate, a.ItemCode, d.Qty, b.Status,b.CreatedDate,b.OrderingType,
			a.BranchID,a.CompID
			
			) x  where (x.Qty > 0 and (x.Qty - x.AcceptedQty) >0) or (x.Qty = 0))z
			where z.OrderNo not in(select distinct a.OrderNo from dbo.fn_Pur_Schedule(@AsonDate,@RptDate,@Branchid,@Compid,@Finyear)a
							where ScheduleNo in (select distinct RefNo from REC_Receiptentry_Dtl where ReceiptQty=0 and ReceiptDate is null 
							and RefType=a.ScheduleType) and Branchid=@Branchid and Compid=@Compid)
			order by z.OrderType, z.OrderNo, z.OrderDate

			
END
GO

/****** Object:  StoredProcedure [dbo].[PUR_PurchaseInvoice_Fil_Item]    Script Date: 17/06/2026 11:30:41 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


CREATE PROCEDURE [dbo].[PUR_PurchaseInvoice_Fil_Item]
(@UserKey Varchar(42),@RRUserKey Varchar(42), @VendorCode int,  @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))        
--@RRDet Varchar(300),  
As        
      
BEGIN      
        
 SET NOCOUNT ON;

Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.ItemCode, c.ItemDescription, d.SDesc as UOM, d.NoOfDecimals as NoDec, e.RatePer, isNull(e.Rate, -1) as Rate, e.AssRate, 
a.AcceptedQty as AcceptedQty, a.InvoicedQty, e.Seq, r.OrderType, r.OrderNo, r.Orderdate 
From
(
Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, b.RefType, b.RefNo, b.RefDate, b.ScheduleDate, b.ItemCode, sum(b.AcceptedQty) as AcceptedQty, 
	isNull((Select Sum(Qty) from PUR_PurchaseInvoice_OrdRef c Where c.RefNo=a.ReceiptEntryNo And c.RefDate=a.ReceiptEntryDate And c.RefType=a.ReceiptEntryType And c.ItemCode=b.ItemCode and c.BranchID=a.BranchID and c.CompID=a.CompID), 0) as InvoicedQty,
	a.BranchID, a.CompID
from REC_ReceiptEntry_Hdr a 
Left Outer Join REC_ReceiptEntry_Dtl b 
On a.ReceiptEntryNo=b.ReceiptEntryNo and a.ReceiptEntryDate=b.ReceiptEntryDate and a.ReceiptEntryType=b.ReceiptEntryType and a.BranchID=b.BranchID and a.CompID=b.CompID 
Where a.VendorCode=@VendorCode and a.InwardType='P'  and b.AcceptedQty > 0 and a.BranchID=@BranchID and a.CompID=@CompID 
	 and a.ReceiptEntryType + ':' + Convert(varchar, a.ReceiptEntryNo)+ ':'+ Convert(Varchar(8), a.ReceiptEntryDate, 112)  in 
	 -- (@RRDet) 
		 (
	 Select SelectStr From Com_SelectList       
					Where UserKey = @RRUserKey and BranchID = @BranchID and CompID = @CompID  
					) 
	 Group by a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, b.RefType, b.RefNo, b.RefDate, b.ScheduleDate, b.ItemCode, a.BranchID, a.CompID
Union All

Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate,  a.RefType, a.RefNo, a.RefDate, a.ScheduleDate, a.ItemCode, a.InspectionQty as AcceptedQty, 0 as InvoicedQty, a.BranchID, a.CompID 
From [fn_REC_Get_RRDocument_WholeLotRejected] (@BranchID, @CompID, @Finyear) a
Where a.VendorCode=@VendorCode and a.InwardType='P'  and a.ReceiptEntryType + ':' + Convert(varchar, a.ReceiptEntryNo)+ ':'+ Convert(Varchar(8), a.ReceiptEntryDate, 112)  in 
 -- (@RRDet) 
		 (
	 Select SelectStr From Com_SelectList       
					Where UserKey = @RRUserKey and BranchID = @BranchID and CompID = @CompID  
					)  and
	Not Exists    
    (    
		Select * From PUR_PurchaseInvoice_Ref s    
		Where s.RefNo=a.ReceiptEntryNo And s.RefDate=a.ReceiptEntryDate And s.RefType=a.ReceiptEntryType and s.Itemcode=a.Itemcode and s.BranchID=@BranchID and s.CompID=@CompID   
    )  

) a
Left Outer Join INV_Material_Master c 
On a.ItemCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID 
Left Outer Join INV_UOM_Master d 
On c.PurchaseUOM=d.Code and a.BranchID=d.BranchID and a.CompID=d.CompID 
Left Outer Join dbo.fn_PUR_Schedule(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) q 
On a.RefNo=q.ScheduleNo and a.RefDate=q.ScheduleDate and a.RefType=q.ScheduleType and a.ItemCode=q.ItemCode and a.ScheduleDate=q.RequiredDate and a.BranchID=q.BranchID and a.CompID=q.CompID 
Left Outer Join dbo.fn_PUR_PurchaseOrder_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) r 
On r.OrderNo=q.OrderNo and r.Orderdate=q.OrderDate and r.OrderType=q.OrderType and r.BranchID=q.BranchID and r.CompID=q.CompID 
Left Outer Join (Select * from dbo.fn_PUR_PurchaseOrder_Dtl(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) x  
					where Exists (Select * From PUR_Invoice_Tmp y Where y.UserKey=@UserKey and x.OrderNo=y.OrdNo and x.OrderDate=y.OrdDate and x.OrderType=y.OrdType and y.BranchID = x.BranchID and y.CompID = x.CompID)
					) e 
On a.ItemCode=e.ItemCode and r.OrderNo=e.OrderNo and r.Orderdate=e.OrderDate and r.OrderType=e.OrderType and r.BranchID=e.BranchID and r.CompID=e.CompID
Where  a.BranchID=@BranchID and a.CompID=@CompID 
