Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, b.RefType, b.RefNo, b.RefDate, b.ScheduleDate, b.ItemCode, sum(b.AcceptedQty) as AcceptedQty, 
