	 -- (@RRDet) 
		 (
	 Select SelectStr From Com_SelectList       
					Where UserKey = @RRUserKey and BranchID = @BranchID and CompID = @CompID  
					) 
	 Group by a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, b.RefType, b.RefNo, b.RefDate, b.ScheduleDate, b.ItemCode, a.BranchID, a.CompID
Union All

Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate,  a.RefType, a.RefNo, a.RefDate, a.ScheduleDate, a.ItemCode, a.InspectionQty as AcceptedQty, 0 as InvoicedQty, a.BranchID, a.CompID 
