Where a.VendorCode=@VendorCode and a.InwardType='P'  and a.ReceiptEntryType + ':' + Convert(varchar, a.ReceiptEntryNo)+ ':'+ Convert(Varchar(8), a.ReceiptEntryDate, 112)  in 
