/****** Object:  StoredProcedure [dbo].[PUR_PurchaseInvoice_Hlp_RR]    Script Date: 17/06/2026 11:30:41 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PUR_PurchaseInvoice_Hlp_RR](@ModuleCode int, @VendorCode int, @AsOnDate datetime, 
 @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))                  
As                  
BEGIN                  
    SET NOCOUNT ON;  
  
    Select Distinct p.ReceiptEntryType, p.ReceiptEntryNo, p.ReceiptEntryDate, r.OrderType, r.OrderNo, r.OrderDate, 
				r.FormulaCode, s.FrmLName, r.PostingAc   
    From   
    (  
        Select Distinct x.ReceiptEntryType, x.ReceiptEntryNo, x.ReceiptEntryDate, x.RefType, 
						x.RefNo, x.RefDate   
        From    
        (  
            Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.RefType, a.RefNo, a.RefDate, 
									a.ItemCode, a.AcceptedQty, a.InvoicedQty  
            From  
            (  
                Select re.ReceiptEntryType, re.ReceiptEntryNo, re.ReceiptEntryDate, re.RefType, re.RefNo, re.RefDate, 
										re.ItemCode, re.AcceptedQty, isNull(Sum(pv.Qty), 0) As InvoicedQty   
                From REC_ReceiptEntry_vw re   
                Left Outer Join PUR_PurchaseInvoice_Ref pv   
                    On re.ReceiptEntryNo=pv.RefNo And re.ReceiptEntryDate=pv.RefDate and re.ReceiptEntryType=pv.RefType 
											and re.itemcode=pv.itemcode and re.BranchID=pv.BranchID and re.CompID=pv.CompID   
                Where re.VendorCode=@VendorCode and re.InwardType='P' and re.BranchID=@BranchID 
										and re.CompID=@CompID and re.AcceptedQty>0 and (re.AcceptedDate Is Not Null) 
                Group by re.ReceiptEntryType, re.ReceiptEntryNo, re.ReceiptEntryDate, re.RefType, re.RefNo, 
										re.RefDate, re.ItemCode, re.AcceptedQty   
            ) a  
            Where a.AcceptedQty>a.InvoicedQty 
  
						UNION ALL 
  
            Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.RefType, a.RefNo, a.RefDate, a.ItemCode, 
									a.InspectionQty, 0 As InvoicedQty   
            From dbo.fn_REC_Get_RRDocument_WholeLotRejected(@BranchID, @CompID, @Finyear) a  
            Where a.VendorCode=@VendorCode and a.InwardType='P'   
                and Not Exists( Select * From PUR_PurchaseInvoice_Ref s      
																Where s.RefNo=a.ReceiptEntryNo And s.RefDate=a.ReceiptEntryDate And s.RefType=a.ReceiptEntryType 
																		and s.Itemcode=a.Itemcode and s.BranchID=@BranchID and s.CompID=@CompID      
															)    
        ) x   
        --Where AcceptedQty > InvoicedQty   
    ) p  
    Left Outer Join dbo.fn_PUR_Schedule(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) q   
			On p.RefNo=q.ScheduleNo and p.RefDate=q.ScheduleDate and p.RefType=q.ScheduleType   
    Left Outer Join dbo.fn_PUR_PurchaseOrder_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) r   
			On r.OrderNo=q.OrderNo and r.Orderdate=q.OrderDate and r.OrderType=q.OrderType   
    Left Outer Join COM_FormulaMast_Hdr s   
			On r.FormulaCode=s.FrmID and s.ModuleCode=@ModuleCode and r.BranchID=s.BranchID and r.CompID=s.CompID  
    Order by r.OrderNo  
  END
GO

