As        
      
BEGIN      
        
 SET NOCOUNT ON;

 Select distinct p.ReceiptEntryType, p.ReceiptEntryNo, p.ReceiptEntryDate, r.OrderType, r.OrderNo, r.OrderDate, r.FormulaCode, s.FrmLName, r.PostingAc 
 from 
 (
 Select distinct ReceiptEntryType, ReceiptEntryNo, ReceiptEntryDate, RefType, RefNo, RefDate 
 from  
 (
 Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.RefType, a.RefNo, a.RefDate, a.ItemCode, a.AcceptedQty, isNull(Sum(c.Qty), 0) as InvoicedQty 
 from REC_ReceiptEntry_vw a 
 Left Outer Join PUR_PurchaseInvoice_Ref c  
 On c.RefNo=a.ReceiptEntryNo And c.RefDate=a.ReceiptEntryDate And c.RefType=a.ReceiptEntryType and c.itemcode=a.itemcode and c.BranchID=a.BranchID and c.CompID=a.CompID 
 Where a.VendorCode=@VendorCode and a.InwardType='P' and a.BranchID=@BranchID and a.CompID=@CompID  and a.AcceptedQty>0
 Group by a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.RefType, a.RefNo, a.RefDate, a.ItemCode, a.AcceptedQty 
 
 Union All

Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.RefType, a.RefNo, a.RefDate, a.ItemCode, a.InspectionQty, 0 as InvoicedQty 
From [fn_REC_Get_RRDocument_WholeLotRejected] (@BranchID, @CompID, @Finyear) a
Where a.VendorCode=@VendorCode and a.InwardType='P'  
	--and Not Exists    
 --   (    
	--	Select * From PUR_PurchaseInvoice_Ref s    
	--	Where s.RefNo=a.ReceiptEntryNo And s.RefDate=a.ReceiptEntryDate And s.RefType=a.ReceiptEntryType and s.Itemcode=a.Itemcode and s.BranchID=@BranchID and s.CompID=@CompID    
 --   )  
 ) x 
 --Where AcceptedQty > InvoicedQty 
 ) p
 Left Outer Join dbo.fn_PUR_Schedule(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) q 
 On p.RefNo=q.ScheduleNo and p.RefDate=q.ScheduleDate and p.RefType=q.ScheduleType 
 Left Outer Join dbo.fn_PUR_PurchaseOrder_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) r 
 On r.OrderNo=q.OrderNo and r.Orderdate=q.OrderDate and r.OrderType=q.OrderType 
 Left Outer Join COM_FormulaMast_Hdr s 
 On r.FormulaCode=s.FrmID and s.ModuleCode=@ModuleCode and r.BranchID=s.BranchID and r.CompID=s.CompID
 Order by r.OrderNo

  END

