CREATE PROCEDURE [dbo].[PUR_PurchaseInvoice_Hlp_Vendor](@ModuleCode int, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))        
      
As        
      
BEGIN      
        
 SET NOCOUNT ON;   

	Select a.PartyName, a.PartyCode, isNull(a.VendorFormulaCode, 0) as FormulaCode, isNull(b.FrmLName, '') as FrmLName  
	from FAS_Party_Master a 
	Left Outer Join COM_FormulaMast_Hdr b 
	On a.VendorFormulaCode=b.FrmID and a.BranchID=b.BranchID and a.CompID=b.CompID
	Where a.AcType in ('P', 'Y') and b.ModuleCode=@ModuleCode and a.BranchID=@BranchID and a.CompID=@CompID and a.EffStatus = 1 

	--Union All

	--Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.VendorCode, a.RefType, a.RefNo, a.RefDate, a.Scheduledate,  a.ItemCode, 	a.InspectionQty
	--From [fn_REC_Get_RRDocument_WholeLotRejected] a
	--Where Not Exists    
 --    (    
 --     Select * From PUR_PurchaseInvoice_Ref s    
