CREATE PROCEDURE [dbo].[PUR_PurchaseOrder_Hlp_AmendmentDocument](@Status varchar(3)='ALL', @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20)='')    
As                                
BEGIN                                    
	SET NOCOUNT ON; 

	Select Distinct a.OrderType, a.OrderNo, a.OrderDate, a.VendorCode, (Select b.PartyName from FAS_Party_Master b 
							where b.PartyCode=a.VendorCode and b.BranchID=a.BranchID and b.CompID=a.CompID) As VendorName, 
		a.Source, a.ValidFrom, a.ValidTo, a.CreditDays, a.CreditFrom, a.OrderingType, a.Narration, 
		a.SplInstruction, a.OrderValue, Convert(varchar(19), a.CreatedDate, 120) as CreatedDate, a.Status, 
		a.Finyear 
	From dbo.fn_Pur_PurchaseOrder_Hdr(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a 
	Where ((@Status='ME' and a.Status In('M','E')) or (@Status='AU' and a.Status In('A')) or ((@Status='' or @Status='ALL') and a.Status In ('A', 'M', 'Y','E')))
		and a.BranchID=@BranchID and a.CompID=@CompID and (@Finyear='' or (@Finyear<>'' and a.Finyear=@Finyear))
END
GO

