SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[PUR_Rpt_CancellationLetter] (@PartyCode int, @PartyName varchar(50), @OrderType varchar(3), @OrderNo int, @OrderDate datetime, @AsOnDate datetime, @RptDate datetime,  @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))

AS

SET NOCOUNT ON

		Select Distinct OrderType, OrderNo, OrderDate, ItemCode, ItemDescription, UOMDesc, PartyName,
					PartyCode, OrderQty, Sum(RecdQty)as ReceiptQty, Add1, Add2, Add3, City, PinCode, Status, IStatus 
		From (	Select distinct a.OrderType, a.OrderNo, a.OrderDate, a.ItemCode, c.ItemDescription,
				c.UOMDesc, @PartyName as PartyName, @PartyCode as PartyCode, a.Qty as OrderQty, 
				IsNull((Select ReceiptQty From Receiptentry m Where m.InwardType = 'P' and m.RefNo=q.ScheduleNo 
						and m.RefDate=q.ScheduleDate and m.RefType=q.ScheduleType 
						and m.ItemCode=q.ItemCode and m.BranchID=q.BranchID and m.CompID=q.CompID
				), 0)RecdQty,
 				g.Add1, g.Add2, g.Add3, g.City, g.PinCode, b.Status, 
				a.Status ItemStatus, Case When a.Status in ('S','C') then 'Cancelled' end as Istatus 
			From dbo.fn_PUR_PurchaseOrder_Dtl (@AsOnDate, @RptDate,  @BranchID, @CompID, @Finyear) a 
			Left Outer Join dbo.fn_PUR_PurchaseOrder_Hdr (@AsOnDate, @RptDate,  @BranchID, @CompID, @Finyear) b 
				On a.OrderType = b.OrderType and a.OrderNo = b.OrderNo and a.OrderDate = b.OrderDate 
					and a.BranchID = b.BranchID and a.CompID = b.CompID 
			Left Outer Join dbo.fn_PUR_Schedule(@AsOnDate, @RptDate,  @BranchID, @CompID, @Finyear) q 
				On a.OrderType = q.OrderType and a.OrderNo = q.OrderNo and a.OrderDate = q.OrderDate 
					and a.ItemCode = q.ItemCode and a.BranchID = q.BranchID and a.CompID = q.CompID 
			Left Outer join Material_Master c 
				On c.ItemCode = a.ItemCode and c.Branchid = a.Branchid and c.Compid = a.Compid 
			Left Outer Join FAS_Party_Address g 
				On g.PartyCode=@PartyCode and g.BranchID=a.BranchID and g.CompID=a.CompID 
			Where a.BranchID = @BranchID and a.CompID = @CompID -----and a.Finyear= @Finyear
				and a.OrderType= @OrderType and a.OrderNo=@OrderNo and a.OrderDate=@OrderDate
				and (a.Status in ('C', 'S')) -- or b.Status in ('C', 'S'))
			) x  
		Group By OrderType, OrderNo, OrderDate, ItemCode, ItemDescription, UOMDesc, OrderQty, PartyName,
			PartyCode, Add1, Add2, Add3, City, PinCode, Status, IStatus 
		Order by x.ItemCode
GO

/****** Object:  StoredProcedure [dbo].[PUR_Rpt_DCSRPrint_Gen]    Script Date: 17/06/2026 11:30:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PUR_Rpt_DCSRPrint_Gen](@DCSRType varchar(3), @DCSRNo int, @DCSRDate datetime, @Percentage Float=90, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS          
BEGIN          
    SET NOCOUNT ON;          
              
	DECLARE @Tmptbl AS TABLE     
		(      
			Itemcode		VARCHAR(20),     
			Rate			FLOAT,      
			CreatedDate		DATETIME    
		)      
      
	INSERT INTO @Tmptbl   
		SELECT DISTINCT b.ItemCode, b.Rate, b.CreatedDate     
		FROM dbo.fn_SAL_Order_Dtl(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear) b      
		LEFT OUTER JOIN dbo.fn_SAL_Order_Hdr(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear) b1      
			ON b.OrderType = b1.OrderType AND b.OrderNo = b1.OrderNo AND b.OrderDate = b1.OrderDate AND b.BranchID = b1.BranchID AND b.CompID = b1.CompID    
		WHERE b.CreatedDate = 
			(      
				SELECT MAX(g.CreatedDate) AS CreatedDate      
				FROM dbo.fn_SAL_Order_Dtl(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear) g      
				WHERE g.ItemCode = b.ItemCode      
			)      

		UNION ALL      
       
		SELECT DISTINCT b.SentItemCode, b.Rate, b.CreatedDate    
		FROM dbo.fn_SAL_JobWorkOrder_Dtl(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear) b      
		LEFT OUTER JOIN dbo.fn_SAL_JobWorkOrder_Hdr(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear) b1      
			ON b.OrderType = b1.OrderType AND b.OrderNo = b1.OrderNo AND b.OrderDate = b1.OrderDate AND b.BranchID = b1.BranchID AND b.CompID = b1.CompID       
		WHERE b.CreatedDate =     
			(      
				SELECT MAX(g.CreatedDate) AS CreatedDate      
				FROM dbo.fn_SAL_JobWorkOrder_Dtl(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear) g      
				WHERE g.SentItemCode = b.SentItemCode      
			)       

	Select a.DCSRType, a.DCSRNo, a.DCSRDate, a.VendorCode, a.Remarks, a.SentItemCode, a.SentItemDesc, a.SentUOM, a.SendUOMDecimal, a.SentSeq, 
		a.RecdSpec, a.RecdItemCode, a.RecdItemDesc, a.RecdOpr, a.RecdItemDesc, a.RecdUOM, a.RecdUOMDecimal, a.RecdSeq, a.Norms, a.SendQty, a.RecdQty, a.ParentItemCode, 
		a.PurSalRate, a.LaborOrderRate, (a.SendQty*((a.PurSalRate*(@Percentage/100))-IsNull(a.LaborOrderRate,0))) as MaterialValue, 
		a.PartyName, a.Add1, a.Add2, a.Add3, a.City, a.PinCode, IsNull(a.GSTRegNo,'') as GSTRegNo  
	From
	(
		Select Distinct a.DCSRType, a.DCSRNo, a.DCSRDate, b.VendorCode,b.Remarks, c.SentItemCode, d.ItemDescription SentItemDesc, 
			d.UOMDesc SentUOM,d.UOMDecimal SendUOMDecimal, isNull(h.OperationSequence,-1) SentSeq, isNull(i.OperationSpecification,'') RecdSpec,
			c.RecdItemCode, e.ItemDescription as RecdOpr, i.OperationName  as RecdItemDesc, 
			e.UOMDesc RecdUOM, e.UOMDecimal RecdUOMDecimal,  i.OperationSequence RecdSeq, a.Norms, 
			a.ScheduleQty SendQty, Round((a.ScheduleQty / a.Norms),0) RecdQty,
			IsNull(i.Itemcode, c.SentItemCode) as ParentItemCode, 
		
			Case When d.ItemNature in ('C','CC', 'F','CF') Then r.Rate
				Else dbo.fn_Pur_Item_Rate(c.SentItemCode,0,'',0,Null,@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear)
			End as PurSalRate,

			IsNull(j.Rate,0) as LaborOrderRate, 
			f.PartyName , g.Add1, g.Add2, g.Add3, g.City, g.PinCode, IsNull(g.GSTRegNo,'') as GSTRegNo  
		From dbo.fn_PUR_DCSR_Tran(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear) a 
		LEFT OUTER JOIN PUR_DCSR_Hdr b 
			On a.DCSRType = b.DCSRType and a.DCSRNo = b.DCSRNo and a.DCSRDate = b.DCSRDate and a.Branchid = b.Branchid and a.Compid = b.Compid 
		LEFT OUTER JOIN PUR_SubCont_ItemMaster c 
			On a.ItemGroupKey = c.ItemGroupKey and b.VendorCode = c.SubContCode and a.SentItemCode = c.SentItemCode 
			and a.Branchid = c.Branchid and a.Compid = c.Compid 
		LEFT OUTER JOIN Material_Master d 
			On d.ItemCode = c.SentItemCode and d.Branchid = c.Branchid and d.Compid = c.Compid 
		LEFT OUTER JOIN Material_Master e 
			On e.ItemCode = c.RecdItemCode and e.Branchid = c.Branchid and e.Compid = c.Compid 
		LEFT OUTER JOIN Fas_Party_Master f 
			On b.VendorCode = f.PartyCode and f.Branchid = b.Branchid and f.Compid = b.Compid 
		LEFT OUTER JOIN FAs_Party_Address g 
			On g.PartyCode = f.PartyCode and g.Branchid = f.Branchid and g.Compid = f.Compid 
		LEFT OUTER JOIN (select * from MPSMaster) h 
			On c.SentItemCode = h.StageCode and c.Branchid = h.Branchid and c.Compid = h.Compid 
		LEFT OUTER JOIN (select * from MPSMaster) i 
			On c.RecdItemCode = i.StageCode and c.Branchid = i.Branchid  and c.Compid = i.Compid 

		LEFT OUTER JOIN fn_PUR_LaborOrder_Vw (@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear)j        
			On b.OrderType= j.OrderType and b.OrderNo= j.OrderNo and b.OrderDate=j.OrderDate        
			and b.VendorCode= j.VendorCode and b.BranchId=j.BranchID and b.CompId= j.CompID        
			and a.SentItemCode= j.SentItemCode and j.RecdItemCode= c.RecdItemCode      

		LEFT OUTER JOIN     
			(      
				SELECT DISTINCT b.ItemCode, b.Rate      
				FROM @Tmptbl b      
				WHERE b.CreatedDate =
					(      
						SELECT MAX(g.CreatedDate) AS CreatedDate      
						FROM @Tmptbl g      
						WHERE g.ItemCode = b.ItemCode      
					)      
			) r      
			ON IsNull(i.Itemcode, c.SentItemCode) = r.ItemCode    

		where a.Status not in ('C','S') and a.DCSRType = @DCSRType  and a.DCSRNo = @DCSRNo  and a.DCSRDate = @DCSRDate and a.Mode = 'NW' 
			and a.BranchId = @BranchId and a.CompId = @CompId and f.EffStatus = 1 
	)a
	order by a.RecdItemCode
          
END 
GO

/****** Object:  StoredProcedure [dbo].[PUR_Rpt_PendingQCReport_Gen_HeatNo]    Script Date: 17/06/2026 11:30:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PUR_Rpt_PendingQCReport_Gen_HeatNo](@DocType varchar(3), @DocNo int, @DocDate datetime,   
@ItemCode varchar(20),  @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3),   
@Finyear Varchar(20))              
As              
BEGIN              
 SET NOCOUNT ON;  
  
 Declare @MaxLen_HeatNo As int;  
 Declare @MaxLen_Manufact As int;  
  
 /* Assign Max Len Of HeatNo & ManufactureDate */  
 Select @MaxLen_HeatNo=IsNull(Max(x.Len_HeatNo),0), @MaxLen_Manufact=IsNull(Max(Len_Manufact),0)  
 From (  
   Select Len(a.HeatNo) As Len_HeatNo, Len(a.ManufactureDate) As Len_Manufact From REC_ReceiptEntry_Dtl_Trace a  
   Where a.ReceiptEntryDate=@DocDate and a.ReceiptEntryNo=@DocNo and a.ReceiptEntryType=@DocType and a.ItemCode=@ItemCode   
      and a.BranchID=@BranchID and a.CompID=@CompID  
 ) x  
  
 /* Output */  
 Select a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.ItemCode, a.SubLotId, a.HeatNo,   
    a.ManufactureDate, a.Qty, a.AcceptedQty, a.RejectedQty, a.ScrapQty, a.Seq, a.ItemSeq,  
    IsNull(@MaxLen_HeatNo,0) As MaxLen_HeatNo, IsNull(@MaxLen_Manufact,0) As MaxLen_Manufact  
 From REC_ReceiptEntry_Dtl_Trace a  
 Where a.ReceiptEntryDate=@DocDate and a.ReceiptEntryNo=@DocNo and a.ReceiptEntryType=@DocType and a.ItemCode=@ItemCode   
    and a.BranchID=@BranchID and a.CompID=@CompID  
 Order by a.ReceiptEntryDate, a.ReceiptEntryNo, a.ItemCode, a.HeatNo  
END  
GO

/****** Object:  StoredProcedure [dbo].[PUR_Rpt_VendorRating_All_Vendor]    Script Date: 17/06/2026 11:30:42 ******/
SET ANSI_NULLS ON
GO

