GO

 CREATE PROCEDURE [dbo].[PUR_Rpt_VendorRating_All_Vendor](@VendorUserKey Varchar(36),@FrmFlg Char(1),@FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))  
As  
  
SET NOCOUNT ON  
  
 Begin   
    
  If @FrmFlg = 'P'  
  
   Insert into COM_SelectList  
    Select @VendorUserKey,VendorCode,'',@BranchID,@CompID,@AsonDate From  
    (  
     Select distinct a.VendorCode   
     From dbo.fn_PUR_Schedule(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear)a  
     Where a.Status not in ('C','S') and a.RequiredDate between  @FromDate and @ToDate  
    )X  
     
  Else  
  
   Insert into COM_SelectList  
    Select @VendorUserKey,VendorCode,'',@BranchID,@CompID,@AsonDate From  
    (  
     Select distinct d.VendorCode   
     From dbo.fn_PUR_DCSR_Schedule(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear)a  
     Left Outer Join PUR_DCSR_Hdr d   
     On a.DCSRNo = d.DCSRNo and a.DCSRDate = d.DCSRDate and a.DCSRType = d.DCSRType and a.BranchId = d.BranchId and a.CompId = d.CompId  
     Where a.Status not in ('C','S')  and a.RequiredDate between  @FromDate and @ToDate  
     
    )x  
  
  /*
  Insert into COM_SelectList    
    Select @VendorUserKey,VendorCode,'',@BranchID,@CompID,@AsonDate From    
    (    
     Select distinct a.VendorCode     
     From dbo.fn_PUR_Schedule(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear)a    
     Where a.Status not in ('C','S') and a.RequiredDate between  @FromDate and @ToDate    
    )X    
  */
 End
GO

/****** Object:  StoredProcedure [dbo].[PUR_Rpt_VendorRating_Gen]    Script Date: 17/06/2026 11:30:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PUR_Rpt_VendorRating_Gen]( @VendUserKey Varchar(36),  @FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))      
As      
BEGIN      
 SET NOCOUNT ON;    
  
 Select VendorCode, PartyName, ROUND(DelPer, 2) as DelPer, ROUND(QuaPer, 2) as QuaPer,    
  ROUND(Case When DPer>Delivery Then Delivery Else DPer End, 2) as DPer,    
  ROUND(Case When QPer>Quality Then Quality Else QPer End, 2) as QPer,    
  ROUND(Price, 2) as PPer       
 From    
 (    
  Select x.VendorCode, x.PartyName,     
   (sum(x.DeliveryValue) / sum(x.cnt)) as DelPer,     
   (sum(x.QualityValue) / sum(x.cnt)) as QuaPer,     
   ((sum(x.DeliveryValue) / sum(x.cnt)) *  x.DeliveryMastPerc) /100 as DPer, x.DeliveryMastPerc as Delivery,     
   ((sum(x.QualityValue) / sum(x.cnt)) * x.QualityMastPerc) /100 as QPer, x.QualityMastPerc as Quality,
	x.PriceMastPerc as Price          
  From     
   (      
        
    Select a.VendorCode, c.PartyName, a.ItemCode, a.ScheduleQty, f.ReceiptQty, f.AcceptedQty,      
     ((f3.ReceiptWithOutRejectionDCQty/a.ScheduleQty)* 100) as DeliveryValue,   
     ((f.AcceptedQty/f.ReceiptQty)* 100) as QualityValue,      
     e.Delivery as DeliveryMastPerc, e.Quality as QualityMastPerc, e.Price as PriceMastPerc, 1 as Cnt     
    From dbo.fn_PUR_Schedule(@AsonDate, @RptDate, @BranchID, @CompID, @Finyear)a      
       
    Left Outer Join FAS_Party_Master c      
     On a.VendorCode=c.PartyCode and a.BranchID=c.BranchID and a.CompID=c.CompID    
        
    Left Outer Join     
     (    
      Select top 1 Delivery, Quality, Price, Branchid, CompID      
      From PUR_VendorRating_Master
     ) e       
     On e.BranchID = a.BranchID and e.CompID = a.CompID      
        
    Left Outer Join     
     (     
      Select RefType,RefNo,RefDate,ItemCode,ScheduleDate, sum(ReceiptQty) ReceiptQty,sum(AcceptedQty) AcceptedQty, Branchid, Compid     
      From REC_ReceiptEntry_Dtl f       
      Group by RefType,RefNo,RefDate,ItemCode,ScheduleDate,Branchid,Compid    
     ) f    
     On a.ScheduleNo=f.RefNo and a.ScheduleDate=f.RefDate and a.ScheduleType=f.RefType and  a.RequiredDate=f.ScheduleDate and a.ItemCode=f.ItemCode      
     and a.BranchID=f.BranchID and a.CompID=f.CompID      
        
    Outer Apply     
     (     
      Select sum(f.ReceiptQty-isNull(f1.RejectionDCQty,0)) as ReceiptWithOutRejectionDCQty  
      From REC_ReceiptEntry_Dtl f       
      Left Outer Join    
       (   
        Select f1.RRType, f1.RRNo, f1.RRDate, f1.ItemCode, Sum(f1.RejectionDCQty) as RejectionDCQty, f1.BranchID, f1.CompID  
        From RejectionDC f1  
        Where f1.BranchID=@BranchID and f1.CompID=@CompID  
         and (@VendUserKey=''     
           OR (@VendUserKey<>''      
             and f1.VendorCode in      
             (      
              Select SelectInt From Com_SelectList       
              Where UserKey = @VendUserKey and BranchID = @BranchID and CompID = @CompID      
             )    
            )    
          )     
        Group by f1.RRType, f1.RRNo, f1.RRDate, f1.ItemCode, f1.BranchID, f1.CompID   
       )f1  
       On f1.RRType=f.ReceiptEntryType and f1.RRNo=f.ReceiptEntryNo and f1.RRDate=f.ReceiptEntryDate and f1.ItemCode=f.ItemCode  
       and f1.BranchID=f.BranchID and f1.CompID=f.CompID  
      Where a.ScheduleNo=f.RefNo and a.ScheduleDate=f.RefDate and a.ScheduleType=f.RefType and  a.RequiredDate=f.ScheduleDate and a.ItemCode=f.ItemCode      
       and a.BranchID=f.BranchID and a.CompID=f.CompID  
     ) f3     
        
    Where a.EffStatus='1' and a.[Status] not in ('C','S') and f.ReceiptQty > 0     
    and a.RequiredDate between @FromDate and @ToDate and a.BranchID =@BranchID and a.CompID = @CompID      
   ) x       
  Where (@VendUserKey=''     
    OR (@VendUserKey<>'' and     
      x.VendorCode in      
      (      
       Select SelectInt From Com_SelectList       
       Where UserKey = @VendUserKey and BranchID = @BranchID and CompID = @CompID      
      )    
     )    
   )       
  Group by x.VendorCode, x.PartyName, x.DeliveryMastPerc, x.QualityMastPerc, x.PriceMastPerc  
 )  y    
 Order by y.VendorCode    
END  
  
GO

/****** Object:  StoredProcedure [dbo].[PUR_Rpt_VendorRating_Gen_Purchase]    Script Date: 17/06/2026 11:30:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PUR_Rpt_VendorRating_Gen_Purchase]( @VendUserKey Varchar(36),  @FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))          
As          
BEGIN          
 SET NOCOUNT ON;        
       
 Declare @RatingCode int      
  Select @RatingCode= RatingCode       
  From fn_PUR_VendorRating_Master('A',@AsonDate,@RptDate,@BranchID,@CompID)       
  Where IsSubContract='0'      
      
 Select VendorCode, PartyName, ROUND(DelPer, 2) as DelPer, ROUND(QuaPer, 2) as QuaPer,        
  ROUND(Case When DPer>Delivery Then Delivery Else DPer End, 2) as DPer,        
  ROUND(Case When QPer>Quality Then Quality Else QPer End, 2) as QPer,        
  ROUND(Case When PPer>Price Then Price Else PPer End, 2) as PPer,        
  ROUND(Case When FieldPer>Field Then Field Else FieldPer End, 2) as FieldPer,        
  ROUND(Case When FreightPer>PremFrieght Then PremFrieght Else FreightPer End, 2) as FreightPer        
 From        
 (        
  Select x.VendorCode, x.PartyName,         
   (sum(x.DeliveryValue) / sum(x.cnt)) as DelPer,         
   (sum(x.QualityValue) / sum(x.cnt)) as QuaPer,         
   ((sum(x.DeliveryValue) / sum(x.cnt)) *  x.DeliveryMastPerc) /100 as DPer, x.DeliveryMastPerc as Delivery,         
   ((sum(x.QualityValue) / sum(x.cnt)) * x.QualityMastPerc) /100 as QPer, x.QualityMastPerc as Quality,          
   ((sum(x.RatingPercentage) / sum(x.cnt)) * x.PriceMastPerc) /100 as PPer, x.PriceMastPerc as Price,        
   ((sum(x.FieldCompValue) / sum(x.cnt)) * x.FieldCompMastPerc) /100 as FieldPer, x.FieldCompMastPerc as Field,        
   ((sum(x.PremFrieghtValue) / sum(x.cnt)) * x.PremFrieghtMastPerc) /100 as FreightPer, x.PremFrieghtMastPerc as PremFrieght        
  From         
   (          
            
    Select a.VendorCode, c.PartyName, a.ItemCode, a.ScheduleQty, f.ReceiptQty, f.AcceptedQty,          
     --((f.ReceiptQty/a.ScheduleQty)* 100) as DeliveryValue,          
     ((f3.ReceiptWithOutRejectionDCQty/a.ScheduleQty)* 100) as DeliveryValue,       
     ((f.AcceptedQty/f.ReceiptQty)* 100) as QualityValue,          
      
     (      
      Select m.RatingPercentage       
      From dbo.fn_PUR_Get_VendorRating_Item_Rate(@AsonDate, @RptDate, @BranchID, @CompID, @Finyear) m          
      Where m.VendorCode=a.VendorCode and m.ItemCode=a.ItemCode        
     ) as RatingPercentage,        
          
     e.Delivery as DeliveryMastPerc, e.Quality as QualityMastPerc, e.Price as PriceMastPerc,         
     e.FieldComplaint as FieldCompMastPerc, e.PremiumFreight as PremFrieghtMastPerc,          
            
     (      
      Select Percentage         
      From dbo.fn_PUR_VendorRating_FieldComplaint ( 'A',@AsonDate,@RptDate, @BranchID,@CompID) a        
      Inner Join        
       (        
        Select count(*) FieldCnt       
        From QC_CustomerComplaintRegister i          
        where i.CustomerCode=a.VendorCode and i.ComplaintRegisterDate between @FromDate and @ToDate          
         and i.BranchID=a.BranchID and i.CompID=a.CompID        
       ) b        
       On b.FieldCnt between a.FromRank and a.ToRank        
      Where a.RatingCode=@RatingCode      
     ) as FieldCompValue,          
            
     (      
      Select Percentage         
      From dbo.fn_PUR_VendorRating_PremiumFreight ('A',@AsonDate,@RptDate, @BranchID,@CompID) a        
      Inner Join        
       (        
        Select count(*) FreightCnt       
        From COM_FormulaCalc_Hdr g          
        Left Outer Join PUR_PurchaseInvoice_Hdr h           
         On g.DocNo=h.DocNo and g.DocDate=h.DocDate and g.DocType=h.DocType           
         and  g.BranchID=h.BranchID and g.CompID=h.CompID and g.Finyear=h.Finyear          
        where g.PostingAc = 709 and (g.DocDate between @FromDate and @ToDate)        
         and h.VendorCode=a.VendorCode and g.BranchID=a.BranchID and g.CompID=a.CompID        
       ) b        
       On b.FreightCnt between  a.FromRank and a.ToRank         
      Where a.RatingCode=@RatingCode      
     ) as PremFrieghtValue,        
            
     1 as Cnt        
            
    From dbo.fn_PUR_Schedule(@AsonDate, @RptDate, @BranchID, @CompID, @Finyear)a          
           
    Left Outer Join dbo.fn_FAS_Party_Master( 'M',@AsonDate,@RptDate, @BranchID,@CompID) c          
     On a.VendorCode=c.PartyCode         
            
    Left Outer Join         
     (        
      Select top 1 Delivery, Quality, Price, FieldComplaint, PremiumFreight, Branchid, CompID          
      From dbo.fn_PUR_VendorRating_Master('A',@AsonDate,@RptDate, @BranchID,@CompID)        
      Where IsSubContract='0'       
     ) e           
     On e.BranchID = a.BranchID and e.CompID = a.CompID          
            
    Left Outer Join         
     (         
      Select RefType,RefNo,RefDate,ItemCode,ScheduleDate, sum(ReceiptQty) ReceiptQty,sum(AcceptedQty) AcceptedQty, Branchid, Compid         
      From REC_ReceiptEntry_Dtl f           
      Group by RefType,RefNo,RefDate,ItemCode,ScheduleDate,Branchid,Compid        
     ) f        
     On a.ScheduleNo=f.RefNo and a.ScheduleDate=f.RefDate and a.ScheduleType=f.RefType and  a.RequiredDate=f.ScheduleDate and a.ItemCode=f.ItemCode          
     and a.BranchID=f.BranchID and a.CompID=f.CompID          
            
    Outer Apply         
     (         
      Select sum(f.ReceiptQty-isNull(f1.RejectionDCQty,0)) as ReceiptWithOutRejectionDCQty      
      From REC_ReceiptEntry_Dtl f           
      Left Outer Join        
       (       
        Select f1.RRType, f1.RRNo, f1.RRDate, f1.ItemCode, Sum(f1.RejectionDCQty) as RejectionDCQty, f1.BranchID, f1.CompID      
        From RejectionDC f1      
        Where f1.BranchID=@BranchID and f1.CompID=@CompID      
         and (@VendUserKey=''         
           OR (@VendUserKey<>''          
             and f1.VendorCode in          
             (          
              Select SelectInt From Com_SelectList           
              Where UserKey = @VendUserKey and BranchID = @BranchID and CompID = @CompID          
             )        
            )        
          )         
        Group by f1.RRType, f1.RRNo, f1.RRDate, f1.ItemCode, f1.BranchID, f1.CompID       
       )f1      
       On f1.RRType=f.ReceiptEntryType and f1.RRNo=f.ReceiptEntryNo and f1.RRDate=f.ReceiptEntryDate and f1.ItemCode=f.ItemCode      
       and f1.BranchID=f.BranchID and f1.CompID=f.CompID      
      Where a.ScheduleNo=f.RefNo and a.ScheduleDate=f.RefDate and a.ScheduleType=f.RefType and  a.RequiredDate=f.ScheduleDate and a.ItemCode=f.ItemCode          
       and a.BranchID=f.BranchID and a.CompID=f.CompID --and f.ReceiptEntryDate<=f.ScheduleDate         
     ) f3         
            
    Where a.EffStatus='1' and a.[Status] not in ('C','S') and f.ReceiptQty > 0         
    and a.RequiredDate between @FromDate and @ToDate and a.BranchID =@BranchID and a.CompID = @CompID          
   ) x           
  Where (@VendUserKey=''         
    OR (@VendUserKey<>'' and         
      x.VendorCode in          
      (          
       Select SelectInt From Com_SelectList           
       Where UserKey = @VendUserKey and BranchID = @BranchID and CompID = @CompID          
      )        
     )        
   )           
  Group by x.VendorCode, x.PartyName, x.DeliveryMastPerc, x.QualityMastPerc, x.PriceMastPerc, x.FieldCompMastPerc,       
   x.PremFrieghtMastPerc, x.PremFrieghtValue, x.FieldCompValue        
 )  y        
 Order by y.VendorCode        
END      
GO

/****** Object:  StoredProcedure [dbo].[PUR_Rpt_VendorRating_Gen_Subcont]    Script Date: 17/06/2026 11:30:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

  
  CREATE PROCEDURE [dbo].[PUR_Rpt_VendorRating_Gen_Subcont](@VendUserKey Varchar(36),  @FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))        
As        
BEGIN        
 SET NOCOUNT ON;      
    
 Declare @RatingCode int    
  Select @RatingCode= RatingCode     
  From fn_PUR_VendorRating_Master('A',@AsonDate,@RptDate,@BranchID,@CompID)     
  Where IsSubContract='1'    
    
 Select VendorCode, PartyName, ROUND(DelPer, 2) as DelPer, ROUND(QuaPer, 2) as QuaPer,      
  ROUND(Case When DPer>Delivery Then Delivery Else DPer End, 2) as DPer,      
  ROUND(Case When QPer>Quality Then Quality Else QPer End, 2) as QPer,      
  ROUND(Case When PPer>Price Then Price Else PPer End, 2) as PPer,      
  ROUND(Case When FieldPer>Field Then Field Else FieldPer End, 2) as FieldPer,      
  ROUND(Case When FreightPer>PremFrieght Then PremFrieght Else FreightPer End, 2) as FreightPer      
 From      
  (      
   Select x.VendorCode, x.PartyName,       
    (sum(x.DeliveryValue) / sum(x.cnt)) as DelPer,       
    (sum(x.QualityValue) / sum(x.cnt)) as QuaPer,       
    ((sum(x.DeliveryValue) / sum(x.cnt)) *  x.DeliveryMastPerc) /100 as DPer, x.DeliveryMastPerc as Delivery,       
    ((sum(x.QualityValue) / sum(x.cnt)) * x.QualityMastPerc) /100 as QPer, x.QualityMastPerc as Quality,        
    ((sum(x.RatingPercentage) / sum(x.cnt)) * x.PriceMastPerc) /100 as PPer, x.PriceMastPerc as Price,      
    ((sum(x.FieldCompValue) / sum(x.cnt)) * x.FieldCompMastPerc) /100 as FieldPer, x.FieldCompMastPerc as Field,      
    ((sum(x.PremFrieghtValue) / sum(x.cnt)) * x.PremFrieghtMastPerc) /100 as FreightPer, x.PremFrieghtMastPerc as PremFrieght      
   From       
   (        
          
    Select b.VendorCode, c.PartyName,       
     --((f2.ReceiptQty/a.ScheduleQty)* 100) as DeliveryValue,       
     ((f3.ReceiptWithOutRejectionDCQty/a.ScheduleQty)* 100) as DeliveryValue,     
     ((f2.AcceptedQty/f2.ReceiptQty)* 100) as QualityValue,        
          
     (    
      Select m.RatingPercentage     
      From dbo.fn_PUR_Get_SubcontractRating_Item_Rate(@AsonDate, @RptDate, @BranchID, @CompID, @Finyear) m        
      Where m.VendorCode = b.VendorCode and m.RecdItemCode = a.RecdItemCode and m.ItemGroupKey = a.ItemGroupKey      
     ) as RatingPercentage,      
          
     e.Delivery as DeliveryMastPerc, e.Quality as QualityMastPerc, e.Price as PriceMastPerc,       
     e.FieldComplaint as FieldCompMastPerc, e.PremiumFreight as PremFrieghtMastPerc,        
     (    
      Select Percentage       
      From dbo.fn_PUR_VendorRating_FieldComplaint ( 'A',@AsonDate,@RptDate, @BranchID,@CompID) a      
      Inner Join      
       (      
        Select count(*) FieldCnt From QC_CustomerComplaintRegister i        
        where i.CustomerCode = b.VendorCode and i.ComplaintRegisterDate between @FromDate and @ToDate        
        and i.BranchID = b.BranchID and i.CompID = b.CompID      
       ) b      
       On b.FieldCnt between a.FromRank and a.ToRank      
      Where a.RatingCode=@RatingCode    
     ) as FieldCompValue,        
          
     (    
      Select Percentage       
      From dbo.fn_PUR_VendorRating_PremiumFreight ('A',@AsonDate,@RptDate, @BranchID,@CompID) a      
      Inner Join      
       (      
        Select count(*) FreightCnt From COM_FormulaCalc_Hdr g        
        Left Outer Join PUR_LaborInvoice_Hdr h         
        On g.DocNo=h.DocNo and g.DocDate=h.DocDate and g.DocType=h.DocType         
        and  g.BranchID=h.BranchID and g.CompID=h.CompID and g.Finyear=h.Finyear        
        where g.PostingAc = 709 and g.DocDate between @FromDate and @ToDate        
        and h.VendorCode = b.VendorCode and g.BranchID = b.BranchID and g.CompID = b.CompID      
       ) b      
       On b.FreightCnt between  a.FromRank and a.ToRank      
      Where a.RatingCode=@RatingCode     
     ) as PremFrieghtValue,      
          
     1 as Cnt      
          
    From dbo.fn_PUR_DCSR_Schedule(@AsonDate, @RptDate, @BranchID, @CompID, @Finyear)a        
          
    Left Outer Join dbo.fn_PUR_DCSR (@AsonDate, @RptDate, @BranchID, @CompID, @Finyear) b        
     On a.DCSRNo = b.DCSRNo and a.DCSRDate = b.DCSRDate and a.DCSRType = b.DCSRType      
     and a.BranchID = b.BranchID and a.CompID = b.CompID and a.Finyear = b.Finyear        
          
    Left Outer Join dbo.fn_FAS_Party_Master( 'M',@AsonDate,@RptDate, @BranchID,@CompID) c        
     On b.VendorCode = c.PartyCode and b.BranchID = c.BranchID and b.CompID = c.CompID        
          
    Left Outer Join       
     (      
      Select top 1 Delivery, Quality, Price, FieldComplaint, PremiumFreight, Branchid, CompID        
      From dbo.fn_PUR_VendorRating_Master ('A',@AsonDate,@RptDate, @BranchID,@CompID)      
      Where IsSubContract='1'    
     ) e         
     On e.BranchID = a.BranchID and e.CompID = a.CompID     
        
    Outer Apply       
     (       
      Select sum(ReceiptQty) ReceiptQty    
      From REC_ReceiptEntry_Dtl f         
      where a.DCSRNo=f.RefNo and a.DCSRDate=f.RefDate and a.DCSRType=f.RefType and  a.RequiredDate=f.ScheduleDate and a.RecdItemCode=f.ItemCode        
      and a.BranchID=f.BranchID and a.CompID=f.CompID and f.ReceiptEntryDate<=f.ScheduleDate       
     ) f1         
          
    Outer Apply       
     (       
      Select sum(ReceiptQty) ReceiptQty,sum(AcceptedQty) AcceptedQty    
      From REC_ReceiptEntry_Dtl f         
      where a.DCSRNo=f.RefNo and a.DCSRDate=f.RefDate and a.DCSRType=f.RefType and  a.RequiredDate=f.ScheduleDate and a.RecdItemCode=f.ItemCode        
      and a.BranchID=f.BranchID and a.CompID=f.CompID    
     ) f2      
    
    Outer Apply       
     (       
      Select sum(f.ReceiptQty-isNull(f1.RejectionDCQty,0)) as ReceiptWithOutRejectionDCQty    
      From REC_ReceiptEntry_Dtl f         
      Left Outer Join      
       (     
        Select f1.RRType, f1.RRNo, f1.RRDate, f1.ItemCode, Sum(f1.RejectionDCQty) as RejectionDCQty, f1.BranchID, f1.CompID    
        From RejectionDC f1    
        Where f1.BranchID=@BranchID and f1.CompID=@CompID    
         and (@VendUserKey=''       
           OR (@VendUserKey<>''        
             and f1.VendorCode in        
             (        
              Select SelectInt From Com_SelectList         
              Where UserKey = @VendUserKey and BranchID = @BranchID and CompID = @CompID        
             )      
            )      
          )       
        Group by f1.RRType, f1.RRNo, f1.RRDate, f1.ItemCode, f1.BranchID, f1.CompID     
       )f1    
       On f1.RRType=f.ReceiptEntryType and f1.RRNo=f.ReceiptEntryNo and f1.RRDate=f.ReceiptEntryDate and f1.ItemCode=f.ItemCode    
       and f1.BranchID=f.BranchID and f1.CompID=f.CompID    
      Where a.DCSRNo=f.RefNo and a.DCSRDate=f.RefDate and a.DCSRType=f.RefType and  a.RequiredDate=f.ScheduleDate and a.RecdItemCode=f.ItemCode        
       and a.BranchID=f.BranchID and a.CompID=f.CompID --and f.ReceiptEntryDate<=f.ScheduleDate       
     ) f3       
          
    Where a.EffStatus='1' and a.[Status] not in ('C','S') and f2.ReceiptQty > 0       
     and (a.RequiredDate between @FromDate and @ToDate) and a.BranchID =@BranchID and a.CompID = @CompID        
   ) x         
   Where (@VendUserKey=''       
     OR (@VendUserKey<>''       
       and x.VendorCode in        
       (        
        Select SelectInt From Com_SelectList         
        Where UserKey = @VendUserKey and BranchID = @BranchID and CompID = @CompID        
       )      
      )      
    )         
   Group by x.VendorCode, x.PartyName, x.DeliveryMastPerc, x.QualityMastPerc, x.PriceMastPerc, x.FieldCompMastPerc, x.PremFrieghtMastPerc, x.PremFrieghtValue, x.FieldCompValue      
  )  y      
 Order by y.VendorCode        
        
END     
    
  
GO

