 CREATE PROCEDURE [dbo].[PUR_Rpt_VendorRating_Sel_Vendor](@FrmFlg Char(1), @FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))    
As    
    
SET NOCOUNT ON    
    
 Begin
 
 If @FrmFlg = 'P'  
  
   Select distinct --(Select dbo.fn_COM_Get_PartyName(a.VendorCode,a.Transtamp,@BranchID,@CompID)) as PartyName , 
	b.PartyName, a.VendorCode   
   From dbo.fn_PUR_Schedule(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear)a  
	Left Outer Join FAS_Party_Master b  
   On a.VendorCode = b.PartyCode and a.BranchID = b.BranchID and a.CompID = b.CompID
   Where a.Status not in ('C','S') and a.RequiredDate between  @FromDate and @ToDate  
   Order by PartyName  
  
  Else  
  
   Select distinct -- (Select dbo.fn_COM_Get_PartyName(d.VendorCode,d.Transtamp,@BranchID,@CompID)) as PartyName, 
   b.PartyName, d.VendorCode   
   From dbo.fn_PUR_DCSR_Schedule(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear)a  
   Left Outer Join PUR_DCSR_Hdr d   
   On a.DCSRNo = d.DCSRNo and a.DCSRDate = d.DCSRDate and a.DCSRType = d.DCSRType and a.BranchId = d.BranchId and a.CompId = d.CompId  
   Left Outer Join FAS_Party_Master b  
   On d.VendorCode = b.PartyCode and d.BranchID = b.BranchID and d.CompID = b.CompID 
   Where a.Status not in ('C','S')  and a.RequiredDate between  @FromDate and @ToDate  
   Order by PartyName  
        
  
    /*
   Select distinct b.PartyName, a.VendorCode     
   From dbo.fn_PUR_Schedule(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear)a     
   Left Outer Join FAS_Party_Master b  
   On a.VendorCode = b.PartyCode and a.BranchID = b.BranchID and a.CompID = b.CompID  
   Where a.Status not in ('C','S') and a.RequiredDate between  @FromDate and @ToDate    
   Order by PartyName    
    */
  
    
 End
GO

