CREATE PROCEDURE [dbo].[PUR_Rpt_VendorRatingLetter_Fil](@FrmFlg char(1),@FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))  
As  
  
SET NOCOUNT ON  
  
 Begin   
  
  If @FrmFlg = 'P'  
  
   Select distinct --(Select dbo.fn_COM_Get_PartyName(a.VendorCode,a.Transtamp,@BranchID,@CompID)) as PartyName, 
   b.PartyName, a.Vendorcode  
   From dbo.fn_PUR_Schedule(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear)a  
   Left Outer Join dbo.fn_FAS_Party_Master('M', @AsOnDate, @RptDate, @BranchID, @CompID) b  
   On a.VendorCode = b.PartyCode and a.BranchID = b.BranchID and a.CompID = b.CompID  
    Left Outer Join     
   (     
    select RefType,RefNo,RefDate,ItemCode,ScheduleDate, IsNull(sum(ReceiptQty), 0) as ReceiptQty,sum(AcceptedQty) AcceptedQty, Branchid, Compid     
    from REC_ReceiptEntry_Dtl f       
    group by RefType,RefNo,RefDate,ItemCode,ScheduleDate,Branchid,Compid    
   ) f    
   On a.ScheduleNo=f.RefNo and a.ScheduleDate=f.RefDate and a.ScheduleType=f.RefType     
   and a.RequiredDate=f.ScheduleDate and a.ItemCode=f.ItemCode and a.Branchid=f.Branchid and a.Compid=f.Compid  
   Where a.Status Not in ('C', 'S') and f.ReceiptQty > 0 and a.RequiredDate between @FromDate and @ToDate  
    and a.BranchID = @BranchID and a.CompID = @CompID  
  
    Else  
  
   Select distinct --(Select dbo.fn_COM_Get_PartyName(b.VendorCode,b.Transtamp,@BranchID,@CompID)) as PartyName
   c.PartyName, b.VendorCode  
   From dbo.fn_PUR_DCSR_Schedule(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear)a  
   Left Outer Join dbo.fn_PUR_DCSR (@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear) b  
   On a.DCSRNo = b.DCSRNo and a.DCSRDate = b.DCSRDate and a.DCSRType = b.DCSRType and   
   a.Branchid = b.Branchid and a.Compid = b.Compid and a.Finyear = b.Finyear  
   Left Outer Join dbo.fn_FAS_Party_Master('M', @AsOnDate, @RptDate, @BranchID, @CompID) c  
   On b.VendorCode = c.PartyCode and b.Branchid = c.Branchid and b.Compid = c.Compid  
    Left Outer Join     
    (     
     select RefType,RefNo,RefDate,ItemCode,ScheduleDate, IsNull(sum(ReceiptQty), 0) as ReceiptQty,sum(AcceptedQty) AcceptedQty, Branchid, Compid     
     from REC_ReceiptEntry_Dtl f       
     group by RefType,RefNo,RefDate,ItemCode,ScheduleDate,Branchid,Compid    
    ) f    
    On a.DCSRNo=f.RefNo and a.DCSRDate=f.RefDate and a.DCSRType=f.RefType and  a.RequiredDate=f.ScheduleDate and a.RecdItemCode=f.ItemCode      
    and a.BranchID=f.BranchID and a.CompID=f.CompID      
   Where a.EffStatus='1' and a.Status not in ('C','S') and f.ReceiptQty > 0 and a.RequiredDate between @FromDate and @ToDate  
    and a.BranchID = @BranchID and a.CompID = @CompID  
   
  
  
 End

GO

/****** Object:  StoredProcedure [dbo].[PUR_Rpt_VendorRatingLetter_Gen]    Script Date: 17/06/2026 11:30:42 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PUR_Rpt_VendorRatingLetter_Gen](@VendorCode int, @FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))  
As  
  
SET NOCOUNT ON  
  
 Begin   
    
  
   Select x.VendorCode, x.PartyName, (sum(x.DeleiveryPer) / sum(x.cnt)) as DelPer, (sum(x.QualityPer) / sum(x.cnt)) as QuaPer, x.Delivery, x.Quality, x.Price,  
      ((sum(x.DeleiveryPer) / sum(x.cnt)) *  x.Delivery) /100 as DPer,  ((sum(x.QualityPer) / sum(x.cnt)) * x.Quality) /100 as QPer, y.Add1, y.Add2, y.Add3, y.City, y.PinCode,(x.Quality+ x.Delivery+ x.Price)Ratings  
    From (  
       Select a.VendorCode, c.PartyName, a.ItemCode, a.ScheduleQty, f.ReceiptQty, f.AcceptedQty, ((f.ReceiptQty/a.ScheduleQty)* 100) as DeleiveryPer,  
          ((f.AcceptedQty/f.ReceiptQty)* 100) as QualityPer, e.Delivery, e.Quality, e.Price, 1 as Cnt  
        From dbo.fn_PUR_Schedule(@AsOnDate, @RptDate, @BranchID, @CompID,@Finyear)a  
        Left Outer Join REC_ReceiptEntry_Dtl f  
         On  a.ScheduleNo=f.RefNo and a.ScheduleDate=f.RefDate and a.ScheduleType=f.RefType and a.RequiredDate=f.ScheduleDate and a.ItemCode=f.ItemCode and a.Branchid=f.Branchid and a.Compid=f.Compid  
        Left Outer Join (Select top 1 Delivery, Quality, Price, Branchid, Compid From dbo.fn_PUR_VendorRating_Master('A', @AsOnDate,@RptDate,@BranchID,@CompID)) e  
         On e.branchid = a.Branchid and e.Compid = a.Compid  
        Left Outer Join dbo.fn_FAS_Party_Master('A', @AsOnDate,@RptDate,@BranchID,@CompID)  c  
        On a.VendorCode = c.PartyCode and a.Branchid = c.Branchid  and a.Compid = c.Compid  
       Where a.VendorCode=@VendorCode  and a.Status not in ('C','S') and f.ReceiptQty > 0 and a.RequiredDate between @FromDate and @ToDate  
        and a.BranchID = @BranchID and a.CompID = @CompID  
        ) x  
    Left Outer Join dbo.fn_FAS_Party_Address('A', @AsOnDate,@RptDate,@BranchID,@CompID) y  
     On x.VendorCode = y.PartyCode   
    Where y.BranchID = @BranchID and y.CompID = @CompID /* x.VendorCode =@VendorCode and*/  
    Group by x.VendorCode, x.PartyName, x.Delivery, x.Quality, x.Price, y.Add1, y.Add2, y.Add3, y.City, y.PinCode    
    Order by x.VendorCode  
  
  
/*    
  Select a.VendorCode, a.PartyName, (a.Quality+ a.Delivery+ a.Price)Ratings, b.Add1, b.Add2, b.Add3, b.City, b.PinCode   
  From (   
   Select VendorCode, PartyName,  Case When ReceiptQty = 0 then 0 When ScheduleQty < AcceptedQty Then Quality Else ((AcceptedQty / ReceiptQty) * Quality) end Quality,  
   Case when DelayDates = 0 then Delivery else ((250.0-AvgDelayDates)/10.0) end Delivery, DelayDates, Price  
   From  
    (Select x.VendorCode, x.PartyName, Sum(x.ScheduleQty) as ScheduleQty, Sum(x.ReceiptQty) as ReceiptQty,  
     Sum(x.AcceptedQty) as AcceptedQty, Sum(DelayDates) as DelayDates, Avg(DelayDates) as AvgDelayDates, x.Quality, x.Delivery, x.Price  
    From  
     (Select VendorCode, PartyName, ItemCode, Sum(SchQty) as ScheduleQty, Sum(ReceiptQty) as ReceiptQty, Sum(AcceptedQty) as AcceptedQty,  
      DelayDates, Quality, Delivery, Price  
     From  
      (select a.VendorCode, c.PartyName, a.ItemCode, Case When a.Status = 'S' Then isnull(b.ReceiptQty, 0) Else a.ScheduleQty End as SchQty,  
       isNull(b.ReceiptQty,0) ReceiptQty,  isnull(b.AcceptedQty,0) AcceptedQty,  
       Case when DateDiff(d, a.RequiredDate, b.ReceiptEntryDate) > 10 then DateDiff(d, a.RequiredDate, b.ReceiptEntryDate) else 0 end DelayDates,  
       e.Quality , e.Delivery, e.Price  
      From dbo.fn_PUR_Schedule(@AsOnDate, @RptDate, @BranchID, @CompID,@Finyear)a  
      Left Outer Join  
       (Select RefNo, RefType, RefDate, ItemCode, VendorCode, ScheduleDate, BranchID, CompID, Max(ReceiptEntryDate) ReceiptEntryDate,  
        Sum(ReceiptQty) as ReceiptQty, Sum(AcceptedQty) AcceptedQty  
        From ReceiptEntry Where InwardType = 'P' and BranchId = @BranchID and CompID = @CompID  
       Group By RefNo, RefType, RefDate, ItemCode, VendorCode, ScheduleDate, BranchID, CompID  
       ) b  
       On a.ScheduleType = b.RefType and a.ScheduleNo = b.RefNo and a.ScheduleDate = b.RefDate  
        and a.VendorCode = b.VendorCode and a.ItemCode = b.ItemCode and a.RequiredDate = b.ScheduleDate and a.BranchID = b.BranchID and a.CompID = b.CompID  
      Left Outer Join FAS_Party_Master c  
       On a.VendorCode = c.PartyCode and a.Branchid = c.Branchid and a.Compid = c.Compid  
      Left Outer Join (Select top 1 RatingCode, Quality, Delivery, Price, Branchid, Compid   
        From dbo.fn_PUR_VendorRating_Master('A', @AsOnDate,@RptDate,@BranchID,@CompID)  
        Where BranchId = @BranchID and CompID = @CompID)  
         e  
       On e.BranchId = a.BranchId and e.CompId = a.CompId  
      Where a.Status not in ('C') and a.RequiredDate between @FromDate and @ToDate and a.VendorCode = @VendorCode  
    ) w  
    Group by VendorCode, PartyName, ItemCode, SchQty, DelayDates, Quality, Delivery, Price  
    ) x  
    Group by x.VendorCode, x.PartyName, x.Quality, x.Delivery, x.Price  
   ) y )a  
  Left Outer Join dbo.fn_FAS_Party_Address('A', @AsOnDate,@RptDate,@BranchID,@CompID) b  
  On a.VendorCode = b.PartyCode and b.BranchID = @BranchID and b.CompID = @CompID  
  Order by a.partyname  
  
*/  
  
 End
GO

