CREATE PROCEDURE [dbo].[PUR_Rpt_VendorRatingLetter_Gen_Spr_Purchase](@VendorCode int,@FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))    
As    
      
 Begin     
    
  SET NOCOUNT ON;    
  
 Declare @RatingCode int  
  Select @RatingCode= RatingCode   
  From fn_PUR_VendorRating_Master('A',@AsonDate,@RptDate,@BranchID,@CompID)   
  Where IsSubContract='0'  
  
 Select x.VendorCode, x.PartyName, (sum(x.DeleiveryPer) / sum(x.cnt)) as DelPer,    
  (sum(x.QualityPer) / sum(x.cnt)) as QuaPer, x.Delivery, x.Quality, x.Price,    
  ((sum(x.DeleiveryPer) / sum(x.cnt)) *  x.Delivery) /100 as DPer,    
  ((sum(x.QualityPer) / sum(x.cnt)) * x.Quality) /100 as QPer,    
  ((sum(x.RatingPercentage) / sum(x.cnt)) * x.Price) /100 as PPer,    
  ((sum(x.FieldPer) / sum(x.cnt)) * x.FieldComplaint) /100 as FieldPer,    
  ((sum(x.PreFri) / sum(x.cnt)) * x.PremiumFreight) /100 as FreightPer,    
  y.Add1, y.Add2, y.Add3, y.City, y.PinCode     
 From     
 (    
  Select a.VendorCode, c.PartyName, a.ItemCode, a.ScheduleQty, f.ReceiptQty,    
   f.AcceptedQty, ((f.ReceiptQty/a.ScheduleQty)* 100) as DeleiveryPer,    
   ((f.AcceptedQty/f.ReceiptQty)* 100) as QualityPer,     
   (    
    Select m.RatingPercentage   
    From dbo.fn_PUR_Get_VendorRating_Item_Rate(@AsonDate, @RptDate, @BranchID , @CompID , @Finyear) m     
    Where m.VendorCode = a.VendorCode and m.ItemCode = a.ItemCode    
   ) as RatingPercentage,    
   e.Delivery , e.Quality, e.Price, e.FieldComplaint, e.PremiumFreight,     
   (    
    Select     
     (    
      Select Percentage     
      From dbo.fn_PUR_VendorRating_FieldComplaint ('A',@AsonDate,@RptDate, @BranchID,@CompID)    
      Where RatingCode=@RatingCode and y.FieldCnt between FromRank and ToRank  
     ) Percentage     
    From    
    (    
     Select count(*) FieldCnt From QC_CustomerComplaintRegister i     
     Where i.CustomerCode = a.VendorCode and i.ComplaintRegisterDate between @FromDate and @ToDate    
      and i.BranchID = a.BranchID and i.CompID = a.Compid    
    )y  
   ) as FieldPer,    
   (    
    Select   
     (  
      Select Percentage     
      From dbo.fn_PUR_VendorRating_PremiumFreight ('A',@AsonDate,@RptDate, @BranchID,@CompID)     
      Where RatingCode=@RatingCode and x.FreightCnt between FromRank and ToRank    
     ) Percentage     
    From    
    (    
     Select count(*) FreightCnt     
     --From dbo.fn_COM_FormulaCalc_Hdr( 'A',@AsonDate,@RptDate, @BranchID,@CompID,@Finyear) g    
	 From COM_FormulaCalc_Hdr g   
     Left Outer Join PUR_PurchaseInvoice_Hdr h     
     On g.DocNo=h.DocNo and g.DocDate=h.DocDate and g.DocType=h.DocType and g.BranchID=h.BranchID and g.CompID=h.CompID and g.Finyear=h.Finyear    
     Where g.PostingAc = 709 and g.DocDate between @FromDate and @ToDate    
     and h.VendorCode = a.VendorCode and g.Branchid = a.Branchid and g.Compid = a.Compid    
    )x  
   ) as PreFri,1 as Cnt    
  From dbo.fn_PUR_Schedule(@AsonDate, @RptDate, @BranchID , @CompID , @Finyear)a    
     
  Left Outer Join   
   (   
    select RefType,RefNo,RefDate,ItemCode,ScheduleDate, IsNull(sum(ReceiptQty), 0) as  ReceiptQty,sum(AcceptedQty) AcceptedQty, Branchid, Compid   
    from REC_ReceiptEntry_Dtl f     
    group by RefType,RefNo,RefDate,ItemCode,ScheduleDate,Branchid,Compid  
   ) f  
   On a.ScheduleNo=f.RefNo and a.ScheduleDate=f.RefDate and a.ScheduleType=f.RefType   
   and a.RequiredDate=f.ScheduleDate and a.ItemCode=f.ItemCode and a.Branchid=f.Branchid and a.Compid=f.Compid    
     
  Left Outer Join     
   (    
    Select top 1 Delivery, Quality, Price, FieldComplaint, PremiumFreight, Branchid, Compid     
    From fn_PUR_VendorRating_Master('A',@AsonDate,@RptDate,@BranchID,@CompID)    
    Where IsSubContract='0'  
   ) e    
   On e.branchid = a.Branchid and e.Compid = a.Compid    
  Left Outer Join dbo.fn_FAS_Party_Master ('M',@AsonDate,@RptDate, @BranchID,@CompID) c    
   On a.VendorCode = c.PartyCode and a.Branchid = c.Branchid  and a.Compid = c.Compid    
  Where a.EffStatus='1' and a.Status not in ('C','S') and f.ReceiptQty > 0 and a.RequiredDate between @FromDate and @ToDate    
   and a.BranchID = @BranchID  and a.CompID = @CompID     
 ) x     
 Left Outer Join dbo.fn_FAS_Party_Address( 'M',@AsonDate,@RptDate, @BranchID,@CompID) y    
  On x.VendorCode = y.PartyCode     
 Where x.VendorCode = @VendorCode and y.BranchID = @BranchID and y.CompID = @CompID    
 Group by x.VendorCode, x.PartyName, x.Delivery, x.Quality, x.Price, x.FieldComplaint, x.PremiumFreight,   
  x.PreFri, x.FieldPer,y.Add1, y.Add2, y.Add3, y.City, y.PinCode     
 Order by x.VendorCode    
    
 End  

GO

