  CREATE PROCEDURE [dbo].[PUR_Rpt_VendorRatingLetter_Gen_Spr_Rate](@IsSubContract bit='1',@Value float, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3))  
As  
  
 Begin   
  
  SET NOCOUNT ON;  
  
  If @Value=''  
  
   Select FromPer, ToPer, Grade, GradeDescription, Delivery, Quality, Price,   
    FieldComplaint, PremiumFreight, BranchID, CompID   
   From dbo.fn_PUR_VendorRating_Master('A',@AsOnDate,@RptDate,@BranchID,@CompID)  
   Where IsSubContract=@IsSubContract and BranchID=@BranchID and CompID=@CompID  
  Else  
     
   Select FromPer, ToPer, Grade, GradeDescription, Delivery, Quality, Price,   
    FieldComplaint, PremiumFreight BranchID, CompID    
   From dbo.fn_PUR_VendorRating_Master('A',@AsOnDate,@RptDate,@BranchID,@CompID)   
   Where IsSubContract=@IsSubContract and BranchID=@BranchID and CompID =@CompID and @Value between FromPer and ToPer  
  
 End  
GO

