CREATE PROCEDURE [dbo].[PUR_Sav_Vendor_ItemMaster]
	(@VendorCode 		[int],
	 @ItemCode 		[varchar](20),
	 @Rate 		[money],
	 @AssessableRate 	[money],
	 @RatePer 		[float],
	@LeadTime		[int],
	@LeadTimeUnit		[char](10),
	 @ValidFrom 		[datetime],
	 @ValidTo 		[datetime],
	 @QcCheck		[bit],
	 @Remarks		[varchar](50),
	 @isActive 		[bit],
	 @FormulaCode	 	[int],
	 @UserID 		[varchar](10),
	 @BranchID 		[varchar](3),
	 @CompID 		[varchar](3))

AS 

	Declare @cBranchid varchar(3)
	
	Declare  BranchidList cursor For
	Select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid
	
	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
		Begin		
			If Exists (Select * from PUR_Vendor_ItemMaster Where VendorCode=@VendorCode and ItemCode=@ItemCode and BranchID=@cBranchID and CompID=@CompID)
	
				Begin
					Execute [dbo].[PUR_Up_Vendor_ItemMaster]
									@VendorCode,
									 @ItemCode,
									 @Rate,
									 @AssessableRate,
									 @RatePer,
								  	 @LeadTime,
									 @LeadTimeUnit,
									 @ValidFrom,
									 @ValidTo,
									 @QcCheck,
									 @Remarks,
									 @isActive,
									 @FormulaCode,
									 @UserID,
									 @cBranchID,
									 @CompID
	
				End
			Else
				Begin
					
					Execute  [dbo].[PUR_Ins_Vendor_ItemMaster]							
									 @VendorCode,
									 @ItemCode,
									 @Rate,
									 @AssessableRate,
									 @RatePer,
									 @LeadTime,
									 @LeadTimeUnit,
									 @ValidFrom,
									 @ValidTo,
									 @QcCheck,
									 @Remarks,
									 @isActive,
									 @FormulaCode,
									 @UserID,
									 @cBranchID,
									 @CompID
				End

			FETCH NEXT FROM BranchidList into @cBranchid 
		END
			 	
	Close BranchIDList
	Deallocate BranchIDList
GO

