/****** Object:  StoredProcedure [dbo].[PUR_VendorRating_Auth]    Script Date: 17/06/2026 11:30:43 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


 CREATE PROCEDURE [dbo].[PUR_VendorRating_Auth] (@AsOnDate datetime, @RatingCode int, @AuthStatus char(2), @AuthDate datetime,  @UserID [varchar](10),  @BranchID Varchar(3), @CompID Varchar(3))    
AS    
BEGIN    
  
  SET NOCOUNT ON    
     
  Declare @RevIncr int    
  Select @RevIncr=Case When Right(@AuthStatus, 1)='A' Then 1 Else 0 End    
      
  Declare @RevNo as int    
      
  Select @RevNo = IsNull(a.RevNo, @RevNo)     
  From fn_PUR_VendorRating_Grp('A', @AsOnDate, @BranchID, @CompID)a    
   Where a.RatingCode = @RatingCode    
      
  --declare @cBranchID varchar(3), @cCompID varchar(3)    
      
  --declare  BranchIDList cursor For    
  --select BranchID, CompID from dbo.fn_COM_Get_BranchCommonOperation(@RevNo, @AsOnDate, @AsOnDate, @BranchID, @CompID)    
  --OPEN BranchIDList    
  --FETCH NEXT FROM BranchIDList into @cBranchID, @cCompID    
  --WHILE @@FETCH_STATUS = 0    
      
  BEGIN    
  --Master Header    
   Insert into PUR_VendorRating_Master    
   Select a.RatingCode, a.FromPer, a.ToPer, a.Grade, a.GradeDescription, a.Delivery, a.Quality, a.Price, a.FieldComplaint, a.PremiumFreight, a.isSubContract, a.Seq,    
     a.RevNo+@RevIncr, Convert(varchar(10),@AsOnDate,120), Right(@AuthStatus, 1)+Right(a.EffStatus, 1),    
    a.EffDate, Case Right(@AuthStatus, 1) When 'H' Then a.isTranLock Else '0' End, @UserID, @BranchID, @CompID, @AsOnDate    
       
   From PUR_VendorRating_Master a    
   Where a.TranStamp = (Select Max(b.TranStamp) From PUR_VendorRating_Master b                  
                Where b.TranStamp <= @AsOnDate and b.RatingCode=a.RatingCode and b.isSubContract=a.isSubContract and b.Seq=a.Seq and b.BranchID=a.BranchID and b.CompID=a.CompID    
              )    
    and a.RatingCode=@RatingCode and a.BranchID=@BranchID and a.CompID=@CompID and Left(a.EffStatus, 1) Not in ('A', 'X')    
  --Price Detail    
   Insert into PUR_VendorRating_Price    
   Select a.RatingCode, a.FromRank, a.ToRank, a.Percentage, a.Seq, a.RevNo+@RevIncr, Convert(varchar(10),@AsOnDate,120), Right(@AuthStatus, 1)+Right(a.EffStatus, 1),     
    a.EffDate, Case Right(@AuthStatus, 1) When 'H' Then a.isTranLock Else '0' End, @UserID, @BranchID, @CompID, @AsOnDate    
   From PUR_VendorRating_Price a    
   Where a.TranStamp = (Select Max(b.TranStamp) From PUR_VendorRating_Price b    
                Where b.TranStamp <= @AsOnDate and b.RatingCode=a.RatingCode and b.Seq=a.Seq and b.BranchID=a.BranchID and b.CompID=a.CompID    
              )    
    and a.RatingCode=@RatingCode and a.BranchID=@BranchID and a.CompID=@CompID  and Left(a.EffStatus, 1) Not in ('A', 'X')    
    
  --PremiumFreight Detail    
   Insert into PUR_VendorRating_PremiumFreight    
   Select a.RatingCode, a.FromRank, a.ToRank, a.Percentage, a.Seq, a.RevNo+@RevIncr, Convert(varchar(10),@AsOnDate,120), Right(@AuthStatus, 1)+Right(a.EffStatus, 1),    
    a.EffDate, Case Right(@AuthStatus, 1) When 'H' Then a.isTranLock Else '0' End, @UserID, @BranchID, @CompID, @AsOnDate    
       
   From PUR_VendorRating_PremiumFreight a    
   Where a.TranStamp = (Select Max(b.TranStamp) From PUR_VendorRating_PremiumFreight b    
                Where b.TranStamp <= @AsOnDate and b.RatingCode=a.RatingCode and b.Seq=a.Seq and b.BranchID=a.BranchID and b.CompID=a.CompID    
              )    
    and a.RatingCode=@RatingCode and a.BranchID=@BranchID and a.CompID=@CompID and Left(a.EffStatus, 1) Not in ('A', 'X')    
  --FieldComplaint Detail    
   Insert into PUR_VendorRating_FieldComplaint    
   Select a.RatingCode,  a.FromRank, a.ToRank, a.Percentage, a.Seq, a.RevNo+@RevIncr, Convert(varchar(10),@AsOnDate,120), Right(@AuthStatus, 1)+Right(a.EffStatus, 1),     
    a.EffDate, Case Right(@AuthStatus, 1) When 'H' Then a.isTranLock Else '0' End, @UserID, @BranchID, @CompID, @AsOnDate    
   From PUR_VendorRating_FieldComplaint a    
   Where a.TranStamp = (Select Max(b.TranStamp) From PUR_VendorRating_FieldComplaint b    
                Where b.TranStamp <= @AsOnDate and b.RatingCode=a.RatingCode and b.Seq=a.Seq and b.BranchID=a.BranchID and b.CompID=a.CompID    
        )    
    and a.RatingCode=@RatingCode and a.BranchID=@BranchID and a.CompID=@CompID  and Left(a.EffStatus, 1) Not in ('A', 'X')    
      
  --DisQualification Detail    
   Insert into PUR_VendorRating_DisQualification    
   Select a.RatingCode, a.Grade, a.DisqualificationCount, a.RevNo+@RevIncr, Convert(varchar(10),@AsOnDate,120), Right(@AuthStatus, 1)+Right(a.EffStatus, 1),     
    a.EffDate, Case Right(@AuthStatus, 1) When 'H' Then a.isTranLock Else '0' End, @UserID, @BranchID, @CompID, @AsOnDate    
   From PUR_VendorRating_DisQualification a    
   Where a.TranStamp = (Select Max(b.TranStamp) From PUR_VendorRating_DisQualification b    
                Where b.TranStamp <= @AsOnDate and b.RatingCode=a.RatingCode and b.Grade=a.Grade and b.DisqualificationCount=a.DisqualificationCount and b.BranchID=a.BranchID and b.CompID=a.CompID    
              )    
    and a.RatingCode=@RatingCode and a.BranchID=@BranchID and a.CompID=@CompID  and Left(a.EffStatus, 1) Not in ('A', 'X')    
        
  
     
  END    
 
  
END   

GO

/****** Object:  StoredProcedure [dbo].[PUR_VendorRating_DisQualification_Ins]    Script Date: 17/06/2026 11:30:43 ******/
