CREATE PROCEDURE [dbo].[PUR_VendorRating_DisQualification_Ins]    
 (@RatingCode  [int],    
  @Grade   [char](1),    
  @DisqualificationCount  [int],    
  @EffStatus  [char](2),    
  @EffDate  [datetime],     
  @IsTranLock  [bit],    
  @UserID  [varchar](10), 
  @BranchID   [varchar](3),    
  @CompID  [varchar](3),    
  @TranStamp  [datetime]    
 )    
AS     
BEGIN    
 SET  NOCOUNT ON    
     
 Declare @RevNo as int    
 Declare @RevDate as datetime    
 Select @RevNo=-1     
 Select @RevDate=Convert(varchar(10),@TranStamp,120)    
 if @EffStatus<>'NA'    
  Begin    
   Select @RevNo = IsNull(a.RevNo, @RevNo) ,  @RevDate =IsNull(a.RevDate, @RevDate)     
   From  fn_PUR_VendorRating_Grp ('W',@TranStamp, @BranchID, @CompID)  a    
   Where a.RatingCode=@RatingCode     
  End    
      
 BEGIN    
  INSERT INTO [PUR_VendorRating_Disqualification]     
   ([RatingCode],    
    [Grade],    
    [DisqualificationCount],    
    [RevNo],    
    [RevDate],    
    [EffStatus],    
    [EffDate],     
    [IsTranLock],      
    [UserID],    
    [BranchID],    
    [CompID],    
    [TranStamp]    
   )     
       
  VALUES     
   (@RatingCode,    
    @Grade,    
    @DisqualificationCount,    
    @RevNo,    
    @RevDate,    
    @EffStatus,    
    @EffDate,     
    @IsTranLock,       
    @UserID,    
    @BranchID,    
    @CompID,    
    @TranStamp    
   )    
     
 END    
    
END    
  
GO

