/****** Object:  StoredProcedure [dbo].[Qc_Auto_Calibrationissue]    Script Date: 17/06/2026 11:30:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Qc_Auto_Calibrationissue]
	(@Branchid	[varchar](3),
	 @Compid 	[varchar](3))

AS 

SET NOCOUNT on

declare @ItemCode varchar(20)
declare @Schedule Datetime
declare @IsInternal varchar(20)
declare @Mintrument varchar(20)
declare @UserId varchar(10)
declare @Finyear varchar(20)
declare @IssueNo int

declare  BranchidList cursor For
	/*Select Distinct a.ItemCode,a.ScheduleDate,'Internal'as isInternal,b.Masterinstrument,b.UserId,b.Branchid,b.Compid,
		Case when a.ScheduleDate between '2005-04-01' and '2006-03-31' then '04-2005 03-2006'
			when a.ScheduleDate between '2006-04-01' and '2007-03-31' then '04-2006 03-2007'
			when a.ScheduleDate between '2007-04-01' and '2008-03-31' then '04-2007 03-2008'
			when a.ScheduleDate between '2008-04-01' and '2009-03-31' then '04-2008 03-2009' else '' end Finyear
	 	from fn_QC_Calibration_IssueItem('2008-11-10' ,'00','01')a
			left outer join Qc_Calibration_Masterinstument b on a.ItemCode=b.ItemCode 
		where ScheduleDate<='2008-10-31' 
			--and (a.ItemCode like 'ASG0%' or a.ItemCode like 'PG00%' or a.ItemCode like 'SG00%')  order by ScheduleDate*/

	/*Select Distinct a.ItemCode,a.ScheduleDate,c.CalibrationFor,b.Masterinstrument,b.UserId,b.Branchid,b.Compid,
		Case when a.ScheduleDate between '2005-04-01' and '2006-03-31' then '04-2005 03-2006'
			when a.ScheduleDate between '2006-04-01' and '2007-03-31' then '04-2006 03-2007'
			when a.ScheduleDate between '2007-04-01' and '2008-03-31' then '04-2007 03-2008'
			when a.ScheduleDate between '2008-04-01' and '2009-03-31' then '04-2008 03-2009' else '' end Finyear
	 	from fn_QC_Calibration_IssueItem('2008-11-12' ,'00','01')a
			left outer join Qc_Calibration_Master c 
				on c.ITemCode=a.ItemCode
			Left outer join Qc_Calibration_Masterinstument b on a.ItemCode=b.ItemCode 
		where ScheduleDate<'2008-11-12' and c.CalibrationFor='Internal'
			and b.Masterinstrument is not null*/
	/*Select Distinct a.ItemCode,a.ScheduleDate,c.CalibrationFor,b.Masterinstrument,b.UserId,b.Branchid,b.Compid,
		Case when a.ScheduleDate between '2005-04-01' and '2006-03-31' then '04-2005 03-2006'
			when a.ScheduleDate between '2006-04-01' and '2007-03-31' then '04-2006 03-2007'
			when a.ScheduleDate between '2007-04-01' and '2008-03-31' then '04-2007 03-2008'
			when a.ScheduleDate between '2008-04-01' and '2009-03-31' then '04-2008 03-2009' else '' end Finyear
	 	from (Select a.* from Qc_Calibration_Schedule a 
		left outer join QC_CalibrationIssue b on b.ItemCode=a.ItemCode and b.ScheduleDate=a.ScheduleDate
		where ActualDate is not null and b.OutofCalibration is null)a
			left outer join Qc_Calibration_Master c 
				on c.ITemCode=a.ItemCode
			Left outer join Qc_Calibration_Masterinstument b on a.ItemCode=b.ItemCode 
		where ScheduleDate<'2008-11-12' and c.CalibrationFor='Internal'
			and b.Masterinstrument is not null*/

	Select Distinct a.ItemCode,a.ScheduleDate,c.CalibrationFor,b.AgencyCode,b.UserId,b.Branchid,b.Compid,
		Case when a.ScheduleDate between '2002-04-01' and '2003-03-31' then '04-2002 03-2003'
			when a.ScheduleDate between '2003-04-01' and '2004-03-31' then '04-2003 03-2004'
			when a.ScheduleDate between '2004-04-01' and '2005-03-31' then '04-2004 03-2005'
			when a.ScheduleDate between '2005-04-01' and '2006-03-31' then '04-2005 03-2006'
			when a.ScheduleDate between '2006-04-01' and '2007-03-31' then '04-2006 03-2007'
			when a.ScheduleDate between '2007-04-01' and '2008-03-31' then '04-2007 03-2008'
			when a.ScheduleDate between '2008-04-01' and '2009-03-31' then '04-2008 03-2009' else '' end Finyear
	 	from (Select a.* from Qc_Calibration_Schedule a 
		left outer join QC_CalibrationIssue b on b.ItemCode=a.ItemCode and b.ScheduleDate=a.ScheduleDate
		where ActualDate is not null and b.OutofCalibration is null)a
					left outer join Qc_Calibration_Master c 
						on c.ITemCode=a.ItemCode
					Left outer join Qc_Calibration_Agency b on a.ItemCode=b.ItemCode 
				where ScheduleDate<='2008-11-11' and c.CalibrationFor='External'

	/*Select Distinct a.ItemCode,a.ScheduleDate,c.CalibrationFor,b.AgencyCode,b.UserId,b.Branchid,b.Compid,
		Case when a.ScheduleDate between '2002-04-01' and '2003-03-31' then '04-2002 03-2003'
			when a.ScheduleDate between '2003-04-01' and '2004-03-31' then '04-2003 03-2004'
			when a.ScheduleDate between '2004-04-01' and '2005-03-31' then '04-2004 03-2005'
			when a.ScheduleDate between '2005-04-01' and '2006-03-31' then '04-2005 03-2006'
			when a.ScheduleDate between '2006-04-01' and '2007-03-31' then '04-2006 03-2007'
			when a.ScheduleDate between '2007-04-01' and '2008-03-31' then '04-2007 03-2008'
			when a.ScheduleDate between '2008-04-01' and '2009-03-31' then '04-2008 03-2009' else '' end Finyear
	 	from fn_QC_Calibration_IssueItem('2008-11-10' ,'00','01')a
			left outer join Qc_Calibration_Master c 
				on c.ITemCode=a.ItemCode
			Left outer join Qc_Calibration_Agency b on a.ItemCode=b.ItemCode 
		where ScheduleDate<='2008-11-11' and c.CalibrationFor='External'*/

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @ItemCode,@Schedule,@IsInternal,@Mintrument,@UserId,@Branchid,@Compid,@Finyear
	Begin Tran
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

		Select @IssueNo=isnull(Max(Issueno),0)+1 from QC_CalibrationIssue where Finyear=@Finyear


			INSERT INTO [QC_CalibrationIssue] 
				 ( [IssueType],
				 [IssueNo],
				 [IssueDate],
				 [ItemCode],
				 [ScheduleDate],
				 [InternalExternal],
				 [AgencyCode],
				 [Remarks],
				 [Userid],
				 [Branchid],
				 [Compid],
				 [Finyear]) 
			 
			VALUES 
			
				( 'CIS',
				 @IssueNo,
				 @Schedule,
				 @ItemCode,
				 @Schedule,
				 Left(@IsInternal,1),
				 @Mintrument,
				 'Auto',
				 @Userid,
				 @Branchid,
				 @Compid,
				 @Finyear)


			 INSERT INTO [dbo].[Qc_CalibrationIssue_Dtl] 
				 ( [ItemCode],
				 [RefType],
				 [RefNo],
				 [RefDate],
				 [CalibrationFor],
				 [Code],
				 [WharehouseCode],
				 [Rackbin],
				 [Userid],
				 [Branchid],
				 [Compid]) 
			 
			VALUES 
				( @ItemCode,
				  'CIS',
				 @IssueNo,
				 @Schedule,
				 @IsInternal,
				 @Mintrument,
				 'CHI',
				 'Auto',
				 @Userid,
				 @Branchid,
				 @Compid)
		
		Update QC_Calibration_Schedule set Status=0 where ItemCode=@ItemCode and ScheduleDate=@Schedule and Branchid=@Branchid and Compid=@Compid

		Update QC_Calibration_Master set Status = 0 where ItemCode=@ItemCode and Branchid=@Branchid and Compid=@Compid
		
		if @@Error<>0
			Begin
				Rollback tran
				Print 'ERROR'
				Goto Err
			End
		

		FETCH NEXT FROM BranchidList into @ItemCode,@Schedule,@IsInternal,@Mintrument,@UserId,@Branchid,@Compid,@Finyear
	END
 	commit tran
Err:
	close BranchidList
	deallocate BranchidList
GO

/****** Object:  StoredProcedure [dbo].[Qc_Auto_CalibrationStatus]    Script Date: 17/06/2026 11:30:44 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[Qc_Auto_CalibrationStatus]
	(@Branchid	[varchar](3),
	 @Compid 	[varchar](3))

AS 

SET NOCOUNT on

declare @ItemCode varchar(20)
declare @ScheduleDate Datetime
declare @IssueType varchar(3)
declare @IssueNo int
declare @IssueDate Datetime
Declare @Userid varchar(10)
declare @Sno varchar(3)
Declare @Parameter varchar(20)
Declare @ObservedValue float
declare @Finyear varchar(20)


declare  BranchidList cursor For
	 Select a.IssueType,a.IssueNo,a.IssueDate,a.ItemCode,a.ScheduleDate,a.UserID,Finyear  From QC_CalibrationIssue a 
		where (a.CalibrationStatus=0  and OutofCalibration='') and a.Branchid = @Branchid and a.Compid =@Compid
		
		/*	and Not Exists (Select * from (select ItemCode,Max(ScheduleDate)ScheduleDate from Qc_Calibration_Schedule group by ItemCode)x 
			where ScheduleDate=a.ScheduleDate and ItemCode=a.ItemCode)*/

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @IssueType,@IssueNo,@IssueDate,@ItemCode,@ScheduleDate,@UserId,@Finyear
	Begin Tran
	WHILE @@FETCH_STATUS = 0
	
	BEGIN

			 UPDATE [QC_CalibrationIssue] 

				SET  	 [ReceivedDate]		 = Dateadd(d,2,@ScheduleDate),
					 [CalibrationDate]	 = Dateadd(d,1,@ScheduleDate),
					 [CalibrationStatus]	 = 1,
					 [OutofCalibration]	 = '',
					 [RefNo]		 = 'RR'+Convert(varchar(10),Dateadd(d,2,@ScheduleDate),120),
					 [RefDate]		 =Dateadd(d,2,@ScheduleDate),
					 [Reason]		 = '',
					 [ApprovedBy]		 = @UserId
				
				WHERE 
				
					( [IssueType]	 = @IssueType AND
					 [IssueNo]	 = @IssueNo AND
					 [IssueDate]	 = @IssueDate AND
					 [ItemCode]	 = @ItemCode AND
					 [ScheduleDate]	 = @ScheduleDate AND
					 [Branchid]	 = @Branchid AND
					 [Compid]	 = @Compid AND
					 [Finyear]	 = @Finyear)

		Declare  Parameter cursor For
			Select Distinct Sno,Parameter,case when (Tovalue-0.001)<0 then Tovalue else (Tovalue-0.001) end Observed
				from Qc_Calibration_Parameter where ItemCode=@ItemCode

			OPEN Parameter
				FETCH NEXT FROM Parameter into @Sno,@Parameter,@ObservedValue
			
			WHILE @@FETCH_STATUS = 0
			
			BEGIN

				INSERT  INTO [QC_CalibrationStatus_Parameter] 
					 ( [IssueType],
					 [IssueNo],
					 [IssueDate],
					 [ItemCode],
					 [Sno],
					 [Parameter],
					 [ObservedValue],
					 [Userid],
					 [Branchid],
					 [Compid],
					 [Finyear]) 
				 
				VALUES 
					( @IssueType,
					 @IssueNo,
					 @IssueDate,
					 @ItemCode,
					 @Sno,
					 @Parameter,
					 @ObservedValue,
					 @Userid,
					 @Branchid,
					 @Compid,
					 @Finyear)

				FETCH NEXT FROM Parameter into @Sno,@Parameter,@ObservedValue
			END
		
		Update QC_Calibration_Master set Status = 0 where ItemCode = @ItemCode 

		Update QC_Calibration_Schedule set ActualDate = @ScheduleDate Where ItemCode = @ItemCode
  			 and ScheduleDate =@ScheduleDate

		close Parameter
		deallocate Parameter
		
		if @@Error<>0
			Begin
				Rollback tran
				Print 'ERROR'
				Goto Err
			End
		

	FETCH NEXT FROM BranchidList into @IssueType,@IssueNo,@IssueDate,@ItemCode,@ScheduleDate,@UserId,@Finyear
	END
 	commit tran
Err:
	close BranchidList
	deallocate BranchidList
GO

