CREATE PROCEDURE [dbo].[QC_INS_Inspection_ItemCodes] @item varchar(10)

as	

SET NOCOUNT ON

Select	i.inspectiontypeShortName,  i.inspectiontypeDescription,   q.qualityplantypeShortName,  
q.qualityplantypedescription,     p.parametercode parametercode, 
s.samplingplantypeShortName ,    s.samplingplantypeDescription,   s.InspectionLevelcode,    
s.AQLevelcode,     s.SamplingPlanTypeCode,    i.inspectiontypecode,     
q.qualityplantypecode,p.NoofReadings 
from	Qc_InspectionType_Master i,  Qc_SamplingPlantype_Master s,   Qc_QualityPlantype_Master q, 
Qc_inspection_Master p 
Where   p.Inspectiontypecode = i.inspectiontypecode And i.SamplingPlantypecode = s.samplingplantypecode 
and i.qualityplantypecode = q.qualityplantypecode
and 	p.ItemCode= @item


GO

