CREATE PROCEDURE [dbo].[QC_INS_Inspection_Itemcodes2]	@item  varchar(20) 

AS

SET NOCOUNT ON

select Distinct         v.ShortName , v.InstrumentTypeCode, 
                 v.fromValue, v.tovalue, v.Mean, v.defect,v.validate
	 from 		    Qc_inspection_master v 
	 inner join  Qc_Instrumentgroup_Master i 
	 on   v.Itemcode =i.Itemcode and v.instrumenttypecode = i.instrumenttypecode
	where v.Itemcode= @item


GO

