/****** Object:  StoredProcedure [dbo].[Qc_INS_InstrumentTran_Dtl]    Script Date: 17/06/2026 11:30:48 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Qc_INS_InstrumentTran_Dtl]
	(@ItemCode 	[varchar](20),
	 @RefType 	[varchar](3),
	 @RefNo 	[int],
	 @RefDate 	[datetime],
	 @CheckingQty 	[float],
	 @Userid 	[varchar](10),
	 @Branchid 	[varchar](3),
	 @Compid 	[varchar](3))

AS
	IF Not Exists(Select * from Qc_InstrumentTran_Dtl where ItemCode=@ItemCode and RefType=@RefType and RefNo=@RefNo and RefDate=@RefDate and Branchid=@Branchid and Compid=@Compid)

		 INSERT INTO [TERP].[dbo].[Qc_InstrumentTran_Dtl] 
			 ( [ItemCode],
			 [RefType],
			 [RefNo],
			 [RefDate],
			 [CheckingQty],
			 [Userid],
			 [Branchid],
			 [Compid]) 
		 
		VALUES 
			( @ItemCode,
			 @RefType,
			 @RefNo,
			 @RefDate,
			 @CheckingQty,
			 @Userid,
			 @Branchid,
			 @Compid)
	Else
		UPDATE [dbo].[Qc_InstrumentTran_Dtl] 

		SET  	 [CheckingQty]	 =CheckingQty+ @CheckingQty
		
		WHERE 
			( [ItemCode]	 = @ItemCode AND
			 [RefType]	 = @RefType AND
			 [RefNo]	 = @RefNo AND
			 [RefDate]	 = @RefDate AND
			 [Branchid]	 = @Branchid AND
			 [Compid]	 = @Compid)
GO

