SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[Qc_INS_MaxTime_tmp]
	(@DocType 	[varchar](50),
	 @DocNo 	[int],
	 @DocDate 	[datetime],
	 @Maxtime 	[datetime],
	 @Logtime 	[datetime],
	 @Flg		[char](1))

AS 

	IF Not exists (select *from [dbo].[Qc_MaxTime_tmp] where DocType=@DocType  and Docno=@DocNo  and DocDate=@DocDate)
		Begin
			INSERT INTO [dbo].[Qc_MaxTime_tmp] 
				 ( [DocType],
				 [DocNo],
				 [DocDate],
				 [Maxtime]) 
			 
			VALUES 
				( @DocType,
				 @DocNo,
				 @DocDate,
				 @Maxtime)
		End
	Else
		Begin
			if @Flg='P'
				Begin
					UPDATE [dbo].[Qc_MaxTime_tmp] 
					Set [Maxtime]=@Maxtime
					WHERE
						([DocType]= @DocType and
						 [DocNo]=@DocNo and
						 [DocDate]=@DocDate)
				End
			else
			 	Begin
					UPDATE [dbo].[Qc_MaxTime_tmp] 
					Set [LogTime]=@LogTime
					WHERE
						([DocType]= @DocType and
						 [DocNo]=@DocNo and
						 [DocDate]=@DocDate)
				End

		End
GO

