CREATE PROCEDURE [dbo].[QC_Inspection_Fil_Option]
(
    @Code VARCHAR(50),
    @InspTypeCode INT,
    @BranchID VARCHAR(3),
    @CompID VARCHAR(3)
)
AS
BEGIN
    SET NOCOUNT ON;
	
	Declare @OptCode As int;  
	SET @OptCode = 7;		-- LOG ENTRY AT SHIFT END   

    SELECT 
        a.Code,
        a.Description,
        a.UOM,
        ISNULL(b.val,'') AS Val,
		ISNULL(b.val,'') AS Value,		--> in various forms hanling --> Val/Value
        ISNULL(b.isval,0) AS isval,
		b.CarStatus
    FROM COM_Inspection_Option_Hdr a
    LEFT OUTER JOIN COM_Inspection_Option_Dtl b 
        ON a.Code = b.Code
        AND b.InspectionTypeCode = @InspTypeCode
        AND b.BranchID = @BranchID
        AND b.CompID = @CompID
    WHERE a.Code<>@OptCode
        AND (@Code IS NULL OR @Code = '')
        OR a.Code IN (
            SELECT CAST(Value AS INT)
            FROM dbo.fn_SplitString(@Code, '-')
        )
    ORDER BY a.Code
END
GO

