/****** Object:  StoredProcedure [dbo].[QC_Inspection_Get_Finyear]    Script Date: 17/06/2026 11:30:49 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QC_Inspection_Get_Finyear](@AsOnDate datetime, @RptDate datetime,   
	@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))      
As    
BEGIN    
	SET NOCOUNT ON;  

	Declare @CurrYear As int;
	Declare @PrevYear As int;

	Select @CurrYear=IsNull(@CurrYear,0), @PrevYear=IsNull(@PrevYear,0); 
	
	If IsNull(@Finyear,'')<>''
	 Begin
		SET @CurrYear=SubString(@Finyear,4,4);
		SET @PrevYear= Case When (@CurrYear-1)>0 Then (@CurrYear-1) Else 0 End;

		Select @CurrYear=IsNull(@CurrYear,0), @PrevYear=IsNull(@PrevYear,0); 
	 End	
   
  Select Distinct a.FromYear, DateAdd(Second,-1,DateAdd(day,1,a.ToYear)) As ToYear,    
		(Case When Len(Convert(varchar(2),Month(a.FromYear)))=1 Then '0' Else '' End)+(Convert(varchar(2),Month(a.FromYear))+'-'+Convert(varchar(4),Year(a.FromYear)))+' '+(Case When Len(Convert(varchar(2),Month(a.ToYear)))=1 Then '0' Else '' End)+(Convert(varchar(2),Month(a.ToYear))+'-'+Convert(varchar(4),Year(a.ToYear))) As Finyear
	From Company_Finyear a  
	Where Year(a.FromYear)=@PrevYear and a.BranchID=@BranchID and a.CompID=@CompID
	Order by FromYear Desc 
END  
GO

