CREATE PROCEDURE [dbo].[QC_Inspection_Get_Machine](@DocType varchar(3), @DocNo int, @DocDate datetime, @ShiftCode varchar(3), 
	@InspnTypeCode int=0, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), 
	@PrevFinyear Varchar(20)='', @Finyear Varchar(20)='')                                                  
AS                                      
BEGIN                                      
	SET NOCOUNT ON;

	Select Distinct a.MachineCode, Convert(varchar(16),a.StartTime,120) As StartTime,
      Convert(varchar(16),EndTime,120) As EndTime, Convert(varchar(5),a.TobeEnterTime,108) As TobeEnterTime, a.Status 
	From dbo.fn_QC_PatrolInspectionItemSelect(@DocType, @DocNo, @DocDate, @ShiftCode, @BranchID, @CompID) a
	Left Outer Join QC_Inspection_Hdr b 
		On a.DocNo=b.RefNo and a.DocDate=b.RefDate and a.DocType=b.RefType 
			and a.StageCode=b.ItemCode and a.MachineCode=b.MachineCode and a.BranchID=b.BranchID and a.CompID=b.CompID
	Where IsNull(b.InspectionTypeCode, @InspnTypeCode)=@InspnTypeCode and a.BranchID=@BranchID and a.CompID=@CompID
END
