/****** Object:  StoredProcedure [dbo].[QC_Inspection_Get_MaxParamReadingData]    Script Date: 17/06/2026 11:30:49 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QC_Inspection_Get_MaxParamReadingData](@ItemCode varchar(20), @InspectionTypeCode int,    
@BranchID varchar(3), @CompID varchar(3))            
As            
BEGIN            
 SET NOCOUNT ON;    
 /* Note: QC_Inspection_Master - Table Fields    
      NoofReadings      --> No. Of Sample (NOS)    
      NoOfReadingsPerSample  --> No. Of Reading Per Sample (NORPS)    
 */    
    
 /* Get Max NoOfReadings Per Sample */    
 Begin    
  /* Output */    
  Select Top 1 IsNull(x.MaxActualNo,0) As MaxActualNo, IsNull(x.AlternateConvFactor,0) As AlternateConvFactor,     
     IsNull(x.IsReqAlterUomToInspect ,'0') As IsReqAlterUomToInspect, b.SDesc as AlternateUOMDesc, b.NoofDecimals, c.UOMDesc  as ActUOMDesc  
  From (Select Max(a.NoOfReadingsPerSample) As MaxActualNo, a.AlternateConvFactor, a.IsReqAlterUomToInspect,   
    a.AlternateUOM, a.BranchID, a.CompID   
     From QC_Inspection_Master a      
     Where a.ItemCode=@ItemCode and a.InspectionTypeCode=@InspectionTypeCode and a.Inspect='1'     
        and a.BranchID=@BranchID and a.CompID=@CompID    
     Group by a.AlternateConvFactor, a.IsReqAlterUomToInspect, a.AlternateUOM, a.BranchID, a.CompID      
  ) x    
   Left Outer Join Inv_Uom_Master b  
  On x.AlternateUOM=b.Code and x.BranchID=b.BranchID and x.CompID=b.CompID    
  Left Outer Join Material_Master c 
	On c.ItemCode=@ItemCode and  x.Branchid = c.Branchid and x.Compid = c.Compid   
 End            
END 
GO

/****** Object:  StoredProcedure [dbo].[QC_Inspection_Get_ParamReadingData]    Script Date: 17/06/2026 11:30:49 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QC_Inspection_Get_ParamReadingData](@ItemCode varchar(20), @MParamCode int, @InspectionTypeCode int,
@BranchID varchar(3), @CompID varchar(3))        
As        
BEGIN        
	SET NOCOUNT ON;
	/* Note: QC_Inspection_Master - Table Fields
						NoofReadings						--> No. Of Sample (NOS)
						NoOfReadingsPerSample		--> No. Of Reading Per Sample (NORPS)
	*/

	Declare @MaxSampleNo As int;
	Declare @MaxActualNo As int;

	/* Get ItemCode Based Max NoOfReadings (No. Of Sample (NOS)) Data */
	Begin
		Select @MaxSampleNo=Max(a.NoofReadings), @MaxActualNo=Max(a.NoOfReadingsPerSample) 
		From QC_Inspection_Master a 
		Where a.ItemCode=@ItemCode and a.InspectionTypeCode=@InspectionTypeCode and a.Inspect='1'  
					and a.BranchID=@BranchID and a.CompID=@CompID  
	End

	/* Output - ItemCode & MParamCode Based ActualNo Data */
  Select Distinct a.ItemCode, a.MParamCode, IsNull(a.NoOfReadingsPerSample,0) As ActualNo, 
					IsNull(@MaxSampleNo,0) As MaxSampleNo, IsNull(@MaxActualNo,0) As MaxActualNo      
  From QC_Inspection_Master a	          
  Where a.ItemCode=@ItemCode and a.MParamCode=@MParamCode and a.InspectionTypeCode=@InspectionTypeCode 
				and a.Inspect='1' and a.BranchID=@BranchID and a.CompID=@CompID       
END
GO

