CREATE PROCEDURE [dbo].[QC_Inspection_Hlp_Document](@LogSheet bit='0', @InspnTypeCode int=0, @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @PrevFinyear Varchar(20)='', @Finyear Varchar(20)='')                                                
AS                                      
BEGIN                                      
	SET NOCOUNT ON;
	
	If @LogSheet='1'
	 Begin
		Select Distinct a.DocType, a.DocNo, a.DocDate, a.StartDate,
			Shift, (select convert(varchar,DateAdd(n,s.ShiftMinutes, a.StartDate+convert(varchar(5),s.StartTime,108)),120) 
							From PPC_Shift_MAster s
							Where s.ShiftCode=a.Shift and s.BranchID=a.BRanchID and s.CompID=a.CompID) As EndTime, 
							0 As InspectionTypeCode, a.Finyear
		From PPC_QuickProductionplan_Dtl a  
		Where Not Exists(Select * From Qc_Inspection_Master b 
									Where b.ItemCode=a.StageCode and b.BranchID=a.BranchID
										and a.CompID=b.CompID and b.InspectionTypeCode=@InspnTypeCode) 
			and a.ShortClose=0 and a.BranchID=@BranchID and a.CompID=@CompID 
			and (@Finyear='' or (@Finyear<>'' and a.Finyear In(@Finyear,@PrevFinyear)))				
		Order by a.DocDate Desc, a.DocNo Desc
	 End
	Else
	 Begin
		Select Distinct a.DocType, a.DocNo, a.DocDate,  a.StartDate, 
			Shift, (select convert(varchar,DateAdd(n,s.ShiftMinutes, a.StartDate+convert(varchar(5),s.StartTime,108)),120) 
							From PPC_Shift_MAster s
							Where s.ShiftCode=a.Shift and s.BranchID=a.BRanchID and s.CompID=a.CompID) As EndTime, 
							b.InspectionTypeCode, a.Finyear
		From PPC_QuickProductionplan_Dtl a 
		Inner Join Qc_Inspection_Master b
		On a.StageCode=b.ItemCode and a.BranchID=b.BranchID and b.CompID=a.CompID 
		Where b.InspectionTypeCode=@InspnTypeCode 		
			--and Not Exists(Select * From Qc_Inspection_Hdr b 
			--						Where b.InspectionType = 'PIR' and b.RefType=a.DocType and b.RefNo=a.DocNo and b.RefDate=a.DocDate and b.MachineCode=a.MachineCode 
			--						and b.ItemCode=a.StageCode and b.Shift=a.Shift and b.BranchID=a.BranchID and a.CompID=b.CompID and a.Finyear = b.Finyear) 
			and a.ShortClose=0 and a.BranchID=@BranchID and a.CompID=@CompID
			and (@Finyear='' or (@Finyear<>'' and a.Finyear In(@Finyear,@PrevFinyear)))
		Order by a.Finyear Desc, a.DocDate Desc, a.DocNo Desc
	 End	 
END
GO

