CREATE PROCEDURE [dbo].[QC_Inspection_Hlp_Instrument](@InstrumentType varchar(50), 
			@BranchID varchar(3), @CompID varchar(3))      
AS      
BEGIN      
	SET NOCOUNT ON;

	Select Distinct a.ItemCode 
	From BOM_InstrumentGroup_Master a 
	Inner Join QC_Calibration_Master b 
		On a.ItemCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID
	Where a.InstrumentTypeCode In(Select InstrumentTypeCode From BOM_InstrumentType_Master i1
													Where i1.InstrumentType=@InstrumentType and i1.BranchID=@BranchID and i1.CompID=@CompID)
				and a.BranchID=@BranchID and a.CompID=@CompID
END
