CREATE PROCEDURE [dbo].[QC_Inspection_Hlp_Item](@IsSetup bit='0', @DocType varchar(3), @DocNo int, @DocDate datetime,
	@MachineCode varchar(20), @InspTypeCode int, @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @PrevFinyear Varchar(20)='', @Finyear Varchar(20)='')                                                  
AS                                      
BEGIN                                      
	SET NOCOUNT ON; 

	If @IsSetup='1'
	 Begin
		Select Distinct a.StageCode, a.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo,
			a.WorkOrderDate, a.UOMDesc, a.CycleTime, Convert(varchar(16),a.StartTime,120) As StartTime,
			Convert(varchar(16),a.EndTime,120) As EndTime, Convert(varchar(16),a.ToBeEnterTime,120) As TobeEnterTime,
			a.Status, IsNull(a.DrawingCode,'') As DrawingCode, convert(varchar(16),a.ToBeEnterTime,120) As sTime
		From QC_SetupItem_Select_Tmp a
		Left Outer Join Qc_Inspection_Hdr b
			On a.DocNo=b.RefNo and a.DocDate=b.RefDate and a.DocType=b.RefType
				and a.StageCode=b.ItemCode and a.StartTime=b.Starttime and a.MachineCode=b.MachineCode 
				and b.InspectionTypeCode=@InspTypeCode and a.BranchID=b.BranchID and a.CompID=b.CompID
		Where a.Docno=@DocNo and a.DocDate=@DocDate and a.DocType=@DocType and (b.InspectionType Is Null)
			and a.Branchid=@BranchID and a.CompID=@CompID
	 End
	Else
	 Begin
		Select Distinct x.StageCode, x.ItemDescription, x.MachineCode, x.WorkOrderType, x.WorkOrderNo,
			x.WorkOrderDate, x.UOMDesc, x.CycleTime, x.StartTime, x.EndTime, x.TobeEnterTime,
			x.Status, IsNull(x.DrawingCode,'') As DrawingCode, x.sTime
		From (
			Select Distinct a.StageCode, a.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo,
				a.WorkOrderDate, a.UOMDesc, a.CycleTime, Convert(varchar(16),a.StartTime,120) As StartTime,
				Convert(varchar(16),a.EndTime,120) As EndTime, Convert(varchar(16),a.ToBeEnterTime,120) As TobeEnterTime,
				a.Status, IsNull(a.DrawingCode,'') As DrawingCode, convert(varchar(16),a.ToBeEnterTime,120) As sTime,
				a.BranchID, a.CompID
			From QC_PatrolItem_Select_Tmp a
			Left Outer Join QC_Inspection_Hdr b
				On a.DocNo=b.RefNo and a.DocDate=b.RefDate and a.DocType=b.RefType
					and a.StageCode=b.ItemCode and a.StartTime=b.Starttime and a.MachineCode=b.MachineCode 
					and b.InspectionTypeCode=@InspTypeCode and a.BranchID=b.BranchID and a.CompID=b.CompID
			Where a.Docno=@DocNo and a.DocDate=@DocDate and a.DocType=@DocType and (b.InspectionType Is Null)
				and a.BranchID=@BranchID and a.CompID=@CompID 
		) x
		Where x.MachineCode=@MachineCode and x.BranchID=@BranchID and x.CompID=@CompID
	 End
END
GO

