CREATE PROCEDURE [dbo].[QC_Inspection_Hlp_Machine](@IsSetup bit='0', @DocType varchar(3), @DocNo int, 
	@DocDate datetime, @InspTypeCode int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), 
	@CompID varchar(3), @PrevFinyear Varchar(20)='', @Finyear Varchar(20)='')                                                  
AS                                      
BEGIN                                      
	SET NOCOUNT ON; 

	If @IsSetup='1'
	 Begin
	  Select Distinct a.MachineCode, c.ItemDescription, Convert(varchar(16),a.TobeEnterTime,120) As TobeEnterTime,
			a.Status 
		From QC_SetupItem_Select_Tmp a
		Left Outer Join QC_Inspection_Hdr b 
			On b.RefNo=a.DocNo and b.RefDate=a.DocDate and b.RefType=a.DocType
				and a.StartTime=b.Starttime and b.ItemCode=a.StageCode and b.MachineCode=a.MachineCode 
				and b.InspectionTypeCode=@InspTypeCode and b.BranchID=a.BranchID and b.Compid=a.CompID
		Left Outer Join Inv_Material_Master c 
			On a.MachineCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID 
		Where a.Docno=@DocNo and a.DocDate=@DocDate and a.DocType=@DocType and (b.InspectionType Is Null)
			and a.Branchid=@BranchID and a.CompID=@CompID 
	 End
	Else
	 Begin
		Select Distinct a.MachineCode, c.ItemDescription, Convert(varchar(16),a.TobeEnterTime,120) As TobeEnterTime,
			a.Status 
		From Qc_PatrolItem_Select_Tmp a
		Left Outer Join Qc_Inspection_Hdr b 
			On b.RefNo=a.DocNo and b.RefDate=a.DocDate and b.RefType=a.DocType
				and a.StartTime=b.Starttime and b.ItemCode=a.StageCode and b.MachineCode=a.MachineCode 
				and b.InspectionTypeCode=@InspTypeCode and b.BranchID=a.BranchID and b.Compid=a.CompID
		Left Outer Join Inv_Material_Master c 
			On a.MachineCode=c.ItemCode and a.BranchID=c.BranchID and a.CompID=c.CompID 
		Where a.Docno=@DocNo and a.DocDate=@DocDate and a.DocType=@DocType and (b.InspectionType Is Null)
			and a.Branchid=@BranchID and a.CompID=@CompID 
	 End
END
GO

