CREATE PROCEDURE [dbo].[QC_Inspection_Ins_SetupPatrol](@IsSetup bit='0', @DocType varchar(3), @DocNo int, @DocDate datetime,
	@ShiftCode varchar(3), @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), 
	@PrevFinyear Varchar(20)='', @Finyear Varchar(20)='')                                                  
AS                                      
BEGIN                                      
	SET NOCOUNT ON;    

	If @IsSetup='1'					/* Setup Inspection */
	 Begin
		/* Insert Data Into Temp Table */
		Insert Into Qc_SetupItem_Select_Tmp

		Select a.DocType, a.DocNo, a.DocDate, a.StageCode, a.ItemDescription, a.MachineCode, 
			a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.UOMDesc, a.CycleTime, a.StartTime, 
			a.EndTime, a.ToBeEnterTime, a.Status, a.DrawingCode, a.BranchID, a.CompID 
		From dbo.fn_QC_PatrolInspectionItemSelect(@DocType, @DocNo, @DocDate, @ShiftCode, @BranchID, @CompID) a
		Where a.Docno=@DocNo and a.DocDate=@DocDate and a.DocType=@DocType
				and a.Branchid=@BranchID and a.CompID=@CompID
	 End
	Else										/* Patrol Inspection */
	 Begin
		/* Insert Data Into Temp Table */
		Insert Into QC_PatrolItem_Select_Tmp

		Select a.DocType, a.DocNo, a.DocDate, a.StageCode, a.ItemDescription, a.MachineCode, 
			a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.UOMDesc, a.CycleTime, a.StartTime, 
			a.EndTime, a.ToBeEnterTime, a.Status, a.DrawingCode, a.BranchID, a.CompID 
		From dbo.fn_QC_PatrolInspectionItemSelect(@DocType, @DocNo, @DocDate, @ShiftCode, @BranchID, @CompID) a
		Where a.Docno=@DocNo and a.DocDate=@DocDate and a.DocType=@DocType
				and a.Branchid=@BranchID and a.CompID=@CompID
	 End
END
GO

