CREATE PROCEDURE [dbo].[QC_Inspection_Val](@DocType varchar(3), @DocNo int, @DocDate datetime,
	@MachineCode varchar(20), @ItemCode varchar(20), @ShiftCode varchar(3), @EndTime datetime, 
	@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), 
	@PrevFinyear Varchar(20)='', @Finyear Varchar(20)='')                                                  
AS                                      
BEGIN                                      
	SET NOCOUNT ON;

	Select Distinct a.DocType, a.DocNo, a.DocDate, a.StartDate, a.NoofDay, a.PlanType, a.StageCode,
	 a.OperationName, a.CurStock, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate,
	 a.BAlOrderQty, a.Starttime, a.Endtime, a.Shift, a.Date1, a.BalanceQty, a.Priority, a.Remarks,
	 a.Operator, a.Inchargename, a.Status, a.Reason, a.RevisionNo, a.Seq, a.UserID, a.BranchID,
	 a.CompID, a.Finyear, a.ShortClose
	From PPC_QuickProductionplan_Dtl a
	Left Outer Join QC_Inspection_Hdr e 
		On a.DocType=e.RefType and a.DocNo=e.RefNo
			and a.DocDate=e.RefDate and  a.StartTime=e.Starttime and a.MachineCode=e.MachineCode 
			and a.StageCode=e.ItemCode and a.BranchID=e.BranchID and a.CompID=e.CompID
	Where a.Docno=@DocNo and a.DocDate=@DocDate and a.DocType=@DocType and a.Shift=@ShiftCode
		and a.OperationName='SETTING' and a.EndTime<=@EndTime
		and a.RevisionNo=(Select Max(p1.RevisionNo) From PPC_QuickProductionplan_Dtl	p1
											Where p1.DocNo=a.DocNo and p1.DocDate=a.DocDate and p1.DocType=a.DocType  
												and p1.BranchID=@BranchID and p1.CompID=@CompID)
	and a.Status<>0 and IsNull(e.SetupApprovel,1)=1 and IsNull(e.inspectionTypeCode,16)=16 
	and a.StageCode=@ItemCode and (e.CompletedDate Is Null) and a.MachineCode=@MachineCode
					and a.BranchID=@BranchID and a.CompID=@CompID
END
GO

