CREATE  PROCEDURE [dbo].[QC_InspectionCreate_Tfr_Tool](@ItemCode varchar(20), @MachineCode varchar(20), 
@ToolCode As varchar(20), @AsOnDate datetime, @BranchID varchar(3), @CompID varchar(3))  
  
 As  
  
 BEGIN  
  
 SET NOCOUNT ON   
  
  If @ItemCode<>''  
   Begin    
    Select Distinct a.Toolcode  
    From dbo.fn_BOM_StagewiseToolMaster_Dtl(@AsOnDate, @BranchID, @CompID) a  
    Where a.ItemCode=@ItemCode and a.BranchID=@BranchID and a.CompID=@CompID  
   End  
  
  Else  
  
   Begin  
    Select Distinct a.LogQty, a.AssetToolCode, a.MachineCode, a.TCount  
    From QC_ToolMonitoring_Dtl a  
    Where a.TCount=( Select Max(b.TCount) As TCount  
                From QC_ToolMonitoring_Dtl b  
          Where a.ToolCode=b.Toolcode and a.BranchID=b.BranchID and a.CompID=b.CompID  
             )   
      and a.Toolcode=@Toolcode and a.MachineCode=@MachineCode  
      and a.RetType='1' and a.Status='1'  
   End  
  
 END  
GO

