CREATE PROCEDURE [dbo].[QC_InspectionModify_Get_ParamReadingData](@InspectionType varchar(3), @InspectionNo int,   
@InspectionDate datetime, @ItemCode varchar(20), @MParamCode int, @BranchID varchar(3),   
@CompID varchar(3), @Finyear varchar(20))          
As          
BEGIN          
 SET NOCOUNT ON;  
  
 Declare @MaxParamActualNo As int;  
  
 /* Get ItemCode & MParamCode Based Max ActualNo (NoOfReadings Per Sample)  Data */  
 Begin  
  Select @MaxParamActualNo=Max(a.ActualNo)  
  From QC_Inspection_Dtl a   
  Where a.InspectionNo=@InspectionNo and a.InspectionDate=@InspectionDate   
     and a.InspectionType=@InspectionType   
     and Exists(Select * From QC_Inspection_Hdr h1   
          Where h1.InspectionNo=a.InspectionNo and h1.InspectionDate=a.InspectionDate  
             and h1.InspectionType=a.InspectionType  
             and (@ItemCode='' or (@ItemCode<>'' and h1.ItemCode=@ItemCode))  
             and h1.BranchID=@BranchID and h1.CompID=@CompID and h1.Finyear=@Finyear   
          )            
     and a.MParamCode=@MParamCode and a.BranchID=@BranchID and a.CompID=@CompID   
     and a.Finyear=@Finyear    
 End  
  
 /* Output - SampleNo/MaxParamActualNo/ActualNo/ActualReading Data */  
 Select Distinct @ItemCode As ItemCode, a.MParamCode, IsNull(a.SampleNo,0) As SampleNo,   
    @MaxParamActualNo As MaxParamActualNo, IsNull(a.ActualNo,0) As ActualNo,   
    IsNull(a.ActualReading,0) As ActualReading  
 From QC_Inspection_Dtl a  
 Where a.InspectionNo=@InspectionNo and a.InspectionDate=@InspectionDate   
     and a.InspectionType=@InspectionType   
     and Exists(Select * From  QC_Inspection_Hdr h1   
          Where h1.InspectionNo=a.InspectionNo and h1.InspectionDate=a.InspectionDate  
             and h1.InspectionType=a.InspectionType  
             and (@ItemCode='' or (@ItemCode<>'' and h1.ItemCode=@ItemCode))  
             and h1.BranchID=@BranchID and h1.CompID=@CompID and h1.Finyear=@Finyear   
          )  
     and a.MParamCode=@MParamCode and a.BranchID=@BranchID and a.CompID=@CompID   
     and a.Finyear=@Finyear    
 Order by ItemCode, a.MParamCode, SampleNo, ActualNo  
END
GO

