CREATE PROCEDURE [dbo].[QC_InspectionModify_Trn](@DocType varchar(3),@DocNo int,@DocDate datetime,@StageCode varchar(20),
@MachineCode varchar(20), @Starttime datetime, @BranchID varchar(3), @CompID varchar(3),@Finyear Varchar(20))  
As  
  
SET NOCOUNT ON  
  
 Begin  

    Select StartTime,EndTime,Priority,RevisionNo  
    From PPC_QuickProductionplan_Dtl a   
    Where Docno=@DocNo and DocDate=@DocDate and DocType=@DocType and StageCode=@StageCode and MachineCode=@MachineCode 
    and a.RevisionNo=  
    (  
        Select Max(RevisionNo)   
        From PPC_QuickProductionplan_Dtl    
        Where A.DocNo = DocNo And A.DocDate = DocDate And A.DocType = DocType and a.Branchid=BranchID and a.Compid=CompID
		and a.Finyear = Finyear  
    )   
    and Priority =  
    (  
        Select distinct Priority   
        From  PPC_QuickProductionplan_Dtl   
        Where Docno=a.Docno and DocDate=a.DocDate and DocType=a.DocType  
        and StageCode=a.StageCode and MachineCode=a.MachineCode and OperationName = a.OperationName and Starttime=@Starttime   
        and a.RevisionNo=  
        (  
            Select Max(RevisionNo)   
            From PPC_QuickProductionplan_Dtl    
            Where A.DocNo = DocNo And A.DocDate = DocDate And A.DocType = DocType and a.Branchid=BranchID and a.Compid=CompID   
        	and a.Finyear = Finyear  
	)  
    )+1   
    and Branchid=@BranchID and Compid=@CompID and Finyear=@Finyear  
      
 End
GO

