CREATE PROCEDURE [dbo].[QC_LogItemSelect] (@PlanType varchar(3), @PlanNo int, @PlanDate datetime, @ShiftCode varchar(3), @BranchID varchar(3), @CompID varchar(3))  


AS  

BEGIN 

	Declare @PatrolCode int
	Declare @PatrolDuration int		
	Declare @sEOF int	

	Select @PatrolCode = 15		--Inspection Code for Patrol Inspection Type
	Select @PatrolDuration = val FROM Com_Inspection_Option_dtl where InspectionTypeCode=@PatrolCode and Code=2 and InspectionTypeCode=@PatrolCode	-- In Mintes

	Declare @MaxTime datetime		--Last Entry Time for Current Shift
	Declare @MaxTime1 datetime		--Last Entry Time for Current Shift
	Declare @StartTime datetime		--Previous Entry Time for Current Shift
	Declare @ToBeEnterCount int		--To Be Entered Count from Production Plan
	Declare @EnteredCount int		--Entered Count from Inspection Details
	Declare @NewPatrolSetEntry bit		--Whether Pending Items or New Set
	Declare @EndTime as datetime		--Shift end  time


	--Select @MaxTime='2008-09-16 4:30'

			

	Begin
		Select a.DocType,a.DocNo,a.DocDate,a.StageCode, e.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, Date1,
			e.UOMDesc, b.CycleTime, a.StartTime, a.EndTime,@MaxTime as '2008-09-16 4:30', '' as DrawingCode, 
				case when exists (select Distinct ItemCode from  Qc_Inspection_MAster f where f.InspectionTypeCode=@PatrolCode and f.Inspect=1 
				and f.ItemCode=a.StageCode) then 1 else 0 end Status,
			round(((case when a.Starttime<=dateadd(n,-(@PatrolDuration-1),'2008-09-16 4:30') then @PatrolDuration else  (@PatrolDuration-datediff(n,dateadd(n,-(@PatrolDuration-1),'2008-09-16 4:30'),a.Starttime) )  end  *60)/b.CycleTime),0)-Sum(isnull(c.Qty,0))LotSize,a.Branchid,a.Compid,1 as nn
							 
			from PPC_Quickproductionplan_dtl a
			
			Left Outer Join BOM_ItemwiseMachinewiseCycleTime b 
			on b.ItemCode=a.StageCode and b.MachineCode=a.MachineCode and b.Branchid=a.Branchid and b.Compid=a.Compid 
			
			Left outer join QC_Inspection_Criteria c 
			on c.RefNo=a.DocNo and c.RefDate=a.DocDate and c.RefType=a.DocType and c.MachineCode=a.MachineCode 
			and c.Branchid=a.Branchid and c.Compid=a.Compid and c.TobeEnterTime between dateadd(n,-(@PatrolDuration-1),@MaxTime) and @MaxTime
			and CriteriaCode not in (select case when ItemCode=a.StageCode then 0 else 20 end  from QC_Inspection_Criteria where RefNo=a.DocNo and RefDate=a.DocDate and RefType=a.DocType and MachineCode=a.MachineCode and 
			Branchid=a.Branchid and Compid=a.Compid and TobeEnterTime between dateadd(n,-(@PatrolDuration-1),'2008-09-16 4:30') and @MaxTime and CriteriaCode=20)
			
			Left outer join (Select RefType,RefNo,RefDate,ItemCode,MachineCode,Starttime,Branchid,Compid,Type,Sum(Qty)Qty from QC_Inspection_Criteria 
					Group by  RefType,RefNo,RefDate,ItemCode,MachineCode,Starttime,Branchid,Compid,Type)d
			on d.RefNo=a.DocNo and d.RefDate=a.DocDate and d.RefType=a.DocType and d.ItemCode=a.StageCode and d.MachineCode=a.MachineCode 
			and d.Starttime=a.Starttime and d.Branchid=a.Branchid and d.Compid=a.Compid and d.Type='C'
			
			Left Outer Join Material_Master e On e.ItemCode=a.StageCode and e.BranchID=a.BranchID and e.CompID=a.CompID
			
			where a.Revisionno=(Select max(Revisionno) from PPC_Quickproductionplan_dtl where DocType=a.Doctype and docno=a.Docno and Docdate=a.Docdate
						and branchid=a.Branchid and Compid=a.Compid )
				 and DocNo=@PlanNo and DocDate=@PlanDate and DocType=@PlanType and a.Status<>0 
				and a.StartTime<@MaxTime and a.OperationName<>'SETTING'

				and Not Exists (Select * from QC_Inspection_Criteria g where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType 
					and g.ItemCode=a.StageCode and g.MachineCode=a.MachineCode and g.Starttime=a.Starttime and g.Branchid=a.Branchid and g.Compid=a.Compid
					and CompletedStatus=1)

			group by a.DocType,a.DocNo,a.DocDate,a.StageCode, e.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, 
			a.Date1, e.UOMDesc, b.CycleTime, a.StartTime, a.EndTime,d.Qty ,a.Branchid,a.Compid

			having round(((case when a.Starttime<=dateadd(n,-(@PatrolDuration-1),'2008-09-16 4:30') then @PatrolDuration else  (@PatrolDuration-datediff(n,dateadd(n,-(@PatrolDuration-1),'2008-09-16 4:30'),a.Starttime) )  end  *60)/b.CycleTime),0)>Sum(isnull(c.Qty,0))  and a.Date1>Sum(isnull(d.Qty,0))

		End

	
END
GO

/****** Object:  StoredProcedure [dbo].[QC_PatrolInspectionItemSelect_TmpV2]    Script Date: 17/06/2026 11:30:51 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QC_PatrolInspectionItemSelect_TmpV2](@PlanType varchar(3), @PlanNo int, @PlanDate datetime,   
 @ShiftCode varchar(3), @BranchID varchar(3), @CompID varchar(3))        
As    
BEGIN    
	SET NOCOUNT ON; 
--ALTER FUNCTION [dbo].[QC_PatrolInspectionItemSelect_TmpV2] (@PlanType varchar(3), @PlanNo int, @PlanDate datetime,   
-- @ShiftCode varchar(3), @BranchID varchar(3), @CompID varchar(3))  
          
Declare @Item As TABLE      
 (DocType  varchar(3),      
 DocNo   int,      
 DocDate  Datetime,      
 StageCode  varchar(20),      
 ItemDescription  varchar(50),      
 MachineCode  varchar(20),         
 WorkOrderType  varchar(3),      
 WorkOrderNo  int,      
 WorkOrderDate  datetime,      
 UOMDesc  varchar(5),      
 CycleTime  float,      
 StartTime  datetime,      
 EndTime  datetime,      
 ToBeEnterTime   datetime,      
 Status   varchar(10),      
 DrawingCode  varchar(20),      
 Branchid  varchar(3),      
 Compid   varchar(3)  
)          
   
 Declare @PatrolCode int      
 Declare @PatrolDuration int        
 Declare @sEOF int       
      
 Select @PatrolCode = 8  --Inspection Code for Patrol Inspection Type      
 Select @PatrolDuration = val FROM Com_Inspection_Option_dtl where InspectionTypeCode=@PatrolCode and Code=1 -- In Mintes      
      
 Declare @MaxTime datetime  --Last Entry Time for Current Shift      
 Declare @MaxTime1 datetime        
 Declare @ToBeEnterCount int  --To Be Entered Count from Production Plan      
 Declare @EnteredCount int  --Entered Count from Inspection Details      
 Declare @NewPatrolSetEntry bit  --Whether Pending Items or New Set      
 Declare @EndTime as datetime  --Shift end  time      
      
 Begin      
  Select @MaxTime=DateAdd(n, @PatrolDuration, a.StartDate+convert(varchar(5),b.StartTime,108)) , @EndTime=DateAdd(n,b.ShiftMinutes, a.StartDate+convert(varchar(5),b.StartTime,108))       
  from       
   (Select top 1 StartDate, BranchID, CompID      
    from PPC_QuickProductionplan_Dtl       
   Where DocNo=@PlanNo and DocDate=@PlanDate and DocType=@PlanType and BranchID=@BranchID and CompID=@CompID      
   ) a      
  Left Outer Join PPC_Shift_Master b On a.BranchID=b.BranchID and a.CompID=b.CompID      
  Where b.ShiftCode=@ShiftCode      
      
  /* To Be implemented  
  Select @MaxTime1=dateadd(n,-@PatrolDuration,a.MaxTime) From QC_Maxtime_Tmp a  
 Where a.Docno=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType */  
  
 Select @MaxTime1=MaxTime From Qc_Maxtime_Tmp  -- Select * From Qc_Maxtime_Tmp Where DocType='PWA' and Docno=851 and DocDate='2023-02-21'  
 Where DocType=@PLanType and Docno=@PlanNo and DocDate=@PlanDate  
      
  If isnull(@Maxtime1,0)<>0       
  Begin  
    Select @Maxtime=@Maxtime1          
  End  
 End        
      
eLoopFirst:       
  if @EndTime>= @MaxTime      
   Begin      
    Insert into @Item      
     Select Distinct a.DocType,a.DocNo,a.DocDate, a.StageCode, b.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate,       
      b.UOMDesc, c.CycleTime, a.StartTime, a.EndTime,@MaxTime, 'Current',d.DrawingCode,a.Branchid,a.Compid      
     from PPC_QuickProductionplan_Dtl a       
     Left Outer Join Material_Master b On a.StageCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID      
     Left Outer Join BOM_ItemwiseMachinewiseCycleTime c on a.StageCode=c.ItemCode and a.MachineCode=c.MachineCode and a.Branchid=c.Branchid and a.Compid=c.Compid       
     Left Outer Join BOM_Drawing_Master d on a.StageCode=d.ItemCode and Type='O' and a.Branchid=d.Branchid and a.Compid=d.Compid      
     left outer join QC_Inspection_Hdr e on a.DocType=e.RefType and a.DocNo=e.RefNo and a.DocDate=e.RefDate and e.MachineCode=a.MachineCode     
   and e.ItemCode=a.StageCode and e.Starttime=a.Starttime and a.Branchid=e.Branchid and a.Compid=e.Compid       
      and  e.InspectionTypeCode=@PatrolCode       
     Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Shift=@ShiftCode and a.BranchID=@BranchID and a.CompID=@CompID      
      --and (@MaxTime between  a.StartTime and dateadd(n,59,a.Endtime))  
			-- (@MaxTime between  a.StartTime and a.Endtime) 
   and ((@MaxTime>a.StartTime and @MaxTime<=a.Endtime)  or (a.StartTime<@MaxTime and Datediff(minute,a.StartTime,a.EndTime)<@PatrolDuration))  
     
   and a.OperationName<>'SETTING'--between a.StartTime and a.EndTime      
   and a.RevisionNo=(Select Max(RevisionNo) From PPC_QuickProductionplan_Dtl        
         Where a.DocNo = DocNo and a.DocType = DocType and a.DocDate = DocDate and a.Branchid=BranchID and a.Compid=CompID and Finyear=a.Finyear      
         )       
      and Not Exists (Select * from QC_Inspection_Hdr g Left Outer Join QC_Inspection_Dtl h On g.InspectionNo=h.InspectionNo and g.InspectionDate=h.InspectionDate     
           and g.InspectionType=h.InspectionType and g.Branchid=h.Branchid and g.Compid=h.Compid        
           Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType  and g.MachineCode=a.MachineCode --and g.Starttime=a.Starttime      
            and g.Branchid=a.BranchID and g.Compid=a.CompID and h.ToBeEnterTime=@MaxTime      
           )      
      and Exists (Select * from QC_Inspection_Master  where InspectiontypeCode=@PatrolCode and ItemCode=a.StageCode and Inspect=1 and Branchid=@Branchid and Compid=@Compid )      
      and e.CompletedDate is null and a.Status<>0       

----------------------        
Select 'Part 1 - EndTime >= MaxTime' As E_EqMx, @PatrolDuration As tMinutes, @EndTime As EndTime, @MaxTime As MaxTime
Select * From @Item
----------------------
           
    select @sEOF=isnull(count(*),0) from @Item     --Record Not then Time To Add      
     if isnull(@sEOF,0)=0      
      Begin      
       Select @MaxTime = DateAdd(n, @PatrolDuration, @MaxTime)      
        goto eLoopFirst      
      End        
     Else      
      Begin      
       Insert into @Item  --Non Completed Items      
        Select Distinct a.DocType,a.DocNo,a.DocDate, a.StageCode, b.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate,       
         b.UOMDesc, c.CycleTime, a.StartTime, a.EndTime,@MaxTime,'Balance' ,d.DrawingCode,@Branchid,@Compid      
        from      
         (Select Distinct a.DocType,a.DocNo,a.DocDate,a.StageCode, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.StartTime, a.EndTime, @BranchID as BranchID, @CompID as CompID      
         from      
          (Select Distinct a.DocType,a.DocNo,a.DocDate,a.StageCode, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.StartTime, a.EndTime, Sum(Date1) as PlannedQty      
          from PPC_QuickProductionplan_Dtl a Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Shift=@ShiftCode and a.OperationName<>'SETTING' and a.BranchID=@BranchID and a.CompID=@CompID and  a.Status<>0      
          and a.RevisionNo=(Select Max(RevisionNo) From PPC_QuickProductionplan_Dtl        
            Where a.DocNo = DocNo and a.DocType = DocType and a.DocDate = DocDate and a.Branchid=BranchID and a.Compid=CompID      
            )       
          Group By  a.DocType,a.DocNo,a.DocDate, a.StageCode, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.StartTime, a.EndTime      
          ) a      
         Left Outer Join      
          (Select g.ItemCode, g.MachineCode, Sum(j.Qty) as CompletedQty from QC_Inspection_Hdr g       
          Left Outer Join (Select * from QC_Inspection_Criteria Where Type='C' or (Type in('R','LR') and CriteriaCode=14)) j      
           On g.InspectionNo=j.InspectionNo and g.InspectionDate=j.InspectionDate and g.InspectionType=j.InspectionType and g.ItemCode=j.ItemCode and g.MachineCode=j.MachineCode and g.Branchid=j.Branchid and g.Compid=j.Compid         
          Where g.RefNo=@PlanNo and g.RefDate=@PlanDate and g.RefType=@PlanType and g.Branchid=@BranchID and g.Compid=@CompID        
          Group by g.ItemCode, g.MachineCode) b On a.StageCode=b.ItemCode and a.MachineCode=b.MachineCode      
         Where isNull(a.PlannedQty, 0) > isNull(b.CompletedQty, 0)      
         ) a      
         Left Outer Join Material_Master b On a.StageCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID      
         Left Outer Join BOM_ItemwiseMachinewiseCycleTime c on a.StageCode=c.ItemCode and a.MachineCode=c.MachineCode and a.Branchid=c.Branchid and a.Compid=c.Compid       
         Left Outer Join BOM_Drawing_Master d on a.StageCode=d.ItemCode and Type='O' and a.Branchid=d.Branchid and a.Compid=d.Compid      
         left outer join QC_Inspection_Hdr e on a.DocType=e.RefType and a.DocNo=e.RefNo and a.DocDate=e.RefDate and e.MachineCode=a.MachineCode and e.ItemCode=a.StageCode     
     and e.Starttime=a.Starttime and a.Branchid=e.Branchid and a.Compid=e.Compid and  e.InspectionTypeCode=@PatrolCode       
              
         Where Not Exists (Select * from @Item n       
           Where a.StageCode=n.StageCode and a.MachineCode=n.MachineCode and a.StartTime=n.StartTime and a.EndTime=n.EndTime       
            and a.WorkOrderType=n.WorkOrderType and a.WorkOrderNo=n.WorkOrderNo and a.WorkOrderDate=n.WorkOrderDate) and isnull(e.CompletedStatus,0)=0 and e.InspectionType is Not NUll      
         and Not Exists (Select *  from QC_Inspection_Hdr g       
           Left Outer Join QC_Inspection_Dtl h On g.InspectionNo=h.InspectionNo and g.InspectionDate=h.InspectionDate and g.InspectionType=h.InspectionType and g.Branchid=h.Branchid and g.Compid=h.Compid        
           Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType  and g.MachineCode=a.MachineCode and g.Starttime=a.Starttime      
            and g.Branchid=a.BranchID and g.Compid=a.CompID and h.ToBeEnterTime=@MaxTime) and CompletedDate is null       
       End        
   End      
  Else        
   Begin      
       Insert into @Item  --Non Completed Items      
        Select Distinct a.DocType,a.DocNo,a.DocDate, a.StageCode, b.ItemDescription, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate,       
         b.UOMDesc, c.CycleTime, a.StartTime, a.EndTime,@MaxTime,'Balance' ,d.DrawingCode,@Branchid,@Compid      
        from      
         (Select Distinct a.DocType,a.DocNo,a.DocDate,a.StageCode, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.StartTime, a.EndTime, @BranchID as BranchID, @CompID as CompID      
         from      
          (Select Distinct a.DocType,a.DocNo,a.DocDate,a.StageCode, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.StartTime, a.EndTime, Sum(Date1) as PlannedQty      
          from PPC_QuickProductionplan_Dtl a Where a.DocNo=@PlanNo and a.DocDate=@PlanDate and a.DocType=@PlanType and a.Shift=@ShiftCode and a.OperationName<>'SETTING' and a.BranchID=@BranchID and a.CompID=@CompID and  a.Status<>0      
          and a.RevisionNo=(Select Max(RevisionNo) From PPC_QuickProductionplan_Dtl        
            Where a.DocNo = DocNo and a.DocType = DocType and a.DocDate = DocDate and a.Branchid=BranchID and a.Compid=CompID      
            )       
          Group By  a.DocType,a.DocNo,a.DocDate,a.StageCode, a.MachineCode, a.WorkOrderType, a.WorkOrderNo, a.WorkOrderDate, a.StartTime, a.EndTime      
          ) a      
         Left Outer Join      
          (Select g.ItemCode, g.MachineCode, Sum(j.Qty) as CompletedQty from QC_Inspection_Hdr g       
          Left Outer Join (Select * from QC_Inspection_Criteria Where Type='C' or (Type in('R','LR') and CriteriaCode=14)) j      
           On g.InspectionNo=j.InspectionNo and g.InspectionDate=j.InspectionDate and g.InspectionType=j.InspectionType and g.ItemCode=j.ItemCode and g.MachineCode=j.MachineCode and g.Branchid=j.Branchid and g.Compid=j.Compid         
          Where g.RefNo=@PlanNo and g.RefDate=@PlanDate and g.RefType=@PlanType and g.Branchid=@BranchID and g.Compid=@CompID        
          Group by g.ItemCode, g.MachineCode) b On a.StageCode=b.ItemCode and a.MachineCode=b.MachineCode      
         Where isNull(a.PlannedQty, 0) > isNull(b.CompletedQty, 0)      
         ) a      
         Left Outer Join Material_Master b On a.StageCode=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID      
         Left Outer Join BOM_ItemwiseMachinewiseCycleTime c on a.StageCode=c.ItemCode and a.MachineCode=c.MachineCode and a.Branchid=c.Branchid and a.Compid=c.Compid       
         Left Outer Join BOM_Drawing_Master d on a.StageCode=d.ItemCode and Type='O' and a.Branchid=d.Branchid and a.Compid=d.Compid      
         left outer join QC_Inspection_Hdr e on a.DocType=e.RefType and a.DocNo=e.RefNo and a.DocDate=e.RefDate and e.MachineCode=a.MachineCode and e.ItemCode=a.StageCode     
     and e.Starttime=a.Starttime and a.Branchid=e.Branchid and a.Compid=e.Compid and  e.InspectionTypeCode=@PatrolCode      
              
         Where Not Exists (Select * from @Item n       
           Where a.StageCode=n.StageCode and a.MachineCode=n.MachineCode and a.StartTime=n.StartTime and a.EndTime=n.EndTime       
            and a.WorkOrderType=n.WorkOrderType and a.WorkOrderNo=n.WorkOrderNo and a.WorkOrderDate=n.WorkOrderDate)  
       and isnull(e.CompletedStatus,0)=0 and e.InspectionType is Not NUll      
            and Not Exists (Select *  from QC_Inspection_Hdr g                  
      Left Outer Join QC_Inspection_Dtl h On g.InspectionNo=h.InspectionNo and g.InspectionDate=h.InspectionDate and g.InspectionType=h.InspectionType     
      and g.Branchid=h.Branchid and g.Compid=h.Compid        
           Where g.RefNo=a.DocNo and g.RefDate=a.DocDate and g.RefType=a.DocType  and g.MachineCode=a.MachineCode and g.Starttime=a.Starttime      
        and g.Branchid=a.BranchID and g.Compid=a.CompID and h.ToBeEnterTime=@MaxTime) and CompletedDate is null  
				
----------------------        
Select 'Part 2 - EndTime < MaxTime' As E_Less, @EndTime As EndTime, @MaxTime As MaxTime
Select * From @Item
----------------------				     
       End 
    
END  
GO

/****** Object:  StoredProcedure [dbo].[QC_Rpt_InspectionReport_Get_MaxParamReadingData]    Script Date: 17/06/2026 11:30:51 ******/
SET ANSI_NULLS ON
