CREATE PROCEDURE [dbo].[QC_Rpt_InspectionReport_Get_MaxParamReadingData](@InspectionType varchar(3), @InspectionNo int, 
@InspectionDate datetime, @ItemCode varchar(20)='', @BranchID varchar(3), @CompID varchar(3), 
@Finyear varchar(20))        
As        
BEGIN        
	SET NOCOUNT ON;

	/* Output - Get Max SampleNo/ActualNo Data */
	Begin
		Select IsNull(Max(a.SampleNo),0) As MaxSampleNo, IsNull(Max(a.ActualNo),0) As MaxActualNo			
		From QC_Inspection_Dtl1 a 
		Where a.InspectionNo=@InspectionNo and a.InspectionDate=@InspectionDate 
					and a.InspectionType=@InspectionType 
					and (@ItemCode='' or (@ItemCode<>'' and a.ItemCode=@ItemCode))
					and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear			
	End
END
GO

/****** Object:  StoredProcedure [dbo].[QC_Rpt_InspectionReport_Get_ParamReadingData]    Script Date: 17/06/2026 11:30:51 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QC_Rpt_InspectionReport_Get_ParamReadingData](@InspectionType varchar(3), @InspectionNo int, 
@InspectionDate datetime, @ItemCode varchar(20), @MParamCode int, @BranchID varchar(3), 
@CompID varchar(3), @Finyear varchar(20))        
As        
BEGIN        
	SET NOCOUNT ON;

	Declare @MaxParamActualNo As int;

	/* Get ItemCode & MParamCode Based Max ActualNo (NoOfReadings Per Sample)  Data */
	Begin
		Select @MaxParamActualNo=Max(a.ActualNo)
		From QC_Inspection_Dtl1 a 
		Where a.InspectionNo=@InspectionNo and a.InspectionDate=@InspectionDate 
					and a.InspectionType=@InspectionType and a.ItemCode=@ItemCode 
					and a.MParamCode=@MParamCode and a.BranchID=@BranchID and a.CompID=@CompID 
					and a.Finyear=@Finyear 	
	End

	/* Output - SampleNo/MaxParamActualNo/ActualNo/ActualReading Data */
	Select Distinct a.ItemCode, a.MParamCode, IsNull(a.SampleNo,0) As SampleNo, @MaxParamActualNo As MaxParamActualNo,
				IsNull(a.ActualNo,0) As ActualNo, IsNull(a.ActualReading,0) As ActualReading
	From QC_Inspection_Dtl1 a
	Where a.InspectionNo=@InspectionNo and a.InspectionDate=@InspectionDate 
					and a.InspectionType=@InspectionType and a.ItemCode=@ItemCode 
					and a.MParamCode=@MParamCode and a.BranchID=@BranchID and a.CompID=@CompID 
					and a.Finyear=@Finyear 	
	Order by a.ItemCode, a.MParamCode, SampleNo, ActualNo
END
GO

/****** Object:  StoredProcedure [dbo].[QC_Rpt_MasterBlankReport_Get_MaxParamReadingData]    Script Date: 17/06/2026 11:30:51 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QC_Rpt_MasterBlankReport_Get_MaxParamReadingData](@ItemCode varchar(20), @InspectionTypeCode int,  
@BranchID varchar(3), @CompID varchar(3))          
As          
BEGIN          
 SET NOCOUNT ON;  
 /* Note: QC_Inspection_Master - Table Fields  
      NoofReadings      --> No. Of Sample (NOS)  
      NoOfReadingsPerSample  --> No. Of Reading Per Sample (NORPS)  
 */  
  
 /* Get Max NoOfReadings Per Sample */  
 Begin  
  /* Output */  
  Select Top 1 IsNull(x.MaxSampleNo,0) As MaxSampleNo, IsNull(x.MaxActualNo,0) As MaxActualNo, 
			IsNull(x.AlternateConvFactor,0) As AlternateConvFactor,   
			IsNull(x.IsReqAlterUomToInspect ,'0') As IsReqAlterUomToInspect  
  From (Select Max(a.NoofReadings) As MaxSampleNo, Max(a.NoOfReadingsPerSample) As MaxActualNo, 
						a.AlternateConvFactor, a.IsReqAlterUomToInspect 							  
     From QC_Inspection_Master a   
     Where a.ItemCode=@ItemCode and a.InspectionTypeCode=@InspectionTypeCode and a.Inspect='1'   
        and a.BranchID=@BranchID and a.CompID=@CompID  
     Group by a.AlternateConvFactor, a.IsReqAlterUomToInspect    
  ) x  
  
 End          
END  
GO

