	 @QONo 	[int],
	 @QODate 	[datetime],
	 @RefNo	[int],
	 @SNo 		[varchar](20),
	 @Heading	[varchar](200),
	 @QualityObjectives 	[varchar](5000),
	 @Seq		[int],
	 @RevNo 	[int],
	 @RevDate 	[datetime],
	 @HdrStatus	[char](1),
	 @EffStatus 	[char](1),
	 @EffDate 	[datetime],
	 @TranStamp 	[datetime],
	 @UserId 	[varchar](10),
	 @BranchId	[varchar](3),
	 @CompId 	[varchar](3),
	 @Finyear 	[varchar](20))

AS 


if @HdrStatus='E'
		Begin
			Select @RevNo=Isnull(Max(RevNo),0) from QMS_QualityObjectives_Dtl where QOType=@QOType and QONo=@QONo and QODate=@QODate and Branchid=@Branchid and Compid=@Compid and RefNo=@RefNo
			Select @RevNo=@RevNo+1
		End

	Else
		Select @RevNo=Isnull(Max(RevNo),0) from QMS_QualityObjectives_Dtl where QOType=@QOType and QONo=@QONo and QODate=@QODate and Branchid=@Branchid and Compid=@Compid and RefNo=@RefNo
		Select @RevDate=Isnull(@RevDate,@RevDate) from QMS_QualityObjectives_Dtl where QOType=@QOType and QONo=@QONo and QODate=@QODate and RevNo=@RevNo and Branchid=@Branchid and Compid=@Compid  and RefNo=@RefNo



INSERT INTO [QMS_QualityObjectives_Dtl] 
	 ( [QOType],
	 [QONo],
	 [QODate],
	 [RefNo],
	 [SNo],
	 [Heading],
	 [QualityObjectives],
	 [Seq],
	 [RevNo],
	 [RevDate],
	 [EffStatus],
	 [EffDate],
	 [TranStamp],
	 [UserId],
	 [BranchId],
	 [CompId],
	 [Finyear]) 
 
VALUES 
	(@QOType,
	 @QONo,
	 @QODate,
	 @RefNo,
	 @SNo,
	 @Heading,
	 @QualityObjectives,
	 @Seq,
	 @RevNo,
	 @RevDate,
	 @EffStatus,
	 @EffDate,
	 @TranStamp,
	 @UserId,
	 @BranchId,
	 @CompId,
	 @Finyear)
GO

