/****** Object:  StoredProcedure [dbo].[QMS_V1_StandardDocument_Dtl_Rep_Ins]    Script Date: 17/06/2026 11:30:53 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QMS_V1_StandardDocument_Dtl_Rep_Ins]     
(    
	@StdID [int],						/* Treat As DocType */
	@DocNo [int],	
	@DocDate [datetime],
	@LevelSerialNo [varchar](20),
	@MainContent [nvarchar](1000), 
	@SubContent [nvarchar](1000), 
	@Parent [int],	
	@Relation [int],
	@SeqNo [int],
	@SymRef [int],
	@RefValue [float],	
	@DocFileID [int],	
	@Remarks [varchar](200),     
	@FromDate [datetime],
	@ToDate [datetime],
	@EffStatus  [bit],   
	@UserID  [varchar](10),  
	@BranchID [varchar](3),  
	@CompID [varchar](3), 
	@Finyear  [varchar](20), 
	@TranStamp  [datetime],
	@TranType  [int] 
)  
AS          
BEGIN          
	SET NOCOUNT ON;    
	/* Note:	@StdID -> Treat As DocType
						@SymRef -> 2 Question / 3 Evidence / 6 Document / (No Need) 7 Other and Other(s) <None>
						fn_QMS_V1_RESX_FileRepository_Dtl - > AssetCode Treat As DocFileID (NodeIdx)
	*/

	Declare @Tmp_DocFileID As int;
	Declare @Tmp_FileID As int;	

	SET @Tmp_DocFileID=0;
	SET @Tmp_FileID=0;	

	SET @Tmp_DocFileID=IsNull(@DocFileID,0);				/* Initial DocFileID */

	If @TranType<>1		/* Modify */
	 Begin
		If @DocFileID<=0 
		 Begin
			If @SymRef>0 And (@SymRef=2 or @SymRef=3 or @SymRef=6)			-- (No Need) or @SymRef=7 ERPRef
			 Begin
				Select Distinct @Tmp_FileID=IsNull(b.FileID,0), @Tmp_DocFileID=Convert(int,IsNull(b.AssetCode,'0')) 
				From QMS_V1_StandardDocument_Dtl a 
				Inner Join dbo.fn_QMS_V1_RESX_FileRepository_Dtl(@TranStamp, @TranStamp, @BranchID, @CompID, @Finyear) b  
					On a.StdID=Convert(int,IsNull(b.ItemCode,'0')) and a.DocNo=b.DocNo and a.DocDate=b.DocDate   
						and a.DocFileID=Convert(int,IsNull(b.AssetCode,'0')) and a.BranchID=b.BranchID and a.CompID=b.CompID  --and b.Finyear=@Finyear     
				Where a.StdID=@StdID and a.DocNo=@DocNo and a.DocDate=@DocDate and a.SeqNo=@SeqNo and a.BranchID=@BranchID 
					and a.CompId=@CompID  --and a.Finyear=@Finyear    

				Select @Tmp_FileID=IsNull(@Tmp_FileID,0),  @Tmp_DocFileID=IsNull(@Tmp_DocFileID,0);				
			End
		 End

		 SET @DocFileID=IsNull(@Tmp_DocFileID,0);
	 End
	
	/* Insert Data Into Table */  
	Begin                           
		INSERT INTO QMS_V1_StandardDocument_Dtl_Rep     
		(          
			[StdID],
			[DocNo],		
			[DocDate],		
			[LevelSerialNo],
			[MainContent],
			[SubContent],
			[Parent],		
			[Relation],
			[SeqNo],
			[SymRef],
			[RefValue],		
			[DocFileID],
			[Remarks],
			[FromDate],
			[ToDate],
			[EffStatus],
			[UserID],
			[BranchID],
			[CompID],
			[Finyear],
			[TranStamp]  
		)  
		VALUES  
		(	@StdID,
			@DocNo,		
			@DocDate,		
			@LevelSerialNo,
			@MainContent,
			@SubContent,
			@Parent,		
			@Relation,
			@SeqNo,
			@SymRef,
			@RefValue,
			@Tmp_DocFileID,		
			@Remarks,
			@FromDate,
			@ToDate,
			@EffStatus,
			@UserID,
			@BranchID,
			@CompID,
			@Finyear,
			@TranStamp  
		)  
	End  
END  
GO

/****** Object:  StoredProcedure [dbo].[QMS_V1_StandardDocument_Fil_File]    Script Date: 17/06/2026 11:30:53 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QMS_V1_StandardDocument_Fil_File](@TranType int=1, @StdID int, @DocType varchar(4), @DocNo int, @DocDate datetime, 
	@NodeIdx int, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))        
AS        
BEGIN         
	SET NOCOUNT ON;  

	/* Note:	@StdID	-> Treat As DocType		
					@TranType -> 1 View / 2 Edit / 3 History				
					@SymRef -> 2 Question / 3 Evidence / 6 Document / (No Need) 7 Other and Other(s) <None>
					fn_QMS_V1_RESX_FileRepository_Dtl - > AssetCode Treat As DocFileID (NodeIdx)
					@Status -> 0 In-Active / 1 Active / 2 Delete
	*/	
   
	 If (@TranType=1 or @TranType=2)				/*  View / Edit: EffStatus - Active Only */
	  Begin
		 Select a.FileID, Case When IsNull(a.EffStatus,0) = 0 Then 'In-Active' 
												When IsNull(a.EffStatus,0) = 1 Then 'Active' Else 'Delete' End As EffStatus,  
				(Case When IsNull(b.FileExtension,'')<>'' Then	
						(Case When IsNull(b.FileNameWithoutExtension,'')<>'' Then IsNull(b.FileNameWithoutExtension,'')+ '.' + IsNull(b.FileExtension,'') Else IsNull(b.FileExtension,'') End)	
				Else										
					IsNull(a.DeletedFileName,'')
				End) As FileName,
				IsNull(b.FileNameWithoutExtension,'') + '.' + IsNull(b.FileExtension,'') As FileName, 
				IsNull(a.FileID,0) As FileID, Convert(int,IsNull(a.AssetCode,'')) As DocFileID, IsNull(c.SeqNo,0) As SeqNo, 
				IsNull(c.Parent,0) As Parent, IsNull(c.SymRef,0) As SymRef  
		 From dbo.fn_QMS_V1_RESX_FileRepository_Dtl(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a    
		 Left Outer Join RESX_FileRepository_vw b    
			On a.FileID=b.FileID and a.CompID=b.CompID and a.BranchID=b.BranchID  
		 Left Outer Join QMS_V1_StandardDocument_Dtl c  
			On c.StdID=@StdID and a.DocNo=c.DocNo and a.DocDate=c.DocDate and c.SeqNo=@NodeIdx   
			 and IsNull(a.AssetCode,'')=Convert(varchar(10),c.DocFileID) and a.BranchID=c.BranchID and a.CompID=c.CompID  --and a.Finyear=@Finyear     
		 Where IsNull(a.ItemCode,'')=Convert(varchar(30),IsNull(@StdID,0)) and a.DocNo=@DocNo and a.DocDate=@DocDate 
				and a.DocType=@DocType and IsNull(a.AssetCode,'')=Convert(varchar(10),IsNull(@NodeIdx,0)) and IsNull(a.FileID,0)>0 
				and IsNull(a.EffStatus,0)=1 and a.BranchID=@BranchID and a.CompId=@CompID  --and a.Finyear=@Finyear  
		 Order by c.StdID, a.DocDate, a.DocNo
	 End
	Else									/* View: EffStatus - Active  */
	 Begin
		Select a.FileID, Case When IsNull(a.EffStatus,0) = 0 Then 'In-Active' When IsNull(a.EffStatus,0) = 1 Then 'Active' Else 'Delete' End As EffStatus,   
				(Case When IsNull(b.FileExtension,'')<>'' Then	
						(Case When IsNull(b.FileNameWithoutExtension,'')<>'' Then IsNull(b.FileNameWithoutExtension,'')+ '.' + IsNull(b.FileExtension,'') Else IsNull(b.FileExtension,'') End)	
				Else										
					IsNull(a.DeletedFileName,'')
				End) As FileName, 
				IsNull(a.FileID,0) As FileID, Convert(int,IsNull(a.AssetCode,'0')) As DocFileID, IsNull(c.SeqNo,0) As SeqNo, 
				IsNull(c.Parent,0) As Parent, IsNull(c.SymRef,0) As SymRef  
		 From dbo.fn_QMS_V1_RESX_FileRepository_Dtl(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) a    
		 Left Outer Join RESX_FileRepository_vw b    
			On a.FileID=b.FileID and a.CompID=b.CompID and a.BranchID=b.BranchID  
		 Left Outer Join QMS_V1_StandardDocument_Dtl c  
			On c.StdID=@StdID and a.DocNo=c.DocNo and a.DocDate=c.DocDate and c.SeqNo=@NodeIdx   
			 and Convert(int,IsNull(a.AssetCode,'0'))=c.DocFileID and a.BranchID=c.BranchID and a.CompID=c.CompID  --and a.Finyear=@Finyear     
		 Where IsNull(a.ItemCode,'')=Convert(varchar(30),IsNull(@StdID,0)) and a.DocNo=@DocNo and a.DocDate=@DocDate 
				and a.DocType=@DocType and IsNull(a.AssetCode,'')=Convert(varchar(10),IsNull(@NodeIdx,0)) 
				and IsNull(a.FileID,0)>0 and a.BranchID=@BranchID and a.CompId=@CompID  --and a.Finyear=@Finyear  
		 Order by c.StdID, a.DocDate, a.DocNo
	 End	   
END
GO

