CREATE PROCEDURE [dbo].[QMS_V1_StandardDocument_Gen](@StdID int, @DocNo int, @DocDate datetime, @FromDate datetime,   
 @ToDate datetime, @ParentCode int=0, @SeqNo int=0, @Status bit='0', @AsOnDate datetime, @RptDate datetime, 
 @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                          
As                
BEGIN                
 SET NOCOUNT ON;    
  
	If @Status ='1'      
	 Begin      
		Select Distinct a.StdID, a.DocNo, a.DocDate, a.LevelSerialNo, (IsNull(a.LevelSerialNo,'')+' '+a.MainContent) As ChildCode, 
			IsNull(a.Relation,0) As Type, 1 As IsRM, Parent, a.SeqNo As Seq, IsNull(a.SymRef,0) As SymRef          
		From QMS_V1_StandardDocument_Dtl a   
		Where a.StdID=@StdID and a.DocNo=@DocNo and a.DocDate=@DocDate and a.Parent=0   
			and a.FromDate=@FromDate /*and a.ToDate=@ToDate*/ and a.BranchID=@BranchID   
			and a.CompID=@CompID and a.Finyear=@Finyear   
		Order by Seq      
	 End      
	Else      
	 Begin      
		Select Distinct a.StdID, a.DocNo, a.DocDate, a.LevelSerialNo, (IsNull(a.LevelSerialNo,'')+' '+a.MainContent) As ChildCode, 
			IsNull(Relation,0) As Type, 1 As IsRM, Parent, a.SeqNo As Seq, IsNull(a.SymRef,0) As SymRef  
		From QMS_V1_StandardDocument_Dtl a              
		Where a.StdID=@StdID and a.DocNo=@DocNo and a.DocDate=@DocDate and a.Parent=@ParentCode    
			and a.FromDate=@FromDate /*and a.ToDate=@ToDate*/ and a.BranchID=@BranchID   
			and a.CompID=@CompID and a.Finyear=@Finyear   
		Order by Seq          
	 End              
END  
GO

