CREATE PROCEDURE [dbo].[QMS_V1_StandardMaster_Fil_ClauseLinkBasedStdName](@TranType int, @StdID int=0,   
 @StdClauseID int, @BranchID varchar(3), @CompID varchar(3))            
AS            
BEGIN            
 SET NOCOUNT ON;        

	if @TranType=1   /* Create */      
   Begin      
		Select a.StdID, a.StdName As StdName, '0' As IsLinkApplicable      
		From QMS_V1_StandardMaster_Hdr a      
		Where a.EffStatus='1' and a.StdID<>@StdID and a.BranchID=@BranchID and a.CompID=@CompID      
		Order by a.StdID      
   End      
	Else   /* Modify */      
	 Begin  
		/* Note: Getting Each Standard Clause Link (Common) Related Standard Name */		 		

		Select Distinct a.StdID, a.StdName, IsNull(b.StdClauseID,0) As StdClauseID, 
				IsNull(b.IsClauseApplicable,'0') As IsClauseApplicable,				
				IsNull(b.StdLinkClauseID,0) As StdLinkClauseID,
				IsNull(b.IsLinkApplicable,'0') As IsLinkApplicable				 				
		From QMS_V1_StandardMaster_Hdr a 
		Left Join QMS_V1_StandardMaster_Dtl b
			On a.StdID=b.StdID and b.StdClauseID=@StdClauseID and IsNull(b.IsClauseApplicable,'0')='1' 
				and b.StdLinkClauseID=@StdClauseID and IsNull(b.IsLinkApplicable,'0')='1' and b.EffStatus='1' 
				and Exists(Select * From QMS_V1_StandardMaster_Dtl m1
										Where m1.StdID=@StdID and m1.StdClauseID=@StdClauseID and m1.StdLinkClauseID=0 
											and IsNull(m1.IsClauseApplicable,'0')='1' and m1.EffStatus='1' 
											and m1.BranchID=@BranchID and m1.CompID=@CompID
									)
				and Exists(Select * From QMS_V1_StandardMaster_Dtl m2
										Where m2.StdID=@StdID and m2.StdClauseID=b.StdClauseID and m2.StdClauseID=b.StdLinkClauseID 
											and IsNull(m2.IsClauseApplicable,'0')='1' and m2.StdLinkClauseID=0  and m2.EffStatus='1' 
											and m2.BranchID=@BranchID and m2.CompID=@CompID
									)
				and Exists(Select * From QMS_V1_StandardMaster_Dtl m3
										Where m3.StdID=b.StdID and m3.StdClauseID=b.StdClauseID and m3.StdLinkClauseID=b.StdLinkClauseID 
											and IsNull(m3.IsLinkApplicable,'0')='1' and m3.StdLinkClauseID>0 and m3.EffStatus='1' 
											and m3.BranchID=@BranchID and m3.CompID=@CompID
									)				
				and a.BranchID=b.BranchID and a.CompID=b.CompID
		Where a.StdID<>@StdID and a.EffStatus='1' and a.BranchID=@BranchID and a.CompID=@CompID
		Order by a.StdID 
	 End		   
--------------------				
/* Previous Query 2:
	if @TranType=1   /* Create */      
   Begin      
		Select a.StdID, a.StdName As StdName, '0' As IsLinkApplicable      
		From QMS_V1_StandardMaster_Hdr a      
		Where a.EffStatus='1' and a.StdID<>@StdID and a.BranchID=@BranchID and a.CompID=@CompID      
		Order by a.StdID      
   End      
	Else   /* Modify */      
	 Begin  
		/* Note: Getting Each Standard Clause Link (Common) Related Standard Name */		 		

		Select Distinct a.StdID, a.StdName, IsNull(b.StdClauseID,0) As StdClauseID, 
				IsNull(b.IsClauseApplicable,'0') As IsClauseApplicable,				
				IsNull(b.StdLinkClauseID,0) As StdLinkClauseID,
				IsNull(b.IsLinkApplicable,'0') As IsLinkApplicable				 				
		From QMS_V1_StandardMaster_Hdr a 
		Left Join QMS_V1_StandardMaster_Dtl b
			On a.StdID=b.StdID and b.StdClauseID=@StdClauseID and IsNull(b.IsClauseApplicable,'0')='1' 
				and b.StdLinkClauseID=@StdClauseID and IsNull(b.IsLinkApplicable,'0')='1' and b.EffStatus='1' 
				and Exists(Select * From QMS_V1_StandardMaster_Dtl m1
										Where m1.StdID=@StdID and m1.StdClauseID=@StdClauseID and m1.StdLinkClauseID=0 
											and IsNull(m1.IsClauseApplicable,'0')='1' and m1.EffStatus='1' 
											and m1.BranchID=@BranchID and m1.CompID=@CompID
									)
				and Exists(Select * From QMS_V1_StandardMaster_Dtl m2
										Where m2.StdID=b.StdID and m2.StdClauseID=b.StdClauseID and m2.StdClauseID=b.StdLinkClauseID 
											and IsNull(m2.IsClauseApplicable,'0')='1' and m2.StdLinkClauseID=0  and m2.EffStatus='1' 
											and m2.BranchID=@BranchID and m2.CompID=@CompID
									)
				and Exists(Select * From QMS_V1_StandardMaster_Dtl m3
										Where m3.StdID=@StdID and m3.StdClauseID=b.StdClauseID and m3.StdLinkClauseID=b.StdLinkClauseID 
											and IsNull(m3.IsLinkApplicable,'0')='1' and m3.StdLinkClauseID>0 and m3.EffStatus='1' 
											and m3.BranchID=@BranchID and m3.CompID=@CompID
									)				
				and a.BranchID=b.BranchID and a.CompID=b.CompID
		Where a.StdID<>@StdID and a.EffStatus='1' and a.BranchID=@BranchID and a.CompID=@CompID
		Order by a.StdID
*/
--------------------				
/* Previous Query 1:
		Select Distinct a.StdID, a.StdName, IsNull(c.StdClauseID,0) As StdClauseID, IsNull(c.StdID,0) As c_StdID, 
			IsNull(c.IsClauseApplicable,'0') As IsClauseApplicable,				
			(Case When a.StdID=IsNull(b.StdID,0) and IsNull(b.StdClauseID,0)=@StdClauseID
						and IsNull(b.IsClauseApplicable,'0')='0' Then '0' Else IsNull(c.IsLinkApplicable,'0') End) As IsLinkApplicable, 
			IsNull(b.StdID,0) As b_StdID, IsNull(b.StdClauseID,0) As b_StdClauseID, 
			IsNull(b.IsClauseApplicable,'0') As b_IsClauseApplicable, IsNull(b.StdLinkClauseID,0) As b_StdLinkClauseID
		From QMS_V1_StandardMaster_Hdr a  
		Left Outer Join QMS_V1_StandardMaster_Dtl b
			On a.StdID=b.StdID and b.StdClauseID=@StdClauseID and b.StdID<>@StdID and b.StdLinkClauseID=0
				and b.EffStatus='1' and a.BranchID=b.BranchID and a.CompID=b.CompID
		Left Outer Join QMS_V1_StandardMaster_Dtl c
			On a.StdID=c.StdID and c.StdClauseID=@StdClauseID and c.StdLinkClauseID=@StdClauseID and c.StdID<>@StdID
				and c.IsClauseApplicable='1' and c.IsLinkApplicable='1' and c.EffStatus='1' 				
				and a.BranchID=c.BranchID and a.CompID=c.CompID    
		Where a.EffStatus='1' and a.StdID<>@StdID  and a.BranchID=@BranchID and a.CompID=@CompID      
		Order by a.StdID, StdClauseID
*/				  
END  
GO

