BEGIN      
 SET NOCOUNT ON;  

	Select a.StdClauseID, a.StdClauseName, Case When a.EffStatus='1' Then 'Active' Else 'In-active' End As EffStatus, 
		a.TranStamp
	From QMS_V1_StandardClauseMaster a
	Where a.EffStatus='1' and a.BranchID=@BranchID and a.CompID=@CompID
