/****** Object:  StoredProcedure [dbo].[QMS_V1_StandardMaster_Fil_DtlStdClauseList]    Script Date: 17/06/2026 11:30:53 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QMS_V1_StandardMaster_Fil_DtlStdClauseList](@TranType int, @StdID int=0, @BranchID varchar(3),   
@CompID varchar(3))        
AS        
BEGIN        
 SET NOCOUNT ON;    
  
 if @TranType=1   /* Create */  
  Begin  
		Select a.StdClauseID, a.StdClauseName, '1' As IsClauseApplicable,    
		 Case When a.EffStatus='1' Then 'Active' Else 'In-active' End As EffStatus,   
		 a.TranStamp  
		From QMS_V1_StandardClauseMaster a  
		Where a.EffStatus='1' and a.BranchID=@BranchID and a.CompID=@CompID  
		Order by a.StdClauseID
  End  
 Else   /* Modify */  
  Begin  
		Select Distinct IsNull(b.StdID,0) As StdID, a.StdClauseID, a.StdClauseName, 
				IsNull(b.IsClauseApplicable,'0') As IsClauseApplicable,  IsNull(b.StdLinkID,0) As StdLinkID, 
				IsNull(b.StdLinkClauseID,0) As StdLinkClauseID, IsNull(b.IsLinkApplicable,'0') As IsLinkApplicable,     
			 Case When IsNull(b.EffStatus,'0')='1' Then 'Active' Else 'In-active' End As EffStatus			 
		From QMS_V1_StandardClauseMaster a  
		Left Outer Join QMS_V1_StandardMaster_Dtl b  
		 On b.StdID=@StdID and a.StdClauseID=b.StdClauseID and b.StdLinkID=0 and b.StdLinkClauseID=0
			and a.BranchID=b.BranchID and a.CompID=b.CompID  
		Where a.EffStatus='1' and a.BranchID=@BranchID and a.CompID=@CompID 
		Order by StdID, a.StdClauseID 
  End  
END 
GO

/****** Object:  StoredProcedure [dbo].[QMS_V1_StandardMaster_Fil_StdDocDtl]    Script Date: 17/06/2026 11:30:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QMS_V1_StandardMaster_Fil_StdDocDtl](@StdID int, @AsOnDate datetime, @RptDate datetime,     
 @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS          
BEGIN          
 SET NOCOUNT ON;      
    
 Declare @DocNo int;    
 Declare @DocDate datetime;    
    
 Begin    
  Select @DocNo=Max(a.DocNo), @DocDate=Max(a.DocDate)    
  From QMS_V1_StandardDocument_Dtl a      
  Where a.StdID=@StdID and a.BranchID=@BranchID and a.CompID=@CompID     
    and a.Finyear=@Finyear    
    
  Select @DocNo=IsNull(@DocNo,0), @DocDate=(Case When (@DocDate Is Null) Then '1900-01-01' Else @DocDate End);    
 End    
      
 /* Output (Result) */    
 Select a.StdID, a.DocNo, b.StdName As DocType, a.DocDate, IsNull(a.MainContent,'') As MainContent,    
   IsNull(a.SubContent,'') As SubContent, IsNull(a.Parent,0) As Parent, IsNull(a.SymRef,0) As SymRef,    
   IsNull(a.Relation,0) As Relation, IsNull(a.RefValue,0) As RefValue, IsNull(a.SeqNo,0) As SeqNo, 
	 IsNull(a.DocFileID,0) As DocFileID, IsNull(a.Remarks,'') As Remarks, a.FromDate, a.ToDate,    
   Case When IsNull(a.EffStatus,'0')='0' Then 'In-active' Else 'Active' End As EffStatus,    
   IsNull(a.Finyear,'') As Finyear    
 From QMS_V1_StandardDocument_Dtl a     
 Left Outer Join QMS_V1_StandardMaster_Hdr b    
  On a.StdID=b.StdID and a.BranchID=b.BranchID and a.CompID=b.CompID    
  Where a.StdID=@StdID and a.DocNo=@DocNo and a.DocDate=@DocDate    
  /* and (Convert(varchar(10),@AsOnDate,121)>=a.FromDate and Convert(varchar(10),@AsOnDate,121)<=a.ToDate) */    
  and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear    
END       
GO

/****** Object:  StoredProcedure [dbo].[QMS_V1_StandardMaster_Fil_StdDocLevel]    Script Date: 17/06/2026 11:30:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QMS_V1_StandardMaster_Fil_StdDocLevel](@StdID int, @DocNo int, @DocDate datetime, 
	@FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime,   
	@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))
As            
BEGIN
	SET NOCOUNT ON;

	Declare @TmpTbl_StdDocLevel As Table
	(
		StdID int, 
		DocNo int,
		DocDate datetime,
		LevelSerialNo varchar(20), 
		MainContent varchar(1000), 
		SubContent varchar(1000), 
		Parent int, 
		Relation int, 
		SeqNo int,
		SymRef int,
		DocFileID int,
		FromDate datetime,
		ToDate datetime,
		EffStatus bit,
		BranchID varchar(3),  
		CompID varchar(3), 
		Finyear varchar(20),
		SymRefCnt int,
		SetSeq int
	)

	/* Note:	@StdID	-> Treat As DocType						
					@SymRef -> 2 Question / 3 Evidence / 6 Document / (No Need) 7 Other and Other(s) <None>
					fn_QMS_V1_RESX_FileRepository_Dtl - > AssetCode Treat As DocFileID (NodeIdx)
	*/	

	Begin	
		Declare @SymRefCnt As int;

		/* Insert Data Into Temp Table */
		Insert Into @TmpTbl_StdDocLevel

		Select a.StdID, a.DocNo, a.DocDate, a.LevelSerialNo, a.MainContent, a.SubContent, a.Parent, a.Relation, 
				a.SeqNo, a.SymRef, a.DocFileID, a.FromDate, a.ToDate, a.EffStatus, a.BranchID, a.CompID, a.Finyear,
				0 As SymRefCnt, 0 As SetSeq
		From QMS_V1_StandardDocument_Dtl a
		Where a.StdID=@StdID and a.DocNo=@DocNo and a.DocDate=@DocDate and a.FromDate=@FromDate 
			/*and a.ToDate=@ToDate*/ and a.EffStatus='1' and a.BranchID=@BranchID and a.CompID=@CompID 
			and a.Finyear=@Finyear
		Order by a.SeqNo

		/* Get SymRef Count */
		Select @SymRefCnt=Count(x.SymRef)
		From (
					Select Distinct a.SymRef From @TmpTbl_StdDocLevel a					 
					Where a.SetSeq=0 and a.StdID=@StdID and a.SymRef In(2,3,6,7) and a.BranchID=@BranchID and a.CompID=@CompID 
					and a.Finyear=@Finyear
		) x
	End

		/* Output (Result) */	 
		Select a.StdID, a.DocNo, a.DocDate, a.LevelSerialNo, a.MainContent, a.SubContent, a.Parent, a.Relation, 
				a.SeqNo, a.SymRef, Case When (a.SymRef=2 or a.SymRef=3 or a.SymRef=6 or a.SymRef=7) Then 1 Else 0 End As SymRefAvailable, 
				a.DocFileID, a.FromDate, a.ToDate, a.EffStatus, a.BranchID, a.CompID, a.Finyear,
				@SymRefCnt As SymRefCnt, 1 As SetSeq
		From @TmpTbl_StdDocLevel a
		Where a.SetSeq=0 and a.StdID=@StdID and a.BranchID=@BranchID and a.CompID=@CompID 
			and a.Finyear=@Finyear
		Order by a.SeqNo

	/*	/* Output (Result) */	  
	Select a.StdID, sm.StdName As DocType, a.DocNo, a.DocDate, IsNull(a.Lev1_SerialNo,'') As Lev1_SerialNo, a.Lev1_Content, a.Lev1_Parent, 
			IsNull(a.Lev1_Relation,0) As Lev1_Relation, a.Lev1_SeqNo, IsNull(a.Lev1_SymRef,0) As Lev1_SymRef, IsNull(a.Lev1_DocFileID,0) As Lev1_DocFileID, 
			IsNull(b.Lev2_SerialNo,'') As Lev2_SerialNo, IsNull(b.Lev2_Content,'') As Lev2_Content, IsNull(b.Lev2_Parent,0) As Lev2_Parent, IsNull(b.Lev2_Relation,0) As Lev2_Relation, 
			IsNull(b.Lev2_SeqNo,0) As Lev2_SeqNo, IsNull(b.Lev2_SymRef,0) As Lev2_SymRef, IsNull(b.Lev2_DocFileID,0) As Lev2_DocFileID,  
			IsNull(c.Lev3_SerialNo,'') As Lev3_SerialNo, IsNull(c.Lev3_Content,'') As Lev3_Content, IsNull(c.Lev3_Parent,0) As Lev3_Parent, IsNull(c.Lev3_Parent,0) As Lev3_Relation, 
			IsNull(c.Lev3_SeqNo,0) As Lev3_SeqNo,  IsNull(c.Lev3_SymRef,0) As Lev3_SymRef, IsNull(c.Lev3_DocFileID,0) As Lev3_DocFileID, 
			IsNull(d.Lev4_SerialNo,'') As Lev4_SerialNo, IsNull(d.Lev4_Content,'') As Lev4_Content, IsNull(d.Lev4_Parent,0) As Lev4_Parent, IsNull(d.Lev4_Parent,0) As Lev4_Relation, 
			IsNull(d.Lev4_SeqNo,0) As Lev4_SeqNo,  IsNull(d.Lev4_SymRef,0) As Lev4_SymRef, IsNull(d.Lev4_DocFileID,0) As Lev4_DocFileID, 
			IsNull(e.Lev5_SerialNo,'') As Lev5_SerialNo, IsNull(e.Lev5_Content,'') As Lev5_Content, IsNull(e.Lev5_Parent,0) As Lev5_Parent, 
			IsNull(e.Lev5_Parent,0) As Lev5_Relation, IsNull(e.Lev5_SeqNo,0) As Lev5_SeqNo,  IsNull(e.Lev5_SymRef,0) As Lev5_SymRef, IsNull(e.Lev5_DocFileID,0) As Lev5_DocFileID, 
			IsNull(f.Lev6_Parent,0) As Lev6_Parent, IsNull(f.Lev6_Parent,0) As Lev5_Relation, IsNull(f.Lev6_SeqNo,0) As Lev6_SeqNo,  
			IsNull(f.Lev6_SymRef,0) As Lev6_SymRef, IsNull(f.Lev6_DocFileID,0) As Lev6_DocFileID, 
			/*IsNull(f.Question,'') As Question, IsNull(f.E_SymRef,0) As E_SymRef, IsNull(f.Evidence,'') As Evidence, 
			IsNull(f.D_SymRef,0) As D_SymRef, IsNull(f.Document,'') As Document, */ @SymRefCnt As SymRefCnt,
			a.FromDate, a.ToDate, a.EffStatus, a.BranchID, a.CompID, a.Finyear 
	From (
		Select a1.StdID, a1.DocNo, a1.DocDate,  a1.LevelSerialNo As Lev1_SerialNo, a1.MainContent As Lev1_Content, a1.Parent As Lev1_Parent, 
						a1.Relation As Lev1_Relation, a1.SeqNo As Lev1_SeqNo, a1.SymRef As Lev1_SymRef, a1.DocFileID As Lev1_DocFileID, a1.FromDate, a1.ToDate, 
						a1.EffStatus, a1.BranchID, a1.CompID, a1.Finyear
				From @TmpTbl_StdDocLevel a1
				Where a1.StdID=@StdID and a1.Parent>=0
							--and Exists(Select * From @TmpTbl_StdDocLevel a2
							--					Where a2.StdID=@StdID and a2.Parent=0 --and a2.Parent=a1.SeqNo 
							--						and a2.BranchID=@BranchID and a2.CompID=@CompID
							--					)
							and a1.BranchID=@BranchID and a1.CompID=@CompID
				) a	
	Left Outer Join (Select b1.StdID, b1.LevelSerialNo As Lev2_SerialNo, b1.MainContent As Lev2_Content, b1.Parent As Lev2_Parent, 
										b1.Relation As Lev2_Relation,	b1.SeqNo As Lev2_SeqNo, b1.SymRef As Lev2_SymRef, b1.DocFileID As Lev2_DocFileID
				From @TmpTbl_StdDocLevel b1
				Where b1.StdID=@StdID and b1.Parent>0
							and Exists(Select * From @TmpTbl_StdDocLevel b2
												Where b2.StdID=@StdID and b2.Parent>0 and b2.SeqNo=b1.Parent 
													and b2.BranchID=@BranchID and b2.CompID=@CompID
												)
							and b1.BranchID=@BranchID and b1.CompID=@CompID
				) b
		On a.StdID=b.StdID  and b.Lev2_Parent>0 and a.Lev1_SeqNo=b.Lev2_Parent
	Left Outer Join (Select c1.StdID, c1.LevelSerialNo As Lev3_SerialNo, c1.MainContent As Lev3_Content, c1.Parent As Lev3_Parent, 
										c1.Relation As Lev3_Relation,	c1.SeqNo As Lev3_SeqNo, c1.SymRef As Lev3_SymRef, c1.DocFileID As Lev3_DocFileID
				From @TmpTbl_StdDocLevel c1
				Where c1.StdID=@StdID and c1.Parent>0
							and Exists(Select * From @TmpTbl_StdDocLevel c2
												Where c2.StdID=@StdID and c2.Parent>0 and c2.SeqNo=c1.Parent 
													and c2.BranchID=@BranchID and c2.CompID=@CompID
												)
							and c1.BranchID=@BranchID and c1.CompID=@CompID
				) c
		On a.StdID=c.StdID  and c.Lev3_Parent>0 and b.Lev2_SeqNo=c.Lev3_Parent
	Left Outer Join (Select d1.StdID, d1.LevelSerialNo As Lev4_SerialNo, d1.MainContent As Lev4_Content, d1.Parent As Lev4_Parent, 
										d1.Relation As Lev4_Relation,	d1.SeqNo As Lev4_SeqNo, d1.SymRef As Lev4_SymRef, d1.DocFileID As Lev4_DocFileID
				From @TmpTbl_StdDocLevel d1
				Where d1.StdID=@StdID and d1.Parent>0
							and Exists(Select * From @TmpTbl_StdDocLevel d2
												Where d2.StdID=@StdID and d2.Parent>0 and d2.SeqNo=d1.Parent 
													and d2.BranchID=@BranchID and d2.CompID=@CompID
												)
							and d1.BranchID=@BranchID and d1.CompID=@CompID
				) d
		On a.StdID=d.StdID  and d.Lev4_Parent>0 and c.Lev3_SeqNo=d.Lev4_Parent
	Left Outer Join (Select e1.StdID, e1.LevelSerialNo As Lev5_SerialNo, e1.MainContent As Lev5_Content, e1.Parent As Lev5_Parent, 
										e1.Relation As Lev5_Relation,	e1.SeqNo As Lev5_SeqNo, e1.SymRef As Lev5_SymRef, e1.DocFileID As Lev5_DocFileID
				From @TmpTbl_StdDocLevel e1
				Where e1.StdID=@StdID and e1.Parent>0
							and Exists(Select * From @TmpTbl_StdDocLevel e2
												Where e2.StdID=@StdID and e2.Parent>0 and e2.SeqNo=e1.Parent 
													and e2.BranchID=@BranchID and e2.CompID=@CompID
												)
							and e1.BranchID=@BranchID and e1.CompID=@CompID
				) e
		On a.StdID=e.StdID  and e.Lev5_Parent>0 and d.Lev4_SeqNo=e.Lev5_Parent
	Left Outer Join (Select f1.StdID, f1.LevelSerialNo As Lev6_SerialNo, f1.MainContent As Lev6_Content, f1.Parent As Lev6_Parent, 
										f1.Relation As Lev6_Relation,	f1.SeqNo As Lev6_SeqNo, f1.SymRef As Lev6_SymRef, f1.DocFileID As Lev6_DocFileID
				From @TmpTbl_StdDocLevel f1
				Where f1.StdID=@StdID and f1.Parent>0
							and Exists(Select * From @TmpTbl_StdDocLevel f2
												Where f2.StdID=@StdID and f2.Parent>0 and f2.SeqNo=f1.Parent 
													and f2.BranchID=@BranchID and f2.CompID=@CompID
												)
							and f1.BranchID=@BranchID and f1.CompID=@CompID
				) f
		On a.StdID=f.StdID  and f.Lev6_Parent>0 and e.Lev5_SeqNo=f.Lev6_Parent
	Left Outer Join QMS_StandardMaster_Hdr sm  
		On a.StdID=sm.StdID and sm.EffStatus='1' and a.BranchID=sm.BranchID and a.CompID=sm.CompID  
	Where a.BranchID=@BranchID and a.CompID=@CompID  
	Order by a.Lev1_SeqNo, b.Lev2_SeqNo, c.Lev3_SeqNo, d.Lev4_SeqNo, e.Lev5_SeqNo, f.Lev6_SeqNo
*/
END
GO

/****** Object:  StoredProcedure [dbo].[QMS_V1_StandardMaster_Fil_StdName]    Script Date: 17/06/2026 11:30:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QMS_V1_StandardMaster_Fil_StdName](@StdID int, @StdClauseID int, 
	@BranchID varchar(3), @CompID varchar(3))            
AS            
BEGIN            
	SET NOCOUNT ON;        
 
	/* Note: Getting Each Standard Clause Link (Common) Related Standard Name */		 		

	Select a.StdID, b.StdName, IsNull(a.StdClauseID,0) As StdClauseID, 
			IsNull(a.IsClauseApplicable,'0') As IsClauseApplicable,				
			IsNull(a.IsLinkApplicable,'0') As IsLinkApplicable,
			IsNull(a.StdLinkClauseID,0) As StdLinkClauseID				
	From QMS_V1_StandardMaster_Dtl a
	Inner Join QMS_V1_StandardMaster_Hdr b
		On a.StdID=b.StdID and b.EffStatus='1' and a.BranchID=b.BranchID and a.CompID=b.CompID
	Where a.StdClauseID=@StdClauseID and IsNull(a.IsClauseApplicable,'0')='1' and a.StdLinkClauseID=@StdClauseID 
			and IsNull(a.IsLinkApplicable,'0')='1' and a.EffStatus='1' 
			and Exists(	Select * From QMS_V1_StandardMaster_Dtl m1
									Where m1.StdID=@StdID and m1.StdClauseID=@StdClauseID and m1.StdLinkClauseID=0 
										and IsNull(m1.IsClauseApplicable,'0')='1' and m1.EffStatus='1' 
										and m1.BranchID=@BranchID and m1.CompID=@CompID
								)
			and Exists(Select * From QMS_V1_StandardMaster_Dtl m2
									Where m2.StdID=a.StdID and m2.StdClauseID=a.StdClauseID and m2.StdClauseID=a.StdLinkClauseID 
										and IsNull(m2.IsClauseApplicable,'0')='1' and m2.StdLinkClauseID=0  and m2.EffStatus='1' 
										and m2.BranchID=@BranchID and m2.CompID=@CompID
								)
			and Exists(Select * From QMS_V1_StandardMaster_Dtl m3
										Where m3.StdID=@StdID and m3.StdClauseID=a.StdClauseID and m3.StdLinkClauseID=a.StdLinkClauseID 
											and IsNull(m3.IsLinkApplicable,'0')='1' and m3.StdLinkClauseID>0 and m3.EffStatus='1' 
											and m3.BranchID=@BranchID and m3.CompID=@CompID
									)
			and a.BranchID=@BranchID and a.CompID=@CompID
	Order by a.StdID
END 
GO

