CREATE PROCEDURE [dbo].[QMS_V1_StandardMaster_Get_MaxDocNoDate](@StdID int, @AsOnDate datetime, @RptDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))      
AS      
BEGIN      
 SET NOCOUNT ON;  

	Declare @DocNo int;
	Declare @DocDate datetime;

	Begin
		Select @DocNo=Max(a.DocNo), @DocDate=Max(a.DocDate)
		From QMS_V1_StandardDocument_Dtl_Rep a  
		Where a.StdID=@StdID and a.BranchID=@BranchID and a.CompID=@CompID 
				and a.Finyear=@Finyear

		Select IsNull(@DocNo,0) As DocNo, (Case When (@DocDate Is Null) Then '1900-01-01' Else @DocDate End) As DocDate;
	End
END
GO

/****** Object:  StoredProcedure [dbo].[QMS_V1_StandardMaster_Get_Period]    Script Date: 17/06/2026 11:30:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QMS_V1_StandardMaster_Get_Period](@AsOnDate datetime, @RptDate datetime,     
 @BranchID varchar(3), @CompID varchar(3))                            
As                
BEGIN                
 SET NOCOUNT ON;    
    
  Select Distinct a.FromYear, a.ToYear,     
   (SubString(Convert(varchar(10),a.FromYear,105),4,7) + ' ' + SubString(Convert(varchar(10),a.ToYear,105),4,7)) As Finyear    
  From Company_Finyear a --dbo.fn_COM_Company_Finyear('A', @AsOnDate, @RptDate) a                
  Where a.BranchID=@BranchID and a.CompID=@CompID    
  Order by a.FromYear Desc    
END 
GO

