CREATE PROCEDURE [dbo].[QMS_V1_StandardMaster_Get_StdData](@StdID int=0, @StdName varchar(50)='', @BranchID varchar(3), 
	@CompID varchar(3))                            
As                
BEGIN                
 SET NOCOUNT ON;    
    
  Select Distinct a.StdID, a.StdName, (Case When Len(convert(varchar(5),a.StdID))=1 Then ('20' + convert(varchar(5),a.StdID)) 
		When Len(convert(varchar(5),a.StdID))=2 Then ('2' + convert(varchar(5),a.StdID))  
		When Len(convert(varchar(5),a.StdID))=3 Then Convert(varchar(5),a.StdID) Else '0' End) As MenuIdx
  From QMS_V1_StandardMaster_Hdr a                
  Where (@StdID<=0 or (@StdID>0 and a.StdID=@StdID)) and (@StdName='' or (@StdName<>'' and a.StdName=@StdName)) 
		and a.EffStatus='1' and a.BranchID=@BranchID and a.CompID=@CompID    
  Order by a.StdID    
END 
GO

