CREATE PROCEDURE [dbo].[QMS_V1_StandardMaster_Hlp_StdDocDtl](@StdID int, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))        
AS        
BEGIN        
 SET NOCOUNT ON;    
  
 /* Output (Result) */  
 Select Distinct a.StdID, a.DocNo, b.StdName As DocType, a.DocDate, a.FromDate, a.ToDate,  
   Case When IsNull(a.EffStatus,'0')='0' Then 'In-active' Else 'Active' End As EffStatus,  
   IsNull(a.Finyear,'') As Finyear  
 From QMS_V1_StandardDocument_Dtl a   
 Left Outer Join QMS_V1_StandardMaster_Hdr b  
  On a.StdID=b.StdID and a.BranchID=b.BranchID and a.CompID=b.CompID  
  Where a.StdID=@StdID and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear
	Order by a.StdID, a.DocDate Desc, a.DocNo Desc, a.FromDate Desc
END     
GO

/****** Object:  StoredProcedure [dbo].[QMS_V1_StandardMaster_Sav_LinkData]    Script Date: 17/06/2026 11:30:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QMS_V1_StandardMaster_Sav_LinkData]     
(      
 @StdID [int],  
 @StdClauseID [int],  
 @IsClauseApplicable [bit],  
 @StdLinkID [int],  
 @StdLinkClauseID [int],  
 @IsLinkApplicable [bit], 
 @EffStatus  [bit],   
 @UserID  [varchar](10),  
 @BranchID [varchar](3),  
 @CompID [varchar](3),    
 @TranStamp  [datetime]   
)  
AS          
BEGIN          
	SET NOCOUNT ON;    

	Declare @IsClauseApp As bit;
	Declare @IsLinkApp As bit;

	Select @IsClauseApp='0', @IsLinkApp='0';

 /* Note: @IsClauseApplicable <-- '0' / @IsLinkApplicable <-- @IsLinkApplicable */
  
	If Exists(Select * From QMS_V1_StandardMaster_Dtl_Rep a 
						Where a.StdID=@StdID and a.StdClauseID=@StdClauseID --and a.StdLinkID=@StdLinkID 
							and a.StdLinkClauseID=@StdLinkClauseID and a.BranchID=@BranchID and a.CompID=@CompID
					)
	 Begin
		Select @IsClauseApp=a.IsClauseApplicable --, @IsLinkApp=a.IsLinkApplicable
		From QMS_V1_StandardMaster_Dtl_Rep a 
		Where a.StdID=@StdID and a.StdClauseID=@StdClauseID --and a.StdLinkID=0 
			and a.StdLinkClauseID=0 and a.BranchID=@BranchID and a.CompID=@CompID

		Select @IsClauseApp=IsNull(@IsClauseApp,'0'); --, @IsLinkApp=IsNull(@IsLinkApp,'0');

		if @IsClauseApp='0'		/* Clause Not Applicable */
		 Begin 
			SET @IsClauseApp=(Case When @IsLinkApplicable='1' Then '1' Else '0' End);  /* Link Based Clause Applicable */
			SET @IsLinkApp=@IsLinkApplicable;				/* Link Applicable */
		 End
		Else									/* Clause Applicable */
		 Begin 
			SET @IsClauseApp=@IsClauseApp;  /* Link Based Clause Applicable */
			SET @IsLinkApp=@IsLinkApplicable;				/* Link Applicable */
		 End

		/* Update Data Into Table */
		Update QMS_V1_StandardMaster_Dtl_Rep SET IsClauseApplicable=@IsClauseApp, IsLinkApplicable=@IsLinkApp
		Where StdID=@StdID and StdClauseID=@StdClauseID -- and StdLinkID=@StdLinkID 
			and StdLinkClauseID=@StdLinkClauseID and BranchID=@BranchID and CompID=@CompID;
	 End
	Else	
	 Begin				
		if @StdLinkClauseID='1' and @IsLinkApplicable='1'		/* Link Based Clause Applicable */
		 Begin 
			SET @IsLinkApp='1';

			/* Insert Data Into Table */
			Insert Into QMS_V1_StandardMaster_Dtl_Rep(StdID, StdClauseID, IsClauseApplicable, StdLinkID, StdLinkClauseID, IsLinkApplicable, EffStatus, UserID, BranchID, CompID, TranStamp)
			Values(@StdID, @StdClauseID, @IsLinkApp, @StdLinkID, @StdLinkClauseID, @IsLinkApplicable, @EffStatus, @UserID, @BranchID, @CompID, @TranStamp);
		 End
	 End 
END  
GO

