/****** Object:  StoredProcedure [dbo].[QMS_V1_StandardMaster_Val_HdrStdName]    Script Date: 17/06/2026 11:30:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QMS_V1_StandardMaster_Val_HdrStdName](@TranType int, @StdName varchar(50)='', 
	@New_StdName varchar(50)='', @BranchID varchar(3), @CompID varchar(3))        
AS        
BEGIN        
 SET NOCOUNT ON;    

 /* Note: @StdName			:  Already Existing Data for using only Modify
					@New_StdName	:  New Data for using Create/Modify
 */ 
  
	if @TranType<>1				/* Modify */
	 Begin
		Select a.StdId, a.StdName  
		From QMS_V1_StandardMaster_Hdr a  
		Where a.StdName=@New_StdName and a.BranchID=@BranchID and a.CompID=@CompID
	 End
	Else				/* Create */
	 Begin
		Select a.StdId, a.StdName  
		From QMS_V1_StandardMaster_Hdr a  
		Where a.StdName<>@StdName and a.StdName=@New_StdName 
			and a.BranchID=@BranchID and a.CompID=@CompID
	 End	 
END
GO

/****** Object:  StoredProcedure [dbo].[QMS_V1_StandardMaster_Val_StdClause]    Script Date: 17/06/2026 11:30:54 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[QMS_V1_StandardMaster_Val_StdClause](@StdID int, @BranchID varchar(3), @CompID varchar(3))            
AS            
BEGIN            
 SET NOCOUNT ON;        

		Select a.StdID, b.StdName, a.StdClauseID, IsNull(a.StdLinkID,0) As StdLinkID, IsNull(a.StdLinkClauseID,0) As StdLinkClauseID,
				(Case When a.EffStatus='1' and b.EffStatus='1' and IsNull(a.IsClauseApplicable,'0')='1' Then IsNull(a.IsClauseApplicable,'0') Else '0' End) As IsClauseApplicable
		From QMS_V1_StandardMaster_Dtl a
		Left Outer Join QMS_V1_StandardMaster_Hdr b
			On a.STdID=b.STdID and a.BranchID=b.BranchID and a.CompID=b.CompID		 
		Where @StdID>0 and a.StdID=@StdID and IsNull(a.StdLinkClauseID,0)=0 and a.BranchID=@BranchID and a.CompID=@CompID		 
		Order by a.StdID, a.StdClauseID
END 
GO

