CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_CashPurchaseItem] (@AsOnDate Datetime, @RptDate Datetime, @BranchID varchar(3), 
    @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

     Select a.ItemCode, a.ItemDescription, IsNull(a.PurchaseUOMDesc,'') As PurchaseUOMDesc,  
         IsNull(a.PurchaseUOMDecimal,0) As PurchaseUOMDecimal, IsNull(a.HeatNoApplicable,'0') As HeatNoApplicable, 
         IsNull(a.ShelfLifePeriodApplicable,'0') As ShelfLifePeriodApplicable, 
         IsNull(a.SelfLifePeriod,0) As SelfLifeDays 
     From MATERIAL_MASTER a Where a.ItemNature In('M','T','L','C','A') 
     and a.Boughtout In('B','S') and a.Branchid=@BranchID and a.Compid=@CompID 
     Order by a.ItemCode
END
