CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_CustomerSuppliedProductItem] (@DocType varchar(5), @DocNo int, @DocDate datetime, @SetDate datetime, 
    @CurrDate datetime, @AsOnDate Datetime, @RptDate Datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

    Select a.ReceivedItemCode, b.ItemDescription, b.PurchaseUOMDesc, b.PurchaseUOMDecimal, a.OrderType, a.OrderNo, a.OrderDate,
        a.ItemGroupKey, b.HeatNoApplicable, b.ShelfLifePeriodApplicable  
    from dbo.fn_SAL_JOBWORKORDER_DTL(@SetDate, @CurrDate, @BranchID, @CompID, @Finyear) a  
    Left Outer Join MATERIAL_MASTER b 
        On a.ReceivedItemCode = b.ItemCode and a.Branchid = b.Branchid and a.Compid = b.Compid 
    where a.OrderType= @DocType and a.OrderNo = @DocNo and a.OrderDate=@DocDate
        and a.Status<>'C' and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear>=@TmpFinyear
    order by a.ReceivedItemCode
END
