CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_CustomerSuppliedProductVendor] (@SetDate datetime, @CurrDate datetime, @AsOnDate datetime, 
	@RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

    Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

     Select distinct (select b.PartyName From FAS_PARTY_MASTER b 
                     where b.PartyCode=a.CustomerCode and b.Branchid=a.Branchid and b.Compid=a.Compid) As PartyName,a.CustomerCode, 
        isNull((Select sum(e.ChallanQty) From REC_ReceiptEntry_Dtl e 
        Where e.RefType = a.OrderType and e.RefNo = a.OrderNo and e.RefDate = a.OrderDate 
        and e.Branchid=@BranchID and e.Compid=@CompID and e.Finyear>=@TmpFinyear and ReceiptDate is null and AcceptedDate is Null),0) As ChallanQty, 
        a.OrderType,a.OrderNo,a.OrderDate  
    From dbo.fn_SAL_JOBWORKORDER_HDR(@SetDate, @CurrDate, @BranchID, @CompID, @Finyear) a 
    where Convert(datetime,@CurrDate,111) between a.ValidFrom and a.ValidTo  and a.Status='A' 
        and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear>=@TmpFinyear
    Order by PartyName
END
GO

