CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_DCSRReturnItem] (@DocType varchar(5), @DocNo int, @DocDate datetime, @SetDate Datetime, 
	@CurrDate datetime, @AsOnDate Datetime, @RptDate Datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

	Select x.SentItemCode, x.ItemDescription, x.PurchaseUOMDesc, x.PurchaseUOMDecimal, x.SchDate, 
		x.SchQty, x.DCSRType, x.DCSRNo, x.DCSRDate, x.ItemGroupKey, x.Norms, SchQty-(ChallanQty+RecptQty) As BalQty,  
		'' as HeatNo, ItemNature, x.HeatNoApplicable, x.ShelfLifePeriodApplicable 
	From ( 
		Select a.SchDate, a.SentItemCode, b.ItemDescription, b.PurchaseUOMDesc, b.PurchaseUOMDecimal, a.DCSRType, 
			a.DCSRNo, a.DCSRDate, a.ItemGroupKey, a.Norms, (a.ScheduleQty) SchQty, IsNull(Sum(d.AcceptedQty), 0) As AcceptedQty, 
			isNull(Sum(Case When (d.ReceiptDate is Null and d.AcceptedDate is Null) then d.ChallanQty else 0 End), 0) as ChallanQty, 
			isNull(Sum(Case When (d.ReceiptDate is not Null and d.AcceptedDate is Null) then d.ReceiptQty else 0 End), 0) as RecptQty, 
			a.Branchid, a.compid, b.ItemNature, b.HeatNoApplicable, b.ShelfLifePeriodApplicable 
		From (
			Select a.SchDate, a.SentItemCode, a.ItemGroupKey, a.DCSRType, a.DCSRNo, a.DCSRDate, a.Norms, a.BranchID, a.CompID, 
				Sum(a.ScheduleQty) ScheduleQty 
			From dbo.fn_PUR_Dcsr_Tran_Min(@SetDate, @CurrDate, @BranchID, @CompID, @Finyear) a 
			Where a.DCSRType = @DocType and a.DCSRNo = @DocNo and a.DCSRDate = @DocDate 
				and a.Branchid= @BranchID and a.Compid= @CompID and a.Finyear>=@TmpFinyear
			Group By a.SchDate, a.SentItemCode, a.DCSRType, a.DCSRNo, a.DCSRDate, a.ItemGroupKey, a.Norms, a.BranchID, a.CompID 
			Having Sum(A.ScheduleQty) > 0 
	 ) a 
	 Left Outer Join ReceiptEntry d 
		On a.DCSRDate = d.RefDate and a.DCSRNo = d.Refno and a.DCSRType = d.RefType 
			and d.ItemGroupKey = a.ItemGroupKey and d.Branchid=a.Branchid 
			and d.Compid = a.Compid and d.Finyear>=@TmpFinyear
	 Left Outer Join MATERIAL_MASTER b 
		On a.SentItemCode=b.ItemCode and a.Branchid=b.Branchid and a.Compid=b.compid 
	 group by a.DCSRType, a.DCSRNo, a.DCSRDate, a.SentItemCode, b.ItemDescription, b.PurchaseUOMDesc, 
		b.PurchaseUOMDecimal, a.ScheduleQty, a.SchDate, a.ItemGroupKey, a.Norms, a.Branchid, a.compid, 
		b.ItemNature,b.HeatNoApplicable, b.ShelfLifePeriodApplicable  
	) x 
	Where SchQty - (ChallanQty + RecptQty) > 0 
END
GO

