CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_DCSRReturnVendor] (@SetDate datetime, @CurrDate datetime, @AsOnDate Datetime, 
	@RptDate Datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

	 Select x.PartyName, x.VendorCode, x.DCSRType, x.DCSRNo, x.DCSRDate, x.SchQty, SchQty-(ChallanQty+RecptQty) As BalQty 
	From ( 
		Select a.VendorCode, 
			(Select e.PartyName From FAS_PARTY_MASTER e 
			Where e.PartyCode=a.VendorCode and e.Branchid=@BranchID and e.Compid=@CompID) As PartyName, 
			a.SentItemCode, a.DCSRType, a.DCSRNo, a.DCSRDate, a.ItemGroupKey, (a.ScheduleQty) SchQty, 
			IsNull(Sum(d.AcceptedQty), 0)AcceptedQty, 
			isNull(Sum(Case When (d.ReceiptDate is Null and d.AcceptedDate is Null) then d.ChallanQty else 0 End), 0) as ChallanQty, 
			isNull(Sum(Case When (d.ReceiptDate is not Null and d.AcceptedDate is Null) then d.ReceiptQty else 0 End), 0) as RecptQty 
		From (
			Select c.VendorCode, a.SentItemCode, a.ItemGroupKey, a.DCSRType, a.DCSRNo, a.DCSRDate, a.Norms, a.BranchID, a.CompID, 
				Sum(a.ScheduleQty) ScheduleQty 
			From dbo.fn_PUR_Dcsr_Tran_Min(@SetDate, @CurrDate, @BranchID, @CompID, @Finyear) a 
			Left Outer Join PUR_DCSR_HDR c 
				On a.DCSRType=c.DCSRType and a.DCSRNo=c.DCSRNo and a.DCSRDate=c.DCSRDate and a.Branchid=c.Branchid 
					and a.Compid=c.Compid and a.Finyear=c.Finyear
			Where a.Branchid=@BranchID and a.Compid= @CompID and a.Finyear>=@TmpFinyear
			Group By c.VendorCode, a.SentItemCode, a.DCSRType, a.DCSRNo, a.DCSRDate, a.ItemGroupKey, a.Norms, a.BranchID, a.CompID 
			Having Sum(A.ScheduleQty) > 0 
		) a 
		Left Outer Join ReceiptEntry d 
			On a.DCSRDate = d.RefDate and a.DCSRNo = d.Refno and a.DCSRType = d.RefType and d.ItemGroupKey = a.ItemGroupKey 
				and d.Branchid=a.Branchid and d.Compid = a.Compid and d.Finyear>=@TmpFinyear
		group by a.VendorCode, a.DCSRType, a.DCSRNo, a.DCSRDate, a.SentItemCode, A.ScheduleQty, A.ItemGroupKey 
	) x 
	Where SchQty - (ChallanQty + RecptQty) > 0 
	Order by x.PartyName
END
GO

