CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_DismantlingDCVendor] (@AsOnDate Datetime, 
	@RptDate Datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

    Select Distinct x.VendorCode,(Select PartyName from FAS_Party_Master 
                                    where PartyCode=x.VendorCode and Branchid=x.Branchid and Compid=x.Compid) As VendorName,
        x.DocType, x.DocNo, x.DocDate, x.OrderType, x.OrderNo, x.OrderDate 
    From DismantlingDc x  
    Inner Join (select a.DocType,a.DocNo,a.DocDate,a.RecdItemCode,a.ToBeRecdQty as DcQty,a.ScheduleDate, 
                    isnull(B.AccQty + B.RejQty + B.ScrapQty, 0) As CompleteQty 
                From PUR_DismantlingDc_Dtl a 
                Left outer join Receive_DismantlingDc b 
                    on a.DocType=b.RefType and a.DocNo=b.RefNo and a.DocDate=b.RefDate 
                        and a.ScheduleDate=b.ScheduleDate and a.RecdItemCode=b.RecdItemCode 
                        and a.ItemGroupKey=b.ItemGroupKEy and a.Branchid=b.BRanchid and a.Compid=b.Compid 
                Where a.ToBeRecdQty>isnull(b.AccQty+b.RejQty+b.ScrapQty,0)
    ) z 
    On x.DocType=z.DocType and x.DocNo=z.DocNo and x.DocDate=z.DocDate 
    Where x.Branchid=@BranchID and x.Compid=@CompID
END
GO

