CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_LOMiscDCItem] (@DocType varchar(5), @DocNo int, @DocDate datetime, @SetDate datetime, 
    @CurrDate datetime, @AsOnDate Datetime, @RptDate Datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

    Select Distinct ItemCode, ItemDescription, PurchaseUOMDesc, OrderQty, PUrchaseUOMDecimal,
    DocType, DocNo, DocDate,((OrderQty)-Sum(AcceptedQty+RejectionQty))PendingQty, HeatNoApplicable, ShelfLifePeriodApplicable
    From (
		Select a.DocType, a.DocNo, a.DocDate, a.VendorCode, c.PartyName, a.ItemCode,
			d.ItemDescription, d.PurchaseUOMDecimal, d.PurchaseUOMDesc, a.OrderQty,
			isNull(Sum(Case When b.ReceiptDate is Null and b.AcceptedDate is Null then b.ChallanQty else 0 End), 0) as ChallanQty,
			isNull(Sum(Case When b.ReceiptDate is Not Null and b.AcceptedDate is Null then b.ReceiptQty else 0 End), 0) as RecptQty,
			IsNull(B.AcceptedQty,0)AcceptedQty, IsNull(b.RejectionQty,0)RejectionQty, d.HeatNoApplicable, d.ShelfLifePeriodApplicable
		From (
			Select  a.DocType, a.DocNo, a.DocDate, a.VendorCode, b.ItemCode, b.Qty as OrderQty, a.BranchID, a.CompID
			From PUR_LaborOrderMiscDc_Hdr a
			Left Outer Join dbo.fn_Pur_LaborOrderMiscDc_Dtl(@SetDate, @CurrDate, @BranchID, @CompID, @Finyear) b
				On a.DocType = b.DocType and a.DocNo = b.DocNo and a.DocDate = b.DocDate
					and a.BranchID = b.BranchID and a.CompID = b.CompID and b.Finyear>=@TmpFinyear
			Where a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear>=@TmpFinyear
			Group by a.DocType, a.DocNo, a.DocDate, a.VendorCode, b.ItemCode, a.BranchID, a.CompID, b.Qty
			Having B.Qty > 0
		) a
		Left Outer Join ReceiptEntry b
			On a.DocType = b.RefType and a.DocNo = b.RefNo and a.DocDate = b.RefDate and a.ItemCode = b.ItemCode
				and b.BranchID = @BranchID and b.CompID = @CompID and b.Finyear>=@TmpFinyear
		Left Outer Join FAS_Party_Master c
			On a.VendorCode = c.PartyCode and a.BranchID = c.BranchID and a.CompID = c.CompID
		Left Outer Join MAterial_Master d
			On a.ItemCode = d.ItemCode and a.BranchID = d.BranchID and a.CompID = d.CompID
		Where a.DocType = @DocType and a.DocNo = @DocNo and a.DocDate = @DocDate 
			and a.BranchiD = @BranchID and a.CompID = @CompID
		Group by a.DocType, a.DocNo, a.DocDate, a.VendorCode, a.ItemCode, a.OrderQty,
			b.AcceptedQty, b.RejectionQty, c.PartyName, d.ItemDescription, d.PurchaseUOMDesc, d.PurchaseUOMDecimal, 
			d.HeatNoApplicable, d.ShelfLifePeriodApplicable
    ) x
    Group by ItemCode, ItemDescription, PurchaseUOMDesc, OrderQty, PUrchaseUOMDecimal, HeatNoApplicable, ShelfLifePeriodApplicable,
		DocType, DocNo, DocDate
    Having ((OrderQty) - Sum(AcceptedQty + RejectionQty)) > 0
END
GO

