CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_NCDCItem] (@DocType varchar(5), @DocNo int, @DocDate datetime, @CurrDate datetime,
	@AsOnDate Datetime, @RptDate Datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

	Select ItemCode, ItemDescription, PurchaseUOMDesc, PurchaseUOMDecimal, SendQty, ReceivedQty, ChallanQty, 
		RecptQty, (SendQty-(ReceivedQty+ChallanQty+RecptQty)) as BalQty, 
		ScheduleDate, NCDCType, NCDCNo, NCDCDate, ItemNature, HeatNoApplicable, ShelfLifePeriodApplicable 
	From (
		Select a.ItemCode, b.ItemDescription, b.PurchaseUOMDesc, b.PurchaseUOMDecimal, a.SendQty, a.ReceivedQty, 
			a.ScheduleDate, a.NCDCType, a.NCDCNo, a.NCDCDate, 
			isNull((Select sum(e.ChallanQty) From REC_ReceiptEntry_Dtl e 
					Where e.RefType = a.NCDCType And e.RefNo = a.NCDCNo And e.RefDate = a.NCDCDate 
						and e.ScheduleDate = a.ScheduleDate and e.ItemCode = a.ItemCode 
						and e.Branchid=@BranchID and e.Compid=@CompID and e.Finyear>=@TmpFinyear
						and ReceiptDate is Null and AcceptedDate is Null 
					group by RefType, RefNo, RefDate, ScheduleDate, ItemCode, BranchID, CompID),0) As ChallanQty, 
			isNull((Select sum(e.ReceiptQty) From REC_ReceiptEntry_Dtl e 
					Where e.RefType = a.NCDCType And e.RefNo = a.NCDCNo And e.RefDate = a.NCDCDate 
						and e.ScheduleDate = a.ScheduleDate and e.ItemCode = a.ItemCode 
						and e.Branchid=@BranchID and e.Compid=@CompID and e.Finyear>=@TmpFinyear
						and ReceiptDate is Not Null and AcceptedDate is Null 
					group by RefType, RefNo, RefDate, ScheduleDate, ItemCode, BranchID, CompID),0) As RecptQty, 
			b.ItemNature, b.HeatNoApplicable, b.ShelfLifePeriodApplicable 
		From INV_NCDC_DTL a 
		Left Outer Join MATERIAL_MASTER b
			On  a.ItemCode=b.ItemCode and a.Branchid=b.Branchid and a.Compid=b.Compid 
		Where a.NCDCType = @DocType and a.NCDCNo = @DocNo and a.NCDCDate = @DocDate and a.ScheduleDate <= @CurrDate 
			and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear>=@TmpFinyear
		) x 
		Where (SendQty - (ReceivedQty + ChallanQty + RecptQty)) > 0 
		Order by ItemCode
END
GO

