CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_PurchaseItem](@DocType varchar(5), @DocNo int, @DocDate datetime, @GateDate datetime, 
	@AsOnDate Datetime, @RptDate Datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
 SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

	--/* Get Previous Finyear */
	--Declare @PrevFinyear As varchar(20), @IsAllowedPrevFinyar As bit;
	--Select @PrevFinyear=dbo.fn_PreviousFinyearProcess_Get_BasedOnGivenFinyear(@Finyear), @IsAllowedPrevFinyar='0';

	Select x.ItemCode, x.ItemDescription, x.PurchaseUOMDesc, x.PurchaseUOMDecimal, x.ScheduleQty, 
		(x.AcceptedQty+x.RecptQty+x.ChallanQty), x.RequiredDate,  x.ScheduleType, x.ScheduleNo, x.ScheduleDate, 
		(x.ScheduleQty -(x.AcceptedQty+x.RecptQty+x.ChallanQty)) BalQty, x.HeatNoApplicable, 
		x.ShelfLifePeriodApplicable 
	From (
		select a.ItemCode,b.ItemDescription, b.PurchaseUOMDesc, b.PurchaseUOMDecimal, a.ScheduleQty, 
		sum(isNull(c.AcceptedQty,0)) as AcceptedQty, a.RequiredDate, a.ScheduleType,a.ScheduleNo,a.ScheduleDate, 
		isNull((select sum(e.ReceiptQty) from REC_ReceiptEntry_Dtl e 
				where  e.RefType = a.ScheduleType 
						and e.RefNo = a.ScheduleNo and e.RefDate = a.ScheduleDate and e.ScheduleDate = a.RequiredDate 
						and e.ItemCode = a.ItemCode and e.Branchid=@BranchID and e.Compid=@CompID and ReceiptDate is Not Null 
						and AcceptedDate is Null 
				group by RefType, RefNo, RefDate, ScheduleDate, ItemCode, BranchID, CompID),0) As RecptQty, 
		isNull((select sum(e.ChallanQty) from REC_ReceiptEntry_Dtl e 
				where  e.RefType = a.ScheduleType and e.RefNo = a.ScheduleNo and e.RefDate = a.ScheduleDate 
					and e.ScheduleDate = a.RequiredDate and e.ItemCode = a.ItemCode 
					and e.Branchid=@BranchID and e.Compid=@CompID and ReceiptDate is Null and AcceptedDate is Null 
				group by RefType, RefNo, RefDate, ScheduleDate, ItemCode, BranchID, CompID),0) ChallanQty, 
				b.HeatNoApplicable, b.ShelfLifePeriodApplicable 
		From dbo.fn_PUR_SCHEDULE(@AsOnDate, @GateDate, @BranchID, @CompID, @Finyear) a 
		Left Outer join PUR_SCHEDULE_RECEIVE_DTL c 
			On c.RequiredDate=a.RequiredDate and c.ItemCode=a.ItemCode  and c.ScheduleNo=a.ScheduleNo 
				and a.ScheduleDate=c.ScheduleDate and a.ScheduleType=c.ScheduleType and a.Branchid=c.Branchid 
				and a.Compid=c.Compid and a.Finyear=c.Finyear
		Left Outer Join MATERIAL_MASTER b 
			On a.ItemCode=b.ItemCode and a.Branchid=b.Branchid and a.Compid=b.Compid 
		Where a.ScheduleNo=@DocNo and a.ScheduleDate=@DocDate and a.ScheduleType=@DocType
			and a.RequiredDate<=Convert(datetime,Convert(varchar(10),@AsOnDate,121)) 
			and a.Status in ('N','E','M','A')
			and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear>=@TmpFinyear 
			--and ((@IsAllowedPrevFinyar='0' and a.Finyear=@Finyear) or (@IsAllowedPrevFinyar='1' and a.Finyear In(@PrevFinyear,@Finyear)))		
		Group by a.ItemCode, b.ItemDescription, b.PurchaseUOMDesc, b.PurchaseUOMDecimal, 
			a.ScheduleQty, a.RequiredDate, a.ScheduleType, a.ScheduleNo, a.ScheduleDate,  
			b.HeatNoApplicable, b.ShelfLifePeriodApplicable 
		) x 
	Where (x.ScheduleQty - (x.AcceptedQty+x.RecptQty+x.ChallanQty)) > 0 
	order by x.ItemCode, x.RequiredDate 
END
GO

