CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_PurchaseVendor](@GateDate Datetime, @AsOnDate Datetime, @RptDate Datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

	--/* Get Previous Finyear */
	--Declare @PrevFinyear As varchar(20), @IsAllowedPrevFinyar As bit;
	--Select @PrevFinyear=dbo.fn_PreviousFinyearProcess_Get_BasedOnGivenFinyear(@Finyear), @IsAllowedPrevFinyar='0';

	Select Distinct (Select b.PartyName From FAS_PARTY_MASTER b 
				Where b.PartyCode=x.VendorCode and b.Branchid=@BranchID and b.Compid=@CompID) As PartyName, 
		x.VendorCode, x.ScheduleType, x.ScheduleNo, x.ScheduleDate, x.OrderType, x.OrderNo, x.OrderDate 
	From  (
	Select a.VendorCode,  a.ScheduleType, a.ScheduleNo, a.ScheduleDate, a.ScheduleQty, 
		sum(isNull(c.AcceptedQty,0)) As AcceptedQty,  
		isNull((select sum(e.ReceiptQty) from REC_ReceiptEntry_Dtl e 
			where  e.RefType = a.ScheduleType and e.RefNo = a.ScheduleNo and e.RefDate = a.ScheduleDate 
				and e.ScheduleDate= a.RequiredDate and e.ItemCode = a.ItemCode and e.Branchid=@BranchID and e.Compid=@CompID 
				and ReceiptDate is not null and AcceptedDate is Null),0) As RecptQty, 
	isNull((Select sum(e.ChallanQty) From REC_ReceiptEntry_Dtl e 
			Where e.RefType = a.ScheduleType and e.RefNo = a.ScheduleNo and e.RefDate = a.ScheduleDate and e.ItemCode = a.ItemCode 
				and e.ScheduleDate= a.RequiredDate and e.Branchid=@BranchID and e.Compid=@CompID 
				and ReceiptDate is null and AcceptedDate is Null),0) As ChallanQty, 
			a.OrderType,a.OrderNo, a.OrderDate 
	From dbo.fn_PUR_SCHEDULE(@AsOnDate, @GateDate, @BranchID, @CompID, @Finyear) a 
	Left Outer join PUR_SCHEDULE_RECEIVE_DTL c 
	On c.RequiredDate=a.RequiredDate and c.ItemCode=a.ItemCode  
		and a.ScheduleNo=c.ScheduleNo and a.ScheduleDate=c.ScheduleDate and a.ScheduleType=c.ScheduleType 
		and a.Branchid=c.Branchid and a.Compid=c.Compid and a.Finyear=c.Finyear
	where a.RequiredDate<=Convert(datetime,Convert(varchar(10),@AsOnDate,121))
		and a.Status in ('N', 'E', 'M','A') 
		and a.Branchid = @BranchID and a.Compid = @CompID and a.Finyear>=@TmpFinyear 
		--and ((@IsAllowedPrevFinyar='0' and a.Finyear=@Finyear) or (@IsAllowedPrevFinyar='1' and a.Finyear In(@PrevFinyear,@Finyear)))
	Group by a.VendorCode, a.ScheduleType, a.ScheduleNo, a.ScheduleDate, a.RequiredDate, a.ItemCode, 
		a.ScheduleQty, a.OrderType, a.OrderNo, a.OrderDate) x  
	Where (x.ScheduleQty - (x.AcceptedQty+x.RecptQty+x.ChallanQty)) > 0  and x.ScheduleDate>='2019-04-01' 
	order by PartyName
END
GO

