CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_ReWorkDCItem] (@DocType varchar(5), @DocNo int, @DocDate datetime, 
    @AsOnDate Datetime, @RptDate Datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

     Select a.ItemCode,c.ItemDescription,c.PurchaseUOMDesc as UOM,c.PurchaseUOMDecimal as UOMDecimal, 
        a.Qty as DcQty,(a.Qty-isnull(b.AccQty+b.RejQty+b.ScrapQty,0)) as PendingQty,
        a.ScheduleDate,a.DocType,a.DocNo,a.DocDate,a.ItemGroupKey, c.HeatNoApplicable, c.ShelfLifePeriodApplicable 
     From PUR_ReworkDc_Dtl a 
     Left Outer Join Receive_ReWorkDc b 
        on a.DocType=b.RefType and a.DocNo=b.RefNo and a.DocDate=b.RefDate and a.ScheduleDate=b.ScheduleDate 
            and a.ItemCode=b.ItemCode and a.Branchid=b.BRanchid and a.Compid=b.Compid and b.Finyear>=@TmpFinyear
    Left outer join Material_MAster c 
        on a.ItemCode=c.ItemCode and a.Branchid=c.Branchid and a.Compid=c.Compid
    Where a.Qty > isnull(b.AccQty + b.RejQty + b.ScrapQty, 0) and a.DocType=@DocType and a.DocNo=@DocNo 
        and a.DocDate=@DocDate and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear>=@TmpFinyear
END
GO

