CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_ReWorkDCVendor] (@AsOnDate datetime, 
	@RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

    Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

      Select Distinct x.VendorCode,(Select PartyName From FAS_Party_Master 
                                    Where PartyCode=x.VendorCode and Branchid=x.Branchid and Compid=x.Compid) As VendorName,
            x.DocType,x.DocNo, x.DocDate, x.OrderType, x.OrderNo, x.OrderDate 
      from ReworkDc x Inner Join (
                    Select a.DocType,a.DocNo,a.DocDate,a.ItemCode,a.Qty as DcQty,a.ScheduleDate, 
                                        isnull(B.AccQty + B.RejQty + B.ScrapQty, 0) As CompleteQty 
                    From PUR_ReworkDc_Dtl a 
                    Left Outer Join Receive_ReWorkDc b 
                        on a.DocType=b.RefType and a.DocNo=b.RefNo and a.DocDate=b.RefDate 
                            and a.ScheduleDate=b.ScheduleDate and a.ItemCode=b.ItemCode 
                            and a.Branchid=b.BRanchid and a.Compid=b.Compid 
                    Where a.Qty>isnull(b.AccQty+b.RejQty+b.ScrapQty,0)
                        and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear>=@TmpFinyear
                ) z 
       on x.DocType=z.DocType and x.DocNo=z.DocNo and x.DocDate=z.DocDate 
       Where x.Branchid=@BranchID and x.Compid=@CompID and x.Finyear>=@TmpFinyear
END
