CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_SubContractItem] (@DocType varchar(5), @DocNo int, @DocDate datetime, @SetDate Datetime, 
	@CurrDate datetime, @AsOnDate Datetime, @RptDate Datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

	--/* Get Previous Finyear */
	--Declare @PrevFinyear As varchar(20), @IsAllowedPrevFinyar As bit;
	--Select @PrevFinyear=dbo.fn_PreviousFinyearProcess_Get_BasedOnGivenFinyear(@Finyear), @IsAllowedPrevFinyar='0';

	Select RecdItemCode, ItemDescription, PurchaseUOMDesc, PurchaseUOMDecimal, ScheduleQty, (ActualPendingQty-(ChallanQty+RecptQty))PendingQty, 
		SchDate, DCSRType, DCSRNo, DCSRDate, x.ItemGroupKey, K.DrawingNo, k.RevisionNo, '' as HeatNo, x.HeatNoApplicable, 
		x.ShelfLifePeriodApplicable 
	From (
		Select m.DCSRType, m.DCSRNo, m.DCSRDate, m.ItemGroupKey, m.RecdItemCode, f.ItemDescription, f.PurchaseUOMDesc, f.PurchaseUOMDecimal, 
			m.ScheduleQty, m.ActualPendingQty, m.SchDate, isnull(sum(AcceptedQty), 0) As AcceptedQty, 
			isNull(Sum(Case When e.ReceiptDate is Null and e.AcceptedDate is Null then e.ChallanQty else 0 End), 0) as ChallanQty, 
			isNull(Sum(Case When e.ReceiptDate is Not Null and e.AcceptedDate is Null then e.ReceiptQty else 0 End), 0) as RecptQty, 
			m.RequiredDate, m.Branchid, m.Compid, f.HeatNoApplicable, f.ShelfLifePeriodApplicable 
		From (
			Select distinct d.DCSRType, d.DCSRNo, d.DCSRDate, a.ItemGroupKey, d.RecdItemCode, d.ScheduleQty, 
				a.ScheduleQty as ActualPendingQty, a.SchDate, d.RequiredDate, d.BranchID, d.CompID 
			From (
				Select DCSRType, DCSRNo, DCSRDate, ItemGroupKey, SchDate, BranchID, CompID, Min(Qty) as ScheduleQty 
				From (
					Select  DCSRType, DCSRNo, DCSRDate, ItemGroupKey, SchDate, BranchID, CompID, SentItemCode, 
						Sum(Qty/Norms) as Qty 
					From PUR_DCSR_Tran 
					Where Status <> 'C' and SchDate<=@CurrDate and BranchID=@BranchID and CompID=@CompID
						and Finyear>=@TmpFinyear
						--and ((@IsAllowedPrevFinyar='0' and Finyear=@Finyear) or (@IsAllowedPrevFinyar='1' and Finyear In(@PrevFinyear,@Finyear)))
					Group by DCSRType, DCSRNo, DCSRDate, ItemGroupKey, SchDate, BranchID, CompID, SentItemCode
					) x1 
				Group by DCSRType, DCSRNo, DCSRDate, ItemGroupKey, SchDate, BranchID, CompID
				Having Min(Qty) > 0
				) a  
			Left Outer Join dbo.fn_PUR_DCSR_Schedule_Doc(@DocType, @DocNo, @DocDate, @SetDate, @CurrDate, @BranchID, @CompID, @Finyear) d 
				On d.DCSRNo=a.DCSRNo and d.DCSRDate=a.DCSRDate and d.DCSRType=a.DCSRType and d.RequiredDate=a.SchDate 
					and d.ItemGroupKey=a.ItemGroupKey and d.BranchID=a.BranchID and d.CompID=a.CompID 
					and d.Finyear>=@TmpFinyear
						--and ((@IsAllowedPrevFinyar='0' and Finyear=@Finyear) or (@IsAllowedPrevFinyar='1' and Finyear In(@PrevFinyear,@Finyear)))
			Where d.DCSRType = @DocType and d.DCSRNo = @DocNo and d.DCSRDate = @DocDate and d.Requireddate <= @CurrDate 
			) m 
		Left Outer Join REC_ReceiptEntry_dtl e 
			On e.RefType = m.DCSRType and e.RefNo = m.DCSRNo and e.RefDate = m.DCSRDate and e.ItemGroupKey = m.ItemGroupKey 
				and e.BranchID=m.BranchID and e.CompID=m.CompID 
				and e.Finyear>=@TmpFinyear
						--and ((@IsAllowedPrevFinyar='0' and Finyear=@Finyear) or (@IsAllowedPrevFinyar='1' and Finyear In(@PrevFinyear,@Finyear)))
		Left outer join Material_Master f 
			On m.RecdItemCode = f.ItemCode and m.Branchid = f.Branchid and m.Compid = f.Compid 
		Group by m.DCSRType, m.DCSRNo, m.DCSRDate, m.ItemGroupKey, m.RecdItemCode, f.ItemDescription, f.PurchaseUOMDesc, 
			f.PurchaseUOMDecimal, m.SchDate, m.ScheduleQty, m.ActualPendingQty, m.RequiredDate, m.Branchid, m.Compid, 
			f.HeatNoApplicable, f.ShelfLifePeriodApplicable 
		) x  
		Left Outer Join (
			Select * From BOM_DrawingTran_Dtl 
			Where RefType = @DocType and RefNo = @DocNo and RefDate = @DocDate and BranchID = @BranchID and CompID = @CompID
		) k 
			On x.RecdItemCode = k.ItemCode and x.ItemGroupkey = k.ItemGroupkey 
		Where (x.ScheduleQty-(x.ChallanQty+x.RecptQty))>0
END
GO

