CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_SubContractPartialItem] (@DocType varchar(5), @DocNo int, @DocDate datetime, @SetDate Datetime, 
	@GateDate Datetime, @CurrDate datetime, @AsOnDate Datetime, @RptDate Datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

	Select Distinct x.RecdItemCode, x.FromSeq, x.ToSeq, y.ItemDescription, y.PurchaseUOMDesc, 
		y.PurchaseUOMDecimal, x.TobeRecdQty, min(round(x.BalQty/x.Norms, 0)) As BalTobeRecd, 
		x.RequiredDate, x.DCSRType, x.DCSRNo, x.DCSRDate,ItemGroupKey,  
		isnull((Select dbo.fn_COM_Get_HeatNo(x.DCSRType, x.DCSRNo, x.DCSRDate, @BranchID, @CompID, @Finyear)),'') as HeatNo, 
		IsNull(y.HeatNoApplicable,'0') As HeatNoApplicable, IsNull(y.ShelfLifePeriodApplicable,'0') As ShelfLifePeriodApplicable, 
		IsNull(y.SelfLifePeriod,0) As SelfLifeDays 
	From (
		select a.DCSRType, a.DCSRNo, a.DCSRDate, a.SentItemCode,
			(select m.OperationSequence from MPSMaster m 
			where m.Stagecode=a.SentItemCode and m.Branchid=a.Branchid and m.compid=a.Compid) As FromSeq,
			a.Norms, Sum(a.ScheduleQty) As BalQty, b.RecdItemCode, b.ItemGroupKey, 
			(Select m.OperationSequence From MPSMaster m 
			where m.Stagecode=b.RecdItemCode and m.Branchid=a.Branchid and m.compid=a.Compid) As ToSeq, 
			b.ScheduleQty as TobeRecdQty, b.RequiredDate 
		From dbo.fn_PUR_DCSR_Tran(@SetDate, @CurrDate, @BranchID, @CompID, @Finyear) a  
		Left Outer Join dbo.fn_PUR_DCSR_SCHEDULE(@AsOnDate, @GateDate, @BranchID, @CompID, @Finyear) b  
			On a.DCSRType=b.DCSRType and a.DCSRNo=b.DCSRNo and a.DCSRDate=b.DCSRDate and a.ItemGroupKey=b.ItemGroupKey 
				and a.Branchid=b.Branchid and a.Compid=b.Compid and a.Finyear=b.Finyear
		Where a.Mode <> 'SC' and b.DCSRType=@DocType and b.DCSRNo=@DocNo and b.DCSRDate=@DocDate 
			and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear>=@TmpFinyear
		group by a.DCSRType, a.DCSRNo, a.DCSRDate, a.SentItemCode, a.Norms, b.ItemGroupkey, 
			b.RecdItemCode, b.ScheduleQty, b.RequiredDate, a.Branchid, a.Compid 
	) x 
	Left Outer Join MATERIAL_MASTER y 
		On x.RecdItemCode=y.ItemCode and y.Branchid=@BranchID and y.Compid=@CompID 
	Where ToBeRecdQty > 0 and (ToSeq-FromSeq) > 1 
	group by x.RecdItemCode, x.FromSeq, x.ToSeq, y.ItemDescription, y.PurchaseUOMDesc, 
		y.PurchaseUOMDecimal, x.TobeRecdQty, x.RequiredDate, x.DCSRType, x.DCSRNo, x.DCSRDate, ItemGroupKey,  		
		y.HeatNoApplicable,y.ShelfLifePeriodApplicable, y.SelfLifePeriod	
	having min(round(x.BalQty/x.Norms,0))>0

END
GO

