CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_SubContractPartialOperation] (@DocType varchar(5), @DocNo int, @DocDate datetime, @ItemCode varchar(30),
	@FromSeq int, @ToSeq int, @ItemGroupkey int, @HeatNo varchar(50), @HeatNoApplicable varchar(10), @ShelfLifePeriodApplicable varchar(10),
	@SelfLifeDays int, @TobeRecdQty float, @BalToBeRecd float, @UOM varchar(10), @UOMDecimal int, @RequiredDate datetime, 
	@AsOnDate Datetime, @RptDate Datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))	
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

	Select Distinct a.StageCode As OperationCode, a.OperationName, @TobeRecdQty As TobeRecdQty, 
		@BalToBeRecd As BalToBeRecd, @UOM As UOM, @UOMDecimal As UOMDecimal,
		@RequiredDate As RequiredDate, @DocType As RefType, @DocNo As RefNo,
		@DocDate As RefDate, a.ItemCode, @ItemGroupkey As ItemGroupkey, @HeatNo As HeatNo, 
		@HeatNoApplicable as HeatNoApplicable, @ShelfLifePeriodApplicable As ShelfLifePeriodApplicable, 
		@SelfLifeDays As SelfLifeDays 
	From MPSMaster a 
	Where ItemCode=(select m1.ItemCode from MPSMaster m1 where m1.StageCode = @ItemCode)
		and a.OperationSequence > @FromSeq and a.OperationSequence < @ToSeq
END
GO

