SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_SubContractPartialVendor] (@CurrDate datetime, @AsOnDate Datetime, 
	@RptDate Datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

	Select distinct (Select e.PartyName From FAS_PARTY_MASTER e 
					Where e.PartyCode=x.VendorCode  and e.Branchid=@BranchID and e.Compid=@CompID) As PartyName, 
		x.VendorCode, x.DCSRType, x.DCSRNo, x.DCSRDate  
	From (
		select a.DCSRType, a.DCSRNo, a.DCSRDate, d.VendorCode, a.SentItemCode,
				(Select top 1 c.OperationSequence from MPSMaster c 
				where c.StageCode = a.SentItemCode and c.Branchid = @BranchID and c.Compid = @CompID) SentSeqNo,  
				sum(a.ScheduleQty) BalQty, a.Norms, b.RecdItemCode, 
				(select top 1 f.OperationSequence from MPSMaster f  
				Where f.StageCode = b.RecdItemCode and f.Branchid = @BranchID and f.Compid = @CompID) RecdSeqNo, 
				b.ScheduleQty as  TobeRecdQty,  b.RequiredDate 
			From dbo.fn_PUR_DCSR_Tran(@AsOnDate, @CurrDate, @BranchID, @CompID, @Finyear) a  
			Left Outer Join dbo.fn_PUR_DCSR_SCHEDULE(@AsOnDate, @CurrDate, @BranchID, @CompID, @Finyear) b  
			On a.DCSRType=b.DCSRType and a.DCSRNo=b.DCSRNo and a.DCSRDate=b.DCSRDate and a.ItemGroupKey=b.ItemGroupKey 
				and a.Branchid=b.Branchid and a.Compid=b.Compid and a.Finyear=b.Finyear 
			Left Outer Join PUR_DCSR_HDR d 
			On d.DCSRType=a.DCSRType and d.DCSRNo=a.DCSRNo  and d.DCSRDate=a.DCSRDate 
				and d.Branchid=a.Branchid and d.Compid=a.Compid and d.Finyear=a.Finyear 
		Where a.Mode <> 'SC' and a.Branchid=@BranchID and a.Compid=@CompID and a.Finyear>=@TmpFinyear
		group by a.DCSRType, a.DCSRNo, a.DCSRDate, d.VendorCode, a.SentItemCode, a.Norms, b.RecdItemCode, b.ScheduleQty, b.RequiredDate 
	) x
	Where ToBeRecdQty > 0 and (x.RecdSeqNo - x.SentSeqNo) > 1 
	group by x.DCSRType,  x.DCSRNo, x.DCSRDate, x.VendorCode, x.RecdItemCode, x.TobeRecdQty, x.RequiredDate 
	Having min(round(x.BalQty/x.Norms,0))>0
END
GO

