CREATE PROCEDURE [dbo].[REC_GateEntry_Hlp_SubContractVendor] (@SetDate datetime, @CurrDate Datetime, @AsOnDate Datetime, @RptDate Datetime, 
	@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))          
AS      
BEGIN  
	SET NOCOUNT ON;

	Declare @TmpFinyear As varchar(20);
	SET @TmpFinyear='04-2025 03-2026';

	--/* Get Previous Finyear */
	--Declare @PrevFinyear As varchar(20), @IsAllowedPrevFinyar As bit;
	--Select @PrevFinyear=dbo.fn_PreviousFinyearProcess_Get_BasedOnGivenFinyear(@Finyear), @IsAllowedPrevFinyar='0';

	Select distinct PartyName, VendorCode, DCSRType, DCSRNo, DCSRDate, OrderType, OrderNo, OrderDate 
	From (
		Select Distinct PartyName, x.VendorCode, DCSRType, DCSRNo, DCSRDate, OrderType, OrderNo, OrderDate, 
			(ActualPendingQty-(ChallanQty+RecptQty)) as PendingQty 
		From (
			Select a.DCSRType, a.DCSRNo, a.DCSRDate, d.ScheduleQty, a.ScheduleQty as ActualPendingQty,  
				a.SchDate, b.OrderType, b.OrderNo, b.OrderDate, sum(isNull(e.AcceptedQty,0)) as AcceptedQty, 
				isNull(Sum(Case When e.ReceiptDate is Null and e.AcceptedDate is Null then e.ChallanQty else 0 End), 0) as ChallanQty, 
				isNull(Sum(Case When e.ReceiptDate is Not Null and e.AcceptedDate is Null then e.ReceiptQty else 0 End), 0) as RecptQty, 
				b.VendorCode, a.Branchid, a.Compid 
			From (
				Select DCSRType, DCSRNo, DCSRDate, ItemGroupKey, SchDate, BranchID, CompID, Min(Qty) as ScheduleQty 
				From (
					Select  DCSRType, DCSRNo, DCSRDate, ItemGroupKey, SchDate, BranchID, CompID, SentItemCode, Sum(Qty/Norms) as Qty 
					From PUR_DCSR_Tran 
					Where Status <> 'C' and SchDate<=@CurrDate and BranchID=@BranchID and CompID=@CompID 
						and Finyear>=@TmpFinyear
						--and ((@IsAllowedPrevFinyar='0' and Finyear=@Finyear) or (@IsAllowedPrevFinyar='1' and Finyear In(@PrevFinyear,@Finyear)))
					Group by DCSRType, DCSRNo, DCSRDate, ItemGroupKey, SchDate, BranchID, CompID, SentItemCode
					) x1 
				Group by DCSRType, DCSRNo, DCSRDate, ItemGroupKey, SchDate, BranchID, CompID Having Min(Qty) > 0
				) a  
				Left Outer Join dbo.fn_PUR_DCSR_Schedule(@SetDate, @CurrDate, @BranchID, @CompID, @Finyear) d 
					On d.DCSRNo=a.DCSRNo and d.DCSRDate=a.DCSRDate and d.DCSRType=a.DCSRType and d.RequiredDate=a.SchDate 
						and d.ItemGroupKey=a.ItemGroupKey and d.BranchID=a.BranchID and d.CompID=a.CompID 
						and d.Finyear>=@TmpFinyear
						--and ((@IsAllowedPrevFinyar='0' and d.Finyear=@Finyear) or (@IsAllowedPrevFinyar='1' and d.Finyear In(@PrevFinyear,@Finyear)))
				Left Outer Join PUR_DCSR_Hdr b 
					On a.DcsrNo=b.DcsrNo and a.DcsrDate=b.DcsrDate and a.DcsrType=b.DcsrType
					and a.Branchid=b.Branchid and a.Compid=b.Compid and b.Finyear>=@TmpFinyear
					--and ((@IsAllowedPrevFinyar='0' and b.Finyear=@Finyear) or (@IsAllowedPrevFinyar='1' and b.Finyear In(@PrevFinyear,@Finyear)))
				Left Outer Join REC_ReceiptEntry_dtl e 
					On e.RefNo = a.DCSRNo and e.RefDate = a.DCSRDate and e.ItemGroupKey = a.ItemGroupKey and e.RefType = a.DCSRType
						and e.BranchID=a.BranchID and e.CompID=a.CompID and e.Finyear>=@TmpFinyear
						--and ((@IsAllowedPrevFinyar='0' and e.Finyear=@Finyear) or (@IsAllowedPrevFinyar='1' and e.Finyear In(@PrevFinyear,@Finyear)))
				Group by a.DCSRType, a.DCSRNo, a.DCSRDate, a.SchDate, a.ItemGroupKey, b.OrderType, b.OrderNo, 
					b.OrderDate, d.ScheduleQty, a.ScheduleQty, b.VendorCode, a.Branchid, a.Compid
			) x 
			Left Outer Join FAS_Party_Master y 
				On y.PartyCode = x.VendorCode and y.Branchid = x.Branchid and y.Compid = x.Compid 
			Where (ActualPendingQty - (ChallanQty + RecptQty)) > 0 
	) z 
	where DCSRDate>='2009-04-01' 
	Order by PartyName, VendorCode, DCSRType, DCSRNo, DCSRDate, OrderType, OrderNo, OrderDate
END
GO

