CREATE PROCEDURE [dbo].[REC_INS_RECEIPTENTRY_DTL_TRACE]                            
 (@ReceiptEntryType  [varchar](3),              
  @ReceiptEntryNo  [int],              
  @ReceiptEntryDate  [datetime],              
  @ItemCode   [varchar](20),          
  @SubLotId [int],          
  @HeatNo  [varchar](20),             --[varchar](20) Instead Of [varchar](50) 
  @ManufactureDate  [datetime], 
	@ShelfLifeDays  [int],             
  @Qty  [float],                
 -- @AcceptedQty [float],    
