CREATE PROCEDURE [dbo].[REC_ReceiptEntry_Trace_Tmp_Sel_Ins](@UserKey varchar(42), @DocType Varchar(3), @DocNo int, @DocDate Datetime, 
                                                    @ItemCode varchar(20), @ItemSeq int, @SchDate Datetime, 
                                                    @RefType varchar(3), @RefNo int, @RefDate Datetime, @AsOnDate datetime,
                                                    @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))                                  
As                                  
BEGIN                                       
 SET NOCOUNT ON;              
            
    Insert into REC_ReceiptEntry_Trace_Tmp
        Select @UserKey as UserKey, a.ReceiptEntryType, a.ReceiptEntryNo, a.ReceiptEntryDate, a.ItemCode, 
            @SchDate as SchDate, @RefType as RefType, @RefNo as RefNo, @RefDate as RefDate, IsNull(a.HeatNo,'') As HeatNo,    
            a.ManufactureDate, IsNull(a.ShelfLifeDays,0) As ShelfLifeDays, IsNull(a.Qty,0) As Qty,   
            IsNull(a.AcceptedQty,0) As AcceptedQty, IsNull(a.RejectedQty,0) As RejectedQty,   
            IsNull(a.ScrapQty,0) As ScrapQty, a.Seq, a.ItemSeq,  a.SublotID, a.BranchID, a.CompID, @AsOnDate as TranStamp             
        From REC_ReceiptEntry_Dtl_Trace a        
        Where a.ReceiptEntryType=@DocType and a.ReceiptEntryNo=@DocNo and a.ReceiptEntryDate=@DocDate           
        and a.ItemCode=@ItemCode and (@ItemSeq=0 or a.ItemSeq=@ItemSeq) and a.BranchID=@BranchID and a.CompID=@CompID      
        and a.Finyear=@Finyear            
END  
GO

/****** Object:  StoredProcedure [dbo].[REC_TraceabilityData_Fil]    Script Date: 17/06/2026 11:30:56 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO


  
CREATE PROCEDURE [dbo].[REC_TraceabilityData_Fil](@DocType Varchar(3), @DocNo int, @DocDate Datetime, @ItemCode varchar(20), @ItemGroupKey int, @BranchID varchar(3), @CompID varchar(3), @Finyear Varchar(20))              
As           
                                  
BEGIN           
                                  
 SET NOCOUNT ON;                        
 Declare @sItemCode varchar(20)        
        
 IF @DocType='DCR'        
  BEGIN        
   Select @sItemCode=SentItemCode From PUR_DCSR_Tran        
   Where DCSRType=@DocType and DCSRNo=@DocNo and DCSRDate=@DocDate and ItemGroupKey=@ItemGroupKey        
    and BranchId=@BranchID and CompID=@CompID and Finyear=@Finyear        
  END        
 ELSE        
  SET @sItemCode=@ItemCode        
                     
 Select a.ItemCode, a.LotID, a.SubLotID, IsNull(a.HeatNo,'') As HeatNo, a.ManufactureDate, IsNull(a.ShelfLifeDays,0) As ShelfLifeDays, Qty            
 From dbo.[fn_COM_Get_MultiHeatNo_Qty](@DocType, @DocNo, @DocDate, @BranchID, @CompID, @Finyear) a              
 Where a.ItemCode=@sItemCode          
 Order by a.LotID, a.SubLotID           
                              
END   
  
GO

