As           
                                  
BEGIN           
                                  
 SET NOCOUNT ON;       
 /* Inward Type only Purchase, Cash Purchase & Customer Supplied RawMaterial */               
                     
 Select a.ItemCode, a.LotID, a.SubLotID, IsNull(a.HeatNo,'') As HeatNo, a.ManufactureDate, IsNull(a.ShelfLifeDays,0) As ShelfLifeDays, Qty            
 From dbo.[fn_COM_Get_MultiHeatNo_ReceiptEntry](@DocType, @DocNo, @DocDate, @BranchID, @CompID, @Finyear) a              
 Where a.ItemCode=@ItemCode          
 Order by a.LotID, a.SubLotID           
                              
