/****** Object:  StoredProcedure [dbo].[Rec_UP_UpdateWtAvgRate]    Script Date: 17/06/2026 11:30:57 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Rec_UP_UpdateWtAvgRate] (@AsOnDate datetime,  @FinStart datetime, @BranchID varchar(3),  @CompID varchar(3),  @Finyear varchar(15))  

 AS  

	BEGIN 
		
		Declare @ParentCode varchar(20)
		Declare @ItemCode varchar(20)
		Declare @ItemNature varchar(3)
		Declare @Rate float
		Declare @RptDate datetime
		Declare @Skip bit		

		Declare @UpdateCnt int

		
		Begin Transaction

		Select @RptDate = Convert(datetime, Convert(Varchar(10), @AsOnDate, 111), 111)

		Declare curParent Cursor for	

			Select distinct a.itemcode, b.ItemNature from dbo.fn_Pur_PurchaseOrder_Dtl (@AsOnDate ,  @RptDate ,  @BranchID ,  @CompID , @Finyear ) a
			Left Outer Join Inv_Material_Master b
			On b.ItemCode = a.ItemCode and b.BranchID = a.BranchID and b.CompID = a.CompID
			Where b.BranchID = @BranchID and b.CompID = @BranchID
		
		Open curParent		

		FETCH NEXT FROM curParent into @ParentCode, @ItemNature 		

		Select @UpdateCnt = 0

		While @@Fetch_Status = 0 and @@Error = 0

			Begin 				
				
					If (@ItemNature = 'R' or @ItemNature = 'C' or @ItemNature = 'F')	
						Begin
							Declare curItem Cursor For	
						   		Select ItemCode, isNull(Rate,0) Rate From fn_BOM_ProductImplosion
		  							 (@ParentCode,  '',  @FinStart,  @RptDate,  @BranchID,  @CompID,  @Finyear) 

							Select @Skip = Convert(bit, '0')
						End
					Else
						Begin
							If Not (@ItemNature = 'CC' or @ItemNature = 'CF' or @ItemNature = 'CR')
								Begin
									Declare curItem Cursor For								
										Select @ParentCode, dbo.fn_WtAvgRate (@ParentCode, @FinStart, @RptDate, @BranchID, @CompID, @Finyear) CurRate  

									Select @Skip = Convert(bit, '0')
								End
							Else
								Select @Skip = Convert(bit, '1')

						End
			 
					If @Skip = Convert(bit, '0')
						Begin
							Open curItem		
					
							FETCH NEXT FROM curItem into @ItemCode, @Rate 		
					
							While @@Fetch_Status = 0 and @@Error = 0
			
								Begin
									If @Rate > 0
										Update Inv_Material_Master Set Rate = @Rate
										Where ItemCode = @ItemCode and BranchID = @BranchID and CompID = @CompID	
									
									Select @UpdateCnt = @UpdateCnt + 1
		
									FETCH NEXT FROM curItem into @ItemCode, @Rate
								End
								
							Close curItem
							Deallocate curItem
						End

				FETCH NEXT FROM curParent into @ParentCode, @ItemNature 

			End

			Close curParent
			Deallocate curParent


			Print @UpdateCnt

			If @@Error = 0
				Commit Transaction			 
			else
				Rollback Transaction

	END
GO

/****** Object:  StoredProcedure [dbo].[RESX_FileRepository_Dtl_Ins]    Script Date: 17/06/2026 11:30:57 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[RESX_FileRepository_Dtl_Ins]      
(    
  @DocType   [varchar](3),    /* DocType - Zero + StdID */  
  @DocNo    [int],        /* DocNo */  
  @DocDate   [datetime],     /* DocDate */  
  @ItemCode  [varchar](30),   /* StdID */   
  @AssetCode  [varchar](10),   /* Empty - Reserved For DocFileID */  
	@FileTypeFlag  [varchar](15)='',			/* QMSSTDDOCUMENT */
  @FileID   [int],         /* FileID - DB Resx Repository Table */  
	@DeletedFileName varchar(50)='',	 
	@DocNote varchar(100)='',
  @EffStatus   [int]=1,    
  @UserID    [varchar](10),    
  @BranchID   [varchar](3),    
  @CompID    [varchar](3),    
  @Transtamp   [datetime],  
  @Finyear    [varchar](20),   /* Finyear */  
  @FromDate    [datetime],    /* AuditDate */  
  @SymRef    [int],       /* SymRef   --> 2,3 & 6  ((NoNeed) 7 ERPRef) */  
  @NodeIdx    [int]       /* NodeIndex @ SeqNo */  
)          
AS           
BEGIN      
 SET  NOCOUNT ON;
   
	If @FileTypeFlag='QMSSTDDOCUMENT'
	 Begin
	 /* Note: @StdID -> Treat As DocType  
						@SymRef -> 2 Question / 3 Evidence / 6 Document / (No Need) 7 ERPRef  
						@Status -> 0 Active / @Status -> 0 In-Active / @Status -> 2 Delete
	 */  
		If @EffStatus=2							/* Delete */
		 Begin
			SET @AssetCode=Convert(varchar(10),@NodeIdx); 

			/* Delte Data From Table */  
			Delete From RESX_FileRepository_vw 
			Where (@FileID>0 and FileID=@FileID) and CompID=@CompID and BranchID=@BranchID 
		 End
		Else							/* Active / In-Active */
		 Begin
			Declare @StdID As int;  
			Declare @Tmp_DocFileID As int;  
			Declare @Tmp_FileID As int;   
  
			SET @StdID=Convert(int,@ItemCode);  
			SET @Tmp_DocFileID=0;  
			SET @Tmp_FileID=0;  
  
			If (@EffStatus Is Null)  
			 Begin  
				SET @EffStatus=1;  
			 End  		 

			If (@NodeIdx>0 and @SymRef>0 And (@SymRef=2 or @SymRef=3 or @SymRef=6 or @SymRef=7))  
			 Begin  
				 Select @Tmp_FileID=(Case When a.SymRef>0 And (a.SymRef=2 or a.SymRef=3 or a.SymRef=6) Then b.FileID Else 0 End),  
					@Tmp_DocFileID=(Case When a.SymRef>0 And (a.SymRef=2 or a.SymRef=3 or a.SymRef=6) Then a.DocFileID Else 0 End)  
				 From QMS_V1_StandardDocument_Dtl a  
				 Inner Join dbo.fn_QMS_V1_RESX_FileRepository_Dtl(@Transtamp, @Transtamp, @BranchID, @CompID, @Finyear) b  
					On Convert(varchar(30),a.StdID)=IsNull(b.ItemCode,'') and a.DocNo=b.DocNo and a.DocDate=b.DocDate 						    
						and Convert(varchar(10),a.DocFileID)=IsNull(b.AssetCode,'') and a.FromDate=@FromDate 
						and a.BranchID=b.BranchID and a.CompID=b.CompID  
				 Where a.StdID=@StdID and a.DocNo=@DocNo and a.DocDate=@DocDate and a.SeqNo=@NodeIdx   
					 and a.BranchID=@BranchID and a.CompID=@CompID  --and a.Finyear=@Finyear  
  
				 SET @Tmp_DocFileID=IsNull(@Tmp_DocFileID,0);    
			 End  
      
			If @Tmp_DocFileID>0   
			 Begin   
				SET @AssetCode=Convert(varchar(10),@Tmp_DocFileID);  
			 End  
			Else  
			 Begin  
				SET @AssetCode=Convert(varchar(10),@NodeIdx);  
  
				/* Update Data Into Table */  
				Update QMS_V1_StandardDocument_Dtl_Rep SET DocFileID=@NodeIdx  
				Where StdID=@StdID and DocNo=@DocNo and DocDate=@DocDate and SeqNo=@NodeIdx   
						and BranchID=@BranchID and CompID=@CompID  --and Finyear=@Finyear  
			 End  
		 End
	 End

	INSERT INTO RESX_FileRepository_Dtl  
  (    
		[DocType],    
		[DocNo],    
		[DocDate],    
		[ItemCode],    
		[AssetCode],    
		[FileTypeFlag],
		[FileID],   
		[DeletedFileName],
		[DocNote],
		[EffStatus],  
		[UserID],      
		[BranchID],      
		[CompID],      
		[TranStamp]    
	)              
  VALUES       
  (    
		@DocType,    
		@DocNo,    
		@DocDate,    
		@ItemCode,    
		@AssetCode,  
		@FileTypeFlag,
		@FileID,   
		@DeletedFileName,
		@DocNote, 
		@EffStatus,  
		@UserID,    
		@BranchID,    
		@CompID, 
		@Transtamp    
 )             
END    
GO

