/****** Object:  Stored Procedure dbo.SAL_Ageing_Creditors    Script Date: 15/04/2010 4:00:37 PM ******/

CREATE PROCEDURE [dbo].[SAL_Ageing_Creditors](@RptDate datetime, @PrStart datetime, @PrEnd datetime, @CmCode varchar(12))
  
 As

 SET NOCOUNT ON

 Begin	
	Select LrCode, Particulars,
		abs(Less30) as Amount0to30, case when Less30<0 then 'Cr' when Less30>0 then 'Dr' else '' end Type0,
		abs(Amount31to60) as Amount31to60, case when Amount31to60<0 then 'Cr' when Amount31to60>0 then 'Dr' else '' end Type1,
		abs(Amount61to90) as Amount61to90, case when Amount61to90<0 then 'Cr' when Amount61to90>0 then 'Dr' else '' end Type2,
		abs(Amount91to180) as Amount91to180, case when Amount91to180<0 then 'Cr' when Amount91to180>0 then 'Dr' else '' end Type3,
		abs(Amount180) as Amount180, case when Amount180<0 then 'Cr' when Amount180>0 then 'Dr' else '' end Type4,
		abs(PendingAmt) as PendingAmt, case when PendingAmt<0 then 'Cr' when PendingAmt>0 then 'Dr' else '' end Type5,
		abs(AdvAmt) as AdvAmt, case when AdvAmt<0 then 'Cr' when AdvAmt>0 then 'Dr' else '' end Type6,
		abs(TotAmt) as TotAmt, case when TotAmt<0 then 'Cr' when TotAmt>0 then 'Dr' else '' end Type7
	From dbo.fn_FAS_Dis_AgeingAnalysis_Tmp ('0303', '0', 'B', @RptDate, @PrStart, @PrEnd, @CmCode)
	Where PendingAmt<>0 or AdvAmt <> 0 or Type = 'Group' and TotAmt > 0 
	Order By LrRoute, Type, Particulars
    	 
 End

GO

