As

SET NOCOUNT ON

Begin

	/* @WarehoseCode =  'TCS'
		begin
	
			Select distinct ItemCode,ItemDesc,CBQty,Case When isNull(Rate,0) = 0 then isnull(Rate3,0) Else Rate end as Rate From(
			
			Select distinct ItemCode,Case When isNull(Desc1,'') = '' then isnull(ItemDesc,'') Else Desc1 end as ItemDesc,
			
			Case When isNull(Rate1,0) = 0 then isnull(Rate2,0) Else Rate1 end as Rate,Rate3,CBQty  From(
			
