			Left Outer Join dbo.fn_BOM_Get_Material_Master('A',@AsOnDate, @RptDate, @BranchID, @CompID) b4
			
			On b4.ItemCode = a.ItemCode and a.BranchID = b4.BranchID and a.CompID=b4.CompID 
			
			Left Outer Join SalBankInformation c 
			
