			Where a.BranchID = @BranchID and a.CompID = @CompID and WarehouseCode = @WarehoseCode and RackCode = ''  and CBQty > 0)x 
			)y 
			Order By ItemCode
		End

	 @WarehoseCode <>  'TCS'  */

		Begin
			Select distinct a.ItemCode, b.ItemDescription, a.CBQty, 
			      Case When isNull(c.Rate,0) = 0 then isnull(b.Rate,0) Else c.Rate end as Rate
			from dbo.fn_INV_AsOnDate_Stock_Bank(@AsOnDate,@AsOnDate,@RptDate,@BranchID, @CompID, @Finyear)  a 
			    
			     Left Outer Join INV_MATERIAL_MASTER b --dbo.fn_BOM_Get_Material_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) b
			           On b.ItemCode = a.ItemCode and a.BranchID = b.BranchID and a.CompID=b.CompID 
