/****** Object:  Stored Procedure dbo.SAL_BankProcess_SubContract    Script Date: 14/04/2010 1:27:46 PM ******/
CREATE PROCEDURE [dbo].[SAL_BankProcess_SubContract](@AsOnDate datetime, @RptDate datetime,@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))  
   
 As  
  
 SET NOCOUNT ON  
  
	 Begin   
	   
		   Select distinct a.RecdItemCode as Itemcode, d.ItemDescription,  
		    a.PendingQty as CBQty,Case When isNull(e.Rate,0) = 0 then d.Rate Else e.Rate end as Rate  
		   From dbo.fn_SAL_DCSR_SubContract(@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear) a 
		   Left Outer Join Inv_Material_Master d   
		    On d.ItemCode = a.RecdItemCode and d.BranchID = a.BranchID and d.CompID = a.CompID  
		   Left Outer Join SalBankInformation e   
		    On e.ItemCode = a.RecdItemCode and e.BranchID = a.BranchID and e.CompID = a.CompID  
		   Where a.BranchID = @BranchID AND a.CompID = @CompID 
		   Order by Itemcode  
	 End
GO

