/****** Object:  Stored Procedure dbo.SAL_BankProcess_WIP    Script Date: 14/04/2010 1:27:46 PM ******/
CREATE PROCEDURE [dbo].[SAL_BankProcess_WIP](@WHCode varchar(3),@AsOnDate datetime, @RptDate datetime,@BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))
 
 As

 SET NOCOUNT ON

	 Begin	
	
		Select distinct a.ItemCode, b.Itemdescription, sum(a.CBQty) as qty, Case When isNull(e.Rate,0) = 0 then b.Rate Else e.Rate end as Rate 
		From fn_INV_AsOnDate_Stock_WIP_Bank (@AsOnDate,@AsOnDate,@RptDate,@BranchID,@CompID,@Finyear) a 
		Left Outer Join Inv_Material_Master b 
			On a.ItemCode = b.itemcode and a.BranchID = b.BranchID and a.CompID = b.CompID 
		Left Outer Join SalBankInformation e 
			On e.ItemCode = a.ItemCode and WarehouseCode = WHCode and e.BranchID = a.BranchID and e.CompID = a.CompID
		Where a.CBQty > 0 and WarehouseCode = @WHCode and a.BranchID = @BranchID and a.CompID = @CompID
		Group by a.ItemCode, b.Itemdescription,b.Rate,e.Rate Order by a.Itemcode
	
	 End
