/****** Object:  StoredProcedure [dbo].[Sal_Get_SalesPlan]    Script Date: 17/06/2026 11:30:57 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[Sal_Get_SalesPlan] (@isCreate bit, @DocType varchar(3), @PlanFor int,  @Period datetime,  @Finstart datetime,  @AsOnDate datetime,  @RptDate datetime, @BranchID varchar(3), @CompID varchar(3),  @Finyear varchar(20))

AS

	Begin
		SET NOCOUNT ON
	
		Declare @PlanMonth varchar(2)
		Declare @PlanYear varchar(4)

		Select @PlanMonth = Month(@Period) 
		Select @PlanYear = Year(@Period) 
	
		Select a.ItemCode, b.ItemDescription, 
			(Select top 1 PartNo From PartMast Where StageCode = a.ItemCode and Branchid = a.Branchid and Compid = a.Compid)PartNo,
			b.UomDesc, b.UomDecimal, a.PlanQty,  a.PlanFor, a.PlanPeriod, 
			dbo.fn_Sal_Item_Rate (a.ItemCode, a.CustomerCode, '', 0, Null, @BranchID,  @CompID, @Finyear)Rate, 
			 a.CustomerCode, (Select PartyName From FAS_Party_Master Where acType in ('D', 'Y') and PartyCode = a.CustomerCode and  BranchID = a.BranchID and CompID = a.CompID) CustomerName
			From dbo.fn_Sal_SalesPlan (@AsOnDate,  @RptDate,  @BranchID,  @CompID,  @Finyear)    a
				Left Outer Join Material_Master b
					On b.ItemCode = a.ItemCode and b.BranchID = a.BranchID and b.CompID = a.CompID
			Where ((a.PlanFor=1 and Month(PlanPeriod)=4) or (a.PlanFor > 1 and Month(PlanPeriod) = @PlanMonth))  and Year(PlanPeriod) = @PlanYear	
				and PlanFor = (Select Max(PlanFor) PlanFor From dbo.fn_Sal_SalesPlan (@AsOnDate,  @RptDate,  @BranchID,  @CompID,  @Finyear)    
							Where ((a.PlanFor=1 and Month(PlanPeriod)=4) or (a.PlanFor > 1 and Month(PlanPeriod) = @PlanMonth))  and Year(PlanPeriod) = @PlanYear 
								and ((@isCreate='1' and PlanFor < @PlanFor) or (@isCreate='0' and PlanFor <= @PlanFor))
								and BranchID = a.BranchID and CompID = a.CompID and a.DocType = @DocType)
								and a.DocType = @DocType
		Order By  CustomerName, a.ItemCode, a.PlanFor

	End
GO

