CREATE PROCEDURE [dbo].[SAL_INS_AMENDMENT_DTL]

	(@AmendmentType 	[varchar](3),
	 @AmendmentNo 	[int],
	 @AmendmentDate 	[datetime],
	 @ItemCode 		[varchar](20),
	 @ItemDescription	[varchar](50),
	 @PartNo		[varchar](20),
	 @RevisionNo		[varchar](5),
	 @UOM 		[int],	
	 @Qty 			[float],
	 @NewQty 		[float],
	 @Rate 		[float],
	 @NewRate 		[float],
	 @AssessableRate 	[float],
	 @NewAssessableRate 	[float],
	 @ValidFrom 		[datetime],
	 @Status 		[bit],
	 @Userid 		[varchar](10),
	 @Branchid 		[varchar](3),
	 @Compid 		[varchar](3),
	 @Finyear 		[varchar](20))

