CREATE PROCEDURE [dbo].[SAL_INS_CUSTOMER_ITEMMASTER_His]
	(@CustomerCode 	[int],
	 @Branchid 		[varchar](3),
	 @Compid 		[varchar](3))

AS INSERT INTO SAL_CUSTOMER_ITEMMASTER_His
		Select CustomerCode,ItemCode,isnull((select Max(Revisionno) from Sal_Customer_Itemmaster_His where CustomerCode=a.CustomerCode and Branchid=a.Branchid and Compid=a.Compid),-1)+1 as Revision,
		Model,IssuedNo,PartNo,Rate,AssessableRate,ValidFrom,ValidTo,FormulaCode,QCCheck,Status,Userid,Branchid,Compid,convert(varchar,getdate(),120) from Sal_Customer_Itemmaster a 
		where CustomerCode=@CustomerCode and Branchid=@Branchid  and Compid=@Compid
GO

