CREATE PROCEDURE [dbo].[SAL_INS_Jobwork_ItemMaster_His]
	(@CustomerCode 	[int],
	 @Branchid 	[varchar](3),
	 @Compid 	[varchar](3))

AS INSERT INTO SAL_Jobwork_ItemMaster_His
		select ItemGroupKey,CustomerCode,isnull((select Max(Revisionno) from SAL_Jobwork_ItemMaster_His where CustomerCode=a.CustomerCode and Branchid=a.Branchid and Compid=a.Compid),-1)+1 as Revision,
		ReceivedItemCode,SentItemCode,RelationType,PartNo,RatePer,Rate,AssessableRate,ValidFrom,ValidTo,QcCheck,FormulaCode,isActive,UserID,BranchID,CompID,
		convert(varchar,getdate(),120) from SAL_Jobwork_ItemMaster a 
		where CustomerCode=@CustomerCode and Branchid=@Branchid  and Compid=@Compid
GO

