CREATE PROCEDURE [dbo].[SAL_INV_INS_MATERIALTRAN_DTL]
	(@DOCType 			[varchar](5),
	 @DOCNo 			[int],
	 @DOCDate 			[datetime],
	 @TransactionDate 		[datetime],
	 @TransactionTime 		[datetime],
	 @TransactionItem 		[varchar](20),
	 @TransactionQty 		[float],
	 @Norms 			[float],
	 @FromWarehouseCode 	[varchar](6),
	 @FromRackBinCode 		[varchar](6),
	 @ToWarehouseCode 		[varchar](6),
	 @ToRackBinCode 		[varchar](6),
	 @ItemGroupKey		[int],
	 @FromItem 			[varchar](20),
	 @ToItem 			[varchar](20),
	 @Justification 			[varchar](30),
	 @Userid 			[varchar](10),
	 @Branchid 			[varchar](3),
	 @Compid 			[varchar](3),
	 @Finyear 			[varchar](20))

AS

SET NOCOUNT ON 


	If Exists (Select * from  INV_MATERIALTRAN_DTL Where TransactionDate=@TransactionDate and TransactionItem=@TransactionItem and DOCNo=@DOCNo and DOCType=@DOCType and DOCDate=@DOCDate
			and Branchid=@Branchid and Compid=@Compid and Finyear=@Finyear)
		
		Begin
			Update INV_MATERIALTRAN_DTL Set TransactionQty=TransactionQty+@TransactionQty
			Where TransactionDate=@TransactionDate and TransactionItem=@TransactionItem and DOCNo=@DOCNo and DOCType=@DOCType and DOCDate=@DOCDate
				and Branchid=@Branchid and Compid=@Compid and Finyear=@Finyear

		End

	Else

		Begin
			 INSERT INTO [INV_MATERIALTRAN_DTL] 
				 ( [DOCType],
				 [DOCNo],
				 [DOCDate],
				 [TransactionDate],
				 [TransactionTime],
				 [TransactionItem],
				 [TransactionQty],
				 [Norms],
				 [FromWarehouseCode],
				 [FromRackBinCode],
				 [ToWarehouseCode],
				 [ToRackBinCode],
				 [ItemGroupKey],
				 [FromItem],
				 [ToItem],
				 [Justification],
				 [Userid],
				 [Branchid],
				 [Compid],
				 [Finyear]) 
			 
			VALUES 
				( @DOCType,
				 @DOCNo,
				 @DOCDate,
				 @TransactionDate,
				 @TransactionTime,
				 @TransactionItem,
				 @TransactionQty,
				 @Norms,
				 @FromWarehouseCode,
				 @FromRackBinCode,
				 @ToWarehouseCode,
				 @ToRackBinCode,
				 @ItemGroupKey,
				 @FromItem,
				 @ToItem,
				 @Justification,
				 @Userid,
				 @Branchid,
				 @Compid,
				 @Finyear)
		End
GO

/****** Object:  StoredProcedure [dbo].[SAL_Invoice_Cancel]    Script Date: 17/06/2026 11:31:00 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SAL_Invoice_Cancel] (@InvType varchar(3), @InvNo int, @InvDate datetime, @Remarks Varchar(100), 
	@UserID varchar(10), @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20) )            
AS            
BEGIN
 SET NOCOUNT ON;
      
 /* Update Type 'Cancel' in SAL_Invoice_Hdr Table */        
      
 Update SAL_Invoice_Hdr       
 Set Type='CANCEL', TotalAmount = 0      
 Where InvoiceType=@InvType and InvoiceNo=@InvNo and InvoiceDate=@InvDate and BranchID=@BranchID and CompID=@CompID      
      
 /* Insert Data into Cancel Table */                
 Insert into SAL_Invoice_Cancel_Hdr        
  Select InvoiceType, InvoiceNo, InvoiceDate, InvoiceTime, InvoiceSource, CustomerCode, AInformation1, AInformation2, 
	@Remarks As Narration, ModeCode, VehicleNo, DCNo, PLASlNo, PLADate, NoofPackets, InsurancePolicyNo, InsurancePolicyDate, 
	InsuranceFor, InsuranceSlNo, Type, FIRNo, FIRDate, RemovalTime, TotalAmount, FormulaCode, RRNo, RRDate, RRRemarks,
	/* Transporter, PCNo, AWBNo, AWBDate,*/ @UserID As UserID, Branchid, Compid, Finyear, TranStamp           
  From SAL_Invoice_Hdr       
  Where InvoiceType=@InvType and InvoiceNo=@InvNo and InvoiceDate=@InvDate and BranchID=@BranchID and CompID=@CompID      
      
 Insert into SAL_Invoice_Cancel_Dtl        
  Select InvoiceType, InvoiceNo, InvoiceDate, ItemGroupKey, ItemCode, InvoiceQty, Rate, AssessableRate, 
		OrderType, OrderNo, OrderDate, ReceivedQty, AcceptedQty, @UserID As UserID, Branchid, Compid, Finyear, TranStamp       
  From SAL_Invoice_Dtl      
  Where InvoiceType=@InvType and InvoiceNo=@InvNo and InvoiceDate=@InvDate and BranchID=@BranchID and CompID=@CompID      
      
 Insert into COM_FormulaCalc_Cancel_Hdr        
  Select DocType, DocNo, DocDate, ModuleCode, FrmID, ExprSeq, GrandTotalFlag, 
	ResultValue, PostingAc, /* CalcFlag,*/ @UserID As UserID, BranchID, CompID, Finyear, TranStamp

  From COM_FormulaCalc_Hdr      
  Where DocType=@InvType and DocNo=@InvNo and DocDate=@InvDate and BranchID=@BranchID and CompID=@CompID      
       
 Insert into COM_FormulaCalc_Cancel_Dtl        
  Select DocType, DocNo, DocDate, ModuleCode, FrmID, BlockType, Block, MultiSeq, KeyCol, IsTypePercentage, IsTypeEditable, ValueUsed,       
   IsValueEditable, /* CalcFlag,*/ @UserID As UserID, BranchID, CompID, Finyear, TranStamp       
  From COM_FormulaCalc_Dtl      
  Where DocType=@InvType and DocNo=@InvNo and DocDate=@InvDate and BranchID=@BranchID and CompID=@CompID      
        
 /* Delete Data After insert into Cancel Table */       
 Delete From SAL_Invoice_Dtl       
 Where InvoiceType=@InvType and InvoiceNo=@InvNo and InvoiceDate=@InvDate and BranchID=@BranchID and CompID=@CompID      
       
 Delete From COM_FormulaCalc_Hdr      
 Where DocType=@InvType and DocNo=@InvNo and DocDate=@InvDate and BranchID=@BranchID and CompID=@CompID      
       
 Delete From COM_FormulaCalc_Dtl      
 Where DocType=@InvType and DocNo=@InvNo and DocDate=@InvDate and BranchID=@BranchID and CompID=@CompID      
      
 /* Delete MaterialTran Data */      
 Delete From INV_MaterialTran_dtl       
 Where DocType=@InvType and DocNo=@InvNo and DocDate=@InvDate and BranchID=@BranchID and CompID=@CompID      
       
 /* Delete PACKINGLIST Data */                             
 --Delete from SAl_PACKING_WorkOrder_List                  
 --Where ICode in                   
 -- (                  
 -- Select distinct ICode                  
 -- From SAl_PACKINGLIST_GOODS                    
 -- where OrderType=@InvType and OrderNo=@InvNo and OrderDate=@InvDate and BranchID=@BranchID and CompID=@CompID                    
 -- )                 
 --and BranchID=@BranchID and CompID=@CompID                   
                   
 Delete from SAl_PACKINGLIST_GOODS                         
 where OrderType=@InvType and OrderNo=@InvNo and OrderDate=@InvDate   and BranchID=@BranchID and CompID=@CompID                    
                      
 Delete from SAL_PACKINGLIST                         
 where OrderType=@InvType and OrderNo=@InvNo and OrderDate=@InvDate and BranchID=@BranchID and CompID=@CompID                      
                       
 Delete from SAL_PACKINGLIST_ADDRESS             
 where OrderType=@InvType and OrderNo=@InvNo and OrderDate=@InvDate and BranchID=@BranchID and CompID=@CompID         
      
  /* Update Invoice Type, No & Date into DC Details */                          
 Update SAL_Dc_Dtl Set InvoiceType='', InvoiceNo='', InvoiceDate=Null                       
 Where InvoiceType=@InvType and InvoiceNo=@InvNo and InvoiceDate=@InvDate and BranchID=@BranchID and CompID=@CompID                  
       
 /* Delete FAS Data */        
 Declare @FASCode varchar(12)      
 Select @FASCode = @CompID+@BranchID      
       
 Declare @VrType varchar(3)      
 Declare @VrNo int      
 Declare @VrDate datetime      
 Declare @VrRoute varchar(42)      
       
 Select @VrType=DocType, @VrNo=DocNo, @VrDate=DocDate, @VrRoute=VrRoute   
 From FAS_VoucherTranRef      
 Where RefType=@InvType and RefNo=@InvNo and RefDate=@InvDate and CompCode=@FASCode      
 
 /* FAS Voucher Table List - Cancel */
 Execute FAS_Cancel_Voucher @VrNo, @VrDate, @VrRoute, @FASCode      
END
GO

/****** Object:  StoredProcedure [dbo].[SAL_Invoice_Date_Change]    Script Date: 17/06/2026 11:31:00 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[SAL_Invoice_Date_Change] (@InvType varchar(3), @InvNo int, @InvDate datetime, @NewInvDate datetime, @BranchID varchar(3), @CompID varchar(3))

AS

Begin

	SET NOCOUNT ON

	Update SAL_Invoice_Hdr Set InvoiceDate=@NewInvDate
	where InvoiceType=@InvType and InvoiceNo=@InvNo and InvoiceDate=@InvDate and BranchID=@BranchID and CompID=@CompID
	
	Update SAL_Invoice_Dtl Set InvoiceDate=@NewInvDate
	where InvoiceType=@InvType and InvoiceNo=@InvNo and InvoiceDate=@InvDate and BranchID=@BranchID and CompID=@CompID
	
	Update COM_FormulaCalc_Hdr Set DocDate=@NewInvDate
	where DocType=@InvType and DocNo=@InvNo and DocDate=@InvDate and BranchID=@BranchID and CompID=@CompID
	
	Update COM_FormulaCalc_Dtl Set DocDate=@NewInvDate
	where DocType=@InvType and DocNo=@InvNo and DocDate=@InvDate and BranchID=@BranchID and CompID=@CompID

	Update INV_MaterialTran_dtl Set DocDate=@NewInvDate, TransactionDate=@NewInvDate
	where DocType=@InvType and DocNo=@InvNo and DocDate=@InvDate and BranchID=@BranchID and CompID=@CompID
	
	
	Declare @FASCode varchar(12)
	Select @FASCode = @CompID+@BranchID
	
	Declare @VrType varchar(3)
	Declare @VrNo int
	Declare @VrDate datetime
	Declare @VrRoute varchar(42)
	
	Select @VrType=DocType, @VrNo=DocNo, @VrDate=DocDate, @VrRoute=VrRoute from FAS_VoucherTranRef
	Where RefType=@InvType and RefNo=@InvNo and RefDate=@InvDate and CompCode=@FASCode
	
	Update FAS_VoucherTranRef Set DocDate=@NewInvDate, RefDate=@NewInvDate
	where DocType=@VrType and DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and CompCode=@FASCode
	
	Update FAS_BillDetails Set DocDate=@NewInvDate, RefDate=@NewInvDate
	where DocType=@VrType and DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and CompCode=@FASCode
	
	Update FAS_VoucherTranMast Set DocDate=@NewInvDate
	where DocType=@VrType and DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and CompCode=@FASCode
	
	Update FAS_VoucherTranSub Set DocDate=@NewInvDate
	where DocType=@VrType and DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and CompCode=@FASCode
	
	Update FAS_VoucherTranPay Set DocDate=@NewInvDate
	where DocType=@VrType and DocNo=@VrNo and DocDate=@VrDate and VrRoute=@VrRoute and CompCode=@FASCode


End
GO

