CREATE PROCEDURE [dbo].[SAL_InvoicePrint_Fil_JSON](@IsInvDate bit='0', @FromInvDate datetime=NULL,         
    @ToInvDate datetime=NULL,  @IsInvNo bit='0',@FromInvNo int=0,  @ToInvNo int=0, @AsOnDate datetime,         
    @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                  
As                  
BEGIN                    
  SET NOCOUNT ON;        
      
 Select Distinct a.InvoiceType [Inv. Type], a.InvoiceNo [Inv. No],         
      a.InvoiceDate [Inv. Date], b.PartyName [Customer], a.CustomerCode,         
      IsNull(y.OrderFlag,'') As OrderFlag, IsNull(p.Qty,'') As BoxQty,
      IsNull(a.VehicleNo,'') As VehicleNo, IsNull(a.Transporter,'') As Transporter,         
   IsNull(a.PCNo,'') As PCNo, IsNull(a.AWBNo,'') As AWBNo       
 From SAL_INVOICE_HDR a         
 Left Outer Join FAS_Party_Master b         
  On a.CustomerCode=b.PartyCode and a.BranchID=b.BranchID         
   and a.CompID=b.CompID         
 Left Outer Join SAL_PackingList y     
 On a.InvoiceType=y.OrderType         
  and a.InvoiceNo=y.OrderNo and a.InvoiceDate=y.OrderDate         
  and a.BranchID=y.BranchID and a.CompID=y.CompID    
 Left Outer Join SAL_PackingSlipQty_Dtl p     
 On a.InvoiceNo=p.DocNo and a.InvoiceDate=p.DocDate and a.InvoiceType=p.DocType               
  and a.BranchID=p.BranchID and a.CompID=p.CompID  and a.Finyear=p.Finyear                
 Where (@IsInvDate='0' or (@IsInvDate='1' and (((@ToInvDate Is Not Null) and a.InvoiceDate Between @FromInvDate and @ToInvDate)        
            or ((@ToInvDate Is Null)  and a.InvoiceDate>=@FromInvDate))))        
  and (@IsInvNo='0' or (@IsInvNo='1' and ((@ToInvNo>0 and a.InvoiceNo Between @FromInvNo and @ToInvNo)        
            or (@ToInvNo<=0  and a.InvoiceNo>=@FromInvNo))))        
  and a.BranchID=@BranchID and a.CompID=@CompID and a.finyear=@Finyear      
   and not Exists             
     (Select * From COM_EInvoiceJSONFile x             
       Where x.DocType=a.InvoiceType and x.DocNo=a.InvoiceNo and x.DocDate=a.InvoiceDate                    
        and x.BranchID=a.BranchID and x.CompID=a.CompID and x.Finyear=a.Finyear             
     )       
 Order by a.InvoiceDate Desc, a.InvoiceNo Desc     
      
END 
GO

/****** Object:  StoredProcedure [dbo].[SAL_InvoicePrint_Get_PackingSlip]    Script Date: 17/06/2026 11:31:01 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SAL_InvoicePrint_Get_PackingSlip](@ModuleCode int, @DocType varchar(3), @DocNo int,       
@DocDate datetime, @CustomerCode As int=0, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3),       
@CompID varchar(3), @Finyear varchar(20))                  
As                  
BEGIN                    
  SET NOCOUNT ON;       
 Declare @ItemCode As varchar(30);      
 Declare @ItemSeq As int;      
 Declare @HeatNo As varchar(500);      
 Declare @TmpTbl_TraceProcess As Table( HeatNo varchar(500) );      
 Declare @CompanyName As varchar(50);     
      
 /* Get HeatNo */      
 Select @ItemCode='', @ItemSeq=0, @HeatNo='';      
      
 Begin      
  /* Drop Temp # Table */      
  If OBJECT_ID('tempdb..#TmpTbl_SalesInvoice') IS NOT NULL      
   Begin      
   Drop Table #TmpTbl_SalesInvoice;        
   End      
        
  Select Distinct a.InvoiceType, a.InvoiceNo, a.InvoiceDate, b.PartyCode,       
    b.PartyName, a.ItemCode, IsNull(d.ItemDescription,'') As PartName,       
    c.PartNo As CustPartNo, c.Model, e.PartNo,       
    a.InvoiceQty, d1.SDesc as UOM, a.NoofPackets, a.NoofPackets as PacketQty,             
 /*  
 (Case When IsNull(a.NoofPackets,0)=0 Then      
     Convert(int, a.InvoiceQty/1) +        
     (Case When IsNull(a.NoofPackets,0)<=(a.InvoiceQty-Convert(int, a.InvoiceQty/1)*1) Then 1 Else 0 End)      
    Else      
     Convert(int, a.InvoiceQty/IsNull(a.NoofPackets,1)) +        
     (Case When IsNull(a.NoofPackets,0)<=a.InvoiceQty-Convert(int, a.InvoiceQty/IsNull(a.NoofPackets,1))*IsNull(a.NoofPackets,1) Then 1 Else 0 End)      
    End) As PacketQty_Old,   
 */     
    /*f.PacketNo,      
    (Case When IsNull(a.NoofPackets,0)=0 Then      
     Convert(int, a.InvoiceQty/1) +        
     (Case When IsNull(f.PacketNo,0)<=(a.InvoiceQty-Convert(int, a.InvoiceQty/1)*1) Then 1 Else 0 End)      
    Else      
     Convert(int, a.InvoiceQty/IsNull(a.NoofPackets,1)) +        
     (Case When IsNull(f.PacketNo,0)<=a.InvoiceQty-Convert(int, a.InvoiceQty/IsNull(a.NoofPackets,1))*IsNull(a.NoofPackets,1) Then 1 Else 0 End)      
    End) As PacketQty, */      
    IsNull(q.Qty,0) As BoxQty      
  INTO #TmpTbl_SalesInvoice   /* Insert Into Temp Table */      
  From SalesInvoice a       
  Left Outer Join FAS_Party_Master b      
   On a.CustomerCode=b.PartyCode and a.BranchID=b.BranchID         
    and a.CompID=b.CompID         
  Left Outer Join SAL_Customer_ItemMaster c        
   On a.CustomerCode=c.CustomerCode and a.ItemCode=c.ItemCode       
    and a.BranchID=c.BranchID and a.CompID=c.CompID       
  Left Outer Join INV_Material_Master d        
   On a.ItemCode=d.ItemCode and a.BranchID=d.BranchID and a.CompID=d.CompID   
  Left Outer Join INV_Uom_Master d1        
   On d.UOM=d1.Code and d.BranchID=d1.BranchID and d.CompID=d1.CompID     
  Left Outer Join PartMast e      
   On a.ItemCode=e.StageCode  and a.BranchID=e.BranchID and a.CompID=e.CompID      
  /*      
  Cross Apply(Select n.PacketNo From (Select ROW_NUMBER()OVER(Order By object_id) As PacketNo       
                    From sys.all_objects) n       
        Where n.PacketNo<=(Case When IsNull(a.NoofPackets,0)=0 Then 1 Else IsNull(a.NoofPackets,1) End)        
  ) f      
  */      
  Left Outer Join SAL_PackingSlipQty_Dtl q       
   On a.InvoiceNo=q.DocNo and a.InvoiceDate=q.DocDate and a.InvoiceType=q.DocType      
    and a.CustomerCode=q.CustomerCode and a.BranchID=q.BranchID       
    and a.CompID=q.CompID and a.Finyear=q.Finyear      
  Where a.InvoiceNo=@DocNo and a.InvoiceDate=@DocDate and a.InvoiceType=@DocType       
   and (@CustomerCode=0 or (@CustomerCode>0 and a.CustomerCode=@CustomerCode))      
   and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear        
 End      
       
 /* Insert Data Into Temp Table */      
 Begin      
  Insert Into @TmpTbl_TraceProcess        
   EXECUTE NET_Com_Rpt_TraceabilityPopup_Fil_FromTrace @ModuleCode, @DocType, @DocNo, @DocDate,             
    @ItemCode, @ItemSeq, @BranchID, @CompID        
      
  Select @HeatNo=IsNull(a.HeatNo,'') From @TmpTbl_TraceProcess a      
  Select @HeatNo=IsNull(@HeatNo,'');      
 End      
    
 Select @CompanyName=CompanyName     
 From Company_Master b     
 Where BranchId=@BranchID and CompID=@CompID    
      
 /* Output (Result) */      
 Select x.InvoiceType As InvType, x.InvoiceNo As InvNo, x.InvoiceDate As InvDate,     
   IsNull(x.PartyCode,0) As CustomerCode,IsNull(x.PartyName,'') As CustomerName, x.ItemCode,       
   IsNull(x.PartName,'') As PartName,IsNull(x.CustPartNo,'') As PartNo,       
   IsNull(x.Model,'') As CustModel, /* IsNull(x.PartNo,'') As PartNo, */
   Sum(IsNull(x.InvoiceQty,0)) As InvQty, UOM, IsNull(x.PacketQty,0) As PacketQty,        
   IsNull(x.NoofPackets,0) As NoofPackets, /* IsNull(x.PacketNo,0) As PacketNo, */      
   IsNull(x.BoxQty,0) As BoxQty, IsNull(@HeatNo,'') As HeatNo, @CompanyName as SupplierName        
  From #TmpTbl_SalesInvoice x      
    
  Group by x.InvoiceType, x.InvoiceNo, x.InvoiceDate, x.PartyCode, x.PartyName,       
      x.ItemCode, x.PartName, x.CustPartNo, x.Model, x.PartNo, x.UOM, x.PacketQty,      
      x.NoofPackets, x.BoxQty      
  Order by InvDate Desc, InvNo Desc, CustomerName, x.ItemCode        
      
 /* Drop Temp # Table */      
 If OBJECT_ID('tempdb..#TmpTbl_SalesInvoice') IS NOT NULL      
  Begin      
  Drop Table #TmpTbl_SalesInvoice;        
  End       
END  
GO

/****** Object:  StoredProcedure [dbo].[SAL_InvoicePrint_Get_PackingSlip_2]    Script Date: 17/06/2026 11:31:01 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SAL_InvoicePrint_Get_PackingSlip_2]( @DocType varchar(3), @DocNo int,           
@DocDate datetime, @CustomerCode As int=0, @ModuleCode int=0, @AsOnDate datetime, @RptDate datetime, @BranchID varchar(3),           
@CompID varchar(3), @Finyear varchar(20))                      
As                      
BEGIN                        
  SET NOCOUNT ON;           

	Declare @CompBranchCode As varchar(10);
	Declare @ItemCode As varchar(30);          
	Declare @ItemSeq As int;          
	Declare @HeatNo As varchar(500);          
	Declare @TmpTbl_TraceProcess As Table( HeatNo varchar(500) );          
	Declare @CompanyName As varchar(50);         
	Declare @State As varchar(50);    
	Declare @PINCode As varchar(10);     
 
 /* Assign Initial Value */          
 Select @ItemCode='', @ItemSeq=0, @HeatNo='', @CompBranchCode=(@CompID+@BranchID);
          
 Begin          
  /* Drop Temp # Table */          
  If OBJECT_ID('tempdb..#TmpTbl_SalesInvoice') IS NOT NULL          
   Begin          
  Drop Table #TmpTbl_SalesInvoice;            
   End          
            
  Select Distinct a.InvoiceType, a.InvoiceNo, a.InvoiceDate, b.PartyCode, b.PartyName, 
		ad.Add1, ad.Add2, ad.Add3, ad.Country, ad.State, ad.City, ad.Pincode, b.VendorCode, 
		b.SuplierCode, a.ItemCode, IsNull(d.ItemDescription,'') As PartName,           
    c.PartNo As CustPartNo, c.Model, e.PartNo, a.InvoiceQty, d1.SDesc As UOM,   
		a.NoofPackets, a.NoofPackets As PacketQty,                 
 /*      
 (Case When IsNull(a.NoofPackets,0)=0 Then          
     Convert(int, a.InvoiceQty/1) +            
     (Case When IsNull(a.NoofPackets,0)<=(a.InvoiceQty-Convert(int, a.InvoiceQty/1)*1) Then 1 Else 0 End)          
    Else          
     Convert(int, a.InvoiceQty/IsNull(a.NoofPackets,1)) +            
     (Case When IsNull(a.NoofPackets,0)<=a.InvoiceQty-Convert(int, a.InvoiceQty/IsNull(a.NoofPackets,1))*IsNull(a.NoofPackets,1) Then 1 Else 0 End)          
    End) As PacketQty_Old,       
 */         
    /*f.PacketNo,          
    (Case When IsNull(a.NoofPackets,0)=0 Then          
     Convert(int, a.InvoiceQty/1) +            
     (Case When IsNull(f.PacketNo,0)<=(a.InvoiceQty-Convert(int, a.InvoiceQty/1)*1) Then 1 Else 0 End)          
    Else          
     Convert(int, a.InvoiceQty/IsNull(a.NoofPackets,1)) +            
     (Case When IsNull(f.PacketNo,0)<=a.InvoiceQty-Convert(int, a.InvoiceQty/IsNull(a.NoofPackets,1))*IsNull(a.NoofPackets,1) Then 1 Else 0 End)          
    End) As PacketQty, */          
    IsNull(q.Qty,0) As BoxQty     
  INTO #TmpTbl_SalesInvoice   /* Insert Into Temp Table */          
  From SalesInvoice a           
  Left Outer Join FAS_Party_Master b          
   On a.CustomerCode=b.PartyCode and a.BranchID=b.BranchID and a.CompID=b.CompID
	Left Outer Join FAS_PARTY_ADDRESS ad	
		On b.PartyCode=ad.PartyCode and a.BranchID=ad.BranchID and a.CompID=ad.CompID            
  Left Outer Join SAL_Customer_ItemMaster c            
   On a.CustomerCode=c.CustomerCode and a.ItemCode=c.ItemCode           
    and a.BranchID=c.BranchID and a.CompID=c.CompID           
  Left Outer Join INV_Material_Master d            
   On a.ItemCode=d.ItemCode and a.BranchID=d.BranchID and a.CompID=d.CompID       
  Left Outer Join INV_Uom_Master d1            
   On d.UOM=d1.Code and d.BranchID=d1.BranchID and d.CompID=d1.CompID         
  Left Outer Join PartMast e          
   On a.ItemCode=e.StageCode  and a.BranchID=e.BranchID and a.CompID=e.CompID          
  /*          
  Cross Apply(Select n.PacketNo From (Select ROW_NUMBER()OVER(Order By object_id) As PacketNo           
                    From sys.all_objects) n           
        Where n.PacketNo<=(Case When IsNull(a.NoofPackets,0)=0 Then 1 Else IsNull(a.NoofPackets,1) End)            
  ) f          
  */          
  Left Outer Join SAL_PackingSlipQty_Dtl q           
   On a.InvoiceNo=q.DocNo and a.InvoiceDate=q.DocDate and a.InvoiceType=q.DocType          
    and a.CustomerCode=q.CustomerCode and a.BranchID=q.BranchID           
    and a.CompID=q.CompID and a.Finyear=q.Finyear          
  Where a.InvoiceNo=@DocNo and a.InvoiceDate=@DocDate and a.InvoiceType=@DocType           
   and (@CustomerCode=0 or (@CustomerCode>0 and a.CustomerCode=@CustomerCode))         
   and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear            
 End          
                  
 Begin        
 /* Insert Data Into Temp Table */      
  Insert Into @TmpTbl_TraceProcess            
   EXECUTE NET_Com_Rpt_TraceabilityPopup_Fil_FromTrace @ModuleCode, @DocType, @DocNo, @DocDate,                 
    @ItemCode, @ItemSeq, @BranchID, @CompID            
          
  Select @HeatNo=IsNull(a.HeatNo,'') From @TmpTbl_TraceProcess a          
  Select @HeatNo=IsNull(@HeatNo,'');          
 End          
  
 Begin  
 /* Get Company Details */        
 Select @CompanyName=a.CompanyName, @State=a.State, @PINCode=a.Pincode  
 From Company_Master a         
 Where a.BranchId=@BranchID and a.CompID=@CompID  
  
 Select @CompanyName=(Case When IsNull(@CompanyName,'')='' Then 'Unicorn (Bangalore) Private Limited' Else @CompanyName End),  
   @State=(Case When IsNull(@State,'')='' Then 'PUDUCHERRY' Else @State End),  
   @PINCode=(Case When IsNull(@PINCode,'')='' Then '605009' Else @PINCode End)       
 End        
          
 /* Output (Result) */          
 Select x.InvoiceType As InvType, x.InvoiceNo As InvNo, x.InvoiceDate As InvDate,		
		IsNull(x.PartyCode,0) As CustomerCode,IsNull(x.PartyName,'') As CustomerName, 
		IsNull(x.Add1,'') As CustAdd1, IsNull(x.Add2,'') As CustAdd2, IsNull(x.Add3,'') As CustAdd3, 
		IsNull(x.Country,'') As CustCountry, IsNull(x.State,'') As CustState, IsNull(x.City,'') As CustCity, 
		IsNull(x.Pincode,'') As CustPINCode, IsNull(x.VendorCode,'') As VendorCode, 
		IsNull(x.SuplierCode,'') As SuplierCode, IsNull(x.PartName,'') As PartName, 
		IsNull(x.CustPartNo,'') As PartNo, x.ItemCode, IsNull(x.Model,'') As CustModel, /* IsNull(x.PartNo,'') As PartNo, */    
		Sum(IsNull(x.InvoiceQty,0)) As InvQty, UOM, IsNull(x.PacketQty,0) As PacketQty,            
		IsNull(x.NoofPackets,0) As NoofPackets, /* IsNull(x.PacketNo,0) As PacketNo, */          
		IsNull(x.BoxQty,0) As BoxQty, IsNull(@HeatNo,'') As HeatNo,   
		IsNull(@CompanyName,'') As SupplierName, IsNull(@State,'') As CompState, IsNull(@PINCode,'') As CompPINCode				            
  From #TmpTbl_SalesInvoice x                  
  Group by x.InvoiceType, x.InvoiceNo, x.InvoiceDate, x.PartyCode, x.PartyName, x.Add1, x.Add2, x.Add3, 
			x.Country, x.State, x.City, x.Pincode, x.VendorCode, x.SuplierCode, x.PartName, x.CustPartNo, x.ItemCode, 
			x.Model, x.PartNo, x.UOM, x.PacketQty, x.NoofPackets, x.BoxQty			         
  Order by InvDate Desc, InvNo Desc, CustomerName, x.ItemCode            
          
 /* Drop Temp # Table */          
 If OBJECT_ID('tempdb..#TmpTbl_SalesInvoice') IS NOT NULL          
  Begin          
  Drop Table #TmpTbl_SalesInvoice;            
  End           
END
GO

