SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE Procedure [dbo].[SAL_JobworkDCRef_Hlp] (@DocType varchar(3),@DocNo int,@DocDate datetime,@ItemGroupKey int,@InvType varchar(3),@invNo int,@invDate datetime,@SentItem varchar(20),@AsOnDate datetime, @RptDate datetime,@BranchID varchar(3),@CompID varchar(3))                
--ALTER BY SOMU ON 13102012 14:00:00  
as                
                
Begin                
                
       
 Select DcNo,DcDate, b.ItemCode ,Sum(b.ReceiptQty)as DcQty,            
   dbo.fn_BOM_Norms (b.ItemCode, @SentItem, @AsOnDate, @RptDate,@BranchID, @CompID) as Norms,               
   Round((Sum(b.ReceiptQty)-Isnull(        
            (        
             Select Sum(Qty) from SAL_Invoice_JobworkDC d where d.DcNo=c.DcNo                 
              and d.DcDate=c.DcDate and d.ItemCode=b.ItemCode           
              and d.INVType+convert(varchar,d.INVNo)+convert(varchar,d.INVDate,112)             
              not in (Select @INVType+convert(varchar,@INVNo)+convert(varchar,@INVDate,112))            
              and d.BranchID=c.BranchID and d.CompID=c.CompID        
            )        
           ,0)        
   ),6) as BalQty          
 From REC_ReceiptEntry_dtl b        
 Left outer join REC_ReceiptEntry_Hdr c          
   on c.ReceiptEntryType=b.ReceiptEntryType and c.ReceiptEntryNo=b.ReceiptEntryNo and c.ReceiptEntryDate=b.ReceiptEntryDate                
 Where B.RECEIPTENTRYDATE >= '2012-10-06 00:00:00.000' AND b.BranchID=@BranchID and b.CompId=@CompId        
		and b.RefType=@DocType and b.Refno=@DocNo and b.RefDate=@DocDate
  and b.ItemCode in (        
            Select Distinct FromCode From ItemGroupKey_Dtl        
                   Where ItemGroupKey=@ItemGroupKey and BranchID=@BranchID and CompId=@CompId        
           )                     
 Group by c.DcNo,c.DcDate,b.ItemCode,b.ItemGroupKey,c.BranchID,c.CompID              
   having (Sum(b.ReceiptQty)-Isnull(        
                (        
                 Select Sum(Qty) from SAL_Invoice_JobworkDC d where d.DcNo=c.DcNo                 
                  and d.DcDate=c.DcDate and d.ItemCode=b.ItemCode --and d.ItemGroupKey=b.ItemGroupKey            
                  and d.INVType+convert(varchar,d.INVNo)+convert(varchar,d.INVDate,112)             
                  not in (Select @INVType+convert(varchar,@INVNo)+convert(varchar,@INVDate,112))            
                  and d.BranchID=c.BranchID and d.CompID=c.CompID        
                )        
                ,0)        
       )>0            
  Order by  c.DcNo,c.DcDate,b.ItemCode           
End  
GO

/****** Object:  StoredProcedure [dbo].[SAL_Order_Hlp_FrmName]    Script Date: 17/06/2026 11:31:01 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SAL_Order_Hlp_FrmName](@IsSGST bit, @ModuleCode int, @BranchID int, @CompID int)
AS
BEGIN
	SET NOCOUNT ON

	If (@IsSGST ='1')
		BEGIN
			Select a.FrmLName, a.FrmID 
			from COM_FORMULAMAST_HDR a
			Where ModuleCode=@ModuleCode and isActive='1' and BranchID = @BranchID and CompID = @CompID
			 and Not Exists
			 (
				Select * 
				From COM_LSTCSTGrouping b
				Left Outer Join COM_FormulaExpr_Group c
				On b.ExprGroupID= c.ExprGroupID and b.ModuleCode= c.ModuleCode and b.BranchID=c.BranchId and b.CompID= c.CompID
				Left Outer Join COM_FORMULAMAST_Dtl d
				On c.Route+c.Width= d.ExprRoute and c.ModuleCode= d.ModuleCode and c.BranchID=d.BranchID and c.CompID=d.CompID
				Where b.ModuleCode=@ModuleCode and b.TaxCode=9 and b.BranchID= @BranchID and b.CompID=@CompID /* TaxCode - 9 IGST */
				and a.FrmID= d.FrmID
			 )

		END

	ELSE
		BEGIN

			Select a.FrmLName, a.FrmID 
			from COM_FORMULAMAST_HDR a
			Where ModuleCode=@ModuleCode and isActive='1' and BranchID = @BranchID and CompID = @CompID
			 and Not Exists
			 (
				Select * 
				From COM_LSTCSTGrouping b
				Left Outer Join COM_FormulaExpr_Group c
				On b.ExprGroupID= c.ExprGroupID and b.ModuleCode= c.ModuleCode and b.BranchID=c.BranchId and b.CompID= c.CompID
				Left Outer Join COM_FORMULAMAST_Dtl d
				On c.Route+c.Width= d.ExprRoute and c.ModuleCode= d.ModuleCode and c.BranchID=d.BranchID and c.CompID=d.CompID
				Where b.ModuleCode=@ModuleCode and b.TaxCode=8 and b.BranchID= @BranchID and b.CompID=@CompID /* TaxCode - 8 CGST */
				and a.FrmID= d.FrmID
			 )

		END



END
GO

