CREATE PROCEDURE [dbo].[SAL_PackingSlipQty_Dtl_Ins]     
(    
 @DocType [varchar](3),  
 @DocNo [int],  
 @DocDate [datetime],   
 @CustomerCode [int],  
 @Qty [float],    
 @EffStatus  [char](2),  
 @EffDate  [datetime],  
 @UserID  [varchar](10),  
 @BranchID [varchar](3),  
 @CompID [varchar](3),  
 @Finyear [varchar](20),  
 @TranStamp  [datetime]   
)  
AS          
BEGIN          
 SET NOCOUNT ON;     
   
 Declare @Tmp_EffStatus As char(2);  
 Declare @Tmp_EffDate As datetime;  
  
 If @EffStatus=''  
  Begin  
  SET @Tmp_EffStatus='AA';  
  End  
 Else  
  Begin  
  SET @Tmp_EffStatus=@EffStatus;  
  End  
  
 If (@EffDate Is Null)  
  Begin  
  SET @Tmp_EffDate=@TranStamp;  
  End  
 Else  
  Begin  
  SET @Tmp_EffDate=@EffDate;  
  End  
     
 If Exists(Select * From SAL_PackingSlipQty_Dtl a   
     Where a.DocNo=@DocNo and a.DocDate=@DocDate and a.DocType=@DocType  
       and a.CustomerCode=@CustomerCode and a.BranchID=@BranchID   
       and a.CompID=@CompID and a.Finyear=@Finyear  
     )        
  Begin     
  /* Delete Data Into Table */       
  Delete From SAL_PackingSlipQty_Dtl  
  Where DocNo=@DocNo and DocDate=@DocDate and DocType=@DocType  
    and CustomerCode=@CustomerCode and BranchID=@BranchID   
    and CompID=@CompID and Finyear=@Finyear  
  End    
    
 /* Insert Data Into Table */  
 Begin                           
  INSERT INTO SAL_PackingSlipQty_Dtl     
  (          
   [DocType],  
   [DocNo],  
   [DocDate],  
   [CustomerCode],  
   [Qty],     
   [EffStatus],  
   [EffDate],  
   [UserID],  
   [BranchID],  
   [CompID],  
   [Finyear],  
   [TranStamp]  
  )  
  VALUES  
  ( @DocType,  
   @DocNo,  
   @DocDate,   
   @CustomerCode,  
   @Qty,   
   @Tmp_EffStatus,  
   @Tmp_EffDate,  
   @UserID,  
   @BranchID,  
   @CompID,  
   @Finyear,  
   @TranStamp  
  )  
 End  
END  
GO

/****** Object:  StoredProcedure [dbo].[SAL_Rpt_Achieved_NonAchieved]    Script Date: 17/06/2026 11:31:01 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SAL_Rpt_Achieved_NonAchieved](@PeriodType char(3),@ChartType int, @fromDate datetime, @ToDate datetime, @BranchID varchar(3), @CompID varchar(3))            
As    
BEGIN    
    SET NOCOUNT ON;    
      
    /* Currently Day First shift starttime hard coded. It should be taken from Shift Master */                    
    DECLARE @ShiftStart datetime;                    
        SET @ShiftStart='06:00';      
        
    IF(@PeriodType ='DY')          
        BEGIN          
            With ChartData_CTE            
            As            
            (            
                Select Case When Convert(varchar(8), a.AsOnDate, 108)<=@ShiftStart   
                    Then Convert(varchar(10), DateAdd(day, -1, a.AsOnDate), 120) + ' ' + @ShiftStart Else Convert(varchar(10), a.AsOnDate, 120) + ' ' + @ShiftStart End as ShiftAsOnDate,             
                    AsOnDate, ChartTypeId, PeriodType, Floor(TargetValue) as TargetValue, Floor(PlanValue) as PlanValue,   
                    Floor(PlanTillPeriodValue) as PlanTillPeriodValue, Floor(AchievedValue) as AchievedValue, Floor(Variance) as Variance            
                From DD_KPI_GaugeChartData  a            
                where a.PeriodType=@PeriodType and a.ChartTypeId=@ChartType and a.AsOnDate > @fromDate and  a.AsOnDate<=@ToDate           
            )            
  
            Select Convert(Varchar(10), a.ShiftAsOnDate,121) as Date,
			 a.PlanValue,
			 (a.TargetValue-a.PlanValue) as planshortage_against_target,
			  a.AchievedValue, --(a.TargetValue-a.AchievedValue) as Variance,
			  (a.PlanValue -a.AchievedValue) as shortage_against_plan,
			  (a.TargetValue - a.AchievedValue) as Shortage_against_target , 
			  a.TargetValue
            From ChartData_CTE a            
            Inner Join             
                (            
                    Select ShiftAsOnDate,  Max(AsOnDate) as MaxAsOnDate            
                    From ChartData_CTE            
                    Group by ShiftAsOnDate            
                )b            
                On a.AsOnDate=b.MaxAsOnDate            
            Order by 1            
        END          
    ELSE            
        BEGIN          
            Select b.YearMonth,a.PlanValue,
			(floor(a.TargetValue)-floor(a.PlanValue))as planshortage_against_target,
			 Floor(IsNull(a.AchievedValue,0)) as AchievedValue, --(Floor(a.TargetValue)-Floor(a.AchievedValue)) as Variance,
			  (Floor(a.PlanValue) - Floor(a.AchievedValue)) as shortage_against_plan,
			  (Floor(a.TargetValue) - Floor(a.AchievedValue)) as Shortage_against_target , 
                Floor(a.TargetValue) as TargetValue            
            From DD_KPI_GaugeChartData a               
            Inner Join                   
                (            
                    Select Convert(Varchar(7), AsOnDate,120) as YearMonth, Max(AsOnDate) as MaxAsOnDate            
                    From DD_KPI_GaugeChartData            
                    Where ChartTypeId=@ChartType and PeriodType=@PeriodType              
                        and Convert(Varchar(10),AsOnDate,120)<@ToDate and Convert(Varchar(10),AsOnDate,120)>@fromDate          
                        and BranchID=@BranchID and CompID=@CompID              
                    Group by  Convert(Varchar(7), AsOnDate,120)            
                )b            
                On a.AsOnDate=b.MaxAsOnDate                   
            Where a.ChartTypeId=@ChartType and a.PeriodType=@PeriodType   and Convert(Varchar(10),a.AsOnDate,120)<@ToDate and Convert(Varchar(10),a.AsOnDate,120)>@fromDate           
                and a.BranchID=@BranchID and a.CompID=@CompID                 
            Order by b.YearMonth          
        END          
END 

GO

