/****** Object:  StoredProcedure [dbo].[SAL_Rpt_LCReport_Gen]    Script Date: 17/06/2026 11:31:01 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SAL_Rpt_LCReport_Gen](@CustomerCode int, @LCNo Varchar(50), @Type Varchar(20), @FromDate datetime, @ToDate datetime, @BranchID Varchar(3), @CompID Varchar(3))        
        
AS        
BEGIN        
         
 SET NOCOUNT ON        
           
   Declare @PrvFromDate datetime  
     
   set @PrvFromDate= dateadd(d,-1,@FromDate)  
     
   Select a.LCAmount, b.INVType, b.INVNo, b.INVDate, b.InvAmount,c.InvoiceQty,   
  isnull(a.LCAmount-(Select isnull(Sum(InvAmount),0)  
  From SAL_Invoice_LCRef d  
  Where d.LCNo=a.LCNo and d.CustomerCode=a.CustomerCode and d.INVDate between a.LCDate and @PrvFromDate
			and BranchID=@BranchID and CompID= @CompID),0) as OB,  
  c.RRNo, isnull(c.RRDate,'') as RRDate,c.ReceivedQty, c.AcceptedQty, (c.ReceivedQty - c.AcceptedQty) as RejQty,  
   (  
    Select Sum(InvAmount)   
    From SAL_Invoice_LCRef   
    Where INVDate between @FromDate and @ToDate and CustomerCode=a.CustomerCode and LCNo=a.LCNo 
				and BranchID=@BranchID and CompID= @CompID
   )   
  as TotalInvAmt, (AcceptedQty/InvoiceQty*InvAmount) as AdjustedAmt  
  From SAL_LC_Dtl a        
  Left Outer Join SAL_Invoice_LCRef b        
  On a.LCNo= b.LCNo and a.LCDate= b.LCDate and a.CustomerCode= b.CustomerCode        
  Left Outer Join SalesInvoice c        
  On b.INVType= c.InvoiceType and b.INVNo= c.InvoiceNo and b.INVDate= c.InvoiceDate        
  and b.CustomerCode= c.CustomerCode and b.BranchID=c.BranchID and b.CompID= c.CompID  
  Where a.CustomerCode=@CustomerCode and a.LCNo=@LCNo  and c.Type=@Type  
   and b.INVDate between @FromDate and @ToDate  
  and a.BranchId=@BranchId and a.CompId=@CompID  
  
     
   /*     
   Select a.LCAmount, b.INVType, b.INVNo, b.INVDate, c.InvoiceQty, b.InvAmount, c.RRNo, isnull(c.RRDate,'') as RRDate,        
    c.Rate, c.ReceivedQty, c.AcceptedQty, (c.ReceivedQty - c.AcceptedQty) as RejQty,    
    (AcceptedQty/InvoiceQty*InvAmount) as AdjustedAmt          
   From SAL_LC_Dtl a        
   Left Outer Join SAL_Invoice_LCRef b        
   On a.LCNo= b.LCNo and a.LCDate= b.LCDate and a.CustomerCode= b.CustomerCode        
   Left Outer Join SalesInvoice c        
   On b.INVType= c.InvoiceType and b.INVNo= c.InvoiceNo and b.INVDate= c.InvoiceDate        
   and b.CustomerCode= c.CustomerCode and b.BranchID=c.BranchID and b.CompID= c.CompID        
   Where a.LCDate between @FromDate and @ToDate and a.LCNo=@LCNo        
   and a.BranchID=@BranchID and a.CompID=@CompID and c.Type=@Type        
   and (@CustomerCode = 0 OR a.CustomerCode=@CustomerCode)   
     
   */       
        
        
        
END
GO

