CREATE PROCEDURE [dbo].[SAL_Rpt_LCReport_Hlp_LCNo](@CustomerCode int, @BranchID Varchar(3), @CompID Varchar(3))    
    
AS    
    
BEGIN    
    
  SET NOCOUNT ON    
      
    
   Select a.LCNo, a.LCDate, a.CustomerCode, PartyName, a.LCAmount     
   From SAL_LC_Dtl a    
   Left Outer Join  FAS_Party_Master b     
   On a.CustomerCode=b.PartyCode and b.BranchID=a.BranchID and b.CompId=a.CompId    
   Where a.BranchID=@BranchID and a.CompID=@CompId    
   and (@CustomerCode = 0 OR a.CustomerCode=@CustomerCode)    
       
END
GO

/****** Object:  StoredProcedure [dbo].[SAL_Rpt_SalesPackagingSlipList_Gen]    Script Date: 17/06/2026 11:31:02 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SAL_Rpt_SalesPackagingSlipList_Gen](@InvNo int, @BranchId varchar(3), @CompId varchar(3), @Finyear varchar(20))
As
BEGIN
	SET NOCOUNT ON;

	Select a.InvoiceNo, a.InvoiceDate, a.CustomerCode, b.PartyName as CustomerName, a.NoofPackets, a.ItemCode, c.ItemDescription,
		   IsNull((Select  Top 1 PartNo From PartMast 
			 Where StageCode=a.ItemCode and BranchID=a.BranchID and CompID=a.CompID),'') as PartNo,
		a.InvoiceQty, m.PacketNo,
		Convert(int, a.InvoiceQty/a.NoofPackets) +
			Case When m.PacketNo<=a.InvoiceQty-Convert(int, a.InvoiceQty/a.NoofPackets)*a.NoofPackets Then 1 Else 0 End as PacketQty   
	 from 
	 (
		Select InvoiceNo, InvoiceDate, CustomerCode, ItemCode, InvoiceQty, 
			Case When NoofPackets=0 Then 1 Else NoofPackets End as NoofPackets,
			BranchID, CompID  
		From SalesInvoice 
		Where InvoiceNo=@InvNo and Branchid=@BranchID and Compid=@CompID and Finyear=@Finyear
	 ) a
	 Left Outer Join FAS_Party_Master b
		On b.PartyCode=a.CustomerCode and b.BranchID=a.BranchID and b.CompID=a.CompID
	 Left Outer Join INV_Material_Master c
		On c.Itemcode=a.Itemcode and c.BranchID=a.BranchID and c.CompID=a.CompID
	 CROSS APPLY
		(
			Select n.PacketNo 
			From
				(Select ROW_NUMBER()OVER(Order By object_id) as PacketNo From sys.all_objects) n
			Where n.PacketNo<=Case When a.NoofPackets=0 Then 1 Else a.NoofPackets End
		) m
	 Order by a.InvoiceNo, a.InvoiceDate, m.PacketNo
END
GO

/****** Object:  StoredProcedure [dbo].[SAL_Rpt_Traceability_Documentwise_Report_Test]    Script Date: 17/06/2026 11:31:02 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SAL_Rpt_Traceability_Documentwise_Report_Test](@ItemUserKey varchar(36)='', @ItemCode varchar(20)='', @DocType varchar(3), @DocNo int, 
	@DocDate datetime, @BranchID varchar(3), @CompID varchar(3), @FinYear varchar(20) )                        
AS                        
BEGIN         
               
    SET NOCOUNT ON;                  
         
    Declare @TransactionDate datetime      
    Declare @TransactionTime datetime      
      
    Select @TransactionDate=TransactionDate, @TransactionTime=TransactionTime      
    From INV_MaterialTran_Dtl a        
    Where a.DocType=@DocType and a.DocNo=@DocNo and a.DocDate=@DocDate and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear                 
             
    Select distinct d.TransactionItem as ItemCode, d.FromItem, d.toitem, e.ItemDescription as ItemDesc, h.SDesc as UOMDesc, h.NoofDecimals as UOMDecimal,                   
        d.DocType as DocType, d.DocNo as DocNo, d.DocDate as DocDate,b.LotID, c.Qty, c.FromWarehouseCode, c.FromRackBinCode,                   
        c.ToWarehouseCode, c.ToRackBinCode, a.TransactionDate, isnull(g.HeatNo,IsNull('test1','')) As HeatNo      --isnull(g.HeatNo,IsNull(f.HeatNo,'')) As HeatNo          
    From INV_MaterialTran_Dtl a            
             
    Left Outer Join COM_Trace_MaterialTran_TmpQty b                  
        On a.ICode=b.TranID and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear               
                  
    Left Outer Join COM_Trace_MaterialTran_TmpQty c                  
        On   b.LotID=c.LotID and b.BranchID=c.BranchID and b.CompID=c.CompID and b.Finyear=c.Finyear                 
               
    Left Outer Join           
        (          
            Select * From INV_MaterialTran_Dtl a                        
            Where a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear            
                and Exists           
                (          
                    Select * From BOM_TraceableItems t           
                    Where t.ItemCode=a.TransactionItem          
                ) 
				and ((@ItemCode<>'' and @ItemUserKey='' and Exists(Select * From MPS_Process m  
					Where m.ItemCode=@ItemCode 
						and (m.ItemCode=a.TransactionItem or m.StageCode=a.TransactionItem or m.StageCode=a.ToItem)                                                  
						and m.BranchId=a.BranchId and m.CompID=a.CompID
					))
					or
                 (@ItemUserKey='' or (@ItemUserKey<>'' and Exists(Select * From MPS_Process m        
										Where Exists(Select * From COM_SelectList  n                
													Where n.UserKey=@ItemUserKey and n.SelectStr=m.ItemCode and n.BranchID=@BranchID and n.CompID=@CompID                 
													)          
                                    and (m.ItemCode=a.TransactionItem or m.StageCode=a.TransactionItem or m.StageCode=a.ToItem)                                                    
                                    and m.BranchId=a.BranchId and m.CompID=a.CompID      
									))           
                    ))     
                                  
            Union All          
          
            Select -(ICode), DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode,          
                ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear           
            From INV_WIPTRAN_DTL a                        
            Where a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear                            
                and not exists          
                    (          
                        Select * From INV_MaterialTran_Dtl s        
                        Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate           
                            and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode          
                            and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode           
                            and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem           
                            and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear          
                    )           
                and Exists           
                    (          
                        Select * From BOM_TraceableItems t           
                        Where t.ItemCode=a.TransactionItem          
                    ) 
				and ((@ItemCode<>'' and @ItemUserKey='' and Exists(Select * from MPS_Process m  
						Where m.ItemCode=@ItemCode 
							and (m.ItemCode=a.TransactionItem or m.StageCode=a.TransactionItem or m.StageCode=a.ToItem)                                                  
							and m.BranchId=a.BranchId and m.CompID=a.CompID
					 )) 
					or
					(@ItemUserKey='' or (@ItemUserKey<>'' and Exists(Select * from MPS_Process m        
									Where Exists(Select * From COM_SelectList  n                
											Where n.UserKey=@ItemUserKey and n.SelectStr=m.ItemCode and n.BranchID=@BranchID and n.CompID=@CompID                  
											)          
										and (m.ItemCode=a.TransactionItem or m.StageCode=a.TransactionItem or m.StageCode=a.ToItem)       										         
										and m.BranchId=a.BranchId and m.CompID=a.CompID        
								))           
					))             
        ) d                
        On c.TranID=d.ICode and c.BranchID=d.BranchID and c.CompID=d.CompID and c.Finyear=d.Finyear                  
            
    Left Outer Join INV_Material_Master e                   
        On d.TransactionItem=e.ItemCode and d.BranchID=e.BranchID and d.CompID=e.CompID          
              
    Left Outer Join INV_UOM_Master  h            
        On e.UOM=h.Code and e.BranchID=h.BranchID and e.CompID=h.CompID            
                  
    Left Outer Join COM_Trace_LotMaster_TmpQty g                  
        On b.LotID=g.LotID and b.BranchID=g.BranchID and b.CompID=g.CompID            

    Where a.BranchID=@BranchID and a.CompID= @CompID and a.Finyear= @Finyear and d.TransactionItem is Not null                 
        and a.DocType=@DocType and a.DocNo=@DocNo and a.DocDate=@DocDate                
        and d.TransactionDate + ' ' + d.TransactionTime <= @TransactionDate + ' ' +   @TransactionTime
		and ((@ItemCode<>'' and @ItemUserKey='' and Exists(Select * From MPS_Process m  
					Where m.ItemCode=@ItemCode 
						and (m.ItemCode=a.TransactionItem or m.StageCode=a.TransactionItem or m.StageCode=a.ToItem)                                                  
						and m.BranchId=a.BranchId and m.CompID=a.CompID
					))
					or
					(@ItemUserKey='' or (@ItemUserKey<>'' and Exists(Select * From MPS_Process m        
								Where Exists(Select * From COM_SelectList  n                
										Where n.UserKey=@ItemUserKey and n.SelectStr=m.ItemCode and n.BranchID=@BranchID and n.CompID=@CompID                  
									)          
								and (m.ItemCode=d.TransactionItem or m.StageCode=d.TransactionItem or m.StageCode=d.ToItem)        								        
								and m.BranchId=d.BranchId and m.CompID=d.CompID     
								))           
					))                       
    Order by a.TransactionDate Desc
END      
GO

/****** Object:  StoredProcedure [dbo].[SAL_Rpt_Traceability_Stagewise_Report_Test]    Script Date: 17/06/2026 11:31:02 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SAL_Rpt_Traceability_Stagewise_Report_Test](@DocType varchar(3), @DocNo int, @DocDate datetime, @ItemCode varchar(20)='', 
	@IsDocFiltered bit='0', @IsOpenBalRptNeeded As bit='0', @IsZeroOBal As bit='0', @IsStockLedgerRptNeeded As bit='0', @StockItemCode varchar(20),
	@FromDate datetime, @ToDate datetime, @StockWarehouseCode varchar(6), @AsOnDate datetime, @BranchID varchar(3), @CompID varchar(3), @FinYear varchar(20))                        
AS                        
BEGIN                        
    SET NOCOUNT ON;

	DECLARE @BaseTran As Table
	(
		ICode int,
		DOCType varchar(5),
		DOCNo int,
		DOCDate datetime,
		TransactionDate datetime,
		TransactionTime datetime,
		Tran_DateTime datetime, 
		TransactionItem varchar(20), 
		Norms float,
		HeatNo varchar(20),
		LotID int,
		Tran_Qty float,		
		FromWarehouseCode varchar(6), 
		From_WarehouseName varchar(50), 
		FromRackBinCode varchar(6),          
        ToWarehouseCode varchar(6), 
		To_WarehouseName varchar(50), 
		ToRackBinCode varchar(6), 
		ItemGroupKey int,
		FromItem varchar(20), 
		ToItem varchar(20), 
		Justification varchar(30), 
		LIFO float, 
		FIFO float, 
		WA float, 
		UserID varchar(10), 
		BranchID varchar(3), 
		CompID varchar(3), 
		Finyear varchar(20),	
		SetSeq int
	)

	DECLARE @StockOpenBal As Table
	(
		ItemCode varchar(20),
		ItemDescription varchar(50),
		RevisionNo varchar(10),
		OBQty float,
		TranIssuedQty float,
		TranReceivedQty float,
		Rate float, 
		BranchID varchar(3), 
		CompID varchar(3), 
		Finyear varchar(20),	
		SetSeq int
	)

	DECLARE @StockLedger As Table
	(	
		TransactionDateTime datetime,
		DocType varchar,
		DocNo int,
		DocDate datetime,
		ItemCode varchar(20),
		IssuedQty float,
		ReceivedQty float,
		BranchID varchar(3), 
		CompID varchar(3), 
		Finyear varchar(20),	
		SetSeq int
	)
	
	Declare @MaxTranDateTime datetime     
    
	/* Get Max. Tran Date & Time */
	Begin
		Select @MaxTranDateTime = Convert(datetime,(Convert(varchar(10),a.TransactionDate,121) + ' ' + Convert(varchar(8),a.TransactionTime,108)),121)	
		From INV_MaterialTran_Dtl a        
		Where a.DocType=@DocType and a.DocNo=@DocNo and a.DocDate=@DocDate 
			and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear 
	End

	/* Insert Data Into Temp Table */
	Begin
		Insert Into @BaseTran
		Select Distinct x.ICode, x.DOCType, x.DOCNo, x.DOCDate, x.TransactionDate, x.TransactionTime, 
			x.TransactionDate As Tran_DateTime, 
			x.TransactionItem, x.Norms, '' As HeatNo, 0 As LotID,  x.TransactionQty As Tran_Qty, 
			x.FromWarehouseCode, '' As From_WarehouseName, x.FromRackBinCode, x.ToWarehouseCode, '' As To_WarehouseName, 
			x.ToRackBinCode, x.ItemGroupKey, x.FromItem, x.ToItem, x.Justification, x.LIFO, x.FIFO, x.WA, 
			x.UserID, x.BranchID, x.CompID, x.Finyear, x.SetSeq
		From (          
				Select a.ICode, a.DOCType, a.DOCNo, a.DOCDate, a.TransactionDate, a.TransactionTime, a.TransactionItem, a.TransactionQty, 
					a.Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, a.ItemGroupKey, a.FromItem, 
					a.ToItem, a.Justification, a.LIFO, a.FIFO, a.WA, a.UserID, a.BranchID, a.CompID, a.Finyear, 1 As SetSeq    
				From vw_INV_MaterialTran_Dtl a                        
				Where a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear  
					and a.TransactionDate<=@MaxTranDateTime
					and Exists(Select * From BOM_TraceableItems t 
								Where t.ItemCode=a.TransactionItem) 
					and (@ItemCode<>'' and Exists(Select * From MPS_Process m  
						Where m.ItemCode=@ItemCode 
							and (m.ItemCode=a.TransactionItem or m.StageCode=a.TransactionItem)		-- or m.StageCode=a.ToItem)                                                  
							and m.BranchId=a.BranchId and m.CompID=a.CompID
						))					
                                  
				UNION ALL
          
				Select -(a.ICode), a.DOCType, a.DOCNo, a.DOCDate, a.TransactionDate, a.TransactionTime, a.TransactionItem, a.TransactionQty, 
					a.Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, a.ItemGroupKey, a.FromItem, 
					a.ToItem, a.Justification, a.LIFO, a.FIFO, a.WA, a.UserID, a.BranchID, a.CompID, a.Finyear, 2 As SetSeq           
				From vw_INV_WIPTRAN_DTL a                        
				Where a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear 
					and a.TransactionDate<=@MaxTranDateTime
					and Not Exists( Select * From INV_MaterialTran_Dtl s        
							Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate           
								and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode          
								and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode           
								and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem           
								and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear          
						)           
					and Exists(Select * From BOM_TraceableItems t 
								Where t.ItemCode=a.TransactionItem) 
					and (@ItemCode<>'' and Exists(Select * from MPS_Process m  
							Where m.ItemCode=@ItemCode 
								and (m.ItemCode=a.TransactionItem or m.StageCode=a.TransactionItem)			-- or m.StageCode=a.ToItem)                                                  
								and m.BranchId=a.BranchId and m.CompID=a.CompID
						 )) 					        
			) x
			Where x.BranchID=@BranchID and x.CompID= @CompID and x.Finyear= @Finyear and (x.TransactionItem is Not null)
				and (@IsDocFiltered='0' or (@IsDocFiltered='1' and x.DocType=@DocType and x.DocNo=@DocNo and x.DocDate=@DocDate))				                   
			--Order by x.SetSeq, Tran_DateTime Desc     
	End
	Begin
		Insert Into @BaseTran
		Select Distinct a.ICode, a.DOCType, a.DOCNo, a.DOCDate, a.TransactionDate, a.TransactionTime, 
				a.Tran_DateTime, a.TransactionItem, a.Norms, IsNull(d.HeatNo,'') As HeatNo, b.LotID, c.Qty As Tran_Qty,			--a.TransactionQty, 				 
				c.FromWarehouseCode, IsNull(e.From_WarehouseName,'') As From_WarehouseName, c.FromRackBinCode, 
				c.ToWarehouseCode, IsNull(e.To_WarehouseName,'') As To_WarehouseName, c.ToRackBinCode, 		
				a.ItemGroupKey, a.FromItem, a.ToItem, a.Justification, a.LIFO, a.FIFO, a.WA, a.UserID, 
				a.BranchID, a.CompID, a.Finyear, 3 As SetSeq 
		From @BaseTran a
		 Left Outer Join COM_Trace_MaterialTran_TmpQty b                  
			On a.ICode=b.TranID -- and a.TransactionItem=b.ItemCode
				and Convert(varchar(19),b.TranStamp,121) <= Convert(varchar(19),@MaxTranDateTime,121)
				and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear               
                  
		Left Outer Join COM_Trace_MaterialTran_TmpQty c                  
			On b.LotID=c.LotID --and a.TransactionItem=c.ItemCode  
				and Convert(varchar(10),a.TransactionDate,121) + ' ' + Convert(varchar(8),a.TransactionTime,108)=Convert(varchar(19),c.TranStamp,121)
				and Convert(varchar(19),c.TranStamp,121) <= Convert(varchar(19),@MaxTranDateTime,121)
				and b.BranchID=c.BranchID and b.CompID=c.CompID and b.Finyear=c.Finyear

		Left Outer Join COM_Trace_LotMaster_TmpQty d                  
			On b.LotID=d.LotID --and a.TransactionItem=d.ItemCode 
				and Convert(varchar(19),d.TranStamp,121) <= Convert(varchar(19),@MaxTranDateTime,121)
				and b.BranchID=d.BranchID and b.CompID=d.CompID

		Left Outer Join (Select bt.FromWarehouseCode, bt.ToWarehouseCode,
				(Case When ISNUMERIC(bt.FromWarehouseCode)=1 Then p1.PartyName + ' (' + (Case When p1.AcType='D' Then 'Customer' When p1.AcType='C' Then 'Vendor' Else 'Party' End) + ')'
					When ISNUMERIC(bt.FromWarehouseCode)<>1 and bt.FromWarehouseCode=w1.WarehouseCode Then w1.WarehouseName 
					When ISNUMERIC(bt.FromWarehouseCode)<>1 and bt.FromWarehouseCode=d1.DocumentType Then d1.DocumentType
					Else bt.FromWarehouseCode End) As From_WarehouseName,
				(Case When ISNUMERIC(bt.ToWarehouseCode)=1 Then p2.PartyName + ' (' + (Case When p2.AcType='D' Then 'Customer' When p2.AcType='C' Then 'Vendor' Else 'Party' End) + ')'
					When ISNUMERIC(bt.ToWarehouseCode)<>1 and bt.ToWarehouseCode=w2.WarehouseCode Then w2.WarehouseName 
					When ISNUMERIC(bt.ToWarehouseCode)<>1 and bt.ToWarehouseCode=d2.DocumentType Then d2.DocumentType
					Else bt.ToWarehouseCode End) As To_WarehouseName,
					bt.SetSeq, bt.BranchID, bt.CompID, bt.Finyear
			From @BaseTran bt
			Left Outer Join FAS_Party_Master p1
				On bt.FromWarehouseCode=Convert(varchar(10),p1.PartyCode) and p1.BranchID=bt.BranchID and p1.CompID=bt.CompID
			Left Outer Join FAS_Party_Master p2
				On bt.ToWarehouseCode=Convert(varchar(10),p2.PartyCode) and p2.BranchID=bt.BranchID and p2.CompID=bt.CompID
			Left Outer Join INV_Warehouse_Master w1
				On bt.FromWarehouseCode= w1.WarehouseCode and w1.BranchID=bt.BranchID and w1.CompID=bt.CompID
			Left Outer Join INV_Warehouse_Master w2
				On bt.ToWarehouseCode= w2.WarehouseCode and w2.BranchID=bt.BranchID and w2.CompID=bt.CompID
			Left Outer Join COM_DocumentType_Master d1
				On bt.FromWarehouseCode= d1.DocumentType and d1.BranchID=bt.BranchID and d1.CompID=bt.CompID
			Left Outer Join COM_DocumentType_Master d2
				On bt.ToWarehouseCode= d2.DocumentType and d2.BranchID=bt.BranchID and d2.CompID=bt.CompID
			Where bt.SetSeq=3
		) e
		On a.SetSeq=e.SetSeq and a.FromWarehouseCode=e.FromWarehouseCode and a.ToWarehouseCode=e.ToWarehouseCode
			and a.BranchID=e.BranchID and a.CompID=e.CompID and a.Finyear=e.Finyear
		Where a.Setseq In(1,2) and a.BranchID=@BranchID and a.CompID= @CompID and a.Finyear= @Finyear 
			and (a.TransactionItem is Not null)
	End

	/* Output (Result) */
	Select Distinct a.ICode, a.DOCType, a.DOCNo, a.DOCDate, a.TransactionDate, a.TransactionTime, 
				a.Tran_DateTime, a.TransactionItem, b.ItemDescription, c.SDesc As UOM, a.Norms, 
				IsNull(a.HeatNo,'') As HeatNo, a.LotID, a.Tran_Qty,			--a.TransactionQty, 
				a.FromWarehouseCode, IsNull(a.From_WarehouseName,'') As From_WarehouseName,
				IsNull(a.FromRackBinCode,'') As FromRackBinCode, a.ToWarehouseCode, 
				IsNull(a.To_WarehouseName,'') As To_WarehouseName, IsNull(a.ToRackBinCode,'') As ToRackBinCode, 
				a.ItemGroupKey, a.FromItem, a.ToItem, a.Justification, a.LIFO, a.FIFO, a.WA, 
				a.UserID, a.BranchID, a.CompID, a.Finyear, a.SetSeq
	From @BaseTran a
	Left Outer Join INV_Material_Master b                  
        On a.TransactionItem=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID                        
    Left Outer Join INV_UOM_Master c        
        On b.UOM=c.Code and a.BranchID=c.BranchID and a.CompID=c.CompID	
	Where a.SetSeq=3
	Order by a.SetSeq, a.Tran_DateTime

	-- > ** Opening Balance Report ** <-- ************************** -------------------------------------
	If @IsOpenBalRptNeeded='1'
	Begin
		Select Distinct a.ItemCode, a.WarehouseCode, a.RackBinCode, a.CBQty As OpeningBalance, b.ItemDescription, w.WarehouseCode,
			(Case When IsNull(a.WarehouseCode,'')<>'' and IsNull(t.FromWarehouseCode,'')<>'' and a.WarehouseCode=t.FromWarehouseCode Then t.From_WarehouseName 
				When IsNull(a.WarehouseCode,'')<>'' and IsNull(t.ToWarehouseCode,'')<>'' and a.WarehouseCode=t.ToWarehouseCode Then t.To_WarehouseName 
				When IsNull(a.WarehouseCode,'')<>'' and IsNull(w.WarehouseName,'')<>'' Then w.WarehouseName Else a.WarehouseCode End) As WarehouseName,
			IsNull(b.Rate,0) As Rate, b.UOMDesc, b.UOMDecimal 
		From Inv_Stock_Master a
		Inner Join @BaseTran t
			On t.SetSeq=3 and a.ItemCode=t.TransactionItem and a.BranchID=t.BranchID and a.CompID=t.CompID and t.Finyear=@Finyear
		Left Outer Join INV_Warehouse_Master w
			On a.WarehouseCode=w.WarehouseCode and a.BranchID=w.BranchID and a.CompID=w.CompID 
		Left Outer Join Material_Master b 
			On a.ItemCode = b.ItemCode and a.BranchID = b.BranchID and a.CompID = b.CompID 
		Where (@IsZeroOBal='0' or (@IsZeroOBal='1' and a.CBQty>0))			
			and a.BranchID=@BranchID and a.CompID=@CompID
		Order By WarehouseName
	End	
	-- *************************************************************** -----------------------------------
	-- > ** Stock Ledger Report ** <-- ******************************** ----------------------------------
	If @IsStockLedgerRptNeeded='1'
	Begin
		/* Insert Data Into Temp Table */
		Insert Into @StockOpenBal
		  Select m.ItemCode, n.ItemDescription, n.RevisionNo, Sum(OBQty) As OBQty, Sum(TranIssuedQty) As TranIssuedQty, 
				Sum(TranReceivedQty) As TranReceivedQty, IsNull([dbo].[fn_Sal_ItemRate_Latest] (m.Itemcode, @BranchID, @CompID, @FinYear), n.Rate) As Rate, 
				m.BranchID, m.CompID, m.Finyear, 1 As SetSeq 
			From (Select a.DocType, a.DocNo, a.DocDate,  
					Case when (a.TransactionDate<@FromDate or a.DocType='OpBal') then 
					Case When ToWarehouseCode=@StockWarehouseCode Then TransactionQty Else -TransactionQty End Else 0 End As OBQty, 
					Case when ((a.TransactionDate Between @FromDate and @ToDate) and a.DocType<>'OpBal') then 
					Case When FromWarehouseCode=@StockWarehouseCode Then TransactionQty Else 0 End Else 0 End As TranIssuedQty, 
					Case when ((a.TransactionDate Between @FromDate and @ToDate) and a.DocType<>'OpBal') then 
					Case When ToWarehouseCode=@StockWarehouseCode Then TransactionQty Else 0 End Else 0 End As TranReceivedQty, 
					a.TransactionItem As ItemCode, Case When FromWarehouseCode='FGS' Then TransactionQty Else 0 End As IssuedQty, 
					Case When ToWarehouseCode=@StockWarehouseCode Then TransactionQty Else 0 End As ReceivedQty,
					a.BranchID, a.CompID, a.Finyear
				From INV_MaterialTran_Dtl a  
				Where a.TransactionDate<=@ToDate
					and ((a.FromWarehouseCode=@StockWarehouseCode and a.FromRackBinCode='') or (a.ToWarehouseCode=@StockWarehouseCode) and (a.ToRackBinCode='')) 
					and (@StockItemCode='' or (@StockItemCode<>'' and a.TransactionItem=@StockItemCode)) and a.BranchID=@BranchID and a.compID=@CompID
			) m 
			Left Outer Join INV_Material_Master n 
				On m.ItemCode=n.ItemCode 
			Where n.ItemNature='F' and n.BranchID=@BranchID and n.CompID=@CompID
			Group by m.ItemCode, n.revisionNo, n.ItemDescription, n.Rate, m.BranchID, m.CompID, m.Finyear 
			Order by m.ItemCode
		End

		Begin
			/* Insert Data Into Temp Table */
			Insert Into @StockLedger
			Select Convert(varchar(10),m.TransactionDate,121) + ' ' +  Convert(varchar(8),m.TransactionTime,108) As TransactionDateTime, 
				m.DocType, m.DocNo, m.DocDate, m.ItemCode,  m.IssuedQty, m.ReceivedQty, m.BranchID, m.CompID, m.Finyear, 1 As SetSeq 
			from (Select a.TransactionDate, a.TransactionTime, a.DocType, a.DocNo, a.DocDate, a.TransactionItem As ItemCode, 
					Case When FromWarehouseCode=@StockWarehouseCode Then TransactionQty Else 0 End As IssuedQty, 
					Case When ToWarehouseCode=@StockWarehouseCode Then TransactionQty Else 0 End As ReceivedQty,
                    a.BranchID, a.CompID, a.Finyear
				From INV_MaterialTran_Dtl a 
				where a.DocType<>'OpBal' and (a.TransactionDate Between @FromDate and @ToDate) 
					and (FromWarehouseCode=@StockWarehouseCode or ToWarehouseCode=@StockWarehouseCode) and (FromRackBinCode='' or ToRackBinCode='') 
					and (@StockItemCode='' or (@StockItemCode<>'' and a.TransactionItem=@StockItemCode))
					and a.Branchid=@BranchID and a.compid=@CompID
				) m 
			Left Outer Join INV_Material_Master n
				On m.ItemCode=n.ItemCode 
			where n.Branchid=@BranchID and n.CompID=@CompID and n.ItemNature='F' 
				and (IssuedQty<>0 or ReceivedQty<>0) 
			Order by m.ItemCode, m.TransactionDate, m.TransactionTime
		End

		/* Stock Output (Result) */

		Select * From @StockOpenBal a Where a.SetSeq=1
		Select * From @StockLedger a Where a.SetSeq=1
	-- *************************************************************** -----------------------------------
 END
GO

/****** Object:  StoredProcedure [dbo].[SAL_Rpt_Traceability_Stagewise_Report_Test2]    Script Date: 17/06/2026 11:31:02 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SAL_Rpt_Traceability_Stagewise_Report_Test2](@DocType varchar(3), @DocNo int, @DocDate datetime, @ItemCode varchar(20)='', 
	@IsDocFiltered bit='0', @IsOBalRptNeeded As bit='0', @IsZeroOBal As bit='0', @AsOnDate datetime, 
	@BranchID varchar(3), @CompID varchar(3), @FinYear varchar(20))                        
AS                        
BEGIN                        
    SET NOCOUNT ON;

	DECLARE @BaseTran As Table
	(
		ICode int,
		DOCType varchar(5),
		DOCNo int,
		DOCDate datetime,
		TransactionDate datetime,
		TransactionTime datetime,
		Tran_DateTime datetime, 
		TransactionItem varchar(20), 
		Norms float,
		HeatNo varchar(20),
		LotID int,
		Tran_Qty float,		
		FromWarehouseCode varchar(6), 
		From_WarehouseName varchar(50), 
		FromRackBinCode varchar(6),          
        ToWarehouseCode varchar(6), 
		To_WarehouseName varchar(50), 
		ToRackBinCode varchar(6), 
		ItemGroupKey int,
		FromItem varchar(20), 
		ToItem varchar(20), 
		Justification varchar(30), 
		LIFO float, 
		FIFO float, 
		WA float, 
		UserID varchar(10), 
		BranchID varchar(3), 
		CompID varchar(3), 
		Finyear varchar(20),	
		SetSeq int
	)
	
	Declare @MaxTranDateTime datetime     
    
	/* Get Max. Tran Date & Time */
	Begin
		Select @MaxTranDateTime = Convert(datetime,(Convert(varchar(10),a.TransactionDate,121) + ' ' + Convert(varchar(8),a.TransactionTime,108)),121)	
		From INV_MaterialTran_Dtl a        
		Where a.DocType=@DocType and a.DocNo=@DocNo and a.DocDate=@DocDate 
			and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear 
	End

	/* Insert Data Into Temp Table */
	Begin
		Insert Into @BaseTran
		Select Distinct x.ICode, x.DOCType, x.DOCNo, x.DOCDate, x.TransactionDate, x.TransactionTime, 
			Convert(varchar(10),x.TransactionDate,121) + ' ' + Convert(varchar(8),x.TransactionTime,108) As Tran_DateTime, 
			x.TransactionItem, x.Norms, '' As HeatNo, 0 As LotID,  x.TransactionQty As Tran_Qty, 
			x.FromWarehouseCode, '' As From_WarehouseName, x.FromRackBinCode, x.ToWarehouseCode, '' As To_WarehouseName, 
			x.ToRackBinCode, x.ItemGroupKey, x.FromItem, x.ToItem, x.Justification, x.LIFO, x.FIFO, x.WA, 
			x.UserID, x.BranchID, x.CompID, x.Finyear, x.SetSeq
		From (          
				Select a.ICode, a.DOCType, a.DOCNo, a.DOCDate, a.TransactionDate, a.TransactionTime, a.TransactionItem, a.TransactionQty, 
					a.Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, a.ItemGroupKey, a.FromItem, 
					a.ToItem, a.Justification, a.LIFO, a.FIFO, a.WA, a.UserID, a.BranchID, a.CompID, a.Finyear, 1 As SetSeq    
				From INV_MaterialTran_Dtl a                        
				Where a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear  
					and Convert(varchar(10),a.TransactionDate,121) + ' ' + Convert(varchar(8),a.TransactionTime,108) <= Convert(varchar(19),@MaxTranDateTime,121)
					and Exists(Select * From BOM_TraceableItems t 
								Where t.ItemCode=a.TransactionItem) 
					and (@ItemCode<>'' and Exists(Select * From MPS_Process m  
						Where m.ItemCode=@ItemCode 
							and (m.ItemCode=a.TransactionItem or m.StageCode=a.TransactionItem)		-- or m.StageCode=a.ToItem)                                                  
							and m.BranchId=a.BranchId and m.CompID=a.CompID
						))					
                                  
				UNION ALL
          
				Select -(a.ICode), a.DOCType, a.DOCNo, a.DOCDate, a.TransactionDate, a.TransactionTime, a.TransactionItem, a.TransactionQty, 
					a.Norms, a.FromWarehouseCode, a.FromRackBinCode, a.ToWarehouseCode, a.ToRackBinCode, a.ItemGroupKey, a.FromItem, 
					a.ToItem, a.Justification, a.LIFO, a.FIFO, a.WA, a.UserID, a.BranchID, a.CompID, a.Finyear, 2 As SetSeq           
				From INV_WIPTRAN_DTL a                        
				Where a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear 
					and Convert(varchar(10),a.TransactionDate,121) + ' ' + Convert(varchar(8),a.TransactionTime,108) <= Convert(varchar(19),@MaxTranDateTime,121)
					and Not Exists( Select * From INV_MaterialTran_Dtl s        
							Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate           
								and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode          
								and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode           
								and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem           
								and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear          
						)           
					and Exists(Select * From BOM_TraceableItems t 
								Where t.ItemCode=a.TransactionItem) 
					and (@ItemCode<>'' and Exists(Select * from MPS_Process m  
							Where m.ItemCode=@ItemCode 
								and (m.ItemCode=a.TransactionItem or m.StageCode=a.TransactionItem)			-- or m.StageCode=a.ToItem)                                                  
								and m.BranchId=a.BranchId and m.CompID=a.CompID
						 )) 					        
			) x
			Where x.BranchID=@BranchID and x.CompID= @CompID and x.Finyear= @Finyear and (x.TransactionItem is Not null)
				and (@IsDocFiltered='0' or (@IsDocFiltered='1' and x.DocType=@DocType and x.DocNo=@DocNo and x.DocDate=@DocDate))				                   
			--Order by x.SetSeq, Tran_DateTime Desc     
	End
	Begin
		Insert Into @BaseTran
		Select Distinct a.ICode, a.DOCType, a.DOCNo, a.DOCDate, a.TransactionDate, a.TransactionTime, 
				a.Tran_DateTime, a.TransactionItem, a.Norms, IsNull(d.HeatNo,'') As HeatNo, b.LotID, c.Qty As Tran_Qty,			--a.TransactionQty, 				 
				c.FromWarehouseCode, IsNull(e.From_WarehouseName,'') As From_WarehouseName, c.FromRackBinCode, 
				c.ToWarehouseCode, IsNull(e.To_WarehouseName,'') As To_WarehouseName, c.ToRackBinCode, 		
				a.ItemGroupKey, a.FromItem, a.ToItem, a.Justification, a.LIFO, a.FIFO, a.WA, a.UserID, 
				a.BranchID, a.CompID, a.Finyear, 3 As SetSeq 
		From @BaseTran a
		 Left Outer Join COM_Trace_MaterialTran_TmpQty b                  
			On a.ICode=b.TranID -- and a.TransactionItem=b.ItemCode
				and Convert(varchar(19),b.TranStamp,121) <= Convert(varchar(19),@MaxTranDateTime,121)
				and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear               
                  
		Left Outer Join COM_Trace_MaterialTran_TmpQty c                  
			On b.LotID=c.LotID --and a.TransactionItem=c.ItemCode  
				and Convert(varchar(10),a.TransactionDate,121) + ' ' + Convert(varchar(8),a.TransactionTime,108)=Convert(varchar(19),c.TranStamp,121)
				and Convert(varchar(19),c.TranStamp,121) <= Convert(varchar(19),@MaxTranDateTime,121)
				and b.BranchID=c.BranchID and b.CompID=c.CompID and b.Finyear=c.Finyear

		Left Outer Join COM_Trace_LotMaster_TmpQty d                  
			On b.LotID=d.LotID --and a.TransactionItem=d.ItemCode 
				and Convert(varchar(19),d.TranStamp,121) <= Convert(varchar(19),@MaxTranDateTime,121)
				and b.BranchID=d.BranchID and b.CompID=d.CompID

		Left Outer Join (Select bt.FromWarehouseCode, bt.ToWarehouseCode,
				(Case When ISNUMERIC(bt.FromWarehouseCode)=1 Then p1.PartyName + ' (' + (Case When p1.AcType='D' Then 'Customer' When p1.AcType='C' Then 'Vendor' Else 'Party' End) + ')'
					When ISNUMERIC(bt.FromWarehouseCode)<>1 and bt.FromWarehouseCode=w1.WarehouseCode Then w1.WarehouseName 
					When ISNUMERIC(bt.FromWarehouseCode)<>1 and bt.FromWarehouseCode=d1.DocumentType Then d1.DocumentType
					Else bt.FromWarehouseCode End) As From_WarehouseName,
				(Case When ISNUMERIC(bt.ToWarehouseCode)=1 Then p2.PartyName + ' (' + (Case When p2.AcType='D' Then 'Customer' When p2.AcType='C' Then 'Vendor' Else 'Party' End) + ')'
					When ISNUMERIC(bt.ToWarehouseCode)<>1 and bt.ToWarehouseCode=w2.WarehouseCode Then w2.WarehouseName 
					When ISNUMERIC(bt.ToWarehouseCode)<>1 and bt.ToWarehouseCode=d2.DocumentType Then d2.DocumentType
					Else bt.ToWarehouseCode End) As To_WarehouseName,
					bt.SetSeq, bt.BranchID, bt.CompID, bt.Finyear
			From @BaseTran bt
			Left Outer Join FAS_Party_Master p1
				On bt.FromWarehouseCode=Convert(varchar(10),p1.PartyCode) and p1.BranchID=bt.BranchID and p1.CompID=bt.CompID
			Left Outer Join FAS_Party_Master p2
				On bt.ToWarehouseCode=Convert(varchar(10),p2.PartyCode) and p2.BranchID=bt.BranchID and p2.CompID=bt.CompID
			Left Outer Join INV_Warehouse_Master w1
				On bt.FromWarehouseCode= w1.WarehouseCode and w1.BranchID=bt.BranchID and w1.CompID=bt.CompID
			Left Outer Join INV_Warehouse_Master w2
				On bt.ToWarehouseCode= w2.WarehouseCode and w2.BranchID=bt.BranchID and w2.CompID=bt.CompID
			Left Outer Join COM_DocumentType_Master d1
				On bt.FromWarehouseCode= d1.DocumentType and d1.BranchID=bt.BranchID and d1.CompID=bt.CompID
			Left Outer Join COM_DocumentType_Master d2
				On bt.ToWarehouseCode= d2.DocumentType and d2.BranchID=bt.BranchID and d2.CompID=bt.CompID
			Where bt.SetSeq=3
		) e
		On a.SetSeq=e.SetSeq and a.FromWarehouseCode=e.FromWarehouseCode and a.ToWarehouseCode=e.ToWarehouseCode
			and a.BranchID=e.BranchID and a.CompID=e.CompID and a.Finyear=e.Finyear
		Where a.Setseq In(1,2) and a.BranchID=@BranchID and a.CompID= @CompID and a.Finyear= @Finyear 
			and (a.TransactionItem is Not null)
	End

	/* Output (Result) */
	Select Distinct a.ICode, a.DOCType, a.DOCNo, a.DOCDate, a.TransactionDate, a.TransactionTime, 
				a.Tran_DateTime, a.TransactionItem, b.ItemDescription, c.SDesc As UOM, a.Norms, 
				IsNull(a.HeatNo,'') As HeatNo, a.LotID, a.Tran_Qty,			--a.TransactionQty, 
				a.FromWarehouseCode, IsNull(a.From_WarehouseName,'') As From_WarehouseName,
				IsNull(a.FromRackBinCode,'') As FromRackBinCode, a.ToWarehouseCode, 
				IsNull(a.To_WarehouseName,'') As To_WarehouseName, IsNull(a.ToRackBinCode,'') As ToRackBinCode, 
				a.ItemGroupKey, a.FromItem, a.ToItem, a.Justification, a.LIFO, a.FIFO, a.WA, 
				a.UserID, a.BranchID, a.CompID, a.Finyear, a.SetSeq
	From @BaseTran a
	Left Outer Join INV_Material_Master b                  
        On a.TransactionItem=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID                        
    Left Outer Join INV_UOM_Master c        
        On b.UOM=c.Code and a.BranchID=c.BranchID and a.CompID=c.CompID	
	Where a.SetSeq=3
	Order by a.SetSeq, a.Tran_DateTime

	-- > ** Opening Balance Report ** <--
	If @IsOBalRptNeeded='1'
	Begin
		Select Distinct a.ItemCode, a.WarehouseCode, a.RackBinCode, a.CBQty As OpeningBalance, b.ItemDescription, w.WarehouseCode,
			(Case When IsNull(a.WarehouseCode,'')<>'' and IsNull(t.FromWarehouseCode,'')<>'' and a.WarehouseCode=t.FromWarehouseCode Then t.From_WarehouseName 
				When IsNull(a.WarehouseCode,'')<>'' and IsNull(t.ToWarehouseCode,'')<>'' and a.WarehouseCode=t.ToWarehouseCode Then t.To_WarehouseName 
				When IsNull(a.WarehouseCode,'')<>'' and IsNull(w.WarehouseName,'')<>'' Then w.WarehouseName Else a.WarehouseCode End) As WarehouseName,
			IsNull(b.Rate,0) as Rate, b.UOMDesc, b.UOMDecimal 
		From Inv_Stock_Master a
		Inner Join @BaseTran t
			On t.SetSeq=3 and a.ItemCode=t.TransactionItem and a.BranchID=t.BranchID and a.CompID=t.CompID and t.Finyear=@Finyear
		Left Outer Join INV_Warehouse_Master w
			On a.WarehouseCode=w.WarehouseCode and a.BranchID=w.BranchID and a.CompID=w.CompID 
		Left Outer Join Material_Master b 
			On a.ItemCode = b.ItemCode and a.BranchID = b.BranchID and a.CompID = b.CompID 
		Where (@IsZeroOBal='0' or (@IsZeroOBal='1' and a.CBQty>0))			
			and a.BranchID=@BranchID and a.CompID=@CompID
		Order By WarehouseName
	End
-- *************************************************************** -----------------------------------
 END
GO

/****** Object:  StoredProcedure [dbo].[SAL_Rpt_TraceabilityReport_AllSel]    Script Date: 17/06/2026 11:31:02 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SAL_Rpt_TraceabilityReport_AllSel](@ItemUserkey varchar(36)='',@isSelective bit, @FromDate datetime, @ToDate datetime, @AsOnDate datetime, @BranchID varchar(3), @CompID varchar(3), @FinYear Varchar(20))     
                                       
AS                                        
                                      
BEGIN                                        
            
   SET NOCOUNT ON;             
              
    If (@isSelective = Convert(bit, '1'))        
        SELECT * FROM dbo.fn_SAL_Rpt_TraceabilityReport_Sel(@FromDate, @ToDate, @BranchID, @CompID, @FinYear)                                 
       
    Else                                      
        INSERT INTO COM_Selectlist        
          SELECT @ItemUserkey, '', a.ItemCode, @BranchID, @CompID, @AsOnDate        
          FROM dbo.fn_SAL_Rpt_TraceabilityReport_Sel(@FromDate, @ToDate, @BranchID, @CompID, @FinYear) a                
            
END
GO

/****** Object:  StoredProcedure [dbo].[SAL_Rpt_TraceabilityReport_Gen]    Script Date: 17/06/2026 11:31:02 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SAL_Rpt_TraceabilityReport_Gen](@ItemUserKey Varchar(36), @DocType Varchar(3), @DocNo int, @DocDate datetime, @BranchID Varchar(3), @CompID Varchar(3), @FinYear Varchar(20) )                
    
AS       
             
BEGIN       
             
    SET NOCOUNT ON;                
        
		-------------------------------------------------------
	-- 1. Get Transaction Timestamp
	-------------------------------------------------------
	DECLARE @TransactionDate DATETIME,
			@TransactionTime DATETIME;

	SELECT
		@TransactionDate = TransactionDate,
		@TransactionTime = TransactionTime
	FROM INV_MaterialTran_Dtl
	WHERE DocType=@DocType
	AND DocNo=@DocNo
	AND DocDate=@DocDate
	AND BranchID=@BranchID
	AND CompID=@CompID
	AND FinYear=@FinYear;

	-------------------------------------------------------
	-- 2. Anchor Transaction
	-------------------------------------------------------
	CREATE TABLE #AnchorTran
	(
		ICode INT PRIMARY KEY
	);

	INSERT INTO #AnchorTran(ICode)
	SELECT ICode
	FROM INV_MaterialTran_Dtl
	WHERE DocType=@DocType
	AND DocNo=@DocNo
	AND DocDate=@DocDate
	AND BranchID=@BranchID
	AND CompID=@CompID
	AND FinYear=@FinYear;

	-------------------------------------------------------
	-- 3. Load Lots Related To Anchor
	-------------------------------------------------------
	CREATE TABLE #LotList
	(
		LotID VARCHAR(50)
	);

	INSERT INTO #LotList
	SELECT DISTINCT LotID
	FROM COM_Trace_MaterialTran_TmpQty
	WHERE TranID IN (SELECT ICode FROM #AnchorTran)
	AND BranchID=@BranchID
	AND CompID=@CompID
	AND FinYear=@FinYear;

	CREATE INDEX IX_LotList ON #LotList(LotID);

	-------------------------------------------------------
	-- 4. Load All Trace Transactions For Those Lots
	-------------------------------------------------------
	CREATE TABLE #TraceLotTrans
	(
		TranID INT,
		LotID VARCHAR(50),
		Qty DECIMAL(18,6),
		FromWarehouseCode VARCHAR(50),
		FromRackBinCode VARCHAR(50),
		ToWarehouseCode VARCHAR(50),
		ToRackBinCode VARCHAR(50),
		Transtamp DATETIME
	);

	INSERT INTO #TraceLotTrans
	SELECT
		TranID,
		LotID,
		Qty,
		FromWarehouseCode,
		FromRackBinCode,
		ToWarehouseCode,
		ToRackBinCode,
		Transtamp
	FROM COM_Trace_MaterialTran_TmpQty
	WHERE LotID IN (SELECT LotID FROM #LotList)
	AND BranchID=@BranchID
	AND CompID=@CompID
	AND FinYear=@FinYear;

	CREATE INDEX IX_TraceLotTrans
	ON #TraceLotTrans(TranID,LotID);

	-------------------------------------------------------
	-- 5. Trace Transaction Details
	-------------------------------------------------------
	CREATE TABLE #TraceTrans
	(
		ICode INT,
		DocType VARCHAR(10),
		DocNo INT,
		DocDate DATETIME,
		TransactionDate DATETIME,
		TransactionTime DATETIME,
		TransactionItem VARCHAR(50),
		FromItem VARCHAR(50),
		ToItem VARCHAR(50),
		BranchID VARCHAR(3),
		CompID VARCHAR(3),
		FinYear VARCHAR(20)
	);

	INSERT INTO #TraceTrans
	SELECT
		ICode,
		DocType,
		DocNo,
		DocDate,
		TransactionDate,
		TransactionTime,
		TransactionItem,
		FromItem,
		ToItem,
		BranchID,
		CompID,
		FinYear
	FROM INV_MaterialTran_Dtl
	WHERE BranchID=@BranchID
	AND CompID=@CompID
	AND FinYear=@FinYear

	UNION ALL

	SELECT
		-ICode,
		DocType,
		DocNo,
		DocDate,
		TransactionDate,
		TransactionTime,
		TransactionItem,
		FromItem,
		ToItem,
		BranchID,
		CompID,
		FinYear
	FROM INV_WIPTRAN_DTL
	WHERE BranchID=@BranchID
	AND CompID=@CompID
	AND FinYear=@FinYear;

	CREATE INDEX IX_TraceTrans
	ON #TraceTrans(ICode,BranchID,CompID,FinYear);

	-------------------------------------------------------
	-- 6. Final Result
	-------------------------------------------------------
	SELECT
		d.TransactionItem AS ItemCode,
		d.FromItem,
		d.ToItem,
		e.ItemDescription as ItemDesc,
		h.SDesc AS UOMDesc,
		h.NoofDecimals as UOMDecimal,
		d.DocType,
		d.DocNo,
		d.DocDate,
		t.LotID,
		t.Qty,
		t.FromWarehouseCode,
		t.FromRackBinCode,
		t.ToWarehouseCode,
		t.ToRackBinCode,
		t.Transtamp AS TransactionDate,
		ISNULL(g.HeatNo,'') AS HeatNo
	FROM #TraceLotTrans t

	JOIN #TraceTrans d
	ON t.TranID=d.ICode

	LEFT JOIN INV_Material_Master e
	ON d.TransactionItem=e.ItemCode
	AND d.BranchID=e.BranchID
	AND d.CompID=e.CompID

	LEFT JOIN INV_UOM_Master h
	ON e.UOM=h.Code
	AND e.BranchID=h.BranchID
	AND e.CompID=h.CompID

	LEFT JOIN COM_Trace_LotMaster_TmpQty g
	ON t.LotID=g.LotID
