/****** Object:  StoredProcedure [dbo].[SAL_Rpt_TraceabilityReport_Gen_V2]    Script Date: 17/06/2026 11:31:02 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SAL_Rpt_TraceabilityReport_Gen_V2]
(
    @ItemUserKey VARCHAR(36),
    @DocType VARCHAR(3),
    @DocNo INT,
    @DocDate DATETIME,
    @BranchID VARCHAR(3),
    @CompID VARCHAR(3),
    @FinYear VARCHAR(20)
)
AS
BEGIN

SET NOCOUNT ON;

-------------------------------------------------------
-- Get Transaction Timestamp
-------------------------------------------------------

DECLARE @TransactionDate DATETIME,
        @TransactionTime DATETIME

SELECT
    @TransactionDate = TransactionDate,
    @TransactionTime = TransactionTime
FROM INV_MaterialTran_Dtl
WHERE DocType=@DocType
AND DocNo=@DocNo
AND DocDate=@DocDate
AND BranchID=@BranchID
AND CompID=@CompID
AND FinYear=@FinYear


-------------------------------------------------------
-- Process Filter
-------------------------------------------------------

CREATE TABLE #ProcessFilter
(
    ItemCode VARCHAR(50),
    StageCode VARCHAR(50),
    BranchID VARCHAR(3),
    CompID VARCHAR(3)
)

INSERT INTO #ProcessFilter
SELECT
    m.ItemCode,
    m.StageCode,
    m.BranchID,
    m.CompID
FROM MPS_Process m
WHERE EXISTS
(
    SELECT 1
    FROM COM_SelectList n
    WHERE n.UserKey=@ItemUserKey
    AND n.SelectStr=m.ItemCode
    AND n.BranchID=@BranchID
    AND n.CompID=@CompID
)

CREATE INDEX IX_ProcessFilter
ON #ProcessFilter(ItemCode,StageCode,BranchID,CompID)


-------------------------------------------------------
-- Trace Transactions
-------------------------------------------------------

CREATE TABLE #TraceTrans
(
    ICode INT,
    DocType VARCHAR(10),
    DocNo INT,
    DocDate DATETIME,
    TransactionDate DATETIME,
    TransactionTime DATETIME,
    TransactionItem VARCHAR(50),
    TransactionQty DECIMAL(18,6),
    FromWarehouseCode VARCHAR(50),
    FromRackBinCode VARCHAR(50),
    ToWarehouseCode VARCHAR(50),
    ToRackBinCode VARCHAR(50),
    ItemGroupKey VARCHAR(50),
    FromItem VARCHAR(50),
    ToItem VARCHAR(50),
    BranchID VARCHAR(3),
    CompID VARCHAR(3),
    FinYear VARCHAR(20)
)

INSERT INTO #TraceTrans
SELECT
    ICode,
    DocType,
    DocNo,
    DocDate,
    TransactionDate,
    TransactionTime,
    TransactionItem,
    TransactionQty,
    FromWarehouseCode,
    FromRackBinCode,
    ToWarehouseCode,
    ToRackBinCode,
    ItemGroupKey,
    FromItem,
    ToItem,
    BranchID,
    CompID,
    FinYear
FROM INV_MaterialTran_Dtl a
WHERE a.BranchID=@BranchID
AND a.CompID=@CompID
AND a.FinYear=@FinYear
AND EXISTS
(
    SELECT 1
    FROM BOM_TraceableItems t
    WHERE t.ItemCode=a.TransactionItem
)

UNION ALL

SELECT
    -ICode,
    DocType,
    DocNo,
    DocDate,
    TransactionDate,
    TransactionTime,
    TransactionItem,
    TransactionQty,
    FromWarehouseCode,
    FromRackBinCode,
    ToWarehouseCode,
    ToRackBinCode,
    ItemGroupKey,
    FromItem,
    ToItem,
    BranchID,
    CompID,
    FinYear
FROM INV_WIPTRAN_DTL a
WHERE a.BranchID=@BranchID
AND a.CompID=@CompID
AND a.FinYear=@FinYear
AND NOT EXISTS
(
    SELECT 1
    FROM INV_MaterialTran_Dtl s
    WHERE s.DocNo=a.DocNo
    AND s.DocDate=a.DocDate
    AND s.DocType=a.DocType
    AND s.TransactionItem=a.TransactionItem
    AND s.BranchID=a.BranchID
    AND s.CompID=a.CompID
    AND s.FinYear=a.FinYear
)

CREATE INDEX IX_TraceTrans
ON #TraceTrans(ICode,BranchID,CompID,FinYear)


-------------------------------------------------------
-- Final Query
-------------------------------------------------------

SELECT
    d.TransactionItem AS ItemCode,
    d.FromItem,
    d.ToItem,
    e.ItemDescription AS ItemDesc,
    h.SDesc AS UOMDesc,
    h.NoofDecimals AS UOMDecimal,
    d.DocType,
    d.DocNo,
    d.DocDate,
    b.LotID,
    c.Qty,
    c.FromWarehouseCode,
    c.FromRackBinCode,
    c.ToWarehouseCode,
    c.ToRackBinCode,
    c.Transtamp AS TransactionDate,
    ISNULL(g.HeatNo,'') AS HeatNo
FROM INV_MaterialTran_Dtl a

LEFT JOIN COM_Trace_MaterialTran_TmpQty b
ON a.ICode=b.TranID
AND a.BranchID=b.BranchID
AND a.CompID=b.CompID
AND a.FinYear=b.FinYear

LEFT JOIN COM_Trace_MaterialTran_TmpQty c
ON b.LotID=c.LotID
AND b.BranchID=c.BranchID
AND b.CompID=c.CompID
AND b.FinYear=c.FinYear

LEFT JOIN #TraceTrans d
ON c.TranID=d.ICode
AND c.BranchID=d.BranchID
AND c.CompID=d.CompID
AND c.FinYear=d.FinYear

LEFT JOIN INV_Material_Master e
ON d.TransactionItem=e.ItemCode
AND d.BranchID=e.BranchID
AND d.CompID=e.CompID

LEFT JOIN INV_UOM_Master h
ON e.UOM=h.Code
AND e.BranchID=h.BranchID
AND e.CompID=h.CompID

LEFT JOIN COM_Trace_LotMaster_TmpQty g
ON b.LotID=g.LotID
AND b.BranchID=g.BranchID
AND b.CompID=g.CompID

WHERE
a.DocType=@DocType
AND a.DocNo=@DocNo
AND a.DocDate=@DocDate
AND a.BranchID=@BranchID
AND a.CompID=@CompID
AND a.FinYear=@FinYear
AND d.TransactionItem IS NOT NULL
AND d.TransactionDate <= @TransactionDate
AND
(
    @ItemUserKey=''
    OR EXISTS
    (
        SELECT 1
        FROM #ProcessFilter m
        WHERE
        m.BranchID=d.BranchID
        AND m.CompID=d.CompID
        AND
        (
            m.ItemCode=d.TransactionItem
            OR m.StageCode=d.TransactionItem
            OR m.StageCode=d.ToItem
        )
    )
)

ORDER BY c.Transtamp


-------------------------------------------------------
-- Cleanup
-------------------------------------------------------

DROP TABLE #ProcessFilter
DROP TABLE #TraceTrans

END
GO

/****** Object:  StoredProcedure [dbo].[SAL_Rpt_TraceabilityReport_Gen_V3]    Script Date: 17/06/2026 11:31:02 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

Create PROCEDURE [dbo].[SAL_Rpt_TraceabilityReport_Gen_V3]
(
    @ItemUserKey VARCHAR(36),
    @DocType VARCHAR(3),
    @DocNo INT,
    @DocDate DATETIME,
    @BranchID VARCHAR(3),
    @CompID VARCHAR(3),
    @FinYear VARCHAR(20)
)
AS
BEGIN

SET NOCOUNT ON;

-------------------------------------------------------
-- 1. Get Transaction Timestamp
-------------------------------------------------------
DECLARE @TransactionDate DATETIME,
        @TransactionTime DATETIME;

SELECT
    @TransactionDate = TransactionDate,
    @TransactionTime = TransactionTime
FROM INV_MaterialTran_Dtl
WHERE DocType=@DocType
AND DocNo=@DocNo
AND DocDate=@DocDate
AND BranchID=@BranchID
AND CompID=@CompID
AND FinYear=@FinYear;

-------------------------------------------------------
-- 2. Anchor Transaction
-------------------------------------------------------
CREATE TABLE #AnchorTran
(
    ICode INT PRIMARY KEY
);

INSERT INTO #AnchorTran(ICode)
SELECT ICode
FROM INV_MaterialTran_Dtl
WHERE DocType=@DocType
AND DocNo=@DocNo
AND DocDate=@DocDate
AND BranchID=@BranchID
AND CompID=@CompID
AND FinYear=@FinYear;

-------------------------------------------------------
-- 3. Load Lots Related To Anchor
-------------------------------------------------------
CREATE TABLE #LotList
(
    LotID VARCHAR(50)
);

INSERT INTO #LotList
SELECT DISTINCT LotID
FROM COM_Trace_MaterialTran_TmpQty
WHERE TranID IN (SELECT ICode FROM #AnchorTran)
AND BranchID=@BranchID
AND CompID=@CompID
AND FinYear=@FinYear;

CREATE INDEX IX_LotList ON #LotList(LotID);

-------------------------------------------------------
-- 4. Load All Trace Transactions For Those Lots
-------------------------------------------------------
CREATE TABLE #TraceLotTrans
(
    TranID INT,
    LotID VARCHAR(50),
    Qty DECIMAL(18,6),
    FromWarehouseCode VARCHAR(50),
    FromRackBinCode VARCHAR(50),
    ToWarehouseCode VARCHAR(50),
    ToRackBinCode VARCHAR(50),
    Transtamp DATETIME
);

INSERT INTO #TraceLotTrans
SELECT
    TranID,
    LotID,
    Qty,
    FromWarehouseCode,
    FromRackBinCode,
    ToWarehouseCode,
    ToRackBinCode,
    Transtamp
FROM COM_Trace_MaterialTran_TmpQty
WHERE LotID IN (SELECT LotID FROM #LotList)
AND BranchID=@BranchID
AND CompID=@CompID
AND FinYear=@FinYear;

CREATE INDEX IX_TraceLotTrans
ON #TraceLotTrans(TranID,LotID);

-------------------------------------------------------
-- 5. Trace Transaction Details
-------------------------------------------------------
CREATE TABLE #TraceTrans
(
    ICode INT,
    DocType VARCHAR(10),
    DocNo INT,
    DocDate DATETIME,
    TransactionDate DATETIME,
    TransactionTime DATETIME,
    TransactionItem VARCHAR(50),
    FromItem VARCHAR(50),
    ToItem VARCHAR(50),
    BranchID VARCHAR(3),
    CompID VARCHAR(3),
    FinYear VARCHAR(20)
);

INSERT INTO #TraceTrans
SELECT
    ICode,
    DocType,
    DocNo,
    DocDate,
    TransactionDate,
    TransactionTime,
    TransactionItem,
    FromItem,
    ToItem,
    BranchID,
    CompID,
    FinYear
FROM INV_MaterialTran_Dtl
WHERE BranchID=@BranchID
AND CompID=@CompID
AND FinYear=@FinYear

UNION ALL

SELECT
    -ICode,
    DocType,
    DocNo,
    DocDate,
    TransactionDate,
    TransactionTime,
    TransactionItem,
    FromItem,
    ToItem,
    BranchID,
    CompID,
    FinYear
FROM INV_WIPTRAN_DTL
WHERE BranchID=@BranchID
AND CompID=@CompID
AND FinYear=@FinYear;

CREATE INDEX IX_TraceTrans
ON #TraceTrans(ICode,BranchID,CompID,FinYear);

-------------------------------------------------------
-- 6. Final Result
-------------------------------------------------------
SELECT
    d.TransactionItem AS ItemCode,
    d.FromItem,
    d.ToItem,
    e.ItemDescription as ItemDesc,
    h.SDesc AS UOMDesc,
    h.NoofDecimals as UOMDecimal,
    d.DocType,
    d.DocNo,
    d.DocDate,
    t.LotID,
    t.Qty,
    t.FromWarehouseCode,
    t.FromRackBinCode,
    t.ToWarehouseCode,
    t.ToRackBinCode,
    t.Transtamp AS TransactionDate,
    ISNULL(g.HeatNo,'') AS HeatNo
FROM #TraceLotTrans t

JOIN #TraceTrans d
ON t.TranID=d.ICode

LEFT JOIN INV_Material_Master e
ON d.TransactionItem=e.ItemCode
AND d.BranchID=e.BranchID
AND d.CompID=e.CompID

LEFT JOIN INV_UOM_Master h
ON e.UOM=h.Code
AND e.BranchID=h.BranchID
AND e.CompID=h.CompID

LEFT JOIN COM_Trace_LotMaster_TmpQty g
ON t.LotID=g.LotID
AND d.BranchID=g.BranchID
AND d.CompID=g.CompID

WHERE d.TransactionDate <= @TransactionDate

ORDER BY t.Transtamp;

-------------------------------------------------------
-- 7. Cleanup
-------------------------------------------------------
DROP TABLE #AnchorTran;
DROP TABLE #LotList;
DROP TABLE #TraceLotTrans;
DROP TABLE #TraceTrans;

END
GO

