  CREATE PROCEDURE [dbo].[SAL_Rpt_TraceabilityReport_Hlp](@ItemUSerKey Varchar(36), @FromDate datetime, @ToDate datetime, @BranchID varchar(3),@CompID varchar(3),@Finyear Varchar(20))                  
As                  
 BEGIN        
                 
  SET NOCOUNT ON;                      
           
 Select Distinct a.DocType, a.DocNo, a.DocDate           
 From INV_MaterialTran_Dtl  a            
 Where  a.DocDate between @FromDate and @ToDate          
  and a.BranchID =@BranchID and a.CompID =@CompID and a.Finyear=@Finyear              
  and (@ItemUSerKey='' OR Exists        
   (        
    Select * From COM_SelectList s        
    Where UserKey=@ItemUSerKey and s.SelectStr=a.TransactionItem and s.BranchID=@BranchID and s.CompId=@CompID        
   ))          
    and Exists       
    (      
     Select * From BOM_TraceableItems t       
     Where t.ItemCode=a.TransactionItem      
    )           
 Order by a.DocDate desc, a.DocNo desc       
                 
 /*Select Distinct a.InvoiceType, a.InvoiceNo, a.InvoiceDate, CustomerCode, b.LedgerName as CustomerName                
 From SalesInvoice  a            
 Left Outer Join FAS_LedgerMaster_AuthTbl b            
  On a.CustomerCode = b.LedgerCode and b.CompCode = a.CompID +a.BranchID                  
 Where a.InvoiceDate between @FromDate and @ToDate          
  and a.BranchID =@BranchID and a.CompID =@CompID and a.Finyear=@Finyear              
  and (@ItemUSerKey='' OR Exists        
   (        
    Select * From COM_SelectList         
    Where UserKey=@ItemUSerKey and SelectStr=a.ItemCode and BranchID=@BranchID and CompId=@CompID        
   ))               
 Order by a.InvoiceDate desc, a.InvoiceNo desc */               
            
END 
