CREATE PROCEDURE [dbo].[SAL_UP_JOBWORKAMENDMENTAUTH_HDR]

	(@AmendmentType 		[varchar](3),
	 @AmendmentNo 		[int],
	 @AmendmentDate 		[datetime],
	 @CustomerCode 		[int],
	 @AmendmentAuthorization 	[char](1),
	 @AmendmentAuthorizationDate 	[datetime],
