CREATE PROCEDURE [dbo].[SalesExportOrderList] (@CurDate Datetime, @CustomerCode int, @Branchid varchar(3), @Compid varchar(3), @Finyear varchar(20))

AS
	DECLARE @sDate datetime
	select @sDate=convert(varchar(19),@CurDate+' 23:59:59')
Begin

	select distinct x.PartNo, x.ItemCode,x.ItemDescription,x.UOMDesc,x.UOMDecimal, x.OrderQty,x.Rate,x.AssessableRate,
	x.OrderType, x.OrderNo,x.OrderDate,case when x.OrderingType<>'Open' then (x.OrderQty-IsNull(x.InvoiceQty, 0)) else x.OrderQty end BalQty, x.OrderingType,x.FormulaCode, 
	(select TOP 1 y.FrmLName from COM_FormulaMast_Hdr y where y.FrmID = x.FormulaCode and y.Branchid = @Branchid
	and y.Compid = @Compid and y.ModuleCode = 4) FormulaName, x.ReferenceNo,x.ItemGroupKey, x.ItemStatus from

	(Select (select e.PartNo from SAL_Customer_ItemMaster e where e.ItemCode = a.ItemCode and e.CustomerCode = a.CustomerCode 
	and e.Branchid = a.Branchid and e.Compid = a.Compid) PartNo,  a.ItemCode, c.ItemDescription,c.UOMDesc,c.UOMDecimal, 
	a.OrderQty,a.Rate,a.AssessableRate, a.Status,a.OrderType,a.OrderNo, a.OrderDate,
	isNull((select sum(d.InvoiceQty) from SAL_INVOICE_DTL d where d.ItemCode=a.ItemCode and d.Ordertype=a.OrderType
	and d.OrderNo=a.OrderNo and d.OrderDate=a.OrderDate  and d.Branchid=a.Branchid and d.Compid=a.Compid),0) InvoiceQty, 
	a.OrderingType,a.FormulaCode, a.ReferenceNo,0 as ItemGroupKey, a.ItemStatus  from dbo.fn_SAL_SalesOrder (@sDate, @CurDate, @Branchid,@Compid,@Finyear) a  
	Inner Join SAL_PackingList a1 On a.OrderType=a1.OrderType and a.OrderNo=a1.OrderNo and a.OrderDate=a1.OrderDate and a.BranchID=a1.BranchID and a.CompID=a1.CompID
	left outer join MATERIAL_MASTER c on a.ItemCode=c.ItemCode and a.Branchid=c.Branchid and a.Compid=C.Compid where a.CustomerCode = @CustomerCode and a.Branchid = @Branchid 
	and a.Compid = @Compid and a.ItemStatus <> 'C' and a.Status = 'A'  and @CurDate between a.ValidFrom 
	and a.ValidTo 

	union 
	
	select (select top 1 e1.PartNo from SAL_Jobwork_ItemMaster e1 where e1.SentItemCode = a1.SentItemCode and e1.CustomerCode = a1.CustomerCode and e1.ItemGroupKey=a1.ItemGroupKey
	and e1.Branchid = a1.Branchid and e1.Compid = a1.Compid) PartNo, a1.SentItemCode, c1.ItemDescription,c1.UOMDesc, c1.UOMDecimal, 
	a1.OrderQty, a1.Rate, a1.AssRate,a1.Status,a1.OrderType,a1.OrderNo,a1.OrderDate, isNull((select sum(d1.InvoiceQty) from 
	SAL_INVOICE_DTL d1 where d1.ItemCode=a1.SentItemCode  and d1.Ordertype=a1.OrderType and d1.OrderNo=a1.OrderNo 
	and d1.OrderDate=a1.OrderDate and d1.Branchid=a1.Branchid and d1.Compid=a1.Compid),0) InvoiceQty, 
	a1.OrderingType, a1.FormulaCode, a1.ReferenceNo,a1.ItemGroupKey, a1.ItemStatus 
	from dbo.fn_SAL_JobworkOrder (@sDate, @CurDate, @Branchid,@Compid,@Finyear)  a1	
	left outer join MATERIAL_MASTER c1 
	on a1.SentItemCode=c1.ItemCode and a1.Branchid=c1.Branchid and a1.Compid=c1.Compid 
	where a1.CustomerCode = @CustomerCode and a1.Branchid = @Branchid and a1.Compid = @Compid  
	and a1.ItemStatus<> 'C' and a1.Status='A' and a1.Rate >0 and @CurDate between a1.ValidFrom and a1.ValidTo	
	 )x
	where ( x.OrderingType = 'Specific' and (x.OrderQty-IsNull(x.InvoiceQty, 0)) > 0 ) or x.OrderingType = 'Open'
	order by x.OrderType, x.OrderNo,x.OrderDate, x.PartNo, x.ReferenceNo
	
end
GO

