CREATE PROCEDURE [dbo].[SalesJobworkOrderList] (@CurDate Datetime, @CustomerCode int, @Branchid varchar(3), @Compid varchar(3), @Finyear varchar(20))

AS
	DECLARE @sDate datetime
	select @sDate=convert(varchar(19),@CurDate+' 23:59:59')
Begin

	
	
	(select  distinct (select top 1 e1.PartNo from SAL_Jobwork_ItemMaster e1 where e1.SentItemCode = a1.SentItemCode and e1.CustomerCode = a1.CustomerCode and e1.ItemGroupKey=a1.ItemGroupKey
	and e1.Branchid = a1.Branchid and e1.Compid = a1.Compid) PartNo, a1.SentItemCode, c1.ItemDescription,c1.UOMDesc, c1.UOMDecimal, 
	a1.OrderQty, a1.Rate, a1.AssRate,a1.Status,a1.OrderType,a1.OrderNo,a1.OrderDate, isNull((select sum(d1.InvoiceQty) from 
	SAL_INVOICE_DTL d1 where d1.ItemCode=a1.SentItemCode  and d1.Ordertype=a1.OrderType and d1.OrderNo=a1.OrderNo 
	and d1.OrderNo=a1.OrderNo  and d1.OrderDate=a1.OrderDate and d1.Branchid=a1.Branchid and d1.Compid=a1.Compid),0) InvoiceQty, 
	a1.OrderingType, a1.FormulaCode, a1.ReferenceNo,a1.ItemGroupKey  from dbo.fn_SAL_JobworkOrder (@sDate, @CurDate, @Branchid,@Compid,@Finyear)  a1 left outer join MATERIAL_MASTER c1 on a1.SentItemCode=c1.ItemCode  
	and a1.Branchid=c1.Branchid and a1.Compid=c1.Compid where a1.CustomerCode = @CustomerCode and a1.Branchid = @Branchid 
	and a1.Compid = @Compid and a1.Finyear = @Finyear and a1.Status='A' and a1.Rate >0 and @CurDate between a1.ValidFrom and a1.ValidTo	)
	

end
GO

