SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SalesOrderList] (@CurDate Datetime, @CustomerCode int, @Branchid varchar(3), 
 @Compid varchar(3), @Finyear varchar(20))        
AS    
BEGIN
	SET NOCOUNT ON;

 Declare @sDate datetime;   
 select @sDate=convert(varchar(19),@CurDate+' 23:59:59');   

 /* Final firewall Inspection */
 Declare @InspctionTypeCode int;
 Set @InspctionTypeCode=13;
      
 Select Distinct x.PartNo, x.ItemCode,x.ItemDescription,x.UOMDesc,x.UOMDecimal, x.OrderQty, 
			x.Rate,x.AssessableRate, x.OrderType, x.OrderNo,x.OrderDate,
			case when x.OrderingType<>'Open' then (x.OrderQty-IsNull(x.InvoiceQty, 0)) else x.OrderQty end As BalQty, 
			x.OrderingType,x.FormulaCode,     
			(	Select TOP 1 y.FrmLName From COM_FormulaMast_Hdr y 
				Where y.FrmID = x.FormulaCode and y.Branchid = @Branchid    
						and y.Compid = @Compid and y.ModuleCode = 4) As FormulaName, 
			x.ReferenceNo,x.ItemGroupKey,   
			(Select TOP 1 y1.Description From dbo.TermsMaster y1 
				Where y1.TypeFlg='Payment Terms' and y1.Code = x.PaymentCode and y1.Branchid = @Branchid    
							and y1.Compid = @Compid) As PaymentTerms   
 From (    
	 select (	Select e.PartNo From SAL_Customer_ItemMaster e 
						Where e.ItemCode = a.ItemCode and e.CustomerCode = a.CustomerCode     
									and e.Branchid = a.Branchid and e.Compid = a.Compid) As PartNo,  
			 a.ItemCode, c.ItemDescription,c.UOMDesc,c.UOMDecimal, a.OrderQty,a.Rate,a.AssessableRate, 
			 a.Status,a.OrderType,a.OrderNo, a.OrderDate, 
			 isNull(( Select sum(d.InvoiceQty) From SAL_INVOICE_DTL d 
								Where d.ItemCode=a.ItemCode and d.Ordertype=a.OrderType and d.OrderNo=a.OrderNo     
											and d.OrderDate=a.OrderDate  and d.Branchid=a.Branchid and d.Compid=a.Compid),0) As InvoiceQty,     
			 a.OrderingType,a.FormulaCode, a.ReferenceNo,0 as ItemGroupKey, a.PaymentCode      
	 From dbo.fn_SAL_SalesOrder (@sDate, @CurDate, @Branchid,@Compid,@Finyear) a      
	 Left Outer Join MATERIAL_MASTER c 
		On a.ItemCode=c.ItemCode and a.Branchid=c.Branchid and a.Compid=C.Compid 
	 Where a.CustomerCode = @CustomerCode and a.Branchid = @Branchid     
				and a.Compid = @Compid  and a.Status = 'A'  and a.ItemStatus <> 'C' 
				and (@CurDate between a.ValidFrom and a.ValidTo)

	/* Exists (Select * from PUR_SubCont_ItemMaster b Where RecdItemcode=a.Itemcode and QCCheck='1' and BranchID=@Branchid and CompId=@Compid 
	and exists (Select * from Inv_Material_Master c Where  ItemNature='F' and b.RecdItemcode=c.Itemcode  and BranchID=@Branchid and CompId=@Compid)
	and exists (Select * from QC_Inspection_Hdr1 Where b.RecdItemcode=ItemCode and BranchID=@Branchid and CompId=@Compid and InspectionTypeCode=@InspctionTypeCode)
	)*/
	UNION      
	 (Select (Select top 1 e1.PartNo From SAL_Jobwork_ItemMaster e1 
						Where e1.SentItemCode = a1.SentItemCode and e1.CustomerCode = a1.CustomerCode     
									and e1.ItemGroupKey=a1.ItemGroupKey and e1.Branchid=a1.Branchid 
									and e1.Compid = a1.Compid) As PartNo, 
						a1.SentItemCode, c1.ItemDescription, c1.UOMDesc, c1.UOMDecimal,     
						a1.OrderQty, a1.Rate, a1.AssRate,a1.Status,a1.OrderType,a1.OrderNo,a1.OrderDate, 
						isNull((select sum(d1.InvoiceQty) From SAL_INVOICE_DTL d1 
										Where d1.ItemCode=a1.SentItemCode  and d1.Ordertype=a1.OrderType and d1.OrderNo=a1.OrderNo     
											and d1.OrderDate=a1.OrderDate and d1.Branchid=a1.Branchid and d1.Compid=a1.Compid),0) As InvoiceQty,     
						a1.OrderingType, a1.FormulaCode, a1.ReferenceNo,a1.ItemGroupKey, a1.PaymentCode      
			From dbo.fn_SAL_JobworkOrder (@sDate, @CurDate, @Branchid,@Compid,@Finyear)  a1    
			Left Outer Join MATERIAL_MASTER c1 on a1.SentItemCode=c1.ItemCode and a1.Branchid=c1.Branchid and a1.Compid=c1.Compid     
			Where a1.CustomerCode = @CustomerCode and a1.Branchid = @Branchid and a1.Compid = @Compid  
						and a1.Status='A' and a1.ItemStatus <> 'C'  and a1.Rate >0 
						and (@CurDate between a1.ValidFrom and a1.ValidTo)
			)
 ) x     
 Where ( x.OrderingType = 'Specific' and (x.OrderQty-IsNull(x.InvoiceQty, 0)) > 0 ) or x.OrderingType = 'Open'    
 Order by x.OrderType, x.OrderNo,x.OrderDate, x.PartNo,  x.ReferenceNo        
END
GO

/****** Object:  StoredProcedure [dbo].[SalesPlanVsActualPlanRpt]    Script Date: 17/06/2026 11:31:04 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SalesPlanVsActualPlanRpt] (@YearMonth datetime, @AsOnDate datetime, @RptDate datetime, @UserKey varchar(36), @BranchID varchar(3), @CompID varchar(3), @FinYear varchar(20))  
AS  
BEGIN  
    SET NOCOUNT ON;
    
    Declare @SchMonth varchar(6), @syear varchar(4), @smonth varchar(2);
  
    Select @SchMonth =Convert(varchar(6), @YearMonth, 112), @syear = Convert(varchar(4), @YearMonth, 112), @smonth =Convert(varchar(2), @YearMonth, 101);
  
    Select  z.CustomerCode, isNull((Select PartyName From Fas_Party_Master Where PartyCode = z.CustomerCode and BranchID = @BranchID and CompID = @CompID), 'Not Available') as PartyName,  
        z.ItemCode, isNull((Select top 1 d1.partno  from partmast d1 where d1.Itemcode = z.ItemCode and d1.BranchID = @BranchID and d1.CompID = @CompID), 'Not Available') Partno,    
        isNull((select d2.ItemDescription from Inv_Material_Master d2 where d2.Itemcode=z.ItemCode and d2.BranchID = @BranchID and d2.CompID = @CompID), 'Not Available') ItemDescription,  
        isNull((select d3.UOMDesc from Material_Master d3 where d3.Itemcode=z.ItemCode and d3.BranchID = @BranchID and d3.CompID = @CompID), 'Not Available')UOMDesc,Rate,  
        SchWeek1, SchWeek2, SchWeek3, SchWeek4, InvWeek1, InvWeek2, InvWeek3, InvWeek4, (z.SchWeek1+z.SchWeek2+z.SchWeek3+z.SchWeek4) SchQty  
    From   
    (
        Select isNull(x.CustomerCode, y.CustomerCode) CustomerCode, isNull(x.ItemCode, y.ItemCode) ItemCode,isnull(y.Rate, isNull(x.Rate, 0)) Rate,  
        isNull(SchWeek1, 0)SchWeek1, isNull(SchWeek2, 0)SchWeek2,  isNull(SchWeek3, 0)SchWeek3, isNull(SchWeek4, 0)SchWeek4,   
        isNull(y.InvWeek1, 0) InvWeek1, isNull(y.InvWeek2, 0) InvWeek2, isNull(y.InvWeek3, 0) InvWeek3, isNull(y.InvWeek4, 0) InvWeek4  
  
        From   
        ( 
            Select CustomerCode, ItemCode, Rate, Sum(SchWeek1) SchWeek1, Sum(SchWeek2) SchWeek2, Sum(SchWeek3) SchWeek3, Sum(SchWeek4) SchWeek4, PlanFor  
            From  
            (
                Select a.CustomerCode, a.ItemCode,  
                    [dbo].[fn_Sal_Item_Rate] (a.ItemCode, a.CustomerCode, '', 0, Null, @BranchID, @CompID, @Finyear)  Rate,  
                    (Case when day(a.PlanPeriod) between 1 and 7 then a.PlanQty else 0 End )as SchWeek1,  
                    (Case when day(a.PlanPeriod) between 8 and 14 then a.PlanQty else 0 End) as SchWeek2,  
                    (Case when day(a.PlanPeriod) between 15 and 21 then a.PlanQty else 0 End) as SchWeek3,  
                    (Case when day(a.PlanPeriod) >= 22 then a.PlanQty else 0 End) as SchWeek4,  
                    a.PlanPeriod, a.PlanFor  
                From dbo.fn_sal_SalesPlan(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)a  
                Where PlanFor = 3 and month(a.Planperiod) =@smonth and year(a.Planperiod)=@syear  
                    and a.CreatedDate=(Select Max(a1.CreatedDate)   
                                        From dbo.fn_sal_SalesPlan(@AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)a1  
                                        where a1.Planfor= 3 and  a1.CustomerCode = a.CustomerCode and a1.DocNo=a.DocNo and a1.DocDate = a.DocDate and a1.DocType=a1.DocType   
                                        and a1.BranchID=a.BranchID and a1.CompID=a.CompID)  
                    and a.BranchID = @BranchID and a.CompID = @CompID  
                Group By a.CustomerCode, a.ItemCode, PlanQty, a.Planperiod, PlanFor  
            )p    
            Group By CustomerCode, ItemCode, Rate, PlanFor  
        )x  
  
        Full Outer Join  
  
        (
            Select Distinct m.CustomerCode, n.ItemCode,  
                [dbo].[fn_Sal_Item_Rate] (n.ItemCode, m.CustomerCode, n.OrderType, n.OrderNo, n.OrderDate, @BranchID, @CompID, @FinYear)  Rate,  
                Sum(Case when day(m.InvoiceDate) between 1 and 7 then n.InvoiceQty else 0 End )as InvWeek1,  
                Sum(Case when day(m.InvoiceDate) between 8 and 14 then n.InvoiceQty else 0 End) as InvWeek2,  
                Sum(Case when day(m.InvoiceDate) between 15 and 21 then n.InvoiceQty else 0 End) as InvWeek3,  
                Sum(Case when day(m.InvoiceDate) >= 22 then n.InvoiceQty else 0 End) as InvWeek4  
            from SAL_INVOICE_HDR m   
            Left  Outer Join SAL_INVOICE_DTL n  
                On n.InvoiceType = m.InvoiceType and n.InvoiceNo = m.InvoiceNo and n.InvoiceDate = m.InvoiceDate  
                    and n.BranchID = m.BranchID and n.CompID = m.CompID   
            Where  Convert(varchar(6), m.InvoiceDate, 112) = @SchMonth and m.Type in ('OE', 'Labour')  and m.BranchID = @BranchID and m.CompID = @CompID  
            Group by m.CustomerCode, n.ItemCode,  n.OrderType, n.OrderNo, n.OrderDate  
        ) y  
            On y.ItemCode = x.ItemCode and y.CustomerCode = x.CustomerCode  
  
    )z  
    Where z.CustomerCode in (Select f.SelectInt from COM_SelectList f where f.UserKey= @UserKey and f.BranchID = @BranchID and f.compid=@CompID)
    /* Where z.CustomerCode in (Select f.CustomerCode from sal_tmp_sellst f where f.Userid = @UserID and f.BranchID = @BranchID and f.compid=@CompID)    */
    Order by PartyName, z.ItemCode
END
GO

/****** Object:  StoredProcedure [dbo].[SalesPlanVsDespatchPlanRpt]    Script Date: 17/06/2026 11:31:04 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[SalesPlanVsDespatchPlanRpt] (@YearMonth datetime, @UserID varchar(10), @BranchID varchar(3), @CompID varchar(3), @FinYear varchar(20))

AS

	SET NOCOUNT ON
	
	Declare @SchMonth varchar(6)
	Select @SchMonth =Convert(varchar(6), @YearMonth, 112)

	Select  z.CustomerCode, isNull((Select PartyName From Fas_Party_Master Where PartyCode = z.CustomerCode and BranchID = @BranchID and CompID = @CompID), 'Not Available') as PartyName,
		z.ItemCode, isNull((Select top 1 d1.partno  from partmast d1 where d1.Itemcode = z.ItemCode and d1.BranchID = @BranchID and d1.CompID = @CompID), 'Not Available') Partno,  
		isNull((select d2.ItemDescription from Inv_Material_Master d2 where d2.Itemcode=z.ItemCode and d2.BranchID = @BranchID and d2.CompID = @CompID), 'Not Available') ItemDescription, Rate,
		SchWeek1, SchWeek2, SchWeek3, SchWeek4, InvWeek1, InvWeek2, InvWeek3, InvWeek4, (z.SchWeek1+z.SchWeek2+z.SchWeek3+z.SchWeek4) SchQty

	From 
		(Select isNull(x.CustomerCode, y.CustomerCode) CustomerCode, isNull(x.ItemCode, y.ItemCode) ItemCode, isnull(y.Rate, isNull(x.Rate, 0)) Rate,
			isNull(x.Week1, 0) SchWeek1, isNull(x.Week2, 0) SchWeek2, isNull(x.Week3, 0) SchWeek3, isNull(x.Week4, 0) SchWeek4,
			isNull(y.InvWeek1, 0) InvWeek1, isNull(y.InvWeek2, 0) InvWeek2, isNull(y.InvWeek3, 0) InvWeek3, isNull(y.InvWeek4, 0) InvWeek4
		From 

			(Select Distinct b.CustomerCode, a.ItemCode, 
				[dbo].[fn_Sal_Item_Rate] (a.ItemCode, b.CustomerCode, '', 0, Null, @BranchID, @CompID, @FinYear)  Rate,
				a.Week1, a.Week2, a.Week3, a.Week4, a.ScheduleMonth
			from Sal_Weekplan a 
				Left Outer Join Sal_ScheduleEntry b
					On b.ScheduleType = a.ScheduleType and b.ScheduleNo = a.ScheduleNo and b.ScheduleDate = a.ScheduleDate and a.ItemCode=b.ItemCode
						and b.BranchID = a.BranchID and b.CompID = a.CompID
			Where Convert(varchar(6), a.ScheduleMonth, 112) = @SchMonth  
				and a.ModifiedDate=(Select Max(a1.ModifiedDate) from Sal_Weekplan a1 
							where a1.WeekPlanType=a1.WeekPlanType and a1.WeekPlanNo=a.WeekPlanNo and a.WeekPlanDate=a.WeekPlanDate
							and a1.BranchID=a.BranchID and a1.CompID=a.CompID
						      )
				and a.BranchID = @BranchID and a.CompID = @CompID 
			) x

			Full Outer Join

			(Select Distinct m.CustomerCode, n.ItemCode, 
				[dbo].[fn_Sal_Item_Rate] (n.ItemCode, m.CustomerCode, n.OrderType, n.OrderNo, n.OrderDate, @BranchID, @CompID, @FinYear)  Rate,
				Sum(Case when day(m.InvoiceDate) between 1 and 7 then n.InvoiceQty else 0 End )as InvWeek1,
				Sum(Case when day(m.InvoiceDate) between 8 and 14 then n.InvoiceQty else 0 End) as InvWeek2,
				Sum(Case when day(m.InvoiceDate) between 15 and 21 then n.InvoiceQty else 0 End) as InvWeek3,
				Sum(Case when day(m.InvoiceDate) >= 22 then n.InvoiceQty else 0 End) as InvWeek4
			from SAL_INVOICE_HDR m 
				Left  Outer Join SAL_INVOICE_DTL n
					On n.InvoiceType = m.InvoiceType and n.InvoiceNo = m.InvoiceNo and n.InvoiceDate = m.InvoiceDate
						and n.BranchID = m.BranchID and n.CompID = m.CompID 	
			Where  Convert(varchar(6), m.InvoiceDate, 112) = @SchMonth   and m.Type in ('OE', 'Labour') and m.BranchID = @BranchID and m.CompID = @CompID
			Group by m.CustomerCode, n.ItemCode,  n.OrderType, n.OrderNo, n.OrderDate
			) y
			On y.ItemCode = x.ItemCode and y.CustomerCode = x.CustomerCode
		)z

	Where z.CustomerCode in (Select f.CustomerCode from sal_tmp_sellst f where f.userid=@UserID and f.BranchID = @BranchID and f.compid=@CompID) 
	Order by PartyName, z.ItemCode
GO

