CREATE PROCEDURE [dbo].[SEC_Rpt_UserMaster_Gen](@UserGroupCode char(1), @AsOnDate DateTime, @RptDate DateTime, @BranchID varchar(3), @CompID varchar(3))                
AS               
BEGIN               
    Select a.UserID As Usercode, a.UserName, '' As EMail,
		Case When Right(a.EffStatus,1)='A' then 'Active' Else 'Inactive' End as  Status, a.UserGroupID As UserGroupCode, b.GroupName           
    From fn_Sec_Users(@AsOnDate, @RptDate, @BranchID, @CompID) a          
    Left outer join Sec_UserGroups b          
    On a.UserGroupID=b.UserGroupID          
    Where (@UserGroupCode='' or a.UserGroupID=@UserGroupCode) and a.UserGroupID<>'D'            
END   
  
GO

