/****** Object:  StoredProcedure [dbo].[SP_GETCOLUMNLIST]    Script Date: 17/06/2026 11:31:05 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_GETCOLUMNLIST](@TableName sysname)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @ColList nvarchar(max);
	SET @ColList='';

	DECLARE @ColName sysname;

	DECLARE cur_ColList CURSOR For
		SELECT COLUMN_NAME
		FROM INFORMATION_SCHEMA.COLUMNS
		WHERE TABLE_NAME = @TableName
		ORDER BY ORDINAL_POSITION;

	OPEN cur_ColList;

	FETCH NEXT FROM cur_ColList INTO @ColName;

	WHILE (@@FETCH_STATUS=0)
	BEGIN
		--Print @ColList;
		SET @ColList = @ColList + @ColName + ', ';
		--Print @ColList;
		FETCH NEXT FROM cur_ColList INTO @ColName;
	END

	CLOSE cur_ColList;
	DEALLOCATE cur_ColList;

	SELECT LEFT(@ColList, Len(@ColList)-1);

END
GO

/****** Object:  StoredProcedure [dbo].[SP_GETCOLUMNLIST_ALIAS]    Script Date: 17/06/2026 11:31:05 ******/
SET ANSI_NULLS ON
