CREATE PROCEDURE [dbo].[SP_GETCOLUMNLIST_ALIAS](@TableName sysname)
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @ColList nvarchar(max);
	SET @ColList='';

	DECLARE @ColName sysname;

	DECLARE cur_ColList CURSOR For
		SELECT COLUMN_NAME
		FROM INFORMATION_SCHEMA.COLUMNS
		WHERE TABLE_NAME = @TableName
		ORDER BY ORDINAL_POSITION;

	OPEN cur_ColList;

	FETCH NEXT FROM cur_ColList INTO @ColName;

	WHILE (@@FETCH_STATUS=0)
	BEGIN
		--Print @ColList;
		SET @ColList = @ColList + 'a.' + @ColName + ', ';
		--Print @ColList;
		FETCH NEXT FROM cur_ColList INTO @ColName;
	END

	CLOSE cur_ColList;
	DEALLOCATE cur_ColList;

	SELECT LEFT(@ColList, Len(@ColList)-1);

END
GO

/****** Object:  StoredProcedure [dbo].[sp_help]    Script Date: 17/06/2026 11:31:05 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

create proc [dbo].[sp_help]
	@objname nvarchar(776) = NULL		-- object name we're after
as
	-- PRELIMINARY
	set nocount on
	declare	@dbname	sysname

	-- OBTAIN DISPLAY STRINGS FROM spt_values UP FRONT --
	declare @no varchar(35), @yes varchar(35), @none varchar(35)
	select @no = name from master.dbo.spt_values where type = 'B' and number = 0
	select @yes = name from master.dbo.spt_values where type = 'B' and number = 1
	select @none = name from master.dbo.spt_values where type = 'B' and number = 2

	-- If no @objname given, give a little info about all objects.
	if @objname is null
	begin
		-- DISPLAY ALL SYSOBJECTS --
        select
            'Name'          = o.name,
            'Owner'         = user_name(uid),
            'Object_type'   = substring(v.name,5,31)
        from sysobjects o, master.dbo.spt_values v
        where o.xtype = substring(v.name,1,2) collate database_default and v.type = 'O9T'
        order by Object_type desc, Name asc

		print ' '

		-- DISPLAY ALL USER TYPES
		select
			'User_type'		= name,
			'Storage_type'	= type_name(xtype),
			'Length'		= length,
			'Prec'			= TypeProperty(name, 'precision'),
			'Scale'			= TypeProperty(name, 'scale'),
			'Nullable'		= case when TypeProperty(name, 'AllowsNull') = 1
											then @yes else @no end,
			'Default_name'	= isnull(object_name(tdefault), @none),
			'Rule_name'		= isnull(object_name(domain), @none),
			'Collation'		= collation
		from systypes
		where xusertype > 256
		order by name

		return(0)
	end

	-- Make sure the @objname is local to the current database.
	select @dbname = parsename(@objname,3)

	if @dbname is not null and @dbname <> db_name()
		begin
			raiserror(15250,-1,-1)
			return(1)
		end

	-- @objname must be either sysobjects or systypes: first look in sysobjects
	declare @objid int
	declare @sysobj_type char(2)
	select @objid = id, @sysobj_type = xtype from sysobjects where id = object_id(@objname)

	-- IF NOT IN SYSOBJECTS, TRY SYSTYPES --
	if @objid is null
	begin
		-- UNDONE: SHOULD CHECK FOR AND DISALLOW MULTI-PART NAME
		select @objid = xusertype from systypes where name = @objname

		-- IF NOT IN SYSTYPES, GIVE UP
		if @objid is null
		begin
			select @dbname=db_name()
			raiserror(15009,-1,-1,@objname,@dbname)
			return(1)
		end

		-- DATA TYPE HELP (prec/scale only valid for numerics)
		select
			'Type_name'		= name,
			'Storage_type'	= type_name(xtype),
			'Length'		= length,
			'Prec'			= TypeProperty(name, 'precision'),
			'Scale'			= TypeProperty(name, 'scale'),
			'Nullable'		= case when allownulls=1 then @yes else @no end,
			'Default_name'	= isnull(object_name(tdefault), @none),
			'Rule_name'		= isnull(object_name(domain), @none),
			'Collation'		= collation
		from systypes
		where xusertype = @objid

		return(0)
	end

	-- FOUND IT IN SYSOBJECT, SO GIVE OBJECT INFO
	select
		'Name'				= o.name,
		'Owner'				= user_name(uid),
        'Type'              = substring(v.name,5,31),
		'Created_datetime'	= o.crdate
	from sysobjects o, master.dbo.spt_values v
	where o.id = @objid and o.xtype = substring(v.name,1,2) collate database_default and v.type = 'O9T'

	print ' '

	-- DISPLAY COLUMN IF TABLE / VIEW
	if @sysobj_type in ('S ','U ','V ','TF','IF')
	begin

		-- SET UP NUMERIC TYPES: THESE WILL HAVE NON-BLANK PREC/SCALE
		declare @numtypes nvarchar(80)
		select @numtypes = N'tinyint,smallint,decimal,int,real,money,float,numeric,smallmoney'

		-- INFO FOR EACH COLUMN
		print ' '
		select
			'Column_name'			= name,
			'Type'					= type_name(xusertype),
			'Computed'				= case when iscomputed = 0 then @no else @yes end,
			'Length'				= convert(int, length),
			'Prec'					= case when charindex(type_name(xtype), @numtypes) > 0
										then convert(char(5),ColumnProperty(id, name, 'precision'))
										else '     ' end,
			'Scale'					= case when charindex(type_name(xtype), @numtypes) > 0
										then convert(char(5),OdbcScale(xtype,xscale))
										else '     ' end,
			'Nullable'				= case when isnullable = 0 then @no else @yes end,
			'TrimTrailingBlanks'	= case ColumnProperty(@objid, name, 'UsesAnsiTrim')
										when 1 then @no
										when 0 then @yes
										else '(n/a)' end,
			'FixedLenNullInSource'	= case
						when type_name(xtype) not in ('varbinary','varchar','binary','char')
							Then '(n/a)'
						When status & 0x20 = 0 Then @no
						Else @yes END,
			'Collation'		= collation
		from syscolumns where id = @objid and number = 0 order by colid

		-- IDENTITY COLUMN?
		if @sysobj_type in ('S ','U ','V ','TF')
		begin
			print ' '
			declare @colname sysname
			select @colname = name from syscolumns where id = @objid
						and colstat & 1 = 1
			select
				'Identity'				= isnull(@colname,'No identity column defined.'),
				'Seed'					= ident_seed(@objname),
				'Increment'				= ident_incr(@objname),
				'Not For Replication'	= ColumnProperty(@objid, @colname, 'IsIDNotForRepl')
			-- ROWGUIDCOL?
			print ' '
			select @colname = null
			select @colname = name from syscolumns where id = @objid and number = 0
						and ColumnProperty(@objid, name, 'IsRowGuidCol') = 1
			select 'RowGuidCol' = isnull(@colname,'No rowguidcol column defined.')
		end
	end

	-- DISPLAY PROC PARAMS
	if @sysobj_type in ('P ') --RF too?
	begin
		-- ANY PARAMS FOR THIS PROC?
		if exists (select id from syscolumns where id = @objid)
		begin
			-- INFO ON PROC PARAMS
			print ' '
			select
				'Parameter_name'	= name,
				'Type'				= type_name(xusertype),
                'Length'			= length,
                'Prec'				= case when type_name(xtype) = 'uniqueidentifier' then xprec
										else OdbcPrec(xtype, length, xprec) end,
                'Scale'				= OdbcScale(xtype,xscale),
                'Param_order'		= colid,
				'Collation'		= collation

			from syscolumns where id = @objid
		end
	end

	-- DISPLAY TABLE INDEXES & CONSTRAINTS
	if @sysobj_type in ('S ','U ')
	begin
		print ' '
		execute sp_objectfilegroup @objid
		print ' '
		execute sp_helpindex @objname
		print ' '
		execute sp_helpconstraint @objname,'nomsg'
		if (select count(*) from sysdepends where depid = @objid and deptype = 1) = 0
		begin
			raiserror(15647,-1,-1) -- 'No views with schemabinding reference this table.'
		end
		else
		begin
            select distinct 'Table is referenced by views' = obj.name from sysobjects obj, sysdepends deps
				where obj.xtype ='V' and obj.id = deps.id and deps.depid = @objid
					and deps.deptype = 1 group by obj.name

		end
	end
	else if @sysobj_type in ('V ')
	begin
		-- VIEWS DONT HAVE CONSTRAINTS, BUT PRINT THESE MESSAGES BECAUSE 6.5 DID
		print ' '
		raiserror(15469,-1,-1) -- No constraints defined
		print ' '
		raiserror(15470,-1,-1) --'No foreign keys reference this table.'
		execute sp_helpindex @objname
	end

	return (0) -- sp_help
GO

/****** Object:  StoredProcedure [dbo].[STY_COM_TraceableItem]    Script Date: 17/06/2026 11:31:05 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[STY_COM_TraceableItem](@Display_SalInv bit='0', @DocType varchar(3), @DocNo int, @DocDate datetime, 
		@Display_PartyMast bit='0', @PartyCode int=0, @PartyName varchar(25), @Display_ItmMast bit='0', @ItemCode varchar(20), 
		@Display_TraItm bit='0', @Display_MPSMast bit='0', @Display_StrMast bit='0', @Display_TraRwItm bit='0', 
		@RawItemCode Varchar(20)='', @Display_MatTran bit='0', 
		@Display_TraRecDtl bit='0', @RefType varchar(3)='', @RefNo int=0, @RefDate datetime=NULL, @Qty float=0,
		@Display_TraLotMast bit='0', @Display_HeatNo bit='0', @ItemSeq int=0, 
		@AsOnDate datetime, @RptDate datetime, @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))                          
As
BEGIN                                     
	SET NOCOUNT ON;         

	If @Display_SalInv='1'
	 Begin
		Select * From SalesInvoice a
		Where a.InvoiceNo=@DocNo and a.InvoiceDate=@DocDate and a.InvoiceType=@DocType 
				and a.ItemCode=@ItemCode and a.BranchID=@BranchID and a.CompID=@CompID				
	 End	 

	If @Display_PartyMast='1'
	 Begin
		Select * From FAS_Party_Master a			/* dbo.fn_FAS_Party_Master('A','2022-03-16 20:20:20','2022-03-16 20:20:20','00','02') */
		Where (@PartyCode=0 or (@PartyCode>0 and a.PartyCode=@PartyCode)) 
			and  (@PartyName='' or (@PartyName<>'' and (a.PartyName Like '%' + @PartyName + '%')))
			and a.BranchID=@BranchID and a.CompID=@CompID
	 End

	If @Display_ItmMast='1'
	 Begin
		Select * From INV_Material_Master a
		Where a.ItemCode=@ItemCode and a.BranchID=@BranchID and a.CompID=@CompID
	 End

	If @Display_TraItm='1'
	 Begin
		Select * From BOM_TraceableItems a
		Where a.ItemCode=@ItemCode
	 End

	If @Display_MPSMast='1'
	 Begin
		Select * From BOM_MPS_Master a			/* dbo.fn_BOM_MPS_Master('A', @AsOnDate, @RptDate, @BranchID, @CompID) */
		Where (a.ItemCode=@ItemCode or a.StageCode=@ItemCode)
			and a.BranchID=@BranchID and a.CompID=@CompID
	 End

	If @Display_StrMast='1'
	 Begin
		Select * From BOM_Structure_Hdr a		-- StageCode Same but OperationSequence --> 0 ??
		Where a.ParentCode=@ItemCode					--1) a.ParentCode='2U020640Z0'
			and a.BranchID=@BranchID and a.CompID=@CompID

		Select * From BOM_Structure_Dtl a
		Where (a.ParentCode=@ItemCode or ChildCode=@ItemCode)
			and a.BranchID=@BranchID and a.CompID=@CompID
	 End

	If @Display_TraRwItm='1'
	 Begin
		Select * From BOM_TraceableItems a
		Where a.ItemCode=@RawItemCode
	 End
	
	If @Display_MatTran='1'
	 Begin	 	 
		Select * From Inv_MaterialTran_Dtl a 
		Where (@DocNo<=0 or (@DocNo>0 and a.DocNo=@DocNo and a.DocDate=@DocDate and a.DocType=@DocType)) 
				and (a.TransactionItem=@ItemCode or a.TransactionItem=@RawItemCode)	
				and (@Qty<=0 or (@Qty>0 and a.TransactionQty=@Qty))
				and a.BranchID=@BranchID and a.CompID=@CompID
		Order by a.TransactionDate Desc, a.TransactionTime Desc
	 End	 	 
	
	If @Display_TraRecDtl='1'
	 Begin		 		
		Select * From REC_ReceiptEntry_Dtl_Trace a  -- | TranStamp: 2022-03-09 11:00:12.000 | HeatNo.: A35555 | 
		Where (@RefNo<=0 or (@RefNo>0 and a.ReceiptEntryNo=@RefNo and a.ReceiptEntryDate=@RefDate and a.ReceiptEntryType=@RefType)) 
			and (a.ItemCode=@ItemCode or a.ItemCode=@RawItemCode)	and (@Qty<=0 or (@Qty>0 and a.Qty=@Qty))		
			and a.BranchID=@BranchID and a.CompID=@CompID
		Order by a.TranStamp Desc
	 End

	If @Display_TraLotMast='1'
	 Begin	
		Select * From COM_Trace_LotMaster_TmpQty a                        
		Where (@RefNo<=0 or (@RefNo>0 and a.DocNo=@RefNo and a.DocDate=@RefDate and a.DocType=@RefType))
			and (ItemCode=@ItemCode or ItemCode=@RawItemCode)			
			and a.BranchID=@BranchID and a.CompID=@CompID
	 End

	If @Display_HeatNo='1'
	 Begin
		Select tm.LotID, tm.SubLotID, th.HeatNo, th.ManufactureDate, a.ICode, a.DocType, a.DocNo, a.DocDate, 
			a.TransactionItem, tr.Qty, tr.Seq, tr.ItemSeq, th.LotID, th.SublotID              
		From Inv_MaterialTran_Dtl a        
		Left Outer Join COM_Trace_MaterialTran_TmpQty tm        
			On a.ICode=tm.TranID and a.FromWarehouseCode=tm.FromWarehouseCode and a.FromRackBinCode=tm.FromRackBinCode        
				and a.ToWarehouseCode=tm.ToWarehouseCode and a.ToRackBinCode=tm.ToRackBinCode        
				and a.TransactionItem=tm.ItemCode and a.BranchID=tm.BranchID and a.CompID=tm.CompID       
		Left Outer Join COM_Trace_LotMaster_TmpQty  th          
			On tm.LotID=th.LotID and tm.SubLotID=th.SubLotID	--and tm.ItemCode=th.ItemCode        
				and a.BranchID=th.BranchID and a.CompID=th.CompID 
		Left Outer Join REC_ReceiptEntry_Dtl_Trace tr        
			On th.DocType=tr.ReceiptEntryType and th.DocNo=tr.ReceiptEntryNo and th.DocDate=tr.ReceiptEntryDate        
				and th.ItemCode=tr.ItemCode and th.BranchID=tr.BranchID and th.CompID=tr.CompID                             
		Where a.DocNo=@DocNo and a.DocDate=@DocDate and a.DocType=@DocType             
			and a.TransactionItem=@ItemCode and (@ItemSeq=@ItemSeq or (@ItemSeq>0 and tr.ItemSeq=@ItemSeq))
			and a.BranchID=@BranchID and a.CompID=@CompID           
		Order by th.HeatNo
	 End		 
END
GO

/****** Object:  StoredProcedure [dbo].[STY_PAY_MiscellaneousProcess_Unicorn]    Script Date: 17/06/2026 11:31:05 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[STY_PAY_MiscellaneousProcess_Unicorn](@EmployeeCode varchar(10), @ProcessMonth datetime, 
	@Process bit, @UserID int, @AsonDate datetime, @RptDate datetime, @BranchID varchar(3), 
	@CompID varchar(3), @Finyear varchar(20))        
AS        
 BEGIN                 
  SET NOCOUNT ON;

	-- Cursor: Formula Calculation ------
	Declare @ProsMonth As datetime;
	Declare @PremiumValue As float;
	Declare @PostingAccountDr As int;
	Declare @PostingAccountCr As int;
	Declare @NoofDays As int;
	Declare @EMIAmt As money;
	Declare @ExprGroupID As int;
	Declare @Amount As float;	
	Declare @ABSAmount As float;	
	Declare @Route As varchar(40);
	Declare @AdvanceNo As int; 
	Declare @AdvanceDate As datetime; 
	Declare @AdvDate As datetime;
	Declare @TotalAmount As float;	 
	Declare @MonthlyDeduction As float; 
	Declare @GrandTotalFlag As int;
	Declare @mRCnt As int;	

	SET @ProsMonth=(Convert(varchar(7),@ProcessMonth,121)+'-01');
	SET @GrandTotalFlag=-1	
	SET @ABSAmount=0	
	
-- Part 3: ( Miscellaneous Process )
-- ~~~~~~~
/* Step 2.10: Miscellaneous Process */
	Select @PremiumValue=0, @PostingAccountDr=0, @PostingAccountCr=0, @EMIAmt=0, @ExprGroupID=0, @Amount=0, @NoofDays=0, @Route='', @mRCnt=1000;

	/* Building Employee List */              
	DECLARE CurTmpTbl_FormulaCalc CURSOR FOR
		/* Step 2.10.1: Miscellaneous Process - Get Data From PAY_Time_Entry / PAY_Insurance_Master */
		Select IsNull(a.PremiumValue,0) As PremiumValue, IsNull(a.PostingAccountDr,0) As PostingAccountDr, 
			IsNull(a.PostingAccountCr,0) As PostingAccountCr,
			IsNull((Select count(t.DateIn) From PAY_Time_Entry t 
			Where t.EmployeeCode=@EmployeeCode and Convert(varchar(7),t.DateIn,121)=Convert(varchar(7),@ProcessMonth,121) 
					and t.BranchID=a.BranchID and t.CompID=a.CompID),0) As NoofDays 
		From PAY_Insurance_Master a 
		Where a.EmployeeCode=@EmployeeCode
			and (Convert(varchar(7),@ProcessMonth,121) Between Convert(varchar(7),a.DeductionFrom,121) 
			and Convert(varchar(7),a.MaturityDate,121)) and a.BranchID=@BranchID and a.CompID=@CompID
		Order by a.PolicyDate

	OPEN CurTmpTbl_FormulaCalc

	/* Insert - Formula Calculation - From Employee Data */
	FETCH NEXT FROM CurTmpTbl_FormulaCalc INTO @PremiumValue, @PostingAccountDr, @PostingAccountCr, @NoofDays;            
              
	While @@FETCH_STATUS=0              
	Begin
    SET @mRCnt = @mRCnt + 1;

    /* Step 2.10.2: Miscellaneous Process - Insert --> PAY_Ins_FormulaCalc_Hdr */
    EXECUTE PAY_Ins_FormulaCalc_Hdr @ProsMonth,
				@EmployeeCode, 0, @mRCnt, @mRCnt, 'N', 0, -1, @PremiumValue, @PostingAccountDr,
				@PostingAccountCr, 'M', @Process,	@NoofDays, @UserID, @BranchID, @CompID;
			
    FETCH NEXT FROM CurTmpTbl_FormulaCalc INTO @PremiumValue, @PostingAccountDr, @PostingAccountCr, @NoofDays;     
  End

	CLOSE CurTmpTbl_FormulaCalc;              
	DEALLOCATE CurTmpTbl_FormulaCalc; 
	---------------------------------	
	Select @PremiumValue=0, @PostingAccountDr=0, @PostingAccountCr=0, @EMIAmt=0, @ExprGroupID=0, @Amount=0, @NoofDays=0, @Route='', @mRCnt=1500;

	/* Building Bank Loan Data */              
	DECLARE CurTmpTbl_BankLoan CURSOR FOR
		/* Step 2.10.3: Miscellaneous Process - Bank Loan Master - Get Data From PAY_Time_Entry / PAY_BankLoan_Dtl */
		Select IsNull(a.EMIAmt,0) As EMIAmt, IsNull((Select count(c.DateIn) From PAY_Time_Entry c 
											Where c.EmployeeCode=@EmployeeCode and Convert(varchar(7), c.DateIn, 121)='2022-01' 
												and c.BranchID=a.BranchID and c.CompID=a.CompID
											),0) As NoofDays 
		From PAY_BankLoan_Dtl a 
		Where a.EmployeeCode=@EmployeeCode
				and (Convert(varchar(7),@ProcessMonth,121) Between Convert(varchar(7),a.LoanDate,120) 
				and Convert(varchar(7),a.CompletionDate,120)) and a.BranchID=@BranchID and a.CompID=@CompID

	OPEN CurTmpTbl_BankLoan
	
	/* Insert - Formula Calculation - From Bank Loan Data */
	FETCH NEXT FROM CurTmpTbl_BankLoan INTO @EMIAmt, @NoofDays;            
              
	While @@FETCH_STATUS=0              
	Begin
    SET @mRCnt = @mRCnt + 1;

    /* Step 2.10.4: Miscellaneous Process - Insert --> PAY_Ins_FormulaCalc_Hdr */
    EXECUTE PAY_Ins_FormulaCalc_Hdr @ProsMonth,
				@EmployeeCode, 0, @mRCnt, @mRCnt, 'N', 0, -1, @EMIAmt, 0,
				0, 'M', @Process,	@NoofDays, @UserID, @BranchID, @CompID;
			
    FETCH NEXT FROM CurTmpTbl_BankLoan INTO @EMIAmt, @NoofDays;     
  End

	CLOSE CurTmpTbl_BankLoan;              
	DEALLOCATE CurTmpTbl_BankLoan; 
	------------------------------
	Select @PremiumValue=0, @PostingAccountDr=0, @PostingAccountCr=0, @EMIAmt=0, @ExprGroupID=0, @Amount=0, @NoofDays=0, @Route='', @mRCnt=2000;

	/* Building Miscellaneous Param Data */              
	DECLARE CurTmpTbl_MiscParam CURSOR FOR
		/* Step 2.10.5: Miscellaneous Process - Misc Parameter Master - Get Data From PAY_MiscellaneousParameter_Master / PAY_FormulaExpr_Group */
		Select a.ExprGroupID, IsNull(Sum(a.Amount),0) As Amount, IsNull(a.PostingAccountDr,0) As PostingAccountDr,
			IsNull(a.PostingAccountCr,0) As PostingAccountCr, IsNull(b.Route,'') As Route,
			IsNull((Select count(t.DateIn) From PAY_Time_Entry t
							Where t.EmployeeCode=@EmployeeCode and Convert(varchar(7),t.DateIn,121)=Convert(varchar(7),@ProcessMonth,121)  
								and t.BranchID=@BranchID and t.CompID=@CompID),0) As NoofDays 
		From  PAY_MiscellaneousParameter_Master a 
		Left Outer Join PAY_FormulaExpr_Group b  
			on a.ExprGroupID=b.ExprGroupID and a.BranchID=b.BranchID and a.CompID=b.CompID  
		Where a.EmployeeCode=@EmployeeCode and Convert(varchar(7),a.ProcessMonth,121)=Convert(varchar(7),@ProcessMonth,121)
			and a.BranchID=@BranchID  and a.CompID=@CompID 
		Group by a.ExprGroupID, a.PostingAccountDr,a.PostingAccountCr, b.Route

	OPEN CurTmpTbl_MiscParam

	/* Insert - Formula Calculation - From Miscellaneous Param Data */
	FETCH NEXT FROM CurTmpTbl_MiscParam INTO @ExprGroupID, @Amount, @PostingAccountDr, @PostingAccountCr, @Route, @NoofDays;            
              
	While @@FETCH_STATUS=0              
	Begin
    SET @mRCnt = @mRCnt + 1;
		SET @GrandTotalFlag=(Case When @Amount>0 Then 1 Else -1 End);
		SET @ABSAmount=Abs(@Amount);

    /* Step 2.10.6: Miscellaneous Process - Insert --> PAY_Ins_FormulaCalc_Hdr */
    EXECUTE PAY_Ins_FormulaCalc_Hdr @ProsMonth,
				@EmployeeCode, 0, @mRCnt, @ExprGroupID, 'N', 0, @GrandTotalFlag, @ABSAmount, 
				@PostingAccountDr, @PostingAccountCr, 'M', @Process,	@NoofDays, @UserID, @BranchID, @CompID;
			
    FETCH NEXT FROM CurTmpTbl_MiscParam INTO @ExprGroupID, @Amount, @PostingAccountDr, @PostingAccountCr, @Route, @NoofDays;    
  End

	CLOSE CurTmpTbl_MiscParam;              
	DEALLOCATE CurTmpTbl_MiscParam; 
	-------------------------------
	Select @PremiumValue=0, @PostingAccountDr=0, @PostingAccountCr=0, @EMIAmt=0, @ExprGroupID=0, @Amount=0, @NoofDays=0, @Route='', @mRCnt=3000;

	/* Building Advance Data */              
	DECLARE CurTmpTbl_Advance CURSOR FOR
		/* Step 2.10.7: Miscellaneous Process - Advance Master - Get Data From PAY_Advance_Master / PAY_Advance_Deduction */
		Select x.AdvanceNo, x.AdvanceDate, /* a.EmployeeCode,*/ IsNull(x.TotalAmount,0) As TotalAmount, 
			IsNull(x.MonthlyDeduction,0) As MonthlyDeduction,  IsNull(x.PostingAccountDr,0) As PostingAccountDr, 
			IsNull(x.PostingAccountCr,0) As PostingAccountCr, IsNull(x.DeductedAmount,0) As Amount, 
			IsNull(x.NoofDays,0) As NoofDays
		From (Select a.AdvanceNo, a.AdvanceDate, a.EmployeeCode, a.TotalAmount, a.MonthlyDeduction,  
						a.PostingAccountDr,a.PostingAccountCr, IsNull(sum(b.DeductedAmount),0) As DeductedAmount, 
						(Select Count(c.DateIn) From PAY_Time_Entry c 
						Where c.EmployeeCode=@EmployeeCode 
							and Convert(varchar(7),c.DateIn,121)=Convert(varchar(7),@ProcessMonth,121) 
							and c.EmployeeCode=a.EmployeeCode and c.BranchID=@BranchID and c.CompID=@CompID) As NoofDays 
					From PAY_Advance_Master a 
					Left Outer Join PAY_Advance_Deduction b  
						On a.AdvanceNo=b.AdvanceNo and a.AdvanceDate=b.AdvanceDate  and a.BranchID=b.BranchID 
							and a.CompID=b.CompID 
					Where a.EmployeeCode=@EmployeeCode and Convert(varchar(7),RecoveryFrom,121)<=Convert(varchar(7),@ProcessMonth,121)
							and a.Approved=1 and a.Status=1 and a.BranchID=@BranchID and a.CompID=@CompID 
					group by  a.AdvanceNo, a.AdvanceDate, a.employeecode, a.TotalAmount, a.MonthlyDeduction, 
								a.PostingAccountDr, a.PostingAccountCr
		) x 
		Where (x.TotalAmount-x.DeductedAmount) > 0

	OPEN CurTmpTbl_Advance

	/* Insert - Formula Calculation - From Advance Data */
	FETCH NEXT FROM CurTmpTbl_Advance INTO @AdvanceNo, @AdvanceDate, @TotalAmount, @MonthlyDeduction, @PostingAccountDr, @PostingAccountCr, @Amount, @NoofDays;
              
	While @@FETCH_STATUS=0              
	Begin
    SET @mRCnt = @mRCnt + 1;
		SET @AdvDate=Convert(varchar(10),@AdvanceDAte,121)

    /* Step 2.10.8: Miscellaneous Process - Insert --> PAY_Ins_FormulaCalc_Hdr */
		EXECUTE PAY_Ins_FormulaCalc_Hdr @ProsMonth,
				@EmployeeCode, 0, @mRCnt, @mRCnt, 'N', 0, -1, @MonthlyDeduction, @PostingAccountDr,
				@PostingAccountCr, 'M', @Process,	@NoofDays, @UserID, @BranchID, @CompID;

		/* Step 2.10.9: Miscellaneous Process - Insert --> PAY_Ins_Advance_Deduction */
    EXECUTE PAY_Ins_Advance_Deduction @AdvanceNo, @AdvDate,
				@EmployeeCode,  @ProsMonth, @MonthlyDeduction,
				@UserID, @BranchID, @CompID;
      
			If @Process='1'
			 Begin
        /* Step 2.10.10: Miscellaneous Process - Update --> PAY_Advance_Master */
        Update PAY_Advance_Master SET DeductedAmount=(DeductedAmount+@MonthlyDeduction)
        Where AdvanceNo=@AdvanceNo and AdvanceDate=@AdvDate and EmployeeCode=@EmployeeCode
					and (TotalAmount-DeductedAmount)>0 and Approved=1 and Status=1 
					and BranchID=@BranchID and CompID=@CompID			 
      End
			
    FETCH NEXT FROM CurTmpTbl_Advance INTO @AdvanceNo, @AdvanceDate, @TotalAmount, @MonthlyDeduction, @PostingAccountDr, @PostingAccountCr, @Amount, @NoofDays;
  End
			
	CLOSE CurTmpTbl_Advance;              
	DEALLOCATE CurTmpTbl_Advance; 
	-----------------------------
	Select @PremiumValue=0, @PostingAccountDr=0, @PostingAccountCr=0, @EMIAmt=0, @ExprGroupID=0, @Amount=0, @NoofDays=0, @Route='', @mRCnt=4000;
	
  If Month(@ProcessMonth)=3 Or Month(@ProcessMonth)=9
	 Begin
		/* Building PT Master Data */              
		DECLARE CurTmpTbl_PTMast CURSOR FOR
			/* Step 2.10.11: Miscellaneous Process - PT Master --> Get Data From PAY_Time_Entry / PAY_PT_Master */
			Select IsNull(a.DeductionAmount,0) As Amount,
					IsNull((Select Count(t.DateIn) From PAY_Time_Entry t 
									Where t.EmployeeCode=@EmployeeCode and convert(varchar(7),t.DateIn,121)=Convert(varchar(7),@ProcessMonth,121)
											and t.Branchid=@BranchID and t.Compid=@CompID),0) As NoofDays
			From PAY_PT_Master a
			Where ((Select sum(h1.ResultValue) From PAY_FormulaCalc_Hdr h1
							Where ((Month(@ProcessMonth)=3 and Convert(varchar(7),h1.ProcessMonth, 121) 
											Between (Year(@ProcessMonth)-1+'-10') and (Year(@ProcessMonth)+'-03'))
										or (Month(@ProcessMonth)<>3 and Convert(varchar(7),h1.ProcessMonth, 121) 
											Between (Year(@ProcessMonth)+'-04') and (Year(@ProcessMonth)+'-09'))
										)
									and h1.EmployeeCode=@EmployeeCode and h1.GrandTotalFlag=1) Between a.FromAmount and a.ToAmount)

		OPEN CurTmpTbl_PTMast
		Select top 200 * From PAY_FormulaCalc_Hdr

		/* Insert - Formula Calculation - From PT Master Data */
		FETCH NEXT FROM CurTmpTbl_PTMast INTO @Amount, @NoofDays;            
              
		While @@FETCH_STATUS=0              
		Begin
			SET @mRCnt = @mRCnt + 1;

			/* Step 2.10.12: Miscellaneous Process - Insert --> PAY_Ins_FormulaCalc_Hdr */
			EXECUTE PAY_Ins_FormulaCalc_Hdr @ProsMonth,
					@EmployeeCode, 0, @mRCnt, @mRCnt, 'N', 0, -1, @Amount, 0,
					0, 'M', @Process,	@NoofDays, @UserID, @BranchID, @CompID;
		
			FETCH NEXT FROM CurTmpTbl_PTMast INTO @Amount, @NoofDays;     
		End

		CLOSE CurTmpTbl_PTMast;              
		DEALLOCATE CurTmpTbl_PTMast;
		----------------------------
	End		 	
END
GO

/****** Object:  StoredProcedure [dbo].[Test_SAL_Rpt_TraceabilityReport_Gen]    Script Date: 17/06/2026 11:31:05 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Test_SAL_Rpt_TraceabilityReport_Gen](@ItemUserKey Varchar(36), @DocType Varchar(3), @DocNo int, @DocDate datetime, @BranchID Varchar(3), @CompID Varchar(3), @FinYear Varchar(20) )            

AS   
         
BEGIN   
         
    SET NOCOUNT ON;            
   
    Declare @TransactionDate datetime
    Declare @TransactionTime datetime

    Select @TransactionDate=TransactionDate, @TransactionTime=TransactionTime
    From INV_MaterialTran_Dtl a  
    Where a.DocType=@DocType and a.DocNo=@DocNo and a.DocDate=@DocDate and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear           
       
    Select distinct ---a.DocType as SelDocType, a.DocNo as SelDocNo, a.DocDate as SelDocDate, a.TransactionItem as SelDocItem,            
        d.TransactionItem as ItemCode, d.FromItem, d.toitem, e.ItemDescription as ItemDesc, h.SDesc as UOMDesc, h.NoofDecimals as UOMDecimal,             
        d.DocType as DocType, d.DocNo as DocNo, d.DocDate as DocDate,b.LotID, c.Qty, c.FromWarehouseCode, c.FromRackBinCode,             
        c.ToWarehouseCode, c.ToRackBinCode, c.Transtamp as TransactionDate, isnull(g.HeatNo,IsNull('test1','')) As HeatNo      --isnull(g.HeatNo,IsNull(f.HeatNo,'')) As HeatNo    
    From INV_MaterialTran_Dtl a      
       
    Left Outer Join Test_COM_Trace_MaterialTran_TmpQty b            
        On a.ICode=b.TranID and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear         
            
    Left Outer Join Test_COM_Trace_MaterialTran_TmpQty c            
        On   b.LotID=c.LotID and b.BranchID=c.BranchID and b.CompID=c.CompID and b.Finyear=c.Finyear           
         
    Left Outer Join     
        (    
            Select * From INV_MaterialTran_Dtl a                  
            Where a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear      
                --and Exists     
                --(    
                --    Select * From TMP_TracebaleItems t     
                --    Where t.ItemCode=a.TransactionItem    
                --)        
                and (@ItemUserKey='' OR Exists  
                                    ( Select * from MPS_Process m  
                                        Where Exists          
                                            (            
                                                Select * From COM_SelectList  n          
                                                Where n.UserKey=@ItemUserKey and n.SelectStr=m.ItemCode and n.BranchID=@BranchID and n.CompID=@CompID           
                                            )    
                                            and (m.ItemCode=a.TransactionItem OR m.StageCode=a.TransactionItem) 
                                            and ((a.DocType=@DocType and m.StageCode=a.TransactionItem) Or (m.StageCode=a.ToItem)) --and m.StageCode=a.ToItem   
                                            and m.BranchId=a.BranchId and m.CompID=a.CompID
                                    )     
                    )
                            
            Union All    
    
            Select -(ICode), DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode,    
                ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear     
            From INV_WIPTRAN_DTL a                  
            Where a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear                      
                and not exists    
                    (    
                        Select * From INV_MaterialTran_Dtl s    
                        Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate     
                            and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode    
                            and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode     
                            and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem     
                            and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear    
                    )     
                --and Exists     
                --    (    
                --        Select * From TMP_TracebaleItems t     
                --        Where t.ItemCode=a.TransactionItem    
                --    )     
                and (@ItemUserKey='' OR Exists    
                        (  
                            Select * from MPS_Process m  
                            Where Exists          
                                (            
                                    Select * From COM_SelectList  n          
                                    Where n.UserKey=@ItemUserKey and n.SelectStr=m.ItemCode and n.BranchID=@BranchID and n.CompID=@CompID            
                                )    
                                and (m.ItemCode=a.TransactionItem OR m.StageCode=a.TransactionItem) 
                                and ((a.DocType=@DocType and m.StageCode=a.TransactionItem) Or (m.StageCode=a.ToItem)) --and m.StageCode=a.ToItem   
                                and m.BranchId=a.BranchId and m.CompID=a.CompID  
                        )     
                    )        
        )d          
        On c.TranID=d.ICode and c.BranchID=d.BranchID and c.CompID=d.CompID and c.Finyear=d.Finyear            
      
    Left Outer Join INV_Material_Master e             
        On d.TransactionItem=e.ItemCode and d.BranchID=e.BranchID and d.CompID=e.CompID    
        
    Left Outer Join INV_UOM_Master  h      
        On e.UOM=h.Code and e.BranchID=h.BranchID and e.CompID=h.CompID      
            
    Left Outer Join Test_COM_Trace_LotMaster_TmpQty g            
        On b.LotID=g.LotID and b.BranchID=g.BranchID and b.CompID=g.CompID      
            
    --Left Outer Join REC_ReceiptEntry_Dtl f            
    -- On g.DocNo=f.ReceiptEntryNo and g.DocDate=f.ReceiptEntryDate and g.DocType=f.ReceiptEntryType and a.TransactionItem=f.ItemCode    
    -- and g.BranchID=f.BranchID and g.CompID=f.CompID    
               
    Where a.BranchID=@BranchID and a.CompID= @CompID and a.Finyear= @Finyear and d.TransactionItem is Not null           
        and a.DocType=@DocType and a.DocNo=@DocNo and a.DocDate=@DocDate  
        --and Convert(Varchar(10), a.TransactionDate, 120)  + '' + Convert(Varchar(8), a.TransactionTime, 108) <= Convert(Varchar(10), @TransactionDate, 120)  + '' + Convert(Varchar(8), @TransactionTime, 108)
        and d.TransactionDate + ' ' + d.TransactionTime <= @TransactionDate + ' ' +   @TransactionTime            
        and (@ItemUserKey='' OR Exists  
                ( 
                    Select * from MPS_Process m  
                    Where Exists  
                        (            
                            Select * From COM_SelectList  n          
                            Where n.UserKey=@ItemUserKey and n.SelectStr=m.ItemCode and n.BranchID=@BranchID and n.CompID=@CompID            
                        )    
                    and (m.ItemCode=d.TransactionItem OR m.StageCode=d.TransactionItem)  
                    and ((d.DocType=@DocType and m.StageCode=d.TransactionItem) Or (m.StageCode=d.ToItem)) --and m.StageCode=d.ToItem   
                    and m.BranchId=d.BranchId and m.CompID=d.CompID  
                )     
            )        
        --and Exists    
        -- (    
        --  Select * From MPS_Process s    
        --  Where s.ItemCode=a.TransactionItem and s.StageCode=d.TransactionItem and s.BranchID=a.BranchID and s.CompID=a.CompID    
        -- )    
    Order by c.Transtamp   
  
  
   
 /*  
          --Old Query  
 Select distinct ---a.DocType as SelDocType, a.DocNo as SelDocNo, a.DocDate as SelDocDate, a.TransactionItem as SelDocItem,            
  d.TransactionItem as ItemCode, e.ItemDescription as ItemDesc, h.SDesc as UOMDesc, h.NoofDecimals as UOMDecimal,             
  d.DocType as DocType, d.DocNo as DocNo, d.DocDate as DocDate,b.LotID, c.Qty, c.FromWarehouseCode, c.FromRackBinCode,             
  c.ToWarehouseCode, c.ToRackBinCode, c.Transtamp as TransactionDate, isnull(g.HeatNo,IsNull('test1','')) As HeatNo      --isnull(g.HeatNo,IsNull(f.HeatNo,'')) As HeatNo         
 From INV_MaterialTran_Dtl a            
 Left Outer Join COM_Trace_MaterialTran_TmpQty b            
  On a.ICode=b.TranID and a.BranchID=b.BranchID and a.CompID=b.CompID and a.Finyear=b.Finyear         
            
 Left Outer Join COM_Trace_MaterialTran_TmpQty c            
  On   b.LotID=c.LotID and b.BranchID=c.BranchID and b.CompID=c.CompID and b.Finyear=c.Finyear           
         
 Left Outer Join     
  (    
   Select * From INV_MaterialTran_Dtl a                  
   Where a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear      
  
   Union All    
    
   Select -(ICode), DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode,    
   ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear     
   From INV_WIPTRAN_DTL a                  
   Where a.BranchID = @BranchID and a.CompID = @CompID and a.Finyear = @Finyear                        
    and not exists    
     (    
    Select * From INV_MaterialTran_Dtl s    
    Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate     
     and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode    
     and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode     
     and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem     
     and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear    
     )     
  )d          
  On c.TranID=d.ICode and c.BranchID=d.BranchID and c.CompID=d.CompID and c.Finyear=d.Finyear            
      
 Left Outer Join INV_Material_Master e             
  On d.TransactionItem=e.ItemCode and d.BranchID=e.BranchID and d.CompID=e.CompID    
        
 Left Outer Join INV_UOM_Master  h      
  On e.UOM=h.Code and e.BranchID=h.BranchID and e.CompID=h.CompID      
            
 Left Outer Join COM_Trace_LotMaster_TmpQty g            
  On b.LotID=g.LotID and b.BranchID=g.BranchID and b.CompID=g.CompID      
            
 Left Outer Join REC_ReceiptEntry_Dtl f            
  On g.DocNo=f.ReceiptEntryNo and g.DocDate=f.ReceiptEntryDate and g.DocType=f.ReceiptEntryType and a.TransactionItem=f.ItemCode    
  and g.BranchID=f.BranchID and g.CompID=f.CompID    
               
 Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@FinYear   and d.TransactionItem is Not null           
  and a.DocType=@DocType and a.DocNo=@DocNo and a.DocDate=@DocDate                  
  and (@ItemUserKey='' OR Exists            
    (            
     Select * From COM_SelectList            
     Where UserKey=@ItemUserKey and SelectStr=a.TransactionItem and BranchID=@BranchID and CompID=@CompID            
    )    
   )             
  --and Exists    
  -- (    
  --  Select * From MPS_Process s    
  --  Where s.ItemCode=a.TransactionItem and s.StageCode=d.TransactionItem and s.BranchID=a.BranchID and s.CompID=a.CompID    
  -- )    
 Order by c.Transtamp             
 */  
  
END 
GO

/****** Object:  StoredProcedure [dbo].[Test_TGR_COM_Trace_MaterialTranLotQty]    Script Date: 17/06/2026 11:31:05 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Test_TGR_COM_Trace_MaterialTranLotQty](@FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID Varchar(3), @CompID Varchar(3), @Finyear Varchar(20))              
AS              
BEGIN              
    SET NOCOUNT ON;              
              
    DECLARE @ContLoop bit;              
    Declare @mTranQty Float, @ChildCode Varchar(30), @QtyAvailable Float      
    Declare @StockItem Varchar(30), @StockNorms Float, @StockTranID bigint      
    Declare @SetItemID int, @SetItem Varchar(30), @SetTranID bigint      
              
    Declare @cICode bigint, @cDocType Varchar(3), @cDocNo int, @cDocDate datetime,  @cTransactionDate datetime , @cTransactionTime datetime, @cTransactionItem Varchar(30), @cTransactionQty Float, @cNorms Float,               
        @cFromWarehouseCode Varchar(6), @cFromRackBinCode Varchar(6), @cToWarehouseCode Varchar(6), @cToRackBinCode Varchar(6) , @cFromItem Varchar(30), @cToItem Varchar(30),              
        @cUserID Varchar(10), @cBranchID Varchar(3), @cCompID Varchar(3)             
              
    Declare @LotID bigint, @ReqQty decimal(15, 5);              
            
    /* For Record Count */            
    DECLARE @TotalRecordCount int, @CurrentRecordCount int;            
            
    Select @TotalRecordCount=COUNT(*)  
	From           
		(
			Select * From INV_MaterialTran_Dtl a              
			Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear   
				and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				and Exists 
					(
						Select * From TMP_TracebaleItems t 
						Where t.ItemCode=a.TransactionItem
					)   
				and DocType <> 'OPBAL' 

			Union All

			Select -(ICode), DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode,
				ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
			From INV_WIPTran_Dtl a              
			Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear   
				and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				and Exists 
					(
						Select * From TMP_TracebaleItems t 
						Where t.ItemCode=a.TransactionItem
					)  
				and not exists
					(
						Select * From INV_MaterialTran_Dtl s
						Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
							and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
							and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
							and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
							and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
					) 
				and DocType <> 'OPBAL' and Not (DocType='IGR' and FromWarehouseCode='WIP')
		)a
    Left Outer Join INV_Material_Master b              
        On a.TransactionItem=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID              
    Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear             
        and b.ItemNature in ('R','CR', 'C','CC', 'F', 'CF')               
        
      
    DECLARE CurMaterialTran CURSOR FOR              
        Select ICode, DocType, DocNo, DocDate, (TransactionDate + Convert(varchar(8), TransactionTime, 108)) as TransactionDate, TransactionItem, TransactionQty, 
			Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode,               
            FromItem, ToItem, a.UserID, a.BranchID, a.CompID              
        From --INV_MaterialTran_Dtl a 
			(
				Select * From INV_MaterialTran_Dtl a              
				Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear   
					and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
					and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
					and Exists 
						(
							Select * From TMP_TracebaleItems t 
							Where t.ItemCode=a.TransactionItem
						)  
					and DocType <> 'OPBAL'  

				Union All

				Select -(ICode), DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode,
					ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA, UserId, BranchId, CompId, Finyear 
				From INV_WIPTran_Dtl a              
				Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear   
					and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
					and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
					and Exists 
						(
							Select * From TMP_TracebaleItems t 
							Where t.ItemCode=a.TransactionItem
						)  
					and not exists
						(
							Select * From INV_MaterialTran_Dtl s
							Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
								and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
								and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
								and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
								and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
						) 
					and DocType <> 'OPBAL' and Not (DocType='IGR' and FromWarehouseCode='WIP')
                    --and Not (DocType='IGR' and FromWarehouseCode='WIP' and ToWarehouseCode='WAP')
			)a
        Left Outer Join INV_Material_Master b              
            On a.TransactionItem=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID              
        Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear             
            and b.ItemNature in ('R','CR', 'C','CC', 'F', 'CF')
        Order by (TransactionDate + Convert(varchar(8), TransactionTime, 108)), a.ICode              
              
    OPEN CurMaterialTran              
    FETCH NEXT FROM CurMaterialTran into  @cICode, @cDocType, @cDocNo, @cDocDate, @cTransactionDate, @cTransactionItem, @cTransactionQty, @cNorms, @cFromWarehouseCode, @cFromRackBinCode,               
            @cToWarehouseCode, @cToRackBinCode, @cFromItem, @cToItem, @cUserID, @cBranchID, @cCompID           
               
    PRINT 'Total Record Count: ' + Convert(varchar, @TotalRecordCount);            
             
    SET @CurrentRecordCount=0;            
     
    WHILE @@FETCH_STATUS = 0              
		BEGIN              
			SET @CurrentRecordCount = @CurrentRecordCount + 1;  
			          
			PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)            
				+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Initiated.';            
                 
			Select @StockNorms = 1, @StockItem=@cTransactionItem              
              
			IF ((@cDocType = 'SV' and @cFromWarehouseCode='SV')  
                    OR  (Exists (Select * From COM_DocumentType_Master s 
								    Where s.PertainingTo in ('M') and s.ModuleName='INV' and s.DocumentType=@cDocType
								        and s.BranchID=@cBranchID and s.CompID=@cCompID)))
            
                                            
				BEGIN              
					IF Not Exists (Select * from Test_COM_Trace_LotMaster_TmpQty            
									Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate            
										and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID            
								)    
						BEGIN            
							/* Lot ID Generation */              
							Select @LotID=IsNull(Max(LotID),0)+1              
							From Test_COM_Trace_LotMaster_TmpQty                
							Where BranchID=@BranchID and CompID=@CompID              

							Insert into Test_COM_Trace_LotMaster_TmpQty              
								Select @cDocType, @cDocNo, @cDocDate, @cTransactionItem, @LotID as LotID, '' as HeatNo,             
									@cUserID, @cBranchID, @cCompID, @cTransactionDate              
						END            
					ELSE            
						BEGIN            
							SELECT @LotID=LotID 
							From Test_COM_Trace_LotMaster_TmpQty            
							Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate            
								and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID            
						END            
            
					Insert into Test_COM_Trace_MaterialTran_TmpQty              
						Select @cICode, @LotID, @cTransactionItem, @cTransactionQty as TransactionQty, @cTransactionItem, @cTransactionQty as ChildQty, -4 as CriteriaCode,    
							@cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,    
							'0' as ReverseEntryFlg, -2 UserID, @cBranchID as BranchID, @cCompID as CompID, @Finyear as Finyear, @cTransactionDate    
              
					PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)            
						+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - SV/MR Entry.';            
				END 
				 
			ELSE IF @cDocType = 'RR'  
						            
				BEGIN 
				
					IF Exists (Select * From Rec_ReceiptEntry_Hdr 
								Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate 
									and BranchID=@cBranchID and CompID=@cCompID and InwardType in ('P','C','U'))   --Purchase, CashPurchase, CustomerSuppliedProduct
						BEGIN          
							IF Not Exists (Select * From Test_COM_Trace_LotMaster_TmpQty            
											Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate            
												and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID)            
								BEGIN            
									/* Lot ID Generation */              
									Select @LotID=IsNull(Max(LotID),0)+1              
									From Test_COM_Trace_LotMaster_TmpQty                
									Where BranchID=@BranchID and CompID=@CompID              
              
									Insert into Test_COM_Trace_LotMaster_TmpQty              
										Select a.ReceiptEntryType as DocType, a.ReceiptEntryNo as DocNo, a.ReceiptEntryDate as DocDate, @cTransactionItem, @LotID as LotID, 'H1' as HeatNo,             
											@cUserID, @cBranchID, @cCompID, @cTransactionDate              
										From Rec_ReceiptEntry_Hdr a              
										--Left Outer Join REC_IncomingReceipt_Dtl b              
										--	On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.DocType=b.DocType and a.BranchID=b.BranchID and a.CompID=b.CompID              
										Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear --and b.ItemCode=@StockItem              
											and a.ReceiptEntryType=@cDocType and a.ReceiptEntryNo=@cDocNo and a.ReceiptEntryDate=@cDocDate       
								END            
							ELSE            
								BEGIN            
									SELECT @LotID=LotID 
									From Test_COM_Trace_LotMaster_TmpQty            
									Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate            
										and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID            
								END            
            
							Insert into Test_COM_Trace_MaterialTran_TmpQty              
								Select @cICode, @LotID, @cTransactionItem, @cTransactionQty as TransactionQty, @cTransactionItem, @cTransactionQty as ChildQty, -4 as CriteriaCode,               
									@cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
									'0' as ReverseEntryFlg, -2 UserID, @cBranchID as BranchID, @cCompID as CompID, @Finyear as Finyear, @cTransactionDate               
         
							PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)            
								+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - RR (Purchase, CashPurchase, Customer Supplied Product) Entry.';
						END 
					ELSE
						BEGIN

                            IF (@cToWarehouseCode='UI' and Exists (Select * From Rec_ReceiptEntry_Hdr 
								                                    Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate 
									                                    and BranchID=@cBranchID and CompID=@cCompID and InwardType in ('S','L','M')))   --Subcontract, SubcontractPartial, DismantlingDC
                                BEGIN   
                                    /* TranID Generation */ 
                                    Declare @MaxTranID bigint;             
									    Select @MaxTranID=IsNull(Max(TranID),0)+1              
									    From Test_COM_Trace_MaterialTran_TmpQty                
									    Where ReverseEntryFlg='1' and BranchID=@BranchID and CompID=@CompID

                                    --SentItem -> Subcontract to Dummy
                                    Insert into Test_COM_Trace_MaterialTran_TmpQty
                                        Select @MaxTranID as ICode, b.LotID, a.TransactionItem, b.CBQty as TransactionQty, a.TransactionItem as ChildCode, b.CBQty as ChildQty, -4 as CriteriaCode,               
									        a.ToWarehouseCode as FromWarehouseCode, a.ToRackBinCode as FromRackBinCode, 'DUM' as ToWarehouseCode, '' as ToRackBinCode,               
									        '1' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, @cTransactionDate       
								        From INV_MATERIALTRAN_DTL a						
								        Cross Apply fn_Test_COM_Trace_AsOnDate_Stock_ItemWHS_LotQty(a.TransactionItem, a.ToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)b
								        Where a.BranchID=@cBranchID and a.CompID=@cCompID
                                            and Exists
									        (
										        Select * From Rec_ReceiptEntry_Dtl s
										        Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID
											        and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate 
											        and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End
									        )
                    
                                    --ReceivedItem -> Dummy to Subcontract
                                    Insert into Test_COM_Trace_MaterialTran_TmpQty
                                        Select (@MaxTranID+1) as ICode, b.LotID, @cTransactionItem as TransactionItem, b.CBQty as TransactionQty, @cTransactionItem as ChildCode, b.CBQty as ChildQty, -4 as CriteriaCode,               
									        'DUM' as FromWarehouseCode, '' as FromRackBinCode, @cFromWarehouseCode as ToWarehouseCode, @cFromRackBinCode as ToRackBinCode,               
									        '1' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, @cTransactionDate       
								        From INV_MATERIALTRAN_DTL a						
								        Cross Apply fn_Test_COM_Trace_AsOnDate_Stock_ItemWHS_LotQty(a.TransactionItem, 'DUM', @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)b
								        Where a.BranchID=@cBranchID and a.CompID=@cCompID
                                    and Exists
									        (
										        Select * From Rec_ReceiptEntry_Dtl s
										        Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID
											        and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate 
											        and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End
									        )

                                    Insert into Test_COM_Trace_MaterialTran_TmpQty
								        Select @cICode, b.LotID, @cTransactionItem, b.CBQty as TransactionQty, @cTransactionItem as ChildCode, b.CBQty as ChildQty, -4 as CriteriaCode,               
									        @cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
									        '0' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, @cTransactionDate       
								        From INV_MaterialTran_Dtl a						
								        Cross Apply fn_Test_COM_Trace_AsOnDate_Stock_ItemWHS_LotQty(@cTransactionItem, a.ToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)b
								        Where Exists
									        (
										        Select * From Rec_ReceiptEntry_Dtl s
										        Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID
											        and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate 
											        and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End
									        )
                                END 
                            ELSE
                                BEGIN
                                    Insert into Test_COM_Trace_MaterialTran_TmpQty
								        Select @cICode, b.LotID, @cTransactionItem, b.CBQty as TransactionQty, @cTransactionItem as ChildCode, b.CBQty as ChildQty, -4 as CriteriaCode,               
									        @cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
									        '0' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, @cTransactionDate       
                                        From fn_Test_COM_Trace_AsOnDate_Stock_ItemWHS_LotQty(@cTransactionItem, @cFromWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)b
                                END
  
							/*Insert into Test_COM_Trace_MaterialTran_TmpQty
								Select @cICode, b.LotID, @cTransactionItem, b.CBQty as TransactionQty, @cTransactionItem as ChildCode, b.CBQty as ChildQty, -4 as CriteriaCode,               
									@cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
									-2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, @cTransactionDate       
								From INV_MaterialTran_Dtl a						
								Cross Apply fn_Test_COM_Trace_AsOnDate_Stock_ItemWHS_LotQty(a.TransactionItem, a.ToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)b
								Where Exists
									(
										Select * From Rec_ReceiptEntry_Dtl s
										Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID
											and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate 
											and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End
									)*/

							PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)            
								+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - RR Other Entry.';
						END					       
				END              
			ELSE              
				BEGIN              
					IF (@cFromWarehouseCode='WIP' AND @cToWarehouseCode = 'WAP')  /* Set Transfer */    
						BEGIN      
							Insert into Test_COM_Trace_MaterialTran_TmpQty              
								Select @cICode, v.LotID, @cTransactionItem, v.CBQty as TransactionQty, /* Check Transaction Qty Concept */ 
									isNull(@ChildCode, 0), isNull(@QtyAvailable, 0) as ChildQty, -4 as CriteriaCode,               
									@cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
									'0' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, @cTransactionDate      
								From fn_Test_COM_Trace_AsOnDate_Stock_ItemWHS_LotQty(@cTransactionItem, @cFromWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) v       
      
      
							Select @SetTranID = -(Min(a.ICode)), @SetItem=a.TransactionItem     
							From INV_WIPTran_Dtl a                
							Where a.DocType=@CDocType and a.DocNo=@cDocNo and a.DocDate=@cDocDate and a.FromItem=@cFromItem and a.ToItem=@cToItem 
								and a.ToWarehouseCode = 'WIP' and a.ICode>-(@cICode)
								and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear        
							Group by a.TransactionItem
            
							Insert into Test_COM_Trace_MaterialTran_TmpQty              
								Select @SetTranID, v.LotID, @SetItem, v.Qty/@cNorms as TransactionQty, /* Check Transaction Qty Concept */              
									v.ChildCode, v.ChildQty as ChildQty, -4 as CriteriaCode,               
									@cDocType as FromWarehouseCode, @cToRackBinCode as FromRackBinCode, @cFromWarehouseCode as ToWarehouseCode, @cFromRackBinCode as ToRackBinCode,               
									'0' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, @cTransactionDate      
								From Test_COM_Trace_MaterialTran_TmpQty v      
								Where v.TranID=@cICode and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear            
            
							PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)            
							+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - WAP Entry.' + 'Norms - ' + Convert(varchar, @cNorms);         
   
						END   
                            
					--ELSE IF (NOT (@cFromWarehouseCode='WAP' AND @cToWarehouseCode = 'WIP'))     
                    
                    ELSE IF (NOT (  (Exists (Select * From COM_DocumentType_Master s 
									            Where s.PertainingTo in ('PI', 'SI', 'LO','R') and s.ModuleName='QC' and s.DocumentType=@cFromWarehouseCode
										        and s.BranchID=@cBranchID and s.CompID=@cCompID)
								
								        OR (@cDocType='LOG')
                                
                                    ) AND @cToWarehouseCode = 'WIP'))     

						BEGIN             
							SET @ReqQty=Convert(decimal(15, 5), @cTransactionQty*@StockNorms);              
              
							Insert into Test_COM_Trace_MaterialTran_TmpQty              
							    Select @cICode, v.LotID, @cTransactionItem, v.CBQty*@StockNorms as TransactionQty, /* Check Transaction Qty Concept */ 
								    isNull(@ChildCode, 0), isNull(@QtyAvailable, 0) as ChildQty, -4 as CriteriaCode,               
								    @cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
								    '0' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, @cTransactionDate              
							    From fn_Test_COM_Trace_AsOnDate_Stock_ItemWHS_LotQty(@StockItem, @cFromWarehouseCode, @ReqQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) v              
            
							PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)       
								+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - Other Entry.';            
						END       
				END              
              
			FETCH NEXT FROM CurMaterialTran into  @cICode, @cDocType, @cDocNo, @cDocDate,  @cTransactionDate, @cTransactionItem, @cTransactionQty, @cNorms, @cFromWarehouseCode, @cFromRackBinCode,               
					@cToWarehouseCode, @cToRackBinCode, @cFromItem, @cToItem, @cUserID, @cBranchID, @cCompID          
		END              
              
	PRINT 'Process Completed';            
            
	close CurMaterialTran              
	deallocate CurMaterialTran              
               
END 


GO

