/****** Object:  StoredProcedure [dbo].[TEST20240716_TGR_To_Insert_COM_Trace_MaterialTranLotQty]    Script Date: 17/06/2026 11:31:05 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[TEST20240716_TGR_To_Insert_COM_Trace_MaterialTranLotQty](@FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID Varchar(3), @CompID Varchar(3), @Finyear Varchar(20))
AS  
BEGIN    -- # 1.1                                                    
    SET NOCOUNT ON;     

    DECLARE @ContLoop bit;              
    Declare @mTranQty Float, @ChildCode Varchar(30), @QtyAvailable Float      
    Declare @StockItem Varchar(30), @StockNorms Float, @StockTranID bigint      
    Declare @SetItemID int, @SetItem Varchar(30), @SetTranID bigint      
              
    Declare @cICode bigint, @cDocType Varchar(3), @cDocNo int, @cDocDate datetime,  @cTransactionDate datetime , @cTransactionTime datetime, @cTransactionItem Varchar(30), @cTransactionQty Float, @cNorms Float,               
        @cFromWarehouseCode Varchar(6), @cFromRackBinCode Varchar(6), @cToWarehouseCode Varchar(6), @cToRackBinCode Varchar(6) , @cFromItem Varchar(30), @cToItem Varchar(30),              
        @cUserID Varchar(10), @cBranchID Varchar(3), @cCompID Varchar(3), @cFinyear Varchar(20)             
              
    Declare @LotID bigint, @ReqQty decimal(15, 5), @SubLotID bigint;              

    /* For Record Count */            
    DECLARE @TotalRecordCount int, @CurrentRecordCount int;     
        Select @TotalRecordCount=COUNT(*)  
	    From           
		    (
			    Select * From INV_MaterialTran_Dtl a              
			    Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)   --'04-2023 03-2024', 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				    and Exists 
					    (
						    Select * From BOM_TraceableItems t 
						    Where t.ItemCode=a.TransactionItem  --and t.ItemCode in ('1U0810200R','2U510131T0','2U510132T0','2U510133T0','2U510130T0')
					    )   
				    and DocType <> 'OPBAL' 

			    Union All

			    Select -(ICode), DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode,
				    ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
			    From INV_WIPTran_Dtl a              
			    Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)  --'04-2023 03-2024', 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				    and Exists 
					    (
						    Select * From BOM_TraceableItems t 
						    Where t.ItemCode=a.TransactionItem  --and t.ItemCode in ('1U0810200R','2U510131T0','2U510132T0','2U510133T0','2U510130T0')
					    )  
				    and not exists
					    (
						    Select * From INV_MaterialTran_Dtl s
						    Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
							    and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
							    and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
							    and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
							    and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
					    ) 
				    and DocType <> 'OPBAL' and Not (DocType='IGR' and FromWarehouseCode='WIP')
		    )a
        Left Outer Join INV_Material_Master b              
            On a.TransactionItem=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID              
        Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)          --'04-2023 03-2024', 
            --and b.ItemNature in ('R','CR', 'C','CC', 'F', 'CF')         


     DECLARE CurMaterialTran CURSOR FOR              
        Select ICode, DocType, DocNo, DocDate, (TransactionDate + Convert(varchar(8), TransactionTime, 108)) as TransactionDate, TransactionItem, TransactionQty, 
		    Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode,               
            FromItem, ToItem, a.UserID, a.BranchID, a.CompID, a.Finyear              
        From --INV_MaterialTran_Dtl a              
		    (
			    Select * From INV_MaterialTran_Dtl a              
			    Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)     --'04-2023 03-2024', 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				    and Exists 
					    (
						    Select * From BOM_TraceableItems t 
						    Where t.ItemCode=a.TransactionItem --and t.ItemCode in ('1U0810200R','2U510131T0','2U510132T0','2U510133T0','2U510130T0')
					    )  
				    and DocType <> 'OPBAL'  

			    Union All

			    Select -(ICode), DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode,
				    ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA, UserId, BranchId, CompId, Finyear 
			    From INV_WIPTran_Dtl a              
			    Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear) --'04-2023 03-2024',
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				    and Exists 
					    (
						    Select * From BOM_TraceableItems t 
						    Where t.ItemCode=a.TransactionItem  --and t.ItemCode in ('1U0810200R','2U510131T0','2U510132T0','2U510133T0','2U510130T0')
					    )  
				    and not exists
					    (
						    Select * From INV_MaterialTran_Dtl s
						    Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
							    and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
							    and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
							    and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
							    and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
					    ) 
				    and DocType <> 'OPBAL' and Not (DocType='IGR' and FromWarehouseCode='WIP')
					--and Not (DocType='IGR' and FromWarehouseCode='WIP' and ToWarehouseCode='WAP')
		    )a
        Left Outer Join INV_Material_Master b              
            On a.TransactionItem=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID              
        Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)             --'04-2023 03-2024', 
            --and b.ItemNature in ('R','CR', 'C','CC', 'F', 'CF')
        Order by (TransactionDate + Convert(varchar(8), TransactionTime, 108)), a.ICode           

     
    OPEN CurMaterialTran              
    FETCH NEXT FROM CurMaterialTran into  @cICode, @cDocType, @cDocNo, @cDocDate, @cTransactionDate, @cTransactionItem, @cTransactionQty, @cNorms, @cFromWarehouseCode, @cFromRackBinCode,               
                                        @cToWarehouseCode, @cToRackBinCode, @cFromItem, @cToItem, @cUserID, @cBranchID, @cCompID, @cFinyear           
               
    PRINT 'Total Record Count: ' + Convert(varchar, @TotalRecordCount);            
             
    SET @CurrentRecordCount=0;            
     
    WHILE @@FETCH_STATUS = 0              
		BEGIN  
            SET @CurrentRecordCount = @CurrentRecordCount + 1;  
			          
			PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)     
				+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Initiated.';

            Declare @StgCnt As int;
                SET @StgCnt=0;

            /* PRINT 'START 1' */  
            --IF Exists(Select * From BOM_TraceableItems t Where t.ItemCode=@cTransactionItem)          
                BEGIN /* PRINT 'START 1.1' */     
                  --/* PRINT 'START Declaration' */                                         
              --Declare @ChildCode Varchar(30), @QtyAvailable Float;                                  
                    --Declare @StockItem Varchar(30), @StockNorms Float;                                
                    --Declare @SetItemID int, @SetItem Varchar(30), @SetTranID bigint, @PrevTranQty Float, @PrevNorms Float;                            
                                 
                    --Declare @cICode bigint, @cDocType Varchar(3), @cDocNo int, @cDocDate datetime, @cTransactionDate datetime,   
                    --    @cTransactionTime datetime, @cTransactionItem Varchar(30), @cTransactionQty Float, @cNorms Float,                                           
                    --    @cFromWarehouseCode Varchar(6), @cFromRackBinCode Varchar(6), @cToWarehouseCode Varchar(6),   
                    --    @cToRackBinCode Varchar(6), @cFromItem Varchar(30), @cToItem Varchar(30), @cUserID Varchar(10),   
                    --    @cBranchID Varchar(3), @cCompID Varchar(3), @cFinyear Varchar(20), @cTranstamp datetime                                           
                                          
                    --Declare @LotID bigint, @ReqQty decimal(15, 5);                                            
                    --Declare @SubLotID bigint;                            
                            
                    --Declare @AsOnDate datetime, @RptDate datetime;                            
                    --    Select @AsOnDate = getdate(), @RptDate=@AsOnDate;    
                         
                    Select @StockNorms=1, @StockItem=@cTransactionItem;                                  
                            
                    /* Inserting Data into Trace Table*/                            
                    IF ((@cDocType = 'SV' and @cFromWarehouseCode='SV')                     
                        OR  (Exists (Select * From COM_DocumentType_Master s                             
                                        Where s.PertainingTo in ('M') and s.ModuleName='INV' and s.DocumentType=@cDocType                            
                                            and s.BranchID=@cBranchID and s.CompID=@cCompID          
                                    )          
                            ) )                                         
                        BEGIN                                         
                            IF Not Exists (Select * from TEST20240716_COM_Trace_LotMaster_TmpQty                                        
                                            Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate          
                                                and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID)                                                                      
                                BEGIN                            
                                    /* Lot ID Generation */                                          
                                    Select @LotID=IsNull(Max(LotID),0)+1                                          
                                    From TEST20240716_COM_Trace_LotMaster_TmpQty                         
                                    Where BranchID=@cBranchID and CompID=@cCompID                                             
                                       
                                    /* Insert Data Into TEST20240716_COM_Trace_LotMaster_TmpQty --> In Future need to remove the before Union Part */     
                                    Insert into TEST20240716_COM_Trace_LotMaster_TmpQty              
                                        Select @cDocType, @cDocNo, @cDocDate, @cTransactionItem, @LotID As LotID, 1 As SubLotID, '' As HeatNo,                         
                                            '' As ManufactureDate, '' As ShelfLifeDays, @cUserID, @cBranchID, @cCompID, @cTransactionDate     
                                        UNION             
                                        /* the below From part newly added */                         
                                        Select @cDocType, @cDocNo, @cDocDate, @cTransactionItem, @LotID As LotID, IsNull(a.SubLotID, 1) As SubLotID, --'' As HeatNo,                                         
                                            a.HeatNo, a.ManufactureDate, a.ShelfLifeDays, @cUserID, @cBranchID, @cCompID, @cTransactionDate                             
                                        From Rec_ReceiptEntry_Dtl_Trace a                          
                                        Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate and a.ItemCode=@cTransactionItem                          
                                            and a.BranchId=@cBranchID and a.CompId=@cCompID                                 
                                END                                         
                            ELSE                                        
                                BEGIN                                        
                                    SELECT @LotID=LotID, @SubLotID=IsNull(SubLotID, 1)          
                                    From TEST20240716_COM_Trace_LotMaster_TmpQty                                        
                                    Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate                                        
                                        and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID                                        
                                END  
                                              
                            /* Insert Data Into TEST20240716_COM_Trace_MaterialTran_TmpQty */                               
                            Insert into TEST20240716_COM_Trace_MaterialTran_TmpQty   
                                Select @cICode, IsNull(@LotID, -1),  IsNull(@SubLotID, 1), @cTransactionItem, @cTransactionQty As TransactionQty, @cTransactionItem,   
                                    @cTransactionQty As ChildQty, -4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode,   
                                    @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,                                
                                    '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate     
                   
                            /* PRINT 'ICode: ' + Convert(varchar, @cICode) + ' - Completed - SV Entry.'; */                                     
                        END 
                    
                    ELSE If @cDocType='RR'                                              
                        BEGIN  
                            PRINT 'RR START'
                            
                            IF Exists (Select * From Rec_ReceiptEntry_Hdr                             
                                        Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate                             
                                            and BranchID=@cBranchID and CompID=@cCompID and InwardType in ('P','C','U'))   --Purchase, CashPurchase, CustomerSuppliedProduct   
								BEGIN                                      
                                    IF Not Exists (Select * From TEST20240716_COM_Trace_LotMaster_TmpQty                                        
                                                 Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate                                        
                                                            and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID  
                                                    )                                        
                                        BEGIN   /* Receipt Entry */                      
                                            /* Lot ID Generation */                                          
                                            Select @LotID=IsNull(Max(LotID),0)+1                                          
                                            From TEST20240716_COM_Trace_LotMaster_TmpQty                                            
                                            Where BranchID=@cBranchID and CompID=@cCompID                         
                                          
                                            /* PRINT 'Lot ID Generation'  + Convert(varchar, @LotID) */    
                           
                                            /* Insert Data Into TEST20240716_COM_Trace_LotMaster_TmpQty */                                
                                            Insert into TEST20240716_COM_Trace_LotMaster_TmpQty   
                                                Select a.ReceiptEntryType As DocType, a.ReceiptEntryNo As DocNo, a.ReceiptEntryDate As DocDate, @cTransactionItem,                             
                                                    @LotID As LotID, IsNull(c.SubLotID, 1) As SubLotID, IsNull(c.HeatNo,'') as HeatNo, 
													IsNull(c.ManufactureDate,'') as ManufactureDate, IsNull(c.ShelfLifeDays,0) as ShelfLifeDays, 
													@cUserID, @cBranchID, @cCompID, @cTransactionDate                                          
                                                From Rec_ReceiptEntry_Hdr a                                          
                                                Left Outer Join Rec_ReceiptEntry_Dtl b                                          
                                                    On a.ReceiptEntryNo=b.ReceiptEntryNo and a.ReceiptEntryDate=b.ReceiptEntryDate and a.ReceiptEntryType=b.ReceiptEntryType                             
                                                        and a.BranchID=b.BranchID and a.CompID=b.CompID                           
                                                Left Outer Join Rec_ReceiptEntry_Dtl_Trace c                                          
                                                    On c.ReceiptEntryNo=b.ReceiptEntryNo and c.ReceiptEntryDate=b.ReceiptEntryDate and c.ReceiptEntryType=b.ReceiptEntryType                             
                                                        and c.ItemCode=b.ItemCode and b.ItemSeq=c.ItemSeq and c.BranchID=b.BranchID and c.CompID=b.CompID                                         
                                                Where a.BranchID=@cBranchID and a.CompID=@cCompID and a.Finyear=@cFinyear and b.ItemCode=@cTransactionItem                                          
                                                    and a.ReceiptEntryType=@cDocType and a.ReceiptEntryNo=@cDocNo and a.ReceiptEntryDate=@cDocDate                        
    
                                            /* Insert Data Into TEST20240716_COM_Trace_MaterialTran_TmpQty */                     
                                            Insert into TEST20240716_COM_Trace_MaterialTran_TmpQty  
                                                Select @cICode, @LotID, IsNull(c.SubLotID, 1) as SubLotID, @cTransactionItem, IsNull(c.Qty, @cTransactionQty) As TransactionQty, 
													@cTransactionItem, IsNull(c.Qty, @cTransactionQty) As ChildQty,          
													/* @cTransactionQty As TransactionQty,   @cTransactionItem,   @cTransactionQty As ChildQty, */                      
                                                    -4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode,   
                                                    @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID,   
                                                    @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                           
                                                From Rec_ReceiptEntry_Dtl b
												Left Outer Join Rec_ReceiptEntry_Dtl_Trace c     
													 On c.ReceiptEntryNo=b.ReceiptEntryNo and c.ReceiptEntryDate=b.ReceiptEntryDate and c.ReceiptEntryType=b.ReceiptEntryType                             
                                                     and c.ItemCode=b.ItemCode and b.ItemSeq=c.ItemSeq and c.BranchID=b.BranchID and c.CompID=b.CompID          
                                                Where b.ReceiptEntryNo=@cDocNo and b.ReceiptEntryDate=@cDocDate and b.ReceiptEntryType=@cDocType                           
                                                    and b.ItemCode=@cTransactionItem and b.BranchID=@cBranchID and b.CompID=@cCompID  
                                 
                                            /* PRINT 'TEST20240716_COM_Trace_MaterialTran_TmpQty - Receipt Entry' */                     
                                        END  
                                    ELSE                                        
                                        BEGIN                                        
                                            Select @LotID=LotID, @SubLotID=SubLotID                             
                                            From TEST20240716_COM_Trace_LotMaster_TmpQty                                        
                                            Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate                                        
                                                and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID                        
                                            /* PRINT 'Lot ID Generation' */                                           
                                         
  
                                            /*PRINT 'Lot ID Generation'    + Convert(varchar, @LotID) */                
                               
                                            /* Acceptance Entry - If User enter Accepted, Rejection, Scrap qty then material Tran dtl table have 3 rows   
                                            for three different whs Since this 3 entries need to be saved in  table TEST20240716_COM_Trace_MaterialTran_TmpQty    
                                            individually As well As SublotID wise. So we saved the entries As below */                  
                         
                                            /* Insert Data Into TEST20240716_COM_Trace_MaterialTran_TmpQty - Accepted Qty */                    
                                            Insert into TEST20240716_COM_Trace_MaterialTran_TmpQty  
                                                Select @cICode, @LotID, IsNull(c.SubLotID,1) as SubLotID, @cTransactionItem, 
                                                    Case When IsNull(c.AcceptedQty,0)>0 Then c.AcceptedQty Else r.AcceptedQty End As TransactionQty, @cTransactionItem,
                                                    Case When IsNull(c.AcceptedQty,0)>0 Then c.AcceptedQty Else r.AcceptedQty End As ChildQty,                       
													1 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,
                                                    '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                           
												From Rec_ReceiptEntry_Dtl r
                                                Left Outer Join Rec_ReceiptEntry_Dtl_Trace c
                                                    On c.ReceiptEntryNo=r.ReceiptEntryNo and c.ReceiptEntryDate=r.ReceiptEntryDate and c.ReceiptEntryType=r.ReceiptEntryType and c.ItemCode=r.ItemCode
                                                    and c.BranchID=r.BranchID and c.CompID=r.CompID 
                                                Where r.ReceiptEntryNo=@cDocNo and r.ReceiptEntryDate=@cDocDate and r.ReceiptEntryType=@cDocType                           
                                                    and r.ItemCode=@cTransactionItem and r.BranchID=@cBranchID and r.CompID=@cCompID and r.AcceptedQty > 0                      
                                                    and @cToWarehouseCode not in (Select WarehouseCode From Inv_Warehouse_Master Where WarehouseNature in ('Rejection', 'Scrap'))                
                               
                                            /* PRINT 'TEST20240716_COM_Trace_MaterialTran_TmpQty - Accepted Entry - Accepted Qty' */                    
                    
                                            /* Insert Data Into TEST20240716_COM_Trace_MaterialTran_TmpQty - Rejected Qty */                    
                                            Insert into TEST20240716_COM_Trace_MaterialTran_TmpQty   
                                                Select @cICode, @LotID, IsNull(c.SubLotID,1) as SubLotID, @cTransactionItem, 
                                                    Case When IsNull(c.RejectedQty,0)>0 Then c.RejectedQty Else r.RejectionQty End As TransactionQty, @cTransactionItem,  
                                                    Case When IsNull(c.RejectedQty,0)>0 Then c.RejectedQty Else r.RejectionQty End As ChildQty,                       
                                                    2 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode,          
                                                    @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear,           
                                                    @cTransactionDate                                              
                                                From Rec_ReceiptEntry_Dtl r                                      
                                                Left Outer Join Rec_ReceiptEntry_Dtl_Trace c    
                                                    On c.ReceiptEntryNo=r.ReceiptEntryNo and c.ReceiptEntryDate=r.ReceiptEntryDate and c.ReceiptEntryType=r.ReceiptEntryType and c.ItemCode=r.ItemCode
                                                    and c.BranchID=r.BranchID and c.CompID=r.CompID 
                                                Where r.ReceiptEntryNo=@cDocNo and r.ReceiptEntryDate=@cDocDate and r.ReceiptEntryType=@cDocType                           
                                                    and r.ItemCode=@cTransactionItem and r.BranchID=@cBranchID and r.CompID=@cCompID and r.RejectionQty > 0                      
                                                    and @cToWarehouseCode not in (Select WarehouseCode From Inv_Warehouse_Master Where WarehouseNature in ('InHouse', 'Scrap'))                
                
                                            /* PRINT 'TEST20240716_COM_Trace_MaterialTran_TmpQty - Accepted Entry - Rejected Qty' */                    
                    
                                            /* Insert Data Into TEST20240716_COM_Trace_MaterialTran_TmpQty - Scrap Qty */                    
                                            Insert into TEST20240716_COM_Trace_MaterialTran_TmpQty  
                                                Select @cICode, @LotID, IsNull(c.SubLotID,1) as SubLotID, @cTransactionItem, 
													Case When IsNull(c.ScrapQty,0)>0 Then c.ScrapQty Else r.ScrapQty End As TransactionQty, @cTransactionItem, 
                                                    Case When IsNull(c.ScrapQty,0)>0 Then c.ScrapQty Else r.ScrapQty End As ChildQty,                                            
                                                    4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode,          
                                                    @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear,          
                                                    @cTransactionDate                                           
                                                From Rec_ReceiptEntry_Dtl r                                        
                                                Left Outer Join  Rec_ReceiptEntry_Dtl_Trace c
                                                    On c.ReceiptEntryNo=r.ReceiptEntryNo and c.ReceiptEntryDate=r.ReceiptEntryDate and c.ReceiptEntryType=r.ReceiptEntryType and c.ItemCode=r.ItemCode
                                                    and c.BranchID=r.BranchID and c.CompID=r.CompID 
                                                Where r.ReceiptEntryNo=@cDocNo and r.ReceiptEntryDate=@cDocDate and r.ReceiptEntryType=@cDocType                           
                                                    and r.ItemCode=@cTransactionItem and r.BranchID=@cBranchID and r.CompID=@cCompID and r.ScrapQty > 0                      
                                                    and @cToWarehouseCode not in ( Select WarehouseCode From Inv_Warehouse_Master Where WarehouseNature in ('InHouse', 'Rejection'))                
                
                                            /* PRINT 'TEST20240716_COM_Trace_MaterialTran_TmpQty - Accepted Entry - Scrap Qty' */                     
                                    END  
                                END  
                                /* PRINT 'ICode: ' + Convert(varchar, @cICode) + ' - Completed - RR (Purchase, CashPurchase, Customer Supplied Product) Entry.'; */                          

                            ELSE If @cToWarehouseCode='UI' and Exists (Select * From Rec_ReceiptEntry_Hdr                             
                                                                        Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate                            
                                                                        and BranchID=@cBranchID and CompID=@cCompID and InwardType in ('S','L','M'))                
                                BEGIN     /* Subcontract, SubcontractPartial, DismantlingDC */         --# 1.1.1             
                                    /* TranID Generation */                             
                                    Declare @MaxTranID bigint;                                         
                                        Select @MaxTranID=IsNull(Max(TranID),0)+1                                          
                                        From TEST20240716_COM_Trace_MaterialTran_TmpQty                                            
                                        Where ReverseEntryFlg='1' and BranchID=@cBranchID and CompID=@cCompID                            
                        
                                  /* Insert Data Into TEST20240716_COM_Trace_MaterialTran_TmpQty - SentItem -> Subcontract to Dummy */                        
                                    Insert into TEST20240716_COM_Trace_MaterialTran_TmpQty  
                                        Select @MaxTranID As ICode, b.LotID, b.SubLotID As SubLotID, a.TransactionItem, b.CBQty As TransactionQty,   
											a.TransactionItem As ChildCode, b.CBQty As ChildQty, -4 As CriteriaCode, a.ToWarehouseCode As FromWarehouseCode,   
                                            a.ToRackBinCode As FromRackBinCode, 'DUM' As ToWarehouseCode, '' As ToRackBinCode, '1' As ReverseEntryFlg,   
                                            -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                   
                                        From INV_MATERIALTRAN_DTL a                                  
                                        Cross Apply fn_TEST20240716_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(a.TransactionItem, a.ToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b
                                        Where a.BranchID=@cBranchID and a.CompID=@cCompID                            
                                            and Exists ( Select * From Rec_ReceiptEntry_Dtl s       
                                                        Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                            
                                                            and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                             
                                                            and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                            
                                                    )                            
                                                
                                    /* Insert Data Into TEST20240716_COM_Trace_MaterialTran_TmpQty - ReceivedItem -> Dummy to Subcontract */                           
                                    Insert into TEST20240716_COM_Trace_MaterialTran_TmpQty    
                                        Select (@MaxTranID+1) As ICode, b.LotID, b.SubLotID As SubLotID, @cTransactionItem As TransactionItem,   
                                            b.CBQty As TransactionQty, @cTransactionItem As ChildCode, b.CBQty As ChildQty, -4 As CriteriaCode,                                  
                                            'DUM' As FromWarehouseCode, '' As FromRackBinCode, @cFromWarehouseCode As ToWarehouseCode,   
                                            @cFromRackBinCode As ToRackBinCode, '1' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID,   
                                            @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                   
                                        From INV_MATERIALTRAN_DTL a 
										Outer Apply
											(
												Select o.TranID, o.LotID, o.SubLotID, o.ItemCode, o.Qty as CBQty 
												From TEST20240716_COM_Trace_MaterialTran_TmpQty o
												Where o.TranID=@MaxTranID and o.Transtamp=@cTransactionDate and o.BranchID=@cBranchID and o.CompID=@cCompID
											)b	
                                        --Cross Apply dbo.fn_TEST20240716_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(a.TransactionItem, 'DUM', @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b
                                        Where a.BranchID=@cBranchID and a.CompID=@cCompID                            
                                            and Exists ( Select * From Rec_ReceiptEntry_Dtl s             
                               Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                            
                                                                and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                             
                                                                and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                            
                                                            )                            
   
                                    /* Insert Data Into TEST20240716_COM_Trace_MaterialTran_TmpQty */              
									Insert into TEST20240716_COM_Trace_MaterialTran_TmpQty  
                                        Select @cICode, b.LotID, b.SubLotID As SubLotID, @cTransactionItem, b.CBQty As TransactionQty,   
                                            @cTransactionItem As ChildCode, b.CBQty As ChildQty, -4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, +  
                                            @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,                                           
                                            '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                   
                                        From INV_MaterialTran_Dtl a                                  
                                        Cross Apply dbo.fn_TEST20240716_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@cTransactionItem, a.ToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b
                                        Where Exists ( Select * From Rec_ReceiptEntry_Dtl s                            
                                                        Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                            
                                                            and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                             
                                                            and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                            
                                                    )                            
                                END         --# 1.1.1                               
                            ELSE  
                                BEGIN        --# 1.1.1 
                                    /* Insert Data Into TEST20240716_COM_Trace_MaterialTran_TmpQty - Doctype = RR  and Other Inward Types */          
                                    Insert into TEST20240716_COM_Trace_MaterialTran_TmpQty   
                                        Select @cICode, b.LotID, b.SubLotID As SubLotID, @cTransactionItem, b.CBQty As TransactionQty, @cTransactionItem As ChildCode,     
                                            b.CBQty As ChildQty, -4 As CriteriaCode,  @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode,     
                                            @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID,     
                                            @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                   
                                        From fn_TEST20240716_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@cTransactionItem, @cFromWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b
                        END           --# 1.1.1 
                                                              
                            /* PRINT 'ICode: ' + Convert(varchar, @cICode) + ' - Completed - RR Other Entry.'; */   
                         END

                    ELSE /* Inserting Data into Trace Table*/                              
                        BEGIN                --# 1.1.1   
                            IF (@cFromWarehouseCode='WIP' AND @cToWarehouseCode = 'WAP')  /* Set Transfer */    
						        BEGIN      
							        Insert into TEST20240716_COM_Trace_MaterialTran_TmpQty              
								        Select @cICode, v.LotID, v.SubLotID, @cTransactionItem, v.CBQty as TransactionQty, /* Check Transaction Qty Concept */ 
									        isNull(@ChildCode, 0), isNull(@QtyAvailable, 0) as ChildQty, -4 as CriteriaCode,               
									        @cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
									        '0' as ReverseEntryFlg, -2 UserID, @cBranchID as BranchID, @cCompID as CompID, @cFinyear as Finyear, @cTransactionDate      
								        From fn_TEST20240716_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@cTransactionItem, @cFromWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @cFinyear) v       
      
      
							        Select @SetTranID = -(Min(a.ICode)), @SetItem=a.TransactionItem     
							        From INV_WIPTran_Dtl a                
							        Where a.DocType=@CDocType and a.DocNo=@cDocNo and a.DocDate=@cDocDate and a.FromItem=@cFromItem and a.ToItem=@cToItem 
								        and a.ToWarehouseCode = 'WIP' and a.ICode>-(@cICode)
								        and a.BranchID=@cBranchID and a.CompID=@cCompID and a.Finyear=@cFinyear        
							        Group by a.TransactionItem
            
							        Insert into TEST20240716_COM_Trace_MaterialTran_TmpQty              
								        Select @SetTranID, v.LotID, v.SubLotID, @SetItem, v.Qty/@cNorms as TransactionQty, /* Check Transaction Qty Concept */              
									        v.ChildCode, v.ChildQty as ChildQty, -4 as CriteriaCode,               
									        @cDocType as FromWarehouseCode, @cToRackBinCode as FromRackBinCode, @cFromWarehouseCode as ToWarehouseCode, @cFromRackBinCode as ToRackBinCode,               
									        '0' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, v.Finyear as Finyear, @cTransactionDate      
								        From TEST20240716_COM_Trace_MaterialTran_TmpQty v      
								        Where v.TranID=@cICode and BranchID=@BranchID and CompID=@CompID and Finyear in (@Finyear)              --'04-2023 03-2024', 
            
							        PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)            
							        + ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - WAP Entry.' + 'Norms - ' + Convert(varchar, @cNorms);         
   
						        END   
                            
					        --ELSE IF (NOT (@cFromWarehouseCode='WAP' AND @cToWarehouseCode = 'WIP'))     
                    
                            ELSE IF (NOT (  (Exists (Select * From COM_DocumentType_Master s 
									                    Where s.PertainingTo in ('PI', 'SI', 'LO','R') and s.ModuleName='QC' and s.DocumentType=@cFromWarehouseCode
										                and s.BranchID=@cBranchID and s.CompID=@cCompID)
								
								                OR (@cDocType='LOG')
                                
                                            ) AND @cToWarehouseCode = 'WIP'))     

						        BEGIN             
							        SET @ReqQty=Convert(decimal(15, 5), @cTransactionQty*@StockNorms);              
              
							        Insert into TEST20240716_COM_Trace_MaterialTran_TmpQty              
							  Select @cICode, v.LotID, v.SubLotID, @cTransactionItem, v.CBQty*@StockNorms as TransactionQty, /* Check Transaction Qty Concept */ 
								            isNull(@ChildCode, 0), isNull(@QtyAvailable, 0) as ChildQty, -4 as CriteriaCode,               
								            @cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
								            '0' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, @cFinyear as Finyear, @cTransactionDate              
							            From fn_TEST20240716_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@StockItem, @cFromWarehouseCode, @ReqQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @cFinyear) v              
            
							        PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)       
								        + ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - Other Entry.';            
						        END   

                        END           --# 1.1.1                                        
                END       --# 1.1                                        

            FETCH NEXT FROM CurMaterialTran into  @cICode, @cDocType, @cDocNo, @cDocDate,  @cTransactionDate, @cTransactionItem, @cTransactionQty, @cNorms, @cFromWarehouseCode, @cFromRackBinCode,               
                                                    @cToWarehouseCode, @cToRackBinCode, @cFromItem, @cToItem, @cUserID, @cBranchID, @cCompID, @cFinyear   
     END                --# 1.1  

     PRINT 'Process Completed';            
            
	close CurMaterialTran              
	deallocate CurMaterialTran              
               

END         -- # 1 
GO

/****** Object:  StoredProcedure [dbo].[TGR_COM_Trace_MaterialTranLotQty]    Script Date: 17/06/2026 11:31:06 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[TGR_COM_Trace_MaterialTranLotQty](@FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID Varchar(3), @CompID Varchar(3), @Finyear Varchar(20))              
AS              
BEGIN              
    SET NOCOUNT ON;              
              
    DECLARE @ContLoop bit;              
    Declare @mTranQty Float, @ChildCode Varchar(30), @QtyAvailable Float      
    Declare @StockItem Varchar(30), @StockNorms Float, @StockTranID bigint      
    Declare @SetItemID int, @SetItem Varchar(30), @SetTranID bigint      
              
    Declare @cICode bigint, @cDocType Varchar(3), @cDocNo int, @cDocDate datetime,  @cTransactionDate datetime , @cTransactionTime datetime, @cTransactionItem Varchar(30), @cTransactionQty Float, @cNorms Float,               
        @cFromWarehouseCode Varchar(6), @cFromRackBinCode Varchar(6), @cToWarehouseCode Varchar(6), @cToRackBinCode Varchar(6) , @cFromItem Varchar(30), @cToItem Varchar(30),              
        @cUserID Varchar(10), @cBranchID Varchar(3), @cCompID Varchar(3)             
              
    Declare @LotID bigint, @ReqQty decimal(15, 5);              
            
    /* For Record Count */            
    DECLARE @TotalRecordCount int, @CurrentRecordCount int;            
            
    Select @TotalRecordCount=COUNT(*)  
	From           
		(
			Select * From INV_MaterialTran_Dtl a              
			Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear   
				and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				and Exists 
					(
						Select * From TMP_TracebaleItems t 
						Where t.ItemCode=a.TransactionItem
					)   
				and DocType <> 'OPBAL' 

			Union All

			Select -(ICode), DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode,
				ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
			From INV_WIPTran_Dtl a              
			Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear   
				and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				and Exists 
					(
						Select * From TMP_TracebaleItems t 
						Where t.ItemCode=a.TransactionItem
					)  
				and not exists
					(
						Select * From INV_MaterialTran_Dtl s
						Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
							and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
							and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
							and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
							and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
					) 
				and DocType <> 'OPBAL' 
		)a
    Left Outer Join INV_Material_Master b              
        On a.TransactionItem=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID              
    Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear             
        and b.ItemNature in ('R','CR', 'C','CC', 'F', 'CF')               
        
      
    DECLARE CurMaterialTran CURSOR FOR              
        Select ICode, DocType, DocNo, DocDate, (TransactionDate + Convert(varchar(8), TransactionTime, 108)) as TransactionDate, TransactionItem, TransactionQty, 
			Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode,               
            FromItem, ToItem, a.UserID, a.BranchID, a.CompID              
        From --INV_MaterialTran_Dtl a              
			(
				Select * From INV_MaterialTran_Dtl a              
				Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear   
					and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
					and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
					and Exists 
						(
							Select * From TMP_TracebaleItems t 
							Where t.ItemCode=a.TransactionItem
						)  
					and DocType <> 'OPBAL'  

				Union All

				Select -(ICode), DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode,
					ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA, UserId, BranchId, CompId, Finyear 
				From INV_WIPTran_Dtl a              
				Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear   
					and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
					and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
					and Exists 
						(
							Select * From TMP_TracebaleItems t 
							Where t.ItemCode=a.TransactionItem
						)  
					and not exists
						(
							Select * From INV_MaterialTran_Dtl s
							Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
								and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
								and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
								and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
								and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
						) 
					and DocType <> 'OPBAL' and Not (DocType='IGR' and FromWarehouseCode='WIP' and ToWarehouseCode='WAP')
			)a
        Left Outer Join INV_Material_Master b              
            On a.TransactionItem=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID              
        Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear             
            and b.ItemNature in ('R','CR', 'C','CC', 'F', 'CF')
        Order by (TransactionDate + Convert(varchar(8), TransactionTime, 108)), a.ICode              
              
    OPEN CurMaterialTran              
    FETCH NEXT FROM CurMaterialTran into  @cICode, @cDocType, @cDocNo, @cDocDate, @cTransactionDate, @cTransactionItem, @cTransactionQty, @cNorms, @cFromWarehouseCode, @cFromRackBinCode,               
            @cToWarehouseCode, @cToRackBinCode, @cFromItem, @cToItem, @cUserID, @cBranchID, @cCompID           
               
    PRINT 'Total Record Count: ' + Convert(varchar, @TotalRecordCount);            
             
    SET @CurrentRecordCount=0;            
     
    WHILE @@FETCH_STATUS = 0              
		BEGIN              
			SET @CurrentRecordCount = @CurrentRecordCount + 1;  
			          
			PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)            
				+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Initiated.';            
                 
			Select @StockNorms = 1, @StockItem=@cTransactionItem              
              
			IF @cDocType = 'SV' and @cFromWarehouseCode='SV'              
				BEGIN              
					IF Not Exists (Select * from COM_Trace_LotMaster_TmpQty            
									Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate            
										and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID            
								)            
						BEGIN            
							/* Lot ID Generation */              
							Select @LotID=IsNull(Max(LotID),0)+1              
							From COM_Trace_LotMaster_TmpQty                
							Where BranchID=@BranchID and CompID=@CompID              
              
							Insert into COM_Trace_LotMaster_TmpQty              
								Select @cDocType, @cDocNo, @cDocDate, @cTransactionItem, @LotID as LotID, '' as HeatNo,             
									@cUserID, @cBranchID, @cCompID, @cTransactionDate              
						END            
					ELSE            
						BEGIN            
							SELECT @LotID=LotID 
							From COM_Trace_LotMaster_TmpQty            
							Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate            
								and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID            
						END            
            
					Insert into COM_Trace_MaterialTran_TmpQty              
						Select @cICode, @LotID, @cTransactionItem, @cTransactionQty as TransactionQty, @cTransactionItem, @cTransactionQty as ChildQty, -4 as CriteriaCode,    
							@cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,    
							-2 UserID, @cBranchID as BranchID, @cCompID as CompID, @Finyear as Finyear, @cTransactionDate    
              
					PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)            
						+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - SV Entry.';            
				END 
				 
			ELSE IF @cDocType = 'RR'  
						            
				BEGIN 
				
					IF Exists (Select * From Rec_ReceiptEntry_Hdr 
								Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate 
									and BranchID=@cBranchID and CompID=@cCompID and InwardType in ('P','C','U'))   --Purchase, CashPurchase, CustomerSuppliedProduct
						BEGIN          
							IF Not Exists (Select * From COM_Trace_LotMaster_TmpQty            
											Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate            
												and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID)            
								BEGIN            
									/* Lot ID Generation */              
									Select @LotID=IsNull(Max(LotID),0)+1              
									From COM_Trace_LotMaster_TmpQty                
									Where BranchID=@BranchID and CompID=@CompID              
              
									Insert into COM_Trace_LotMaster_TmpQty              
										Select a.ReceiptEntryType as DocType, a.ReceiptEntryNo as DocNo, a.ReceiptEntryDate as DocDate, @cTransactionItem, @LotID as LotID, 'H1' as HeatNo,             
											@cUserID, @cBranchID, @cCompID, @cTransactionDate              
										From Rec_ReceiptEntry_Hdr a              
										--Left Outer Join REC_IncomingReceipt_Dtl b              
										--	On a.DocNo=b.DocNo and a.DocDate=b.DocDate and a.DocType=b.DocType and a.BranchID=b.BranchID and a.CompID=b.CompID              
										Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear --and b.ItemCode=@StockItem              
											and a.ReceiptEntryType=@cDocType and a.ReceiptEntryNo=@cDocNo and a.ReceiptEntryDate=@cDocDate       
								END            
							ELSE            
								BEGIN            
									SELECT @LotID=LotID 
									From COM_Trace_LotMaster_TmpQty            
									Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate            
										and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID            
								END            
            
							Insert into COM_Trace_MaterialTran_TmpQty              
								Select @cICode, @LotID, @cTransactionItem, @cTransactionQty as TransactionQty, @cTransactionItem, @cTransactionQty as ChildQty, -4 as CriteriaCode,               
									@cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
									-2 UserID, @cBranchID as BranchID, @cCompID as CompID, @Finyear as Finyear, @cTransactionDate               
              
							PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)            
								+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - RR (Purchase, CashPurchase, Customer Supplied Product) Entry.';
						END 
					ELSE
						BEGIN
							Insert into COM_Trace_MaterialTran_TmpQty
								Select @cICode, b.LotID, @cTransactionItem, b.CBQty as TransactionQty, @cTransactionItem as ChildCode, b.CBQty as ChildQty, -4 as CriteriaCode,               
									@cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
									-2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, @cTransactionDate       
								From INV_MaterialTran_Dtl a						
								Cross Apply fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotQty(a.TransactionItem, a.ToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)b
								Where Exists
									(
										Select * From Rec_ReceiptEntry_Dtl s
										Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID
											and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate 
											and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End
									)

							PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)            
								+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - RR Other Entry.';
						END					       
				END              
			ELSE              
				BEGIN              
					IF (@cFromWarehouseCode='WIP' AND @cToWarehouseCode = 'WAP')  /* Set Transfer */    
						BEGIN      
							Insert into COM_Trace_MaterialTran_TmpQty              
								Select @cICode, v.LotID, @cTransactionItem, v.CBQty as TransactionQty, /* Check Transaction Qty Concept */              
									isNull(@ChildCode, 0), isNull(@QtyAvailable, 0) as ChildQty, -4 as CriteriaCode,               
									@cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
									-2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, @cTransactionDate      
								From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotQty(@cTransactionItem, @cFromWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) v       
      
      
							Select @SetTranID = -(Min(a.ICode)), @SetItem=a.TransactionItem     
							From INV_WIPTran_Dtl a                
							Where a.DocType=@CDocType and a.DocNo=@cDocNo and a.DocDate=@cDocDate and a.FromItem=@cFromItem and a.ToItem=@cToItem 
								and a.ToWarehouseCode = 'WIP' and a.ICode>-(@cICode)
								and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear        
							Group by a.TransactionItem
            
							Insert into COM_Trace_MaterialTran_TmpQty              
								Select @SetTranID, v.LotID, @SetItem, v.Qty/@cNorms as TransactionQty, /* Check Transaction Qty Concept */              
									v.ChildCode, v.ChildQty as ChildQty, -4 as CriteriaCode,               
									@cDocType as FromWarehouseCode, @cToRackBinCode as FromRackBinCode, @cFromWarehouseCode as ToWarehouseCode, @cFromRackBinCode as ToRackBinCode,               
									-2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, @cTransactionDate      
								From COM_Trace_MaterialTran_TmpQty v      
								Where v.TranID=@cICode and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear            
            
							PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)            
							+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - WAP Entry.' + 'Norms - ' + Convert(varchar, @cNorms);         
   
						END       
					ELSE IF (NOT (@cFromWarehouseCode='WAP' AND @cToWarehouseCode = 'WIP'))      
						BEGIN             
							SET @ReqQty=Convert(decimal(15, 5), @cTransactionQty*@StockNorms);              
              
							Insert into COM_Trace_MaterialTran_TmpQty              
							Select @cICode, v.LotID, @cTransactionItem, v.CBQty*@StockNorms as TransactionQty, /* Check Transaction Qty Concept */              
								isNull(@ChildCode, 0), isNull(@QtyAvailable, 0) as ChildQty, -4 as CriteriaCode,               
								@cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
								-2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, @cTransactionDate              
							From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotQty(@StockItem, @cFromWarehouseCode, @ReqQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear) v              
            
							PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)            
								+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - Other Entry.';            
						END       
				END              
              
			FETCH NEXT FROM CurMaterialTran into  @cICode, @cDocType, @cDocNo, @cDocDate,  @cTransactionDate, @cTransactionItem, @cTransactionQty, @cNorms, @cFromWarehouseCode, @cFromRackBinCode,               
					@cToWarehouseCode, @cToRackBinCode, @cFromItem, @cToItem, @cUserID, @cBranchID, @cCompID          
		END              
              
	PRINT 'Process Completed';            
            
	close CurMaterialTran              
	deallocate CurMaterialTran              
               
END 
GO

/****** Object:  StoredProcedure [dbo].[TGRProcess_To_Insert_COM_Trace_MaterialTranLotQty]    Script Date: 17/06/2026 11:31:06 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[TGRProcess_To_Insert_COM_Trace_MaterialTranLotQty](@FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID Varchar(3), @CompID Varchar(3), @Finyear Varchar(20))
AS  
BEGIN    -- # 1.1                                                    
    SET NOCOUNT ON;     

    DECLARE @ContLoop bit;              
    Declare @mTranQty Float, @ChildCode Varchar(30), @QtyAvailable Float      
    Declare @StockItem Varchar(30), @StockNorms Float, @StockTranID bigint      
    Declare @SetItemID int, @SetItem Varchar(30), @SetTranID bigint      
              
    Declare @cICode bigint, @cDocType Varchar(3), @cDocNo int, @cDocDate datetime,  @cTransactionDate datetime , @cTransactionTime datetime, @cTransactionItem Varchar(30), @cTransactionQty Float, @cNorms Float,               
        @cFromWarehouseCode Varchar(6), @cFromRackBinCode Varchar(6), @cToWarehouseCode Varchar(6), @cToRackBinCode Varchar(6) , @cFromItem Varchar(30), @cToItem Varchar(30),              
        @cUserID Varchar(10), @cBranchID Varchar(3), @cCompID Varchar(3), @cFinyear Varchar(20)             
              
    Declare @LotID bigint, @ReqQty decimal(15, 5), @SubLotID bigint;              

    /* For Record Count */            
    DECLARE @TotalRecordCount int, @CurrentRecordCount int;     
        Select @TotalRecordCount=COUNT(*)  
	    From           
		    (
			    Select * From INV_MaterialTran_Dtl a              
			    Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)   --'04-2023 03-2024', 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				    and Exists 
					    (
						    Select * From BOM_TraceableItems t 
						    Where t.ItemCode=a.TransactionItem  --and t.ItemCode in ('1U0810200R','2U510131T0','2U510132T0','2U510133T0','2U510130T0')
					    )   
				    and DocType <> 'OPBAL' 

			    Union All

			    Select -(ICode), DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode,
				    ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
			    From INV_WIPTran_Dtl a              
			    Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)  --'04-2023 03-2024', 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				    and Exists 
					    (
						    Select * From BOM_TraceableItems t 
						    Where t.ItemCode=a.TransactionItem  --and t.ItemCode in ('1U0810200R','2U510131T0','2U510132T0','2U510133T0','2U510130T0')
					    )  
				    and not exists
					    (
						    Select * From INV_MaterialTran_Dtl s
						    Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
							    and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
							    and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
							    and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
							    and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
					    ) 
				    and DocType <> 'OPBAL' and Not (DocType='IGR' and FromWarehouseCode='WIP')
		    )a
        Left Outer Join INV_Material_Master b              
            On a.TransactionItem=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID              
        Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)          --'04-2023 03-2024', 
            --and b.ItemNature in ('R','CR', 'C','CC', 'F', 'CF')         


     DECLARE CurMaterialTran CURSOR FOR              
        Select ICode, DocType, DocNo, DocDate, (TransactionDate + Convert(varchar(8), TransactionTime, 108)) as TransactionDate, TransactionItem, TransactionQty, 
		    Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode,               
            FromItem, ToItem, a.UserID, a.BranchID, a.CompID, a.Finyear              
        From --INV_MaterialTran_Dtl a              
		    (
			    Select * From INV_MaterialTran_Dtl a              
			    Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)     --'04-2023 03-2024', 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				    and Exists 
					    (
						    Select * From BOM_TraceableItems t 
						    Where t.ItemCode=a.TransactionItem --and t.ItemCode in ('1U0810200R','2U510131T0','2U510132T0','2U510133T0','2U510130T0')
					    )  
				    and DocType <> 'OPBAL'  

			    Union All

			    Select -(ICode), DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode,
				    ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA, UserId, BranchId, CompId, Finyear 
			    From INV_WIPTran_Dtl a              
			    Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear) --'04-2023 03-2024',
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				    and Exists 
					    (
						    Select * From BOM_TraceableItems t 
						    Where t.ItemCode=a.TransactionItem  --and t.ItemCode in ('1U0810200R','2U510131T0','2U510132T0','2U510133T0','2U510130T0')
					    )  
				    and not exists
					    (
						    Select * From INV_MaterialTran_Dtl s
						    Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
							    and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
							    and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
							    and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
							    and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
					    ) 
				    and DocType <> 'OPBAL' and Not (DocType='IGR' and FromWarehouseCode='WIP')
					--and Not (DocType='IGR' and FromWarehouseCode='WIP' and ToWarehouseCode='WAP')
		    )a
        Left Outer Join INV_Material_Master b              
            On a.TransactionItem=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID              
        Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)             --'04-2023 03-2024', 
            --and b.ItemNature in ('R','CR', 'C','CC', 'F', 'CF')
        Order by (TransactionDate + Convert(varchar(8), TransactionTime, 108)), a.ICode           

     
    OPEN CurMaterialTran              
    FETCH NEXT FROM CurMaterialTran into  @cICode, @cDocType, @cDocNo, @cDocDate, @cTransactionDate, @cTransactionItem, @cTransactionQty, @cNorms, @cFromWarehouseCode, @cFromRackBinCode,               
                                        @cToWarehouseCode, @cToRackBinCode, @cFromItem, @cToItem, @cUserID, @cBranchID, @cCompID, @cFinyear           
               
    PRINT 'Total Record Count: ' + Convert(varchar, @TotalRecordCount);            
             
    SET @CurrentRecordCount=0;            
     
    WHILE @@FETCH_STATUS = 0              
		BEGIN  
            SET @CurrentRecordCount = @CurrentRecordCount + 1;  
			          
			PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)     
				+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Initiated.';

            Declare @StgCnt As int;
                SET @StgCnt=0;

            /* PRINT 'START 1' */  
            --IF Exists(Select * From BOM_TraceableItems t Where t.ItemCode=@cTransactionItem)          
                BEGIN /* PRINT 'START 1.1' */     
                  --/* PRINT 'START Declaration' */                                         
              --Declare @ChildCode Varchar(30), @QtyAvailable Float;                                  
                    --Declare @StockItem Varchar(30), @StockNorms Float;                                
                    --Declare @SetItemID int, @SetItem Varchar(30), @SetTranID bigint, @PrevTranQty Float, @PrevNorms Float;                            
                                 
                    --Declare @cICode bigint, @cDocType Varchar(3), @cDocNo int, @cDocDate datetime, @cTransactionDate datetime,   
                    --    @cTransactionTime datetime, @cTransactionItem Varchar(30), @cTransactionQty Float, @cNorms Float,                                           
                    --    @cFromWarehouseCode Varchar(6), @cFromRackBinCode Varchar(6), @cToWarehouseCode Varchar(6),   
                    --    @cToRackBinCode Varchar(6), @cFromItem Varchar(30), @cToItem Varchar(30), @cUserID Varchar(10),   
                    --    @cBranchID Varchar(3), @cCompID Varchar(3), @cFinyear Varchar(20), @cTranstamp datetime                                           
                                          
                    --Declare @LotID bigint, @ReqQty decimal(15, 5);                                            
                    --Declare @SubLotID bigint;                            
                            
                    --Declare @AsOnDate datetime, @RptDate datetime;                            
                    --    Select @AsOnDate = getdate(), @RptDate=@AsOnDate;    
                         
                    Select @StockNorms=1, @StockItem=@cTransactionItem;                                  
                            
                    /* Inserting Data into Trace Table*/                            
                    IF ((@cDocType = 'SV' and @cFromWarehouseCode='SV')                     
                        OR  (Exists (Select * From COM_DocumentType_Master s                             
                                        Where s.PertainingTo in ('M') and s.ModuleName='INV' and s.DocumentType=@cDocType                            
                                            and s.BranchID=@cBranchID and s.CompID=@cCompID          
                                    )          
                            ) )                                         
                        BEGIN                                         
                            IF Not Exists (Select * from COM_Trace_LotMaster_TmpQty                                        
                                            Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate          
                                                and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID)                                                                      
                                BEGIN                            
                                    /* Lot ID Generation */                                          
                                    Select @LotID=IsNull(Max(LotID),0)+1                                          
                                    From COM_Trace_LotMaster_TmpQty                         
                                    Where BranchID=@cBranchID and CompID=@cCompID                                             
                                       
                                    /* Insert Data Into COM_Trace_LotMaster_TmpQty --> In Future need to remove the before Union Part */     
                                    Insert into COM_Trace_LotMaster_TmpQty              
                                        Select @cDocType, @cDocNo, @cDocDate, @cTransactionItem, @LotID As LotID, 1 As SubLotID, --'' As HeatNo,  
                                            dbo.fn_COM_Get_LatestHeatNo_StockVerification(@cTransactionItem, @cTransactionDate, @cBranchID, @cCompID, @cFinyear) as HeatNo,
                                            '' As ManufactureDate, '' As ShelfLifeDays, @cUserID, @cBranchID, @cCompID, @cTransactionDate     
                                        UNION             
                                        /* the below From part newly added */                         
                                        Select @cDocType, @cDocNo, @cDocDate, @cTransactionItem, @LotID As LotID, IsNull(a.SubLotID, 1) As SubLotID, --'' As HeatNo,                                         
                                            a.HeatNo, a.ManufactureDate, a.ShelfLifeDays, @cUserID, @cBranchID, @cCompID, @cTransactionDate                             
                                        From Rec_ReceiptEntry_Dtl_Trace a                          
                                        Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate and a.ItemCode=@cTransactionItem                          
                                            and a.BranchId=@cBranchID and a.CompId=@cCompID                                 
                                END                                         
                            ELSE                                        
                                BEGIN                                        
                                    SELECT @LotID=LotID, @SubLotID=IsNull(SubLotID, 1)          
                                    From COM_Trace_LotMaster_TmpQty                                        
                                    Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate                                        
                                        and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID                                        
                                END  
                                              
                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty */                               
                            Insert into COM_Trace_MaterialTran_TmpQty   
                                Select @cICode, IsNull(@LotID, -1),  IsNull(@SubLotID, 1), @cTransactionItem, @cTransactionQty As TransactionQty, @cTransactionItem,   
                                    @cTransactionQty As ChildQty, -4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode,   
                                    @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,                                
                                    '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate     
                   
                            /* PRINT 'ICode: ' + Convert(varchar, @cICode) + ' - Completed - SV Entry.'; */                                     
                        END 
                    
                    ELSE If @cDocType='RR'                                              
                        BEGIN  
                            PRINT 'RR START'
                            
                            IF Exists (Select * From Rec_ReceiptEntry_Hdr                             
                                        Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate                             
                                            and BranchID=@cBranchID and CompID=@cCompID and InwardType in ('P','C','U'))   --Purchase, CashPurchase, CustomerSuppliedProduct   
								BEGIN                                      
                              IF Not Exists (Select * From COM_Trace_LotMaster_TmpQty                                        
                                                 Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate                                        
                                                            and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID  
                                                    )                                        
                                        BEGIN   /* Receipt Entry */                      
                                            /* Lot ID Generation */                                          
                                            Select @LotID=IsNull(Max(LotID),0)+1                                          
                                            From COM_Trace_LotMaster_TmpQty                                            
                                            Where BranchID=@cBranchID and CompID=@cCompID                         
                                          
                                            /* PRINT 'Lot ID Generation'  + Convert(varchar, @LotID) */    
                           
                                            /* Insert Data Into COM_Trace_LotMaster_TmpQty */                                
                                            Insert into COM_Trace_LotMaster_TmpQty   
                                                Select a.ReceiptEntryType As DocType, a.ReceiptEntryNo As DocNo, a.ReceiptEntryDate As DocDate, @cTransactionItem,                             
                                                    @LotID As LotID, IsNull(c.SubLotID, 1) As SubLotID, IsNull(c.HeatNo,'') as HeatNo, 
													IsNull(c.ManufactureDate,'') as ManufactureDate, IsNull(c.ShelfLifeDays,0) as ShelfLifeDays, 
													@cUserID, @cBranchID, @cCompID, @cTransactionDate                                          
                                                From Rec_ReceiptEntry_Hdr a                                          
                                                Left Outer Join Rec_ReceiptEntry_Dtl b                                          
                                                    On a.ReceiptEntryNo=b.ReceiptEntryNo and a.ReceiptEntryDate=b.ReceiptEntryDate and a.ReceiptEntryType=b.ReceiptEntryType                             
                                                        and a.BranchID=b.BranchID and a.CompID=b.CompID                           
                                                Left Outer Join Rec_ReceiptEntry_Dtl_Trace c                                          
                                                    On c.ReceiptEntryNo=b.ReceiptEntryNo and c.ReceiptEntryDate=b.ReceiptEntryDate and c.ReceiptEntryType=b.ReceiptEntryType                             
                                                        and c.ItemCode=b.ItemCode and b.ItemSeq=c.ItemSeq and c.BranchID=b.BranchID and c.CompID=b.CompID                                         
                                                Where a.BranchID=@cBranchID and a.CompID=@cCompID and a.Finyear=@cFinyear and b.ItemCode=@cTransactionItem                                          
                                                    and a.ReceiptEntryType=@cDocType and a.ReceiptEntryNo=@cDocNo and a.ReceiptEntryDate=@cDocDate                        
    
                                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty */                     
                                            Insert into COM_Trace_MaterialTran_TmpQty  
                                                Select @cICode, @LotID, IsNull(c.SubLotID, 1) as SubLotID, @cTransactionItem, IsNull(c.Qty, @cTransactionQty) As TransactionQty, 
													@cTransactionItem, IsNull(c.Qty, @cTransactionQty) As ChildQty,          
													/* @cTransactionQty As TransactionQty,   @cTransactionItem,   @cTransactionQty As ChildQty, */                      
                                                    -4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode,   
                                                    @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID,   
                                                    @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                           
                                                From Rec_ReceiptEntry_Dtl b
												Left Outer Join Rec_ReceiptEntry_Dtl_Trace c     
													 On c.ReceiptEntryNo=b.ReceiptEntryNo and c.ReceiptEntryDate=b.ReceiptEntryDate and c.ReceiptEntryType=b.ReceiptEntryType                             
                                                     and c.ItemCode=b.ItemCode and b.ItemSeq=c.ItemSeq and c.BranchID=b.BranchID and c.CompID=b.CompID          
                                                Where b.ReceiptEntryNo=@cDocNo and b.ReceiptEntryDate=@cDocDate and b.ReceiptEntryType=@cDocType                           
                                                    and b.ItemCode=@cTransactionItem and b.BranchID=@cBranchID and b.CompID=@cCompID  
                                 
                                            /* PRINT 'COM_Trace_MaterialTran_TmpQty - Receipt Entry' */                     
                                        END  
                                    ELSE                                        
                                        BEGIN                                        
                                            Select @LotID=LotID, @SubLotID=SubLotID                             
                                            From COM_Trace_LotMaster_TmpQty                                        
                                            Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate                                        
                                                and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID                        
                                            /* PRINT 'Lot ID Generation' */                                           
                                         
  
                                            /*PRINT 'Lot ID Generation'    + Convert(varchar, @LotID) */                
                               
                                            /* Acceptance Entry - If User enter Accepted, Rejection, Scrap qty then material Tran dtl table have 3 rows   
                                            for three different whs Since this 3 entries need to be saved in  table COM_Trace_MaterialTran_TmpQty    
                                            individually As well As SublotID wise. So we saved the entries As below */                  
                         
                                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty - Accepted Qty */                    
                                            Insert into COM_Trace_MaterialTran_TmpQty  
                                                Select @cICode, @LotID, IsNull(c.SubLotID,1) as SubLotID, @cTransactionItem, 
                                                    Case When IsNull(c.AcceptedQty,0)>0 Then c.AcceptedQty Else r.AcceptedQty End As TransactionQty, @cTransactionItem,
                                                    Case When IsNull(c.AcceptedQty,0)>0 Then c.AcceptedQty Else r.AcceptedQty End As ChildQty,                       
													1 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,
              '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                           
												From Rec_ReceiptEntry_Dtl r
                                                Left Outer Join Rec_ReceiptEntry_Dtl_Trace c
                                                    On c.ReceiptEntryNo=r.ReceiptEntryNo and c.ReceiptEntryDate=r.ReceiptEntryDate and c.ReceiptEntryType=r.ReceiptEntryType and c.ItemCode=r.ItemCode
                                                    and c.BranchID=r.BranchID and c.CompID=r.CompID 
                                                Where r.ReceiptEntryNo=@cDocNo and r.ReceiptEntryDate=@cDocDate and r.ReceiptEntryType=@cDocType                           
                                                    and r.ItemCode=@cTransactionItem and r.BranchID=@cBranchID and r.CompID=@cCompID and r.AcceptedQty > 0                      
                                                    and @cToWarehouseCode not in (Select WarehouseCode From Inv_Warehouse_Master Where WarehouseNature in ('Rejection', 'Scrap'))                
                               
                                            /* PRINT 'COM_Trace_MaterialTran_TmpQty - Accepted Entry - Accepted Qty' */                    
                    
                                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty - Rejected Qty */                    
                                            Insert into COM_Trace_MaterialTran_TmpQty   
                                                Select @cICode, @LotID, IsNull(c.SubLotID,1) as SubLotID, @cTransactionItem, 
                                                    Case When IsNull(c.RejectedQty,0)>0 Then c.RejectedQty Else r.RejectionQty End As TransactionQty, @cTransactionItem,  
                                                    Case When IsNull(c.RejectedQty,0)>0 Then c.RejectedQty Else r.RejectionQty End As ChildQty,                       
                                                    2 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode,          
                                                    @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear,           
                                                    @cTransactionDate                                              
                                                From Rec_ReceiptEntry_Dtl r                                      
                                                Left Outer Join Rec_ReceiptEntry_Dtl_Trace c    
                                                    On c.ReceiptEntryNo=r.ReceiptEntryNo and c.ReceiptEntryDate=r.ReceiptEntryDate and c.ReceiptEntryType=r.ReceiptEntryType and c.ItemCode=r.ItemCode
                                                    and c.BranchID=r.BranchID and c.CompID=r.CompID 
                                                Where r.ReceiptEntryNo=@cDocNo and r.ReceiptEntryDate=@cDocDate and r.ReceiptEntryType=@cDocType                           
                                                    and r.ItemCode=@cTransactionItem and r.BranchID=@cBranchID and r.CompID=@cCompID and r.RejectionQty > 0                      
                                                    and @cToWarehouseCode not in (Select WarehouseCode From Inv_Warehouse_Master Where WarehouseNature in ('InHouse', 'Scrap'))                
                
                                            /* PRINT 'COM_Trace_MaterialTran_TmpQty - Accepted Entry - Rejected Qty' */                    
                    
                                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty - Scrap Qty */                    
                                            Insert into COM_Trace_MaterialTran_TmpQty  
                                                Select @cICode, @LotID, IsNull(c.SubLotID,1) as SubLotID, @cTransactionItem, 
													Case When IsNull(c.ScrapQty,0)>0 Then c.ScrapQty Else r.ScrapQty End As TransactionQty, @cTransactionItem, 
                                                    Case When IsNull(c.ScrapQty,0)>0 Then c.ScrapQty Else r.ScrapQty End As ChildQty,                                            
                                                    4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode,          
                                                    @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear,          
                                                    @cTransactionDate                                           
                                                From Rec_ReceiptEntry_Dtl r                                        
                                                Left Outer Join  Rec_ReceiptEntry_Dtl_Trace c
                                                    On c.ReceiptEntryNo=r.ReceiptEntryNo and c.ReceiptEntryDate=r.ReceiptEntryDate and c.ReceiptEntryType=r.ReceiptEntryType and c.ItemCode=r.ItemCode
                                                    and c.BranchID=r.BranchID and c.CompID=r.CompID 
                                                Where r.ReceiptEntryNo=@cDocNo and r.ReceiptEntryDate=@cDocDate and r.ReceiptEntryType=@cDocType                           
                                                    and r.ItemCode=@cTransactionItem and r.BranchID=@cBranchID and r.CompID=@cCompID and r.ScrapQty > 0                      
                                                    and @cToWarehouseCode not in ( Select WarehouseCode From Inv_Warehouse_Master Where WarehouseNature in ('InHouse', 'Rejection'))                
                
                                            /* PRINT 'COM_Trace_MaterialTran_TmpQty - Accepted Entry - Scrap Qty' */                     
                                    END  
                                END  
                                /* PRINT 'ICode: ' + Convert(varchar, @cICode) + ' - Completed - RR (Purchase, CashPurchase, Customer Supplied Product) Entry.'; */                          

                            ELSE If @cToWarehouseCode='UI' and Exists (Select * From Rec_ReceiptEntry_Hdr                             
                                                                        Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate                            
                                                                        and BranchID=@cBranchID and CompID=@cCompID and InwardType in ('S','L','M'))                
                                BEGIN     /* Subcontract, SubcontractPartial, DismantlingDC */         --# 1.1.1             
                                    /* TranID Generation */                             
                                    Declare @MaxTranID bigint;                                         
                                        Select @MaxTranID=IsNull(Max(TranID),0)+1                                          
                                        From COM_Trace_MaterialTran_TmpQty                                            
                                        Where ReverseEntryFlg='1' and BranchID=@cBranchID and CompID=@cCompID                  
                        
                                  /* Insert Data Into COM_Trace_MaterialTran_TmpQty - SentItem -> Subcontract to Dummy */                        
                                    Insert into COM_Trace_MaterialTran_TmpQty  
                                        Select @MaxTranID As ICode, b.LotID, b.SubLotID As SubLotID, a.TransactionItem, b.CBQty As TransactionQty,   
											a.TransactionItem As ChildCode, b.CBQty As ChildQty, -4 As CriteriaCode, a.ToWarehouseCode As FromWarehouseCode,   
                                            a.ToRackBinCode As FromRackBinCode, 'DUM' As ToWarehouseCode, '' As ToRackBinCode, '1' As ReverseEntryFlg,   
                                            -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                   
                                        From INV_MATERIALTRAN_DTL a                                  
                                        Cross Apply fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(a.TransactionItem, a.ToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b
                                        Where a.BranchID=@cBranchID and a.CompID=@cCompID                            
                                            and Exists ( Select * From Rec_ReceiptEntry_Dtl s       
                                                        Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                            
                                                            and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                             
                                                            and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                            
                                                    )                            
                                                
                                    /* Insert Data Into COM_Trace_MaterialTran_TmpQty - ReceivedItem -> Dummy to Subcontract */                           
                                    Insert into COM_Trace_MaterialTran_TmpQty    
                                        Select (@MaxTranID+1) As ICode, b.LotID, b.SubLotID As SubLotID, @cTransactionItem As TransactionItem,   
                                            b.CBQty As TransactionQty, @cTransactionItem As ChildCode, b.CBQty As ChildQty, -4 As CriteriaCode,                                  
                                            'DUM' As FromWarehouseCode, '' As FromRackBinCode, @cFromWarehouseCode As ToWarehouseCode,   
                                            @cFromRackBinCode As ToRackBinCode, '1' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID,   
                                            @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                   
                                        From INV_MATERIALTRAN_DTL a 
										Outer Apply
											(
												Select o.TranID, o.LotID, o.SubLotID, o.ItemCode, o.Qty as CBQty 
												From COM_Trace_MaterialTran_TmpQty o
												Where o.TranID=@MaxTranID and o.Transtamp=@cTransactionDate and o.BranchID=@cBranchID and o.CompID=@cCompID
											)b	
                                        --Cross Apply dbo.fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(a.TransactionItem, 'DUM', @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b
                                        Where a.BranchID=@cBranchID and a.CompID=@cCompID                            
                                            and Exists ( Select * From Rec_ReceiptEntry_Dtl s             
                                                            Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                            
                                                                and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                             
                                                                and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                            
                                                            )                            
   
                                    /* Insert Data Into COM_Trace_MaterialTran_TmpQty */              
									Insert into COM_Trace_MaterialTran_TmpQty  
                                        Select @cICode, b.LotID, b.SubLotID As SubLotID, @cTransactionItem, b.CBQty As TransactionQty,   
                                            @cTransactionItem As ChildCode, b.CBQty As ChildQty, -4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, +  
                                            @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,                                           
                                            '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                   
                                        From INV_MaterialTran_Dtl a                                  
                                        Cross Apply dbo.fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@cTransactionItem, a.ToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b
                                        Where Exists ( Select * From Rec_ReceiptEntry_Dtl s                            
                                                        Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                            
                                                            and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                             
                                                            and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                            
                                                    )                            
                                END         --# 1.1.1                               
                            ELSE  
                                BEGIN        --# 1.1.1 
                                    /* Insert Data Into COM_Trace_MaterialTran_TmpQty - Doctype = RR  and Other Inward Types */          
                                    Insert into COM_Trace_MaterialTran_TmpQty   
                                        Select @cICode, b.LotID, b.SubLotID As SubLotID, @cTransactionItem, b.CBQty As TransactionQty, @cTransactionItem As ChildCode,     
                                            b.CBQty As ChildQty, -4 As CriteriaCode,  @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode,     
                                            @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID,     
                                            @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                   
                                        From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@cTransactionItem, @cFromWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b
                        END    --# 1.1.1 
                                                              
                            /* PRINT 'ICode: ' + Convert(varchar, @cICode) + ' - Completed - RR Other Entry.'; */   
                         END

                    ELSE /* Inserting Data into Trace Table*/                              
                        BEGIN                --# 1.1.1   
                            IF (@cFromWarehouseCode='WIP' AND @cToWarehouseCode = 'WAP')  /* Set Transfer */    
						        BEGIN      
							        Insert into COM_Trace_MaterialTran_TmpQty              
								        Select @cICode, v.LotID, v.SubLotID, @cTransactionItem, v.CBQty as TransactionQty, /* Check Transaction Qty Concept */ 
									        isNull(@ChildCode, 0), isNull(@QtyAvailable, 0) as ChildQty, -4 as CriteriaCode,               
									        @cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
									        '0' as ReverseEntryFlg, -2 UserID, @cBranchID as BranchID, @cCompID as CompID, @cFinyear as Finyear, @cTransactionDate      
								        From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@cTransactionItem, @cFromWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @cFinyear) v       
      
      
							        Select @SetTranID = -(Min(a.ICode)), @SetItem=a.TransactionItem     
							        From INV_WIPTran_Dtl a                
							        Where a.DocType=@CDocType and a.DocNo=@cDocNo and a.DocDate=@cDocDate and a.FromItem=@cFromItem and a.ToItem=@cToItem 
								        and a.ToWarehouseCode = 'WIP' and a.ICode>-(@cICode)
								        and a.BranchID=@cBranchID and a.CompID=@cCompID and a.Finyear=@cFinyear        
							        Group by a.TransactionItem
            
							        Insert into COM_Trace_MaterialTran_TmpQty              
								        Select @SetTranID, v.LotID, v.SubLotID, @SetItem, v.Qty/@cNorms as TransactionQty, /* Check Transaction Qty Concept */              
									        v.ChildCode, v.ChildQty as ChildQty, -4 as CriteriaCode,               
									        @cDocType as FromWarehouseCode, @cToRackBinCode as FromRackBinCode, @cFromWarehouseCode as ToWarehouseCode, @cFromRackBinCode as ToRackBinCode,               
									        '0' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, v.Finyear as Finyear, @cTransactionDate      
								        From COM_Trace_MaterialTran_TmpQty v      
								        Where v.TranID=@cICode and BranchID=@BranchID and CompID=@CompID and Finyear in (@Finyear)              --'04-2023 03-2024', 
            
							        PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)            
							        + ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - WAP Entry.' + 'Norms - ' + Convert(varchar, @cNorms);         
   
						        END   
                            
					        --ELSE IF (NOT (@cFromWarehouseCode='WAP' AND @cToWarehouseCode = 'WIP'))     
                    
                            ELSE IF (NOT (  (Exists (Select * From COM_DocumentType_Master s 
									                    Where s.PertainingTo in ('PI', 'SI', 'LO','R') and s.ModuleName='QC' and s.DocumentType=@cFromWarehouseCode
										                and s.BranchID=@cBranchID and s.CompID=@cCompID)
								
								                OR (@cDocType='LOG')
                                
                                            ) AND @cToWarehouseCode = 'WIP'))     

						        BEGIN             
							        SET @ReqQty=Convert(decimal(15, 5), @cTransactionQty*@StockNorms);              
              
							        Insert into COM_Trace_MaterialTran_TmpQty              
							  Select @cICode, v.LotID, v.SubLotID, @cTransactionItem, v.CBQty*@StockNorms as TransactionQty, /* Check Transaction Qty Concept */ 
								            isNull(@ChildCode, 0), isNull(@QtyAvailable, 0) as ChildQty, -4 as CriteriaCode,               
								            @cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
								            '0' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, @cFinyear as Finyear, @cTransactionDate              
							            From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@StockItem, @cFromWarehouseCode, @ReqQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @cFinyear) v              
            
							        PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)       
								        + ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - Other Entry.';            
						        END   

                        END           --# 1.1.1                                        
                END       --# 1.1                                        

            FETCH NEXT FROM CurMaterialTran into  @cICode, @cDocType, @cDocNo, @cDocDate,  @cTransactionDate, @cTransactionItem, @cTransactionQty, @cNorms, @cFromWarehouseCode, @cFromRackBinCode,               
                                                    @cToWarehouseCode, @cToRackBinCode, @cFromItem, @cToItem, @cUserID, @cBranchID, @cCompID, @cFinyear   
     END                --# 1.1  

     PRINT 'Process Completed';            
            
	close CurMaterialTran              
	deallocate CurMaterialTran              
               

END         -- # 1 
GO

/****** Object:  StoredProcedure [dbo].[TGRProcess_To_Insert_COM_Trace_MaterialTranLotQty_RefTranDocID]    Script Date: 17/06/2026 11:31:06 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[TGRProcess_To_Insert_COM_Trace_MaterialTranLotQty_RefTranDocID](@FromDate datetime, @ToDate datetime, @AsOnDate datetime, @RptDate datetime, @BranchID Varchar(3), @CompID Varchar(3), @Finyear Varchar(20))
AS  
BEGIN    -- # 1.1                                                    
    SET NOCOUNT ON;     

    DECLARE @ContLoop bit;              
    Declare @mTranQty Float, @ChildCode Varchar(30), @QtyAvailable decimal(15,5)      
    Declare @StockItem Varchar(30), @StockNorms Float, @StockTranID bigint      
    Declare @SetItemID int, @SetItem Varchar(30), @SetTranID bigint      
              
    Declare @cICode bigint, @cTranDocId bigint, @cDocType Varchar(3), @cDocNo int, @cDocDate datetime,  @cTransactionDate datetime , @cTransactionTime datetime, 
		@cTransactionItem Varchar(30), @cTransactionQty decimal(15,5), @cNorms Float,               
        @cFromWarehouseCode Varchar(6), @cFromRackBinCode Varchar(6), @cToWarehouseCode Varchar(6), @cToRackBinCode Varchar(6) , @cFromItem Varchar(30), @cToItem Varchar(30),              
        @cUserID Varchar(10), @cBranchID Varchar(3), @cCompID Varchar(3), @cFinyear Varchar(20)             
              
    Declare @LotID bigint, @ReqQty decimal(15, 5), @SubLotID bigint;              
		
	Declare @MissingUserID int;
		Select @MissingUserID=-3;

	Declare @MissingMinDocNo int, @MissingMinLotID int, @MissingMinTranID int, @MissingLotQty decimal(15,5), @LatestHeatNo Varchar(20);
	 
    /* For Record Count */            
    DECLARE @TotalRecordCount int, @CurrentRecordCount int;     
        Select @TotalRecordCount=COUNT(*)  
	    From           
		    (
			    Select * From INV_MATERIALTRAN_DTL_LotTrial a              
			    Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)   --'04-2023 03-2024', 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				    and Exists 
					    (
						    Select * From BOM_TraceableItems t 
						    Where t.ItemCode=a.TransactionItem  --and t.ItemCode in ('1U0810200R','2U510131T0','2U510132T0','2U510133T0','2U510130T0')
					    )   
				    and DocType <> 'OPBAL' 

			    Union All

			    Select -(ICode), TranDocId, DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode,
				    ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA, Userid, Branchid, Compid, Finyear 
			    From INV_WIPTRAN_DTL_LotTrial a              
			    Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)  --'04-2023 03-2024', 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				    and Exists 
					    (
						    Select * From BOM_TraceableItems t 
						    Where t.ItemCode=a.TransactionItem  --and t.ItemCode in ('1U0810200R','2U510131T0','2U510132T0','2U510133T0','2U510130T0')
					    )  
				    and not exists
					    (
						    Select * From INV_MATERIALTRAN_DTL_LotTrial s
						    Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
							    and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
							    and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
							    and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
							    and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
					    ) 
				    and DocType <> 'OPBAL' and Not (DocType='IGR' and FromWarehouseCode='WIP')
		    )a
        Left Outer Join INV_Material_Master b              
            On a.TransactionItem=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID              
        Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)          --'04-2023 03-2024', 
            --and b.ItemNature in ('R','CR', 'C','CC', 'F', 'CF')         


     DECLARE CurMaterialTran CURSOR FOR              
        Select ICode, TranDocId, DocType, DocNo, DocDate, (TransactionDate + Convert(varchar(8), TransactionTime, 108)) as TransactionDate, TransactionItem, TransactionQty, 
		    Norms, FromWarehouseCode, FromRackBinCode, ToWarehouseCode, ToRackBinCode,               
            FromItem, ToItem, a.UserID, a.BranchID, a.CompID, a.Finyear              
        From --INV_MATERIALTRAN_DTL_LotTrial a              
		    (
			    Select * From INV_MATERIALTRAN_DTL_LotTrial a              
			    Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)     --'04-2023 03-2024', 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				    and Exists 
					    (
						    Select * From BOM_TraceableItems t 
						    Where t.ItemCode=a.TransactionItem --and t.ItemCode in ('1U0810200R','2U510131T0','2U510132T0','2U510133T0','2U510130T0')
					    )  
				    and DocType <> 'OPBAL'  

			    Union All

			    Select -(ICode), TranDocId, DOCType, DOCNo, DOCDate, TransactionDate, TransactionTime, TransactionItem, TransactionQty, Norms, FromWarehouseCode, FromRackBinCode,
				    ToWarehouseCode, ToRackBinCode, ItemGroupKey, FromItem, ToItem, Justification, LIFO, FIFO, WA, UserId, BranchId, CompId, Finyear 
			    From INV_WIPTRAN_DTL_LotTrial a              
			    Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear) --'04-2023 03-2024',
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108)) > @FromDate 
				    and (TransactionDate + Convert(varchar(8), TransactionTime, 108))<=@ToDate 
				    and Exists 
					    (
						    Select * From BOM_TraceableItems t 
						    Where t.ItemCode=a.TransactionItem  --and t.ItemCode in ('1U0810200R','2U510131T0','2U510132T0','2U510133T0','2U510130T0')
					    )  
				    and not exists
					    (
						    Select * From INV_MATERIALTRAN_DTL_LotTrial s
						    Where s.DocNo=a.DocNo and s.DocDate=a.DocDate and s.DocType=a.DocType and s.TransactionDate=a.TransactionDate 
							    and s.TransactionTime=a.TransactionTime and s.TransactionItem=a.TransactionItem and s.FromwarehouseCode=a.FromWarehouseCode
							    and s.FromRackBinCode=a.FromRackBinCode and s.TowarehouseCode=a.TowarehouseCode and s.ToRackBinCode=a.ToRackBinCode 
							    and s.ItemGroupKey=a.ItemGroupKey and s.FromItem=a.FromItem and s.ToItem=a.ToItem 
							    and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear
					    ) 
				    and DocType <> 'OPBAL' and Not (DocType='IGR' and FromWarehouseCode='WIP')
					--and Not (DocType='IGR' and FromWarehouseCode='WIP' and ToWarehouseCode='WAP')
		    )a
        Left Outer Join INV_Material_Master b              
            On a.TransactionItem=b.ItemCode and a.BranchID=b.BranchID and a.CompID=b.CompID              
        Where a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear in (@Finyear)             --'04-2023 03-2024', 
            --and b.ItemNature in ('R','CR', 'C','CC', 'F', 'CF')
        Order by (TransactionDate + Convert(varchar(8), TransactionTime, 108)), a.ICode           

     
    OPEN CurMaterialTran              
    FETCH NEXT FROM CurMaterialTran into  @cICode, @cTranDocId, @cDocType, @cDocNo, @cDocDate, @cTransactionDate, @cTransactionItem, @cTransactionQty, @cNorms, @cFromWarehouseCode, @cFromRackBinCode,               
                                        @cToWarehouseCode, @cToRackBinCode, @cFromItem, @cToItem, @cUserID, @cBranchID, @cCompID, @cFinyear           
               
    PRINT 'Total Record Count: ' + Convert(varchar, @TotalRecordCount);            
             
    SET @CurrentRecordCount=0;            
     
    WHILE @@FETCH_STATUS = 0              
		BEGIN  
            SET @CurrentRecordCount = @CurrentRecordCount + 1;  
			          
			PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)     
				+ ' - ICode: ' + Convert(varchar, @cICode) + ' - Initiated.';

            Declare @StgCnt As int;
                SET @StgCnt=0;

            /* PRINT 'START 1' */  
            --IF Exists(Select * From BOM_TraceableItems t Where t.ItemCode=@cTransactionItem)          
                BEGIN /* PRINT 'START 1.1' */     
   
                    Select @StockNorms=1, @StockItem=@cTransactionItem;                                  
                            
                    /* Inserting Data into Trace Table*/                            
                    IF ((@cDocType = 'SV' and @cFromWarehouseCode='SV')                     
                        OR  (Exists (Select * From COM_DocumentType_Master s                             
                                        Where s.PertainingTo in ('M') and s.ModuleName='INV' and s.DocumentType=@cDocType                            
                                            and s.BranchID=@cBranchID and s.CompID=@cCompID          
                                    )          
                            ) )                                         
                        BEGIN                                         
                            IF Not Exists (Select * from COM_Trace_LotMaster_TmpQty_Trial                                        
                                            Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate          
                                                and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID)                                                                      
                                BEGIN                            
                                    /* Lot ID Generation */                                          
                                    Select @LotID=IsNull(Max(LotID),0)+1                                          
                                    From COM_Trace_LotMaster_TmpQty_Trial                         
                                    Where BranchID=@cBranchID and CompID=@cCompID                                             
                                       
                                    /* Insert Data Into COM_Trace_LotMaster_TmpQty_Trial --> In Future need to remove the before Union Part */     
                                    Insert into COM_Trace_LotMaster_TmpQty_Trial              
                                        Select @cDocType, @cDocNo, @cDocDate, @cTransactionItem, @LotID As LotID, 1 As SubLotID, --'' As HeatNo,  
                                            dbo.fn_COM_Get_LatestHeatNo_StockVerification(@cTransactionItem, @cTransactionDate, @cBranchID, @cCompID, @cFinyear) as HeatNo,
                                            '' As ManufactureDate, '' As ShelfLifeDays, @cUserID, @cBranchID, @cCompID, @cTransactionDate     
                                        UNION             
                                        /* the below From part newly added */                         
                                        Select @cDocType, @cDocNo, @cDocDate, @cTransactionItem, @LotID As LotID, IsNull(a.SubLotID, 1) As SubLotID, --'' As HeatNo,                                         
                                            a.HeatNo, a.ManufactureDate, a.ShelfLifeDays, @cUserID, @cBranchID, @cCompID, @cTransactionDate                             
                                        From Rec_ReceiptEntry_Dtl_Trace a                          
										Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate and a.ItemCode=@cTransactionItem                          
											and a.BranchId=@cBranchID and a.CompId=@cCompID                                 
                                END                                         
                            ELSE                                        
                                BEGIN                                        
                                    SELECT @LotID=LotID, @SubLotID=IsNull(SubLotID, 1)          
                                    From COM_Trace_LotMaster_TmpQty_Trial                                        
                                    Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate                                        
                                        and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID                                        
                                END  
                                              
                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty_Trial */                               
                            Insert into COM_Trace_MaterialTran_TmpQty_Trial   
                                Select @cICode, IsNull(@LotID, -1),  IsNull(@SubLotID, 1), @cTransactionItem, @cTransactionQty As TransactionQty, @cTransactionItem,   
                                    @cTransactionQty As ChildQty, -4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode,   
                                    @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,                                
                                    '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate     
                   
							/* Insert Data Into COM_Trace_DocTran_Trial */       
							Insert into COM_Trace_DocTran_Trial   
                                Select @cICode as TranID, @cTransactionItem as ItemCode, @cTransactionQty As TransactionQty, IsNull(@LotID, -1) as LotID, 
									0 as FromTranDocID, @cTranDocId as ToTranDocID, @cFromWarehouseCode As FromWarehouseCode,   
                                    @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,  
									'0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate as Transtamp
                   
                            /* PRINT 'ICode: ' + Convert(varchar, @cICode) + ' - Completed - SV Entry.'; */                                     
                        END 
                    
                    ELSE If @cDocType='RR'                                              
                        BEGIN  
                            PRINT 'RR START'
                            
                            IF Exists (Select * From Rec_ReceiptEntry_Hdr                             
                                        Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate                             
                                            and BranchID=@cBranchID and CompID=@cCompID and InwardType in ('P','C','U'))   --Purchase, CashPurchase, CustomerSuppliedProduct   
								BEGIN                                      
									IF Not Exists (Select * From COM_Trace_LotMaster_TmpQty_Trial                                        
													Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate                                        
                                                            and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID  
                                                    )                                        
										BEGIN   /* Receipt Entry */                      
                                            /* Lot ID Generation */                             
											Select @LotID=IsNull(Max(LotID),0)+1                                          
                                            From COM_Trace_LotMaster_TmpQty_Trial                                            
                                            Where BranchID=@cBranchID and CompID=@cCompID                         
                                          
                                            /* PRINT 'Lot ID Generation'  + Convert(varchar, @LotID) */    
                           
                                            /* Insert Data Into COM_Trace_LotMaster_TmpQty_Trial */                                
                                            Insert into COM_Trace_LotMaster_TmpQty_Trial   
                                                Select a.ReceiptEntryType As DocType, a.ReceiptEntryNo As DocNo, a.ReceiptEntryDate As DocDate, @cTransactionItem,                             
                                                    @LotID As LotID, IsNull(c.SubLotID, 1) As SubLotID, IsNull(c.HeatNo,'') as HeatNo, 
													IsNull(c.ManufactureDate,'') as ManufactureDate, IsNull(c.ShelfLifeDays,0) as ShelfLifeDays, 
													@cUserID, @cBranchID, @cCompID, @cTransactionDate                                          
                                                From Rec_ReceiptEntry_Hdr a                                          
                                                Left Outer Join Rec_ReceiptEntry_Dtl b                                          
                                                    On a.ReceiptEntryNo=b.ReceiptEntryNo and a.ReceiptEntryDate=b.ReceiptEntryDate and a.ReceiptEntryType=b.ReceiptEntryType                             
                                                        and a.BranchID=b.BranchID and a.CompID=b.CompID                           
                                                Left Outer Join Rec_ReceiptEntry_Dtl_Trace c                                          
                                                    On c.ReceiptEntryNo=b.ReceiptEntryNo and c.ReceiptEntryDate=b.ReceiptEntryDate and c.ReceiptEntryType=b.ReceiptEntryType                             
                                                        and c.ItemCode=b.ItemCode and b.ItemSeq=c.ItemSeq and c.BranchID=b.BranchID and c.CompID=b.CompID                                         
                                                Where a.BranchID=@cBranchID and a.CompID=@cCompID and a.Finyear=@cFinyear and b.ItemCode=@cTransactionItem                                          
                                                    and a.ReceiptEntryType=@cDocType and a.ReceiptEntryNo=@cDocNo and a.ReceiptEntryDate=@cDocDate                        
    
                                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty_Trial */                     
                                            Insert into COM_Trace_MaterialTran_TmpQty_Trial  
                                                Select @cICode, @LotID, IsNull(c.SubLotID, 1) as SubLotID, @cTransactionItem, IsNull(c.Qty, @cTransactionQty) As TransactionQty, 
													@cTransactionItem, IsNull(c.Qty, @cTransactionQty) As ChildQty,          
													/* @cTransactionQty As TransactionQty,   @cTransactionItem,   @cTransactionQty As ChildQty, */                      
                                                    -4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode,   
                                                    @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID,   
                                                    @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                          
												From Rec_ReceiptEntry_Dtl b
												Left Outer Join Rec_ReceiptEntry_Dtl_Trace c     
													 On c.ReceiptEntryNo=b.ReceiptEntryNo and c.ReceiptEntryDate=b.ReceiptEntryDate and c.ReceiptEntryType=b.ReceiptEntryType                             
                                                     and c.ItemCode=b.ItemCode and b.ItemSeq=c.ItemSeq and c.BranchID=b.BranchID and c.CompID=b.CompID          
                                                Where b.ReceiptEntryNo=@cDocNo and b.ReceiptEntryDate=@cDocDate and b.ReceiptEntryType=@cDocType                           
                                                    and b.ItemCode=@cTransactionItem and b.BranchID=@cBranchID and b.CompID=@cCompID  
									
											/* Insert Data Into COM_Trace_DocTran */           
											Insert into COM_Trace_DocTran_Trial
												Select @cICode as TranID, @cTransactionItem as ItemCode, a.Qty, @LotID as LotID, 0 as FromTranDocID, @cTranDocId as ToTranDocID,
													@cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode,   
                                                    @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,	
													'0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate as Transtamp
												From COM_Trace_MaterialTran_TmpQty_Trial a
												Where a.TranID=@cICode and a.BranchID=@cBranchID and a.CompID=@cCompID and a.Finyear=@cFinyear and a.Transtamp=@cTransactionDate

                                            /* PRINT 'COM_Trace_MaterialTran_TmpQty_Trial - Receipt Entry' */                     
                                        END  
                                    ELSE                                        
                                        BEGIN                                        
                                            Select @LotID=LotID, @SubLotID=SubLotID                             
                                            From COM_Trace_LotMaster_TmpQty_Trial                                        
                                            Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate                                        
                                                and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID                        
                                            /* PRINT 'Lot ID Generation' */                                           
                                         
  
                                            /*PRINT 'Lot ID Generation'    + Convert(varchar, @LotID) */                
                               
                                            /* Acceptance Entry - If User enter Accepted, Rejection, Scrap qty then material Tran dtl table have 3 rows   
                                            for three different whs Since this 3 entries need to be saved in  table COM_Trace_MaterialTran_TmpQty_Trial    
                                            individually As well As SublotID wise. So we saved the entries As below */                  
                         
                                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty_Trial - Accepted Qty */                    
                                            Insert into COM_Trace_MaterialTran_TmpQty_Trial  
                                                Select @cICode, @LotID, IsNull(c.SubLotID,1) as SubLotID, @cTransactionItem, 
                                                    Case When IsNull(c.AcceptedQty,0)>0 Then c.AcceptedQty Else r.AcceptedQty End As TransactionQty, @cTransactionItem,
                                                    Case When IsNull(c.AcceptedQty,0)>0 Then c.AcceptedQty Else r.AcceptedQty End As ChildQty,                       
													1 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,
													'0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                           
												From Rec_ReceiptEntry_Dtl r
                                                Left Outer Join Rec_ReceiptEntry_Dtl_Trace c
                                                    On c.ReceiptEntryNo=r.ReceiptEntryNo and c.ReceiptEntryDate=r.ReceiptEntryDate and c.ReceiptEntryType=r.ReceiptEntryType and c.ItemCode=r.ItemCode
                                                    and c.BranchID=r.BranchID and c.CompID=r.CompID 
                                                Where r.ReceiptEntryNo=@cDocNo and r.ReceiptEntryDate=@cDocDate and r.ReceiptEntryType=@cDocType                           
                                                    and r.ItemCode=@cTransactionItem and r.BranchID=@cBranchID and r.CompID=@cCompID and r.AcceptedQty > 0                      
                                                    and @cToWarehouseCode not in (Select WarehouseCode From Inv_Warehouse_Master Where WarehouseNature in ('Rejection', 'Scrap'))                
                               
                                            /* PRINT 'COM_Trace_MaterialTran_TmpQty_Trial - Accepted Entry - Accepted Qty' */                    
                    
                                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty_Trial - Rejected Qty */                    
                                            Insert into COM_Trace_MaterialTran_TmpQty_Trial   
                                                Select @cICode, @LotID, IsNull(c.SubLotID,1) as SubLotID, @cTransactionItem, 
                                                    Case When IsNull(c.RejectedQty,0)>0 Then c.RejectedQty Else r.RejectionQty End As TransactionQty, @cTransactionItem,  
                                                    Case When IsNull(c.RejectedQty,0)>0 Then c.RejectedQty Else r.RejectionQty End As ChildQty,                       
                                                    2 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode,          
                                                    @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear,           
                                                    @cTransactionDate                                              
                                                From Rec_ReceiptEntry_Dtl r                                      
                                                Left Outer Join Rec_ReceiptEntry_Dtl_Trace c    
                                                    On c.ReceiptEntryNo=r.ReceiptEntryNo and c.ReceiptEntryDate=r.ReceiptEntryDate and c.ReceiptEntryType=r.ReceiptEntryType and c.ItemCode=r.ItemCode
                                                    and c.BranchID=r.BranchID and c.CompID=r.CompID 
                                                Where r.ReceiptEntryNo=@cDocNo and r.ReceiptEntryDate=@cDocDate and r.ReceiptEntryType=@cDocType                           
                                                    and r.ItemCode=@cTransactionItem and r.BranchID=@cBranchID and r.CompID=@cCompID and r.RejectionQty > 0                      
                                                    and @cToWarehouseCode not in (Select WarehouseCode From Inv_Warehouse_Master Where WarehouseNature in ('InHouse', 'Scrap'))                
                
                                            /* PRINT 'COM_Trace_MaterialTran_TmpQty_Trial - Accepted Entry - Rejected Qty' */                
 
											/* Insert Data Into COM_Trace_MaterialTran_TmpQty_Trial - Scrap Qty */                    
											Insert into COM_Trace_MaterialTran_TmpQty_Trial  
                                                Select @cICode, @LotID, IsNull(c.SubLotID,1) as SubLotID, @cTransactionItem, 
													Case When IsNull(c.ScrapQty,0)>0 Then c.ScrapQty Else r.ScrapQty End As TransactionQty, @cTransactionItem, 
                                                    Case When IsNull(c.ScrapQty,0)>0 Then c.ScrapQty Else r.ScrapQty End As ChildQty,                                            
                                                    4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode,          
                                                    @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear,          
                                                    @cTransactionDate                                           
                                                From Rec_ReceiptEntry_Dtl r                                        
                                                Left Outer Join  Rec_ReceiptEntry_Dtl_Trace c
                                                    On c.ReceiptEntryNo=r.ReceiptEntryNo and c.ReceiptEntryDate=r.ReceiptEntryDate and c.ReceiptEntryType=r.ReceiptEntryType and c.ItemCode=r.ItemCode
                                                    and c.BranchID=r.BranchID and c.CompID=r.CompID 
                                                Where r.ReceiptEntryNo=@cDocNo and r.ReceiptEntryDate=@cDocDate and r.ReceiptEntryType=@cDocType                           
                                                    and r.ItemCode=@cTransactionItem and r.BranchID=@cBranchID and r.CompID=@cCompID and r.ScrapQty > 0                      
                                                    and @cToWarehouseCode not in ( Select WarehouseCode From Inv_Warehouse_Master Where WarehouseNature in ('InHouse', 'Rejection'))                
                
                                            /* PRINT 'COM_Trace_MaterialTran_TmpQty_Trial - Accepted Entry - Scrap Qty' */      
											
											/* Insert Data Into COM_Trace_DocTran */           
											Insert into COM_Trace_DocTran_Trial
												Select @cICode as TranID, @cTransactionItem as ItemCode, a.Qty, @LotID as LotID, 0 as FromTranDocID, @cTranDocId as ToTranDocID,
													@cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode,   
                                                    @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,	
													'0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate as Transtamp
												From COM_Trace_MaterialTran_TmpQty_Trial a
												Where a.TranID=@cICode and a.BranchID=@cBranchID and a.CompID=@cCompID and a.Finyear=@cFinyear and a.Transtamp=@cTransactionDate

                                    END  
                                END  
                                /* PRINT 'ICode: ' + Convert(varchar, @cICode) + ' - Completed - RR (Purchase, CashPurchase, Customer Supplied Product) Entry.'; */                          

                            ELSE If @cToWarehouseCode='UI' and Exists (Select * From Rec_ReceiptEntry_Hdr                             
                                                                        Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate                            
                                                                        and BranchID=@cBranchID and CompID=@cCompID and InwardType in ('S','L','M'))                
                                BEGIN     /* Subcontract, SubcontractPartial, DismantlingDC */         --# 1.1.1             
                                    /* TranID Generation */                             
										Declare @MaxTranID bigint;                                         
											Select @MaxTranID=IsNull(Max(TranID),0)+1                                          
											From COM_Trace_MaterialTran_TmpQty_Trial                                            
											Where ReverseEntryFlg='1' and BranchID=@cBranchID and CompID=@cCompID        
										
									/******************************************************** Dummy Entry ********************************************************/ 
									/* Insert Data Into COM_Trace_MaterialTran_TmpQty_Trial - SentItem -> Subcontract to Dummy */                        
                                    Insert into COM_Trace_MaterialTran_TmpQty_Trial  
                                        Select @MaxTranID As ICode, b.LotID, b.SubLotID As SubLotID, a.TransactionItem, b.CBQty As TransactionQty,   
											a.TransactionItem As ChildCode, b.CBQty As ChildQty, -4 As CriteriaCode, a.ToWarehouseCode As FromWarehouseCode,   
                                            a.ToRackBinCode As FromRackBinCode, 'DUM' As ToWarehouseCode, '' As ToRackBinCode, '1' As ReverseEntryFlg,   
                                            -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                   
                                        From INV_MATERIALTRAN_DTL_LotTrial a                                  
                                        Cross Apply fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_Trial(a.TransactionItem, a.ToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b
                                        Where a.BranchID=@cBranchID and a.CompID=@cCompID                            
                                            and Exists ( Select * From Rec_ReceiptEntry_Dtl s       
                                                        Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                            
                                                            and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                             
                                                            and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                            
                                                    )                            
                                                
                                    /* Insert Data Into COM_Trace_MaterialTran_TmpQty_Trial - ReceivedItem -> Dummy to Subcontract */                           
                                    Insert into COM_Trace_MaterialTran_TmpQty_Trial    
                                        Select (@MaxTranID+1) As ICode, b.LotID, b.SubLotID As SubLotID, @cTransactionItem As TransactionItem,   
                                            b.CBQty As TransactionQty, @cTransactionItem As ChildCode, b.CBQty As ChildQty, -4 As CriteriaCode,                                  
                                            'DUM' As FromWarehouseCode, '' As FromRackBinCode, @cFromWarehouseCode As ToWarehouseCode,   
                                            @cFromRackBinCode As ToRackBinCode, '1' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID,   
                                            @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                   
                                        From INV_MATERIALTRAN_DTL_LotTrial a 
										Outer Apply
											(
												Select o.TranID, o.LotID, o.SubLotID, o.ItemCode, o.Qty as CBQty 
												From COM_Trace_MaterialTran_TmpQty_Trial o
												Where o.TranID=@MaxTranID and o.Transtamp=@cTransactionDate and o.BranchID=@cBranchID and o.CompID=@cCompID
											)b	
                                        --Cross Apply dbo.fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_Trial(a.TransactionItem, 'DUM', @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b
                                        Where a.BranchID=@cBranchID and a.CompID=@cCompID                            
                                            and Exists ( Select * From Rec_ReceiptEntry_Dtl s             
                                                            Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                            
                                                                and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                             
                                                                and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                            
                                                            )                            
									
                                    /* Insert Data Into COM_Trace_MaterialTran_TmpQty_Trial */              
									Insert into COM_Trace_MaterialTran_TmpQty_Trial  
                                        Select @cICode, b.LotID, b.SubLotID As SubLotID, @cTransactionItem, b.CBQty As TransactionQty,   
                                            @cTransactionItem As ChildCode, b.CBQty As ChildQty, -4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, +  
                                            @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,                                           
                                            '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                   
                                        From INV_MATERIALTRAN_DTL_LotTrial a                                  
                                        Cross Apply dbo.fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_Trial(@cTransactionItem, a.ToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b
                                        Where Exists ( Select * From Rec_ReceiptEntry_Dtl s                            
                                                        Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                            
                                                            and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                             
                                                            and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                            
                                                    )  
										
										 
									/* Insert Data Into DocTran Trace Table - SentItem -> Subcontract to Dummy */  
									Insert into COM_Trace_DocTran_Trial  
										Select @MaxTranID as TranID, b.RefItemCode, (@cTransactionQty*b.RefNorms) as TransactionQty, b.RefLotID as LotID, b.RefTranDocID as FromTranDocID, @MaxTranID as ToTranDocID,     
											@cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, 'DUM' as ToWarehouseCode, '' as ToRackBinCode,                 
											'1' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, DateAdd(s,-1,@cTransactionDate)        
										From fn_COM_Trace_RefTranDocId(@cDocType, @cDocNo, @cDocDate, @StockItem, @cFromWarehouseCode, @cToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)b
									 
									/* Insert Data Into DocTran Trace Table - ReceivedItem -> Dummy to Subcontract */ 
									Insert into COM_Trace_DocTran_Trial  
										Select (@MaxTranID+1) as TranID, @cTransactionItem, IsNull(Sum(b.Qty/a1.RefNorms),0) as TransactionQty, b.LotID, 
											@MaxTranID as FromTranDocID, (@MaxTranID+1) as ToTranDocID,
											'DUM' as FromWarehouseCode, '' as FromRackBinCode, @cFromWarehouseCode as ToWarehouseCode, @cFromRackBinCode as ToRackBinCode,                 
											'1' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, DateAdd(s,-1,@cTransactionDate)        
										From COM_Trace_DocTran_Trial b
										Outer Apply
										(
											Select * From fn_COM_Trace_RefTranDocId(@cDocType, @cDocNo, @cDocDate, @StockItem, @cFromWarehouseCode, @cToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)o
										)a1
										Where b.TranID=@MaxTranID and b.ToWarehouseCode='DUM' and b.BranchID=@cBranchID and b.CompID=@CompID and b.Finyear=@Finyear
											and b.Transtamp=DateAdd(s,-1,@cTransactionDate)
										Group by b.LotID

									/* Insert Data Into DocTran Trace Table - ReceivedItem -> Subcontract to GES */ 
									Insert into COM_Trace_DocTran_Trial  
										Select @cICode, @cTransactionItem, b.Qty as TransactionQty, b.LotID, (@MaxTranID+1) as FromTranDocID, @cTranDocID as ToTranDocID, 
											@cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,                 
											'0' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, @Finyear as Finyear, @cTransactionDate        
										From COM_Trace_DocTran_Trial b
										Where b.TranID=(@MaxTranID+1) and b.FromWarehouseCode='DUM' and b.ItemCode=@cTransactionItem and b.BranchID=@cBranchID and b.CompID=@CompID and b.Finyear=@Finyear
											and b.Transtamp=DateAdd(s,-1,@cTransactionDate)
								  
									/****************************************************************************************************************/ 

                                END         --# 1.1.1                               
                            ELSE  
                                BEGIN        --# 1.1.1 
                                    /* Insert Data Into COM_Trace_MaterialTran_TmpQty_Trial - Doctype = RR  and Other Inward Types */          
                                    Insert into COM_Trace_MaterialTran_TmpQty_Trial   
                                        Select @cICode, b.LotID, b.SubLotID As SubLotID, @cTransactionItem, b.CBQty As TransactionQty, @cTransactionItem As ChildCode,     
                                            b.CBQty As ChildQty, -4 As CriteriaCode,  @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode,     
											@cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID,     
                                            @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                   
                                        From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_Trial(@cTransactionItem, @cFromWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b
										 
									Insert into COM_Trace_DocTran_Trial
										 Select @cICode, @cTransactionItem, b.CBQty As TransactionQty, b.RefLotID, b.RefTranDocID as FromTranDocID, @cTranDocId as ToTranDocID,
											@cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode,     
											@cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID,     
                                  @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate as Transtamp  
										From fn_COM_Trace_RefTranDocId(@cDocType, @cDocNo, @cDocDate, @cTransactionItem, @cFromWarehouseCode, @cToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b


								END    --# 1.1.1 
                                                              
                            /* PRINT 'ICode: ' + Convert(varchar, @cICode) + ' - Completed - RR Other Entry.'; */   
                         END

                    ELSE /* Inserting Data into Trace Table*/                              
                        BEGIN                --# 1.1.1   
							IF (@cFromWarehouseCode='WIP' AND @cToWarehouseCode = 'WAP')  /* Set Transfer */    
						        BEGIN   
									 
									/*************** For Missing Stock ***************/
									IF Exists (Select IsNull(Sum(CBQTY),0) From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_Trial(@cTransactionItem, @cFromWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @cFinyear) 
													Having IsNull(Sum(CBQTY),0)<@cTransactionQty)
										BEGIN
											-- Missing Stock DocNo
											Select @MissingMinDocNo = IsNull(Min(DocNo),0)-1 
											From COM_Trace_LotMaster_TmpQty_Trial
											Where DocType='SV' and DocNo<0 and BranchID=@BranchID and CompID=@CompID 
									
											-- Missing Stock LotID
											Select @MissingMinLotID = IsNull(Min(LotID),0)-1 
											From COM_Trace_LotMaster_TmpQty_Trial
											Where LotID<0 and BranchID=@BranchID and CompID=@CompID 
							  
											-- Missing Stock TranID
											Select @MissingMinTranID = IsNull(Min(TranID),0)-1  
											From COM_Trace_MaterialTran_TmpQty_Trial 
											Where TranID<0 and ReverseEntryFlg='1' and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear
									
											-- Missing Stock LotQty
											Select @MissingLotQty = @cTransactionQty;

											Select @MissingLotQty=(@cTransactionQty-CBQty)
											From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_Trial(@cTransactionItem, @cFromWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)
											Where CBQty>0

											IF (@MissingLotQty>0)
												BEGIN
													-- Missing Stock HeatNo.
													Select @LatestHeatNo = dbo.fn_COM_Get_LatestHeatNo_StockVerification(@cTransactionItem, @cTransactionDate, @cBranchID , @cCompID, @Finyear)

													Select @LatestHeatNo = Case When @LatestHeatNo='' Then Convert(Varchar,@MissingMinLotID) Else @LatestHeatNo End 

													-- Missing Stock Insert
													Insert into COM_Trace_LotMaster_TmpQty_Trial    
														Select 'SV' as DocType, @MissingMinDocNo as DocNo, Convert(Varchar(10),@cTransactionDate,121) as DocDate, @cTransactionItem as ItemCode, 
															@MissingMinLotID as LotID, 1 as SubLotID, @LatestHeatNo as HeatNo, '' As ManufactureDate, '' As ShelfLifeDays,
															@MissingUserID as UserID, @cBranchID as BranchID, @cCompID as CompID, DateAdd(s,-1,@cTransactionDate) as TranStamp

													Insert into COM_Trace_MaterialTran_TmpQty_Trial    
														Select @MissingMinTranID as TranID, @MissingMinLotID as LotID, 1 as SubLotID, @cTransactionItem as ItemCode, @MissingLotQty as Qty, @cTransactionItem as ChildCode, @MissingLotQty as Qty, 
															-4 as CriteriaCode, 'SV' as FromWarehouseCode, '' as FromRackBinCode, @cFromWarehouseCode as ToWarehouseCode, '' as ToRackBinCode, 
															'1' as ReverseEntryFlg, @MissingUserID as UserID, @cBranchID as BranchID, @cCompID as CompID, @Finyear as Finyear, DateAdd(s,-1,@cTransactionDate) as TranStamp

													Insert into COM_Trace_DocTran_Trial
														Select @MissingMinTranID as TranID, @cTransactionItem as ItemID, @MissingLotQty as Qty, @MissingMinLotID as LotID, 
														0 as FromTranDocID, @MissingMinTranID as ToTranDocID, 
														'SV' as FromWarehouseCode, '' as FromRackBinCode, @cFromWarehouseCode as ToWarehouseCode, '' as ToRackBinCode, 
														'1' as ReverseEntryFlg, @MissingUserID UserID, @cBranchID as BranchID, @cCompID as CompID, @Finyear as Finyear, DateAdd(s,-1,@cTransactionDate) as TranStamp
												END
										END
										/**************************************************/

							        Insert into COM_Trace_MaterialTran_TmpQty_Trial              
								        Select @cICode, v.LotID, v.SubLotID, @cTransactionItem, v.CBQty as TransactionQty, /* Check Transaction Qty Concept */ 
									        isNull(@ChildCode, 0), isNull(@QtyAvailable, 0) as ChildQty, -4 as CriteriaCode,               
									        @cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
									        '0' as ReverseEntryFlg, -2 UserID, @cBranchID as BranchID, @cCompID as CompID, @cFinyear as Finyear, @cTransactionDate      
								        From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_Trial(@cTransactionItem, @cFromWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @cFinyear) v       
      
									Insert into COM_Trace_DocTran_Trial              
										Select @cICode, @cTransactionItem, v.CBQty as TransactionQty, v.LotID, /* Check Transaction Qty Concept */ 
											v.TranDocID as FromTranDocID, @cTranDocId as ToTranDocID,          
											@cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
											'0' as ReverseEntryFlg, -2 UserID, @cBranchID as BranchID, @cCompID as CompID, @cFinyear as Finyear, @cTransactionDate      
										From fn_COM_Trace_AsOnDate_Stock_ItemWHS_DocTran(@cTransactionItem, @cFromWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @cFinyear) v       
      
	   
							        Select @SetTranID = -(Min(a.ICode)), @SetItem=a.TransactionItem     
							        From INV_WIPTRAN_DTL_LotTrial a                
							        Where a.DocType=@CDocType and a.DocNo=@cDocNo and a.DocDate=@cDocDate and a.FromItem=@cFromItem and a.ToItem=@cToItem 
								        and a.ToWarehouseCode = 'WIP' and a.ICode>-(@cICode)
								        and a.BranchID=@cBranchID and a.CompID=@cCompID and a.Finyear=@cFinyear        
							        Group by a.TransactionItem
            
							        Insert into COM_Trace_MaterialTran_TmpQty_Trial              
								        Select @SetTranID, v.LotID, v.SubLotID, @SetItem, v.Qty/@cNorms as TransactionQty, /* Check Transaction Qty Concept */              
									        v.ChildCode, v.ChildQty as ChildQty, -4 as CriteriaCode,               
									        @cDocType as FromWarehouseCode, @cToRackBinCode as FromRackBinCode, @cFromWarehouseCode as ToWarehouseCode, @cFromRackBinCode as ToRackBinCode,               
									        '0' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, v.Finyear as Finyear, @cTransactionDate      
								        From COM_Trace_MaterialTran_TmpQty_Trial v      
								        Where v.TranID=@cICode and BranchID=@BranchID and CompID=@CompID and Finyear in (@Finyear)              --'04-2023 03-2024', 
            
									Insert into COM_Trace_DocTran_Trial              
								        Select @SetTranID, @SetItem, v.Qty/@cNorms as TransactionQty, /* Check Transaction Qty Concept */              
									        v.LotID, v.FromTranDocID, v.ToTranDocID, 
									        @cDocType as FromWarehouseCode, @cToRackBinCode as FromRackBinCode, @cFromWarehouseCode as ToWarehouseCode, @cFromRackBinCode as ToRackBinCode,               
									        '0' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, v.Finyear as Finyear, @cTransactionDate      
								        From COM_Trace_DocTran_Trial v  
								        Where v.TranID=@cICode and BranchID=@BranchID and CompID=@CompID and Finyear in (@Finyear)              --'04-2023 03-2024', 

							        PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)            
							        + ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - WAP Entry.' + 'Norms - ' + Convert(varchar, @cNorms);         
   
						        END   
                            
					        --ELSE IF (NOT (@cFromWarehouseCode='WAP' AND @cToWarehouseCode = 'WIP'))        
                            ELSE IF (NOT (  (Exists (Select * From COM_DocumentType_Master s 
									                    Where s.PertainingTo in ('PI', 'SI', 'LO','R') and s.ModuleName='QC' and s.DocumentType=@cFromWarehouseCode
														and s.BranchID=@cBranchID and s.CompID=@cCompID)
								
								                OR (@cDocType='LOG')
                                
                                            ) AND @cToWarehouseCode = 'WIP'))  

						        BEGIN             
							        SET @ReqQty=Convert(decimal(15, 5), @cTransactionQty*@StockNorms);              
               
							        
									/*************** For Missing Stock ***************/
									IF Exists (Select IsNull(Sum(CBQTY),0) From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_Trial(@StockItem, @cFromWarehouseCode, @ReqQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @cFinyear) 
													Having IsNull(Sum(CBQTY),0)<@ReqQty)
										BEGIN
											-- Missing Stock DocNo
											Select @MissingMinDocNo = IsNull(Min(DocNo),0)-1 
											From COM_Trace_LotMaster_TmpQty_Trial
											Where DocType='SV' and DocNo<0 and BranchID=@BranchID and CompID=@CompID 
									
											-- Missing Stock LotID
											Select @MissingMinLotID = IsNull(Min(LotID),0)-1 
											From COM_Trace_LotMaster_TmpQty_Trial
											Where LotID<0 and BranchID=@BranchID and CompID=@CompID 
							  
											-- Missing Stock TranID
											Select @MissingMinTranID = IsNull(Min(TranID),0)-1  
											From COM_Trace_MaterialTran_TmpQty_Trial 
											Where TranID<0 and ReverseEntryFlg='1' and BranchID=@BranchID and CompID=@CompID and Finyear=@Finyear
									
											-- Missing Stock LotQty
											Select @MissingLotQty = @ReqQty;

											Select @MissingLotQty=(@ReqQty-CBQty)
											From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_Trial(@StockItem, @cFromWarehouseCode, @ReqQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @Finyear)
											Where CBQty>0

											IF (@MissingLotQty>0)
												BEGIN
													-- Missing Stock HeatNo.
													Select @LatestHeatNo = dbo.fn_COM_Get_LatestHeatNo_StockVerification(@StockItem, @cTransactionDate, @cBranchID , @cCompID, @Finyear)

													Select @LatestHeatNo = Case When @LatestHeatNo='' Then Convert(Varchar,@MissingMinLotID) Else @LatestHeatNo End 

													-- Missing Stock Insert
													Insert into COM_Trace_LotMaster_TmpQty_Trial    
														Select 'SV' as DocType, @MissingMinDocNo as DocNo, Convert(Varchar(10),@cTransactionDate,121) as DocDate, @cTransactionItem as ItemCode, 
															@MissingMinLotID as LotID, 1 as SubLotID, @LatestHeatNo as HeatNo, '' As ManufactureDate, '' As ShelfLifeDays,
															@MissingUserID as UserID, @cBranchID as BranchID, @cCompID as CompID, DateAdd(s,-1,@cTransactionDate) as TranStamp

													Insert into COM_Trace_MaterialTran_TmpQty_Trial    
														Select @MissingMinTranID as TranID, @MissingMinLotID as LotID, 1 as SubLotID, @cTransactionItem as ItemCode, @MissingLotQty as Qty, @cTransactionItem as ChildCode, @MissingLotQty as Qty, 
															-4 as CriteriaCode, 'SV' as FromWarehouseCode, '' as FromRackBinCode, @cFromWarehouseCode as ToWarehouseCode, '' as ToRackBinCode, 
															'1' as ReverseEntryFlg, @MissingUserID as UserID, @cBranchID as BranchID, @cCompID as CompID, @Finyear as Finyear, DateAdd(s,-1,@cTransactionDate) as TranStamp

													Insert into COM_Trace_DocTran_Trial
														Select @MissingMinTranID as TranID, @cTransactionItem as ItemID, @MissingLotQty as Qty, @MissingMinLotID as LotID, 
														0 as FromTranDocID, @MissingMinTranID as ToTranDocID, 
														'SV' as FromWarehouseCode, '' as FromRackBinCode, @cFromWarehouseCode as ToWarehouseCode, '' as ToRackBinCode, 
														'1' as ReverseEntryFlg, @MissingUserID UserID, @cBranchID as BranchID, @cCompID as CompID, @Finyear as Finyear, DateAdd(s,-1,@cTransactionDate) as TranStamp
												END
										END
										/**************************************************/
									
									Insert into COM_Trace_MaterialTran_TmpQty_Trial              
										Select @cICode, v.LotID, v.SubLotID, @cTransactionItem, v.CBQty*@StockNorms as TransactionQty, /* Check Transaction Qty Concept */ 
								            isNull(@ChildCode, 0), isNull(@QtyAvailable, 0) as ChildQty, -4 as CriteriaCode,               
								            @cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
								            '0' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, @cFinyear as Finyear, @cTransactionDate              
							            From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty_Trial(@StockItem, @cFromWarehouseCode, @ReqQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @cFinyear) v              
				
									 Insert into COM_Trace_DocTran_Trial              
										Select @cICode, @cTransactionItem,  Case When v.IsRefDocAvailable='1' Then v.CBQty Else v.CBQty*@StockNorms End as TransactionQty, v.RefLotID as LotID,  /* Check Transaction Qty Concept */ 
											v.RefTranDocId as FromTranDocID, @cTranDocId as ToTranDocID,                 
								            @cFromWarehouseCode as FromWarehouseCode, @cFromRackBinCode as FromRackBinCode, @cToWarehouseCode as ToWarehouseCode, @cToRackBinCode as ToRackBinCode,               
								            '0' as ReverseEntryFlg, -2 UserID, @BranchID as BranchID, @CompID as CompID, @cFinyear as Finyear, @cTransactionDate              
							            From fn_COM_Trace_RefTranDocId(@cDocType, @cDocNo, @cDocDate, @StockItem, @cFromWarehouseCode,  @cToWarehouseCode, @ReqQty, @AsOnDate, @AsOnDate, @RptDate, @BranchID, @CompID, @cFinyear) v              
             
							        PRINT 'Record: ' + Convert(varchar, @CurrentRecordCount) + '/' + Convert(varchar, @TotalRecordCount)       
								        + ' - ICode: ' + Convert(varchar, @cICode) + ' - Completed - Other Entry.';            
						        END   

                        END           --# 1.1.1                                        
                END       --# 1.1                                        

            FETCH NEXT FROM CurMaterialTran into  @cICode, @cTranDocId, @cDocType, @cDocNo, @cDocDate,  @cTransactionDate, @cTransactionItem, @cTransactionQty, @cNorms, @cFromWarehouseCode, @cFromRackBinCode,               
                                                    @cToWarehouseCode, @cToRackBinCode, @cFromItem, @cToItem, @cUserID, @cBranchID, @cCompID, @cFinyear   
     END                --# 1.1  

     PRINT 'Process Completed';            
            
	close CurMaterialTran              
	deallocate CurMaterialTran              
               

END         -- # 1 
GO

/****** Object:  StoredProcedure [dbo].[Tmp_DD_KPI_SalesValue_ChartData_Ins]    Script Date: 17/06/2026 11:31:06 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[Tmp_DD_KPI_SalesValue_ChartData_Ins](@AsOnDate datetime, @BranchID varchar(2), @CompID varchar(2))          
/* Process Current Date, Current Month, Current Year Data from the original table if it is changed from last process        
    and all other data will be taken from already processed data */        
AS                        
BEGIN                    
	SET NOCOUNT ON;        
        
	DECLARE @ChartTypeId int;        
		SET @ChartTypeId=1; /* From Table ChartTypeMaster */        
         
	DECLARE @CurDate datetime;        
		SET @CurDate = getdate();            
              
	/* Currently Day First shift starttime hard coded. It should be taken from Shift Master */          
	DECLARE @ShiftStart datetime;          
		SET @ShiftStart='06:00';          
                
    DECLARE @Finyear varchar(15);                    
                    
    /* Period Start End */                    
    DECLARE @YearStart datetime, @YearEnd datetime, @MonthStart datetime, @MonthEnd datetime, @DayStart datetime, @DayEnd datetime;                      
              
	If (Convert(varchar(8), @AsOnDate, 108)<=@ShiftStart)          
		BEGIN          
			SET @DayStart=Convert(varchar(10), DateAdd(day, -1, @AsOnDate), 120) + ' 06:00';          
			--SET @MonthStart=Convert(varchar(7), DateAdd(day, -1, @AsOnDate), 120) + '-01';          
			--SET @Finyear=dbo.fn_COM_Get_Finyear(DateAdd(day, -1, @AsOnDate));          
		END          
	Else          
		BEGIN          
			SET @DayStart=Convert(varchar(10), @AsOnDate, 120) + ' 06:00';          
			--SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';          
			--SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);          
		END    
    
    SET @MonthStart=Convert(varchar(7), @AsOnDate, 120) + '-01';        
    SET @Finyear=dbo.fn_COM_Get_Finyear(@AsOnDate);    
    
    SELECT @DayEnd=DateAdd(day, 1, @DayStart), @MonthEnd=DateAdd(day, -1, DateAdd(month, 1, @MonthStart));          
    SELECT @YearStart=FinStart, @YearEnd=FinEnd from dbo.fn_COM_Get_FinYearStartEnd(@AsOnDate);                      
            
    DECLARE @MonthWorkingDays int, @TotalShiftHours int, @CompletedDays int;                    
    SET @TotalShiftHours=24;    /* It should be calculated from shift master as sum of all production shifts */                                
             
    Select @MonthWorkingDays=(Day(@MonthEnd) - Count(*))        
    From DD_KPI_HolidayMaster        
    Where HolidayDate between @MonthStart and @MonthEnd and BranchID=@BranchID and CompID=@CompID        
            
    Select @CompletedDays=(DateDiff(day, @MonthStart, Convert(varchar(10),@DayStart,120)) - Count(*)) +1        
    From DD_KPI_HolidayMaster        
    Where HolidayDate between @MonthStart and Convert(varchar(10),@DayStart,120) and BranchID=@BranchID and CompID=@CompID        
               
    DECLARE  @MonthLabelCount money,  @YearLabelCount money ,  @DayLabelCount money;                        
    DECLARE  @MonthTarget money,  @YearTarget money ,  @DayTarget money;                        
                        
    SET @YearLabelCount=12;    /* No. of months in a Year */                    
    SET @MonthLabelCount=@MonthWorkingDays;                     
    SET @DayLabelCount=@TotalShiftHours;                        
        
	DECLARE @YearPeriodType Char(2), @MonthPeriodType Char(2), @DayPeriodType Char(2)    
		SELECT @YearPeriodType='YR', @MonthPeriodType='MN', @DayPeriodType='DY'    
                     
	--SET @YearTarget=360000000;       
	SET @YearTarget = dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'Target',@YearPeriodType,@BranchID,@CompID);                           
	SET @MonthTarget=@YearTarget/12;                        
	SET @DayTarget=  @MonthTarget/@MonthWorkingDays ; --  @MonthTarget/@MonthWorkingDays ;                        
              
	DECLARE @YearPlan money, @YearPlanTillMonth money, @YearSales money, @YearVarianceAllowedPerc decimal(5, 2), @YearVarianceAllowed money,                     
			@MonthPlan money, @MonthPlanTillDate money, @MonthSales money, @MonthVarianceAllowedPerc decimal(5, 2), @MonthVarianceAllowed money,                       
			@DayPlan money, @DayPlanTillNow money, @DaySales money, @DayVarianceAllowedPerc decimal(5, 2), @DayVarianceAllowed money;          
                                    
	--SELECT @YearVarianceAllowedPerc=5.0/100.0, @MonthVarianceAllowedPerc=5.0/100.0, @DayVarianceAllowedPerc=5.0/100.0;                   
	SELECT @YearVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@YearPeriodType,@BranchID,@CompID),     
			@MonthVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@MonthPeriodType,@BranchID,@CompID),     
			@DayVarianceAllowedPerc=dbo.fn_DD_KPI_ChartOptionMaster_Get_TypeValue(@ChartTypeId,'AllowedVariance',@DayPeriodType,@BranchID,@CompID)    
                 
	DECLARE @SalesPlan_Tbl TABLE (PlanFor int, PlanPeriod datetime, CustomerCode int, ItemCode varchar(20), PlanQty money)              
	Insert into @SalesPlan_Tbl              
		Select PlanFor, PlanPeriod, CustomerCode, ItemCode, PlanQty              
		From fn_SAL_SalesPlan_Dtl_v2(@AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear)              
		Where PlanPeriod Between @MonthStart and @MonthEnd              
  
	Select @DayStart, @AsOnDate, @MonthStart, @MonthEnd, @YearStart, @YearEnd , @AsOnDate, @AsOnDate, @BranchID, @CompID, @Finyear         
    
    Select * From @SalesPlan_Tbl
    return;
             
	/* Month Sales */                      
	Select @MonthPlan=Sum(MonthPlanValue), @MonthPlanTillDate=Sum(MonthPlanTillValue), @MonthSales=Sum(MonthSalesValue)                      
	From        
	(        
		Select Sum(PlanQty*Rate) as MonthPlanValue, Sum(PlanQtyTillDate*Rate) as MonthPlanTillValue, Sum(InvoiceValue) as MonthSalesValue        
		From                      
		(                      
			Select isNull(a.CustomerCode, b.CustomerCode) as CustomerCode, isNull(a.ItemCode, b.ItemCode) as ItemCode,                       
				IsNull((a.PlanQty*@CompletedDays)/@MonthWorkingDays,0) as PlanQtyTillDate, IsNull(a.PlanQty,0) as PlanQty, IsNull(b.InvoiceValue,0) as InvoiceValue,                       
				isNull(b.Rate, dbo.fn_SAL_Item_Rate(a.ItemCode, a.CustomerCode, '', 0, Null, @BranchID, @CompID, @Finyear))as Rate                      
			From                      
				(                     
					Select CustomerCode, ItemCode, Sum(a.PlanQty) as PlanQty        
					/*Sum(Case When a.PlanFor=4 and a.PlanPeriod <= @DayStart Then a.PlanQty Else 0 End) as PlanQtyTillDate,               
					Sum(Case When a.PlanFor=2 Then a.PlanQty Else 0 End) as PlanQty              */        
					From @SalesPlan_Tbl a                      
					Where a.PlanFor=2 and (a.PlanPeriod between @MonthStart and @MonthEnd)                                     
					Group by CustomerCode, ItemCode                      
				)a                      
			Full Outer Join                      
				(                      
					Select CustomerCode, ItemCode, Sum(InvoiceQty*Rate) as InvoiceValue,  AVG(Rate) as Rate               
					From SalesInvoice a                      
					Where ((Convert(varchar(10),InvoiceDate, 120)+ ' ' + Convert(varchar(8),InvoiceTime, 108)) BETWEEN @MonthStart and @AsOnDate)                      
						and Type In ('OE', 'Labour', 'VAT', 'EOU') and BranchID=@BranchID and CompID=@CompID and Finyear = @Finyear                        
					Group by CustomerCode, ItemCode                      
				)b                      
			On a.CustomerCode=b.CustomerCode and a.ItemCode=b.ItemCode                      
		)a                      
	)a             

	/* Day Sales */                       
	Select @DayPlan=(@MonthPlan/@MonthWorkingDays), @DaySales=Sum(InvoiceValue)                    
	From                      
		(  
			
			Select CustomerCode, ItemCode, Sum(InvoiceQty*Rate) as InvoiceValue,  AVG(Rate) as Rate                      
			From SalesInvoice a                      
			Where ((Convert(varchar(10),InvoiceDate, 120)+ ' ' + Convert(varchar(8),InvoiceTime, 108)) BETWEEN @DayStart and @AsOnDate)                    
				and Type In ('OE', 'Labour', 'VAT', 'EOU') and BranchID=@BranchID and CompID=@CompID and Finyear = @Finyear                        
			Group by CustomerCode, ItemCode                                         
		)a                     
                  
	/* Since Hourly Plan not available DayPlanTillNow calculated on prorate basis */                    
	SET @DayPlanTillNow=(@DayPlan * DateDiff(minute, @DayStart, @AsOnDate))/DateDiff(minute, @DayStart, @DayEnd)           
        
	    
	/* Year Sales */         
	Select @YearPlan=Sum(YearPlan) , @YearPlanTillMonth=Sum(YearPlanTillMonth), @YearSales=Sum(YearSales)        
	From        
	(        
		Select @MonthPlan as YearPlan, @MonthPlanTillDate as YearPlanTillMonth,  @MonthSales as YearSales        
            
		Union All        
        
		/* Year Sales (From Digital Data Table) */        
		Select IsNull(Sum(PlanValue),0) as YearPlanValue, IsNull(Sum(PlanValue),0) as YearPlanTillValue, IsNull(Sum(AchievedValue),0) as YearSalesValue        
		From DD_KPI_GaugeChartData a         
		Inner Join             
			(      
				Select Convert(Varchar(7), AsOnDate,120) as YearMonth, Max(AsOnDate) as AsOnDate      
				From DD_KPI_GaugeChartData      
				Where ChartTypeId=@ChartTypeId and PeriodType=@MonthPeriodType        
					and Convert(Varchar(10),AsOnDate,120)<@MonthStart and Convert(Varchar(10),AsOnDate,120)>@YearStart     
					and BranchID=@BranchID and CompID=@CompID        
				Group by  Convert(Varchar(7), AsOnDate,120)      
			)b      
			On a.AsOnDate=b.AsOnDate             
		Where a.ChartTypeId=@ChartTypeId and a.PeriodType=@MonthPeriodType and Convert(Varchar(10),a.AsOnDate,120)<@MonthStart and Convert(Varchar(10),a.AsOnDate,120)>@YearStart      
			and a.BranchID=@BranchID and a.CompID=@CompID         
	)a        
              
	/* Allowed Variance */                      
	Select @YearVarianceAllowed=@YearVarianceAllowedPerc*@YearPlanTillMonth,                      
		@MonthVarianceAllowed=@MonthVarianceAllowedPerc*@MonthPlanTillDate,                
		@DayVarianceAllowed=@DayVarianceAllowedPerc*@DayPlanTillNow                    
             
	If Exists (Select * From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate)                  
		Delete From DD_KPI_GaugeChartData Where ChartTypeId=@ChartTypeId and AsOnDate=@AsOnDate        
        
	Insert into DD_KPI_GaugeChartData        
		Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @DayPeriodType as PeriodType, isNull(@DayTarget, 0) as TargetValue, isNull(@DayPlan, 0) as PlanValue,         
			isNull(@DayPlanTillNow, 0) as PlanTillPeriodValue, isNull(@DaySales, 0) as AchievedValue,       
			isNull(@DaySales, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.      
			isNull(@DayVarianceAllowed, 0) as AllowVariance,          
			isNull((@DayPlanTillNow-@DaySales), 0) as Variance,        
			@BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp        
          
		Union All        
            
		Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @MonthPeriodType as PeriodType, isNull(@MonthTarget, 0) as TargetValue,         
			isNull(@MonthPlan, 0) as PlanValue, isNull(@MonthPlanTillDate, 0) as PlanTillPeriodValue, isNull(@MonthSales, 0) as AchievedValue,       
			isNull(@MonthSales, 0) as AchievedValue2, -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.      
			isNull(@MonthVarianceAllowed, 0) as AllowVariance,  isNull((@MonthPlanTillDate-@MonthSales), 0) as Variance, @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp        
        
		Union All        
            
		Select @ChartTypeId as ChartTypeId, @AsOnDate as AsOnDate, @YearPeriodType as PeriodType, isNull(@YearTarget, 0) as TargetValue,         
			isNull(@YearPlan, 0) as PlanValue, isNull(@YearPlanTillMonth, 0) as PlanTillPeriodValue, isNull(@YearSales, 0) as AchievedValue,       
			isNull(@YearSales, 0) as AchievedValue2,  -- AchievedValue2 ->Temporary used AchievedValue. Future to changed concept.      
			isNull(@YearVarianceAllowed, 0) as AllowVariance,  isNull((@YearPlanTillMonth-@YearSales), 0) as Variance, @BranchID as BranchID, @CompID as CompID, @CurDate as Transtamp        
                  
END 



GO

/****** Object:  StoredProcedure [dbo].[Update_TDI_Groups]    Script Date: 17/06/2026 11:31:06 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO

CREATE PROCEDURE [dbo].[Update_TDI_Groups] (@CallBy varchar(10))

AS

Begin

	While Exists (Select * from FAS_TDI_GroupMaster a Left Outer Join (Select * from FAS_TDI_GroupMaster) b
			On a.Parent=b.GroupName
			Where isNull(b.GrRoute, '')+isNull(b.GrWidth, '')<>'' and (a.GrRoute='' and a.GrWidth<>''))

		Update FAS_TDI_GroupMaster Set GrRoute=b.GrRoute+b.GrWidth
		from FAS_TDI_GroupMaster a Left Outer Join (Select * from FAS_TDI_GroupMaster) b On a.Parent=b.GroupName
		Where isNull(b.GrRoute, '')+isNull(b.GrWidth, '')<>'' and (a.GrRoute='' and a.GrWidth<>'')

End
GO

/****** Object:  StoredProcedure [dbo].[UpTERMSMASTER]    Script Date: 17/06/2026 11:31:06 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[UpTERMSMASTER]
	(@TYPEFLG 		[char](30),
	 @CODE 		[varchar](10),
	 @DESCRIPTION 	[varchar](100),
	 @STATUS 		[bit],
	 @USERID 		[varchar](10),
	 @Branchid		[varchar](3),
	 @COMPID 		[varchar](3))

AS 
BEGIN
SET NOCOUNT ON

declare @cBranchid varchar(3)

declare  BranchidList cursor For
select Branchid from Company_Master where IsBranchAvail = 0 and Compid = @compid

	OPEN BranchidList
	FETCH NEXT FROM BranchidList into @cBranchid 
	WHILE @@FETCH_STATUS = 0
	
	BEGIN


		UPDATE [TERMSMASTER] 
		
		SET  	[DESCRIPTION]	 = @DESCRIPTION,
			[STATUS]	 = @STATUS,
			[USERID]	 = @USERID
			 
		WHERE 
			( [TYPEFLG]	= @TYPEFLG AND
			 [CODE]	 	= @CODE AND
			 [Branchid]	=@cBranchid and 
			 [COMPID]	= @COMPID)
		
		FETCH NEXT FROM BranchidList into @cBranchid 
	END
 	
	close BranchidList
	deallocate BranchidList
END
GO

/****** Object:  StoredProcedure [dbo].[WIPStockDetails]    Script Date: 17/06/2026 11:31:06 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO



CREATE PROCEDURE [dbo].[WIPStockDetails] (@AsOnDate datetime, @Branchid varchar(3), @Compid varchar(3))

AS

begin
	select x.ProcessWorkOrderType,x.ProcessWorkOrderNo,x.ProcessWorkOrderDate, x.FromStageCode, x.UOMDesc , y.ItemDescription, y.UOMDecimal, 
	y.Rate, ((x.IssuedQty-x.MRNQty) - Round(x.IGRQty * x.Norms,3)) WIPStock from (
	select a.ProcessWorkOrderType,a.ProcessWorkOrderNo,a.ProcessWorkOrderDate, a.FromStageCode,
	(Select UOMDesc from Material_Master where  a.FromStageCode=ItemCode and 
	a.Branchid = Branchid and a.Compid = Compid) UOMDesc, 
	a.Norms, isNull((select sum(c.TransactionQty) from INV_MATERIALTRAN_DTL c
	where c.DocType = b.StoreRequestType and c.DocNo = b.StoreRequestNo and c.DocDate = b.StoreRequestDate
	and c.TransactionItem = b.ItemCode and c.Branchid = b.Branchid and c.Compid = b.Compid),0) IssuedQty,

	isNull((select sum(c1.StockReturnQty+c1.LineRejectionQty+c1.ScrapQty) from MaterialReturnNote c1
	where c1.StoreRequestType = b.StoreRequestType and c1.StoreRequestNo = b.StoreRequestNo 
	and c1.StoreRequestDate = b.StoreRequestDate and c1.ItemCode = b.ItemCode and c1.Branchid = b.Branchid 
	and c1.Compid = b.Compid),0) MRNQty,

	isNull((select sum(e.TransactionQty) from INV_MATERIALTRAN_DTL e left outer join PPC_InwardGoodsReceipt d 
	on e.DocType = d.InwardGoodsReceiptType and e.DocNo = d.InwardGoodsReceiptNo and e.DocDate = d.InwardGoodsReceiptDate 
	and e.TransactionItem = d.ItemCode and e.Branchid = d.Branchid and e.Compid = d.Compid
	where d.WorkOrderType = a.ProcessWorkOrderType and d.WorkOrderNo = a.ProcessWorkOrderNo and d.WorkOrderDate = a.ProcessWorkOrderDate
	and d.ItemCode = a.ToStageCode and d.Branchid = a.Branchid and d.Compid = a.Compid),0) IGRQty
	
	from PPC_ProcessWorkOrder a left outer join StoreRequest b 
	on a.ProcessWorkOrderType = b.WOType and a.ProcessWorkOrderNo = b.WONo and a.ProcessWorkOrderDate = b.WODate 
	and a.ParentCode = b.ParentCode and a.FromStageCode = b.ItemCode and a.Branchid = b.Branchid and a.Compid = b.Compid
	where a.ProcessWorkOrderDate <= @AsOnDate and a.Branchid = @Branchid and a.Compid =@Compid and woshortclose=0 and completedstatus=0) x 
	left outer join Material_Master y 
	on x.FromStageCode = y.ItemCode where ((x.IssuedQty-x.MRNQty) - Round(x.IGRQty * x.Norms,3)) > 0 and y.Branchid = @Branchid and y.Compid =@Compid
	
	union 
	
	(select x1.AssemblyWorkOrderType,x1.AssemblyWorkOrderNo,x1.AssemblyWorkOrderDate, x1.ItemCode, 
	x1.UOMDesc,y1.ItemDescription, y1.UOMDecimal, y1.Rate,((x1.IssuedQty-x1.MRNQty) - Round(x1.IGRQty * x1.Norms,3)) WIPStock from (
	select a1.AssemblyWorkOrderType,a1.AssemblyWorkOrderNo,a1.AssemblyWorkOrderDate, a1.ItemCode, 
	(Select UOMDesc from Material_Master where  a1.ItemCode=ItemCode and 
	a1.Branchid = Branchid and a1.Compid = Compid)UOMDesc,
	a1.Norms, isNull((select sum(c1.TransactionQty) from INV_MATERIALTRAN_DTL c1
	where c1.DocType = b1.StoreRequestType and c1.DocNo = b1.StoreRequestNo and c1.DocDate = b1.StoreRequestDate
	and c1.TransactionItem = b1.ItemCode and c1.Branchid = b1.Branchid and c1.Compid = b1.Compid),0) IssuedQty,

	isNull((select sum(c2.StockReturnQty+c2.LineRejectionQty+c2.ScrapQty) from MaterialReturnNote c2
	where c2.StoreRequestType = b1.StoreRequestType and c2.StoreRequestNo = b1.StoreRequestNo 
	and c2.StoreRequestDate = b1.StoreRequestDate and c2.ItemCode = b1.ItemCode and c2.Branchid = b1.Branchid 
	and c2.Compid = b1.Compid),0) MRNQty,

	
	isNull((select sum(e1.TransactionQty) from INV_MATERIALTRAN_DTL e1 left outer join PPC_InwardGoodsReceipt d1 
	on e1.DocType = d1.InwardGoodsReceiptType and e1.DocNo = d1.InwardGoodsReceiptNo and e1.DocDate = d1.InwardGoodsReceiptDate 
	and e1.TransactionItem = d1.ItemCode and e1.Branchid = d1.Branchid and e1.Compid = d1.Compid
	where d1.WorkOrderType = a1.AssemblyWorkOrderType and d1.WorkOrderNo = a1.AssemblyWorkOrderNo and d1.WorkOrderDate = a1.AssemblyWorkOrderDate
	and d1.ItemCode = a1.ItemCode and d1.Branchid = a1.Branchid and d1.Compid = a1.Compid),0) IGRQty
	
	from AssemblyWorkOrder a1 left outer join StoreRequest b1 
	on a1.AssemblyWorkOrderType = b1.WOType and a1.AssemblyWorkOrderNo = b1.WONo and a1.AssemblyWorkOrderDate = b1.WODate and a1.ParentCode = b1.ParentCode and a1.ItemCode = b1.ItemCode and a1.Branchid = b1.Branchid and a1.Compid = b1.Compid
	
	where a1.AssemblyWorkOrderDate <= @AsOnDate and a1.Branchid = @Branchid and a1.Compid =@Compid and woshortclose=0 and completedstatus=0) x1 
	left outer join Material_Master y1 on x1.ItemCode = y1.ItemCode
	where ((x1.IssuedQty-x1.MRNQty) - Round(x1.IGRQty * x1.Norms,3)) > 0 and y1.Branchid = @Branchid and y1.Compid =@Compid  )

	order by x.ProcessWorkOrderType,x.ProcessWorkOrderNo,x.ProcessWorkOrderDate, x.FromStageCode

end
GO

/****** Object:  StoredProcedure [dbo].[WIPStockSummary]    Script Date: 17/06/2026 11:31:06 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO



CREATE PROCEDURE [dbo].[WIPStockSummary] (@AsOnDate datetime, @Branchid varchar(3), @Compid varchar(3))

AS 

begin

	select x.FromStageCode, y.ItemDescription, y.UOMDecimal, x.UOMDesc,y.Rate, sum(((x.IssuedQty-x.MRNQty) - Round(x.IGRQty * x.Norms,3))) WIPStock from (
	select a.ProcessWorkOrderType,a.ProcessWorkOrderNo,a.ProcessWorkOrderDate, a.FromStageCode, 
	(Select UOMDesc from Material_Master where  a.FromStageCode=ItemCode and 
	a.Branchid = Branchid and a.Compid = Compid) UOMDesc,
	a.Norms, a.RequiredQty, isNull((select sum(c.TransactionQty) from INV_MATERIALTRAN_DTL c
	where c.DocType = b.StoreRequestType and c.DocNo = b.StoreRequestNo and c.DocDate = b.StoreRequestDate
	and c.TransactionItem = b.ItemCode and c.Branchid = b.Branchid and c.Compid = b.Compid),0) IssuedQty,

	isNull((select sum(c1.StockReturnQty+c1.LineRejectionQty+c1.ScrapQty) from MaterialReturnNote c1
	where c1.StoreRequestType = b.StoreRequestType and c1.StoreRequestNo = b.StoreRequestNo 
	and c1.StoreRequestDate = b.StoreRequestDate and c1.ItemCode = b.ItemCode and c1.Branchid = b.Branchid 
	and c1.Compid = b.Compid),0) MRNQty,

	isNull((select sum(e.TransactionQty) from INV_MATERIALTRAN_DTL e left outer join PPC_InwardGoodsReceipt d 
	on e.DocType = d.InwardGoodsReceiptType and e.DocNo = d.InwardGoodsReceiptNo and e.DocDate = d.InwardGoodsReceiptDate 
	and e.TransactionItem = d.ItemCode and e.Branchid = d.Branchid and e.Compid = d.Compid
	where d.WorkOrderType = a.ProcessWorkOrderType and d.WorkOrderNo = a.ProcessWorkOrderNo and d.WorkOrderDate = a.ProcessWorkOrderDate
	and d.ItemCode = a.ToStageCode and d.Branchid = a.Branchid and d.Compid = a.Compid),0) IGRQty
	
	from PPC_ProcessWorkOrder a left outer join StoreRequest b 
	on a.ProcessWorkOrderType = b.WOType and a.ProcessWorkOrderNo = b.WONo and a.ProcessWorkOrderDate = b.WODate 
	and a.ParentCode = b.ParentCode and a.FromStageCode = b.ItemCode and a.Branchid = b.Branchid and a.Compid = b.Compid
	where a.ProcessWorkOrderDate <= @AsOnDate and a.Branchid = @Branchid and a.Compid =@Compid and woshortclose=0 and completedstatus=0) x 
	left outer join Material_Master y on x.FromStageCode = y.ItemCode 
	where ((x.IssuedQty-x.MRNQty) - Round(x.IGRQty * x.Norms,3)) > 0 and y.Branchid = @Branchid and y.Compid =@Compid
	group by x.FromStageCode, y.ItemDescription,y.UOMDecimal, x.UOMDesc,y.Rate
	
	union 
	(select x1.ItemCode, y1.ItemDescription, y1.UOMDecimal, x1.UOMDesc, y1.Rate, sum(((x1.IssuedQty-x1.MRNQty) - Round(x1.IGRQty * x1.Norms,3))) WIPStock from (
	select a1.AssemblyWorkOrderType,a1.AssemblyWorkOrderNo,a1.AssemblyWorkOrderDate, a1.ItemCode, 
	(Select UOMDesc from Material_Master where  a1.ItemCode=ItemCode and 
	a1.Branchid = Branchid and a1.Compid = Compid)UOMDesc,
	a1.Norms, a1.RequiredQty, isNull((select sum(c1.TransactionQty) from INV_MATERIALTRAN_DTL c1
	where c1.DocType = b1.StoreRequestType and c1.DocNo = b1.StoreRequestNo and c1.DocDate = b1.StoreRequestDate
	and c1.TransactionItem = b1.ItemCode and c1.Branchid = b1.Branchid and c1.Compid = b1.Compid),0) IssuedQty,

	isNull((select sum(c2.StockReturnQty+c2.LineRejectionQty+c2.ScrapQty) from MaterialReturnNote c2
	where c2.StoreRequestType = b1.StoreRequestType and c2.StoreRequestNo = b1.StoreRequestNo 
	and c2.StoreRequestDate = b1.StoreRequestDate and c2.ItemCode = b1.ItemCode and c2.Branchid = b1.Branchid 
	and c2.Compid = b1.Compid),0) MRNQty,

	isNull((select sum(e1.TransactionQty) from INV_MATERIALTRAN_DTL e1 left outer join PPC_InwardGoodsReceipt d1 
	on e1.DocType = d1.InwardGoodsReceiptType and e1.DocNo = d1.InwardGoodsReceiptNo and e1.DocDate = d1.InwardGoodsReceiptDate 
	and e1.TransactionItem = d1.ItemCode and e1.Branchid = d1.Branchid and e1.Compid = d1.Compid
	where d1.WorkOrderType = a1.AssemblyWorkOrderType and d1.WorkOrderNo = a1.AssemblyWorkOrderNo and d1.WorkOrderDate = a1.AssemblyWorkOrderDate
	and d1.ItemCode = a1.ItemCode and d1.Branchid = a1.Branchid and d1.Compid = a1.Compid),0) IGRQty
	
	from AssemblyWorkOrder a1 left outer join StoreRequest b1 
	on a1.AssemblyWorkOrderType = b1.WOType and a1.AssemblyWorkOrderNo = b1.WONo and a1.AssemblyWorkOrderDate = b1.WODate 
	and a1.ParentCode = b1.ParentCode and a1.ItemCode = b1.ItemCode and a1.Branchid = b1.Branchid and a1.Compid = b1.Compid
	
	where a1.AssemblyWorkOrderDate <= @AsOnDate and a1.Branchid = @Branchid and a1.Compid =@Compid and woshortclose=0 and completedstatus=0) x1 
	left outer join Material_Master y1 on x1.ItemCode = y1.ItemCode 
	where ((x1.IssuedQty-x1.MRNQty) - Round(x1.IGRQty * x1.Norms,3)) > 0 and y1.Branchid = @Branchid and y1.Compid =@Compid 
	group by x1.ItemCode, y1.ItemDescription, y1.UOMDecimal,x1.UOMDesc, y1.Rate) order by x.FromStageCode

end
GO

/****** Object:  StoredProcedure [dbo].[WtAvgFGRate]    Script Date: 17/06/2026 11:31:06 ******/
SET ANSI_NULLS OFF
GO

SET QUOTED_IDENTIFIER OFF
GO







CREATE Procedure [dbo].[WtAvgFGRate] (@Start DateTime, @End DateTime, @CmpCode VarChar(4) , @FinYear VarChar(20))
As

SET NOCOUNT ON

Begin
	Set NoCount On
	Select ItemCode,Round((Value/SumOfQty),2) as WtAvgFGRate
	from (
		Select ItemCode,Sum(Qty) SumOfQty,Sum((Rate*Qty)) as Value 
		from( 
			Select ItemCode,IsNull(Rate,0)Rate,Sum(Qty) as Qty 
			from( 
				Select IsNull(K0.Item_Code,K1.Item_Code) as ItemCode,K0.Rate,IsNull(K1.Qty,0) as Qty
				from 
					(Select J0.OrdType,J0.OrdNum,J0.OrdDate,J0.CustCode,J1.Item_Code,J1.Rate 
					from Sal_OrdMai J0 Join Sal_OrdSub J1
					On J0.OrdType=J1.OrdType and J0.OrdNum =J1.OrdNum And J0.CompId=J1.CompId and J0.FinYear=J1.FinYear
					where J1.CompId=@CmpCode and J1.finyear=@FinYear) K0
				Full Outer Join 
					(Select I0.InvType,I0.InvNum ,I0.CustCode,I1.Item_Code,I1.Qty,I1.OrdType,I1.OrdNum,I1.OrdDate from 
					Sal_InvMai I0 Join Sal_InvSub I1
					On I0.InvType=I1.InvType and I0.InvNum=I1.InvNum and I0.CompId=I1.CompId and I0.FinYear=I1.FinYear
					Where I0.InvDt BetWeen Convert(DateTime,@Start,111) and Convert(DateTime,@End,111)
					and I1.CompId=@CmpCode And I1.FinYear=@FinYear) K1
				On K0.OrdType=K1.OrdType and K0.OrdNum=K1.OrdNum and K0.OrdDate=K1.OrdDate  and K0.CustCode=K1.CustCode
			) K2
			Where Qty > 0 Group By ItemCode,Rate	
		) K3 
		Group by ItemCode
	) K4
	Where Round((Value/SumOfQty),2) > 0
End


GO

/****** Object:  StoredProcedure [dbo].[zTmp_TriggerBased_COM_Trace_MaterialTranLotQty_Tmp]    Script Date: 17/06/2026 11:31:06 ******/
SET ANSI_NULLS ON
GO

SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[zTmp_TriggerBased_COM_Trace_MaterialTranLotQty_Tmp](@CheckInsertedData bit='0', @DocType varchar(3)='', 
	@DocNo int=0, @DocDate datetime=NULL, @TranSactionDate datetime=NULL, @TranSactionItem varchar(20)='', @FromWHCode varchar(10)='',
	@ToWHCode varchar(10)='', @BranchID varchar(3), @CompID varchar(3), @Finyear varchar(20))
-- ON [dbo].[INV_MATERIALTRAN_DTL] FOR INSERT, UPDATE, DELETE                              
AS    
BEGIN    -- # 1.1                                                      
    SET NOCOUNT ON;    
	/* Purpose: Test (INV_MaterialTran_Dtl Based Trigger - TGR_To_Insert_COM_Trace_MaterialTranLotQty) */

    Declare @StgCnt As int;  
    SET @StgCnt=0;  

	/* Insert Data Into Tmp Table (Tmp_Inserted) */
	Select * Into #Tmp_Inserted From vw_INV_MATERIALTRAN_DTL a
	Where (@DocType='' or (@DocType<>'' and a.DocType=@DocType))	
		and (@DocNo<=0 or (@DocNo>0 and a.DocNo=@DocNo))
		and (IsNull(@DocDate,'NULL')='NULL' or (IsNull(@DocDate,'NULL')<>'NULL' and a.DocDate=@DocDate))
		and (IsNull(@TranSactionDate,'NULL')='NULL' or (IsNull(@TranSactionDate,'NULL')<>'NULL' and a.TranSactionDate=@TranSactionDate))
		and (@TranSactionItem='' or (@TranSactionItem<>'' and a.TranSactionItem=@TranSactionItem)) 
		and (@FromWHCode='' or (@FromWHCode<>'' and a.FromWarehouseCode=@FromWHCode))
		and (@ToWHCode='' or (@ToWHCode<>'' and a.ToWarehouseCode=@ToWHCode))		
		and a.BranchID=@BranchID and a.CompID=@CompID and a.Finyear=@Finyear
                              
	If @CheckInsertedData='1'
	 Begin
		Select * From #Tmp_Inserted a
		Order by a.TranSactionDate Desc;
	 End
	Else
	 Begin
    /* PRINT 'START' */                    
    --IF Exists ( Select * From DELETED a Where Exists(Select * From BOM_TraceableItems t Where t.ItemCode=a.TransactionItem) )                              
    --    BEGIN      
    --        /* Delete Data Into COM_Trace_MaterialTran_TmpQty */                           
    --        -- Delete --  COM_Trace_MaterialTran_TmpQty                              
    --        From COM_Trace_MaterialTran_TmpQty a                              
    --        Where Exists( Select * From DELETED s                              
    --                        Where s.ICode=a.TranID and s.BranchID=a.BranchID and s.CompID=a.CompID     
    --                            and s.Finyear=a.Finyear                              
    --                    )                              
    --    END                             
                          
    /* PRINT 'START 1' */                              
    IF Exists( Select * From #Tmp_Inserted a Where Exists(Select * From BOM_TraceableItems t Where t.ItemCode=a.TransactionItem) )            
        BEGIN /* PRINT 'START 1.1' */                       
            /* PRINT 'START Declaration' */                                           
            Declare @ChildCode Varchar(30), @QtyAvailable Float;                                    
            Declare @StockItem Varchar(30), @StockNorms Float;                                  
            Declare @SetItemID int, @SetItem Varchar(30), @SetTranID bigint, @PrevTranQty Float, @PrevNorms Float;                              
                                   
            Declare @cICode bigint, @cDocType Varchar(3), @cDocNo int, @cDocDate datetime, @cTransactionDate datetime,     
                @cTransactionTime datetime, @cTransactionItem Varchar(30), @cTransactionQty Float, @cNorms Float,                                             
                @cFromWarehouseCode Varchar(6), @cFromRackBinCode Varchar(6), @cToWarehouseCode Varchar(6),     
                @cToRackBinCode Varchar(6), @cFromItem Varchar(30), @cToItem Varchar(30), @cUserID Varchar(10),     
                @cBranchID Varchar(3), @cCompID Varchar(3), @cFinyear Varchar(20), @cTranstamp datetime                                             
                                            
            Declare @LotID bigint, @ReqQty decimal(15, 5);                                              
            Declare @SubLotID bigint;                              
                              
            Declare @AsOnDate datetime, @RptDate datetime, @fAsOnDate datetime, @fRptDate datetime, @PrevFinyear Datetime;                              
            Select @AsOnDate = getdate(), @RptDate=@AsOnDate;            
            --//For Financial year stock import into Stock Verification warehouse.                      
            Select @fAsOnDate=Convert(Varchar(4), year(@cTransactionDate)) + Convert(Varchar(15),'-03-31 23:59:59');      
    
            Select @fRptDate = @fAsOnDate;    
                   
            /* PRINT 'ASSIGN START' */                                  
            Select @cICode=ICode, @cDocType=DocType, @cDocNo=DocNo, @cDocDate=DocDate,     
                @cTransactionDate=(Convert(varchar(10),a.TransactionDate,121)+' '+Convert(varchar(8),a.TransactionTime,108)),                              
                @cTransactionItem=TransactionItem, @cTransactionQty=TransactionQty, @cNorms=Norms, @cFromWarehouseCode=FromWarehouseCode,                              
                @cFromRackBinCode=FromRackBinCode, @cToWarehouseCode=ToWarehouseCode, @cToRackBinCode=ToRackBinCode,         
                @cFromItem=FromItem, @cToItem=ToItem, @cUserID=a.UserID, @cBranchID=a.BranchID, @cCompID=a.CompID,     
               @cFinyear=a.Finyear                                    
            From #Tmp_Inserted a                                   
            Where Exists (Select * From BOM_TraceableItems t Where t.ItemCode=a.TransactionItem)                          
                              
            Select @StockNorms=1, @StockItem=@cTransactionItem;                                    
                              
            /* Inserting Data into Trace Table*/                              
            IF ((@cDocType = 'SV' and @cFromWarehouseCode='SV')                       
                OR  (Exists (Select * From COM_DocumentType_Master s                               
                                Where s.PertainingTo in ('M') and s.ModuleName='INV' and s.DocumentType=@cDocType                              
                                    and s.BranchID=@cBranchID and s.CompID=@cCompID            
                            )            
                    )            
                )                                           
                BEGIN                                          
                    IF Not Exists (Select * from COM_Trace_LotMaster_TmpQty                                          
                                    Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate            
                                        and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID)                                                                       
                        BEGIN                              
                            /* Lot ID Generation */                                            
                            Select @LotID=IsNull(Max(LotID),0)+1                                            
                            From COM_Trace_LotMaster_TmpQty                           
                            Where BranchID=@cBranchID and CompID=@cCompID                                               
                                         
                            /* Insert Data Into COM_Trace_LotMaster_TmpQty --> In Future need to remove the before Union Part */       
                            -- Insert into -- COM_Trace_LotMaster_TmpQty                
							Select @cDocType, @cDocNo, @cDocDate, @cTransactionItem, @LotID As LotID, 1 As SubLotID, --'' As HeatNo,                           
							 dbo.fn_COM_Get_LatestHeatNo_StockVerification(@cTransactionItem, @cTransactionDate, @cBranchID, @cCompID, @cFinyear) as HeatNo,  
							 '' As ManufactureDate, '' As ShelfLifeDays, @cUserID, @cBranchID, @cCompID, @cTransactionDate                            
							UNION               
							/* the below From part newly added */                           
							Select @cDocType, @cDocNo, @cDocDate, @cTransactionItem, @LotID As LotID, IsNull(a.SubLotID, 1) As SubLotID, --'' As HeatNo,                                           
							 a.HeatNo, a.ManufactureDate, a.ShelfLifeDays, @cUserID, @cBranchID, @cCompID, @cTransactionDate                               
							From Rec_ReceiptEntry_Dtl_Trace a                            
							Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate and a.ItemCode=@cTransactionItem                            
							 and a.BranchId=@cBranchID and a.CompId=@cCompID                                   
                        END                                           
                    ELSE                                          
                        BEGIN                                          
                            SELECT @LotID=LotID, @SubLotID=IsNull(SubLotID, 1)            
                            From COM_Trace_LotMaster_TmpQty                                          
                            Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate                                          
                                and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID                                          
                        END    
                                    
                    Declare @WhsCode Varchar(10);    
                        Select @WhsCode = Case When @cFromWarehouseCode = 'SV' Then @cToWarehouseCode Else @cFromWarehouseCode End   
              
                    /* Insert Data Into COM_Trace_MaterialTran_TmpQty */                                 
                    -- Insert into -- COM_Trace_MaterialTran_TmpQty     
                        --Select @cICode, IsNull(@LotID, b.LotID),  IsNull(@SubLotID, b.SubLotID), @cTransactionItem, @cTransactionQty As TransactionQty, @cTransactionItem,     
                        Select @cICode, IsNull(@LotID, -1),  IsNull(@SubLotID, 1), @cTransactionItem, @cTransactionQty As TransactionQty, @cTransactionItem,     
                            @cTransactionQty As ChildQty, -4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode,     
                            @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,                                  
                            '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear,     
                            @cTransactionDate       
                        --From #Tmp_Inserted a                                
                        -- Cross Apply fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(a.TransactionItem, @WhsCode, @cTransactionQty, @fAsOnDate, @fAsOnDate, @fRptDate, @cBranchID, @cCompID, @cFinyear)b                             
    
                    /* PRINT 'ICode: ' + Convert(varchar, @cICode) + ' - Completed - SV Entry.'; */                                       
                END  
              
            ELSE If @cDocType='RR'                                                
                BEGIN  /* PRINT 'RR START' */                                                  
                    IF Exists (Select * From Rec_ReceiptEntry_Hdr                               
                                Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate                               
                                    and BranchID=@cBranchID and CompID=@cCompID and InwardType in ('P','C','U'))   --Purchase, CashPurchase, CustomerSuppliedProduct                              
                        BEGIN                                        
                            IF Not Exists (Select * From COM_Trace_LotMaster_TmpQty                                          
                                                Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate                                          
                                                    and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID    
                                            )                                          
                                BEGIN   /* Receipt Entry */                        
                                    /* Lot ID Generation */                                            
                                    Select @LotID=IsNull(Max(LotID),0)+1                                            
                                    From COM_Trace_LotMaster_TmpQty                                              
                                    Where BranchID=@cBranchID and CompID=@cCompID                           
                                            
                                    /* PRINT 'Lot ID Generation'  + Convert(varchar, @LotID) */      
                             
                                    /* Insert Data Into COM_Trace_LotMaster_TmpQty */                                  
                                    -- Insert into -- COM_Trace_LotMaster_TmpQty     
                                        Select a.ReceiptEntryType As DocType, a.ReceiptEntryNo As DocNo, a.ReceiptEntryDate As DocDate, @cTransactionItem,                               
                                           @LotID As LotID, IsNull(c.SubLotID, 1) As SubLotID, IsNull(c.HeatNo,'') as HeatNo,  
										   IsNull(c.ManufactureDate,'') as ManufactureDate, IsNull(c.ShelfLifeDays,0) as ShelfLifeDays,   
										   @cUserID, @cBranchID, @cCompID, @cTransactionDate                                            
                                        From Rec_ReceiptEntry_Hdr a                                            
                                        Left Outer Join Rec_ReceiptEntry_Dtl b                                            
                                            On a.ReceiptEntryNo=b.ReceiptEntryNo and a.ReceiptEntryDate=b.ReceiptEntryDate and a.ReceiptEntryType=b.ReceiptEntryType                               
                                                and a.BranchID=b.BranchID and a.CompID=b.CompID                             
                                        Left Outer Join Rec_ReceiptEntry_Dtl_Trace c                                            
                                            On c.ReceiptEntryNo=b.ReceiptEntryNo and c.ReceiptEntryDate=b.ReceiptEntryDate and c.ReceiptEntryType=b.ReceiptEntryType                               
                                                and c.ItemCode=b.ItemCode and b.ItemSeq=c.ItemSeq and c.BranchID=b.BranchID and c.CompID=b.CompID                                           
                                        Where a.BranchID=@cBranchID and a.CompID=@cCompID and a.Finyear=@cFinyear and b.ItemCode=@cTransactionItem                                            
                                            and a.ReceiptEntryType=@cDocType and a.ReceiptEntryNo=@cDocNo and a.ReceiptEntryDate=@cDocDate                          
      
                                    /* Insert Data Into COM_Trace_LotMaster_TmpQty */                       
                                    -- Insert into -- COM_Trace_MaterialTran_TmpQty    
                                        Select @cICode, @LotID, IsNull(c.SubLotID, 1) as SubLotID, @cTransactionItem, IsNull(c.Qty, @cTransactionQty) As TransactionQty,   
											@cTransactionItem,  IsNull(c.Qty, @cTransactionQty) As ChildQty,                         
                                            /* @cTransactionQty As TransactionQty,   @cTransactionItem,   @cTransactionQty As ChildQty, */                        
                                            -4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode,     
                                            @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID,     
                                            @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                             
                                        From Rec_ReceiptEntry_Dtl b  
										Left Outer Join Rec_ReceiptEntry_Dtl_Trace c       
											On c.ReceiptEntryNo=b.ReceiptEntryNo and c.ReceiptEntryDate=b.ReceiptEntryDate and c.ReceiptEntryType=b.ReceiptEntryType                               
                                                and c.ItemCode=b.ItemCode and b.ItemSeq=c.ItemSeq and c.BranchID=b.BranchID and c.CompID=b.CompID                                   
                                        Where b.ReceiptEntryNo=@cDocNo and b.ReceiptEntryDate=@cDocDate and b.ReceiptEntryType=@cDocType                             
                                            and b.ItemCode=@cTransactionItem and b.BranchID=@cBranchID and b.CompID=@cCompID    
                                   
                                    /* PRINT 'COM_Trace_MaterialTran_TmpQty - Receipt Entry' */                       
						   END    
                            ELSE                                          
                                BEGIN                                          
                                    Select @LotID=LotID, @SubLotID=SubLotID                               
                                    From COM_Trace_LotMaster_TmpQty                                          
                                    Where DocType=@cDocType and DocNo=@cDocNo and DocDate=@cDocDate                                          
                                    and ItemCode=@cTransactionItem and BranchID=@cBranchID and CompID=@cCompID                          
                       
                                    /*PRINT 'Lot ID Generation'    + Convert(varchar, @LotID) */                  
                                 
                                    /* Acceptance Entry - If User enter Accepted, Rejection, Scrap qty then material Tran dtl table have 3 rows     
                                    for three different whs Since this 3 entries need to be saved in  table COM_Trace_MaterialTran_TmpQty      
                                    individually As well As SublotID wise. So we saved the entries As below */                    
                           
                                    /* Insert Data Into COM_Trace_MaterialTran_TmpQty - Accepted Qty */                      
                                    -- Insert into -- COM_Trace_MaterialTran_TmpQty    
                                        Select @cICode, @LotID, IsNull(c.SubLotID,1) as SubLotID, @cTransactionItem,   
											Case When IsNull(c.AcceptedQty,0)>0 Then c.AcceptedQty Else r.AcceptedQty End As TransactionQty, @cTransactionItem,    
                                            Case When IsNull(c.AcceptedQty,0)>0 Then c.AcceptedQty Else r.AcceptedQty End As ChildQty,        
											--c.AcceptedQty As TransactionQty, @cTransactionItem,  c.AcceptedQty As ChildQty,                         
                                            1 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,                                        
             
                                            '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                             
                                        From Rec_ReceiptEntry_Dtl r    
                                        Left Outer Join Rec_ReceiptEntry_Dtl_Trace c  
                                            On c.ReceiptEntryNo=r.ReceiptEntryNo and c.ReceiptEntryDate=r.ReceiptEntryDate and c.ReceiptEntryType=r.ReceiptEntryType and c.ItemCode=r.ItemCode  
                                            and c.BranchID=r.BranchID and c.CompID=r.CompID    
                                        Where r.ReceiptEntryNo=@cDocNo and r.ReceiptEntryDate=@cDocDate and r.ReceiptEntryType=@cDocType                             
                                            and r.ItemCode=@cTransactionItem and r.BranchID=@cBranchID and r.CompID=@cCompID and r.AcceptedQty>0    --c.AcceptedQty > 0                        
                                            and @cToWarehouseCode not in (Select WarehouseCode From Inv_Warehouse_Master Where WarehouseNature in ('Rejection', 'Scrap'))                  
                                 
                                    /* PRINT 'COM_Trace_MaterialTran_TmpQty - Accepted Entry - Accepted Qty' */                      
                      
                                    /* Insert Data Into COM_Trace_MaterialTran_TmpQty - Rejected Qty */                      
                                    -- Insert into -- COM_Trace_MaterialTran_TmpQty     
                                        Select @cICode, @LotID, IsNull(c.SubLotID,1) as SubLotID, @cTransactionItem,   
											Case When IsNull(c.RejectedQty,0)>0 Then c.RejectedQty Else r.RejectionQty End As TransactionQty, @cTransactionItem,   
                                            Case When IsNull(c.RejectedQty,0)>0 Then c.RejectedQty Else r.RejectionQty End As ChildQty,  
                                            --c.RejectedQty As TransactionQty, @cTransactionItem,  c.RejectedQty As ChildQty,                                                
                                            2 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode,            
                                            @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear,             
                                            @cTransactionDate                                                
                                        From Rec_ReceiptEntry_Dtl r  
                                        Left Outer Join Rec_ReceiptEntry_Dtl_Trace c  
                                            On c.ReceiptEntryNo=r.ReceiptEntryNo and c.ReceiptEntryDate=r.ReceiptEntryDate and c.ReceiptEntryType=r.ReceiptEntryType   
												and c.ItemCode=r.ItemCode and c.BranchID=r.BranchID and c.CompID=r.CompID    
                                        Where r.ReceiptEntryNo=@cDocNo and r.ReceiptEntryDate=@cDocDate and r.ReceiptEntryType=@cDocType                             
                                            and r.ItemCode=@cTransactionItem and r.BranchID=@cBranchID and r.CompID=@cCompID and r.RejectionQty > 0      --and c.RejectedQty > 0                        
                                            and @cToWarehouseCode not in (Select WarehouseCode From Inv_Warehouse_Master Where WarehouseNature in ('InHouse', 'Scrap'))                  
                  
                                    /* PRINT 'COM_Trace_MaterialTran_TmpQty - Accepted Entry - Rejected Qty' */                      
                      
                                    /* Insert Data Into COM_Trace_MaterialTran_TmpQty - Scrap Qty */                      
                                    -- Insert into -- COM_Trace_MaterialTran_TmpQty    
                                        Select @cICode, @LotID, IsNull(c.SubLotID,1) as SubLotID, @cTransactionItem,   
											Case When IsNull(c.ScrapQty,0)>0 Then c.ScrapQty Else r.ScrapQty End As TransactionQty, @cTransactionItem,   
                                            Case When IsNull(c.ScrapQty,0)>0 Then c.ScrapQty Else r.ScrapQty End As ChildQty,  
                                            --c.ScrapQty As TransactionQty, @cTransactionItem,  c.ScrapQty As ChildQty,                         
                                            4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode,            
                                            @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear,            
                                            @cTransactionDate                                             
                                        From Rec_ReceiptEntry_Dtl r  
                                        Left Outer Join Rec_ReceiptEntry_Dtl_Trace c  
                                            On c.ReceiptEntryNo=r.ReceiptEntryNo and c.ReceiptEntryDate=r.ReceiptEntryDate and c.ReceiptEntryType=r.ReceiptEntryType   
												and c.ItemCode=r.ItemCode and c.BranchID=r.BranchID and c.CompID=r.CompID   
                                        Where r.ReceiptEntryNo=@cDocNo and r.ReceiptEntryDate=@cDocDate and r.ReceiptEntryType=@cDocType                             
                                            and r.ItemCode=@cTransactionItem and r.BranchID=@cBranchID and r.CompID=@cCompID and r.ScrapQty > 0 --and c.ScrapQty > 0                        
                                   and @cToWarehouseCode not in ( Select WarehouseCode From Inv_Warehouse_Master Where WarehouseNature in ('InHouse', 'Rejection'))                  
                  
                                    /* PRINT 'COM_Trace_MaterialTran_TmpQty - Accepted Entry - Scrap Qty' */                       
                                      
                                END    
                        END  
                    /* PRINT 'ICode: ' + Convert(varchar, @cICode) + ' - Completed - RR (Purchase, CashPurchase, Customer Supplied Product) Entry.'; */                              
                    ELSE If @cToWarehouseCode='UI' and Exists (Select * From Rec_ReceiptEntry_Hdr                               
                                                                Where ReceiptEntryType=@cDocType and ReceiptEntryNo=@cDocNo and ReceiptEntryDate=@cDocDate                              
                                                                    and BranchID=@cBranchID and CompID=@cCompID and InwardType in ('S','L','M')            
                                                            )                     
                        BEGIN     /* Subcontract, SubcontractPartial, DismantlingDC */         --# 1.1.1  
						-- <Temporary Query 30/04/2025 by Mr.Selvaganesh>: (Temporarily using: If LotID, SubLotID, & CBQty  is null, v.LotID=0 / v.SubLotID=1 / v.CBQty=@cTransactionQty will be assigned)
                            /* TranID Generation */                               
                            Declare @MaxTranID bigint;                                           
                                Select @MaxTranID=IsNull(Max(TranID),0)+1                                            
                                From COM_Trace_MaterialTran_TmpQty                                              
                                Where ReverseEntryFlg='1' and BranchID=@cBranchID and CompID=@cCompID                              
                                
                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty - SentItem -> Subcontract to Dummy */                          
                            -- Insert into -- COM_Trace_MaterialTran_TmpQty    
                                Select @MaxTranID As ICode, IsNull(b.LotID,0) As LotID, IsNull(b.SubLotID,1) As SubLotID, a.TransactionItem, 
									IsNull(b.CBQty,@cTransactionQty) As TransactionQty,     
                                    a.TransactionItem As ChildCode, IsNull(b.CBQty,@cTransactionQty) As ChildQty, -4 As CriteriaCode, a.ToWarehouseCode As FromWarehouseCode,     
                                    a.ToRackBinCode As FromRackBinCode, 'DUM' As ToWarehouseCode, '' As ToRackBinCode, '1' As ReverseEntryFlg,     
                                    -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                     
                                From INV_MATERIALTRAN_DTL a                                    
                                Cross Apply fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(a.TransactionItem, a.ToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b                             
                                Where a.BranchID=@cBranchID and a.CompID=@cCompID                              
                                    and Exists ( Select * From Rec_ReceiptEntry_Dtl s         
                                                Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                              
                                                    and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                               
                                                    and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                              
                                            )                              
                                                  
                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty - ReceivedItem -> Dummy to Subcontract */                             
                            -- Insert into -- COM_Trace_MaterialTran_TmpQty      
                                Select (@MaxTranID+1) As ICode, IsNull(b.LotID,0) As LotID, IsNull(b.SubLotID,1) As SubLotID, 
									@cTransactionItem As TransactionItem, IsNull(b.CBQty,@cTransactionQty) As TransactionQty, 
									@cTransactionItem As ChildCode, IsNull(b.CBQty,@cTransactionQty) As ChildQty, -4 As CriteriaCode,                                    
                                    'DUM' As FromWarehouseCode, '' As FromRackBinCode, @cFromWarehouseCode As ToWarehouseCode,     
                                    @cFromRackBinCode As ToRackBinCode, '1' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID,     
                                    @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                     
                                From INV_MATERIALTRAN_DTL a     
								Outer Apply  
								 (  
								  Select o.TranID, o.LotID, o.SubLotID, o.ItemCode, o.Qty as CBQty   
								  From COM_Trace_MaterialTran_TmpQty o  
								  Where o.TranID=@MaxTranID and o.BranchID=@cBranchID and o.CompID=@cCompID --and o.Transtamp=@cTransactionDate   
								 ) b  
                                --Cross Apply dbo.fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(a.TransactionItem, 'DUM', @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b                              
                                Where b.LotID is Not Null and a.BranchID=@cBranchID and a.CompID=@cCompID                              
                                    and Exists ( Select * From Rec_ReceiptEntry_Dtl s                              
                                                    Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                              
                                                        and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                               
                                                        and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                              
                                                    )                              
            
                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty */                       
                            -- Insert into -- COM_Trace_MaterialTran_TmpQty    
                                Select @cICode, IsNull(b.LotID,0) As LotID, IsNull(b.SubLotID,1) As SubLotID, @cTransactionItem, 
									IsNull(b.CBQty,@cTransactionQty) As TransactionQty, @cTransactionItem As ChildCode, 
									IsNull(b.CBQty,@cTransactionQty) As ChildQty, -4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, +    
                                    @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,                                             
                                    '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, 
									@cTransactionDate                                     
                                From INV_MaterialTran_Dtl a    
								Outer Apply  
								 (  
								  Select o.TranID, o.LotID, o.SubLotID, o.ItemCode, o.Qty as CBQty   
								  From COM_Trace_MaterialTran_TmpQty o  
								  Where o.TranID=(@MaxTranID+1) and o.BranchID=@cBranchID and o.CompID=@cCompID --and o.Transtamp=@cTransactionDate   
								 ) b  
                                --Cross Apply dbo.fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@cTransactionItem, a.ToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b   
                                Where Exists ( Select * From Rec_ReceiptEntry_Dtl s                              
                                                Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                              
                                                    and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                               
                                                    and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                              
                                            )  

							/* -- <Original Query Backup>:                                
                            Declare @MaxTranID bigint;                                           
                                Select @MaxTranID=IsNull(Max(TranID),0)+1                                            
                                From COM_Trace_MaterialTran_TmpQty                                              
                                Where ReverseEntryFlg='1' and BranchID=@cBranchID and CompID=@cCompID                              
                                
                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty - SentItem -> Subcontract to Dummy */                          
                            -- Insert into -- COM_Trace_MaterialTran_TmpQty    
                                Select @MaxTranID As ICode, b.LotID, b.SubLotID As SubLotID, a.TransactionItem, b.CBQty As TransactionQty,     
                                    a.TransactionItem As ChildCode, b.CBQty As ChildQty, -4 As CriteriaCode, a.ToWarehouseCode As FromWarehouseCode,     
                                    a.ToRackBinCode As FromRackBinCode, 'DUM' As ToWarehouseCode, '' As ToRackBinCode, '1' As ReverseEntryFlg,     
                                    -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                     
                                From INV_MATERIALTRAN_DTL a                                    
                                Cross Apply fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(a.TransactionItem, a.ToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b                             
                                Where a.BranchID=@cBranchID and a.CompID=@cCompID                              
                                    and Exists ( Select * From Rec_ReceiptEntry_Dtl s         
                                                Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                              
                                                    and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                               
                                                    and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                              
                                            )                              
                                                  
                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty - ReceivedItem -> Dummy to Subcontract */                             
                            -- Insert into -- COM_Trace_MaterialTran_TmpQty      
                                Select (@MaxTranID+1) As ICode, b.LotID, b.SubLotID As SubLotID, @cTransactionItem As TransactionItem,     
                                    b.CBQty As TransactionQty, @cTransactionItem As ChildCode, b.CBQty As ChildQty, -4 As CriteriaCode,                                    
                                    'DUM' As FromWarehouseCode, '' As FromRackBinCode, @cFromWarehouseCode As ToWarehouseCode,     
                                    @cFromRackBinCode As ToRackBinCode, '1' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID,     
                                    @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                     
                                From INV_MATERIALTRAN_DTL a     
								Outer Apply  
								 (  
								  Select o.TranID, o.LotID, o.SubLotID, o.ItemCode, o.Qty as CBQty   
								  From COM_Trace_MaterialTran_TmpQty o  
								  Where o.TranID=@MaxTranID and o.BranchID=@cBranchID and o.CompID=@cCompID --and o.Transtamp=@cTransactionDate   
								 ) b  
                                --Cross Apply dbo.fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(a.TransactionItem, 'DUM', @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b                              
                                Where b.LotID is Not Null and a.BranchID=@cBranchID and a.CompID=@cCompID                              
                                    and Exists ( Select * From Rec_ReceiptEntry_Dtl s                              
                                                    Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                              
                                                        and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                               
                                                        and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                              
                                                    )                              
            
                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty */                       
                            -- Insert into -- COM_Trace_MaterialTran_TmpQty    
                                Select @cICode, b.LotID, b.SubLotID As SubLotID, @cTransactionItem, b.CBQty As TransactionQty,     
                                    @cTransactionItem As ChildCode, b.CBQty As ChildQty, -4 As CriteriaCode, @cFromWarehouseCode As FromWarehouseCode, +    
                                    @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,                                             
                                    '0' As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                     
                                From INV_MaterialTran_Dtl a    
								Outer Apply  
								 (  
								  Select o.TranID, o.LotID, o.SubLotID, o.ItemCode, o.Qty as CBQty   
								  From COM_Trace_MaterialTran_TmpQty o  
								  Where o.TranID=(@MaxTranID+1) and o.BranchID=@cBranchID and o.CompID=@cCompID --and o.Transtamp=@cTransactionDate   
								 ) b  
                                --Cross Apply dbo.fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@cTransactionItem, a.ToWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear)b   
                                Where Exists ( Select * From Rec_ReceiptEntry_Dtl s                              
                                                Where s.RefNo=a.DocNo and s.RefDate=a.DocDate and s.RefType=a.DocType and s.BranchID=a.BranchID and s.CompID=a.CompID                              
                                                    and s.ReceiptEntryType=@cDocType and s.ReceiptEntryNo=@cDocNo and s.ReceiptEntryDate=@cDocDate                               
                                                    and s.ItemCode= Case When a.ToItem ='' Then a.TransactionItem Else a.ToItem End                              
                                            )  

						*/
                        END  
                    ELSE    
                        BEGIN        --# 1.1.1    
                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty - Doctype = RR  and Other Inward Types */  
							-- <Temporary Query 30/04/2025 by Mr.Selvaganesh>: (Temporarily using: If LotID, SubLotID, & CBQty  is null, v.LotID=0 / v.SubLotID=1 / v.CBQty=@cTransactionQty will be assigned)
                            -- Insert into -- COM_Trace_MaterialTran_TmpQty     
                                Select @cICode, IsNull(b.LotID,0) As LotID, IsNull(b.SubLotID,1) As SubLotID, @cTransactionItem, 
									IsNull(b.CBQty,@cTransactionQty) As TransactionQty, @cTransactionItem As ChildCode,       
                                    IsNull(b.CBQty,@cTransactionQty) As ChildQty, -4 As CriteriaCode,  
									@cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode,       
                                    @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID,       
                                    @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                     
                                From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@cTransactionItem, @cFromWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear) b

							/* -- <Original Query Backup>:
							-- Insert into -- COM_Trace_MaterialTran_TmpQty     
                                Select @cICode, b.LotID, b.SubLotID As SubLotID, @cTransactionItem, b.CBQty As TransactionQty, @cTransactionItem As ChildCode,       
                                    b.CBQty As ChildQty, -4 As CriteriaCode,  @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode,       
                                    @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode, '0' As ReverseEntryFlg, -2 UserID,       
                                    @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                     
                                From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@cTransactionItem, @cFromWarehouseCode, @cTransactionQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear) b
							*/
                        END          --# 1.1.1    
  
                    /* PRINT 'ICode: ' + Convert(varchar, @cICode) + ' - Completed - RR Other Entry.'; */     
                END  
  
            ELSE                                            
                BEGIN      --# 1.1                                                          
                    If ((Exists (Select * From COM_DocumentType_Master s                               
                                    Where s.PertainingTo in ('PI', 'SI', 'LO','R') and s.ModuleName='QC' and s.DocumentType = @cFromWarehouseCode                              
                                        and s.BranchID=@cBranchID and s.CompID=@cCompID                              
                                )                               
                            OR (@cDocType='LOG'))                               
                            AND @cToWarehouseCode = 'WIP'                              
                        )                              
                        BEGIN     --# 1.1.1                             
                            /* Finding Set(Previous) TranId, Item */                              
                            Select @SetTranID=a.ICode, @SetItem=a.TransactionItem, @PrevTranQty=a.TransactionQty, @PrevNorms=a.Norms                              
                            From INV_MATERIALTRAN_DTL a                              
                            Where a.BranchID=@cBranchID and a.CompID=@cCompID and a.Finyear=@cFinyear                              
                                and a.ICode=(Select Max(s.ICode) From INV_MATERIALTRAN_DTL s                                    
                                                Where s.DocType=@CDocType and s.DocNo=@cDocNo and s.DocDate=@cDocDate and s.FromItem=@cFromItem and s.ToItem=@cToItem                               
                                                    and s.ToWarehouseCode='WAP' and s.ICode<(@cICode)                               
                                                    and s.BranchID=a.BranchID and s.CompID=a.CompID and s.Finyear=a.Finyear                                 
                                            )                              
                                     
                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty - Log Entry Prev Stage WIP Entry*/                 
                            -- Insert into -- COM_Trace_MaterialTran_TmpQty    
                            Select @SetTranID, v.LotID, v.SubLotID As SubLotID, @SetItem, v.CBQty As TransactionQty, /* Check Transaction Qty Concept */                                            
                                isNull(@ChildCode, 0), isNull(@QtyAvailable, 0) As ChildQty, -4 As CriteriaCode,                                             
                                @cToWarehouseCode As FromWarehouseCode, @cToRackBinCode As FromRackBinCode,                               
                                @cFromWarehouseCode As ToWarehouseCode, @cFromRackBinCode As ToRackBinCode,                                             
                                0 As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                               
                            From fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@SetItem, @cToWarehouseCode, @PrevTranQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear) v                                     
                                                        
                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty - Log Entry Current Stage WAP Entry*/                              
                            -- Insert into -- COM_Trace_MaterialTran_TmpQty    
                            Select @cICode, v.LotID, v.SubLotID As SubLotID, @cTransactionItem, (v.Qty/@PrevNorms) As TransactionQty, /* Check Transaction Qty Concept */                                            
                                v.ChildCode, v.ChildQty As ChildQty, -4 As CriteriaCode,                                             
                                @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode,     
                                @cToRackBinCode As ToRackBinCode, 0 As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID,     
                                @cFinyear As Finyear, @cTransactionDate                                    
                            From COM_Trace_MaterialTran_TmpQty v                                    
                            Where v.TranID=@SetTranID and BranchID=@cBranchID and CompID=@cCompID and Finyear=@cFinyear                                          
                                          
                            /* PRINT 'ICode: ' + Convert(varchar, @cICode) + ' - Completed - LogEntry Entry.'; */    
                        END      --# 1.1.1                                       
                    ELSE If (NOT (@cFromWarehouseCode='WIP' AND @cToWarehouseCode = 'WAP'))                                    
                        BEGIN     --# 1.1.1                                           
                            SET @ReqQty=Convert(decimal(15, 5), @cTransactionQty*@StockNorms);                                            
    
                            /* Insert Data Into COM_Trace_MaterialTran_TmpQty */                                                                     
                            -- Insert into -- COM_Trace_MaterialTran_TmpQty  
							
							-- <Temporary Query 30/04/2025 by Mr.Selvaganesh>: (Temporarily using: If LotID, SubLotID, & CBQty  is null, v.LotID=0 / v.SubLotID=1 / v.CBQty=@cTransactionQty will be assigned)
							Select @cICode, IsNull(v.LotID,0), IsNull(v.SubLotID,1) As SubLotID, @cTransactionItem, 
								IsNull(v.CBQty,@cTransactionQty)*@StockNorms As TransactionQty, /* Check Transaction Qty Concept */                                            
                                isNull(@ChildCode, 0), isNull(@QtyAvailable, 0) As ChildQty, -4 As CriteriaCode,                                             
                                @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, 
								@cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,                             
                                0 As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, 
								@cFinyear As Finyear, @cTransactionDate                                            
                            From dbo.fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@StockItem, @cFromWarehouseCode, @ReqQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear) v                                     

                           /* -- <Original Query Backup>:
							Select @cICode, v.LotID, v.SubLotID As SubLotID, @cTransactionItem, v.CBQty*@StockNorms As TransactionQty, /* Check Transaction Qty Concept */                                            
                                isNull(@ChildCode, 0), isNull(@QtyAvailable, 0) As ChildQty, -4 As CriteriaCode,                                             
                                @cFromWarehouseCode As FromWarehouseCode, @cFromRackBinCode As FromRackBinCode, @cToWarehouseCode As ToWarehouseCode, @cToRackBinCode As ToRackBinCode,                             
                                0 As ReverseEntryFlg, -2 UserID, @cBranchID As BranchID, @cCompID As CompID, @cFinyear As Finyear, @cTransactionDate                                            
                            From dbo.fn_COM_Trace_AsOnDate_Stock_ItemWHS_LotSubLotQty(@StockItem, @cFromWarehouseCode, @ReqQty, @AsOnDate, @AsOnDate, @RptDate, @cBranchID, @cCompID, @cFinyear) v
							*/
                                      
                            /* PRINT 'ICode: ' + Convert(varchar, @cICode) + ' - Completed - Other Entry.'; */                                          
                        END      --# 1.1.1     
                END                --# 1.1    
        END  
	End
END       
GO

